import { fixupConfigRules } from "@eslint/compat";
import { defineConfig, globalIgnores } from "eslint/config";
import nextVitals from "eslint-config-next/core-web-vitals";
import nextTs from "eslint-config-next/typescript";
import typescriptEslint from "typescript-eslint";

const baselineRules = new Set([
  "@next/next/no-before-interactive-script-outside-document",
  "@next/next/no-img-element",
  "@next/next/no-location-assign-relative-destination",
  "@typescript-eslint/no-unused-expressions",
  "@typescript-eslint/no-unused-vars",
  "import/no-anonymous-default-export",
  "jsx-a11y/alt-text",
  "react-hooks/exhaustive-deps",
]);

function promoteBaselineRules(configs) {
  return configs.map((config) => ({
    ...config,
    rules: Object.fromEntries(
      Object.entries(config.rules ?? {}).map(([rule, setting]) => [
        rule,
        baselineRules.has(rule)
          ? Array.isArray(setting)
            ? ["error", ...setting.slice(1)]
            : "error"
          : setting,
      ]),
    ),
  }));
}

const eslintConfig = defineConfig([
  ...fixupConfigRules(promoteBaselineRules(nextVitals)),
  ...fixupConfigRules(promoteBaselineRules(nextTs)),
  // Type-aware TS rules (Codacy parity: no-unsafe-*), same shape as
  // packages/tooling/eslint/src/index.js — kept local because apps/web
  // composes eslint-config-next presets instead of @game-guild/eslint-config.
  // eslint-config-next/typescript already registers the @typescript-eslint
  // plugin (same instance), and fixupConfigRules wraps that registration —
  // re-declaring plugins here trips the "Cannot redefine plugin" guard, so
  // the plugin key is stripped from the added configs.
  ...typescriptEslint.configs.recommendedTypeChecked.map(({ plugins: _plugins, ...config }) => config),
  {
    languageOptions: {
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
      },
    },
  },
  // Plain JS files are rarely in a tsconfig project; drop type-aware linting
  // there (resets projectService:false) so config files don't fail the
  // project service lookup.
  {
    files: ["**/*.{js,mjs,cjs}"],
    ...typescriptEslint.configs.disableTypeChecked,
  },
  // Test files are excluded from tsconfig.json by design (Next.js projects
  // don't type-check vitest files); without a TS project the project service
  // cannot parse them. Drop type-aware rules there — same tradeoff as JS.
  {
    files: [
      "**/*.test.{ts,tsx,mts,js,jsx,mjs}",
      "**/*.spec.{ts,tsx,mts,js,jsx,mjs}",
      "src/test/**/*",
      "**/__tests__/**/*",
    ],
    ...typescriptEslint.configs.disableTypeChecked,
  },
  {
    // ESLint suppressions only baseline errors. Promote warning-only rules so
    // legacy debt is recorded explicitly and every new violation still fails CI.
    linterOptions: {
      reportUnusedDisableDirectives: "error",
    },
  },
  // Override default ignores of eslint-config-next.
  globalIgnores([
    // Default ignores of eslint-config-next:
    ".next/**",
    ".next-*/**",
    "out/**",
    "build/**",
    "coverage/**",
    "next-env.d.ts",
    // Versioned browser assets are generated or vendored and linted at source.
    "public/**",
    "test-results/**",
  ]),
]);

export default eslintConfig;

import type { NextConfig } from "next";
import createNextIntlPlugin from "next-intl/plugin";
import path from "node:path";
import { COI_LEARN_RULES } from "./src/lib/emception/coi-headers";

const configuredDevOrigins = process.env.NEXT_ALLOWED_DEV_ORIGINS?.split(",")
  .map((origin) => origin.trim())
  .filter(Boolean);
const fastDev =
  process.env.GAMEGUILD_FAST_DEV === "1" ||
  process.env.npm_lifecycle_event === "dev:fast";
const gradingValidationE2e = process.env.GRADING_VALIDATION_E2E === "1";
// Keep the optional provider out of the disabled sign-in dependency graph.
// With a project ID, both bundlers resolve the real, installed SDK normally.
const walletConnectEnabled = Boolean(process.env.NEXT_PUBLIC_WALLETCONNECT_PROJECT_ID?.trim());
const walletConnectDisabledModule = "./src/lib/web3/walletconnect-disabled.ts";
const isolatedDistDir =
  process.env.CODING_CYCLE_E2E === "1"
    ? ".next-e2e-coding-cycle"
    : gradingValidationE2e
      ? ".next-e2e-grading-turbo"
      : fastDev
        ? ".next-fast"
        : undefined;

const nextConfig: NextConfig = {
  // ponytail: isolated E2E boots a second `next dev` on a dedicated port
  // alongside the user's running dev server; without a separate distDir the
  // two fight over the .next/ dev-server lock. Gated by env so production
  // builds are unaffected.
  ...(isolatedDistDir ? { distDir: isolatedDistDir } : {}),
  allowedDevOrigins: configuredDevOrigins ?? [
    "gameguild.localhost",
    "gameguild.127.0.0.1.sslip.io",
    "localhost",
    "127.0.0.1",
  ],
  reactCompiler: true,
  // Locale routing must see RSC headers to preserve internal navigation.
  skipProxyUrlNormalize: true,
  output: "standalone",
  outputFileTracingRoot: path.resolve(__dirname, "../.."),
  transpilePackages: [
    "@game-guild/ui",
    "@game-guild/auth-components",
    "@game-guild/block-content-editor",
    "@game-guild/block-list",
    "@game-guild/community-members",
    "@game-guild/content-rendering",
    "@game-guild/lexical-surface",
    "@game-guild/quiz",
    "@game-guild/quiz-surface",
    "@game-guild/courses",
    "@game-guild/dotnet-wasm",
    "@game-guild/emception-ui",
    "emception",
    "@gameguild/emception-browser",
    "@gameguild/emception-react",
    "@gameguild/emception-webcomponent",
    "@gameguild/emception-ide",
    "@gameguild/emception-xterm",
    "mermaid",
    "@mermaid-js/parser",
    "langium",
    "vscode-jsonrpc",
    "chevrotain",
  ],
  images: {
    // ponytail: any https host allowed; tighten back to allowlist if image proxy abuse appears
    remotePatterns: [{ protocol: "https", hostname: "**" }],
    // Previous allowlist:
    // remotePatterns: [
    //   { protocol: "https", hostname: "placehold.co" },
    //   { protocol: "https", hostname: "i.imgur.com" },
    //   { protocol: "https", hostname: "images.unsplash.com" },
    //   { protocol: "https", hostname: "cdn.gameguild.gg" },
    //   { protocol: "https", hostname: "www.python.org" },
    // ],
  },
  experimental: {
    authInterrupts: true,
    cpus: 1,
  },
  turbopack: {
    rules: {
      "*.py": {
        loaders: [
          path.resolve(__dirname, "scripts/turbopack-raw-source-loader.cjs"),
        ],
        as: "*.js",
      },
    },
    resolveAlias: {
      ...(!walletConnectEnabled
        ? { "@walletconnect/ethereum-provider": walletConnectDisabledModule }
        : {}),
      ...(fastDev
        ? {
            "@game-guild/client/react":
              "../../packages/infrastructure/client/dist-fast/react.js",
            "@game-guild/client/next":
              "../../packages/infrastructure/client/dist-fast/next.js",
            "@game-guild/client":
              "../../packages/infrastructure/client/dist-fast/index.js",
          }
        : {}),
      module: {
        browser: "./src/lib/browser-node-module-stub.ts",
      },
      "node:module": {
        browser: "./src/lib/browser-node-module-stub.ts",
      },
    },
  },
  async redirects() {
    return [
      {
        source: "/console/community/testing-lab/:path*",
        destination: "/workspace/testing-lab/:path*",
        permanent: true,
      },
      {
        source: "/:locale/console/community/testing-lab/:path*",
        destination: "/:locale/workspace/testing-lab/:path*",
        permanent: true,
      },
      { source: "/dashboard/teams/:path*", destination: "/my/teams/:path*", permanent: true },
      { source: "/dashboard/projects/:path*", destination: "/my/projects/:path*", permanent: true },
      { source: "/dashboard/invitations", destination: "/my/invitations", permanent: true },
      { source: "/dashboard/settings/account", destination: "/my/settings/account", permanent: true },
      { source: "/:locale/dashboard/teams/:path*", destination: "/:locale/my/teams/:path*", permanent: true },
      { source: "/:locale/dashboard/projects/:path*", destination: "/:locale/my/projects/:path*", permanent: true },
      { source: "/:locale/dashboard/invitations", destination: "/:locale/my/invitations", permanent: true },
      { source: "/:locale/dashboard/settings/account", destination: "/:locale/my/settings/account", permanent: true },
    ];
  },
  async rewrites() {
    return [
      {
        source: "/langs/:file*.wasm",
        destination: "/langs/:file*.wasm.gz",
      },
      {
        source: "/langs/:file*.js",
        destination: "/langs/:file*.js.gz",
      },
      {
        source: "/langs/:file*.json",
        destination: "/langs/:file*.json.gz",
      },
      {
        source: "/pyodide/:file*.js",
        destination: "/pyodide/:file*.js.gz",
      },
    ];
  },
  async headers() {
    return [
      {
        // ponytail: COOP only — GIS popup sign-in breaks under COEP
        // credentialless (opener postMessage severed, Google session
        // stripped from the GIS iframe). COEP stays on emception/learn
        // routes only, where SharedArrayBuffer actually needs it.
        source: "/sign-in",
        headers: [
          { key: "Cross-Origin-Opener-Policy", value: "same-origin-allow-popups" },
        ],
      },
      {
        source: "/:locale/sign-in",
        headers: [
          { key: "Cross-Origin-Opener-Policy", value: "same-origin-allow-popups" },
        ],
      },
      {
        source: "/api/auth/:path*",
        headers: [
          { key: "Cross-Origin-Opener-Policy", value: "same-origin-allow-popups" },
        ],
      },
      {
        source: "/:locale/workspace/economy/kyc",
        headers: [
          {
            key: "Content-Security-Policy",
            value: "default-src 'self'; script-src 'self' 'unsafe-inline' 'unsafe-eval' https://static.sumsub.com; style-src 'self' 'unsafe-inline' https://static.sumsub.com; frame-src 'self' https://*.sumsub.com; connect-src 'self' https://*.sumsub.com wss://*.sumsub.com; img-src 'self' data: blob: https://*.sumsub.com; media-src 'self' blob: https://*.sumsub.com; worker-src 'self' blob:;",
          },
          {
            key: "Permissions-Policy",
            value: "camera=(self \"https://api.sumsub.com\"), microphone=(self \"https://api.sumsub.com\")",
          },
        ],
      },
      {
        source: "/block-content-editor/:path((?!doc-editor|quiz-editor).*)",
        headers: [
          { key: "Cross-Origin-Opener-Policy", value: "same-origin" },
          { key: "Cross-Origin-Embedder-Policy", value: "credentialless" },
        ],
      },
      {
        source:
          "/:locale/block-content-editor/:path((?!doc-editor|quiz-editor).*)",
        headers: [
          { key: "Cross-Origin-Opener-Policy", value: "same-origin" },
          { key: "Cross-Origin-Embedder-Policy", value: "credentialless" },
        ],
      },
      ...COI_LEARN_RULES,
      // A cross-origin-isolated page may only spawn Workers whose script
      // response also carries COEP, else Chromium blocks it with
      // ERR_BLOCKED_BY_RESPONSE and the emception boot hangs forever.
      {
        source: "/_next/static/chunks/:file(emception-toolchain.*)",
        headers: [
          { key: "Cross-Origin-Opener-Policy", value: "same-origin" },
          { key: "Cross-Origin-Embedder-Policy", value: "credentialless" },
        ],
      },
      {
        source: "/wasm/:path*.wasm",
        headers: [
          { key: "Content-Encoding", value: "gzip" },
          { key: "Content-Type", value: "application/wasm" },
          {
            key: "Cache-Control",
            value: "public, max-age=31536000, immutable",
          },
          { key: "Cross-Origin-Resource-Policy", value: "cross-origin" },
        ],
      },
      {
        source: "/langs/:path*.wasm",
        headers: [
          { key: "Content-Encoding", value: "gzip" },
          { key: "Content-Type", value: "application/wasm" },
          {
            key: "Cache-Control",
            value: "public, max-age=31536000, immutable",
          },
          { key: "Cross-Origin-Resource-Policy", value: "cross-origin" },
        ],
      },
      {
        source: "/langs/:path*.js",
        headers: [
          { key: "Content-Encoding", value: "gzip" },
          { key: "Content-Type", value: "application/javascript" },
          {
            key: "Cache-Control",
            value: "public, max-age=31536000, immutable",
          },
          { key: "Cross-Origin-Resource-Policy", value: "cross-origin" },
        ],
      },
      {
        source: "/langs/:path*.json",
        headers: [
          { key: "Content-Encoding", value: "gzip" },
          { key: "Content-Type", value: "application/json" },
          {
            key: "Cache-Control",
            value: "public, max-age=31536000, immutable",
          },
          { key: "Cross-Origin-Resource-Policy", value: "cross-origin" },
        ],
      },
      {
        source: "/langs/:path*.zip",
        headers: [
          { key: "Content-Type", value: "application/zip" },
          {
            key: "Cache-Control",
            value: "public, max-age=31536000, immutable",
          },
          { key: "Cross-Origin-Resource-Policy", value: "cross-origin" },
        ],
      },
      {
        source: "/pyodide/:path*.js",
        headers: [
          { key: "Content-Encoding", value: "gzip" },
          { key: "Content-Type", value: "application/javascript" },
          {
            key: "Cache-Control",
            value: "public, max-age=31536000, immutable",
          },
          { key: "Cross-Origin-Resource-Policy", value: "cross-origin" },
        ],
      },
      {
        source: "/managed/:path*",
        headers: [
          {
            key: "Cache-Control",
            value: "public, max-age=31536000, immutable",
          },
          { key: "Cross-Origin-Resource-Policy", value: "cross-origin" },
        ],
      },
      {
        source: "/mathlive/:path*",
        headers: [
          {
            key: "Cache-Control",
            value: "public, max-age=31536000, immutable",
          },
          { key: "Cross-Origin-Resource-Policy", value: "cross-origin" },
        ],
      },
    ];
  },
  webpack: (config, { isServer, webpack }) => {
    if (process.env.GAMEGUILD_DISABLE_WEBPACK_CACHE === "1") {
      config.cache = false;
    }

    const resolvePackageDir = (pkg: string): string => {
      try {
        return path.dirname(require.resolve(`${pkg}/package.json`));
      } catch {
        const nested = [
          path.resolve(
            __dirname,
            "node_modules/vscode-languageserver/node_modules",
            pkg,
          ),
          path.resolve(
            __dirname,
            "../../node_modules/vscode-languageserver/node_modules",
            pkg,
          ),
        ];

        return (
          nested.find((candidate) =>
            require("node:fs").existsSync(candidate),
          ) ?? pkg
        );
      }
    };

    config.resolve.alias = {
      ...config.resolve.alias,
      ...(!walletConnectEnabled
        ? {
            "@walletconnect/ethereum-provider$": path.resolve(
              __dirname,
              walletConnectDisabledModule,
            ),
          }
        : {}),
      // The isolated coding-cycle runner must exercise the packages checked
      // out beside this app. A developer may have another worktree mounted
      // through node_modules, which would otherwise make a green browser run
      // validate stale Emception code instead of the change under test.
      ...(process.env.CODING_CYCLE_E2E === "1"
        ? {
            // `$` makes this entry exact. Without it, webpack consumes every
            // `@game-guild/emception-ui/assessment/*` import with this root
            // alias before it reaches the file aliases below.
            "@game-guild/emception-ui$": path.resolve(
              __dirname,
              "../../packages/infrastructure/ui-emception/src",
            ),
            "@game-guild/emception-ui/assessment/editor": path.resolve(
              __dirname,
              "../../packages/infrastructure/ui-emception/src/assessment/editor.ts",
            ),
            "@game-guild/emception-ui/assessment/plan": path.resolve(
              __dirname,
              "../../packages/infrastructure/ui-emception/src/assessment/plan.ts",
            ),
            "@game-guild/emception-ui/assessment/presets": path.resolve(
              __dirname,
              "../../packages/infrastructure/ui-emception/src/assessment/presets.ts",
            ),
            "@game-guild/emception-ui/assessment/storage": path.resolve(
              __dirname,
              "../../packages/infrastructure/ui-emception/src/assessment/workspace-storage.ts",
            ),
            emception: path.resolve(
              __dirname,
              "../../tools/emception/packages/core/dist",
            ),
            "@gameguild/emception-browser": path.resolve(
              __dirname,
              "../../tools/emception/packages/browser/dist",
            ),
            "@gameguild/emception-ide": path.resolve(
              __dirname,
              "../../tools/emception/packages/ide/dist",
            ),
          }
        : {}),
      "@game-guild/dotnet-wasm": path.resolve(
        __dirname,
        "../../packages/infrastructure/wasm/dotnet/src/index.ts",
      ),
      "vscode-jsonrpc": resolvePackageDir("vscode-jsonrpc"),
      "vscode-languageserver-protocol": resolvePackageDir(
        "vscode-languageserver-protocol",
      ),
      "vscode-languageserver-types": resolvePackageDir(
        "vscode-languageserver-types",
      ),
    };

    config.resolve.fallback = {
      ...config.resolve.fallback,
      module: false,
      fs: false,
      path: false,
      canvas: false,
      crypto: false,
      stream: false,
      buffer: false,
    };

    config.module.rules.push({
      test: /\.md$/,
      type: "asset/source",
    });

    // Handle Vite-style `?raw` imports (used by @gameguild/emception-browser
    // to import subprocess_shim.py as a string). Webpack needs an explicit
    // rule for the resourceQuery; without it, the .py file is parsed as JS.
    config.module.rules.push({
      resourceQuery: /raw/,
      type: "asset/source",
    });

    if (isServer) {
      config.plugins ??= [];
      config.plugins.push(
        new webpack.DefinePlugin({
          self: "globalThis",
        }),
      );
    }

    return config;
  },
};

const withNextIntl = createNextIntlPlugin();
export default withNextIntl(nextConfig);

#!/usr/bin/env node

import { mkdir } from "node:fs/promises";
import { randomUUID } from "node:crypto";
import { resolve } from "node:path";
import { createClient, GeneratedApi } from "@game-guild/client";
import { chromium } from "playwright";
import {
  assertSharedAuthCookie,
  learningViewports,
  resolveNodeHealthCheckUrl,
  trackAppHttpFailures,
} from "./learning-browser-e2e-support.mjs";

const apiBaseUrl = (
  process.env.API_BASE_URL ??
  process.env.NEXT_PUBLIC_API_URL ??
  "http://localhost:8080"
).replace(/\/$/, "");
const webBaseUrl = (
  process.env.PUBLIC_E2E_BASE_URL ??
  process.env.NEXT_PUBLIC_APP_URL ??
  "http://gameguild.localhost:3011"
).replace(/\/$/, "");
const learningBaseUrl = `${webBaseUrl}/learn`;
const existingTenantId =
  process.env.API_TENANT_ID ?? process.env.TENANT_ID ?? undefined;
const evidenceDir = resolve(
  process.env.LEARNING_E2E_EVIDENCE_DIR ??
    "apps/web/test-results/learning-student",
);
const headless = !["0", "false", "no"].includes(
  (process.env.LEARNING_E2E_HEADLESS ?? "true").toLowerCase(),
);
const expectedCookieDomain = process.env.LEARNING_E2E_COOKIE_DOMAIN;
function getLearningPath(path) {
  return new URL(`${learningBaseUrl}${path}`).pathname;
}
const refreshWaitMs = Number.parseInt(
  process.env.LEARNING_E2E_REFRESH_WAIT_MS ?? "0",
  10,
);

function unique() {
  return `${Date.now()}-${randomUUID().replaceAll("-", "").slice(0, 8)}`;
}

function formatApiError(error) {
  if (!error) return "unknown API error";
  const detail = typeof error.detail === "string" ? ` ${error.detail}` : "";
  return `${error.status ?? "unknown"} ${error.message ?? "request failed"}${detail}`.trim();
}

function unwrap(result, label) {
  if (result.ok) return result.data;
  throw new Error(`${label} failed: ${formatApiError(result.error)}`);
}

function createApiClient(accessToken, tenantId) {
  return createClient({
    baseUrl: apiBaseUrl,
    timeout: 30_000,
    devtools: { enabled: false },
    ...(accessToken
      ? { auth: { getAccessToken: async () => accessToken } }
      : {}),
    ...(tenantId ? { tenant: { getTenantId: async () => tenantId } } : {}),
  });
}

async function enableCapability(client, tenantId, capability) {
  unwrap(
    await client.request({
      method: "POST",
      path: `/v1/tenants/${tenantId}/capabilities`,
      body: {
        capability,
        isEnabled: true,
        source: "override:e2e",
        reason: `Enable ${capability} for the learner browser E2E`,
        expiresAt: null,
      },
      requiresAuth: true,
    }),
    `Enable ${capability} for tenant ${tenantId}`,
  );
}

async function assertHttpOk(url, label) {
  const response = await fetch(resolveNodeHealthCheckUrl(url), {
    redirect: "manual",
  });
  if (!response.ok && (response.status < 300 || response.status >= 400)) {
    throw new Error(
      `${label} is not reachable at ${url}: HTTP ${response.status}`,
    );
  }
}

async function waitForSubmissionResult(page, label) {
  const success = page.getByText("Submission received").first();
  const persistedAssessment = page.getByText("Awaiting grading").first();
  const persistedContent = page.getByText("Activity completed").first();
  const failure = page.getByText("Submission failed").first();
  try {
    await Promise.any([
      success.waitFor({ timeout: 45_000 }),
      persistedAssessment.waitFor({ timeout: 45_000 }),
      persistedContent.waitFor({ timeout: 45_000 }),
      failure.waitFor({ timeout: 45_000 }),
    ]);
  } catch {
    const body = await page
      .locator("body")
      .innerText()
      .catch(() => "");
    throw new Error(
      `${label} did not render a success or failure state at ${page.url()}:\n${body.slice(0, 3000)}`,
    );
  }
  if (await failure.isVisible()) {
    const alert = failure.locator('xpath=ancestor::*[@role="alert"][1]');
    throw new Error(
      `${label} failed in the learner UI: ${(await alert.textContent())?.trim() || "unknown error"}`,
    );
  }
}

async function seedLearnerCourse() {
  await assertHttpOk(`${apiBaseUrl}/health`, "API");
  const tag = unique();
  const authorEmail = `learning-student-author-${tag}@example.test`;
  const password = "Str0ng!Passw0rd123!";
  const publicClient = createApiClient();
  const signUp = unwrap(
    await publicClient.request({
      method: "POST",
      path: "/v1/auth/sign-up",
      body: {
        username: `learning_student_author_${tag.replace(/[^a-z0-9]/gi, "_")}`,
        email: authorEmail,
        password,
        ...(existingTenantId ? { tenantId: existingTenantId } : {}),
      },
      requiresAuth: false,
    }),
    "Author sign-up",
  );

  let accessToken = signUp.accessToken;
  const bootstrapClient = createApiClient(accessToken);
  const tenantsPage = unwrap(
    await bootstrapClient.request({
      method: "GET",
      path: "/v1/tenants",
      params: { page: 1, pageSize: 500, status: "active" },
      requiresAuth: true,
    }),
    "Load active tenants for learner E2E",
  );
  const platformTenantId = tenantsPage.items?.find(
    (tenant) => tenant.isDefault,
  )?.id;
  if (!platformTenantId)
    throw new Error(
      "The learner E2E requires an active default platform tenant.",
    );

  let tenantId = existingTenantId;
  if (!tenantId) {
