import React from 'react';
import { notFound } from 'next/navigation';
import { getCourse, getCourseStudents } from '@/lib/learning';
import { Card, CardContent } from '@game-guild/ui/components/card';
import { CheckCircle2, Clock, TrendingUp, Users } from 'lucide-react';
import { StudentTable } from '@/components/learning/console/courses/[course]/students/student-table';

export default async function Page({ params }: PageProps<'/[locale]/console/learning/courses/[course]/students'>): Promise<React.JSX.Element> {
  const { course: courseId } = await params;

  const [course, studentsData] = await Promise.all([getCourse(courseId), getCourseStudents(courseId)]);

  if (!course) {
    notFound();
  }

  const { students, total } = studentsData;

  const sevenDaysAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
  const enriched = students.map((student) => ({
    ...student,
    completionPercent: student.progress,
    isActive: new Date(student.lastActivity).getTime() > sevenDaysAgo,
  }));

  const activeCount = enriched.filter((s) => s.isActive).length;
  const completedCount = enriched.filter((s) => s.completionPercent >= 100).length;
  const avgProgress = enriched.length > 0 ? Math.round(enriched.reduce((acc, s) => acc + s.completionPercent, 0) / enriched.length) : 0;

  return (
    <div className="flex flex-col gap-6">
      {/* Stats */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <Card>
          <CardContent className="flex items-center gap-4 p-4">
            <div className="flex size-10 items-center justify-center rounded-lg bg-blue-100 dark:bg-blue-900">
              <Users className="size-5 text-blue-600 dark:text-blue-400" />
            </div>
            <div>
              <p className="text-2xl font-bold">{total}</p>
              <p className="text-sm text-muted-foreground">Total Enrolled</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 p-4">
            <div className="flex size-10 items-center justify-center rounded-lg bg-green-100 dark:bg-green-900">
              <TrendingUp className="size-5 text-green-600 dark:text-green-400" />
            </div>
            <div>
              <p className="text-2xl font-bold">{activeCount}</p>
              <p className="text-sm text-muted-foreground">Active (7d)</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 p-4">
            <div className="flex size-10 items-center justify-center rounded-lg bg-purple-100 dark:bg-purple-900">
              <CheckCircle2 className="size-5 text-purple-600 dark:text-purple-400" />
            </div>
            <div>
              <p className="text-2xl font-bold">{completedCount}</p>
              <p className="text-sm text-muted-foreground">Completed</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 p-4">
            <div className="flex size-10 items-center justify-center rounded-lg bg-orange-100 dark:bg-orange-900">
              <Clock className="size-5 text-orange-600 dark:text-orange-400" />
            </div>
            <div>
              <p className="text-2xl font-bold">{avgProgress}%</p>
              <p className="text-sm text-muted-foreground">Avg Progress</p>
            </div>
          </CardContent>
        </Card>
      </div>

      <StudentTable courseId={course.id} students={enriched} total={total} />
    </div>
  );
}

import { getCourse, getCourseDiscussions, getCourseSupportTickets } from '@/lib/learning';
import { notFound } from 'next/navigation';
import React from 'react';

/**
 * Support Group Layout
 *
 * Shared layout for all support subroutes.
 * Preloads support-related data for child pages.
 *
 * Routes:
 * - /support (redirect → /support/tickets)
 * - /support/tickets - Support ticket list
 * - /support/tickets/[ticketId] - Ticket detail
 * - /support/discussions - Forum threads (conditional: hasDiscussions)
 * - /support/discussions/[threadId] - Thread detail
 */
export default async function SupportLayout({
  children,
  params,
}: LayoutProps<'/[locale]/console/learning/courses/[course]/support'>): Promise<React.JSX.Element> {
  const { course: courseId } = await params;

  const course = await getCourse(courseId);
  if (!course) {
    notFound();
  }

  // Preload support data
  getCourseSupportTickets(courseId);

  if (course.features.hasDiscussions) {
    getCourseDiscussions(courseId);
  }

  return <>{children}</>;
}

'use client';

import { cn } from "@game-guild/ui/lib/utils";
import { Link, useRouter } from '@/i18n/navigation';
import { createCourse, deleteCourse, updateCourse } from '@/lib/learning/actions';
import { getCourseRouteParam } from '@/lib/learning/course-route';
import {
  CONTENT_VISIBILITIES,
  ENROLLMENT_STATUSES,
  formatEnumLabel,
  PROGRAM_CATEGORIES,
  PROGRAM_DIFFICULTIES,
} from '@/lib/learning/enums';
import { Button, buttonVariants } from '@game-guild/ui/components/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@game-guild/ui/components/card';
import { Input } from '@game-guild/ui/components/input';
import { Label } from '@game-guild/ui/components/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@game-guild/ui/components/select';
import { Textarea } from '@game-guild/ui/components/textarea';
import { ArrowLeft, ArrowRight, Check, Loader2 } from 'lucide-react';
import React, { useState, useTransition } from 'react';

function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .trim();
}

const STEPS = ['Basics', 'Details', 'Settings'] as const;

function parseEnrollmentCap(value: string): number | null {
  if (!value.trim()) return null;

  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
}

export default function CreateCoursePage({ params }: PageProps<'/[locale]/console/learning/courses/new'>) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [step, setStep] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [recoveryHref, setRecoveryHref] = useState<string | null>(null);

  // params is unused now (locale handled by next-intl router)
  void params;

  // Step 1: Basics
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [slug, setSlug] = useState('');
  const [autoSlug, setAutoSlug] = useState(true);

  // Step 2: Details
  const [category, setCategory] = useState('General');
  const [difficulty, setDifficulty] = useState('Beginner');
  const [estimatedHours, setEstimatedHours] = useState('');
  const [passingScore, setPassingScore] = useState('60');
  const [thumbnail, setThumbnail] = useState('');
  const [videoShowcaseUrl, setVideoShowcaseUrl] = useState('');

  // Step 3: Settings
  const [visibility, setVisibility] = useState('Public');
  const [enrollmentStatus, setEnrollmentStatus] = useState('Open');
  const [maxEnrollments, setMaxEnrollments] = useState('');
  const [skillsRequired, setSkillsRequired] = useState('');
  const [skillsProvided, setSkillsProvided] = useState('');

  function handleTitleChange(value: string) {
    setTitle(value);
    if (autoSlug) {
      setSlug(slugify(value));
    }
  }

  function handleSlugChange(value: string) {
    setAutoSlug(false);
    setSlug(slugify(value));
  }

  function canAdvance(): boolean {
    if (step === 0) {
      return title.trim().length >= 3 && description.trim().length >= 10 && slug.trim().length >= 1;
    }
    return true;
  }

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setRecoveryHref(null);

    if (step < STEPS.length - 1) {
      setStep(step + 1);
      return;
    }

    startTransition(async () => {
      // Step 1: Create the course with basics
      const createResult = await createCourse({ title, description, slug });
      if (!createResult.success) {
        setError(createResult.error);
        return;
      }

      const courseId = createResult.data.id;
      const courseRouteParam = createResult.data.routeParam || getCourseRouteParam({ id: courseId, slug: createResult.data.slug });

      // Step 2: Update with extended fields
      const updateResult = await updateCourse({
        courseId,
        category,
        difficulty,
        visibility,
        enrollmentStatus,
        estimatedHours: estimatedHours ? parseInt(estimatedHours, 10) : undefined,
        passingScore: passingScore ? parseInt(passingScore, 10) : undefined,
        thumbnail: thumbnail || undefined,
        videoShowcaseUrl: videoShowcaseUrl || undefined,
        maxEnrollments: parseEnrollmentCap(maxEnrollments),
        skillsRequired: skillsRequired.trim() || undefined,
        skillsProvided: skillsProvided.trim() || undefined,
      });
      if (!updateResult.success) {
        const rollbackResult = await deleteCourse(courseId);
        if (rollbackResult.success) {
          setError(`${updateResult.error} The incomplete draft was removed; review the form and try again.`);
          return;
        }

        setRecoveryHref(`/console/learning/courses/${courseRouteParam}/overview`);
        setError(
          `${updateResult.error} The draft still exists as "${createResult.data.slug}" because cleanup failed: ${rollbackResult.error}`,
        );
        return;
      }

      router.push(`/console/learning/courses/${courseRouteParam}/overview`);
    });
  }

  return (
    <div className="mx-auto flex max-w-2xl flex-col gap-6 p-6">
      <div className="flex items-center gap-4">
        <Link
          href="/console/learning/courses"
          className={cn(buttonVariants({ variant: "ghost", size: "icon" }))}
        >
          <ArrowLeft className="size-5" />
        </Link>
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Create Course</h1>
          <p className="text-muted-foreground">
            Step {step + 1} of {STEPS.length}: {STEPS[step]}
          </p>
        </div>
      </div>

      {/* Stepper */}
      <div className="flex items-center gap-2">
        {STEPS.map((label, i) => (
          <React.Fragment key={label}>
            <button
              type="button"
              onClick={() => i < step && setStep(i)}
              disabled={i > step}
              className={`flex size-8 items-center justify-center rounded-full text-sm font-medium transition-colors ${i < step
                ? 'bg-primary text-primary-foreground cursor-pointer'
                : i === step
                  ? 'bg-primary text-primary-foreground'
                  : 'bg-muted text-muted-foreground'
                }`}
            >
              {i < step ? <Check className="size-4" /> : i + 1}
            </button>
            {i < STEPS.length - 1 && <div className={`h-0.5 flex-1 ${i < step ? 'bg-primary' : 'bg-muted'}`} />}
          </React.Fragment>
        ))}
      </div>

      <form onSubmit={handleSubmit}>
        {/* Step 1: Basics */}
        {step === 0 && (
          <Card>
            <CardHeader>
              <CardTitle>Course Basics</CardTitle>
              <CardDescription>Enter the core information for your course.</CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-5">
              <div className="flex flex-col gap-2">
                <Label htmlFor="title">Title *</Label>
                <Input
                  id="title"
                  placeholder="e.g. Introduction to Game Development"
                  value={title}
                  onChange={(e) => handleTitleChange(e.target.value)}
                  required
                  minLength={3}
                  maxLength={255}
                />
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="slug">URL Slug</Label>
                <Input id="slug" placeholder="introduction-to-game-development" value={slug} onChange={(e) => handleSlugChange(e.target.value)} required />
                <p className="text-muted-foreground text-xs">Auto-generated from title. Edit to customize.</p>
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="description">Description *</Label>
                <Textarea
                  id="description"
                  placeholder="Describe what students will learn..."
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  required
                  minLength={10}
                  maxLength={2000}
                  rows={5}
                />
                <p className="text-muted-foreground text-xs">Minimum 10 characters. {description.length}/2000 characters</p>
              </div>
            </CardContent>
          </Card>
        )}

        {/* Step 2: Details */}
        {step === 1 && (
          <Card>
            <CardHeader>
              <CardTitle>Course Details</CardTitle>
              <CardDescription>Categorize your course and add media.</CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-5">
              <div className="grid grid-cols-2 gap-4">
                <div className="flex flex-col gap-2">
                  <Label htmlFor="course-category">Category</Label>
                  <Select value={category} onValueChange={(value) => setCategory(value ?? '')}>
                    <SelectTrigger id="course-category">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {PROGRAM_CATEGORIES.map((value) => (
                        <SelectItem key={value} value={value}>
                          {formatEnumLabel(value)}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className="flex flex-col gap-2">
                  <Label htmlFor="course-difficulty">Difficulty</Label>
                  <Select value={difficulty} onValueChange={(value) => setDifficulty(value ?? '')}>
                    <SelectTrigger id="course-difficulty">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {PROGRAM_DIFFICULTIES.map((value) => (
                        <SelectItem key={value} value={value}>
                          {formatEnumLabel(value)}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="estimatedHours">Estimated Hours</Label>
                <Input
                  id="estimatedHours"
                  type="number"
                  min="1"
                  max="1000"
                  placeholder="e.g. 40"
                  value={estimatedHours}
                  onChange={(e) => setEstimatedHours(e.target.value)}
                />
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="passingScore">Passing score (%)</Label>
                <Input
                  id="passingScore"
                  type="number"
                  min={0}
                  max={100}
                  step={1}
                  value={passingScore}
                  onChange={(e) => setPassingScore(e.target.value)}
                />
                <p className="text-muted-foreground text-xs">
                  Minimum percentage (0-100) required to pass this course. Applied to all assessments.
                </p>
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="thumbnail">Thumbnail URL</Label>
                <Input id="thumbnail" type="url" placeholder="https://example.com/image.jpg" value={thumbnail} onChange={(e) => setThumbnail(e.target.value)} />
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="videoShowcaseUrl">Video Showcase URL</Label>
                <Input
                  id="videoShowcaseUrl"
                  type="url"
                  placeholder="https://youtube.com/watch?v=..."
                  value={videoShowcaseUrl}
                  onChange={(e) => setVideoShowcaseUrl(e.target.value)}
                />
                <p className="text-muted-foreground text-xs">Optional promotional video for the course landing page.</p>
              </div>
            </CardContent>
          </Card>
        )}

        {/* Step 3: Settings */}
        {step === 2 && (
          <Card>
            <CardHeader>
              <CardTitle>Course Settings</CardTitle>
              <CardDescription>Configure visibility, enrollment, and skills.</CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-5">
              <div className="grid grid-cols-2 gap-4">
                <div className="flex flex-col gap-2">
                  <Label htmlFor="course-visibility">Visibility</Label>
                  <Select value={visibility} onValueChange={(value) => setVisibility(value ?? '')}>
                    <SelectTrigger id="course-visibility">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {CONTENT_VISIBILITIES.map((value) => (
                        <SelectItem key={value} value={value}>
                          {formatEnumLabel(value)}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className="flex flex-col gap-2">
                  <Label htmlFor="course-enrollment-status">Enrollment Status</Label>
                  <Select value={enrollmentStatus} onValueChange={(value) => setEnrollmentStatus(value ?? '')}>
                    <SelectTrigger id="course-enrollment-status">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {ENROLLMENT_STATUSES.map((value) => (
                        <SelectItem key={value} value={value}>
                          {formatEnumLabel(value)}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="maxEnrollments">Max Enrollments</Label>
                <Input
                  id="maxEnrollments"
                  type="number"
                  min="0"
                  placeholder="0 for unlimited"
                  value={maxEnrollments}
                  onChange={(e) => setMaxEnrollments(e.target.value)}
                />
                <p className="text-muted-foreground text-xs">Use 0 or leave blank for unlimited seats.</p>
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="skillsRequired">Skills Required</Label>
                <Textarea
                  id="skillsRequired"
                  placeholder="e.g. Basic programming knowledge, familiarity with C#"
                  value={skillsRequired}
                  onChange={(e) => setSkillsRequired(e.target.value)}
                  rows={2}
                />
                <p className="text-muted-foreground text-xs">Prerequisites students should have before enrolling.</p>
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="skillsProvided">Skills Provided</Label>
                <Textarea
                  id="skillsProvided"
                  placeholder="e.g. Game development basics, Unity fundamentals, 2D/3D concepts"
                  value={skillsProvided}
                  onChange={(e) => setSkillsProvided(e.target.value)}
                  rows={2}
                />
                <p className="text-muted-foreground text-xs">What students will learn from this course.</p>
              </div>
            </CardContent>
          </Card>
        )}

        {error && (
          <div role="alert" className="mt-4 rounded-md border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:border-red-900 dark:bg-red-950 dark:text-red-300">
            <p>{error}</p>
            {recoveryHref ? (
              <Link
                href={recoveryHref}
                className={cn(
                  buttonVariants({
                    variant: "link",
                    className: "mt-2 h-auto p-0 text-red-700 underline dark:text-red-300",
                  }),
                )}
              >
