        </div>
      </form>
    </div>
  );
}

import { EmailDeliverability } from '@/components/console/platform/email-deliverability/email-deliverability';
import { Alert, AlertDescription, AlertTitle } from '@game-guild/ui/components/alert';
import { getToken } from '@/auth';
import { createServerClient, GeneratedApi } from '@game-guild/client';
import { AlertTriangle } from 'lucide-react';
import { getTranslations } from 'next-intl/server';
import React from 'react';

/**
 * Console → Platform → Email Deliverability.
 *
 * Server-fetched first pages of the three admin feeds; writes (unsuppress,
 * requeue) and the per-notification timeline drill-down go through
 * `@/lib/notifications/email-deliverability-actions` (session + revalidate).
 * No live updates — data refreshes on action revalidation only.
 */
export default async function EmailDeliverabilityPage({
  params,
}: {
  params: Promise<{ locale: string }>;
}): Promise<React.JSX.Element> {
  const { locale } = await params;
  const t = await getTranslations({ locale, namespace: 'emailDeliverability' });

  const apiUrl =
    process.env.API_URL ||
    process.env.NEXT_PUBLIC_API_URL ||
    'http://localhost:8080';
  const client = createServerClient({
    baseUrl: apiUrl,
    auth: { getAccessToken: () => getToken() },
  });
  const notifications = new GeneratedApi.NotificationsModule(client);

  const [eventsResult, suppressionsResult, deadLettersResult] = await Promise.all([
    notifications.getEmailDeliveryEmailEvents({ take: 20 }),
    notifications.getEmailDeliverySuppressions({ take: 20, includeReleased: true }),
    notifications.getEmailDeliveryDeadletters({ take: 20 }),
  ]);

  const failed =
    !eventsResult.ok || !eventsResult.data || !suppressionsResult.ok || !suppressionsResult.data || !deadLettersResult.ok || !deadLettersResult.data;

  // Generated DTO fields are all optional+nullable — normalize to strict
  // component props before crossing the server/client boundary.
  const events = failed
    ? []
    : (eventsResult.data?.items ?? [])
        .filter((item) => item.id)
        .map((item) => ({
          id: item.id as string,
          occurredAt: item.occurredAt ?? '',
          eventType: item.eventType ?? 'Unknown',
          recipientEmail: item.recipientEmail ?? '',
          providerMessageId: item.providerMessageId ?? '',
          bounceType: item.bounceType ?? null,
          diagnosticCode: item.diagnosticCode ?? null,
          payloadPreview: item.payloadPreview ?? null,
        }));
  const suppressions = failed
    ? []
    : (suppressionsResult.data?.items ?? [])
        .filter((item) => item.id)
        .map((item) => ({
          id: item.id as string,
          emailAddress: item.emailAddress ?? '',
          reason: item.reason ?? 'HardBounce',
          bounceType: item.bounceType ?? null,
          suppressedAt: item.suppressedAt ?? '',
          releasedAt: item.releasedAt ?? null,
          isActive: item.isActive ?? false,
        }));
  const deadLetters = failed
    ? []
    : (deadLettersResult.data?.items ?? [])
        .filter((item) => item.id)
        .map((item) => ({
          id: item.id as string,
          title: item.title ?? item.type ?? item.id as string,
          type: item.type ?? '',
          channel: item.channel ?? '',
          recipientEmail: item.recipientEmail ?? null,
          recipientId: item.recipientId ?? null,
          lastError: item.lastError ?? null,
          attemptCount: item.attemptCount ?? 0,
          requeueCount: item.requeueCount ?? 0,
          createdAt: item.createdAt ?? '',
        }));

  return (
    <div className="flex flex-col gap-6 p-6">
      <div className="flex flex-col gap-2">
        <h1 className="text-3xl font-bold tracking-tight">{t('title')}</h1>
        <p className="text-muted-foreground">{t('description')}</p>
      </div>

      {failed ? (
        <Alert variant="destructive">
          <AlertTriangle className="size-4" />
          <AlertTitle>{t('loadError.title')}</AlertTitle>
          <AlertDescription>{t('loadError.description')}</AlertDescription>
        </Alert>
      ) : (
        <EmailDeliverability events={events} suppressions={suppressions} deadLetters={deadLetters} />
      )}
    </div>
  );
}

import { auth, authConfig, readSessionUnCached } from '@/auth';
import { GitHubStarPrompt } from '@/components/community/github-star-prompt';
import { WorkspaceShell } from '@/components/console/workspace-shell';
import { AccessibilitySyncInitializer } from '@/components/settings/accessibility-sync-initializer';
import { EditorPreferencesSyncInitializer } from '@/components/settings/editor-preferences-sync-initializer';
import { ThemeSyncInitializer } from '@/components/settings/theme-sync-initializer';
import { TwoFactorNudgeBanner } from '@/components/settings/two-factor-nudge-banner';
import { redirect } from '@/i18n/navigation';
import { getDashboardNotificationSummary } from '@/lib/dashboard-notifications';
import { getDashboardContexts } from '@/lib/dashboard-contexts';
import { getMfaStatus } from '@/lib/user-settings/mfa-actions';
import { SessionStore, resolveCookieOptions } from '@game-guild/client';
import { cookies, headers } from 'next/headers';
import React from 'react';

/**
 * Defensive MFA status read for the no-2FA nudge banner (issue #838): any
 * failure means "don't render the banner" — the nudge must fail silent.
 */
async function fetchTwoFactorEnabled(): Promise<boolean | null> {
  try {
    const status = await getMfaStatus();
    if (!status.ok) return null;
    return status.data.isEnabled ?? false;
  } catch {
    return null;
  }
}

/**
 * The browser-visible path the proxy forwarded (issue #864): layouts receive
 * no search params, so a transient unauthenticated render recovers the real
 * target for the sign-in callbackUrl instead of losing it to `/workspace`.
 * The proxy strips the locale prefix; non-slash-relative values are rejected.
 */
async function currentPublicPath(): Promise<string | null> {
  try {
    const forwarded = (await headers()).get('x-gameguild-path');
    return forwarded?.startsWith('/') && !forwarded.startsWith('//') ? forwarded : null;
  } catch {
    return null;
  }
}

export default async function Layout({ children, params }: LayoutProps<'/[locale]'>): Promise<React.JSX.Element> {
  const { locale } = await params;

  let session = await auth();

  if (!session || typeof session === 'function') {
    // Session write/rotation race post-MFA (issue #864): the full-page
    // redirect after MFA verify can land here while the rotated session
    // cookie is not yet observable through auth(), briefly rendering the
    // sign-in screen ("sign-in flash"). A present-but-unreadable session
    // cookie means the browser DID send credentials — retry auth() once
    // after a short delay before bouncing to /sign-in. No cookie at all
    // is a genuine anonymous request and redirects immediately.
    const cookieStore = await cookies();
    const cookieOptions = resolveCookieOptions(authConfig.cookies, authConfig.cookies.secure);
    const sessionCookieName = new SessionStore(cookieOptions).getCookieName();
    const hasSessionCookie = Boolean(cookieStore.get(sessionCookieName)?.value);

    if (hasSessionCookie) {
      await new Promise((resolve) => setTimeout(resolve, 150));
      // auth() is memoized per request (cache()); retry through the
      // uncached reader so the re-read sees the rotated session cookie.
      session = await readSessionUnCached();
    }

    if (!session || typeof session === 'function') {
      const callbackUrl = (await currentPublicPath()) ?? '/workspace';
      redirect({ href: { pathname: '/sign-in', query: { callbackUrl } }, locale });
      throw new Error('Unauthenticated dashboard access');
    }
  }

  const [notifications, dashboardContexts, twoFactorEnabled] = await Promise.all([
    getDashboardNotificationSummary(session.user.id),
    getDashboardContexts(),
    fetchTwoFactorEnabled(),
  ]);
  const dashboardUser = {
    id: session.user.id,
    name: session.user.name?.trim() || session.user.email?.split('@')[0] || 'GameGuild user',
    email: session.user.email ?? 'No email available',
    image: session.user.image ?? null,
  };

  return (
    <WorkspaceShell
      notifications={notifications}
      user={dashboardUser}
      capabilities={dashboardContexts.capabilities}
      contexts={dashboardContexts.contexts}
    >
      <ThemeSyncInitializer />
      <AccessibilitySyncInitializer />
      <EditorPreferencesSyncInitializer />
      {twoFactorEnabled === false && <TwoFactorNudgeBanner twoFactorEnabled={false} />}
      <GitHubStarPrompt />
      {children}
    </WorkspaceShell>
  );
}

