import { getCourse, getCourseDiscussions, getCourseSupportTickets } from '@/lib/learning';
import { notFound } from 'next/navigation';
import React from 'react';

/**
 * Support Group Layout
 *
 * Shared layout for all support subroutes.
 * Preloads support-related data for child pages.
 *
 * Routes:
 * - /support (redirect → /support/tickets)
 * - /support/tickets - Support ticket list
 * - /support/tickets/[ticketId] - Ticket detail
 * - /support/discussions - Forum threads (conditional: hasDiscussions)
 * - /support/discussions/[threadId] - Thread detail
 */
export default async function SupportLayout({
  children,
  params,
}: LayoutProps<'/[locale]/workspace/learning/courses/[course]/support'>): Promise<React.JSX.Element> {
  const { course: courseId } = await params;

  const course = await getCourse(courseId);
  if (!course) {
    notFound();
  }

  // Preload support data
  getCourseSupportTickets(courseId);

  if (course.features.hasDiscussions) {
    getCourseDiscussions(courseId);
  }

  return <>{children}</>;
}

'use client';

import { cn } from "@game-guild/ui/lib/utils";
import { Link, useRouter } from '@/i18n/navigation';
import { createCourse, deleteCourse, updateCourse } from '@/lib/learning/actions';
import { getCourseRouteParam } from '@/lib/learning/course-route';
import {
  CONTENT_VISIBILITIES,
  ENROLLMENT_STATUSES,
  formatEnumLabel,
  PROGRAM_CATEGORIES,
  PROGRAM_DIFFICULTIES,
} from '@/lib/learning/enums';
import { Button, buttonVariants } from '@game-guild/ui/components/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@game-guild/ui/components/card';
import { Input } from '@game-guild/ui/components/input';
import { Label } from '@game-guild/ui/components/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@game-guild/ui/components/select';
import { Textarea } from '@game-guild/ui/components/textarea';
import { ArrowLeft, ArrowRight, Check, Loader2 } from 'lucide-react';
import React, { useState, useTransition } from 'react';

function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .trim();
}

const STEPS = ['Basics', 'Details', 'Settings'] as const;

function parseEnrollmentCap(value: string): number | null {
  if (!value.trim()) return null;

  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
}

export default function CreateCoursePage({ params }: PageProps<'/[locale]/workspace/learning/courses/new'>) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [step, setStep] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [recoveryHref, setRecoveryHref] = useState<string | null>(null);

  // params is unused now (locale handled by next-intl router)
  void params;

  // Step 1: Basics
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [slug, setSlug] = useState('');
  const [autoSlug, setAutoSlug] = useState(true);

  // Step 2: Details
  const [category, setCategory] = useState('General');
  const [difficulty, setDifficulty] = useState('Beginner');
  const [estimatedHours, setEstimatedHours] = useState('');
  const [passingScore, setPassingScore] = useState('60');
  const [thumbnail, setThumbnail] = useState('');
  const [videoShowcaseUrl, setVideoShowcaseUrl] = useState('');

  // Step 3: Settings
  const [visibility, setVisibility] = useState('Public');
  const [enrollmentStatus, setEnrollmentStatus] = useState('Open');
  const [maxEnrollments, setMaxEnrollments] = useState('');
  const [skillsRequired, setSkillsRequired] = useState('');
  const [skillsProvided, setSkillsProvided] = useState('');

  function handleTitleChange(value: string) {
    setTitle(value);
    if (autoSlug) {
      setSlug(slugify(value));
    }
  }

  function handleSlugChange(value: string) {
    setAutoSlug(false);
    setSlug(slugify(value));
  }

  function canAdvance(): boolean {
    if (step === 0) {
      return title.trim().length >= 3 && description.trim().length >= 10 && slug.trim().length >= 1;
    }
    return true;
  }

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setRecoveryHref(null);

    if (step < STEPS.length - 1) {
      setStep(step + 1);
      return;
    }

    startTransition(async () => {
      // Step 1: Create the course with basics
      const createResult = await createCourse({ title, description, slug });
      if (!createResult.success) {
        setError(createResult.error);
        return;
      }

      const courseId = createResult.data.id;
      const courseRouteParam = createResult.data.routeParam || getCourseRouteParam({ id: courseId, slug: createResult.data.slug });

      // Step 2: Update with extended fields
      const updateResult = await updateCourse({
        courseId,
        category,
        difficulty,
        visibility,
        enrollmentStatus,
        estimatedHours: estimatedHours ? parseInt(estimatedHours, 10) : undefined,
        passingScore: passingScore ? parseInt(passingScore, 10) : undefined,
        thumbnail: thumbnail || undefined,
        videoShowcaseUrl: videoShowcaseUrl || undefined,
        maxEnrollments: parseEnrollmentCap(maxEnrollments),
        skillsRequired: skillsRequired.trim() || undefined,
        skillsProvided: skillsProvided.trim() || undefined,
      });
      if (!updateResult.success) {
        const rollbackResult = await deleteCourse(courseId);
        if (rollbackResult.success) {
          setError(`${updateResult.error} The incomplete draft was removed; review the form and try again.`);
          return;
        }

        setRecoveryHref(`/workspace/learning/courses/${courseRouteParam}/overview`);
        setError(
          `${updateResult.error} The draft still exists as "${createResult.data.slug}" because cleanup failed: ${rollbackResult.error}`,
        );
        return;
      }

      router.push(`/workspace/learning/courses/${courseRouteParam}/overview`);
    });
  }

  return (
    <div className="mx-auto flex max-w-2xl flex-col gap-6 p-6">
      <div className="flex items-center gap-4">
        <Link
          href="/workspace/learning/courses"
          className={cn(buttonVariants({ variant: "ghost", size: "icon" }))}
        >
          <ArrowLeft className="size-5" />
        </Link>
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Create Course</h1>
          <p className="text-muted-foreground">
            Step {step + 1} of {STEPS.length}: {STEPS[step]}
          </p>
        </div>
      </div>

      {/* Stepper */}
      <div className="flex items-center gap-2">
        {STEPS.map((label, i) => (
          <React.Fragment key={label}>
            <button
              type="button"
              onClick={() => i < step && setStep(i)}
              disabled={i > step}
              className={`flex size-8 items-center justify-center rounded-full text-sm font-medium transition-colors ${i < step
                ? 'bg-primary text-primary-foreground cursor-pointer'
                : i === step
                  ? 'bg-primary text-primary-foreground'
                  : 'bg-muted text-muted-foreground'
                }`}
            >
              {i < step ? <Check className="size-4" /> : i + 1}
            </button>
            {i < STEPS.length - 1 && <div className={`h-0.5 flex-1 ${i < step ? 'bg-primary' : 'bg-muted'}`} />}
          </React.Fragment>
        ))}
      </div>

      <form onSubmit={handleSubmit}>
        {/* Step 1: Basics */}
        {step === 0 && (
          <Card>
            <CardHeader>
              <CardTitle>Course Basics</CardTitle>
              <CardDescription>Enter the core information for your course.</CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-5">
              <div className="flex flex-col gap-2">
                <Label htmlFor="title">Title *</Label>
                <Input
                  id="title"
                  placeholder="e.g. Introduction to Game Development"
                  value={title}
                  onChange={(e) => handleTitleChange(e.target.value)}
                  required
                  minLength={3}
                  maxLength={255}
                />
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="slug">URL Slug</Label>
                <Input id="slug" placeholder="introduction-to-game-development" value={slug} onChange={(e) => handleSlugChange(e.target.value)} required />
                <p className="text-muted-foreground text-xs">Auto-generated from title. Edit to customize.</p>
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="description">Description *</Label>
                <Textarea
                  id="description"
                  placeholder="Describe what students will learn..."
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  required
                  minLength={10}
                  maxLength={2000}
                  rows={5}
                />
                <p className="text-muted-foreground text-xs">Minimum 10 characters. {description.length}/2000 characters</p>
              </div>
            </CardContent>
          </Card>
        )}

        {/* Step 2: Details */}
        {step === 1 && (
          <Card>
            <CardHeader>
              <CardTitle>Course Details</CardTitle>
              <CardDescription>Categorize your course and add media.</CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-5">
              <div className="grid grid-cols-2 gap-4">
                <div className="flex flex-col gap-2">
                  <Label htmlFor="course-category">Category</Label>
                  <Select value={category} onValueChange={(value) => setCategory(value ?? '')}>
                    <SelectTrigger id="course-category">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {PROGRAM_CATEGORIES.map((value) => (
                        <SelectItem key={value} value={value}>
                          {formatEnumLabel(value)}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className="flex flex-col gap-2">
                  <Label htmlFor="course-difficulty">Difficulty</Label>
                  <Select value={difficulty} onValueChange={(value) => setDifficulty(value ?? '')}>
                    <SelectTrigger id="course-difficulty">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {PROGRAM_DIFFICULTIES.map((value) => (
                        <SelectItem key={value} value={value}>
                          {formatEnumLabel(value)}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="estimatedHours">Estimated Hours</Label>
                <Input
                  id="estimatedHours"
                  type="number"
                  min="1"
                  max="1000"
                  placeholder="e.g. 40"
                  value={estimatedHours}
                  onChange={(e) => setEstimatedHours(e.target.value)}
                />
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="passingScore">Passing score (%)</Label>
                <Input
                  id="passingScore"
                  type="number"
                  min={0}
                  max={100}
                  step={1}
                  value={passingScore}
                  onChange={(e) => setPassingScore(e.target.value)}
                />
                <p className="text-muted-foreground text-xs">
                  Minimum percentage (0-100) required to pass this course. Applied to all assessments.
                </p>
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="thumbnail">Thumbnail URL</Label>
                <Input id="thumbnail" type="url" placeholder="https://example.com/image.jpg" value={thumbnail} onChange={(e) => setThumbnail(e.target.value)} />
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="videoShowcaseUrl">Video Showcase URL</Label>
                <Input
                  id="videoShowcaseUrl"
                  type="url"
                  placeholder="https://youtube.com/watch?v=..."
                  value={videoShowcaseUrl}
                  onChange={(e) => setVideoShowcaseUrl(e.target.value)}
                />
                <p className="text-muted-foreground text-xs">Optional promotional video for the course landing page.</p>
              </div>
            </CardContent>
          </Card>
        )}

        {/* Step 3: Settings */}
        {step === 2 && (
          <Card>
            <CardHeader>
              <CardTitle>Course Settings</CardTitle>
              <CardDescription>Configure visibility, enrollment, and skills.</CardDescription>
            </CardHeader>
            <CardContent className="flex flex-col gap-5">
              <div className="grid grid-cols-2 gap-4">
                <div className="flex flex-col gap-2">
                  <Label htmlFor="course-visibility">Visibility</Label>
                  <Select value={visibility} onValueChange={(value) => setVisibility(value ?? '')}>
                    <SelectTrigger id="course-visibility">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {CONTENT_VISIBILITIES.map((value) => (
                        <SelectItem key={value} value={value}>
                          {formatEnumLabel(value)}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className="flex flex-col gap-2">
                  <Label htmlFor="course-enrollment-status">Enrollment Status</Label>
                  <Select value={enrollmentStatus} onValueChange={(value) => setEnrollmentStatus(value ?? '')}>
                    <SelectTrigger id="course-enrollment-status">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {ENROLLMENT_STATUSES.map((value) => (
                        <SelectItem key={value} value={value}>
                          {formatEnumLabel(value)}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="maxEnrollments">Max Enrollments</Label>
                <Input
                  id="maxEnrollments"
                  type="number"
                  min="0"
                  placeholder="0 for unlimited"
                  value={maxEnrollments}
                  onChange={(e) => setMaxEnrollments(e.target.value)}
                />
                <p className="text-muted-foreground text-xs">Use 0 or leave blank for unlimited seats.</p>
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="skillsRequired">Skills Required</Label>
                <Textarea
                  id="skillsRequired"
                  placeholder="e.g. Basic programming knowledge, familiarity with C#"
                  value={skillsRequired}
                  onChange={(e) => setSkillsRequired(e.target.value)}
                  rows={2}
                />
                <p className="text-muted-foreground text-xs">Prerequisites students should have before enrolling.</p>
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="skillsProvided">Skills Provided</Label>
                <Textarea
                  id="skillsProvided"
                  placeholder="e.g. Game development basics, Unity fundamentals, 2D/3D concepts"
                  value={skillsProvided}
                  onChange={(e) => setSkillsProvided(e.target.value)}
                  rows={2}
                />
                <p className="text-muted-foreground text-xs">What students will learn from this course.</p>
              </div>
            </CardContent>
          </Card>
        )}

        {error && (
          <div role="alert" className="mt-4 rounded-md border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:border-red-900 dark:bg-red-950 dark:text-red-300">
            <p>{error}</p>
            {recoveryHref ? (
              <Link
                href={recoveryHref}
                className={cn(
                  buttonVariants({
                    variant: "link",
                    className: "mt-2 h-auto p-0 text-red-700 underline dark:text-red-300",
                  }),
                )}
              >
                Open the draft and finish it manually
              </Link>
            ) : null}
          </div>
        )}

        <div className="mt-4 flex gap-3">
          {step > 0 && (
            <Button type="button" variant="outline" onClick={() => setStep(step - 1)}>
              <ArrowLeft className="mr-2 size-4" />
              Back
            </Button>
          )}

          {step < STEPS.length - 1 ? (
            <Button type="submit" disabled={!canAdvance()}>
              Next
              <ArrowRight className="ml-2 size-4" />
            </Button>
          ) : (
            <Button type="submit" disabled={isPending}>
              {isPending ? (
                <>
                  <Loader2 className="mr-2 size-4 animate-spin" />
                  Creating...
                </>
              ) : (
                'Create Course'
              )}
            </Button>
          )}

          <Link
            href="/workspace/learning/courses"
            className={cn(buttonVariants({ variant: "ghost" }))}
          >
            Cancel
          </Link>
        </div>
      </form>
    </div>
  );
}

import { WorkspaceHub } from '@/components/workspace/workspace-hub';
import React from 'react';

export default async function Page(): Promise<React.JSX.Element> {
  return <WorkspaceHub />;
}

import { auth, getToken } from '@/auth';
import {
  ConnectedAccountsCard,
  type LinkedAccount,
  type SettingsBanner,
} from '@/components/connected-accounts-card';
import { PasswordCard } from '@/components/password-card';
import { SessionStateCard } from '@/components/auth/session-state-card';
import { parseGrantedScopesHeader } from '@/lib/auth/external-login-consent';
import { redirect } from '@/i18n/navigation';
import { createServerClient } from '@game-guild/client';
import { getTranslations } from 'next-intl/server';
import React from 'react';

// Must live server-side: a 'use client' export would arrive here as a
// client-reference proxy whose lookups silently return undefined.
const ERROR_BANNER_KEYS: Record<
  string,
  'conflict' | 'lastSignInMethod' | 'stateMismatch' | 'generic'
> = {
  conflict: 'conflict',
  'last-method': 'lastSignInMethod',
  state_mismatch: 'stateMismatch',
};

/**
 * Account settings — Connected Accounts card for Google + Discord link /
 * unlink. Authentication is guarded here (mirroring the dashboard layout) and
 * the linked-provider metadata is fetched server-side with the session's
 * bearer via HEAD /v1/auth/external-logins (no body; providers arrive in the
 * X-Linked-Providers header as 'provider=iso-timestamp' pairs). The recorded
 * OAuth scope consents (issue #250) arrive in the X-Granted-Scopes header as
 * 'provider=iso-consent-timestamp|consent-version|url-encoded-scopes' entries.
 */
function parseLinkedProviders(header: string): LinkedAccount[] {
  return header
    .split(',')
    .filter(Boolean)
    .map((pair) => {
      const [provider, linkedAt] = pair.split('=');
      return { provider, linkedAt: linkedAt ?? '' };
    })
    .filter((row) => row.provider !== '' && row.linkedAt !== '');
}
export default async function AccountSettingsPage({
  params,
  searchParams,
}: { params: Promise<{ locale: string }>; searchParams: Promise<{ linked?: string; error?: string }> }): Promise<React.JSX.Element> {
  const [{ locale }, query] = await Promise.all([params, searchParams]);
  const t = await getTranslations({ locale, namespace: 'settings' });

  const session = await auth();
  if (!session || typeof session === 'function') {
    redirect({ href: { pathname: '/sign-in', query: { callbackUrl: '/workspace/settings/account' } }, locale });
    throw new Error('Unauthenticated dashboard access');
  }

  const apiUrl =
    process.env.API_URL ||
    process.env.NEXT_PUBLIC_API_URL ||
    'http://localhost:8080';
  const client = createServerClient({
    baseUrl: apiUrl,
    auth: { getAccessToken: () => getToken() },
  });

  let linkedAccounts: LinkedAccount[] = [];
  const result = await client.requestRaw<void>({
    method: 'HEAD',
    path: '/v1/auth/external-logins',
    requiresAuth: true,
  });
  if (result.ok) {
    const consentsByProvider = new Map(
      parseGrantedScopesHeader(result.data.headers.get('x-granted-scopes')).map((consent) => [
        consent.provider,
        consent,
      ]),
    );
    linkedAccounts = parseLinkedProviders(
      result.data.headers.get('x-linked-providers') ?? '',
    )
      .filter((row) => row.provider === 'google' || row.provider === 'discord')
      .map((row) => {
        const consent = consentsByProvider.get(row.provider);
        return {
          ...row,
          grantedScopes: consent?.grantedScopes ?? [],
          consentedAt: consent?.consentedAt ?? null,
          consentVersion: consent?.consentVersion ?? 0,
        };
      });
  }

  let banner: SettingsBanner = null;
  if (query?.linked === 'discord') {
    banner = { kind: 'linked', provider: 'discord' };
  } else if (typeof query?.error === 'string') {
    const code = ERROR_BANNER_KEYS[query.error];
    if (code) banner = { kind: 'error', code };
  }

  return (
    <div className="mx-auto max-w-2xl space-y-6">
      <header>
        <h1 className="text-3xl font-bold tracking-tight">{t('accountTitle')}</h1>
        <p className="text-muted-foreground">{t('accountDescription')}</p>
      </header>
      <ConnectedAccountsCard linkedAccounts={linkedAccounts} banner={banner} />
      <SessionStateCard />
      <PasswordCard />
    </div>
  );
}

import { NotificationPreferences } from '@/components/settings/notifications/notification-preferences';
import { Callout } from '@/components/ui/callout';
import { auth, getToken } from '@/auth';
import { redirect } from '@/i18n/navigation';
import { createServerClient, GeneratedApi } from '@game-guild/client';
import { getTranslations } from 'next-intl/server';
import React from 'react';

/**
 * Notification/email preferences — channel, category and per-type toggles,
 * email digest frequency and quiet hours. Backed by the Notifications-module
 * preference endpoints (never the deprecated UserPreferences jsonb resource).
 * Data is fetched server-side; writes go through server actions.
 */
export default async function NotificationSettingsPage({
  params,
}: {
  params: Promise<{ locale: string }>;
}): Promise<React.JSX.Element> {
  const { locale } = await params;
  const t = await getTranslations({ locale, namespace: 'settings' });
  const tp = await getTranslations({ locale, namespace: 'notificationPrefs' });

  const session = await auth();
  if (!session || typeof session === 'function') {
    redirect({
      href: { pathname: '/sign-in', query: { callbackUrl: '/workspace/settings/notifications' } },
      locale,
    });
    throw new Error('Unauthenticated dashboard access');
  }

  const apiUrl =
    process.env.API_URL ||
    process.env.NEXT_PUBLIC_API_URL ||
    'http://localhost:8080';
  const client = createServerClient({
    baseUrl: apiUrl,
    auth: { getAccessToken: () => getToken() },
  });
  const notifications = new GeneratedApi.NotificationsModule(client);

  const [preferencesResult, catalogResult] = await Promise.all([
    notifications.getApiNotificationsPreferences(),
    notifications.getApiNotificationsTypesCatalog(),
  ]);

  const preferences =
    preferencesResult.ok && catalogResult.ok && preferencesResult.data
      ? {
          emailEnabled: preferencesResult.data.emailEnabled ?? true,
          inAppEnabled: preferencesResult.data.inAppEnabled ?? true,
          pushEnabled: preferencesResult.data.pushEnabled ?? true,
          smsEnabled: preferencesResult.data.smsEnabled ?? false,
          marketingEnabled: preferencesResult.data.marketingEnabled ?? true,
          socialEnabled: preferencesResult.data.socialEnabled ?? true,
          learningEnabled: preferencesResult.data.learningEnabled ?? true,
          achievementsEnabled: preferencesResult.data.achievementsEnabled ?? true,
          emailDigestFrequency: preferencesResult.data.emailDigestFrequency ?? null,
          quietHoursStart: preferencesResult.data.quietHoursStart ?? null,
          quietHoursEnd: preferencesResult.data.quietHoursEnd ?? null,
          timezone: preferencesResult.data.timezone ?? null,
          mutedTypes: preferencesResult.data.mutedTypes ?? [],
        }
      : null;
  const catalog =
    catalogResult.ok && catalogResult.data
      ? catalogResult.data
          .filter((item) => item.type)
          .map((item) => ({
            type: item.type as string,
            displayName: item.displayName ?? (item.type as string),
            category: item.category ?? 'System',
            suppressible: item.suppressible ?? true,
          }))
      : null;

  return (
    <div className="mx-auto max-w-2xl space-y-6">
      <header>
        <h1 className="text-3xl font-bold tracking-tight">{t('notificationsTitle')}</h1>
        <p className="text-muted-foreground">{t('notificationsDescription')}</p>
      </header>
      {preferences && catalog && catalog.length > 0 ? (
        <NotificationPreferences preferences={preferences} catalog={catalog} />
      ) : (
        <Callout type="error" title={tp('loadError.title')}>
          {tp('loadError.description')}
        </Callout>
      )}
    </div>
  );
}

import { auth } from '@/auth';
import { ProfileForm } from '@/components/settings/profile-form';
import { getCommunityProfile, getProfile } from '@/lib/user-settings/queries';
import { getTranslations } from 'next-intl/server';
import React from 'react';

export default async function ProfileSettingsPage({
  params,
}: {
  params: Promise<{ locale: string }>;
}): Promise<React.JSX.Element> {
  const { locale } = await params;
  const [t, session, profile, socialProfile] = await Promise.all([
    getTranslations({ locale, namespace: 'settings.profile' }),
    auth(),
    getProfile(),
    getCommunityProfile().catch(() => null),
  ]);
  const accountName = session && typeof session !== 'function'
    ? session.user.name?.trim() || session.user.email?.split('@')[0] || t('fallbackName')
    : t('fallbackName');
  const accountEmail = session && typeof session !== 'function'
    ? session.user.email ?? t('fallbackEmail')
    : t('fallbackEmail');
  const currentUserId = session && typeof session !== 'function' ? session.user.id : null;
  const fallbackHandle = `${accountEmail.split('@')[0] ?? 'creator'}-${currentUserId?.slice(0, 6) ?? 'profile'}`
    .toLowerCase()
    .replace(/[^a-z0-9_-]/g, '-');

  return (
    <div className="space-y-6">
      <header>
        <h1 className="text-3xl font-bold tracking-tight">{t('title')}</h1>
        <p className="text-muted-foreground">{t('description')}</p>
      </header>
      <ProfileForm
        accountName={accountName}
        accountEmail={accountEmail}
        defaultValues={{
          handle: socialProfile?.handle ?? fallbackHandle,
          displayName: profile?.displayName ?? socialProfile?.displayName ?? accountName,
          bio: profile?.bio ?? '',
          location: profile?.location ?? '',
          website: profile?.website ?? '',
          jobTitle: profile?.jobTitle ?? '',
          company: profile?.company ?? '',
          avatarUrl: socialProfile?.avatarUrl ?? '',
          bannerUrl: socialProfile?.bannerUrl ?? '',
        }}
        defaultVisibility={socialProfile ? socialProfile.visibility : null}
        hasCommunityProfile={socialProfile !== null}
        publicProfilePath={`/social/profiles/${socialProfile?.handle ?? fallbackHandle}`}
      />
    </div>
  );
}

import { TestingEventApplications } from "@/components/testing-lab/testing-event-management";
import { getMembers } from "@/lib/community/queries/members";
import { TestingLabPageHeader } from "@/components/testing-lab/testing-lab-page-header";
import { TestingLabAccessIssues } from "@/components/testing-lab/testing-lab-state";
import { Link } from "@/i18n/navigation";
import { isTestingEventReadOnly } from "@/lib/testing-lab/event-workspace";
import { getTestingEventWorkspaceData } from "@/lib/testing-lab/events-queries";
import { getTestingProjectOptions } from "@/lib/testing-lab/queries";
import { cn } from "@game-guild/ui/lib/utils";
import type { TestingLabTestingApplicationStatus } from "@game-guild/client";
import { ClipboardList } from "lucide-react";
import { notFound } from "next/navigation";

const statuses: Array<{
  label: string;
  value?: TestingLabTestingApplicationStatus;
}> = [
  { label: "All" },
  { label: "Pending", value: "Pending" },
  { label: "In review", value: "UnderReview" },
  { label: "Approved", value: "Approved" },
  { label: "Waitlisted", value: "Waitlisted" },
  { label: "Rejected", value: "Rejected" },
];

export default async function TestingEventApplicationsPage({
  params,
  searchParams,
}: {
  params: Promise<{ eventId: string }>;
  searchParams: Promise<{ applicationStatus?: string }>;
}) {
  const [{ eventId }, query] = await Promise.all([params, searchParams]);
  const [detail, memberDirectory, projects] = await Promise.all([
    getTestingEventWorkspaceData(eventId),
    getMembers({ page: 1, limit: 100 }),
    getTestingProjectOptions(),
  ]);
  if (!detail.event) {
    if (detail.accessIssues.length > 0) {
      return (
        <div className="space-y-5">
          <TestingLabPageHeader
            headingLevel={2}
            icon={ClipboardList}
            title="Project applications"
            description="Review project candidates, record committee decisions, and reserve capacity only when a project is approved."
          />
          <TestingLabAccessIssues issues={detail.accessIssues} />
        </div>
      );
    }
    notFound();
  }
  const projectLabels = Object.fromEntries(
    projects.map((project) => [project.id, project.title]),
  );
  const memberLabels = Object.fromEntries(
    memberDirectory.members.map((member) => [
      member.id,
      member.displayName && member.email
        ? `${member.displayName} / ${member.email}`
        : member.displayName || member.email || "Member details unavailable",
    ]),
  );

  const selected = statuses.find(
    (status) => status.value === query.applicationStatus,
  )?.value;
  const applications = selected
    ? detail.applications.filter(
        (application) => application.status === selected,
      )
    : detail.applications;

  return (
    <div className="space-y-5">
      <TestingLabPageHeader
        headingLevel={2}
        icon={ClipboardList}
        title="Project applications"
        description="Review project candidates, record committee decisions, and reserve capacity only when a project is approved."
      />

      <TestingLabAccessIssues issues={detail.accessIssues} />

      <nav aria-label="Application status" className="flex flex-wrap gap-2">
        {statuses.map((status) => {
          const active =
            status.value === selected || (!status.value && !selected);
          const href = status.value
            ? `/workspace/testing-lab/events/${eventId}/applications?applicationStatus=${status.value}`
            : `/workspace/testing-lab/events/${eventId}/applications`;
          return (
            <Link
              key={status.label}
              href={href}
              aria-current={active ? "page" : undefined}
              className={cn(
                "rounded-md border px-3 py-1.5 text-sm text-muted-foreground hover:text-foreground",
                active && "border-foreground/20 bg-muted text-foreground",
              )}
            >
              {status.label}
            </Link>
          );
        })}
      </nav>

      <TestingEventApplications
        eventId={eventId}
        access={detail.applicationAccess}
        applications={applications}
        slots={detail.slots}
        readOnly={isTestingEventReadOnly(detail.event)}
        projectLabels={projectLabels}
        memberLabels={memberLabels}
      />
    </div>
  );
}

import { getMembers } from '@/lib/community/queries/members';
import { TestingLabPageHeader } from '@/components/testing-lab/testing-lab-page-header';
import { TestingLabAccessIssues, TestingLabEmptyState } from '@/components/testing-lab/testing-lab-state';
import { formatEventDateTime } from '@/lib/testing-lab/event-workspace';
import { getTestingEventFeedbackReview, getTestingEventWorkspaceData } from '@/lib/testing-lab/events-queries';
import { getTestingProjectOptions } from '@/lib/testing-lab/queries';
import { Badge } from '@game-guild/ui/components/badge';
import { BarChart3, CheckCircle2, Clock3, Star } from 'lucide-react';
import { notFound } from 'next/navigation';

function feedbackDetails(value?: string | null): Array<{ label: string; value: string }> {
  if (!value) return [];
  try {
    const parsed = JSON.parse(value) as unknown;
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      return Object.entries(parsed as Record<string, unknown>).map(([label, detail]) => ({
        label: label.replace(/([a-z])([A-Z])/g, '$1 $2').replace(/^./, (character) => character.toUpperCase()),
        value: typeof detail === 'string' ? detail : JSON.stringify(detail),
      }));
    }
  } catch {
    // Plain-text feedback remains a supported API payload.
  }
  return [{ label: 'Feedback', value }];
}

export default async function TestingEventFeedbackPage({ params }: { params: Promise<{ eventId: string }> }) {
  const { eventId } = await params;
  const [detail, review, memberDirectory, projects] = await Promise.all([getTestingEventWorkspaceData(eventId), getTestingEventFeedbackReview(eventId), getMembers({ page: 1, limit: 100 }), getTestingProjectOptions()]);
  if (!detail.event) notFound();

  const members = new Map(memberDirectory.members.map((member) => [member.id, member.displayName || member.email || 'Unknown tester']));
  const projectTitles = new Map(projects.map((project) => [project.id, project.title]));
  const applications = new Map(detail.applications.map((application) => [application.id, application]));
  const slots = new Map(detail.slots.map((slot) => [slot.id, slot]));
  const pending = review.feedback.filter((item) => item.status === 'Pending' || !item.feedback).length;
  const submitted = review.feedback.filter((item) => Boolean(item.feedback)).length;
  const ratings = review.feedback.map((item) => item.feedback?.overallRating).filter((rating): rating is number => typeof rating === 'number');
  const averageRating = ratings.length > 0 ? (ratings.reduce((sum, rating) => sum + rating, 0) / ratings.length).toFixed(1) : null;

  return (
    <div className="space-y-5">
      <TestingLabPageHeader headingLevel={2} icon={BarChart3} title="Feedback review" description="Read tester feedback and see which games are still waiting for responses." />

      <TestingLabAccessIssues issues={review.accessIssues} />

      <section className="grid gap-3 sm:grid-cols-3">
        <article className="rounded-md border p-4">
          <div className="flex items-center gap-2 text-muted-foreground">
            <Clock3 className="size-4" />
            <span className="text-sm">Awaiting feedback</span>
          </div>
          <p className="mt-2 text-2xl font-semibold">{pending} pending</p>
        </article>
        <article className="rounded-md border p-4">
          <div className="flex items-center gap-2 text-muted-foreground">
            <CheckCircle2 className="size-4" />
            <span className="text-sm">Received feedback</span>
          </div>
          <p className="mt-2 text-2xl font-semibold">{submitted} submitted</p>
        </article>
        <article className="rounded-md border p-4">
          <div className="flex items-center gap-2 text-muted-foreground">
            <Star className="size-4" />
            <span className="text-sm">Average rating</span>
          </div>
          <p className="mt-2 text-2xl font-semibold">{averageRating ? `${averageRating}/10` : 'No ratings'}</p>
        </article>
      </section>

      {review.feedback.length === 0 ? (
        <TestingLabEmptyState title="No feedback obligations yet" description="Assign an approved project to a checked-in tester to create a required feedback obligation." />
      ) : (
        <div className="divide-y rounded-md border">
          {review.feedback.map((item) => {
            const application = applications.get(item.applicationId);
            const projectTitle = application?.projectId ? (projectTitles.get(application.projectId) ?? 'Approved project') : 'Approved project';
            const testerName = item.testerUserId
              ? members.get(item.testerUserId) ?? 'Unknown tester'
              : 'Unknown tester';
            const slot = slots.get(item.slotId);
            const details = feedbackDetails(item.feedback?.feedbackData);

            return (
              <article key={item.obligationId} className="space-y-4 p-4">
                <header className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
                  <div className="min-w-0">
                    <h2 className="truncate font-semibold">{projectTitle}</h2>
                    <div className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm text-muted-foreground">
                      <span>{testerName}</span>
                      {slot?.startsAt ? <span className="before:mr-2 before:content-['/']">{formatEventDateTime(slot.startsAt, detail.event!.timeZoneId ?? 'UTC')}</span> : null}
                    </div>
                  </div>
                  <div className="flex flex-wrap items-center gap-2">
                    {typeof item.feedback?.overallRating === 'number' ? <Badge variant="secondary">{item.feedback.overallRating}/10</Badge> : null}
                    <Badge variant={item.feedback ? 'secondary' : 'outline'}>{item.feedback ? 'Submitted' : 'Pending'}</Badge>
                  </div>
                </header>

                {item.feedback ? (
                  <div className="grid gap-4 border-t pt-4 lg:grid-cols-[minmax(0,1fr)_minmax(14rem,0.4fr)]">
                    <dl className="grid gap-3 sm:grid-cols-2">
                      {details.map((detailItem) => (
                        <div key={detailItem.label}>
                          <dt className="text-xs font-medium text-muted-foreground">{detailItem.label}</dt>
                          <dd className="mt-1 text-sm">{detailItem.value}</dd>
                        </div>
                      ))}
                    </dl>
                    <div className="text-sm">
                      <p className="text-xs font-medium text-muted-foreground">Recommendation</p>
                      <p className="mt-1">{item.feedback.wouldRecommend === true ? 'Would recommend' : item.feedback.wouldRecommend === false ? 'Would not recommend' : 'Not provided'}</p>
                      {item.feedback.additionalNotes ? (
                        <>
                          <p className="mt-3 text-xs font-medium text-muted-foreground">Additional notes</p>
                          <p className="mt-1">{item.feedback.additionalNotes}</p>
                        </>
                      ) : null}
                    </div>
                  </div>
                ) : (
                  <p className="border-t pt-4 text-sm text-muted-foreground">This tester still needs to submit feedback before participation can be completed.</p>
                )}
              </article>
            );
          })}
        </div>
      )}
    </div>
  );
}

import {
  EditTestingEventDialog,
  TestingEventLifecycleActions,
} from "@/components/testing-lab/testing-event-management";
import { TestingEventWorkspaceNav } from "@/components/testing-lab/testing-event-workspace-nav";
