import { getMembers } from '@/lib/community/queries/members';
import { TestingSlotRegistrations, type TestingLabApprovedApplicationOption } from '@/components/testing-lab/testing-event-management';
import { TestingLabPageHeader } from '@/components/testing-lab/testing-lab-page-header';
import { formatEventDateRange, isTestingEventReadOnly } from '@/lib/testing-lab/event-workspace';
import { getTestingApplicationTesterEligibility, getTestingEventWorkspaceData } from '@/lib/testing-lab/events-queries';
import { getTestingProjectOptions } from '@/lib/testing-lab/queries';
import { Badge } from '@game-guild/ui/components/badge';
import { UsersRound } from 'lucide-react';
import { notFound } from 'next/navigation';

export default async function TestingEventTestersPage({ params }: { params: Promise<{ eventId: string }> }) {
  const { eventId } = await params;
  const [detail, memberDirectory, projects] = await Promise.all([getTestingEventWorkspaceData(eventId), getMembers({ page: 1, limit: 100 }), getTestingProjectOptions()]);
  if (!detail.event) notFound();

  const testerUserIds = [...new Set(
    Object.values(detail.registrationsBySlot)
      .flat()
      .map((registration) => registration.userId)
      .filter((userId): userId is string => Boolean(userId)),
  )];
  const testerEligibility = await getTestingApplicationTesterEligibility(eventId, testerUserIds);
  const eligibleTesterIdsByApplication = new Map<string, string[]>();
  testerEligibility.eligibility.forEach(({ testerUserId, eligibleApplicationIds }) => {
    if (!testerUserId) return;
    (eligibleApplicationIds ?? []).forEach((applicationId) => {
      const testerIds = eligibleTesterIdsByApplication.get(applicationId) ?? [];
      testerIds.push(testerUserId);
      eligibleTesterIdsByApplication.set(applicationId, testerIds);
    });
  });

  const readOnly = isTestingEventReadOnly(detail.event);
  const terminalStatuses = new Set(['Cancelled', 'Completed', 'NoShow']);
  const isActiveRegistration = (status?: string | null) => !terminalStatuses.has(status ?? '');
  const total = Object.values(detail.registrationsBySlot)
    .flat()
    .filter((registration) => isActiveRegistration(registration.status)).length;
  const memberLabels = Object.fromEntries(memberDirectory.members.map((member) => [member.id, member.displayName || member.email || 'Unknown tester']));
  const projectLabels = new Map(projects.map((project) => [project.id, project.title]));
  const approvedApplications: TestingLabApprovedApplicationOption[] = detail.applications
    .filter(
      (
        application,
      ): application is typeof application & {
        id: string;
        projectId: string;
      } => application.status === 'Approved' && Boolean(application.id) && Boolean(application.projectId),
    )
    .map((application) => ({
      id: application.id,
      slotId: application.assignedSlotId,
      label: projectLabels.get(application.projectId) ?? 'Approved project',
      eligibleTesterUserIds: eligibleTesterIdsByApplication.get(application.id) ?? [],
    }));

  return (
    <div className="space-y-5">
      <TestingLabPageHeader headingLevel={2} icon={UsersRound} title="Participants and attendance" description="See who signed up, record attendance, and assign games to testers." />

      <p className="text-sm text-muted-foreground">{total === 1 ? '1 tester registered across this event.' : `${total} testers registered across this event.`}</p>
      {testerEligibility.accessIssues.length > 0 ? (
        <p role="alert" className="text-sm text-destructive">
          Project eligibility could not be loaded. Assignment is disabled to prevent conflicts of interest.
        </p>
      ) : null}

      {detail.slots.length === 0 ? (
        <div className="rounded-md border border-dashed p-8 text-center">
          <h2 className="font-medium">No tester schedule available</h2>
          <p className="mt-1 text-sm text-muted-foreground">Create event slots before accepting tester registrations.</p>
        </div>
      ) : (
        <div className="space-y-3">
          {detail.slots.map((slot) => {
            const registrations = slot.id ? (detail.registrationsBySlot[slot.id] ?? []) : [];
            const activeRegistrationCount = registrations.filter((registration) =>
              isActiveRegistration(registration.status),
            ).length;
            return (
              <section key={slot.id} className="rounded-md border p-4">
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <div>
                    <h2 className="font-semibold">{formatEventDateRange(slot.startsAt, slot.endsAt, detail.event!.timeZoneId ?? 'UTC')}</h2>
                    <p className="text-sm text-muted-foreground">{slot.campusName ?? slot.meetingUrl ?? slot.mode}</p>
                  </div>
                  <Badge variant="outline">{activeRegistrationCount} registered</Badge>
                </div>
                <TestingSlotRegistrations eventId={eventId} registrations={registrations} memberLabels={memberLabels} approvedApplications={approvedApplications} readOnly={readOnly} />
              </section>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { CreateTestingEventDialog, RestoreTestingEventDialog } from '@/components/testing-lab/testing-event-management';
import { TestingEventDirectoryFilters } from '@/components/testing-lab/testing-event-directory-filters';
import { formatTestingEventStatus } from '@/lib/testing-lab/format';
import { countLabel, formatEventDateRange } from '@/lib/testing-lab/event-workspace';
import { TestingLabPageHeader } from '@/components/testing-lab/testing-lab-page-header';
import { TestingLabAccessIssues, TestingLabEmptyState } from '@/components/testing-lab/testing-lab-state';
import { Link } from '@/i18n/navigation';
import { getTestingLabSettings } from '@/lib/testing-lab';
import { getArchivedTestingEventsDirectory, getTestingEventTemplates, getTestingEventsDirectory } from '@/lib/testing-lab/events-queries';
import type { TestingLabTestingEventStatus } from '@game-guild/client';
import { Badge } from '@game-guild/ui/components/badge';
import { buttonVariants } from '@game-guild/ui/components/button-variants';
import { CalendarDays, ChevronRight, FlaskConical, Layers3 } from 'lucide-react';

const statuses: TestingLabTestingEventStatus[] = [
  'Draft',
  'ApplicationsOpen',
  'ApplicationsClosed',
  'Scheduled',
  'Active',
  'Completed',
  'Cancelled',
];

function eventDateRange(startsAt?: string, endsAt?: string, timeZoneId?: string | null) {
  return formatEventDateRange(startsAt, endsAt, timeZoneId || 'UTC');
}

export default async function TestingEventsPage({
  searchParams,
}: {
  searchParams: Promise<{ status?: string; q?: string; page?: string; archived?: string }>;
}) {
  const query = await searchParams;
  const archived = query.archived === 'true';
  const selectedStatus = statuses.find((status) => status === query.status);
  const directory = archived
    ? await getArchivedTestingEventsDirectory({ skip: 0, take: 100 })
    : await getTestingEventsDirectory({ status: selectedStatus, skip: 0, take: 100 });
  const templates = archived ? { templates: [], accessIssues: [] } : await getTestingEventTemplates();
  const labSettings = await getTestingLabSettings();
  const searchTerm = query.q?.trim().toLocaleLowerCase() ?? '';
  const filteredEvents = directory.events.filter((event) =>
    searchTerm
      ? `${event.name ?? ''} ${event.description ?? ''} ${event.mode ?? ''}`.toLocaleLowerCase().includes(searchTerm)
      : true,
  );
  const pageSize = 25;
  const page = Math.max(1, Number.parseInt(query.page ?? '1', 10) || 1);
  const pageCount = Math.max(1, Math.ceil(filteredEvents.length / pageSize));
  const visibleEvents = filteredEvents.slice((Math.min(page, pageCount) - 1) * pageSize, Math.min(page, pageCount) * pageSize);
  const querySuffix = `${archived ? '&archived=true' : ''}${selectedStatus ? `&status=${selectedStatus}` : ''}${query.q ? `&q=${encodeURIComponent(query.q)}` : ''}`;

  return (
    <div className="flex flex-col gap-6 p-4 lg:p-6">
      <TestingLabPageHeader
        icon={CalendarDays}
        title="Testing events"
        description="Publish playtests, review game applications, and organize tester sessions."
        actions={
          <CreateTestingEventDialog
            templates={templates.templates}
            defaultTimeZone={labSettings.settings?.timezone ?? 'UTC'}
          />
        }
        navigation={
          <TestingEventDirectoryFilters
            search={query.q}
            status={selectedStatus}
            archived={archived}
          />
        }
      />
      <TestingLabAccessIssues issues={[...directory.accessIssues, ...templates.accessIssues, ...labSettings.accessIssues]} />
      {visibleEvents.length === 0 ? (
        <TestingLabEmptyState
          title={searchTerm ? 'No matching events' : archived ? 'No archived events' : 'No testing events'}
          description={searchTerm ? 'Adjust the search or status filter.' : archived ? 'Completed and cancelled events can be archived from their management workspace.' : 'Create an event to collect project applications and organize independent online or campus test slots.'}
          action={
            archived ? undefined : (
              <CreateTestingEventDialog
                templates={templates.templates}
                defaultTimeZone={labSettings.settings?.timezone ?? 'UTC'}
              />
            )
          }
        />
      ) : (
        <section className="divide-y border-y" aria-label="Testing event directory">
          {visibleEvents.map((event) => (
            <article key={event.id} className="grid gap-4 p-4 lg:grid-cols-[minmax(0,1fr)_auto] lg:items-center">
              <div className="min-w-0">
                <div className="flex flex-wrap items-center gap-2">
                  <h2 className="truncate font-semibold">{event.name ?? 'Untitled testing event'}</h2>
                  <Badge variant="outline">{formatTestingEventStatus(event.status)}</Badge>
                  <Badge variant="secondary">{event.mode ?? 'Online'}</Badge>
                </div>
                <p className="mt-1 line-clamp-2 text-sm text-muted-foreground">{event.description ?? 'No event brief.'}</p>
                <div className="mt-3 flex flex-wrap gap-x-5 gap-y-1 text-xs text-muted-foreground">
                  <span className="flex items-center gap-1.5"><CalendarDays className="size-3.5" />{eventDateRange(event.startsAt, event.endsAt, event.timeZoneId)}</span>
                  <span className="flex items-center gap-1.5"><Layers3 className="size-3.5" />{event.slotCount ?? 0} {event.slotCount === 1 ? 'session' : 'sessions'}</span>
                  <span className="flex items-center gap-1.5"><FlaskConical className="size-3.5" />{countLabel(event.applicationCount ?? 0, 'game application')}</span>
                </div>
              </div>
              {archived ? (
                <RestoreTestingEventDialog event={event} />
              ) : event.id ? (
                <Link
                  href={`/workspace/testing-lab/events/${event.id}`}
                  className={buttonVariants({ variant: 'outline' })}
                >
                  Open event workspace<ChevronRight className="ml-2 size-4" />
                </Link>
              ) : null}
            </article>
          ))}
        </section>
      )}
      {pageCount > 1 ? (
        <nav aria-label="Testing event pages" className="flex items-center justify-end gap-2">
          {page <= 1 ? (
            <span
              aria-disabled="true"
              className={buttonVariants({ size: 'sm', variant: 'outline', className: 'pointer-events-none opacity-50' })}
            >
              Previous
            </span>
          ) : (
            <Link
              href={`/workspace/testing-lab/events?page=${page - 1}${querySuffix}`}
              className={buttonVariants({ size: 'sm', variant: 'outline' })}
            >
              Previous
            </Link>
          )}
          <span className="text-sm text-muted-foreground">Page {Math.min(page, pageCount)} of {pageCount}</span>
          {page >= pageCount ? (
            <span
              aria-disabled="true"
              className={buttonVariants({ size: 'sm', variant: 'outline', className: 'pointer-events-none opacity-50' })}
            >
              Next
            </span>
          ) : (
            <Link
              href={`/workspace/testing-lab/events?page=${page + 1}${querySuffix}`}
              className={buttonVariants({ size: 'sm', variant: 'outline' })}
            >
              Next
            </Link>
          )}
        </nav>
      ) : null}
    </div>
  );
}

import { TestingLabCalendar } from "@/components/testing-lab/testing-lab-calendar";
import { CreateTestingEventDialog } from "@/components/testing-lab/testing-event-management";
import { TestingLabAccessIssues } from "@/components/testing-lab/testing-lab-state";
import { Link } from "@/i18n/navigation";
import {
  getTestingLabAnalytics,
  getTestingLabSettings,
} from "@/lib/testing-lab";
import {
  getTestingApplicationsDirectory,
  getTestingEventTemplates,
  getTestingEventsDirectory,
} from "@/lib/testing-lab/events-queries";
import { buttonVariants } from "@game-guild/ui/components/button-variants";
import {
  ClipboardCheck,
  ExternalLink,
  FlaskConical,
  TriangleAlert,
} from "lucide-react";

export default async function TestingLabPage() {
  const [
    analytics,
    events,
    pendingApplications,
    labSettings,
    templates,
  ] =
    await Promise.all([
      getTestingLabAnalytics(),
      getTestingEventsDirectory({ take: 100 }),
      getTestingApplicationsDirectory({ status: "Pending" }),
      getTestingLabSettings(),
      getTestingEventTemplates(),
    ]);
  const issues = [
    ...analytics.accessIssues,
    ...events.accessIssues,
    ...pendingApplications.accessIssues,
    ...labSettings.accessIssues,
    ...templates.accessIssues,
  ];
  const draftEvents = events.events.filter(
    (event) => event.status === "Draft",
  ).length;
  const attentionItems = [
    {
      count: pendingApplications.entries.length,
      label: `Review ${pendingApplications.entries.length} pending game application${pendingApplications.entries.length === 1 ? "" : "s"}`,
      href: pendingApplications.entries[0]?.event.id
        ? `/workspace/testing-lab/events/${pendingApplications.entries[0].event.id}/applications?applicationStatus=Pending`
        : "/workspace/testing-lab/events",
      Icon: ClipboardCheck,
    },
    {
      count: draftEvents,
