import type { Metadata } from 'next';
import { notFound, permanentRedirect } from 'next/navigation';

import { BlogPostView } from '@/components/blogs/blog-post-view';
import { BlogComments } from '@/components/blogs/blog-comments';
import { BlogReactions } from '@/components/blogs/blog-reactions';
import { buildBlogPostMetadata, isReservedBlogSegment, type BlogAuthorProfile } from '@/lib/blogs/seo';
import { getBlogPost } from '@/lib/blogs/queries';
import { getViewerBlogAuthor } from '@/lib/blogs/actions';

interface PostPageProps {
  readonly params: Promise<{ username: string; slug: string }>;
}

export async function generateMetadata({ params }: PostPageProps): Promise<Metadata> {
  const { username, slug } = await params;

  if (isReservedBlogSegment(username)) {
    return { title: 'Not Found', robots: { index: false, follow: false } };
  }

  const lookup = await getBlogPost(decodeURIComponent(username), decodeURIComponent(slug));
  if (lookup.status !== 'ok') {
    return { title: 'Not Found', robots: { index: false, follow: false } };
  }

  const authorProfiles: BlogAuthorProfile[] = [
    { handle: lookup.post.primaryAuthorHandle, displayName: lookup.post.primaryAuthorDisplayName },
    ...(lookup.post.coAuthorHandles ?? []).map((handle) => ({ handle, displayName: null as string | null })),
  ];

  return buildBlogPostMetadata(lookup.post, authorProfiles);
}

export default async function BlogPostPage({ params }: PostPageProps) {
  const { username, slug } = await params;

  if (isReservedBlogSegment(username)) {
    notFound();
  }

  const lookup = await getBlogPost(decodeURIComponent(username), decodeURIComponent(slug));

  if (lookup.status === 'redirect') {
    permanentRedirect(`/blogs/${lookup.redirect.handle}/${lookup.redirect.slug}`);
  }

  if (lookup.status === 'not-found') {
    notFound();
  }

  const post = lookup.post;
  const viewer = await getViewerBlogAuthor();

  return (
    <>
      <BlogPostView post={post} />
      {post.id ? (
        <div className="mx-auto max-w-3xl px-4 pb-12">
          <BlogReactions
            postId={post.id}
            currentUserId={viewer.userId}
            initialReactionCount={post.reactionCount ?? 0}
          />
          <BlogComments
            postId={post.id}
            allowComments={post.allowComments ?? true}
            currentUserId={viewer.userId}
            isPostAuthor={
              viewer.handle != null &&
              viewer.handle.length > 0 &&
              (viewer.handle === username ||
                (post.coAuthorHandles ?? []).includes(viewer.handle))
            }
            coAuthorIds={[]}
            currentUserHandle={viewer.handle}
          />
        </div>
      ) : null}
    </>
  );
}

import type { Metadata } from 'next';
import Link from 'next/link';
import { notFound } from 'next/navigation';

import { BlogPostCard } from '@/components/blogs/blog-post-card';
import { BLOG_INDEX_PATH, buildBlogAuthorPath, isReservedBlogSegment } from '@/lib/blogs/seo';
import { getAuthorPosts } from '@/lib/blogs/queries';

interface AuthorPageProps {
  readonly params: Promise<{ username: string }>;
  readonly searchParams: Promise<{ before?: string; beforeId?: string }>;
}

function cursorFromParams(searchParams: { before?: string; beforeId?: string }): { beforePublishedAt: string; beforeId: string } | undefined {
  return searchParams.before && searchParams.beforeId
    ? { beforePublishedAt: searchParams.before, beforeId: searchParams.beforeId }
    : undefined;
}

export async function generateMetadata({ params }: AuthorPageProps): Promise<Metadata> {
  const { username } = await params;
  return {
    title: `${decodeURIComponent(username)} — posts`,
    description: `All published posts by ${decodeURIComponent(username)} on GameGuild.`,
    robots: { index: true, follow: true },
  };
}

export default async function AuthorBlogPage({ params, searchParams }: AuthorPageProps) {
  const [{ username }, query] = await Promise.all([params, searchParams]);

  if (isReservedBlogSegment(username)) {
    notFound();
  }

  const handle = decodeURIComponent(username);
  const page = await getAuthorPosts(handle, cursorFromParams(query));

  if (!page) {
    notFound();
  }

  const items = page.items;
  const last = items[items.length - 1];
  const nextCursor =
    page.hasMore && last ? `?before=${encodeURIComponent(last.publishedAt ?? '')}&beforeId=${encodeURIComponent(last.id ?? '')}` : null;

  return (
    <main className="min-h-screen bg-[#070a12] text-white">
      <section className="border-b border-white/10">
        <div className="container mx-auto flex flex-col gap-4 px-4 py-16">
          <p className="text-sm text-slate-400">
            <Link href={BLOG_INDEX_PATH} className="hover:text-slate-200">
              Blog
            </Link>
            <span aria-hidden="true"> / </span>
            <span className="text-slate-300">{handle}</span>
          </p>
          <h1 className="text-4xl font-semibold tracking-tight md:text-5xl">{handle}</h1>
          <p className="text-sm text-slate-400">
            <a href={`${buildBlogAuthorPath(handle)}/rss.xml`} className="hover:text-slate-200">
              RSS feed
            </a>
          </p>
        </div>
      </section>

      <section className="container mx-auto px-4 py-12">
        {items.length === 0 ? (
          <p className="text-slate-400">No posts published yet.</p>
