'use client';

const IMAGE_EXTENSIONS = ['.png', '.jpg', '.jpeg', '.gif', '.webp', '.svg', '.bmp', '.avif'];

function fileNameOf(payload: string): string {
  const withoutQuery = payload.split('?')[0] ?? payload;
  const segments = withoutQuery.split('/');
  return segments[segments.length - 1] || withoutQuery;
}

/**
 * FilePayload viewer. The payload is a file reference (URL or filename):
 * images render inline, PDFs embed via <object>, everything else gets a
 * filename + download link.
 */
export function FileViewer({ payload }: { payload: string }): React.JSX.Element {
  const name = fileNameOf(payload);
  const lower = name.toLowerCase();
  const isImage = IMAGE_EXTENSIONS.some((ext) => lower.endsWith(ext));
  const isPdf = lower.endsWith('.pdf');

  if (isImage) {
    return (
      <div data-testid="file-viewer">
        <img data-testid="file-image" src={payload} alt={name} className="max-h-[70vh] w-full rounded-md border object-contain" />
      </div>
    );
  }

  if (isPdf) {
    return (
      <div data-testid="file-viewer">
        <object data-testid="file-pdf" data={payload} type="application/pdf" className="h-[70vh] w-full rounded-md border">
          <a href={payload} className="text-sm text-primary underline">
            {name}
          </a>
        </object>
      </div>
    );
  }

  return (
    <div data-testid="file-viewer" className="space-y-2 rounded-md border bg-card p-4">
      <div data-testid="file-fallback" className="flex items-center gap-2 text-sm">
        <span className="font-medium">{name}</span>
      </div>
      <a
        data-testid="file-download"
        href={payload}
        download={name}
        target="_blank"
        rel="noopener noreferrer"
        className="text-sm text-primary underline-offset-4 hover:underline"
      >
        Download file
      </a>
    </div>
  );
}

'use client';

import { useCallback, useEffect, useMemo, useState } from 'react';
import type {
  LearningAssessmentsGradingQueueAssessment,
  LearningAssessmentsGradingQueueItem,
} from '@game-guild/client';
import type {
  AssessmentSubmissionRuntimeViewV1,
  GradeItemResultV1,
} from '@game-guild/grading';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { Input } from '@game-guild/ui/components/input';
import { Textarea } from '@game-guild/ui/components/textarea';
import { CalendarClock, CalendarX, CheckCircle2, EyeOff, Send } from 'lucide-react';
import {
  cancelRuntimeSubmissionReleaseSchedule,
  getRuntimeSubmission,
  regradeRuntimeSubmission,
  releaseRuntimeSubmission,
  resolveRuntimeInstructorReview,
  scheduleRuntimeSubmissionRelease,
} from '@/lib/learning/grading-runtime-actions';
import {
  pointsToScoreUnits,
  scoreUnitsToPoints,
} from '@/lib/learning/academic-values';
import { useRouter } from '@/i18n/navigation';

const dateFormatter = new Intl.DateTimeFormat('en-US', {
  year: 'numeric',
  month: 'short',
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
});

export interface GradingPanelProps {
  item: LearningAssessmentsGradingQueueItem;
  assessment: LearningAssessmentsGradingQueueAssessment;
  onReviewStateChanged?: (submission: AssessmentSubmissionRuntimeViewV1) => void;
}

interface ItemResolutionState {
  points: string;
  feedback: string;
}

export function GradingPanel(props: GradingPanelProps): React.JSX.Element {
  return <GradingPanelSession key={props.item.submissionId} {...props} />;
}

function GradingPanelSession({
  item,
  assessment,
  onReviewStateChanged,
}: GradingPanelProps): React.JSX.Element {
  const router = useRouter();
  const [submission, setSubmission] =
    useState<AssessmentSubmissionRuntimeViewV1 | null>(null);
  const [resolutions, setResolutions] = useState<
    Record<string, ItemResolutionState>
  >({});
  const [overallFeedback, setOverallFeedback] = useState('');
  const [criterionScores, setCriterionScores] = useState<Record<string, string>>({});
  const [overrideReason, setOverrideReason] = useState('');
  const [regradeReason, setRegradeReason] = useState('');
  const [releaseScheduledFor, setReleaseScheduledFor] = useState('');
  const [releaseScheduleReason, setReleaseScheduleReason] = useState('');
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const orderedItemIds = useMemo(() => {
    if (!submission) return [];
    const known = new Set(Object.keys(submission.execution.itemMaxScores));
    const ordered = submission.execution.delivery.itemOrder.filter((id) =>
      known.delete(id),
    );
    return [...ordered, ...known];
  }, [submission]);

  const acceptRuntimeSubmission = useCallback((nextSubmission: AssessmentSubmissionRuntimeViewV1) => {
    setSubmission(nextSubmission);
    const resultByItem = new Map(
      (nextSubmission.execution.instructorVisibleResult?.items ?? []).map(
        (result) => [result.itemId, result],
      ),
    );
    const next = Object.fromEntries(
      Object.entries(nextSubmission.execution.itemMaxScores).map(
        ([itemId]) => {
          const result = resultByItem.get(itemId);
          return [
            itemId,
            {
              points:
                result?.score == null
                  ? ''
                  : String(scoreUnitsToPoints(result.score)),
              feedback: result?.feedback ?? '',
            },
          ];
        },
      ),
    );
    setResolutions(next);
    setOverallFeedback(
      nextSubmission.execution.instructorVisibleResult?.feedback ?? '',
    );
    setCriterionScores(Object.fromEntries(Object.entries(
      nextSubmission.execution.instructorVisibleRubricScores ?? {},
    ).map(([id, units]) => [id, String(scoreUnitsToPoints(units))])));
    const activeRound = nextSubmission.execution.history.find(
      (round) => round.roundId === nextSubmission.execution.activeRoundId,
    );
    setReleaseScheduledFor(
      activeRound?.releaseSchedule?.status === 'scheduled'
        ? toLocalDateTimeInput(activeRound.releaseSchedule.scheduledFor)
        : '',
    );
  }, []);

  useEffect(() => {
    let cancelled = false;
    getRuntimeSubmission(item.submissionId ?? '').then((result) => {
      if (cancelled) return;
      setLoading(false);
      if (!result.success) {
        setError(result.error);
        return;
      }
      acceptRuntimeSubmission(result.data);
    });
    return () => { cancelled = true; };
  }, [item.submissionId, acceptRuntimeSubmission]);

  const frozenRubric = submission?.execution.instructorVisibleRubric;
  const rubricValues = frozenRubric?.criteria.map((criterion) => {
    try {
      const raw = criterionScores[criterion.id] ?? '';
      if (!raw.trim()) return null;
      const units = pointsToScoreUnits(raw);
      return units <= criterion.points ? units : null;
    } catch { return null; }
  });
  const rubricComplete = rubricValues?.every((value) => value !== null);
  const rubricTotal = rubricComplete ? rubricValues.reduce<number>((sum, value) => sum + value, 0) : 0;

  const itemRows = orderedItemIds.map((itemId) => {
    const maxUnits = submission?.execution.itemMaxScores[itemId] ?? 0;
    const raw = itemId === 'code' && frozenRubric
      ? rubricComplete ? String(scoreUnitsToPoints(rubricTotal)) : ''
      : resolutions[itemId]?.points ?? '';
    let scoreUnits: ReturnType<typeof pointsToScoreUnits> | null = null;
    try {
      if (raw.trim()) scoreUnits = pointsToScoreUnits(raw);
    } catch {
      scoreUnits = null;
    }
    return {
      itemId,
      label: readItemLabel(submission, itemId),
      maxUnits,
      maxPoints: scoreUnitsToPoints(maxUnits),
      raw,
      scoreUnits,
      valid: scoreUnits != null && scoreUnits <= maxUnits,
      prior: submission?.execution.instructorVisibleResult?.items.find(
        (entry) => entry.itemId === itemId,
      ),
    };
  });
  const canResolve =
    submission?.execution.requiresInstructorReview === true &&
    itemRows.length > 0 &&
    itemRows.every((row) => row.valid) &&
    !submitting;
  const finalResult =
    submission?.execution.instructorVisibleResult?.state === 'final'
      ? submission.execution.instructorVisibleResult
      : null;
  const activeRound = submission?.execution.history.find(
    (round) => round.roundId === submission.execution.activeRoundId,
  );
  const activeRoundReleased = activeRound?.released === true;
  const canRelease = Boolean(
    submission &&
      finalResult &&
      activeRound?.status === 'finalized' &&
      !activeRoundReleased,
  );
  const releaseSchedule = activeRound?.releaseSchedule ?? null;
  const scheduledReleaseTimestamp = Date.parse(releaseScheduledFor);
  const canSchedule = Boolean(
    canRelease &&
      releaseScheduledFor &&
      Number.isFinite(scheduledReleaseTimestamp),
  );

  async function submitReview() {
    if (!submission || !canResolve) return;
    setSubmitting(true);
    setError(null);
    const result = await resolveRuntimeInstructorReview(
      submission.submissionId,
      {
        schemaVersion: 1,
        items: itemRows.map((row) => ({
          itemId: row.itemId,
          score: row.scoreUnits!,
          feedback: resolutions[row.itemId]?.feedback.trim() || null,
        })),
        feedback: overallFeedback.trim() || null,
        overrideReason: overrideReason.trim() || null,
        ...(frozenRubric ? {
          rubricScores: Object.fromEntries(frozenRubric.criteria.map((criterion) => [
            criterion.id, pointsToScoreUnits(criterionScores[criterion.id] ?? ''),
          ])),
        } : {}),
      },
      createIdempotencyKey(),
    );
    setSubmitting(false);
    if (!result.success) {
      setError(result.error);
      return;
    }
    acceptRuntimeSubmission(result.data);
    onReviewStateChanged?.(result.data);
  }

  async function releaseResult() {
    if (!submission || !submission.execution.activeRoundId) return;
    setSubmitting(true);
    setError(null);
    const result = await releaseRuntimeSubmission(
      {
        submissionId: submission.submissionId,
        version: submission.version,
        expectedRoundId: submission.execution.activeRoundId,
      },
      'Released by instructor from SpeedGrader.',
      createIdempotencyKey(),
    );
    setSubmitting(false);
    if (!result.success) {
      setError(result.error);
      return;
    }
    const refreshed = await getRuntimeSubmission(submission.submissionId);
    if (refreshed.success) acceptRuntimeSubmission(refreshed.data);
    router.refresh();
  }

  async function scheduleResultRelease() {
    if (!submission || !submission.execution.activeRoundId || !canSchedule) return;
    if (scheduledReleaseTimestamp <= Date.now()) {
      setError('Scheduled release must be in the future.');
      return;
    }
    setSubmitting(true);
    setError(null);
    const result = await scheduleRuntimeSubmissionRelease(
      {
        submissionId: submission.submissionId,
        version: submission.version,
        expectedRoundId: submission.execution.activeRoundId,
        expectedScheduleVersion: releaseSchedule?.version ?? 0,
      },
      new Date(scheduledReleaseTimestamp).toISOString(),
      releaseScheduleReason.trim() || null,
      createIdempotencyKey(),
    );
    setSubmitting(false);
    if (!result.success) {
      setError(result.error);
      return;
    }
    const refreshed = await getRuntimeSubmission(submission.submissionId);
    if (refreshed.success) acceptRuntimeSubmission(refreshed.data);
    router.refresh();
  }

  async function cancelScheduledRelease() {
    if (
      !submission ||
      !submission.execution.activeRoundId ||
      releaseSchedule?.status !== 'scheduled' ||
      !releaseScheduleReason.trim()
    ) return;
    setSubmitting(true);
    setError(null);
    const result = await cancelRuntimeSubmissionReleaseSchedule(
      {
        submissionId: submission.submissionId,
        version: submission.version,
        expectedRoundId: submission.execution.activeRoundId,
        expectedScheduleVersion: releaseSchedule.version,
      },
      releaseScheduleReason.trim(),
      createIdempotencyKey(),
    );
    setSubmitting(false);
    if (!result.success) {
      setError(result.error);
      return;
    }
    const refreshed = await getRuntimeSubmission(submission.submissionId);
    if (refreshed.success) acceptRuntimeSubmission(refreshed.data);
    router.refresh();
  }

  async function startRegrade() {
    if (!submission || !regradeReason.trim()) return;
    setSubmitting(true);
    setError(null);
    const result = await regradeRuntimeSubmission(
      submission.submissionId,
      regradeReason.trim(),
      createIdempotencyKey(),
    );
    setSubmitting(false);
    if (!result.success) {
      setError(result.error);
      return;
    }
    acceptRuntimeSubmission(result.data);
    setRegradeReason('');
    onReviewStateChanged?.(result.data);
  }

  return (
    <div data-testid="grading-panel" className="h-full space-y-4 overflow-auto p-4">
      <div data-testid="attempt-meta" className="flex flex-wrap items-center gap-2 text-sm text-muted-foreground">
        <span>
          attempt {item.attemptNumber ?? 1}
          {item.attemptCount ? ` of ${item.attemptCount}` : ''}
        </span>
        {item.submittedAt && (
          <span>· {dateFormatter.format(new Date(item.submittedAt))}</span>
        )}
        {item.isLate && <Badge variant="destructive">Late</Badge>}
        {submission?.execution.requiresInstructorReview && (
          <Badge variant="secondary">Instructor review</Badge>
        )}
        {submission?.execution.released && <Badge>Released</Badge>}
      </div>

      {item.isGroup && (item.memberNames?.length ?? 0) > 0 && (
        <div data-testid="group-banner" className="rounded-md border bg-muted/40 p-3">
          <p className="text-sm font-medium">
            One result applies to {item.memberNames?.length} frozen participants
          </p>
          <div data-testid="group-members" className="mt-2 flex flex-wrap gap-1">
            {item.memberNames?.map((name) => (
              <Badge key={name} variant="secondary">{name}</Badge>
            ))}
          </div>
        </div>
      )}

      {loading && <p className="text-sm text-muted-foreground">Loading grading round...</p>}

      {!loading && submission && (
        <>
          {frozenRubric && (
            <section data-testid="rubric-grid" className="space-y-3" aria-label="Frozen scoring rubric">
              <h2 className="text-sm font-semibold">{frozenRubric.title}</h2>
              {frozenRubric.criteria.map((criterion) => (
                <div key={criterion.id} data-testid={`criterion-row-${criterion.id}`} className="space-y-2 rounded-md border p-3">
                  <label htmlFor={`criterion-${criterion.id}`} className="text-sm font-medium">{criterion.description}</label>
                  <div className="flex items-center gap-2">
                    <Input id={`criterion-${criterion.id}`} data-testid={`criterion-points-${criterion.id}`}
                      type="number" min={0} max={scoreUnitsToPoints(criterion.points)} step="0.01"
                      value={criterionScores[criterion.id] ?? ''}
                      disabled={!submission.execution.requiresInstructorReview || submitting}
                      onChange={(event) => setCriterionScores((current) => ({ ...current, [criterion.id]: event.target.value }))}
                      className="w-28" />
                    <span>/ {scoreUnitsToPoints(criterion.points)}</span>
                  </div>
                </div>
              ))}
              <p data-testid="rubric-total">Total: {scoreUnitsToPoints(rubricTotal)}</p>
            </section>
          )}
          <section className="space-y-3" aria-label="Item scores">
            <div className="flex items-center justify-between gap-2">
              <h2 className="text-sm font-semibold">Item scores</h2>
              <span className="text-xs text-muted-foreground">
                Total is calculated by the server
              </span>
            </div>
            {itemRows.map((row) => (
              <div key={row.itemId} className="space-y-2 rounded-md border p-3">
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <p className="text-sm font-medium">{row.label}</p>
                    <p className="text-xs text-muted-foreground">{row.itemId}</p>
                  </div>
                  {row.prior && <ResultStateBadge result={row.prior} />}
                </div>
                <div className="flex items-center gap-2">
                  <Input
                    data-testid={`item-score-${row.itemId}`}
                    aria-label={`Score for ${row.label}`}
                    type="number"
                    min={0}
                    max={row.maxPoints}
                    step="0.01"
                    value={row.raw}
                    disabled={!submission.execution.requiresInstructorReview || submitting ||
                      (row.itemId === 'code' && Boolean(frozenRubric))}
                    onChange={(event) =>
                      setResolutions((current) => ({
                        ...current,
                        [row.itemId]: {
                          ...(current[row.itemId] ?? { feedback: '' }),
                          points: event.target.value,
                        },
                      }))
                    }
                    className="w-28"
                  />
                  <span className="text-sm text-muted-foreground">/ {row.maxPoints}</span>
                </div>
                {row.raw && !row.valid && (
                  <p role="alert" className="text-xs text-destructive">
                    Enter a value from 0 to {row.maxPoints}.
                  </p>
                )}
                <Input
                  value={resolutions[row.itemId]?.feedback ?? ''}
                  disabled={!submission.execution.requiresInstructorReview || submitting}
                  onChange={(event) =>
                    setResolutions((current) => ({
                      ...current,
                      [row.itemId]: {
                        ...(current[row.itemId] ?? { points: '' }),
                        feedback: event.target.value,
                      },
                    }))
                  }
                  placeholder="Item feedback"
                />
              </div>
            ))}
          </section>

          <div className="space-y-2">
            <label htmlFor="overall-feedback" className="text-sm font-medium">Overall feedback</label>
            <Textarea
              id="overall-feedback"
              value={overallFeedback}
              disabled={!submission.execution.requiresInstructorReview || submitting}
              onChange={(event) => setOverallFeedback(event.target.value)}
              rows={3}
            />
          </div>

          {submission.execution.requiresInstructorReview && (
            <div className="space-y-2">
              <label htmlFor="override-reason" className="text-sm font-medium">Override reason</label>
              <Input
                id="override-reason"
                value={overrideReason}
                onChange={(event) => setOverrideReason(event.target.value)}
                placeholder="Required when policy demands an override reason"
              />
            </div>
          )}

          <div className="flex flex-wrap gap-2">
            {submission.execution.requiresInstructorReview && (
              <Button
                type="button"
                data-testid={frozenRubric ? 'submit-grade' : 'resolve-instructor-review'}
                onClick={() => void submitReview()}
                disabled={!canResolve}
              >
                Finalize review
              </Button>
            )}
          </div>

          {finalResult && (
            <section
              data-testid="result-release-status"
              aria-live="polite"
              className={
                activeRoundReleased
                  ? 'space-y-3 rounded-md border border-emerald-500/40 bg-emerald-500/10 p-4'
                  : 'space-y-3 rounded-md border border-amber-500/50 bg-amber-500/10 p-4'
              }
            >
              <div className="flex items-start gap-3">
                {activeRoundReleased ? (
                  <CheckCircle2 className="mt-0.5 size-5 shrink-0 text-emerald-600" />
                ) : (
                  <EyeOff className="mt-0.5 size-5 shrink-0 text-amber-600" />
                )}
                <div className="min-w-0 space-y-1">
                  <h2 className="text-sm font-semibold">
                    {activeRoundReleased
                      ? 'Released to learner'
                      : 'Ready to release'}
                  </h2>
                  <p className="text-sm">
                    Final result: {scoreUnitsToPoints(finalResult.score ?? 0)} /{' '}
                    {scoreUnitsToPoints(finalResult.maxScore)}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    {activeRoundReleased
                      ? 'The learner can now see the score and released feedback.'
                      : 'Grading is complete, but the learner cannot see the score or feedback until this result is released.'}
                  </p>
                </div>
              </div>
              {canRelease && (
                <div className="space-y-3">
                  <div className="flex flex-wrap gap-2">
                    <Button
                      type="button"
                      data-testid="release-result"
                      onClick={() => void releaseResult()}
                      disabled={submitting}
                    >
                      <Send className="size-4" />
                      Release to learner
                    </Button>
                  </div>
                  <div className="grid gap-2 sm:grid-cols-[minmax(0,1fr)_auto]">
                    <Input
                      aria-label="Scheduled release time"
                      type="datetime-local"
                      value={releaseScheduledFor}
                      disabled={submitting}
                      onChange={(event) => setReleaseScheduledFor(event.target.value)}
                    />
                    <Button
                      type="button"
                      variant="outline"
                      data-testid="schedule-result-release"
                      onClick={() => void scheduleResultRelease()}
                      disabled={submitting || !canSchedule}
                    >
                      <CalendarClock className="size-4" />
                      {releaseSchedule?.status === 'scheduled' ? 'Reschedule' : 'Schedule'}
                    </Button>
                  </div>
                  <Input
                    aria-label="Release schedule reason"
                    value={releaseScheduleReason}
                    disabled={submitting}
                    onChange={(event) => setReleaseScheduleReason(event.target.value)}
                    placeholder="Reason for scheduling or cancellation"
                  />
                  {releaseSchedule?.status === 'scheduled' && (
                    <div className="flex flex-wrap items-center justify-between gap-2 text-xs text-muted-foreground">
                      <span>
                        Scheduled for {dateFormatter.format(new Date(releaseSchedule.scheduledFor))}
                      </span>
                      <Button
                        type="button"
                        size="sm"
                        variant="ghost"
                        data-testid="cancel-result-release-schedule"
                        onClick={() => void cancelScheduledRelease()}
                        disabled={submitting || !releaseScheduleReason.trim()}
                      >
                        <CalendarX className="size-4" />
                        Cancel schedule
                      </Button>
                    </div>
                  )}
                </div>
              )}
            </section>
          )}

          {finalResult && (
            <div className="space-y-2 border-t pt-4">
              <label htmlFor="regrade-reason" className="text-sm font-medium">Regrade</label>
              <div className="flex gap-2">
                <Input
                  id="regrade-reason"
                  value={regradeReason}
                  onChange={(event) => setRegradeReason(event.target.value)}
                  placeholder="Reason for opening a new round"
                />
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => void startRegrade()}
                  disabled={submitting || !regradeReason.trim()}
                >
                  Start regrade
                </Button>
              </div>
            </div>
          )}

          {submission.execution.history.length > 0 && (
            <section className="space-y-2 border-t pt-4">
              <h2 className="text-sm font-semibold">Round history</h2>
              {submission.execution.history.map((round) => (
                <div key={round.roundId} className="flex items-center justify-between gap-2 text-sm">
                  <span>Round {round.roundNumber}: {round.reason}</span>
                  <Badge variant="outline">
                    {round.status}{round.released ? ' · released' : ''}
                  </Badge>
                </div>
              ))}
            </section>
          )}
        </>
      )}

      {error && (
        <div role="alert" className="rounded-md border border-destructive bg-destructive/10 p-3 text-sm text-destructive">
          {error}
        </div>
      )}

      {!loading && !submission && !error && (
        <p className="text-sm text-muted-foreground">
          No runtime grading execution is available for {assessment.title ?? 'this assessment'}.
        </p>
      )}
    </div>
  );
}

function readItemLabel(
  submission: AssessmentSubmissionRuntimeViewV1 | null,
  itemId: string,
): string {
  const payload = submission?.execution.delivery.items[itemId]?.learnerPayload;
  if (isRecord(payload) && isRecord(payload.entry) && typeof payload.entry.stem === 'string') {
    return payload.entry.stem;
  }
  return `Item ${itemId}`;
}

function ResultStateBadge({ result }: { result: GradeItemResultV1 }) {
  return (
    <Badge variant={result.state === 'graded' ? 'secondary' : 'outline'}>
      {result.state}
    </Badge>
  );
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function createIdempotencyKey(): string {
  return globalThis.crypto?.randomUUID?.() ?? `grading-${Date.now()}-${Math.random()}`;
}

function toLocalDateTimeInput(value: string): string {
  const date = new Date(value);
  const offset = date.getTimezoneOffset() * 60_000;
  return new Date(date.getTime() - offset).toISOString().slice(0, 16);
}

import { getToken } from '@/auth';
import { createServerClient, type LearningAssessmentsAssessmentType } from '@game-guild/client';
import type { ReviewMethods, ScoreValue } from '@game-guild/grading';

// Local queue contract (camelCase wire shape), kept out of the generated
// client: the generated types model assessment.rubric as non-nullable but the
// API returns null for rubric-less assessments (the default state), failing
// response validation — so the queue is fetched via the raw request channel
// and typed here.

export type SpeedgraderGradingQueue = {
  assessment?: {
    id?: string;
    title?: string | null;
    type?: LearningAssessmentsAssessmentType;
    maxScore?: ScoreValue;
    reviewMethods?: ReviewMethods;
    groupSetId?: string | null;
    hasRubric?: boolean;
    rubric?: {
      id?: string;
      title?: string | null;
      criteria?: Array<{
        id?: string;
        description?: string | null;
        points?: ScoreValue;
        order?: number;
      }> | null;
    } | null;
  };
  items?: Array<{
    submissionId?: string;
    canonicalSubmissionId?: string;
    userId?: string | null;
    displayName?: string | null;
    groupName?: string | null;
    memberNames?: string[] | null;
    groupId?: string | null;
    attemptNumber?: number;
    attemptCount?: number;
    status?: 'InProgress' | 'Submitted' | 'Graded' | 'Returned' | 'Late';
    assignmentScore?: ScoreValue | null;
    assignmentPassed?: boolean | null;
    isLate?: boolean;
    submittedAt?: string | null;
    isGroup?: boolean;
    activeGradeRoundId?: string | null;
    activeGradeRoundStatus?:
      | 'pending'
      | 'running'
      | 'awaiting-evidence'
      | 'awaiting-instructor-resolution'
      | 'failed'
      | 'finalized'
      | null;
    activeReviewStageId?: string | null;
    activeReviewMethod?:
      | 'AutomatedReview'
      | 'InstructorReview'
      | 'SelfReview'
      | 'PeerReview'
      | 'AIReview'
      | null;
    activeReviewStageStatus?:
      | 'pending'
      | 'running'
      | 'awaiting-evidence'
      | 'awaiting-instructor-resolution'
      | 'completed'
      | 'failed'
      | null;
    requiresStaffReview?: boolean;
  }> | null;
  total?: number;
  needsGrading?: number;
};

export type QueueResult =
  | { ok: true; data: SpeedgraderGradingQueue }
  | { ok: false; status?: number; message: string };

export async function fetchGradingQueue(
  assessmentId: string,
): Promise<QueueResult> {
  const apiUrl = process.env.API_URL || process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8080';
  const client = createServerClient({
    baseUrl: apiUrl,
    auth: { getAccessToken: () => getToken() },
  });
  try {
    const result = await client.request<SpeedgraderGradingQueue>({
      method: 'GET',
      path: `/v1.0/assessments/${assessmentId}/grading-queue`,
      requiresAuth: true,
    });
    if (result.ok) {
      return { ok: true, data: result.data };
    }
    return {
      ok: false,
      status: result.error?.status,
      message:
        result.error?.status === 403
          ? 'You do not have permission to grade this assessment.'
          : 'The grading queue could not be loaded. Try again in a moment.',
    };
  } catch (err) {
    console.error('Error fetching grading queue:', err);
    return {
      ok: false,
      message: 'The grading queue could not be loaded. Try again in a moment.',
    };
  }
}

import React from 'react';
import { forbidden, notFound } from 'next/navigation';
import type { LearningAssessmentsGradingQueue } from '@game-guild/client';
import { Link } from '@/i18n/navigation';
import { fetchGradingQueue } from './grading-queue';
import { SpeedgraderWorkspace } from './speedgrader-workspace';
import { getCourseAccessCapabilities } from '@/lib/learning';

/**
 * SpeedGrader page: server-fetches the grading queue and lets each panel read
 * the immutable runtime execution for the selected submission.
 *
 * Route: `/[locale]/speedgrader/assessments/[assessmentId]?course=<slug>&nav=<index>`
 *
 * The route has no course segment, so the back link's `courseSlug` arrives via
 * the `?course=` searchParam.
 */
export default async function SpeedgraderAssessmentPage({
  params,
  searchParams,
}: {
  params: Promise<{ locale: string; assessmentId: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}): Promise<React.JSX.Element> {
  const { assessmentId } = await params;
  const query = await searchParams;

  const courseParam = typeof query.course === 'string' ? query.course : undefined;
  if (!courseParam) {
    notFound();
  }

  const access = await getCourseAccessCapabilities(courseParam);
  if (!access.canReviewAsStaff) {
    forbidden();
  }

  const queue = await fetchGradingQueue(assessmentId);
  if (!queue.ok) {
    if (queue.status === 404) {
      notFound();
    }
    return (
      <main className="grid flex-1 place-items-center p-6">
        <div data-testid="speedgrader-error" className="max-w-md text-center">
          <h1 className="text-lg font-semibold text-foreground">Grading queue unavailable</h1>
          <p className="mt-2 text-sm text-muted-foreground">{queue.message}</p>
          <Link
            href={`/dashboard/learning/courses/${courseParam}/assessments/${assessmentId}/submissions`}
            className="mt-4 inline-block text-sm text-primary underline-offset-4 hover:underline"
          >
            Back to submissions
          </Link>
        </div>
      </main>
    );
  }

  const data = queue.data;
  const requestedSubmission =
    typeof query.submission === 'string' ? query.submission : null;
  const submissionIndex = requestedSubmission
    ? data.items?.findIndex((item) => item.submissionId === requestedSubmission) ?? -1
    : -1;
  const navParam =
    typeof query.nav === 'string' ? Number.parseInt(query.nav, 10) : Number.NaN;
  const initialIndex =
    submissionIndex >= 0 ? submissionIndex : Number.isFinite(navParam) ? navParam : 0;

  return (
    <SpeedgraderWorkspace
      // Cast: workspace props use the generated type, whose `rubric` field
      // wrongly excludes null (the API sends null for rubric-less
      // assessments) — grading-queue.ts holds the accurate contract.
      queue={data as LearningAssessmentsGradingQueue}
      assessmentId={assessmentId}
      courseSlug={courseParam}
      initialIndex={initialIndex}
    />
  );
}

'use client';

interface QuizAnswerView {
  key: string;
  value: string;
}

interface QuizGradeItemView {
  blockId: string;
  label: string;
}

/** Render one StructuredAnswer (grading feature vocabulary) readably. */
function answerToText(answer: unknown): string {
  if (answer == null || typeof answer !== 'object') {
    return String(answer ?? '');
  }
  const record = answer as Record<string, unknown>;
  const parts: string[] = [];
  if (Array.isArray(record.selectedOptionIds)) {
    parts.push(`Selected: ${record.selectedOptionIds.join(', ')}`);
  }
  if (record.textAnswers && typeof record.textAnswers === 'object') {
    const texts = Object.entries(record.textAnswers as Record<string, unknown>)
      .map(([prompt, reply]) => `${prompt}: ${String(reply)}`)
      .join('; ');
    if (texts) parts.push(texts);
  }
  if (record.categorizations && typeof record.categorizations === 'object') {
    const cats = Object.entries(record.categorizations as Record<string, unknown>)
      .map(([bucket, ids]) => `${bucket}: ${(Array.isArray(ids) ? ids : []).join(', ')}`)
      .join('; ');
    if (cats) parts.push(cats);
  }
  if (Array.isArray(record.ordering) && record.ordering.length > 0) {
    parts.push(`Order: ${(record.ordering as unknown[]).join(' > ')}`);
  }
  if (typeof record.rating === 'number') {
    parts.push(`Rating: ${record.rating}`);
  }
  return parts.join(' · ') || JSON.stringify(answer);
}

/**
 * Parse a quiz answer envelope into renderable question/answer rows.
 * Tolerant of the legacy `{answer: string}` shape and of an embedded
 * GradeResult-style auto-grade (`gradeResult` key).
 */
export function parseQuizPayload(payload: string): {
  answers: QuizAnswerView[];
  gradeItems: QuizGradeItemView[];
} {
  let parsed: unknown;
  try {
    parsed = JSON.parse(payload);
  } catch {
    return { answers: [{ key: 'Response', value: payload }], gradeItems: [] };
  }
  if (parsed == null || typeof parsed !== 'object') {
    return {
      answers: [{ key: 'Response', value: String(parsed) }],
      gradeItems: [],
    };
  }
  const record = parsed as Record<string, unknown>;

  const answers: QuizAnswerView[] = [];
  if (typeof record.answer === 'string') {
    answers.push({ key: 'answer', value: record.answer });
  }
  if (record.answers && typeof record.answers === 'object') {
    for (const [key, value] of Object.entries(record.answers as Record<string, unknown>)) {
      answers.push({ key, value: answerToText(value) });
    }
  }

  const gradeItems: QuizGradeItemView[] = [];
  const grade = record.gradeResult ?? record.GradeResult;
  if (grade && typeof grade === 'object') {
    const items = (grade as Record<string, unknown>).items;
    if (Array.isArray(items)) {
      for (const item of items) {
        if (item && typeof item === 'object') {
          const row = item as Record<string, unknown>;
          gradeItems.push({
            blockId: String(row.contentBlockId ?? ''),
            label: `${row.isCorrect === true ? 'correct' : (row.status ?? 'graded')} · ${String(row.score ?? '?')}/${String(row.maxScore ?? '?')}`,
          });
        }
      }
    }
  }

  return { answers, gradeItems };
}

/** Quiz response viewer: readable question/answer list and review statuses. */
export function QuizViewer({ payload }: { payload: string }): React.JSX.Element {
  const { answers, gradeItems } = parseQuizPayload(payload);
  return (
    <div data-testid="quiz-viewer" className="space-y-3 rounded-md border bg-card p-4">
      <dl className="space-y-3">
        {answers.map((answer) => (
          <div key={answer.key} className="space-y-1">
            <dt data-testid={`quiz-question-${answer.key}`} className="text-sm font-medium text-foreground">
              {answer.key}
            </dt>
            <dd className="whitespace-pre-wrap rounded bg-muted p-2 text-sm text-muted-foreground">{answer.value}</dd>
          </div>
        ))}
      </dl>
      {gradeItems.length > 0 && (
        <ul className="space-y-1 border-t pt-3 text-sm">
          {gradeItems.map((item) => (
            <li key={item.blockId} data-testid={`quiz-grade-${item.blockId}`}>
              <span className="font-medium">{item.blockId}</span> — {item.label}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

'use client';

import { cn } from "@game-guild/ui/lib/utils";
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { useSearchParams } from 'next/navigation';
import { Link, usePathname, useRouter } from '@/i18n/navigation';
import { useState, type ReactNode } from 'react';
import type { LearningAssessmentsGradingQueueItem } from '@game-guild/client';
import { Badge } from '@game-guild/ui/components/badge';
import { Button, buttonVariants } from '@game-guild/ui/components/button';
import {
  ResizableHandle,
  ResizablePanel,
  ResizablePanelGroup,
} from '@game-guild/ui/components/resizable';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@game-guild/ui/components/select';

// ponytail: viewer/grading slots are render-props over the CURRENT item so
// todo 12 can slot real viewers/panels in without touching navigation logic.

export function itemLabel(
  item: LearningAssessmentsGradingQueueItem,
): string {
  const attempt = item.attemptCount
    ? `attempt ${item.attemptNumber ?? 1} of ${item.attemptCount}`
    : `attempt ${item.attemptNumber ?? 1}`;
  if (item.isGroup) {
    const members = item.memberNames?.length
      ? ` (${item.memberNames.join(', ')})`
      : '';
    return `Group: ${item.groupName ?? 'Unnamed group'}${members} — ${attempt} — ${item.status ?? 'InProgress'}`;
  }
  return `${item.displayName ?? 'Unknown student'} — ${attempt} — ${item.status ?? 'InProgress'}`;
}

export interface SpeedgraderShellProps {
  assessmentTitle: string;
  assessmentId: string;
  courseSlug: string;
  items: LearningAssessmentsGradingQueueItem[];
  needsGrading: number;
  initialIndex?: number;
  /** Todo 12: render the submission viewer for the current item. */
  renderViewer?: (item: LearningAssessmentsGradingQueueItem) => ReactNode;
  /** Todo 12: render the grading panel for the current item. */
  renderGrading?: (item: LearningAssessmentsGradingQueueItem) => ReactNode;
}

export function SpeedgraderShell({
  assessmentTitle,
  assessmentId,
  courseSlug,
  items,
  needsGrading,
  initialIndex = 0,
  renderViewer,
  renderGrading,
}: SpeedgraderShellProps): React.JSX.Element {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const total = items.length;
  const maxIndex = Math.max(total - 1, 0);
  const [rawIndex, setRawIndex] = useState(initialIndex);
  // Clamp at render: covers ?nav= out of range AND item-count changes after refresh.
  const index = Math.min(
    Number.isFinite(rawIndex) ? Math.max(rawIndex, 0) : 0,
    maxIndex,
  );

  const goTo = (next: number) => {
    setRawIndex(next);
    const params = new URLSearchParams(searchParams?.toString());
    params.set('nav', String(next));
    router.replace(`${pathname}?${params.toString()}`, { scroll: false });
  };

  const backHref = `/dashboard/learning/courses/${courseSlug}/assessments/${assessmentId}/submissions`;

  if (total === 0) {
    return (
      <div data-testid="speedgrader-empty" className="grid flex-1 place-items-center p-6">
        <div className="max-w-md text-center">
          <h1 className="text-lg font-semibold text-foreground">{assessmentTitle}</h1>
          <p className="mt-2 text-sm text-muted-foreground">
            No submissions to grade yet. Check back once students start submitting.
          </p>
          <Link
            href={backHref}
            className="mt-4 inline-block text-sm text-primary underline-offset-4 hover:underline"
          >
            Back to submissions
          </Link>
        </div>
      </div>
    );
  }

  const current = items[index];

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <header
        data-testid="speedgrader-header"
        className="flex flex-wrap items-center gap-2 border-b px-3 py-2"
      >
        <Link
          href={backHref}
          aria-label="Back to submissions"
          className={cn(buttonVariants({ variant: "ghost", size: "sm" }))}
        >
          <ChevronLeft className="size-4" />
          Back
        </Link>
        <h1 className="min-w-0 truncate text-sm font-semibold">{assessmentTitle}</h1>
        <Badge data-testid="needs-grading-badge" variant="secondary">
          {needsGrading} to grade
        </Badge>
        <div className="ml-auto flex items-center gap-2">
          <Button
            variant="outline"
            size="icon"
            aria-label="Previous submission"
            onClick={() => goTo((index - 1 + total) % total)}
          >
            <ChevronLeft className="size-4" />
          </Button>
          <span data-testid="item-counter" className="text-sm tabular-nums">
            {index + 1} of {total}
          </span>
          <Button
            variant="outline"
            size="icon"
            aria-label="Next submission"
            onClick={() => goTo((index + 1) % total)}
          >
            <ChevronRight className="size-4" />
          </Button>
          <Select
            data-testid="item-picker"
            value={String(index)}
            onValueChange={(value) => goTo(Number.parseInt(value ?? String(index), 10))}
          >
            <SelectTrigger className="w-64" aria-label="Select submission">
              <SelectValue placeholder="Select submission" />
            </SelectTrigger>
            <SelectContent>
              {items.map((item, i) => (
                <SelectItem key={item.submissionId ?? String(i)} value={String(i)}>
                  {itemLabel(item)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </header>

      <ResizablePanelGroup orientation="horizontal" className="min-h-0 flex-1">
        <ResizablePanel defaultSize="60" minSize="20">
          {renderViewer ? (
            renderViewer(current)
          ) : (
            <div data-testid="viewer-slot" className="h-full overflow-auto p-4 text-sm">
              {itemLabel(current)}
            </div>
          )}
        </ResizablePanel>
        <ResizableHandle />
        <ResizablePanel defaultSize="40" minSize="20">
          {renderGrading ? (
            renderGrading(current)
          ) : (
            <div data-testid="grading-slot" className="h-full overflow-auto p-4 text-sm text-muted-foreground">
              Grading panel
            </div>
          )}
        </ResizablePanel>
      </ResizablePanelGroup>
    </div>
  );
}

'use client';

import type { LearningAssessmentsGradingQueue, LearningAssessmentsGradingQueueItem } from '@game-guild/client';
import type { AssessmentSubmissionRuntimeViewV1 } from '@game-guild/grading';
import { useCallback, useState } from 'react';
import { SpeedgraderShell } from './speedgrader-shell';
import { SubmissionViewer } from './submission-viewer';
import { GradingPanel } from './grading-panel';

export interface SpeedgraderWorkspaceProps {
  queue: LearningAssessmentsGradingQueue;
  assessmentId: string;
  courseSlug: string;
  initialIndex: number;
}

interface ConfirmedReview {
  previousRoundId: string | null;
  roundId: string | null;
  supersededRoundIds: (string | null)[];
  requiresStaffReview: boolean;
  finalized: boolean;
  acknowledged: boolean;
  version: number;
}

function requiresStaffReview(item: LearningAssessmentsGradingQueueItem): boolean {
  return item.activeGradeRoundId != null
    ? item.requiresStaffReview === true
    : item.status === 'Submitted' || item.status === 'Late';
}

function reconcileConfirmations(
  queue: LearningAssessmentsGradingQueue,
  confirmed: Record<string, ConfirmedReview>,
): Record<string, ConfirmedReview> {
  const items = new Map((queue.items ?? []).map((item) => [item.submissionId, item]));
  return Object.fromEntries(Object.entries(confirmed).flatMap<[string, ConfirmedReview]>(([id, review]) => {
    const item = items.get(id);
    if (!item) return [];
    const roundId = item.activeGradeRoundId ?? null;
    if (review.supersededRoundIds.includes(roundId)) return [[id, review]];
    if (roundId === review.roundId) {
      // A finalized round cannot acquire more work. Retain its confirmation
      // after acknowledgement too, so a late refresh cannot resurrect it.
      if (review.finalized) return [[id, review]];
      if (!review.acknowledged && review.previousRoundId === roundId
        && requiresStaffReview(item) !== review.requiresStaffReview
        && item.activeGradeRoundStatus !== 'finalized') return [[id, review]];
    }
    // A new canonical round can introduce work, including an automated stage
    // advancing to instructor review. Remember the old round for late refreshes.
    return [[id, {
      ...review,
      roundId,
      supersededRoundIds: roundId === review.roundId
        ? review.supersededRoundIds
        : [...review.supersededRoundIds, review.roundId],
      requiresStaffReview: requiresStaffReview(item),
      finalized: item.activeGradeRoundStatus === 'finalized',
      acknowledged: true,
    }]];
  }));
}

/**
 * Client wrapper that fills the shell's renderViewer/renderGrading slots.
 * The run-tests computed score flows from the (left) code viewer into the
 * (right) grading panel through here, keyed by the submission it belongs to.
 */
export function SpeedgraderWorkspace({
  queue,
  assessmentId,
  courseSlug,
  initialIndex,
}: SpeedgraderWorkspaceProps): React.JSX.Element {
  const assessment = queue.assessment ?? {};
  const [reviewState, setReviewState] = useState<{
    queue: LearningAssessmentsGradingQueue;
    confirmed: Record<string, ConfirmedReview>;
  }>({
    queue,
    confirmed: {},
  });
  let confirmed = reviewState.confirmed;
  if (reviewState.queue !== queue) {
    confirmed = reconcileConfirmations(queue, confirmed);
    // Reconcile changed server props before rendering children, rather than
    // briefly painting an acknowledged confirmation over a newer round.
    setReviewState({ queue, confirmed });
  }

  const confirmReview = useCallback((submission: AssessmentSubmissionRuntimeViewV1) => {
    if (submission.assessmentId !== assessmentId) return;
    setReviewState((current) => {
      // An action can finish after newer queue props arrive. Read the current
      // queue here instead of retaining the queue captured before its await.
      const item = current.queue.items?.find((entry) => entry.submissionId === submission.submissionId);
      if (!item) return current;
      const prior = current.confirmed[submission.submissionId];
      if (prior && prior.version > submission.version) return current;
      const roundId = submission.execution.activeRoundId ?? null;
      if (prior?.supersededRoundIds.includes(roundId)) return current;
      const currentRoundId = item.activeGradeRoundId ?? null;
      // A late mutation result cannot reopen a round already confirmed final
      // by a newer queue snapshot, including before any local confirmation.
      if ((prior?.roundId === roundId && prior.finalized)
        || (currentRoundId === roundId && item.activeGradeRoundStatus === 'finalized')) return current;
      // Without a recorded confirmation, a response for another round may
      // predate fresh queue props. Its history must establish the ordering.
      if (currentRoundId !== null && currentRoundId !== roundId
        && !submission.execution.history.some((round) => round.roundId === currentRoundId)
        && !(prior?.roundId === roundId && prior.supersededRoundIds.includes(currentRoundId))) return current;
      const supersededRoundIds = new Set(prior?.supersededRoundIds ?? []);
      supersededRoundIds.add(currentRoundId);
      if (prior) supersededRoundIds.add(prior.roundId);
      for (const round of submission.execution.history) supersededRoundIds.add(round.roundId);
      supersededRoundIds.delete(roundId);
      return {
        ...current,
        confirmed: {
          ...current.confirmed,
          [submission.submissionId]: {
            previousRoundId: item.activeGradeRoundId ?? null,
            roundId,
            supersededRoundIds: [...supersededRoundIds],
            requiresStaffReview: submission.execution.requiresInstructorReview,
            finalized: submission.execution.history.some((round) => round.roundId === roundId && round.status === 'finalized'),
            acknowledged: false,
            version: submission.version,
          },
        },
      };
    });
  }, [assessmentId]);

  const needsGrading = Math.max(0, (queue.needsGrading ?? 0) + (queue.items ?? []).reduce((delta, item) => {
    const review = item.submissionId ? confirmed[item.submissionId] : undefined;
    if (!review) return delta;
    return delta + Number(review.requiresStaffReview) - Number(requiresStaffReview(item));
  }, 0));

  const renderViewer = (item: LearningAssessmentsGradingQueueItem) => (
    <SubmissionViewer submissionId={item.submissionId ?? ''} />
  );

  const renderGrading = (item: LearningAssessmentsGradingQueueItem) => (
    <GradingPanel item={item} assessment={assessment} onReviewStateChanged={confirmReview} />
  );

  return (
    <SpeedgraderShell
      assessmentTitle={assessment.title ?? 'Assessment'}
      assessmentId={assessmentId}
      courseSlug={courseSlug}
      items={queue.items ?? []}
      needsGrading={needsGrading}
      initialIndex={initialIndex}
      renderViewer={renderViewer}
      renderGrading={renderGrading}
    />
  );
}

'use client';

import { useEffect, useMemo, useState, type ComponentType } from 'react';
import type { AssessmentSubmissionRuntimeViewV1 } from '@game-guild/grading';
import {
  parseQuizAnswerEnvelope,
  QUIZ_ASSESSMENT_TYPE_ADAPTER,
  type QuizLearnerDeliveryItemV1,
} from '@game-guild/grading-adapter-quiz';
import { createEmptyQuizAnswer, type QuizAnswer } from '@game-guild/quiz';
import { QuizPlayer, type QuizSubmissionResult } from '@game-guild/quiz-surface/player';
import { Badge } from '@game-guild/ui/components/badge';
import { getRuntimeSubmission } from '@/lib/learning/grading-runtime-actions';
import { scoreUnitsToPoints } from '@/lib/learning/academic-values';
import { readCodeRuntimeDefinition } from '@/lib/coding-assignment/runtime';
import { codePayloadToFiles } from '@/lib/coding-assignment/code-payload';
import { EMCEPTION_MANIFEST_URL } from '@/lib/emception/manifest-url';
import type { AssessmentGraderProps } from '@/components/learning/assessment-grading/assessment-grader';

export interface SubmissionViewerProps {
  submissionId: string;
}

/**
 * Instructor view of the exact delivery and response bound to the official
 * grading execution. The authored content is intentionally not consulted.
 */
export function SubmissionViewer(props: SubmissionViewerProps): React.JSX.Element {
  return <SubmissionViewerSession key={props.submissionId} {...props} />;
}

function SubmissionViewerSession({
  submissionId,
}: SubmissionViewerProps): React.JSX.Element {
  const [submission, setSubmission] =
    useState<AssessmentSubmissionRuntimeViewV1 | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    getRuntimeSubmission(submissionId).then((result) => {
      if (cancelled) return;
      if (result.success) {
        setSubmission(result.data);
      } else {
        setError(result.error);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [submissionId]);

  if (error) {
    return (
      <div
        data-testid="viewer-error"
        role="alert"
        className="p-4 text-sm text-destructive"
      >
        {error}
      </div>
    );
  }
  if (!submission) {
    return (
      <div
        data-testid="viewer-loading"
        className="p-4 text-sm text-muted-foreground"
      >
        Loading submission...
      </div>
    );
  }

  return <RuntimeSubmission submission={submission} />;
}

function RuntimeSubmission({
  submission,
}: {
  submission: AssessmentSubmissionRuntimeViewV1;
}): React.JSX.Element {
  const quiz = useMemo(() => readQuizSubmission(submission), [submission]);

  return (
    <div
      data-testid="submission-viewer"
      className="h-full space-y-4 overflow-auto p-4"
    >
      <div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
        <Badge variant="outline">Attempt {submission.attemptNumber}</Badge>
        <span>Delivery {submission.execution.deliveryHash.slice(0, 12)}</span>
        <span>Revision {submission.definitionRevisionId.slice(0, 8)}</span>
      </div>

      {submission.execution.delivery.items.code?.adapterKey === 'code-assessment-type' ? (
        <CodeRuntimeSubmission submission={submission} />
      ) : quiz ? (
        <div className="space-y-4" data-testid="runtime-quiz-submission">
          {quiz.items.map((item, index) => (
            <section
              key={item.itemId}
              className="space-y-3 rounded-md border bg-card p-4"
            >
              <div className="flex items-center justify-between gap-3">
                <h2 className="text-sm font-semibold">Question {index + 1}</h2>
                <Badge variant="secondary">
                  {scoreUnitsToPoints(
                    submission.execution.itemMaxScores[item.itemId] ?? 0,
                  )}{' '}
                  pts
                </Badge>
              </div>
              <QuizPlayer
                entry={item.delivery.entry}
                answer={item.answer}
                onAnswerChange={() => undefined}
                onSubmit={() => undefined}
                submissionResult={item.result}
                disabled
              />
            </section>
          ))}
        </div>
      ) : (
        <GenericRuntimeSubmission submission={submission} />
      )}
    </div>
  );
}

function CodeRuntimeSubmission({ submission }: { submission: AssessmentSubmissionRuntimeViewV1 }) {
  const [Grader, setGrader] = useState<ComponentType<AssessmentGraderProps> | null>(null);
  const [error, setError] = useState<string | null>(null);
  useEffect(() => {
    let active = true;
    void import('@/components/learning/assessment-grading/assessment-grader').then((module) => {
      if (active) setGrader(() => module.AssessmentGrader);
    }).catch((failure: unknown) => {
      if (active) setError(failure instanceof Error ? failure.message : 'The Code grading editor is unavailable.');
    });
    return () => { active = false; };
  }, []);
  const content = useMemo(() => readFrozenCodeSubmission(submission), [submission]);
  if (error) return <p role="alert">{error}</p>;
  if (!content.success) return <p role="alert">{content.error}</p>;
  if (!Grader) return <p>Loading Code grading editor...</p>;
  return <Grader assignment={content.definition} submittedFiles={content.files}
    maxScore={content.definition.Grading.MaxScore} manifestUrl={EMCEPTION_MANIFEST_URL}
    submissionId={submission.submissionId} />;
}

function readFrozenCodeSubmission(submission: AssessmentSubmissionRuntimeViewV1) {
  try {
    const definition = readCodeRuntimeDefinition(submission, true);
    const payload = submission.execution.submittedResponse?.payload as { files?: unknown } | undefined;
    const files = payload?.files ? codePayloadToFiles(JSON.stringify(payload.files)) : [];
    return { success: true as const, definition, files };
  } catch (failure) {
    return { success: false as const,
      error: failure instanceof Error ? failure.message : 'The frozen Code submission is unavailable.' };
  }
}

function readQuizSubmission(submission: AssessmentSubmissionRuntimeViewV1): {
  items: Array<{
    itemId: string;
    delivery: QuizLearnerDeliveryItemV1;
    answer: QuizAnswer;
    result: QuizSubmissionResult;
  }>;
} | null {
  const delivery = submission.execution.delivery;
  if (
    delivery.itemOrder.some((itemId) => {
      const item = delivery.items[itemId];
      return (
        !item ||
        item.adapterKey !== QUIZ_ASSESSMENT_TYPE_ADAPTER.key ||
        item.adapterVersion !== QUIZ_ASSESSMENT_TYPE_ADAPTER.version
      );
    })
  ) {
    return null;
  }

  let answers: Record<string, QuizAnswer> = {};
  if (submission.execution.submittedResponse) {
    try {
      answers = parseQuizAnswerEnvelope(
        submission.execution.submittedResponse,
      ).payload.answers;
    } catch {
      return null;
    }
  }

  const resultByItem = new Map(
    (submission.execution.instructorVisibleResult?.items ?? []).map((item) => [
      item.itemId,
      item,
    ]),
  );
  return {
    items: delivery.itemOrder.map((itemId) => {
      const item = delivery.items[itemId]!;
      const learnerPayload = item.learnerPayload as QuizLearnerDeliveryItemV1;
      if (learnerPayload.itemId !== itemId) {
        throw new Error(`Quiz delivery item ${itemId} has a mismatched payload.`);
      }
      const answer =
        answers[itemId] ?? createEmptyQuizAnswer(learnerPayload.entry.type);
      const result = resultByItem.get(itemId);
      return {
        itemId,
        delivery: learnerPayload,
        answer,
        result: toQuizSubmissionResult(result),
      };
    }),
  };
}

function toQuizSubmissionResult(
  item:
    | NonNullable<
        AssessmentSubmissionRuntimeViewV1['execution']['instructorVisibleResult']
      >['items'][number]
    | undefined,
): QuizSubmissionResult {
  if (!item || item.state !== 'graded' || item.score == null) {
    return {
      status: 'pending',
      feedback: 'Awaiting grading.',
    };
  }
  return {
    status: item.score === item.maxScore ? 'correct' : 'incorrect',
    feedback: item.feedback ?? undefined,
  };
}

function GenericRuntimeSubmission({
  submission,
}: {
  submission: AssessmentSubmissionRuntimeViewV1;
}): React.JSX.Element {
  return (
    <div data-testid="runtime-generic-submission" className="space-y-4">
      <div className="rounded-md border bg-card p-4">
        <h2 className="text-sm font-semibold">Immutable delivery</h2>
        <pre className="mt-3 overflow-auto whitespace-pre-wrap text-xs text-muted-foreground">
          {JSON.stringify(submission.execution.delivery, null, 2)}
        </pre>
      </div>
      <div className="rounded-md border bg-card p-4">
        <h2 className="text-sm font-semibold">Submitted response</h2>
        <pre className="mt-3 overflow-auto whitespace-pre-wrap text-xs text-muted-foreground">
          {JSON.stringify(submission.execution.submittedResponse, null, 2)}
        </pre>
      </div>
    </div>
  );
}

import type { LearningAssessmentsSubmissionModality } from '@game-guild/client';

const MODALITY_NAMES = ['Text', 'File', 'Url', 'Code', 'Media', 'Project', 'StructuredAnswer'] as const;

export type ModalityName = (typeof MODALITY_NAMES)[number];

const MODALITY_FLAG_BITS: Record<ModalityName, number> = {
  Text: 1,
  File: 2,
  Url: 4,
  Code: 8,
  Media: 16,
  Project: 32,
  StructuredAnswer: 64,
};

/**
 * Parse SubmittedModalities from the wire. The API serializes the backend
 * [Flags] enum as comma-separated names ("Text, Code"); tolerate a raw
 * numeric string ("3" → Text|File) and "None"/empty as no modalities.
 * Pure + client/server safe.
 */
export function parseSubmittedModalities(raw: LearningAssessmentsSubmissionModality | null | undefined): Set<ModalityName> {
  const result = new Set<ModalityName>();
  const trimmed = (raw ?? '').trim();
  if (!trimmed || trimmed === 'None') return result;

  const asNumber = Number.parseInt(trimmed, 10);
  if (Number.isFinite(asNumber) && String(asNumber) === trimmed) {
    for (const name of MODALITY_NAMES) {
      if ((asNumber & MODALITY_FLAG_BITS[name]) !== 0) result.add(name);
    }
    return result;
  }

  for (const part of trimmed.split(',')) {
    const name = part.trim();
    if ((MODALITY_NAMES as readonly string[]).includes(name)) {
      result.add(name as ModalityName);
    }
  }
  return result;
}

import { Providers } from '@/components/providers';
import { routing } from '@/i18n';
import type { Metadata } from 'next';
import { hasLocale, NextIntlClientProvider } from 'next-intl';
import { getMessages, setRequestLocale } from 'next-intl/server';
import { notFound } from 'next/navigation';
import React from 'react';

export async function generateStaticParams() {
  return routing.locales.map((locale) => ({ locale }));
}

export async function generateMetadata(): Promise<Metadata> {
  return {
    title: {
      template: '%s | GameGuild',
      default: 'GameGuild',
    },
  };
}

export default async function Layout({ children, params }: LayoutProps<'/[locale]'>): Promise<React.JSX.Element> {
  const { locale } = await params;

  if (!hasLocale(routing.locales, locale)) notFound();

  // Enable static rendering (cache) based on the locale.
  setRequestLocale(locale);

  // Get messages for the client-side.
  const messages = await getMessages();

  return (
    <NextIntlClientProvider locale={locale} messages={messages}>
      <Providers>
        {children}
      </Providers>
    </NextIntlClientProvider>
  );
}

import { auth, getToken } from '@/auth';
