} from '@game-guild/quiz-content';

interface SubmissionFile {
  path: string;
  content: string;
  encoding: 'text';
  modifiable: boolean;
}

/**
 * Best-effort restore of the learner's latest code submission for an
 * assessment: list my submissions, keep matching ones with a code payload,
 * take the highest attemptNumber, parse the payload. Any failure returns
 * null so the page still renders with starter files.
 */
async function loadLastSubmissionFiles(
  assessmentId: string,
  enrollmentId: string,
): Promise<SubmissionFile[] | null> {
  try {
    const apiUrl =
      process.env.API_URL ||
      process.env.NEXT_PUBLIC_API_URL ||
      'http://localhost:8080';
    const client = createServerClient({
      baseUrl: apiUrl,
      auth: { getAccessToken: () => getToken() },
    });
    const assessments = new GeneratedApi.LearningAssessmentsModule(client);
    const result = await assessments.getAssessmentsMySubmissions(enrollmentId);
    if (!result.ok) return null;
    const matching = result.data.filter(
      (entry) =>
        entry.assessmentId === assessmentId && entry.codePayload != null,
    );
    const latest = matching.reduce<(typeof matching)[number] | null>(
      (max, entry) =>
        !max || (entry.attemptNumber ?? 0) > (max.attemptNumber ?? 0)
          ? entry
          : max,
      null,
    );
    if (!latest?.codePayload) return null;
    return codePayloadToFiles(latest.codePayload).map((file) => ({
      ...file,
      encoding: 'text' as const,
      modifiable: true,
    }));
  } catch (err) {
    console.error('loadLastSubmissionFiles: unexpected error', err);
    return null;
  }
}

function promptBody(value: unknown): string {
  if (typeof value === 'string') return value;
  if (value && typeof value === 'object') return JSON.stringify(value, null, 2);
  return '';
}

/** submissionModalities is a comma-separated string of C# [Flags] enum names — "Code", not 8. */
function allowsCodeModality(modalities: string | undefined): boolean {
  if (!modalities) return false;
  return modalities
    .split(',')
    .map((entry) => entry.trim())
    .includes('Code');
}

function parseServerGradedQuizContent(value: unknown): {
  content: QuizRuntimeContentDocument | null;
  issues: ReturnType<typeof parseQuizLearnerContentDocument>['issues'];
} {
  const learner = parseQuizLearnerContentDocument(value);
  if (learner.issues.length === 0) {
    return {
      content: prepareQuizLearnerContentForRuntime(learner.document),
      issues: [],
    };
  }

  // Defense in depth for callers that still return an authoring-shaped
  // document: redact it on the server before crossing the client boundary.
  const authoring = parseQuizContentDocument(value);
  if (authoring.issues.length === 0) {
    return {
      content: prepareQuizContentForRuntime(authoring.document, 'server-graded'),
      issues: [],
    };
  }

  return { content: null, issues: learner.issues };
}

export default async function LearnerActivityPage({
  params,
}: {
  params: Promise<{ activityId: string; slug: string }>;
}) {
  const { activityId, slug } = await params;
  const access = await getCourseAccessData(slug);
  if (access.kind === 'not-found') notFound();
  if (access.kind !== 'ready') return <CourseAccessGate access={access} />;
  if (!access.course.enrollmentId) notFound();

  const context = await getCourseLearnerContext(access.course.id);
  let activity: LearnerActivityDescriptor | null = null;
  let codingAssignment: CodingAssignmentContent | null = null;
  let useCodingExperience = false;
  let codingUnpublished = false;
  let quizContent: QuizRuntimeContentDocument | null = null;
  let quizContentItem:
    | {
        id: string;
        title: string;
        description?: string;
        isRequired: boolean;
        status: 'locked' | 'available' | 'in-progress' | 'completed';
      }
    | null = null;
  let quizUnavailable = false;
  let quizSubmissionId: string | null = null;
  let submissionFiles: SubmissionFile[] | null = null;
  let userId: string | null = null;
  let description = '';
  let dueAt: string | null | undefined;
  let points: number | undefined;

  if (activityId.startsWith('assessment-')) {
    const assessmentId = activityId.slice('assessment-'.length);
    const assessment = context.assessments.find((candidate) => candidate.id === assessmentId);
    if (!assessment) notFound();
    const submission = context.submissions.find(
      (candidate) => candidate.assessmentId === assessmentId,
    );
    quizSubmissionId = submission?.id ?? null;
    // Unconditional: the coding experience needs a user id for its
    // user-scoped draft token, not just Project-type project listings.
    const session = await auth();
    userId = session?.user?.id ?? null;
    const projects = userId ? await getMyProjects(userId) : [];
    activity = { kind: 'assessment', assessment, submission, projects };
    description = assessment.description || '';
    dueAt = assessment.dueAt;
    points = assessment.maxScore;

    const codingEligible =
      Boolean(assessment.id) &&
      Boolean(assessment.contentId) &&
      (assessment.type === 'Assignment' || assessment.type === 'Project') &&
      allowsCodeModality(assessment.submissionModalities);
    if (codingEligible && assessment.id && assessment.contentId) {
      // v1: fetch via ProgramContent route — server strips Private tests + Private files.
      const candidate = await getCodingAssignmentPublic(
        access.course.id,
        assessment.contentId,
      );
      if (candidate && candidate.Type === 'coding-assignment') {
        codingAssignment = candidate;
        useCodingExperience = true;
        submissionFiles = await loadLastSubmissionFiles(
          assessment.id,
          access.course.enrollmentId,
        );
      }
    }
    codingUnpublished = codingEligible && !codingAssignment;

    if (assessment.type === 'Quiz' && assessment.contentId) {
      const linkedContent = access.course.modules
        .flatMap((module) => module.items)
        .find((candidate) => candidate.id === assessment.contentId);
      if (linkedContent) {
        const parsed = parseServerGradedQuizContent(linkedContent.content);
        if (parsed.content) {
          quizContent = parsed.content;
          quizContentItem = {
            id: linkedContent.id,
            title: linkedContent.title,
            description: linkedContent.description,
            isRequired: linkedContent.isRequired,
            status: linkedContent.status,
          };
        } else {
          console.error(
            'LearnerActivityPage: invalid published quiz content',
            parsed.issues,
          );
        }
      }
      quizUnavailable = !quizContent || !quizContentItem;
    }
  } else if (activityId.startsWith('content-')) {
    const contentId = activityId.slice('content-'.length);
    const item = access.course.modules
      .flatMap((module) => module.items)
      .find((candidate) => candidate.id === contentId);
    if (!item) {
      notFound();
    }

    if (item.contentType === 'Questionnaire') {
      const parsed = parseServerGradedQuizContent(item.content);
      if (!parsed.content) {
        console.error(
          'LearnerActivityPage: invalid published quiz content',
          parsed.issues,
        );
        quizUnavailable = true;
      } else {
        quizContent = parsed.content;
        quizContentItem = {
          id: item.id,
          title: item.title,
          description: item.description,
          isRequired: item.isRequired,
          status: item.status,
        };
      }
    } else if (
      ['Discussion', 'Reflection', 'Survey'].includes(item.contentType || '')
    ) {
      activity = {
        kind: 'content',
        contentId: item.id,
        contentType: item.contentType as 'Discussion' | 'Reflection' | 'Survey',
        title: item.title,
        description: item.description,
        completed: item.status === 'completed',
      };
      description = promptBody(item.content) || item.description || '';
    } else {
      notFound();
    }
  }

  if (!activity && !quizContentItem) notFound();
  const title = quizContentItem?.title ??
    (activity?.kind === 'assessment'
      ? activity.assessment.title || 'Assessment'
      : activity?.title || 'Activity');
  const type = quizContentItem
    ? 'Quiz'
    : activity?.kind === 'assessment'
      ? activity.assessment.type
      : activity?.contentType || 'Activity';
  // learn/layout.tsx already redirects signed-out visitors; the userId
  // guard keeps the client's user-scoped token well-formed even if that
  // invariant ever breaks.
  const codingProps =
    activity?.kind === 'assessment' &&
    useCodingExperience &&
    codingAssignment &&
    activity.assessment.id &&
    userId
      ? {
          assessmentId: activity.assessment.id,
          assignment: codingAssignment,
          userId,
        }
      : null;

  return (
    <div
      className={
        codingProps ? 'w-full space-y-6' : 'mx-auto max-w-4xl space-y-6'
      }
    >
      <Link href={`/learn/courses/${slug}/activities`} className={buttonVariants({ variant: 'ghost', className: '-ml-3' })}>
        <ArrowLeft className="size-4" />
        All activities
      </Link>
      <header className="border-b pb-6">
        <div className="flex flex-wrap items-center gap-2">
          <Badge variant="outline">{type}</Badge>
          {points != null ? <Badge variant="secondary">{points} points</Badge> : null}
        </div>
        <h1 className="mt-4 text-3xl font-semibold">{title}</h1>
        {dueAt ? (
          <p className="mt-3 inline-flex items-center gap-2 text-sm text-muted-foreground">
            <CalendarClock className="size-4" />
            Due{' '}
            {new Intl.DateTimeFormat('en-US', {
              dateStyle: 'long',
              timeStyle: 'short',
            }).format(new Date(dueAt))}
          </p>
        ) : null}
      </header>
      {description ? (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-lg">
              <ClipboardCheck className="size-5 text-primary" />
              Instructions
            </CardTitle>
          </CardHeader>
          <CardContent className="prose max-w-none dark:prose-invert">
            <MarkdownRenderer content={description} />
          </CardContent>
        </Card>
      ) : null}
      {codingUnpublished ? (
        <Card className="border-amber-500/50 bg-amber-500/5">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-lg text-amber-600 dark:text-amber-400">
              <ClipboardCheck className="size-5" />
              Coding assignment not published yet
            </CardTitle>
          </CardHeader>
          <CardContent className="text-sm text-muted-foreground">
            This coding assignment hasn't been published by the instructor
            yet. The interactive code editor will appear here once the
            definition is saved — until then, you can still submit your
            response using the form below.
          </CardContent>
        </Card>
      ) : null}
      {quizUnavailable ? (
        <Card className="border-amber-500/50 bg-amber-500/5">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-lg text-amber-600 dark:text-amber-400">
              <ClipboardCheck className="size-5" />
              Quiz not published yet
            </CardTitle>
          </CardHeader>
          <CardContent className="text-sm text-muted-foreground">
            The questions for this quiz are not available yet. Please contact
            the course instructor if this continues.
          </CardContent>
        </Card>
      ) : null}
      {quizContent && quizContentItem ? (
        <LearnerQuizActivity
          contentId={quizContentItem.id}
          courseId={access.course.id}
          existingSubmissionId={quizSubmissionId}
          title={quizContentItem.title}
          description={quizContentItem.description}
          content={quizContent}
          isRequired={quizContentItem.isRequired}
          status={quizContentItem.status}
        />
      ) : codingProps ? (
        <div data-testid="ide-fullwidth-mount">
          <CodingActivityClient
            assessmentId={codingProps.assessmentId}
            enrollmentId={access.course.enrollmentId}
            courseId={access.course.id}
            slug={slug}
            assignment={codingProps.assignment}
            manifestUrl={process.env.NEXT_PUBLIC_EMCEPTION_MANIFEST_URL}
            userId={codingProps.userId}
            submissionFiles={submissionFiles}
          />
        </div>
      ) : activity && !quizUnavailable ? (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Your response</CardTitle>
          </CardHeader>
          <CardContent>
            <LearnerActivityForm
              courseId={access.course.id}
              courseSlug={slug}
              enrollmentId={access.course.enrollmentId}
              activity={activity}
            />
          </CardContent>
        </Card>
      ) : null}
    </div>
  );
}

import { CourseAccessGate } from "@/components/learning/course-access-gate";
import { CourseDiscussionThread } from "@/components/learning/course-discussion-thread";
import { getCourseAccessData } from "@/lib/learner/courses";
import { getCourseDiscussionThread } from "@/lib/learner/records";
import { notFound } from "next/navigation";

export default async function CourseDiscussionPage({
  params,
}: {
  params: Promise<{ slug: string; discussionId: string }>;
}) {
  const { slug, discussionId } = await params;
  const access = await getCourseAccessData(slug);

  if (access.kind === "not-found") notFound();
  if (access.kind !== "ready") return <CourseAccessGate access={access} />;

  const thread = await getCourseDiscussionThread(discussionId);
  if (!thread || thread.discussion.courseId !== access.course.id) notFound();

  return (
    <CourseDiscussionThread
      courseSlug={slug}
      courseTitle={access.course.title}
      discussion={thread.discussion}
      replies={thread.replies}
    />
  );
}

import '@testing-library/jest-dom/vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { LearnCourseGroups } from './groups-section';
import type { CourseGroupSetView } from '@/lib/learning/queries/assessments';
import { joinGroup, leaveGroup } from '@/lib/learning/actions';

const actionsMock = vi.hoisted(() => ({
  join: vi.fn(),
  leave: vi.fn(),
}));

const routerMocks = vi.hoisted(() => ({
  refresh: vi.fn(),
}));

vi.mock('@/lib/learning/actions', () => ({
  joinGroup: actionsMock.join,
  leaveGroup: actionsMock.leave,
}));

vi.mock('next/navigation', () => ({
  useRouter: () => routerMocks,
}));

// --- Fixtures ---------------------------------------------------------------

/** Actor ("user-me") is NOT a member of any group — Join buttons available. */
const openSets: CourseGroupSetView[] = [
  {
    id: 'set-open',
    name: 'Project teams',
    groups: [
      {
        id: 'group-3',
        name: 'Team Gamma',
        capacity: 3,
        memberCount: 0,
        members: [],
      },
      {
        id: 'group-4',
        name: 'Team Delta',
        capacity: 4,
        memberCount: 3,
        members: [
          { userId: 'user-1', displayName: 'Ada Lovelace' },
          { userId: 'user-2', displayName: 'Grace Hopper' },
          { userId: 'user-3', displayName: 'Alan Turing' },
        ],
      },
    ],
  },
];

/** Actor IS a member of group-1; group-2 is full. */
const memberSets: CourseGroupSetView[] = [
  {
    id: 'set-member',
    name: 'Lab pairs',
    groups: [
      {
        id: 'group-1',
        name: 'Team Alpha',
        capacity: 4,
        memberCount: 2,
        members: [
          { userId: 'user-me', displayName: 'Me Myself' },
          { userId: 'user-1', displayName: 'Ada Lovelace' },
        ],
      },
      {
        id: 'group-2',
        name: 'Team Beta',
        capacity: 3,
        memberCount: 3,
        members: [
          { userId: 'user-2', displayName: 'Grace Hopper' },
          { userId: 'user-3', displayName: 'Alan Turing' },
          { userId: 'user-4', displayName: 'Katherine Johnson' },
        ],
      },
    ],
  },
];

// --- Tests ------------------------------------------------------------------

describe('LearnCourseGroups', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    actionsMock.join.mockResolvedValue({ success: true, data: null });
    actionsMock.leave.mockResolvedValue({ success: true, data: null });
  });

  it('renders group names, member names, and capacity counts', () => {
    render(<LearnCourseGroups courseId="course-1" currentUserId="user-me" sets={memberSets} />);

    expect(screen.getByText('Lab pairs')).toBeInTheDocument();
    expect(screen.getByText('Team Alpha')).toBeInTheDocument();
    expect(screen.getByText('Team Beta')).toBeInTheDocument();
    expect(screen.getByText('Ada Lovelace')).toBeInTheDocument();
    expect(screen.getByText('2/4')).toBeInTheDocument();
    expect(screen.getByText('3/3')).toBeInTheDocument();
  });

  it('shows Leave on the own group and no Join anywhere in the set', () => {
    render(<LearnCourseGroups courseId="course-1" currentUserId="user-me" sets={memberSets} />);

    expect(screen.getByRole('button', { name: /leave team alpha/i })).toBeInTheDocument();
    expect(screen.queryByRole('button', { name: /^join/i })).not.toBeInTheDocument();
  });

  it('calls joinGroup with course + group ids and refreshes', async () => {
    const user = userEvent.setup();
    render(<LearnCourseGroups courseId="course-1" currentUserId="user-me" sets={openSets} />);

    await user.click(screen.getByRole('button', { name: /join team gamma/i }));

    await waitFor(() => expect(actionsMock.join).toHaveBeenCalledWith('course-1', 'group-3'));
    await waitFor(() => expect(routerMocks.refresh).toHaveBeenCalled());
  });

  it('calls leaveGroup with course + group ids', async () => {
    const user = userEvent.setup();
    render(<LearnCourseGroups courseId="course-1" currentUserId="user-me" sets={memberSets} />);

    await user.click(screen.getByRole('button', { name: /leave team alpha/i }));

    await waitFor(() => expect(actionsMock.leave).toHaveBeenCalledWith('course-1', 'group-1'));
    await waitFor(() => expect(routerMocks.refresh).toHaveBeenCalled());
  });

  it('disables Join on a full group', () => {
    render(<LearnCourseGroups courseId="course-1" currentUserId="other-user" sets={memberSets} />);

    expect(screen.getByRole('button', { name: /join team beta/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /join team alpha/i })).toBeEnabled();
  });

  it('disables both Join and Leave with a tooltip when the server reports the set locked', async () => {
    const user = userEvent.setup();
    actionsMock.join.mockResolvedValue({
      success: false,
      error: 'Group membership is locked because a linked assessment is due.',
    });
    render(<LearnCourseGroups courseId="course-1" currentUserId="user-me" sets={openSets} />);

    await user.click(screen.getByRole('button', { name: /join team gamma/i }));

    expect(await screen.findByText('Locked at deadline')).toBeInTheDocument();
    const lockedSection = screen.getByTestId('group-set-set-open');
    expect(lockedSection).toHaveTextContent('Locked at deadline');
    const joinButtons = lockedSection.querySelectorAll('button');
    joinButtons.forEach((button) => expect(button).toBeDisabled());
  });

  it('surfaces the one-group-per-set error as a message', async () => {
    const user = userEvent.setup();
    actionsMock.join.mockResolvedValue({
      success: false,
      error: 'You are already in a group in this set.',
    });
    render(<LearnCourseGroups courseId="course-1" currentUserId="user-me" sets={openSets} />);

    await user.click(screen.getByRole('button', { name: /join team gamma/i }));

    expect(await screen.findByText('You are already in a group in this set.')).toBeInTheDocument();
  });
});

'use client';

import { useState } from 'react';
import type { CourseGroupSetView } from '@/lib/learning/queries/assessments';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { Card, CardHeader, CardTitle } from '@game-guild/ui/components/card';
import { joinGroup, leaveGroup } from '@/lib/learning/actions';
import { useRouter } from 'next/navigation';

interface LearnCourseGroupsProps {
  courseId: string;
  currentUserId: string;
  sets: CourseGroupSetView[];
}

/**
 * Student group self-signup on the learn course page. The API owns the rules
 * (capacity, one-group-per-set, lock at deadline); this surface disables what
 * it can see and surfaces server rejections as messages. A "locked" rejection
 * latches per set: both buttons disable with a "Locked at deadline" note.
 */
export function LearnCourseGroups({ courseId, currentUserId, sets }: LearnCourseGroupsProps): React.JSX.Element | null {
  const router = useRouter();
  const [lockedSets, setLockedSets] = useState<Set<string>>(new Set());
  const [messages, setMessages] = useState<Record<string, string | null>>({});
  const [pendingGroup, setPendingGroup] = useState<string | null>(null);

  if (sets.length === 0) return null;

  function applyResult(setId: string, result: { success: boolean; error?: string }) {
    if (result.success) {
      setMessages((prev) => ({ ...prev, [setId]: null }));
      router.refresh();
      return;
    }
    const error = result.error ?? 'Something went wrong.';
    if (error.toLowerCase().includes('lock')) {
      setLockedSets((prev) => new Set(prev).add(setId));
      setMessages((prev) => ({ ...prev, [setId]: null }));
      return;
    }
    setMessages((prev) => ({ ...prev, [setId]: error }));
  }

  async function handleJoin(setId: string, groupId: string) {
    setPendingGroup(groupId);
    const result = await joinGroup(courseId, groupId);
    applyResult(setId, result);
    setPendingGroup(null);
  }

  async function handleLeave(setId: string, groupId: string) {
    setPendingGroup(groupId);
    const result = await leaveGroup(courseId, groupId);
    applyResult(setId, result);
    setPendingGroup(null);
  }

  return (
    <section data-testid="learn-course-groups" className="space-y-4">
      <h2 className="text-xl font-semibold tracking-tight">Groups</h2>
      {sets.map((set) => {
        const locked = lockedSets.has(set.id);
        const memberGroup = set.groups.find((group) => group.members.some((member) => member.userId === currentUserId));
        return (
          <Card key={set.id} data-testid={`group-set-${set.id}`}>
            <CardHeader>
              <div className="flex items-center justify-between gap-2">
                <CardTitle className="text-base">{set.name}</CardTitle>
                {locked && (
                  <Badge variant="outline" title="Locked at deadline">
                    Locked at deadline
                  </Badge>
                )}
              </div>
              <div className="mt-3 space-y-2">
                {set.groups.map((group) => {
                  const isMember = memberGroup?.id === group.id;
                  const isFull = group.memberCount >= group.capacity;
                  return (
                    <div key={group.id} data-testid={`group-${group.id}`} className="flex flex-wrap items-center justify-between gap-2 rounded-md border p-3">
                      <div className="min-w-0">
                        <p className="text-sm font-medium">
                          {group.name}{' '}
                          <span className="text-muted-foreground">
                            {group.memberCount}/{group.capacity}
                          </span>
                        </p>
                        {group.members.length > 0 && (
                          <p className="mt-0.5 flex flex-wrap gap-1 text-xs text-muted-foreground">
                            {group.members.map((member) => (
                              <span key={member.userId} data-testid={`group-member-${member.userId}`}>
                                {member.displayName}
                              </span>
                            ))}
                          </p>
                        )}
                      </div>
                      {isMember ? (
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => handleLeave(set.id, group.id)}
                          disabled={locked || pendingGroup === group.id}
                          title={locked ? 'Locked at deadline' : undefined}
                        >
                          Leave {group.name}
                        </Button>
                      ) : !memberGroup ? (
                        <Button
                          size="sm"
                          onClick={() => handleJoin(set.id, group.id)}
                          disabled={locked || isFull || pendingGroup === group.id}
                          title={locked ? 'Locked at deadline' : isFull ? 'This group is full' : undefined}
                        >
                          Join {group.name}
                        </Button>
                      ) : null}
                    </div>
                  );
                })}
              </div>
              {messages[set.id] && (
                <p role="alert" className="mt-2 text-sm text-destructive">
                  {messages[set.id]}
                </p>
              )}
            </CardHeader>
          </Card>
        );
      })}
    </section>
  );
}

import { Link } from '@/i18n/navigation';
import { CourseAccessGate } from '@/components/learning/course-access-gate';
import { LearnerLessonRenderer } from '@/components/learning/learner-lesson-renderer';
import { LessonProgressControls } from '@/components/learning/lesson-progress-controls';
import { getCourseAccessData } from '@/lib/learner/courses';
import { canEditCourse } from '@/lib/learning/queries/course';
import { Badge } from '@game-guild/ui/components/badge';
import { buttonVariants } from '@game-guild/ui/components/button-variants';
import { ArrowLeft, ArrowRight, Lock, Pencil } from 'lucide-react';
import { notFound } from 'next/navigation';

export default async function LessonPage({
  params,
}: {
  params: Promise<{ lessonSlug: string; slug: string }>;
}) {
  const { lessonSlug, slug } = await params;
  const access = await getCourseAccessData(slug);

  if (access.kind === 'not-found') notFound();
  if (access.kind !== 'ready') return <CourseAccessGate access={access} />;

  const items = access.course.modules.flatMap((module) => module.items);
  const itemIndex = items.findIndex((candidate) => candidate.slug === lessonSlug || candidate.id === lessonSlug);
  const item = items[itemIndex];
  if (!item || item.type !== 'lesson') notFound();

  const canEdit = await canEditCourse(access.course.id);
  const courseHref = `/learn/courses/${slug}`;
  const editHref = `/console/learning/courses/${slug}/content/${item.slug ?? item.id}`;
  const previous = [...items.slice(0, itemIndex)].reverse().find((candidate) => candidate.type === 'lesson');
  const next = items.slice(itemIndex + 1).find((candidate) => candidate.type === 'lesson');

  return (
    <article className="mx-auto max-w-4xl space-y-8">
      <header className="border-b pb-6">
        <Link href={`${courseHref}/content`} className={buttonVariants({ variant: 'ghost', className: '-ml-3 mb-4' })}>
          <ArrowLeft className="size-4" />
          Course content
        </Link>
        <div className="flex flex-wrap items-center gap-2">
          <Badge variant="outline">Lesson</Badge>
          {item.duration ? <Badge variant="secondary">{item.duration} min</Badge> : null}
          {canEdit ? (
            <Link
              href={editHref}
              className={buttonVariants({
                variant: 'ghost',
                size: 'icon-xs',
                className: 'ml-auto text-muted-foreground hover:text-foreground',
              })}
              title="Edit lesson"
            >
              <Pencil className="size-3.5" />
              <span className="sr-only">Edit lesson</span>
            </Link>
          ) : null}
        </div>
        <h1 className="mt-4 text-3xl font-semibold sm:text-4xl">{item.title}</h1>
        {item.description ? (
          <p className="mt-3 text-sm leading-6 text-muted-foreground">{item.description}</p>
        ) : null}
        <div className="mt-5">
          <LessonProgressControls
            contentId={item.id}
            courseId={access.course.id}
            status={item.status}
          />
        </div>
      </header>

      {item.status === 'locked' ? (
        <section className="flex min-h-64 flex-col items-center justify-center border-y text-center">
          <Lock className="size-8 text-muted-foreground" />
          <h2 className="mt-4 font-semibold">This lesson is locked</h2>
          <p className="mt-2 text-sm text-muted-foreground">
            Complete the prerequisite lesson before opening this content.
          </p>
        </section>
      ) : (
        <div className="min-w-0">
          <LearnerLessonRenderer
            courseId={access.course.id}
            enrollmentId={access.course.enrollmentId}
            itemId={item.id}
            format={item.lessonFormat}
            content={item.content}
          />
        </div>
      )}

      <nav aria-label="Lesson navigation" className="flex justify-between gap-4 border-t pt-6">
        {previous ? (
          <Link href={`${courseHref}/lessons/${previous.slug || previous.id}`} className={buttonVariants({ variant: 'outline' })}>
            <ArrowLeft className="size-4" />
            Previous
          </Link>
        ) : (
          <span />
        )}
        {next ? (
          <Link href={`${courseHref}/lessons/${next.slug || next.id}`} className={buttonVariants()}>
            Next
            <ArrowRight className="size-4" />
          </Link>
        ) : null}
      </nav>
    </article>
  );
}

