import { authConfig, getToken } from '@/auth';
import {
  constantTimeEqual,
  LINK_STATE_COOKIE_NAME,
  settingsAccountPath,
  verifyLinkStateCookie,
} from '@/lib/auth/oauth-link-state';
import { createServerClient, GeneratedApi } from '@game-guild/client';
import { cookies } from 'next/headers';
import { NextRequest, NextResponse } from 'next/server';

/**
 * GET /api/auth/link/discord/callback — complete the Discord account link.
 *
 * Validates the signed link-state cookie (HMAC + exp + flow === 'link' +
 * constant-time state match against the query), deletes it (single-use), then
 * exchanges the authorization code server-to-server with the caller's bearer
 * and redirects back to the account settings page with `?linked=discord` or
 * an `?error=` code for the localized banner.
 */
export async function GET(request: NextRequest): Promise<NextResponse> {
  const url = request.nextUrl;
  const code = url.searchParams.get('code');
  const state = url.searchParams.get('state');

  const cookieStore = await cookies();
  const cookieValue = cookieStore.get(LINK_STATE_COOKIE_NAME)?.value;

  const payload = await verifyLinkStateCookie(cookieValue, authConfig.secret);

  if (!payload || payload.flow !== 'link' || !state || !code) {
    cookieStore.delete(LINK_STATE_COOKIE_NAME);
    return redirectToSettings(url, payload?.locale, '?error=state_mismatch');
  }
  if (!constantTimeEqual(payload.state, state)) {
    cookieStore.delete(LINK_STATE_COOKIE_NAME);
    return redirectToSettings(url, payload.locale, '?error=state_mismatch');
  }

  cookieStore.delete(LINK_STATE_COOKIE_NAME);

  const apiUrl =
    process.env.API_URL ||
    process.env.NEXT_PUBLIC_API_URL ||
    'http://localhost:8080';
  const authModule = new GeneratedApi.AuthModule(
    createServerClient({
      baseUrl: apiUrl,
      auth: { getAccessToken: () => getToken() },
    }),
  );

  const result = await authModule.postAuthExternalLoginsDiscordLinkCallback({
    code,
    state,
    redirectUri: `${url.origin}/api/auth/link/discord/callback`,
  });

  if (result.ok) {
    return redirectToSettings(url, payload.locale, '?linked=discord');
  }
  // 409 — Discord identity already linked to another account.
  return redirectToSettings(
    url,
    payload.locale,
    result.error?.status === 409 ? '?error=conflict' : '?error=generic',
  );
}

function redirectToSettings(
  requestUrl: URL,
  locale: string | undefined,
  query: string,
): NextResponse {
  const target = new URL(settingsAccountPath(locale) + query, requestUrl.origin);
  return NextResponse.redirect(target, 302);
}

import { auth, authConfig, getToken } from '@/auth';
import { routing } from '@/i18n';
import {
  LINK_STATE_COOKIE_NAME,
  linkStateCookieOptions,
  signLinkStatePayload,
} from '@/lib/auth/oauth-link-state';
import { createServerClient, GeneratedApi } from '@game-guild/client';
import { NextRequest, NextResponse } from 'next/server';

/**
 * GET /api/auth/link/discord — start the Discord ACCOUNT-LINK flow.
 *
 * Distinct from /api/auth/signin/discord (client lib sign-in flow): this
 * requires an existing session, calls the authenticated
 * `external-logins/discord:link-authorize` endpoint with the caller's bearer,
 * and stashes a signed link-state cookie (`__gg-oauth-link-state-discord`,
 * flow:'link') validated by the callback route.
 */
export async function GET(request: NextRequest): Promise<NextResponse> {
  const session = await auth();
  if (!session || typeof session === 'function') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const redirectUri = `${request.nextUrl.origin}/api/auth/link/discord/callback`;

  const apiUrl =
    process.env.API_URL ||
    process.env.NEXT_PUBLIC_API_URL ||
    'http://localhost:8080';
  const authModule = new GeneratedApi.AuthModule(
    createServerClient({
      baseUrl: apiUrl,
      auth: { getAccessToken: () => getToken() },
    }),
  );

  const result = await authModule.postAuthExternalLoginsDiscordLinkAuthorize({ redirectUri });
  if (!result.ok || !result.data.authUrl || !result.data.state) {
    // Pass the backend status through (503 when Discord OAuth is not
    // configured, 401 on token issues) — visible proof of correct wiring.
    return NextResponse.json(
      { error: result.ok ? 'invalid_authorize_response' : 'link_authorize_failed', message: result.ok ? undefined : result.error?.message },
      { status: !result.ok ? (result.error?.status ?? 500) : 502 },
    );
  }

  const localeParam = request.nextUrl.searchParams.get('locale') ?? '';
  const locale = routing.locales.includes(localeParam as (typeof routing.locales)[number])
    ? localeParam
    : undefined;

  const cookieValue = await signLinkStatePayload(
    {
      state: result.data.state,
      flow: 'link',
      exp: Date.now() + 600_000,
      locale,
    },
    authConfig.secret,
  );

  const response = NextResponse.redirect(result.data.authUrl);
  response.cookies.set(LINK_STATE_COOKIE_NAME, cookieValue, linkStateCookieOptions());
  return response;
}

import { authConfig } from '@/auth';
import { routing } from '@/i18n/routing';
import {
  constantTimeEqual,
  SAML_STATE_COOKIE_NAME,
  verifySamlStateCookie,
} from '@/lib/auth/saml-signin-state';
import {
  createJWTPayload,
  createServerClient,
  encodeSession,
  GeneratedApi,
  parseBackendAuthResponse,
  resolveCookieOptions,
  SessionStore,
} from '@game-guild/client';
import { cookies } from 'next/headers';
import { NextRequest, NextResponse } from 'next/server';

/**
 * POST /api/auth/saml/[slug]/callback — browser form receiver for the SAML
 * HTTP-POST binding (issue #268).
 *
 * This is the Assertion Consumer Service URL the web app registers with the
 * identity provider: the provider answers the AuthnRequest with an
 * auto-submitting HTML form (`application/x-www-form-urlencoded` carrying the
 * Base64 `SAMLResponse` and the `RelayState` issued at sign-in initiation).
 * The route binds that callback to the initiating browser before anything is
 * forwarded: the posted RelayState must constant-time-match the signed,
 * single-use state cookie set in this browser when the flow started, and the
 * cookie must name this provider slug. Foreign, missing, reused (the cookie is
 * deleted on first use), or cross-provider state all fail closed. Only then is
 * the response forwarded to the API's JSON ACS
 * (`POST /v1/auth/saml/{slug}:assertion-consumer`), which enforces the
 * cryptographic validation (signatures, issuer, audience, lifetimes, signed
 * subject correlation) and single-use consumption. On success the web session
 * cookie is established exactly like the social-provider callback.
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string }> },
): Promise<NextResponse> {
  const { slug } = await params;
  const url = request.nextUrl;
  const errorPage = authConfig.pages.error || '/sign-in';

  const form = await request.formData().catch(() => null);
  const samlResponse = form?.get('SAMLResponse');
  const postedRelayState = form?.get('RelayState');

  const cookieStore = await cookies();
  const cookieValue = cookieStore.get(SAML_STATE_COOKIE_NAME)?.value;
  const payload = await verifySamlStateCookie(cookieValue, authConfig.secret);

  if (
    !payload ||
    payload.flow !== 'saml' ||
    payload.slug !== slug ||
    typeof samlResponse !== 'string' ||
    samlResponse.length === 0 ||
    typeof postedRelayState !== 'string' ||
    !constantTimeEqual(payload.state, postedRelayState)
  ) {
    // Missing (never initiated here / already used), tampered, expired,
    // cross-provider, or foreign RelayState — one fail-closed branch, and the
    // cookie is always burnt so it can never be retried against this browser.
    cookieStore.delete(SAML_STATE_COOKIE_NAME);
    return NextResponse.redirect(
      new URL(`${errorPage}?error=state_mismatch`, url.origin),
      302,
    );
  }

  cookieStore.delete(SAML_STATE_COOKIE_NAME);

  const apiUrl =
    process.env.API_URL ||
    process.env.NEXT_PUBLIC_API_URL ||
    'http://localhost:8080';
  const authModule = new GeneratedApi.AuthModule(
    createServerClient({ baseUrl: apiUrl }),
  );

  const result = await authModule.postAuthSamlAssertionConsumer(slug, {
    samlResponse,
    relayState: postedRelayState,
    rememberMe: payload.rememberMe,
    tenantId: payload.tenantId,
  });

  if (!result.ok || !result.data.accessToken) {
    // 401 — the API's fail-closed validation (signature, correlation, replay,
    // tenant isolation, MFA policy); anything else is a federation failure.
    const code = !result.ok && result.error.status === 401 ? 'saml_rejected' : 'saml_failed';
    return NextResponse.redirect(
      new URL(`${errorPage}?error=${code}`, url.origin),
      302,
    );
  }

  const providerResult = parseBackendAuthResponse(
    result.data as unknown as Record<string, unknown>,
  );
  providerResult.rememberMe = payload.rememberMe;

  const signInAllowed = await authConfig.callbacks.signIn({
    user: providerResult.user,
    provider: `saml:${slug}`,
  });
  if (signInAllowed === false) {
    return NextResponse.redirect(
      new URL(`${errorPage}?error=access_denied`, url.origin),
      302,
    );
  }

  // Establish the session exactly like the library's OAuth callback
  // (createJWTPayload → jwt callback → encodeSession → session cookie).
  let token = createJWTPayload(providerResult, authConfig);
  token = await authConfig.callbacks.jwt({
    token,
    user: providerResult.user,
    trigger: 'signIn',
  });
  const encrypted = await encodeSession(token, authConfig);
  const cookieOptions = resolveCookieOptions(
    authConfig.cookies,
    authConfig.cookies.secure,
  );
  new SessionStore(cookieOptions).write(
    encrypted,
    (name, value, options) => cookieStore.set(name, value, options),
    { storage: payload.rememberMe === false ? 'session' : 'persistent' },
  );

  let callbackUrl = payload.redirectTo || '/';
  if (
    payload.locale &&
    routing.locales.includes(payload.locale as (typeof routing.locales)[number]) &&
    !callbackUrl.startsWith(`/${payload.locale}`)
  ) {
    callbackUrl = `/${payload.locale}${callbackUrl}`;
  }
  if (!callbackUrl.startsWith('/') || callbackUrl.startsWith('//')) {
    callbackUrl = '/';
  }

  return NextResponse.redirect(new URL(callbackUrl, url.origin), 302);
}

import { authConfig } from '@/auth';
import { resolveAllowedAuthRedirect } from '@/lib/auth/cross-domain-auth';
import {
  SAML_STATE_COOKIE_NAME,
  SAML_STATE_COOKIE_MAX_AGE,
  samlStateCookieOptions,
  signSamlStatePayload,
} from '@/lib/auth/saml-signin-state';
import { createServerClient, GeneratedApi } from '@game-guild/client';
import { cookies } from 'next/headers';
import { NextRequest, NextResponse } from 'next/server';

/**
 * GET /api/auth/saml/[slug]/signin — start a SAML federation sign-in (issue #268).
 *
 * Asks the API to issue an AuthnRequest (`POST /v1/auth/saml/{slug}:sign-in-authorize`),
 * binds the returned RelayState token to a signed, single-use, HttpOnly state
 * cookie in the initiating browser (SameSite=None: the IdP returns the browser
 * through a top-level cross-site form POST), then redirects the browser to the
 * identity provider. The ACS receiver (`/api/auth/saml/[slug]/callback`) later
 * refuses any callback whose posted RelayState does not match this cookie.
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string }> },
): Promise<NextResponse> {
  const { slug } = await params;
  const url = request.nextUrl;
  const errorPage = authConfig.pages.error || '/sign-in';

  if (!isValidSlug(slug)) {
    return NextResponse.redirect(new URL(`${errorPage}?error=saml_invalid_provider`, url.origin), 302);
  }

  const apiUrl =
    process.env.API_URL ||
    process.env.NEXT_PUBLIC_API_URL ||
    'http://localhost:8080';
  const authModule = new GeneratedApi.AuthModule(
    createServerClient({ baseUrl: apiUrl }),
  );

  const result = await authModule.postAuthSamlSignInAuthorize(slug, {});

  if (!result.ok || !result.data.redirectUrl || !result.data.relayState) {
    // Unknown/disabled/misconfigured provider, or the API could not issue the
    // request — fail closed, never send the browser to the provider.
    return NextResponse.redirect(new URL(`${errorPage}?error=saml_unavailable`, url.origin), 302);
  }

  const rememberMe = url.searchParams.get('rememberMe');
  const tenantId = url.searchParams.get('tenantId');
  const cookieStore = await cookies();
  cookieStore.set(
    SAML_STATE_COOKIE_NAME,
    await signSamlStatePayload(
      {
        state: result.data.relayState,
        slug,
        flow: 'saml',
        redirectTo: resolveAllowedAuthRedirect(url.searchParams.get('redirectTo')),
        // Only a real UUID survives: the callback forwards this value into the
        // API's UUID-typed DTO, and a malformed one must degrade to "no tenant
        // requested" here — not surface as a 500 at callback time.
        tenantId: tenantId && UUID_PATTERN.test(tenantId) ? tenantId : undefined,
        locale: url.searchParams.get('locale') ?? undefined,
        rememberMe:
          rememberMe === null ? undefined : rememberMe.toLowerCase() === 'true',
        exp: Date.now() + SAML_STATE_COOKIE_MAX_AGE * 1000,
      },
      authConfig.secret,
    ),
    samlStateCookieOptions(),
  );

  return NextResponse.redirect(result.data.redirectUrl, 302);
}

/**
 * Provider slugs are the configured `Saml:<slug>` keys and must satisfy the
 * shared federation-slug contract enforced by the API
 * (`ExternalProviderOptions.IsValidFederationSlug`): lowercase ASCII letters,
 * digits, and hyphens, starting and ending with a letter or digit, max 64.
 */
function isValidSlug(slug: string): boolean {
  return /^[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?$/.test(slug);
}

/** Tenant ids are GUIDs on the API side; anything else is dropped, never forwarded. */
const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

