import type { MetadataRoute } from 'next';
import { PUBLIC_PROGRAM_PACKAGES } from '@/lib/courses/public-programs';
import { getPublicCourseCatalog } from '@/lib/courses/services/course.service';
import { getAllBlogPostsForSitemap, getAllPublishedProjectsForSitemap } from '@/lib/sitemap/public-entries';
import { buildBlogAbsoluteCanonicalUrl, BLOG_SITE_BASE_URL } from '@/lib/blogs/seo';

const baseUrl = process.env.NEXT_PUBLIC_APP_URL ?? 'https://gameguild.gg';
const staticRoutes = [
  '',
  '/sign-in',
  '/sign-up',
  '/courses',
  '/projects',
  '/community',
  '/testing-lab',
  '/launch-pad',
  '/jobs',
  '/about',
  '/about/roadmap',
  '/about/contributors',
  '/contact',
  '/legal',
  '/terms-of-service',
  '/terms-of-use',
  '/polices/privacy',
  '/polices/cookies',
  '/legal/licenses',
  '/legal/ferpa-waiver',
  '/legal/academic-honesty',
];

// NOTE: This must stay a single sitemap (no `generateSitemaps`). With `generateSitemaps`
// Next.js serves the sitemap at `/sitemap/<id>.xml` and `/sitemap.xml` 404s — which is
// what robots.ts advertises. sitemap.test.ts guards this coupling.
export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const now = new Date();
  const [projects, catalog, blogPosts] = await Promise.all([
    getAllPublishedProjectsForSitemap().catch(() => []),
    getPublicCourseCatalog().catch(() => null),
    getAllBlogPostsForSitemap().catch(() => []),
  ]);
  const courseRoutes = catalog?.success
    ? catalog.data
        .map((course) => (typeof course.slug === 'string' && course.slug.length > 0 ? course.slug : null))
        .filter((slug): slug is string => Boolean(slug))
        .map((slug) => ({
          url: `${baseUrl}/courses/${slug}`,
          lastModified: now,
          changeFrequency: 'weekly' as const,
          priority: 0.7,
        }))
    : [];

  return [
    ...staticRoutes.map((route) => ({
      url: `${baseUrl}${route}`,
      lastModified: now,
      changeFrequency: route === '' ? ('daily' as const) : ('monthly' as const),
      priority: route === '' ? 1 : 0.6,
    })),
    ...projects.map((project) => ({
      url: `${baseUrl}/projects/${project.slug}`,
      lastModified: now,
      changeFrequency: 'weekly' as const,
      priority: 0.7,
    })),
    ...PUBLIC_PROGRAM_PACKAGES.map((program) => ({
      url: `${baseUrl}/programs/${program.slug}`,
      lastModified: now,
      changeFrequency: 'weekly' as const,
      priority: 0.7,
    })),
    ...courseRoutes,
    ...blogPosts
      .filter((post) => post.slug && post.primaryAuthorHandle)
      .map((post) => ({
        url: buildBlogAbsoluteCanonicalUrl(BLOG_SITE_BASE_URL, post.primaryAuthorHandle ?? '', post.slug ?? ''),
        lastModified: post.publishedAt ? new Date(post.publishedAt) : now,
        changeFrequency: 'weekly' as const,
        priority: 0.6,
      })),
  ];
}

import { cache } from "react";
import {
  GameGuildAuth,
  CredentialsProvider,
  CredentialsSignInError,
  GoogleProvider,
  DiscordProvider,
  GitHubProvider,
  processSession,
  encodeSession,
  SessionStore,
  resolveCookieOptions,
  type Session,
} from "@game-guild/client";
import { cookies } from "next/headers";
import { verifyTurnstileToken } from "@/lib/antibot/turnstile";
import { createSharedAuthCookieConfig } from "@/lib/auth/cross-domain-auth";
import { createMagicLinkCredentialsAuthorize } from "@/lib/auth/magic-link-credentials";
import { createEmailCodeCredentialsAuthorize } from "@/lib/auth/email-code-credentials";
import { createWeb3CredentialsAuthorize } from "@/lib/auth/web3-credentials";
import { withAntibotVerification } from "@/lib/auth/antibot-authorize";

const passwordCredentials = CredentialsProvider();
const apiUrl =
  process.env.API_URL ||
  process.env.NEXT_PUBLIC_API_URL ||
  "http://localhost:8080";

const result = GameGuildAuth({
  providers: [
    CredentialsProvider({
      authorize: createWeb3CredentialsAuthorize(
        createMagicLinkCredentialsAuthorize(
          createEmailCodeCredentialsAuthorize(
            // Turnstile gates ONLY the password layer: magic-link, MFA and web3
            // are token-less or use their own challenge tokens and must not
            // require a Turnstile token (see withAntibotVerification).
            withAntibotVerification(passwordCredentials.authorize),
            apiUrl,
          ),
          apiUrl,
        ),
        apiUrl,
      ),
    }),
    ...(process.env.GOOGLE_CLIENT_ID && process.env.GOOGLE_CLIENT_SECRET
      ? [
          GoogleProvider({
            clientId: process.env.GOOGLE_CLIENT_ID,
            clientSecret: process.env.GOOGLE_CLIENT_SECRET,
          }),
        ]
      : []),
    ...(process.env.DISCORD_CLIENT_ID && process.env.DISCORD_CLIENT_SECRET
      ? [
          DiscordProvider({
            clientId: process.env.DISCORD_CLIENT_ID,
            clientSecret: process.env.DISCORD_CLIENT_SECRET,
          }),
        ]
      : []),
    ...(process.env.GITHUB_CLIENT_ID && process.env.GITHUB_CLIENT_SECRET
      ? [
          GitHubProvider({
            clientId: process.env.GITHUB_CLIENT_ID,
            clientSecret: process.env.GITHUB_CLIENT_SECRET,
          }),
        ]
      : []),
  ],
  pages: {
    // Callback failures redirect here with ?error=; the page renders it inline.
    error: "/sign-in",
  },
  apiUrl,
  secret:
    process.env.AUTH_SECRET ||
    (process.env.NEXT_PHASE === "phase-production-build"
      ? "build-time-placeholder-not-used-at-runtime"
      : process.env.NODE_ENV === "development"
        ? "game-guild-web-local-development-secret"
        : undefined),
  debug: process.env.NODE_ENV === "development",
  cookies: createSharedAuthCookieConfig({
    authCookieDomain: process.env.AUTH_COOKIE_DOMAIN,
    authCookieSecure: process.env.AUTH_COOKIE_SECURE,
    nodeEnv: process.env.NODE_ENV,
  }),
});

export const { handlers, signIn, signOut, update } = result;

const rawSignUp = result.signUp;

/**
 * Sign-up is always password-based, so it is gated unconditionally. The
 * fail-open behavior comes from verifyTurnstileToken itself when
 * TURNSTILE_SECRET_KEY is unset (dev/e2e).
 */
export async function signUp(
  credentials: Parameters<typeof rawSignUp>[0] & { turnstileToken?: string },
  options?: Parameters<typeof rawSignUp>[1],
) {
  const verification = await verifyTurnstileToken(credentials.turnstileToken);

  if (!verification.success) {
    throw new CredentialsSignInError("Bot verification failed");
  }

  return rawSignUp(credentials, options);
}

export const authConfig = result.config;

type AuthProxyHandler = Parameters<typeof result.auth>[0];

// All server readers use the same request-bound Next cookie context. The
// explicit-request proxy wrapper still belongs to the shared auth library.
export function auth(): Promise<Session | null>;
export function auth(handler: AuthProxyHandler): ReturnType<typeof result.auth>;
export function auth(handler?: AuthProxyHandler) {
  return handler ? result.auth(handler) : getSession();
}

// Single-flight guard for refresh-token rotation: concurrent readers within
// ONE request rotating in parallel would present already-revoked tokens (one
// cookie write wins; the sibling's token is revoked). The guard is keyed by the
// per-request cookie store (Next returns a fresh store object per request), so
// unrelated concurrent requests never suppress each other's cookie writes.
const requestRotations = new WeakMap<object, Promise<void>>();

async function readCurrentSession() {
  const cookieStore = await cookies();
  const cookieOptions = resolveCookieOptions(
    authConfig.cookies,
    authConfig.cookies.secure,
  );
  const sessionStore = new SessionStore(cookieOptions);
  const encrypted = sessionStore.read((name) => cookieStore.get(name)?.value);

  if (!encrypted) {
    return { session: null, token: null };
  }

  const { session, token, updated } = await processSession(
    encrypted,
    authConfig,
  );

  if (updated && token) {
    const write = async () => {
      try {
        const newEncrypted = await encodeSession(token, authConfig);
        sessionStore.write(newEncrypted, (name, value, options) =>
          cookieStore.set(name, value, options),
        );
      } catch {
        // Server Components can read a valid refreshed session even when the
        // response context cannot persist its rotated cookie.
      }
    };

    // A concurrent rotation on this request's cookie store already wrote;
    // skip writing our possibly-stale cookie — the sibling write is
    // authoritative.
    const prior = requestRotations.get(cookieStore);
    if (prior) {
      await prior;
    } else {
      const rotation = write().finally(() => {
        requestRotations.delete(cookieStore);
      });
      requestRotations.set(cookieStore, rotation);
      await rotation;
    }
  }

  if (!session) {
    try {
      sessionStore.delete((name, value, options) => cookieStore.set(name, value, options));
    } catch {
      // Read-only Server Components still return an anonymous authentication state.
    }
  }

  return { session, token };
}

// Server Components must read Next's request-bound cookie store directly.
// The shared auth helper uses a dynamic next/headers import that is unavailable
// in the standalone RSC runtime, while the proxy continues to use auth().
/**
 * Resolves the complete authentication state once for the active request.
 *
 * Keeping the session, token, and tenant together prevents parallel API
 * clients from observing different rotations of the same session cookie.
 */
export const getRequestAuthContext = cache(async () => {
  const { session, token } = await readCurrentSession();
  return {
    session,
    token: token?.accessToken ?? null,
    tenantId: session?.tenantId ?? null,
  };
});

export async function getSession() {
  return (await getRequestAuthContext()).session;
}

export async function getToken(): Promise<string | null> {
  return (await getRequestAuthContext()).token;
}

/**
 * Uncached session read for the post-MFA rotation race (issue #864): the
 * cached getRequestAuthContext is memoized per request, so a layout guard
 * retry through auth() would replay the first (null) result. This re-reads
 * the session cookie store directly, bypassing the memoization.
 */
export async function readSessionUnCached(): Promise<Session | null> {
  const { session } = await readCurrentSession();
  return session;
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { screen, waitFor } from '@testing-library/react';
import { createMockUseAuth, renderWithUser, type MockUseAuthReturn } from '@/test/auth-test-helpers';

/* ------------------------------------------------------------------ */
/*  Module mocks                                                       */
/* ------------------------------------------------------------------ */

let mockAuth: MockUseAuthReturn;

vi.mock('@game-guild/client/react', () => ({
  useAuth: () => mockAuth,
}));

vi.mock('next/link', () => ({
  default: ({ children, href, ...rest }: { children: React.ReactNode; href: string }) => (
    <a href={href} {...rest}>
      {children}
    </a>
  ),
}));

vi.mock('next-intl', () => ({
  useLocale: () => 'en-US',
}));

vi.mock('@/i18n/navigation', () => ({
  Link: ({ children, href, locale: _locale, ...rest }: { children: React.ReactNode; href: string; locale?: string }) => (
    <a href={href} {...rest}>
      {children}
    </a>
  ),
  useRouter: () => ({ replace: vi.fn(), push: vi.fn() }),
}));

// Must import AFTER mocks
const { SignInForm } = await import('@/components/sign-in-form');

/* ------------------------------------------------------------------ */
/*  Tests                                                              */
/* ------------------------------------------------------------------ */

describe('SignInForm', () => {
  beforeEach(() => {
    mockAuth = createMockUseAuth();
  });

  /* ---------- Rendering ---------- */

  it('renders the login form with all required elements', () => {
    renderWithUser(<SignInForm />);

    expect(screen.getByText('Welcome back')).toBeInTheDocument();
    expect(screen.getByLabelText('Email')).toBeInTheDocument();
    expect(screen.getByLabelText('Password')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /sign in$/i })).toBeInTheDocument();
    expect(screen.queryByRole('button', { name: /login with apple/i })).not.toBeInTheDocument();
    expect(screen.queryByRole('button', { name: /login with google/i })).not.toBeInTheDocument();
  });

  it('renders navigation links', () => {
    renderWithUser(<SignInForm />);

    expect(screen.getByText('Sign up')).toHaveAttribute('href', '/sign-up?redirectTo=%2F');
    expect(screen.getByText('Forgot your password?')).toHaveAttribute('href', '/forgot-password');
    // Terms of Service / Privacy Policy moved to the shared (auth) layout footer.
  });

  /* ---------- Client-side validation ---------- */

  it('shows error when email is empty on submit', async () => {
    const { user } = renderWithUser(<SignInForm />);

    await user.click(screen.getByRole('button', { name: /sign in$/i }));

    expect(screen.getByText('Email is required.')).toBeInTheDocument();
    expect(mockAuth.signIn).not.toHaveBeenCalled();
  });

  it('shows error when password is empty on submit', async () => {
    const { user } = renderWithUser(<SignInForm />);

    await user.type(screen.getByLabelText('Email'), 'test@example.com');
    await user.click(screen.getByRole('button', { name: /sign in$/i }));

    expect(screen.getByText('Password is required.')).toBeInTheDocument();
    expect(mockAuth.signIn).not.toHaveBeenCalled();
  });

  it('clears field error when user starts typing', async () => {
    const { user } = renderWithUser(<SignInForm />);

    // Trigger email error
    await user.click(screen.getByRole('button', { name: /sign in$/i }));
    expect(screen.getByText('Email is required.')).toBeInTheDocument();

    // Start typing clears error
    await user.type(screen.getByLabelText('Email'), 'a');
    expect(screen.queryByText('Email is required.')).not.toBeInTheDocument();
  });

  /* ---------- Successful submission ---------- */

  it('calls signIn with credentials on valid submission', async () => {
    const { user } = renderWithUser(<SignInForm />);

    await user.type(screen.getByLabelText('Email'), 'test@example.com');
    await user.type(screen.getByLabelText('Password'), 'password123');
    await user.click(screen.getByRole('button', { name: /sign in$/i }));

    expect(mockAuth.clearError).toHaveBeenCalled();
    expect(mockAuth.signIn).toHaveBeenCalledWith('credentials', {
      email: 'test@example.com',
      password: 'password123',
      rememberMe: false,
      redirectTo: '/',
      turnstileToken: null,
    });
  });

  /* ---------- Loading state ---------- */

  it('shows loading text and disables inputs while loading', () => {
    mockAuth = createMockUseAuth({ isLoading: true });
    renderWithUser(<SignInForm />);

    expect(screen.getByRole('button', { name: /signing in/i })).toBeDisabled();
    expect(screen.getByLabelText('Email')).toBeDisabled();
    expect(screen.getByLabelText('Password')).toBeDisabled();
  });

  /* ---------- Error display ---------- */

  it('displays API error from useAuth', () => {
    mockAuth = createMockUseAuth({
      error: new Error('Invalid credentials'),
    });
    renderWithUser(<SignInForm />);

    expect(screen.getByText('Invalid credentials')).toBeInTheDocument();
  });

  it('clears error on new submission', async () => {
    const { user } = renderWithUser(<SignInForm />);

    await user.type(screen.getByLabelText('Email'), 'test@example.com');
    await user.type(screen.getByLabelText('Password'), 'pass');
    await user.click(screen.getByRole('button', { name: /sign in$/i }));

    expect(mockAuth.clearError).toHaveBeenCalled();
  });

  /* ---------- Accessibility ---------- */

  it('sets aria-invalid on email field when validation fails', async () => {
    const { user } = renderWithUser(<SignInForm />);

    await user.click(screen.getByRole('button', { name: /sign in$/i }));

    expect(screen.getByLabelText('Email')).toHaveAttribute('aria-invalid', 'true');
  });

  it('sets aria-invalid on password field when validation fails', async () => {
    const { user } = renderWithUser(<SignInForm />);

    await user.type(screen.getByLabelText('Email'), 'test@example.com');
    await user.click(screen.getByRole('button', { name: /sign in$/i }));

    expect(screen.getByLabelText('Password')).toHaveAttribute('aria-invalid', 'true');
  });

  /* ---------- Handles signIn rejection ---------- */

  it('handles signIn rejection gracefully', async () => {
    mockAuth = createMockUseAuth({
      signIn: vi.fn().mockRejectedValue(new Error('Network error')),
    });
    const { user } = renderWithUser(<SignInForm />);

    await user.type(screen.getByLabelText('Email'), 'test@example.com');
    await user.type(screen.getByLabelText('Password'), 'password123');

    // Should not throw
    await user.click(screen.getByRole('button', { name: /sign in$/i }));
  });

  /* ---------- className forwarding ---------- */

  it('forwards className prop', () => {
    const { container } = renderWithUser(<SignInForm className="custom-class" />);

    expect(container.firstChild).toHaveClass('custom-class');
  });
});

import { afterEach, beforeEach, describe, it, expect, vi } from 'vitest';
import { screen, waitFor } from '@testing-library/react';
import {
  createMockUseAuth,
  renderWithUser,
  type MockUseAuthReturn,
} from '@/test/auth-test-helpers';

/* ------------------------------------------------------------------ */
/*  Module mocks                                                       */
/* ------------------------------------------------------------------ */

let mockAuth: MockUseAuthReturn;

const turnstileHarness = vi.hoisted(() => ({
  captured: null as null | { onToken: (token: string | null) => void; action?: string },
}));

vi.mock('@/components/antibot/turnstile-widget', () => ({
  TurnstileWidget: (props: { onToken: (token: string | null) => void; action?: string }) => {
    turnstileHarness.captured = props;
    return null;
  },
}));

vi.mock('@game-guild/client/react', () => ({
  useAuth: () => mockAuth,
}));

vi.mock('@/i18n/navigation', () => ({
  Link: ({
    children,
    href,
    locale,
    ...rest
  }: {
    children: React.ReactNode;
    href: string;
    locale?: string;
  }) => (
    <a href={locale ? `/${locale}${href}` : href} data-locale={locale} {...rest}>
      {children}
    </a>
  ),
}));

vi.mock('next-intl', () => ({
  useLocale: () => 'en-US',
}));

const { SignupForm } = await import('@/components/signup-form');

/* ------------------------------------------------------------------ */
/*  Tests                                                              */
/* ------------------------------------------------------------------ */

