  beforeEach(() => {
    mockAuth = createMockUseAuth();
    turnstileHarness.captured = null;
  });

  /* ---------- Rendering ---------- */

  it('renders the signup form with all required elements', () => {
    renderWithUser(<SignupForm />);

    expect(screen.getByText('Create your GameGuild account')).toBeInTheDocument();
    expect(screen.getByLabelText('Full Name')).toBeInTheDocument();
    expect(screen.getByLabelText('Email')).toBeInTheDocument();
    expect(screen.getByLabelText('Password')).toBeInTheDocument();
    expect(screen.getByLabelText('Confirm Password')).toBeInTheDocument();
    expect(
      screen.getByRole('button', { name: /create account$/i })
    ).toBeInTheDocument();
  });

  it('renders navigation links', () => {
    renderWithUser(<SignupForm />);

    expect(screen.getByText('Sign in')).toHaveAttribute('href', '/en-US/sign-in?redirectTo=%2F');
    // Terms of Service / Privacy Policy moved to the shared (auth) layout footer.
  });

  /* ---------- Client-side validation ---------- */

  it('shows error when name is empty on submit', async () => {
    const { user } = renderWithUser(<SignupForm />);

    await user.click(
      screen.getByRole('button', { name: /create account$/i })
