"use client";

import { type FormEvent, useSyncExternalStore } from "react";
import { useTranslations } from "next-intl";
import { useAuth } from "@game-guild/client/react";
import { Link } from "@/i18n/navigation";
import { Button } from "@game-guild/ui/components/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@game-guild/ui/components/card";
import {
  Field,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@game-guild/ui/components/field";
import { Input } from "@game-guild/ui/components/input";

const subscribeToHydration = () => () => undefined;

/**
 * MFA challenge form for the dedicated /sign-in/2fa route. The challenge
 * (mfaToken, availableMethods) is persisted by useAuth in sessionStorage so
 * it survives the navigation from /sign-in; without one (direct visit or
 * post-expiry refresh) a back-to-sign-in notice renders.
 */
export function MfaChallengeForm({
  className,
  redirectTo = "/",
  ...props
}: React.ComponentProps<"div"> & {
  redirectTo?: string;
}) {
  const { signIn, isLoading, error, mfaChallenge, clearMfa } = useAuth();
  const t = useTranslations("signIn.mfa");
  const isHydrated = useSyncExternalStore(
    subscribeToHydration,
    () => true,
    () => false,
  );

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!mfaChallenge) return;
    const form = e.currentTarget;
    const data = new FormData(form);
    try {
      await signIn("credentials", {
        mfaToken: mfaChallenge.mfaToken,
        method: data.get("method") || "Totp",
        code: data.get("code") as string,
        redirectTo,
      });
      form.reset();
    } catch {
      /* The hook keeps the current challenge and exposes the error. */
    }
  }

  if (!mfaChallenge) {
    return (
      <Card className={className} {...props}>
        <CardHeader className="text-center">
          <CardTitle className="text-2xl">
            <h1>{t("title")}</h1>
          </CardTitle>
          <CardDescription className="text-slate-300">
            {t("noChallenge")}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Link
            href="/sign-in"
            className="text-sky-200 underline-offset-4 hover:underline"
          >
            {t("backToSignIn")}
          </Link>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className={className} {...props}>
      <Card className="border-white/10 bg-slate-900/85 text-white shadow-2xl shadow-sky-950/30 backdrop-blur">
        <CardHeader className="text-center">
          <CardTitle className="text-2xl">
            <h1>{t("title")}</h1>
          </CardTitle>
          <CardDescription className="text-slate-300">
            {t("description")}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form
            method="post"
            onSubmit={(event) => {
              void handleSubmit(event);
            }}
            data-auth-ready={isHydrated ? "true" : "false"}
          >
            <FieldGroup>
              {mfaChallenge.availableMethods.includes("BackupCode") && (
                <Field>
                  <FieldLabel htmlFor="mfa-method">
                    {t("methodLabel")}
                  </FieldLabel>
                  <select
                    id="mfa-method"
                    name="method"
                    defaultValue="Totp"
                    disabled={isLoading}
                    className="h-10 rounded border border-white/10 bg-slate-900 px-3"
                  >
                    <option value="Totp">{t("methodTotp")}</option>
                    <option value="BackupCode">{t("methodBackupCode")}</option>
                  </select>
                </Field>
              )}
              <Field>
                <FieldLabel htmlFor="mfa-code">{t("codeLabel")}</FieldLabel>
                <Input
                  id="mfa-code"
                  name="code"
                  autoComplete="one-time-code"
                  required
                  disabled={isLoading}
                  className="h-10 border-white/10 bg-white/5 text-white"
                />
              </Field>
              {error &&
                !("type" in error && error.type === "MfaRequired") && (
                  <FieldError>{error.message}</FieldError>
                )}
              <Button type="submit" disabled={isLoading || !isHydrated}>
                {t("submit")}
              </Button>
              <Button
                type="button"
                variant="ghost"
                disabled={isLoading}
                className="text-slate-200 hover:bg-white/10 hover:text-white"
                onClick={() => {
                  clearMfa();
                }}
              >
                {t("startAgain")}
              </Button>
            </FieldGroup>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

"use client"

/**
 * Surface-agnostic registry of preview renderers for embeddable blocks.
 *
 * Each entry takes a `Block` envelope and renders the matching `preview-*`
 * component already used elsewhere in the editor. Heavy previews are
 * loaded lazily so embedding a `divider` never pulls in mermaid/vega/code
 * bundles.
 *
 * MUST NOT import from `lexical`, `@lexical/*`, or `../plugins/` /
 * `../nodes/` (except `nodes/base/serialized-*` types).
 */

import { lazy } from "react"
import { Loader2 } from "lucide-react"

import { PreviewHTML } from "../plugins/preview-components/preview-html"

import type { Block } from "../lib/storage/editor/block-structure"
import type { SerializedHTMLNode } from "../nodes/html-node"
import type { SerializedMarkdownNode } from "../nodes/markdown-node"

import type {
  EmbedPreviewProps,
  EmbeddableBlockConfig,
} from "./types"
import { ClientOnlyLazy } from "../lib/client-only-lazy"

// ---------------------------------------------------------------------------
// Lazy previews for heavy bundles
// ---------------------------------------------------------------------------

function PreviewSkeleton({ label }: { label: string }) {
  return (
    <div className="my-4 flex items-center gap-2 rounded-lg border border-dashed bg-muted/30 p-4 text-sm text-muted-foreground">
      <Loader2 className="h-4 w-4 animate-spin" />
      <span>Carregando {label}…</span>
    </div>
  )
}

const LazyPreviewCodeStudio = lazy(async () => ({
  default: (await import("../lazy-client-components")).CodeStudioEditor,
}))

const LazyPreviewMermaid = lazy(async () => ({
  default: (await import("../plugins/preview-components/preview-mermaid")).PreviewMermaid,
}))

const LazyPreviewVegaLite = lazy(async () => ({
  default: (await import("../plugins/preview-components/preview-vega-lite")).PreviewVegaLite,
}))

// Markdown is loaded lazily to avoid a static import cycle:
// preview-markdown → markdown-renderer → this registry.
const LazyPreviewMarkdown = lazy(async () => ({
  default: (await import("../plugins/preview-components/preview-markdown")).PreviewMarkdown,
}))

// ---------------------------------------------------------------------------
// Adapters: Block envelope → preview component props
// ---------------------------------------------------------------------------

function toSerialized<T extends string, D>(block: Block & { type: T; data: D }) {
  return { type: block.type, version: 1, data: block.data }
}

function PreviewCodeStudioAdapter({ block }: EmbedPreviewProps<"code-studio">) {
  return (
    <ClientOnlyLazy
      component={LazyPreviewCodeStudio}
      props={{ data: block.data, isPreview: true }}
      fallback={<PreviewSkeleton label="code studio" />}
    />
  )
}

function PreviewHTMLAdapter({ block }: EmbedPreviewProps<"html">) {
  return <PreviewHTML node={toSerialized(block) as SerializedHTMLNode} />
}

function PreviewMarkdownAdapter({ block }: EmbedPreviewProps<"markdown">) {
  return (
    <ClientOnlyLazy
      component={LazyPreviewMarkdown}
      props={{ node: toSerialized(block) as SerializedMarkdownNode }}
      fallback={<PreviewSkeleton label="markdown" />}
    />
  )
}

// ---------------------------------------------------------------------------
// Public registry
// ---------------------------------------------------------------------------

export const EMBEDDABLE_BLOCK_CONFIG: EmbeddableBlockConfig = {
  "code-studio": { Preview: PreviewCodeStudioAdapter },
  "html": { Preview: PreviewHTMLAdapter },
  "markdown": { Preview: PreviewMarkdownAdapter },
}

"use client"

/**
 * Surface-agnostic React shell for an embedded block.
 *
 * Renders the preview registered for `block.type` and, when `editable`,
 * overlays minimal affordances (Editar / Remover) that delegate to the
 * surface (Lexical decorator today, Markdown renderer in the future) via
 * the `onChange` / `onRemove` callbacks.
 *
 * MUST NOT import from `lexical`, `@lexical/*`, or anything under
 * `../nodes/` / `../plugins/`.
 */

import { useCallback, useEffect, useRef, useState } from "react"
import { Pencil, Trash2 } from "lucide-react"
import { Button } from "@game-guild/ui/components/button"
import { cn } from "@/lib/utils"

import { BlockEditorModal } from "../engines/blocks/block-editor-modal"
import { EMBEDDABLE_BLOCK_CONFIG } from "./block-embed-registry"
import { isEmbeddableBlockType } from "./embeddable-blocks"
import type { EmbeddableBlock, EmbeddableBlockData } from "./types"

interface BlockEmbedViewProps {
  block: EmbeddableBlock
  editable: boolean
  /** Called with the new `data` after the user saves the inline editor. */
  onChange?: (data: EmbeddableBlockData) => void
  /** Called when the user clicks the Remove affordance. */
  onRemove?: () => void
  /**
   * When true, opens the editor automatically once if `block.data.isNew`
   * is truthy. Default true.
   */
  autoOpenIfNew?: boolean
}

export function BlockEmbedView({
  block,
  editable,
  onChange,
  onRemove,
  autoOpenIfNew = true,
}: BlockEmbedViewProps) {
  const [editorOpen, setEditorOpen] = useState(false)
  const autoOpenedRef = useRef(false)

  // Auto-open editor for newly inserted blocks (one-shot).
  useEffect(() => {
    if (!editable || !autoOpenIfNew || autoOpenedRef.current) return
    const data = block.data as { isNew?: boolean } | null
    if (data && data.isNew) {
      autoOpenedRef.current = true
      setEditorOpen(true)
    }
  }, [editable, autoOpenIfNew, block.data])

  const handleSave = useCallback(
    (newData: EmbeddableBlockData) => {
      // Strip transient `isNew` flag on first save, matching the block array
      // engine convention.
      const cleaned =
        newData && typeof newData === "object" && "isNew" in (newData as object)
          ? { ...(newData as unknown as Record<string, unknown>), isNew: undefined }
          : newData
      onChange?.(cleaned as EmbeddableBlockData)
      setEditorOpen(false)
    },
    [onChange],
  )

  if (!isEmbeddableBlockType(block.type)) {
    // Defensive: shouldn't happen — surface code only stores embeddable types.
    return null
  }

  const entry = EMBEDDABLE_BLOCK_CONFIG[block.type]
  // The registry keys are strictly typed, so this is safe at runtime; the
  // generic preview component accepts the matching Block shape.
  const Preview = entry.Preview as React.ComponentType<{ block: EmbeddableBlock }>

  return (
    <div
      className={cn(
        "group relative my-2 rounded-lg",
        editable && "ring-1 ring-transparent transition-shadow hover:ring-border",
      )}
      data-block-embed
      data-block-type={block.type}
    >
      <Preview block={block} />

      {editable && (
        <div className="pointer-events-none absolute right-2 top-2 flex items-center gap-1 opacity-0 transition-opacity group-hover:opacity-100">
          <Button
            type="button"
            size="icon"
            variant="secondary"
            aria-label="Editar bloco embedado"
            title="Editar"
            className="pointer-events-auto h-7 w-7 shadow-md"
            onClick={(e) => {
              e.preventDefault()
              e.stopPropagation()
              setEditorOpen(true)
            }}
          >
            <Pencil className="h-3.5 w-3.5" />
          </Button>
          <Button
            type="button"
            size="icon"
            variant="destructive"
            aria-label="Remover bloco embedado"
            title="Remover"
            className="pointer-events-auto h-7 w-7 shadow-md"
            onClick={(e) => {
              e.preventDefault()
              e.stopPropagation()
              onRemove?.()
            }}
          >
            <Trash2 className="h-3.5 w-3.5" />
          </Button>
        </div>
      )}

      {editable && editorOpen && (
        <BlockEditorModal
          open={editorOpen}
          onOpenChange={setEditorOpen}
          block={block}
          blockType={block.type}
          onSave={handleSave}
        />
      )}
    </div>
  )
}

"use client"

/**
 * BlockArrayEditor
 *
 * The only field implementation. Renders an ordered list of `Block`s with
 * insert seams (`InsertLine`) between them, drag-and-drop reordering, and
 * per-block toolbars (edit / delete / move up / move down).
 *
 * Insertion flow:
 *   1. User clicks a "+" insert line.
 *   2. `BlockTypePicker` opens, filtered by `FieldConfig.allowedBlockTypes`.
 *   3. On select, `BLOCK_REGISTRY[type].createEmpty()` produces a new `Block`.
 *   4. `onChange(nextBlocks)` is called \u2014 the parent (typically
 *      `useProjectStorage.setBlocks`) updates state and the debounced auto-save
 *      kicks in.
 *
 * Editing a block opens `BlockEditorModal`, which dispatches to the
 * type-specific editor in `extras/<area>/`.
 *
 * See `docs/ARCHITECTURE.md` (\"The Block Engine\").
 */

import { useState, useCallback, useRef, useEffect } from "react"
import { Plus, GripVertical, Trash2, ChevronUp, ChevronDown, Pencil } from "lucide-react"
import { insertBlock, moveBlock, removeBlock, updateBlock } from "@game-guild/block-list"
import { BlockTypePicker } from "./block-type-picker"
import { BlockEditorModal } from "./block-editor-modal"
import { BLOCK_REGISTRY, type BlockCellType } from "./block-component-registry"
import { DeleteConfirmDialog } from "@/components/block-content-editor/extras/dialogs/delete-confirm-dialog"
import type { Block, BlockArray } from "@/components/block-content-editor/lib/storage/editor/block-structure"
import { nextBlockId } from "@/components/block-content-editor/lib/storage/editor/block-structure"
import { getProjectTypeStructure, type ProjectType } from "@/components/block-content-editor/lib/storage/editor/project-types"
import { BlockContentRenderer } from "./block-array-viewer"
import { InlineRichTextEditor } from "../../extras/rich-text/inline-rich-text-editor"
import type { RichTextData } from "../../nodes/rich-text-node"
import { DragPreview, useBlockDragDrop } from "./block-drag-drop"
import type { QuizSubmissionMode } from "@game-guild/quiz-surface/player"

// ============================================================================
// Insert Line — the "seam" between blocks where new blocks can be added
// ============================================================================

function InsertLine({ onInsert }: { onInsert: () => void }) {
  return (
    <div className="group/insert relative flex items-center py-1.5">
      {/* Horizontal line */}
      <div className="flex-1 h-px bg-gray-200 dark:bg-gray-700 group-hover/insert:bg-blue-400 dark:group-hover/insert:bg-blue-500 transition-colors" />
      {/* Centered + button */}
      <button
        type="button"
        onClick={onInsert}
        className="relative z-10 flex items-center justify-center w-7 h-7 mx-2 rounded-full border-2 border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-900 text-gray-400 opacity-40 group-hover/insert:opacity-100 group-hover/insert:border-blue-400 group-hover/insert:text-blue-500 dark:group-hover/insert:border-blue-500 dark:group-hover/insert:text-blue-400 hover:scale-110 transition-all cursor-pointer"
        title="Insert block here"
      >
        <Plus className="h-4 w-4" />
      </button>
      <div className="flex-1 h-px bg-gray-200 dark:bg-gray-700 group-hover/insert:bg-blue-400 dark:group-hover/insert:bg-blue-500 transition-colors" />
    </div>
  )
}

// ============================================================================
// Block Card — a single block with header bar and content area
// ============================================================================

interface BlockCardProps {
  block: Block
  index: number
  total: number
  onMoveUp: () => void
  onMoveDown: () => void
  onRemove: () => void
  onEdit: () => void
  /** Called with new block data when the inline editor (rich-text) updates. */
  onUpdate?: (data: unknown) => void
  readOnly: boolean
  /**
   * When true, the block header hides the move/remove buttons
   * (single-block document mode). The edit button remains.
   */
  hideRemove?: boolean
  onDragStart?: () => void
  onDragEnd?: () => void
  isDragSource?: boolean
  /** Called during drag with the insertion index (before=index, after=index+1) */
  onDragHover?: (insertIndex: number) => void
  onDropHere?: () => void
  quizSubmissionMode?: QuizSubmissionMode
}

function BlockCard({ block, index, total, onMoveUp, onMoveDown, onRemove, onEdit, onUpdate, readOnly, hideRemove, onDragStart, onDragEnd, isDragSource, onDragHover, onDropHere, quizSubmissionMode }: BlockCardProps) {
  const config = BLOCK_REGISTRY[block.type]

  if (!config) return null

  const Icon = config.icon

  return (
    <div
      data-block-card
      onDragOver={onDragHover ? (e) => {
        e.preventDefault()
        e.dataTransfer.dropEffect = "move"
        const rect = e.currentTarget.getBoundingClientRect()
        const midY = rect.top + rect.height / 2
        onDragHover(e.clientY < midY ? index : index + 1)
      } : undefined}
      onDrop={onDropHere ? (e) => { e.preventDefault(); onDropHere() } : undefined}
      className={`group/card rounded-lg border bg-white dark:bg-gray-900 overflow-hidden transition-all duration-300 ${
        isDragSource
          ? "border-dashed border-blue-300 dark:border-blue-600 opacity-30"
          : "border-gray-200 dark:border-gray-700 shadow-sm hover:shadow-md"
      }`}
    >
      {/* Header bar */}
      <div className="flex items-center gap-2 px-3 py-2 bg-gray-50 dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
        {/* Grip handle */}
        {!readOnly && !hideRemove && (
          <div
            draggable
            onDragStart={(e) => {
              const card = e.currentTarget.closest("[data-block-card]") as HTMLElement
              if (card) e.dataTransfer.setDragImage(card, card.offsetWidth / 2, 20)
              e.dataTransfer.effectAllowed = "move"
              onDragStart?.()
            }}
            onDragEnd={() => onDragEnd?.()}
            className="shrink-0 cursor-grab active:cursor-grabbing"
          >
            <GripVertical className="h-4 w-4 text-gray-300 dark:text-gray-600" />
          </div>
        )}

        {/* Type icon + label */}
        <div className="flex items-center gap-1.5 min-w-0">
          <Icon className="h-4 w-4 text-gray-500 dark:text-gray-400 shrink-0" />
          <span className="text-xs font-medium text-gray-600 dark:text-gray-300 truncate">{config.label}</span>
        </div>

        {/* Index badge (hidden in single-block mode) */}
        {!hideRemove && (
          <span className="text-[11px] font-mono text-gray-400 dark:text-gray-500 bg-gray-100 dark:bg-gray-700 px-1.5 py-0.5 rounded shrink-0">
            #{index + 1}
          </span>
        )}

        {/* Spacer */}
        <div className="flex-1" />

        {/* Action buttons */}
        {!readOnly && (
          <div className="flex items-center gap-0.5">
            {/* Edit button — opens the focused modal editor */}
            <button
              type="button"
              onClick={onEdit}
              className="p-1 rounded text-blue-500 hover:text-blue-700 hover:bg-blue-50 dark:text-blue-400 dark:hover:text-blue-300 dark:hover:bg-blue-950/40 transition-colors"
              title="Open focused editor"
            >
              <Pencil className="h-3.5 w-3.5" />
            </button>
            {/* Move/delete — visible on hover; hidden in single-block mode */}
            {!hideRemove && (
              <div className="flex items-center gap-0.5 opacity-0 group-hover/card:opacity-100 transition-opacity">
                <button
                  type="button"
                  onClick={onMoveUp}
                  disabled={index === 0}
                  className="p-1 rounded text-gray-400 hover:text-gray-700 hover:bg-gray-200/60 dark:hover:text-gray-200 dark:hover:bg-gray-700/60 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                  title="Move up"
                >
                  <ChevronUp className="h-3.5 w-3.5" />
                </button>
                <button
                  type="button"
                  onClick={onMoveDown}
                  disabled={index === total - 1}
                  className="p-1 rounded text-gray-400 hover:text-gray-700 hover:bg-gray-200/60 dark:hover:text-gray-200 dark:hover:bg-gray-700/60 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                  title="Move down"
                >
                  <ChevronDown className="h-3.5 w-3.5" />
                </button>
                <button
                  type="button"
                  onClick={onRemove}
                  className="p-1 rounded text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:text-red-400 dark:hover:bg-red-950/40 transition-colors"
                  title="Remove block"
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </button>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Content area */}
      {block.type === "rich-text" ? (
        <InlineRichTextEditor
          data={block.data as RichTextData}
          readOnly={readOnly}
          onChange={(data) => onUpdate?.(data)}
        />
      ) : (
        <div className="p-4">
          <div className="prose prose-sm dark:prose-invert max-w-none">
            <BlockContentRenderer block={block} quizSubmissionMode={quizSubmissionMode} />
          </div>
        </div>
      )}
    </div>
  )
}

// ============================================================================
// Block Array Editor — main component
// ============================================================================

interface BlockArrayEditorProps {
  blocks: BlockArray
  onChange: (blocks: BlockArray) => void
  readOnly?: boolean
  allowedBlockTypes?: import("@/components/block-content-editor/lib/storage/editor/block-structure").BlockCellType[]
  /** High-level editor structure, used by direct BlockArrayEditor consumers. */
  projectType?: ProjectType
  /** Which tab to show by default in the picker */
  defaultPickerTab?: "blocks" | "templates"
  /** Hide the Block Types tab in the picker */
  hideBlockTypesTab?: boolean
  /**
   * Mode "single block document": hides the insertion lines, the
   * empty state, and the move/remove buttons of the single block.
   * The auto-create of the block is done in `EditorField`.
   */
  singleBlockMode?: boolean
  /** Called when drag state changes (for parent zoom) */
  onDragStateChange?: (dragging: boolean) => void
  /** How quiz blocks behave when the preview Submit button is clicked. */
  quizSubmissionMode?: QuizSubmissionMode
}

export function BlockArrayEditor({ blocks, onChange, readOnly = false, allowedBlockTypes, projectType, defaultPickerTab, hideBlockTypesTab, singleBlockMode, onDragStateChange, quizSubmissionMode }: BlockArrayEditorProps) {
  const [pickerOpen, setPickerOpen] = useState(false)
  const [insertIndex, setInsertIndex] = useState<number | null>(null)
  const projectTypeStructure = projectType ? getProjectTypeStructure(projectType) : {}
  const effectiveAllowedBlockTypes = allowedBlockTypes ?? projectTypeStructure.allowedBlockTypes
  const effectiveSingleBlockMode = singleBlockMode ?? projectTypeStructure.singleBlockMode
  const isQuizMode = projectType === "quiz"
  const hasRestrictedBlockTypes = !!effectiveAllowedBlockTypes && effectiveAllowedBlockTypes.length <= 1
  const effectiveHideBlockTypesTab = hideBlockTypesTab ?? (hasRestrictedBlockTypes || (isQuizMode && !effectiveAllowedBlockTypes?.length))
  const effectiveDefaultPickerTab = defaultPickerTab ?? (effectiveHideBlockTypesTab || isQuizMode ? "templates" : "blocks")

  // Editor modal state
  const [editorOpen, setEditorOpen] = useState(false)
  const [editingIndex, setEditingIndex] = useState<number | null>(null)
  const [editingBlock, setEditingBlock] = useState<Block | null>(null)
  const [editingBlockType, setEditingBlockType] = useState<BlockCellType | null>(null)

  // Delete confirmation state
  const [deleteIndex, setDeleteIndex] = useState<number | null>(null)
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false)

  // Scroll-to-block after move
  const scrollToIndexRef = useRef<number | null>(null)
  const blockRefsMap = useRef<Map<number, HTMLDivElement>>(new Map())

  // Drag-and-drop (extracted to useBlockDragDrop)
  const {
    containerRef,
    dragIndex,
    dropTargetIndex,
    handleContainerDragLeave,
    handleContainerDragOver,
    handleDragEnd,
    handleDragStart,
    isDragging,
    setDropTargetIndex,
  } = useBlockDragDrop({ blocks, onChange, onDragStateChange, scrollToIndexRef })



  const handleAddBlock = useCallback((factory: (id: string) => Block) => {
    const idx = insertIndex ?? blocks.length
    const block = factory(nextBlockId(blocks))
    onChange(insertBlock(blocks, idx, block))

    // Immediately open editor for the newly added block
    setEditingIndex(idx)
    setEditingBlock(block)
    setEditingBlockType(block.type)
    setEditorOpen(true)

    setInsertIndex(null)
  }, [blocks, onChange, insertIndex])

  const handleEditBlock = useCallback((index: number) => {
    const block = blocks[index]
    if (!block) return
    setEditingIndex(index)
    setEditingBlock(block)
    setEditingBlockType(block.type)
    setEditorOpen(true)
  }, [blocks])

  const handleInlineBlockUpdate = useCallback((index: number, data: unknown) => {
    const current = blocks[index]
    if (!current) return
    onChange(updateBlock<Block>(blocks, current.id, data as Block["data"]))
  }, [blocks, onChange])

  const handleEditorSave = useCallback((data: unknown) => {
    if (editingIndex === null || !editingBlock) return
    onChange(updateBlock<Block>(blocks, editingBlock.id, data as Block["data"]))
    setEditorOpen(false)
    setEditingIndex(null)
    setEditingBlock(null)
    setEditingBlockType(null)
  }, [editingIndex, editingBlock, blocks, onChange])

  const handleRemoveBlock = useCallback((index: number) => {
    setDeleteIndex(index)
    setDeleteDialogOpen(true)
  }, [])

  const handleConfirmDelete = useCallback(() => {
    if (deleteIndex === null) return
    const block = blocks[deleteIndex]
    if (block) onChange(removeBlock(blocks, block.id))
    setDeleteIndex(null)
    setDeleteDialogOpen(false)
  }, [deleteIndex, blocks, onChange])

  const handleMoveUp = useCallback((index: number) => {
    if (index <= 0) return
    onChange(moveBlock(blocks, index, index - 1))
    scrollToIndexRef.current = index - 1
  }, [blocks, onChange])

  const handleMoveDown = useCallback((index: number) => {
    if (index >= blocks.length - 1) return
    onChange(moveBlock(blocks, index, index + 1))
    scrollToIndexRef.current = index + 1
  }, [blocks, onChange])

  // Scroll to moved block after render
  useEffect(() => {
    if (scrollToIndexRef.current !== null) {
      const idx = scrollToIndexRef.current
      scrollToIndexRef.current = null
      // Delay scroll to let any scale transition finish (300ms in editor-field)
      setTimeout(() => {
        requestAnimationFrame(() => {
          const el = blockRefsMap.current.get(idx)
          el?.scrollIntoView({ behavior: "smooth", block: "center" })
        })
      }, 150)
    }
  })

  const openPickerAt = (index: number) => {
    setInsertIndex(index)
    setPickerOpen(true)
  }

  return (
    <div className="space-y-0">
      {/* Empty state (oculto em modo single-block; EditorField auto-cria o bloco) */}
      {blocks.length === 0 && !readOnly && !effectiveSingleBlockMode && (
        <div className="flex flex-col items-center justify-center py-20">
          <button
            type="button"
            onClick={() => openPickerAt(0)}
            className="flex items-center justify-center w-14 h-14 rounded-full border-2 border-dashed border-gray-300 dark:border-gray-600 text-gray-400 hover:border-blue-400 hover:text-blue-500 dark:hover:border-blue-500 dark:hover:text-blue-400 hover:scale-110 transition-all cursor-pointer mb-4"
          >
            <Plus className="h-7 w-7" />
          </button>
          <p className="text-sm font-medium text-gray-500 dark:text-gray-400">Add your first block</p>
          <p className="text-xs text-gray-400 dark:text-gray-500 mt-1">Choose from 20 different block types</p>
        </div>
      )}

      {/* Block list with insert lines / drag preview */}
      {blocks.length > 0 && (
        <div
          ref={containerRef}
          onDragOver={isDragging ? handleContainerDragOver : undefined}
          onDragLeave={isDragging ? handleContainerDragLeave : undefined}
        >
          {/* Insert line before first block (normal mode) */}
          {!readOnly && !isDragging && !effectiveSingleBlockMode && <InsertLine onInsert={() => openPickerAt(0)} />}

          {/* Drag preview before first block */}
          {isDragging && dropTargetIndex === 0 && dragIndex !== null && (
            <DragPreview onDragOver={handleContainerDragOver} onDrop={() => handleDragEnd()} />
          )}

          {blocks.map((block, index) => (
            <div key={block.id} ref={(el) => { if (el) blockRefsMap.current.set(index, el); else blockRefsMap.current.delete(index) }}>
              <BlockCard
                block={block}
                index={index}
                total={blocks.length}
                onMoveUp={() => handleMoveUp(index)}
                onMoveDown={() => handleMoveDown(index)}
                onRemove={() => handleRemoveBlock(index)}
                onEdit={() => handleEditBlock(index)}
                onUpdate={(data) => handleInlineBlockUpdate(index, data)}
                readOnly={readOnly}
                hideRemove={effectiveSingleBlockMode}
                onDragStart={() => handleDragStart(index)}
                onDragEnd={handleDragEnd}
                isDragSource={dragIndex === index}
                onDragHover={isDragging ? (targetIdx) => setDropTargetIndex(targetIdx) : undefined}
                onDropHere={isDragging ? () => handleDragEnd() : undefined}
                quizSubmissionMode={quizSubmissionMode}
              />

              {/* Drag preview after this block */}
              {isDragging && dropTargetIndex === index + 1 && dragIndex !== null && (
                <DragPreview onDragOver={handleContainerDragOver} onDrop={() => handleDragEnd()} />
              )}

              {/* Insert line after each block (normal mode; oculto em single-block) */}
              {!readOnly && !isDragging && !effectiveSingleBlockMode && <InsertLine onInsert={() => openPickerAt(index + 1)} />}
            </div>
          ))}
        </div>
      )}

      <BlockTypePicker
        open={pickerOpen}
        onOpenChange={setPickerOpen}
        onSelect={handleAddBlock}
        allowedBlockTypes={effectiveAllowedBlockTypes}
        defaultTab={effectiveDefaultPickerTab}
        hideBlockTypesTab={effectiveHideBlockTypesTab}
      />

      <BlockEditorModal
        open={editorOpen}
        onOpenChange={(v) => {
          setEditorOpen(v)
          if (!v) {
            setEditingIndex(null)
            setEditingBlock(null)
            setEditingBlockType(null)
          }
        }}
        block={editingBlock}
        blockType={editingBlockType}
        onSave={handleEditorSave}
      />

      <DeleteConfirmDialog
        open={deleteDialogOpen}
        onOpenChange={(v) => {
          setDeleteDialogOpen(v)
          if (!v) setDeleteIndex(null)
        }}
        title="Delete Block"
        itemName={deleteIndex !== null && blocks[deleteIndex] ? BLOCK_REGISTRY[blocks[deleteIndex]!.type]?.label ?? "Block" : "Block"}
        itemType="block"
        onConfirm={handleConfirmDelete}
      />
    </div>
  )
}

"use client"

import { useState, useCallback } from "react"
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@game-guild/ui/components/dialog"
import { Button } from "@game-guild/ui/components/button"
import { Input } from "@game-guild/ui/components/input"
import { Label } from "@game-guild/ui/components/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@game-guild/ui/components/select"
import type { Block } from "@/components/block-content-editor/lib/storage/editor/block-structure"
import type { BlockCellType } from "@/components/block-content-editor/lib/storage/editor/block-structure"
import { BLOCK_REGISTRY } from "./block-component-registry"
import {
  CodeStudioEditor,
  HTMLEditor,
  MarkdownEditor,
  ModeSelectionDialog,
  QuizSettingsDialog,
  RichTextEditor,
} from "@/components/block-content-editor/lazy-client-components"

// Pattern A standalone editors
import type { CodeStudioMode } from "@/components/block-content-editor/extras/code-studio/types"
import { LANGUAGE_CONFIGS } from "@/components/block-content-editor/extras/code-studio/types"
import type { BaseMediaData } from "@/components/block-content-editor/nodes/base/media-node-base"

// ============================================================================
// Simple form editors for Pattern B types (no standalone editor exists)
// ============================================================================

function YouTubeForm({ data, onChange }: { data: any; onChange: (d: any) => void }) {
  return (
    <div className="space-y-4">
      <div>
        <Label>YouTube Video URL or ID</Label>
        <Input
          placeholder="https://youtube.com/watch?v=... or video ID"
          value={data.videoId || ""}
          onChange={(e) => {
            const val = e.target.value
            // Extract videoId from URL if needed
            const match = val.match(/(?:v=|youtu\.be\/)([a-zA-Z0-9_-]{11})/)
            onChange({ ...data, videoId: match ? match[1] : val, isNew: false })
          }}
        />
      </div>
      <div>
        <Label>Title</Label>
        <Input placeholder="Video title" value={data.title || ""} onChange={(e) => onChange({ ...data, title: e.target.value })} />
      </div>
      <div>
        <Label>Caption</Label>
        <Input placeholder="Caption text" value={data.caption || ""} onChange={(e) => onChange({ ...data, caption: e.target.value })} />
      </div>
      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label>Size (%)</Label>
          <Input type="number" min={10} max={100} value={data.size ?? 100} onChange={(e) => onChange({ ...data, size: Number(e.target.value) })} />
        </div>
        <div>
          <Label>Start at (seconds)</Label>
          <Input type="number" min={0} value={data.startAt ?? 0} onChange={(e) => onChange({ ...data, startAt: Number(e.target.value) })} />
        </div>
      </div>
    </div>
  )
}

function SpotifyForm({ data, onChange }: { data: any; onChange: (d: any) => void }) {
  return (
    <div className="space-y-4">
      <div>
        <Label>Spotify URL or ID</Label>
        <Input
          placeholder="https://open.spotify.com/track/... or ID"
          value={data.spotifyId || ""}
          onChange={(e) => {
            const val = e.target.value
            const match = val.match(/(?:track|album|playlist|artist)\/([a-zA-Z0-9]+)/)
            if (match) {
              const typeMatch = val.match(/(track|album|playlist|artist)\//)
              onChange({ ...data, spotifyId: match[1], type: typeMatch?.[1] || data.type, isNew: false })
            } else {
              onChange({ ...data, spotifyId: val, isNew: false })
            }
          }}
        />
      </div>
      <div>
        <Label>Type</Label>
        <Select value={data.type || "track"} onValueChange={(v) => onChange({ ...data, type: v })}>
          <SelectTrigger><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="track">Track</SelectItem>
            <SelectItem value="album">Album</SelectItem>
            <SelectItem value="playlist">Playlist</SelectItem>
            <SelectItem value="artist">Artist</SelectItem>
          </SelectContent>
        </Select>
      </div>
      <div>
        <Label>Title</Label>
        <Input placeholder="Title" value={data.title || ""} onChange={(e) => onChange({ ...data, title: e.target.value })} />
      </div>
    </div>
  )
}

function HeaderForm({ data, onChange }: { data: any; onChange: (d: any) => void }) {
  return (
    <div className="space-y-4">
      <div>
        <Label>Header Text</Label>
        <Input placeholder="Section title" value={data.text || ""} onChange={(e) => onChange({ ...data, text: e.target.value })} autoFocus />
      </div>
      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label>Level</Label>
          <Select value={String(data.level ?? 1)} onValueChange={(v) => onChange({ ...data, level: Number(v) })}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>
              {[1, 2, 3, 4, 5, 6].map((l) => (
                <SelectItem key={l} value={String(l)}>H{l}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <div>
          <Label>Style</Label>
          <Select value={data.style || "default"} onValueChange={(v) => onChange({ ...data, style: v })}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="default">Default</SelectItem>
              <SelectItem value="underlined">Underlined</SelectItem>
              <SelectItem value="bordered">Bordered</SelectItem>
              <SelectItem value="gradient">Gradient</SelectItem>
              <SelectItem value="accent">Accent</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>
    </div>
  )
}

function SourceForm({ data, onChange }: { data: any; onChange: (d: any) => void }) {
  const sources: any[] = data.sources || []

  const addSource = () => {
    onChange({
      ...data,
      sources: [...sources, { id: crypto.randomUUID(), type: "website", author: "", title: "", url: "" }],
    })
  }

  const updateSource = (index: number, field: string, value: string) => {
    const newSources = sources.map((s, i) => (i === index ? { ...s, [field]: value } : s))
    onChange({ ...data, sources: newSources })
  }

  const removeSource = (index: number) => {
    onChange({ ...data, sources: sources.filter((_, i) => i !== index) })
  }

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label>Title</Label>
          <Input value={data.title || "References"} onChange={(e) => onChange({ ...data, title: e.target.value })} />
        </div>
        <div>
          <Label>Citation Style</Label>
          <Select value={data.style || "apa"} onValueChange={(v) => onChange({ ...data, style: v })}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>
              {["apa", "mla", "chicago", "harvard", "ieee", "abnt"].map((s) => (
                <SelectItem key={s} value={s}>{s.toUpperCase()}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>
      {sources.map((src, i) => (
        <div key={src.id || i} className="border rounded p-3 space-y-2">
          <div className="flex items-center justify-between">
            <span className="text-xs font-medium text-gray-500">Source #{i + 1}</span>
            <button type="button" onClick={() => removeSource(i)} className="text-xs text-red-500 hover:text-red-700">Remove</button>
          </div>
          <div className="grid grid-cols-2 gap-2">
            <Input placeholder="Author" value={src.author || ""} onChange={(e) => updateSource(i, "author", e.target.value)} />
            <Input placeholder="Title" value={src.title || ""} onChange={(e) => updateSource(i, "title", e.target.value)} />
            <Input placeholder="URL" value={src.url || ""} onChange={(e) => updateSource(i, "url", e.target.value)} />
            <Input placeholder="Year" value={src.year || ""} onChange={(e) => updateSource(i, "year", e.target.value)} />
          </div>
        </div>
      ))}
      <Button variant="outline" size="sm" onClick={addSource}>+ Add Source</Button>
    </div>
  )
}

// ============================================================================
// Main Block Editor Modal
// ============================================================================

interface BlockEditorModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  block: Block | null
  blockType: BlockCellType | null
  onSave: (data: any) => void
}

export function BlockEditorModal({ open, onOpenChange, block, blockType, onSave }: BlockEditorModalProps) {
  const [editData, setEditData] = useState<any>(null)
  const [showModeSelection, setShowModeSelection] = useState(false)

  // Initialize editData when block changes
  const currentData = editData ?? block?.data ?? null

  const handleSave = useCallback((data: any) => {
    onSave(data)
    setEditData(null)
    setShowModeSelection(false)
    onOpenChange(false)
  }, [onSave, onOpenChange])

  const handleCancel = useCallback(() => {
    setEditData(null)
    setShowModeSelection(false)
    onOpenChange(false)
  }, [onOpenChange])

  const handleModeSelect = useCallback((mode: CodeStudioMode) => {
    const defaultLanguage = (currentData?.language || "javascript") as keyof typeof LANGUAGE_CONFIGS
    const languageConfig = LANGUAGE_CONFIGS[defaultLanguage]
    const fileId = "1"
    setEditData({
      ...currentData,
      mode,
      files: [
        {
          id: fileId,
          name: `main${languageConfig.defaultExtension}`,
          content: languageConfig.defaultTemplate,
          language: defaultLanguage,
          isFile: 'f' as const,
          isVisible: true,
          path: `main${languageConfig.defaultExtension}`,
        },
      ],
      folders: [],
      openTabs: [fileId],
      activeFileId: fileId,
    })
    setShowModeSelection(false)
  }, [currentData])

  const handleDataChange = useCallback((newData: any) => {
    setEditData(newData)
  }, [])

  if (!blockType || !currentData) return null

  const config = BLOCK_REGISTRY[blockType as BlockCellType]
  if (!config) return null

  // ─── Pattern A: Standalone editors that manage their own UI ───

  // Quiz — has its own dialog
  if (blockType === "quiz") {
    return (
      <QuizSettingsDialog
        open={open}
        onOpenChange={(nextOpen) => {
          if (!nextOpen) handleCancel()
        }}
        value={currentData}
        onCommit={handleSave}
      />
    )
  }

  // Code Studio — mode selection for new blocks, then full-screen editor
  if (blockType === "code-studio") {
    if (!open) return null
    const isNewCodeStudio = !currentData.files || currentData.files.length === 0
    if (isNewCodeStudio && !showModeSelection && !editData) {
      // Auto-show mode selection for new Code Studio blocks
      return <ModeSelectionDialog onSelect={handleModeSelect} onCancel={handleCancel} />
    }
    return <CodeStudioEditor data={currentData} onSave={handleSave} onCancel={handleCancel} />
  }

  // Markdown — renders its own full-screen overlay
  if (blockType === "markdown") {
    if (!open) return null
    return <MarkdownEditor initialData={currentData} onSave={handleSave} onCancel={handleCancel} />
  }

  // HTML — renders its own full-screen overlay
  if (blockType === "html") {
    if (!open) return null
    return <HTMLEditor initialData={currentData} onSave={handleSave} onCancel={handleCancel} />
  }

  // Rich Text — renders its own full-screen overlay
  if (blockType === "rich-text") {
    if (!open) return null
    return <RichTextEditor initialData={currentData} onSave={handleSave} onCancel={handleCancel} />
  }

  // ─── Pattern B: Simple form editors ───

  const formMap: Record<string, React.ComponentType<{ data: any; onChange: (d: any) => void }>> = {
    "youtube": YouTubeForm,
    "spotify": SpotifyForm,
    "header": HeaderForm,
    "source": SourceForm,
  }
  const FormComponent = formMap[blockType]

  // Presentation and Project get a simple form too
  if (blockType === "presentation") {
    return (
      <Dialog open={open} onOpenChange={(v) => { if (!v) handleCancel() }}>
        <DialogContent className="max-w-2xl">
          <DialogHeader><DialogTitle>Presentation Settings</DialogTitle></DialogHeader>
          <div className="space-y-4">
            <div>
              <Label>Title</Label>
              <Input
                value={(editData ?? currentData).title || ""}
                onChange={(e) => handleDataChange({ ...currentData, ...editData, title: e.target.value })}
                autoFocus
              />
            </div>
            <p className="text-xs text-gray-500">Full presentation editing is available in the preview. Configure the title here.</p>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={handleCancel}>Cancel</Button>
            <Button onClick={() => handleSave(editData ?? currentData)}>Save</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    )
  }

  if (blockType === "project") {
    return (
      <Dialog open={open} onOpenChange={(v) => { if (!v) handleCancel() }}>
        <DialogContent className="max-w-2xl">
          <DialogHeader><DialogTitle>Project Reference</DialogTitle></DialogHeader>
          <div className="space-y-4">
            <div>
              <Label>Project ID</Label>
              <Input
                placeholder="Enter project ID to embed"
                value={(editData ?? currentData).projectId || ""}
                onChange={(e) => handleDataChange({ ...currentData, ...editData, projectId: e.target.value })}
                autoFocus
              />
            </div>
            <div>
              <Label>Project Name</Label>
              <Input
                placeholder="Display name"
                value={(editData ?? currentData).projectName || ""}
                onChange={(e) => handleDataChange({ ...currentData, ...editData, projectName: e.target.value })}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={handleCancel}>Cancel</Button>
            <Button onClick={() => handleSave(editData ?? currentData)}>Save</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    )
  }

  // Generic form-based editor for Pattern B types
  if (FormComponent) {
    const formData = editData ?? currentData
    return (
      <Dialog open={open} onOpenChange={(v) => { if (!v) handleCancel() }}>
        <DialogContent className="max-w-2xl max-h-[85vh] overflow-auto">
          <DialogHeader>
            <DialogTitle>{config.label} Editor</DialogTitle>
          </DialogHeader>
          <FormComponent data={formData} onChange={handleDataChange} />
          <DialogFooter>
            <Button variant="outline" onClick={handleCancel}>Cancel</Button>
            <Button onClick={() => handleSave(formData)}>Save</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    )
  }

  // Fallback
  return (
    <Dialog open={open} onOpenChange={(v) => { if (!v) handleCancel() }}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>{config.label}</DialogTitle>
        </DialogHeader>
        <p className="text-sm text-gray-500">Editor not available for this block type.</p>
        <DialogFooter>
          <Button variant="outline" onClick={handleCancel}>Close</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

