  // Renderizar conteúdo de cada painel
  const renderPanelContent = (panel: LeafPanel, displayConfig?: DisplayConfig) => {
    // Pick the Monaco-options group based on which display this leaf
    // belongs to. The base display (display-1) — and the `isPreview`
    // re-mount, which also targets the base display — uses the global
    // `preview` group because that's what students see. Every other
    // display is the IDE-style authoring surface and uses the global
    // `editor` group.
    const isBaseLeaf = isPreview || (displayConfig?.id !== undefined && displayConfig.id === baseDisplayId)
    const optionsForLeaf = isBaseLeaf ? previewOptions : editorOptions
    switch (panel.type) {
      case "explorer":
        return (
          <FileExplorer
            files={localData.files}
            folders={localData.folders || []}
            activeFileId={localData.activeFileId}
            onFileSelect={handleFileSelect}
            onCreateFile={handleCreateFile}
            onCreateFolder={handleCreateFolder}
            onDeleteFile={handleDeleteFile}
            onDeleteFolder={handleDeleteFolder}
            onRenameFile={handleRenameFile}
            onRenameFolder={handleRenameFolder}
            onToggleFolder={handleToggleFolder}
            onMoveFile={handleMoveFile}
            onMoveFolder={handleMoveFolder}
            onReorderFiles={handleReorderFiles}
            onAddFileFromAsset={handleAddFileFromAsset}
            onChangeFileType={handleChangeFileType}
            onToggleFileVisibility={handleToggleFileVisibility}
            onToggleFolderVisibility={handleToggleFolderVisibility}
            onToggleFileReadonly={handleToggleFileReadonly}
            onToggleFolderReadonly={handleToggleFolderReadonly}
            onToggleFocusFolder={handleToggleFocusFolder}
            onSetAllReadonly={handleSetAllReadonly}
            onSetAllHidden={handleSetAllHidden}
            onImportCollection={handleImportCollection}
            onSaveAsCollection={handleSaveAsCollection}
            isPreview={isPreview}
          />
        )
      
      case "full-editor": {
        // No preview, usar displayConfig passado; no editor, usar activeDisplay
        const displayToUse = isPreview && displayConfig ? displayConfig : getActiveDisplay()
        const isUniqueInstance = panel.editorInstance === "unique"
        const rawCurrentOpenTabs = isUniqueInstance 
          ? (displayToUse?.uniqueOpenTabs || [])
          : (localData.openTabs || [])

        // When the same display also has a focus-editor, files that live in
        // the focus folder are owned exclusively by it — strip them out of the
        // full-editor's tab strip so they don't show up in both places. This
        // is defensive: handleFileSelect / handleCreateFile already avoid
        // adding them, but legacy data may carry stale entries.
        const fullDisplayHasFocus = displayToUse ? displayHasPanelType(displayToUse, "focus-editor") : false
        const fullFocusFolder = fullDisplayHasFocus
          ? localData.folders?.find(f => f.isFocusFolder)
          : undefined
        const currentOpenTabs = fullFocusFolder
          ? rawCurrentOpenTabs.filter(tabId => {
              const f = localData.files.find(file => file.id === tabId)
              if (!f) return true
              const folderPath = f.path.substring(0, f.path.lastIndexOf('/'))
              return folderPath !== fullFocusFolder.path
            })
          : rawCurrentOpenTabs

        const rawCurrentActiveFileId = isUniqueInstance
          ? displayToUse?.uniqueActiveFileId
          : localData.activeFileId
        // If the global active file points at a focus-folder file (now owned
        // by the focus-editor), the full-editor should fall back to the first
        // tab it actually has so its editor surface keeps showing something
        // meaningful instead of going blank.
        const currentActiveFileId = rawCurrentActiveFileId && currentOpenTabs.includes(rawCurrentActiveFileId)
          ? rawCurrentActiveFileId
          : currentOpenTabs[0]
        
        // No preview, verificar se há explorer no Display Base para permitir fechar tabs
        const hasExplorer = displayConfig ? displayHasPanelType(displayConfig, 'explorer') : true
        const canCloseTabs = isPreview ? hasExplorer : true
        
        return (
          <div className="flex flex-col h-full relative">
            {/* Editor Instance Switch */}
            {panel.editorInstance && localData.layout?.editMode && (
              <EditorInstanceSwitch
                editorInstance={panel.editorInstance}
                onToggle={() => handleToggleEditorInstance(panel.id)}
              />
            )}
            
            <FileTabs
              files={localData.files}
              openTabs={currentOpenTabs}
              activeFileId={currentActiveFileId}
              editorInstance={panel.editorInstance}
              panelId={panel.id}
              onSelectTab={(fileId) => handleFileSelect(fileId, panel.id)}
              onCloseTab={canCloseTabs ? (fileId) => handleCloseTab(fileId, panel.id) : undefined}
              onReorderTabs={handleReorderTabs}
            />
            <div className="flex-1 min-h-0 relative">
              {currentOpenTabs.length === 0 ? (
                <EmptyEditorState />
              ) : (
                <>
                  {currentOpenTabs.map((fileId, index) => {
                    const file = localData.files.find(f => f.id === fileId)
                    if (!file) return null
                    const isActive = fileId === currentActiveFileId
                    
                    // Verificar se arquivo ou pasta pai está readonly
                    let isFileReadonly = file.readonly || false
                    if (!isFileReadonly && localData.folders) {
                      // Verificar se está dentro de uma pasta readonly
                      const fileFolder = localData.folders.find(folder => 
                        file.path.startsWith(folder.path + "/")
                      )
                      if (fileFolder?.readonly) {
                        isFileReadonly = true
                      }
                    }
                    
                    return (
                      <div
                        key={`${file.id}-${index}`}
                        className="absolute inset-0"
                        style={{ 
                          visibility: isActive ? 'visible' : 'hidden',
                          pointerEvents: isActive ? 'auto' : 'none',
                          zIndex: isActive ? 1 : 0
                        }}
                      >
                        <MonacoCodeEditor
                          fileId={file.id}
                          filePath={file.path}
                          instanceId={localData.id} // ID único da instância para isolamento completo
                          value={resolvedContents[file.id] || file.content}
                          onChange={(content) => handleCodeChange(content, file.id)}
                          language={file.language}
                          readonly={localData.readonly || isFileReadonly}
                          options={optionsForLeaf}
                        />
                      </div>
                    )
                  })}
                </>
              )}
            </div>
          </div>
        )
      
      }
      case "focus-editor": {
        // Focus editor: Language selector instead of file tabs.
        // Always rendered in "multiple" mode — it intentionally shares the
        // global active file with sibling editors so the toggle is hidden.
        const focusFolderForRender = localData.folders?.find(f => f.isFocusFolder)

        // No focus folder configured — the focus-editor has no scope to render.
        // Show a guidance message instead of an empty editor; the author can
        // mark any folder as the focus folder from the file explorer.
        if (!focusFolderForRender) {
          return (
            <div className="flex flex-col h-full items-center justify-center text-center px-6 py-8 gap-2 text-gray-600 dark:text-gray-300">
              <div className="text-sm font-medium">
                Nenhuma pasta marcada como foco
              </div>
              <div className="text-xs text-gray-500 dark:text-gray-400 max-w-xs">
                Marque uma pasta como “foco” no explorador de arquivos para
                que ela apareça aqui.
              </div>
            </div>
          )
        }

        const rawFocusActiveFileId = localData.activeFileId

        // Constrain the rendered file to the focus folder. When the global
        // active file lives outside (e.g. user opened it in a sibling Full
        // Editor), fall back to the first file inside the focus folder so the
        // focus-editor keeps showing the focus context instead of spilling.
        const focusFolderFiles = localData.files.filter(
          f => f.path.substring(0, f.path.lastIndexOf('/')) === focusFolderForRender.path,
        )
        const focusActiveFileId = rawFocusActiveFileId && focusFolderFiles.some(f => f.id === rawFocusActiveFileId)
          ? rawFocusActiveFileId
          : focusFolderFiles[0]?.id
        
        return (
          <div className="flex flex-col h-full relative">
            <LanguageSelector
              files={localData.files}
              folders={localData.folders || []}
              activeFileId={focusActiveFileId}
              onSelectLanguage={(fileId) => handleFileSelect(fileId, panel.id)}
              isPreview={isPreview}
              onResetFile={handleResetFile}
              onResetAllFiles={handleResetAllFiles}
            />
            
            <div className="flex-1 min-h-0 relative">
              {!focusActiveFileId ? (
                <EmptyEditorState />
              ) : (
                (() => {
                  const file = localData.files.find(f => f.id === focusActiveFileId)
                  if (!file) return <EmptyEditorState />
                  
                  // Check if file or parent folder is readonly
                  let isFileReadonly = file.readonly || false
                  if (!isFileReadonly && localData.folders) {
                    const fileFolder = localData.folders.find(folder => 
                      file.path.startsWith(folder.path + "/")
                    )
                    if (fileFolder?.readonly) {
                      isFileReadonly = true
                    }
                  }
                  
                  return (
                    <MonacoCodeEditor
                      fileId={file.id}
                      filePath={file.path}
                      instanceId={localData.id}
                      value={resolvedContents[file.id] || file.content}
                      onChange={(content) => handleCodeChange(content, file.id)}
                      language={file.language}
                      readonly={localData.readonly || isFileReadonly}
                      options={optionsForLeaf}
                    />
                  )
                })()
              )}
            </div>
          </div>
        )
      
      }
      case "output": {
        const mainFile = localData.files.find(f => f.isFile === 'm')
        const testFile = localData.files.find(f => f.isFile === 't')
        
        return (
          <ResultPanel
            ref={terminalRef}
            output={output}
            isExecuting={isExecuting}
            mode={localData.mode!}
            onExecuteFile={handleExecuteFile}
            onExecuteProject={handleExecuteProject}
            onExecuteTest={handleExecuteTest}
            onStop={handleStop}
            testCases={localData.testCases?.[localData.activeFileId || ""] || []}
            activeFile={activeFile}
            hasMainFile={!!mainFile}
            hasTestFile={!!testFile}
          />
        )
      }
    }
  }

  // Executa o arquivo atualmente selecionado
  const handleExecuteFile = async () => {
    if (!codeRunnerRef.current || !terminalRef.current) return
    
    // Buscar arquivo ativo: primeiro tentar painéis únicos, depois global
    const activeDisplay = getActiveDisplay()
    let fileToExecute = activeFile // Padrão: arquivo global ativo
    
    // Se houver painéis com instância única, usar o arquivo ativo deles
    if (activeDisplay) {
      const uniqueEditorPanel = findUniqueEditorLeaf(activeDisplay)
      if (uniqueEditorPanel && activeDisplay.uniqueActiveFileId) {
        fileToExecute = localData.files.find(f => f.id === activeDisplay.uniqueActiveFileId)
      }
    }
    
    if (!fileToExecute) return
    
    await executeFile(fileToExecute)
  }

  // Executa o arquivo marcado como 'm' (main)
  const handleExecuteProject = async () => {
    if (!codeRunnerRef.current || !terminalRef.current) return
    
    const mainFile = localData.files.find(f => f.isFile === 'm')
    if (!mainFile) return
    
    await executeFile(mainFile)
  }

  // Executa o arquivo marcado como 't' (test)
  const handleExecuteTest = async () => {
    if (!codeRunnerRef.current || !terminalRef.current) return
    
    const testFile = localData.files.find(f => f.isFile === 't')
    if (!testFile) return
    
    await executeFile(testFile)
  }

  // Função auxiliar para executar um arquivo
  const executeFile = async (fileToExecute: CodeFile) => {
    if (!codeRunnerRef.current || !terminalRef.current) return
    
    setIsExecuting(true)
    setOutput('') // Limpar output anterior - isso vai limpar o terminal via useEffect

    terminalRef.current.write('\x1b[33m⟳ Starting execution...\x1b[0m\r\n')

    try {
      // Criar mapa de arquivos para suportar imports - apenas arquivos da mesma linguagem
      // Resolver conteúdos de assets antes de executar
      const filesMap: Record<string, string> = {}
      for (const file of localData.files) {
        if (file.language === fileToExecute.language && 
            hasValidExtension(file.path, fileToExecute.language)) {
          // Resolver conteúdo se for referência a asset
          const content = resolvedContents[file.id] || file.content
          filesMap[`/${file.path}`] = content
        }
      }

      // Usar runWithFiles para suportar imports entre arquivos
      const result = await codeRunnerRef.current.runWithFiles(
        fileToExecute.language,
        `/${fileToExecute.path}`,
        filesMap
      )

      // Escrever resultado no terminal (já foi limpo automaticamente quando isExecuting=true)
      if (result.stdout) {
        terminalRef.current.write(result.stdout.replace(/\n/g, '\r\n'))
      }
      if (result.stderr) {
        if (result.stdout) terminalRef.current.write('\r\n')
        terminalRef.current.write('\x1b[31m' + result.stderr.replace(/\n/g, '\r\n') + '\x1b[0m')
      }
      if (result.exitCode !== 0) {
        terminalRef.current.write(`\r\n\x1b[33m[Process exited with code ${result.exitCode}]\x1b[0m`)
      }
      terminalRef.current.write(`\r\n\x1b[90m[Execution time: ${result.executionTime.toFixed(2)}ms]\x1b[0m\r\n`)
    } catch (error) {
      terminalRef.current.write(`\r\n\x1b[31mExecution error: ${error instanceof Error ? error.message : String(error)}\x1b[0m\r\n`)
    } finally {
      setIsExecuting(false)
    }
  }

  const handleExecute = handleExecuteFile // Manter retrocompatibilidade

  const handleStop = async () => {
    if (codeRunnerRef.current) {
      await codeRunnerRef.current.interrupt()
      setIsExecuting(false)
      setOutput(prev => prev + '\n\x1b[33m[Execution interrupted]\x1b[0m')
    }
  }

  const handleSaveClick = async () => {
    if (isSaving) return
    setIsSaving(true)
    const createdAssetUris: AssetUri[] = []
    const usageScope = { type: "code-studio", id: `${projectId ?? "local"}:${localData.id}` }
    const previousUris = findAssetUris(localData.files)
    try {
      const files = await Promise.all(localData.files.map(async (file): Promise<CodeFile> => {
        if (!file.content) {
          return { ...file, assetId: undefined, isModified: false }
        }
        if (isAssetUri(file.content) && !file.isModified) return file

        const content = isAssetUri(file.content)
          ? resolvedContents[file.id]
          : file.content
        if (content === undefined) {
          throw new Error(`Cannot save ${file.name}: its asset content is unavailable`)
        }
        if (!content) return { ...file, content: "", assetId: undefined, isModified: false }

        const record = await assetRepository.importBlob(
          new Blob([content], { type: inferMimeType(file.name) }),
          {
            name: file.name,
            source: { type: "generated", value: "code-studio" },
            scope: { type: "code-studio", id: `${projectId ?? "local"}:${localData.id}` },
          },
        )
        createdAssetUris.push(record.uri)
        return { ...file, content: record.uri, assetId: record.uri, isModified: false }
      }))

      const display1 = localData.layout?.displays.find(d => d.id === 'display-1')
      const isDisplay1Unique = display1 ? !!findUniqueEditorLeaf(display1) : false
      let syncedActiveFileId = localData.activeFileId

      if (isDisplay1Unique) {
        if (display1?.uniqueOpenTabs && display1.uniqueOpenTabs.length > 0) {
          syncedActiveFileId = display1.uniqueActiveFileId
        } else {
          syncedActiveFileId = undefined
        }
      } else {
        if (localData.openTabs && localData.openTabs.length > 0) {
          if (localData.activeFileId && localData.openTabs.includes(localData.activeFileId)) {
            syncedActiveFileId = localData.activeFileId
          } else {
            syncedActiveFileId = localData.openTabs[localData.openTabs.length - 1]
          }
        } else {
          syncedActiveFileId = undefined
        }
      }

      const dataToSave: CodeStudioData = {
        ...localData,
        files,
        layout: localData.layout ? {
          ...localData.layout,
          activeDisplayId: 'display-1'
        } : undefined,
        activeFileId: syncedActiveFileId
      }
      await assetRepository.reconcileUsage(
        usageScope,
        findAssetUris(files).map((uri, index) => ({
          uri,
          consumerId: `file:${index}`,
          role: "code-file",
        })),
      )
      await onSave?.(dataToSave)
      setLocalData(draft => {
        Object.assign(draft, dataToSave)
      })
    } catch (error) {
      await assetRepository.reconcileUsage(
        usageScope,
        previousUris.map((uri, index) => ({
          uri,
          consumerId: `file:${index}`,
          role: "code-file",
        })),
      ).catch(() => undefined)
      await Promise.all(
        createdAssetUris.map((uri) =>
          assetRepository.remove(uri, { force: true }).catch(() => undefined),
        ),
      )
      toast.error("Failed to save Code Studio", {
        description: error instanceof Error ? error.message : "Asset persistence failed",
      })
    } finally {
      setIsSaving(false)
    }
  }

  const handleCancelClick = () => {
    onCancel?.()
  }

  // Se for preview (renderizado no documento), não mostra o modal
  if (isPreview) {
    // Usar Display Base (display-1) como espelho do preview
    const baseDisplay = localData.layout?.displays.find(d => d.id === 'display-1')
    if (!baseDisplay) return null

    const leaves = getAllLeaves(baseDisplay.root)
    const isSingleLeaf = leaves.length === 1
    // Minimal embed: a single focus-editor or full-editor leaf renders without
    // any surrounding chrome (no rounded card, no border). Larger trees use
    // the full SplitterCanvas in read-only mode.
    if (isSingleLeaf && leaves[0]) {
      return (
        <div className="w-full h-[500px] min-h-0">
          {renderPanelContent(leaves[0], baseDisplay)}
        </div>
      )
    }

    return (
      <div className="w-full h-[500px] min-h-0">
        <SplitterCanvas
          root={baseDisplay.root}
          renderLeaf={(leaf) => renderPanelContent(leaf, baseDisplay)}
          editable={false}
          resizable
        />
      </div>
    )
  }

  // Modal de edição (fullscreen)
  const baseDisplayIdForSettings = localData.layout?.displays[0]?.id
  const activeDisplayIdForSettings = localData.layout?.activeDisplayId
  const isViewingBase = baseDisplayIdForSettings !== undefined && baseDisplayIdForSettings === activeDisplayIdForSettings

  return (
    <BlockEditorShell
      settings={settings}
      onClose={handleCancelClick}
      icon={<Code2 className="h-5 w-5 text-blue-600 dark:text-blue-400" />}
      title="Code Studio"
      defaultMonacoTab={isViewingBase ? 'preview' : 'editor'}
    >
        {/* Settings Bar */}
        <div className="flex items-center gap-3 p-4 border-b border-gray-200 dark:border-gray-800 bg-gray-50 dark:bg-gray-900 flex-wrap">
          <div className="flex items-center gap-2 shrink-0">
            <Label htmlFor="title" className="text-sm font-medium">
              Title:
            </Label>
            <Input
              id="title"
              value={localData.title || ""}
              onChange={(e) => handleDataChange({ title: e.target.value })}
              placeholder="Optional title"
              className="w-48"
            />
          </div>

          {/* Display Selector — read-only chips when NOT editing layout */}
          {!localData.layout?.editMode && localData.layout && (
            <div className="flex items-center gap-1 px-2 py-1 bg-gray-100 dark:bg-gray-800 rounded-md border border-gray-200 dark:border-gray-700">
              {localData.layout.displays.map((display) => (
                <button
                  key={display.id}
                  onClick={() => handleSelectDisplay(display.id)}
                  className={cn(
                    "px-2.5 py-1 rounded text-xs font-medium transition-all",
                    localData.layout?.activeDisplayId === display.id
                      ? "bg-blue-600 text-white shadow-sm"
                      : "bg-transparent text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-700"
                  )}
                  title={display.name}
                >
                  {display.name}
                </button>
              ))}
            </div>
          )}

          {/* Inline layout-edit toolbar (display tabs + templates + add-panel) */}
          {localData.layout?.editMode && localData.layout && (() => {
            const editToolbarActive = localData.layout.displays.find(
              d => d.id === localData.layout?.activeDisplayId,
            )
            const existingPanelTypes = editToolbarActive
              ? new Set<PanelType>(getAllLeaves(editToolbarActive.root).map(l => l.type))
              : undefined
            return (
              <DisplayManager
                displays={localData.layout.displays}
                activeDisplayId={localData.layout.activeDisplayId}
                activeDisplayScope={
                  localData.layout.displays[0]?.id === localData.layout.activeDisplayId ? "compact" : "expanded"
                }
                existingPanelTypes={existingPanelTypes}
                onSelectDisplay={handleSelectDisplay}
                onCreateDisplay={handleCreateDisplay}
                onDeleteDisplay={handleDeleteDisplay}
                onRenameDisplay={handleRenameDisplay}
                onApplyTemplate={handleApplyTemplate}
                onAddPanel={handleAddPanel}
              />
            )
          })()}

          {/* Layout Edit Button */}
          <div className="ml-auto flex items-center gap-2 shrink-0">
            <Button
              variant={localData.layout?.editMode ? "default" : "outline"}
              size="sm"
              onClick={handleToggleLayoutEdit}
              className="h-8"
              title={localData.layout?.editMode ? "Exit Layout Edit" : "Edit Layout"}
            >
              <Layout className="h-4 w-4 mr-2" />
              {localData.layout?.editMode ? "Done" : "Layout"}
            </Button>
          </div>
        </div>

        {/* Main Content - Splitter-pane Layout */}
        <div className="flex-1 min-h-0 p-3 bg-gray-100 dark:bg-gray-950 overflow-hidden flex flex-col">

          {/* Canvas Container
              Base (first) display → embed-sized preview frame centered, plus
              an author-only sidebar on the left when editing the layout.
              Secondary displays → fill the available canvas area. */}
          {(() => {
            const activeDisplay = getActiveDisplay()
            if (!activeDisplay) return null

            const isBase = localData.layout?.displays[0]?.id === activeDisplay.id
            const isEditing = localData.layout?.editMode || false
            // Author-only Files sidebar appears on Base whenever the layout
            // itself doesn't already expose a student-facing Explorer panel.
            // Visible in both edit and view modes so authors can manage files
            // without entering layout edit mode.
            const showBaseSidebar = isBase && !displayHasPanelType(activeDisplay, "explorer")

            const outerClass = isBase
              ? "flex-1 min-h-0 overflow-hidden flex items-stretch justify-center gap-10 p-4"
              : "flex-1 min-h-0 overflow-hidden flex items-stretch justify-stretch"
            const containerClass = isBase
              ? "h-[600px] w-full max-w-[720px] self-center"
              : "w-full h-full"

            const canvas = (
              <div
                className={cn(
                  containerClass,
                  isEditing && "ring-2 ring-blue-500/40 ring-dashed rounded-lg",
                )}
              >
                <SplitterCanvas
                  root={activeDisplay.root}
                  renderLeaf={(leaf) => renderPanelContent(leaf, activeDisplay)}
                  editable={isEditing}
                  resizable
                  onSplitResize={handleSplitResize}
                  onMovePanel={handleMovePanel}
                  onRemovePanel={handleRemovePanel}
                />
              </div>
            )

            if (showBaseSidebar) {
              return (
                <div className={outerClass}>
                  <BaseAuthorSidebar
                    fileExplorerProps={{
                      files: localData.files,
                      folders: localData.folders || [],
                      activeFileId: localData.activeFileId,
                      onFileSelect: handleFileSelect,
                      onCreateFile: handleCreateFile,
                      onCreateFolder: handleCreateFolder,
                      onDeleteFile: handleDeleteFile,
                      onDeleteFolder: handleDeleteFolder,
                      onRenameFile: handleRenameFile,
                      onRenameFolder: handleRenameFolder,
                      onToggleFolder: handleToggleFolder,
                      onMoveFile: handleMoveFile,
                      onMoveFolder: handleMoveFolder,
                      onReorderFiles: handleReorderFiles,
                      onAddFileFromAsset: handleAddFileFromAsset,
                      onChangeFileType: handleChangeFileType,
                      onToggleFileVisibility: handleToggleFileVisibility,
                      onToggleFolderVisibility: handleToggleFolderVisibility,
                      onToggleFileReadonly: handleToggleFileReadonly,
                      onToggleFolderReadonly: handleToggleFolderReadonly,
                      onToggleFocusFolder: handleToggleFocusFolder,
                      onSetAllReadonly: handleSetAllReadonly,
                      onSetAllHidden: handleSetAllHidden,
                      onImportCollection: handleImportCollection,
                      onSaveAsCollection: handleSaveAsCollection,
                    }}
                  />
                  {canvas}
                </div>
              )
            }

            return <div className={outerClass}>{canvas}</div>
          })()}
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-gray-200 dark:border-gray-800 bg-gray-50 dark:bg-gray-900">
          <div className="flex items-center gap-4">
            <div className="flex-1">
              <Label htmlFor="caption" className="text-sm font-medium">
                Caption:
              </Label>
              <Input
                id="caption"
                value={localData.caption || ""}
                onChange={(e) => handleDataChange({ caption: e.target.value })}
                placeholder="Optional caption"
                className="mt-1"
              />
            </div>

            <div className="flex gap-2">
              <Button 
                variant="outline" 
                onClick={handleCancelClick}
                disabled={localData.layout?.editMode || isSaving}
              >
                Cancel
              </Button>
              <Button 
                onClick={handleSaveClick} 
                className="flex items-center gap-2"
                disabled={localData.layout?.editMode || isSaving}
              >
                <Save className="h-4 w-4" />
                {isSaving ? "Saving..." : "Save"}
              </Button>
            </div>
          </div>
        </div>
    </BlockEditorShell>
  )
}

"use client"

import { useState } from "react"
import { Input } from "@game-guild/ui/components/input"
import { Plus, Trash2, Edit2 } from "lucide-react"
import type { DisplayConfig, PanelType } from "./types"
import { getTemplatesByScope, type LayoutTemplate as Template, type TemplateSilhouette } from "./templates/templates"
import { DeleteConfirmDialog } from "../dialogs/delete-confirm-dialog"
import { cn } from "@/lib/utils"

interface DisplayManagerProps {
  displays: DisplayConfig[]
  activeDisplayId: string
  /**
   * Scope of the currently active display, used to filter the template strip.
   * - "compact": Base display (embed-sized).
   * - "expanded": secondary displays (Mirror, Test, custom).
   */
  activeDisplayScope: "compact" | "expanded"
  /**
   * Panel types already present in the active display — used to disable the
   * add-panel button for types capped at one per layout (full-editor and
   * focus-editor).
   */
  existingPanelTypes?: Set<PanelType>
  onSelectDisplay: (displayId: string) => void
  onCreateDisplay: (name: string, templateId: string) => void
  onDeleteDisplay: (displayId: string) => void
  onRenameDisplay: (displayId: string, newName: string) => void
  onApplyTemplate: (displayId: string, templateId: string) => void
  onAddPanel: (type: PanelType) => void
}

/**
 * Inline editing toolbar shown on the Title row while the layout is in edit
 * mode. Contains, all visible at once (no popups):
 *   - Display tabs with rename / delete inline actions
 *   - "+ Display" button (creates from the first expanded template)
 *   - Template strip filtered by the active display's scope, applies on click
 *   - Add-panel quick buttons for the active display
 */
export function DisplayManager({
  displays,
  activeDisplayId,
  activeDisplayScope,
  existingPanelTypes,
  onSelectDisplay,
  onCreateDisplay,
  onDeleteDisplay,
  onRenameDisplay,
  onApplyTemplate,
  onAddPanel,
}: DisplayManagerProps) {
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editingName, setEditingName] = useState("")
  const [pendingDeleteId, setPendingDeleteId] = useState<string | null>(null)

  const pendingDeleteDisplay = pendingDeleteId
    ? displays.find(d => d.id === pendingDeleteId)
    : undefined

  const confirmDelete = () => {
    if (pendingDeleteId) {
      onDeleteDisplay(pendingDeleteId)
      setPendingDeleteId(null)
    }
  }

  const handleStartRename = (display: DisplayConfig) => {
    setEditingId(display.id)
    setEditingName(display.name)
  }

  const handleFinishRename = () => {
    if (editingId && editingName.trim()) {
      onRenameDisplay(editingId, editingName.trim())
    }
    setEditingId(null)
    setEditingName("")
  }

  const handleCreateDisplay = () => {
    const expanded = getTemplatesByScope("expanded")
    const fallback = expanded[0]
    if (!fallback) return
    onCreateDisplay(fallback.name, fallback.id)
  }

  const activeDisplay = displays.find(d => d.id === activeDisplayId)
  const templates = getTemplatesByScope(activeDisplayScope)

  return (
    <div className="flex items-center gap-2 flex-wrap">
      {/* Display tabs */}
      <div className="flex items-center gap-1 flex-wrap">
        {displays.map(display => (
          <div key={display.id} className="flex items-center gap-0.5">
            {editingId === display.id ? (
              <Input
                value={editingName}
                onChange={(e) => setEditingName(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") handleFinishRename()
                  if (e.key === "Escape") setEditingId(null)
                }}
                className="h-7 w-28 text-xs"
                autoFocus
                onBlur={handleFinishRename}
              />
            ) : (
              <button
                onClick={() => onSelectDisplay(display.id)}
                className={cn(
                  "px-2.5 py-1 rounded text-xs font-medium transition-colors",
                  activeDisplayId === display.id
                    ? "bg-blue-600 text-white shadow-sm"
                    : "bg-gray-200 dark:bg-gray-700 text-gray-600 dark:text-gray-400 hover:bg-gray-300 dark:hover:bg-gray-600",
                )}
                title={display.name}
              >
                {display.name}
              </button>
            )}

            {activeDisplayId === display.id && editingId !== display.id && (
              <>
                <button
                  onClick={() => handleStartRename(display)}
                  className="p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded text-gray-600 dark:text-gray-400"
                  title="Rename display"
                >
                  <Edit2 className="h-3 w-3" />
                </button>
                {displays.length > 1 && (
                  <button
                    onClick={() => setPendingDeleteId(display.id)}
                    className="p-1 hover:bg-red-100 dark:hover:bg-red-900/30 text-red-600 dark:text-red-400 rounded"
                    title="Delete display"
                  >
                    <Trash2 className="h-3 w-3" />
                  </button>
                )}
              </>
            )}
          </div>
        ))}

        <button
          onClick={handleCreateDisplay}
          className="px-1.5 py-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded text-gray-600 dark:text-gray-400 flex items-center gap-0.5"
          title="New display"
        >
          <Plus className="h-3.5 w-3.5" />
          <span className="text-xs">Display</span>
        </button>
      </div>

      <div className="h-6 w-px bg-gray-300 dark:bg-gray-700" />

      {/* Template strip — filtered by scope of active display */}
      <div className="flex items-center gap-1 flex-wrap">
        <span className="text-[11px] uppercase tracking-wide text-gray-500 dark:text-gray-400 mr-1">
          Templates
        </span>
        {templates.map(template => {
          const isActive = template.id === activeDisplay?.templateId
          return (
            <button
              key={template.id}
              onClick={() => onApplyTemplate(activeDisplayId, template.id)}
              className={cn(
                "flex items-center gap-1.5 p-1 rounded border transition-colors",
                isActive
                  ? "border-blue-500 bg-blue-50 dark:bg-blue-900/20"
                  : "border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 hover:border-blue-400 dark:hover:border-blue-500",
              )}
              title={`${template.name} — ${template.description}`}
            >
              <div className="h-5 w-8 bg-gray-100 dark:bg-gray-950 rounded overflow-hidden">
                <TemplatePreview schema={template.preview.schema} />
              </div>
              <span className="text-[11px] font-medium text-gray-700 dark:text-gray-300">
                {template.name}
              </span>
            </button>
          )
        })}
      </div>

      <div className="h-6 w-px bg-gray-300 dark:bg-gray-700" />

      {/* Add panel quick buttons */}
      <div className="flex items-center gap-1 flex-wrap">
        <span className="text-[11px] uppercase tracking-wide text-gray-500 dark:text-gray-400 mr-1">
          Add panel
        </span>
        <PanelAddButton label="Explorer" tone="green" onClick={() => onAddPanel("explorer")} />
        <PanelAddButton
          label="Full Editor"
          tone="blue"
          onClick={() => onAddPanel("full-editor")}
          disabled={existingPanelTypes?.has("full-editor")}
          disabledTitle="Only one Full Editor allowed per display"
        />
        <PanelAddButton
          label="Focus Editor"
          tone="cyan"
          onClick={() => onAddPanel("focus-editor")}
          disabled={existingPanelTypes?.has("focus-editor")}
          disabledTitle="Only one Focus Editor allowed per display"
        />
        <PanelAddButton label="Output" tone="purple" onClick={() => onAddPanel("output")} />
      </div>

      <DeleteConfirmDialog
        open={pendingDeleteId !== null}
        onOpenChange={(open) => {
          if (!open) setPendingDeleteId(null)
        }}
        title="Delete display"
        itemName={pendingDeleteDisplay?.name}
        itemType="display"
        onConfirm={confirmDelete}
      />
    </div>
  )
}

// ---------------------------------------------------------------------------
// Add-panel button

function PanelAddButton({
  label,
  tone,
  onClick,
  disabled = false,
  disabledTitle,
}: {
  label: string
  tone: "green" | "blue" | "cyan" | "purple"
  onClick: () => void
  disabled?: boolean
  disabledTitle?: string
}) {
  const toneClass = {
    green: "bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 hover:bg-green-200 dark:hover:bg-green-900/50",
    blue: "bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 hover:bg-blue-200 dark:hover:bg-blue-900/50",
    cyan: "bg-cyan-100 dark:bg-cyan-900/30 text-cyan-700 dark:text-cyan-400 hover:bg-cyan-200 dark:hover:bg-cyan-900/50",
    purple: "bg-purple-100 dark:bg-purple-900/30 text-purple-700 dark:text-purple-400 hover:bg-purple-200 dark:hover:bg-purple-900/50",
  }[tone]
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      className={cn(
        "px-2 py-1 text-[11px] rounded transition-colors",
        toneClass,
        disabled && "opacity-40 cursor-not-allowed hover:bg-transparent",
      )}
      title={disabled ? (disabledTitle ?? `${label} already present`) : `Add ${label} panel`}
    >
      + {label}
    </button>
  )
}

// ---------------------------------------------------------------------------
// Template silhouette preview

function TemplatePreview({ schema }: { schema: TemplateSilhouette }) {
  if (schema.kind === "leaf") {
    return <div className={cn("h-full w-full", leafToneFor(schema.type))} />
  }
  const isHorizontal = schema.direction === "horizontal"
  return (
    <div className={cn("h-full w-full flex gap-px", isHorizontal ? "flex-row" : "flex-col")}>
      {schema.children.map((child, idx) => (
        <div
          key={idx}
          style={isHorizontal ? { width: `${schema.sizes[idx]}%` } : { height: `${schema.sizes[idx]}%` }}
          className="overflow-hidden"
        >
          <TemplatePreview schema={child} />
        </div>
      ))}
    </div>
  )
}

function leafToneFor(type: PanelType): string {
  switch (type) {
    case "explorer":
      return "bg-green-300 dark:bg-green-700"
    case "full-editor":
      return "bg-blue-300 dark:bg-blue-700"
    case "focus-editor":
      return "bg-cyan-300 dark:bg-cyan-700"
    case "output":
      return "bg-purple-300 dark:bg-purple-700"
    default:
      return "bg-gray-300 dark:bg-gray-700"
  }
}

"use client"

import { useEffect, useState } from "react"
import { Folder, File, ChevronRight, ChevronDown, Package, Trash2, Download, Plus } from "lucide-react"
import type { CollectionMetadata, CollectionManifest, CollectionFolder, CollectionFile } from "./collection-types"
import { collectionRepository } from "./collection-repository"
import { Button } from "@game-guild/ui/components/button"
import { Input } from "@game-guild/ui/components/input"
import { ScrollArea } from "@game-guild/ui/components/scroll-area"
import { Badge } from "@game-guild/ui/components/badge"
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@game-guild/ui/components/dialog"

interface CollectionBrowserProps {
  onImportFiles: (files: Array<{ name: string; path: string; assetId: string; isFile?: 'f' | 'm' | 't'; readonly?: boolean; isVisible?: boolean }>, folderMetadata?: Map<string, { readonly?: boolean; isVisible?: boolean }>) => void
  onClose: () => void
}

export function CollectionBrowser({ onImportFiles, onClose }: CollectionBrowserProps) {
  const [collections, setCollections] = useState<CollectionMetadata[]>([])
  const [selectedCollection, setSelectedCollection] = useState<CollectionManifest | null>(null)
  const [expandedFolders, setExpandedFolders] = useState<Set<string>>(new Set())
  const [selectedFiles, setSelectedFiles] = useState<Set<string>>(new Set())
  const [searchQuery, setSearchQuery] = useState("")
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    loadCollections()
  }, [])

  const loadCollections = async () => {
    setIsLoading(true)
    try {
      const list = await collectionRepository.list()
      setCollections(list)
    } catch (error) {
      console.error("Failed to load collections:", error)
    } finally {
      setIsLoading(false)
    }
  }

  const handleSelectCollection = async (collectionId: string) => {
    try {
      const manifest = await collectionRepository.get(collectionId)
      setSelectedCollection(manifest)
      setSelectedFiles(new Set())
      setExpandedFolders(new Set())
    } catch (error) {
      console.error("Failed to load collection:", error)
    }
  }

  const handleDeleteCollection = async (collectionId: string) => {
    if (!confirm("Delete this collection? Referenced assets will not be affected.")) return

    try {
      await collectionRepository.remove(collectionId)
      await loadCollections()
      if (selectedCollection?.metadata.id === collectionId) {
        setSelectedCollection(null)
      }
    } catch (error) {
      console.error("Failed to delete collection:", error)
    }
  }

  const toggleFolder = (path: string) => {
    setExpandedFolders((prev) => {
      const next = new Set(prev)
      if (next.has(path)) {
        next.delete(path)
      } else {
        next.add(path)
      }
      return next
    })
  }

  const toggleFileSelection = (file: CollectionFile) => {
    const key = file.path
    setSelectedFiles((prev) => {
      const next = new Set(prev)
      if (next.has(key)) {
        next.delete(key)
      } else {
        next.add(key)
      }
      return next
    })
  }

  const handleImportAll = () => {
    if (!selectedCollection) return

    const allFiles: Array<{ name: string; path: string; assetId: string; isFile?: 'f' | 'm' | 't'; readonly?: boolean; isVisible?: boolean }> = []
    const folderMetadata = new Map<string, { readonly?: boolean; isVisible?: boolean }>()

    const collectFiles = (folder: CollectionFolder) => {
      // Store folder metadata
      console.log('[CollectionBrowser] Storing folder metadata:', folder.path, {
        readonly: folder.readonly,
        isVisible: folder.isVisible,
      })
      folderMetadata.set(folder.path, {
        readonly: folder.readonly,
        isVisible: folder.isVisible,
      })
      
      for (const file of folder.files) {
        allFiles.push({
          name: file.name,
          path: file.path,
          assetId: file.assetUri ?? "",
          isFile: file.isFile,
          readonly: file.readonly,
          isVisible: file.isVisible,
        })
      }
      if (folder.folders) {
        for (const subfolder of folder.folders) {
          collectFiles(subfolder)
        }
      }
    }

    // Collect from root
    for (const file of selectedCollection.structure.files) {
      allFiles.push({
        name: file.name,
        path: file.path,
        assetId: file.assetUri ?? "",
        isFile: file.isFile,
        readonly: file.readonly,
        isVisible: file.isVisible,
      })
    }
    for (const folder of selectedCollection.structure.folders) {
      collectFiles(folder)
    }

    console.log('[CollectionBrowser] Final folderMetadata:', Array.from(folderMetadata.entries()))
    onImportFiles(allFiles, folderMetadata)
    onClose()
  }

  const handleImportSelected = () => {
    if (!selectedCollection || selectedFiles.size === 0) return

    const filesToImport: Array<{ name: string; path: string; assetId: string; isFile?: 'f' | 'm' | 't'; readonly?: boolean; isVisible?: boolean }> = []
    const folderMetadata = new Map<string, { readonly?: boolean; isVisible?: boolean }>()

    const findFiles = (folder: CollectionFolder) => {
      // Store folder metadata
      console.log('[CollectionBrowser] Storing folder metadata (selected):', folder.path, {
        readonly: folder.readonly,
        isVisible: folder.isVisible,
      })
      folderMetadata.set(folder.path, {
        readonly: folder.readonly,
        isVisible: folder.isVisible,
      })
      
      for (const file of folder.files) {
        if (selectedFiles.has(file.path)) {
          filesToImport.push({
            name: file.name,
            path: file.path,
            assetId: file.assetUri ?? "",
            isFile: file.isFile,
            readonly: file.readonly,
            isVisible: file.isVisible,
          })
        }
      }
      if (folder.folders) {
        for (const subfolder of folder.folders) {
          findFiles(subfolder)
        }
      }
    }

    // Find in root
    for (const file of selectedCollection.structure.files) {
      if (selectedFiles.has(file.path)) {
        filesToImport.push({
          name: file.name,
          path: file.path,
          assetId: file.assetUri ?? "",
          isFile: file.isFile,
          readonly: file.readonly,
          isVisible: file.isVisible,
        })
      }
    }
    for (const folder of selectedCollection.structure.folders) {
      findFiles(folder)
    }

    console.log('[CollectionBrowser] Final folderMetadata (selected):', Array.from(folderMetadata.entries()))
    onImportFiles(filesToImport, folderMetadata)
    onClose()
  }

  const renderFolder = (folder: CollectionFolder, level: number = 0) => {
    const isExpanded = expandedFolders.has(folder.path)
    const paddingLeft = level * 16

    return (
      <div key={folder.path} className="select-none">
        <div
          className="flex items-center gap-2 py-1 px-2 hover:bg-accent/50 cursor-pointer rounded"
          style={{ paddingLeft }}
          onClick={() => toggleFolder(folder.path)}
        >
          {isExpanded ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
          <Folder className="h-4 w-4 text-blue-500" />
          <span className="text-sm">{folder.name}</span>
        </div>

        {isExpanded && (
          <div>
            {folder.files.map((file) => renderFile(file, level + 1))}
            {folder.folders?.map((subfolder) => renderFolder(subfolder, level + 1))}
          </div>
        )}
      </div>
    )
  }

  const renderFile = (file: CollectionFile, level: number = 0) => {
    const isSelected = selectedFiles.has(file.path)
    const paddingLeft = level * 16 + 24 // Extra padding to align with folder content

    return (
      <div
        key={file.path}
        className={`flex items-center gap-2 py-1 px-2 hover:bg-accent/50 cursor-pointer rounded ${
          isSelected ? "bg-accent" : ""
        }`}
        style={{ paddingLeft }}
        onClick={() => toggleFileSelection(file)}
      >
        <File className="h-4 w-4 text-gray-500" />
        <span className="text-sm flex-1">{file.name}</span>
        {file.size && <span className="text-xs text-muted-foreground">{formatBytes(file.size)}</span>}
      </div>
    )
  }

  const formatBytes = (bytes: number): string => {
    if (bytes < 1024) return `${bytes} B`
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
  }

  const filteredCollections = collections.filter(
    (c) =>
      searchQuery === "" ||
      c.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      c.description?.toLowerCase().includes(searchQuery.toLowerCase())
  )

  if (isLoading) {
    return (
      <Dialog open onOpenChange={onClose}>
        <DialogContent className="sm:max-w-[700px]">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Package className="h-5 w-5" />
              Import Collection
            </DialogTitle>
          </DialogHeader>
          <div className="flex items-center justify-center h-96">
            <div className="text-center">
              <Package className="h-12 w-12 mx-auto mb-2 text-muted-foreground" />
              <p className="text-sm text-muted-foreground">Loading collections...</p>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    )
  }

  if (!selectedCollection) {
    return (
      <Dialog open onOpenChange={onClose}>
        <DialogContent className="sm:max-w-[700px]">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Package className="h-5 w-5" />
              Import Collection
            </DialogTitle>
          </DialogHeader>
          <div className="flex flex-col h-96">
            <div className="p-4 border-b">
              <Input
                placeholder="Search collections..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="mb-2"
              />
            </div>

            <ScrollArea className="flex-1">
              <div className="p-4 space-y-2">
                {filteredCollections.length === 0 ? (
                  <div className="text-center py-8">
                    <Package className="h-12 w-12 mx-auto mb-2 text-muted-foreground" />
                    <p className="text-sm text-muted-foreground">No collections found</p>
                    <p className="text-xs text-muted-foreground mt-1">
                      Save a Code Studio project as a collection to import it later
                    </p>
                  </div>
                ) : (
                  filteredCollections.map((collection) => (
                    <div
                      key={collection.id}
                      className="border rounded-lg p-3 hover:bg-accent/50 cursor-pointer transition-colors"
                      onClick={() => handleSelectCollection(collection.id)}
                    >
                      <div className="flex items-start justify-between gap-2">
                        <div className="flex-1">
                          <div className="flex items-center gap-2">
                            <Package className="h-4 w-4" />
                            <h3 className="font-medium text-sm">{collection.name}</h3>
                          </div>
                          {collection.description && (
                            <p className="text-xs text-muted-foreground mt-1">{collection.description}</p>
                          )}
                          <div className="flex items-center gap-2 mt-2">
                            {collection.tags?.map((tag) => (
                              <Badge key={tag} variant="secondary" className="text-xs">
                                {tag}
                              </Badge>
                            ))}
                          </div>
                        </div>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={(e) => {
                            e.stopPropagation()
                            handleDeleteCollection(collection.id)
                          }}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </ScrollArea>
          </div>
        </DialogContent>
      </Dialog>
    )
  }

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[700px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Package className="h-5 w-5" />
            {selectedCollection.metadata.name}
          </DialogTitle>
        </DialogHeader>
        <div className="flex flex-col h-96">
          <div className="p-4 border-b">
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-2">
                <Button variant="ghost" size="sm" onClick={() => setSelectedCollection(null)}>
                  ←
                </Button>
                <h2 className="font-semibold">{selectedCollection.metadata.name}</h2>
              </div>
              <div className="flex gap-2">
                <Button variant="outline" size="sm" onClick={handleImportAll} disabled={selectedFiles.size > 0}>
                  <Download className="h-4 w-4 mr-1" />
                  Import All
                </Button>
                <Button size="sm" onClick={handleImportSelected} disabled={selectedFiles.size === 0}>
                  <Plus className="h-4 w-4 mr-1" />
                  Import Selected ({selectedFiles.size})
                </Button>
              </div>
            </div>
            {selectedCollection.metadata.description && (
              <p className="text-xs text-muted-foreground">{selectedCollection.metadata.description}</p>
            )}
          </div>

          <ScrollArea className="flex-1">
            <div className="p-4">
              {selectedCollection.structure.files.map((file) => renderFile(file))}
              {selectedCollection.structure.folders.map((folder) => renderFolder(folder))}
            </div>
          </ScrollArea>
        </div>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import { useState, useEffect } from "react"
import { 
  ChevronRight, 
  ChevronDown, 
  File, 
  Folder, 
  FolderOpen,
  Plus,
  FileText,
  Trash2,
  Edit3,
  MoreVertical,
  GripVertical,
  Lock,
  Unlock,
  Eye,
  EyeOff,
  Package,
  Download,
  Save
} from "lucide-react"
import { Button } from "@game-guild/ui/components/button"
import { Input } from "@game-guild/ui/components/input"
import { Switch } from "@game-guild/ui/components/switch"
import { DeleteConfirmDialog } from "../../dialogs/delete-confirm-dialog"
import { DuplicateNameDialog } from "../../dialogs/duplicate-name-dialog"
import { BaseConfirmDialog } from "../../dialogs/base-confirm-dialog"
import type { AssetRecord } from "@game-guild/assets"
import { getDefaultBrowserAssetRepository } from "@game-guild/assets/browser"
import { AssetPickerDialog, AssetsProvider } from "@game-guild/assets/react"
import { FileSourceMenu } from "../file-source-menu"
import { SaveCollectionDialog } from "./save-collection-dialog"
import { CollectionBrowser } from "./collection-browser"
import type { CodeFile, FileTreeFolder, FileTreeItem, FileType } from "../types"
import { cn } from "@/lib/utils"

const assetRepository = getDefaultBrowserAssetRepository()

interface FileExplorerProps {
  files: CodeFile[]
  folders: FileTreeFolder[]
  activeFileId?: string
  onFileSelect: (fileId: string) => void
  onCreateFile: (path: string, name: string) => void
  onCreateFolder: (path: string, name: string) => void
  onDeleteFile: (fileId: string) => void
  onDeleteFolder: (folderId: string) => void
  onRenameFile: (fileId: string, newName: string) => void
  onRenameFolder: (folderId: string, newName: string) => void
  onToggleFolder: (folderId: string) => void
  onMoveFile: (fileId: string, newPath: string) => void
  onMoveFolder: (folderId: string, newPath: string) => void
  onReorderFiles?: (newOrder: CodeFile[]) => void
  onAddFileFromAsset?: (path: string, assetId: string, fileName: string, content: string) => void
  onChangeFileType?: (fileId: string, fileType: FileType) => void
  onToggleFileVisibility?: (fileId: string) => void
  onToggleFolderVisibility?: (folderId: string) => void
  onToggleFileReadonly?: (fileId: string) => void
  onToggleFolderReadonly?: (folderId: string) => void
  onToggleFocusFolder?: (folderId: string) => void
  onSetAllReadonly?: (readonly: boolean) => void
  onSetAllHidden?: (hidden: boolean) => void
  onImportCollection?: (path: string, files: Array<{ name: string; path: string; assetId: string; isFile?: 'f' | 'm' | 't'; readonly?: boolean; isVisible?: boolean }>, folderMetadata?: Map<string, { readonly?: boolean; isVisible?: boolean }>) => void
  onSaveAsCollection?: (path: string, folderName?: string) => Promise<{ success: boolean; error?: string }>
  isPreview?: boolean
}

export function FileExplorer({
  files,
  folders,
  activeFileId,
  onFileSelect,
  onCreateFile,
  onCreateFolder,
  onDeleteFile,
  onDeleteFolder,
  onRenameFile,
  onRenameFolder,
  onToggleFolder,
  onMoveFile,
  onMoveFolder,
  onReorderFiles,
  onAddFileFromAsset,
  onChangeFileType,
  onToggleFileVisibility,
  onToggleFolderVisibility,
  onToggleFileReadonly,
  onToggleFolderReadonly,
  onToggleFocusFolder,
  onSetAllReadonly,
  onSetAllHidden,
  onImportCollection,
  onSaveAsCollection,
  isPreview = false,
}: FileExplorerProps) {
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editingName, setEditingName] = useState("")
  const [creatingType, setCreatingType] = useState<"file" | "folder" | null>(null)
  const [creatingPath, setCreatingPath] = useState("")
  const [newItemName, setNewItemName] = useState("")
  const [openMenuId, setOpenMenuId] = useState<string | null>(null)
  const [dragEnabled, setDragEnabled] = useState(false)
  const [draggedItem, setDraggedItem] = useState<{ id: string; type: "file" | "folder" } | null>(null)
  const [dropTarget, setDropTarget] = useState<string | null>(null)
  const [showAssetDialog, setShowAssetDialog] = useState(false)
  const [assetDialogPath, setAssetDialogPath] = useState("")
  const [deleteDialog, setDeleteDialog] = useState<{
    open: boolean
    type: "file" | "folder"
    id: string
    name: string
  } | null>(null)
  const [duplicateDialog, setDuplicateDialog] = useState<{
    open: boolean
    type: "file" | "folder"
    originalName: string
    path: string
    mode: "create" | "rename"
    itemId?: string
  } | null>(null)
  const [bulkActionDialog, setBulkActionDialog] = useState<{
    open: boolean
    type: "readonly" | "hidden"
    action: "set" | "unset"
  } | null>(null)
  const [showCollectionBrowser, setShowCollectionBrowser] = useState(false)
  const [collectionPath, setCollectionPath] = useState("")
  const [showSaveCollectionDialog, setShowSaveCollectionDialog] = useState(false)
  const [saveCollectionPath, setSaveCollectionPath] = useState("")
  const [saveCollectionFolderName, setSaveCollectionFolderName] = useState("")

  // Fechar menu ao clicar fora
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      const target = e.target as HTMLElement
      if (openMenuId && !target.closest('.context-menu-container')) {
        setOpenMenuId(null)
      }
    }
    
    if (openMenuId) {
      document.addEventListener('mousedown', handleClickOutside)
      return () => document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [openMenuId])

  // Organizar arquivos em árvore
  const buildTree = (): FileTreeItem[] => {
    const tree: FileTreeItem[] = [...folders]
    
    // Adicionar arquivos raiz (sem pasta)
    const rootFiles = files.filter(f => !f.path.includes("/"))
    tree.push(...rootFiles)
    
    return tree.sort((a, b) => {
      // Pastas primeiro
      if ('type' in a && a.type === 'folder' && !('type' in b)) return -1
      if ('type' in b && b.type === 'folder' && !('type' in a)) return 1
      return a.name.localeCompare(b.name)
    })
  }

  const handleStartCreating = (type: "file" | "folder", path: string = "") => {
    setCreatingType(type)
    setCreatingPath(path)
    setNewItemName("")
  }

  const handleOpenAssetDialog = (path: string = "") => {
    setAssetDialogPath(path)
    setShowAssetDialog(true)
  }

  const handleAssetSelected = async (results: AssetRecord | AssetRecord[]) => {
    if (!onAddFileFromAsset) return

    const assets = Array.isArray(results) ? results : [results]

    for (const asset of assets) {
      try {
        const content = await assetRepository.readText(asset.uri)
        onAddFileFromAsset(assetDialogPath, asset.uri, asset.name, content)
      } catch (error) {
        console.error(`Failed to read ${asset.name} as text:`, error)
      }
    }

    setShowAssetDialog(false)
  }

  const handleFinishCreating = () => {
    if (!newItemName.trim()) {
      setCreatingType(null)
      return
    }

    if (creatingType === "file") {
      // Verificar se já existe arquivo com mesmo nome no mesmo caminho
      const fullPath = creatingPath ? `${creatingPath}/${newItemName}` : newItemName
      const fileExists = files.some(f => f.path === fullPath)
      
      if (fileExists) {
        setDuplicateDialog({
          open: true,
          type: "file",
          originalName: newItemName,
          path: creatingPath,
          mode: "create",
        })
        return
      }
      
      onCreateFile(creatingPath, newItemName)
    } else if (creatingType === "folder") {
      // Verificar se já existe pasta com mesmo nome no mesmo caminho
      const fullPath = creatingPath ? `${creatingPath}/${newItemName}` : newItemName
      const folderExists = folders.some(f => f.path === fullPath)
      
      if (folderExists) {
        setDuplicateDialog({
          open: true,
          type: "folder",
          originalName: newItemName,
          path: creatingPath,
          mode: "create",
        })
        return
      }
      
      onCreateFolder(creatingPath, newItemName)
    }

    setCreatingType(null)
    setNewItemName("")
    setCreatingPath("")
  }

  const handleStartRename = (id: string, currentName: string) => {
    setEditingId(id)
    setEditingName(currentName)
  }

  const handleFinishRename = (id: string, isFolder: boolean) => {
    if (editingName.trim() && editingName !== (isFolder ? folders : files).find(f => f.id === id)?.name) {
      if (isFolder) {
        const folder = folders.find(f => f.id === id)
        if (!folder) return
        
        const pathParts = folder.path.split('/')
        pathParts[pathParts.length - 1] = editingName
        const newPath = pathParts.join('/')
        
        // Verificar se já existe pasta com mesmo nome no mesmo nível
        const folderExists = folders.some(f => f.path === newPath && f.id !== id)
        if (folderExists) {
          setDuplicateDialog({
            open: true,
            type: "folder",
            originalName: editingName,
            path: pathParts.slice(0, -1).join('/'),
            mode: "rename",
            itemId: id,
          })
          setEditingId(null)
          setEditingName("")
          return
        }
        
        onRenameFolder(id, editingName)
      } else {
        const file = files.find(f => f.id === id)
        if (!file) return
        
        const pathParts = file.path.split('/')
        pathParts[pathParts.length - 1] = editingName
        const newPath = pathParts.join('/')
        
        // Verificar se já existe arquivo com mesmo nome no mesmo nível
        const fileExists = files.some(f => f.path === newPath && f.id !== id)
        if (fileExists) {
          setDuplicateDialog({
            open: true,
            type: "file",
            originalName: editingName,
            path: pathParts.slice(0, -1).join('/'),
            mode: "rename",
            itemId: id,
          })
          setEditingId(null)
          setEditingName("")
          return
        }
        
        onRenameFile(id, editingName)
      }
    }
    setEditingId(null)
    setEditingName("")
  }

  const handleDuplicateConfirm = (newName: string) => {
    if (!duplicateDialog) return

    const { type, path, mode, itemId } = duplicateDialog

    if (mode === "create") {
      // Criar com o novo nome
      if (type === "file") {
        onCreateFile(path, newName)
      } else {
        onCreateFolder(path, newName)
      }
      setCreatingType(null)
      setNewItemName("")
      setCreatingPath("")
    } else if (mode === "rename" && itemId) {
      // Renomear com o novo nome
      if (type === "file") {
        onRenameFile(itemId, newName)
      } else {
        onRenameFolder(itemId, newName)
      }
    }

    setDuplicateDialog(null)
  }

  const handleDuplicateCancel = () => {
    setDuplicateDialog(null)
    // Se estava criando, não limpar os campos para permitir correção
    // Se estava renomeando, já foi limpo antes de abrir o dialog
  }

  const handleBulkReadonlyClick = () => {
    // Verificar se algum arquivo/pasta já está readonly
    const hasReadonly = files.some(f => f.readonly) || folders.some(f => f.readonly)
    setBulkActionDialog({
      open: true,
      type: "readonly",
      action: hasReadonly ? "unset" : "set"
    })
  }

  const handleBulkHiddenClick = () => {
    // Verificar se algum arquivo/pasta já está hidden
    const hasHidden = files.some(f => !f.isVisible) || folders.some(f => !f.isVisible)
    setBulkActionDialog({
      open: true,
      type: "hidden",
      action: hasHidden ? "unset" : "set"
    })
  }

  const handleConfirmBulkAction = () => {
    if (!bulkActionDialog) return

    if (bulkActionDialog.type === "readonly") {
      onSetAllReadonly?.(bulkActionDialog.action === "set")
    } else if (bulkActionDialog.type === "hidden") {
      onSetAllHidden?.(bulkActionDialog.action === "set")
    }

    setBulkActionDialog(null)
  }

  // Drag and Drop handlers
  const handleDragStart = (e: React.DragEvent, id: string, type: "file" | "folder") => {
    if (!dragEnabled) return
    setDraggedItem({ id, type })
    e.dataTransfer.effectAllowed = "move"
  }

  const handleDragOver = (e: React.DragEvent, targetId: string) => {
    if (!dragEnabled || !draggedItem) return
    e.preventDefault()
    e.dataTransfer.dropEffect = "move"
    setDropTarget(targetId)
  }

  const handleDragLeave = () => {
    setDropTarget(null)
  }

  const handleDrop = (e: React.DragEvent, targetId: string, targetType: "folder" | "root" | "file") => {
    e.preventDefault()
    e.stopPropagation()
    if (!dragEnabled || !draggedItem) return

    const { id: draggedId, type: draggedType } = draggedItem

    // Não permitir dropar em si mesmo
    if (draggedId === targetId) {
      setDraggedItem(null)
      setDropTarget(null)
      return
    }

    // Se dropou arquivo sobre arquivo
    if (targetType === "file" && draggedType === "file" && onReorderFiles) {
      const draggedFile = files.find(f => f.id === draggedId)
      const targetFile = files.find(f => f.id === targetId)
      
      if (draggedFile && targetFile) {
        // Extrair o path pai de cada arquivo
        const draggedPath = draggedFile.path.substring(0, draggedFile.path.lastIndexOf('/') + 1)
        const targetPath = targetFile.path.substring(0, targetFile.path.lastIndexOf('/') + 1)
        
        // Se estão no mesmo nível, reordenar
        if (draggedPath === targetPath) {
          // Filtrar arquivos do mesmo nível
          const sameLevelFiles = files.filter(f => {
            const filePath = f.path.substring(0, f.path.lastIndexOf('/') + 1)
            return filePath === draggedPath
          })
          
          // Criar nova ordem
          const newOrder = [...sameLevelFiles]
          const draggedIndex = newOrder.findIndex(f => f.id === draggedId)
          const targetIndex = newOrder.findIndex(f => f.id === targetId)
          
          if (draggedIndex !== -1 && targetIndex !== -1) {
            // Remover da posição atual
            const [movedFile] = newOrder.splice(draggedIndex, 1)

            // Verificar se o arquivo foi encontrado
            if (!movedFile) return

            // Ajustar o índice de destino se estamos movendo para baixo
            // Quando removemos o item antes, os índices mudam
            const adjustedTargetIndex = draggedIndex < targetIndex ? targetIndex - 1 : targetIndex

            // Inserir na nova posição
            newOrder.splice(adjustedTargetIndex, 0, movedFile)
            
            // Combinar com arquivos de outros níveis mantendo ordem
            const otherFiles = files.filter(f => {
              const filePath = f.path.substring(0, f.path.lastIndexOf('/') + 1)
              return filePath !== draggedPath
            })
            
            onReorderFiles([...otherFiles, ...newOrder])
          }
          
          setDraggedItem(null)
          setDropTarget(null)
          return
        } else {
          // Se estão em níveis diferentes, mover e depois reordenar na posição do alvo
          const targetFolderPath = targetPath.slice(0, -1)
          const targetFileId = targetFile.id
          
          // Primeiro move o arquivo
          onMoveFile(draggedId, targetFolderPath)
          
          // Depois reordena para garantir a posição correta
          setTimeout(() => {
            if (!onReorderFiles) return
            
            // Simular o novo path do arquivo movido
            const draggedFileName = draggedFile.path.substring(draggedFile.path.lastIndexOf('/') + 1)
            const newDraggedPath = targetFolderPath ? `${targetFolderPath}/${draggedFileName}` : draggedFileName
            
            // Pegar todos os arquivos do nível de destino (incluindo o que acabou de ser movido)
            const targetLevelFiles = files
              .map(f => {
                // Atualizar o path do arquivo movido
                if (f.id === draggedId) {
                  return { ...f, path: newDraggedPath }
                }
                return f
              })
              .filter(f => {
                const filePath = f.path.substring(0, f.path.lastIndexOf('/') + 1)
                return filePath === targetPath
              })
            
            // Criar nova ordem: remover o movido e inserir antes do alvo
            const newOrder = targetLevelFiles.filter(f => f.id !== draggedId)
            const targetIndex = newOrder.findIndex(f => f.id === targetFileId)
            const movedFile = targetLevelFiles.find(f => f.id === draggedId)
            
            if (targetIndex !== -1 && movedFile) {
              newOrder.splice(targetIndex, 0, movedFile)
              
              // Combinar com arquivos de outros níveis
              const otherFiles = files
                .filter(f => f.id !== draggedId) // Remover o arquivo movido da lista antiga
                .filter(f => {
                  const filePath = f.path.substring(0, f.path.lastIndexOf('/') + 1)
                  return filePath !== targetPath
                })
              
              onReorderFiles([...otherFiles, ...newOrder])
            }
          }, 100)
          
          setDraggedItem(null)
          setDropTarget(null)
          return
        }
      }
    }

    // Determinar o novo path
    let newPath = ""
    if (targetType === "folder") {
      const targetFolder = folders.find(f => f.id === targetId)
      if (targetFolder) {
        newPath = targetFolder.path
        
        // Verificar se está tentando mover uma pasta para dentro dela mesma ou de seus descendentes
        if (draggedType === "folder") {
          const draggedFolder = folders.find(f => f.id === draggedId)
          if (draggedFolder) {
            // Não permitir mover para si mesma ou para suas subpastas
            if (newPath === draggedFolder.path || newPath.startsWith(draggedFolder.path + "/")) {
              setDraggedItem(null)
              setDropTarget(null)
              return
            }
          }
        }
      }
    }

    // Executar a movimentação
    if (draggedType === "file") {
      onMoveFile(draggedId, newPath)
    } else {
      onMoveFolder(draggedId, newPath)
    }

    setDraggedItem(null)
    setDropTarget(null)
  }

  const handleDragEnd = () => {
    setDraggedItem(null)
    setDropTarget(null)
  }

  const handleDeleteClick = (id: string, name: string, type: "file" | "folder") => {
    setDeleteDialog({
      open: true,
      type,
      id,
      name,
    })
    setOpenMenuId(null)
  }

  const handleConfirmDelete = () => {
    if (!deleteDialog) return

    if (deleteDialog.type === "folder") {
      onDeleteFolder(deleteDialog.id)
    } else {
      onDeleteFile(deleteDialog.id)
    }

    setDeleteDialog(null)
  }

  const countFolderContents = (folderId: string): { files: number; folders: number } => {
    const folder = folders.find(f => f.id === folderId)
    if (!folder) return { files: 0, folders: 0 }

    const filesInFolder = files.filter(f => f.path.startsWith(folder.path + "/"))
    const foldersInFolder = folders.filter(f => f.path.startsWith(folder.path + "/") && f.id !== folderId)

    return {
      files: filesInFolder.length,
      folders: foldersInFolder.length,
    }
  }

  const getDeleteDescription = (): string => {
    if (!deleteDialog) return ""

    if (deleteDialog.type === "folder") {
      const contents = countFolderContents(deleteDialog.id)
      const totalItems = contents.files + contents.folders

      if (totalItems === 0) {
        return `Are you sure you want to delete "${deleteDialog.name}"? This folder will be permanently removed and cannot be recovered.`
      }

      const itemsText = []
      if (contents.files > 0) {
        itemsText.push(`${contents.files} file${contents.files > 1 ? "s" : ""}`)
      }
      if (contents.folders > 0) {
        itemsText.push(`${contents.folders} subfolder${contents.folders > 1 ? "s" : ""}`)
      }

      return `Are you sure you want to delete "${deleteDialog.name}"? This folder contains ${itemsText.join(" and ")} that will also be permanently removed and cannot be recovered.`
    }

    return `Are you sure you want to delete "${deleteDialog.name}"? This file will be permanently removed and cannot be recovered.`
  }

  const renderFileIcon = (fileName: string) => {
    const ext = fileName.split('.').pop()?.toLowerCase()
    return <File className="h-4 w-4 text-gray-500 dark:text-gray-400 shrink-0" />
  }

  const renderFolder = (folder: FileTreeFolder, level: number = 0) => {
    const isExpanded = folder.isExpanded
    const folderFiles = files.filter(f => f.path.startsWith(folder.path + "/") && 
                                          f.path.split("/").length === folder.path.split("/").length + 1)
    const subFolders = folders.filter(f => f.path.startsWith(folder.path + "/") &&
                                          f.path.split("/").length === folder.path.split("/").length + 1)
    
    const isDragging = draggedItem?.id === folder.id
    const isDropTarget = dropTarget === folder.id
    
    return (
      <div key={folder.id}>
        <div
          className={cn(
            "flex items-center gap-1 px-2 py-1 select-none hover:bg-gray-100 dark:hover:bg-gray-800 cursor-pointer group",
            "text-sm",
            isDragging && "opacity-50",
            isDropTarget && "bg-blue-50 dark:bg-blue-900/20 border-l-2 border-blue-500"
          )}
          style={{ paddingLeft: `${level * 12 + 8}px` }}
          draggable={dragEnabled && !editingId}
          onDragStart={(e) => handleDragStart(e, folder.id, "folder")}
          onDragOver={(e) => handleDragOver(e, folder.id)}
          onDragLeave={handleDragLeave}
          onDrop={(e) => handleDrop(e, folder.id, "folder")}
          onDragEnd={handleDragEnd}
        >
          {dragEnabled && !editingId && (
            <GripVertical className="h-3 w-3 text-gray-400 shrink-0 cursor-grab active:cursor-grabbing" />
          )}
          <button
            onClick={() => onToggleFolder(folder.id)}
            className="p-0 hover:bg-transparent"
          >
            {isExpanded ? (
              <ChevronDown className="h-4 w-4 text-gray-500" />
            ) : (
              <ChevronRight className="h-4 w-4 text-gray-500" />
            )}
          </button>
          
          {editingId === folder.id ? (
            <Input
              value={editingName}
              onChange={(e) => setEditingName(e.target.value)}
              onBlur={() => handleFinishRename(folder.id, true)}
              onKeyDown={(e) => {
                if (e.key === "Enter") handleFinishRename(folder.id, true)
                if (e.key === "Escape") setEditingId(null)
              }}
              className="h-6 text-xs flex-1"
              autoFocus
            />
          ) : (
            <>
              {isExpanded ? (
                <FolderOpen className="h-4 w-4 text-blue-500 shrink-0" />
              ) : (
                <Folder className="h-4 w-4 text-blue-500 shrink-0" />
              )}
              <span className="flex-1 truncate flex items-center gap-1" onClick={() => onToggleFolder(folder.id)}>
                {folder.name}
                {folder.isFocusFolder && (
                  <span className="text-[9px] px-1 py-0.5 rounded bg-cyan-100 dark:bg-cyan-900/30 text-cyan-600 dark:text-cyan-400" title="Focus folder for focus-editor">
                    🎯
                  </span>
                )}
                {folder.readonly && (
                  <span className="text-[9px] px-1 py-0.5 rounded bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400" title="Read-only">
                    🔒
                  </span>
                )}
                {!folder.isVisible && !isPreview && (
                  <span className="text-[9px] px-1 py-0.5 rounded bg-gray-200 dark:bg-gray-700 text-gray-500 dark:text-gray-400" title="Hidden in preview">
                    🙈
                  </span>
                )}
              </span>
              <div className="opacity-0 group-hover:opacity-100 flex items-center gap-1 relative context-menu-container">
                <Button
                  variant="ghost"
                  size="sm"
                  className="h-5 w-5 p-0"
                  onClick={(e) => {
                    e.stopPropagation()
                    setOpenMenuId(openMenuId === folder.id ? null : folder.id)
                  }}
                >
                  <MoreVertical className="h-3 w-3" />
                </Button>
                
                {openMenuId === folder.id && (
                  <div 
                    className="absolute right-0 top-6 z-50 w-48 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-md shadow-lg py-1"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <button
                      className="w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2"
                      onClick={(e) => {
                        e.stopPropagation()
                        handleStartCreating("file", folder.path)
                        setOpenMenuId(null)
                      }}
                    >
                      <FileText className="h-3 w-3" />
                      New File
                    </button>
                    {onAddFileFromAsset && (
                      <button
                        className="w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2"
                        onClick={(e) => {
                          e.stopPropagation()
                          handleOpenAssetDialog(folder.path)
                          setOpenMenuId(null)
                        }}
                      >
                        <FileText className="h-3 w-3" />
                        Add from Assets
                      </button>
                    )}
                    <button
                      className="w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2"
                      onClick={(e) => {
                        e.stopPropagation()
                        handleStartCreating("folder", folder.path)
                        setOpenMenuId(null)
                      }}
                    >
                      <Plus className="h-3 w-3" />
                      New Folder
                    </button>
                    <button
                      className="w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2"
                      onClick={(e) => {
                        e.stopPropagation()
                        handleStartRename(folder.id, folder.name)
                        setOpenMenuId(null)
                      }}
                    >
                      <Edit3 className="h-3 w-3" />
                      Rename
                    </button>
                    {onToggleFolderVisibility && (
                      <button
                        className="w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2"
                        onClick={(e) => {
                          e.stopPropagation()
                          onToggleFolderVisibility(folder.id)
                          setOpenMenuId(null)
                        }}
                      >
                        {folder.isVisible ? (
                          <>
                            <span className="h-3 w-3 flex items-center justify-center">👁️</span>
                            Hide in Preview
                          </>
                        ) : (
                          <>
                            <span className="h-3 w-3 flex items-center justify-center">🙈</span>
                            Show in Preview
                          </>
                        )}
                      </button>
                    )}
                    {onToggleFolderReadonly && (
                      <button
                        className="w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2"
                        onClick={(e) => {
                          e.stopPropagation()
                          onToggleFolderReadonly(folder.id)
                          setOpenMenuId(null)
                        }}
                      >
                        {folder.readonly ? (
                          <>
                            <span className="h-3 w-3 flex items-center justify-center">🔓</span>
                            Allow Editing
                          </>
                        ) : (
                          <>
                            <span className="h-3 w-3 flex items-center justify-center">🔒</span>
                            Set Read-Only
                          </>
                        )}
                      </button>
                    )}
                    {onToggleFocusFolder && (
                      <button
                        className="w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2"
                        onClick={(e) => {
                          e.stopPropagation()
                          onToggleFocusFolder(folder.id)
                          setOpenMenuId(null)
                        }}
                      >
                        {folder.isFocusFolder ? (
                          <>
                            <span className="h-3 w-3 flex items-center justify-center">🎯</span>
                            Unset Focus Folder
                          </>
                        ) : (
                          <>
                            <span className="h-3 w-3 flex items-center justify-center">🎯</span>
                            Set as Focus Folder
                          </>
                        )}
                      </button>
                    )}
                    <button
                      className="w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2 text-red-600 dark:text-red-400"
                      onClick={(e) => {
                        e.stopPropagation()
                        handleDeleteClick(folder.id, folder.name, "folder")
                      }}
                    >
                      <Trash2 className="h-3 w-3" />
                      Delete
                    </button>
                    <div className="border-t border-gray-200 dark:border-gray-700 my-1" />
                    {onImportCollection && (
                      <button
                        className="w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2"
                        onClick={(e) => {
                          e.stopPropagation()
                          setCollectionPath(folder.path)
                          setShowCollectionBrowser(true)
                          setOpenMenuId(null)
                        }}
                      >
                        <Download className="h-3 w-3" />
                        Import Collection
                      </button>
                    )}
                    {onSaveAsCollection && (
                      <button
                        className="w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2"
                        onClick={(e) => {
                          e.stopPropagation()
                          setSaveCollectionPath(folder.path)
                          setSaveCollectionFolderName(folder.name)
                          setShowSaveCollectionDialog(true)
                          setOpenMenuId(null)
                        }}
                      >
                        <Save className="h-3 w-3" />
                        Save as Collection
                      </button>
                    )}
                  </div>
                )}
              </div>
            </>
          )}
        </div>
        
        {isExpanded && (
          <div>
            {subFolders
              .filter(f => !isPreview || f.isVisible)
              .map(subFolder => renderFolder(subFolder, level + 1))}
            {folderFiles
              .filter(f => !isPreview || f.isVisible)
              .map((file, index) => renderFile(file, level + 1, index === folderFiles.length - 1))}
            
            {creatingType && creatingPath === folder.path && (
              <div 
                className="flex items-center gap-1 px-2 py-1"
                style={{ paddingLeft: `${(level + 1) * 12 + 8}px` }}
              >
                {creatingType === "folder" ? (
                  <Folder className="h-4 w-4 text-blue-500 shrink-0" />
                ) : (
                  <File className="h-4 w-4 text-gray-500 shrink-0" />
                )}
                <Input
                  value={newItemName}
                  onChange={(e) => setNewItemName(e.target.value)}
                  onBlur={handleFinishCreating}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") handleFinishCreating()
                    if (e.key === "Escape") setCreatingType(null)
                  }}
                  placeholder={creatingType === "folder" ? "Folder name" : "File name"}
                  className="h-6 text-xs flex-1"
                  autoFocus
                />
              </div>
            )}
          </div>
        )}
      </div>
    )
  }

  const renderFile = (file: CodeFile, level: number = 0, isLastInLevel: boolean = false) => {
    const isActive = file.id === activeFileId
    const isDragging = draggedItem?.id === file.id
    const isDropTarget = dropTarget === file.id
    const isDropTargetAfter = dropTarget === `${file.id}-after`
    
    return (
      <div key={file.id}>
        <div
          className={cn(
            "flex items-center gap-1 px-2 py-1 cursor-pointer group text-sm select-none",
            isActive 
              ? "bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300" 
              : "hover:bg-gray-100 dark:hover:bg-gray-800",
            isDragging && "opacity-50",
            isDropTarget && "border-t-2 border-blue-500"
          )}
          style={{ paddingLeft: `${level * 12 + 8}px` }}
          onClick={() => onFileSelect(file.id)}
          draggable={dragEnabled && !editingId}
          onDragStart={(e) => handleDragStart(e, file.id, "file")}
          onDragOver={(e) => handleDragOver(e, file.id)}
          onDragLeave={handleDragLeave}
          onDrop={(e) => handleDrop(e, file.id, "file")}
          onDragEnd={handleDragEnd}
        >
        {dragEnabled && !editingId && (
          <GripVertical className="h-3 w-3 text-gray-400 shrink-0 cursor-grab active:cursor-grabbing" />
        )}
        {editingId === file.id ? (
          <Input
            value={editingName}
            onChange={(e) => setEditingName(e.target.value)}
            onBlur={() => handleFinishRename(file.id, false)}
            onKeyDown={(e) => {
              if (e.key === "Enter") handleFinishRename(file.id, false)
              if (e.key === "Escape") setEditingId(null)
            }}
            className="h-6 text-xs flex-1"
            autoFocus
            onClick={(e) => e.stopPropagation()}
          />
        ) : (
          <>
            {renderFileIcon(file.name)}
            <span className="flex-1 truncate flex items-center gap-1">
              {file.name}
              {file.readonly && (
                <span className="text-[9px] px-1 py-0.5 rounded bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400" title="Read-only">
                  🔒
                </span>
              )}
              {!file.isVisible && !isPreview && (
                <span className="text-[9px] px-1 py-0.5 rounded bg-gray-200 dark:bg-gray-700 text-gray-500 dark:text-gray-400" title="Hidden in preview">
                  🙈
                </span>
              )}
              {file.isFile === 'm' && (
                <span className="text-[9px] px-1 py-0.5 rounded bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400" title="Main file (Project)">
                  M
                </span>
              )}
              {file.isFile === 't' && (
                <span className="text-[9px] px-1 py-0.5 rounded bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400" title="Test file">
                  T
                </span>
              )}
              {file.assetId && (
                <span className="text-[9px] px-1 py-0.5 rounded bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400" title="From assets">
                  A
                </span>
              )}
              {file.isModified && (
                <span className="text-[9px] px-1 py-0.5 rounded bg-yellow-100 dark:bg-yellow-900/30 text-yellow-600 dark:text-yellow-400" title="Modified">
                  ●
                </span>
              )}
            </span>
            <div className="opacity-0 group-hover:opacity-100 flex items-center gap-1 relative context-menu-container">
              <Button
                variant="ghost"
                size="sm"
                className="h-5 w-5 p-0"
                onClick={(e) => {
                  e.stopPropagation()
                  setOpenMenuId(openMenuId === file.id ? null : file.id)
                }}
              >
                <MoreVertical className="h-3 w-3" />
              </Button>
              
              {openMenuId === file.id && (
                <div 
                  className="absolute right-0 top-6 z-50 w-40 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-md shadow-lg py-1"
                  onClick={(e) => e.stopPropagation()}
                >
                  <button
                    className="w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2"
                    onClick={(e) => {
                      e.stopPropagation()
                      handleStartRename(file.id, file.name)
                      setOpenMenuId(null)
                    }}
                  >
                    <Edit3 className="h-3 w-3" />
                    Rename
                  </button>
                  {onChangeFileType && (
                    <>
                      <div className="border-t border-gray-200 dark:border-gray-700 my-1" />
                      <div className="px-3 py-1 text-xs text-gray-500 dark:text-gray-400 font-medium">Mark as:</div>
                      <button
                        className={cn(
                          "w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2",
                          file.isFile === 'f' && "bg-gray-100 dark:bg-gray-700"
                        )}
                        onClick={(e) => {
                          e.stopPropagation()
                          onChangeFileType(file.id, 'f')
                          setOpenMenuId(null)
                        }}
                      >
                        {file.isFile === 'f' && <span className="text-blue-600 dark:text-blue-400">✓</span>}
                        <span className={file.isFile !== 'f' ? 'ml-5' : ''}>Regular File</span>
                      </button>
                      <button
                        className={cn(
                          "w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2",
                          file.isFile === 'm' && "bg-gray-100 dark:bg-gray-700"
                        )}
                        onClick={(e) => {
                          e.stopPropagation()
                          onChangeFileType(file.id, 'm')
                          setOpenMenuId(null)
                        }}
                      >
                        {file.isFile === 'm' && <span className="text-green-600 dark:text-green-400">✓</span>}
                        <span className={file.isFile !== 'm' ? 'ml-5' : ''}>Main File (Project)</span>
                      </button>
                      <button
                        className={cn(
                          "w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2",
                          file.isFile === 't' && "bg-gray-100 dark:bg-gray-700"
                        )}
                        onClick={(e) => {
                          e.stopPropagation()
                          onChangeFileType(file.id, 't')
                          setOpenMenuId(null)
                        }}
                      >
                        {file.isFile === 't' && <span className="text-purple-600 dark:text-purple-400">✓</span>}
                        <span className={file.isFile !== 't' ? 'ml-5' : ''}>Test File</span>
                      </button>
                      <div className="border-t border-gray-200 dark:border-gray-700 my-1" />
                    </>
                  )}
                  {onToggleFileVisibility && (
                    <button
                      className="w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2"
                      onClick={(e) => {
                        e.stopPropagation()
                        onToggleFileVisibility(file.id)
                        setOpenMenuId(null)
                      }}
                    >
                      {file.isVisible ? (
                        <>
                          <span className="h-3 w-3 flex items-center justify-center">👁️</span>
                          Hide in Preview
                        </>
                      ) : (
                        <>
                          <span className="h-3 w-3 flex items-center justify-center">🙈</span>
                          Show in Preview
                        </>
                      )}
                    </button>
                  )}
                  {onToggleFileReadonly && (
                    <button
                      className="w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2"
                      onClick={(e) => {
                        e.stopPropagation()
                        onToggleFileReadonly(file.id)
                        setOpenMenuId(null)
                      }}
                    >
                      {file.readonly ? (
                        <>
                          <span className="h-3 w-3 flex items-center justify-center">🔓</span>
                          Allow Editing
                        </>
                      ) : (
                        <>
                          <span className="h-3 w-3 flex items-center justify-center">🔒</span>
                          Set Read-Only
                        </>
                      )}
                    </button>
                  )}
                  <button
                    className="w-full px-3 py-1.5 text-left text-xs hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2 text-red-600 dark:text-red-400"
                    onClick={(e) => {
                      e.stopPropagation()
                      handleDeleteClick(file.id, file.name, "file")
                    }}
                  >
                    <Trash2 className="h-3 w-3" />
                    Delete
                  </button>
                </div>
              )}
            </div>
          </>
        )}
        </div>
        
        {/* Drop zone after last file */}
        {isLastInLevel && draggedItem?.type === "file" && (
          <div
            className={cn(
              "h-4 transition-all",
              isDropTargetAfter && "h-8 bg-blue-50 dark:bg-blue-900/20 border-2 border-dashed border-blue-500"
            )}
            style={{ paddingLeft: `${level * 12 + 8}px` }}
            onDragOver={(e) => {
              if (!dragEnabled || !draggedItem) return
              e.preventDefault()
              e.stopPropagation()
              e.dataTransfer.dropEffect = "move"
              setDropTarget(`${file.id}-after`)
            }}
            onDragLeave={() => setDropTarget(null)}
            onDrop={(e) => {
              e.preventDefault()
              e.stopPropagation()
              if (!dragEnabled || !draggedItem || draggedItem.type !== "file") return
              
              // Get the files in the same level as target
              const filePath = file.path.substring(0, file.path.lastIndexOf('/') + 1)
              const sameLevelFiles = files.filter(f => {
                const fPath = f.path.substring(0, f.path.lastIndexOf('/') + 1)
                return fPath === filePath
              })
              
              const draggedFile = files.find(f => f.id === draggedItem.id)
              if (!draggedFile) return
              
              // Check if same level
              const draggedPath = draggedFile.path.substring(0, draggedFile.path.lastIndexOf('/') + 1)
              
              if (draggedPath === filePath) {
                // Same level - reorder
                const newOrder = [...sameLevelFiles]
                const draggedIndex = newOrder.findIndex(f => f.id === draggedItem.id)
                const targetIndex = newOrder.findIndex(f => f.id === file.id)
                
                if (draggedIndex !== -1 && targetIndex !== -1) {
                  const [movedFile] = newOrder.splice(draggedIndex, 1)
                  if (!movedFile) return
                  
                  // Insert after target (no adjustment needed since we're going after)
                  newOrder.splice(targetIndex + (draggedIndex < targetIndex ? 0 : 1), 0, movedFile)
                  
                  const otherFiles = files.filter(f => {
                    const fPath = f.path.substring(0, f.path.lastIndexOf('/') + 1)
                    return fPath !== filePath
                  })
                  
                  if (onReorderFiles) {
                    onReorderFiles([...otherFiles, ...newOrder])
                  }
                }
              } else {
                // Different level - move to target folder and reorder after target file
                const targetFolderPath = filePath.slice(0, -1)
                const targetFileId = file.id
                const draggedFileId = draggedItem.id
                
                // Primeiro move o arquivo
                onMoveFile(draggedFileId, targetFolderPath)
                
                // Depois reordena para garantir a posição após o arquivo alvo
                setTimeout(() => {
                  if (!onReorderFiles) return
                  
                  // Simular o novo path do arquivo movido
                  const draggedFileName = draggedFile.path.substring(draggedFile.path.lastIndexOf('/') + 1)
                  const newDraggedPath = targetFolderPath ? `${targetFolderPath}/${draggedFileName}` : draggedFileName
                  
                  // Pegar todos os arquivos do nível de destino (incluindo o que acabou de ser movido)
                  const targetLevelFiles = files
                    .map(f => {
                      // Atualizar o path do arquivo movido
                      if (f.id === draggedFileId) {
                        return { ...f, path: newDraggedPath }
                      }
                      return f
                    })
                    .filter(f => {
                      const fPath = f.path.substring(0, f.path.lastIndexOf('/') + 1)
                      return fPath === filePath
                    })
                  
                  // Criar nova ordem: remover o movido e inserir após o alvo
                  const newOrder = targetLevelFiles.filter(f => f.id !== draggedFileId)
                  const targetIndex = newOrder.findIndex(f => f.id === targetFileId)
                  const movedFile = targetLevelFiles.find(f => f.id === draggedFileId)
                  
                  if (targetIndex !== -1 && movedFile) {
                    // Inserir após o arquivo alvo
                    newOrder.splice(targetIndex + 1, 0, movedFile)
                    
                    // Combinar com arquivos de outros níveis
                    const otherFiles = files
                      .filter(f => f.id !== draggedFileId) // Remover o arquivo movido da lista antiga
                      .filter(f => {
                        const fPath = f.path.substring(0, f.path.lastIndexOf('/') + 1)
                        return fPath !== filePath
                      })
                    
                    onReorderFiles([...otherFiles, ...newOrder])
                  }
                }, 100)
              }
              
              setDraggedItem(null)
              setDropTarget(null)
            }}
          />
        )}
      </div>
    )
  }

  const tree = buildTree()
  const rootFiles = files.filter(f => !f.path.includes("/"))

  return (
    <div 
      className="h-full flex flex-col bg-gray-50 dark:bg-gray-950 border-r border-gray-200 dark:border-gray-800"
      onDragOver={(e) => {
        if (dragEnabled && draggedItem) {
          e.preventDefault()
        }
      }}
      onDrop={(e) => handleDrop(e, "", "root")}
    >
      {/* Header */}
      <div className="flex items-center justify-between p-2 border-b border-gray-200 dark:border-gray-800 bg-gray-100 dark:bg-gray-900">
        <div className="flex items-center gap-2">
          <span className="text-xs font-medium text-gray-600 dark:text-gray-400">FILES</span>
          <div className="flex items-center gap-1.5">
            <Switch
              checked={dragEnabled}
              onCheckedChange={setDragEnabled}
              className="scale-75"
            />
            <span className="text-[10px] text-gray-500 dark:text-gray-500">
              {dragEnabled ? "Drag enabled" : "Drag disabled"}
            </span>
          </div>
        </div>
        <div className="flex items-center gap-1">
          {onSetAllReadonly && (
            <Button
              variant="ghost"
              size="sm"
              className="h-6 w-6 p-0"
              onClick={handleBulkReadonlyClick}
              title="Toggle Read-Only for All"
            >
              {files.some(f => f.readonly) || folders.some(f => f.readonly) ? (
                <Unlock className="h-3 w-3" />
              ) : (
                <Lock className="h-3 w-3" />
              )}
            </Button>
          )}
          {onSetAllHidden && (
            <Button
              variant="ghost"
              size="sm"
              className="h-6 w-6 p-0"
              onClick={handleBulkHiddenClick}
              title="Toggle Visibility for All"
            >
              {files.some(f => !f.isVisible) || folders.some(f => !f.isVisible) ? (
                <Eye className="h-3 w-3" />
              ) : (
                <EyeOff className="h-3 w-3" />
              )}
            </Button>
          )}
          {onAddFileFromAsset ? (
            <FileSourceMenu
              onCreateNew={() => handleStartCreating("file", "")}
              onAddFromAssets={() => handleOpenAssetDialog("")}
              trigger={
                <Button variant="ghost" size="sm" className="h-6 w-6 p-0" title="Add File">
                  <FileText className="h-3 w-3" />
                </Button>
              }
            />
          ) : (
            <Button
              variant="ghost"
              size="sm"
              className="h-6 w-6 p-0"
              onClick={() => handleStartCreating("file", "")}
              title="New File"
            >
              <FileText className="h-3 w-3" />
            </Button>
          )}
          <Button
            variant="ghost"
            size="sm"
            className="h-6 w-6 p-0"
            onClick={() => handleStartCreating("folder", "")}
            title="New Folder"
          >
            <Plus className="h-3 w-3" />
          </Button>
          {onImportCollection && (
            <Button
              variant="ghost"
              size="sm"
              className="h-6 w-6 p-0"
              onClick={() => {
                setCollectionPath("")
                setShowCollectionBrowser(true)
              }}
              title="Import Collection"
            >
              <Download className="h-3 w-3" />
            </Button>
          )}
          {onSaveAsCollection && (
            <Button
              variant="ghost"
              size="sm"
              className="h-6 w-6 p-0"
              onClick={() => {
                setSaveCollectionPath("")
                setSaveCollectionFolderName("")
                setShowSaveCollectionDialog(true)
              }}
              title="Save as Collection"
            >
              <Package className="h-3 w-3" />
            </Button>
          )}
        </div>
      </div>

      {/* File Tree */}
      <div className="flex-1 overflow-auto">
        {folders
          .filter(f => !f.path.includes("/"))
          .filter(f => !isPreview || f.isVisible)
          .map(folder => renderFolder(folder))}
        {rootFiles
          .filter(f => !isPreview || f.isVisible)
          .map((file, index) => renderFile(file, 0, index === rootFiles.length - 1))}
        
        {creatingType && creatingPath === "" && (
          <div className="flex items-center gap-1 px-2 py-1">
            {creatingType === "folder" ? (
              <Folder className="h-4 w-4 text-blue-500 shrink-0" />
            ) : (
              <File className="h-4 w-4 text-gray-500 shrink-0" />
            )}
            <Input
              value={newItemName}
              onChange={(e) => setNewItemName(e.target.value)}
              onBlur={handleFinishCreating}
              onKeyDown={(e) => {
                if (e.key === "Enter") handleFinishCreating()
                if (e.key === "Escape") setCreatingType(null)
              }}
              placeholder={creatingType === "folder" ? "Folder name" : "File name"}
              className="h-6 text-xs flex-1"
              autoFocus
            />
          </div>
        )}
      </div>

      {/* Delete Confirmation Dialog */}
      {deleteDialog && (
        <DeleteConfirmDialog
          open={deleteDialog.open}
          onOpenChange={(open) => !open && setDeleteDialog(null)}
          title={deleteDialog.type === "folder" ? "Delete Folder" : "Delete File"}
          itemName={deleteDialog.name}
          itemType={deleteDialog.type}
          onConfirm={handleConfirmDelete}
          description={getDeleteDescription()}
        />
      )}

      {/* Duplicate Name Dialog */}
      {duplicateDialog && (
        <DuplicateNameDialog
          open={duplicateDialog.open}
          onOpenChange={(open) => !open && setDuplicateDialog(null)}
          itemType={duplicateDialog.type}
          originalName={duplicateDialog.originalName}
          onConfirm={handleDuplicateConfirm}
          onCancel={handleDuplicateCancel}
        />
      )}

      {/* Bulk Action Confirmation Dialog */}
      {bulkActionDialog && (
        <BaseConfirmDialog
          open={bulkActionDialog.open}
          onOpenChange={(open) => !open && setBulkActionDialog(null)}
          title={
            bulkActionDialog.type === "readonly"
              ? bulkActionDialog.action === "set"
                ? "Set All Files Read-Only"
                : "Allow Editing for All Files"
              : bulkActionDialog.action === "set"
              ? "Hide All Files in Preview"
              : "Show All Files in Preview"
          }
          description={
            bulkActionDialog.type === "readonly"
              ? bulkActionDialog.action === "set"
                ? "This will make all files and folders read-only. You won't be able to edit them."
                : "This will allow editing for all files and folders."
              : bulkActionDialog.action === "set"
              ? "This will hide all files and folders in preview mode."
              : "This will show all files and folders in preview mode."
          }
          onConfirm={handleConfirmBulkAction}
          confirmText={bulkActionDialog.action === "set" ? "Apply" : "Apply"}
          icon={
            bulkActionDialog.type === "readonly" ? (
              bulkActionDialog.action === "set" ? (
                <Lock className="h-12 w-12 text-orange-500" />
              ) : (
                <Unlock className="h-12 w-12 text-green-500" />
              )
            ) : bulkActionDialog.action === "set" ? (
              <EyeOff className="h-12 w-12 text-gray-500" />
            ) : (
              <Eye className="h-12 w-12 text-blue-500" />
            )
          }
        />
      )}

      {onAddFileFromAsset && (
        <AssetsProvider>
          <AssetPickerDialog
            open={showAssetDialog}
            onOpenChange={setShowAssetDialog}
            onSelect={(assets) => void handleAssetSelected(assets)}
            title="Add code files"
            description="Upload or select text files stored in this browser."
            kinds={["code", "document", "dataset"]}
            multiple
          />
        </AssetsProvider>
      )}

      {onImportCollection && showCollectionBrowser && (
        <CollectionBrowser
          onClose={() => setShowCollectionBrowser(false)}
          onImportFiles={(files, folderMetadata) =>
            onImportCollection(collectionPath, files, folderMetadata)
          }
        />
      )}

      {/* Save Collection Dialog */}
      {onSaveAsCollection && (
        <SaveCollectionDialog
          open={showSaveCollectionDialog}
          onOpenChange={setShowSaveCollectionDialog}
          onSave={async (params) => {
            if (onSaveAsCollection) {
              return await onSaveAsCollection(saveCollectionPath, saveCollectionFolderName || params.name)
            }
            return { success: false, error: "Handler not available" }
          }}
          folderName={saveCollectionFolderName}
        />
      )}
    </div>
  )
}

"use client"

import { useState, useEffect } from "react"
import { Package, Tag, AlertCircle } from "lucide-react"
import { Button } from "@game-guild/ui/components/button"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@game-guild/ui/components/dialog"
import { Input } from "@game-guild/ui/components/input"
import { Label } from "@game-guild/ui/components/label"
import { Textarea } from "@game-guild/ui/components/textarea"
import { Badge } from "@game-guild/ui/components/badge"
import { Alert, AlertDescription } from "@game-guild/ui/components/alert"

interface SaveCollectionDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onSave: (params: { name: string; description?: string; tags: string[] }) => Promise<{ success: boolean; error?: string }>
  folderName?: string
}

export function SaveCollectionDialog({ open, onOpenChange, onSave, folderName }: SaveCollectionDialogProps) {
  const [name, setName] = useState(folderName || "")
  const [description, setDescription] = useState("")
  const [tagInput, setTagInput] = useState("")
  const [tags, setTags] = useState<string[]>([])
  const [isSaving, setIsSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // Update name when folderName changes
  useEffect(() => {
    if (folderName) {
      setName(folderName)
    }
  }, [folderName])

  const handleAddTag = () => {
    const tag = tagInput.trim()
    if (tag && !tags.includes(tag)) {
      setTags([...tags, tag])
      setTagInput("")
    }
  }

  const handleRemoveTag = (tagToRemove: string) => {
    setTags(tags.filter((t) => t !== tagToRemove))
  }

  const handleSave = async () => {
    if (!name.trim()) {
      setError("Collection name is required")
      return
    }

    setIsSaving(true)
    setError(null)

    try {
      const result = await onSave({
        name: name.trim(),
        description: description.trim() || undefined,
        tags,
      })

      if (result.success) {
        // Reset form
        setName("")
        setDescription("")
        setTags([])
        setTagInput("")
        onOpenChange(false)
      } else {
        setError(result.error || "Failed to save collection")
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error")
    } finally {
      setIsSaving(false)
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      e.preventDefault()
      handleAddTag()
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Package className="h-5 w-5" />
            Save as Collection
          </DialogTitle>
          <DialogDescription>
            Create a reusable asset collection from your current project. Only files with asset references will be
            included.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          <div className="space-y-2">
            <Label htmlFor="name">Collection Name *</Label>
            <Input
              id="name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="My Project Assets"
              disabled={isSaving}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description</Label>
            <Textarea
              id="description"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Describe what this collection contains..."
              rows={3}
              disabled={isSaving}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="tags" className="flex items-center gap-2">
              <Tag className="h-4 w-4" />
              Tags
            </Label>
            <div className="flex gap-2">
              <Input
                id="tags"
                value={tagInput}
                onChange={(e) => setTagInput(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="Add tag (press Enter)"
                disabled={isSaving}
              />
              <Button type="button" variant="outline" onClick={handleAddTag} disabled={isSaving}>
                Add
              </Button>
            </div>
            {tags.length > 0 && (
              <div className="flex flex-wrap gap-2 mt-2">
                {tags.map((tag) => (
                  <Badge key={tag} variant="secondary" className="cursor-pointer" onClick={() => handleRemoveTag(tag)}>
                    {tag} ×
                  </Badge>
                ))}
              </div>
            )}
          </div>

          {error && (
            <Alert variant="destructive">
              <AlertCircle className="h-4 w-4" />
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={isSaving}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={isSaving || !name.trim()}>
            {isSaving ? "Saving..." : "Save Collection"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import { Folder, ChevronDown } from "lucide-react"
import { Button } from "@game-guild/ui/components/button"
import type { FileTreeFolder } from "./types"
import { cn } from "@/lib/utils"
import { useState, useRef, useEffect } from "react"

interface FocusEditorConfigProps {
  focusIndexPath?: string
  folders: FileTreeFolder[]
  editorInstance?: "multiple" | "unique"
  onSetIndexPath: (path: string) => void
}

export function FocusEditorConfig({
  focusIndexPath,
  folders,
  editorInstance,
  onSetIndexPath,
}: FocusEditorConfigProps) {
  const [isOpen, setIsOpen] = useState(false)
  const dropdownRef = useRef<HTMLDivElement>(null)

  // Only show config for unique editor instances
  // Multiple instances use the folder marked as focus
  if (editorInstance === "multiple") {
    return null
  }

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false)
      }
    }

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside)
      return () => document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [isOpen])

  // Get all folders as dropdown options
  const availableFolders = folders.filter(f => !f.readonly).sort((a, b) => a.path.localeCompare(b.path))

  const selectedFolder = focusIndexPath 
    ? folders.find(f => f.path === focusIndexPath)
    : null

  return (
    <div 
      ref={dropdownRef}
      className="relative flex items-center gap-2 px-3 py-2 bg-amber-50 dark:bg-amber-950/20 border-b border-amber-200 dark:border-amber-800"
      data-no-drag="true"
    >
      <Folder className="h-4 w-4 text-amber-600 dark:text-amber-400 shrink-0" />
      <span className="text-xs text-amber-700 dark:text-amber-400 shrink-0 font-medium">
        Index Folder:
      </span>
      
      <Button
        variant="ghost"
        size="sm"
        onClick={() => setIsOpen(!isOpen)}
        className={cn(
          "h-7 px-3 text-xs flex items-center gap-2 flex-1 justify-between",
          "bg-white dark:bg-gray-800 border border-amber-300 dark:border-amber-700",
          "hover:bg-amber-50 dark:hover:bg-gray-750 text-amber-900 dark:text-amber-100"
        )}
      >
        <span className="truncate">
          {selectedFolder ? selectedFolder.path : "Select folder..."}
        </span>
        <ChevronDown className={cn(
          "h-3 w-3 shrink-0 transition-transform",
          isOpen && "rotate-180"
        )} />
      </Button>

      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-1 z-50 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-md shadow-lg max-h-48 overflow-y-auto">
          {availableFolders.length === 0 ? (
            <div className="px-4 py-2 text-xs text-gray-500 dark:text-gray-400 italic">
              No folders available
            </div>
          ) : (
            availableFolders.map(folder => {
              const isSelected = folder.path === focusIndexPath
              
              return (
                <button
                  key={folder.path}
                  onClick={() => {
                    onSetIndexPath(folder.path)
                    setIsOpen(false)
                  }}
                  className={cn(
                    "w-full px-4 py-2 text-left text-xs flex items-center gap-2",
                    "hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors",
                    isSelected && "bg-amber-50 dark:bg-amber-900/20 text-amber-600 dark:text-amber-400 font-medium"
                  )}
                >
                  <Folder className="h-3 w-3 shrink-0" />
                  <span className="truncate">{folder.path}</span>
                </button>
              )
            })
          )}
        </div>
      )}
    </div>
  )
}

"use client"

import { ChevronDown, Code, FileCode, RotateCcw } from "lucide-react"
import { Button } from "@game-guild/ui/components/button"
import type { CodeFile, FileTreeFolder } from "./types"
import { cn } from "@/lib/utils"
import { useState, useRef, useEffect } from "react"
import { ResetConfirmDialog } from "../dialogs/reset-confirm-dialog"

interface LanguageSelectorProps {
  files: CodeFile[]
  folders: FileTreeFolder[]
  activeFileId?: string
  onSelectLanguage: (fileId: string) => void
  isPreview?: boolean
  onResetFile?: (fileId: string) => void
  onResetAllFiles?: () => void
}

export function LanguageSelector({
  files,
  folders,
  activeFileId,
  onSelectLanguage,
  isPreview = false,
  onResetFile,
  onResetAllFiles,
}: LanguageSelectorProps) {
  const [openDropdown, setOpenDropdown] = useState<string | null>(null)
  const [showResetMenu, setShowResetMenu] = useState(false)
  const [resetDialogOpen, setResetDialogOpen] = useState(false)
  const [resetType, setResetType] = useState<"current" | "all">("current")
  const dropdownRef = useRef<HTMLDivElement>(null)
  const resetMenuRef = useRef<HTMLDivElement>(null)
  // Track last selected file ID for each basename
  const lastSelectedPerBasenameRef = useRef<Record<string, string>>({})

  // Filter files by focus folder and group by basename
  const getFileGroups = () => {
    // Find folder marked as focus
    const focusFolder = folders.find(f => f.isFocusFolder)
    if (!focusFolder) return new Map<string, CodeFile[]>()
    
    // Filter files that are in the focus folder
    const indexFiles = files.filter(file => {
      const filePath = file.path
      const folderPath = filePath.substring(0, filePath.lastIndexOf('/'))
      return folderPath === focusFolder.path
    })

    // Group by basename (name without extension)
    const grouped = new Map<string, CodeFile[]>()
    indexFiles.forEach(file => {
      const basename = file.name.substring(0, file.name.lastIndexOf('.'))
      if (!grouped.has(basename)) {
        grouped.set(basename, [])
      }
      grouped.get(basename)!.push(file)
    })

    return grouped
  }

  const fileGroups = getFileGroups()
  const basenames = Array.from(fileGroups.keys())
  
  // Determine current basename from active file
  const activeFile = files.find(f => f.id === activeFileId)
  const currentBasename = activeFile ? activeFile.name.substring(0, activeFile.name.lastIndexOf('.')) : basenames[0] || null

  // Update last selected file when active file changes
  useEffect(() => {
    if (activeFile && currentBasename) {
      lastSelectedPerBasenameRef.current[currentBasename] = activeFile.id
    }
  }, [activeFile, currentBasename])

  // Reset handlers
  const handleResetClick = (type: "current" | "all") => {
    setResetType(type)
    setResetDialogOpen(true)
    setShowResetMenu(false)
  }

  const handleConfirmReset = () => {
    if (resetType === "current" && activeFileId && onResetFile) {
      onResetFile(activeFileId)
    } else if (resetType === "all" && onResetAllFiles) {
      onResetAllFiles()
    }
    setResetDialogOpen(false)
  }

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setOpenDropdown(null)
      }
      if (resetMenuRef.current && !resetMenuRef.current.contains(event.target as Node)) {
        setShowResetMenu(false)
      }
    }

    if (openDropdown || showResetMenu) {
      document.addEventListener('mousedown', handleClickOutside)
      return () => document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [openDropdown, showResetMenu])

  if (basenames.length === 0) {
    return (
      <div className="flex items-center gap-2 px-3 py-2 bg-gray-100 dark:bg-gray-900 border-b border-gray-200 dark:border-gray-800">
        <Code className="h-4 w-4 text-gray-400" />
        <span className="text-xs text-gray-500 dark:text-gray-400 italic">
          No focus folder selected (mark a folder as focus 🎯)
        </span>
      </div>
    )
  }

  return (
    <div 
      ref={dropdownRef}
      className="flex items-center gap-3 px-3 py-2 bg-gray-100 dark:bg-gray-900 border-b border-gray-200 dark:border-gray-800 flex-wrap"
    >
      {basenames.length === 1 ? (
        // Single basename: show "Language: [dropdown]"
        <>
          <Code className="h-4 w-4 text-blue-600 dark:text-blue-400 shrink-0" />
          <span className="text-xs text-gray-600 dark:text-gray-400 shrink-0">
            Language:
          </span>
          {(() => {
            const basename = basenames[0]!
            const basenameFiles = fileGroups.get(basename) || []
            const activeBasenameFile = basenameFiles.find(f => f.id === activeFileId)
            const activeExtension = activeBasenameFile?.name.split('.').pop() || basenameFiles[0]?.name.split('.').pop() || "js"
            const isOpen = openDropdown === basename

            return (
              <div className="relative">
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setOpenDropdown(isOpen ? null : basename)}
                  className={cn(
                    "h-7 px-3 text-xs font-medium flex items-center gap-2",
                    "bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700",
                    "hover:bg-gray-50 dark:hover:bg-gray-750"
                  )}
                >
                  <span className="uppercase">{activeExtension}</span>
                  <ChevronDown className={cn(
                    "h-3 w-3 transition-transform",
                    isOpen && "rotate-180"
                  )} />
                </Button>

                {isOpen && (
                  <div className={cn(
                    "absolute top-full left-0 mt-1 z-50 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-md shadow-lg overflow-hidden",
                    basenameFiles.length > 8 ? "grid grid-cols-2 min-w-[320px]" : "min-w-[180px]"
                  )}>
                    {basenameFiles.map(file => {
                      const extension = file.name.split('.').pop() || ''
                      const isActive = file.id === activeFileId
                      
                      return (
                        <button
                          key={file.id}
                          onClick={() => {
                            onSelectLanguage(file.id)
                            setOpenDropdown(null)
                          }}
                          className={cn(
                            "w-full px-4 py-2 text-left text-xs flex items-center gap-2",
                            "hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors",
                            isActive && "bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400"
                          )}
                        >
                          <span className="uppercase font-medium">{extension}</span>
                          <span className="text-gray-500 dark:text-gray-400">({file.language})</span>
                        </button>
                      )
                    })}
                  </div>
                )}
              </div>
            )
          })()}
        </>
      ) : (
        // Multiple basenames: show "basename: [dropdown]" for each
        <>
          <Code className="h-4 w-4 text-blue-600 dark:text-blue-400 shrink-0" />
          {basenames.map((basename) => {
            const basenameFiles = fileGroups.get(basename) || []
            const isCurrentBasename = basename === currentBasename
            
            // Determine which file to show in the dropdown button
            let displayFile: CodeFile | undefined
            if (isCurrentBasename) {
              // Current basename: show active file
              displayFile = basenameFiles.find(f => f.id === activeFileId)
            } else {
              // Other basename: show last selected or first
              const lastSelectedId = lastSelectedPerBasenameRef.current[basename]
              displayFile = lastSelectedId 
                ? basenameFiles.find(f => f.id === lastSelectedId)
                : undefined
            }
            
            const activeExtension = displayFile?.name.split('.').pop() || basenameFiles[0]?.name.split('.').pop() || "js"
            const isOpen = openDropdown === basename

            return (
              <div key={basename} className="flex items-center gap-2">
                <FileCode className="h-3 w-3 text-gray-500 dark:text-gray-400" />
                <button
                  onClick={() => {
                    // Select last selected file of this basename, or first if none selected before
                    if (!isCurrentBasename) {
                      const lastSelectedId = lastSelectedPerBasenameRef.current[basename]
                      const fileToSelect = lastSelectedId 
                        ? basenameFiles.find(f => f.id === lastSelectedId) || basenameFiles[0]
                        : basenameFiles[0]
                      
                      if (fileToSelect) {
                        onSelectLanguage(fileToSelect.id)
                      }
                    }
                  }}
                  className={cn(
                    "text-xs font-medium shrink-0 hover:underline cursor-pointer transition-colors",
                    isCurrentBasename ? "text-blue-600 dark:text-blue-400" : "text-gray-600 dark:text-gray-400 hover:text-blue-500 dark:hover:text-blue-300"
                  )}
                >
                  {basename}:
                </button>
                
                <div className="relative">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => setOpenDropdown(isOpen ? null : basename)}
                    className={cn(
                      "h-7 px-3 text-xs font-medium flex items-center gap-2",
                      "bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-700",
                      "hover:bg-gray-50 dark:hover:bg-gray-750",
                      isCurrentBasename && "border-blue-500 dark:border-blue-500"
                    )}
                  >
                    <span className="uppercase">{activeExtension}</span>
                    <ChevronDown className={cn(
                      "h-3 w-3 transition-transform",
                      isOpen && "rotate-180"
                    )} />
                  </Button>

                  {isOpen && (
                    <div className={cn(
                      "absolute top-full left-0 mt-1 z-50 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-md shadow-lg overflow-hidden",
                      basenameFiles.length > 8 ? "grid grid-cols-2 min-w-[320px]" : "min-w-[180px]"
                    )}>
                      {basenameFiles.map(file => {
                        const extension = file.name.split('.').pop() || ''
                        const isActive = file.id === activeFileId
                        
                        return (
                          <button
                            key={file.id}
                            onClick={() => {
                              onSelectLanguage(file.id)
                              setOpenDropdown(null)
                            }}
                            className={cn(
                              "w-full px-4 py-2 text-left text-xs flex items-center gap-2",
                              "hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors",
                              isActive && "bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400"
                            )}
                          >
                            <span className="uppercase font-medium">{extension}</span>
                            <span className="text-gray-500 dark:text-gray-400">({file.language})</span>
                          </button>
                        )
                      })}
                    </div>
                  )}
                </div>
              </div>
            )
          })}
        </>
      )}
      
      {/* Reset Button - Only in preview mode */}
      {isPreview && (onResetFile || onResetAllFiles) && (
        <div ref={resetMenuRef} className="relative ml-auto">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setShowResetMenu(!showResetMenu)}
            className={cn(
              "h-7 px-2 text-xs flex items-center gap-1.5",
              "hover:bg-orange-100 dark:hover:bg-orange-900/20",
              "text-orange-600 dark:text-orange-400"
            )}
            title="Reset files"
          >
            <RotateCcw className="h-3.5 w-3.5" />
            <span>Reset</span>
          </Button>

          {showResetMenu && (
            <div className="absolute top-full right-0 mt-1 z-50 min-w-[180px] bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-md shadow-lg overflow-hidden">
              <button
                onClick={() => handleResetClick("current")}
                disabled={!activeFileId}
                className={cn(
                  "w-full px-4 py-2 text-left text-xs flex items-center gap-2",
                  "hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors",
                  !activeFileId && "opacity-50 cursor-not-allowed"
                )}
              >
                <RotateCcw className="h-3.5 w-3.5 text-orange-600 dark:text-orange-400" />
                <span>Reset Current File</span>
              </button>
              <button
                onClick={() => handleResetClick("all")}
                className="w-full px-4 py-2 text-left text-xs flex items-center gap-2 hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
              >
                <RotateCcw className="h-3.5 w-3.5 text-orange-600 dark:text-orange-400" />
                <span>Reset All Files</span>
              </button>
            </div>
          )}
        </div>
      )}

      {/* Reset Confirmation Dialog */}
      <ResetConfirmDialog
        open={resetDialogOpen}
        onOpenChange={setResetDialogOpen}
        resetType={resetType}
        fileName={activeFile?.name}
        onConfirm={handleConfirmReset}
      />
    </div>
  )
}

import type { CodeRunner, RunnerResult, RunnerOptions, FileMap } from './types'
import { WASIWorkerHost, type WASIFS, type BinaryWASIFS } from '@runno/wasi'
import { loadCompressedWasm, loadTarGz } from './wasm-loader'

let clangBlobUrl: string | null = null
let wasmLdBlobUrl: string | null = null
let clangFS: BinaryWASIFS | null = null

async function getClangBlobUrl(): Promise<string> {
  if (clangBlobUrl) {
    return clangBlobUrl
  }

  const wasmBuffer = await loadCompressedWasm('/langs/clang.wasm.gz')
  const blob = new Blob([wasmBuffer], { type: 'application/wasm' })
  clangBlobUrl = URL.createObjectURL(blob)
  
  return clangBlobUrl
}

async function getWasmLdBlobUrl(): Promise<string> {
  if (wasmLdBlobUrl) {
    return wasmLdBlobUrl
  }

  const wasmBuffer = await loadCompressedWasm('/langs/wasm-ld.wasm.gz')
  const blob = new Blob([wasmBuffer], { type: 'application/wasm' })
  wasmLdBlobUrl = URL.createObjectURL(blob)
  
  return wasmLdBlobUrl
}

async function getClangFS(): Promise<BinaryWASIFS> {
  if (clangFS) {
    return clangFS
  }

  const fs = await loadTarGz('/langs/clang-fs.tar.gz')
  
  const hasStdio = '/sys/include/stdio.h' in fs
  const hasSysInclude = Object.keys(fs).filter(p => p.startsWith('/sys/')).length
  console.log('[CRunner] Clang FS loaded:', {
    totalFiles: Object.keys(fs).length,
    hasSysFiles: hasSysInclude,
    hasStdio,
    samplePaths: Object.keys(fs).slice(0, 10)
  })
  
  clangFS = fs
  
  return fs
}

export class CRunner implements CodeRunner {
  private isInterrupted = false
  private readonly options: RunnerOptions

  constructor(options: RunnerOptions = {}) {
    this.options = {
      timeout: options.timeout || 30000,
      memoryLimit: options.memoryLimit || 64 * 1024 * 1024,
      onRequestInput: options.onRequestInput,
      onProgress: options.onProgress,
    }
  }

  private async compileToObject(
    clangUrl: string,
    baseFS: BinaryWASIFS,
    sourceFile: string,
    userFS: WASIFS = {}
  ): Promise<{ exitCode: number; stdout: string; stderr: string; fs?: WASIFS }> {
    let compileStdout = ''
    let compileStderr = ''
    
    const compileFS: WASIFS = {
      ...baseFS,
      ...userFS,
    }

    const clangHost = new WASIWorkerHost(clangUrl, {
      args: [
        'clang',
        '-cc1',
        '-emit-obj',
        '-isysroot',
        '/sys',
        '-internal-isystem',
        '/sys/include',
        '-internal-isystem',
        '/sys/lib/clang/8.0.1/include',
        '-o',
        '/program.o',
        '-x',
        'c',
        sourceFile
      ],
      env: {},
      fs: compileFS,
      stdout: (out) => { compileStdout += out },
      stderr: (err) => { compileStderr += err },
    })

    const result = await clangHost.start()
    
    return {
      exitCode: result.exitCode,
      stdout: compileStdout,
      stderr: compileStderr,
      fs: result.fs,
    }
  }

  private async linkToWasm(
    wasmLdUrl: string,
    baseFS: BinaryWASIFS,
    objectFS: WASIFS
  ): Promise<{ exitCode: number; stdout: string; stderr: string; fs?: WASIFS }> {
    let linkStdout = ''
    let linkStderr = ''
    
    const linkFS: WASIFS = {
      ...baseFS,
      ...objectFS,
    }

    const wasmLdHost = new WASIWorkerHost(wasmLdUrl, {
      args: [
        'wasm-ld',
        '--no-threads',
        '--export-dynamic',
        '-z',
        'stack-size=1048576',
        '-L/sys/lib/wasm32-wasi',
        '/sys/lib/wasm32-wasi/crt1.o',
        '/program.o',
        '-lc',
        '-o',
        '/program.wasm'
      ],
      env: {},
      fs: linkFS,
      stdout: (out) => { linkStdout += out },
      stderr: (err) => { linkStderr += err },
    })

    const result = await wasmLdHost.start()
    
    console.log('[CRunner] Link result:', {
      exitCode: result.exitCode,
      hasStdout: linkStdout.length,
      hasStderr: linkStderr.length,
    })
    
    return {
      exitCode: result.exitCode,
      stdout: linkStdout,
      stderr: linkStderr,
      fs: result.fs,
    }
  }

  private async runWasm(
    wasmFS: WASIFS,
    stdin?: string
  ): Promise<{ exitCode: number; stdout: string; stderr: string }> {
    let runStdout = ''
    let runStderr = ''
    
    if (!wasmFS['/program.wasm']) {
      return {
        exitCode: 1,
        stdout: '',
        stderr: 'Failed to generate /program.wasm',
      }
    }

    const programWasm = wasmFS['/program.wasm'].content
    const programBlob = new Blob(
      [typeof programWasm === 'string' ? programWasm : programWasm.buffer as ArrayBuffer],
      { type: 'application/wasm' }
    )
    const programUrl = URL.createObjectURL(programBlob)

    try {
      const programHost = new WASIWorkerHost(programUrl, {
        args: ['program'],
        env: {},
        fs: wasmFS,
        stdout: (out) => { runStdout += out },
        stderr: (err) => { runStderr += err },
      })

      if (stdin) {
        programHost.pushStdin(stdin)
        programHost.pushEOF()
      }

      const runResult = await programHost.start()
      
      return {
        exitCode: runResult.exitCode,
        stdout: runStdout,
        stderr: runStderr,
      }
    } finally {
      URL.revokeObjectURL(programUrl)
    }
  }

  async execute(code: string, stdin?: string): Promise<RunnerResult> {
    const startTime = performance.now()
    
    try {
      this.isInterrupted = false

      this.options.onProgress?.('Loading compiler...')
      const [clangUrl, wasmLdUrl, baseFS] = await Promise.all([
        getClangBlobUrl(),
        getWasmLdBlobUrl(),
        getClangFS(),
      ])

      const sourceFS: WASIFS = {
