      if (linkResult.exitCode !== 0) {
        const executionTime = performance.now() - startTime
        return {
          stdout: (compileResult.stdout + linkResult.stdout).trimEnd(),
          stderr: (compileResult.stderr + linkResult.stderr).trimEnd(),
