import type { CodeRunner, RunnerResult, RunnerOptions, FileMap } from './types'
import { setDownloadNotificationCallback, installManagedFetchInterceptor } from './wasm-loader'
import { CSharpCompiler, type CSharpFile, type CSharpResult } from '@game-guild/dotnet-wasm'

/**
 * DotNetRunner - C# Code Execution using Mono WebAssembly and Roslyn
 * 
 * This runner compiles and executes C# code entirely in the browser.
 * It uses the @game-guild/dotnet-wasm package which provides:
 * - Mono WebAssembly runtime
 * - Roslyn C# compiler
 * - IL assembly execution
 * 
 * Architecture:
 * 1. Load Mono WASM runtime (cached after first load)
 * 2. Compile C# code using Roslyn → IL assembly
 * 3. Execute IL assembly in Mono interpreter
 * 4. Return stdout/stderr/exit code
 * 
 * Note: The actual runtime files must be served from /managed/ path:
 * - /managed/dotnet.wasm
 * - /managed/dotnet.js
 * - /managed/*.dll
 * - /managed/icudt.dat
 */

// Shared compiler instance for reuse
let compilerInstance: CSharpCompiler | null = null

async function getDotNetCompiler(): Promise<CSharpCompiler> {
  // Return existing instance if available
  if (compilerInstance && compilerInstance.isReady()) {
    return compilerInstance
  }

  // Create new compiler instance if needed
  if (!compilerInstance) {
    try {
      console.log('[DotNetRunner] Creating new CSharpCompiler instance')
      
      // Install fetch interceptor for managed files (only once)
      installManagedFetchInterceptor()
      
      // Use public path for the managed runtime
      compilerInstance = new CSharpCompiler('/managed')
      await compilerInstance.initialize()
      console.log('[DotNetRunner] CSharpCompiler initialized successfully')
    } catch (error) {
      console.error('[DotNetRunner] Failed to initialize compiler:', error)
      throw new Error(
        `Failed to initialize C# compiler. Make sure the dotnet-wasm runtime files are available.\n` +
        `Error: ${error instanceof Error ? error.message : String(error)}`
      )
    }
  }

  return compilerInstance
}

export class DotNetRunner implements CodeRunner {
  private isInterrupted = false
  private readonly options: RunnerOptions

  constructor(options: RunnerOptions = {}) {
    this.options = {
      timeout: options.timeout || 30000, // 30 second default
      memoryLimit: options.memoryLimit || 256 * 1024 * 1024, // 256MB (not enforced yet)
      onRequestInput: options.onRequestInput,
      onProgress: options.onProgress,
    }
  }

  async execute(code: string, stdin?: string): Promise<RunnerResult> {
    const startTime = performance.now()

    try {
      this.isInterrupted = false

      // Set up download notifications
      if (this.options.onProgress) {
        setDownloadNotificationCallback((message, isDownloading) => {
          this.options.onProgress?.(message)
        })
      }

      // Load and initialize compiler
      this.options.onProgress?.('Loading C# compiler...')
      const compiler = await getDotNetCompiler()

      // Compile and execute
      this.options.onProgress?.('Compiling and executing C# code...')
      const result: CSharpResult = await compiler.execute(code)

      const totalTime = performance.now() - startTime

      // Clear download callback
      setDownloadNotificationCallback(null)

      // Convert CSharpResult to RunnerResult
      if (result.error) {
        return {
          stdout: result.output || '',
          stderr: result.error,
          exitCode: 1,
          executionTime: totalTime,
        }
      }

      return {
        stdout: result.output || '',
        stderr: '',
        exitCode: 0,
        executionTime: totalTime,
      }
    } catch (error) {
      const executionTime = performance.now() - startTime
      
      // Clear download callback on error
      setDownloadNotificationCallback(null)

      console.error('[DotNetRunner] execute caught error:', error)

      let errorMessage = 'Unknown error'
      if (error instanceof Error) {
        errorMessage = error.message
        if (error.stack) {
          console.error('DotNetRunner execute error stack:', error.stack)
        }
      } else if (typeof error === 'object' && error !== null) {
        errorMessage = JSON.stringify(error, null, 2)
      } else {
        errorMessage = String(error)
      }

      return {
        stdout: '',
        stderr: errorMessage,
        exitCode: 1,
        executionTime,
      }
    }
  }

  async executeWithFiles(
    entryPoint: string,
    files: FileMap,
    stdin?: string
  ): Promise<RunnerResult> {
    const startTime = performance.now()

    try {
      this.isInterrupted = false

      const mainFile = files[entryPoint]

      if (!mainFile) {
        return {
          stdout: '',
          stderr: `Entry point file not found: ${entryPoint}`,
          exitCode: 1,
          executionTime: 0,
        }
      }

      // Set up download notifications
      if (this.options.onProgress) {
        setDownloadNotificationCallback((message, isDownloading) => {
          this.options.onProgress?.(message)
        })
      }

      // Load and initialize compiler
      this.options.onProgress?.('Loading C# compiler...')
      const compiler = await getDotNetCompiler()

      // If multiple files, use executeMultiple
      if (Object.keys(files).length > 1) {
        this.options.onProgress?.('Compiling multiple C# files...')
        
        // Convert FileMap to CSharpFile array - filter only .cs files
        const csharpFiles: CSharpFile[] = Object.entries(files)
          .filter(([name]) => name !== entryPoint)
          .map(([name, content]) => ({ name, content }))

        const result: CSharpResult = await compiler.executeMultiple(mainFile, csharpFiles)
        const totalTime = performance.now() - startTime

        // Clear download callback
        setDownloadNotificationCallback(null)

        if (result.error) {
          return {
            stdout: result.output || '',
            stderr: result.error,
            exitCode: 1,
            executionTime: totalTime,
          }
        }

        return {
          stdout: result.output || '',
          stderr: '',
          exitCode: 0,
          executionTime: totalTime,
        }
      }

      // Single file execution
      return await this.execute(mainFile, stdin)
    } catch (error) {
      const executionTime = performance.now() - startTime
      
      // Clear download callback on error
      setDownloadNotificationCallback(null)

      console.error('[DotNetRunner] executeWithFiles caught error:', error)

      let errorMessage = 'Unknown error'
      if (error instanceof Error) {
        errorMessage = error.message
      } else {
        errorMessage = String(error)
      }

      return {
        stdout: '',
        stderr: errorMessage,
        exitCode: 1,
        executionTime,
      }
    }
  }

  async interrupt(): Promise<void> {
    this.isInterrupted = true
    // Note: The current CSharpCompiler doesn't have interrupt support yet
    console.warn('[DotNetRunner] Interrupt requested but not fully implemented in compiler')
  }

  dispose(): void {
    // We don't dispose the shared compiler instance here
    // because it can be reused across multiple executions
    // The compiler will be disposed when the page unloads
    this.isInterrupted = false
  }
}

/**
 * Preload the DotNet compiler to speed up first execution
 * Call this during application initialization
 */
export async function preloadDotNetCompiler(): Promise<void> {
  try {
    await getDotNetCompiler()
    console.log('[DotNetRunner] Compiler preloaded successfully')
  } catch (error) {
    console.error('[DotNetRunner] Failed to preload compiler:', error)
  }
}

/**
 * Dispose the shared compiler instance
 * Call this when cleaning up the application
 */
export function disposeDotNetCompiler(): void {
  if (compilerInstance) {
    compilerInstance = null
  }
}

import type { CodeRunner, FileMap, RunnerOptions, RunnerResult } from './types'

let luaFactory: any = null

async function getLuaFactory(): Promise<any> {
  if (!luaFactory) {
    // Dynamically import wasmoon to avoid loading it during SSR/build
    const { LuaFactory } = await import('wasmoon')
    luaFactory = new LuaFactory()
  }
  return luaFactory
}

async function createFreshLuaEngine(): Promise<any> {
  const factory = await getLuaFactory()
  return await factory.createEngine()
}

export class LuaRunner implements CodeRunner {
  private isInterrupted = false
  private readonly options: RunnerOptions

  constructor(options: RunnerOptions = {}) {
    this.options = {
      timeout: options.timeout || 30000,
      memoryLimit: options.memoryLimit || 64 * 1024 * 1024,
      onRequestInput: options.onRequestInput,
    }
  }

  async execute(code: string, stdin?: string): Promise<RunnerResult> {

    const startTime = performance.now()
    let stdout = ''
    let stderr = ''
    let exitCode = 0
    let lua: any = null

    try {
      lua = await createFreshLuaEngine()
      this.isInterrupted = false

      // Setup print function to capture output
      await lua.doString(`
        local output_buffer = {}
        
        function print(...)
          local args = {...}
          local str_args = {}
          for i, v in ipairs(args) do
            table.insert(str_args, tostring(v))
          end
          local line = table.concat(str_args, "\\t")
          table.insert(output_buffer, line)
        end
        
        function get_output()
          return table.concat(output_buffer, "\\n")
        end
        
        function clear_output()
          output_buffer = {}
        end
      `)

      // Setup stdin - either from pre-provided string or interactive callback
      if (stdin !== undefined) {
        // Pre-provided stdin (static)
        const stdinLines = stdin.split('\n')
        await lua.doString(`
          _stdin_lines = {}
          _stdin_index = 1
        `)

        // Load stdin lines into Lua
        for (const line of stdinLines) {
          const escapedLine = line.replace(/\\/g, '\\\\').replace(/"/g, '\\"')
          await lua.doString(`table.insert(_stdin_lines, "${escapedLine}")`)
        }

        // Override io.read to use stdin
        await lua.doString(`
          io.read = function()
            if _stdin_index <= #_stdin_lines then
              local line = _stdin_lines[_stdin_index]
              _stdin_index = _stdin_index + 1
              return line
            end
            return nil
          end
        `)
      } else if (this.options.onRequestInput) {
        // Interactive input via callback
        const requestInput = this.options.onRequestInput

        lua.global.set('_request_input_js', (prompt?: string) => {
          // Get current output before requesting input
          if (!lua) return Promise.reject(new Error('Lua engine not initialized'))
          return lua.doString('return get_output()').then((currentOutput: unknown) => {
            const outputStr = String(currentOutput || '')
            return requestInput(prompt, outputStr)
          })
        })

        await lua.doString(`
          io.read = function(prompt)
            local promise = _request_input_js(prompt)
            return promise:await()
          end
        `)
      }

      // Clear previous output
      await lua.doString('clear_output()')

      // Execute with timeout
      const timeoutPromise = new Promise<never>((_, reject) => {
        setTimeout(() => reject(new Error('Execution timeout')), this.options.timeout)
      })

      const execPromise = lua.doString(code)

      await Promise.race([execPromise, timeoutPromise])

      // Get output
      const outputResult = await lua.doString('return get_output()')
      stdout = String(outputResult || '')

    } catch (error) {
      exitCode = 1
      const errorMsg = error instanceof Error ? error.message : String(error)
      stderr = errorMsg
    } finally {
      // Clean up the engine after execution
      if (lua) {
        lua.global.close()
      }
    }

    const executionTime = performance.now() - startTime

    return {
      stdout: stdout.trimEnd(),
      stderr: stderr.trimEnd(),
      exitCode,
      executionTime,
    }
  }

  async executeWithFiles(entryPoint: string, files: FileMap, stdin?: string): Promise<RunnerResult> {
    const startTime = performance.now()
    let stdout = ''
    let stderr = ''
    let exitCode = 0
    let lua: any = null

    try {
      lua = await createFreshLuaEngine()
      this.isInterrupted = false

      // Setup print function to capture output
      await lua.doString(`
        local output_buffer = {}
        
        function print(...)
          local args = {...}
          local str_args = {}
          for i, v in ipairs(args) do
            table.insert(str_args, tostring(v))
          end
          local line = table.concat(str_args, "\\t")
          table.insert(output_buffer, line)
        end
        
        function get_output()
          return table.concat(output_buffer, "\\n")
        end
        
        function clear_output()
          output_buffer = {}
        end
      `)

      // Create a virtual file system in Lua using a table
      await lua.doString(`
        _virtual_fs = {}
        _loaded_modules = {}
        
        function _load_module(modulename)
          -- Check if module is already loaded
          if _loaded_modules[modulename] then
            return function() return _loaded_modules[modulename] end
          end
          
          -- Try to load from virtual FS
          local path = modulename:gsub("%.", "/")
          local content = nil
          local source_name = nil
          
          -- Try with .lua extension
          if _virtual_fs[path .. ".lua"] then
            content = _virtual_fs[path .. ".lua"]
            source_name = "@" .. path .. ".lua"
          -- Try exact match
          elseif _virtual_fs[path] then
            content = _virtual_fs[path]
            source_name = "@" .. path
          -- Try as filename directly (for require "module.lua")
          elseif _virtual_fs[modulename] then
            content = _virtual_fs[modulename]
            source_name = "@" .. modulename
          end
          
          if content then
            local chunk, err = load(content, source_name)
            if not chunk then
              error("Error loading module '" .. modulename .. "': " .. tostring(err))
            end
            
            -- Execute the module and cache its return value
            local module_result = chunk()
            if module_result == nil then
              module_result = true  -- If module returns nothing, cache true
            end
            _loaded_modules[modulename] = module_result
            
            return function() return module_result end
          end
          
          error("Module '" .. modulename .. "' not found in virtual filesystem")
        end
        
        -- Override require to use virtual FS with module caching
        local original_require = require
        require = function(modulename)
          local success, loader = pcall(_load_module, modulename)
          if success then
            return loader()
          else
            -- Fallback to original require for built-in modules
            local builtin_success, builtin_result = pcall(original_require, modulename)
            if builtin_success then
              return builtin_result
            else
              -- Re-throw the virtual FS error if builtin also fails
              error(loader)
            end
          end
        end
      `)

      // Load all files into the virtual file system
      for (const [filePath, content] of Object.entries(files)) {
        // Normalize path (remove leading ./ or /)
        const normalizedPath = filePath.replace(/^\.?\//, '')

        // Escape the content for Lua string
        const escapedContent = content
          .replace(/\\/g, '\\\\')
          .replace(/"/g, '\\"')
          .replace(/\n/g, '\\n')
          .replace(/\r/g, '\\r')
          .replace(/\t/g, '\\t')

        // Add to virtual FS with original path
        await lua.doString(`_virtual_fs["${normalizedPath}"] = "${escapedContent}"`)

        // Also add without .lua extension if present (for easier require)
        if (normalizedPath.endsWith('.lua')) {
          const pathWithoutExt = normalizedPath.slice(0, -4)
          await lua.doString(`_virtual_fs["${pathWithoutExt}"] = "${escapedContent}"`)
        }
      }

      // Setup stdin - either from pre-provided string or interactive callback
      if (stdin !== undefined) {
        // Pre-provided stdin (static)
        const stdinLines = stdin.split('\n')
        await lua.doString(`
          _stdin_lines = {}
          _stdin_index = 1
        `)

        for (const line of stdinLines) {
          const escapedLine = line.replace(/\\/g, '\\\\').replace(/"/g, '\\"')
          await lua.doString(`table.insert(_stdin_lines, "${escapedLine}")`)
        }

        await lua.doString(`
          io.read = function()
            if _stdin_index <= #_stdin_lines then
              local line = _stdin_lines[_stdin_index]
              _stdin_index = _stdin_index + 1
              return line
            end
            return nil
          end
        `)
      } else if (this.options.onRequestInput) {
        // Interactive input via callback
        const requestInput = this.options.onRequestInput

        lua.global.set('_request_input_js', (prompt?: string) => {
          // Get current output before requesting input
          if (!lua) return Promise.reject(new Error('Lua engine not initialized'))
          return lua.doString('return get_output()').then((currentOutput: unknown) => {
            const outputStr = String(currentOutput || '')
            return requestInput(prompt, outputStr)
          })
        })

        await lua.doString(`
          io.read = function(prompt)
            local promise = _request_input_js(prompt)
            return promise:await()
          end
        `)
      }

      // Clear previous output
      await lua.doString('clear_output()')

      // Get entry point content and execute
      const entryContent = files[entryPoint]
      if (!entryContent) {
        throw new Error(`Entry point file '${entryPoint}' not found`)
      }

      // Execute with timeout
      const timeoutPromise = new Promise<never>((_, reject) => {
        setTimeout(() => reject(new Error('Execution timeout')), this.options.timeout)
      })

      const execPromise = lua.doString(entryContent)

      await Promise.race([execPromise, timeoutPromise])

      // Get output
      const outputResult = await lua.doString('return get_output()')
      stdout = String(outputResult || '')

    } catch (error) {
      exitCode = 1
      const errorMsg = error instanceof Error ? error.message : String(error)
      stderr = errorMsg
    } finally {
      // Clean up the engine after execution
      if (lua) {
        lua.global.close()
      }
    }

    const executionTime = performance.now() - startTime

    return {
      stdout: stdout.trimEnd(),
      stderr: stderr.trimEnd(),
      exitCode,
      executionTime,
    }
  }

  async interrupt(): Promise<void> {
    this.isInterrupted = true
  }

  dispose(): void {
    // Wasmoon handles cleanup internally
    this.isInterrupted = false
  }
}

import type { CodeRunner, RunnerResult, RunnerOptions, FileMap } from './types'
import { WASIWorkerHost, type WASIFS } from '@runno/wasi'
import { loadCompressedWasm } from './wasm-loader'

let phpBlobUrl: string | null = null

async function getPhpBlobUrl(): Promise<string> {
  if (phpBlobUrl) {
    return phpBlobUrl
  }

  const wasmBuffer = await loadCompressedWasm('/langs/php-cgi.wasm.gz')
  const blob = new Blob([wasmBuffer], { type: 'application/wasm' })
  phpBlobUrl = URL.createObjectURL(blob)
  
  return phpBlobUrl
}

export class PhpRunner implements CodeRunner {
  private isInterrupted = false
  private readonly options: RunnerOptions

  constructor(options: RunnerOptions = {}) {
    this.options = {
      timeout: options.timeout || 30000,
      memoryLimit: options.memoryLimit || 64 * 1024 * 1024,
      onRequestInput: options.onRequestInput,
      onProgress: options.onProgress,
    }
  }

  private async runPhp(
    phpUrl: string,
    phpFS: WASIFS,
    scriptPath: string,
    stdin?: string
  ): Promise<{ exitCode: number; stdout: string; stderr: string }> {
    let phpStdout = ''
    let phpStderr = ''

    const phpHost = new WASIWorkerHost(phpUrl, {
      args: ['php-cgi', scriptPath],
      env: {
        REDIRECT_STATUS: '1', // Required for php-cgi
        REQUEST_METHOD: 'GET',
        SCRIPT_FILENAME: scriptPath,
        PATH_TRANSLATED: scriptPath,
      },
      fs: phpFS,
      stdout: (out) => { phpStdout += out },
      stderr: (err) => { phpStderr += err },
    })

    if (stdin) {
      phpHost.pushStdin(stdin)
      phpHost.pushEOF()
    }

    const result = await phpHost.start()
    
    // PHP-CGI outputs HTTP headers, strip them from stdout
    const outputParts = phpStdout.split('\r\n\r\n')
    const actualOutput = outputParts.length > 1 ? outputParts.slice(1).join('\r\n\r\n') : phpStdout
    
    return {
      exitCode: result.exitCode,
      stdout: actualOutput,
      stderr: phpStderr,
    }
  }

  async execute(code: string, stdin?: string): Promise<RunnerResult> {
    const startTime = performance.now()
    
    try {
      this.isInterrupted = false

      this.options.onProgress?.('Loading PHP interpreter...')
      const phpUrl = await getPhpBlobUrl()

      const phpFS: WASIFS = {
        '/program.php': {
          path: '/program.php',
          timestamps: {
            access: new Date(),
            modification: new Date(),
            change: new Date(),
          },
          mode: 'string',
          content: code,
        },
      }

      this.options.onProgress?.('Running PHP code...')
      const runResult = await this.runPhp(phpUrl, phpFS, '/program.php', stdin)
      
      const executionTime = performance.now() - startTime
      
      return {
        stdout: runResult.stdout.trimEnd(),
        stderr: runResult.stderr.trimEnd(),
        exitCode: runResult.exitCode,
        executionTime,
      }
    } catch (error) {
      const executionTime = performance.now() - startTime
      
      console.error('[PhpRunner] execute caught error:', error)
      
      let errorMessage = 'Unknown error'
      if (error instanceof Error) {
        errorMessage = error.message
        if (error.stack) {
          console.error('PhpRunner execute error stack:', error.stack)
        }
      } else if (typeof error === 'object' && error !== null) {
        errorMessage = JSON.stringify(error, null, 2)
      } else {
        errorMessage = String(error)
      }
      
      return {
        stdout: '',
        stderr: errorMessage,
        exitCode: 1,
        executionTime,
      }
    }
  }

  async executeWithFiles(entryPoint: string, files: FileMap, stdin?: string): Promise<RunnerResult> {
    const startTime = performance.now()
    
    try {
      this.isInterrupted = false

      this.options.onProgress?.('Loading PHP interpreter...')
      const phpUrl = await getPhpBlobUrl()

      const phpFS: WASIFS = {}
      for (const [path, content] of Object.entries(files)) {
        phpFS[path] = {
          path,
          timestamps: {
            access: new Date(),
            modification: new Date(),
            change: new Date(),
          },
          mode: 'string',
          content,
        }
      }

      this.options.onProgress?.('Running PHP code...')
      const runResult = await this.runPhp(phpUrl, phpFS, entryPoint, stdin)
      
      const executionTime = performance.now() - startTime
      
      return {
        stdout: runResult.stdout.trimEnd(),
        stderr: runResult.stderr.trimEnd(),
        exitCode: runResult.exitCode,
        executionTime,
      }
    } catch (error) {
      const executionTime = performance.now() - startTime
      
      console.error('[PhpRunner] executeWithFiles caught error:', error)
      
      let errorMessage = 'Unknown error'
      if (error instanceof Error) {
        errorMessage = error.message
        if (error.stack) {
          console.error('PhpRunner executeWithFiles error stack:', error.stack)
        }
      } else if (typeof error === 'object' && error !== null) {
        errorMessage = JSON.stringify(error, null, 2)
      } else {
        errorMessage = String(error)
      }
      
      return {
        stdout: '',
        stderr: errorMessage,
        exitCode: 1,
        executionTime,
      }
    }
  }

  async interrupt(): Promise<void> {
    this.isInterrupted = true
  }

  dispose(): void {
    // Cleanup if needed
  }
}

import type { CodeRunner, RunnerResult, RunnerOptions, FileMap } from './types'
import { loadCompressedScript } from './wasm-loader'

// Pyodide module interface
interface PyodideModule {
  runPythonAsync(code: string): Promise<any>
  setStdout(options: { batched: (text: string) => void }): void
  setStderr(options: { batched: (text: string) => void }): void
  setStdin(options: { stdin: () => string | null }): void
  setInterruptBuffer(buffer: Int32Array): void
  loadPackagesFromImports?(code: string): Promise<void>
  FS: {
    writeFile(path: string, data: string | Uint8Array): void
    readFile(path: string): Uint8Array
    mkdir(path: string): void
    rmdir(path: string): void
    unlink(path: string): void
  }
  globals: {
    get(key: string): any
  }
}

// Pyodide loader interface
interface LoadPyodideOptions {
  indexURL?: string
  fullStdLib?: boolean
}

declare global {
  interface Window {
    loadPyodide?: (options?: LoadPyodideOptions) => Promise<PyodideModule>
  }
}

let pyodideInstance: PyodideModule | null = null
let pyodidePromise: Promise<PyodideModule> | null = null

async function loadPyodideRuntime(): Promise<void> {
  if (typeof window === 'undefined') return
  if (typeof window.loadPyodide !== 'undefined') return

  // Load compressed Pyodide runtime scripts using wasm-loader
  await loadCompressedScript('/langs/pyodide.js.gz')
  
  // Wait a bit for the script to initialize
  await new Promise(resolve => setTimeout(resolve, 100))
}

async function getPyodide(): Promise<PyodideModule> {
  if (pyodideInstance) {
    return pyodideInstance
  }

  if (!pyodidePromise) {
    pyodidePromise = (async () => {
      // Load Pyodide runtime scripts
      await loadPyodideRuntime()

      if (!window.loadPyodide) {
        throw new Error('Pyodide runtime not available')
      }

      // Initialize Pyodide pointing to our compressed files
      // Pyodide will automatically fetch .wasm files from indexURL
      const pyodide = await window.loadPyodide({
        indexURL: '/langs/',
        fullStdLib: false,
      })

      pyodideInstance = pyodide
      
      return pyodide
    })()
  }

  return pyodidePromise
}

export class PythonRunner implements CodeRunner {
  private isInterrupted = false
  private readonly options: RunnerOptions

  constructor(options: RunnerOptions = {}) {
    this.options = {
      timeout: options.timeout || 30000,
      memoryLimit: options.memoryLimit || 64 * 1024 * 1024,
    }
  }

  async execute(code: string, stdin?: string): Promise<RunnerResult> {
    // Small delay to prevent race conditions
    await new Promise(resolve => setTimeout(resolve, 5))
    
    const startTime = performance.now()
    let stdout = ''
    let stderr = ''
    let exitCode = 0

    try {
      // Notificar usuário sobre download se necessário
      const pyodide = await getPyodide()
      this.isInterrupted = false

      // Redirect stdout/stderr
      pyodide.setStdout({ 
        batched: (text) => { stdout += text }
      })
      pyodide.setStderr({ 
        batched: (text) => { stderr += text }
      })

      // Setup stdin if provided
      if (stdin !== undefined) {
        const lines = stdin.split('\n')
        let lineIndex = 0
        pyodide.setStdin({
          stdin: () => {
            if (lineIndex < lines.length) {
              return lines[lineIndex++] + '\n'
            }
            return null
          },
        })
      }

      // Load packages from imports if available
      if (pyodide.loadPackagesFromImports) {
        try {
          await pyodide.loadPackagesFromImports(code)
        } catch {
          // Ignore package loading errors
        }
      }

      // Execute with timeout
      const timeoutPromise = new Promise<never>((_, reject) => {
        setTimeout(() => reject(new Error('Execution timeout')), this.options.timeout)
      })

      const execPromise = pyodide.runPythonAsync(code)

      await Promise.race([execPromise, timeoutPromise])

    } catch (error) {
      exitCode = 1
      const errorMsg = error instanceof Error ? error.message : String(error)
      
      // Add error to stderr if not already there
      if (!stderr.includes(errorMsg)) {
        stderr += (stderr ? '\n' : '') + errorMsg
      }
    }

    const executionTime = performance.now() - startTime

    return {
      stdout: stdout.trimEnd(),
      stderr: stderr.trimEnd(),
      exitCode,
      executionTime,
    }
  }

  async executeWithFiles(entryPoint: string, files: FileMap, stdin?: string): Promise<RunnerResult> {
    await new Promise(resolve => setTimeout(resolve, 5))
    
    const startTime = performance.now()
    let stdout = ''
    let stderr = ''
    let exitCode = 0

    try {
      const pyodide = await getPyodide()
      this.isInterrupted = false

      // Redirect stdout/stderr
      pyodide.setStdout({ 
        batched: (text) => { stdout += text }
      })
      pyodide.setStderr({ 
        batched: (text) => { stderr += text }
      })

      // Setup stdin if provided
      if (stdin !== undefined) {
        const lines = stdin.split('\n')
        let lineIndex = 0
        pyodide.setStdin({
          stdin: () => {
            if (lineIndex < lines.length) {
              return lines[lineIndex++] + '\n'
            }
            return null
          },
        })
      }

      // Criar estrutura de diretórios e escrever todos os arquivos no FS do Pyodide
      const createdDirs = new Set<string>()
      
      for (const [path, content] of Object.entries(files)) {
        // Remover leading slash se houver
        const cleanPath = path.startsWith('/') ? path.substring(1) : path
        
        // Criar diretórios necessários
        const parts = cleanPath.split('/')
        if (parts.length > 1) {
          let currentPath = ''
          for (let i = 0; i < parts.length - 1; i++) {
            currentPath += (currentPath ? '/' : '') + parts[i]
            if (!createdDirs.has(currentPath)) {
              try {
                pyodide.FS.mkdir(currentPath)
                createdDirs.add(currentPath)
              } catch {
                // Diretório já existe
              }
            }
          }
        }
        
        // Escrever arquivo
        try {
          pyodide.FS.writeFile(cleanPath, content)
        } catch (error) {
          console.error(`Failed to write file ${cleanPath}:`, error)
        }
      }

      // Obter código do entry point
      const mainCode = files[entryPoint]
      if (!mainCode) {
        throw new Error(`Entry point not found: ${entryPoint}`)
      }

      // Load packages from imports if available
      if (pyodide.loadPackagesFromImports) {
        try {
          await pyodide.loadPackagesFromImports(mainCode)
        } catch {
          // Ignore package loading errors
        }
      }

      // Execute with timeout
      const timeoutPromise = new Promise<never>((_, reject) => {
        setTimeout(() => reject(new Error('Execution timeout')), this.options.timeout)
      })

      const execPromise = pyodide.runPythonAsync(mainCode)

      await Promise.race([execPromise, timeoutPromise])

    } catch (error) {
      exitCode = 1
      const errorMsg = error instanceof Error ? error.message : String(error)
      
      if (!stderr.includes(errorMsg)) {
        stderr += (stderr ? '\n' : '') + errorMsg
      }
    }

    const executionTime = performance.now() - startTime

    return {
      stdout: stdout.trimEnd(),
      stderr: stderr.trimEnd(),
      exitCode,
      executionTime,
    }
  }

  async interrupt(): Promise<void> {
    this.isInterrupted = true
    if (pyodideInstance) {
      const interruptBuffer = new Int32Array(new SharedArrayBuffer(4))
      interruptBuffer[0] = 2
      pyodideInstance.setInterruptBuffer(interruptBuffer)
    }
  }

  dispose(): void {
    // Pyodide é singleton global, não dispose individual
  }
}

