      const rubyFS: WASIFS = {}
      for (const [path, content] of Object.entries(files)) {
        rubyFS[path] = {
          path,
          timestamps: {
            access: new Date(),
            modification: new Date(),
            change: new Date(),
          },
          mode: 'string',
          content,
        }
      }

      this.options.onProgress?.('Running Ruby code...')
      const runResult = await this.runRuby(rubyUrl, rubyFS, entryPoint, stdin)
      
