/**
 * WASI Clocks Interface (wasi:clocks)
 * Component Model standard interface for time operations
 * 
 * @see https://github.com/WebAssembly/WASI/blob/main/preview2/clocks.wit
 */

import type { Datetime, Pollable } from '../types.js'

export interface WasiWallClock {
  'now': () => Datetime
  'resolution': () => Datetime
}

export interface WasiMonotonicClock {
  'now': () => bigint
  'resolution': () => bigint
  'subscribe-instant': (when: bigint) => Pollable
  'subscribe-duration': (duration: bigint) => Pollable
}

export function createWallClock(): WasiWallClock {
  return {
    'now': () => {
      const ms = Date.now()
      return {
        seconds: BigInt(Math.floor(ms / 1000)),
        nanoseconds: (ms % 1000) * 1_000_000,
      }
    },
    'resolution': () => ({
      seconds: 0n,
      nanoseconds: 1_000_000, // 1ms resolution
    }),
  }
}

export function createMonotonicClock(createPollable: () => Pollable): WasiMonotonicClock {
  return {
    'now': () => BigInt(Math.floor(performance.now() * 1_000_000)),
    'resolution': () => 1_000n, // 1μs
    'subscribe-instant': (when: bigint) => createPollable(),
    'subscribe-duration': (duration: bigint) => createPollable(),
  }
}

/**
 * WASI I/O Interface (wasi:io)
 * Component Model standard interface for I/O operations
 * 
 * @see https://github.com/WebAssembly/WASI/blob/main/preview2/io.wit
 */

import type { InputStream, OutputStream, Pollable, StreamError } from '../types.js'

export interface WasiStreams {
  'read': (stream: InputStream, len: bigint) => Uint8Array | StreamError
  'write': (stream: OutputStream, contents: Uint8Array) => bigint | StreamError
  'blocking-read': (stream: InputStream, len: bigint) => Uint8Array | StreamError
  'blocking-write': (stream: OutputStream, contents: Uint8Array) => bigint | StreamError
  'subscribe-to-input-stream': (stream: InputStream) => Pollable
  'subscribe-to-output-stream': (stream: OutputStream) => Pollable
}

export interface WasiPoll {
  'poll': (pollables: Array<Pollable>) => Array<number>
}

interface StreamHandler {
  type: 'input' | 'output'
  onWrite?: (data: Uint8Array) => void
  onRead?: (len: number) => Uint8Array
}

export function createStreams(
  streams: Map<number, StreamHandler>,
  createPollable: () => Pollable
): WasiStreams {
  return {
    'read': (stream: InputStream, len: bigint) => {
      const handler = streams.get(stream)
      if (!handler || handler.type !== 'input') {
        return { tag: 'closed' } as StreamError
      }
      return handler.onRead ? handler.onRead(Number(len)) : new Uint8Array(0)
    },

    'write': (stream: OutputStream, contents: Uint8Array) => {
      const handler = streams.get(stream)
      if (!handler || handler.type !== 'output') {
        return { tag: 'closed' } as StreamError
      }
      if (handler.onWrite) {
        handler.onWrite(contents)
      }
      return BigInt(contents.length)
    },

    'blocking-read': (stream: InputStream, len: bigint) => {
      const handler = streams.get(stream)
      if (!handler || handler.type !== 'input') {
        return { tag: 'closed' } as StreamError
      }
      return handler.onRead ? handler.onRead(Number(len)) : new Uint8Array(0)
    },

    'blocking-write': (stream: OutputStream, contents: Uint8Array) => {
      const handler = streams.get(stream)
      if (!handler || handler.type !== 'output') {
        return { tag: 'closed' } as StreamError
      }
      if (handler.onWrite) {
        handler.onWrite(contents)
      }
      return BigInt(contents.length)
    },

    'subscribe-to-input-stream': (stream: InputStream) => createPollable(),
    'subscribe-to-output-stream': (stream: OutputStream) => createPollable(),
  }
}

export function createPoll(): WasiPoll {
  return {
    'poll': (pollables: Array<Pollable>) => {
      // All pollables are immediately ready in this simplified implementation
      return pollables.map((_, i) => i)
    },
  }
}

import type { CodeRunner, RunnerResult, RunnerOptions, FileMap } from './types'
import type { WASIFS } from '@runno/wasi'
import { createWatEnvironment } from './wat-env-bindings'
import { createWasiStdinReader } from './wasi-stdin'
import { runtimeValueToString } from './runtime-value-to-string'

// Load wabt from local public assets (managed by update-wasm.mjs script)
let wabtInstance: any = null

async function getWabtInstance(): Promise<any> {
  if (wabtInstance) {
    return wabtInstance
  }

  try {
    // Load wabt from local assets if not already loaded
    if (typeof window !== 'undefined' && !(window as any).WabtModule) {
      await new Promise((resolve, reject) => {
        const script = document.createElement('script')
        script.src = '/langs/wabt.js'
        script.onload = resolve
        script.onerror = () => reject(new Error('Failed to load wabt.js'))
        document.head.appendChild(script)
      })
    }

    // Initialize wabt
    const WabtModule = (window as any).WabtModule
    if (!WabtModule) {
      throw new Error('WabtModule not found after script load')
    }
    
    wabtInstance = await WabtModule()
    return wabtInstance
  } catch (error) {
    console.error('[WatRunner] Failed to load/initialize wabt:', error)
    throw new Error(`Failed to initialize WebAssembly compiler: ${error instanceof Error ? error.message : String(error)}`)
  }
}

export class WatRunner implements CodeRunner {
  private isInterrupted = false
  private readonly options: RunnerOptions

  constructor(options: RunnerOptions = {}) {
    this.options = {
      timeout: options.timeout || 30000,
      memoryLimit: options.memoryLimit || 64 * 1024 * 1024,
      onRequestInput: options.onRequestInput,
      onProgress: options.onProgress,
    }
  }

  private async compileWatToWasm(watCode: string, filename: string = 'program.wat'): Promise<Uint8Array> {
    try {
      const wabtModule = await getWabtInstance()
      
      // Parse WAT to a module using parseWat
      const wasmModule = wabtModule.parseWat(filename, watCode, {
        exceptions: true,
        mutable_globals: true,
        sat_float_to_int: true,
        sign_extension: true,
        simd: true,
        threads: true,
        multi_value: true,
        tail_call: true,
        bulk_memory: true,
        reference_types: true,
      })

      // Validate the module
      wasmModule.validate()

      // Convert to binary WASM
      const binaryOutput = wasmModule.toBinary({
        log: false,
        write_debug_names: true,
      })

      // Clean up
      wasmModule.destroy()

      // Return the buffer (Uint8Array)
      return binaryOutput.buffer
    } catch (error) {
      // Improve error message for WAT compilation errors
      console.error(`[WatRunner] Compilation error in ${filename}:`, error)
      if (error instanceof Error) {
        throw new Error(`WAT compilation failed in ${filename}: ${error.message}`)
      }
      throw new Error(`WAT compilation failed in ${filename}: ${String(error)}`)
    }
  }

  /**
   * Compile all WAT files to WASM binaries
   * This is necessary when WAT files import each other
   */
  private async compileAllWatFiles(files: FileMap): Promise<Map<string, Uint8Array>> {
    const compiledModules = new Map<string, Uint8Array>()
    const watFiles = Object.entries(files).filter(([path]) => path.endsWith('.wat'))

    this.options.onProgress?.(`Compiling ${watFiles.length} WAT file(s)...`)

    // Compile all WAT files to WASM
    for (const [path, watCode] of watFiles) {
      try {
        console.log(`[WatRunner] Compiling ${path}...`)
        const wasmBinary = await this.compileWatToWasm(watCode, path)
        compiledModules.set(path, wasmBinary)
        
        // Also store the .wasm version of the filename
        const wasmPath = path.replace(/\.wat$/, '.wasm')
        compiledModules.set(wasmPath, wasmBinary)
        
        console.log(`[WatRunner] Compiled ${path} -> ${wasmBinary.length} bytes`)
      } catch (error) {
        console.error(`[WatRunner] Failed to compile ${path}:`, error)
        throw error
      }
    }

    return compiledModules
  }

  /**
   * Create a WASI filesystem with all compiled WASM modules
   */
  private createWASIFilesystem(
    files: FileMap,
    compiledModules: Map<string, Uint8Array>
  ): WASIFS {
    const wasmFS: WASIFS = {}

    // Add all source files (non-WAT files)
    for (const [path, content] of Object.entries(files)) {
      if (!path.endsWith('.wat')) {
        wasmFS[path] = {
          path,
          timestamps: {
            access: new Date(),
            modification: new Date(),
            change: new Date(),
          },
          mode: 'string',
          content,
        }
      }
    }

    // Add all compiled WASM modules as binary files
    for (const [path, binary] of compiledModules.entries()) {
      wasmFS[path] = {
        path,
        timestamps: {
          access: new Date(),
          modification: new Date(),
          change: new Date(),
        },
        mode: 'binary',
        content: binary,
      }
    }

    return wasmFS
  }

  private async runWasm(
    wasmBinary: Uint8Array,
    wasmFS: WASIFS,
    compiledModules: Map<string, Uint8Array> = new Map(),
    stdin?: string
  ): Promise<{ exitCode: number; stdout: string; stderr: string }> {
    let wasmStdout = ''
    let wasmStderr = ''

    try {
      // Create shared memory for environment
      const sharedMemory = new WebAssembly.Memory({ initial: 256, maximum: 512 })

      // Create comprehensive environment using wat-env-bindings
      const envBindings = createWatEnvironment(
        (text: string) => {
          wasmStdout += text
          console.log('[WAT stdout]', text)
        },
        (text: string) => {
          wasmStderr += text
          console.error('[WAT stderr]', text)
        },
        sharedMemory
      )

      // Ensure importObject is properly structured
      const importObject: Record<string, any> = { ...envBindings }
      
      console.log('[WatRunner] Import object keys:', Object.keys(importObject))
      console.log('[WatRunner] env is object:', typeof importObject.env === 'object' && importObject.env !== null)

      // First, instantiate all imported modules
      for (const [moduleName, moduleBytes] of compiledModules.entries()) {
        try {
          console.log(`[WatRunner] Pre-instantiating module: ${moduleName}`)
          
          // Recursively instantiate with the growing import object
          const instantiated = await WebAssembly.instantiate(
            moduleBytes,
            importObject as WebAssembly.Imports
          ) as unknown as WebAssembly.WebAssemblyInstantiatedSource

          const exported = instantiated.instance.exports

          if (!exported) {
            console.warn(`[WatRunner] Module ${moduleName} has no exports`)
            continue
          }

          // Add exports using multiple name variations
          const variations = new Set<string>()

          // Full path without extension: /wat/math.wat -> /wat/math
          variations.add(moduleName.replace(/\.(wat|wasm)$/, ''))

          // Just filename without extension: /wat/math.wat -> math
          const fileName = moduleName.split('/').pop()?.replace(/\.(wat|wasm)$/, '')
          if (fileName) {
            variations.add(fileName)
          }

          // Register all variations
          for (const name of variations) {
            importObject[name] = exported
            console.log(`[WatRunner] Registered import: "${name}" with ${Object.keys(exported).length} exports`)
          }
        } catch (error) {
          console.error(`[WatRunner] Failed to preload module ${moduleName}:`, error)
          throw new Error(`Failed to load dependency ${moduleName}: ${error instanceof Error ? error.message : String(error)}`)
        }
      }

      console.log('[WatRunner] Available imports:', Object.keys(importObject))

      // Now instantiate the main module with all imports available
      const { WASI } = await import('@runno/wasi')
      
      const wasi = new WASI({
        args: ['program.wasm'],
        env: {},
        fs: wasmFS,
        stdout: (out: string) => { wasmStdout += out },
        stderr: (err: string) => { wasmStderr += err },
      })

      // The pinned WASI string callback truncates encoded input to each iovec.
      // Share a byte cursor across both namespaces; retain native reads for all
      // other descriptors and every other native WASI operation.
      const readStdin = createWasiStdinReader(stdin ?? '', () => wasi.memory)
      const wasiImports = wasi.getImportObject()
      for (const namespace of Object.values(wasiImports)) {
        const fdRead = namespace.fd_read.bind(namespace)
        namespace.fd_read = (fd, pointer, length, result) =>
          fd === 0 ? readStdin(pointer, length, result) : fdRead(fd, pointer, length, result)
      }
      Object.assign(importObject, wasiImports)

      // Instantiate the main module with imports
      const instantiateResult = await WebAssembly.instantiate(
        wasmBinary as BufferSource,
        importObject as WebAssembly.Imports
      )
      const instantiatedSource = instantiateResult as WebAssembly.WebAssemblyInstantiatedSource
      
      // Check if module has _start (WASI command) or _initialize (WASI reactor)
      const exports = instantiatedSource.instance.exports
      const memory = exports.memory instanceof WebAssembly.Memory ? exports.memory : sharedMemory
      let exitCode = 0
      
      console.log('[WatRunner] Module exports:', Object.keys(exports))
      
      if ('_start' in exports && typeof exports._start === 'function') {
        // It's a WASI command - run it
        console.log('[WatRunner] Running WASI command with _start')
        exitCode = wasi.start(instantiatedSource, { memory }).exitCode
      } else if ('_initialize' in exports && typeof exports._initialize === 'function') {
        // It's a WASI reactor - initialize it
        console.log('[WatRunner] Initializing WASI reactor with _initialize')
        wasi.initialize(instantiatedSource, { memory })
        
        // If there's a main function, call it
        if ('main' in exports && typeof exports.main === 'function') {
          console.log('[WatRunner] Calling main function after _initialize')
          const result: unknown = exports.main()
          exitCode = typeof result === 'number' ? result : 0
        }
      } else if ('main' in exports && typeof exports.main === 'function') {
        // Module has main but no WASI initialization
        wasi.initialize(instantiatedSource, { memory })
        console.log('[WatRunner] Calling main function')
        
        try {
          const result: unknown = exports.main()
          
          // The result might be the value to print
          if (typeof result === 'number') {
            wasmStdout += result.toString() + '\n'
            exitCode = 0
          } else if (result !== undefined) {
            wasmStdout += runtimeValueToString(result) + '\n'
            exitCode = 0
          } else {
            // Function executed successfully but returned nothing
            exitCode = 0
          }
          
          console.log('[WatRunner] Main function returned:', result)
          console.log('[WatRunner] Captured stdout:', wasmStdout)
          console.log('[WatRunner] Captured stderr:', wasmStderr)
        } catch (error) {
          console.error('[WatRunner] Error calling main:', error)
          throw error
        }
      } else {
        // No standard entry point - this might be a pure library module
        wasi.initialize(instantiatedSource, { memory })
        // Try to find any exported function that looks like an entry point
        const exportKeys = Object.keys(exports)
        const callableFuncs = exportKeys.filter(key => typeof exports[key] === 'function')
        
        if (callableFuncs.length === 0) {
          throw new Error(`Module has no callable functions. Exports: ${exportKeys.join(', ')}`)
        }
        
        // If there's exactly one function, call it
        if (callableFuncs.length === 1) {
          const funcName: string = callableFuncs[0] as string
          console.log(`[WatRunner] Calling single exported function: ${funcName}`)
          const entryPoint = exports[funcName]
          if (typeof entryPoint !== 'function') {
            throw new Error(`Exported entry point is not callable: ${funcName}`)
          }
          const result: unknown = entryPoint()
          if (typeof result === 'number') {
            wasmStdout += result.toString() + '\n'
          }
          exitCode = 0
        } else {
          throw new Error(`Module has no standard entry point (_start, _initialize, or main). Available functions: ${callableFuncs.join(', ')}`)
        }
      }

      return {
        exitCode,
        stdout: wasmStdout,
        stderr: wasmStderr,
      }
    } catch (error) {
      console.error('[WatRunner] WASM execution error:', error)
      
      let errorMessage = String(error)
      if (error instanceof Error) {
        errorMessage = error.message
      } else if (typeof error === 'object' && error !== null) {
        errorMessage = JSON.stringify(error, null, 2)
      }
      
      throw new Error(`WASM execution failed: ${errorMessage}`)
    }
  }

  async execute(code: string, stdin?: string): Promise<RunnerResult> {
    const startTime = performance.now()
    
    try {
      this.isInterrupted = false

      this.options.onProgress?.('Compiling WAT to WASM...')
      
      // Compile WAT to WASM binary
      const wasmBinary = await this.compileWatToWasm(code, 'program.wat')
      
      if (!wasmBinary || wasmBinary.length === 0) {
        throw new Error('WAT compilation produced empty binary')
      }

      const wasmFS: WASIFS = {}

      this.options.onProgress?.('Running WebAssembly...')
      const runResult = await this.runWasm(wasmBinary, wasmFS, undefined, stdin)
      
      const executionTime = performance.now() - startTime
      
      return {
        stdout: runResult.stdout.trimEnd(),
        stderr: runResult.stderr.trimEnd(),
        exitCode: runResult.exitCode,
        executionTime,
      }
    } catch (error) {
      const executionTime = performance.now() - startTime
      
      console.error('[WatRunner] execute caught error:', error)
      
      let errorMessage = 'Unknown error'
      if (error instanceof Error) {
        errorMessage = error.message
        if (error.stack) {
          console.error('WatRunner execute error stack:', error.stack)
        }
      } else if (typeof error === 'object' && error !== null) {
        errorMessage = JSON.stringify(error, null, 2)
      } else {
        errorMessage = String(error)
      }
      
      return {
        stdout: '',
        stderr: errorMessage,
        exitCode: 1,
        executionTime,
      }
    }
  }

  async executeWithFiles(entryPoint: string, files: FileMap, stdin?: string): Promise<RunnerResult> {
    const startTime = performance.now()
    
    try {
      this.isInterrupted = false

      // Get the WAT code from the entry point
      const watCode = files[entryPoint]
      if (!watCode) {
        throw new Error(`Entry point file not found: ${entryPoint}`)
      }

      // Compile all WAT files to WASM (handles imports)
      const compiledModules = await this.compileAllWatFiles(files)

      // Get the main module binary
      const mainBinary = compiledModules.get(entryPoint)
      if (!mainBinary) {
        throw new Error(`Failed to compile entry point: ${entryPoint}`)
      }

      // Create filesystem with all compiled modules and other files
      const wasmFS = this.createWASIFilesystem(files, compiledModules)

      // Remove the main module from compiledModules to avoid re-instantiation
      const importModules = new Map(compiledModules)
      importModules.delete(entryPoint)
      
      // Also try removing the .wasm version
      const wasmPath = entryPoint.replace(/\.wat$/, '.wasm')
      importModules.delete(wasmPath)

      this.options.onProgress?.('Running WebAssembly...')
      const runResult = await this.runWasm(mainBinary, wasmFS, importModules, stdin)
      
      const executionTime = performance.now() - startTime
      
      return {
        stdout: runResult.stdout.trimEnd(),
        stderr: runResult.stderr.trimEnd(),
        exitCode: runResult.exitCode,
        executionTime,
      }
    } catch (error) {
      const executionTime = performance.now() - startTime
      
      console.error('[WatRunner] executeWithFiles caught error:', error)
      
      let errorMessage = 'Unknown error'
      if (error instanceof Error) {
        errorMessage = error.message
        if (error.stack) {
          console.error('WatRunner executeWithFiles error stack:', error.stack)
        }
      } else if (typeof error === 'object' && error !== null) {
        errorMessage = JSON.stringify(error, null, 2)
      } else {
        errorMessage = String(error)
      }
      
      return {
        stdout: '',
        stderr: errorMessage,
        exitCode: 1,
        executionTime,
      }
    }
  }

  async interrupt(): Promise<void> {
    this.isInterrupted = true
  }

  dispose(): void {
    // Cleanup if needed
  }
}

import type { LayoutNode, LeafPanel, SplitNode, DisplayConfig, PanelType, EditorInstance } from "./types"

/**
 * Immutable-ish helpers for navigating and mutating a splitter tree.
 * Designed to be called from inside `useImmer` setLocalData drafts.
 */

let panelIdCounter = 0
function nextPanelId(type: PanelType): string {
  panelIdCounter += 1
  return `${type}-${Date.now()}-${panelIdCounter}`
}

let splitIdCounter = 0
function nextSplitId(): string {
  splitIdCounter += 1
  return `split-${Date.now()}-${splitIdCounter}`
}

// ---------------------------------------------------------------------------
// Traversal

export function isLeaf(node: LayoutNode): node is LeafPanel {
  return node.kind === "leaf"
}

export function isSplit(node: LayoutNode): node is SplitNode {
  return node.kind === "split"
}

/**
 * Flatten the tree to all leaf panels (left-to-right / top-to-bottom).
 */
export function getAllLeaves(node: LayoutNode): LeafPanel[] {
  if (isLeaf(node)) return [node]
  const out: LeafPanel[] = []
  for (const child of node.children) {
    out.push(...getAllLeaves(child))
  }
  return out
}

/**
 * Walk the tree looking for a leaf with the given id.
 */
export function findLeaf(node: LayoutNode, leafId: string): LeafPanel | undefined {
  if (isLeaf(node)) {
    return node.id === leafId ? node : undefined
  }
  for (const child of node.children) {
    const hit = findLeaf(child, leafId)
    if (hit) return hit
  }
  return undefined
}

/**
 * Locate the path from root to the target node id (leaf or split).
 * Returns the chain of indices to walk into `children` arrays.
 */
function findPath(node: LayoutNode, targetId: string, acc: number[] = []): number[] | undefined {
  if (node.id === targetId || (isLeaf(node) && node.id === targetId)) {
    return acc
  }
  if (isSplit(node)) {
    for (let i = 0; i < node.children.length; i += 1) {
      const child = node.children[i]
      if (!child) continue
      const sub = findPath(child, targetId, [...acc, i])
      if (sub) return sub
    }
  }
  return undefined
}

// ---------------------------------------------------------------------------
// Mutation helpers (work on Immer drafts — direct field assignment is fine)

/**
 * Apply new percent sizes to the split identified by `splitId`. No-op if not found.
 */
export function setSplitSizes(root: LayoutNode, splitId: string, sizes: number[]): void {
  if (isSplit(root) && root.id === splitId) {
    if (root.children.length === sizes.length) {
      root.sizes = sizes.map(s => Math.max(0, s))
    }
    return
  }
  if (isSplit(root)) {
    for (const child of root.children) {
      setSplitSizes(child, splitId, sizes)
    }
  }
}

/**
 * Remove the leaf with id `leafId` from the tree. If its parent split is left
 * with a single child, the split collapses (the parent is replaced by that
 * child in the grandparent). If the leaf is the root, returns a fallback
 * empty placeholder (no-op leaves should be avoided by callers).
 *
 * Returns the new root reference (callers should assign it back).
 */
export function removeLeaf(root: LayoutNode, leafId: string): LayoutNode | null {
  if (isLeaf(root)) {
    return root.id === leafId ? null : root
  }

  const newChildren: LayoutNode[] = []
  const keptSizes: number[] = []
  for (let i = 0; i < root.children.length; i += 1) {
    const child = root.children[i]
    if (!child) continue
    if (isLeaf(child)) {
      if (child.id === leafId) continue
      newChildren.push(child)
      keptSizes.push(root.sizes[i] ?? 0)
    } else {
      const updated = removeLeaf(child, leafId)
      if (updated == null) continue
      newChildren.push(updated)
      keptSizes.push(root.sizes[i] ?? 0)
    }
  }

  if (newChildren.length === 0) return null
  if (newChildren.length === 1) return newChildren[0]

  // Re-normalize sizes to sum to 100.
  const total = keptSizes.reduce((acc, s) => acc + s, 0)
  const normalized = total > 0
    ? keptSizes.map(s => (s / total) * 100)
    : keptSizes.map(() => 100 / keptSizes.length)

  return {
    kind: "split",
    id: root.id,
    direction: root.direction,
    sizes: normalized,
    children: newChildren,
  }
}

/**
 * Add a fresh panel by splitting the target leaf in two. The new leaf takes
 * `newSize` percent of the existing leaf's space.
 *
 * Returns the new root reference.
 */
export function splitLeafWithPanel(
  root: LayoutNode,
  targetLeafId: string,
  newPanelType: PanelType,
  direction: "horizontal" | "vertical",
  position: "before" | "after" = "after",
  newSize = 30,
): LayoutNode {
  const newLeaf: LeafPanel =
    newPanelType === "full-editor" || newPanelType === "focus-editor"
      ? { kind: "leaf", id: nextPanelId(newPanelType), type: newPanelType, editorInstance: "multiple" }
      : { kind: "leaf", id: nextPanelId(newPanelType), type: newPanelType }

  function visit(node: LayoutNode): LayoutNode {
    if (isLeaf(node)) {
      if (node.id !== targetLeafId) return node
      const children = position === "after" ? [node, newLeaf] : [newLeaf, node]
      const sizes = position === "after" ? [100 - newSize, newSize] : [newSize, 100 - newSize]
      return {
        kind: "split",
        id: nextSplitId(),
        direction,
        sizes,
        children,
      }
    }
    return { ...node, children: node.children.map(visit) }
  }

  return visit(root)
}

/**
 * Add a panel by splitting the entire root. Used when the user just wants to
 * append a panel without picking a specific leaf to host the split.
 */
export function addPanelAtRoot(
  root: LayoutNode,
  panelType: PanelType,
  direction: "horizontal" | "vertical" = "horizontal",
  newSize = 30,
): LayoutNode {
  const newLeaf: LeafPanel =
    panelType === "full-editor" || panelType === "focus-editor"
      ? { kind: "leaf", id: nextPanelId(panelType), type: panelType, editorInstance: "multiple" }
      : { kind: "leaf", id: nextPanelId(panelType), type: panelType }

  return {
    kind: "split",
    id: nextSplitId(),
    direction,
    sizes: [100 - newSize, newSize],
    children: [root, newLeaf],
  }
}

/**
 * Toggle a leaf's editor-instance flag between "multiple" and "unique".
 * Only meaningful for "full-editor" / "focus-editor" leaves.
 */
export function toggleLeafEditorInstance(root: LayoutNode, leafId: string): void {
  const leaf = findLeaf(root, leafId)
  if (!leaf) return
  if (leaf.type !== "full-editor" && leaf.type !== "focus-editor") return
  const next: EditorInstance = leaf.editorInstance === "unique" ? "multiple" : "unique"
  leaf.editorInstance = next
}

/**
 * Re-dock an existing leaf next to a target leaf.
 *
 * Used by the drag-and-drop quadrant docking: the user grabs a leaf and drops
 * it on one of the four edges of another leaf. The source leaf is first
 * removed (parents collapse when single-child), then re-inserted as a fresh
 * split sibling of the target.
 *
 * Returns the new root reference. If `sourceLeafId === targetLeafId` or either
 * id is missing, the tree is returned unchanged.
 */
export function moveLeafRelativeTo(
  root: LayoutNode,
  sourceLeafId: string,
  targetLeafId: string,
  position: "top" | "right" | "bottom" | "left",
  newSize = 30,
): LayoutNode {
  if (sourceLeafId === targetLeafId) return root
  const source = findLeaf(root, sourceLeafId)
  if (!source) return root
  // Snapshot the source leaf so we can re-insert it after removal collapses
  // any parents.
  const sourceSnapshot: LeafPanel = {
    kind: "leaf",
    id: source.id,
    type: source.type,
    ...(source.editorInstance ? { editorInstance: source.editorInstance } : {}),
  }

  const removed = removeLeaf(root, sourceLeafId)
  if (removed == null) return root

  // Target may have been collapsed during removal; re-find on the new tree.
  const target = findLeaf(removed, targetLeafId)
  if (!target) return root

  const direction: "horizontal" | "vertical" =
    position === "left" || position === "right" ? "horizontal" : "vertical"
  const placeAfter = position === "right" || position === "bottom"

  function visit(node: LayoutNode): LayoutNode {
    if (isLeaf(node)) {
      if (node.id !== targetLeafId) return node
      const children = placeAfter ? [node, sourceSnapshot] : [sourceSnapshot, node]
      const sizes = placeAfter ? [100 - newSize, newSize] : [newSize, 100 - newSize]
      return {
        kind: "split",
        id: nextSplitId(),
        direction,
        sizes,
        children,
      }
    }
    return { ...node, children: node.children.map(visit) }
  }

  return visit(removed)
}

// ---------------------------------------------------------------------------
// Display-level helpers

export function displayHasPanelType(display: DisplayConfig, type: PanelType): boolean {
  return getAllLeaves(display.root).some(p => p.type === type)
}

export function displayHasUniqueEditor(display: DisplayConfig): boolean {
  return getAllLeaves(display.root).some(
    p => (p.type === "full-editor" || p.type === "focus-editor") && p.editorInstance === "unique",
  )
}

export function findUniqueEditorLeaf(display: DisplayConfig): LeafPanel | undefined {
  return getAllLeaves(display.root).find(
    p => (p.type === "full-editor" || p.type === "focus-editor") && p.editorInstance === "unique",
  )
}

"use client"

import { useEffect, useRef, useCallback, useImperativeHandle, forwardRef, useState } from "react"
import { Terminal } from "@xterm/xterm"
import { FitAddon } from "@xterm/addon-fit"
import { WebglAddon } from "@xterm/addon-webgl"
import { SearchAddon } from "@xterm/addon-search"
import { WebLinksAddon } from "@xterm/addon-web-links"
import { ClipboardAddon } from "@xterm/addon-clipboard"
import { Unicode11Addon } from "@xterm/addon-unicode11"
import "@xterm/xterm/css/xterm.css"
import { useTheme } from "next-themes"
import { X, ChevronUp, ChevronDown } from "lucide-react"
import { LinkConfirmDialog } from "../dialogs/link-confirm-dialog"

interface XTermTerminalProps {
  output: string
  isExecuting: boolean
  onClear?: () => void
}

export interface XTermTerminalHandle {
  requestInput: () => Promise<string>
  write: (text: string) => void
  clear: () => void
  search: (term: string, searchOptions?: { incremental?: boolean }) => boolean
  searchNext: () => boolean
  searchPrevious: () => boolean
  clearSearch: () => void
}

const darkTheme = {
  background: "#0a0a0a",
  foreground: "#e5e7eb",
  cursor: "#60a5fa",
  black: "#1f2937",
  red: "#ef4444",
  green: "#10b981",
  yellow: "#f59e0b",
  blue: "#3b82f6",
  magenta: "#a855f7",
  cyan: "#06b6d4",
  white: "#e5e7eb",
  brightBlack: "#4b5563",
  brightRed: "#f87171",
  brightGreen: "#34d399",
  brightYellow: "#fbbf24",
  brightBlue: "#60a5fa",
  brightMagenta: "#c084fc",
  brightCyan: "#22d3ee",
  brightWhite: "#f9fafb",
}

const lightTheme = {
  background: "#ffffff",
  foreground: "#1f2937",
  cursor: "#3b82f6",
  black: "#374151",
  red: "#ef4444",
  green: "#10b981",
  yellow: "#f59e0b",
  blue: "#3b82f6",
  magenta: "#a855f7",
  cyan: "#06b6d4",
  white: "#6b7280",
  brightBlack: "#9ca3af",
  brightRed: "#f87171",
  brightGreen: "#34d399",
  brightYellow: "#fbbf24",
  brightBlue: "#60a5fa",
  brightMagenta: "#c084fc",
  brightCyan: "#22d3ee",
  brightWhite: "#1f2937",
}

export const XTermTerminal = forwardRef<XTermTerminalHandle, XTermTerminalProps>(
  function XTermTerminal({ output, isExecuting }, ref) {
    const terminalRef = useRef<HTMLDivElement>(null)
    const xtermRef = useRef<Terminal | null>(null)
    const fitAddonRef = useRef<FitAddon | null>(null)
    const searchAddonRef = useRef<SearchAddon | null>(null)
    const inputBufferRef = useRef<string>("")
    const inputResolverRef = useRef<((value: string) => void) | null>(null)
    const [showSearch, setShowSearch] = useState(false)
    const [searchTerm, setSearchTerm] = useState("")
    const [linkConfirmDialog, setLinkConfirmDialog] = useState<{ open: boolean; url: string }>({
      open: false,
      url: "",
    })
    const { resolvedTheme } = useTheme()
    const isDarkMode = resolvedTheme === "dark"

    // Expose methods via ref
    useImperativeHandle(ref, () => ({
      requestInput: async (): Promise<string> => {
        return new Promise((resolve) => {
          if (!xtermRef.current) {
            resolve("")
            return
          }
          
          // Set up the resolver
          inputResolverRef.current = resolve
          inputBufferRef.current = ""
        })
      },
      write: (text: string) => {
        if (xtermRef.current) {
          xtermRef.current.write(text)
        }
      },
      clear: () => {
        if (xtermRef.current) {
          xtermRef.current.clear()
        }
      },
      search: (term: string, searchOptions?: { incremental?: boolean }) => {
        if (searchAddonRef.current) {
          return searchAddonRef.current.findNext(term, searchOptions)
        }
        return false
      },
      searchNext: () => {
        if (searchAddonRef.current) {
          return searchAddonRef.current.findNext('')
        }
        return false
      },
      searchPrevious: () => {
        if (searchAddonRef.current) {
          return searchAddonRef.current.findPrevious('')
        }
        return false
      },
      clearSearch: () => {
        if (searchAddonRef.current) {
          searchAddonRef.current.clearDecorations()
        }
      },
    }))

  const fitTerminal = useCallback(() => {
    fitAddonRef.current?.fit()
  }, [])

  useEffect(() => {
    if (!terminalRef.current || xtermRef.current) return

    const terminal = new Terminal({
      cursorBlink: true,
      fontSize: 13,
      fontFamily: 'Menlo, Monaco, "Courier New", monospace',
      theme: isDarkMode ? darkTheme : lightTheme,
      rows: 20,
      scrollback: 1000,
      disableStdin: false, // Enable input for interactive mode
      allowProposedApi: true, // Required for clipboard addon
    })
    xtermRef.current = terminal

    const fitAddon = new FitAddon()
    fitAddonRef.current = fitAddon
    terminal.loadAddon(fitAddon)

    // Load search addon for Ctrl+F functionality
    const searchAddon = new SearchAddon()
    searchAddonRef.current = searchAddon
    terminal.loadAddon(searchAddon)

    // Load web links addon for clickable URLs with confirmation
    const webLinksAddon = new WebLinksAddon((event, uri) => {
      event.preventDefault()
      setLinkConfirmDialog({ open: true, url: uri })
    })
    terminal.loadAddon(webLinksAddon)

    // Load clipboard addon for better copy/paste support
    const clipboardAddon = new ClipboardAddon()
    terminal.loadAddon(clipboardAddon)

    // Load unicode11 addon for better emoji and special character support
    const unicode11Addon = new Unicode11Addon()
    terminal.loadAddon(unicode11Addon)
    terminal.unicode.activeVersion = '11' // Activate Unicode 11

    // Defer open to next frame so container is visible and has dimensions.
    // xterm's renderer crashes with "dimensions is undefined" if the
    // container has 0 width/height when open() is called.
    const openFrame = requestAnimationFrame(() => {
      if (!terminalRef.current) return
      try {
        terminal.open(terminalRef.current)
      } catch (e) {
        console.warn('[XTermTerminal] Failed to open terminal:', e)
        return
      }

      // Try to load WebGL addon for better performance
      try {
        const webglAddon = new WebglAddon()
        terminal.loadAddon(webglAddon)
      } catch (e) {
        // WebGL not supported, fallback to canvas renderer
        console.warn('WebGL addon could not be loaded, using canvas renderer')
      }

      // Delay fit to ensure container has dimensions
      requestAnimationFrame(() => {
        fitTerminal()
      })
    })

    // Handle keyboard shortcuts for copy/paste
    terminal.attachCustomKeyEventHandler((event) => {
      // Ctrl+F / Cmd+F - Open search
      if ((event.ctrlKey || event.metaKey) && event.key === 'f' && event.type === 'keydown') {
        event.preventDefault()
        setShowSearch(true)
        return false
      }
      // Escape - Close search
      if (event.key === 'Escape' && showSearch && event.type === 'keydown') {
        setShowSearch(false)
        searchAddonRef.current?.clearDecorations()
        return false
      }
      // Allow default browser behavior for copy (Ctrl+C / Cmd+C) when text is selected
      if ((event.ctrlKey || event.metaKey) && event.key === 'c' && terminal.hasSelection()) {
        return false // Let browser handle copy
      }
      // Allow default browser behavior for paste (Ctrl+V / Cmd+V)
      if ((event.ctrlKey || event.metaKey) && event.key === 'v') {
        return false // Let browser handle paste
      }
      return true
    })

    // Handle input from user
    terminal.onData((data) => {
      if (!inputResolverRef.current) return
      
      const code = data.charCodeAt(0)
      
      // Enter key
      if (code === 13) {
        terminal.write('\r\n')
        const input = inputBufferRef.current
        inputBufferRef.current = ""
        inputResolverRef.current(input)
        inputResolverRef.current = null
      }
      // Backspace
      else if (code === 127 || code === 8) {
        if (inputBufferRef.current.length > 0) {
          inputBufferRef.current = inputBufferRef.current.slice(0, -1)
          terminal.write('\b \b')
        }
      }
      // Regular character
      else if (code >= 32) {
        inputBufferRef.current += data
        terminal.write(data)
      }
    })

    window.addEventListener("resize", fitTerminal)

    return () => {
      cancelAnimationFrame(openFrame)
      window.removeEventListener("resize", fitTerminal)
      terminal.dispose()
      xtermRef.current = null
    }
  }, [fitTerminal]) // A dependência `isDarkMode` foi removida para evitar recriação

  useEffect(() => {
    if (xtermRef.current) {
      xtermRef.current.options.theme = isDarkMode ? darkTheme : lightTheme
    }
  }, [isDarkMode])

  useEffect(() => {
    if (!xtermRef.current) return

    // Quando começar uma execução, limpar o terminal
    if (isExecuting) {
      xtermRef.current.clear()
      return
    }
    
    // Só mostrar output quando não está executando (já foi limpo quando isExecuting=true)
    if (output) {
      xtermRef.current.writeln(output.replace(/\n/g, "\r\n"))
      xtermRef.current.scrollToBottom()
    }
  }, [output, isExecuting])

  // Capturar scroll para evitar que propague para a página principal
  useEffect(() => {
    const terminalElement = terminalRef.current
    if (!terminalElement) return

    const handleWheel = (e: WheelEvent) => {
      // Sempre prevenir propagação do scroll para o elemento pai
      e.stopPropagation()
      e.preventDefault()
      
      // Scrollar manualmente o viewport do xterm
      const viewport = terminalElement.querySelector('.xterm-viewport') as HTMLElement
      if (viewport) {
        viewport.scrollTop += e.deltaY
      }
    }

    // Adicionar listener com capture: true para capturar em toda a área
    terminalElement.addEventListener('wheel', handleWheel, { passive: false, capture: true })

    return () => {
      terminalElement.removeEventListener('wheel', handleWheel, { capture: true })
    }
  }, [])

  return (
    <div className="h-full w-full overflow-hidden p-2 relative">
      {/* Link Confirmation Dialog */}
      <LinkConfirmDialog
        open={linkConfirmDialog.open}
        onOpenChange={(open) => setLinkConfirmDialog({ open, url: "" })}
        url={linkConfirmDialog.url}
        onConfirm={() => {
          window.open(linkConfirmDialog.url, '_blank', 'noopener,noreferrer')
          setLinkConfirmDialog({ open: false, url: "" })
        }}
      />

      {/* Search Bar */}
      {showSearch && (
        <div className="absolute top-2 right-2 z-10 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-md shadow-lg p-2 flex items-center gap-2">
          <input
            type="text"
            value={searchTerm}
            onChange={(e) => {
              setSearchTerm(e.target.value)
              if (searchAddonRef.current && e.target.value) {
                searchAddonRef.current.findNext(e.target.value, { incremental: true })
              } else {
                searchAddonRef.current?.clearDecorations()
              }
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                if (e.shiftKey) {
                  searchAddonRef.current?.findPrevious(searchTerm)
                } else {
                  searchAddonRef.current?.findNext(searchTerm)
                }
              } else if (e.key === 'Escape') {
                setShowSearch(false)
                searchAddonRef.current?.clearDecorations()
              }
            }}
            placeholder="Find..."
            className="px-2 py-1 text-sm border border-gray-300 dark:border-gray-600 rounded bg-white dark:bg-gray-900 text-gray-900 dark:text-gray-100 outline-none focus:ring-1 focus:ring-blue-500 w-48"
            autoFocus
          />
          <button
            onClick={() => searchAddonRef.current?.findPrevious(searchTerm)}
            className="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded"
            title="Previous (Shift+Enter)"
          >
            <ChevronUp className="h-4 w-4" />
          </button>
          <button
            onClick={() => searchAddonRef.current?.findNext(searchTerm)}
            className="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded"
            title="Next (Enter)"
          >
            <ChevronDown className="h-4 w-4" />
          </button>
          <button
            onClick={() => {
              setShowSearch(false)
              setSearchTerm("")
              searchAddonRef.current?.clearDecorations()
            }}
            className="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded"
            title="Close (Esc)"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
      )}
      
      <div
        ref={terminalRef}
        className="h-full w-full"
      />
    </div>
  )
})

"use client"

import React from "react"

import { Badge } from "@game-guild/ui/components/badge"
import { Button } from "@game-guild/ui/components/button"
import { Card, CardContent } from "@/components/ui/card"
import { Slider } from "@game-guild/ui/components/slider"
import { WebPConverter } from "@/components/block-content-editor/lib/editor/webp-converter"
import {
  Eye,
  EyeOff,
  Move3D,
  RotateCcw,
  SplitSquareHorizontal,
  ToggleLeft,
  ToggleRight,
  ZoomIn,
  ZoomOut,
} from "lucide-react"
import { useCallback, useRef, useState } from "react"

export interface PreviewData {
  original: {
    url: string
    size: number
    name: string
  }
  compressed?: {
    url: string
    size: number
    compressionRatio: number
  }
}

interface BeforeAfterPreviewProps {
  data: PreviewData
  className?: string
}

type ViewMode = "side-by-side" | "slider" | "toggle"

export function BeforeAfterPreview({ data, className = "" }: BeforeAfterPreviewProps) {
  const [viewMode, setViewMode] = useState<ViewMode>("side-by-side")
  const [sliderPosition, setSliderPosition] = useState([50])
  const [showOriginal, setShowOriginal] = useState(true)
  const [zoom, setZoom] = useState(100)
  const [isDragging, setIsDragging] = useState(false)
  const containerRef = useRef<HTMLDivElement>(null)

  const handleSliderDrag = useCallback(
    (clientX: number) => {
      if (!containerRef.current || !isDragging) return

      const rect = containerRef.current.getBoundingClientRect()
      const position = ((clientX - rect.left) / rect.width) * 100
      setSliderPosition([Math.max(0, Math.min(100, position))])
    },
    [isDragging],
  )

  const handleMouseMove = useCallback(
    (e: MouseEvent) => {
      handleSliderDrag(e.clientX)
    },
    [handleSliderDrag],
  )

  const handleMouseUp = useCallback(() => {
    setIsDragging(false)
  }, [])

  const handleMouseDown = useCallback(() => {
    setIsDragging(true)
  }, [])

  // Add event listeners for dragging
  React.useEffect(() => {
    if (isDragging) {
      document.addEventListener("mousemove", handleMouseMove)
      document.addEventListener("mouseup", handleMouseUp)
      return () => {
        document.removeEventListener("mousemove", handleMouseMove)
        document.removeEventListener("mouseup", handleMouseUp)
      }
    }
  }, [isDragging, handleMouseMove, handleMouseUp])

  const resetZoom = () => setZoom(100)
  const zoomIn = () => setZoom((prev) => Math.min(prev + 25, 200))
  const zoomOut = () => setZoom((prev) => Math.max(prev - 25, 25))

  const renderSideBySide = () => (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 h-full">
      {/* Original */}
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <h4 className="font-medium text-sm">Original</h4>
          <Badge variant="outline">{WebPConverter.formatFileSize(data.original.size)}</Badge>
        </div>
        <div className="relative aspect-video bg-muted rounded-lg overflow-hidden">
          <img
            src={data.original.url || "/placeholder.svg"}
            alt="Original"
            className="w-full h-full object-contain transition-transform duration-200"
            style={{ transform: `scale(${zoom / 100})` }}
          />
        </div>
      </div>

      {/* Compressed */}
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <h4 className="font-medium text-sm">Compressed</h4>
          <div className="flex gap-2">
            {data.compressed && (
              <>
                <Badge variant="outline">{WebPConverter.formatFileSize(data.compressed.size)}</Badge>
                {data.compressed.compressionRatio > 0 && (
                  <Badge variant="secondary">-{Math.round(data.compressed.compressionRatio)}%</Badge>
                )}
              </>
            )}
          </div>
        </div>
        <div className="relative aspect-video bg-muted rounded-lg overflow-hidden">
          {data.compressed ? (
            <img
              src={data.compressed.url || "/placeholder.svg"}
              alt="Compressed"
              className="w-full h-full object-contain transition-transform duration-200"
              style={{ transform: `scale(${zoom / 100})` }}
            />
          ) : (
            <div className="flex items-center justify-center h-full text-muted-foreground">
              No compressed version available
            </div>
          )}
        </div>
      </div>
    </div>
  )

  const renderSlider = () => (
    <div className="space-y-2">
      <div className="flex items-center justify-between">
        <h4 className="font-medium text-sm">Comparison</h4>
        <div className="flex gap-2">
          <Badge variant="outline">Original: {WebPConverter.formatFileSize(data.original.size)}</Badge>
          {data.compressed && (
            <Badge variant="secondary">
              Compressed: {WebPConverter.formatFileSize(data.compressed.size)}
              (-{Math.round(data.compressed.compressionRatio)}%)
            </Badge>
          )}
        </div>
      </div>

      <div
        ref={containerRef}
        className="relative aspect-video bg-muted rounded-lg overflow-hidden cursor-col-resize"
        onMouseDown={handleMouseDown}
      >
        {/* Original Image (background) */}
        <img
          src={data.original.url || "/placeholder.svg"}
          alt="Original"
          className="absolute inset-0 w-full h-full object-contain"
          style={{ transform: `scale(${zoom / 100})` }}
        />

        {/* Compressed Image (clipped) */}
        {data.compressed && (
          <div
            className="absolute inset-0 overflow-hidden"
            style={{ clipPath: `inset(0 ${100 - (sliderPosition[0] ?? 50)}% 0 0)` }}
          >
            <img
              src={data.compressed?.url || "/placeholder.svg"}
              alt="Compressed"
              className="w-full h-full object-contain"
              style={{ transform: `scale(${zoom / 100})` }}
            />
          </div>
        )}

        {/* Slider Line */}
        <div
          className="absolute top-0 bottom-0 w-0.5 bg-white shadow-lg z-10 cursor-col-resize"
          style={{ left: `${sliderPosition && sliderPosition[0] !== undefined ? sliderPosition[0] : 50}%` }}
        >
          <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-8 h-8 bg-white rounded-full shadow-lg flex items-center justify-center">
            <Move3D className="h-4 w-4 text-gray-600" />
          </div>
        </div>
      </div>

      <Slider value={sliderPosition} onValueChange={(value) => setSliderPosition(Array.isArray(value) ? [...value] : [value])} max={100} min={0} step={1} className="mt-2" />
    </div>
  )

  const renderToggle = () => (
    <div className="space-y-2">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <h4 className="font-medium text-sm">{showOriginal ? "Original" : "Compressed"}</h4>
          <Button variant="outline" size="sm" onClick={() => setShowOriginal(!showOriginal)} className="h-6 px-2">
            {showOriginal ? <Eye className="h-3 w-3" /> : <EyeOff className="h-3 w-3" />}
            Toggle
          </Button>
        </div>
        <div className="flex gap-2">
          {showOriginal ? (
            <Badge variant="outline">{WebPConverter.formatFileSize(data.original.size)}</Badge>
          ) : data.compressed ? (
            <>
              <Badge variant="outline">{WebPConverter.formatFileSize(data.compressed.size)}</Badge>
              <Badge variant="secondary">-{Math.round(data.compressed.compressionRatio)}%</Badge>
            </>
          ) : null}
        </div>
      </div>

      <div className="relative aspect-video bg-muted rounded-lg overflow-hidden">
        <img
          src={showOriginal ? data.original.url : data.compressed?.url || data.original.url}
          alt={showOriginal ? "Original" : "Compressed"}
          className="w-full h-full object-contain transition-all duration-300"
          style={{ transform: `scale(${zoom / 100})` }}
        />
      </div>
    </div>
  )

  return (
    <Card className={className}>
      <CardContent className="p-4">
        {/* Controls */}
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <Button
              variant={viewMode === "side-by-side" ? "default" : "outline"}
              size="sm"
              onClick={() => setViewMode("side-by-side")}
            >
              <SplitSquareHorizontal className="h-4 w-4 mr-1" />
              Side by Side
            </Button>
            <Button
              variant={viewMode === "slider" ? "default" : "outline"}
              size="sm"
              onClick={() => setViewMode("slider")}
              disabled={!data.compressed}
            >
              <Move3D className="h-4 w-4 mr-1" />
              Slider
            </Button>
            <Button
              variant={viewMode === "toggle" ? "default" : "outline"}
              size="sm"
              onClick={() => setViewMode("toggle")}
              disabled={!data.compressed}
            >
              {showOriginal ? <ToggleLeft className="h-4 w-4 mr-1" /> : <ToggleRight className="h-4 w-4 mr-1" />}
              Toggle
            </Button>
          </div>

          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" onClick={zoomOut} disabled={zoom <= 25}>
              <ZoomOut className="h-4 w-4" />
            </Button>
            <span className="text-sm font-medium min-w-[3rem] text-center">{zoom}%</span>
            <Button variant="outline" size="sm" onClick={zoomIn} disabled={zoom >= 200}>
              <ZoomIn className="h-4 w-4" />
            </Button>
            <Button variant="outline" size="sm" onClick={resetZoom}>
              <RotateCcw className="h-4 w-4" />
            </Button>
          </div>
        </div>

        {/* Preview Content */}
        <div className="min-h-[300px]">
          {viewMode === "side-by-side" && renderSideBySide()}
          {viewMode === "slider" && renderSlider()}
          {viewMode === "toggle" && renderToggle()}
        </div>

        {/* File Info */}
        {data.compressed && (
          <div className="mt-4 pt-4 border-t">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 text-sm">
              <div>
                <span className="font-medium">Original Size:</span>
                <br />
                {WebPConverter.formatFileSize(data.original.size)}
              </div>
              <div>
                <span className="font-medium">Compressed Size:</span>
                <br />
                {WebPConverter.formatFileSize(data.compressed.size)}
              </div>
              <div>
                <span className="font-medium">Space Saved:</span>
                <br />
                {WebPConverter.formatFileSize(data.original.size - data.compressed.size)}(
                {Math.round(data.compressed.compressionRatio)}%)
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  )
}

"use client"

import { Badge } from "@game-guild/ui/components/badge"
import { Button } from "@game-guild/ui/components/button"
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "@game-guild/ui/components/dialog"
import { Label } from "@game-guild/ui/components/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@game-guild/ui/components/select"
import { Separator } from "@game-guild/ui/components/separator"
import { Slider } from "@game-guild/ui/components/slider"
import { Switch } from "@game-guild/ui/components/switch"
import { WEBP_PRESETS, WebPConverter, type WebPConversionOptions } from "@/components/block-content-editor/lib/editor/webp-converter"
import { ImageIcon, Palette, Settings, Zap } from "lucide-react"
import { useCallback, useEffect, useState } from "react"

export interface CompressionSettings extends WebPConversionOptions {
  applyToAll: boolean
  preset?: string
}

interface CompressionSettingsDialogProps {
  isOpen: boolean
  onClose: () => void
  file: File
  onConfirm: (settings: CompressionSettings) => void
  onCancel: () => void
  remainingCount?: number
}

export function CompressionSettingsDialog({
  isOpen,
  onClose,
  file,
  onConfirm,
  onCancel,
  remainingCount = 0,
}: CompressionSettingsDialogProps) {
  const [originalDimensions, setOriginalDimensions] = useState<{ width: number; height: number } | null>(null)
  const [scaleMultiplier, setScaleMultiplier] = useState(100) // 100% = original size

  const [settings, setSettings] = useState<CompressionSettings>({
    quality: WebPConverter.getOptimalQuality(file.size),
    maxWidth: 1920,
    maxHeight: 1080,
    maintainAspectRatio: true,
    lossless: false,
    applyToAll: false,
  })

  const [previewData, setPreviewData] = useState<{
    original: string
    compressed?: string
    originalSize: number
    compressedSize?: number
    compressionRatio?: number
  }>({
    original: "",
    originalSize: file.size,
  })

  const [isGeneratingPreview, setIsGeneratingPreview] = useState(false)

  // Generate original preview
  useEffect(() => {
    const img = new Image()
    const objectUrl = URL.createObjectURL(file)

    img.onload = () => {
      setOriginalDimensions({ width: img.naturalWidth, height: img.naturalHeight })
      // Set initial settings based on original dimensions
      setSettings((prev) => ({
        ...prev,
        maxWidth: img.naturalWidth,
        maxHeight: img.naturalHeight,
      }))
      URL.revokeObjectURL(objectUrl)
    }

    img.src = objectUrl
    setPreviewData((prev) => ({ ...prev, original: objectUrl }))

    return () => URL.revokeObjectURL(objectUrl)
  }, [file])

  // Generate compressed preview when settings change
  const generatePreview = useCallback(async () => {
    setIsGeneratingPreview(true)
    try {
      const result = await WebPConverter.convertToWebP(file, settings)
      if (result.success && result.dataUrl) {
        setPreviewData((prev) => ({
          ...prev,
          compressed: result.dataUrl,
          compressedSize: result.compressedSize,
          compressionRatio: result.compressionRatio,
        }))
      }
    } catch (error) {
      console.error("Preview generation failed:", error)
    } finally {
      setIsGeneratingPreview(false)
    }
  }, [file, settings])

  useEffect(() => {
    const debounceTimer = setTimeout(generatePreview, 500)
    return () => clearTimeout(debounceTimer)
  }, [generatePreview])

  const handlePresetChange = (preset: string) => {
    if (preset === "custom") {
      setSettings((prev) => ({ ...prev, preset }))
      return
    }

    const presetConfig = WEBP_PRESETS[preset as keyof typeof WEBP_PRESETS]
    if (presetConfig) {
      setSettings((prev) => ({ ...prev, ...presetConfig, preset }))
    }
  }

  const handleQualityChange = (value: number | readonly number[]) => {
    const quality = Array.isArray(value) ? value[0] : value;
    if (quality !== undefined) {
      setSettings((prev) => ({ ...prev, quality: quality / 100, preset: "custom" }))
    }
  }

  const handleScaleChange = (value: number | readonly number[]) => {
    const newScale = Array.isArray(value) ? value[0] : value
    if (newScale === undefined) return;
    setScaleMultiplier(newScale)

    if (originalDimensions) {
      const newWidth = Math.round((originalDimensions.width * newScale) / 100)
      const newHeight = Math.round((originalDimensions.height * newScale) / 100)

      setSettings((prev) => ({
        ...prev,
        maxWidth: newWidth,
        maxHeight: newHeight,
        preset: "custom",
      }))
    }
  }

  const getFinalDimensions = () => {
    if (!originalDimensions) return null

    const { maxWidth = originalDimensions.width, maxHeight = originalDimensions.height } = settings

    if (!settings.maintainAspectRatio) {
      return { width: maxWidth, height: maxHeight }
    }

    const aspectRatio = originalDimensions.width / originalDimensions.height

    let finalWidth = maxWidth
    let finalHeight = maxHeight

    if (finalWidth / aspectRatio > finalHeight) {
      finalWidth = Math.round(finalHeight * aspectRatio)
    } else {
      finalHeight = Math.round(finalWidth / aspectRatio)
    }

    return { width: finalWidth, height: finalHeight }
  }

  const finalDimensions = getFinalDimensions()

  const handleConfirm = () => {
    onConfirm(settings)
    onClose()
  }

  const handleCancel = () => {
    onCancel()
    onClose()
  }

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="min-w-[65vw] max-h-[95vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Settings className="h-5 w-5" />
            Compression Settings
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-6">
          {/* Preview Panel */}
          <div className="space-y-4">
            <Label className="text-lg font-semibold">Preview Comparison</Label>

            <div className="grid grid-cols-2 gap-6 min-w-0">
              {/* Original */}
              <div className="space-y-3 min-w-0">
                <div className="flex items-center justify-between">
                  <Label className="text-base font-medium">Original</Label>
                  <div className="flex gap-2">
                    <Badge variant="outline">{WebPConverter.formatFileSize(previewData.originalSize)}</Badge>
                    {originalDimensions && (
                      <Badge variant="secondary">
                        {originalDimensions.width} × {originalDimensions.height}
                      </Badge>
                    )}
                  </div>
                </div>
                <div className="relative aspect-video bg-muted rounded-lg overflow-hidden min-h-[300px]">
                  <img
                    src={previewData.original || "/placeholder.svg"}
                    alt="Original"
                    className="w-full h-full object-contain"
                  />
                </div>
              </div>

              {/* Compressed */}
              <div className="space-y-3 min-w-0">
                <div className="flex items-center justify-between">
                  <Label className="text-base font-medium">Compressed</Label>
                  <div className="flex gap-2">
                    {previewData.compressedSize && (
                      <Badge variant="outline">{WebPConverter.formatFileSize(previewData.compressedSize)}</Badge>
                    )}
                    {finalDimensions && (
                      <Badge variant="secondary">
                        {finalDimensions.width} × {finalDimensions.height}
                      </Badge>
                    )}
                    {previewData.compressionRatio && previewData.compressionRatio > 0 && (
                      <Badge variant="secondary">-{Math.round(previewData.compressionRatio)}%</Badge>
                    )}
                  </div>
                </div>
                <div className="relative aspect-video bg-muted rounded-lg overflow-hidden min-h-[300px]">
                  {isGeneratingPreview ? (
                    <div className="flex items-center justify-center h-full">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : previewData.compressed ? (
                    <img
                      src={previewData.compressed || "/placeholder.svg"}
                      alt="Compressed"
                      className="w-full h-full object-contain"
                    />
                  ) : (
                    <div className="flex items-center justify-center h-full text-muted-foreground">
                      Generating preview...
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>

          <Separator />

          {/* Settings Panel */}
          <div className="space-y-6">
            <Label className="text-lg font-semibold">Compression Settings</Label>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              <div>
                <Label className="text-base font-medium">Preset</Label>
                <Select value={settings.preset || "custom"} onValueChange={(value) => value !== null && handlePresetChange(value)}>
                  <SelectTrigger className="mt-2">
                    <SelectValue placeholder="Choose preset" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="HIGH_QUALITY">High Quality</SelectItem>
                    <SelectItem value="BALANCED">Balanced</SelectItem>
                    <SelectItem value="COMPRESSED">Compressed</SelectItem>
                    <SelectItem value="THUMBNAIL">Thumbnail</SelectItem>
                    <SelectItem value="custom">Custom</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <div className="flex items-center justify-between mb-3">
                  <Label className="text-base font-medium flex items-center gap-2">
                    <Zap className="h-4 w-4" />
                    Quality
                  </Label>
                  <Badge variant="secondary">{Math.round(settings.quality * 100)}%</Badge>
                </div>
                <Slider
                  value={[settings.quality * 100]}
                  onValueChange={handleQualityChange}
                  max={100}
                  min={10}
                  step={5}
                  className="mt-2"
                />
                <div className="flex justify-between text-xs text-muted-foreground mt-1">
                  <span>Smaller file</span>
                  <span>Better quality</span>
                </div>
              </div>

              <div>
                <div className="flex items-center justify-between mb-3">
                  <Label className="text-base font-medium flex items-center gap-2">
                    <ImageIcon className="h-4 w-4" />
                    Scale
                  </Label>
                  <Badge variant="secondary">{scaleMultiplier}%</Badge>
                </div>
                <Slider
                  value={[scaleMultiplier]}
                  onValueChange={handleScaleChange}
                  max={100}
                  min={10}
                  step={1}
                  className="mt-2"
                />
                <div className="flex justify-between text-xs text-muted-foreground mt-1">
                  <span>10% (smaller)</span>
                  <span>100% (original)</span>
                </div>
                {finalDimensions && (
                  <div className="text-xs text-muted-foreground mt-2 text-center">
                    Final: {finalDimensions.width} × {finalDimensions.height}px
                  </div>
                )}
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              <div className="flex items-center justify-between">
                <Label className="text-base font-medium">Maintain Aspect Ratio</Label>
                <Switch
                  checked={settings.maintainAspectRatio}
                  onCheckedChange={(checked) =>
                    setSettings((prev) => ({ ...prev, maintainAspectRatio: checked, preset: "custom" }))
                  }
                />
              </div>

              <div className="flex items-center justify-between">
                <Label className="text-base font-medium flex items-center gap-2">
                  <Palette className="h-4 w-4" />
                  Lossless Compression
                </Label>
                <Switch
                  checked={settings.lossless}
                  onCheckedChange={(checked) =>
                    setSettings((prev) => ({ ...prev, lossless: checked, preset: "custom" }))
                  }
                />
              </div>

              {remainingCount > 0 && (
                <div className="flex items-center justify-between">
                  <div>
                    <Label className="text-base font-medium">Apply to All</Label>
                    <p className="text-sm text-muted-foreground">Apply to {remainingCount} remaining images</p>
                  </div>
                  <Switch
                    checked={settings.applyToAll}
                    onCheckedChange={(checked) => setSettings((prev) => ({ ...prev, applyToAll: checked }))}
                  />
                </div>
              )}
            </div>
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={handleCancel}>
            Cancel
          </Button>
          <Button onClick={handleConfirm}>
            {settings.applyToAll ? `Apply to All (${remainingCount + 1})` : "Apply"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import { useState, useCallback } from "react"

export interface CompressionOptions {
  quality: number // 0.1 to 1.0
  maxWidth?: number
  maxHeight?: number
  format: "webp" | "jpeg" | "png"
}

export interface CompressionResult {
  originalFile: File
  compressedBlob: Blob
  originalSize: number
  compressedSize: number
  compressionRatio: number
  dataUrl: string
}

export interface ImageCompressorProps {
  file: File
  options: CompressionOptions
  onCompressionComplete: (result: CompressionResult) => void
  onError: (error: string) => void
}

export const useImageCompressor = () => {
  const [isCompressing, setIsCompressing] = useState(false)

  const compressImage = useCallback(async (file: File, options: CompressionOptions): Promise<CompressionResult> => {
    setIsCompressing(true)

    try {
      return new Promise((resolve, reject) => {
        const canvas = document.createElement("canvas")
        const ctx = canvas.getContext("2d")
        const img = new Image()

        img.onload = () => {
          // Calculate new dimensions
          let { width, height } = img
          const { maxWidth = 1920, maxHeight = 1080 } = options

          if (width > maxWidth || height > maxHeight) {
            const ratio = Math.min(maxWidth / width, maxHeight / height)
            width *= ratio
            height *= ratio
          }

          canvas.width = width
          canvas.height = height

          // Draw and compress
          ctx?.drawImage(img, 0, 0, width, height)

          canvas.toBlob(
            (blob) => {
              if (!blob) {
                reject(new Error("Failed to compress image"))
                return
              }

              const compressionRatio = ((file.size - blob.size) / file.size) * 100
              const dataUrl = canvas.toDataURL(`image/${options.format}`, options.quality)

              resolve({
                originalFile: file,
                compressedBlob: blob,
                originalSize: file.size,
                compressedSize: blob.size,
                compressionRatio,
                dataUrl,
              })
            },
            `image/${options.format}`,
            options.quality,
          )
        }

        img.onerror = () => reject(new Error("Failed to load image"))
        img.src = URL.createObjectURL(file)
      })
    } catch (error) {
      throw new Error(`Compression failed: ${error}`)
    } finally {
      setIsCompressing(false)
    }
  }, [])

  const getRecommendedQuality = useCallback((fileSize: number): number => {
    // Recommend compression for files larger than 500KB
    if (fileSize > 5 * 1024 * 1024) return 0.7 // Large files (>5MB)
    if (fileSize > 2 * 1024 * 1024) return 0.8 // Medium files (>2MB)
    if (fileSize > 500 * 1024) return 0.85 // Small files (>500KB)
    return 0.9 // Very small files
  }, [])

  const shouldRecommendCompression = useCallback((fileSize: number): boolean => {
    return fileSize > 500 * 1024 // Recommend for files > 500KB
  }, [])

  const formatFileSize = useCallback((bytes: number): string => {
    if (bytes === 0) return "0 Bytes"
    const k = 1024
    const sizes = ["Bytes", "KB", "MB", "GB"]
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return Number.parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i]
  }, [])

  return {
    compressImage,
    isCompressing,
    getRecommendedQuality,
    shouldRecommendCompression,
    formatFileSize,
  }
}

// Default compression options
export const DEFAULT_COMPRESSION_OPTIONS: CompressionOptions = {
  quality: 0.85,
  maxWidth: 1920,
  maxHeight: 1080,
  format: "webp",
}

// High quality options for automatic compression
export const AUTO_COMPRESSION_OPTIONS: CompressionOptions = {
  quality: 0.9,
  maxWidth: 2048,
  maxHeight: 2048,
  format: "webp",
}

"use client"

import { useState } from "react"
import { BaseConfirmDialog } from "./base-confirm-dialog"
import { AlertTriangle } from "lucide-react"
import { Input } from "@game-guild/ui/components/input"
import { Label } from "@game-guild/ui/components/label"

interface DuplicateNameDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  itemType: "file" | "folder"
  originalName: string
  onConfirm: (newName: string) => void
  onCancel?: () => void
}

export function DuplicateNameDialog({
  open,
  onOpenChange,
  itemType,
  originalName,
  onConfirm,
  onCancel,
}: DuplicateNameDialogProps) {
  const [newName, setNewName] = useState(originalName)

  const handleConfirm = () => {
    if (newName.trim() && newName !== originalName) {
      onConfirm(newName.trim())
      onOpenChange(false)
    }
  }

  const handleCancel = () => {
    setNewName(originalName)
    onOpenChange(false)
    onCancel?.()
  }

  return (
    <BaseConfirmDialog
      open={open}
      onOpenChange={(open) => {
        if (!open) handleCancel()
      }}
      title={`${itemType === "file" ? "File" : "Folder"} Already Exists`}
      description={`A ${itemType} named "${originalName}" already exists in this location. Please choose a different name.`}
      onConfirm={handleConfirm}
      confirmText="Create with New Name"
      cancelText="Cancel"
      confirmButtonClass="bg-blue-600 text-white hover:bg-blue-700"
      icon={
        <div className="w-12 h-12 rounded-full bg-yellow-100 dark:bg-yellow-900/20 flex items-center justify-center">
          <AlertTriangle className="w-6 h-6 text-yellow-600 dark:text-yellow-400" />
        </div>
      }
    >
      <div className="space-y-2">
        <Label htmlFor="newName" className="text-sm font-medium">
          New {itemType === "file" ? "File" : "Folder"} Name
        </Label>
        <Input
          id="newName"
          value={newName}
          onChange={(e) => setNewName(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") handleConfirm()
            if (e.key === "Escape") handleCancel()
          }}
          placeholder={`Enter ${itemType} name`}
          autoFocus
          className="w-full"
        />
        {newName.trim() === originalName && (
          <p className="text-xs text-red-600 dark:text-red-400">
            Name must be different from "{originalName}"
          </p>
        )}
      </div>
    </BaseConfirmDialog>
  )
}

"use client"

import { useState, useEffect } from "react"
import { Button } from "@game-guild/ui/components/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@game-guild/ui/components/dialog"
import { Input } from "@game-guild/ui/components/input"
import { Label } from "@game-guild/ui/components/label"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@game-guild/ui/components/tabs"
import { ScrollArea } from "@game-guild/ui/components/scroll-area"
import { Badge } from "@game-guild/ui/components/badge"
import { 
  History, 
  Tag, 
  Eye, 
  RotateCcw, 
  Camera, 
  Clock,
  GitCommit,
  Loader2
} from "lucide-react"
import { toast } from "sonner"
import type { CommitInfo, SnapshotInfo } from "@/components/block-content-editor/lib/storage/git"

interface ProjectHistoryDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  projectId: string
  projectName: string
  isViewingHistory: boolean
  currentViewingSha: string | null
  onLoadCommit: (sha: string) => Promise<void>
  onLoadSnapshot: (tag: string) => Promise<void>
  onReturnToHead: () => Promise<void>
  onCreateSnapshot: (name?: string) => Promise<void>
  listHistory: (projectId: string) => Promise<CommitInfo[]>
  listSnapshots: (projectId: string) => Promise<SnapshotInfo[]>
}

export function ProjectHistoryDialog({
  open,
  onOpenChange,
  projectId,
  projectName,
  isViewingHistory,
  currentViewingSha,
  onLoadCommit,
  onLoadSnapshot,
  onReturnToHead,
  onCreateSnapshot,
  listHistory,
  listSnapshots,
}: ProjectHistoryDialogProps) {
  const [commits, setCommits] = useState<CommitInfo[]>([])
  const [snapshots, setSnapshots] = useState<SnapshotInfo[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [isCreatingSnapshot, setIsCreatingSnapshot] = useState(false)
  const [snapshotName, setSnapshotName] = useState("")
  const [showCreateSnapshot, setShowCreateSnapshot] = useState(false)
  const [loadingItem, setLoadingItem] = useState<string | null>(null)

  // Load history and snapshots when dialog opens
  useEffect(() => {
    if (open && projectId) {
      loadData()
    }
  }, [open, projectId])

  const loadData = async () => {
    setIsLoading(true)
    try {
      const [historyData, snapshotsData] = await Promise.all([
        listHistory(projectId),
        listSnapshots(projectId)
      ])
      setCommits(historyData)
      setSnapshots(snapshotsData)
    } catch (error) {
      console.error("Failed to load history:", error)
      toast.error("Failed to load history")
    } finally {
      setIsLoading(false)
    }
  }

  const handleLoadCommit = async (sha: string) => {
    setLoadingItem(sha)
    try {
      await onLoadCommit(sha)
      onOpenChange(false)
    } catch (error) {
      console.error("Failed to load commit:", error)
      toast.error("Failed to load commit")
    } finally {
      setLoadingItem(null)
    }
  }

  const handleLoadSnapshot = async (tag: string) => {
    setLoadingItem(tag)
    try {
      await onLoadSnapshot(tag)
      onOpenChange(false)
    } catch (error) {
      console.error("Failed to load snapshot:", error)
      toast.error("Failed to load snapshot")
    } finally {
      setLoadingItem(null)
    }
  }

  const handleReturnToHead = async () => {
    setLoadingItem("head")
    try {
      await onReturnToHead()
      onOpenChange(false)
    } catch (error) {
      console.error("Failed to return to HEAD:", error)
      toast.error("Failed to return to latest version")
    } finally {
      setLoadingItem(null)
    }
  }

  const handleCreateSnapshot = async () => {
    setIsCreatingSnapshot(true)
    try {
      await onCreateSnapshot(snapshotName.trim() || undefined)
      setSnapshotName("")
      setShowCreateSnapshot(false)
      await loadData() // Refresh the list
      toast.success("Snapshot created successfully")
    } catch (error) {
      console.error("Failed to create snapshot:", error)
      toast.error(error instanceof Error ? error.message : "Failed to create snapshot")
    } finally {
      setIsCreatingSnapshot(false)
    }
  }

  const formatDate = (dateString: string) => {
    const date = new Date(dateString)
    return date.toLocaleString()
  }

  const formatRelativeTime = (dateString: string) => {
    const date = new Date(dateString)
    const now = new Date()
    const diffMs = now.getTime() - date.getTime()
    const diffMins = Math.floor(diffMs / 60000)
    const diffHours = Math.floor(diffMs / 3600000)
    const diffDays = Math.floor(diffMs / 86400000)

    if (diffMins < 1) return "just now"
    if (diffMins < 60) return `${diffMins}m ago`
    if (diffHours < 24) return `${diffHours}h ago`
    if (diffDays < 7) return `${diffDays}d ago`
    return date.toLocaleDateString()
  }

  // Find if a commit has a snapshot tag
  const getSnapshotForCommit = (sha: string): SnapshotInfo | undefined => {
    return snapshots.find(s => s.sha === sha)
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[600px] max-h-[80vh]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <History className="h-5 w-5" />
            Project History
          </DialogTitle>
          <DialogDescription>
            View commit history and snapshots for "{projectName}"
          </DialogDescription>
        </DialogHeader>

        {/* Current State Banner */}
        {isViewingHistory && (
          <div className="flex items-center justify-between p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 rounded-lg">
            <div className="flex items-center gap-2 text-amber-800 dark:text-amber-200">
              <Eye className="h-4 w-4" />
              <span className="text-sm font-medium">
                Viewing historical version (read-only)
              </span>
            </div>
            <Button
              size="sm"
              variant="outline"
              onClick={handleReturnToHead}
              disabled={loadingItem === "head"}
              className="gap-1"
            >
              {loadingItem === "head" ? (
                <Loader2 className="h-3 w-3 animate-spin" />
              ) : (
                <RotateCcw className="h-3 w-3" />
              )}
              Return to Latest
            </Button>
          </div>
        )}

        <Tabs defaultValue="history" className="w-full">
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="history" className="gap-2">
              <GitCommit className="h-4 w-4" />
              History ({commits.length})
            </TabsTrigger>
            <TabsTrigger value="snapshots" className="gap-2">
              <Tag className="h-4 w-4" />
              Snapshots ({snapshots.length})
            </TabsTrigger>
          </TabsList>

          <TabsContent value="history" className="mt-4">
            {isLoading ? (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
              </div>
            ) : commits.length === 0 ? (
              <div className="text-center py-8 text-muted-foreground">
                <GitCommit className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p>No commit history yet</p>
                <p className="text-sm">Save the project to create history</p>
              </div>
            ) : (
              <ScrollArea className="h-[300px] pr-4">
                <div className="space-y-2">
                  {commits.map((commit, index) => {
                    const snapshot = getSnapshotForCommit(commit.sha)
                    const isHead = index === 0
                    const isCurrentlyViewing = currentViewingSha === commit.sha

                    return (
                      <div
                        key={commit.sha}
                        className={`p-3 border rounded-lg transition-colors ${
                          isCurrentlyViewing
                            ? "border-blue-500 bg-blue-50 dark:bg-blue-900/20"
                            : "border-gray-200 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-800"
                        }`}
                      >
                        <div className="flex items-start justify-between gap-2">
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 mb-1">
                              <code className="text-xs text-muted-foreground font-mono">
                                {commit.sha.substring(0, 7)}
                              </code>
                              {isHead && (
                                <Badge variant="default" className="text-xs">
                                  HEAD
                                </Badge>
                              )}
                              {snapshot && (
                                <Badge variant="secondary" className="text-xs gap-1">
                                  <Tag className="h-3 w-3" />
                                  {snapshot.tag}
                                </Badge>
                              )}
                              {isCurrentlyViewing && (
                                <Badge variant="outline" className="text-xs">
                                  Viewing
                                </Badge>
                              )}
                            </div>
                            <p className="text-sm text-gray-700 dark:text-gray-300 truncate">
                              {commit.message}
                            </p>
                            <div className="flex items-center gap-1 mt-1 text-xs text-muted-foreground">
                              <Clock className="h-3 w-3" />
                              <span title={formatDate(commit.date)}>
                                {formatRelativeTime(commit.date)}
                              </span>
                            </div>
                          </div>
                          <Button
                            size="sm"
                            variant={isCurrentlyViewing ? "secondary" : "outline"}
                            onClick={() => handleLoadCommit(commit.sha)}
                            disabled={loadingItem !== null || isCurrentlyViewing}
                            className="shrink-0"
                          >
                            {loadingItem === commit.sha ? (
                              <Loader2 className="h-4 w-4 animate-spin" />
                            ) : (
                              <Eye className="h-4 w-4" />
                            )}
                          </Button>
                        </div>
                      </div>
                    )
                  })}
                </div>
              </ScrollArea>
            )}
          </TabsContent>

          <TabsContent value="snapshots" className="mt-4">
            {/* Create Snapshot Section */}
            {!isViewingHistory && (
              <div className="mb-4">
                {showCreateSnapshot ? (
                  <div className="p-3 border border-dashed border-gray-300 dark:border-gray-600 rounded-lg space-y-3">
                    <div className="space-y-2">
                      <Label htmlFor="snapshot-name">Snapshot Name (optional)</Label>
                      <Input
                        id="snapshot-name"
                        placeholder={`${projectName}-v1`}
                        value={snapshotName}
                        onChange={(e) => setSnapshotName(e.target.value)}
                        disabled={isCreatingSnapshot}
                      />
                      <p className="text-xs text-muted-foreground">
                        Leave empty to auto-generate a name
                      </p>
                    </div>
                    <div className="flex gap-2">
                      <Button
                        size="sm"
                        onClick={handleCreateSnapshot}
                        disabled={isCreatingSnapshot}
                        className="gap-1"
                      >
                        {isCreatingSnapshot ? (
                          <Loader2 className="h-4 w-4 animate-spin" />
                        ) : (
                          <Camera className="h-4 w-4" />
                        )}
                        Create
                      </Button>
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => {
                          setShowCreateSnapshot(false)
                          setSnapshotName("")
                        }}
                        disabled={isCreatingSnapshot}
                      >
                        Cancel
                      </Button>
                    </div>
                  </div>
                ) : (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setShowCreateSnapshot(true)}
                    className="w-full gap-2 border-dashed"
                  >
                    <Camera className="h-4 w-4" />
                    Create Snapshot from Current State
                  </Button>
                )}
              </div>
            )}

            {isLoading ? (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
              </div>
            ) : snapshots.length === 0 ? (
              <div className="text-center py-8 text-muted-foreground">
                <Tag className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p>No snapshots yet</p>
                <p className="text-sm">Create a snapshot to save a version</p>
              </div>
            ) : (
              <ScrollArea className="h-[250px] pr-4">
                <div className="space-y-2">
                  {snapshots.map((snapshot) => {
                    const isCurrentlyViewing = currentViewingSha === snapshot.sha

                    return (
                      <div
                        key={snapshot.tag}
                        className={`p-3 border rounded-lg transition-colors ${
                          isCurrentlyViewing
                            ? "border-blue-500 bg-blue-50 dark:bg-blue-900/20"
                            : "border-gray-200 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-800"
                        }`}
                      >
                        <div className="flex items-start justify-between gap-2">
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 mb-1">
                              <Badge variant="secondary" className="gap-1">
                                <Tag className="h-3 w-3" />
                                {snapshot.tag}
                              </Badge>
                              {isCurrentlyViewing && (
                                <Badge variant="outline" className="text-xs">
                                  Viewing
                                </Badge>
                              )}
                            </div>
                            <p className="text-sm text-gray-700 dark:text-gray-300 truncate">
                              {snapshot.message}
                            </p>
                            <div className="flex items-center gap-2 mt-1 text-xs text-muted-foreground">
                              <code className="font-mono">{snapshot.sha.substring(0, 7)}</code>
                              <span>•</span>
                              <span title={formatDate(snapshot.date)}>
                                {formatRelativeTime(snapshot.date)}
                              </span>
                            </div>
                          </div>
                          <Button
                            size="sm"
                            variant={isCurrentlyViewing ? "secondary" : "outline"}
                            onClick={() => handleLoadSnapshot(snapshot.tag)}
                            disabled={loadingItem !== null || isCurrentlyViewing}
                            className="shrink-0"
                          >
                            {loadingItem === snapshot.tag ? (
                              <Loader2 className="h-4 w-4 animate-spin" />
                            ) : (
                              <Eye className="h-4 w-4" />
                            )}
                          </Button>
                        </div>
                      </div>
                    )
                  })}
                </div>
              </ScrollArea>
            )}
          </TabsContent>
        </Tabs>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Close
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import { Button } from "@game-guild/ui/components/button"
import { Input } from "@game-guild/ui/components/input"
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@game-guild/ui/components/dialog"
import { Label } from "@game-guild/ui/components/label"
import { useEffect, useState } from "react"
import { toast } from "sonner"
import { StorageOptionSelector } from "./storage-option-selector"
import { EMPTY_PROJECT_DATA } from "@/components/block-content-editor/lib/storage/editor/block-storage"
import type { ProjectData } from "@/components/block-content-editor/lib/storage/editor/project-data"
import { getProjectTypeStructure, PROJECT_TYPE_LABELS, type ProjectType } from "@/components/block-content-editor/lib/storage/editor/project-types"
import type { BlockCellType } from "@/components/block-content-editor/lib/storage/editor/block-structure"
import type { ProjectPreferences } from "@/components/block-content-editor/lib/storage/editor/project-preferences"
import type { StorageType } from "@/components/block-content-editor/lib/storage/editor/storage-types"

interface StorageAdapter {
  list: () => Promise<ProjectData[]>
  save: (id: string, name: string, data: string, tags: string[], storageType?: StorageType, preferences?: ProjectPreferences) => Promise<void>
}

interface CreateProjectDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  isDbInitialized: boolean
  storageAdapter: StorageAdapter
  availableTags: Array<{ name: string }>
  onProjectCreate: (projectData: {
    id: string
    name: string
    tags: string[]
    storageType: StorageType
    preferences: ProjectPreferences
  }) => void
  onProjectsListUpdate: () => void
  onAvailableTagsUpdate: () => void
  generateProjectId: () => string
  /** Page-declared structural constraints to persist on the new project. */
  projectType?: ProjectType
  /**
   * Which project types this page is allowed to create. When undefined or
   * containing more than one entry, the dialog shows a project-type selector
   * (so a "general" page lets the user choose document / quiz / general).
   */
  allowedProjectTypes?: ProjectType[]
  singleBlockMode?: boolean
  allowedBlockTypes?: BlockCellType[]
}

export function CreateProjectDialog({
  open,
  onOpenChange,
  isDbInitialized: _isDbInitialized,
  storageAdapter,
  availableTags,
  onProjectCreate,
  onProjectsListUpdate,
  onAvailableTagsUpdate,
  generateProjectId,
  projectType,
  allowedProjectTypes,
  singleBlockMode,
  allowedBlockTypes,
}: CreateProjectDialogProps) {
  const [newCreateProjectName, setNewCreateProjectName] = useState("")
  const [projectTags, setProjectTags] = useState<string[]>([])
  const [tagInput, setTagInput] = useState("")
  const [showTagDropdown, setShowTagDropdown] = useState(false)
  const [storageOption, setStorageOption] = useState<StorageType>("local")

  // Available project types: page filter wins; otherwise show all three.
  const ALL_TYPES: ProjectType[] = ["document", "quiz", "general"]
  const availableTypes: ProjectType[] = allowedProjectTypes && allowedProjectTypes.length > 0
    ? allowedProjectTypes
    : ALL_TYPES
  const initialType: ProjectType =
    projectType && availableTypes.includes(projectType)
      ? projectType
      : (availableTypes[0] ?? "general")
  const [selectedType, setSelectedType] = useState<ProjectType>(initialType)

  // Reset selected type whenever the dialog reopens or page defaults change.
  useEffect(() => {
    if (open) setSelectedType(initialType)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, projectType, allowedProjectTypes?.join("|")])


  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (showTagDropdown) {
        const target = event.target as Element
        if (!target.closest(".relative")) setShowTagDropdown(false)
      }
    }
    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [showTagDropdown])

  const handleCreate = async () => {
    if (!newCreateProjectName.trim()) {
      toast.error("Nome obrigatório", {
        description: "Por favor, digite um nome para o projeto",
        duration: 3000,
        icon: "✏️",
      })
      return
    }
    if (projectTags.length === 0) {
      toast.error("Tags obrigatórias", {
        description: "Por favor, adicione pelo menos uma tag ao projeto",
        duration: 3000,
        icon: "🏷️",
      })
      return
    }
    if (!storageOption) {
      toast.error("Opção de armazenamento obrigatória", {
        description: "Por favor, selecione uma opção de armazenamento",
        duration: 3000,
        icon: "💾",
      })
      return
    }

    const existingProjects = await storageAdapter.list()
    if (existingProjects.some((p) => p.name === newCreateProjectName.trim())) {
      let suggestedName = `${newCreateProjectName.trim()}-v2`
      let counter = 2
      while (existingProjects.some((p) => p.name === suggestedName)) {
        counter++
        suggestedName = `${newCreateProjectName.trim()}-v${counter}`
      }
      toast.error("Nome já existe", {
        description: `Já há projeto com o nome "${newCreateProjectName.trim()}". Sugestão: ${suggestedName}`,
        duration: 5000,
        icon: "🚫",
      })
      return
    }

    try {
      const newProjectId = generateProjectId()
      // Page-pinned structural rules win; otherwise fall back to the defaults
      // implied by the chosen project type.
      const typeDefaults = getProjectTypeStructure(selectedType)
      const effectiveSingleBlockMode = singleBlockMode ?? typeDefaults.singleBlockMode
      const effectiveAllowedBlockTypes = allowedBlockTypes ?? typeDefaults.allowedBlockTypes
      const preferences: ProjectPreferences = {
        global: {
          projectType: selectedType,
          ...(effectiveSingleBlockMode !== undefined ? { singleBlockMode: effectiveSingleBlockMode } : {}),
          ...(effectiveAllowedBlockTypes !== undefined ? { allowedBlockTypes: effectiveAllowedBlockTypes } : {}),
        },
      }

      await storageAdapter.save(
        newProjectId,
        newCreateProjectName,
        EMPTY_PROJECT_DATA,
        projectTags,
        storageOption,
        preferences,
      )

      onProjectCreate({
        id: newProjectId,
        name: newCreateProjectName,
        tags: projectTags,
        storageType: storageOption,
        preferences,
      })

      setNewCreateProjectName("")
      setProjectTags([])
      setTagInput("")
      setShowTagDropdown(false)
      setStorageOption("local")
      onOpenChange(false)

      await onProjectsListUpdate()
      await onAvailableTagsUpdate()

      toast.success("Novo projeto criado", {
        description: `"${newCreateProjectName}" foi criado com sucesso`,
        duration: 3000,
        icon: "🎉",
      })
    } catch (error) {
      console.error("Create error:", error)
      toast.error("Erro ao criar projeto", {
        description: "Não foi possível criar o projeto. Tente novamente.",
        duration: 4000,
        icon: "❌",
      })
    }
  }

  const handleCancel = () => {
    setNewCreateProjectName("")
    setProjectTags([])
    setTagInput("")
    setShowTagDropdown(false)
    setStorageOption("local")
    onOpenChange(false)
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-5xl">
        <DialogHeader>
          <DialogTitle className="text-2xl">Create New Project</DialogTitle>
        </DialogHeader>

        <div>
          <Label htmlFor="create-project-name" className="text-sm font-semibold">Project Name *</Label>
          <Input
            id="create-project-name"
            value={newCreateProjectName}
            onChange={(e) => setNewCreateProjectName(e.target.value)}
            placeholder="Enter project name..."
            onKeyDown={(e) => e.key === "Enter" && !e.shiftKey && handleCreate()}
            className="mt-1.5 h-10"
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-3">

            {availableTypes.length > 1 ? (
              <div>
                <Label htmlFor="project-type" className="text-sm font-semibold">Project Type *</Label>
                <select
                  id="project-type"
                  value={selectedType}
                  onChange={(e) => setSelectedType(e.target.value as ProjectType)}
                  className="w-full px-3 py-2 mt-1.5 bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 dark:focus:ring-blue-400"
                >
                  {availableTypes.map((t) => (
                    <option key={t} value={t}>{PROJECT_TYPE_LABELS[t]}</option>
                  ))}
                </select>
              </div>
            ) : null}

            <div className="space-y-1.5">
              <Label className="text-sm font-semibold">Tags (required) *</Label>
              <div className="relative">
                <div className="flex gap-2">
                  <div className="relative flex-1">
                    <Input
                      placeholder="Search or create tags..."
                      value={tagInput}
                      onChange={(e) => { setTagInput(e.target.value); setShowTagDropdown(true) }}
                      onKeyDown={(e) => {
                        if (e.key === "Enter" && tagInput.trim()) {
                          e.preventDefault()
                          const newTag = tagInput.trim()
                          if (!projectTags.includes(newTag)) setProjectTags((prev) => [...prev, newTag])
                          setTagInput("")
                          setShowTagDropdown(false)
                        }
                        if (e.key === "Escape") setShowTagDropdown(false)
                      }}
                      onFocus={() => setShowTagDropdown(true)}
                      className="pr-10"
                    />
                    <button
                      type="button"
                      onClick={() => setShowTagDropdown(!showTagDropdown)}
                      className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                    >
                      <svg className={`w-4 h-4 transition-transform ${showTagDropdown ? "rotate-180" : ""}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                      </svg>
                    </button>
                  </div>
                </div>

                {showTagDropdown && (
                  <div className="absolute z-10 w-full mt-1 bg-white dark:bg-gray-800 border dark:border-gray-700 rounded-md shadow-lg max-h-36 overflow-y-auto">
                    {(() => {
                      const filteredTags = tagInput.trim()
                        ? availableTags.filter((tag) => tag.name.toLowerCase().includes(tagInput.toLowerCase()) && !projectTags.includes(tag.name))
                        : availableTags.filter((tag) => !projectTags.includes(tag.name))
                      return (
                        <>
                          {filteredTags.length > 0 && (
                            <>
                              {filteredTags.slice(0, 8).map((tag) => (
                                <button
                                  key={tag.name}
                                  type="button"
                                  onClick={() => { setProjectTags((prev) => [...prev, tag.name]); setTagInput(""); setShowTagDropdown(false) }}
                                  className="w-full px-3 py-1.5 text-left hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center justify-between"
                                >
                                  <span className="text-sm">{tag.name}</span>
                                </button>
                              ))}
                              {tagInput.trim() && !availableTags.some((tag) => tag.name.toLowerCase() === tagInput.toLowerCase()) && !projectTags.includes(tagInput.trim()) && (
                                <div className="border-t dark:border-gray-700 my-0.5" />
                              )}
                            </>
                          )}
                          {tagInput.trim() && !availableTags.some((tag) => tag.name.toLowerCase() === tagInput.toLowerCase()) && !projectTags.includes(tagInput.trim()) && (
                            <button
                              type="button"
                              onClick={() => { const newTag = tagInput.trim(); setProjectTags((prev) => [...prev, newTag]); setTagInput(""); setShowTagDropdown(false) }}
                              className="w-full px-3 py-1.5 text-left hover:bg-gray-100 dark:hover:bg-gray-700"
                            >
                              <div className="flex items-center gap-2">
                                <svg className="w-3.5 h-3.5 text-green-600 dark:text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                                </svg>
                                <span className="text-sm">Create "<strong>{tagInput.trim()}</strong>"</span>
                              </div>
                            </button>
                          )}
                          {filteredTags.length === 0 && !tagInput.trim() && (
                            <div className="px-3 py-1.5 text-sm text-gray-500 dark:text-gray-400">
                              {availableTags.length === 0 ? "No tags yet. Type to create one." : "Type to search or create tags..."}
                            </div>
                          )}
                        </>
                      )
                    })()}
                  </div>
                )}
              </div>

              {projectTags.length > 0 && (
                <div className="flex flex-wrap gap-1.5">
                  {projectTags.map((tag, index) => (
                    <span key={index} className="inline-flex items-center gap-1 px-2.5 py-0.5 bg-blue-100 dark:bg-blue-900 text-blue-800 dark:text-blue-200 text-xs rounded-full">
                      {tag}
                      <button
                        type="button"
                        onClick={() => setProjectTags((prev) => prev.filter((_, i) => i !== index))}
                        className="hover:text-blue-600 dark:hover:text-blue-300 ml-0.5"
                      >
                        <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                        </svg>
                      </button>
                    </span>
                  ))}
                </div>
              )}
            </div>
          </div>

          <div className="space-y-3">
            <div>
              <Label className="text-sm font-semibold">Storage Location *</Label>
              <div className="mt-1.5">
                <StorageOptionSelector selectedOption={storageOption} onSelectionChange={setStorageOption} />
              </div>
            </div>

            <div className="p-2 bg-blue-50 dark:bg-blue-900/50 rounded-lg">
              <p className="text-xs text-blue-700 dark:text-blue-300">
                Creates a new empty project. At least one tag is required.
              </p>
            </div>
          </div>
        </div>

        <div className="flex justify-end gap-2 pt-1">
          <Button variant="outline" onClick={handleCancel}>Cancel</Button>
          <Button onClick={handleCreate} disabled={projectTags.length === 0 || !storageOption}>
            Create Project
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import { useState } from "react"

interface EditableProjectTitleProps {
  projectName: string
  isEditing: boolean
  editingName: string
  onEditStart: () => void
  onEditEnd: () => void
  onNameChange: (name: string) => void
  onSave: () => void
}

export function EditableProjectTitle({
  projectName,
  isEditing,
  editingName,
  onEditStart,
  onEditEnd,
  onNameChange,
  onSave,
}: EditableProjectTitleProps) {
  return (
    <>
      {isEditing ? (
        <input
          type="text"
          value={editingName}
          onChange={(e) => onNameChange(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              onSave()
            } else if (e.key === "Escape") {
              onEditEnd()
            }
          }}
          onBlur={onSave}
          className="w-full bg-transparent px-2 py-0.5 text-sm font-medium text-gray-900 outline-none dark:text-gray-100"
          autoFocus
        />
      ) : (
        <span
          className="cursor-pointer px-2 py-0.5 text-sm font-medium text-gray-900 transition-colors hover:bg-gray-100 dark:text-gray-100 dark:hover:bg-gray-800 rounded truncate block"
          onClick={onEditStart}
          title={projectName || "Click to edit project name"}
        >
          {projectName || "Untitled Project"}
        </span>
      )}
    </>
  )
}

"use client"

import type React from "react"

import { Button } from "@game-guild/ui/components/button"
import { Input } from "@game-guild/ui/components/input"
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@game-guild/ui/components/dialog"
import { Label } from "@game-guild/ui/components/label"
import { useState, useEffect, useRef } from "react"
import { toast } from "sonner"
import { Upload, FileText, FolderOpen, Archive, X } from "lucide-react"
import { ProjectImporter, type ImportedProjectData } from "@/components/block-content-editor/lib/interopAdapter/project-importer"
import type { ProjectData } from "@/components/block-content-editor/lib/storage/editor/project-data"
import type { StorageType } from "@/components/block-content-editor/lib/storage/editor/storage-types"
import type { ProjectPreferences } from "@/components/block-content-editor/lib/storage/editor/project-preferences"
import { findAssetUris } from "@game-guild/assets"
import { getDefaultBrowserAssetRepository } from "@game-guild/assets/browser"

const assetRepository = getDefaultBrowserAssetRepository()

function getImportErrorDescription(error: unknown, fallback: string): string {
  if (typeof error === "object" && error !== null && "message" in error
    && typeof error.message === "string" && error.message) {
    return error.message
  }
  return fallback
}

function isFileEntry(entry: FileSystemEntry): entry is FileSystemFileEntry {
  return entry.isFile
}

function isDirectoryEntry(entry: FileSystemEntry): entry is FileSystemDirectoryEntry {
  return entry.isDirectory
}

interface StorageAdapter {
  list: () => Promise<ProjectData[]>
  save: (id: string, name: string, data: string, tags: string[], storageType?: StorageType, preferences?: ProjectPreferences) => Promise<void>
}

interface ImportProjectDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  isDbInitialized: boolean
  storageAdapter: StorageAdapter
  availableTags: Array<{ name: string }>
  onProjectCreate: (projectData: { id: string; name: string; tags: string[] }) => void
  onProjectsListUpdate: () => void | Promise<void>
  onAvailableTagsUpdate: () => void | Promise<void>
  generateProjectId: () => string
  onOpenProject?: (projectData: { id: string; name: string; tags: string[] }) => void
}

export function ImportProjectDialog({
  open,
  onOpenChange,
  storageAdapter,
  availableTags,
  onProjectCreate,
  onProjectsListUpdate,
  onAvailableTagsUpdate,
  generateProjectId,
  onOpenProject,
}: ImportProjectDialogProps) {
  const [projectName, setProjectName] = useState("")
  const [projectTags, setProjectTags] = useState<string[]>([])
  const [tagInput, setTagInput] = useState("")
  const [showTagDropdown, setShowTagDropdown] = useState(false)
  const [importedProject, setImportedProject] = useState<ImportedProjectData | null>(null)
  const [isDragOver, setIsDragOver] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)
  const folderInputRef = useRef<HTMLInputElement>(null)

  // Close tag dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (showTagDropdown) {
        const target = event.target as Element
        if (!target.closest(".relative")) {
          setShowTagDropdown(false)
        }
      }
    }

    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [showTagDropdown])

  const resetForm = () => {
    setProjectName("")
    setProjectTags([])
    setTagInput("")
    setShowTagDropdown(false)
    setImportedProject(null)
    setIsDragOver(false)
  }

  const applyImportedData = (importedData: ImportedProjectData, sourceLabel: string) => {
    if (!ProjectImporter.validateImportedData(importedData)) {
      throw new Error('Invalid project data format')
    }
    setImportedProject(importedData)
    setProjectName(importedData.name)
    setProjectTags(importedData.tags)
    toast.success("Imported successfully", {
      description: `Loaded project: ${importedData.name} (from ${sourceLabel})`,
      duration: 3000,
      icon: "📁",
    })
  }

  const handleFileUpload = async (file: File) => {
    try {
      if (!ProjectImporter.isSupportedFile(file.name)) {
        const supportedExtensions = ProjectImporter.getSupportedExtensions()
        throw new Error(`Unsupported file format. Supported formats: ${supportedExtensions.join(', ')}`)
      }
      const importedData = await ProjectImporter.importFromFile(file)
      applyImportedData(importedData, file.name)
    } catch (error: unknown) {
      console.error("Import error:", error)
      toast.error("Import failed", {
        description: getImportErrorDescription(error, "Failed to import project file"),
        duration: 4000,
        icon: "❌",
      })
    }
  }

  const handleFolderUpload = async (files: File[]) => {
    try {
      const importedData = await ProjectImporter.importFromFolder(files)
      const folderLabel = files[0]?.webkitRelativePath?.split('/')[0] || 'folder'
      applyImportedData(importedData, folderLabel)
    } catch (error: unknown) {
      console.error("Folder import error:", error)
      toast.error("Import failed", {
        description: getImportErrorDescription(error, "Failed to import project folder"),
        duration: 4000,
        icon: "❌",
      })
    }
  }

  // Recursively read files from a dropped directory entry
  const readEntriesAsFiles = async (entry: FileSystemEntry, pathPrefix = ""): Promise<File[]> => {
    if (isFileEntry(entry)) {
      return new Promise<File[]>((resolve, reject) => {
        entry.file((file: File) => {
          // Patch webkitRelativePath so importFromFolder can locate inner paths
          try {
            Object.defineProperty(file, 'webkitRelativePath', {
              value: `${pathPrefix}${file.name}`,
              configurable: true,
            })
          } catch {
            /* non-fatal */
          }
          resolve([file])
        }, reject)
      })
    }
    if (isDirectoryEntry(entry)) {
      const reader = entry.createReader()
      const allEntries: FileSystemEntry[] = []
      // readEntries returns batches; loop until empty
      while (true) {
        const batch = await new Promise<FileSystemEntry[]>((resolve, reject) => reader.readEntries(resolve, reject))
        if (!batch.length) break
        allEntries.push(...batch)
      }
      const nested = await Promise.all(
        allEntries.map((e) => readEntriesAsFiles(e, `${pathPrefix}${entry.name}/`)),
      )
      return nested.flat()
    }
    return []
  }

  const handleDrop = async (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(false)

    try {
      const items = e.dataTransfer.items
      if (items && items.length > 0) {
        // Detect directory drops
        const entries: FileSystemEntry[] = []
        for (let i = 0; i < items.length; i++) {
          const entry = items[i]?.webkitGetAsEntry?.()
          if (entry) entries.push(entry)
        }
        const dirEntry = entries.find(isDirectoryEntry)
        if (dirEntry) {
          const collected = await readEntriesAsFiles(dirEntry)
          if (collected.length > 0) {
            await handleFolderUpload(collected)
            return
          }
        }
      }

      const file = e.dataTransfer.files[0]
      if (file) {
        await handleFileUpload(file)
      }
    } catch (error: unknown) {
      console.error("Folder import error:", error)
      toast.error("Import failed", {
        description: getImportErrorDescription(error, "Failed to import project folder"),
        duration: 4000,
        icon: "❌",
      })
    }
  }

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(true)
  }

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(false)
  }

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) {
      void handleFileUpload(file)
    }
    // Reset so the same file can be re-selected later
    e.target.value = ""
  }

  const handleFolderSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (files && files.length > 0) {
      void handleFolderUpload(Array.from(files))
    }
    e.target.value = ""
  }

  const handleSave = async (openAfterSave = false) => {
    if (!importedProject) {
      toast.error("No project to import", {
        description: "Please upload a project file first",
        duration: 3000,
        icon: "📁",
      })
      return
    }

    if (!projectName.trim()) {
      toast.error("Project name required", {
        description: "Please enter a name for the project",
        duration: 3000,
        icon: "✏️",
      })
      return
    }

    if (projectTags.length === 0) {
      toast.error("Tags required", {
        description: "Please add at least one tag to the project",
        duration: 3000,
        icon: "🏷️",
      })
      return
    }



    try {
      // Check if project with same name already exists
      const existingProjects = await storageAdapter.list()
      if (existingProjects.some((p) => p.name === projectName.trim())) {
        let suggestedName = `${projectName.trim()}-imported`
        let counter = 1

        while (existingProjects.some((p) => p.name === suggestedName)) {
          counter++
          suggestedName = `${projectName.trim()}-imported-${counter}`
        }

        toast.error("Name already exists", {
          description: `Project "${projectName.trim()}" already exists. Suggestion: ${suggestedName}`,
          duration: 5000,
          icon: "🚫",
        })
        return
      }

      const newProjectId = generateProjectId()
      
      // Save project with preferences
      await storageAdapter.save(
        newProjectId, 
        projectName.trim(), 
        importedProject.data, 
        projectTags,
        undefined, // storageType
        importedProject.preferences || importedProject.metadata?.preferences
      )

      const importedUris = findAssetUris(JSON.parse(importedProject.data) as unknown)
      await assetRepository.reconcileUsage(
        { type: "project", id: newProjectId },
        importedUris.map((uri, index) => ({
          uri,
          consumerId: `imported-reference:${index}`,
          role: "project-content",
        })),
      )

      if (importedProject.assetsImported > 0) {
        toast.info("Assets imported", {
          description: `${importedProject.assetsImported} assets restored from the project bundle`,
          duration: 3000,
          icon: "📦",
        })
      }

      const projectData = {
        id: newProjectId,
        name: projectName.trim(),
        tags: projectTags,
      }

      onProjectCreate(projectData)

      // Reset form
      resetForm()
      onOpenChange(false)

      // Update lists
      await onProjectsListUpdate()
      await onAvailableTagsUpdate()

      if (openAfterSave && onOpenProject) {
        onOpenProject(projectData)
      }

      toast.success("Project imported successfully", {
        description: `"${projectName.trim()}" has been ${openAfterSave ? "imported and opened" : "imported"}`,
        duration: 3000,
        icon: "🎉",
      })
    } catch (error: unknown) {
      console.error("Save error:", error)
      toast.error("Failed to save project", {
        description: "Could not save the imported project. Please try again.",
        duration: 4000,
        icon: "❌",
      })
    }
  }

  const handleCancel = () => {
    if (importedProject?.importedAssetUris.length) {
      void Promise.all(
        importedProject.importedAssetUris.map((uri) =>
          assetRepository.remove(uri, { force: true }).catch(() => undefined),
        ),
      )
    }
    resetForm()
    onOpenChange(false)
  }

  return (
    <Dialog open={open} onOpenChange={(nextOpen) => nextOpen ? onOpenChange(true) : handleCancel()}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>Import Project</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          {/* File Upload Area */}
          {!importedProject && (
            <div
              className={`border-2 border-dashed rounded-lg p-6 text-center transition-colors ${
                isDragOver
                  ? "border-blue-500 bg-blue-50 dark:bg-blue-950"
                  : "border-gray-300 dark:border-gray-600 hover:border-gray-400 dark:hover:border-gray-500"
              }`}
              onDrop={(event) => { void handleDrop(event) }}
              onDragOver={handleDragOver}
              onDragLeave={handleDragLeave}
            >
              <Upload className="w-8 h-8 mx-auto mb-2 text-gray-400" />
              <p className="text-sm text-gray-600 dark:text-gray-400 mb-2">
                Drag and drop your project file or folder here, or click to browse
              </p>
              <p className="text-xs text-gray-500 dark:text-gray-500 mb-4">
                Supports: .zip, .block-content-editor file, or an uncompressed projeto-* folder
              </p>
              <div className="flex justify-center gap-2">
                <Button variant="outline" onClick={() => fileInputRef.current?.click()}>
                  <FileText className="w-4 h-4 mr-2" />
                  Choose File
                </Button>
                <Button variant="outline" onClick={() => folderInputRef.current?.click()}>
                  <FolderOpen className="w-4 h-4 mr-2" />
                  Choose Folder
                </Button>
              </div>
              <input
                ref={fileInputRef}
                type="file"
                accept=".zip,.block-content-editor"
                onChange={handleFileSelect}
                className="hidden"
              />
              <input
                ref={folderInputRef}
                type="file"
                onChange={handleFolderSelect}
                className="hidden"
                // @ts-expect-error non-standard attributes for directory picker
                webkitdirectory=""
                directory=""
                multiple
              />
            </div>
          )}

          {/* Project Details Form */}
          {importedProject && (
            <>
              {/* File Info */}
              <div className="p-3 bg-green-50 dark:bg-green-950 rounded-lg">
                <div className="flex items-center gap-2 mb-2">
                  <Archive className="w-4 h-4 text-green-600 dark:text-green-400" />
                  <span className="text-sm font-medium text-green-800 dark:text-green-200">
                    File Imported Successfully
                  </span>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => setImportedProject(null)}
                    className="ml-auto h-6 w-6 p-0"
                  >
                    <X className="w-3 h-3" />
                  </Button>
                </div>
                <p className="text-xs text-green-700 dark:text-green-300">
                  Project data loaded. You can modify the name and tags below.
                </p>
              </div>

              {/* Project Name */}
              <div>
                <Label htmlFor="import-project-name">Project Name</Label>
                <Input
                  id="import-project-name"
                  value={projectName}
                  onChange={(e) => setProjectName(e.target.value)}
                  placeholder="Enter project name..."
                  className="mt-1"
                />
              </div>

              {/* Tags Section - Same as create dialog */}
              <div className="space-y-3">
                <Label>Tags (required) *</Label>

                <div className="relative">
                  <div className="flex gap-2">
                    <div className="relative flex-1">
                      <Input
                        placeholder="Search existing tags or type to create new..."
                        value={tagInput}
                        onChange={(e) => {
                          setTagInput(e.target.value)
                          setShowTagDropdown(true)
                        }}
                        onKeyDown={(e) => {
                          if (e.key === "Enter" && tagInput.trim()) {
                            e.preventDefault()
                            const newTag = tagInput.trim()
                            if (!projectTags.includes(newTag)) {
                              setProjectTags((prev) => [...prev, newTag])
                            }
                            setTagInput("")
                            setShowTagDropdown(false)
                          }
                          if (e.key === "Escape") {
                            setShowTagDropdown(false)
                          }
                        }}
                        onFocus={() => setShowTagDropdown(true)}
                        className="pr-10"
                      />
                      <button
                        type="button"
                        onClick={() => setShowTagDropdown(!showTagDropdown)}
                        className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                      >
                        <svg
                          className={`w-4 h-4 transition-transform ${showTagDropdown ? "rotate-180" : ""}`}
                          fill="none"
                          stroke="currentColor"
                          viewBox="0 0 24 24"
                        >
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                        </svg>
                      </button>
                    </div>
                  </div>

                  {/* Tag Dropdown - Same logic as create dialog */}
                  {showTagDropdown && (
                    <div className="absolute z-10 w-full mt-1 bg-white dark:bg-gray-800 border dark:border-gray-700 rounded-md shadow-lg max-h-48 overflow-y-auto">
                      {(() => {
                        const filteredTags = tagInput.trim()
                          ? availableTags.filter(
                              (tag) =>
                                tag.name.toLowerCase().includes(tagInput.toLowerCase()) &&
                                !projectTags.includes(tag.name),
                            )
                          : availableTags.filter((tag) => !projectTags.includes(tag.name))

                        return (
                          <>
                            {filteredTags.length > 0 && (
                              <>
                                {filteredTags.slice(0, 10).map((tag) => (
                                  <button
                                    key={tag.name}
                                    type="button"
                                    onClick={() => {
                                      setProjectTags((prev) => [...prev, tag.name])
                                      setTagInput("")
                                      setShowTagDropdown(false)
                                    }}
                                    className="w-full px-3 py-2 text-left hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center justify-between"
                                  >
                                    <span className="text-sm">{tag.name}</span>
                                  </button>
                                ))}
                                {tagInput.trim() &&
                                  !availableTags.some((tag) => tag.name.toLowerCase() === tagInput.toLowerCase()) &&
                                  !projectTags.includes(tagInput.trim()) && (
                                    <div className="border-t dark:border-gray-700 my-1"></div>
                                  )}
                              </>
                            )}

                            {tagInput.trim() &&
                              !availableTags.some((tag) => tag.name.toLowerCase() === tagInput.toLowerCase()) &&
                              !projectTags.includes(tagInput.trim()) && (
                                <button
                                  type="button"
                                  onClick={() => {
                                    const newTag = tagInput.trim()
                                    setProjectTags((prev) => [...prev, newTag])
                                    setTagInput("")
                                    setShowTagDropdown(false)
                                  }}
                                  className="w-full px-3 py-2 text-left hover:bg-gray-100 dark:hover:bg-gray-700"
                                >
                                  <div className="flex items-center gap-2">
                                    <svg
                                      className="w-4 h-4 text-green-600 dark:text-green-400"
                                      fill="none"
                                      stroke="currentColor"
                                      viewBox="0 0 24 24"
                                    >
                                      <path
                                        strokeLinecap="round"
                                        strokeLinejoin="round"
                                        strokeWidth={2}
                                        d="M12 4v16m8-8H4"
                                      />
                                    </svg>
                                    <span className="text-sm">
                                      Create "<strong>{tagInput.trim()}</strong>"
                                    </span>
                                  </div>
                                </button>
                              )}
                          </>
                        )
                      })()}
                    </div>
                  )}
                </div>

                {/* Selected Tags */}
                {projectTags.length > 0 && (
                  <div className="space-y-2">
                    <Label className="text-sm text-gray-600 dark:text-gray-400">Selected tags:</Label>
                    <div className="flex flex-wrap gap-2">
                      {projectTags.map((tag, index) => (
                        <span
                          key={index}
                          className="inline-flex items-center gap-1 px-3 py-1 bg-blue-100 dark:bg-blue-900 text-blue-800 dark:text-blue-200 text-sm rounded-full"
                        >
                          {tag}
                          <button
                            type="button"
                            onClick={() => setProjectTags((prev) => prev.filter((_, i) => i !== index))}
                            className="hover:text-blue-600 dark:hover:text-blue-300 ml-1"
                          >
                            <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M6 18L18 6M6 6l12 12"
                              />
                            </svg>
                          </button>
                        </span>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </>
          )}

          {/* Action Buttons */}
          <div className="flex justify-end gap-2">
            <Button variant="outline" onClick={handleCancel}>
              Cancel
            </Button>
            {importedProject && (
              <>
                <Button
                  variant="outline"
                  onClick={() => { void handleSave(false) }}
                  disabled={!projectName.trim() || projectTags.length === 0}
                >
                  Save and Exit
                </Button>
                <Button onClick={() => { void handleSave(true) }} disabled={!projectName.trim() || projectTags.length === 0}>
                  Save and Open
                </Button>
              </>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import type React from "react"
import { Button } from "@game-guild/ui/components/button"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@game-guild/ui/components/dialog"
import { Input } from "@game-guild/ui/components/input"
import { Label } from "@game-guild/ui/components/label"
import { useState, useEffect } from "react"
import { toast } from "sonner"
import { X } from "lucide-react"
import { StorageOptionSelector, type StorageOption } from "./storage-option-selector"
import type { ProjectData } from "@/components/block-content-editor/lib/storage/editor/project-data"

interface StorageAdapter {
  list: () => Promise<Array<{ id: string; name: string }>>
}

interface InfoDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  project: ProjectData | null
  onSave: (projectId: string, newName: string, newTags: string[], storageOption: StorageOption) => Promise<void>
  availableTags: Array<{ name: string }>
  storageAdapter: StorageAdapter
}

export function InfoDialog({
  open,
  onOpenChange,
  project,
  onSave,
  availableTags,
  storageAdapter,
}: InfoDialogProps) {
  const [name, setName] = useState("")
  const [tags, setTags] = useState<string[]>([])
  const [tagInput, setTagInput] = useState("")
  const [showTagDropdown, setShowTagDropdown] = useState(false)
  const [storageOption, setStorageOption] = useState<StorageOption>("local")

  useEffect(() => {
    if (project) {
      setName(project.name)
      setTags(project.tags || [])
      setStorageOption(project.storageType || "local")
    } else {
      // Reset state when dialog is closed or project is null
      setName("")
      setTags([])
      setTagInput("")
      setStorageOption("local")
    }
  }, [project])

  // Close tag dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (showTagDropdown) {
        const target = event.target as Element
        // Updated to check against a more specific class
        if (!target.closest(".tag-input-container")) {
          setShowTagDropdown(false)
        }
      }
    }

    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [showTagDropdown])

  const handleSave = async () => {
    if (!project) return
    if (!name.trim()) {
      toast.error("Project name cannot be empty.")
      return
    }

    // Check if another project with the same name already exists
    const existingProjects = await storageAdapter.list()
    const trimmedName = name.trim()
    const conflictingProject = existingProjects.find(
      (p) => p.name === trimmedName && p.id !== project.id,
    )

    if (conflictingProject) {
      toast.error("Project name already exists", {
        description: `Another project is already named "${trimmedName}". Please choose a different name.`,
        duration: 5000,
        icon: "🚫",
      })
      return
    }

    try {
      await onSave(project.id, trimmedName, tags, storageOption)
      onOpenChange(false)
    } catch (error) {
      // Error is handled in the onSave implementation, but we can add a fallback
      console.error("Failed to save project info:", error)
    }
  }

  const handleTagInputKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter" && tagInput.trim()) {
      e.preventDefault()
      const newTag = tagInput.trim()
      if (newTag && !tags.includes(newTag)) {
        setTags([...tags, newTag])
      }
      setTagInput("")
      setShowTagDropdown(false)
    }
  }

  const removeTag = (tagToRemove: string) => {
    setTags(tags.filter((tag) => tag !== tagToRemove))
  }

  if (!project) return null

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>Edit Project Information</DialogTitle>
          <DialogDescription>Update the name and tags for your project.</DialogDescription>
        </DialogHeader>
        <div className="grid gap-4 py-4">
          <div className="grid grid-cols-4 items-center gap-4">
            <Label htmlFor="name" className="text-right">
              Name
            </Label>
            <Input id="name" value={name} onChange={(e) => setName(e.target.value)} className="col-span-3" />
          </div>
          <div className="grid grid-cols-4 items-center gap-4">
            <Label htmlFor="tags" className="text-right">
              Tags
            </Label>
            <div className="col-span-3">
              {/* Tag Input with Dropdown */}
              <div className="relative tag-input-container">
                <div className="flex gap-2">
                  <div className="relative flex-1">
                    <Input
                      placeholder="Search or create tags..."
                      value={tagInput}
                      onChange={(e) => {
                        setTagInput(e.target.value)
                        setShowTagDropdown(true)
                      }}
                      onKeyDown={(e) => {
                        if (e.key === "Enter" && tagInput.trim()) {
                          handleTagInputKeyDown(e)
                        }
                        if (e.key === "Escape") {
                          setShowTagDropdown(false)
                        }
                      }}
                      onFocus={() => setShowTagDropdown(true)}
                      className="pr-10"
                    />
                    <button
                      type="button"
                      onClick={() => setShowTagDropdown(!showTagDropdown)}
                      className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                    >
                      <svg
                        className={`h-4 w-4 transition-transform ${showTagDropdown ? "rotate-180" : ""}`}
                        fill="none"
                        stroke="currentColor"
                        viewBox="0 0 24 24"
                      >
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                      </svg>
                    </button>
                  </div>
                </div>

                {/* Dropdown with existing tags */}
                {showTagDropdown && (
                  <div className="absolute z-10 mt-1 w-full rounded-md border bg-white shadow-lg dark:border-gray-700 dark:bg-gray-800 max-h-48 overflow-y-auto">
                    {(() => {
                      const filteredTags = tagInput.trim()
                        ? availableTags.filter(
                            (tag) =>
                              tag.name.toLowerCase().includes(tagInput.toLowerCase()) && !tags.includes(tag.name),
                          )
                        : availableTags.filter((tag) => !tags.includes(tag.name))

                      return (
                        <>
                          {/* Show filtered existing tags */}
                          {filteredTags.length > 0 && (
                            <>
                              {filteredTags.slice(0, 10).map((tag) => (
                                <button
                                  key={tag.name}
                                  type="button"
                                  onClick={() => {
                                    setTags((prev) => [...prev, tag.name])
                                    setTagInput("")
                                    setShowTagDropdown(false)
                                  }}
                                  className="flex w-full items-center justify-between px-3 py-2 text-left hover:bg-gray-100 dark:hover:bg-gray-700"
                                >
                                  <span className="text-sm">{tag.name}</span>
                                </button>
                              ))}
                              {tagInput.trim() &&
                                !availableTags.some((tag) => tag.name.toLowerCase() === tagInput.toLowerCase()) &&
                                !tags.includes(tagInput.trim()) && (
                                  <div className="my-1 border-t dark:border-gray-700"></div>
                                )}
                            </>
                          )}

                          {/* Create new tag option */}
                          {tagInput.trim() &&
                            !availableTags.some((tag) => tag.name.toLowerCase() === tagInput.toLowerCase()) &&
                            !tags.includes(tagInput.trim()) && (
                              <button
                                type="button"
                                onClick={() => {
                                  const newTag = tagInput.trim()
                                  setTags((prev) => [...prev, newTag])
                                  setTagInput("")
                                  setShowTagDropdown(false)
                                }}
                                className="w-full px-3 py-2 text-left hover:bg-gray-100 dark:hover:bg-gray-700"
                              >
                                <div className="flex items-center gap-2">
                                  <svg
                                    className="h-4 w-4 text-green-600 dark:text-green-400"
                                    fill="none"
                                    stroke="currentColor"
                                    viewBox="0 0 24 24"
                                  >
                                    <path
                                      strokeLinecap="round"
                                      strokeLinejoin="round"
                                      strokeWidth={2}
                                      d="M12 4v16m8-8H4"
                                    />
                                  </svg>
                                  <span className="text-sm">
                                    Create "<strong>{tagInput.trim()}</strong>"
                                  </span>
                                </div>
                              </button>
                            )}
                        </>
                      )
                    })()}
                  </div>
                )}
              </div>

              {/* Selected Tags */}
              {tags.length > 0 && (
                <div className="mt-2 flex flex-wrap gap-2">
                  {tags.map((tag) => (
                    <span
                      key={tag}
                      className="inline-flex items-center gap-1 rounded-full bg-blue-100 px-2 py-1 text-xs text-blue-800 dark:bg-blue-900 dark:text-blue-200"
                    >
                      {tag}
                      <button
                        type="button"
                        onClick={() => removeTag(tag)}
                        className="ml-1 rounded-full hover:bg-blue-200 dark:hover:bg-blue-800"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </span>
                  ))}
                </div>
              )}
            </div>
          </div>
          
          {/* Storage Options Section */}
          <div className="grid grid-cols-4 items-start gap-4">
            <Label className="text-right pt-2">
              Storage
            </Label>
            <div className="col-span-3">
              <StorageOptionSelector
                selectedOption={storageOption}
                onSelectionChange={setStorageOption}
              />
            </div>
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button onClick={handleSave}>Save Changes</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import { useState } from "react"
import { FolderOpen, Plus, Upload } from "lucide-react"
import { toast } from "sonner"

import { Button } from "@game-guild/ui/components/button"
import { DeleteConfirmDialog } from "@/components/block-content-editor/extras/dialogs/delete-confirm-dialog"
import { ProjectSearchFilters } from "@/components/block-content-editor/extras/project-dialog/project-search-filters"
import { ProjectList } from "@/components/block-content-editor/extras/project-dialog/project-list"
import { ProjectPagination } from "@/components/block-content-editor/extras/project-dialog/project-pagination"
import { ProjectPickerShell } from "@/components/block-content-editor/extras/project-dialog/project-picker-shell"
import { useProjectDialog } from "@/components/block-content-editor/hooks/editor/use-project-dialog"
import { useProjectActions } from "@/components/block-content-editor/hooks/editor/use-project-actions"
import { ImportProjectDialog } from "./import-project-dialog"
import { InfoDialog } from "./info-dialog"
import type { ProjectData } from "@/components/block-content-editor/lib/storage/editor/project-data"
import type { ProjectType } from "@/components/block-content-editor/lib/storage/editor/project-types"
import type { StorageType } from "@/components/block-content-editor/lib/storage/editor/storage-types"
import type { ProjectPreferences } from "@/components/block-content-editor/lib/storage/editor/project-preferences"

interface StorageAdapter {
  save: (
    id: string,
    name: string,
    data: string,
    tags: string[],
    storageType?: StorageType,
    preferences?: ProjectPreferences,
  ) => Promise<void>
  list: () => Promise<ProjectData[]>
  load: (id: string) => Promise<ProjectData | null>
  delete: (id: string) => Promise<void>
  searchProjects: (
    searchTerm: string,
    tags: string[],
    filterMode: "all" | "any",
    storageTypeFilter?: StorageType,
  ) => Promise<ProjectData[]>
}

interface OpenProjectDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  isFirstTime: boolean
  isDbInitialized: boolean
  storageAdapter: StorageAdapter
  availableTags: Array<{ name: string }>
  onProjectLoad: (projectData: ProjectData) => void
  onProjectsListUpdate: () => void
  onCreateNew: () => void
  currentProjectName: string
  /**
   * If set, the dialog only lists projects whose `preferences.global.projectType`
   * matches one of these values. Projects with no `projectType` are treated as
   * "general". Undefined = accept all.
   */
  allowedProjectTypes?: ProjectType[]
}

export function OpenProjectDialog({
  open,
  onOpenChange,
  isFirstTime,
  isDbInitialized,
  storageAdapter,
  availableTags,
  onProjectLoad,
  onProjectsListUpdate,
  onCreateNew,
  currentProjectName,
  allowedProjectTypes,
}: OpenProjectDialogProps) {
  const {
    searchTerm,
    setSearchTerm,
    selectedTags,
    setSelectedTags,
    storageTypeFilter,
    setStorageTypeFilter,
    currentPage,
    setCurrentPage,
    itemsPerPage,
    setItemsPerPage,
    filteredProjects,
    totalProjects,
    tagFilterMode,
    setTagFilterMode,
    loadProject,
  } = useProjectDialog({ isDbInitialized, storageAdapter })

  const [importDialogOpen, setImportDialogOpen] = useState(false)

  const projectActions = useProjectActions({
    storageAdapter,
    onProjectsListUpdate,
    onProjectUpdate: async () => {
      onProjectsListUpdate()
    },
  })

  const handleOpen = async (projectId: string) => {
    const projectData = await loadProject(projectId)
    if (!projectData) {
      console.error("Project data not found")
      return
    }

    try {
      if (!projectData.data) {
        throw new Error("Project data is missing")
      }

      // Guard: don't allow opening a project whose type this page doesn't accept.
      if (allowedProjectTypes && allowedProjectTypes.length > 0) {
        const t = projectData.preferences?.global?.projectType ?? "general"
        if (!allowedProjectTypes.includes(t)) {
          toast.error("Projeto incompatível com esta página", {
            description: `Este editor não abre projetos do tipo "${t}".`,
            duration: 4000,
            icon: "🚫",
          })
          return
        }
      }

      onProjectLoad(projectData)
      onOpenChange(false)
      await new Promise((resolve) => setTimeout(resolve, 100))

      toast.success("Projeto carregado", {
        description: `"${projectData.name}" foi aberto com sucesso`,
        duration: 2500,
        icon: "📂",
      })
    } catch (error) {
      console.error("Failed to load project:", error, "Project data:", projectData)
      const errorMessage = error instanceof Error ? error.message : "Unknown error"
      toast.error("Erro ao carregar projeto", {
        description: `O arquivo do projeto está corrompido ou em formato inválido: ${errorMessage}`,
        duration: 4000,
        icon: "❌",
      })
    }
  }

  const handleImportProject = (projectData: { id: string; name: string; tags: string[] }) => {
    handleOpen(projectData.id)
  }

  const generateProjectId = () => {
    return Date.now().toString() + Math.random().toString(36).substr(2, 9)
  }

  // Page-level filter by project type. Projects with no projectType stored
  // are treated as "general".
  const visibleProjects = allowedProjectTypes && allowedProjectTypes.length > 0
    ? filteredProjects.filter((p) => {
        const t = p.preferences?.global?.projectType ?? "general"
        return allowedProjectTypes.includes(t)
      })
    : filteredProjects
  const visibleTotal = allowedProjectTypes && allowedProjectTypes.length > 0
    ? visibleProjects.length
    : totalProjects

  return (
    <>
      <ProjectPickerShell
        open={open}
        onOpenChange={onOpenChange}
        title={isFirstTime ? "Welcome! Choose an Option" : "Open Project"}
        description={
          isFirstTime
            ? "To get started, please open an existing project or create a new one."
            : undefined
        }
        onAuthSuccess={onProjectsListUpdate}
        authSuccessToast={{
          title: "Google Drive connected successfully!",
          description: "You can now access your Google Drive projects.",
        }}
        filters={
          <ProjectSearchFilters
            searchTerm={searchTerm}
            onSearchChange={setSearchTerm}
            selectedTags={selectedTags}
            onTagsChange={setSelectedTags}
            availableTags={availableTags}
            tagFilterMode={tagFilterMode}
            onTagFilterModeChange={setTagFilterMode}
            storageTypeFilter={storageTypeFilter}
            onStorageTypeFilterChange={setStorageTypeFilter}
            itemsPerPage={itemsPerPage}
            onItemsPerPageChange={setItemsPerPage}
            showFilters={true}
          />
        }
        list={
          <ProjectList
            projects={visibleProjects}
            currentPage={currentPage}
            itemsPerPage={itemsPerPage}
            searchTerm={searchTerm}
            selectedTags={selectedTags}
            viewMode="grid"
            onOpen={handleOpen}
            onDelete={projectActions.handleConfirmDelete}
            onDownload={projectActions.handleDownload}
            onInfo={projectActions.handleOpenInfo}
            showDeleteButton={true}
            openButtonText="Open"
          />
        }
        pagination={
          <ProjectPagination
            currentPage={currentPage}
            totalProjects={visibleTotal}
            itemsPerPage={itemsPerPage}
            onPageChange={setCurrentPage}
          />
        }
        footerLeft={
          <>
            <Button
              variant="ghost"
              onClick={() => {
                onOpenChange(false)
                onCreateNew()
              }}
              className="gap-2"
              disabled={!isDbInitialized}
            >
              <Plus className="w-4 h-4" />
              Create New
            </Button>
            <Button
              variant="ghost"
              onClick={() => {
                onOpenChange(false)
                setImportDialogOpen(true)
              }}
              className="gap-2"
              disabled={!isDbInitialized}
            >
              <Upload className="w-4 h-4" />
              Import Project
            </Button>
          </>
        }
        footerRight={
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={!currentProjectName}
            className="bg-transparent"
          >
            Fechar
          </Button>
        }
      />

      <DeleteConfirmDialog
        open={projectActions.deleteDialogOpen}
        onOpenChange={projectActions.setDeleteDialogOpen}
        itemName={projectActions.projectToDelete?.name}
        itemType="projeto"
        onConfirm={projectActions.handleDelete}
        title={""}
      />

      <ImportProjectDialog
        open={importDialogOpen}
        onOpenChange={(open) => {
          setImportDialogOpen(open)
          if (!open) {
            onOpenChange(true)
          }
        }}
        isDbInitialized={isDbInitialized}
        storageAdapter={{
          ...storageAdapter,
          save: storageAdapter.save,
        }}
        availableTags={availableTags}
        onProjectCreate={(projectData) => {
          const { id, name, tags } = projectData
          onProjectLoad({
            id,
            name,
            tags,
            data: "",
            metadata: { size: 0, hash: "", createdAt: "", updatedAt: "" },
            storageType: "local",
          })
        }}
        onProjectsListUpdate={onProjectsListUpdate}
        onAvailableTagsUpdate={() => {}}
        generateProjectId={generateProjectId}
        onOpenProject={handleImportProject}
      />

      <InfoDialog
        open={projectActions.infoDialogOpen}
        onOpenChange={projectActions.setInfoDialogOpen}
        project={projectActions.projectToEdit}
        onSave={projectActions.handleSaveInfo}
        availableTags={availableTags}
        storageAdapter={storageAdapter}
      />
    </>
  )
}

"use client"

import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@game-guild/ui/components/dialog"
import { Button } from "@game-guild/ui/components/button"
import { Input } from "@game-guild/ui/components/input"
import { Label } from "@game-guild/ui/components/label"
import { SaveAll } from 'lucide-react'
import { useState, useEffect } from "react"
import { StorageOptionSelector, type StorageOption } from "./storage-option-selector"

interface SaveAsDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  projectName: string
  onProjectNameChange: (name: string) => void
  onSave: (storageOption: StorageOption, tags: string[]) => void
  currentProjectSize: number
  getSizeIndicatorColor: () => string
  formatSize: (size: number) => string
  isDbInitialized: boolean
  availableTags?: Array<{ name: string }>
  initialTags?: string[]
}

export function SaveAsDialog({
  open,
  onOpenChange,
  projectName,
  onProjectNameChange,
  onSave,
  currentProjectSize,
  getSizeIndicatorColor,
  formatSize,
  isDbInitialized,
  availableTags = [],
  initialTags = [],
}: SaveAsDialogProps) {
  const [storageOption, setStorageOption] = useState<StorageOption>("local")
  const [projectTags, setProjectTags] = useState<string[]>(initialTags)
  const [tagInput, setTagInput] = useState("")
  const [showTagDropdown, setShowTagDropdown] = useState(false)

  // Sync initialTags when dialog opens
  useEffect(() => {
    if (open) setProjectTags(initialTags)
  }, [open, initialTags])

  // Close tag dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (showTagDropdown) {
        const target = event.target as Element
        if (!target.closest(".save-as-tag-dropdown")) {
          setShowTagDropdown(false)
        }
      }
    }
    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [showTagDropdown])

  const handleSave = () => {
    onSave(storageOption, projectTags)
    onOpenChange(false)
  }
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Save Project As</DialogTitle>
        </DialogHeader>
        <div className="space-y-4">
          <div>
            <Label htmlFor="project-name">Project Name</Label>
            <Input
              id="project-name"
              value={projectName}
              onChange={(e) => onProjectNameChange(e.target.value)}
              placeholder="Enter project name..."
              onKeyDown={(e) => e.key === "Enter" && handleSave()}
              className="mt-1"
            />
          </div>
          {/* Storage Options Section */}
          <StorageOptionSelector
            selectedOption={storageOption}
            onSelectionChange={setStorageOption}
          />

          {/* Tags Section */}
          <div className="space-y-1.5">
            <Label className="text-sm font-semibold">Tags</Label>
            <div className="relative save-as-tag-dropdown">
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <Input
                    placeholder="Search or create tags..."
                    value={tagInput}
                    onChange={(e) => {
                      setTagInput(e.target.value)
                      setShowTagDropdown(true)
                    }}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" && tagInput.trim()) {
                        e.preventDefault()
                        const newTag = tagInput.trim()
                        if (!projectTags.includes(newTag)) {
                          setProjectTags((prev) => [...prev, newTag])
                        }
                        setTagInput("")
                        setShowTagDropdown(false)
                      }
                      if (e.key === "Escape") {
                        setShowTagDropdown(false)
                      }
                    }}
                    onFocus={() => setShowTagDropdown(true)}
                    className="pr-10"
                  />
                  <button
                    type="button"
                    onClick={() => setShowTagDropdown(!showTagDropdown)}
                    className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                  >
                    <svg
                      className={`w-4 h-4 transition-transform ${showTagDropdown ? "rotate-180" : ""}`}
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                    </svg>
                  </button>
                </div>
              </div>

              {showTagDropdown && (
                <div className="absolute z-10 w-full mt-1 bg-white dark:bg-gray-800 border dark:border-gray-700 rounded-md shadow-lg max-h-36 overflow-y-auto">
                  {(() => {
                    const filteredTags = tagInput.trim()
                      ? availableTags.filter(
                          (tag) =>
                            tag.name.toLowerCase().includes(tagInput.toLowerCase()) && !projectTags.includes(tag.name),
                        )
                      : availableTags.filter((tag) => !projectTags.includes(tag.name))

                    return (
                      <>
                        {filteredTags.length > 0 && filteredTags.slice(0, 8).map((tag) => (
                          <button
                            key={tag.name}
                            type="button"
                            onClick={() => {
                              setProjectTags((prev) => [...prev, tag.name])
                              setTagInput("")
                              setShowTagDropdown(false)
                            }}
                            className="w-full px-3 py-1.5 text-left hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center justify-between"
                          >
                            <span className="text-sm">{tag.name}</span>
                          </button>
                        ))}

                        {tagInput.trim() &&
                          !availableTags.some((tag) => tag.name.toLowerCase() === tagInput.toLowerCase()) &&
                          !projectTags.includes(tagInput.trim()) && (
                            <button
                              type="button"
                              onClick={() => {
                                setProjectTags((prev) => [...prev, tagInput.trim()])
                                setTagInput("")
                                setShowTagDropdown(false)
                              }}
                              className="w-full px-3 py-1.5 text-left hover:bg-gray-100 dark:hover:bg-gray-700"
                            >
                              <div className="flex items-center gap-2">
                                <svg className="w-3.5 h-3.5 text-green-600 dark:text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                                </svg>
                                <span className="text-sm">
                                  Create &quot;<strong>{tagInput.trim()}</strong>&quot;
                                </span>
                              </div>
                            </button>
                          )}

                        {filteredTags.length === 0 && !tagInput.trim() && (
                          <div className="px-3 py-1.5 text-sm text-gray-500 dark:text-gray-400">
                            {availableTags.length === 0
                              ? "No tags yet. Type to create one."
                              : "Type to search or create tags..."}
                          </div>
                        )}
                      </>
                    )
                  })()}
                </div>
              )}
            </div>

            {/* Selected Tags */}
            {projectTags.length > 0 && (
              <div className="flex flex-wrap gap-1.5">
                {projectTags.map((tag, index) => (
                  <span
                    key={index}
                    className="inline-flex items-center gap-1 px-2.5 py-0.5 bg-blue-100 dark:bg-blue-900 text-blue-800 dark:text-blue-200 text-xs rounded-full"
                  >
                    {tag}
                    <button
                      type="button"
                      onClick={() => setProjectTags((prev) => prev.filter((_, i) => i !== index))}
                      className="hover:text-blue-600 dark:hover:text-blue-300 ml-0.5"
                    >
                      <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                      </svg>
                    </button>
                  </span>
                ))}
              </div>
            )}
          </div>
          
          <div className="flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-800 rounded-lg">
            <span className="text-sm text-gray-600 dark:text-gray-300">Project size:</span>
            <span className={`text-sm font-medium ${getSizeIndicatorColor()}`}>
              {formatSize(currentProjectSize)}
            </span>
          </div>
          <div className="flex justify-end gap-2">
            <Button variant="outline" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button onClick={handleSave}>Save Project</Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  )
}

import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@game-guild/ui/components/dialog"
import { Button } from "@game-guild/ui/components/button"
import { HardDrive, FolderArchive, Image, FileText } from "lucide-react"

interface AssetInfo {
  id: string
  name: string
  size: number
  thumbnail?: string
  mimeType?: string
}

interface SizeDetailsDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  currentProjectSize: number
  currentProjectAssetsSize: number
  currentProjectAssets: AssetInfo[]
  recommendedSizeKB: number
  formatSize: (sizeInKB: number) => string
  getSizeIndicatorColor: () => string
}

export function SizeDetailsDialog({
  open,
  onOpenChange,
  currentProjectSize,
  currentProjectAssetsSize,
  currentProjectAssets,
  recommendedSizeKB,
  formatSize,
  getSizeIndicatorColor,
}: SizeDetailsDialogProps) {
  // Separate assets and collections
  const collections = currentProjectAssets.filter(asset => asset.mimeType === 'application/collection')
  const regularAssets = currentProjectAssets.filter(asset => asset.mimeType !== 'application/collection')
  
  const totalCollectionsSize = collections.reduce((sum, c) => sum + c.size, 0)
  const totalAssetsSize = regularAssets.reduce((sum, a) => sum + a.size, 0)

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>Project Size Details</DialogTitle>
        </DialogHeader>
        <div className="space-y-4">
          {/* JSON Size */}
          <div className="flex items-center justify-between rounded-lg bg-gray-50 p-3 dark:bg-gray-800">
            <span className="text-sm font-medium text-gray-700 dark:text-gray-300">JSON Content:</span>
            <span className={`text-sm font-semibold ${getSizeIndicatorColor()}`}>
              {formatSize(currentProjectSize)}
            </span>
          </div>

          {/* Assets Section */}
          {regularAssets.length > 0 && (
            <div className="space-y-2">
              <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300">
                Assets ({regularAssets.length}):
              </h4>
              <div className="max-h-60 space-y-1.5 overflow-y-auto rounded-lg bg-gray-50 p-2 dark:bg-gray-800">
                {regularAssets.map((asset) => (
                  <div
                    key={asset.id}
                    className="flex items-center gap-2 rounded bg-white px-3 py-2 text-xs dark:bg-gray-900"
                  >
                    {/* Thumbnail */}
                    {asset.thumbnail && asset.mimeType?.startsWith("image/") ? (
                      <img
                        src={asset.thumbnail}
                        alt={asset.name}
                        className="h-10 w-10 rounded border border-gray-200 object-cover dark:border-gray-700"
                      />
                    ) : asset.mimeType?.startsWith("image/") ? (
                      <div className="flex h-10 w-10 items-center justify-center rounded border border-gray-200 bg-blue-50 dark:border-gray-700 dark:bg-blue-900/30">
                        <Image className="h-5 w-5 text-blue-500 dark:text-blue-400" />
                      </div>
                    ) : (
                      <div className="flex h-10 w-10 items-center justify-center rounded border border-gray-200 bg-gray-100 dark:border-gray-700 dark:bg-gray-800">
                        <FileText className="h-5 w-5 text-gray-400 dark:text-gray-600" />
                      </div>
                    )}

                    {/* Name and Size */}
                    <div className="flex min-w-0 flex-1 items-center justify-between">
                      <span className="truncate text-gray-700 dark:text-gray-300" title={asset.name}>
                        {asset.name}
                      </span>
                      <span className="ml-2 whitespace-nowrap font-medium text-blue-600 dark:text-blue-400">
                        {formatSize(asset.size)}
                      </span>
                    </div>
                  </div>
                ))}
              </div>

              {/* Assets Subtotal */}
              <div className="flex items-center justify-between rounded-lg bg-blue-50 p-3 dark:bg-blue-900/30">
                <span className="text-sm font-medium text-blue-700 dark:text-blue-300">Total Assets:</span>
                <span className="text-sm font-semibold text-blue-600 dark:text-blue-400">
                  {formatSize(totalAssetsSize)}
                </span>
              </div>
            </div>
          )}

          {/* Collections Section */}
          {collections.length > 0 && (
            <div className="space-y-2">
              <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300">
                Collections ({collections.length}):
              </h4>
              <div className="max-h-60 space-y-1.5 overflow-y-auto rounded-lg bg-gray-50 p-2 dark:bg-gray-800">
                {collections.map((collection) => (
                  <div
                    key={collection.id}
                    className="flex items-center gap-2 rounded bg-white px-3 py-2 text-xs dark:bg-gray-900"
                  >
                    {/* Collection Icon */}
                    <div className="flex h-10 w-10 items-center justify-center rounded border border-purple-200 bg-purple-50 dark:border-purple-700 dark:bg-purple-900/30">
                      <FolderArchive className="h-5 w-5 text-purple-500 dark:text-purple-400" />
                    </div>

                    {/* Name and Size */}
                    <div className="flex min-w-0 flex-1 items-center justify-between">
                      <span className="truncate text-gray-700 dark:text-gray-300" title={collection.name}>
                        {collection.name}
                      </span>
                      <span className="ml-2 whitespace-nowrap font-medium text-purple-600 dark:text-purple-400">
                        {formatSize(collection.size)}
                      </span>
                    </div>
                  </div>
                ))}
              </div>

              {/* Collections Subtotal */}
              <div className="flex items-center justify-between rounded-lg bg-purple-50 p-3 dark:bg-purple-900/30">
                <span className="text-sm font-medium text-purple-700 dark:text-purple-300">Total Collections:</span>
                <span className="text-sm font-semibold text-purple-600 dark:text-purple-400">
                  {formatSize(totalCollectionsSize)}
                </span>
              </div>
            </div>
          )}

          {/* Total Size */}
          <div className="flex items-center justify-between rounded-lg bg-linear-to-r from-purple-50 to-blue-50 p-3 dark:from-purple-900/30 dark:to-blue-900/30">
            <span className="text-sm font-bold text-gray-800 dark:text-gray-200">Total Project Size:</span>
            <span className={`text-lg font-bold ${getSizeIndicatorColor()}`}>
              {formatSize(currentProjectSize + currentProjectAssetsSize)}
            </span>
          </div>

          {/* Recommended size warning */}
          {currentProjectSize + currentProjectAssetsSize > recommendedSizeKB && (
            <div className="rounded-lg bg-amber-50 p-3 dark:bg-amber-900/30">
              <p className="text-xs text-amber-800 dark:text-amber-200">
                ⚠️ Your project exceeds the recommended size of {formatSize(recommendedSizeKB)}. Consider
                optimizing images or splitting content.
              </p>
            </div>
          )}

          <div className="flex justify-end">
            <Button variant="outline" onClick={() => onOpenChange(false)}>
              Close
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  )
}

"use client"

interface SyncSettingsDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
}

export function SyncSettingsDialog({ open, onOpenChange }: SyncSettingsDialogProps) {
