}

"use client"

import { useCallback, useEffect, useMemo, useState } from "react"
import {
  Code2,
  File as FileIcon,
  Pencil,
  Plus,
  RefreshCw,
  Save,
  ShieldAlert,
  Trash2,
} from "lucide-react"
import { useTheme } from "next-themes"

import { Button } from "@game-guild/ui/components/button"
import { Input } from "@game-guild/ui/components/input"
import { cn } from "@/lib/utils"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@game-guild/ui/components/tooltip"

import { BlockEditorShell } from "@/components/block-content-editor/extras/block-editor-shell"
import { useEditorSettings } from "../settings-menu"
import { FileTabs } from "../code-studio/file-tabs"
import { MonacoCodeEditor } from "../code-studio/monaco-code-editor"
import type { CodeFile } from "../code-studio/types"

import type { HTMLData, HTMLFile } from "@/components/block-content-editor/nodes/html-node"
import {
  ALLOWED_HTML_EXTENSIONS,
  buildHTMLPreviewSrcDoc,
  createDefaultHTMLData,
  languageForFile,
  validateHTMLFileName,
} from "./html-utils"
import { DeleteConfirmDialog } from "../dialogs/delete-confirm-dialog"

interface HTMLEditorProps {
  initialData?: HTMLData
  onSave: (data: HTMLData) => void
  onCancel: () => void
}

/**
 * Two-pane custom-node editor:
 *   - Left: file explorer + tab strip + Monaco editor (HTML/CSS/JSON/XML).
 *   - Right: live iframe preview built from `index.html` and sibling files.
 *
 * Scripting is disabled at every layer: the file allowlist rejects
 * JS-flavoured extensions (`html-utils.validateHTMLFileName`), the
 * preview document strips `<script>` tags and inline event handlers, and
 * the iframe runs with an empty `sandbox` attribute (no scripts, no
 * same-origin).
 */
export function HTMLEditor({ initialData, onSave, onCancel }: HTMLEditorProps) {
  const { resolvedTheme } = useTheme()
  const isDarkMode = resolvedTheme === "dark"
  const settings = useEditorSettings("html")

  // ------------------------------------------------------------------
  // Multi-file state — seeded from initialData or a fresh default.
  // ------------------------------------------------------------------
  const [data, setData] = useState<HTMLData>(() => {
    if (initialData && Array.isArray(initialData.files) && initialData.files.length > 0) {
      return {
        files: initialData.files,
        openTabs: initialData.openTabs?.length ? initialData.openTabs : [initialData.files[0]!.id],
        activeFileId: initialData.activeFileId ?? initialData.files[0]!.id,
      }
    }
    return createDefaultHTMLData()
  })

  const activeFile = useMemo(
    () => data.files.find(f => f.id === data.activeFileId) ?? data.files[0],
    [data.files, data.activeFileId],
  )

  // ------------------------------------------------------------------
  // Live iframe preview — rebuilt with a short debounce when files change.
  // ------------------------------------------------------------------
  const [previewDoc, setPreviewDoc] = useState<string>("")
  useEffect(() => {
    const handle = setTimeout(() => setPreviewDoc(buildHTMLPreviewSrcDoc(data.files)), 200)
    return () => clearTimeout(handle)
  }, [data.files])

  // ------------------------------------------------------------------
  // File operations
  // ------------------------------------------------------------------
  const [newFileName, setNewFileName] = useState("")
  const [newFileError, setNewFileError] = useState<string | null>(null)
  const [renamingId, setRenamingId] = useState<string | null>(null)
  const [renameValue, setRenameValue] = useState("")
  const [renameError, setRenameError] = useState<string | null>(null)
  const [pendingDelete, setPendingDelete] = useState<HTMLFile | null>(null)

  const updateActive = useCallback((id: string) => {
    setData(prev => {
      const exists = prev.files.some(f => f.id === id)
      if (!exists) return prev
      const openTabs = prev.openTabs.includes(id) ? prev.openTabs : [...prev.openTabs, id]
      return { ...prev, activeFileId: id, openTabs }
    })
  }, [])

  const updateContent = useCallback((id: string, content: string) => {
    setData(prev => ({
      ...prev,
      files: prev.files.map(f => (f.id === id ? { ...f, content } : f)),
    }))
  }, [])

  const handleCreateFile = useCallback(() => {
    const validation = validateHTMLFileName(newFileName, data.files.map(f => f.name))
    if (!validation.ok) {
      setNewFileError(validation.reason ?? "Invalid file name")
      return
    }
    const id = typeof crypto !== "undefined" ? crypto.randomUUID() : `f-${Date.now()}`
    const file: HTMLFile = { id, name: newFileName.trim(), content: "" }
    setData(prev => ({
      files: [...prev.files, file],
      openTabs: [...prev.openTabs, id],
      activeFileId: id,
    }))
    setNewFileName("")
    setNewFileError(null)
  }, [newFileName, data.files])

  const beginRename = useCallback((file: HTMLFile) => {
    setRenamingId(file.id)
    setRenameValue(file.name)
    setRenameError(null)
  }, [])

  const commitRename = useCallback(() => {
    if (!renamingId) return
    const current = data.files.find(f => f.id === renamingId)
    if (!current) {
      setRenamingId(null)
      return
    }
    if (renameValue.trim() === current.name) {
      setRenamingId(null)
      return
    }
    const others = data.files.filter(f => f.id !== renamingId).map(f => f.name)
    const validation = validateHTMLFileName(renameValue, others)
    if (!validation.ok) {
      setRenameError(validation.reason ?? "Invalid file name")
      return
    }
    setData(prev => ({
      ...prev,
      files: prev.files.map(f => (f.id === renamingId ? { ...f, name: renameValue.trim() } : f)),
    }))
    setRenamingId(null)
    setRenameError(null)
  }, [renamingId, renameValue, data.files])

  const performDelete = useCallback(() => {
    if (!pendingDelete) return
    const id = pendingDelete.id
    setData(prev => {
      const files = prev.files.filter(f => f.id !== id)
      const openTabs = prev.openTabs.filter(t => t !== id)
      const activeFileId =
        prev.activeFileId === id
          ? (openTabs[openTabs.length - 1] ?? files[0]?.id)
          : prev.activeFileId
      return { files, openTabs, activeFileId }
    })
    setPendingDelete(null)
  }, [pendingDelete])

  const handleCloseTab = useCallback((id: string) => {
    setData(prev => {
      const openTabs = prev.openTabs.filter(t => t !== id)
      const activeFileId =
        prev.activeFileId === id
          ? (openTabs[openTabs.length - 1] ?? prev.files[0]?.id)
          : prev.activeFileId
      return { ...prev, openTabs, activeFileId }
    })
  }, [])

  const handleReorderTabs = useCallback((newOrder: string[]) => {
    setData(prev => ({ ...prev, openTabs: newOrder }))
  }, [])

  // ------------------------------------------------------------------
  // Adapt our HTMLFile[] to code-studio's CodeFile[] for FileTabs reuse.
  // ------------------------------------------------------------------
  const tabFiles: CodeFile[] = useMemo(
    () =>
      data.files.map(f => ({
        id: f.id,
        name: f.name,
        content: f.content,
        language: languageForFile(f.name),
        isFile: "f",
        isVisible: true,
        path: f.name,
      })),
    [data.files],
  )

  const handleSave = () => {
    onSave(data)
  }

  return (
    <BlockEditorShell
      settings={settings}
      onClose={onCancel}
      icon={<Code2 className="h-5 w-5 text-orange-600 dark:text-orange-400" />}
      title="HTML Custom Block"
      headerMeta={
        <div className="flex items-center gap-1 text-xs text-amber-600 dark:text-amber-400">
          <ShieldAlert className="h-3.5 w-3.5" />
          <span>Scripts disabled</span>
        </div>
      }
      footer={
        <div className="flex gap-2 justify-end">
          <Button
            variant="outline"
            onClick={onCancel}
            className="border-gray-300 dark:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-800 bg-transparent"
          >
            Cancel
          </Button>
          <Button
            onClick={handleSave}
            className="flex items-center gap-2 bg-orange-600 hover:bg-orange-700 dark:bg-orange-500 dark:hover:bg-orange-600"
          >
            <Save className="h-4 w-4" />
            Save
          </Button>
        </div>
      }
    >
      <div className="flex-1 overflow-hidden flex">
        {/* LEFT — Editor environment */}
        <div className="flex-1 min-w-0 flex border-r border-gray-200 dark:border-gray-800">
          {/* File panel */}
          <aside className="w-56 shrink-0 flex flex-col border-r border-gray-200 dark:border-gray-800 bg-gray-50 dark:bg-gray-950">
            <div className="px-3 py-2 border-b border-gray-200 dark:border-gray-800 flex items-center justify-between">
              <h3 className="text-[11px] font-semibold uppercase tracking-wide text-gray-600 dark:text-gray-400">
                Files
              </h3>
              <span className="text-[10px] text-gray-400 dark:text-gray-600">
                {data.files.length}
              </span>
            </div>

            <ul className="flex-1 overflow-y-auto py-1">
              {data.files.map(file => {
                const isActive = file.id === data.activeFileId
                const isRenaming = renamingId === file.id
                return (
                  <li key={file.id}>
                    {isRenaming ? (
                      <div className="px-2 py-1">
                        <Input
                          autoFocus
                          value={renameValue}
                          onChange={e => {
                            setRenameValue(e.target.value)
                            setRenameError(null)
                          }}
                          onBlur={commitRename}
                          onKeyDown={e => {
                            if (e.key === "Enter") commitRename()
                            else if (e.key === "Escape") {
                              setRenamingId(null)
                              setRenameError(null)
                            }
                          }}
                          className="h-7 text-xs"
                        />
                        {renameError && (
                          <p className="mt-1 text-[10px] text-red-600 dark:text-red-400">
                            {renameError}
                          </p>
                        )}
                      </div>
                    ) : (
                      <div
                        className={cn(
                          "group flex items-center gap-1.5 px-3 py-1 cursor-pointer text-xs",
                          isActive
                            ? "bg-white dark:bg-gray-900 text-orange-600 dark:text-orange-400 font-medium"
                            : "text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-900",
                        )}
                        onClick={() => updateActive(file.id)}
                      >
                        <FileIcon className="h-3 w-3 shrink-0" />
                        <span className="truncate flex-1">{file.name}</span>
                        <button
                          type="button"
                          aria-label={`Rename ${file.name}`}
                          className="opacity-0 group-hover:opacity-100 text-gray-400 hover:text-gray-700 dark:hover:text-gray-200"
                          onClick={e => {
                            e.stopPropagation()
                            beginRename(file)
                          }}
                        >
                          <Pencil className="h-3 w-3" />
                        </button>
                        <button
                          type="button"
                          aria-label={`Delete ${file.name}`}
                          className="opacity-0 group-hover:opacity-100 text-gray-400 hover:text-red-600 dark:hover:text-red-400"
                          onClick={e => {
                            e.stopPropagation()
                            setPendingDelete(file)
                          }}
                        >
                          <Trash2 className="h-3 w-3" />
                        </button>
                      </div>
                    )}
                  </li>
                )
              })}
            </ul>

            <div className="border-t border-gray-200 dark:border-gray-800 p-2 space-y-1">
              <div className="flex gap-1">
                <Input
                  value={newFileName}
                  onChange={e => {
                    setNewFileName(e.target.value)
                    setNewFileError(null)
                  }}
                  onKeyDown={e => {
                    if (e.key === "Enter") handleCreateFile()
                  }}
                  placeholder="name.html"
                  className="h-7 text-xs"
                />
                <TooltipProvider delay={300}>
                  <Tooltip>
                    <TooltipTrigger render={<Button type="button"
                        size="sm"
                        variant="outline"
                        onClick={handleCreateFile}
                        disabled={!newFileName.trim()}
                        className="h-7 px-2" />}>
                      <Plus className="h-3.5 w-3.5" />
                    </TooltipTrigger>
                    <TooltipContent side="top">Add file</TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              </div>
              {newFileError && (
                <p className="text-[10px] text-red-600 dark:text-red-400">{newFileError}</p>
              )}
              <p className="text-[10px] text-gray-500 dark:text-gray-500">
                Allowed: {ALLOWED_HTML_EXTENSIONS.join(", ")}
              </p>
            </div>
          </aside>

          {/* Tabs + Monaco */}
          <div className="flex-1 min-w-0 flex flex-col">
            <FileTabs
              files={tabFiles}
              openTabs={data.openTabs}
              activeFileId={data.activeFileId}
              onSelectTab={updateActive}
              onCloseTab={handleCloseTab}
              onReorderTabs={handleReorderTabs}
            />
            <div className="flex-1 min-h-0">
              {activeFile ? (
                <MonacoCodeEditor
                  key={activeFile.id}
                  value={activeFile.content}
                  language={languageForFile(activeFile.name)}
                  onChange={(value) => updateContent(activeFile.id, value)}
                  options={settings.editor}
                  fileId={activeFile.id}
                  filePath={activeFile.name}
                  instanceId={`html-block-${activeFile.id}`}
                />
              ) : (
                <div className="h-full flex items-center justify-center text-sm text-gray-500 dark:text-gray-500">
                  No file selected.
                </div>
              )}
            </div>
          </div>
        </div>

        {/* RIGHT — Live preview */}
        <div className="w-2/5 min-w-[320px] flex flex-col bg-white dark:bg-gray-950">
          <div className="px-4 py-2 border-b border-gray-200 dark:border-gray-800 bg-gray-50 dark:bg-gray-900 flex items-center justify-between">
            <h3 className="text-[11px] font-semibold uppercase tracking-wide text-gray-600 dark:text-gray-400">
              Live preview · index.html
            </h3>
            <Button
              type="button"
              size="sm"
              variant="ghost"
              className="h-6 px-2 text-[11px]"
              onClick={() => setPreviewDoc(buildHTMLPreviewSrcDoc(data.files))}
              title="Refresh preview"
            >
              <RefreshCw className="h-3 w-3" />
            </Button>
          </div>
          <div className="flex-1 overflow-hidden">
            <iframe
              key={isDarkMode ? "dark" : "light"}
              srcDoc={previewDoc}
              title="HTML preview"
              sandbox=""
              className="w-full h-full border-0 bg-white"
            />
          </div>
        </div>
      </div>

      {pendingDelete && (
        <DeleteConfirmDialog
          open
          onOpenChange={(open) => {
            if (!open) setPendingDelete(null)
          }}
          title={`Delete ${pendingDelete.name}?`}
          itemName={pendingDelete.name}
          itemType="file"
          onConfirm={performDelete}
          confirmText="Delete"
        />
      )}
    </BlockEditorShell>
  )
}

/**
 * Helpers shared between the HTML editor surface and the HTML preview
 * surface. Lives outside of `html-editor.tsx` so the read-only preview
 * (used in the viewer / serialized renderer) does not pull in the Monaco
 * bundle.
 *
 * Security model:
 *   - JS-bearing extensions are rejected at file create / rename time.
 *   - Inline `<script>` tags are stripped from the preview render.
 *   - DOMPurify sanitises the index.html before parsing, with
 *     `WHOLE_DOCUMENT` so we keep <head>, <link>, <style>, <meta>.
 *   - The preview iframe runs with an empty `sandbox` attribute (no
 *     scripts, no same-origin), so even if a tag slipped through it
 *     could not execute.
 *
 * Cross-file resolution:
 *   - `<link rel="stylesheet" href="X.css">` is inlined as a `<style>`
 *     block with the CSS file's content.
 *   - `[src]` / anchor `[href]` referencing a known file is replaced
 *     with a `data:` URL of that file's content. We use data URLs (not
 *     blob URLs) so callers never need to manage URL lifecycle.
 */

import type { HTMLData, HTMLFile } from "../../nodes/html-node"
import type { SupportedLanguage } from "../code-studio/types"

// ---------------------------------------------------------------------------
// Allowed / blocked file extensions
// ---------------------------------------------------------------------------

/**
 * Lowercase extensions accepted by the HTML custom-node editor. Anything
 * outside this list — and notably every JS-flavoured extension — is
 * rejected at the editor boundary.
 */
export const ALLOWED_HTML_EXTENSIONS = [
  "html",
  "htm",
  "css",
  "json",
  "xml",
  "svg",
  "md",
] as const

export type AllowedHTMLExtension = (typeof ALLOWED_HTML_EXTENSIONS)[number]

/**
 * Extensions explicitly rejected. Listed separately so the error message
 * can say "scripts blocked" instead of "unknown extension" — better UX
 * for the common attempt to add a .js file.
 */
export const BLOCKED_HTML_EXTENSIONS = [
  "js",
  "mjs",
  "cjs",
  "ts",
  "tsx",
  "jsx",
  "wasm",
  "py",
  "rb",
  "php",
  "sh",
  "bat",
  "exe",
  "dll",
] as const

export function getExtension(name: string): string {
  const trimmed = name.trim()
  const dot = trimmed.lastIndexOf(".")
  if (dot <= 0 || dot === trimmed.length - 1) return ""
  return trimmed.slice(dot + 1).toLowerCase()
}

export interface FileNameValidation {
  ok: boolean
  reason?: string
}

export function validateHTMLFileName(name: string, existingNames: string[] = []): FileNameValidation {
  const trimmed = name.trim()
  if (!trimmed) return { ok: false, reason: "File name is required" }
  if (/[\\/]/.test(trimmed)) return { ok: false, reason: "File name cannot contain / or \\" }
  if (trimmed.length > 100) return { ok: false, reason: "File name is too long" }
  const ext = getExtension(trimmed)
  if (!ext) return { ok: false, reason: "File must have an extension" }
  if ((BLOCKED_HTML_EXTENSIONS as readonly string[]).includes(ext)) {
    return { ok: false, reason: `.${ext} is not allowed (scripts are blocked)` }
  }
  if (!(ALLOWED_HTML_EXTENSIONS as readonly string[]).includes(ext)) {
    return { ok: false, reason: `.${ext} is not supported (use ${ALLOWED_HTML_EXTENSIONS.join(", ")})` }
  }
  const lower = trimmed.toLowerCase()
  if (existingNames.some(n => n.toLowerCase() === lower)) {
    return { ok: false, reason: `A file named "${trimmed}" already exists` }
  }
  return { ok: true }
}

// ---------------------------------------------------------------------------
// Language inference for the Monaco surface
// ---------------------------------------------------------------------------

export function languageForFile(name: string): SupportedLanguage {
  switch (getExtension(name)) {
    case "html":
    case "htm":
    case "svg":
      return "html"
    case "css":
      return "css"
    case "json":
      return "json"
    case "xml":
      return "xml"
    case "md":
      return "markdown"
    default:
      return "html"
  }
}

// ---------------------------------------------------------------------------
// MIME helpers (for cross-file data: URLs in the preview)
// ---------------------------------------------------------------------------

export function mimeForFile(name: string): string {
  switch (getExtension(name)) {
    case "html":
    case "htm":
      return "text/html;charset=utf-8"
    case "css":
      return "text/css;charset=utf-8"
    case "json":
      return "application/json;charset=utf-8"
    case "xml":
      return "application/xml;charset=utf-8"
    case "svg":
      return "image/svg+xml;charset=utf-8"
    case "md":
      return "text/markdown;charset=utf-8"
    default:
      return "text/plain;charset=utf-8"
  }
}

/** UTF-8 safe base64 encode (`btoa` is latin-1 only). */
function encodeBase64Utf8(text: string): string {
  if (typeof window === "undefined") return ""
  const bytes = new TextEncoder().encode(text)
  let binary = ""
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]!)
  return window.btoa(binary)
}

export function dataUrlForFile(file: HTMLFile): string {
  return `data:${mimeForFile(file.name)};base64,${encodeBase64Utf8(file.content)}`
}

// ---------------------------------------------------------------------------
// Preview document builder
// ---------------------------------------------------------------------------

const PREVIEW_PLACEHOLDER = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="font-family:system-ui,sans-serif;color:#9ca3af;padding:24px"><em>No index.html — create one to see the preview.</em></body></html>`

function findFile(files: HTMLFile[], name: string): HTMLFile | undefined {
  const lower = name.toLowerCase()
  return files.find(f => f.name.toLowerCase() === lower)
}

/**
 * Build the `srcdoc` for the preview iframe by resolving cross-file
 * references inside `index.html` against `files`. Returns a placeholder
 * document when no `index.html` is present.
 *
 * Must run client-side (uses DOMParser). The DOMPurify import is
 * client-only as well.
 */
export function buildHTMLPreviewSrcDoc(files: HTMLFile[]): string {
  if (typeof window === "undefined") return PREVIEW_PLACEHOLDER
  const index = findFile(files, "index.html")
  if (!index) return PREVIEW_PLACEHOLDER

  // Lazy require so server bundles don't pull DOMPurify.
  // dompurify v3 exports the factory as the module itself (callable);
  // invoke it with `window` to obtain an instance bound to this realm.
  const createDOMPurify = require("dompurify") as (win: Window) => {
    sanitize: (input: string, cfg?: Record<string, unknown>) => string
  }
  const DOMPurify = createDOMPurify(window)

  // Strip <script> tags up-front (belt-and-suspenders alongside the sandbox
  // attribute and DOMPurify's FORBID_TAGS). DOMParser-based removal because
  // a regex strip is bypassable by nested/trick markup.
  const parsed = new DOMParser().parseFromString(index.content, "text/html")
  parsed.querySelectorAll("script").forEach(el => el.remove())
  const stripped = `<!DOCTYPE html>${parsed.documentElement.outerHTML}`

  const sanitized = DOMPurify.sanitize(stripped, {
    WHOLE_DOCUMENT: true,
    FORBID_TAGS: ["script"],
    FORBID_ATTR: [
      "onload",
      "onerror",
      "onclick",
      "onmouseover",
      "onfocus",
      "onblur",
      "onchange",
      "oninput",
      "onsubmit",
      "onkeydown",
      "onkeyup",
      "onkeypress",
    ],
  }) as string

  const doc = new DOMParser().parseFromString(sanitized, "text/html")

  // Inline referenced stylesheets.
  doc.querySelectorAll("link[rel='stylesheet'][href]").forEach(link => {
    const href = link.getAttribute("href") ?? ""
    const file = findFile(files, href)
    if (!file) return
    const style = doc.createElement("style")
    style.textContent = file.content
    link.replaceWith(style)
  })

  // Rewrite [src]/[href] referring to known sibling files into data: URLs.
  const rewriteAttr = (selector: string, attr: "src" | "href") => {
    doc.querySelectorAll(selector).forEach(el => {
      const v = el.getAttribute(attr)
      if (!v) return
      const file = findFile(files, v)
      if (file) el.setAttribute(attr, dataUrlForFile(file))
    })
  }
  rewriteAttr("[src]", "src")
  rewriteAttr("a[href]", "href")
  rewriteAttr("link[href]", "href")
  rewriteAttr("use[href]", "href")
  rewriteAttr("image[href]", "href")

  // Ensure <base target="_blank"> so anchor clicks don't try to navigate
  // the iframe (which has empty sandbox and would just break).
  if (!doc.querySelector("base")) {
    const base = doc.createElement("base")
    base.setAttribute("target", "_blank")
    doc.head.prepend(base)
  }

  return `<!DOCTYPE html>${doc.documentElement.outerHTML}`
}

// ---------------------------------------------------------------------------
// Default seed used when a new "html" block is created
// ---------------------------------------------------------------------------

export function createDefaultHTMLData(): HTMLData {
  const indexId = (typeof crypto !== "undefined" ? crypto.randomUUID() : `idx-${Date.now()}`)
  const cssId = (typeof crypto !== "undefined" ? crypto.randomUUID() : `css-${Date.now()}`)
  return {
    files: [
      {
        id: indexId,
        name: "index.html",
        content: `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Custom Block</title>
  <link rel="stylesheet" href="styles.css">
</head>
<body>
  <main>
    <h1>Hello, world!</h1>
    <p>Edit <code>index.html</code> on the left to start building.</p>
  </main>
</body>
</html>`,
      },
      {
        id: cssId,
        name: "styles.css",
        content: `body {
  font-family: system-ui, -apple-system, sans-serif;
  margin: 0;
  padding: 24px;
  color: #1f2937;
  background: #ffffff;
}

main { max-width: 640px; margin: 0 auto; }
h1 { color: #ea580c; }
code { background: #f3f4f6; padding: 2px 6px; border-radius: 4px; }
`,
      },
    ],
    openTabs: [indexId],
    activeFileId: indexId,
  }
}

"use client"
import { Button } from "@game-guild/ui/components/button"
import { Slider } from "@game-guild/ui/components/slider"
import { Minus, Plus } from "lucide-react"

interface ImageSizeControlProps {
  size: number
  onChange: (size: number) => void
  className?: string
}

interface SizePreset {
  name: string
  size: number
}

const sizePresets: SizePreset[] = [
  { name: "Full", size: 100 },
  { name: "Regular", size: 75 },
  { name: "Small", size: 50 },
]

export function ImageSizeControl({ size, onChange, className }: ImageSizeControlProps) {
  const decreaseSize = () => {
    const newSize = Math.max(10, size - 10)
    onChange(newSize)
  }

  const increaseSize = () => {
    const newSize = Math.min(100, size + 10)
    onChange(newSize)
  }

  return (
    <div className={`flex flex-col gap-2 ${className}`}>
      <div className="flex items-center justify-between gap-2">
        {sizePresets.map((preset) => (
          <Button
            key={preset.name}
            variant={size === preset.size ? "secondary" : "ghost"}
            size="sm"
            className="flex-1"
            onClick={() => onChange(preset.size)}
          >
            {preset.name}
          </Button>
        ))}
      </div>
      <div className="flex items-center gap-2">
        <Button variant="ghost" size="icon" className="h-8 w-8" onClick={decreaseSize} disabled={size <= 10}>
          <Minus className="h-4 w-4" />
        </Button>
        <Slider
          value={[size]}
          min={10}
          max={100}
          step={1}
          className="flex-1"
          onValueChange={(values) => onChange((Array.isArray(values) ? values[0] : values) ?? size)}
        />
        <Button variant="ghost" size="icon" className="h-8 w-8" onClick={increaseSize} disabled={size >= 100}>
          <Plus className="h-4 w-4" />
        </Button>
        <div className="min-w-[3rem] text-sm text-center">{size}%</div>
      </div>
    </div>
  )
}

"use client"

import React from 'react'
import { Card as ShadcnCard } from "@/components/ui/card"
import { Badge } from "@game-guild/ui/components/badge"
import { Button } from "@game-guild/ui/components/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@game-guild/ui/components/dropdown-menu"
import { MoreVertical } from 'lucide-react'
import { type AssetCard, type CardAction } from '../types'
import { formatFileSize, getMimeTypeIcon, getMimeTypeBadgeColor } from './utils'
import { useAssetPreview } from './hooks'
import { CardActionsMenu } from './card-actions-menu'

interface AssetCardComponentProps {
  card: AssetCard
  isGrid: boolean
  isCompact?: boolean
  primaryActions: CardAction[]
  secondaryActions: CardAction[]
  onClick?: (card: AssetCard) => void
}

export function AssetCardComponent({ 
  card, 
  isGrid, 
  isCompact = false, 
  primaryActions, 
  secondaryActions, 
  onClick 
}: AssetCardComponentProps) {
  const assetDataUrl = useAssetPreview(card.id, card.mimeType)
  const Icon = getMimeTypeIcon(card.mimeType)
  const isImage = card.mimeType.startsWith('image/')
  const mimeTypeCategory = card.mimeType.split('/')[0]
  const mimeTypeDetail = card.mimeType.split('/')[1]

  if (isGrid) {
    if (isCompact) {
      return (
        <ShadcnCard 
          className="group relative border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 shadow-sm hover:shadow-lg hover:border-gray-300 dark:hover:border-gray-600 transition-all duration-200 cursor-pointer overflow-hidden aspect-video"
          onClick={() => onClick?.(card)}
        >
          <div className="absolute inset-0 bg-gray-100 dark:bg-gray-900 flex items-center justify-center">
            {isImage && assetDataUrl ? (
              <img 
                src={assetDataUrl} 
                alt={card.name}
                className="w-full h-full object-cover"
              />
            ) : (
              <Icon className="w-8 h-8 text-gray-400 dark:text-gray-600" />
            )}
          </div>

          <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity">
            <DropdownMenu>
              <DropdownMenuTrigger onClick={(e) => e.stopPropagation()} render={<Button variant="secondary" 
                  size="sm" 
                  className="h-7 w-7 p-0 bg-white/90 dark:bg-gray-800/90 backdrop-blur-sm hover:bg-white dark:hover:bg-gray-800 shadow-md" />}>
                <MoreVertical className="h-4 w-4" />
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-56">
                <div className="px-2 py-2 border-b border-gray-200 dark:border-gray-700">
                  <div className="text-xs font-medium text-gray-900 dark:text-white truncate mb-1">
                    {card.name}
                  </div>
                  <div className="flex flex-wrap gap-1 mb-1">
                    <Badge className={`text-[10px] px-1.5 py-0.5 ${getMimeTypeBadgeColor(card.mimeType)}`}>
                      {mimeTypeCategory}/{mimeTypeDetail}
                    </Badge>
                  </div>
                  <div className="text-[10px] text-gray-500 dark:text-gray-400">
                    {formatFileSize(card.size)}
                  </div>
                </div>
                
                {primaryActions.map((action, idx) => (
                  <DropdownMenuItem 
                    key={idx}
                    onClick={(e) => {
                      e.stopPropagation()
                      action.onClick(card)
                    }}
                  >
                    {action.icon}
                    <span className="ml-2">{action.label}</span>
                  </DropdownMenuItem>
                ))}
                {secondaryActions.length > 0 && <DropdownMenuSeparator />}
                {secondaryActions.map((action, idx) => (
                  <DropdownMenuItem 
                    key={idx}
                    onClick={(e) => {
                      e.stopPropagation()
                      action.onClick(card)
                    }}
                    className={action.variant === 'destructive' ? 'text-red-600 dark:text-red-400' : ''}
                  >
                    {action.icon}
                    <span className="ml-2">{action.label}</span>
                  </DropdownMenuItem>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </ShadcnCard>
      )
    }

    return (
      <ShadcnCard 
        className="group border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 shadow-sm hover:shadow-lg hover:border-gray-300 dark:hover:border-gray-600 transition-all duration-200 cursor-pointer overflow-hidden flex flex-col p-0"
        onClick={() => onClick?.(card)}
      >
        <div className="bg-gray-100 dark:bg-gray-900 flex items-center justify-center min-h-[120px] m-0">
          {isImage && assetDataUrl ? (
            <img 
              src={assetDataUrl} 
              alt={card.name}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="p-6">
              <Icon className="w-8 h-8 text-gray-400 dark:text-gray-600" />
            </div>
          )}
        </div>

        <div className="p-2 sm:p-3 flex flex-col gap-2 min-h-[70px] sm:min-h-[80px]">
          <div className="flex items-start justify-between gap-2">
            <h3 className="text-xs sm:text-sm font-medium text-gray-900 dark:text-white truncate leading-tight flex-1">
              {card.name}
            </h3>
            <CardActionsMenu
              card={card}
              primaryActions={primaryActions}
              secondaryActions={secondaryActions}
              buttonClassName="h-7 w-7 sm:h-8 sm:w-8 p-0 shrink-0"
            />
          </div>

          <div className="flex flex-wrap gap-1">
            <Badge className={`text-[9px] sm:text-xs ${getMimeTypeBadgeColor(card.mimeType)}`}>
              {mimeTypeCategory}
            </Badge>
            <Badge variant="outline" className="text-[9px] sm:text-xs">
              {mimeTypeDetail}
            </Badge>
          </div>

          <div className="flex items-center justify-between text-[10px] sm:text-xs text-gray-500 dark:text-gray-400 mt-auto">
            <span>{formatFileSize(card.size)}</span>
            {card.projects && card.projects.length > 0 && (
              <Badge variant="secondary" className="text-[9px] sm:text-xs hidden sm:inline-flex">
                {card.projects.length} {card.projects.length === 1 ? 'project' : 'projects'}
              </Badge>
            )}
          </div>
        </div>
      </ShadcnCard>
    )
  }

  // List view
  return (
    <ShadcnCard 
      className="border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 shadow-sm hover:shadow-lg hover:border-gray-300 dark:hover:border-gray-600 transition-all duration-200 cursor-pointer"
      onClick={() => onClick?.(card)}
    >
      <div className="px-3 flex items-center gap-3">
        <div className="w-24 h-14 bg-gray-100 dark:bg-gray-900 rounded flex items-center justify-center shrink-0 overflow-hidden">
          {isImage && assetDataUrl ? (
            <img 
              src={assetDataUrl} 
              alt={card.name}
              className="w-full h-full object-cover"
            />
          ) : (
            <Icon className="w-5 h-5 text-gray-400 dark:text-gray-600" />
          )}
        </div>

        <div className="flex-1 min-w-0">
          <h3 className="text-sm font-medium text-gray-900 dark:text-white truncate mb-0.5">
            {card.name}
          </h3>
          <div className="flex items-center gap-1.5 flex-wrap">
            <Badge className={`text-xs py-0.5 ${getMimeTypeBadgeColor(card.mimeType)}`}>
              {mimeTypeCategory}
            </Badge>
            <Badge variant="outline" className="text-xs py-0.5">
              {mimeTypeDetail}
            </Badge>
            <span className="text-xs text-gray-500 dark:text-gray-400">
              {formatFileSize(card.size)}
            </span>
            {card.projects && card.projects.length > 0 && (
              <Badge variant="secondary" className="text-xs py-0.5">
                {card.projects.length} {card.projects.length === 1 ? 'project' : 'projects'}
              </Badge>
            )}
          </div>
        </div>

        <CardActionsMenu
          card={card}
          primaryActions={primaryActions}
          secondaryActions={secondaryActions}
          buttonClassName="h-6 w-6 p-0 shrink-0"
          iconClassName="h-3.5 w-3.5"
        />
      </div>
    </ShadcnCard>
  )
}

"use client"

import React, { useState } from 'react'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@game-guild/ui/components/popover"
import { Button } from "@game-guild/ui/components/button"
import { Badge } from "@game-guild/ui/components/badge"
import { Checkbox } from "@game-guild/ui/components/checkbox"
import { ChevronDown, ChevronRight, X } from "lucide-react"
import { ScrollArea } from "@game-guild/ui/components/scroll-area"

interface MimeTypeOption {
  value: string
  label: string
  extensions: string[]
  color: string
}

const MIME_TYPE_OPTIONS: MimeTypeOption[] = [
  {
    value: 'image',
    label: 'Images',
    extensions: ['.jpg', '.jpeg', '.png', '.gif', '.svg', '.webp', '.bmp', '.ico', '.tiff', '.psd'],
    color: 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200'
  },
  {
    value: 'video',
    label: 'Videos',
    extensions: ['.mp4', '.webm', '.ogg', '.avi', '.mov', '.wmv', '.flv', '.mkv', '.m4v', '.3gp'],
    color: 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200'
  },
  {
    value: 'audio',
    label: 'Audio',
    extensions: ['.mp3', '.wav', '.ogg', '.m4a', '.flac', '.aac', '.wma', '.opus', '.oga'],
    color: 'bg-pink-100 text-pink-800 dark:bg-pink-900 dark:text-pink-200'
  },
  {
    value: 'text',
    label: 'Text & Code',
    extensions: ['.txt', '.md', '.js', '.ts', '.jsx', '.tsx', '.json', '.xml', '.html', '.css', '.scss', '.sass', '.less', '.py', '.java', '.c', '.cpp', '.h', '.hpp', '.rs', '.go', '.rb', '.php', '.sh', '.bash', '.yml', '.yaml', '.sql', '.lua', '.r', '.swift', '.kt', '.cs', '.vb', '.pl', '.dart', '.scala'],
    color: 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200'
  },
  {
    value: 'application',
    label: 'Applications',
    extensions: ['.pdf', '.zip', '.rar', '.7z', '.tar', '.gz', '.exe', '.dmg', '.apk', '.deb', '.rpm', '.msi'],
    color: 'bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-200'
  },
  {
    value: 'font',
    label: 'Fonts',
    extensions: ['.ttf', '.otf', '.woff', '.woff2', '.eot', '.svg'],
    color: 'bg-indigo-100 text-indigo-800 dark:bg-indigo-900 dark:text-indigo-200'
  },
]

interface FilterMimeTypesProps {
  selectedTypes: string[] // Array of extensions like ['.jpg', '.png', '.mp4']
  onChange: (types: string[]) => void
  className?: string
}

export function FilterMimeTypes({ 
  selectedTypes, 
  onChange, 
  className = "w-[180px]" 
}: FilterMimeTypesProps) {
  const [open, setOpen] = useState(false)
  const [expandedCategories, setExpandedCategories] = useState<string[]>([])

  const toggleCategory = (categoryValue: string) => {
    setExpandedCategories(prev =>
      prev.includes(categoryValue)
        ? prev.filter(c => c !== categoryValue)
        : [...prev, categoryValue]
    )
  }

  const handleToggleExtension = (extension: string) => {
    if (selectedTypes.includes(extension)) {
      onChange(selectedTypes.filter(t => t !== extension))
    } else {
      onChange([...selectedTypes, extension])
    }
  }

  const handleToggleCategory = (category: MimeTypeOption) => {
    const categoryExtensions = category.extensions
    const allSelected = categoryExtensions.every(ext => selectedTypes.includes(ext))
    
    if (allSelected) {
      // Deselect all extensions from this category
      onChange(selectedTypes.filter(t => !categoryExtensions.includes(t)))
    } else {
      // Select all extensions from this category
      const newSelections = [...new Set([...selectedTypes, ...categoryExtensions])]
      onChange(newSelections)
    }
  }

  const getSelectedCountForCategory = (category: MimeTypeOption) => {
    return category.extensions.filter(ext => selectedTypes.includes(ext)).length
  }

  const isCategoryFullySelected = (category: MimeTypeOption) => {
    return category.extensions.every(ext => selectedTypes.includes(ext))
  }

  const isCategoryPartiallySelected = (category: MimeTypeOption) => {
    const count = getSelectedCountForCategory(category)
    return count > 0 && count < category.extensions.length
  }

  const handleClear = (e: React.MouseEvent) => {
    e.stopPropagation()
    onChange([])
  }

  const getButtonLabel = () => {
    if (selectedTypes.length === 0) return "File types"
    if (selectedTypes.length === 1) return selectedTypes[0]
    return `${selectedTypes.length} extensions`
  }

  return (
    <Popover
      open={open}
      onOpenChange={(nextOpen, eventDetails) => {
        if (!nextOpen && eventDetails.reason === 'outside-press') {
          const target = eventDetails.event.target as HTMLElement
          if (target.closest('[data-mime-type-content]')) {
            eventDetails.cancel()
            return
          }
        }
        setOpen(nextOpen)
      }}
    >
      <PopoverTrigger render={<Button variant="outline"
          role="combobox"
          aria-expanded={open}
          className={`${className} justify-between`} />}>
        <span className="truncate">{getButtonLabel()}</span>
        <div className="flex items-center gap-1 ml-2">
          {selectedTypes.length > 0 && (
            <button
              onClick={handleClear}
              className="hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full p-0.5"
            >
              <X className="h-3 w-3" />
            </button>
          )}
          <ChevronDown className="h-4 w-4 shrink-0 opacity-50" />
        </div>
      </PopoverTrigger>
      <PopoverContent
        className="w-[500px] p-0"
        align="start"
      >
        <div className="p-3 border-b border-gray-200 dark:border-gray-700">
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-sm font-semibold">File Types & Extensions</h4>
            {selectedTypes.length > 0 && (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => onChange([])}
                className="h-6 text-xs"
              >
                Clear all
              </Button>
            )}
          </div>
          <p className="text-xs text-gray-500 dark:text-gray-400">
            Select specific file extensions to filter
          </p>
        </div>

        <ScrollArea className="max-h-[500px]" data-mime-type-content>
          <div className="p-2 space-y-1">
            {MIME_TYPE_OPTIONS.map((option) => {
              const isExpanded = expandedCategories.includes(option.value)
              const selectedCount = getSelectedCountForCategory(option)
              const isFullySelected = isCategoryFullySelected(option)
              const isPartiallySelected = isCategoryPartiallySelected(option)

              return (
                <div
                  key={option.value}
                  className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden"
                >
                  {/* Category Header */}
                  <div className="flex items-center gap-2 p-2 bg-gray-50 dark:bg-gray-800/50 hover:bg-gray-100 dark:hover:bg-gray-800">
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-6 w-6 p-0"
                      onClick={() => toggleCategory(option.value)}
                    >
                      {isExpanded ? (
                        <ChevronDown className="h-4 w-4" />
                      ) : (
                        <ChevronRight className="h-4 w-4" />
                      )}
                    </Button>
                    
                    <Checkbox
                      checked={isFullySelected}
                      onCheckedChange={() => handleToggleCategory(option)}
                      className="mt-0"
                      {...(isPartiallySelected ? { 'data-state': 'indeterminate' as any } : {})}
                    />
                    
                    <div className="flex-1 min-w-0 flex items-center gap-2">
                      <span className="text-sm font-medium">{option.label}</span>
                      <Badge 
                        variant="secondary" 
                        className={`text-xs px-1.5 py-0 ${option.color}`}
                      >
                        {selectedCount > 0 ? `${selectedCount}/` : ''}{option.extensions.length}
                      </Badge>
                    </div>

                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-6 text-xs px-2"
                      onClick={() => toggleCategory(option.value)}
                    >
                      {isExpanded ? 'Collapse' : 'Expand'}
                    </Button>
                  </div>

                  {/* Extensions Grid */}
                  {isExpanded && (
                    <div className="p-3 bg-white dark:bg-gray-900 border-t border-gray-200 dark:border-gray-700">
                      <div className="grid grid-cols-4 gap-2">
                        {option.extensions.map((ext) => (
                          <label
                            key={ext}
                            className="flex items-center gap-2 p-2 rounded hover:bg-gray-100 dark:hover:bg-gray-800 cursor-pointer"
                          >
                            <Checkbox
                              checked={selectedTypes.includes(ext)}
                              onCheckedChange={() => handleToggleExtension(ext)}
                            />
                            <span className="text-xs font-mono text-gray-700 dark:text-gray-300">
                              {ext}
                            </span>
                          </label>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        </ScrollArea>

        <div className="p-3 border-t border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900">
          <div className="flex items-center justify-between text-xs">
            <span className="text-gray-600 dark:text-gray-400">
              {selectedTypes.length} extension{selectedTypes.length !== 1 ? 's' : ''} selected
            </span>
            <Button
              size="sm"
              onClick={() => setOpen(false)}
              className="h-7"
            >
              Done
            </Button>
          </div>
        </div>
      </PopoverContent>
    </Popover>
  )
}

"use client"

import React from 'react'
import { type FilterConfig } from '../types'
import { FilterSearch } from './filter-search'
import { FilterTags } from './filter-tags'
import { FilterSelect } from './filter-select'
import { FilterMimeTypes } from './filter-mime-types'
import { FilterSort } from './filter-sort'
import { FilterActiveBadges } from './filter-active-badges'
import {
  STORAGE_TYPE_OPTIONS,
  MIME_TYPE_OPTIONS,
  ASSET_TYPE_OPTIONS,
  USAGE_FILTER_OPTIONS,
  ITEMS_PER_PAGE_OPTIONS,
} from './filter-options'

interface ManagerFiltersProps {
  filters: FilterConfig
  onFilterChange: (filters: Partial<FilterConfig>) => void
  availableTags?: Array<{ name: string }>
  availableProjects?: Array<{ id: string; name: string }>
  contextType: 'projects' | 'assets' | 'collections'
  itemsPerPage: number
  onItemsPerPageChange: (items: number) => void
}

export function ManagerFilters({
  filters,
  onFilterChange,
  availableTags = [],
  availableProjects = [],
  contextType,
  itemsPerPage,
  onItemsPerPageChange,
}: ManagerFiltersProps) {
  const isProjectContext = contextType === 'projects'
  const isAssetContext = contextType === 'assets'
  const isCollectionContext = contextType === 'collections'

  const searchPlaceholder = isProjectContext 
    ? "Search projects..." 
    : isAssetContext 
    ? "Search assets..." 
    : "Search collections..."

  const projectOptions = [
    { value: 'all', label: 'All projects' },
    ...availableProjects.map(p => ({ value: p.id, label: p.name }))
  ]

  return (
    <div className="p-4 space-y-4">
      {/* Search and Tags Row */}
      <div className="flex items-center gap-2 flex-wrap">
        <FilterSearch
          value={filters.searchTerm}
          onChange={(value) => onFilterChange({ searchTerm: value })}
          placeholder={searchPlaceholder}
        />

        {(isProjectContext || isCollectionContext) && availableTags.length > 0 && (
          <FilterTags
            selectedTags={filters.tags || []}
            availableTags={availableTags}
            tagFilterMode={filters.tagFilterMode || 'all'}
            onTagsChange={(tags) => onFilterChange({ tags })}
            onModeChange={(mode) => onFilterChange({ tagFilterMode: mode })}
          />
        )}

        <FilterSelect
          value={itemsPerPage.toString()}
          onChange={(value) => onItemsPerPageChange(parseInt(value))}
          options={ITEMS_PER_PAGE_OPTIONS}
          className="w-[140px]"
        />
      </div>

      {/* Additional Filters Row */}
      <div className="flex items-center gap-2 flex-wrap">
        {isProjectContext && (
          <FilterSelect
            value={filters.storageType || 'all'}
            onChange={(value) => onFilterChange({ storageType: value as any })}
            options={STORAGE_TYPE_OPTIONS}
            placeholder="Storage type"
            className="w-[180px]"
          />
        )}

        {isAssetContext && (
          <>
            <FilterMimeTypes
              selectedTypes={filters.mimeTypes || []}
              onChange={(types) => { onFilterChange({ mimeTypes: types }); }}
            />

            <FilterSelect
              value={filters.assetType || 'all'}
              onChange={(value) => onFilterChange({ assetType: value as any })}
              options={ASSET_TYPE_OPTIONS}
              placeholder="Asset type"
            />

            {availableProjects.length > 0 && (
              <FilterSelect
                value={filters.projectFilter || 'all'}
                onChange={(value) => onFilterChange({ projectFilter: value })}
                options={projectOptions}
                placeholder="Filter by project"
                className="w-[180px]"
              />
            )}

            <FilterSelect
              value={filters.usageFilter || 'all'}
              onChange={(value) => onFilterChange({ usageFilter: value as any })}
              options={USAGE_FILTER_OPTIONS}
              placeholder="Usage"
            />
          </>
        )}

        <FilterSort
          sortOrder={filters.sortOrder || []}
          onSortChange={(sortOrder) => onFilterChange({ sortOrder })}
        />
      </div>

      <FilterActiveBadges
        filters={filters}
        availableProjects={availableProjects}
        onFilterChange={onFilterChange}
      />
    </div>
  )
}

/**
 * Sorting utilities for manager page
 * Handles multi-criteria sorting with normalized scoring
 */

type SortOrder = 'newest' | 'oldest' | 'name' | 'name-desc' | 'size-largest' | 'size-smallest'

interface SortableItem {
  name: string
  size?: number
  totalSize?: number  // For collections
  createdAt?: string
  updatedAt?: string
  created?: string    // For collections
  updated?: string    // For collections
}

/**
 * Apply multi-criteria sorting with averaged scoring
 * Each criterion contributes equally to the final sort order
 */
export function applySorting<T extends SortableItem>(
  items: T[],
  sortOrder: SortOrder[],
  dateField: 'createdAt' | 'updatedAt' | 'created' | 'updated' = 'updatedAt'
): T[] {
  if (!sortOrder || sortOrder.length === 0) {
    // Default: newest first
    const field = dateField
    return [...items].sort((a, b) => {
      const dateA = a[field] ? new Date(a[field]!).getTime() : 0
      const dateB = b[field] ? new Date(b[field]!).getTime() : 0
      return dateB - dateA
    })
  }

  const sorted = [...items]

  // Calculate min/max values for normalization
  const dates = sorted.map(item => {
    const dateStr = item[dateField]
    return dateStr ? new Date(dateStr).getTime() : 0
  })
  const sizes = sorted.map(item => item.size ?? item.totalSize ?? 0)
  const minDate = Math.min(...dates)
  const maxDate = Math.max(...dates)
  const minSize = Math.min(...sizes)
  const maxSize = Math.max(...sizes)

  // Calculate composite score for each item
  sorted.sort((a, b) => {
    let scoreA = 0
    let scoreB = 0

    for (const sortType of sortOrder) {
      let partialScoreA = 0
      let partialScoreB = 0

      switch (sortType) {
        case "newest": {
          // Normalize dates to 0-1 range (newer = higher score)
          const dateA = a[dateField] ? new Date(a[dateField]!).getTime() : 0
          const dateB = b[dateField] ? new Date(b[dateField]!).getTime() : 0
          partialScoreA = maxDate !== minDate ? (dateA - minDate) / (maxDate - minDate) : 0
          partialScoreB = maxDate !== minDate ? (dateB - minDate) / (maxDate - minDate) : 0
          break
        }
        case "oldest": {
          // Normalize dates to 0-1 range (older = higher score)
          const dateA = a[dateField] ? new Date(a[dateField]!).getTime() : 0
          const dateB = b[dateField] ? new Date(b[dateField]!).getTime() : 0
          partialScoreA = maxDate !== minDate ? (maxDate - dateA) / (maxDate - minDate) : 0
          partialScoreB = maxDate !== minDate ? (maxDate - dateB) / (maxDate - minDate) : 0
          break
        }
        case "name": {
          // Alphabetical: earlier in alphabet = higher score
          const comparison = a.name.toLowerCase().localeCompare(b.name.toLowerCase())
          partialScoreA = comparison <= 0 ? 1 : 0
          partialScoreB = comparison >= 0 ? 1 : 0
          break
        }
        case "name-desc": {
          // Reverse alphabetical: later in alphabet = higher score
          const comparisonDesc = b.name.toLowerCase().localeCompare(a.name.toLowerCase())
          partialScoreA = comparisonDesc <= 0 ? 1 : 0
          partialScoreB = comparisonDesc >= 0 ? 1 : 0
          break
        }
        case "size-largest": {
          // Normalize sizes to 0-1 range (larger = higher score)
          const sizeA = a.size ?? a.totalSize ?? 0
          const sizeB = b.size ?? b.totalSize ?? 0
          partialScoreA = maxSize !== minSize ? (sizeA - minSize) / (maxSize - minSize) : 0
          partialScoreB = maxSize !== minSize ? (sizeB - minSize) / (maxSize - minSize) : 0
          break
        }
        case "size-smallest": {
          // Normalize sizes to 0-1 range (smaller = higher score)
          const sizeA = a.size ?? a.totalSize ?? 0
          const sizeB = b.size ?? b.totalSize ?? 0
          partialScoreA = maxSize !== minSize ? (maxSize - sizeA) / (maxSize - minSize) : 0
          partialScoreB = maxSize !== minSize ? (maxSize - sizeB) / (maxSize - minSize) : 0
          break
        }
      }

      scoreA += partialScoreA
      scoreB += partialScoreB
    }

    // Average the scores
    scoreA /= sortOrder.length
    scoreB /= sortOrder.length

    return scoreB - scoreA // Higher score comes first
  })

  return sorted
}

import { type Components } from "react-markdown"
import { Prism as SyntaxHighlighter } from "react-syntax-highlighter"
import { vscDarkPlus, vs } from "react-syntax-highlighter/dist/esm/styles/prism"
import { useTheme } from "next-themes"
import { MermaidDiagram } from "@game-guild/content-rendering"
import { VegaLiteViewer } from "@game-guild/lexical-surface"
import { AssetImage } from "../media/asset-image"

export function useMarkdownComponents(): Components {
  const { theme } = useTheme()
  const isDarkMode = theme === "dark"

  return {
    // Code blocks with syntax highlighting
    code({ node, className, children, ...props }: any) {
      const match = /language-(\w[\w-]*)/.exec(className || "")
      const language = match ? match[1] : ""
      const inline = !className

      if (!inline && language === "mermaid") {
        return <MermaidDiagram code={String(children).replace(/\n$/, "")} />
      }

      if (!inline && (language === "vega" || language === "vegalite" || language === "vega-lite")) {
        return <VegaLiteViewer spec={String(children).replace(/\n$/, "")} />
      }

      return !inline && language ? (
        <SyntaxHighlighter
          style={isDarkMode ? (vscDarkPlus) : (vs as any)}
          language={language}
          PreTag="div"
          className="mt-4! mb-4! rounded-lg! text-sm!"
          {...props}
        >
          {String(children).replace(/\n$/, "")}
        </SyntaxHighlighter>
      ) : (
        <code
          className="px-1.5 py-0.5 rounded bg-gray-100 dark:bg-gray-800 text-pink-600 dark:text-pink-400 font-mono text-sm"
          {...props}
        >
          {children}
        </code>
      )
    },

    // Headings with proper styling
    h1: ({ children, ...props }) => (
      <h1 className="text-4xl font-bold mt-8 mb-4 text-gray-900 dark:text-gray-100" {...props}>
        {children}
      </h1>
    ),
    h2: ({ children, ...props }) => (
      <h2 className="text-3xl font-bold mt-6 mb-3 text-gray-900 dark:text-gray-100" {...props}>
        {children}
      </h2>
    ),
    h3: ({ children, ...props }) => (
      <h3 className="text-2xl font-bold mt-5 mb-2 text-gray-900 dark:text-gray-100" {...props}>
        {children}
      </h3>
    ),
    h4: ({ children, ...props }) => (
      <h4 className="text-xl font-bold mt-4 mb-2 text-gray-900 dark:text-gray-100" {...props}>
        {children}
      </h4>
    ),
    h5: ({ children, ...props }) => (
      <h5 className="text-lg font-bold mt-3 mb-2 text-gray-900 dark:text-gray-100" {...props}>
        {children}
      </h5>
    ),
    h6: ({ children, ...props }) => (
      <h6 className="text-base font-bold mt-2 mb-2 text-gray-900 dark:text-gray-100" {...props}>
        {children}
      </h6>
    ),

    // Paragraphs
    p: ({ children, ...props }) => (
      <p className="mb-4 leading-7 text-gray-700 dark:text-gray-300" {...props}>
        {children}
      </p>
    ),

    // Links
    a: ({ children, href, ...props }) => (
      <a
        href={href}
        className="text-blue-600 dark:text-blue-400 hover:underline"
        target="_blank"
        rel="noopener noreferrer"
        {...props}
      >
        {children}
      </a>
    ),

    // Blockquotes
    blockquote: ({ children, ...props }) => (
      <blockquote
        className="border-l-4 border-blue-500 bg-blue-50 dark:bg-blue-900/10 pl-4 pr-4 py-2 my-4 italic"
        {...props}
      >
        {children}
      </blockquote>
    ),

    // Lists
    ul: ({ children, ...props }) => (
      <ul className="list-disc list-inside mb-4 space-y-2 text-gray-700 dark:text-gray-300" {...props}>
        {children}
      </ul>
    ),
    ol: ({ children, ...props }) => (
      <ol className="list-decimal list-inside mb-4 space-y-2 text-gray-700 dark:text-gray-300" {...props}>
        {children}
      </ol>
    ),
    li: ({ children, ...props }) => {
      // Check if this is a task list item
      const childArray = Array.isArray(children) ? children : [children]
      const firstChild = childArray[0]
      
      if (typeof firstChild === "string") {
        // Task list item with [ ] or [x]
        const taskMatch = firstChild.match(/^\[([ x])\]\s*(.*)/)
        if (taskMatch) {
          const [, checked, text] = taskMatch
          const isChecked = checked === "x"
          const remainingChildren = childArray.slice(1)
          
          return (
            <li className="flex items-start gap-2 list-none" {...props}>
              <input
                type="checkbox"
                checked={isChecked}
