                className="mt-1 h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
              />
              <span className={isChecked ? "line-through text-gray-500 dark:text-gray-500" : ""}>
                {text}
                {remainingChildren}
              </span>
