    ),
    thead: ({ children, ...props }) => (
      <thead className="bg-gray-100 dark:bg-gray-800" {...props}>
        {children}
      </thead>
    ),
    tbody: ({ children, ...props }) => (
      <tbody {...props}>
        {children}
      </tbody>
    ),
    tr: ({ children, ...props }) => (
      <tr className="border-b border-gray-200 dark:border-gray-700" {...props}>
        {children}
      </tr>
    ),
    th: ({ children, ...props }) => (
      <th
        className="px-4 py-2 text-left font-semibold text-gray-900 dark:text-gray-100 border border-gray-300 dark:border-gray-600"
        {...props}
      >
        {children}
      </th>
    ),
    td: ({ children, ...props }) => (
      <td
        className="px-4 py-2 text-gray-700 dark:text-gray-300 border border-gray-300 dark:border-gray-600"
        {...props}
      >
        {children}
      </td>
    ),

    // Horizontal rule
    hr: ({ ...props }) => (
      <hr className="my-6 border-gray-300 dark:border-gray-700" {...props} />
    ),

    // Images
    img: ({ src, alt, ...props }) => (
      <AssetImage
        src={typeof src === "string" ? src : undefined}
        alt={alt}
        className="rounded-lg shadow-md max-w-full h-auto my-4"
        {...props}
      />
    ),

    // Strong/Bold
    strong: ({ children, ...props }) => (
      <strong className="font-bold text-gray-900 dark:text-gray-100" {...props}>
        {children}
      </strong>
    ),

    // Emphasis/Italic
    em: ({ children, ...props }) => (
      <em className="italic text-gray-800 dark:text-gray-200" {...props}>
        {children}
      </em>
    ),

    // Delete/Strikethrough
    del: ({ children, ...props }) => (
      <del className="line-through text-gray-500 dark:text-gray-500" {...props}>
        {children}
      </del>
    ),

    // Details/Summary (Collapsible)
    details: ({ children, ...props }) => (
      <details className="my-4 p-4 border border-gray-300 dark:border-gray-600 rounded-lg bg-gray-50 dark:bg-gray-800/50" {...props}>
        {children}
      </details>
    ),
    summary: ({ children, ...props }) => (
      <summary className="font-semibold text-gray-900 dark:text-gray-100 cursor-pointer hover:text-blue-600 dark:hover:text-blue-400 mb-2" {...props}>
        {children}
      </summary>
    ),
  }
}

"use client"

/**
 * Markdown block editor.
 *
 * Layout: Monaco source on the left, live `MarkdownRenderer` preview on the right.
 *
 * Embed insertion (mirrors the Lexical surface UX):
 *   1. Header "Insert Block" button → opens the shared `BlockTypePicker`.
 *   2. Inline slash menu — typing `/` in Monaco at the start of a line or
 *      after whitespace opens a typeahead listing every embeddable block
 *      type. Filtering is live (typed text after `/`), arrow keys move
 *      the selection, Enter inserts, Esc closes.
 *
 * Selection replaces the `/query` range with a `<block-embed id="..."/>`
 * token and stores the freshly-created block in `embeds`. Unused embeds
 * are pruned on save.
 */

import { useCallback, useEffect, useRef, useState } from "react"
import { createPortal } from "react-dom"
import type * as MonacoNS from "monaco-editor"

import { Button } from "@game-guild/ui/components/button"
import { Save, FileText, Blocks } from "lucide-react"
import { useTheme } from "next-themes"

import { BaseMonacoEditor } from "@/components/block-content-editor/lib/monaco"
import type { MarkdownData } from "@/components/block-content-editor/nodes/markdown-node"
import type { Block } from "@/components/block-content-editor/lib/storage/editor/block-structure"
import { useEditorSettings } from "../settings-menu"
import { BlockEditorShell } from "@/components/block-content-editor/extras/block-editor-shell"
import { MarkdownRenderer, buildEmbedToken, pruneUnusedEmbeds } from "./markdown-renderer"
import { BlockTypePicker } from "@/components/block-content-editor/engines/blocks/block-type-picker"
import {
  EMBEDDABLE_BLOCK_TYPES,
  type EmbeddableBlock,
  type EmbeddableBlockData,
  type EmbeddableBlockType,
} from "@/components/block-content-editor/embed/types"
import { BLOCK_REGISTRY } from "@/components/block-content-editor/engines/blocks/block-component-registry"
import { BLOCK_EMBED_TOKEN_RE } from "./markdown-renderer"
import { cn } from "@/lib/utils"

// ---------------------------------------------------------------------------
// Slash menu types
// ---------------------------------------------------------------------------

type IStandaloneCodeEditor = MonacoNS.editor.IStandaloneCodeEditor

interface SlashMenuState {
  query: string
  anchor: { top: number; left: number }
  /** Range covering `/query` so we can replace it on accept. */
  range: MonacoNS.IRange
}

/** Match `/foo` at end of the line, preceded by start-of-line or whitespace. */
const SLASH_TRIGGER_RE = /(?:^|\s)\/([\w-]*)$/

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

interface MarkdownEditorProps {
  initialData?: MarkdownData
  onSave: (data: MarkdownData) => void
  onCancel: () => void
}

export function MarkdownEditor({ initialData, onSave, onCancel }: MarkdownEditorProps) {
  const { resolvedTheme } = useTheme()
  const isDarkMode = resolvedTheme === "dark"

  const [content, setContent] = useState(initialData?.content || "")
  const [embeds, setEmbeds] = useState<Record<string, EmbeddableBlock>>(
    initialData?.embeds ?? {},
  )
  const [showBlockPicker, setShowBlockPicker] = useState(false)
  const [slashMenu, setSlashMenu] = useState<SlashMenuState | null>(null)
  const [highlightedIndex, setHighlightedIndex] = useState(0)

  const settings = useEditorSettings("markdown")
  const editorRef = useRef<IStandaloneCodeEditor | null>(null)
  const slashMenuRef = useRef<SlashMenuState | null>(null)
  const highlightedRef = useRef(0)
  const optionRefs = useRef<Array<HTMLButtonElement | null>>([])

  // Mirror state into refs so Monaco event handlers see the latest values
  // without re-binding every render.
  useEffect(() => {
    slashMenuRef.current = slashMenu
  }, [slashMenu])
  useEffect(() => {
    highlightedRef.current = highlightedIndex
    const el = optionRefs.current[highlightedIndex]
    if (el) el.scrollIntoView({ block: "nearest" })
  }, [highlightedIndex])

  // -------------------------------------------------------------------------
  // Slash menu — options
  // -------------------------------------------------------------------------

  const allOptions = EMBEDDABLE_BLOCK_TYPES
    // Markdown cannot embed itself — avoids infinite-nesting UX and editing loops.
    .filter((type) => type !== "markdown")
    .map((type) => {
      const entry = BLOCK_REGISTRY[type]
      return {
        type,
        title: entry.label,
        description: entry.description,
        Icon: entry.icon,
      }
    })

  const filteredOptions = (() => {
    const q = (slashMenu?.query ?? "").toLowerCase()
    if (!q) return allOptions
    return allOptions.filter(
      (o) =>
        o.title.toLowerCase().includes(q) ||
        o.description.toLowerCase().includes(q) ||
        o.type.toLowerCase().includes(q),
    )
  })()

  // Keep highlight in range when the filter changes.
  useEffect(() => {
    if (highlightedIndex >= filteredOptions.length) {
      setHighlightedIndex(0)
    }
  }, [filteredOptions.length, highlightedIndex])

  // -------------------------------------------------------------------------
  // Insert helpers
  // -------------------------------------------------------------------------

  const insertEmbedBlock = useCallback(
    (block: Block, replaceRange?: MonacoNS.IRange) => {
      const embeddable = block as EmbeddableBlock
      setEmbeds((prev) => ({ ...prev, [block.id]: embeddable }))

      const token = buildEmbedToken(block.id)
      const editor = editorRef.current
      if (!editor) {
        setContent((c) => `${c}\n${token}\n`)
        return
      }
      const model = editor.getModel()
      if (!model) return

      if (replaceRange) {
        editor.executeEdits("insert-embed", [
          { range: replaceRange, text: token, forceMoveMarkers: true },
        ])
      } else {
        const position = editor.getPosition()
        if (!position) {
          setContent((c) => `${c}\n${token}\n`)
          return
        }
        editor.executeEdits("insert-embed", [
          {
            range: {
              startLineNumber: position.lineNumber,
              startColumn: position.column,
              endLineNumber: position.lineNumber,
              endColumn: position.column,
            },
            text: `\n${token}\n`,
            forceMoveMarkers: true,
          },
        ])
      }
      setContent(model.getValue())
      editor.focus()
    },
    [],
  )

  const handlePickerSelect = useCallback(
    (factory: (id: string) => Block) => {
      const block = factory(crypto.randomUUID())
      insertEmbedBlock(block)
      setShowBlockPicker(false)
    },
    [insertEmbedBlock],
  )

  /**
   * Persist edits made through the inline `BlockEmbedView` editor.
   * The block keeps its id; only `data` changes.
   */
  const handleEmbedChange = useCallback(
    (id: string, data: EmbeddableBlockData) => {
      setEmbeds((prev) => {
        const existing = prev[id]
        if (!existing) return prev
        return { ...prev, [id]: { ...existing, data } as EmbeddableBlock }
      })
    },
    [],
  )

  /**
   * Remove an embed both from the payload map and from the markdown source.
   * Strips every `<block-embed id="<id>" />` occurrence (defensive: usually 1).
   */
  const handleEmbedRemove = useCallback((id: string) => {
    setEmbeds((prev) => {
      if (!(id in prev)) return prev
      const next = { ...prev }
      delete next[id]
      return next
    })
    setContent((prev) => {
      const next = prev.replace(BLOCK_EMBED_TOKEN_RE, (full, capturedId) =>
        capturedId === id ? "" : full,
      )
      const editor = editorRef.current
      if (editor) {
        const model = editor.getModel()
        if (model && model.getValue() !== next) {
          model.setValue(next)
        }
      }
      return next
    })
  }, [])

  const handleSlashSelect = useCallback(
    (type: EmbeddableBlockType) => {
      const state = slashMenuRef.current
      if (!state) return
      const config = BLOCK_REGISTRY[type]
      const block = config.createEmpty(crypto.randomUUID())
      insertEmbedBlock(block, state.range)
      setSlashMenu(null)
      setHighlightedIndex(0)
    },
    [insertEmbedBlock],
  )

  // -------------------------------------------------------------------------
  // Monaco wiring: detect slash trigger + capture nav keys
  // -------------------------------------------------------------------------

  const updateSlashMenuFromCursor = useCallback((editor: IStandaloneCodeEditor) => {
    const model = editor.getModel()
    const position = editor.getPosition()
    if (!model || !position) {
      setSlashMenu(null)
      return
    }
    const lineContent = model.getLineContent(position.lineNumber)
    const before = lineContent.slice(0, position.column - 1)
    const match = before.match(SLASH_TRIGGER_RE)
    if (!match) {
      setSlashMenu(null)
      return
    }
    const query = match[1] ?? ""
    // The `/` character itself starts at the captured group's index - 1
    // (the optional leading whitespace doesn't consume `/`).
    const slashIndex = before.length - query.length - 1
    const range: MonacoNS.IRange = {
      startLineNumber: position.lineNumber,
      startColumn: slashIndex + 1,
      endLineNumber: position.lineNumber,
      endColumn: position.column,
    }

    const visible = editor.getScrolledVisiblePosition(position)
    const domNode = editor.getDomNode()
    if (!visible || !domNode) {
      setSlashMenu(null)
      return
    }
    const rect = domNode.getBoundingClientRect()
    setSlashMenu({
      query,
      anchor: {
        top: rect.top + visible.top + visible.height + 4,
        left: rect.left + visible.left,
      },
      range,
    })
  }, [])

  const handleEditorMount = useCallback(
    (editor: IStandaloneCodeEditor) => {
      editorRef.current = editor

      editor.onDidChangeModelContent(() => {
        updateSlashMenuFromCursor(editor)
      })
      editor.onDidChangeCursorPosition(() => {
        updateSlashMenuFromCursor(editor)
      })
      editor.onDidScrollChange(() => {
        // Re-anchor or close while scrolling — simpler to close.
        if (slashMenuRef.current) setSlashMenu(null)
      })
      editor.onDidBlurEditorWidget(() => {
        // Delay so click on the menu still registers.
        setTimeout(() => setSlashMenu(null), 120)
      })

      editor.onKeyDown((e) => {
        const menu = slashMenuRef.current
        if (!menu) return
        const opts = filteredOptionsRef.current
        if (opts.length === 0) return

        // Browser keyCode mapping: ArrowUp=38 ArrowDown=40 Enter=13
        // Tab=9 Escape=27. Monaco's IKeyboardEvent.keyCode is its OWN enum,
        // so use `browserEvent.key` for reliability.
        const key = e.browserEvent.key
        if (key === "ArrowDown") {
          e.preventDefault()
          e.stopPropagation()
          setHighlightedIndex((i) => (i + 1) % opts.length)
        } else if (key === "ArrowUp") {
          e.preventDefault()
          e.stopPropagation()
          setHighlightedIndex((i) => (i - 1 + opts.length) % opts.length)
        } else if (key === "Enter" || key === "Tab") {
          e.preventDefault()
          e.stopPropagation()
          const selected = opts[highlightedRef.current]
          if (selected) handleSlashSelect(selected.type)
        } else if (key === "Escape") {
          e.preventDefault()
          e.stopPropagation()
          setSlashMenu(null)
        }
      })
    },
    [updateSlashMenuFromCursor, handleSlashSelect],
  )

  // Keep filtered options reachable from the keydown handler without
  // rebinding it on every keystroke.
  const filteredOptionsRef = useRef(filteredOptions)
  useEffect(() => {
    filteredOptionsRef.current = filteredOptions
  }, [filteredOptions])

  // -------------------------------------------------------------------------
  // Save / cancel
  // -------------------------------------------------------------------------

  const handleSave = () => {
    onSave({
      content,
      embeds: pruneUnusedEmbeds(content, embeds),
      title: initialData?.title,
      caption: initialData?.caption,
    })
  }

  // -------------------------------------------------------------------------
  // Render
  // -------------------------------------------------------------------------

  return (
    <>
      <BlockEditorShell
        settings={settings}
        onClose={onCancel}
        icon={<FileText className="h-5 w-5 text-blue-600 dark:text-blue-400" />}
        title="Markdown Editor"
        headerActions={
          <Button
            variant="outline"
            size="sm"
            onClick={() => setShowBlockPicker(true)}
            className="border-gray-300 dark:border-gray-600 hover:bg-gray-100 dark:hover:bg-gray-800"
          >
            <Blocks className="h-4 w-4 mr-1" />
            Insert Block
          </Button>
        }
        footer={
          <div className="flex gap-2 justify-end">
            <Button
              variant="outline"
              onClick={onCancel}
              className="border-gray-300 dark:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-800 bg-transparent"
            >
              Cancel
            </Button>
            <Button
              onClick={handleSave}
              className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 dark:bg-blue-500 dark:hover:bg-blue-600"
            >
              <Save className="h-4 w-4" />
              Save Markdown
            </Button>
          </div>
        }
      >
        <div className="flex-1 overflow-hidden flex">
          {/* Left — Monaco source */}
          <div className="w-1/2 border-r border-gray-200 dark:border-gray-800 flex flex-col">
            <div className="p-4 border-b border-gray-200 dark:border-gray-800 bg-gray-50 dark:bg-gray-900">
              <h3 className="text-sm font-medium text-gray-800 dark:text-gray-200 uppercase tracking-wide">
                Editor
              </h3>
            </div>
            <div className="flex-1 overflow-hidden">
              <BaseMonacoEditor
                language="markdown"
                value={content}
                onChange={(value) => setContent(value || "")}
                onMount={handleEditorMount}
                isDark={isDarkMode}
                options={settings.editor}
                extraOptions={{ roundedSelection: true }}
              />
            </div>
          </div>

          {/* Right — live preview */}
          <div className="w-1/2 flex flex-col">
            <div className="p-4 border-b border-gray-200 dark:border-gray-800 bg-gray-50 dark:bg-gray-900">
              <h3 className="text-sm font-medium text-gray-800 dark:text-gray-200 uppercase tracking-wide">
                Live Preview
              </h3>
            </div>
            <div className="flex-1 overflow-auto p-6 bg-white dark:bg-gray-950">
              <MarkdownRenderer
                content={content}
                embeds={embeds}
                editable
                onEmbedChange={handleEmbedChange}
                onEmbedRemove={handleEmbedRemove}
                className=""
                emptyFallback={
                  <p className="text-gray-400 dark:text-gray-600 italic">
                    Your markdown preview will appear here. Type{" "}
                    <code className="px-1 py-0.5 rounded bg-gray-100 dark:bg-gray-800">/</code>{" "}
                    to insert a block.
                  </p>
                }
              />
            </div>
          </div>
        </div>
      </BlockEditorShell>

      <BlockTypePicker
        open={showBlockPicker}
        onOpenChange={setShowBlockPicker}
        onSelect={handlePickerSelect}
        allowedBlockTypes={
          EMBEDDABLE_BLOCK_TYPES.filter((t) => t !== "markdown") as EmbeddableBlockType[]
        }
      />

      {slashMenu && filteredOptions.length > 0 && typeof document !== "undefined"
        ? createPortal(
            <div
              className={cn(
                "fixed z-80 min-w-[280px] max-h-[360px] overflow-y-auto",
                "rounded-md border-2 border-blue-500/40 bg-popover text-popover-foreground shadow-2xl",
              )}
              style={{ top: slashMenu.anchor.top, left: slashMenu.anchor.left }}
              role="listbox"
              onMouseDown={(e) => e.preventDefault()}
            >
              <div className="p-1">
                {filteredOptions.map((option, i) => {
                  const Icon = option.Icon
                  const isSelected = highlightedIndex === i
                  return (
                    <button
                      key={option.type}
                      ref={(el) => {
                        optionRefs.current[i] = el
                      }}
                      type="button"
                      role="option"
                      aria-selected={isSelected}
                      tabIndex={-1}
                      onMouseEnter={() => setHighlightedIndex(i)}
                      onClick={() => handleSlashSelect(option.type)}
                      className={cn(
                        "relative flex w-full items-start gap-2 rounded-sm px-2 py-1.5 text-left text-sm outline-none transition-colors",
                        isSelected
                          ? "bg-blue-600 text-white ring-2 ring-blue-400 ring-inset"
                          : "hover:bg-accent/60",
                      )}
                    >
                      <Icon
                        className={cn(
                          "h-4 w-4 mt-0.5 shrink-0",
                          isSelected ? "text-white" : "text-muted-foreground",
                        )}
                      />
                      <div className="min-w-0 flex-1">
                        <div className="font-medium leading-tight">{option.title}</div>
                        <div
                          className={cn(
                            "text-xs leading-tight truncate",
                            isSelected ? "text-blue-100" : "text-muted-foreground",
                          )}
                        >
                          {option.description}
                        </div>
                      </div>
                    </button>
                  )
                })}
              </div>
            </div>,
            document.body,
          )
        : null}
    </>
  )
}

"use client"

/**
 * Shared Markdown renderer.
 *
 * Single source of truth for how a markdown block is rendered, used by:
 *   - `preview-markdown.tsx` (read-only viewers / `block-array-viewer`)
 *   - `markdown-editor.tsx` (the live preview pane inside the editor)
 *   - `block-embed-registry.tsx` (when markdown is embedded in Lexical)
 *
 * Beyond GFM + raw HTML, this renderer understands one custom token:
 *
 *   <block-embed id="..." />
 *
 * which is resolved against the `embeds` map and rendered via the
 * embed registry used by markdown rendering.
 */

import { useMemo, useRef } from "react"
import ReactMarkdown, { defaultUrlTransform } from "react-markdown"
import remarkGfm from "remark-gfm"
import rehypeRaw from "rehype-raw"
import { isAssetUri } from "@game-guild/assets"

import { useMarkdownComponents } from "./markdown-components"
import { EMBEDDABLE_BLOCK_CONFIG } from "../../embed/block-embed-registry"
import { BlockEmbedView } from "../../embed/block-embed-view"
import type {
  EmbeddableBlock,
  EmbeddableBlockData,
  EmbeddableBlockType,
} from "../../embed/types"

// ---------------------------------------------------------------------------
// Embed token helpers (shared with the editor)
// ---------------------------------------------------------------------------

/**
 * Matches `<block-embed id="..." />` or `<block-embed id="..."></block-embed>`
 * with single or double quotes. Anchored to capture the id.
 */
export const BLOCK_EMBED_TOKEN_RE = /<block-embed\b[^>]*\bid=["']([^"']+)["'][^>]*\/?>(?:\s*<\/block-embed>)?/gi

export function extractEmbedIds(content: string): string[] {
  const ids: string[] = []
  for (const match of content.matchAll(BLOCK_EMBED_TOKEN_RE)) {
    if (match[1]) ids.push(match[1])
  }
  return ids
}

export function pruneUnusedEmbeds(
  content: string,
  embeds: Record<string, EmbeddableBlock> | undefined,
): Record<string, EmbeddableBlock> {
  if (!embeds) return {}
  const used = new Set(extractEmbedIds(content))
  const next: Record<string, EmbeddableBlock> = {}
  for (const [id, block] of Object.entries(embeds)) {
    if (used.has(id)) next[id] = block
  }
  return next
}

export function buildEmbedToken(id: string): string {
  return `<block-embed id="${id}"></block-embed>`
}

// ---------------------------------------------------------------------------
// Rehype plugin: lift <block-embed> out of any wrapping <p>
// ---------------------------------------------------------------------------

/**
 * Markdown wraps any inline-looking HTML in `<p>`. Our `<block-embed>` token
 * therefore lands inside a paragraph by default, and the registered Preview
 * component renders block-level content (divs, sections, iframes…), which
 * produces invalid HTML and React hydration errors.
 *
 * This rehype plugin walks the tree and splits any `<p>` that contains one
 * or more `<block-embed>` children into adjacent `<p>` segments around the
 * embeds, leaving each `<block-embed>` as a sibling at the block level.
 */
type HastNode = {
  type: string
  tagName?: string
  children?: HastNode[]
  [key: string]: unknown
}

function rehypeUnwrapBlockEmbed() {
  return (tree: HastNode) => {
    const walk = (node: HastNode) => {
      if (!Array.isArray(node.children)) return
      const next: HastNode[] = []
      for (const child of node.children) {
        if (
          child.type === "element" &&
          child.tagName === "p" &&
          Array.isArray(child.children) &&
          child.children.some(
            (c) => c.type === "element" && c.tagName === "block-embed",
          )
        ) {
          // Split: emit alternating <p> segments and bare <block-embed>s.
          let buffer: HastNode[] = []
          const flushParagraph = () => {
            if (buffer.length === 0) return
            next.push({ ...child, children: buffer })
            buffer = []
          }
          for (const c of child.children) {
            if (c.type === "element" && c.tagName === "block-embed") {
              flushParagraph()
              next.push(c)
            } else {
              buffer.push(c)
            }
          }
          flushParagraph()
        } else {
          walk(child)
          next.push(child)
        }
      }
      node.children = next
    }
    walk(tree)
  }
}

// ---------------------------------------------------------------------------
// Renderer
// ---------------------------------------------------------------------------

interface MarkdownRendererProps {
  content: string
  embeds?: Record<string, EmbeddableBlock>
  title?: string
  caption?: string
  /** Tailwind class for the outer wrapper. */
  className?: string
  /** Shown when `content` is empty. Pass `null` to hide. */
  emptyFallback?: React.ReactNode
  /**
   * When true, each embed renders inside `BlockEmbedView` — clicking the
   * pencil affordance opens the block's own editor (same UX as Lexical).
   * Requires `onEmbedChange` to persist edits.
   */
  editable?: boolean
  /** Called with the new data after the inline editor saves. */
  onEmbedChange?: (id: string, data: EmbeddableBlockData) => void
  /** Called when the user removes the embed via the inline UI. */
  onEmbedRemove?: (id: string) => void
}

const DEFAULT_EMPTY = (
  <p className="text-gray-400 dark:text-gray-600 italic">No markdown content</p>
)

export function MarkdownRenderer({
  content,
  embeds,
  title,
  caption,
  className = "my-4",
  emptyFallback = DEFAULT_EMPTY,
  editable = false,
  onEmbedChange,
  onEmbedRemove,
}: MarkdownRendererProps) {
  const baseComponents = useMarkdownComponents()

  // Keep latest values reachable from a STABLE EmbedTag component below.
  // If `EmbedTag` itself were re-created on every render, react-markdown
  // would see a new component type for `<block-embed>` and unmount /
  // remount every embed on each keystroke — which would close any open
  // inline editor modal.
  const embedsRef = useRef(embeds)
  const editableRef = useRef(editable)
  const onChangeRef = useRef(onEmbedChange)
  const onRemoveRef = useRef(onEmbedRemove)
  embedsRef.current = embeds
  editableRef.current = editable
  onChangeRef.current = onEmbedChange
  onRemoveRef.current = onEmbedRemove

  // Defined once per MarkdownRenderer instance — identity is stable across
  // re-renders so React preserves the underlying BlockEmbedView subtree.
  const EmbedTag = useMemo(() => {
    function EmbedTagImpl(props: { id?: string }) {
      const id = props.id
      if (!id) return null
      const block = embedsRef.current?.[id]
      if (!block) {
        return (
          <div className="my-4 rounded-md border border-dashed border-amber-300 bg-amber-50 dark:bg-amber-900/10 dark:border-amber-700 p-3 text-xs text-amber-700 dark:text-amber-300">
            Missing embed <code>{id}</code>
          </div>
        )
      }
      const entry = EMBEDDABLE_BLOCK_CONFIG[block.type as EmbeddableBlockType]
      if (!entry) {
        return (
          <div className="my-4 rounded-md border border-dashed border-red-300 bg-red-50 dark:bg-red-900/10 dark:border-red-700 p-3 text-xs text-red-700 dark:text-red-300">
            Block type &ldquo;{block.type}&rdquo; is not embeddable
          </div>
        )
      }
      if (editableRef.current) {
        return (
          <BlockEmbedView
            block={block}
            editable
            onChange={(data) => onChangeRef.current?.(id, data)}
            onRemove={onRemoveRef.current ? () => onRemoveRef.current?.(id) : undefined}
          />
        )
      }
      const Preview = entry.Preview as React.ComponentType<{ block: EmbeddableBlock }>
      return <Preview block={block} />
    }
    return EmbedTagImpl
  }, [])

  const components = useMemo(
    () =>
      ({
        ...baseComponents,
        "block-embed": EmbedTag,
      }) as typeof baseComponents,
    [baseComponents, EmbedTag],
  )

  return (
    <div className={className}>
      {title && (
        <h1 className="text-3xl font-bold mb-2 text-gray-900 dark:text-gray-100">{title}</h1>
      )}
      {caption && (
        <p className="text-sm text-gray-600 dark:text-gray-400 mb-6">{caption}</p>
      )}
      {content ? (
        <ReactMarkdown
          remarkPlugins={[remarkGfm]}
          rehypePlugins={[rehypeRaw, rehypeUnwrapBlockEmbed]}
          components={components}
          urlTransform={(url) => (isAssetUri(url) ? url : defaultUrlTransform(url))}
        >
          {content}
        </ReactMarkdown>
      ) : (
        emptyFallback
      )}
    </div>
  )
}

/**
 * Math input component (LaTeX-based)
 *
 * Thin React wrapper around the MathLive `<math-field>` web component.
 * The stored `value` is a LaTeX string. The component handles upgrading
 * the custom element on the client and forwarding `input` events as
 * `onChange(latex)` callbacks.
 *
 * The `<math-field>` element gives users a visual formula editor that
 * supports fractions, roots, integrals, sums, Greek letters, and the
 * full LaTeX math vocabulary — not just bare ASCII text.
 */

"use client"

import { useEffect, useRef, useState, type CSSProperties } from "react"
import type { MathfieldElement } from "mathlive"
import { cn } from "@/lib/utils"

interface MathInputProps {
  value: string
  onChange?: (latex: string) => void
  onCommit?: (latex: string) => void
  readOnly?: boolean
  placeholder?: string
  className?: string
  style?: CSSProperties
  autoFocus?: boolean
}

// Module-level promise so the MathLive runtime is loaded (and the
// `<math-field>` custom element registered) only once across the app.
let mathliveReady: Promise<void> | null = null
function ensureMathLive(): Promise<void> {
  if (typeof window === "undefined") return Promise.resolve()
  if (!mathliveReady) {
    mathliveReady = import("mathlive").then((mod) => {
      // Serve MathLive's KaTeX fonts and sounds from our own origin
      // (copied into `public/mathlive/` by `scripts/copy-mathlive-assets.cjs`).
      //
      // The directories MUST be absolute URLs (with scheme + host) — if we
      // pass a root-relative path like `/mathlive/fonts/`, MathLive's
      // `resolveUrl` falls through to a `fetch HEAD` against its own
      // script URL (the Next.js chunk), which logs an `Invalid URL`
      // error that Next's dev overlay surfaces as a fatal.
      const ME = (mod as unknown as { MathfieldElement?: typeof import("mathlive").MathfieldElement })
        .MathfieldElement
      if (ME) {
        const origin = window.location.origin
        ME.fontsDirectory = `${origin}/mathlive/fonts/`
        ME.soundsDirectory = `${origin}/mathlive/sounds/`
      }

      // Sinaliza globalmente quando o teclado virtual está visível.
      // Marcamos `<body data-math-keyboard-open>` para que diálogos /
      // popovers possam ignorar cliques fora enquanto o teclado estiver
      // aberto (o teclado é montado em `document.body`, fora da árvore
      // de qualquer Radix Dialog/Popover).
      const vk = (
        window as unknown as { mathVirtualKeyboard?: EventTarget & { visible: boolean } }
      ).mathVirtualKeyboard
      if (vk) {
        const sync = () => {
          if (vk.visible) document.body.setAttribute("data-math-keyboard-open", "true")
          else document.body.removeAttribute("data-math-keyboard-open")
        }
        vk.addEventListener("geometrychange", sync)
        // `update-state` é disparado em show/hide; cobre os dois eventos.
        vk.addEventListener("update-state" as keyof HTMLElementEventMap, sync)
        sync()

        // Guarda global: enquanto o teclado virtual estiver aberto,
        // interceptamos pointerdown/mousedown na fase de captura para
        // que detectores de "clique fora" (Radix Dialog/Popover, etc.)
        // não fechem nada quando o usuário toca em qualquer ponto fora
        // do teclado. Apenas chamamos `stopPropagation` — o evento de
        // `click` resultante ainda atinge botões normalmente, então
        // ações explícitas (Save/Cancel) continuam funcionando.
        const guard = (e: Event) => {
          if (!document.body.hasAttribute("data-math-keyboard-open")) return
          const target = e.target as HTMLElement | null
          if (!target) return
          if (target.closest(".ML__keyboard, .ML__virtual-keyboard, math-field")) return
          e.stopPropagation()
        }
        document.addEventListener("pointerdown", guard, true)
        document.addEventListener("mousedown", guard, true)
        document.addEventListener("touchstart", guard, true)
      }
    })
  }
  return mathliveReady
}

export function MathInput({
  value,
  onChange,
  onCommit,
  readOnly,
  placeholder,
  className,
  style,
  autoFocus,
}: MathInputProps) {
  const ref = useRef<MathfieldElement | null>(null)
  const [ready, setReady] = useState(false)
  // Turns `true` when the `<math-field>` has been mounted AND its internal mathfield
  // (`this.mathfield`) already exists — only then is it safe to set
  // `value`, call `focus()`, etc. Without this guard, MathLive throws
  // `TypeError: can't access property "options", this.mathfield is
  // undefined` during subsequent blur.
  const [elementReady, setElementReady] = useState(false)

  useEffect(() => {
    let cancelled = false
    ensureMathLive().then(() => {
      if (!cancelled) setReady(true)
    })
    return () => {
      cancelled = true
    }
  }, [])

  // Waits for the custom element to finish initializing.
  useEffect(() => {
    if (!ready) return
    const mf = ref.current
    if (!mf) return
    let cancelled = false
    let raf = 0
    const check = (attempt = 0) => {
      if (cancelled) return
      // MathfieldElement stores the internal instance in `_mathfield`
      // (created asynchronously inside the connectedCallback).
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const m = mf as any
      if (m._mathfield != null || m.mathfield != null) {
        setElementReady(true)
        return
      }
      if (attempt > 120) {
        // Fallback: assume ready after ~2s to avoid blocking the UI if
        // the internal name changes in future versions.
        setElementReady(true)
        return
      }
      raf = requestAnimationFrame(() => check(attempt + 1))
    }
    raf = requestAnimationFrame(() => check(0))
    return () => {
      cancelled = true
      cancelAnimationFrame(raf)
    }
  }, [ready])

  // Keep MathLive value in sync with React-controlled `value`.
  useEffect(() => {
    if (!elementReady) return
    const mf = ref.current
    if (!mf) return
    try {
      if (mf.value !== value) mf.value = value ?? ""
    } catch {
      /* ignore */
    }
  }, [value, elementReady])

  useEffect(() => {
    if (!elementReady) return
    const mf = ref.current
    if (!mf) return
    try { mf.readOnly = !!readOnly } catch { /* ignore */ }
  }, [readOnly, elementReady])

  useEffect(() => {
    if (!elementReady) return
    const mf = ref.current
    if (!mf || placeholder === undefined) return
    try { mf.placeholder = placeholder } catch { /* ignore */ }
  }, [placeholder, elementReady])

  useEffect(() => {
    if (!elementReady) return
    const mf = ref.current
    if (!mf) return
    const handleInput = () => onChange?.(mf.value)
    const handleChange = () => onCommit?.(mf.value)
    mf.addEventListener("input", handleInput)
    mf.addEventListener("change", handleChange)
    return () => {
      mf.removeEventListener("input", handleInput)
      mf.removeEventListener("change", handleChange)
    }
  }, [onChange, onCommit, elementReady])

  useEffect(() => {
    if (!elementReady || !autoFocus) return
    const mf = ref.current
    if (!mf) return
    try {
      mf.focus?.()
    } catch {
      /* ignore — user can focus manually */
    }
  }, [autoFocus, elementReady])

  // The `<math-field>` tag is a custom element not in the React JSX
  // namespace. Cast through `any` to keep TS happy without polluting
  // the global JSX intrinsic-elements map.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const Tag = "math-field" as any

  // Defer mounting `<math-field>` until MathLive has loaded AND we've
  // configured the font/sound directories. Mounting earlier triggers
  // `connectedCallback` -> `loadFonts()` with the default `./fonts/`
  // path, which resolves to a non-existent chunk URL and throws a
  // console error that the Next dev overlay surfaces as a fatal.
  if (!ready) {
    return (
      <div
        className={cn(
          "block w-full rounded-md border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 px-3 py-2 text-base text-gray-400 dark:text-gray-500 min-h-[2.5rem]",
          className,
        )}
        style={style}
        aria-busy="true"
      >
        {placeholder ?? "\u00A0"}
      </div>
    )
  }

  return (
    <Tag
      ref={ref}
      class={cn(
        "block w-full rounded-md border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 px-3 py-2 text-base text-gray-900 dark:text-gray-100 outline-none focus:border-blue-500",
        className,
      )}
      style={style}
    />
  )
}

"use client"

import { useResolvedAssetUrl } from "@game-guild/assets/react"

interface AssetImageProps extends React.ImgHTMLAttributes<HTMLImageElement> {
  src?: string
}

/**
 * Image component that automatically resolves asset:// URLs
 * For non-asset URLs, renders normally
 */
export function AssetImage({ src, ...props }: AssetImageProps) {
  const { url: resolvedSrc, loading: isLoading } = useResolvedAssetUrl(src)

  if (!src) return null
  
  if (isLoading) {
    return (
      <span
        aria-label={props.alt ? `Loading ${props.alt}` : "Loading image"}
        className={props.className}
        role="status"
        style={props.style}
      >
        <span className="flex h-full w-full items-center justify-center bg-gray-100 dark:bg-gray-800">
          <span className="text-xs text-gray-400">Loading...</span>
        </span>
      </span>
    )
  }

  if (!resolvedSrc) return null

  return <img src={resolvedSrc} {...props} />
}

