"use client"

import { useState } from "react"
import { Label } from "@game-guild/ui/components/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@game-guild/ui/components/select"
import { Button } from "@game-guild/ui/components/button"
import { Plus, Lock, Unlock, X, MoreVertical } from "lucide-react"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@game-guild/ui/components/dropdown-menu"
import type { BaseMediaData } from "@/components/block-content-editor/nodes/base/media-node-base"
import { AssetImage } from "./asset-image"

interface LayoutTabProps {
  items: BaseMediaData[]
  onItemsChange: (items: BaseMediaData[]) => void
  columns: number
  onColumnsChange: (columns: number) => void
}

export function LayoutTab({ items, onItemsChange, columns, onColumnsChange }: LayoutTabProps) {
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null)
  const [dragOverIndex, setDragOverIndex] = useState<number | null>(null)
  const [hasDropped, setHasDropped] = useState(false)

  // Calculate total grid slots - always show at least one empty row below content
  const minSlots = columns * 2
  const currentRows = Math.ceil(items.length / columns)
  const totalSlots = Math.max(minSlots, (currentRows + 1) * columns) // +1 row for empty space
  
  // ARRAY 1: Static items map (position -> item)
  const staticItemsMap = new Map<number, BaseMediaData>()
  items.forEach(item => {
    if (item.isStatic && item.gridPosition !== undefined) {
      staticItemsMap.set(item.gridPosition, item)
    }
  })
  
  // ARRAY 2: Dynamic items (ordered list of non-static items)
  const dynamicItems = items.filter(item => !item.isStatic || item.gridPosition === undefined)
  
  // ARRAY 3: Final grid (combines static at fixed positions + dynamic in remaining slots)
  const gridSlots: (BaseMediaData | null)[] = Array(totalSlots).fill(null)
  
  // Place static items at their fixed positions
  staticItemsMap.forEach((item, position) => {
    if (position < totalSlots) {
      gridSlots[position] = item
    }
  })
  
  // Fill remaining slots with dynamic items in order
  let dynamicIndex = 0
  for (let i = 0; i < totalSlots && dynamicIndex < dynamicItems.length; i++) {
    if (gridSlots[i] === null) {
      const item = dynamicItems[dynamicIndex]
      if (item) {
        gridSlots[i] = item
      }
      dynamicIndex++
    }
  }
  
  // Helper: Get list of static items for display
  const staticItems = Array.from(staticItemsMap.values())

  const handleDragStart = (e: React.DragEvent, index: number) => {
    const item = gridSlots[index]
    if (!item || item.isStatic) {
      e.preventDefault()
      return
    }
    e.dataTransfer.effectAllowed = "move"
    setDraggedIndex(index)
    setHasDropped(false) // Reset drop flag
  }

  const handleDragEnd = () => {
    // If drag ended without a successful drop, just clear states (cancel)
    setDraggedIndex(null)
    setDragOverIndex(null)
    setHasDropped(false)
  }

  const handleDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault()
    
    const targetItem = gridSlots[index]
    // Don't allow dropping on static items
    if (targetItem?.isStatic) {
      e.dataTransfer.dropEffect = "none"
      return
    }
    
    e.dataTransfer.dropEffect = "move"
    
    if (draggedIndex !== null && draggedIndex !== index) {
      setDragOverIndex(index)
    }
  }

  const handleDragLeave = () => {
    setDragOverIndex(null)
  }

  const handleDrop = (e: React.DragEvent, targetIndex: number) => {
    e.preventDefault()
    e.stopPropagation() // Prevent event bubbling
    
    if (draggedIndex === null || draggedIndex === targetIndex) {
      setDragOverIndex(null)
      setHasDropped(true) // Mark as dropped (even if same position)
      return
    }

    const targetItem = gridSlots[targetIndex]
    if (targetItem?.isStatic) {
      setDragOverIndex(null)
      setHasDropped(true)
      return
    }

    const draggedItem = gridSlots[draggedIndex]
    
    if (!draggedItem) {
      setDragOverIndex(null)
      setHasDropped(true)
      return
    }

    // Reconstruct items array using the 3-array approach
    const newStaticMap = new Map(staticItemsMap) // Copy static map
    const newDynamicItems = [...dynamicItems] // Copy dynamic list
    
    // Create temp grid to perform swap
    const tempGrid: (BaseMediaData | null)[] = Array(totalSlots).fill(null)
    
    // Place static items at their fixed positions
    newStaticMap.forEach((item, position) => {
      if (position < totalSlots) {
        tempGrid[position] = item
      }
    })
    
    // Fill remaining slots with dynamic items
    let dynIdx = 0
    for (let i = 0; i < totalSlots; i++) {
      if (tempGrid[i] === null && dynIdx < newDynamicItems.length) {
        const item = newDynamicItems[dynIdx]
        if (item) {
          tempGrid[i] = item
        }
        dynIdx++
      }
    }
    
    // Perform swap in tempGrid
    const temp = tempGrid[draggedIndex] ?? null
    tempGrid[draggedIndex] = tempGrid[targetIndex] ?? null
    tempGrid[targetIndex] = temp
    
    // Rebuild final items array from tempGrid, preserving static positions
    const newItems: BaseMediaData[] = []
    
    // For static items, preserve their gridPosition property
    // For dynamic items, add them in the order they appear in tempGrid
    tempGrid.forEach((item, index) => {
      if (item) {
        if (newStaticMap.has(index)) {
          // This is a static item - ensure gridPosition is set
          newItems.push({
            ...item,
            isStatic: true,
            gridPosition: index
          })
        } else {
          // This is a dynamic item - no gridPosition
          newItems.push({
            ...item,
            isStatic: false,
            gridPosition: undefined
          })
        }
      }
    })
    
    onItemsChange(newItems)
    setHasDropped(true) // Mark as successfully dropped
    
    setDraggedIndex(null)
    setDragOverIndex(null)
  }
  
  const handleCreatePlaceholder = (index: number, isStatic: boolean) => {
    const newPlaceholder: BaseMediaData = {
      type: "image",
      src: "",
      isPlaceholder: true,
      isStatic: isStatic,
      gridPosition: isStatic ? index : undefined
    }
    
    const newItems = [...items, newPlaceholder]
    onItemsChange(newItems)
  }
  
  const handleRemoveSlot = (index: number) => {
    const itemToRemove = gridSlots[index]
    if (!itemToRemove) return
    
    const newItems = items.filter(item => item !== itemToRemove)
    onItemsChange(newItems)
  }
  
  const handleToggleStatic = (index: number) => {
    const item = gridSlots[index]
    if (!item) return
    
    const newIsStatic = !item.isStatic
    
    if (newIsStatic) {
      // Making static - just update the item with its current position
      const newItems = items.map(i => {
        if (i === item) {
          return {
            ...i,
            isStatic: true,
            gridPosition: index
          }
        }
        return i
      })
      onItemsChange(newItems)
    } else {
      // Making movable - need to rebuild array maintaining visual order
      // Create a new items array based on current grid visual order
      const newItems: BaseMediaData[] = []
      
      gridSlots.forEach((slot, slotIndex) => {
        if (slot) {
          if (slot === item) {
            // This is the item being made movable - remove static props
            newItems.push({
              ...slot,
              isStatic: false,
              gridPosition: undefined
            })
          } else {
            // Keep other items as they are
            newItems.push(slot)
          }
        }
      })
      
      onItemsChange(newItems)
    }
  }
  
  // Get visual representation during drag
  const getVisualSlots = () => {
    if (draggedIndex === null || dragOverIndex === null) {
      return gridSlots
    }
    
    const draggedItem = gridSlots[draggedIndex]
    const targetItem = gridSlots[dragOverIndex]
    
    // Don't show swap if target is static or dragged item doesn't exist
    if (targetItem?.isStatic || !draggedItem || draggedItem.isStatic) {
      return gridSlots
    }
    
    // Create visual grid using the 3-array approach
    const visual: (BaseMediaData | null)[] = Array(totalSlots).fill(null)
    
    // Place static items at their fixed positions (unchanged during drag)
    staticItemsMap.forEach((item, position) => {
      if (position < totalSlots) {
        visual[position] = item
      }
    })
    
    // Create a copy of dynamic items for swap preview
    const dynamicWithSwap = [...dynamicItems]
    
    // Find indices in dynamic array
    const draggedDynamicIndex = dynamicItems.findIndex(item => item === draggedItem)
    const targetDynamicIndex = dynamicItems.findIndex(item => item === targetItem)
    
    if (draggedDynamicIndex !== -1 && targetDynamicIndex !== -1) {
      // Swap in dynamic array
      const temp = dynamicWithSwap[draggedDynamicIndex]
      const target = dynamicWithSwap[targetDynamicIndex]
      if (temp && target) {
        dynamicWithSwap[draggedDynamicIndex] = target
        dynamicWithSwap[targetDynamicIndex] = temp
      }
    } else if (draggedDynamicIndex !== -1 && targetItem === null) {
      // Dragging to empty slot - reorder in dynamic array
      dynamicWithSwap.splice(draggedDynamicIndex, 1)
      
      // Calculate where to insert in dynamic array based on target position
      let insertIndex = 0
      for (let i = 0; i < dragOverIndex; i++) {
        if (!staticItemsMap.has(i)) {
          insertIndex++
        }
      }
      dynamicWithSwap.splice(Math.min(insertIndex, dynamicWithSwap.length), 0, draggedItem)
    }
    
    // Fill remaining slots with reordered dynamic items
    let dynIdx = 0
    for (let i = 0; i < totalSlots && dynIdx < dynamicWithSwap.length; i++) {
      if (visual[i] === null) {
        const item = dynamicWithSwap[dynIdx]
        if (item) {
          visual[i] = item
        }
        dynIdx++
      }
    }
    
    return visual
  }
  
  const visualSlots = getVisualSlots()

  return (
    <div className="space-y-6">
      {/* Column Selection */}
      <div className="space-y-2">
        <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">
          Number of Columns
        </Label>
        <Select value={columns.toString()} onValueChange={(value) => value !== null && onColumnsChange(parseInt(value))}>
          <SelectTrigger className="w-full">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="1">1 Column</SelectItem>
            <SelectItem value="2">2 Columns</SelectItem>
            <SelectItem value="3">3 Columns</SelectItem>
            <SelectItem value="4">4 Columns</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Layout Preview with Drag & Drop */}
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">
            Arrange Items (Drag to reorder)
          </Label>
          {staticItems.length > 0 && (
            <div className="flex items-center gap-1 text-xs text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20 px-2 py-1 rounded">
              <Lock className="h-3 w-3" />
              {staticItems.length} static {staticItems.length === 1 ? 'item' : 'items'}
            </div>
          )}
        </div>
        
        <div 
          className="grid gap-3"
          style={{ gridTemplateColumns: `repeat(${columns}, 1fr)` }}
          onDragOver={(e) => {
            // Allow drop on the grid container itself
            e.preventDefault()
          }}
          onDrop={(e) => {
            // If dropped on grid container (not on a specific slot), cancel
            e.preventDefault()
            e.stopPropagation()
            setDraggedIndex(null)
            setDragOverIndex(null)
            setHasDropped(true)
          }}
        >
          {visualSlots.map((slot, slotIndex) => {
            const isDragging = draggedIndex === slotIndex
            const isDragOver = dragOverIndex === slotIndex
            const isStatic = slot?.isStatic ?? false
            const isPlaceholder = slot?.isPlaceholder ?? false
            const hasSlot = slot !== null
            const hasContent = slot && !isPlaceholder // Real content (not placeholder)
            
            return (
              <div
                key={slotIndex}
                draggable={!!(hasSlot && !isStatic)}
                onDragStart={(e) => handleDragStart(e, slotIndex)}
                onDragEnd={handleDragEnd}
                onDragOver={(e) => handleDragOver(e, slotIndex)}
                onDragLeave={handleDragLeave}
                onDrop={(e) => handleDrop(e, slotIndex)}
                className={`
                  relative group rounded-lg border-2 transition-all duration-200
                  ${hasSlot ? (hasContent ? 'bg-gray-100 dark:bg-gray-800 p-3' : 'bg-purple-50 dark:bg-purple-900/10 p-3') : 'border-dashed bg-gray-50 dark:bg-gray-800/30'}
                  ${isDragging ? 'opacity-40 scale-95 border-blue-400 dark:border-blue-500' : 'opacity-100 scale-100'}
                  ${isDragOver && !isStatic ? 'border-blue-500 dark:border-blue-400 ring-2 ring-blue-500/50 dark:ring-blue-400/50' : 'border-gray-200 dark:border-gray-700'}
                  ${hasSlot && !isStatic && !isDragging && !isDragOver ? 'cursor-move hover:border-blue-500 dark:hover:border-blue-400' : ''}
                  ${isStatic ? 'border-amber-500 dark:border-amber-400' : ''}
                  ${isPlaceholder && !isStatic ? 'border-purple-500 dark:border-purple-400' : ''}
                  ${!hasSlot ? 'border-gray-300 dark:border-gray-600' : ''}
                `}
              >
                {/* Slot Controls Menu */}
                <div className="absolute top-1 right-1 z-10 opacity-0 group-hover:opacity-100 transition-opacity">
                  <DropdownMenu>
                    <DropdownMenuTrigger render={<Button variant="ghost" 
                        size="sm" 
                        className="h-6 w-6 p-0 bg-white/90 dark:bg-gray-800/90 hover:bg-white dark:hover:bg-gray-800"
                        onClick={(e) => e.stopPropagation()} />}>
                      <MoreVertical className="h-3 w-3" />
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end" className="w-48">
                      {!slot && (
                        <>
                          <DropdownMenuItem onClick={() => handleCreatePlaceholder(slotIndex, false)}>
                            <Plus className="mr-2 h-4 w-4" />
                            Create Placeholder
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={() => handleCreatePlaceholder(slotIndex, true)}>
                            <Lock className="mr-2 h-4 w-4" />
                            Create Static Placeholder
                          </DropdownMenuItem>
                        </>
                      )}
                      {slot && (
                        <>
                          <DropdownMenuItem onClick={() => handleToggleStatic(slotIndex)}>
                            {isStatic ? (
                              <>
                                <Unlock className="mr-2 h-4 w-4" />
                                Make Movable
                              </>
                            ) : (
                              <>
                                <Lock className="mr-2 h-4 w-4" />
                                Make Static
                              </>
                            )}
                          </DropdownMenuItem>
                          <DropdownMenuSeparator />
                          <DropdownMenuItem 
                            onClick={() => handleRemoveSlot(slotIndex)}
                            className="text-red-600 dark:text-red-400"
                          >
                            <X className="mr-2 h-4 w-4" />
                            Remove {isPlaceholder ? 'Placeholder' : 'Item'}
                          </DropdownMenuItem>
                        </>
                      )}
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>

                {/* Content or Empty State */}
                {hasContent ? (
                  <>
                    {/* Item Preview */}
                    <div className="aspect-video bg-gray-200 dark:bg-gray-700 rounded overflow-hidden">
                      {slot.type === "image" && slot.src && (
                        <AssetImage src={slot.src} alt="" className="w-full h-full object-cover" />
                      )}
                      {slot.type !== "image" && (
                        <div className="w-full h-full flex items-center justify-center text-xs text-gray-500">
                          {slot.type}
                        </div>
                      )}
                    </div>

                    {/* Static Badge */}
                    {isStatic && (
                      <div className="absolute top-1 left-1 bg-amber-500 text-white text-xs px-2 py-1 rounded flex items-center gap-1">
                        <Lock className="h-3 w-3" />
                        Static #{slot.gridPosition !== undefined ? slot.gridPosition + 1 : slotIndex + 1}
                      </div>
                    )}
                    
                    {/* Drag Handle Indicator */}
                    {!isDragging && !isStatic && (
                      <div className="absolute top-1 left-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <div className="bg-gray-700/80 dark:bg-gray-300/80 text-white dark:text-gray-900 text-xs px-2 py-1 rounded">
                          ⋮⋮
                        </div>
                      </div>
                    )}
                  </>
                ) : isPlaceholder ? (
                  <>
                    {/* Placeholder State */}
                    <div className="aspect-video flex items-center justify-center">
                      <div className="text-center">
                        <div className="w-12 h-12 mx-auto mb-2 rounded-lg bg-purple-100 dark:bg-purple-900/30 flex items-center justify-center">
                          {isStatic ? (
                            <Lock className="h-6 w-6 text-purple-500 dark:text-purple-400" />
                          ) : (
                            <Plus className="h-6 w-6 text-purple-500 dark:text-purple-400" />
                          )}
                        </div>
                        <p className="text-xs text-purple-600 dark:text-purple-400 font-medium">
                          {isStatic ? 'Static' : 'Movable'} Placeholder
                        </p>
                      </div>
                    </div>
                    
                    {/* Static Badge for Placeholder */}
                    {isStatic && slot && (
                      <div className="absolute top-1 left-1 bg-amber-500 text-white text-xs px-2 py-1 rounded flex items-center gap-1">
                        <Lock className="h-3 w-3" />
                        Static #{slot.gridPosition !== undefined ? slot.gridPosition + 1 : slotIndex + 1}
                      </div>
                    )}
                    
                    {/* Drag Handle Indicator for Placeholder */}
                    {!isDragging && !isStatic && (
                      <div className="absolute top-1 left-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <div className="bg-purple-700/80 dark:bg-purple-300/80 text-white dark:text-gray-900 text-xs px-2 py-1 rounded">
                          ⋮⋮
                        </div>
                      </div>
                    )}
                  </>
                ) : (
                  <>
                    {/* Empty State */}
                    <div className="aspect-video flex items-center justify-center">
                      <Plus className={`h-8 w-8 transition-colors ${
                        isDragOver 
                          ? 'text-blue-500 dark:text-blue-400' 
                          : 'text-gray-400 dark:text-gray-600'
                      }`} />
                    </div>
                  </>
                )}

                {/* Position Badge */}
                <div className="absolute bottom-1 right-1 bg-gray-700/80 dark:bg-gray-300/80 text-white dark:text-gray-900 text-xs px-2 py-0.5 rounded">
                  {slotIndex + 1}
                </div>
              </div>
            )
          })}
        </div>
      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import { Button } from "@game-guild/ui/components/button"
import { Plus, Trash2, Image, Video, Music } from "lucide-react"
import type { AssetRecord } from "@game-guild/assets"
import { AssetPickerDialog, AssetsProvider } from "@game-guild/assets/react"
import type { BaseMediaData } from "@/components/block-content-editor/nodes/base/media-node-base"
import { AssetImage } from "./asset-image"

interface MediaListTabProps {
  items: BaseMediaData[]
  onItemsChange: (items: BaseMediaData[]) => void
  allowMixedTypes?: boolean
  defaultType?: "image" | "video" | "audio"
}

export function MediaListTab({ items, onItemsChange, allowMixedTypes = false, defaultType = "image" }: MediaListTabProps) {
  const [showUploadDialog, setShowUploadDialog] = useState(false)
  const [uploadType, setUploadType] = useState<"image" | "video" | "audio">(defaultType)

  const handleAddMedia = (type: "image" | "video" | "audio") => {
    setUploadType(type)
    setShowUploadDialog(true)
  }

  const handleMediaSelected = (result: AssetRecord | AssetRecord[]) => {
    if (Array.isArray(result)) {
      // Multiple files
      const newItems = result.map((item) => ({
        type: uploadType,
        src: item.uri,
        alt: item.name || "",
        caption: "",
        size: 100,
        embedType: "direct",
        embedAudioType: "direct",
        videoType: "video/mp4",
        audioType: "audio/mpeg",
      } as BaseMediaData))
      onItemsChange([...items, ...newItems])
    } else {
      // Single file
      const newItem: BaseMediaData = {
        type: uploadType,
        src: result.uri,
        alt: result.name || "",
        caption: "",
        size: 100,
        embedType: "direct",
        embedAudioType: "direct",
        videoType: "video/mp4",
        audioType: "audio/mpeg",
      }
      onItemsChange([...items, newItem])
    }
  }

  const handleRemoveItem = (index: number) => {
    const newItems = items.filter((_, i) => i !== index)
    onItemsChange(newItems)
  }

  const getMediaIcon = (type: string) => {
    switch (type) {
      case "image":
        return <Image className="h-4 w-4" />
      case "video":
        return <Video className="h-4 w-4" />
      case "audio":
        return <Music className="h-4 w-4" />
      default:
        return <Image className="h-4 w-4" />
    }
  }

  return (
    <div className="space-y-4">
      {/* Add Media Buttons */}
      <div className="flex gap-2">
        <Button
          variant="outline"
          size="sm"
          onClick={() => handleAddMedia("image")}
          className="flex items-center gap-2"
        >
          <Image className="h-4 w-4" />
          Add Image
        </Button>
        {/*allowMixedTypes && (
          <>
            <Button
              variant="outline"
              size="sm"
              onClick={() => handleAddMedia("video")}
              className="flex items-center gap-2"
            >
              <Video className="h-4 w-4" />
              Add Video
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() => handleAddMedia("audio")}
              className="flex items-center gap-2"
            >
              <Music className="h-4 w-4" />
              Add Audio
            </Button>
          </>
        )*/}
      </div>

      {/* Media List */}
      <div className="space-y-2 max-h-[500px] overflow-y-auto">
        {items.length === 0 ? (
          <div className="text-center py-8 text-gray-500 dark:text-gray-400 bg-gray-50 dark:bg-gray-800/50 rounded-lg border-2 border-dashed">
            <Plus className="h-8 w-8 mx-auto mb-2 opacity-50" />
            <p>No media items yet</p>
            <p className="text-sm">Click the buttons above to add media</p>
          </div>
        ) : (
          items.map((item, index) => (
            <div
              key={index}
              className="flex items-center gap-3 p-3 bg-gray-50 dark:bg-gray-800/50 rounded-lg border border-gray-200 dark:border-gray-700 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
            >
              {/* Thumbnail */}
              <div className="w-16 h-16 bg-gray-200 dark:bg-gray-700 rounded overflow-hidden shrink-0">
                {item.type === "image" && item.src && (
                  <AssetImage src={item.src} alt={item.alt || ""} className="w-full h-full object-cover" />
                )}
                {item.type === "video" && (
                  <div className="w-full h-full flex items-center justify-center">
                    <Video className="h-6 w-6 text-gray-400" />
                  </div>
                )}
                {item.type === "audio" && (
                  <div className="w-full h-full flex items-center justify-center">
                    <Music className="h-6 w-6 text-gray-400" />
                  </div>
                )}
              </div>

              {/* Info */}
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  {getMediaIcon(item.type)}
                  <span className="text-sm font-medium capitalize text-gray-900 dark:text-gray-100">
                    {item.type}
                  </span>
                  <span className="text-xs text-gray-500 dark:text-gray-400">#{index + 1}</span>
                </div>
                <p className="text-xs text-gray-600 dark:text-gray-400 truncate mt-1">
                  {item.src || "No URL"}
                </p>
              </div>

              {/* Actions */}
              <Button
                variant="ghost"
                size="sm"
                onClick={() => handleRemoveItem(index)}
                className="text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-900/20"
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            </div>
          ))
        )}
      </div>

      {/* Upload Dialog */}
      <AssetsProvider>
        <AssetPickerDialog
          open={showUploadDialog}
          onOpenChange={setShowUploadDialog}
          onSelect={handleMediaSelected}
          title={`Add ${uploadType}`}
          accept={uploadType === "image" ? "image/*" : uploadType === "video" ? "video/*" : "audio/*"}
          kinds={[uploadType]}
          multiple={true}
        />
      </AssetsProvider>
    </div>
  )
}

"use client"

import { useState, useRef, useEffect } from "react"
import { Play, Pause, Volume2, VolumeX, Maximize, AlertCircle } from "lucide-react"
import { Button } from "@game-guild/ui/components/button"
import { Slider } from "@game-guild/ui/components/slider"
import type { BaseMediaData } from "@/components/block-content-editor/nodes/base/media-node-base"
import { useResolvedAssetUrl } from "@game-guild/assets/react"
import { AssetImage } from "./asset-image"

interface MediaPreviewProps {
  data: BaseMediaData
}

export function MediaPreview({ data }: MediaPreviewProps) {
  const [isLoading, setIsLoading] = useState(true)
  const [hasError, setHasError] = useState(false)
  const [errorMessage, setErrorMessage] = useState("")
  const { url: resolvedSrc, loading: isLoadingAsset } = useResolvedAssetUrl(data.src)

  // Video/Audio player state
  const [isPlaying, setIsPlaying] = useState(false)
  const [currentTime, setCurrentTime] = useState(0)
  const [duration, setDuration] = useState(0)
  const [volume, setVolume] = useState(0.7)
  const [muted, setMuted] = useState(false)
  const [showControls, setShowControls] = useState(false)

  const mediaRef = useRef<HTMLVideoElement | HTMLAudioElement>(null)

  const formatTime = (time: number) => {
    const minutes = Math.floor(time / 60)
    const seconds = Math.floor(time % 60)
    return `${minutes}:${seconds < 10 ? "0" : ""}${seconds}`
  }

  const togglePlay = () => {
    if (!mediaRef.current) return

    try {
      if (isPlaying) {
        mediaRef.current.pause()
        setIsPlaying(false)
      } else {
        const playPromise = mediaRef.current.play()
        if (playPromise !== undefined) {
          playPromise
            .then(() => {
              setIsPlaying(true)
            })
            .catch((error) => {
              console.error("Error playing media:", error)
              setIsPlaying(false)
            })
        }
      }
    } catch (error) {
      console.error("Error controlling media:", error)
      setIsPlaying(false)
    }
  }

  const handleTimeUpdate = () => {
    if (!mediaRef.current) return
    setCurrentTime(mediaRef.current.currentTime)
    if (mediaRef.current.duration && !duration) {
      setDuration(mediaRef.current.duration)
    }
  }

  const handleSliderChange = (values: number | readonly number[]) => {
    const newTime = Array.isArray(values) ? values[0] : values
    if (!mediaRef.current || !newTime) return
    mediaRef.current.currentTime = newTime
    setCurrentTime(newTime)
  }

  const handleVolumeChange = (values: number | readonly number[]) => {
    const newVolume = Array.isArray(values) ? values[0] : values
    if (!mediaRef.current || newVolume === undefined) return
    mediaRef.current.volume = newVolume
    setVolume(newVolume)
    setMuted(newVolume === 0)
  }

  const toggleMute = () => {
    if (!mediaRef.current) return
    mediaRef.current.muted = !mediaRef.current.muted
    setMuted(!muted)
  }

  const handleFullscreen = () => {
    if (!mediaRef.current) return
    if (document.fullscreenElement) {
      document.exitFullscreen()
    } else {
      mediaRef.current.requestFullscreen()
    }
  }

  const renderImage = () => (
    <div className="flex items-center justify-center h-full w-full p-8">
      <div style={{ width: `${data.size}%` }} className="relative">
        {(isLoading || isLoadingAsset) && (
          <div className="absolute inset-0 flex items-center justify-center bg-muted/50 rounded-lg">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
          </div>
        )}
        {hasError ? (
          <div className="bg-red-50 dark:bg-red-900/20 text-red-800 dark:text-red-200 rounded-lg p-4 flex flex-col items-center justify-center min-h-[200px]">
            <AlertCircle className="h-6 w-6 mb-2" />
            <p className="text-center">{errorMessage || "Erro ao carregar imagem"}</p>
          </div>
        ) : (
          <AssetImage
            src={data.src || "/placeholder.svg"}
            alt={data.alt || ""}
            className="w-full h-auto rounded-lg"
            onLoad={() => setIsLoading(false)}
            onError={() => {
              setIsLoading(false)
              setHasError(true)
              setErrorMessage("Não foi possível carregar a imagem")
            }}
          />
        )}
        {data.caption && (
          <div className="mt-2 text-sm text-muted-foreground text-center">{data.caption}</div>
        )}
      </div>
    </div>
  )

  const renderVideo = () => {
    // Check if it's an embedded video
    const embedType = data.embedType
    
    if (embedType && embedType !== "direct") {
      return renderEmbeddedVideo()
    }

    return (
      <div className="flex items-center justify-center h-full w-full p-8">
        <div
          style={{ width: `${data.size}%` }}
          className="relative"
          onMouseEnter={() => setShowControls(true)}
          onMouseLeave={() => setShowControls(false)}
        >
          {hasError ? (
            <div className="bg-red-50 dark:bg-red-900/20 text-red-800 dark:text-red-200 rounded-lg p-4 flex flex-col items-center justify-center min-h-[200px]">
              <AlertCircle className="h-6 w-6 mb-2" />
              <p className="text-center">{errorMessage || "Erro ao carregar vídeo"}</p>
            </div>
          ) : (
            <>
              <video
                ref={mediaRef as React.RefObject<HTMLVideoElement>}
                src={resolvedSrc || data.src}
                className="w-full h-auto rounded-lg"
                onLoadedData={() => setIsLoading(false)}
                onTimeUpdate={handleTimeUpdate}
                onEnded={() => setIsPlaying(false)}
                onError={() => {
                  setIsLoading(false)
                  setHasError(true)
                  setErrorMessage("Não foi possível carregar o vídeo")
                }}
              >
                <source src={resolvedSrc || data.src} type={data.videoType || "video/mp4"} />
              </video>

              {/* Custom controls */}
              {showControls && (
                <div className="absolute bottom-0 left-0 right-0 bg-black/70 text-white p-2 rounded-b-lg">
                  <div className="space-y-2">
                    <Slider
                      value={[currentTime]}
                      max={duration || 100}
                      step={0.1}
                      onValueChange={handleSliderChange}
                      className="cursor-pointer"
                    />
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-white hover:bg-white/20"
                          onClick={togglePlay}
                        >
                          {isPlaying ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}
                        </Button>
                        <span className="text-xs">
                          {formatTime(currentTime)} / {formatTime(duration)}
                        </span>
                      </div>
                      <div className="flex items-center gap-2">
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-white hover:bg-white/20"
                          onClick={toggleMute}
                        >
                          {muted ? <VolumeX className="h-4 w-4" /> : <Volume2 className="h-4 w-4" />}
                        </Button>
                        <Slider
                          value={[muted ? 0 : volume]}
                          max={1}
                          step={0.1}
                          onValueChange={handleVolumeChange}
                          className="w-20"
                        />
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-white hover:bg-white/20"
                          onClick={handleFullscreen}
                        >
                          <Maximize className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </>
          )}
          {data.caption && (
            <div className="mt-2 text-sm text-muted-foreground text-center">{data.caption}</div>
          )}
        </div>
      </div>
    )
  }

  const renderEmbeddedVideo = () => {
    let embedUrl = ""
    let videoId = ""

    // Extract video ID from URL
    if (data.embedType === "youtube") {
      const match = data.src.match(/(?:youtube\.com\/(?:[^/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?/\s]{11})/i)
      if (match && match[1]) {
        videoId = match[1]
        embedUrl = `https://www.youtube-nocookie.com/embed/${videoId}?enablejsapi=1`
      }
    } else if (data.embedType === "vimeo") {
      const match = data.src.match(/(?:vimeo\.com\/(?:video\/)?|player\.vimeo\.com\/video\/)([0-9]+)/i)
      if (match && match[1]) {
        videoId = match[1]
        embedUrl = `https://player.vimeo.com/video/${videoId}`
      }
    } else if (data.embedType === "dailymotion") {
      const match = data.src.match(/(?:dailymotion\.com\/(?:video\/|embed\/video\/)|dai\.ly\/)([a-zA-Z0-9]+)/i)
      if (match && match[1]) {
        videoId = match[1]
        embedUrl = `https://www.dailymotion.com/embed/video/${videoId}`
      }
    }

    if (!embedUrl) {
      return (
        <div className="flex items-center justify-center h-full">
          <div className="bg-red-50 dark:bg-red-900/20 text-red-800 dark:text-red-200 rounded-lg p-4">
            <AlertCircle className="h-6 w-6 mb-2 mx-auto" />
            <p className="text-center">URL de vídeo inválida</p>
          </div>
        </div>
      )
    }

    return (
      <div className="flex items-center justify-center h-full w-full p-8">
        <div style={{ width: `${data.size}%` }} className="relative">
          <div className="relative pt-[56.25%]">
            <iframe
              src={embedUrl}
              className="absolute inset-0 w-full h-full rounded-lg"
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
              allowFullScreen
              onLoad={() => setIsLoading(false)}
              // @ts-expect-error credentialless is not yet in React's iframe types
              credentialless="true"
            />
          </div>
          {data.caption && (
            <div className="mt-2 text-sm text-muted-foreground text-center">{data.caption}</div>
          )}
        </div>
      </div>
    )
  }

  const renderAudio = () => {
    // Check if it's an embedded audio
    const embedType = data.embedAudioType
    
    if (embedType && embedType !== "direct") {
      return renderEmbeddedAudio()
    }

    return (
      <div className="flex items-center justify-center h-full w-full p-8">
        <div style={{ width: `${data.size}%` }} className="relative">
          {hasError ? (
            <div className="bg-red-50 dark:bg-red-900/20 text-red-800 dark:text-red-200 rounded-lg p-4 flex flex-col items-center justify-center min-h-[80px]">
              <AlertCircle className="h-6 w-6 mb-2" />
              <p className="text-center">{errorMessage || "Erro ao carregar áudio"}</p>
            </div>
          ) : (
            <div className="bg-card border rounded-lg p-4">
              <audio
                ref={mediaRef as React.RefObject<HTMLAudioElement>}
                src={resolvedSrc || data.src}
                onLoadedData={() => setIsLoading(false)}
                onTimeUpdate={handleTimeUpdate}
                onEnded={() => setIsPlaying(false)}
                onError={() => {
                  setIsLoading(false)
                  setHasError(true)
                  setErrorMessage("Não foi possível carregar o áudio")
                }}
              >
                <source src={resolvedSrc || data.src} type={data.audioType || "audio/mpeg"} />
              </audio>

              {/* Custom controls */}
              <div className="space-y-2">
                <Slider
                  value={[currentTime]}
                  max={duration || 100}
                  step={0.1}
                  onValueChange={handleSliderChange}
                  className="cursor-pointer"
                />
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8"
                      onClick={togglePlay}
                    >
                      {isPlaying ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}
                    </Button>
                    <span className="text-xs text-muted-foreground">
                      {formatTime(currentTime)} / {formatTime(duration)}
                    </span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8"
                      onClick={toggleMute}
                    >
                      {muted ? <VolumeX className="h-4 w-4" /> : <Volume2 className="h-4 w-4" />}
                    </Button>
                    <Slider
                      value={[muted ? 0 : volume]}
                      max={1}
                      step={0.1}
                      onValueChange={handleVolumeChange}
                      className="w-20"
                    />
                  </div>
                </div>
              </div>
            </div>
          )}
          {data.caption && (
            <div className="mt-2 text-sm text-muted-foreground text-center">{data.caption}</div>
          )}
        </div>
      </div>
    )
  }

  const renderEmbeddedAudio = () => {
    let embedUrl = ""
    let audioId = ""
    let height = "80"

    if (data.embedAudioType === "youtube") {
      const match = data.src.match(/(?:youtube\.com\/(?:[^/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?/\s]{11})/i)
      if (match && match[1]) {
        audioId = match[1]
        embedUrl = `https://www.youtube-nocookie.com/embed/${audioId}?feature=oembed&enablejsapi=1&showinfo=0&controls=1&disablekb=1&rel=0&modestbranding=1&vq=small&iv_load_policy=3&fs=0`
        height = "60"
      }
    } else if (data.embedAudioType === "spotify") {
      const match = data.src.match(/(?:spotify\.com\/track\/|spotify:track:)([a-zA-Z0-9]+)/i)
      if (match && match[1]) {
        audioId = match[1]
        embedUrl = `https://open.spotify.com/embed/track/${audioId}`
      }
    } else if (data.embedAudioType === "soundcloud") {
      const match = data.src.match(/soundcloud\.com\/([^/]+\/[^/]+)/i)
      if (match && match[1]) {
        audioId = match[1]
        embedUrl = `https://w.soundcloud.com/player/?url=https%3A//soundcloud.com/${audioId}&color=%23ff5500&auto_play=false&hide_related=false&show_comments=true&show_user=true&show_reposts=false&show_teaser=true`
        height = "166"
      }
    }

    if (!embedUrl) {
      return (
        <div className="flex items-center justify-center h-full">
          <div className="bg-red-50 dark:bg-red-900/20 text-red-800 dark:text-red-200 rounded-lg p-4">
            <AlertCircle className="h-6 w-6 mb-2 mx-auto" />
            <p className="text-center">URL de áudio inválida</p>
          </div>
        </div>
      )
    }

    return (
      <div className="flex items-center justify-center h-full w-full p-8">
        <div style={{ width: `${data.size}%` }} className="relative">
          <iframe
            src={embedUrl}
            height={height}
            className="w-full rounded-lg border"
            allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture"
            loading="lazy"
            onLoad={() => setIsLoading(false)}
            // @ts-expect-error credentialless is not yet in React's iframe types
            credentialless="true"
          />
          {data.caption && (
            <div className="mt-2 text-sm text-muted-foreground text-center">{data.caption}</div>
          )}
        </div>
      </div>
    )
  }

  const renderContent = () => {
    if (!data.src) {
      return (
        <div className="flex items-center justify-center h-full">
          <div className="text-center text-muted-foreground">
            <p>Nenhuma mídia selecionada</p>
            <p className="text-sm mt-1">Configure a URL da mídia no painel à esquerda</p>
          </div>
        </div>
      )
    }

    switch (data.type) {
      case "image":
        return renderImage()
      case "video":
        return renderVideo()
      case "audio":
        return renderAudio()
      default:
        return null
    }
  }

  return (
    <div className="w-full h-full bg-muted/30 flex items-center justify-center overflow-auto">
      {renderContent()}
    </div>
  )
}

"use client"

import { useState, useEffect } from "react"
import { Button } from "@game-guild/ui/components/button"
import { Input } from "@game-guild/ui/components/input"
import { Label } from "@game-guild/ui/components/label"
import { Save, Image, Video, Music, FileText, Eye, Grid } from "lucide-react"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@game-guild/ui/components/tabs"
import { useEditorSettings } from "@/components/block-content-editor/extras/settings-menu"
import { BlockEditorShell } from "@/components/block-content-editor/extras/block-editor-shell"
import { MediaPreview } from "./media-preview"
import { ImageOptions } from "./image-options"
import { VideoOptions } from "./video-options"
import { AudioOptions } from "./audio-options"
import { MediaListTab } from "./media-list-tab"
import { LayoutTab } from "./layout-tab"
import { CaptionsTab } from "./captions-tab"
import {
  detectVideoEmbedType,
  detectAudioEmbedType,
  detectVideoFileType,
  detectAudioFileType
} from "./url-detection"
import type { BaseMediaData } from "@/components/block-content-editor/nodes/base/media-node-base"
import { AssetImage } from "./asset-image"

interface UnifiedMediaEditorProps {
  data: BaseMediaData
  onChange: (data: Partial<BaseMediaData>) => void
  onClose?: () => void
  onSave?: (items?: BaseMediaData[], columns?: number, caption?: string) => void
  mode?: "single" | "gallery"
  galleryItems?: BaseMediaData[]
  onGalleryItemsChange?: (items: BaseMediaData[]) => void
  galleryColumns?: number
  onGalleryColumnsChange?: (columns: number) => void
  galleryCaption?: string
  onGalleryCaptionChange?: (caption: string) => void
}

export function UnifiedMediaEditor({ 
  data, 
  onChange, 
  onClose, 
  onSave,
  mode = "single",
  galleryItems = [],
  onGalleryItemsChange,
  galleryColumns = 2,
  onGalleryColumnsChange,
  galleryCaption = "",
  onGalleryCaptionChange
}: UnifiedMediaEditorProps) {
  const [localData, setLocalData] = useState<BaseMediaData>(data)
  const [urlDetectionEnabled, setUrlDetectionEnabled] = useState(true)
  const [activeTab, setActiveTab] = useState<string>("media")
  const settings = useEditorSettings("media")
  
  // Only allow gallery mode for images (video/audio always single)
  const canUseGallery = data.type === "image"
  
  // Sempre trabalha em modo galeria, começando vazio ou com items existentes
  const [localGalleryItems, setLocalGalleryItems] = useState<BaseMediaData[]>(() => {
    if (!canUseGallery) {
      // Para video/audio, sempre usa o item único se tiver src
      return data.src ? [data] : []
    }
    // Para imagens, usa galleryItems se tiver, senão usa data apenas se tiver src válida
    if (galleryItems.length > 0) {
      return galleryItems
    }
    // Só inclui o data inicial se tiver uma src válida (não vazia)
    return data.src && data.src.trim() !== "" ? [data] : []
  })
  const [localColumns, setLocalColumns] = useState(galleryColumns)
  const [localGlobalCaption, setLocalGlobalCaption] = useState(galleryCaption)
  
  // Determina se é galeria baseado no número de itens (apenas para imagens)
  const isGalleryMode = canUseGallery && localGalleryItems.length > 1

  // Sincroniza localData com o primeiro item da galeria ou mantém vazio
  useEffect(() => {
    const firstItem = localGalleryItems[0]
    if (firstItem && !isGalleryMode) {
      setLocalData(firstItem)
    } else if (!firstItem && localGalleryItems.length === 0) {
      // Se não há items, mantém localData com src vazio
      setLocalData(prev => ({ ...prev, src: "" }))
    }
  }, [localGalleryItems, isGalleryMode])

  // Auto-detect embed type when URL changes
  useEffect(() => {
    if (!urlDetectionEnabled || !localData.src) return
    
    if (localData.type === "video") {
      const detectedType = detectVideoEmbedType(localData.src)
      
      if (detectedType !== localData.embedType) {
        const updates: Partial<BaseMediaData> = { embedType: detectedType }
        
        // If it's a direct file, also detect the video format
        if (detectedType === "direct") {
          updates.videoType = detectVideoFileType(localData.src)
        }
        
        const newData = { ...localData, ...updates }
        setLocalData(newData)
        // Don't call onChange here, it will be called on save
      }
    } else if (localData.type === "audio") {
      const detectedType = detectAudioEmbedType(localData.src)
      
      if (detectedType !== localData.embedAudioType) {
        const updates: Partial<BaseMediaData> = { embedAudioType: detectedType }
        
        // If it's a direct file, also detect the audio format
        if (detectedType === "direct") {
          updates.audioType = detectAudioFileType(localData.src)
        }
        
        const newData = { ...localData, ...updates }
        setLocalData(newData)
        // Don't call onChange here, it will be called on save
      }
    }
  }, [localData.src, localData.type, urlDetectionEnabled, localData])

  const handleChange = (field: keyof BaseMediaData, value: any) => {
    const newData = { ...localData, [field]: value }
    setLocalData(newData)
    onChange({ [field]: value })
    
    // Disable auto-detection temporarily when user manually changes embed type
    if (field === "embedType" || field === "embedAudioType") {
      setUrlDetectionEnabled(false)
      // Re-enable after a delay
      setTimeout(() => setUrlDetectionEnabled(true), 2000)
    }
  }
  
  const handleUrlChange = (newUrl: string) => {
    setUrlDetectionEnabled(true) // Re-enable detection on URL change
    handleChange("src", newUrl)
  }

  const handleSave = () => {
    // Filter out items without src that are not placeholders
    const validItems = localGalleryItems.filter(item => 
      item.isPlaceholder || (item.src && item.src.trim() !== "")
    )
    
    if (onSave) {
      // Pass all data to onSave - it will decide what to do
      // Only pass gallery data if canUseGallery is true
      if (canUseGallery) {
        onSave(validItems, localColumns, localGlobalCaption)
      } else {
        // For video/audio, just save the single item if valid
        const itemToSave = validItems.length > 0 ? validItems : [localData]
        onSave(itemToSave, undefined, undefined)
      }
    } else {
      // Fallback to old behavior
      if (isGalleryMode && canUseGallery) {
        // Save gallery data (múltiplos itens) - only for images
        if (onGalleryItemsChange) onGalleryItemsChange(validItems)
        if (onGalleryColumnsChange) onGalleryColumnsChange(localColumns)
        if (onGalleryCaptionChange) onGalleryCaptionChange(localGlobalCaption)
      } else {
        // Save single media data (1 item apenas ou video/audio)
        const singleItem = validItems[0] || localData
        onChange(singleItem)
      }
      
      if (onClose) {
        onClose()
      }
    }
  }

  const handleClose = () => {
    if (onClose) {
      onClose()
    }
  }

  const getMediaIcon = () => {
    switch (localData.type) {
      case "image":
        return <Image className="h-5 w-5 text-blue-600 dark:text-blue-400" />
      case "video":
        return <Video className="h-5 w-5 text-blue-600 dark:text-blue-400" />
      case "audio":
        return <Music className="h-5 w-5 text-blue-600 dark:text-blue-400" />
    }
  }

  const getMediaTitle = () => {
    if (isGalleryMode) {
      return "Gallery Editor"
    }
    const firstItem = localGalleryItems[0] || localData
    switch (firstItem.type) {
      case "image":
        return "Image Editor"
      case "video":
        return "Video Editor"
      case "audio":
        return "Audio Editor"
    }
  }
  
  const getHeaderIcon = () => {
    if (isGalleryMode) {
      return <Grid className="h-5 w-5 text-blue-600 dark:text-blue-400" />
    }
    return getMediaIcon()
  }

  const renderMediaSpecificOptions = () => {
    switch (localData.type) {
      case "video":
        return <VideoOptions data={localData} onChange={handleChange} />
      case "audio":
        return <AudioOptions data={localData} onChange={handleChange} />
      case "image":
      default:
        return <ImageOptions data={localData} onChange={handleChange} />
    }
  }

  return (
    <BlockEditorShell
      settings={settings}
      includeMonacoTheme={false}
      onClose={handleClose}
      icon={getHeaderIcon()}
      title={getMediaTitle()}
      headerMeta={
        isGalleryMode ? (
          <>
            <span className="text-sm text-gray-600 dark:text-gray-400 bg-gray-100 dark:bg-gray-800 px-2 py-1 rounded">
              Items: <span className="font-medium text-gray-800 dark:text-gray-200">{localGalleryItems.length}</span>
            </span>
            <span className="text-sm text-gray-600 dark:text-gray-400 bg-blue-50 dark:bg-blue-900/30 px-2 py-1 rounded">
              Columns: <span className="font-medium text-blue-600 dark:text-blue-400">{localColumns}</span>
            </span>
          </>
        ) : (
          <>
            <span className="text-sm text-gray-600 dark:text-gray-400 bg-gray-100 dark:bg-gray-800 px-2 py-1 rounded">
              Type: <span className="font-medium text-gray-800 dark:text-gray-200 capitalize">{localData.type}</span>
            </span>
            {localData.embedType && localData.embedType !== "direct" && (
              <span className="text-sm text-gray-600 dark:text-gray-400 bg-blue-50 dark:bg-blue-900/30 px-2 py-1 rounded flex items-center gap-1">
                <span className="font-medium text-blue-600 dark:text-blue-400 capitalize">{localData.embedType}</span>
                {urlDetectionEnabled && <span className="text-xs">🔍</span>}
              </span>
            )}
            {localData.embedAudioType && localData.embedAudioType !== "direct" && (
              <span className="text-sm text-gray-600 dark:text-gray-400 bg-blue-50 dark:bg-blue-900/30 px-2 py-1 rounded flex items-center gap-1">
                <span className="font-medium text-blue-600 dark:text-blue-400 capitalize">{localData.embedAudioType}</span>
                {urlDetectionEnabled && <span className="text-xs">🔍</span>}
              </span>
            )}
            {localData.embedType === "direct" && localData.type === "video" && localData.videoType && (
              <span className="text-sm text-gray-600 dark:text-gray-400 bg-green-50 dark:bg-green-900/30 px-2 py-1 rounded">
                <span className="font-medium text-green-600 dark:text-green-400">{localData.videoType}</span>
              </span>
            )}
            {localData.embedAudioType === "direct" && localData.type === "audio" && localData.audioType && (
              <span className="text-sm text-gray-600 dark:text-gray-400 bg-green-50 dark:bg-green-900/30 px-2 py-1 rounded">
                <span className="font-medium text-green-600 dark:text-green-400">{localData.audioType}</span>
              </span>
            )}
          </>
        )
      }
      footer={
        <div className="flex items-center justify-end gap-2">
          <Button
            variant="outline"
            onClick={handleClose}
            className="border-gray-300 dark:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-800 bg-transparent"
          >
            Cancel
          </Button>
          <Button
            onClick={handleSave}
            className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 dark:bg-blue-500 dark:hover:bg-blue-600"
          >
            <Save className="h-4 w-4" />
            {isGalleryMode ? "Save Gallery" : "Save Media"}
          </Button>
        </div>
      }
    >
      {/* Main Content */}
      <div className="flex-1 flex min-h-0">
          {/* Left Panel - Configuration */}
          <div className="w-1/2 border-r border-gray-200 dark:border-gray-800 flex flex-col bg-white dark:bg-gray-900">
            <div className="p-4 border-b border-gray-200 dark:border-gray-800 bg-gray-50 dark:bg-gray-900">
              <h3 className="font-medium flex items-center gap-2 text-gray-800 dark:text-gray-200">
                <FileText className="h-4 w-4 text-blue-600 dark:text-blue-400" />
                Configuration
              </h3>
            </div>

            <div className="flex-1 overflow-y-auto p-4">
              {canUseGallery ? (
                <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
                  <TabsList className="grid w-full grid-cols-3 mb-4">
                    <TabsTrigger value="media">Media</TabsTrigger>
                    <TabsTrigger value="layout">Layout</TabsTrigger>
                    <TabsTrigger value="captions">Captions</TabsTrigger>
                  </TabsList>
                  
                  <TabsContent value="media" className="space-y-4">
                    <MediaListTab
                      items={localGalleryItems}
                      onItemsChange={setLocalGalleryItems}
                      allowMixedTypes={true}
                      defaultType={localData.type}
                    />
                  </TabsContent>
                  
                  <TabsContent value="layout" className="space-y-4">
                    <LayoutTab
                      items={localGalleryItems}
                      onItemsChange={setLocalGalleryItems}
                      columns={localColumns}
                      onColumnsChange={setLocalColumns}
                    />
                  </TabsContent>
                  
                  <TabsContent value="captions" className="space-y-4">
                    <CaptionsTab
                      items={localGalleryItems}
