                  </TabsContent>
                </Tabs>
              ) : (
                <div className="space-y-4">
                  {/* URL Field */}
                  <div className="space-y-2">
                    <Label htmlFor="src" className="text-sm font-medium text-gray-700 dark:text-gray-300">
