"use client"

import { useState, useEffect } from "react"
import { Button } from "@game-guild/ui/components/button"
import { Badge } from "@game-guild/ui/components/badge"
import { ScrollArea } from "@game-guild/ui/components/scroll-area"
import { FileText, Calendar, Filter, Pin, PinOff } from "lucide-react"
import { ProjectSearchFilters } from "../../extras/project-dialog/project-search-filters"
import type { ProjectData } from "./preview-load-operations"
import type { StorageType } from "@/components/block-content-editor/lib/storage/editor/storage-types"

interface ProjectSidebarListProps {
  storageAdapter: {
    list: () => Promise<ProjectData[]>
    searchProjects: (searchTerm: string, tags: string[], filterMode: "all" | "any", storageTypeFilter?: StorageType) => Promise<ProjectData[]>
  }
  availableTags: Array<{ name: string }>
  currentProject: ProjectData | null
  onProjectSelect: (project: ProjectData) => void
  isDbInitialized: boolean
  isSticky?: boolean
  searchModeOnly?: boolean
}

export function ProjectSidebarList({
  storageAdapter,
  availableTags,
  currentProject,
  onProjectSelect,
  isDbInitialized,
  isSticky = false,
  searchModeOnly = true,
}: ProjectSidebarListProps) {
  const [projects, setProjects] = useState<ProjectData[]>([])
  const [filteredProjects, setFilteredProjects] = useState<ProjectData[]>([])
  const [searchTerm, setSearchTerm] = useState("")
  const [selectedTags, setSelectedTags] = useState<string[]>([])
  const [tagFilterMode, setTagFilterMode] = useState<"all" | "any">("any")
  const [storageTypeFilter, setStorageTypeFilter] = useState<StorageType | undefined>(undefined)
  const [showFilters, setShowFilters] = useState(false)
  const [loading, setLoading] = useState(false)
  const [itemsPerPage, setItemsPerPage] = useState(20)
  const [isPinned, setIsPinned] = useState(isSticky)
  const [isMobile, setIsMobile] = useState(false)

  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth < 1024) // lg breakpoint
    }
    checkMobile()
    window.addEventListener("resize", checkMobile)
    return () => window.removeEventListener("resize", checkMobile)
  }, [])

  // Load projects on initialization
  useEffect(() => {
    if (isDbInitialized) {
      loadProjects()
    }
  }, [isDbInitialized])

  // Filter projects when search term, tags, or storage type change
  useEffect(() => {
    if (searchTerm || selectedTags.length > 0 || storageTypeFilter) {
      searchProjects()
    } else {
      if (searchModeOnly) {
        setFilteredProjects([])
      } else {
        setFilteredProjects(projects)
      }
    }
  }, [searchTerm, selectedTags, tagFilterMode, storageTypeFilter, projects, searchModeOnly])

  const loadProjects = async () => {
    try {
      setLoading(true)
      if (searchModeOnly) {
        setProjects([])
        setFilteredProjects([])
      } else {
        const allProjects = await storageAdapter.list()
        setProjects(allProjects)
        setFilteredProjects(allProjects)
      }
    } catch (error) {
      console.error("Failed to load projects:", error)
    } finally {
      setLoading(false)
    }
  }

  const searchProjects = async () => {
    try {
      setLoading(true)
      const results = await storageAdapter.searchProjects(searchTerm, selectedTags, tagFilterMode, storageTypeFilter)
      setFilteredProjects(results)
    } catch (error) {
      console.error("Failed to search projects:", error)
    } finally {
      setLoading(false)
    }
  }

  const handleTagToggle = (tagName: string) => {
    const newSelectedTags = selectedTags.includes(tagName)
      ? selectedTags.filter((t) => t !== tagName)
      : [...selectedTags, tagName]
    setSelectedTags(newSelectedTags)
  }

  const clearFilters = () => {
    setSearchTerm("")
    setSelectedTags([])
  }

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return "0 B"
    const k = 1024
    const sizes = ["B", "KB", "MB", "GB"]
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i]
  }

  return (
    <div className={`${(isPinned || isMobile) ? 'sticky top-24 max-h-[calc(100vh-7rem)]' : ''}`}>
      <div className={`w-full md:w-96 bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 shadow-sm flex flex-col ${(isPinned || isMobile) ? 'max-h-[calc(100vh-7rem)]' : 'h-full'} md:mr-8`}>
        {/* Header */}
        <div className="p-6 border-b border-gray-200 dark:border-gray-700 shrink-0 bg-gray-50 dark:bg-gray-900">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">Documents</h3>
            <div className="flex items-center gap-1">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setIsPinned(!isPinned)}
                className="h-8 w-8 p-0 hover:bg-gray-100 dark:hover:bg-gray-800 hidden lg:flex"
                title={isPinned ? "Unpin sidebar" : "Pin sidebar"}
              >
                {isPinned ? <PinOff className="h-4 w-4" /> : <Pin className="h-4 w-4" />}
              </Button>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setShowFilters(!showFilters)}
                className="h-8 w-8 p-0 hover:bg-gray-100 dark:hover:bg-gray-800"
              >
                <Filter className="h-4 w-4" />
              </Button>
            </div>
          </div>

          <ProjectSearchFilters
            searchTerm={searchTerm}
            onSearchChange={setSearchTerm}
            selectedTags={selectedTags}
            onTagsChange={setSelectedTags}
            availableTags={availableTags}
            tagFilterMode={tagFilterMode}
            onTagFilterModeChange={setTagFilterMode}
            storageTypeFilter={storageTypeFilter}
            onStorageTypeFilterChange={setStorageTypeFilter}
            itemsPerPage={itemsPerPage}
            onItemsPerPageChange={setItemsPerPage}
            showFilters={showFilters}
            forceVerticalLayout={true}
          />
        </div>

        {/* Project List */}
        <ScrollArea className="flex-1 px-6 py-4 overflow-auto">
          <div className="space-y-3">
            {loading ? (
              <div className="text-center py-8 text-sm text-gray-500">
                <div className="animate-pulse">Loading documents...</div>
              </div>
            ) : filteredProjects.length === 0 ? (
              <div className="text-center py-12">
                <FileText className="w-12 h-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
                <p className="text-sm text-gray-500 dark:text-gray-400 mb-1">
                  {searchTerm || selectedTags.length > 0 || storageTypeFilter
                    ? "No documents found"
                    : searchModeOnly
                      ? "Use the filters to search for documents"
                      : "No documents available"}
                </p>
                {searchTerm || selectedTags.length > 0 || storageTypeFilter ? (
                  <p className="text-xs text-gray-400 dark:text-gray-500">Try adjusting your search or filters</p>
                ) : searchModeOnly ? (
                  <p className="text-xs text-gray-400 dark:text-gray-500">The list will appear after searching</p>
                ) : null}
              </div> // null
            ) : (
              filteredProjects.map((project) => (
                <div
                  key={project.id}
                  onClick={() => onProjectSelect(project)}
                  className={`p-4 border cursor-pointer transition-all duration-200 hover:shadow-sm ${
                    currentProject?.id === project.id
                      ? "bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-700/50 shadow-sm"
                      : "bg-gray-50 dark:bg-gray-800/50 border-gray-200 dark:border-gray-700 hover:bg-gray-100 dark:hover:bg-gray-800"
                  }`}
                >
                  <div className="flex items-start gap-3">
                    <div className={`p-2 ${
                      currentProject?.id === project.id
                        ? "bg-blue-100 dark:bg-blue-900/40"
                        : "bg-gray-100 dark:bg-gray-700"
                    }`}>
                      <FileText className="w-4 h-4 text-gray-600 dark:text-gray-400" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <h4 className="text-sm font-medium text-gray-900 dark:text-gray-100 truncate mb-1">
                        {project.name}
                      </h4>
                      
                      {project.tags && project.tags.length > 0 && (
                        <div className="flex flex-wrap gap-1 mb-3">
                          {project.tags.slice(0, 3).map((tag) => (
                            <Badge key={tag} variant="outline" className="text-xs px-2 py-0.5 h-5">
                              {tag}
                            </Badge>
                          ))}
                          {project.tags.length > 3 && (
                            <Badge variant="outline" className="text-xs px-2 py-0.5 h-5">
                              +{project.tags.length - 3}
                            </Badge>
                          )}
                        </div>
                      )}

                      <div className="flex items-center gap-3 text-xs text-gray-500 dark:text-gray-400">
                        <div className="flex items-center gap-1">
                          <Calendar className="w-3 h-3" />
                          {new Date(project.metadata.updatedAt).toLocaleDateString()}
                        </div>
                        <span>•</span>
                        <span>{formatFileSize(project.metadata.size)}</span>
                        <span>•</span>
                        <Badge 
                          variant={project.storageType === "local" ? "default" : "outline"} 
                          className="text-xs px-1.5 py-0.5 h-4"
                        >
                          {project.storageType === "local" ? "📱" : "☁️"}
                        </Badge>
                      </div>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        </ScrollArea>

        {/* Footer Stats */}
        <div className="p-4 border-t border-gray-200 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50 shrink-0">
          <div className="text-xs text-gray-500 dark:text-gray-400 text-center">
            <div className="font-medium">
              {filteredProjects.length} of {projects.length} documents
            </div>
            {selectedTags.length > 0 && (
              <div className="mt-1 text-gray-400 dark:text-gray-500">
                Filtered by {selectedTags.length} tag{selectedTags.length > 1 ? 's' : ''}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

