import { Badge } from "@game-guild/ui/components/badge"
import { Button } from "@game-guild/ui/components/button"
import { Input } from "@game-guild/ui/components/input"
import { Label } from "@game-guild/ui/components/label"
import { ScrollArea } from "@game-guild/ui/components/scroll-area"
import { Calendar, ChevronDown, FileText, Filter, Search } from "lucide-react"
import { useEffect, useState } from "react"
import type { ProjectData } from "@/components/block-content-editor/lib/storage/editor/project-data"
import type { StorageType } from "@/components/block-content-editor/lib/storage/editor/storage-types"

interface ProjectSidebarListProps {
  storageAdapter: {
    list: () => Promise<ProjectData[]>
    searchProjects: (searchTerm: string, tags: string[], filterMode: "all" | "any", storageTypeFilter?: StorageType) => Promise<ProjectData[]>
  }
  availableTags: Array<{ name: string; usageCount: number }>
  currentProject: ProjectData | null
  onProjectSelect: (project: ProjectData) => void
  isDbInitialized: boolean
}

export function ProjectSidebarList({
  storageAdapter,
  availableTags,
  currentProject,
  onProjectSelect,
  isDbInitialized,
}: ProjectSidebarListProps) {
  const [projects, setProjects] = useState<ProjectData[]>([])
  const [filteredProjects, setFilteredProjects] = useState<ProjectData[]>([])
  const [searchTerm, setSearchTerm] = useState("")
  const [selectedTags, setSelectedTags] = useState<string[]>([])
  const [tagFilterMode, setTagFilterMode] = useState<"all" | "any">("any")
  const [storageTypeFilter, setStorageTypeFilter] = useState<StorageType | undefined>(undefined)
  const [showFilters, setShowFilters] = useState(false)
  const [loading, setLoading] = useState(false)
  const [tagSearchInput, setTagSearchInput] = useState("")
  const [showTagDropdown, setShowTagDropdown] = useState(false)

  // Close tag dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (showTagDropdown) {
        const target = event.target as Element
        if (!target.closest(".tag-dropdown-container")) {
          setShowTagDropdown(false)
        }
      }
    }

    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [showTagDropdown])

  // Load projects on initialization
  useEffect(() => {
    if (isDbInitialized) {
      loadProjects()
    }
  }, [isDbInitialized])

  // Filter projects when search term or tags change
  useEffect(() => {
    if (searchTerm || selectedTags.length > 0) {
      searchProjects()
    } else {
      setFilteredProjects(projects)
    }
  }, [searchTerm, selectedTags, tagFilterMode, projects])

  const loadProjects = async () => {
    try {
      setLoading(true)
      const allProjects = await storageAdapter.list()
      setProjects(allProjects)
      setFilteredProjects(allProjects)
    } catch (error) {
      console.error("Failed to load projects:", error)
    } finally {
      setLoading(false)
    }
  }

  const searchProjects = async () => {
    try {
      setLoading(true)
      const results = await storageAdapter.searchProjects(searchTerm, selectedTags, tagFilterMode, storageTypeFilter)
      setFilteredProjects(results)
    } catch (error) {
      console.error("Failed to search projects:", error)
    } finally {
      setLoading(false)
    }
  }

  const handleTagToggle = (tagName: string) => {
    const newSelectedTags = selectedTags.includes(tagName)
      ? selectedTags.filter((t) => t !== tagName)
      : [...selectedTags, tagName]
    setSelectedTags(newSelectedTags)
  }

  const clearFilters = () => {
    setSearchTerm("")
    setSelectedTags([])
    setTagSearchInput("")
  }

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return "0 B"
    const k = 1024
    const sizes = ["B", "KB", "MB", "GB"]
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i]
  }

  const filteredTagsForDropdown = tagSearchInput.trim()
    ? availableTags.filter((tag) => tag.name.toLowerCase().includes(tagSearchInput.toLowerCase()))
    : availableTags

  return (
    <div className="w-80 bg-white dark:bg-gray-900 border-r border-gray-200 dark:border-gray-800 flex flex-col h-full">
      {/* Header */}
      <div className="p-4 border-b border-gray-200 dark:border-gray-700">
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-sm font-semibold text-gray-900 dark:text-gray-100">Documents</h3>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setShowFilters(!showFilters)}
            className="h-8 w-8 p-0"
          >
            <Filter className="h-4 w-4" />
          </Button>
        </div>

        {/* Search */}
        <div className="relative mb-3">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
          <Input
            placeholder="Search documents..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10 h-8 text-sm"
          />
        </div>

        {/* Collapsible Filters */}
        {showFilters && (
          <div className="space-y-3 pt-3 border-t border-gray-200 dark:border-gray-700">
            <div className="flex items-center justify-between">
              <Label className="text-xs font-medium text-gray-700 dark:text-gray-300">Filter Mode:</Label>
              <select
                value={tagFilterMode}
                onChange={(e) => setTagFilterMode(e.target.value as "all" | "any")}
                className="px-2 py-1 border rounded text-xs bg-background"
              >
                <option value="any">Any tags</option>
                <option value="all">All tags</option>
              </select>
            </div>

            {/* Tag Filter */}
            <div className="relative tag-dropdown-container">
              <Input
                placeholder="Search tags..."
                value={tagSearchInput}
                onChange={(e) => {
                  setTagSearchInput(e.target.value)
                  setShowTagDropdown(true)
                }}
                onFocus={() => setShowTagDropdown(true)}
                className="h-8 text-xs pr-8"
              />
              <button
                type="button"
                onClick={() => setShowTagDropdown(!showTagDropdown)}
                className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
              >
                <ChevronDown className={`w-3 h-3 transition-transform ${showTagDropdown ? "rotate-180" : ""}`} />
              </button>

              {showTagDropdown && (
                <div className="absolute z-10 w-full mt-1 bg-white dark:bg-gray-800 border dark:border-gray-700 rounded-md shadow-lg max-h-32 overflow-y-auto">
                  {filteredTagsForDropdown.length === 0 ? (
                    <div className="px-3 py-2 text-xs text-gray-500">No tags found</div>
                  ) : (
                    filteredTagsForDropdown.map((tag) => (
                      <button
                        key={tag.name}
                        type="button"
                        onClick={() => {
                          handleTagToggle(tag.name)
                          setShowTagDropdown(false)
                        }}
                        className="w-full px-3 py-1.5 text-left hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center justify-between text-xs"
                      >
                        <div className="flex items-center gap-2">
                          <div
                            className={`w-3 h-3 border rounded flex items-center justify-center ${selectedTags.includes(tag.name)
                                ? "bg-blue-500 border-blue-500"
                                : "border-gray-300"
                              }`}
                          >
                            {selectedTags.includes(tag.name) && (
                              <svg className="w-2 h-2 text-white" fill="currentColor" viewBox="0 0 20 20">
                                <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                              </svg>
                            )}
                          </div>
                          <span>{tag.name}</span>
                        </div>
                        <span className="text-gray-400">({tag.usageCount})</span>
                      </button>
                    ))
                  )}
                </div>
              )}
            </div>

            {/* Selected Tags */}
            {selectedTags.length > 0 && (
              <div className="space-y-2">
                <div className="flex flex-wrap gap-1">
                  {selectedTags.map((tagName) => (
                    <Badge
                      key={tagName}
                      variant="secondary"
                      className="text-xs px-2 py-0.5 cursor-pointer"
                      onClick={() => handleTagToggle(tagName)}
                    >
                      {tagName} ×
                    </Badge>
                  ))}
                </div>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={clearFilters}
                  className="h-6 text-xs text-blue-600 hover:text-blue-700 p-0"
                >
                  Clear all filters
                </Button>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Project List */}
      <ScrollArea className="flex-1">
        <div className="p-2 space-y-1">
          {loading ? (
            <div className="text-center py-8 text-sm text-gray-500">Loading documents...</div>
          ) : filteredProjects.length === 0 ? (
            <div className="text-center py-8">
              <FileText className="w-8 h-8 text-gray-300 dark:text-gray-600 mx-auto mb-2" />
              <p className="text-sm text-gray-500 dark:text-gray-400">
                {searchTerm || selectedTags.length > 0 ? "No documents found" : "No documents available"}
              </p>
            </div>
          ) : (
            filteredProjects.map((project) => (
              <div
                key={project.id}
                onClick={() => onProjectSelect(project)}
                className={`p-3 rounded-lg border cursor-pointer transition-colors ${currentProject?.id === project.id
                    ? "bg-blue-50 dark:bg-blue-900/30 border-blue-200 dark:border-blue-700"
                    : "bg-gray-50 dark:bg-gray-800 border-gray-200 dark:border-gray-700 hover:bg-gray-100 dark:hover:bg-gray-700"
                  }`}
              >
                <div className="flex items-start gap-2">
                  <FileText className="w-4 h-4 text-gray-400 dark:text-gray-500 mt-0.5 shrink-0" />
                  <div className="flex-1 min-w-0">
                    <h4 className="text-sm font-medium text-gray-900 dark:text-gray-100 truncate">
                      {project.name}
                    </h4>

                    {project.tags && project.tags.length > 0 && (
                      <div className="flex flex-wrap gap-1 mt-1">
                        {project.tags.slice(0, 2).map((tag) => (
                          <Badge key={tag} variant="outline" className="text-xs px-1 py-0">
                            {tag}
                          </Badge>
                        ))}
                        {project.tags.length > 2 && (
                          <Badge variant="outline" className="text-xs px-1 py-0">
                            +{project.tags.length - 2}
                          </Badge>
                        )}
                      </div>
                    )}

                    <div className="flex items-center gap-2 mt-2 text-xs text-gray-500 dark:text-gray-400">
                      <div className="flex items-center gap-1">
                        <Calendar className="w-3 h-3" />
                        {new Date(project.metadata.updatedAt).toLocaleDateString()}
                      </div>
                      <span>•</span>
                      <span>{formatFileSize(project.metadata.size)}</span>
                    </div>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </ScrollArea>

      {/* Footer Stats */}
      <div className="p-3 border-t border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800">
        <div className="text-xs text-gray-500 dark:text-gray-400 text-center">
          {filteredProjects.length} of {projects.length} documents
          {selectedTags.length > 0 && (
            <span className="ml-1">
              • Filtered by {selectedTags.length} tag{selectedTags.length > 1 ? 's' : ''}
            </span>
          )}
        </div>
      </div>
    </div>
  )
}

"use client"
import type { SerializedEditorState } from "lexical"

// Import all preview components
import { PreviewQuiz } from "@/components/block-content-editor/plugins/preview-components/preview-quiz"
import { PreviewImage } from "@/components/block-content-editor/plugins/preview-components/preview-image"
import { PreviewGallery } from "@/components/block-content-editor/plugins/preview-components/preview-gallery"
import { PreviewMarkdown } from "@/components/block-content-editor/plugins/preview-components/preview-markdown"
import { PreviewHTML } from "@/components/block-content-editor/plugins/preview-components/preview-html"
import { PreviewVideo } from "@/components/block-content-editor/plugins/preview-components/preview-video"
import { PreviewAudio } from "@/components/block-content-editor/plugins/preview-components/preview-audio"
import { PreviewHeader } from "@/components/block-content-editor/plugins/preview-components/preview-header"
import { PreviewDivider } from "@/components/block-content-editor/plugins/preview-components/preview-divider"
import { PreviewSource } from "@/components/block-content-editor/plugins/preview-components/preview-source"
import { PreviewAdmonition } from "@/components/block-content-editor/plugins/preview-components/preview-admonition"
import { PreviewButton } from "@/components/block-content-editor/plugins/preview-components/preview-button"
import { PreviewText } from "@/components/block-content-editor/plugins/preview-components/preview-text"
import { PreviewMermaid } from "@/components/block-content-editor/plugins/preview-components/preview-mermaid"
import { PreviewParagraph } from "@/components/block-content-editor/plugins/preview-components/preview-paragraph"
import { PreviewQuote } from "@/components/block-content-editor/plugins/preview-components/preview-quote"
import { PreviewList } from "@/components/block-content-editor/plugins/preview-components/preview-list"
import { PreviewListItem } from "@/components/block-content-editor/plugins/preview-components/preview-list-item"
import { PreviewLink } from "@/components/block-content-editor/plugins/preview-components/preview-link"
import { PreviewHeading } from "@/components/block-content-editor/plugins/preview-components/preview-heading"
import { PreviewVegaLite } from "@/components/block-content-editor/plugins/preview-components/preview-vega-lite"
import { PreviewCodeStudio } from "@/components/block-content-editor/plugins/preview-components/preview-code-studio"
import { PreviewProject } from "@/components/block-content-editor/plugins/preview-components/preview-project"
import { PreviewRichText } from "@/components/block-content-editor/plugins/preview-components/preview-rich-text"

interface SerializedContentRendererProps {
  serializedState: SerializedEditorState
  className?: string
  projectId?: string
  storageAdapter?: {
    load: (id: string) => Promise<any>
  }
}

export function SerializedContentRenderer({
  serializedState,
  className = "prose prose-stone dark:prose-invert max-w-none",
  projectId,
  storageAdapter,
}: SerializedContentRendererProps) {
  let headingCounter = 0

  // Validate serializedState structure
  if (!serializedState || !serializedState.root || !serializedState.root.children) {
    console.error("Invalid serializedState:", serializedState)
    return (
      <div className="p-8 text-center border border-red-200 bg-red-50 dark:border-red-700 dark:bg-red-900/20">
        <p className="text-red-600 dark:text-red-400 font-medium">
          Unable to render content: Invalid data structure
        </p>
        <p className="text-sm text-red-500 dark:text-red-500 mt-2">
          The editor state is missing required properties (root.children)
        </p>
      </div>
    )
  }

  const renderNode = (node: any, index = 0, parentPath = "") => {
    // Create unique key using path and index
    const uniqueKey = `${parentPath}-${node.type}-${index}-${node.version || 0}`

    // Handle quiz nodes
    if (node.type === "quiz") {
      return <PreviewQuiz key={uniqueKey} node={node} />
    }

    // Handle image nodes
    if (node.type === "image") {
      return <PreviewImage key={uniqueKey} node={node} />
    }

    // Handle gallery nodes
    if (node.type === "gallery") {
      return <PreviewGallery key={uniqueKey} node={node} />
    }

    // Handle markdown nodes
    if (node.type === "markdown") {
      return <PreviewMarkdown key={uniqueKey} node={node} />
    }

    // Handle HTML nodes
    if (node.type === "html") {
      return <PreviewHTML key={uniqueKey} node={node} />
    }

    // Handle Rich Text nodes
    if (node.type === "rich-text") {
      return <PreviewRichText key={uniqueKey} node={node} />
    }

    // Handle video nodes
    if (node.type === "video") {
      return <PreviewVideo key={uniqueKey} node={node} />
    }

    // Handle audio nodes
    if (node.type === "audio") {
      return <PreviewAudio key={uniqueKey} node={node} />
    }

    // Handle header nodes
    if (node.type === "header") {
      return <PreviewHeader key={uniqueKey} node={node} />
    }

    // Handle divider nodes
    if (node.type === "divider") {
      return <PreviewDivider key={uniqueKey} node={node} />
    }

    // Handle button nodes
    if (node.type === "button") {
      return <PreviewButton key={uniqueKey} node={node} />
    }

    // Handle admonition nodes
    if (node.type === "admonition") {
      return <PreviewAdmonition key={uniqueKey} node={node} />
    }

    // Handle source nodes
    if (node.type === "source") {
      return <PreviewSource key={uniqueKey} node={node} />
    }

    // For text content - now using the new component
    if (node.type === "text") {
      return <PreviewText key={uniqueKey} node={node} />
    }

    // For Mermaid diagrams
    if (node.type === "mermaid") {
      return <PreviewMermaid key={uniqueKey} data={node.data} />
    }

    // For Vega-Lite charts
    if (node.type === "vega-lite") {
      return <PreviewVegaLite key={uniqueKey} node={node} />
    }

    // For CodeStudio nodes
    if (node.type === "code-studio") {
      return <PreviewCodeStudio key={uniqueKey} data={node.data} projectId={projectId} />
    }

    // For Project nodes
    if (node.type === "project") {
      return <PreviewProject key={uniqueKey} node={node} storageAdapter={storageAdapter} />
    }

    if (node.children) {
      const children = node.children.map((child: any, childIndex: number) => renderNode(child, childIndex, uniqueKey))

      switch (node.type) {
        case "paragraph":
          return (
            <PreviewParagraph key={uniqueKey} node={node}>
              {children}
            </PreviewParagraph>
          )
        case "quote":
          return (
            <PreviewQuote key={uniqueKey} node={node}>
              {children}
            </PreviewQuote>
          )
        case "list":
        case "custom-list":
          return (
            <PreviewList key={uniqueKey} node={node}>
              {children}
            </PreviewList>
          )
        case "listitem":
          return (
            <PreviewListItem key={uniqueKey} node={node}>
              {children}
            </PreviewListItem>
          )
        case "link":
          return (
            <PreviewLink key={uniqueKey} node={node}>
              {children}
            </PreviewLink>
          )
        case "heading": {
          const currentHeadingIndex = headingCounter++
          console.log("[v0] Rendering heading with index:", currentHeadingIndex)
          return (
            <PreviewHeading key={uniqueKey} node={node} index={currentHeadingIndex}>
              {children}
            </PreviewHeading>
          )
        }
        default:
          return <div key={uniqueKey}>{children}</div>
      }
    }

    return null
  }

  return (
    <div className={className}>
      {serializedState.root.children.map((node: any, index: number) => renderNode(node, index, "root"))}
    </div>
  )
}

"use client"

import type React from "react"
import { useState } from "react"

import { FolderOpen } from "lucide-react"
import { DownloadConfirmDialog } from "@/components/block-content-editor/extras/dialogs/download-confirm-dialog"
import { ProjectGridView } from "./project-grid-view"
import { ProjectListView } from "./project-list-view"
import type { ProjectData } from "@/components/block-content-editor/lib/storage/editor/project-data"
import type { ProjectPreferences } from "@/components/block-content-editor/lib/storage/editor/project-preferences"

interface ProjectListProps {
  projects: ProjectData[]
  currentPage: number
  itemsPerPage: number
  searchTerm: string
  selectedTags: string[]
  viewMode?: 'grid' | 'list'
  gridColumns?: number
  listColumns?: number
  onOpen: (projectId: string, event?: React.MouseEvent) => void
  onView?: (projectId: string, event?: React.MouseEvent) => void
  onDelete?: (projectId: string, projectName: string) => void
  onInfo?: (project: ProjectData) => void
  onDownload?: (
    projectId: string,
    projectName: string,
    projectData: string,
    projectTags: string[],
    createdAt: string,
    updatedAt: string,
    projectPreferences?: ProjectPreferences
  ) => void
  showDeleteButton?: boolean
  showStudioViewerButtons?: boolean
  openButtonText?: string
  openButtonIcon?: React.ReactNode
}

export function ProjectList({
  projects,
  currentPage,
  itemsPerPage,
  searchTerm,
  selectedTags,
  viewMode = 'grid',
  gridColumns = 5,
  listColumns = 1,
  onOpen,
  onView,
  onDelete,
  onInfo,
  onDownload,
  showDeleteButton = true,
  showStudioViewerButtons = false,
  openButtonText = "Open",
  openButtonIcon,
}: ProjectListProps) {
  const [downloadDialog, setDownloadDialog] = useState<{
    open: boolean
    project: ProjectData | null
  }>({ open: false, project: null })

  // Format file size
  const formatSize = (sizeInKB: number): string => {
    if (sizeInKB < 1024) {
      return `${sizeInKB.toFixed(1)}KB`
    } else {
      return `${(sizeInKB / 1024).toFixed(1)}MB`
    }
  }

  const handleDownloadClick = (project: ProjectData) => {
    setDownloadDialog({ open: true, project })
  }

  const handleDownloadConfirm = async () => {
    if (downloadDialog.project) {
      if (onDownload) {
        // Call the provided onDownload function
        onDownload(
          downloadDialog.project.id,
          downloadDialog.project.name,
          downloadDialog.project.data,
          downloadDialog.project.tags,
          downloadDialog.project.metadata.createdAt,
          downloadDialog.project.metadata.updatedAt,
          downloadDialog.project.preferences
        )
      } else {
        // If no onDownload provided, implement download locally
        try {
          // Dynamic imports to avoid issues if these aren't available
          const [{ HashManager }, { ProjectExporter }] = await Promise.all([
            import("@/components/block-content-editor/lib/sync/editor/hash-manager"),
            import("@/components/block-content-editor/lib/interopAdapter/project-exporter")
          ])

          console.log('[Download] Starting download for project:', downloadDialog.project.id)

          // Generate hash for the project
          const hash = await HashManager.generateHash(downloadDialog.project.data)
          console.log('[Download] Generated hash:', hash)

          // Prepare project data for export using ProjectExporter
          const exportProjectData = {
            id: downloadDialog.project.id,
            name: downloadDialog.project.name,
            data: downloadDialog.project.data,
            tags: downloadDialog.project.tags,
            size: new Blob([downloadDialog.project.data]).size,
            createdAt: downloadDialog.project.metadata.createdAt,
            updatedAt: downloadDialog.project.metadata.updatedAt,
            hash: hash,
            storageType: "local" as const,
            preferences: downloadDialog.project.preferences
          }

          console.log('[Download] Export project data prepared:', {
            id: exportProjectData.id,
            name: exportProjectData.name,
            hasPreferences: !!exportProjectData.preferences
          })

          // Use ProjectExporter to create the ZIP file
          const zipBlob = await ProjectExporter.createZipFile(exportProjectData, hash)
          console.log('[Download] ZIP file created, size:', zipBlob.size)

          // Create download link
          const url = URL.createObjectURL(zipBlob)
          const link = document.createElement("a")
          link.href = url
          link.download = ProjectExporter.getDownloadFilename(exportProjectData)
          document.body.appendChild(link)
          link.click()

          console.log('[Download] Download initiated:', link.download)

          // Cleanup
          document.body.removeChild(link)
          URL.revokeObjectURL(url)
        } catch (error) {
          console.error("Download error:", error)
        }
      }
    }
    setDownloadDialog({ open: false, project: null })
  }

  const paginatedProjects = projects.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage)

  if (projects.length === 0) {
    return (
      <div className="max-h-[30vh] overflow-y-auto">
        <div className="text-center py-12">
          <FolderOpen className="w-12 h-12 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
          <p className="text-sm text-gray-500 dark:text-gray-400">
            {searchTerm || selectedTags.length > 0
              ? "No projects found matching your criteria"
              : "No saved projects found"}
          </p>
          <p className="text-xs text-gray-400 dark:text-gray-500 mt-1">
            {searchTerm || selectedTags.length > 0
              ? "Try adjusting your search or filters"
              : showDeleteButton
                ? "Create your first project to get started"
                : "Create projects in the editor first"}
          </p>
        </div>
      </div>
    )
  }

  const handleProjectDownload = (project: ProjectData) => {
    // Always show confirmation dialog first
    handleDownloadClick(project)
  }

  return (
    <>
      <div className="flex-1 min-h-0 overflow-y-auto p-1">
        {viewMode === 'grid' ? (
          <ProjectGridView
            projects={paginatedProjects}
            columns={gridColumns}
            onOpen={onOpen}
            onView={onView}
            onDelete={onDelete}
            onInfo={onInfo}
            onDownload={handleProjectDownload}
            showDeleteButton={showDeleteButton}
            showStudioViewerButtons={showStudioViewerButtons}
            openButtonText={openButtonText}
            openButtonIcon={openButtonIcon}
          />
        ) : (
          <ProjectListView
            projects={paginatedProjects}
            columns={listColumns}
            onOpen={onOpen}
            onView={onView}
            onDelete={onDelete}
            onInfo={onInfo}
            onDownload={handleProjectDownload}
            showDeleteButton={showDeleteButton}
            showStudioViewerButtons={showStudioViewerButtons}
            openButtonText={openButtonText}
            openButtonIcon={openButtonIcon}
          />
        )}
      </div>

      <DownloadConfirmDialog
        open={downloadDialog.open}
        onOpenChange={(open) => setDownloadDialog({ open, project: null })}
        fileName={`gg-lexical-editor-${downloadDialog.project?.name || "project"}.zip`}
        fileSize={formatSize(downloadDialog.project?.metadata.size || 0)}
        lastModified={downloadDialog.project ? new Date(downloadDialog.project.metadata.updatedAt).toLocaleDateString() : ""}
        onConfirm={handleDownloadConfirm}
        project={downloadDialog.project}
      />
    </>
  )
}

"use client"

import type React from "react"
import { useState } from "react"
import { toast } from "sonner"
import { Cloud } from "lucide-react"

import { Button } from "@game-guild/ui/components/button"
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@game-guild/ui/components/dialog"
import { useGoogleDriveAuth } from "@/components/block-content-editor/hooks/editor/use-google-drive-auth"
import { GoogleDriveAuthDialog } from "@/components/block-content-editor/extras/editor/google-drive-auth-dialog"

interface ProjectPickerShellProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  title: string
  description?: string
  trigger?: React.ReactElement
  /** Filters area (typically <ProjectSearchFilters />) */
  filters: React.ReactNode
  /** Main list area (typically <ProjectList />) */
  list: React.ReactNode
  /** Pagination area (typically <ProjectPagination />) */
  pagination: React.ReactNode
  /** Left-side footer actions */
  footerLeft?: React.ReactNode
  /** Right-side footer actions (always rendered) */
  footerRight: React.ReactNode
  /** Optional hook fired after a successful Google Drive connection */
  onAuthSuccess?: () => void
  /** Toast shown after auth */
  authSuccessToast?: { title: string; description: string }
}

/**
 * Shared chrome for project picker dialogs (Open Project / Open Project for Preview).
 * Houses the layout, header with Google Drive auth control, body slots and footer slots
 * so callers only need to provide the variable content.
 */
export function ProjectPickerShell({
  open,
  onOpenChange,
  title,
  description,
  trigger,
  filters,
  list,
  pagination,
  footerLeft,
  footerRight,
  onAuthSuccess,
  authSuccessToast,
}: ProjectPickerShellProps) {
  const [googleDriveAuthDialogOpen, setGoogleDriveAuthDialogOpen] = useState(false)
  const { isAuthenticated, isLoading, signOut, refreshAuthState } = useGoogleDriveAuth()

  return (
    <Dialog
      open={open}
      onOpenChange={(nextOpen, eventDetails) => {
        if (!nextOpen && eventDetails.reason === 'outside-press') {
          eventDetails.cancel()
          return
        }
        onOpenChange(nextOpen)
      }}
    >
      {trigger && <DialogTrigger render={trigger} />}

      <DialogContent
        className="max-w-2xl lg:max-w-4xl w-full h-[92vh] p-0 gap-0 flex flex-col overflow-hidden rounded-xl border-border/60 shadow-2xl"
      >
        {/* Header */}
        <DialogHeader className="shrink-0 border-b border-border/40 bg-muted/20 px-6 py-4">
          <div className="flex items-start justify-between gap-4">
            <div className="min-w-0">
              <DialogTitle className="text-lg font-semibold tracking-tight">{title}</DialogTitle>
              {description && (
                <p className="mt-0.5 text-sm text-muted-foreground">{description}</p>
              )}
            </div>

            {/* Google Drive Auth */}
            <div className="shrink-0">
              {isAuthenticated ? (
                <div className="flex items-center gap-2 rounded-full border border-emerald-500/30 bg-emerald-500/10 pl-3 pr-1 py-1">
                  <div className="flex items-center gap-1.5 text-xs font-medium text-emerald-600 dark:text-emerald-400">
                    <Cloud className="h-3.5 w-3.5" />
                    <span>Google Drive</span>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={signOut}
                    className="h-6 px-2 text-[11px] text-muted-foreground hover:text-red-600"
                    title="Disconnect Google Drive"
                  >
                    Disconnect
                  </Button>
                </div>
              ) : (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setGoogleDriveAuthDialogOpen(true)}
                  disabled={isLoading}
                  className="h-8 gap-1.5 rounded-full text-xs"
                  title="Connect to Google Drive to access your cloud projects"
                >
                  <Cloud className="h-3.5 w-3.5" />
                  {isLoading ? "Connecting…" : "Connect Google Drive"}
                </Button>
              )}
            </div>
          </div>
        </DialogHeader>

        {/* Body */}
        <div className="flex-1 min-h-0 flex flex-col gap-4 px-6 py-5">
          <div className="shrink-0">{filters}</div>

          <div className="flex-1 min-h-0 overflow-y-auto -mx-1 px-1">
            {list}
          </div>

          <div className="shrink-0 flex items-center justify-center pt-1">
            {pagination}
          </div>
        </div>

        {/* Footer */}
        <div className="shrink-0 border-t border-border/40 bg-muted/20 px-6 py-3.5 flex items-center justify-between gap-3">
          <div className="flex items-center gap-2">{footerLeft}</div>
          <div className="flex items-center gap-2">{footerRight}</div>
        </div>
      </DialogContent>

      <GoogleDriveAuthDialog
        open={googleDriveAuthDialogOpen}
        onOpenChange={setGoogleDriveAuthDialogOpen}
        onAuthSuccess={() => {
          setGoogleDriveAuthDialogOpen(false)
          refreshAuthState()
          onAuthSuccess?.()
          if (authSuccessToast) {
            toast.success(authSuccessToast.title, {
              description: authSuccessToast.description,
              duration: 3000,
              icon: "☁️",
            })
          }
        }}
      />
    </Dialog>
  )
}

"use client"

import { useState, useEffect } from "react"
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@game-guild/ui/components/dialog"
import { Button } from "@game-guild/ui/components/button"
import { Input } from "@game-guild/ui/components/input"
import { FileText, Search, X, HardDrive, Cloud, Database } from "lucide-react"
import { ScrollArea } from "@game-guild/ui/components/scroll-area"
import type { ProjectData } from "@/components/block-content-editor/lib/storage/editor/project-data"
import type { StorageType } from "@/components/block-content-editor/lib/storage/editor/storage-types"

interface SelectProjectDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onProjectSelect: (project: ProjectData) => void
  currentProjectId?: string
  storageAdapter: {
    list: () => Promise<ProjectData[]>
    searchProjects: (
      searchTerm: string,
      tags: string[],
      filterMode: "all" | "any",
      storageTypeFilter?: StorageType
    ) => Promise<ProjectData[]>
  }
}

export function SelectProjectDialog({
  open,
  onOpenChange,
  onProjectSelect,
  currentProjectId,
  storageAdapter,
}: SelectProjectDialogProps) {
  const [projects, setProjects] = useState<ProjectData[]>([])
  const [searchTerm, setSearchTerm] = useState("")
  const [loading, setLoading] = useState(false)
  const [selectedTags, setSelectedTags] = useState<string[]>([])

  const loadProjects = async () => {
    setLoading(true)
    try {
      let allProjects = await storageAdapter.list()
      
      // Exclude current project
      allProjects = allProjects.filter(
        (p) => p.id !== currentProjectId
      )

      // Apply search filter
      if (searchTerm) {
        allProjects = allProjects.filter((p) =>
          p.name.toLowerCase().includes(searchTerm.toLowerCase())
        )
      }

      // Sort by updated date (newest first)
      allProjects.sort((a, b) => new Date(b.metadata.updatedAt).getTime() - new Date(a.metadata.updatedAt).getTime())

      setProjects(allProjects)
    } catch (error) {
      console.error("Failed to load projects:", error)
    } finally {
      setLoading(false)
    }
  }

  // Load projects when dialog opens
  useEffect(() => {
    if (open) {
      loadProjects()
    }
  }, [open])

  // Format size
  const formatSize = (sizeInKB: number): string => {
    if (sizeInKB < 1024) {
      return `${sizeInKB.toFixed(1)}KB`
    } else {
      return `${(sizeInKB / 1024).toFixed(1)}MB`
    }
  }

  // Get storage icon
  const getStorageIcon = (storageType?: StorageType) => {
    switch (storageType) {
      case "gameguild-cloud":
        return <Database className="h-3 w-3" />
      case "google-drive":
        return <Cloud className="h-3 w-3" />
      default:
        return <HardDrive className="h-3 w-3" />
    }
  }

  // Get project type label
  const getTypeLabel = (): string => {
    return "Single Project"
  }

  const handleSelect = (project: ProjectData) => {
    onProjectSelect(project)
    onOpenChange(false)
  }

  const handleSearch = (value: string) => {
    setSearchTerm(value)
    // Debounce search
    setTimeout(() => {
      loadProjects()
    }, 300)
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-3xl max-h-[80vh]">
        <DialogHeader>
          <DialogTitle>Import Project</DialogTitle>
          <DialogDescription>
            Select a project to import. You can edit imported projects, which will create a local copy.
          </DialogDescription>
        </DialogHeader>

        {/* Search bar */}
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
          <Input
            placeholder="Search projects by name..."
            value={searchTerm}
            onChange={(e) => handleSearch(e.target.value)}
            className="pl-10 pr-10"
          />
          {searchTerm && (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => {
                setSearchTerm("")
                loadProjects()
              }}
              className="absolute right-1 top-1/2 -translate-y-1/2 h-8 w-8 p-0"
            >
              <X className="h-4 w-4" />
            </Button>
          )}
        </div>

        {/* Filter info */}
        <div className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400">
          <span>Showing: Single Projects</span>
        </div>

        {/* Projects list */}
        <ScrollArea className="h-[400px] pr-4">
          {loading ? (
            <div className="flex items-center justify-center h-32">
              <div className="text-sm text-gray-500">Loading projects...</div>
            </div>
          ) : projects.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-32 text-center">
              <FileText className="h-12 w-12 text-gray-400 mb-2" />
              <div className="text-sm text-gray-500">No projects found</div>
              <div className="text-xs text-gray-400 mt-1">
                {searchTerm
                  ? "Try adjusting your search"
                  : "Create a project to import"}
              </div>
            </div>
          ) : (
            <div className="space-y-2">
              {projects.map((project) => (
                <div
                  key={project.id}
                  onClick={() => handleSelect(project)}
                  className="p-4 border border-gray-200 dark:border-gray-700 rounded-lg hover:border-blue-500 dark:hover:border-blue-500 hover:bg-blue-50/50 dark:hover:bg-blue-950/20 cursor-pointer transition-all group"
                >
                  <div className="flex items-start justify-between gap-4">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <FileText className="h-4 w-4 text-blue-600 dark:text-blue-400 shrink-0" />
                        <span className="font-semibold text-gray-900 dark:text-gray-100 truncate">
                          {project.name}
                        </span>
                      </div>

                      <div className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400 flex-wrap">
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded bg-gray-100 dark:bg-gray-800">
                          {getTypeLabel()}
                        </span>
                        <span className="inline-flex items-center gap-1">
                          {getStorageIcon(project.storageType)}
                          {project.storageType || "local"}
                        </span>
                        <span>•</span>
                        <span>{formatSize(project.metadata.size)}</span>
                        <span>•</span>
                        <span>{new Date(project.metadata.updatedAt).toLocaleDateString()}</span>
                      </div>

                      {project.tags && project.tags.length > 0 && (
                        <div className="flex flex-wrap gap-1 mt-2">
                          {project.tags.slice(0, 3).map((tag) => (
                            <span
                              key={tag}
                              className="inline-flex items-center px-2 py-0.5 text-xs rounded bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300"
                            >
                              {tag}
                            </span>
                          ))}
                          {project.tags.length > 3 && (
                            <span className="text-xs text-gray-500">+{project.tags.length - 3}</span>
                          )}
                        </div>
                      )}
                    </div>

                    <Button
                      variant="ghost"
                      size="sm"
                      className="opacity-0 group-hover:opacity-100 transition-opacity"
                    >
                      Import
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </ScrollArea>

        {/* Footer */}
        <div className="flex justify-between items-center pt-4 border-t">
          <div className="text-xs text-gray-500">
            {projects.length} project{projects.length !== 1 ? "s" : ""} available
          </div>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  )
}

