"use client"

/**
 * Inline editable rich-text editor used directly inside a block card —
 * no modal. Thin wrapper around the unified `<LexicalSurface />`.
 *
 * Top toolbar is hidden because this editor lives inside a constrained
 * block card; bubble toolbars cover the formatting needs.
 */

import { useCallback, useEffect, useRef, useState } from "react"
import type { LexicalEditor, SerializedEditorState } from "lexical"

import { LexicalSurface } from "@game-guild/lexical-surface"
import type { RichTextData } from "../../nodes/rich-text-node"

interface InlineRichTextEditorProps {
  data: RichTextData | undefined
  onChange: (data: RichTextData) => void
  readOnly?: boolean
}

export function InlineRichTextEditor({ data, onChange, readOnly = false }: InlineRichTextEditorProps) {
  const onChangeRef = useRef(onChange)
  onChangeRef.current = onChange
  const titleRef = useRef<string | undefined>(data?.title)
  titleRef.current = data?.title

  const lastEmittedRef = useRef<SerializedEditorState | null | undefined>(data?.content)
  const [mountKey, setMountKey] = useState(0)
  const seededContentRef = useRef<SerializedEditorState | null | undefined>(data?.content)

  useEffect(() => {
    const incoming = data?.content
    if (incoming !== lastEmittedRef.current) {
      seededContentRef.current = incoming
      lastEmittedRef.current = incoming
      setMountKey((k) => k + 1)
    }
  }, [data?.content])

  const handleChange = useCallback((serialized: SerializedEditorState, _editor: LexicalEditor) => {
    lastEmittedRef.current = serialized
    onChangeRef.current({
      content: serialized,
      title: titleRef.current,
    })
  }, [])

  return (
    <LexicalSurface
      namespace="InlineRichTextEditor"
      mountKey={mountKey}
      readOnly={readOnly}
      initialState={seededContentRef.current ?? null}
      onChange={handleChange}
      placeholder="Start writing…"
      contentClassName="min-h-[80px]"
      features={{ toolbar: false, pageLayout: false }}
    />
  )
}

"use client"

/**
 * Modal Rich Text Editor — opens in `BlockEditorShell` and saves on
 * confirm. Thin wrapper around `<LexicalSurface />` with full feature set.
 */

import { useCallback, useMemo, useRef, useState } from "react"
import type { LexicalEditor, SerializedEditorState } from "lexical"
import { FileText, Save } from "lucide-react"

import { Button } from "@game-guild/ui/components/button"
import { Input } from "@game-guild/ui/components/input"
import { Label } from "@game-guild/ui/components/label"
import { LexicalSurface } from "@game-guild/lexical-surface"
import { useEditorSettings } from "@/components/block-content-editor/extras/settings-menu"
import { BlockEditorShell } from "@/components/block-content-editor/extras/block-editor-shell"
import type { RichTextData } from "../../nodes/rich-text-node"

interface RichTextEditorProps {
  initialData?: RichTextData
  onSave: (data: RichTextData) => void
  onCancel: () => void
}

export function RichTextEditor({ initialData, onSave, onCancel }: RichTextEditorProps) {
  const [title, setTitle] = useState(initialData?.title ?? "")
  const editorStateRef = useRef<SerializedEditorState | null>(initialData?.content ?? null)
  const settings = useEditorSettings("rich-text")

  const handleChange = useCallback((serialized: SerializedEditorState, _editor: LexicalEditor) => {
    editorStateRef.current = serialized
  }, [])

  const handleSave = useCallback(() => {
    onSave({
      content: editorStateRef.current,
      title: title || undefined,
    })
  }, [onSave, title])

  const initialState = useMemo(() => initialData?.content ?? null, [initialData])

  return (
    <BlockEditorShell
      settings={settings}
      includeMonacoTheme={false}
      onClose={onCancel}
      icon={<FileText className="h-5 w-5 text-blue-600 dark:text-blue-400" />}
      title="Rich Text Editor"
      headerActions={
        <div className="flex items-center gap-2">
          <Label htmlFor="rt-title" className="text-sm text-gray-600 dark:text-gray-400 whitespace-nowrap">
            Title
          </Label>
          <Input
            id="rt-title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Section title (optional)"
            className="h-8 w-48 text-sm"
          />
        </div>
      }
      footer={
        <div className="flex gap-2 justify-end">
          <Button
            variant="outline"
            onClick={onCancel}
            className="border-gray-300 dark:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-800 bg-transparent"
          >
            Cancel
          </Button>
          <Button
            onClick={handleSave}
            className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 dark:bg-blue-500 dark:hover:bg-blue-600"
          >
            <Save className="h-4 w-4" />
            Save
          </Button>
        </div>
      }
    >
      <div className="flex-1 overflow-auto bg-gray-50 dark:bg-gray-950">
        <div className="w-full max-w-5xl mx-auto flex flex-col bg-white dark:bg-gray-900 border-x border-gray-200 dark:border-gray-800 shadow-sm min-h-full">
          <LexicalSurface
            namespace="RichTextEditor"
            initialState={initialState}
            onChange={handleChange}
            placeholder="Start writing your rich text content..."
            contentClassName="min-h-[400px] max-w-none"
            className="flex-1 flex flex-col"
          />
        </div>
      </div>
    </BlockEditorShell>
  )
}

"use client"

/**
 * Read-only renderer for persisted `SerializedEditorState` content.
 * Thin wrapper around `<LexicalSurface />` in read-only mode.
 */

import { useMemo } from "react"
import type { SerializedEditorState } from "lexical"

import { LexicalSurface, stripSelection } from "@game-guild/lexical-surface"

interface RichTextPreviewRendererProps {
  content: SerializedEditorState | null | undefined
  className?: string
}

export function RichTextPreviewRenderer({ content, className }: RichTextPreviewRendererProps) {
  const sanitizedContent = useMemo(() => stripSelection(content), [content])
  const mountKey = useMemo(
    () => (sanitizedContent ? Math.random().toString(36).slice(2) : "empty"),
    [sanitizedContent],
  )

  if (!content) return null

  return (
    <LexicalSurface
      namespace="RichTextPreview"
      mountKey={mountKey}
      readOnly
      initialState={sanitizedContent}
      contentClassName={className || "text-sm text-foreground"}
    />
  )
}

"use client"

import { Label } from "@game-guild/ui/components/label"
import { Maximize2 } from "lucide-react"
import { 
  ModalSize, 
  getEditorPreferences, 
  setNodeTypePreference,
  MODAL_SIZE_LABELS 
} from "@/components/block-content-editor/lib/storage/editor/editor-preferences"
import { useState, useEffect, useRef } from "react"

interface SystemSettingsProps {
  nodeType?: string
  onModalSizeChange?: (size: ModalSize) => void
}

export function SystemSettings({ nodeType = 'code-studio', onModalSizeChange }: SystemSettingsProps) {
  const [modalSize, setModalSize] = useState<ModalSize>('widescreen')
  const [isLoading, setIsLoading] = useState(true)
  const timeoutRef = useRef<NodeJS.Timeout | null>(null)
  
  useEffect(() => {
    // Load preferences whenever component mounts
    const loadPreferences = async () => {
      setIsLoading(true)
      
      // Get current modal size (node-specific or fallback to global)
      const prefs = await getEditorPreferences(nodeType)
      setModalSize(prefs.modalSize)
      
      setIsLoading(false)
    }
    
    loadPreferences()
  }, [nodeType])
  
  useEffect(() => {
    // Cleanup timeout on unmount
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current)
      }
    }
  }, [])
  
  const handleModalSizeChange = async (size: ModalSize) => {
    setModalSize(size)
    
    // Clear previous timeout
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current)
    }
    
    // Delay actual save and notification by 250ms
    timeoutRef.current = setTimeout(async () => {
      // Always save as node-specific (code-studio only)
      await setNodeTypePreference(nodeType, 'modalSize', size)
      
      // Notify parent component after delay
      onModalSizeChange?.(size)
    }, 250)
  }
  
  if (isLoading) {
    return <div className="text-sm text-gray-500">Loading...</div>
  }
  
  return (
    <>
      {/* Modal Size */}
      <div className="space-y-3">
        <div className="flex items-center gap-2">
          <Maximize2 className="h-4 w-4 text-orange-500" />
          <Label className="text-sm font-medium">
            Modal Size: {MODAL_SIZE_LABELS[modalSize]}
          </Label>
        </div>
        
        <div className="space-y-2">
          <input
            type="range"
            min="0"
            max="3"
            step="1"
            value={['compact', 'widescreen', 'ultrawide', 'fullscreen'].indexOf(modalSize)}
            onChange={(e) => {
              const sizes: ModalSize[] = ['compact', 'widescreen', 'ultrawide', 'fullscreen']
              const selectedSize = sizes[parseInt(e.target.value)]
              if (selectedSize) {
                handleModalSizeChange(selectedSize)
              }
            }}
            className="w-full h-2 bg-gray-200 dark:bg-gray-700 rounded-lg appearance-none cursor-pointer accent-orange-500"
            style={{
              background: `linear-gradient(to right, 
                rgb(249, 115, 22) 0%, 
                rgb(249, 115, 22) ${(['compact', 'widescreen', 'ultrawide', 'fullscreen'].indexOf(modalSize) / 3) * 100}%, 
                rgb(229, 231, 235) ${(['compact', 'widescreen', 'ultrawide', 'fullscreen'].indexOf(modalSize) / 3) * 100}%, 
                rgb(229, 231, 235) 100%)`
            }}
          />
          <div className="flex justify-between text-xs text-gray-500 dark:text-gray-400 px-1">
            <span>Compact</span>
            <span>Wide</span>
            <span>Ultra</span>
            <span>Full</span>
          </div>
        </div>
      </div>
    </>
  )
}

"use client"

import { useState, useEffect, useCallback } from "react"
import {
  type ModalSize,
  type AllPreferences,
  type MonacoOptionsPreferences,
  getModalSizeClasses,
  getAllPreferences,
  setGlobalPreference,
  setNodeTypePreference,
  clearNodeTypePreference,
  setMonacoOption,
  subscribeToPreferences,
} from "@/components/block-content-editor/lib/storage/editor/editor-preferences"

/**
 * Scope of a preference write. Only `modalSize` exposes a nodeType-
 * specific override (existing System tab behaviour). All Monaco-surface
 * options (`editor`, `preview`) are always global so the user gets a
 * single, formalized experience across the document.
 */
export type PreferenceScope = "global" | "nodeType"

export interface EditorSettings {
  nodeType: string
  showSettingsMenu: boolean
  setShowSettingsMenu: (show: boolean) => void

  // Modal size (resolved with nodeType override)
  modalSize: ModalSize | null
  modalSizeIsOverride: boolean
  setModalSize: (size: ModalSize, scope?: PreferenceScope) => Promise<void>
  clearModalSizeOverride: () => Promise<void>

  /** Inner panel sizing classes for the selected modal size. */
  modalClassName: string
  /** Outer overlay sizing classes for the selected modal size. */
  containerClassName: string

  /**
   * Global Monaco options applied to every editable surface (code-studio
   * secondary displays, html, markdown, mermaid, vega-lite, …). `null`
   * while preferences are still hydrating from IndexedDB.
   */
  editor: MonacoOptionsPreferences | null
  /**
   * Global Monaco options applied to read-only previews and to the
   * code-studio "base" display (what students see).
   */
  preview: MonacoOptionsPreferences | null

  /** Update a single key inside the global `editor` options group. */
  setEditorOption: <K extends keyof MonacoOptionsPreferences>(
    key: K,
    value: MonacoOptionsPreferences[K],
  ) => Promise<void>
  /** Update a single key inside the global `preview` options group. */
  setPreviewOption: <K extends keyof MonacoOptionsPreferences>(
    key: K,
    value: MonacoOptionsPreferences[K],
  ) => Promise<void>
}

export function useEditorSettings(nodeType: string): EditorSettings {
  const [showSettingsMenu, setShowSettingsMenu] = useState(false)
  const [prefs, setPrefs] = useState<AllPreferences | null>(null)

  // Hydrate preferences and re-hydrate whenever any editor in the app
  // writes a new value (cross-editor reactivity).
  useEffect(() => {
    let cancelled = false
    const load = () => {
      getAllPreferences().then((all) => {
        if (!cancelled) setPrefs(all)
      })
    }
    load()
    const unsubscribe = subscribeToPreferences(load)
    return () => {
      cancelled = true
      unsubscribe()
    }
  }, [nodeType])

  // Close settings menu on click outside
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      const target = e.target as HTMLElement
      if (showSettingsMenu && !target.closest('.settings-menu-container')) {
        setShowSettingsMenu(false)
      }
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [showSettingsMenu])

  // Modal size resolves with nodeType override; Monaco options are global-only.
  const modalSizeOverride = prefs?.nodeTypes[nodeType]?.modalSize
  const modalSize: ModalSize | null = prefs
    ? (modalSizeOverride ?? prefs.global.modalSize)
    : null
  const modalSizeIsOverride = modalSizeOverride !== undefined

  const editor: MonacoOptionsPreferences | null = prefs ? prefs.global.editor : null
  const preview: MonacoOptionsPreferences | null = prefs ? prefs.global.preview : null

  const modalClasses = modalSize ? getModalSizeClasses(modalSize) : null
  const modalClassName = modalClasses?.modal ?? 'w-full max-w-7xl h-[90vh]'
  const containerClassName = modalClasses?.container ?? 'p-4'

  const setModalSize = useCallback(
    async (size: ModalSize, scope: PreferenceScope = "nodeType") => {
      if (scope === "global") {
        await setGlobalPreference("modalSize", size)
      } else {
        await setNodeTypePreference(nodeType, "modalSize", size)
      }
    },
    [nodeType],
  )

  const clearModalSizeOverride = useCallback(
    async () => {
      await clearNodeTypePreference(nodeType, "modalSize")
    },
    [nodeType],
  )

  const setEditorOption = useCallback(
    async <K extends keyof MonacoOptionsPreferences>(key: K, value: MonacoOptionsPreferences[K]) => {
      await setMonacoOption('editor', key, value)
    },
    [],
  )

  const setPreviewOption = useCallback(
    async <K extends keyof MonacoOptionsPreferences>(key: K, value: MonacoOptionsPreferences[K]) => {
      await setMonacoOption('preview', key, value)
    },
    [],
  )

  return {
    nodeType,
    showSettingsMenu,
    setShowSettingsMenu,
    modalSize,
    modalSizeIsOverride,
    setModalSize,
    clearModalSizeOverride,
    modalClassName,
    containerClassName,
    editor,
    preview,
    setEditorOption,
    setPreviewOption,
  }
}

"use client"

import { useState, useEffect } from "react"
import type { editor } from "monaco-editor"
import { CSyntaxHighlighter } from "./c-syntax-highlighter"
import { CTypeChecker } from "./c-type-checker"
import { CCompletionProvider } from "./c-completion-provider"

interface CLanguageServiceProps {
  monaco: typeof import("monaco-editor") | null
  editor: editor.IStandaloneCodeEditor | null
  code: string
  enabled: boolean
}

export function CLanguageService({ monaco, editor, code, enabled }: CLanguageServiceProps) {
  const [editorInstance, setEditorInstance] = useState<editor.IStandaloneCodeEditor | null>(null)
  const [monacoInstance, setMonacoInstance] = useState<typeof import("monaco-editor") | null>(null)

  useEffect(() => {
    if (monaco && editor && enabled) {
      setEditorInstance(editor)
      setMonacoInstance(monaco)
    }
  }, [monaco, editor, enabled])

  if (!enabled || !editorInstance || !monacoInstance) {
    return null
  }

  return (
    <>
      <CSyntaxHighlighter monaco={monacoInstance} editor={editorInstance} />
      <CTypeChecker monaco={monacoInstance} editor={editorInstance} code={code} />
      <CCompletionProvider monaco={monacoInstance} editor={editorInstance} />
    </>
  )
}

"use client"

import type { editor } from "monaco-editor"
import { useEffect, useState } from "react"

interface CTypeCheckerProps {
  monaco: typeof import("monaco-editor") | null
  editor: editor.IStandaloneCodeEditor | null
  code: string
}

interface TypeError {
  line: number
  column: number
  message: string
  severity: "error" | "warning" | "info"
}

export function CTypeChecker({ monaco, editor, code }: CTypeCheckerProps) {
  const [errors, setErrors] = useState<TypeError[]>([])

  useEffect(() => {
    if (!monaco || !editor) return

    // Create a marker collection for C type errors
    const model = editor.getModel()
    if (!model) return

    // Simple C type checking
    const cTypeCheck = (code: string): TypeError[] => {
      const errors: TypeError[] = []
      const lines = code.split("\n")

      // Track variable declarations and their types
      const variables: Record<string, string> = {}

      // Track function declarations and their return types
      const functions: Record<string, string> = {}

      // Track if we're inside a function, struct, or enum
      let inFunction = false
      let inStruct = false
      let inEnum = false

      // Track braces for block scope
      let braceCount = 0

      // Track preprocessor #if/#ifdef/#ifndef state
      let inPreprocessorIf = false

      lines.forEach((line, lineIndex) => {
        // Skip comments
        if (line.trim().startsWith("//") || line.trim().startsWith("/*")) {
          return
        }

        // Check for missing semicolons
        if (
          !line.trim().endsWith(";") &&
          !line.trim().endsWith("{") &&
          !line.trim().endsWith("}") &&
          !line.trim().startsWith("#") &&
          line.trim() !== "" &&
          !line.trim().endsWith(":") && // For labels
          !line.includes("//") && // Line with comments
          !inPreprocessorIf
        ) {
          // Check if it's not a function declaration or control structure
          if (
            !line.includes("if") &&
            !line.includes("for") &&
            !line.includes("while") &&
            !line.includes("switch") &&
            !line.includes("else") &&
            !line.includes("do")
          ) {
            errors.push({
              line: lineIndex + 1,
              column: line.length,
              message: "Missing semicolon",
              severity: "warning",
            })
          }
        }

        // Check for preprocessor directives
        if (line.trim().startsWith("#")) {
          const directive = line.trim().substring(1).trim().split(" ")[0]

          if (directive === "if" || directive === "ifdef" || directive === "ifndef") {
            inPreprocessorIf = true
          } else if (directive === "endif") {
            inPreprocessorIf = false
          }

          // Check for common preprocessor errors
          if (directive === "include") {
            const includePattern = /#include\s+[<"]([^>"]+)[>"]/
            const match = line.match(includePattern)

            if (!match) {
              errors.push({
                line: lineIndex + 1,
                column: line.indexOf("include") + 7,
                message: "Invalid #include directive",
                severity: "error",
              })
            }
          }

          return
        }

        // Track braces
        const openBraces = (line.match(/{/g) || []).length
        const closeBraces = (line.match(/}/g) ?? []).length
        braceCount += openBraces - closeBraces

        // Check for variable declarations
        const varDeclarationRegex =
          /\b(int|char|float|double|void|long|short|unsigned|signed|struct|enum|union|bool)\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*(\[\s*[a-zA-Z0-9_]*\s*\])?\s*(=|;|\(|,)/
        const varMatch = line.match(varDeclarationRegex)

        if (varMatch && !line.includes("(")) {
          const varType = varMatch[1] ?? ''
          const varName = varMatch[2]
          if (varName) {
            variables[varName] = varType
          }
        }

        // Check for function declarations
        const funcDeclarationRegex =
          /\b(int|char|float|double|void|long|short|unsigned|signed|struct|enum|union|bool)\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/
        const funcMatch = line.match(funcDeclarationRegex)

        if (funcMatch) {
          const returnType = funcMatch[1] ?? ''
          const funcName = funcMatch[2]
          if (funcName) {
            functions[funcName] = returnType
          }

          if (line.includes("{")) {
            inFunction = true
          }
        }

        // Check for struct declarations
        if (line.includes("struct") && line.includes("{")) {
          inStruct = true
        }

        // Check for enum declarations
        if (line.includes("enum") && line.includes("{")) {
          inEnum = true
        }

        // Check for closing braces that end functions, structs, or enums
        if (line.includes("}")) {
          if (inFunction && braceCount === 0) {
            inFunction = false
          }
          if (inStruct && braceCount === 0) {
            inStruct = false
          }
          if (inEnum && braceCount === 0) {
            inEnum = false
          }
        }

        // Check for common C errors

        // 1. Using = instead of == in conditions
        if (
          (line.includes("if") || line.includes("while")) &&
          line.includes("(") &&
          !line.includes("==") &&
          line.includes("=")
        ) {
          errors.push({
            line: lineIndex + 1,
            column: line.indexOf("="),
            message: "Assignment in condition. Did you mean == ?",
            severity: "warning",
          })
        }

        // 2. Missing return statement in non-void functions
        if (inFunction && line.includes("}") && braceCount === 0) {
          // Check if the function has a return type other than void
          const funcName = Object.keys(functions).find((name) => functions[name] !== "void")
          if (funcName && !code.includes("return")) {
            errors.push({
              line: lineIndex + 1,
              column: 0,
              message: `Function '${funcName}' has non-void return type but no return statement`,
              severity: "warning",
            })
          }
        }

        // 3. Potential null pointer dereference
        if (line.includes("->") || line.includes("*")) {
          const pointerRegex = /([a-zA-Z_][a-zA-Z0-9_]*)\s*->/
          const pointerMatch = line.match(pointerRegex)

          if (pointerMatch) {
            const pointerName = pointerMatch[1]
            if (line.includes(`${pointerName} = NULL`) || line.includes(`${pointerName} = 0`)) {
              errors.push({
                line: lineIndex + 1,
                column: line.indexOf("->"),
                message: "Potential null pointer dereference",
                severity: "warning",
              })
            }
          }
        }

        // 4. Array index out of bounds (simple cases)
        const arrayAccessRegex = /([a-zA-Z_][a-zA-Z0-9_]*)\[([^\]]+)\]/g
        let arrayMatch

        while ((arrayMatch = arrayAccessRegex.exec(line)) !== null) {
          const arrayName = arrayMatch[1] ?? ''
          const indexExpr = arrayMatch[2] ?? ''

          // Check for negative indices
          if (indexExpr.includes("-") || indexExpr === "0-1") {
            errors.push({
              line: lineIndex + 1,
              column: arrayMatch.index + arrayName.length + 1,
              message: "Potential negative array index",
              severity: "warning",
            })
          }

          // Check for constant indices that might be out of bounds
          if (/^\d+$/.test(indexExpr)) {
            const index = Number.parseInt(indexExpr, 10)
            if (index < 0) {
              errors.push({
                line: lineIndex + 1,
                column: arrayMatch.index + arrayName.length + 1,
                message: "Negative array index",
                severity: "error",
              })
            }
          }
        }
      })

      // Check for unbalanced braces
      if (braceCount !== 0) {
        const lastLine = lines[lines.length - 1] ?? ""
        errors.push({
          line: lines.length,
          column: lastLine.length,
          message: braceCount > 0 ? "Missing closing brace(s)" : "Extra closing brace(s)",
          severity: "error",
        })
      }

      return errors
    }

    // Run type checking
    const typeErrors = cTypeCheck(code)
    setErrors(typeErrors)

    // Set markers in the editor
    const markers = typeErrors.map((error) => ({
      startLineNumber: error.line,
      startColumn: error.column,
      endLineNumber: error.line,
      endColumn: error.column + 1,
      message: error.message,
      severity:
        error.severity === "error"
          ? monaco.MarkerSeverity.Error
          : error.severity === "warning"
            ? monaco.MarkerSeverity.Warning
            : monaco.MarkerSeverity.Info,
    }))

    monaco.editor.setModelMarkers(model, "c-type-checker", markers)

    return () => {
      // Clear markers when component unmounts
      if (model) {
        monaco.editor.setModelMarkers(model, "c-type-checker", [])
      }
    }
  }, [monaco, editor, code])

  return null
}

