  codeEditorHeight,
  terminalHeight,
  handleCodeEditorResize,
  handleTerminalResize,
  handleEditorMount,
  updateActiveFileContent,
  isFileReadOnly,
  toggleFileVisibility,
  setMainFile,
  deleteFile,
  setFileReadOnlyState,
  reorderFiles,
  showFileDialog,
  showRenameDialog,
  showImportDialog,
  showConfirmDialog,
  showLanguagesDialog,
  getBaseName,
  getExtensionForSelectedLanguage,
  getAllowedProgrammingLanguages,
