  getStateIcon,
  draggedFileId,
  setDraggedFileId,
  dragOverFileId,
  setDragOverFileId,
  showBasicFileActionsInReadMode,
  showFilePropertiesInReadMode,
  setShowBasicFileActionsInReadMode,
  setShowFilePropertiesInReadMode,
  isExecuting,
  output,
  input,
  setInput,
  waitingForInput,
  inputPrompt,
  handleTerminalInput,
  handleExecute,
  handleStopExecution,
  clearTerminalOnRun,
