      // Execute the code with proper error handling
      await executor.execute(fileId, context)
    } catch (error) {
      console.error(`Test execution error:`, error)
      const errorMessage = error instanceof Error ? error.message : String(error)
      addOutput(`Error: ${errorMessage}`)
      testOutputLines.push(`Error: ${errorMessage}`)
    }

    // Get the captured output
    const actualOutput = testOutputLines.join("\n")

    // Normalize both outputs for comparison (trim whitespace, etc.)
    const normalizedActual = normalizeOutput(actualOutput)
    const normalizedExpected = normalizeOutput(testCase?.expectedOutput || "")

    // Compare output with expected output
    const passed = normalizedActual === normalizedExpected

    // Update test results
    setTestResults((prev) => {
      const fileResults = [...(prev[fileId] || [])]
      fileResults[i] = {
        passed,
        actual: actualOutput,
        expected: testCase?.expectedOutput || "",
      }
      return {
        ...prev,
        [fileId]: fileResults,
      }
    })

    // Add test result to terminal output
    addOutput(`[Test ${i + 1}] ${passed ? "✓ Passed" : "✗ Failed"}`)
  }
}

/**
 * Deep equality comparison for objects and arrays
 */
export function deepEqual(a: any, b: any): boolean {
  if (a === b) return true

  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false
    }
    return true
  }

  if (typeof a === "object" && a !== null && typeof b === "object" && b !== null) {
    const keysA = Object.keys(a)
    const keysB = Object.keys(b)

    if (keysA.length !== keysB.length) return false

    for (const key of keysA) {
      if (!keysB.includes(key)) return false
      if (!deepEqual(a[key], b[key])) return false
    }

    return true
  }

  return false
}

"use client"

import type React from "react"

import type { CodeFile, ProgrammingLanguage } from "@/components/block-content-editor/extras/source-code/types"
import { useCallback, useState } from "react"
import { getExecutor } from "./executors/executor-factory"
import type { ExecutionContext } from "./executors/types"

interface UseCodeExecutionOptions {
  files: CodeFile[]
  selectedLanguage: ProgrammingLanguage
  clearTerminalOnRun: boolean
  addOutput: (output: string | string[]) => void
  clearTerminal: () => void
  testCases?: any[]
  setTestResults?: (results: Record<string, { passed: boolean; actual: string; expected: string }[]>) => void
}

export function useCodeExecution(options: UseCodeExecutionOptions) {
  const { files, selectedLanguage, clearTerminalOnRun, addOutput, clearTerminal } = options
  const [isExecuting, setIsExecuting] = useState(false)
  const [capturedOutput, setCapturedOutput] = useState<string[]>([])
  const [isCapturingOutput, setIsCapturingOutput] = useState(false)
  const [currentTestFileId, setCurrentTestFileId] = useState<string | null>(null)
  const [currentTestIndex, setCurrentTestIndex] = useState<number>(-1)
  const [output, setOutput] = useState<string[]>([])
  const [input, setInput] = useState<string>("")

  // Handle terminal commands
  const handleTerminalCommand = useCallback(
    (command: string): boolean => {
      if (command.toLowerCase() === "clear") {
        clearTerminal()
        return true
      }

      // Get the appropriate executor for the selected language
      const executor = getExecutor(selectedLanguage)

      // If the executor has a command handler, use it
      if (executor.handleCommand) {
        const context: ExecutionContext = {
          files,
          selectedLanguage,
          addOutput,
          clearTerminal,
          setIsExecuting,
        }

        return executor.handleCommand(command, context)
      }

      // Default command handling
      if (command.toLowerCase().includes("help")) {
        addOutput("Available commands: help, clear, echo [text]")
        return true
      } else if (command.toLowerCase().startsWith("echo ")) {
        addOutput(command.substring(5))
        return true
      }

      return false
    },
    [selectedLanguage, addOutput, clearTerminal, files, setIsExecuting],
  )

  // Stop execution
  const handleStopExecution = useCallback(() => {
    // Stop any ongoing execution
    const executor = getExecutor(selectedLanguage)

    // Check if the executor has a stop method before calling it
    if (executor && typeof executor.stop === "function") {
      executor.stop()
    } else {
      console.warn(`Executor for ${selectedLanguage} does not have a stop method`)
    }

    setIsExecuting(false)
    addOutput("Execution stopped by user.")

    // Reset test execution state
    setIsCapturingOutput(false)
    setCapturedOutput([])
    setCurrentTestFileId(null)
    setCurrentTestIndex(-1)

    // Reset callbacks
    window.promptCallback = () => { }
    window.confirmCallback = () => { }
    window.alertCallback = () => { }
  }, [addOutput, selectedLanguage])

  // Execute code
  const handleExecute = useCallback(
    async (activeFileId: string) => {
      // If already executing, don't start another execution
      if (isExecuting) return

      // Clear terminal if the option is enabled, otherwise just add a separator
      if (clearTerminalOnRun) {
        clearTerminal()
      } else {
        // Add a separator line instead of clearing the output
        addOutput("--- New Execution ---")
      }

      // Reset global callbacks
      window.promptCallback = () => { }
      window.confirmCallback = () => { }
      window.alertCallback = () => { }

      // Get the appropriate executor for the selected language
      const executor = getExecutor(selectedLanguage)

      // Create execution context
      const context: ExecutionContext = {
        files,
        selectedLanguage,
        addOutput,
        clearTerminal,
        setIsExecuting,
      }

      // Check if the language is compiled
      if (executor.isCompiled) {
        addOutput(`Executing ${selectedLanguage.toUpperCase()} code (compiled language)...`)
      } else {
        addOutput(`Executing ${selectedLanguage.toUpperCase()} code (interpreted language)...`)
      }

      // Execute the code
      await executor.execute(activeFileId, context)
    },
    [isExecuting, clearTerminalOnRun, clearTerminal, addOutput, files, selectedLanguage],
  )

  const getExecutorForLanguage = (language: ProgrammingLanguage) => {
    return getExecutor(language)
  }

  const handleTerminalInput = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      e.preventDefault()

      // Check if we're waiting for alert acknowledgment
      if (window.__awaitingAlertAck && window.alertCallback) {
        // Call the alert callback to acknowledge the alert
        window.alertCallback()
        addOutput(`> OK`)
        setInput("")
        return
      }

      // Check if we're waiting for prompt input
      if (window.__awaitingPromptInput && window.promptCallback) {
        // Call the prompt callback with the input value
        window.promptCallback(input)
        addOutput(`> ${input}`)
        setInput("")
        return
      }

      // Check if we're waiting for confirm input
      if (window.__awaitingConfirmInput && window.confirmCallback) {
        // Call the confirm callback with the input value
        window.confirmCallback(input)
        addOutput(`> ${input}`)
        setInput("")
        return
      }

      // Handle normal terminal commands
      if (input.trim()) {
        // Add the input to the terminal output
        addOutput(`$ ${input}`)

        // Check if the active executor has a command handler
        const activeExecutor = getExecutorForLanguage(selectedLanguage)
        if (activeExecutor && activeExecutor.handleCommand) {
          const handled = activeExecutor.handleCommand(input, {
            files,
            selectedLanguage,
            addOutput,
            setIsExecuting,
          })

          if (handled) {
            setInput("")
            return
          }
        }

        // If not handled by the executor, try to execute the command
        if (input.trim().toLowerCase() === "clear") {
          setOutput([])
        } else if (input.trim().toLowerCase() === "run") {
          handleExecute("") // Assuming executeCode is meant to be handleExecute
        } else {
          addOutput(`Unknown command: ${input}`)
        }

        setInput("")
      }
    }
  }

  return {
    isExecuting,
    setIsExecuting,
    handleExecute,
    handleStopExecution,
    handleTerminalCommand,
    handleTerminalInput,
    setInput,
  }
}

"use client"

import type React from "react"

import type { CodeFile } from "@/components/block-content-editor/extras/source-code/types"
import { useCallback, useMemo } from "react"

interface UseFileContentProps {
  files: CodeFile[]
  setFiles: React.Dispatch<React.SetStateAction<CodeFile[]>>
  activeFileId: string
  selectedLanguage?: string
}

interface UseFileContentReturn {
  activeFile: CodeFile | undefined
  activeFileContent: string
  updateActiveFileContent: (content: string) => void
  getVisibleFiles: (isEditing: boolean) => CodeFile[]
  addSolutionTemplate: () => void
}

export function insertSolutionTemplate(content: string, language: string): string {
  // Check if a solution function already exists
  if (
    content.includes("function solution") ||
    content.includes("def solution") ||
    content.includes("int solution") ||
    content.includes("auto solution") ||
    content.includes("class Solution")
  ) {
    return content
  }

  let template = ""

  switch (language) {
    case "javascript":
      template = `
// Write your solution function here

function solution(a) {
  // Your solution here
  // The 'a' parameter contains the input from "Initial stdin"
  // console.log(a);
  return a;
}
`
      break
    case "typescript":
      template = `
// Write your solution function here
function solution(value: any): any[] {
  // Your solution here
  return [];
}
`
      break
    case "python":
      template = `
# Write your solution function here
def solution(value):
    # Your solution here
    return []
`
      break
    case "lua":
      template = `
-- Write your solution function here
function solution(value)
    -- Your solution here
    return {}
end
`
      break
    case "c":
      template = `
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/**
 * Write your solution function here
 * @param value The input value
 * @return The result
 */
int solution(int value) {
    // Your solution here
    return 0;
}
`
      break
    case "cpp":
      template = `
#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

/**
 * Write your solution function here
 * @param value The input value
 * @return The result
 */
int solution(int value) {
    // Your solution here
    return 0;
}

// For vector return type, use this template instead:
/*
std::vector<int> solution(int value) {
    // Your solution here
    return {};
}
*/
`
      break
    case "h":
      template = `
#ifndef SOLUTION_H
#define SOLUTION_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/**
 * Write your solution function declaration here
 * @param value The input value
 * @return The result
 */
int solution(int value);

// Implementation can be provided in a separate .c file
// or inline here if this is a header-only implementation
#ifdef HEADER_IMPLEMENTATION
int solution(int value) {
    // Your solution here
    return 0;
}
#endif

#endif // SOLUTION_H
`
      break
    case "hpp":
      template = `
#ifndef SOLUTION_HPP
#define SOLUTION_HPP

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

/**
 * Function-based solution
 * @param value The input value
 * @return The result
 */
int solution(int value);

// Class-based solution (alternative)
/*
class Solution {
public:
    // Constructor
    Solution() {}
    
    // Main solution method
    int solve(int value) {
        // Your solution here
        return 0;
    }
    
    // For vector return type
    std::vector<int> solveVector(int value) {
        // Your solution here
        return {};
    }
};
*/

// Implementation can be provided in a separate .cpp file
// or inline here if this is a header-only implementation
#ifdef HEADER_IMPLEMENTATION
int solution(int value) {
    // Your solution here
    return 0;
}
#endif

#endif // SOLUTION_HPP
`
      break
    default:
      return content
  }

  return content + template
}

export function useFileContent({ files, setFiles, activeFileId }: UseFileContentProps): UseFileContentReturn {
  // Get visible files based on editing mode
  const getVisibleFiles = (isEditing: boolean) => {
    return isEditing ? files : files.filter((file) => file.isVisible)
  }

  // Get active file
  const activeFile = useMemo(() => {
    const visibleFiles = getVisibleFiles(true) // Always check all files first
    // First try to find the active file in all files
    const file = visibleFiles.find((file) => file.id === activeFileId)
    if (file) return file

    // If active file is not found, select the first file
    return visibleFiles[0] || files[0]
  }, [files, activeFileId])

  // Get active file content based on selected language
  const activeFileContent = useMemo(() => {
    return activeFile?.content || ""
  }, [activeFile])

  // Update active file content
  const updateActiveFileContent = useCallback(
    (content: string) => {
      // Check if file is in read-only mode
      const currentFile = files.find((file) => file.id === activeFileId)
      if (currentFile?.readOnlyState === "always") {
        console.log("File is read-only, cannot update content")
        return
      }

      console.log("Updating file content:", activeFileId, content.substring(0, 20) + "...")
      setFiles((prevFiles) =>
        prevFiles.map((file) => {
          if (file.id !== activeFileId) return file
          return { ...file, content }
        }),
      )
    },
    [activeFileId, files, setFiles],
  )

  // Add a function to add the solution template to the active file
  const addSolutionTemplate = useCallback(() => {
    if (!activeFile) return

    const newContent = insertSolutionTemplate(activeFileContent, activeFile.language || "javascript")
    updateActiveFileContent(newContent)
  }, [activeFile, activeFileContent, updateActiveFileContent])

  return {
    activeFile,
    activeFileContent,
    updateActiveFileContent,
    getVisibleFiles,
    addSolutionTemplate,
  }
}

"use client"

import type React from "react"

import type { CodeFile, LanguageType } from "@/components/block-content-editor/extras/source-code/types"
import { getExtension, getExtensionForLanguage, getLanguageFromExtension } from "@/components/block-content-editor/extras/source-code/utils"
import { useRef, useState } from "react"

interface UseFileManagementProps {
  files: CodeFile[]
  setFiles: React.Dispatch<React.SetStateAction<CodeFile[]>>
  activeFileId: string
  setActiveFileId: (id: string) => void
}

interface UseFileManagementReturn {
  // Dialog states
  showFileDialog: boolean
  setShowFileDialog: (show: boolean) => void
  newFileName: string
  setNewFileName: (name: string) => void
  newFileLanguage: LanguageType
  setNewFileLanguage: (lang: LanguageType) => void
  newFileHasStates: boolean
  setNewFileHasStates: (hasStates: boolean) => void

  // Import dialog states
  showImportDialog: boolean
  setShowImportDialog: (show: boolean) => void
  importContents: { name: string; content: string }[]
  setImportContents: (contents: { name: string; content: string }[]) => void
  importFileNames: string[]
  setImportFileNames: (names: string[]) => void
  importFileHasStates: boolean
  setImportFileHasStates: (hasStates: boolean) => void
  fileInputRef: React.RefObject<HTMLInputElement | null>

  // Confirm dialog states
  showConfirmDialog: boolean
  setShowConfirmDialog: (show: boolean) => void

  // Rename dialog states
  showRenameDialog: boolean
  setShowRenameDialog: (show: boolean) => void
  renameFileName: string
  setRenameFileName: (name: string) => void
  renameFileLanguage: LanguageType
  setRenameFileLanguage: (lang: LanguageType) => void
  fileToRename: string | null
  setFileToRename: (id: string | null) => void

  // Drag and drop states
  draggedFileId: string | null
  setDraggedFileId: (id: string | null) => void
  dragOverFileId: string | null
  setDragOverFileId: (id: string | null) => void

  // File operations
  addNewFile: () => void
  importFile: () => void
  handleFileUpload: (e: React.ChangeEvent<HTMLInputElement>) => void
  deleteFile: (fileId: string) => void
  renameFile: () => void
  reorderFiles: (fileId: string, targetFileId: string) => void
}

export function useFileManagement({
  files,
  setFiles,
  activeFileId,
  setActiveFileId,
}: UseFileManagementProps): UseFileManagementReturn {
  // New file dialog states
  const [showFileDialog, setShowFileDialog] = useState(false)
  const [newFileName, setNewFileName] = useState("")
  const [newFileLanguage, setNewFileLanguage] = useState<LanguageType>("javascript")
  const [newFileHasStates, setNewFileHasStates] = useState(false)

  // Import dialog states
  const [showImportDialog, setShowImportDialog] = useState(false)
  const [importContents, setImportContents] = useState<{ name: string; content: string }[]>([])
  const [importFileNames, setImportFileNames] = useState<string[]>([])
  const [importFileHasStates, setImportFileHasStates] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)

  // Confirm dialog states
  const [showConfirmDialog, setShowConfirmDialog] = useState(false)

  // Rename dialog states
  const [showRenameDialog, setShowRenameDialog] = useState(false)
  const [renameFileName, setRenameFileName] = useState("")
  const [renameFileLanguage, setRenameFileLanguage] = useState<LanguageType>("javascript")
  const [fileToRename, setFileToRename] = useState<string | null>(null)

  // Drag and drop states
  const [draggedFileId, setDraggedFileId] = useState<string | null>(null)
  const [dragOverFileId, setDragOverFileId] = useState<string | null>(null)

  // Add a new file
  const addNewFile = () => {
    if (!newFileName.trim()) return

    // Determine file extension based on whether it has one already or needs to use the language default
    let fileName = newFileName.trim()
    let fileExtension = getExtension(fileName)

    if (!fileExtension) {
      fileExtension = getExtensionForLanguage(newFileLanguage)
      fileName = `${fileName}.${fileExtension}`
    }

    // Check if file with same name already exists
    if (files.some((file) => file.name.toLowerCase() === fileName.toLowerCase())) {
      alert(`A file named "${fileName}" already exists.`)
      return
    }

    const newFile: CodeFile = {
      id: crypto.randomUUID(),
      name: fileName,
      content: "",
      language: newFileLanguage,
      isMain: false,
      isVisible: true,
    }

    setFiles((prev) => [...prev, newFile])
    setActiveFileId(newFile.id)
    setNewFileName("")
    setNewFileHasStates(false)
    setShowFileDialog(false)
  }

  // Import a file
  const importFile = () => {
    if (importContents.length === 0) return

    const newFiles: CodeFile[] = importContents.map((fileData) => {
      // Detect language from file extension
      const extension = getExtension(fileData.name)
      const language = getLanguageFromExtension(extension)

      const newFile: CodeFile = {
        id: crypto.randomUUID(),
        name: fileData.name,
        content: fileData.content,
        language,
        isMain: false,
        isVisible: true,
      }

      return newFile
    })

    setFiles((prev) => [...prev, ...newFiles])

    // Set the active file to the first imported file
    if (newFiles.length > 0 && newFiles[0]) {
      setActiveFileId(newFiles[0].id)
    }

    setImportFileNames([])
    setImportContents([])
    setShowImportDialog(false)
  }

  // Handle file upload
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (!files || files.length === 0) return

    const fileNames: string[] = []
    const filePromises: Promise<{ name: string; content: string }>[] = []

    Array.from(files).forEach((file) => {
      fileNames.push(file.name)

      const promise = new Promise<{ name: string; content: string }>((resolve) => {
        const reader = new FileReader()
        reader.onload = (event) => {
          const content = event.target?.result as string
          resolve({ name: file.name, content })
        }
        reader.readAsText(file)
      })

      filePromises.push(promise)
    })

    setImportFileNames(fileNames)

    Promise.all(filePromises).then((results) => {
      setImportContents(results)
    })
  }

  // Delete a file
  const deleteFile = (fileId: string) => {
    // Don't allow deleting the last file
    if (files.length <= 1) return

    // If deleting active file, switch to another file
    if (fileId === activeFileId) {
      const visibleFiles = files.filter((f) => f.isVisible)
      const fileIndex = visibleFiles.findIndex((f) => f.id === fileId)
      const newActiveIndex = fileIndex > 0 ? fileIndex - 1 : fileIndex + 1
      if (visibleFiles[newActiveIndex]) {
        setActiveFileId(visibleFiles[newActiveIndex].id)
      }
    }

    setFiles(files.filter((f) => f.id !== fileId))
  }

  // Rename a file
  const renameFile = () => {
    if (!fileToRename || !renameFileName.trim()) return

    setFiles((prevFiles) =>
      prevFiles.map((file) => {
        if (file.id !== fileToRename) return file

        // Get the current extension
        const currentExt = getExtension(file.name)

        // Make sure the new name has the same extension
        let newName = renameFileName.trim()
        const newExt = getExtension(newName)

        // If no extension provided, use the extension for the selected language
        if (!newExt) {
          // For language-specific files, use the current extension
          // For regular files, use the extension for the selected language
          const newExtension = currentExt ? currentExt : getExtensionForLanguage(renameFileLanguage)
          newName = `${newName}.${newExtension}`
        }

        // Check if file with same name already exists
        if (files.some((f) => f.id !== file.id && f.name.toLowerCase() === newName.toLowerCase())) {
          alert(`A file named "${newName}" already exists.`)
          return file
        }

        // Return updated file with new name and language (only update language for non-language-specific files)
        return {
          ...file,
          name: newName,
          language: renameFileLanguage,
        }
      }),
    )

    setFileToRename(null)
    setRenameFileName("")
    setRenameFileLanguage("javascript")
    setShowRenameDialog(false)
  }

  // Reorder files (drag and drop)
  const reorderFiles = (fileId: string, targetFileId: string) => {
    if (fileId === targetFileId) return

    setFiles((prevFiles) => {
      const newFiles = [...prevFiles]
      const fileIndex = newFiles.findIndex((f) => f.id === fileId)
      const targetIndex = newFiles.findIndex((f) => f.id === targetFileId)

      if (fileIndex === -1 || targetIndex === -1) return prevFiles

      // Remove the file from its current position
      const [movedFile] = newFiles.splice(fileIndex, 1)

      // Insert it at the target position
      if (movedFile) {
        newFiles.splice(targetIndex, 0, movedFile)
      }

      return newFiles
    })
  }

  return {
    // Dialog states
    showFileDialog,
    setShowFileDialog,
    newFileName,
    setNewFileName,
    newFileLanguage,
    setNewFileLanguage,
    newFileHasStates,
    setNewFileHasStates,

    // Import dialog states
    showImportDialog,
    setShowImportDialog,
    importContents,
    setImportContents,
    importFileNames,
    setImportFileNames,
    importFileHasStates,
    setImportFileHasStates,
    fileInputRef,

    // Confirm dialog states
    showConfirmDialog,
    setShowConfirmDialog,

    // Rename dialog states
    showRenameDialog,
    setShowRenameDialog,
    renameFileName,
    setRenameFileName,
    renameFileLanguage,
    setRenameFileLanguage,
    fileToRename,
    setFileToRename,

    // Drag and drop states
    draggedFileId,
    setDraggedFileId,
    dragOverFileId,
    setDragOverFileId,

    // File operations
    addNewFile,
    importFile,
    handleFileUpload,
    deleteFile,
    renameFile,
    reorderFiles,
  }
}

import type { CodeFile } from "@/components/block-content-editor/extras/source-code/types"
import type React from "react"

interface UseFileStateProps {
  files: CodeFile[]
  setFiles: React.Dispatch<React.SetStateAction<CodeFile[]>>
}

interface UseFileStateReturn {
  toggleFileVisibility: (fileId: string) => void
  setMainFile: (fileId: string) => void
  setFileReadOnlyState: (fileId: string, state: "hidden" | "always" | "never" | null) => void
  isFileReadOnly: (file: CodeFile, globalReadOnly: boolean) => boolean
}

export function useFileState({ files, setFiles }: UseFileStateProps): UseFileStateReturn {
  // Toggle file visibility
  const toggleFileVisibility = (fileId: string) => {
    setFiles((prevFiles) =>
      prevFiles.map((file) => (file.id === fileId ? { ...file, isVisible: !file.isVisible } : file)),
    )
  }

  // Set main file
  const setMainFile = (fileId: string) => {
    // Modified to toggle main status - if the file is already main, unset it
    setFiles((prevFiles) =>
      prevFiles.map((file) => ({
        ...file,
        isMain: file.id === fileId ? !file.isMain : false,
      })),
    )
  }

  // Set file read-only state
  const setFileReadOnlyState = (fileId: string, state: "hidden" | "always" | "never" | null) => {
    setFiles((prevFiles) => prevFiles.map((file) => (file.id === fileId ? { ...file, readOnlyState: state } : file)))
  }

  // Check if file is read-only
  const isFileReadOnly = (file: CodeFile, globalReadOnly: boolean): boolean => {
    if (file.readOnlyState === "always") return true
    if (file.readOnlyState === "never") return false
    if (file.readOnlyState === "hidden") return globalReadOnly // Use global setting for hidden files
    return globalReadOnly // Use global setting
  }

  return {
    toggleFileVisibility,
    setMainFile,
    setFileReadOnlyState,
    isFileReadOnly,
  }
}

"use client"

import { useState, useEffect, useCallback } from "react"
import { toast } from "sonner"
import { GoogleDriveSecurity } from "@/components/block-content-editor/utils/editor/google-drive-security"
import { GoogleDriveService } from "@/components/block-content-editor/services/editor/google-drive-service"

interface GoogleDriveAuthState {
  isAuthenticated: boolean
  isLoading: boolean
  selectedFolder: string | null
  folderName: string | null
  accessToken: string | null
  error: string | null
}

interface GoogleDriveFolder {
  id: string
  name: string
  createdTime: string
}

// Extend window type for new Google Identity Services
declare global {
  interface Window {
    google: any
    gapi: any
  }
}

export function useGoogleDriveAuth() {
  const [authState, setAuthState] = useState<GoogleDriveAuthState>({
    isAuthenticated: false,
    isLoading: false,
    selectedFolder: null,
    folderName: null,
    accessToken: null,
    error: null,
  })

  // Helper function to update localStorage and notify other instances
  const updateLocalStorage = useCallback((key: string, value: string) => {
    localStorage.setItem(key, value)
    // Dispatch custom event for same-tab updates
    window.dispatchEvent(new CustomEvent('block-content-editor-storage-change', { 
      detail: { key, value } 
    }))
  }, [])

  // Google Drive API configuration
  const CLIENT_ID = process.env.NEXT_PUBLIC_GOOGLE_DRIVE_CLIENT_ID
  const API_KEY = process.env.NEXT_PUBLIC_GOOGLE_DRIVE_API_KEY
  const DISCOVERY_DOC = 'https://www.googleapis.com/discovery/v1/apis/drive/v3/rest'
  
  // Minimal required scopes - only file access within app-created folders
  const SCOPES = 'https://www.googleapis.com/auth/drive.file'

  // Configure GoogleDriveService when authentication state changes
  useEffect(() => {
    const googleDriveService = GoogleDriveService.getInstance()
    
    if (authState.isAuthenticated && authState.accessToken && authState.selectedFolder) {
      // Configure the service with authentication credentials
      googleDriveService.setAuth(authState.accessToken, authState.selectedFolder)
      console.log('GoogleDriveService configured with auth credentials')
    }
  }, [authState.isAuthenticated, authState.accessToken, authState.selectedFolder])

  // Load Google APIs (both GIS and GAPI)
  const loadGoogleAPI = useCallback(async () => {
    if (typeof window === 'undefined') return false

    try {
      // Load Google Identity Services (new auth)
      if (!window.google) {
        await new Promise<void>((resolve, reject) => {
          const script = document.createElement('script')
          script.src = 'https://accounts.google.com/gsi/client'
          script.onload = () => resolve()
          script.onerror = () => reject(new Error('Failed to load Google Identity Services'))
          document.head.appendChild(script)
        })
      }

      // Load Google API script (for Drive API)
      if (!window.gapi) {
        await new Promise<void>((resolve, reject) => {
          const script = document.createElement('script')
          script.src = 'https://apis.google.com/js/api.js'
          script.onload = () => resolve()
          script.onerror = () => reject(new Error('Failed to load Google API'))
          document.head.appendChild(script)
        })
      }

      // Initialize GAPI for Drive API
      await new Promise<void>((resolve) => {
        window.gapi.load('client', resolve)
      })

      // Initialize client
      await window.gapi.client.init({
        apiKey: API_KEY,
        discoveryDocs: [DISCOVERY_DOC],
      })

      return true
    } catch (error) {
      console.error('Failed to load Google API:', error)
      setAuthState(prev => ({ 
        ...prev, 
        error: 'Falha ao carregar API do Google Drive',
        isLoading: false 
      }))
      return false
    }
  }, [API_KEY])

  // Check authentication status
  const checkAuthStatus = useCallback(async () => {
    // Check if we have a stored access token
    const storedToken = localStorage.getItem('block-content-editor_google_drive_token')
    const storedExpiry = localStorage.getItem('block-content-editor_google_drive_token_expiry')
    
    if (storedToken && storedExpiry) {
      const expiryTime = parseInt(storedExpiry)
      const now = Date.now()
      
      if (now < expiryTime) {
        // Token is still valid
        const savedFolder = localStorage.getItem('block-content-editor_google_drive_folder')
        const savedFolderName = localStorage.getItem('block-content-editor_google_drive_folder_name')
        
        setAuthState(prev => ({
          ...prev,
          isAuthenticated: true,
          accessToken: storedToken,
          selectedFolder: savedFolder,
          folderName: savedFolderName,
          error: null,
        }))
        return
      } else {
        // Token expired, clean up
        localStorage.removeItem('block-content-editor_google_drive_token')
        localStorage.removeItem('block-content-editor_google_drive_token_expiry')
      }
    }
  }, [])

  // Initialize Google Drive API
  useEffect(() => {
    const initialize = async () => {
      // Validate environment first
      const envValidation = GoogleDriveSecurity.validateEnvironment()
      if (!envValidation.isValid) {
        console.warn('Google Drive API not properly configured:', envValidation.errors)
        return
      }

      // Clean up expired data
      GoogleDriveSecurity.cleanupExpiredData()

      setAuthState(prev => ({ ...prev, isLoading: true }))
      
      const loaded = await loadGoogleAPI()
      if (loaded) {
        await checkAuthStatus()
      }
      
      setAuthState(prev => ({ ...prev, isLoading: false }))
    }

    initialize()
  }, [loadGoogleAPI, checkAuthStatus, CLIENT_ID, API_KEY])

  // Authenticate with Google using new GIS
  const authenticate = useCallback(async (): Promise<boolean> => {
    if (!window.google || !CLIENT_ID) {
      toast.error('Google API não carregada')
      return false
    }

    try {
      setAuthState(prev => ({ ...prev, isLoading: true, error: null }))
      
      // Use new Google Identity Services
      return new Promise((resolve) => {
        const tokenClient = window.google.accounts.oauth2.initTokenClient({
          client_id: CLIENT_ID,
          scope: SCOPES,
          callback: async (response: any) => {
            if (response.error) {
              console.error('Google authentication failed:', response)
              
              let errorMessage = 'Falha na autenticação'
              if (response.error === 'popup_closed_by_user') {
                errorMessage = 'Autenticação cancelada pelo usuário'
              } else if (response.error === 'access_denied') {
                errorMessage = 'Acesso negado pelo usuário'
              }
              
              setAuthState(prev => ({ 
                ...prev, 
                error: errorMessage,
                isLoading: false 
              }))
              
              toast.error(errorMessage)
              resolve(false)
              return
            }

            // Success - we have an access token
            const accessToken = response.access_token
            const expiresIn = response.expires_in ? parseInt(response.expires_in) * 1000 : 3600000 // Default 1 hour
            const expiryTime = Date.now() + expiresIn

            // Store token with expiry
            updateLocalStorage('block-content-editor_google_drive_token', accessToken)
            updateLocalStorage('block-content-editor_google_drive_token_expiry', expiryTime.toString())
            updateLocalStorage('block-content-editor_google_drive_auth_time', Date.now().toString())

            setAuthState(prev => ({
              ...prev,
              isAuthenticated: true,
              accessToken: accessToken,
              isLoading: false,
              error: null,
            }))

            GoogleDriveSecurity.logSecurityEvent('google_drive_auth_success')
            toast.success('Autenticado com Google Drive')
            resolve(true)
          },
        })

        // Request access token
        tokenClient.requestAccessToken({ prompt: 'consent' })
      })
    } catch (error: any) {
      console.error('Google authentication failed:', error)
      
      setAuthState(prev => ({ 
        ...prev, 
        error: 'Falha na autenticação',
        isLoading: false 
      }))
      
      toast.error('Falha na autenticação')
      return false
    }
  }, [CLIENT_ID, SCOPES])

  // Create or find Block Content Editor folder
  const createOrFindFolder = useCallback(async (folderName: string): Promise<string | null> => {
    if (!authState.accessToken) return null

    // Sanitize folder name
    const sanitizedName = GoogleDriveSecurity.sanitizeFileName(folderName.replace('.block-content-editor.json', ''))
    const finalFolderName = sanitizedName.replace('.block-content-editor.json', '') // Remove extension for folder name

    try {
      return await GoogleDriveSecurity.throttleApiCall(async () => {
        // Set the access token for GAPI client before making API calls
        window.gapi.client.setToken({ access_token: authState.accessToken })
        
        // First, check if folder already exists
        const searchResponse = await window.gapi.client.drive.files.list({
          q: `name='${finalFolderName}' and mimeType='application/vnd.google-apps.folder' and trashed=false`,
          fields: 'files(id, name, createdTime)',
        })

        if (searchResponse.result.files && searchResponse.result.files.length > 0) {
          const folder = searchResponse.result.files[0]
          
          // Save folder info
          updateLocalStorage('block-content-editor_google_drive_folder', folder.id!)
          updateLocalStorage('block-content-editor_google_drive_folder_name', folder.name!)
          
          setAuthState(prev => ({
            ...prev,
            selectedFolder: folder.id!,
            folderName: folder.name!,
          }))
          
          return folder.id!
        }

        // Create new folder if not found
        const createResponse = await window.gapi.client.drive.files.create({
          resource: {
            name: finalFolderName,
            mimeType: 'application/vnd.google-apps.folder',
          },
          fields: 'id, name',
        })

        const folderId = createResponse.result.id!
        
        // Save folder info
        updateLocalStorage('block-content-editor_google_drive_folder', folderId)
        updateLocalStorage('block-content-editor_google_drive_folder_name', finalFolderName)
        
        setAuthState(prev => ({
          ...prev,
          selectedFolder: folderId,
          folderName: finalFolderName,
        }))

        toast.success(`Pasta "${finalFolderName}" criada no Google Drive`)
        return folderId
      })
    } catch (error) {
      console.error('Failed to create/find folder:', error)
      GoogleDriveSecurity.logSecurityEvent('folder_creation_failed', { error: String(error) })
      toast.error('Falha ao criar pasta no Google Drive')
      return null
    }
  }, [authState.accessToken])

  // Sign out
  const signOut = useCallback(async () => {
    try {
      // Revoke the access token
      const accessToken = authState.accessToken
      if (accessToken) {
        // Revoke token using new GIS method
        window.google?.accounts?.oauth2?.revoke(accessToken, () => {
          console.log('Token revoked')
        })
      }
      
      // Clear stored data
      localStorage.removeItem('block-content-editor_google_drive_token')
      localStorage.removeItem('block-content-editor_google_drive_token_expiry')
      localStorage.removeItem('block-content-editor_google_drive_folder')
      localStorage.removeItem('block-content-editor_google_drive_folder_name')
      localStorage.removeItem('block-content-editor_google_drive_auth_time')
      
      setAuthState({
        isAuthenticated: false,
        isLoading: false,
        selectedFolder: null,
        folderName: null,
        accessToken: null,
        error: null,
      })

      toast.success('Desconectado do Google Drive')
    } catch (error) {
      console.error('Sign out failed:', error)
      toast.error('Falha ao desconectar')
    }
  }, [authState.accessToken])

  // Get available folders (for selection)
  const getAvailableFolders = useCallback(async (): Promise<GoogleDriveFolder[]> => {
    if (!authState.accessToken) return []

    try {
      // Set the access token for GAPI client
      window.gapi.client.setToken({ access_token: authState.accessToken })
      
      const response = await window.gapi.client.drive.files.list({
        q: "mimeType='application/vnd.google-apps.folder' and trashed=false",
        fields: 'files(id, name, createdTime)',
        orderBy: 'name',
      })

      return response.result.files || []
    } catch (error) {
      console.error('Failed to get folders:', error)
      return []
    }
  }, [authState.accessToken])

  // Add a refresh function to force state update
  const refreshAuthState = useCallback(() => {
    const storedToken = localStorage.getItem('block-content-editor_google_drive_token')
    const storedExpiry = localStorage.getItem('block-content-editor_google_drive_token_expiry')
    
    if (storedToken && storedExpiry) {
      const expiryTime = parseInt(storedExpiry)
      const now = Date.now()
      
      if (now < expiryTime) {
        // Token is still valid
        const savedFolder = localStorage.getItem('block-content-editor_google_drive_folder')
        const savedFolderName = localStorage.getItem('block-content-editor_google_drive_folder_name')
        
        setAuthState(prev => ({
          ...prev,
          isAuthenticated: true,
          accessToken: storedToken,
          selectedFolder: savedFolder,
          folderName: savedFolderName,
          error: null,
        }))
      } else {
        // Token expired, clean up
        localStorage.removeItem('block-content-editor_google_drive_token')
        localStorage.removeItem('block-content-editor_google_drive_token_expiry')
        setAuthState(prev => ({
          ...prev,
          isAuthenticated: false,
          accessToken: null,
          selectedFolder: null,
          folderName: null,
        }))
      }
    } else {
      setAuthState(prev => ({
        ...prev,
        isAuthenticated: false,
        accessToken: null,
        selectedFolder: null,
        folderName: null,
      }))
    }
  }, [])

  // Listen for localStorage changes to automatically refresh auth state
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'block-content-editor_google_drive_token' || 
          e.key === 'block-content-editor_google_drive_token_expiry' ||
          e.key === 'block-content-editor_google_drive_folder') {
        // Token or folder changed, refresh auth state
        refreshAuthState()
      }
    }

    const handleCustomStorageChange = (e: CustomEvent) => {
      const { key } = e.detail
      if (key === 'block-content-editor_google_drive_token' || 
          key === 'block-content-editor_google_drive_token_expiry' ||
          key === 'block-content-editor_google_drive_folder') {
        // Token or folder changed, refresh auth state
        refreshAuthState()
      }
    }

    window.addEventListener('storage', handleStorageChange)
    window.addEventListener('block-content-editor-storage-change', handleCustomStorageChange as EventListener)
    
    return () => {
      window.removeEventListener('storage', handleStorageChange)
      window.removeEventListener('block-content-editor-storage-change', handleCustomStorageChange as EventListener)
    }
  }, [refreshAuthState])

  return {
    ...authState,
    authenticate,
    signOut,
    createOrFindFolder,
    getAvailableFolders,
    refreshAuthState,
    hasValidSetup: authState.isAuthenticated && authState.selectedFolder,
  }
}

