"use client"

import type React from "react"

import type { LanguageType, ProgrammingLanguage } from "@/components/block-content-editor/extras/source-code/types"
import { useState } from "react"

interface UseLanguageSettingsProps {
  initialAllowedLanguages?: Record<LanguageType, boolean>
  initialSelectedLanguage?: ProgrammingLanguage
}

interface UseLanguageSettingsReturn {
  selectedLanguage: ProgrammingLanguage
  setSelectedLanguage: (lang: ProgrammingLanguage | string) => void
  allowedLanguages: Record<LanguageType, boolean>
  setAllowedLanguages: React.Dispatch<React.SetStateAction<Record<LanguageType, boolean>>>
  showLanguagesDialog: boolean
  setShowLanguagesDialog: (show: boolean) => void
  getAllowedLanguageTypes: () => LanguageType[]
  getAllowedProgrammingLanguages: () => ProgrammingLanguage[]
}

export function useLanguageSettings({
  initialAllowedLanguages = {
    javascript: true,
    typescript: true,
    python: true,
    lua: true,
    c: true,
    cpp: true,
    cheader: true,
    cppheader: true,
    html: true,
    css: true,
    json: true,
    xml: true,
    yaml: true,
    text: true,
    h: false,
    hpp: false,
    markdown: false
  },
  initialSelectedLanguage = "javascript",
}: UseLanguageSettingsProps = {}): UseLanguageSettingsReturn {
  const [selectedLanguage, setSelectedLanguage] = useState<ProgrammingLanguage>(initialSelectedLanguage)
  const [allowedLanguages, setAllowedLanguages] = useState<Record<LanguageType, boolean>>(initialAllowedLanguages)
  const [showLanguagesDialog, setShowLanguagesDialog] = useState(false)

  // Get allowed language types
  const getAllowedLanguageTypes = (): LanguageType[] => {
    return Object.entries(allowedLanguages)
      .filter(([_, isAllowed]) => isAllowed)
      .map(([lang]) => lang as LanguageType)
  }

  // Get allowed programming languages
  const getAllowedProgrammingLanguages = (): ProgrammingLanguage[] => {
    return getAllowedLanguageTypes().filter(
      (lang): lang is ProgrammingLanguage =>
        lang === "javascript" || lang === "typescript" || lang === "python" || lang === "lua" || lang === "c" || lang === "cpp" || lang === "cheader" || lang === "cppheader",
    )
  }

  return {
    selectedLanguage,
    setSelectedLanguage: setSelectedLanguage as (lang: ProgrammingLanguage | string) => void,
    allowedLanguages,
    setAllowedLanguages,
    showLanguagesDialog,
    setShowLanguagesDialog,
    getAllowedLanguageTypes,
    getAllowedProgrammingLanguages,
  }
}

import * as React from "react"

const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener("change", onChange)
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return !!isMobile
}

"use client"

import { ProjectExporter, type ProjectData as ExportProjectData } from "@/components/block-content-editor/lib/interopAdapter/project-exporter"
import { HashManager } from "@/components/block-content-editor/lib/sync/editor/hash-manager"
import type { ProjectData } from "@/components/block-content-editor/lib/storage/editor/project-data"
import type { StorageType } from "@/components/block-content-editor/lib/storage/editor/storage-types"
import type { ProjectPreferences } from "@/components/block-content-editor/lib/storage/editor/project-preferences"
import { useCallback, useEffect, useState } from "react"
import { toast } from "sonner"

interface StorageAdapter {
  list: () => Promise<ProjectData[]>
  load: (id: string) => Promise<ProjectData | null>
  delete?: (id: string) => Promise<void>
  searchProjects: (searchTerm: string, tags: string[], filterMode: "all" | "any", storageTypeFilter?: StorageType) => Promise<ProjectData[]>
}

interface UseProjectDialogProps {
  isDbInitialized: boolean
  storageAdapter: StorageAdapter
}

export function useProjectDialog({ isDbInitialized, storageAdapter }: UseProjectDialogProps) {
  const [searchTerm, setSearchTerm] = useState("")
  const [selectedTags, setSelectedTags] = useState<string[]>([])
  const [storageTypeFilter, setStorageTypeFilter] = useState<StorageType | undefined>(undefined)
  const [currentPage, setCurrentPage] = useState(1)
  const [itemsPerPage, setItemsPerPage] = useState(16) // Changed initial itemsPerPage from 10 to 12 to match available options in selector
  const [filteredProjects, setFilteredProjects] = useState<ProjectData[]>([])
  const [totalProjects, setTotalProjects] = useState(0)
  const [tagFilterMode, setTagFilterMode] = useState<"all" | "any">("any")

  // Function to refresh projects list
  const refreshProjects = useCallback(async () => {
    if (!isDbInitialized) return

    try {
      let projects: ProjectData[]

      if (searchTerm || selectedTags.length > 0 || storageTypeFilter) {
        projects = await storageAdapter.searchProjects(searchTerm, selectedTags, tagFilterMode, storageTypeFilter)
      } else {
        projects = await storageAdapter.list()
      }

      setTotalProjects(projects.length)
      setFilteredProjects(projects)
    } catch (error) {
      console.error("Failed to refresh projects:", error)
    }
  }, [isDbInitialized, searchTerm, selectedTags, storageTypeFilter, tagFilterMode, storageAdapter])

  // Reset pagination only when filter criteria actually change
  useEffect(() => {
    setCurrentPage(1)
  }, [searchTerm, selectedTags, tagFilterMode, storageTypeFilter])

  useEffect(() => {
    setCurrentPage(1)
  }, [itemsPerPage])

  // Filter projects based on search and tags
  useEffect(() => {
    refreshProjects()
  }, [refreshProjects])

  const handleDownload = async (
    projectId: string,
    projectName: string,
    projectData: string,
    projectTags: string[],
    createdAt: string,
    updatedAt: string,
    projectPreferences?: ProjectPreferences
  ) => {
    try {
      // Generate hash for the project
      const hash = await HashManager.generateHash(projectData)

      // Prepare project data for export using ProjectExporter
      const exportProjectData: ExportProjectData = {
        id: projectId,
        name: projectName,
        data: projectData,
        tags: projectTags,
        size: new Blob([projectData]).size,
        createdAt: createdAt,
        updatedAt: updatedAt,
        hash: hash,
        storageType: "local",
        preferences: projectPreferences
      }

      // Use ProjectExporter to create the ZIP file
      const zipBlob = await ProjectExporter.createZipFile(exportProjectData, hash)

      // Create download link
      const url = URL.createObjectURL(zipBlob)
      const link = document.createElement("a")
      link.href = url
      link.download = ProjectExporter.getDownloadFilename(exportProjectData)
      document.body.appendChild(link)
      link.click()

      // Cleanup
      document.body.removeChild(link)
      URL.revokeObjectURL(url)

      toast.success("Export completed", {
        description: `Project "${projectName}" exported successfully`,
        duration: 2500,
        icon: "📥",
      })
    } catch (error) {
      console.error("Export failed:", error)
      toast.error("Export failed", {
        description: "Could not export the project. Please try again.",
        duration: 4000,
        icon: "❌",
      })
    }
  }

  const loadProject = async (projectId: string): Promise<ProjectData | null> => {
    try {
      const projectData = await storageAdapter.load(projectId)
      if (!projectData) {
        toast.error("Project not found", {
          description: "Could not locate the project file",
          duration: 3000,
          icon: "🔍",
        })
        return null
      }

      // Additional validation for project data structure
      if (!projectData.data) {
        console.error("Project data missing 'data' field:", projectData)
        toast.error("Project data incomplete", {
          description: "The project file appears to be missing content data",
          duration: 4000,
          icon: "⚠️",
        })
        return null
      }

      // Validate that data is a non-empty string
      if (typeof projectData.data !== 'string' || projectData.data.trim() === '') {
        console.error("Project data is not a valid string:", typeof projectData.data, projectData.data?.length)
        toast.error("Project data invalid", {
          description: "The project content is not in the expected format",
          duration: 4000,
          icon: "⚠️",
        })
        return null
      }

      return projectData
    } catch (error) {
      console.error("Load error:", error)
      toast.error("Error loading project", {
        description: "Could not load the project. Please try again.",
        duration: 4000,
        icon: "❌",
      })
      return null
    }
  }

  return {
    // State
    searchTerm,
    setSearchTerm,
    selectedTags,
    setSelectedTags,
    storageTypeFilter,
    setStorageTypeFilter,
    currentPage,
    setCurrentPage,
    itemsPerPage,
    setItemsPerPage,
    filteredProjects,
    totalProjects,
    tagFilterMode,
    setTagFilterMode,

    // Functions
    handleDownload,
    loadProject,
    refreshProjects,
  }
}

"use client"

// Inspired by react-hot-toast library
import * as React from "react"

import type { Toast, ToastAction } from "@game-guild/ui/components/toast"

type ToastProps = React.ComponentProps<typeof Toast>
type ToastActionElement = React.ReactElement<typeof ToastAction>

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = typeof actionTypes

type Action =
  | {
      type: ActionType["ADD_TOAST"]
      toast: ToasterToast
    }
  | {
      type: ActionType["UPDATE_TOAST"]
      toast: Partial<ToasterToast>
    }
  | {
      type: ActionType["DISMISS_TOAST"]
      toastId?: ToasterToast["id"]
    }
  | {
      type: ActionType["REMOVE_TOAST"]
      toastId?: ToasterToast["id"]
    }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t
        ),
      }

    case "DISMISS_TOAST": {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t
        ),
      }
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, "id">

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  }
}

export { useToast, toast }

