"use client"

/**
 * useProjectSync
 *
 * Polls / subscribes to the {@link SyncManager} via the storage adapter,
 * exposing the current {@link SyncStats}. Also owns the user-toggleable
 * `autoSaveEnabled` flag (the auto-save effect itself lives in
 * `useProjectStorage` since it depends on cross-cutting state).
 */

import { useEffect, useState, type Dispatch, type SetStateAction } from "react"
import { toast } from "sonner"
import type { EnhancedStorageAdapter } from "@/components/block-content-editor/lib/storage/editor/enhanced-storage-adapter"
import type { SyncStats } from "@/components/block-content-editor/lib/sync/editor/sync-types"

export interface UseProjectSyncReturn {
  syncStats: SyncStats | null
  autoSaveEnabled: boolean
  setAutoSaveEnabled: Dispatch<SetStateAction<boolean>>
}

export function useProjectSync(
  db: EnhancedStorageAdapter,
  isDbInitialized: boolean,
): UseProjectSyncReturn {
  const [syncStats, setSyncStats] = useState<SyncStats | null>(null)
  const [autoSaveEnabled, setAutoSaveEnabled] = useState(false)

  useEffect(() => {
    if (!isDbInitialized) return

    const updateSyncStats = async () => {
      try { setSyncStats(await db.getSyncStats()) }
      catch (error) { console.error("Failed to get sync stats:", error) }
    }

    const interval = setInterval(updateSyncStats, 5000)
    updateSyncStats()

    db.onSyncStart(() => { updateSyncStats() })
    db.onSyncComplete((stats: SyncStats) => {
      updateSyncStats()
      if (stats.queue.processing > 0 || stats.queue.completed > 0) {
        toast.success("Synchronization completed", {
          description: `${stats.queue.completed} synchronized projects`,
          duration: 3000, icon: "🔄",
        })
      }
    })
    db.onSyncError(() => {
      updateSyncStats()
      toast.error("Synchronization error", {
        description: "Some projects may not be synchronized",
        duration: 4000, icon: "⚠️",
      })
    })

    return () => { clearInterval(interval) }
  }, [db, isDbInitialized])

  return { syncStats, autoSaveEnabled, setAutoSaveEnabled }
}

"use client"

import { useState, useEffect, useMemo, useCallback } from 'react'
import { Download, Edit, Trash } from "lucide-react"
import { toAssetUri } from "@game-guild/assets"
import { getDefaultBrowserAssetRepository } from "@game-guild/assets/browser"
import {
  applySorting,
  type ManagerCard,
  type CardAction,
  type FilterConfig,
} from "@/components/block-content-editor/extras/manager-page"
import { toast } from "sonner"

const assetRepository = getDefaultBrowserAssetRepository()

interface AssetItem {
  id: string
  name: string
  mimeType: string
  size: number
  createdAt: string
  projects?: string[]
  type?: 'standard' | 'bundler'
}

interface UseAssetManagerProps {
  isDbInitialized: boolean
  activeContext: 'projects' | 'assets' | 'collections'
  filters: FilterConfig
  currentPage: number
  itemsPerPage: number
  additionalFilteredProjects: Array<{ id: string; name: string }>
}

export interface UseAssetManagerReturn {
  assetCards: ManagerCard[]
  assetPrimaryActions: CardAction[]
  assetSecondaryActions: CardAction[]
  filteredCount: number
  uploadDialogOpen: boolean
  setUploadDialogOpen: (open: boolean) => void
  assetToDelete: { id: string; name: string; projects: string[] } | null
  setAssetToDelete: (asset: { id: string; name: string; projects: string[] } | null) => void
  assetToEdit: { id: string; name: string } | null
  setAssetToEdit: (asset: { id: string; name: string } | null) => void
  newAssetName: string
  setNewAssetName: (name: string) => void
  handleConfirmAssetDelete: () => Promise<void>
  handleConfirmAssetEdit: () => Promise<void>
  handleUploadComplete: () => Promise<void>
}

export function useAssetManager({
  isDbInitialized,
  activeContext,
  filters,
  currentPage,
  itemsPerPage,
  additionalFilteredProjects,
}: UseAssetManagerProps): UseAssetManagerReturn {
  const [assets, setAssets] = useState<AssetItem[]>([])
  const [uploadDialogOpen, setUploadDialogOpen] = useState(false)
  const [assetToDelete, setAssetToDelete] = useState<{ id: string; name: string; projects: string[] } | null>(null)
  const [assetToEdit, setAssetToEdit] = useState<{ id: string; name: string } | null>(null)
  const [newAssetName, setNewAssetName] = useState("")

  const loadAssets = useCallback(async () => {
    try {
      const assetList = (await assetRepository.list({ limit: 200 })).items

      const assetsWithProjects = assetList.map((asset) => ({
        id: asset.uri,
        name: asset.name,
        mimeType: asset.mimeType || 'application/octet-stream',
        size: asset.size || 0,
        createdAt: asset.createdAt || new Date().toISOString(),
        projects: [],
        type: 'standard' as const,
      }))

      setAssets(assetsWithProjects)
    } catch (error) {
      console.error("Failed to load assets:", error)
      toast.error("Failed to load assets", {
        description: error instanceof Error ? error.message : "Unknown error"
      })
    }
  }, [])

  // Load assets when switching to assets context
  useEffect(() => {
    console.log("Asset context effect:", { activeContext, isDbInitialized })
    if (activeContext === 'assets' && isDbInitialized) {
      console.log("Loading assets now...")
      loadAssets()
    }
  }, [activeContext, isDbInitialized, loadAssets])

  // Filter and sort assets
  const filteredAssets = useMemo(() => {
    const filtered = assets.filter((asset) => {
      const matchesSearch = !filters.searchTerm ||
        asset.name.toLowerCase().includes(filters.searchTerm.toLowerCase()) ||
        asset.mimeType.toLowerCase().includes(filters.searchTerm.toLowerCase())

      let matchesMimeType = true
      if (filters.mimeTypes && filters.mimeTypes.length > 0) {
        const assetExt = '.' + asset.name.split('.').pop()?.toLowerCase()
        matchesMimeType = filters.mimeTypes.includes(assetExt)
      }

      const assetType = asset.type || 'standard'
      const matchesAssetType =
        filters.assetType === "all" ||
        (filters.assetType === "standard" && assetType === "standard") ||
        (filters.assetType === "bundler" && assetType === "bundler")

      const matchesProject = !filters.projectFilter || filters.projectFilter === "all" || asset.projects?.includes(filters.projectFilter)

      const matchesUsage =
        filters.usageFilter === "all" ||
        (filters.usageFilter === "used" && asset.projects && asset.projects.length > 0) ||
        (filters.usageFilter === "unused" && (!asset.projects || asset.projects.length === 0))

      return matchesSearch && matchesMimeType && matchesAssetType && matchesProject && matchesUsage
    })

    return applySorting(filtered, filters.sortOrder || [], 'createdAt')
  }, [assets, filters])

  // CRUD handlers
  const handleAssetDelete = useCallback((assetId: string, assetName: string) => {
    const asset = assets.find(a => a.id === assetId)
    setAssetToDelete({ id: assetId, name: assetName, projects: asset?.projects || [] })
  }, [assets])

  const handleAssetEdit = useCallback((assetId: string, currentName: string) => {
    setAssetToEdit({ id: assetId, name: currentName })
    setNewAssetName(currentName)
  }, [])

  const handleConfirmAssetDelete = useCallback(async () => {
    if (!assetToDelete) return
    try {
      await assetRepository.remove(toAssetUri(assetToDelete.id), { force: true })
      toast.success("Asset deleted successfully")
      await loadAssets()
      setAssetToDelete(null)
    } catch (error) {
      console.error("Failed to delete asset:", error)
      toast.error("Failed to delete asset")
    }
  }, [assetToDelete, loadAssets])

  const handleConfirmAssetEdit = useCallback(async () => {
    if (!assetToEdit || !newAssetName.trim()) return
    try {
      await assetRepository.rename(toAssetUri(assetToEdit.id), newAssetName.trim())
      toast.success("Asset renamed successfully")
      await loadAssets()
      setAssetToEdit(null)
      setNewAssetName("")
    } catch (error) {
      console.error("Failed to rename asset:", error)
      toast.error("Failed to rename asset")
    }
  }, [assetToEdit, newAssetName, loadAssets])

  const handleAssetDownload = useCallback(async (assetId: string, assetName: string) => {
    try {
      const resolved = await assetRepository.createObjectUrl(toAssetUri(assetId))

      const link = document.createElement('a')
      link.href = resolved.url
      link.download = assetName
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)

      setTimeout(resolved.release, 100)

      toast.success("Asset downloaded successfully")
    } catch (error) {
      console.error("Failed to download asset:", error)
      toast.error("Failed to download asset")
    }
  }, [])

  const handleUploadComplete = useCallback(async () => {
    await loadAssets()
    setUploadDialogOpen(false)
  }, [loadAssets])

  // Convert to ManagerCard format
  const assetCards: ManagerCard[] = useMemo(() => {
    const startIndex = (currentPage - 1) * itemsPerPage
    const endIndex = startIndex + itemsPerPage
    return filteredAssets.slice(startIndex, endIndex).map(asset => ({
      type: 'asset' as const,
      id: asset.id,
      name: asset.name,
      mimeType: asset.mimeType,
      size: asset.size,
      projects: asset.projects,
      createdAt: asset.createdAt,
      updatedAt: asset.createdAt,
      assetType: asset.type,
    }))
  }, [filteredAssets, currentPage, itemsPerPage])

  // Card actions
  const assetPrimaryActions: CardAction[] = useMemo(() => [
    {
      label: 'Download',
      icon: <Download className="h-4 w-4" />,
      onClick: (card) => handleAssetDownload(card.id, card.name),
    },
    {
      label: 'Rename',
      icon: <Edit className="h-4 w-4" />,
      onClick: (card) => handleAssetEdit(card.id, card.name),
    },
  ], [handleAssetDownload, handleAssetEdit])

  const assetSecondaryActions: CardAction[] = useMemo(() => [
    {
      label: 'Delete',
      icon: <Trash className="h-4 w-4" />,
      onClick: (card) => handleAssetDelete(card.id, card.name),
      variant: 'destructive' as const,
    },
  ], [handleAssetDelete])

  return {
    assetCards,
    assetPrimaryActions,
    assetSecondaryActions,
    filteredCount: filteredAssets.length,
    uploadDialogOpen,
    setUploadDialogOpen,
    assetToDelete,
    setAssetToDelete,
    assetToEdit,
    setAssetToEdit,
    newAssetName,
    setNewAssetName,
    handleConfirmAssetDelete,
    handleConfirmAssetEdit,
    handleUploadComplete,
  }
}

"use client"

import { useState, useEffect, useMemo, useCallback } from 'react'
import { Edit, Trash } from "lucide-react"
import { collectionRepository } from "@/components/block-content-editor/extras/code-studio/file-system/collection-repository"
import {
  applySorting,
  type ManagerCard,
  type CardAction,
  type FilterConfig,
} from "@/components/block-content-editor/extras/manager-page"
import { toast } from "sonner"
import { getDefaultBrowserAssetRepository } from "@game-guild/assets/browser"

const assetRepository = getDefaultBrowserAssetRepository()

interface CollectionItem {
  id: string
  name: string
  description?: string
  tags?: string[]
  fileCount: number
  totalSize: number
  created: string
  updated: string
}

interface UseCollectionManagerProps {
  isDbInitialized: boolean
  activeContext: 'projects' | 'assets' | 'collections'
  filters: FilterConfig
  currentPage: number
  itemsPerPage: number
}

export interface UseCollectionManagerReturn {
  collectionCards: ManagerCard[]
  collectionPrimaryActions: CardAction[]
  collectionSecondaryActions: CardAction[]
  filteredCount: number
  collectionToDelete: { id: string; name: string } | null
  setCollectionToDelete: (collection: { id: string; name: string } | null) => void
  collectionToEdit: { id: string; name: string } | null
  setCollectionToEdit: (collection: { id: string; name: string } | null) => void
  newCollectionName: string
  setNewCollectionName: (name: string) => void
  handleConfirmCollectionDelete: () => Promise<void>
  handleConfirmCollectionEdit: () => Promise<void>
}

// Helper functions for collection details
function countFilesInStructure(structure: any): number {
  let count = 0
  if (structure.files) count += structure.files.length
  if (structure.folders) {
    structure.folders.forEach((folder: any) => {
      count += countFilesInStructure(folder)
    })
  }
  return count
}

function calculateTotalSize(structure: any): number {
  let size = 0
  if (structure.files) {
    structure.files.forEach((file: any) => {
      size += file.size ?? 0
    })
  }
  if (structure.folders) {
    structure.folders.forEach((folder: any) => {
      size += calculateTotalSize(folder)
    })
  }
  return size
}

export function useCollectionManager({
  isDbInitialized,
  activeContext,
  filters,
  currentPage,
  itemsPerPage,
}: UseCollectionManagerProps): UseCollectionManagerReturn {
  const [collections, setCollections] = useState<CollectionItem[]>([])
  const [collectionToDelete, setCollectionToDelete] = useState<{ id: string; name: string } | null>(null)
  const [collectionToEdit, setCollectionToEdit] = useState<{ id: string; name: string } | null>(null)
  const [newCollectionName, setNewCollectionName] = useState("")

  const loadCollections = useCallback(async () => {
    try {
      const collectionList = await collectionRepository.list()

      const collectionsWithDetails = await Promise.all(
        collectionList.map(async (collection) => {
          try {
            const manifest = await collectionRepository.get(collection.id)
            if (manifest) {
              const fileCount = countFilesInStructure(manifest.structure)
              const totalSize = calculateTotalSize(manifest.structure)
              return {
                id: collection.id,
                name: collection.name,
                description: collection.description,
                tags: collection.tags,
                fileCount,
                totalSize,
                created: new Date(collection.created).toISOString(),
                updated: new Date(collection.updated).toISOString(),
              }
            }
          } catch (error) {
            console.error(`Failed to load manifest for collection ${collection.id}:`, error)
          }

          return {
            id: collection.id,
            name: collection.name,
            description: collection.description,
            tags: collection.tags,
            fileCount: 0,
            totalSize: 0,
            created: new Date(collection.created).toISOString(),
            updated: new Date(collection.updated).toISOString(),
          }
        })
      )

      setCollections(collectionsWithDetails)
    } catch (error) {
      console.error("Failed to load collections:", error)
      toast.error("Failed to load collections", {
        description: error instanceof Error ? error.message : "Unknown error"
      })
    }
  }, [])

  // Load collections when switching to collections context
  useEffect(() => {
    if (activeContext === 'collections' && isDbInitialized) {
      loadCollections()
    }
  }, [activeContext, isDbInitialized, loadCollections])

  // Filter and sort collections
  const filteredCollections = useMemo(() => {
    const filtered = collections.filter((collection) => {
      const matchesSearch = !filters.searchTerm ||
        collection.name.toLowerCase().includes(filters.searchTerm.toLowerCase()) ||
        (collection.description && collection.description.toLowerCase().includes(filters.searchTerm.toLowerCase()))

      const matchesTags = !filters.tags || filters.tags.length === 0 || (
        collection.tags && (
          filters.tagFilterMode === 'all'
            ? filters.tags.every(tag => collection.tags?.includes(tag))
            : filters.tags.some(tag => collection.tags?.includes(tag))
        )
      )

      return matchesSearch && matchesTags
    })

    return applySorting(filtered, filters.sortOrder || [], 'updated')
  }, [collections, filters])

  // CRUD handlers
  const handleCollectionDelete = useCallback((collectionId: string, collectionName: string) => {
    setCollectionToDelete({ id: collectionId, name: collectionName })
  }, [])

  const handleCollectionEdit = useCallback((collectionId: string, currentName: string) => {
    setCollectionToEdit({ id: collectionId, name: currentName })
    setNewCollectionName(currentName)
  }, [])

  const handleConfirmCollectionDelete = useCallback(async () => {
    if (!collectionToDelete) return
    try {
      await collectionRepository.remove(collectionToDelete.id)
      await assetRepository.reconcileUsage(
        { type: "code-studio-collection", id: collectionToDelete.id },
        [],
      )
      toast.success("Collection deleted successfully")
      await loadCollections()
      setCollectionToDelete(null)
    } catch (error) {
      console.error("Failed to delete collection:", error)
      toast.error("Failed to delete collection")
    }
  }, [collectionToDelete, loadCollections])

  const handleConfirmCollectionEdit = useCallback(async () => {
    if (!collectionToEdit || !newCollectionName.trim()) return
    try {
      const success = await collectionRepository.rename(collectionToEdit.id, newCollectionName.trim())
      if (success) {
        toast.success("Collection renamed successfully")
        await loadCollections()
        setCollectionToEdit(null)
        setNewCollectionName("")
      } else {
        toast.error("Failed to rename collection")
      }
    } catch (error) {
      console.error("Failed to rename collection:", error)
      toast.error("Failed to rename collection")
    }
  }, [collectionToEdit, newCollectionName, loadCollections])

  // Convert to ManagerCard format
  const collectionCards: ManagerCard[] = useMemo(() => {
    const startIndex = (currentPage - 1) * itemsPerPage
    const endIndex = startIndex + itemsPerPage
    return filteredCollections.slice(startIndex, endIndex).map(collection => ({
      type: 'collection' as const,
      id: collection.id,
      name: collection.name,
      description: collection.description,
      tags: collection.tags,
      fileCount: collection.fileCount,
      totalSize: collection.totalSize,
      createdAt: new Date(collection.created).toISOString(),
      updatedAt: new Date(collection.updated).toISOString(),
    }))
  }, [filteredCollections, currentPage, itemsPerPage])

  // Card actions
  const collectionPrimaryActions: CardAction[] = useMemo(() => [
    {
      label: 'Rename',
      icon: <Edit className="h-4 w-4" />,
      onClick: (card) => handleCollectionEdit(card.id, card.name),
    },
  ], [handleCollectionEdit])

  const collectionSecondaryActions: CardAction[] = useMemo(() => [
    {
      label: 'Delete',
      icon: <Trash className="h-4 w-4" />,
      onClick: (card) => handleCollectionDelete(card.id, card.name),
      variant: 'destructive' as const,
    },
  ], [handleCollectionDelete])

  return {
    collectionCards,
    collectionPrimaryActions,
    collectionSecondaryActions,
    filteredCount: filteredCollections.length,
    collectionToDelete,
    setCollectionToDelete,
    collectionToEdit,
    setCollectionToEdit,
    newCollectionName,
    setNewCollectionName,
    handleConfirmCollectionDelete,
    handleConfirmCollectionEdit,
  }
}

import { useState, useEffect } from "react"

/**
 * Hook para detectar se dark mode está ativado (Tailwind)
 * Similar ao comportamento do Tailwind CSS que verifica:
 * 1. Se a classe 'dark' existe no elemento html
 * 2. Se sistema operacional está em dark mode
 */
export function useDarkMode(): boolean {
  // Inicializa com o valor atual (SSR-safe)
  const [isDark, setIsDark] = useState<boolean>(() => {
    if (typeof document !== 'undefined') {
      return document.documentElement.classList.contains('dark')
    }
    return false
  })

  useEffect(() => {
    // Verifica o estado atual imediatamente
    const hasDarkClass = document.documentElement.classList.contains('dark')
    setIsDark(hasDarkClass)

    // Observer para mudanças de classe no elemento html (quando Tailwind muda o tema)
    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        if (mutation.type === 'attributes' && mutation.attributeName === 'class') {
          const hasDarkClass = document.documentElement.classList.contains('dark')
          setIsDark(hasDarkClass)
        }
      })
    })

    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['class'],
    })

    return () => {
      observer.disconnect()
    }
  }, [])

  return isDark
}

