import { useState, useEffect, useRef, useMemo, useCallback } from 'react'
import { EnhancedStorageAdapter } from "@/components/block-content-editor/lib/storage/editor/enhanced-storage-adapter"
import { getDefaultBrowserAssetRepository } from "@game-guild/assets/browser"
import type { ProjectData } from "@/components/block-content-editor/lib/storage/editor/project-data"
import type { ProjectPreferences } from "@/components/block-content-editor/lib/storage/editor/project-preferences"
import type { StorageType } from "@/components/block-content-editor/lib/storage/editor/storage-types"
import { toast } from "sonner"

const assetRepository = getDefaultBrowserAssetRepository()

export interface HomeStorageAdapter {
  load: (id: string) => Promise<ProjectData | null>
  list: () => Promise<ProjectData[]>
  delete: (id: string) => Promise<void>
  save: (id: string, name: string, data: string, tags: string[], storageType?: StorageType, preferences?: ProjectPreferences, type?: string, deps?: unknown, engine?: string) => Promise<void>
  searchProjects: (searchTerm: string, tags: string[], filterMode: "all" | "any", storageTypeFilter?: StorageType) => Promise<ProjectData[]>
}

import { generateProjectId } from "@/components/block-content-editor/lib/storage/editor/project-id"

export interface UseHomeStorageReturn {
  isDbInitialized: boolean
  availableTags: Array<{ name: string }>
  loadAvailableTags: () => Promise<void>
  storageAdapter: HomeStorageAdapter
  generateProjectId: () => string
}

export function useHomeStorage(): UseHomeStorageReturn {
  const [isDbInitialized, setIsDbInitialized] = useState(false)
  const [availableTags, setAvailableTags] = useState<Array<{ name: string }>>([])
  const dbStorage = useRef<EnhancedStorageAdapter>(new EnhancedStorageAdapter())

  const loadAvailableTags = useCallback(async () => {
    try {
      const tags = await dbStorage.current.getAllTags()
      setAvailableTags(tags)
    } catch (error) {
      console.error("Failed to load tags:", error)
    }
  }, [])

  // Initialize database
  useEffect(() => {
    const initializeDatabase = async () => {
      try {
        console.log("Initializing databases...")
        await dbStorage.current.init()
        await assetRepository.getStorageStatus()
        console.log("Databases initialized")
        setIsDbInitialized(true)
        await loadAvailableTags()
      } catch (error) {
        console.error("Failed to initialize database:", error)
        toast.error("Failed to initialize storage", {
          description: "Could not connect to local storage. Some features may not work.",
          duration: 5000,
        })
      }
    }

    initializeDatabase()
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const storageAdapter = useMemo<HomeStorageAdapter>(() => ({
    load: async (id: string): Promise<ProjectData | null> => {
      if (!isDbInitialized) throw new Error("Database not initialized")
      try {
        return await dbStorage.current.load(id)
      } catch (error) {
        console.error("Failed to load project:", error)
        return null
      }
    },

    list: async (): Promise<ProjectData[]> => {
      if (!isDbInitialized) return []
      try {
        return await dbStorage.current.list()
      } catch (error) {
        console.error("Failed to list projects:", error)
        return []
      }
    },

    delete: async (id: string): Promise<void> => {
      if (!isDbInitialized) throw new Error("Database not initialized")
      try {
        await dbStorage.current.delete(id)
      } catch (error) {
        console.error("Failed to delete project:", error)
        throw error
      }
    },

    save: async (id: string, name: string, data: string, tags: string[], storageType?: StorageType, preferences?: ProjectPreferences) => {
      if (!isDbInitialized) throw new Error("Database not initialized")
      try {
        await dbStorage.current.save(id, name, data, tags, storageType, preferences)
      } catch (error) {
        console.error("Failed to save project:", error)
        throw error
      }
    },

    searchProjects: async (searchTerm: string, tags: string[], filterMode: "all" | "any", storageTypeFilter?: StorageType): Promise<ProjectData[]> => {
      if (!isDbInitialized) return []
      try {
        return await dbStorage.current.searchProjects(searchTerm, tags, filterMode, storageTypeFilter)
      } catch (error) {
        console.error("Failed to search projects:", error)
        return []
      }
    },
  }), [isDbInitialized])

  return {
    isDbInitialized,
    availableTags,
    loadAvailableTags,
    storageAdapter,
    generateProjectId,
  }
}

"use client"

import { useCallback, useState } from "react"
import { toast } from "sonner"
import { deserializeProject, serializeProject } from "@/components/block-content-editor/lib/storage/editor/block-storage"
import type { UseProjectStorageReturn } from "./useProjectStorage"

export interface UseProjectHistoryReturn {
  isViewingHistory: boolean
  currentViewingSha: string | null
  loadCommit(sha: string): Promise<void>
  loadSnapshot(tag: string): Promise<void>
  returnToHead(): Promise<void>
}

export function useProjectHistory(project: UseProjectStorageReturn): UseProjectHistoryReturn {
  const [isViewingHistory, setIsViewingHistory] = useState(false)
  const [currentViewingSha, setCurrentViewingSha] = useState<string | null>(null)
  const [headProjectData, setHeadProjectData] = useState<string | null>(null)

  // ── Load commit ──

  const loadCommit = useCallback(async (sha: string) => {
    if (!project.projectId) return

    try {
      const history = await project.db.listHistory(project.projectId)
      const isHead = history.length > 0 && history[0]?.sha === sha

      // If loading HEAD, return to normal editing mode
      if (isHead) {
        if (isViewingHistory && headProjectData) {
          project.setBlocks(deserializeProject(headProjectData))
        }
        setIsViewingHistory(false)
        setCurrentViewingSha(null)
        setHeadProjectData(null)
        toast.success("Viewing latest version", {
          description: "You can edit the project",
          duration: 2000,
          icon: "✏️",
        })
        return
      }

      // Preserve HEAD data before switching to history
      if (!isViewingHistory) {
        setHeadProjectData(serializeProject(project.blocks))
      }

      // Load the commit
      const commitData = await project.db.loadFromHistory(project.projectId, sha)
      if (!commitData) {
        toast.error("Failed to load commit", {
          description: "The historical version could not be found",
          duration: 3000,
        })
        return
      }

      if (!commitData.data) {
        toast.error("Invalid historical data", {
          description: "This commit contains incomplete data. It may be from an older version.",
          duration: 4000,
        })
        return
      }

      project.setBlocks(deserializeProject(commitData.data))

      setIsViewingHistory(true)
      setCurrentViewingSha(sha)

      toast.info("Viewing historical version", {
        description: "This is read-only. Return to latest to edit.",
        duration: 3000,
        icon: "📜",
      })
    } catch (error) {
      console.error("Failed to load commit:", error)
      toast.error("Failed to load historical version", {
        description: error instanceof Error ? error.message : "Unknown error",
        duration: 4000,
      })
    }
  }, [project, isViewingHistory, headProjectData])

  // ── Load snapshot ──

  const loadSnapshot = useCallback(async (tag: string) => {
    if (!project.projectId) return

    if (!isViewingHistory) {
      setHeadProjectData(serializeProject(project.blocks))
    }

    const snapshots = await project.db.listSnapshots(project.projectId)
    const snapshot = snapshots.find((s: any) => s.tag === tag)
    if (snapshot) await loadCommit(snapshot.sha)
  }, [project, isViewingHistory, loadCommit])

  // ── Return to HEAD ──

  const returnToHead = useCallback(async () => {
    if (!project.projectId || !headProjectData) return

    project.setBlocks(deserializeProject(headProjectData))
    setIsViewingHistory(false)
    setCurrentViewingSha(null)
    setHeadProjectData(null)

    toast.success("Returned to latest version", {
      description: "You can now edit the project",
      duration: 2000,
      icon: "✏️",
    })
  }, [project, headProjectData])

  return {
    isViewingHistory,
    currentViewingSha,
    loadCommit,
    loadSnapshot,
    returnToHead,
  }
}

"use client"

import React, { useState, useEffect, useMemo, useCallback } from 'react'
import { Eye, Blocks, Download, Trash, Info } from "lucide-react"
import type { StorageType } from "@/components/block-content-editor/lib/storage/editor/storage-types"
import type { ProjectPreferences } from "@/components/block-content-editor/lib/storage/editor/project-preferences"
import { useProjectDialog } from "@/components/block-content-editor/hooks/editor/use-project-dialog"
import { useProjectActions } from "@/components/block-content-editor/hooks/editor/use-project-actions"
import {
  applySorting,
  type ManagerCard,
  type CardAction,
  type FilterConfig,
} from "@/components/block-content-editor/extras/manager-page"
import { toast } from "sonner"
import type { HomeStorageAdapter } from "./useHomeStorage"
import type { ProjectData } from "@/components/block-content-editor/lib/storage/editor/project-data"
// Engine removed: all projects use the unified Blocks engine.

interface UseProjectManagerProps {
  isDbInitialized: boolean
  storageAdapter: HomeStorageAdapter
  availableTags: Array<{ name: string }>
  loadAvailableTags: () => Promise<void>
  filters: FilterConfig
  currentPage: number
  itemsPerPage: number
}

export interface UseProjectManagerReturn {
  projectCards: ManagerCard[]
  projectPrimaryActions: CardAction[]
  projectSecondaryActions: CardAction[]
  projectActions: ReturnType<typeof useProjectActions>
  filteredCount: number
  additionalFilteredProjects: ProjectData[]
  createDialogOpen: boolean
  setCreateDialogOpen: (open: boolean) => void
  handleCreateNewProject: () => void
  handleProjectCreate: (projectData: { id: string; name: string; tags: string[]; storageType: StorageType }) => void
  refreshProjects: () => Promise<void>
}

export function useProjectManager({
  isDbInitialized,
  storageAdapter,
  availableTags,
  loadAvailableTags,
  filters,
  currentPage,
  itemsPerPage,
}: UseProjectManagerProps): UseProjectManagerReturn {
  // New project dialog state
  const [createDialogOpen, setCreateDialogOpen] = useState(false)

  // Use the project dialog hook
  const {
    searchTerm,
    setSearchTerm,
    selectedTags,
    setSelectedTags,
    storageTypeFilter,
    setStorageTypeFilter,
    filteredProjects,
    tagFilterMode,
    setTagFilterMode,
    loadProject,
    refreshProjects,
  } = useProjectDialog({
    isDbInitialized,
    storageAdapter,
  })

  // Sync filters with useProjectDialog state
  useEffect(() => {
    if (filters.searchTerm !== searchTerm) setSearchTerm(filters.searchTerm)
  }, [filters.searchTerm, searchTerm, setSearchTerm])

  useEffect(() => {
    if (JSON.stringify(filters.tags) !== JSON.stringify(selectedTags)) {
      setSelectedTags(filters.tags || [])
    }
  }, [filters.tags, selectedTags, setSelectedTags])

  useEffect(() => {
    const storageType = filters.storageType === 'all' ? undefined : filters.storageType
    if (storageType !== storageTypeFilter) {
      setStorageTypeFilter(storageType)
    }
  }, [filters.storageType, storageTypeFilter, setStorageTypeFilter])

  useEffect(() => {
    if (filters.tagFilterMode && filters.tagFilterMode !== tagFilterMode) {
      setTagFilterMode(filters.tagFilterMode)
    }
  }, [filters.tagFilterMode, tagFilterMode, setTagFilterMode])

  const updateProjectsList = useCallback(async () => {
    await refreshProjects()
    await loadAvailableTags()
  }, [refreshProjects, loadAvailableTags])

  const projectActions = useProjectActions({
    storageAdapter,
    onProjectsListUpdate: updateProjectsList,
    onProjectUpdate: updateProjectsList,
  })

  // Filter and sort projects
  const additionalFilteredProjects = useMemo(() => {
    return applySorting(filteredProjects, filters.sortOrder || [], 'updatedAt')
  }, [filteredProjects, filters.sortOrder])

  // Navigation handlers
  const handleProjectOpen = useCallback(async (projectId: string, event?: React.MouseEvent) => {
    try {
      toast.loading("Loading project...", { id: `loading-${projectId}` })
      const projectData = await loadProject(projectId)
      if (projectData) {
        toast.success("Redirecting to Studio...", { id: `loading-${projectId}`, duration: 1000 })
        setTimeout(() => {
          const url = `/block-content-editor/studio#${projectId}`
          if (event?.ctrlKey || event?.metaKey) {
            window.open(url, '_blank')
          } else {
            window.location.href = url
          }
        }, 500)
      }
    } catch (error) {
      toast.error("Error loading project", { id: `loading-${projectId}`, description: "Could not load the project" })
    }
  }, [loadProject])

  const handleProjectView = useCallback(async (projectId: string, event?: React.MouseEvent) => {
    try {
      toast.loading("Loading project...", { id: `loading-view-${projectId}` })
      const projectData = await loadProject(projectId)
      if (projectData) {
        toast.success("Redirecting to Viewer...", { id: `loading-view-${projectId}`, duration: 1000 })
        setTimeout(() => {
          const url = `/block-content-editor/viewer#${projectId}`
          if (event?.ctrlKey || event?.metaKey) {
            window.open(url, '_blank')
          } else {
            window.location.href = url
          }
        }, 500)
      }
    } catch (error) {
      toast.error("Error loading project", { id: `loading-view-${projectId}`, description: "Could not load the project" })
    }
  }, [loadProject])

  const handleProjectDownload = useCallback((
    projectId: string,
    projectName: string,
    projectData: string,
    projectTags: string[],
    createdAt: string,
    updatedAt: string,
    projectPreferences?: ProjectPreferences
  ) => {
    projectActions.handleDownload(projectId, projectName, projectData, projectTags, createdAt, updatedAt, projectPreferences)
  }, [projectActions])

  // Convert to ManagerCard format
  const projectCards: ManagerCard[] = useMemo(() => {
    const startIndex = (currentPage - 1) * itemsPerPage
    const endIndex = startIndex + itemsPerPage
    return additionalFilteredProjects.slice(startIndex, endIndex).map(project => ({
      type: 'project' as const,
      id: project.id,
      name: project.name,
      tags: project.tags,
      size: project.metadata.size,
      data: project.data,
      storageType: project.storageType,
      createdAt: project.metadata.createdAt,
      updatedAt: project.metadata.updatedAt,
      projectType: project.preferences?.global?.projectType ?? 'general',
    }))
  }, [additionalFilteredProjects, currentPage, itemsPerPage])

  // Card actions
  const projectPrimaryActions: CardAction[] = useMemo(() => [
    {
      label: 'Open in Studio',
      icon: <Blocks className="h-4 w-4" />,
      onClick: (card) => handleProjectOpen(card.id),
    },
    {
      label: 'View',
      icon: <Eye className="h-4 w-4" />,
      onClick: (card) => handleProjectView(card.id),
    },
    {
      label: 'Information',
      icon: <Info className="h-4 w-4" />,
      onClick: async (card) => {
        const projectData = await loadProject(card.id)
        if (projectData) {
          projectActions.handleOpenInfo(projectData)
        }
      },
    },
  ], [handleProjectOpen, handleProjectView, loadProject, projectActions])

  const projectSecondaryActions: CardAction[] = useMemo(() => [
    {
      label: 'Download',
      icon: <Download className="h-4 w-4" />,
      onClick: (card) => {
        if (card.type === 'project') {
          handleProjectDownload(card.id, card.name, card.data, card.tags, card.createdAt, card.updatedAt)
        }
      },
    },
    {
      label: 'Delete',
      icon: <Trash className="h-4 w-4" />,
      onClick: (card) => projectActions.handleConfirmDelete(card.id, card.name),
      variant: 'destructive' as const,
    },
  ], [handleProjectDownload, projectActions])

  // New project handlers
  const handleCreateNewProject = useCallback(() => {
    setCreateDialogOpen(true)
  }, [])

  const handleProjectCreate = useCallback((projectData: { id: string; name: string; tags: string[]; storageType: StorageType }) => {
    // Navigate to studio with the newly created project's ID
    window.location.href = `/block-content-editor/studio#${projectData.id}`
  }, [])

  return {
    projectCards,
    projectPrimaryActions,
    projectSecondaryActions,
    projectActions,
    filteredCount: additionalFilteredProjects.length,
    additionalFilteredProjects,
    createDialogOpen,
    setCreateDialogOpen,
    handleCreateNewProject,
    handleProjectCreate,
    refreshProjects,
  }
}

"use client"

/**
 * useProjectStorage
 *
 * The main editor hook. Composes the focused sub-hooks under `hooks/editor/`
 * to expose a flat surface to the editor page. Owns only the cross-cutting
 * concerns that don't fit a single sub-hook:
 *
 *   1. The `storageAdapter` — a thin wrapper around the raw DB that gates
 *      every operation on `isDbInitialized`.
 *   2. The URL-hash bootstrap — when `window.location.hash` is a project id,
 *      load it as soon as the DB is ready.
 *   3. The auto-save effect — debounced, gated by `readOnlyRef.current`.
 *
 * Sub-hooks:
 *   - {@link useProjectDbInit}    DB singleton + init + readOnlyRef
 *   - {@link useProjectState}     id/name/tags/blocks/preferences state
 *   - {@link useProjectLists}     savedProjects / availableTags + refresh
 *   - {@link useProjectSizes}     projectSize / assetsSize / assets
 *   - {@link useProjectSync}      syncStats + autoSaveEnabled
 *   - {@link useProjectOperations} save / saveAs / load / create / title / snapshot
 *
 * See `docs/DATA-FLOW.md` ("Editor Flow — Write Path").
 */

import { useCallback, useEffect, useMemo, type Dispatch, type SetStateAction } from "react"
import { toast } from "sonner"
import {
  EnhancedStorageAdapter,
  type ProjectPreferences,
} from "@/components/block-content-editor/lib/storage/editor/enhanced-storage-adapter"
import { serializeProject } from "@/components/block-content-editor/lib/storage/editor/block-storage"

import type { BlockArray, BlockCellType } from "@/components/block-content-editor/lib/storage/editor/block-structure"
import type { ProjectType } from "@/components/block-content-editor/lib/storage/editor/project-types"
import type { StorageType } from "@/components/block-content-editor/lib/storage/editor/storage-types"
import type { SyncStats } from "@/components/block-content-editor/lib/sync/editor/sync-types"
import { checkSelectedProject as checkProject } from "@/components/block-content-editor/extras/editor/project-load-operations"

import { useProjectDbInit } from "./editor/useProjectDbInit"
import { useProjectState } from "./editor/useProjectState"
import { useProjectLists } from "./editor/useProjectLists"
import { useProjectSizes, type ProjectAsset } from "./editor/useProjectSizes"
import { useProjectSync } from "./editor/useProjectSync"
import { useProjectOperations } from "./editor/useProjectOperations"

// ─── Types ───────────────────────────────────────────────────────────────────

export type { ProjectData } from "@/components/block-content-editor/lib/storage/editor/project-data"
import type { ProjectData, ProjectMetadata } from "@/components/block-content-editor/lib/storage/editor/project-data"

export interface StorageAdapterInterface {
  save: (id: string, name: string, data: string, tags?: string[], storageType?: StorageType, preferences?: ProjectPreferences) => Promise<void>
  load: (id: string) => Promise<ProjectData | null>
  delete: (id: string) => Promise<void>
  list: () => Promise<ProjectData[]>
  getProjectInfo: (id: string) => Promise<Pick<ProjectMetadata, "size" | "createdAt" | "updatedAt"> | null>
  searchProjects: (searchTerm: string, tags: string[], filterMode?: "all" | "any", storageTypeFilter?: StorageType) => Promise<ProjectData[]>
}

export interface CreateProjectInput {
  id: string
  name: string
  tags: string[]
  storageType: StorageType
  preferences?: ProjectPreferences
}

export interface ProjectStorageDefaults {
  /** Refuse to hash-load projects whose type isn't allowed by the current page. */
  allowedProjectTypes?: ProjectType[]
  /**
   * Page-declared structural defaults. Used to fill the new project's
   * preferences on Save As when the current project has none (e.g. saving
   * from a fresh untouched editor).
   */
  projectType?: ProjectType
  singleBlockMode?: boolean
  allowedBlockTypes?: BlockCellType[]
}

export interface UseProjectStorageReturn {
  // Status
  isDbInitialized: boolean
  isFirstTime: boolean

  // Project metadata
  projectId: string
  projectName: string
  setProjectName: Dispatch<SetStateAction<string>>
  storageType: StorageType
  tags: string[]
  setTags: Dispatch<SetStateAction<string[]>>
  preferences: ProjectPreferences | undefined
  setPreferences: (p: ProjectPreferences) => void

  // Editor content
  blocks: BlockArray
  setBlocks: Dispatch<SetStateAction<BlockArray>>

  // Operations
  save(): Promise<{ needsSaveAs: boolean }>
  saveAs(name: string, storageOption: StorageType, tags?: string[]): Promise<void>
  loadProject(projectData: ProjectData): void
  createProject(projectData: CreateProjectInput): void

  // Title
  titleEdit(setEditingProjectName: (n: string) => void, setIsEditingTitle: (b: boolean) => void): void
  titleSave(editingName: string, setEditingProjectName: (n: string) => void, setIsEditingTitle: (b: boolean) => void): Promise<void>

  // Snapshot
  createSnapshot(name?: string): Promise<void>

  // ID generation
  generateProjectId(): string

  // Lists
  savedProjects: ProjectData[]
  availableTags: Array<{ name: string; usageCount: number }>
  refreshProjects(): Promise<void>
  refreshTags(): Promise<void>

  // Size
  projectSize: number
  assetsSize: number
  assets: ProjectAsset[]

  // Sync
  syncStats: SyncStats | null

  // Auto-save
  autoSaveEnabled: boolean
  setAutoSaveEnabled: Dispatch<SetStateAction<boolean>>
  lastProjectLoadTime: number

  // Direct DB access (for history hook, import dialog, etc.)
  db: EnhancedStorageAdapter

  // Storage adapter (for components that need it)
  storageAdapter: StorageAdapterInterface

  // Read-only gate (set by page when viewing history — suppresses auto-save)
  readOnlyRef: React.MutableRefObject<boolean>
}

// ─── Hook ────────────────────────────────────────────────────────────────────

export function useProjectStorage(initialDefaults?: ProjectStorageDefaults): UseProjectStorageReturn {
  const { db, isDbInitialized, readOnlyRef } = useProjectDbInit()
  const state = useProjectState()
  const lists = useProjectLists(db, isDbInitialized)
  const sizes = useProjectSizes(state.blocks, state.projectId, isDbInitialized, db)
  const sync = useProjectSync(db, isDbInitialized)

  // ─── Storage adapter (gated wrapper around the raw DB) ───────────────────

  const storageAdapter: StorageAdapterInterface = useMemo(() => ({
    save: async (id, name, data, tags = [], storageType = "local", preferences?) => {
      if (!id || !name || !data) { console.warn("Invalid id, name or data"); return }
      if (!isDbInitialized) throw new Error("Database not initialized")
      try { await db.save(id, name, data, tags, storageType, preferences) }
      catch (error) { console.error("Failed to save project:", error); throw error }
    },
    load: async (id) => {
      if (!isDbInitialized) throw new Error("Database not initialized")
      try { return await db.load(id) }
      catch (error) { console.error("Failed to load project:", error); return null }
    },
    delete: async (id) => {
      if (!isDbInitialized) throw new Error("Database not initialized")
      try { await db.delete(id) }
      catch (error) { console.error("Failed to delete project:", error); throw error }
    },
    list: async () => {
      if (!isDbInitialized) return []
      try { return await db.list() }
      catch (error) { console.error("Failed to list projects:", error); return [] }
    },
    getProjectInfo: async (id) => {
      if (!isDbInitialized) return null
      try { return await db.getProjectInfo(id) }
      catch (error) { console.error("Failed to get project info:", error); return null }
    },
    searchProjects: async (searchTerm, tags, filterMode = "any", storageTypeFilter?) => {
      if (!isDbInitialized) return []
      try { return await db.searchProjects(searchTerm, tags, filterMode, storageTypeFilter) }
      catch (error) { console.error("Failed to search projects:", error); return [] }
    },
  }), [db, isDbInitialized])

  const operations = useProjectOperations({
    state,
    storageAdapter,
    db,
    refreshProjects: lists.refreshProjects,
    recalcAssets: sizes.recalcAssets,
    defaults: {
      projectType: initialDefaults?.projectType,
      singleBlockMode: initialDefaults?.singleBlockMode,
      allowedBlockTypes: initialDefaults?.allowedBlockTypes,
    },
  })

  // ─── URL hash bootstrap — load project from #hash on DB init ─────────────

  useEffect(() => {
    if (!isDbInitialized) return
    checkProject({
      storageAdapter,
      directDbLoad: (id: string) => db.load(id),
      setCurrentProjectId: state.setProjectId,
      setCurrentProjectName: state.setProjectName,
      setCurrentProjectStorageType: state.setStorageType,
      setProjectTags: state.setTags,
      setIsFirstTime: state.setIsFirstTime,
      setLastProjectLoadTime: state.setLastProjectLoadTime,
      setCurrentProjectPreferences: state.setPreferences,
      setBlocks: state.setBlocks,
      allowedProjectTypes: initialDefaults?.allowedProjectTypes,
    })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isDbInitialized])

  // ─── Auto-save effect — debounced, gated by readOnlyRef ──────────────────

  useEffect(() => {
    if (!sync.autoSaveEnabled || !state.projectId || !isDbInitialized || readOnlyRef.current) return
    if (state.blocks.length === 0) return

    const timeSinceLoad = Date.now() - state.lastProjectLoadTime
    if (timeSinceLoad < 1000) return

    const autoSaveTimer = setTimeout(async () => {
      try {
        const dataToSave = serializeProject(state.blocks)
        await storageAdapter.save(
          state.projectId, state.projectName, dataToSave, state.tags,
          state.storageType, state.preferences,
        )
        toast.success("Auto-saved", {
          description: "Changes saved automatically", duration: 1500, icon: "💾",
          style: { opacity: 0.8, fontSize: "0.875rem" },
        })
      } catch (error) {
        console.error("Auto-save failed:", error)
        toast.error("Auto-save failed", { description: "Save manually to ensure", duration: 2000, icon: "⚠️" })
      }
    }, 2000)

    return () => clearTimeout(autoSaveTimer)
  }, [
    state.blocks, sync.autoSaveEnabled, state.projectId, state.projectName,
    state.tags, isDbInitialized, state.storageType, state.lastProjectLoadTime,
    state.preferences, storageAdapter, readOnlyRef,
  ])

  // ─── Setter adapter — preferences needs (p) => void, state has Dispatch ──

  const setPreferences = useCallback((p: ProjectPreferences) => {
    state.setPreferences(p)
  }, [state])

  // ─── Flat return ─────────────────────────────────────────────────────────

  return {
    // Status
    isDbInitialized,
    isFirstTime: state.isFirstTime,

    // Project metadata
    projectId: state.projectId,
    projectName: state.projectName,
    setProjectName: state.setProjectName,
    storageType: state.storageType,
    tags: state.tags,
    setTags: state.setTags,
    preferences: state.preferences,
    setPreferences,

    // Editor content
    blocks: state.blocks,
    setBlocks: state.setBlocks,

    // Operations
    save: operations.save,
    saveAs: operations.saveAs,
    loadProject: operations.loadProject,
    createProject: operations.createProject,

    // Title
    titleEdit: operations.titleEdit,
    titleSave: operations.titleSave,

    // Snapshot
    createSnapshot: operations.createSnapshot,

    // ID generation
    generateProjectId: operations.generateProjectId,

    // Lists
    savedProjects: lists.savedProjects,
    availableTags: lists.availableTags,
    refreshProjects: lists.refreshProjects,
    refreshTags: lists.refreshTags,

    // Size
    projectSize: sizes.projectSize,
    assetsSize: sizes.assetsSize,
    assets: sizes.assets,

    // Sync
    syncStats: sync.syncStats,

    // Auto-save
    autoSaveEnabled: sync.autoSaveEnabled,
    setAutoSaveEnabled: sync.setAutoSaveEnabled,
    lastProjectLoadTime: state.lastProjectLoadTime,

    // Direct DB access
    db,

    // Storage adapter
    storageAdapter,

    // Read-only gate
    readOnlyRef,
  }
}

"use client"

import { useEffect, useMemo, useRef, useState } from "react"
import { toast } from "sonner"
import { EnhancedStorageAdapter } from "@/components/block-content-editor/lib/storage/editor/enhanced-storage-adapter"
import { deserializeProject } from "@/components/block-content-editor/lib/storage/editor/block-storage"
import { checkSelectedProject as checkProjectPreview } from "@/components/block-content-editor/extras/preview/preview-load-operations"
import type { ProjectData } from "@/components/block-content-editor/extras/preview/preview-load-operations"
import type { BlockArray } from "@/components/block-content-editor/lib/storage/editor/block-structure"
import type { StorageType } from "@/components/block-content-editor/lib/storage/editor/storage-types"

export interface UseViewerStorageReturn {
  currentProject: ProjectData | null
  setCurrentProject: (project: ProjectData | null) => void
  isDbInitialized: boolean
  availableTags: Array<{ name: string; usageCount: number }>
  storageAdapter: {
    load: (id: string) => Promise<ProjectData | null>
    list: () => Promise<ProjectData[]>
    searchProjects: (
      searchTerm: string,
      tags: string[],
      filterMode?: "all" | "any",
      storageTypeFilter?: StorageType,
    ) => Promise<ProjectData[]>
  }
  loadProject: (projectData: ProjectData) => void
  blocks: BlockArray
}

export function useViewerStorage(): UseViewerStorageReturn {
  const [currentProject, setCurrentProject] = useState<ProjectData | null>(null)
  const [availableTags, setAvailableTags] = useState<Array<{ name: string; usageCount: number }>>([])
  const [isDbInitialized, setIsDbInitialized] = useState(false)

  const dbStorage = useRef<EnhancedStorageAdapter>(new EnhancedStorageAdapter())

  const storageAdapter = {
    load: async (id: string): Promise<ProjectData | null> => {
      if (!isDbInitialized) throw new Error("Database not initialized")
      try {
        return await dbStorage.current.load(id)
      } catch (error) {
        console.error("Failed to load project:", error)
        return null
      }
    },
    list: async (): Promise<ProjectData[]> => {
      if (!isDbInitialized) return []
      try { return await dbStorage.current.list() }
      catch (error) { console.error("Failed to list projects:", error); return [] }
    },
    searchProjects: async (
      searchTerm: string,
      tags: string[],
      filterMode?: "all" | "any",
      storageTypeFilter?: StorageType,
    ): Promise<ProjectData[]> => {
      if (!isDbInitialized) return []
      try { return await dbStorage.current.searchProjects(searchTerm, tags, filterMode || "any", storageTypeFilter) }
      catch (error) { console.error("Failed to search projects:", error); return [] }
    },
  }

  useEffect(() => {
    const initDB = async () => {
      try {
        await dbStorage.current.init()
        setIsDbInitialized(true)

        try {
          const tags = await dbStorage.current.getAllTags()
          setAvailableTags(tags)
        } catch (error) {
          console.error("Failed to load tags:", error)
        }

        await checkProjectPreview({
          storageAdapter: { load: (id: string) => dbStorage.current.load(id) },
          setCurrentProject,
        })
      } catch (error) {
        console.error("Failed to initialize IndexedDB:", error)
        toast.error("Storage error", {
          description: "Could not initialize database. Some features may not work.",
          duration: 5000, icon: "⚠️",
        })
      }
    }
    initDB()
  }, [])

  const loadProject = (projectData: ProjectData) => {
    setCurrentProject(projectData)
    window.history.pushState(null, "", `#${projectData.id}`)
  }

  const blocks = useMemo<BlockArray>(() => {
    if (!currentProject) return []
    return deserializeProject(currentProject.data)
  }, [currentProject])

  return {
    currentProject,
    setCurrentProject,
    isDbInitialized,
    availableTags,
    storageAdapter,
    loadProject,
    blocks,
  }
}

import { assertSafeServiceUrl } from "@/lib/security/safe-remote-url"
import { syncConfig } from "../../sync/editor/sync-config"
import type { ProjectData, ProjectMetadataRecord } from "../../storage/editor/project-data"

interface SyncResponse {
  success: boolean
  message?: string
  data?: any
}

interface TagData {
  id: string
  name: string
  projectIds: string[]
}

interface ApiConfig {
  baseUrl: string
  timeout: number
  retries: number
}

export class ApiClient {
  private config: ApiConfig
  private isOnline: boolean = typeof window !== "undefined" ? navigator.onLine : true

  constructor(config: Partial<ApiConfig> = {}) {
    const syncConfigData = syncConfig.getConfig()

    this.config = {
      baseUrl: syncConfigData.serverUrl,
      timeout: syncConfigData.timeout,
      retries: syncConfigData.retries,
      ...config,
    }

    if (typeof window !== "undefined") {
      // Monitor online status
      window.addEventListener("online", () => {
        this.isOnline = true
        if (syncConfigData.debugMode) {
          console.log("API Client: Back online")
        }
      })

      window.addEventListener("offline", () => {
        this.isOnline = false
        if (syncConfigData.debugMode) {
          console.log("API Client: Gone offline")
        }
      })
    }

    // Listen for config changes
    syncConfig.onConfigChange((newConfig) => {
      this.config.baseUrl = newConfig.serverUrl
      this.config.timeout = newConfig.timeout
      this.config.retries = newConfig.retries

      if (newConfig.debugMode) {
        console.log("API Client config updated:", this.config)
      }
    })
  }

  private async fetchWithRetry(
    url: string,
    options: RequestInit = {},
    retries: number = this.config.retries,
  ): Promise<Response> {
    const syncConfigData = syncConfig.getConfig()

    if (!syncConfig.isEnabled()) {
      throw new Error("Sync is disabled")
    }

    if (!this.isOnline) {
      throw new Error("No internet connection")
    }

    const controller = new AbortController()
    const timeoutId = setTimeout(() => controller.abort(), this.config.timeout)

    try {
      const response = await fetch(assertSafeServiceUrl(`${this.config.baseUrl}${url}`, this.config.baseUrl), {
        ...options,
        redirect: "error",
        signal: controller.signal,
        headers: {
          "Content-Type": "application/json",
          ...options.headers,
        },
      })

      clearTimeout(timeoutId)

      if (!response.ok) {
        // Check if response has content before trying to parse JSON
        let errorMessage = `HTTP ${response.status}: ${response.statusText}`

        try {
          const contentType = response.headers.get("content-type")
          if (contentType && contentType.includes("application/json")) {
            const errorData = await response.json()
            errorMessage = errorData.message || errorMessage
          }
        } catch (parseError) {
          // Ignore JSON parse errors for error responses
          if (syncConfigData.debugMode) {
            console.warn("Failed to parse error response as JSON:", parseError)
          }
        }

        throw new Error(errorMessage)
      }

      return response
    } catch (error) {
      clearTimeout(timeoutId)

      if (
        retries > 0 &&
        typeof error === "object" &&
        error !== null &&
        "name" in error &&
        (error as { name?: string }).name !== "AbortError"
      ) {
        if (syncConfigData.debugMode) {
          console.log(`API retry ${this.config.retries - retries + 1}/${this.config.retries} for ${url}`)
        }
        await new Promise((resolve) => setTimeout(resolve, 1000 * (this.config.retries - retries + 1)))
        return this.fetchWithRetry(url, options, retries - 1)
      }

      throw error
    }
  }

  async getProjectsMetadata(): Promise<ProjectMetadataRecord[]> {
    if (!syncConfig.isEnabled()) {
      return []
    }

    try {
      const response = await this.fetchWithRetry("/projects/metadata")

      // Check if response has content
      const contentType = response.headers.get("content-type")
      if (!contentType || !contentType.includes("application/json")) {
        throw new Error("Server returned non-JSON response")
      }

      const text = await response.text()
      if (!text.trim()) {
        throw new Error("Server returned empty response")
      }

      const data = JSON.parse(text)
      return data.projects || []
    } catch (error) {
      const syncConfigData = syncConfig.getConfig()

      if (syncConfigData.debugMode) {
        console.warn(
          "⚠️ Sync Warning: Failed to fetch projects metadata:",
          (error instanceof Error ? error.message : String(error))
        )
      } else {
        console.warn("Sync: Server unavailable for metadata fetch")
      }

      return []
    }
  }

  async getProject(id: string): Promise<ProjectData | null> {
    if (!syncConfig.isEnabled()) {
      return null
    }

    try {
      const response = await this.fetchWithRetry(`/projects/${id}`)

      const contentType = response.headers.get("content-type")
      if (!contentType || !contentType.includes("application/json")) {
        throw new Error("Server returned non-JSON response")
      }

      const text = await response.text()
      if (!text.trim()) {
        throw new Error("Server returned empty response")
      }

      const data = JSON.parse(text)
      return data.project || null
    } catch (error) {
      const syncConfigData = syncConfig.getConfig()

      if (syncConfigData.debugMode) {
        console.warn(
          `⚠️ Sync Warning: Failed to fetch project ${id}:`,
          error instanceof Error ? error.message : String(error)
        )
      }

      return null
    }
  }

  async createProject(project: ProjectData): Promise<SyncResponse> {
    if (!syncConfig.isEnabled()) {
      return { success: false, message: "Sync is disabled" }
    }

    try {
      const response = await this.fetchWithRetry("/projects", {
        method: "POST",
        body: JSON.stringify(project),
      })

      const data = await response.json()
      return { success: true, data }
    } catch (error) {
      const syncConfigData = syncConfig.getConfig()

      if (syncConfigData.debugMode) {
        console.warn(
          "⚠️ Sync Warning: Failed to create project:",
          error instanceof Error ? error.message : String(error)
        )
      }

      return { success: false, message: error instanceof Error ? error.message : String(error) }
    }
  }

  async updateProject(project: ProjectData): Promise<SyncResponse> {
    if (!syncConfig.isEnabled()) {
      return { success: false, message: "Sync is disabled" }
    }

    try {
      const response = await this.fetchWithRetry(`/projects/${project.id}`, {
        method: "PUT",
        body: JSON.stringify(project),
      })

      const data = await response.json()
      return { success: true, data }
    } catch (error) {
      const syncConfigData = syncConfig.getConfig()

      if (syncConfigData.debugMode) {
        console.warn(
          "⚠️ Sync Warning: Failed to update project:",
          error instanceof Error ? error.message : String(error)
        )
      }

      return { success: false, message: error instanceof Error ? error.message : String(error) }
    }
  }

  async syncTags(tags: Omit<TagData, "projectIds">[]): Promise<SyncResponse> {
    if (!syncConfig.isEnabled()) {
      return { success: false, message: "Sync is disabled" }
    }

    try {
      const response = await this.fetchWithRetry("/tags/sync", {
        method: "POST",
        body: JSON.stringify({ tags }),
      })

      const data = await response.json()
      return { success: true, data }
    } catch (error) {
      const syncConfigData = syncConfig.getConfig()

      if (syncConfigData.debugMode) {
        console.warn(
          "⚠️ Sync Warning: Failed to sync tags:",
          error instanceof Error ? error.message : String(error),
        )
      }

      return { success: false, message: error instanceof Error ? error.message : String(error) }
    }
  }

  async deleteProject(id: string): Promise<SyncResponse> {
    if (!syncConfig.isEnabled()) {
      return { success: false, message: "Sync is disabled" }
    }

    try {
      const response = await this.fetchWithRetry(`/projects/${id}`, {
        method: "DELETE",
      })

      const data = await response.json()
      return { success: true, data }
    } catch (error) {
      const syncConfigData = syncConfig.getConfig()

      if (syncConfigData.debugMode) {
        console.warn(
          "⚠️ Sync Warning: Failed to delete project:",
          error instanceof Error ? error.message : String(error)
        )
      }

      return { success: false, message: error instanceof Error ? error.message : String(error) }
    }
  }

  async checkProjectHash(id: string, localHash: string): Promise<{ needsUpdate: boolean; serverHash?: string }> {
    if (!syncConfig.isEnabled()) {
      return { needsUpdate: false }
    }

    try {
      const response = await this.fetchWithRetry(`/projects/${id}/hash`)
      const data = await response.json()

      return {
        needsUpdate: data.hash !== localHash,
        serverHash: data.hash,
      }
    } catch (error) {
      const syncConfigData = syncConfig.getConfig()

      if (syncConfigData.debugMode) {
        console.warn(
          `⚠️ Sync Warning: Failed to check hash for project ${id}:`,
          error instanceof Error ? error.message : String(error)
        )
      }

      return { needsUpdate: false }
    }
  }

  isConnected(): boolean {
    return this.isOnline && syncConfig.isEnabled()
  }
}

"use client"

import {
  Suspense,
  useEffect,
  useState,
  type ComponentType,
  type LazyExoticComponent,
  type ReactNode,
} from "react"

export function ClientOnlyLazy<TProps extends object>({
  component: Component,
  props,
  fallback,
}: {
  component: LazyExoticComponent<ComponentType<TProps>>
  props: TProps
  fallback: ReactNode
}) {
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)
  }, [])

  if (!mounted) {
    return <>{fallback}</>
  }

  return (
    <Suspense fallback={fallback}>
      <Component {...props} />
    </Suspense>
  )
}

"use client"

export interface WebPConversionOptions {
  quality: number // 0.1 to 1.0
  lossless?: boolean
  maxWidth?: number
  maxHeight?: number
  maintainAspectRatio?: boolean
  backgroundColor?: string
}

export interface WebPConversionResult {
  success: boolean
  blob?: Blob
  dataUrl?: string
  originalSize: number
  compressedSize: number
  compressionRatio: number
  error?: string
}

export class WebPConverter {
  private static isWebPSupported(): boolean {
    const canvas = document.createElement("canvas")
    canvas.width = 1
    canvas.height = 1
    return canvas.toDataURL("image/webp").indexOf("data:image/webp") === 0
  }

  static async convertToWebP(
    file: File,
    options: WebPConversionOptions = { quality: 0.85 },
  ): Promise<WebPConversionResult> {
    if (!this.isWebPSupported()) {
      return {
        success: false,
        originalSize: file.size,
        compressedSize: 0,
        compressionRatio: 0,
        error: "WebP format is not supported in this browser",
      }
    }

    try {
      const result = await this.processImage(file, options)
      return result
    } catch (error) {
      return {
        success: false,
        originalSize: file.size,
        compressedSize: 0,
        compressionRatio: 0,
        error: error instanceof Error ? error.message : "Unknown error occurred",
      }
    }
  }

  private static processImage(file: File, options: WebPConversionOptions): Promise<WebPConversionResult> {
    return new Promise((resolve, reject) => {
      const img = new Image()
      const canvas = document.createElement("canvas")
      const ctx = canvas.getContext("2d")

      if (!ctx) {
        reject(new Error("Could not get canvas context"))
        return
      }

      img.onload = () => {
        try {
          // Calculate dimensions
          const dimensions = this.calculateDimensions(img.width, img.height, options)

          canvas.width = dimensions.width
          canvas.height = dimensions.height

          // Set background color if specified
          if (options.backgroundColor) {
            ctx.fillStyle = options.backgroundColor
            ctx.fillRect(0, 0, canvas.width, canvas.height)
          }

          // Draw image
          ctx.drawImage(img, 0, 0, dimensions.width, dimensions.height)

          // Convert to WebP
          const mimeType = options.lossless ? "image/webp" : "image/webp"
          const quality = options.lossless ? undefined : options.quality

          canvas.toBlob(
            (blob) => {
              if (!blob) {
                reject(new Error("Failed to convert image to WebP"))
                return
              }

              const compressionRatio = ((file.size - blob.size) / file.size) * 100
              const dataUrl = canvas.toDataURL(mimeType, quality)

              resolve({
                success: true,
                blob,
                dataUrl,
                originalSize: file.size,
                compressedSize: blob.size,
                compressionRatio: Math.max(0, compressionRatio),
              })
            },
            mimeType,
            quality,
          )
        } catch (error) {
          reject(error)
        }
      }

      img.onerror = () => {
        reject(new Error("Failed to load image"))
      }

      // Create object URL for the image
      const objectUrl = URL.createObjectURL(file)
      img.src = objectUrl

      // Clean up object URL after image loads
      const originalOnLoad = img.onload
      img.onload = (event) => {
        URL.revokeObjectURL(objectUrl)
        if (originalOnLoad) {
          originalOnLoad.call(img, event)
        }
      }
    })
  }

  private static calculateDimensions(
    originalWidth: number,
    originalHeight: number,
    options: WebPConversionOptions,
  ): { width: number; height: number } {
    let { width, height } = { width: originalWidth, height: originalHeight }
    const { maxWidth, maxHeight, maintainAspectRatio = true } = options

    if (maxWidth && width > maxWidth) {
      if (maintainAspectRatio) {
        height = (height * maxWidth) / width
      }
      width = maxWidth
    }

    if (maxHeight && height > maxHeight) {
      if (maintainAspectRatio) {
        width = (width * maxHeight) / height
      }
      height = maxHeight
    }

    return {
      width: Math.round(width),
      height: Math.round(height),
    }
  }

  static getOptimalQuality(fileSize: number): number {
    // Return optimal quality based on file size
    if (fileSize > 10 * 1024 * 1024) return 0.7 // >10MB
    if (fileSize > 5 * 1024 * 1024) return 0.75 // >5MB
    if (fileSize > 2 * 1024 * 1024) return 0.8 // >2MB
    if (fileSize > 1 * 1024 * 1024) return 0.85 // >1MB
    return 0.9 // <1MB
  }

  static shouldCompress(file: File): boolean {
    // Recommend compression for files larger than 500KB
    return file.size > 500 * 1024
  }

  static formatFileSize(bytes: number): string {
    if (bytes === 0) return "0 Bytes"
    const k = 1024
    const sizes = ["Bytes", "KB", "MB", "GB"]
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return Number.parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i]
  }

  static async batchConvert(
    files: File[],
    options: WebPConversionOptions,
    onProgress?: (completed: number, total: number) => void,
  ): Promise<WebPConversionResult[]> {
    const results: WebPConversionResult[] = []

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      if (!file) continue;
      const result = await this.convertToWebP(file, options)
      results.push(result)

      if (onProgress) {
        onProgress(i + 1, files.length)
      }
    }

    return results
  }
}

