import JSZip, { type JSZipObject } from "jszip"
import {
  computeAssetContentHash,
  findAssetUris,
  isAssetUri,
  parseAssetUri,
  type AssetUri,
} from "@game-guild/assets"
import { getDefaultBrowserAssetRepository } from "@game-guild/assets/browser"
import type { ProjectPreferences } from "@/components/block-content-editor/lib/storage/editor/project-preferences"
import type { StorageType } from "@/components/block-content-editor/lib/storage/editor/storage-types"
import type { ProjectExportInput, ProjectExportMetadata } from "./interop-types"

export type { ProjectExportInput, ProjectExportMetadata } from "./interop-types"
export type ProjectStorageType = StorageType
export type ProjectData = ProjectExportInput
export type ProjectMetadata = ProjectExportMetadata

interface AssetBundleManifestEntry {
  uri: AssetUri
  name: string
  mimeType: string
  size: number
  contentHash: string
  path: string
}

export interface ImportedProjectData {
  id: string
  name: string
  data: string
  tags: string[]
  metadata: ProjectExportMetadata | null
  assetsImported: number
  importedAssetUris: AssetUri[]
  preferences?: ProjectPreferences
}

export interface FolderStructureData {
  indexContent: string
  dataContent: string
  folderName: string
}

const assetRepository = getDefaultBrowserAssetRepository()

function rewriteAssetUris(value: unknown, replacements: Map<AssetUri, AssetUri>): unknown {
  if (isAssetUri(value)) return replacements.get(value) ?? value
  if (Array.isArray(value)) return value.map((item) => rewriteAssetUris(item, replacements))
  if (!value || typeof value !== "object") return value
  return Object.fromEntries(
    Object.entries(value as Record<string, unknown>).map(([key, item]) => [
      key,
      rewriteAssetUris(item, replacements),
    ]),
  )
}

export class ProjectImporter {
  private static readonly SUPPORTED_EXTENSIONS = [".zip", ".block-content-editor"]
  private static readonly METADATA_FILENAME = "index.json"
  private static readonly DATA_FILENAME = "data.block-content-editor"
  private static readonly ASSETS_FOLDER = "assets"
  private static readonly ASSET_MANIFEST_FILENAME = "manifest.json"
  private static readonly MAX_ASSET_COUNT = 2000
  private static readonly MAX_ASSET_SIZE = 64 * 1024 * 1024
  private static readonly MAX_BUNDLE_ASSET_BYTES = 1024 * 1024 * 1024

  static async importFromFile(file: File): Promise<ImportedProjectData> {
    const extension = `.${file.name.toLowerCase().split(".").pop()}`
    if (!ProjectImporter.SUPPORTED_EXTENSIONS.includes(extension)) {
      throw new Error(`Unsupported file format. Supported: ${ProjectImporter.SUPPORTED_EXTENSIONS.join(", ")}`)
    }
    return extension === ".zip"
      ? ProjectImporter.importFromZip(file)
      : ProjectImporter.importFromBlockContentEditorFile(file)
  }

  private static async importAssetBundle(
    manifestFile: JSZipObject | File | undefined,
    readObject: (path: string) => Promise<Blob | null>,
    documentUris: readonly AssetUri[],
  ): Promise<Map<AssetUri, AssetUri>> {
    const replacements = new Map<AssetUri, AssetUri>()
    if (!manifestFile) return replacements
    const manifestText =
      "async" in manifestFile ? await manifestFile.async("text") : await manifestFile.text()
    const parsedManifest = JSON.parse(manifestText) as unknown
    if (!Array.isArray(parsedManifest)) throw new Error("Invalid asset bundle manifest")
    const manifest = parsedManifest as AssetBundleManifestEntry[]
    if (manifest.length > ProjectImporter.MAX_ASSET_COUNT) {
      throw new Error("Asset bundle contains too many files")
    }
    const available = new Set<AssetUri>()
    const referenced = new Set(documentUris)
    let totalSize = 0
    for (const entry of manifest) {
      const parsedUri = isAssetUri(entry.uri) ? parseAssetUri(entry.uri) : null
      if (
        !parsedUri ||
        !referenced.has(entry.uri) ||
        !entry.name ||
        !entry.mimeType ||
        !/^sha256:[0-9a-f]{64}$/.test(entry.contentHash) ||
        !Number.isSafeInteger(entry.size) ||
        entry.size <= 0 ||
        entry.size > ProjectImporter.MAX_ASSET_SIZE ||
        !/^objects\/[a-zA-Z0-9._-]+$/.test(entry.path)
      ) {
        throw new Error("Invalid asset bundle manifest")
      }
      if (available.has(entry.uri)) throw new Error("Asset bundle contains duplicate references")
      available.add(entry.uri)
      totalSize += entry.size
      if (totalSize > ProjectImporter.MAX_BUNDLE_ASSET_BYTES) {
        throw new Error("Asset bundle exceeds the import size limit")
      }
    }
    const created: AssetUri[] = []
    try {
      for (const entry of manifest) {
        const blob = await readObject(entry.path)
        if (!blob || blob.size !== entry.size) {
          throw new Error(`Missing or corrupt bundled asset: ${entry.name}`)
        }
        if (await computeAssetContentHash(blob) !== entry.contentHash) {
          throw new Error(`Bundled asset failed its integrity check: ${entry.name}`)
        }
        const existed = await assetRepository.get(entry.uri)
        if (existed) {
          if (existed.contentHash !== entry.contentHash) {
            throw new Error(`Asset identity conflicts with existing content: ${entry.uri}`)
          }
          replacements.set(entry.uri, existed.uri)
          continue
        }
        const imported = await assetRepository.importBlob(blob, {
          id: parseAssetUri(entry.uri)!.id,
          name: entry.name,
          mimeType: entry.mimeType,
          source: { type: "device", value: "project-import" },
        })
        replacements.set(entry.uri, imported.uri)
        created.push(imported.uri)
      }
      return replacements
    } catch (error) {
      await Promise.all(
        created.map((uri) =>
          assetRepository.remove(uri, { force: true }).catch(() => undefined),
        ),
      )
      throw error
    }
  }

  private static async importFromZip(file: File): Promise<ImportedProjectData> {
    const zip = await new JSZip().loadAsync(file)
    const projectPath = Object.keys(zip.files)
      .map((path) => path.split("/")[0])
      .find((path) => path?.startsWith("projeto-"))
    if (!projectPath) throw new Error("No project folder found in ZIP file")
    const indexFile = zip.files[`${projectPath}/${ProjectImporter.METADATA_FILENAME}`]
    const dataFile = zip.files[`${projectPath}/${ProjectImporter.DATA_FILENAME}`]
    if (!indexFile || !dataFile) throw new Error("Project metadata or document is missing")

    const metadata = JSON.parse(await indexFile.async("text")) as ProjectMetadata
    if (!ProjectImporter.isValidMetadata(metadata)) throw new Error("Invalid metadata structure")
    const parsed = JSON.parse(await dataFile.async("text")) as unknown
    const documentUris = findAssetUris(parsed)
    const assetsRoot = `${projectPath}/${ProjectImporter.ASSETS_FOLDER}/`
    const manifestFile = zip.files[`${assetsRoot}${ProjectImporter.ASSET_MANIFEST_FILENAME}`]
    const replacements = await ProjectImporter.importAssetBundle(manifestFile, async (path) => {
      const object = zip.files[`${assetsRoot}${path}`]
      return object ? object.async("blob") : null
    }, documentUris)
    const rewritten = rewriteAssetUris(parsed, replacements)

    return {
      id: metadata.id,
      name: metadata.name,
      data: JSON.stringify(rewritten),
      tags: metadata.tags,
      metadata,
      assetsImported: replacements.size,
      importedAssetUris: Array.from(replacements.values()),
      preferences: metadata.preferences,
    }
  }

  private static async importFromBlockContentEditorFile(file: File): Promise<ImportedProjectData> {
    const content = await file.text()
    const parsed = JSON.parse(content) as unknown
    return {
      id: "",
      name: file.name.replace(/\.block-content-editor$/, "") || "Imported Project",
      data: content,
      tags: [],
      metadata: null,
      assetsImported: 0,
      importedAssetUris: [],
    }
  }

  static async importFromFolder(files: File[]): Promise<ImportedProjectData> {
    if (!files.length) throw new Error("No files provided in folder selection")
    const fileMap = new Map<string, File>()
    for (const file of files) {
      const relative = (file as File & { webkitRelativePath?: string }).webkitRelativePath || file.name
      const parts = relative.split("/").filter(Boolean)
      const innerPath = parts.length > 1 ? parts.slice(1).join("/") : parts[0]
      if (innerPath) fileMap.set(innerPath, file)
    }
    const indexFile = fileMap.get(ProjectImporter.METADATA_FILENAME)
    const dataFile = fileMap.get(ProjectImporter.DATA_FILENAME)
    if (!indexFile || !dataFile) throw new Error("Selected folder is missing project files")
    const metadata = JSON.parse(await indexFile.text()) as ProjectMetadata
    if (!ProjectImporter.isValidMetadata(metadata)) throw new Error("Invalid metadata structure")
    const parsed = JSON.parse(await dataFile.text()) as unknown
    const documentUris = findAssetUris(parsed)
    const root = `${ProjectImporter.ASSETS_FOLDER}/`
    const replacements = await ProjectImporter.importAssetBundle(
      fileMap.get(`${root}${ProjectImporter.ASSET_MANIFEST_FILENAME}`),
      async (path) => fileMap.get(`${root}${path}`) ?? null,
      documentUris,
    )
    const rewritten = rewriteAssetUris(parsed, replacements)
    return {
      id: metadata.id,
      name: metadata.name,
      data: JSON.stringify(rewritten),
      tags: metadata.tags,
      metadata,
      assetsImported: replacements.size,
      importedAssetUris: Array.from(replacements.values()),
      preferences: metadata.preferences,
    }
  }

  static async importFromFolderStructure(
    folderData: FolderStructureData,
  ): Promise<ImportedProjectData> {
    const metadata = JSON.parse(folderData.indexContent) as ProjectMetadata
    if (!ProjectImporter.isValidMetadata(metadata)) throw new Error("Invalid metadata structure")
    JSON.parse(folderData.dataContent)
    return {
      id: metadata.id,
      name: metadata.name,
      data: folderData.dataContent,
      tags: metadata.tags,
      metadata,
      assetsImported: 0,
      importedAssetUris: [],
      preferences: metadata.preferences,
    }
  }

  static convertToProjectData(
    importedData: ImportedProjectData,
    newId?: string,
    newStorageType?: ProjectStorageType,
  ): ProjectData {
    const now = new Date().toISOString()
    return {
      id: newId || importedData.id || "",
      name: importedData.name,
      data: importedData.data,
      tags: importedData.tags,
      size: new Blob([importedData.data]).size,
      createdAt: importedData.metadata?.createdAt || now,
      updatedAt: now,
      hash: importedData.metadata?.hash,
      storageType: newStorageType || (importedData.metadata?.storageType as ProjectStorageType) || "local",
      preferences: importedData.preferences || importedData.metadata?.preferences,
    }
  }

  static validateImportedData(importedData: ImportedProjectData): boolean {
    try {
      return Boolean(importedData.name && importedData.data && JSON.parse(importedData.data))
    } catch {
      return false
    }
  }

  private static isValidMetadata(metadata: unknown): metadata is ProjectMetadata {
    if (!metadata || typeof metadata !== "object") return false
    const value = metadata as Record<string, unknown>
    return Boolean(
      value.id &&
      value.name &&
      Array.isArray(value.tags) &&
      value.createdAt &&
      value.updatedAt &&
      value.storageType &&
      value.version,
    )
  }

  static getSupportedExtensions(): string[] {
    return [...ProjectImporter.SUPPORTED_EXTENSIONS]
  }

  static isSupportedFile(filename: string): boolean {
    return ProjectImporter.SUPPORTED_EXTENSIONS.includes(
      `.${filename.toLowerCase().split(".").pop()}`,
    )
  }
}

"use client"

import { lazy, type ComponentType } from "react"
import { useEffect, useRef } from "react"
import type { editor } from "monaco-editor"
import type { EditorProps, Monaco, OnMount } from "@monaco-editor/react"
import type {
  MonacoOptionsPreferences,
  RenderLineHighlight,
} from "@/components/block-content-editor/lib/storage/editor/editor-preferences"
import type { ShikiTheme } from "@/components/block-content-editor/lib/shiki/themes"
import { ensureShikiLoaded } from "@/components/block-content-editor/lib/shiki/highlighter"
import { MonacoErrorBoundary } from "@/components/block-content-editor/extras/code-studio/monaco-error-boundary"
import { applyLineHighlightDecoration } from "./line-highlight"
import {
  FALLBACK_MONACO_OPTIONS,
  buildMonacoOptions,
  type MonacoOptions,
} from "./build-monaco-options"
import { useMonacoThemeBinding } from "./use-monaco-theme-binding"
import { ClientOnlyLazy } from "../client-only-lazy"

const monacoFallback = (
  <div className="flex h-full items-center justify-center text-sm text-gray-500">
    Loading editor…
  </div>
)

// `@monaco-editor/react` is browser-only. Keep it behind a client-only
// lazy boundary without relying on Next's private loadable context.
const MonacoReactEditor = lazy(async () => ({
  default: (await import("@monaco-editor/react")).default as ComponentType<EditorProps>,
}))

export interface BaseMonacoEditorProps {
  /** Controlled value. Mutually exclusive with `defaultValue`. */
  value?: string
  /** Uncontrolled initial value (use with `keepCurrentModel` in multi-file scenarios). */
  defaultValue?: string
  /** Monaco language id (e.g. `'typescript'`, `'markdown'`, `'mermaid'`). */
  language: string
  /** Editor height. Defaults to `100%`. */
  height?: string | number
  /** Read-only mode. */
  readOnly?: boolean
  /** Whether the host page is in dark mode. Drives theme resolution. */
  isDark: boolean
  /**
   * Resolved preference snapshot. `null` is tolerated during hydration
   * and falls back to {@link FALLBACK_MONACO_OPTIONS}.
   */
  options?: MonacoOptionsPreferences | null
  /**
   * Per-surface Monaco options merged on top of the preference-derived
   * ones (always wins on conflict). Use sparingly — anything generic
   * should live in {@link buildMonacoOptions}.
   */
  extraOptions?: MonacoOptions
  /** Fallback Monaco theme used while Shiki is loading. Defaults to `"light"`. */
  fallbackLight?: string
  /** Fallback Monaco theme used while Shiki is loading in dark mode. Defaults to `"vs-dark"`. */
  fallbackDark?: string
  /** Forwarded to `<Editor path={...}>` for multi-file model isolation. */
  path?: string
  /** Forwarded to `<Editor keepCurrentModel={...}>`. */
  keepCurrentModel?: boolean
  /** Stable key to force a full editor re-instantiation (e.g. file switch). */
  editorKey?: string
  /** Called when the user edits the content. */
  onChange?: (value: string | undefined) => void
  /**
   * Called once Monaco has mounted. Use for per-surface setup: language
   * registration, snippet providers, command bindings, JSON schemas, …
   */
  onMount?: (editor: editor.IStandaloneCodeEditor, monaco: Monaco) => void
  /**
   * Called before Monaco mounts (after Shiki is requested). Use for
   * compiler-options / diagnostics defaults that must precede model
   * creation.
   */
  beforeMount?: (monaco: Monaco) => void | Promise<void>
}

/**
 * Centralized Monaco wrapper used by every block-content-editor surface
 * (code-studio, html, markdown, mermaid, vega-lite). Handles the bits
 * that were previously duplicated across five files:
 *
 *  - `MonacoErrorBoundary` and the dynamic `@monaco-editor/react` import.
 *  - Shiki bootstrapping (`ensureShikiLoaded` in `beforeMount`).
 *  - Theme resolution + registration with the global coordinator (see
 *    {@link useMonacoThemeBinding}).
 *  - Options assembly via {@link buildMonacoOptions}, including the
 *    cross-cutting `fixedOverflowWidgets` setting so hover/suggest
 *    widgets float above any host modal.
 *  - Per-editor `data-line-highlight-rectangle` CSS hook synced with
 *    the resolved `renderLineHighlight`.
 *
 * Surfaces only need to pass their language, their resolved preference
 * snapshot, and (optionally) an `onMount` callback for language-
 * specific plumbing.
 */
export function BaseMonacoEditor({
  value,
  defaultValue,
  language,
  height = "100%",
  readOnly = false,
  isDark,
  options,
  extraOptions,
  fallbackLight,
  fallbackDark,
  path,
  keepCurrentModel,
  editorKey,
  onChange,
  onMount,
  beforeMount,
}: BaseMonacoEditorProps) {
  const prefs = options ?? FALLBACK_MONACO_OPTIONS
  const { currentTheme, bindMonaco } = useMonacoThemeBinding({
    shikiTheme: prefs.shikiTheme as ShikiTheme,
    isDark,
    fallbackLight,
    fallbackDark,
  })

  const editorRef = useRef<editor.IStandaloneCodeEditor | null>(null)
  const renderLineHighlightRef = useRef<RenderLineHighlight>(prefs.renderLineHighlight)
  renderLineHighlightRef.current = prefs.renderLineHighlight

  const handleBeforeMount: EditorProps["beforeMount"] = (monaco) => {
    void ensureShikiLoaded(monaco)
    void beforeMount?.(monaco)
  }

  const handleMount: OnMount = (ed, monaco) => {
    editorRef.current = ed
    bindMonaco(monaco)
    applyLineHighlightDecoration(ed, renderLineHighlightRef.current)
    onMount?.(ed, monaco)
  }

  // Keep the rectangle-mode CSS hook in sync with the resolved value;
  // Monaco's own option update is handled through the `options` prop
  // diffing inside `@monaco-editor/react`.
  useEffect(() => {
    applyLineHighlightDecoration(editorRef.current, prefs.renderLineHighlight)
  }, [prefs.renderLineHighlight])

  const mergedOptions = buildMonacoOptions(prefs, { readOnly, ...extraOptions })
  const editorProps: EditorProps = {
    height,
    language,
    value,
    defaultValue,
    path,
    keepCurrentModel,
    onChange,
    beforeMount: handleBeforeMount,
    onMount: handleMount,
    theme: currentTheme,
    loading: "",
    options: mergedOptions,
  }

  return (
    <MonacoErrorBoundary>
      <ClientOnlyLazy
        key={editorKey}
        component={MonacoReactEditor}
        props={editorProps}
        fallback={monacoFallback}
      />
    </MonacoErrorBoundary>
  )
}

"use client"

import { useCallback, useEffect, useRef } from "react"
import type { Monaco } from "@monaco-editor/react"
import { isShikiActive, useShikiReady } from "@/components/block-content-editor/lib/shiki/highlighter"
import { getShikiThemeName, type ShikiTheme } from "@/components/block-content-editor/lib/shiki/themes"
import {
  registerMonacoSurface,
  type MonacoThemeHandle,
} from "@/components/block-content-editor/lib/shiki/theme-coordinator"

interface UseMonacoThemeBindingArgs {
  /** User-selected Shiki theme. Resolved to a light/dark variant. */
  shikiTheme: ShikiTheme
  /** Whether the host page is in dark mode. */
  isDark: boolean
  /**
   * Built-in Monaco theme used while Shiki hasn't finished initializing
   * (or when Shiki is unavailable). Defaults to the standard `"light"`
   * / `"vs-dark"` pair; mermaid passes `"mermaid-light"` / `"mermaid-dark"`.
   */
  fallbackLight?: string
  fallbackDark?: string
}

interface MonacoThemeBinding {
  /** Resolved Monaco theme name for the current frame. */
  currentTheme: string
  /** Whether Shiki has finished loading (for conditional rendering). */
  shikiReady: boolean
  /**
   * Register the surface with the global Monaco theme coordinator. Call
   * once from the editor's `onMount`. The binding tracks the latest
   * resolver via refs, refreshes on theme/dark-mode changes, and
   * unregisters on unmount so closing this surface restores the theme
   * of any underlying Monaco editor.
   */
  bindMonaco: (monaco: Monaco) => void
}

/**
 * Centralizes the Shiki/Monaco theme handshake that every Monaco wrapper
 * in the block-content-editor used to copy/paste:
 *
 * 1. Pick the Shiki theme name when Shiki is loaded; otherwise fall back
 *    to a built-in Monaco theme (light / vs-dark, or a per-surface
 *    custom theme such as mermaid-light).
 * 2. Register with the global theme coordinator so a LIFO stack of
 *    Monaco surfaces play nicely (e.g. opening a mermaid editor doesn't
 *    permanently steal the theme from an underlying code-studio preview).
 * 3. Refresh the coordinator whenever the resolver inputs change.
 * 4. Unregister on unmount.
 */
export function useMonacoThemeBinding({
  shikiTheme,
  isDark,
  fallbackLight = "light",
  fallbackDark = "vs-dark",
}: UseMonacoThemeBindingArgs): MonacoThemeBinding {
  const shikiReady = useShikiReady()

  const resolveTheme = useCallback((): string => {
    if (shikiReady && isShikiActive()) {
      return getShikiThemeName(shikiTheme, isDark)
    }
    return isDark ? fallbackDark : fallbackLight
  }, [shikiReady, shikiTheme, isDark, fallbackLight, fallbackDark])

  // Keep a ref to the resolver so the coordinator's closure always reads
  // the latest inputs without re-registering on every theme change.
  const resolveRef = useRef(resolveTheme)
  resolveRef.current = resolveTheme

  const handleRef = useRef<MonacoThemeHandle | null>(null)

  const bindMonaco = useCallback((monaco: Monaco) => {
    if (handleRef.current) return
    handleRef.current = registerMonacoSurface(monaco, () => resolveRef.current())
  }, [])

  // Refresh the coordinator whenever any input that affects the theme
  // changes. No-op when the handle hasn't been bound yet.
  useEffect(() => {
    handleRef.current?.refresh()
  }, [resolveTheme])

  // Unregister on unmount so the dominant theme falls back to whichever
  // surface was registered before this one.
  useEffect(
    () => () => {
      handleRef.current?.unregister()
      handleRef.current = null
    },
    [],
  )

  return { currentTheme: resolveTheme(), shikiReady, bindMonaco }
}

"use client"

import { useEffect, useState } from "react"
import type { Monaco } from "@monaco-editor/react"
import { shikiToMonaco } from "@shikijs/monaco"
import { createHighlighter, type Highlighter } from "shiki"
import { SHIKI_LANGS } from "@/components/block-content-editor/extras/code-studio/types"

type MonacoEditorModule = typeof import("monaco-editor")
type MonacoEditorRuntime = MonacoEditorModule extends { default: infer T } ? T : MonacoEditorModule

/**
 * Accepts either the `Monaco` namespace from `@monaco-editor/react`
 * (used by html/markdown/mermaid wrappers via `beforeMount`/`onMount`)
 * or a direct `import * as monaco from "monaco-editor"` namespace
 * (used by vega-lite which mounts Monaco manually). Both are structurally
 * compatible with `shikiToMonaco`.
 */
type MonacoNamespace = Monaco | MonacoEditorRuntime

let monacoLoaderConfigured = false
let monacoLoaderConfigPromise: Promise<void> | null = null

function resolveMonacoNamespace(module: MonacoEditorModule): MonacoEditorRuntime {
  const maybeDefault = (module as { default?: MonacoEditorRuntime }).default
  return maybeDefault ?? (module as unknown as MonacoEditorRuntime)
}

async function ensureMonacoLoaderConfigured(monaco?: MonacoNamespace): Promise<void> {
  if (monacoLoaderConfigured) return
  if (typeof window === "undefined") return

  if (monaco) {
    const { loader } = await import("@monaco-editor/react")
    loader.config({ monaco: monaco as Monaco })
    monacoLoaderConfigured = true
    return
  }

  if (!monacoLoaderConfigPromise) {
    monacoLoaderConfigPromise = Promise.all([
      import("@monaco-editor/react"),
      import("monaco-editor"),
    ])
      .then(([monacoReact, monacoModule]) => {
        monacoReact.loader.config({ monaco: resolveMonacoNamespace(monacoModule) as Monaco })
        monacoLoaderConfigured = true
      })
      .catch((error) => {
        monacoLoaderConfigPromise = null
        throw error
      })
  }

  await monacoLoaderConfigPromise
}

// `@monaco-editor/react` defaults to loading monaco-editor from a CDN, so
// without this it would run a *different* Monaco instance than the one
// vega-lite imports directly from `monaco-editor`. That mismatch means
// themes / languages registered on one instance are invisible to the
// other — the symptom is the vega editor (or any other Monaco surface)
// rendering with a broken half-applied theme as soon as Shiki binds to
// one of the two instances. Pinning the loader to our local npm package
// guarantees every Monaco surface in the app shares a single instance.
void ensureMonacoLoaderConfigured()

// Singleton highlighter + one-time monaco binding, shared across every
// Monaco-using editor (code-studio, html, markdown, mermaid, vega-lite).
let highlighter: Highlighter | null = null
let highlighterPromise: Promise<Highlighter> | null = null
let appliedToMonaco = false

// Listeners notified once Shiki has been applied to Monaco for the first
// time. Lets editors that mounted *before* Shiki finished loading swap
// from their fallback theme to the user's chosen Shiki theme.
const readyListeners = new Set<() => void>()

export function isShikiActive(): boolean {
  return appliedToMonaco
}

export async function getShikiHighlighter(): Promise<Highlighter> {
  if (highlighter) return highlighter
  if (!highlighterPromise) {
    highlighterPromise = createHighlighter({
      themes: [
        // Original set
        'github-dark',
        'github-light',
        'github-dark-default',
        'github-light-default',
        'github-dark-dimmed',
        'dark-plus',
        'light-plus',
        'catppuccin-mocha',
        'catppuccin-latte',
        'vitesse-dark',
        'vitesse-light',
        'monokai',
        'solarized-dark',
        'solarized-light',
        'dracula',
        'nord',
        // New themes
        'tokyo-night',
        'one-dark-pro',
        'one-light',
        'material-theme-ocean',
        'material-theme-lighter',
        'rose-pine',
        'rose-pine-dawn',
        'gruvbox-dark-medium',
        'gruvbox-light-medium',
        'night-owl',
        // High-contrast themes
        'github-dark-high-contrast',
        'github-light-high-contrast',
        'min-dark',
        'min-light',
        'slack-dark',
        'slack-ochin',
        'red',
      ],
      langs: SHIKI_LANGS,
    }).then((hl) => {
      highlighter = hl
      return hl
    })
  }
  return highlighterPromise
}

/**
 * Idempotently load Shiki and bind it to the provided Monaco instance.
 * Safe to call from every Monaco editor's `beforeMount` — the highlighter
 * and the `shikiToMonaco` binding are both global singletons, so the
 * first caller pays the cost and every subsequent caller is a no-op.
 *
 * Once this resolves, `isShikiActive()` returns `true` everywhere and any
 * Monaco theme name from `getShikiThemeName(...)` becomes valid for
 * `<Editor theme=...>` or `monaco.editor.setTheme(...)`.
 */
export async function ensureShikiLoaded(monaco: MonacoNamespace): Promise<void> {
  if (appliedToMonaco) return
  try {
    await ensureMonacoLoaderConfigured(monaco)
    const hl = await getShikiHighlighter()
    shikiToMonaco(hl, monaco as Monaco)
    appliedToMonaco = true
    readyListeners.forEach((fn) => {
      try {
        fn()
      } catch (error) {
        console.error('Shiki ready listener threw:', error)
      }
    })
  } catch (error) {
    console.error('Failed to load Shiki:', error)
  }
}

/**
 * React hook returning `true` once Shiki has been bound to Monaco. Use it
 * to force a re-render in editors that may have mounted before the first
 * `ensureShikiLoaded(monaco)` call resolved, so their `theme={...}` prop
 * can switch from `vs-dark`/`light` to the user's selected Shiki theme.
 */
export function useShikiReady(): boolean {
  const [ready, setReady] = useState<boolean>(appliedToMonaco)
  useEffect(() => {
    if (appliedToMonaco) {
      setReady(true)
      return
    }
    const listener = () => setReady(true)
    readyListeners.add(listener)
    return () => {
      readyListeners.delete(listener)
    }
  }, [])
  return ready
}

"use client"

import type { Monaco } from "@monaco-editor/react"
type MonacoEditorModule = typeof import("monaco-editor")
type MonacoEditorRuntime = MonacoEditorModule extends { default: infer T } ? T : MonacoEditorModule

type MonacoNamespace = Monaco | MonacoEditorRuntime

interface Registration {
  monaco: MonacoNamespace
  getTheme: () => string
}

/**
 * Monaco's `editor.setTheme(...)` is *global* — there is no per-editor
 * theme. That means whenever any Monaco surface (mermaid, vega-lite,
 * html, markdown, code-studio…) sets its theme, it stomps the theme of
 * every other surface currently rendered. When that surface unmounts,
 * the stomp persists and the still-mounted surfaces look wrong until
 * something else triggers them to reapply.
 *
 * This module is the single source of truth for the active Monaco theme.
 * Every Monaco wrapper registers its desired theme on mount and removes
 * itself on unmount. At any time the "dominant" theme is the one
 * declared by the *most recently registered* surface that is still
 * mounted — which mirrors the user's mental model: a modal editor opens
 * on top of the document, overrides the theme while it's visible, and
 * then yields back to the document previews when it closes.
 */
const registrations: Registration[] = []

function applyDominant(): void {
  const top = registrations[registrations.length - 1]
  if (!top) return
  try {
    const themeName = top.getTheme()
    if (themeName) {
      top.monaco.editor.setTheme(themeName)
    }
  } catch (err) {
    console.error("Monaco theme coordinator failed to apply theme:", err)
  }
}

export interface MonacoThemeHandle {
  /**
   * Re-evaluate `getTheme` and reapply if this surface is currently
   * dominant. Call when the user changes the theme preference.
   */
  refresh(): void
  /**
   * Remove this surface from the coordinator. Triggers reapplication of
   * the new dominant surface's theme (i.e. restores whatever was
   * underneath this modal).
   */
  unregister(): void
}

/**
 * Register a Monaco surface. Pass the `Monaco` namespace from
 * `@monaco-editor/react`'s `beforeMount`/`onMount`, or `monaco-editor`'s
 * own namespace for surfaces that mount Monaco directly (vega-lite).
 * The `getTheme` callback is invoked every time the coordinator needs
 * to apply this surface's theme, so it can read the current resolved
 * theme name from a ref/state without re-registering.
 */
export function registerMonacoSurface(
  monaco: MonacoNamespace,
  getTheme: () => string,
): MonacoThemeHandle {
  const reg: Registration = { monaco, getTheme }
  registrations.push(reg)
  applyDominant()
  let removed = false
  return {
    refresh() {
      if (removed) return
      applyDominant()
    },
    unregister() {
      if (removed) return
      removed = true
      const i = registrations.lastIndexOf(reg)
      if (i >= 0) registrations.splice(i, 1)
      applyDominant()
    },
  }
}

/**
 * Block Storage
 *
 * Centralizes (de)serialization for the Block Array Engine. End-to-end shape:
 *
 *   serializeProject(blocks)   →  string (JSON of BlockStorage)
 *   deserializeProject(data)   →  BlockArray
 *   blockToPreviewNode(block)  →  fake serialized node shape consumed by
 *                                 preview components in plugins/preview-components/*
 *
 * The persisted shape is:
 *   {
 *     order: [["1", "rich-text"], ["2", "image"], …],
 *     blocks: { "1": <rich-text data>, "2": <image data>, … }
 *   }
 */

import type {
  AnyBlockData,
  Block,
  BlockArray,
  BlockCellType,
  BlockDataMap,
  BlockStorage,
} from "./block-structure"
import {
  EMPTY_BLOCK_STORAGE,
  blockToView,
  blocksToStorage as blocksToBlockListStorage,
  deserializeBlockList,
  serializeBlockList,
  storageToBlocks as storageToBlockList,
  type BlockView,
} from "@game-guild/block-list"

// ============================================================================
// Conversion: BlockArray ↔ BlockStorage
// ============================================================================

export function blocksToStorage(blocks: BlockArray): BlockStorage {
  return blocksToBlockListStorage(blocks) as BlockStorage
}

export function storageToBlocks(storage: BlockStorage | null | undefined): BlockArray {
  return storageToBlockList<BlockCellType, AnyBlockData, Block>(storage)
}

// ============================================================================
// Project-level serialization
// ============================================================================

export const EMPTY_PROJECT_DATA: string = JSON.stringify(EMPTY_BLOCK_STORAGE)

export function serializeProject(blocks: BlockArray): string {
  return serializeBlockList(blocks)
}

export function deserializeProject(data: string | null | undefined): BlockArray {
  return deserializeBlockList<Block>(data)
}

// ============================================================================
// Preview adapter — Block → serialized node shape
//
// Preview components in plugins/preview-components/* consume the generic
// `{ id, type, data, version }` read model from @game-guild/block-list.
// ============================================================================

export type PreviewNode<T extends BlockCellType = BlockCellType> = BlockView<
  T,
  BlockDataMap[T]
>

export function blockToPreviewNode<B extends Block>(block: B): PreviewNode<B["type"]> {
  return blockToView(block) as PreviewNode<B["type"]>
}

/**
 * Editor Preferences Manager
 * Gerencia configurações globais e específicas por tipo de node
 */

import {
  SHIKI_THEME_CONFIGS,
  type ShikiTheme,
} from "@/components/block-content-editor/lib/shiki/themes"

export type ModalSize = 'compact' | 'widescreen' | 'ultrawide' | 'fullscreen'
export type WordWrap = 'on' | 'off'
export type RenderWhitespace = 'none' | 'boundary' | 'all'
/**
 * `'none' | 'gutter' | 'line' | 'all'` map 1:1 to Monaco's native values.
 * `'rectangle'` is a custom mode: it reuses Monaco's `'line'` highlight
 * and overlays a 1px outline (border) on the active line via a CSS hook
 * applied through `applyLineHighlightDecoration`.
 */
export type RenderLineHighlight = 'none' | 'gutter' | 'line' | 'all' | 'rectangle'

/**
 * The full bag of Monaco-surface options the user can customize. Stored
 * twice on `EditorPreferences` — once under `editor` (applied to every
 * editable Monaco surface) and once under `preview` (applied to the
 * read-only render of any Monaco-using block, including the code-studio
 * "base" display that mirrors the student view).
 *
 * Keeping the two scopes structurally identical lets the settings UI
 * render the same form twice and keeps consumer code mechanical: each
 * editor wrapper just picks `settings.editor` or `settings.preview` and
 * spreads it into Monaco's options.
 */
export interface MonacoOptionsPreferences {
  /** Shiki syntax theme. Resolved to a light/dark variant at render time. */
  shikiTheme: ShikiTheme
  /** Font size in pixels. Clamped 10–24 by the UI slider. */
  fontSize: number
  /** When `false`, the gutter line-number column is hidden. */
  lineNumbers: boolean
  /** When `true`, long lines wrap at the viewport edge. */
  wordWrap: boolean
  /** When `true`, the minimap overview ruler is shown on the right. */
  minimap: boolean
  /** Width of a tab in spaces. UI slider exposes 2 / 4 / 8. */
  tabSize: number
  /**
   * Whitespace visualization: `'none'` hides it; `'boundary'` shows it
   * only between non-whitespace tokens; `'all'` shows every space and
   * tab as a dot/arrow.
   */
  renderWhitespace: RenderWhitespace
  /**
   * How the active line is highlighted: `'none'` disables it; `'gutter'`
   * highlights only the line number column; `'line'` highlights only
   * the text area; `'all'` highlights both.
   */
  renderLineHighlight: RenderLineHighlight
}

export interface EditorPreferences {
  /** Modal sizing for any block-editor shell. */
  modalSize: ModalSize
  /**
   * Options applied to every editable Monaco surface (code-studio
   * secondary displays, html, markdown, mermaid, vega-lite, …).
   */
  editor: MonacoOptionsPreferences
  /**
   * Options applied to the read-only render of Monaco-using blocks in
   * document preview, and to the code-studio "base" display — i.e.
   * everywhere students see Monaco rather than editing it.
   */
  preview: MonacoOptionsPreferences
}

export interface NodeTypePreferences {
  [nodeType: string]: Partial<EditorPreferences>
}

export interface AllPreferences {
  global: EditorPreferences
  nodeTypes: NodeTypePreferences
}

const DB_NAME = 'editor-preferences'
const DB_VERSION = 1
const STORE_NAME = 'preferences'
const PREFERENCES_KEY = 'editor-prefs'

// Default Monaco-surface options. Editor and preview share the same
// shape; in practice the preview defaults to slightly more reader-
// friendly values (smaller font, minimap off) but the user can match
// them perfectly through the settings UI.
const DEFAULT_EDITOR_OPTIONS: MonacoOptionsPreferences = {
  shikiTheme: 'github',
  fontSize: 14,
  lineNumbers: true,
  wordWrap: true,
  minimap: false,
  tabSize: 2,
  renderWhitespace: 'none',
  renderLineHighlight: 'line',
}

const DEFAULT_PREVIEW_OPTIONS: MonacoOptionsPreferences = {
  shikiTheme: 'github',
  fontSize: 13,
  lineNumbers: true,
  wordWrap: true,
  minimap: false,
  tabSize: 2,
  renderWhitespace: 'none',
  renderLineHighlight: 'none',
}

// Default preferences
const DEFAULT_PREFERENCES: EditorPreferences = {
  modalSize: 'widescreen',
  editor: DEFAULT_EDITOR_OPTIONS,
  preview: DEFAULT_PREVIEW_OPTIONS,
}

// IndexedDB helper
class PreferencesDB {
  private dbPromise: Promise<IDBDatabase> | null = null

  private async getDB(): Promise<IDBDatabase> {
    if (this.dbPromise) return this.dbPromise

    this.dbPromise = new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION)

      request.onerror = () => reject(request.error)
      request.onsuccess = () => resolve(request.result)

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME)
        }
      }
    })

    return this.dbPromise
  }

  async get(): Promise<AllPreferences> {
    try {
      const db = await this.getDB()
      return new Promise((resolve, reject) => {
        const transaction = db.transaction(STORE_NAME, 'readonly')
        const store = transaction.objectStore(STORE_NAME)
        const request = store.get(PREFERENCES_KEY)

        request.onsuccess = () => {
          const data = request.result
          if (data) {
            // Merge persisted globals with defaults so newly-added
            // preference keys backfill cleanly when the user's DB entry
            // predates them. The two MonacoOptions groups are merged
            // independently so adding a new option (e.g. `tabSize`) on
            // top of an older persisted value doesn't drop the user's
            // existing customizations.
            const persistedGlobal = (data.global ?? {}) as Partial<EditorPreferences>
            const merged: EditorPreferences = {
              ...DEFAULT_PREFERENCES,
              ...persistedGlobal,
              editor: {
                ...DEFAULT_EDITOR_OPTIONS,
                ...(persistedGlobal.editor ?? {}),
              },
              preview: {
                ...DEFAULT_PREVIEW_OPTIONS,
                ...(persistedGlobal.preview ?? {}),
              },
            }
            resolve({
              global: merged,
              nodeTypes: data.nodeTypes ?? {},
            })
          } else {
            // Return default preferences
            resolve({
              global: DEFAULT_PREFERENCES,
              nodeTypes: {},
            })
          }
        }

        request.onerror = () => reject(request.error)
      })
    } catch (error) {
      console.error('Failed to get preferences:', error)
      return {
        global: DEFAULT_PREFERENCES,
        nodeTypes: {},
      }
    }
  }

  async set(preferences: AllPreferences): Promise<void> {
    try {
      const db = await this.getDB()
      return new Promise((resolve, reject) => {
        const transaction = db.transaction(STORE_NAME, 'readwrite')
        const store = transaction.objectStore(STORE_NAME)
        const request = store.put(preferences, PREFERENCES_KEY)

        request.onsuccess = () => resolve()
        request.onerror = () => reject(request.error)
      })
    } catch (error) {
      console.error('Failed to set preferences:', error)
      throw error
    }
  }
}

const db = new PreferencesDB()

// Lightweight pub/sub so every open editor refreshes its resolved
// preferences when one of them writes a new value (e.g. the user picks a
// new global theme inside an html-editor while a mermaid-editor is also
// mounted somewhere on the page).
type PreferencesListener = () => void
const listeners = new Set<PreferencesListener>()

function notifyPreferencesChanged(): void {
  listeners.forEach((fn) => {
    try {
      fn()
    } catch (error) {
      console.error('Preferences listener threw:', error)
    }
  })
}

export function subscribeToPreferences(listener: PreferencesListener): () => void {
  listeners.add(listener)
  return () => {
    listeners.delete(listener)
  }
}

// Public API
export async function getEditorPreferences(nodeType?: string): Promise<EditorPreferences> {
  const allPrefs = await db.get()
  
  if (nodeType && allPrefs.nodeTypes[nodeType]) {
    // Merge node-specific preferences with global defaults
    return {
      ...allPrefs.global,
      ...allPrefs.nodeTypes[nodeType],
    }
  }
  
  return allPrefs.global
}

/**
 * Returns the raw `AllPreferences` snapshot (global + per-nodeType
 * overrides). Use this when the caller needs to distinguish a nodeType
 * override from a global value — e.g. to drive a "this node type only"
 * toggle in the settings UI.
 */
export async function getAllPreferences(): Promise<AllPreferences> {
  return db.get()
}

type StoredEditorPreferencesInput = {
  readonly modalSize?: string
  readonly editor?: Record<string, unknown>
  readonly preview?: Record<string, unknown>
}

function isModalSize(value: unknown): value is ModalSize {
  return value === 'compact' || value === 'widescreen' || value === 'ultrawide' || value === 'fullscreen'
}

function isShikiTheme(value: unknown): value is ShikiTheme {
  return typeof value === 'string' && value in SHIKI_THEME_CONFIGS
}

function isRenderWhitespace(value: unknown): value is RenderWhitespace {
  return value === 'none' || value === 'boundary' || value === 'all'
}

function isRenderLineHighlight(value: unknown): value is RenderLineHighlight {
  return value === 'none' || value === 'gutter' || value === 'line' || value === 'all' || value === 'rectangle'
}

function getStoredMonacoOptions(value: Record<string, unknown>): Partial<MonacoOptionsPreferences> {
  const shikiTheme = value.shikiTheme
  const fontSize = value.fontSize
  const lineNumbers = value.lineNumbers
  const wordWrap = value.wordWrap
  const minimap = value.minimap
  const tabSize = value.tabSize
  const renderWhitespace = value.renderWhitespace
  const renderLineHighlight = value.renderLineHighlight

  return {
    ...(isShikiTheme(shikiTheme) ? { shikiTheme } : {}),
    ...(typeof fontSize === 'number' && Number.isFinite(fontSize) ? { fontSize } : {}),
    ...(typeof lineNumbers === 'boolean' ? { lineNumbers } : {}),
    ...(typeof wordWrap === 'boolean' ? { wordWrap } : {}),
    ...(typeof minimap === 'boolean' ? { minimap } : {}),
    ...(typeof tabSize === 'number' && Number.isFinite(tabSize) ? { tabSize } : {}),
    ...(isRenderWhitespace(renderWhitespace) ? { renderWhitespace } : {}),
    ...(isRenderLineHighlight(renderLineHighlight) ? { renderLineHighlight } : {}),
  }
}

export async function applyStoredGlobalPreferences(
  input: StoredEditorPreferencesInput,
): Promise<void> {
  const allPrefs = await db.get()
  const modalSize = isModalSize(input.modalSize) ? input.modalSize : allPrefs.global.modalSize
  const editor = input.editor
    ? { ...allPrefs.global.editor, ...getStoredMonacoOptions(input.editor) }
    : allPrefs.global.editor
  const preview = input.preview
    ? { ...allPrefs.global.preview, ...getStoredMonacoOptions(input.preview) }
    : allPrefs.global.preview

  allPrefs.global = { modalSize, editor, preview }
  await db.set(allPrefs)
  notifyPreferencesChanged()
}

export async function setGlobalPreference<K extends keyof EditorPreferences>(
  key: K,
  value: EditorPreferences[K]
): Promise<void> {
  const allPrefs = await db.get()
  allPrefs.global[key] = value
  
  // Clear node-specific overrides for this key when setting global
  for (const nodeType in allPrefs.nodeTypes) {
    const nodePrefs = allPrefs.nodeTypes[nodeType]
    if (nodePrefs && nodePrefs[key] !== undefined) {
      delete nodePrefs[key]
      // Remove empty node type entries
      if (Object.keys(nodePrefs).length === 0) {
        delete allPrefs.nodeTypes[nodeType]
      }
    }
  }
  
  await db.set(allPrefs)
  notifyPreferencesChanged()
}

export async function setNodeTypePreference<K extends keyof EditorPreferences>(
  nodeType: string,
  key: K,
  value: EditorPreferences[K]
): Promise<void> {
  const allPrefs = await db.get()
  
  if (!allPrefs.nodeTypes[nodeType]) {
    allPrefs.nodeTypes[nodeType] = {}
  }
  
  allPrefs.nodeTypes[nodeType][key] = value
  await db.set(allPrefs)
  notifyPreferencesChanged()
}

export async function clearNodeTypePreference(
  nodeType: string,
  key: keyof EditorPreferences
): Promise<void> {
  const allPrefs = await db.get()
  
  if (allPrefs.nodeTypes[nodeType]) {
    delete allPrefs.nodeTypes[nodeType][key]
    
    // Remove empty node type entries
    if (Object.keys(allPrefs.nodeTypes[nodeType]).length === 0) {
      delete allPrefs.nodeTypes[nodeType]
    }
  }
  
  await db.set(allPrefs)
  notifyPreferencesChanged()
}

export async function clearAllNodeTypePreferences(nodeType: string): Promise<void> {
  const allPrefs = await db.get()
  delete allPrefs.nodeTypes[nodeType]
  await db.set(allPrefs)
  notifyPreferencesChanged()
}

/**
 * Updates a single key inside one of the two Monaco-options groups
 * (`editor` or `preview`) without disturbing the others. This is the
 * preferred way for the settings UI to update font size, line numbers,
 * theme, etc. because it keeps the write atomic and avoids races where
 * two controls would otherwise overwrite each other's group object.
 */
export async function setMonacoOption<K extends keyof MonacoOptionsPreferences>(
  scope: 'editor' | 'preview',
  key: K,
  value: MonacoOptionsPreferences[K],
): Promise<void> {
  const allPrefs = await db.get()
  allPrefs.global[scope] = {
    ...allPrefs.global[scope],
    [key]: value,
  }
  await db.set(allPrefs)
  notifyPreferencesChanged()
}

export async function hasNodeTypePreference(nodeType: string, key: keyof EditorPreferences): Promise<boolean> {
  const allPrefs = await db.get()
  return !!(allPrefs.nodeTypes[nodeType] && allPrefs.nodeTypes[nodeType][key] !== undefined)
}

// Modal size helper
export function getModalSizeClasses(size: ModalSize): { container: string; modal: string } {
  switch (size) {
    case 'compact':
      return {
        container: 'p-4',
