  /**
   * Create a snapshot (tag) of the current project state
   * @param id - Project ID
   * @param name - Snapshot name (optional, auto-generated if not provided)
   */
  async createSnapshot(id: string, name?: string): Promise<SnapshotInfo | null> {
    if (!this.isInitialized) throw new Error("Storage adapter not initialized")

    const project = await this.loadFromIndexedDB(id)
    if (!project) {
      console.error(`Cannot create snapshot: Project ${id} not found`)
      return null
    }

    try {
      const historyManager = getHistoryManager()
      
      // Generate tag name if not provided
      let tag: string
      if (name) {
        tag = name
      } else {
        const version = await historyManager.getNextVersionNumber(id, project.name)
        tag = `${project.name}-v${version}`
      }

      const snapshot = await historyManager.createSnapshot(id, tag)
      console.log(`Created snapshot "${snapshot.tag}" for project "${project.name}"`)
      return snapshot
    } catch (error) {
      console.error(`Failed to create snapshot for project ${id}:`, error)
      throw error
    }
  }

  /**
   * List all snapshots for a project
   */
  async listSnapshots(id: string): Promise<SnapshotInfo[]> {
    if (!this.isInitialized) throw new Error("Storage adapter not initialized")

    const historyManager = getHistoryManager()
    return await historyManager.listSnapshots(id)
  }

  /**
   * List commit history for a project
   * @param id - Project ID
   * @param maxCount - Maximum number of commits to return (default 50)
   */
  async listHistory(id: string, maxCount: number = 50): Promise<CommitInfo[]> {
    if (!this.isInitialized) throw new Error("Storage adapter not initialized")

    const historyManager = getHistoryManager()
    return await historyManager.listHistory(id, maxCount)
  }

  /**
   * Load a snapshot and replace the current IndexedDB state
   * @param id - Project ID
   * @param tag - Snapshot tag to load
   */
  async loadFromSnapshot(id: string, tag: string): Promise<ProjectData | null> {
    if (!this.isInitialized) throw new Error("Storage adapter not initialized")

    const historyManager = getHistoryManager()
    const snapshotData = await historyManager.loadSnapshot(id, tag)
    
    if (!snapshotData) {
      console.error(`Snapshot "${tag}" not found for project ${id}`)
      return null
    }

    // Parse the snapshot data
    let projectData: ProjectData
    try {
      projectData = JSON.parse(snapshotData)
    } catch (error) {
      console.error(`Failed to parse snapshot data for ${tag}:`, error)
      return null
    }

    // Ensure required fields and update timestamp
    const now = new Date().toISOString()
    const updatedProject: ProjectData = {
      ...projectData,
      id,
      metadata: {
        ...projectData.metadata,
        updatedAt: now,
        hash: await HashManager.generateHash(projectData.data),
      },
      syncStatus: SYNC_STATUS.PENDING,
    }

    // Save to IndexedDB (replaces current state)
    await this.saveToIndexedDB(updatedProject)

    console.log(`Loaded snapshot "${tag}" for project "${updatedProject.name}" - now the current version`)
    return updatedProject
  }

  /**
   * Load a specific commit from history for viewing (READ-ONLY)
   * Does NOT modify IndexedDB - just returns the historical data for display
   * @param id - Project ID
   * @param sha - Commit SHA to load
   */
  async loadFromHistory(id: string, sha: string): Promise<ProjectData | null> {
    if (!this.isInitialized) throw new Error("Storage adapter not initialized")

    const historyManager = getHistoryManager()
    const commitData = await historyManager.loadCommit(id, sha)
    
    if (!commitData) {
      console.error(`Commit ${sha} not found for project ${id}`)
      return null
    }

    // Parse the commit data
    let projectData: ProjectData
    try {
      projectData = JSON.parse(commitData)
    } catch (error) {
      console.error(`Failed to parse commit data for ${sha}:`, error)
      return null
    }

    // Return the historical data AS-IS for viewing (don't modify anything)
    console.log(`Loaded commit ${sha.substring(0, 7)} for project "${projectData.name}" - viewing historical version (read-only)`)
    return projectData
  }

  /**
   * Delete a snapshot
   */
  async deleteSnapshot(id: string, tag: string): Promise<boolean> {
    if (!this.isInitialized) throw new Error("Storage adapter not initialized")

    const historyManager = getHistoryManager()
    return await historyManager.deleteSnapshot(id, tag)
  }

  /**
   * Check if a project has any snapshots
   */
  async hasSnapshots(id: string): Promise<boolean> {
    if (!this.isInitialized) throw new Error("Storage adapter not initialized")

    const historyManager = getHistoryManager()
    return await historyManager.hasSnapshots(id)
  }

  /**
   * Check if a project has any history
   */
  async hasHistory(id: string): Promise<boolean> {
    if (!this.isInitialized) throw new Error("Storage adapter not initialized")

    const historyManager = getHistoryManager()
    return await historyManager.hasHistory(id)
  }

  // Utility methods
  private estimateSize(data: string): number {
    return new Blob([data]).size / 1024
  }

  private formatSize(sizeInKB: number): string {
    if (sizeInKB < 1024) {
      return `${sizeInKB.toFixed(1)}KB`
    } else {
      return `${(sizeInKB / 1024).toFixed(1)}MB`
    }
  }

  destroy(): void {
    this.syncManager.destroy()
  }
}

import git from 'isomorphic-git'
import { getGitFS, getFS, getProjectDir, ensureProjectsDir, projectRepoExists } from './git-fs'

export interface CommitInfo {
  sha: string
  message: string
  date: string
}

export interface SnapshotInfo {
  tag: string
  sha: string
  message: string
  date: string
}

/**
 * Git History Manager
 * 
 * Manages linear commit history per project with optional snapshots (tags).
 * - Every save() creates a commit (automatic history)
 * - Snapshots are tags on specific commits (user-created versions)
 */
export class GitHistoryManager {
  private readonly author = { name: 'Block Content Editor User', email: 'user@block-content-editor.local' }

  /**
   * Initialize a project's git repository if it doesn't exist
   */
  async initRepo(projectId: string): Promise<void> {
    await ensureProjectsDir()
    
    const dir = getProjectDir(projectId)
    const fs = getFS()
    
    if (await projectRepoExists(projectId)) {
      return // Already initialized
    }

    // Create project directory
    try {
      await fs.mkdir(dir)
    } catch {
      // Directory may already exist
    }

    // Initialize git repo
    await git.init({
      fs: getGitFS(),
      dir,
      defaultBranch: 'main'
    })

    console.log(`📁 Git repo initialized: ${dir}/.git/`)
  }

  /**
   * Create a commit with the current project data
   * This is called automatically on every save()
   * @param projectId - Project identifier
   * @param data - Serialized project data (JSON string)
   * @param message - Commit message (auto-generated if not provided)
   */
  async commitProject(
    projectId: string,
    data: string,
    message?: string
  ): Promise<CommitInfo> {
    await this.initRepo(projectId)
    
    const dir = getProjectDir(projectId)
    const fs = getFS()
    const gitFs = getGitFS()

    // Generate commit message if not provided
    const commitMessage = message || `Auto-save: ${new Date().toISOString()}`

    // Write project.json
    await fs.writeFile(`${dir}/project.json`, data, 'utf8')

    // Stage the file
    await git.add({
      fs: gitFs,
      dir,
      filepath: 'project.json'
    })

    // Check if there are changes to commit
    const status = await git.status({
      fs: gitFs,
      dir,
      filepath: 'project.json'
    })

    // If file is unmodified, skip commit
    if (status === 'unmodified') {
      // Return the current HEAD commit info
      const head = await this.getHeadCommit(projectId)
      if (head) {
        return head
      }
    }

    // Get parent commit (if exists)
    let parent: string[] = []
    try {
      const headRef = await git.resolveRef({ fs: gitFs, dir, ref: 'HEAD' })
      parent = [headRef]
    } catch {
      // No parent - first commit
    }

    // Create commit
    const sha = await git.commit({
      fs: gitFs,
      dir,
      message: commitMessage,
      author: this.author,
      parent
    })

    const date = new Date().toISOString()

    console.log(`📝 Git commit: ${sha.substring(0, 7)} - ${commitMessage}`)

    return { sha, message: commitMessage, date }
  }

  /**
   * Get the HEAD commit info
   */
  private async getHeadCommit(projectId: string): Promise<CommitInfo | null> {
    if (!(await projectRepoExists(projectId))) {
      return null
    }

    const dir = getProjectDir(projectId)
    const gitFs = getGitFS()

    try {
      const sha = await git.resolveRef({ fs: gitFs, dir, ref: 'HEAD' })
      const commit = await git.readCommit({ fs: gitFs, dir, oid: sha })
      
      return {
        sha,
        message: commit.commit.message,
        date: new Date(commit.commit.author.timestamp * 1000).toISOString()
      }
    } catch {
      return null
    }
  }

  /**
   * Create a snapshot (tag) on the current HEAD commit
   * @param projectId - Project identifier
   * @param tag - Tag name for the snapshot
   * @param message - Optional message for the tag
   */
  async createSnapshot(
    projectId: string,
    tag: string,
    message?: string
  ): Promise<SnapshotInfo> {
    if (!(await projectRepoExists(projectId))) {
      throw new Error(`Project ${projectId} has no Git history. Save the project first.`)
    }

    const dir = getProjectDir(projectId)
    const gitFs = getGitFS()

    // Sanitize tag name
    const sanitizedTag = this.sanitizeTagName(tag)

    // Check if tag already exists
    const existingTags = await git.listTags({ fs: gitFs, dir })
    if (existingTags.includes(sanitizedTag)) {
      throw new Error(`Snapshot "${sanitizedTag}" already exists`)
    }

    // Get current HEAD
    const sha = await git.resolveRef({ fs: gitFs, dir, ref: 'HEAD' })
    const commit = await git.readCommit({ fs: gitFs, dir, oid: sha })

    // Create tag
    await git.tag({
      fs: gitFs,
      dir,
      ref: sanitizedTag,
      object: sha
    })

    const date = new Date(commit.commit.author.timestamp * 1000).toISOString()
    const snapshotMessage = message || commit.commit.message

    console.log(`📸 Snapshot created:`)
    console.log(`   Project ID: ${projectId}`)
    console.log(`   Path: ${dir}/`)
    console.log(`   Tag: ${sanitizedTag}`)
    console.log(`   SHA: ${sha}`)

    return {
      tag: sanitizedTag,
      sha,
      message: snapshotMessage,
      date
    }
  }

  /**
   * Get the next version number for auto-naming snapshots
   */
  async getNextVersionNumber(projectId: string, baseName: string): Promise<number> {
    const snapshots = await this.listSnapshots(projectId)
    
    // Find the highest "v{N}" suffix for this base name
    let maxVersion = 0
    const sanitizedBase = this.sanitizeTagName(baseName)
    
    for (const snapshot of snapshots) {
      // Match pattern like "ProjectName-v1", "ProjectName-v2"
      const match = snapshot.tag.match(new RegExp(`^${sanitizedBase}-v(\\d+)$`))
      if (match && match[1]) {
        const num = parseInt(match[1], 10)
        if (num > maxVersion) {
          maxVersion = num
        }
      }
    }
    
    return maxVersion + 1
  }

  /**
   * List all commits (history) for a project
   * Returns commits in reverse chronological order (newest first)
   */
  async listHistory(projectId: string, maxCount: number = 50): Promise<CommitInfo[]> {
    if (!(await projectRepoExists(projectId))) {
      return []
    }

    const dir = getProjectDir(projectId)
    const gitFs = getGitFS()

    try {
      const commits = await git.log({
        fs: gitFs,
        dir,
        depth: maxCount
      })

      return commits.map(commit => ({
        sha: commit.oid,
        message: commit.commit.message,
        date: new Date(commit.commit.author.timestamp * 1000).toISOString()
      }))
    } catch (error) {
      console.error('Failed to list history:', error)
      return []
    }
  }

  /**
   * List all snapshots (tags) for a project
   */
  async listSnapshots(projectId: string): Promise<SnapshotInfo[]> {
    if (!(await projectRepoExists(projectId))) {
      return []
    }

    const dir = getProjectDir(projectId)
    const gitFs = getGitFS()

    try {
      const tags = await git.listTags({ fs: gitFs, dir })
      const snapshots: SnapshotInfo[] = []

      for (const tag of tags) {
        try {
          const sha = await git.resolveRef({ fs: gitFs, dir, ref: tag })
          const commit = await git.readCommit({ fs: gitFs, dir, oid: sha })
          
          snapshots.push({
            tag,
            sha,
            message: commit.commit.message,
            date: new Date(commit.commit.author.timestamp * 1000).toISOString()
          })
        } catch (error) {
          console.warn(`Failed to read snapshot ${tag}:`, error)
        }
      }

      // Sort by date descending (newest first)
      snapshots.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())

      return snapshots
    } catch (error) {
      console.error('Failed to list snapshots:', error)
      return []
    }
  }

  /**
   * Load project data from a specific commit
   */
  async loadCommit(projectId: string, sha: string): Promise<string | null> {
    if (!(await projectRepoExists(projectId))) {
      return null
    }

    const dir = getProjectDir(projectId)
    const gitFs = getGitFS()

    try {
      const { blob } = await git.readBlob({
        fs: gitFs,
        dir,
        oid: sha,
        filepath: 'project.json'
      })

      const decoder = new TextDecoder('utf-8')
      return decoder.decode(blob)
    } catch (error) {
      console.error(`Failed to load commit ${sha}:`, error)
      return null
    }
  }

  /**
   * Load project data from a snapshot (tag)
   */
  async loadSnapshot(projectId: string, tag: string): Promise<string | null> {
    if (!(await projectRepoExists(projectId))) {
      return null
    }

    const dir = getProjectDir(projectId)
    const gitFs = getGitFS()

    try {
      const sha = await git.resolveRef({ fs: gitFs, dir, ref: tag })
      return await this.loadCommit(projectId, sha)
    } catch (error) {
      console.error(`Failed to load snapshot ${tag}:`, error)
      return null
    }
  }

  /**
   * Delete a snapshot (tag only, commit remains in history)
   */
  async deleteSnapshot(projectId: string, tag: string): Promise<boolean> {
    if (!(await projectRepoExists(projectId))) {
      return false
    }

    const dir = getProjectDir(projectId)
    const gitFs = getGitFS()

    try {
      await git.deleteTag({ fs: gitFs, dir, ref: tag })
      console.log(`🗑️ Snapshot deleted: ${tag}`)
      return true
    } catch (error) {
      console.error(`Failed to delete snapshot ${tag}:`, error)
      return false
    }
  }

  /**
   * Check if a project has any commits
   */
  async hasHistory(projectId: string): Promise<boolean> {
    const history = await this.listHistory(projectId, 1)
    return history.length > 0
  }

  /**
   * Check if a project has any snapshots
   */
  async hasSnapshots(projectId: string): Promise<boolean> {
    const snapshots = await this.listSnapshots(projectId)
    return snapshots.length > 0
  }

  /**
   * Delete the entire git repository for a project
   * Used when deleting a project
   */
  async deleteProjectRepo(projectId: string): Promise<boolean> {
    if (!(await projectRepoExists(projectId))) {
      return true
    }

    const dir = getProjectDir(projectId)
    const fs = getFS()

    try {
      await this.recursiveDelete(dir)
      console.log(`🗑️ Git repo deleted: ${dir}`)
      return true
    } catch (error) {
      console.error(`Failed to delete project repo ${projectId}:`, error)
      return false
    }
  }

  /**
   * Recursively delete a directory
   */
  private async recursiveDelete(path: string): Promise<void> {
    const fs = getFS()
    
    try {
      const stat = await fs.stat(path)
      
      if (stat.isDirectory()) {
        const entries = await fs.readdir(path)
        for (const entry of entries) {
          await this.recursiveDelete(`${path}/${entry}`)
        }
        await fs.rmdir(path)
      } else {
        await fs.unlink(path)
      }
    } catch {
      // Ignore errors for non-existent paths
    }
  }

  /**
   * Sanitize a string to be used as a git tag
   */
  private sanitizeTagName(name: string): string {
    return name
      .trim()
      .replace(/[\s~^:?*\[\]\\]+/g, '-')
      .replace(/\.{2,}/g, '.')
      .replace(/^-+|-+$/g, '')
      .replace(/-{2,}/g, '-')
      || 'snapshot'
  }
}

// Singleton instance
let historyManagerInstance: GitHistoryManager | null = null

export function getHistoryManager(): GitHistoryManager {
  if (!historyManagerInstance) {
    historyManagerInstance = new GitHistoryManager()
  }
  return historyManagerInstance
}

import { GoogleDriveService } from "../../../services/editor/google-drive-service"
import type { ProjectData } from "../../storage/editor/project-data"

interface SyncResult {
  success: boolean
  error?: string
  projectId?: string
}

export class GoogleDriveSync {
  private googleDriveService: GoogleDriveService

  constructor() {
    this.googleDriveService = GoogleDriveService.getInstance()
  }

  /**
   * Sync a project to Google Drive
   */
  async syncToGoogleDrive(project: ProjectData): Promise<SyncResult> {
    try {
      console.log("GoogleDriveSync: Starting sync for project:", project.name)
      
      if (!project.storageType || project.storageType !== "google-drive") {
        console.log("GoogleDriveSync: Project not configured for Google Drive storage")
        return {
          success: false,
          error: "Project is not configured for Google Drive storage"
        }
      }

      console.log("GoogleDriveService isReady:", this.googleDriveService.isReady())
      console.log("GoogleDriveService instance:", this.googleDriveService)
      
      if (!this.googleDriveService.isReady()) {
        console.error("GoogleDriveSync: Service not ready")
        return {
          success: false,
          error: "Google Drive service is not authenticated or ready"
        }
      }

      console.log("GoogleDriveSync: Calling saveProject...")
      await this.googleDriveService.saveProject(
        project.id,
        project.name,
        project.data,
        project.tags
      )

      console.log("GoogleDriveSync: Project saved successfully")
      return {
        success: true,
        projectId: project.id
      }
    } catch (error) {
      console.error("Google Drive sync error:", error)
      return {
        success: false,
        error: error instanceof Error ? error.message : "Unknown error"
      }
    }
  }

  /**
   * Load a project from Google Drive
   */
  async loadFromGoogleDrive(projectId: string): Promise<ProjectData | null> {
    try {
      if (!this.googleDriveService.isReady()) {
        console.error("Google Drive service not ready")
        return null
      }

      const project = await this.googleDriveService.getProject(projectId)
      
      if (project) {
        return {
          id: project.id,
          name: project.name,
          data: project.data,
          tags: project.tags,
          metadata: {
            size: project.size,
            hash: project.hash,
            createdAt: project.createdAt,
            updatedAt: project.updatedAt,
          },
          storageType: "google-drive"
        }
      }
      
      return null
    } catch (error) {
      console.error("Google Drive load error:", error)
      return null
    }
  }

  /**
   * List all projects from Google Drive
   */
  async listFromGoogleDrive(): Promise<ProjectData[]> {
    try {
      if (!this.googleDriveService.isReady()) {
        return []
      }

      const projects = await this.googleDriveService.listProjects()
      
      return projects.map((project: any) => ({
        id: project.id,
        name: project.name,
        data: project.data,
        tags: project.tags,
        metadata: {
          size: project.size,
          hash: project.hash,
          createdAt: project.createdAt,
          updatedAt: project.updatedAt,
        },
        storageType: "google-drive" as const
      }))
    } catch (error) {
      console.error("Google Drive list error:", error)
      return []
    }
  }

  /**
   * Delete a project from Google Drive
   */
  async deleteFromGoogleDrive(projectId: string): Promise<SyncResult> {
    try {
      if (!this.googleDriveService.isReady()) {
        return {
          success: false,
          error: "Google Drive service is not authenticated or ready"
        }
      }

      await this.googleDriveService.deleteProject(projectId)
      
      return {
        success: true,
        projectId
      }
    } catch (error) {
      console.error("Google Drive delete error:", error)
      return {
        success: false,
        error: error instanceof Error ? error.message : "Unknown error"
      }
    }
  }

  /**
   * Check if Google Drive is available and authenticated
   */
  async isGoogleDriveAvailable(): Promise<boolean> {
    try {
      return this.googleDriveService.isReady()
    } catch (error) {
      console.error("Google Drive availability check error:", error)
      return false
    }
  }

  /**
   * Sync all Google Drive projects to local storage
   */
  async syncAllFromGoogleDrive(): Promise<{
    synced: ProjectData[]
    errors: { projectId: string; error: string }[]
  }> {
    const synced: ProjectData[] = []
    const errors: { projectId: string; error: string }[] = []

    try {
      const projects = await this.listFromGoogleDrive()
      
      for (const project of projects) {
        try {
          const fullProject = await this.loadFromGoogleDrive(project.id)
          if (fullProject) {
            synced.push(fullProject)
          } else {
            errors.push({
              projectId: project.id,
              error: "Failed to load project data"
            })
          }
        } catch (error) {
          errors.push({
            projectId: project.id,
            error: error instanceof Error ? error.message : "Unknown error"
          })
        }
      }
    } catch (error) {
      console.error("Google Drive sync all error:", error)
    }

    return { synced, errors }
  }
}

export class HashManager {
  static async generateHash(data: string): Promise<string> {
    if (typeof crypto !== "undefined" && crypto.subtle) {
      try {
        const encoder = new TextEncoder()
        const dataBuffer = encoder.encode(data)
        const hashBuffer = await crypto.subtle.digest("SHA-1", dataBuffer)
        const hashArray = Array.from(new Uint8Array(hashBuffer))
        return hashArray.map((b) => b.toString(16).padStart(2, "0")).join("")
      } catch (error) {
        console.warn("Failed to generate SHA-1 hash with Web Crypto API, falling back to simple hash:", error)
        return this.generateSimpleHash(data)
      }
    }

    // Fallback for environments without Web Crypto API
    return this.generateSimpleHash(data)
  }

  private static generateSimpleHash(data: string): string {
    let hash = 0
    if (data.length === 0) return hash.toString()

    for (let i = 0; i < data.length; i++) {
      const char = data.charCodeAt(i)
      hash = (hash << 5) - hash + char
      hash = hash & hash // Convert to 32-bit integer
    }

    return Math.abs(hash).toString(16)
  }

  static async compareHashes(hash1: string, hash2: string): Promise<boolean> {
    return hash1 === hash2
  }

  static async generateProjectHash(projectData: {
    name: string
    data: string
    tags: string[]
    metadata: { updatedAt: string }
  }): Promise<string> {
    const hashInput = JSON.stringify({
      name: projectData.name,
      data: projectData.data,
      tags: projectData.tags.sort(), // Sort tags for consistent hashing
      updatedAt: projectData.metadata.updatedAt,
    })

    return this.generateHash(hashInput)
  }

  static async validateHash(data: string, expectedHash: string): Promise<boolean> {
    const actualHash = await this.generateHash(data)
    return this.compareHashes(actualHash, expectedHash)
  }
}

interface SyncConfig {
  enabled: boolean
  serverUrl: string
  timeout: number
  retries: number
  autoSync: boolean
  syncInterval: number // in milliseconds
  batchSize: number
  debugMode: boolean
}

const DEFAULT_CONFIG: SyncConfig = {
  enabled: false, // Enabled by default for simple connection
  serverUrl: process.env.NEXT_PUBLIC_API_URL || "http://localhost:3001/api",
  timeout: 10000,
  retries: 3,
  autoSync: true,
  syncInterval: 30000, // 30 seconds
  batchSize: 10,
  debugMode: process.env.NODE_ENV === "development",
}

class SyncConfigManager {
  private config: SyncConfig
  private listeners: Array<(config: SyncConfig) => void> = []

  constructor() {
    this.config = this.loadConfig()
  }

  private loadConfig(): SyncConfig {
    if (typeof window === "undefined") return DEFAULT_CONFIG

    try {
      const stored = localStorage.getItem("gg-editor-sync-config")
      if (stored) {
        const parsed = JSON.parse(stored)
        return { ...DEFAULT_CONFIG, ...parsed }
      }
    } catch (error) {
      console.warn("Failed to load sync config from localStorage:", error)
    }

    return DEFAULT_CONFIG
  }

  private saveConfig(): void {
    if (typeof window === "undefined") return

    try {
      localStorage.setItem("gg-editor-sync-config", JSON.stringify(this.config))
    } catch (error) {
      console.warn("Failed to save sync config to localStorage:", error)
    }
  }

  getConfig(): SyncConfig {
    return { ...this.config }
  }

  updateConfig(updates: Partial<SyncConfig>): void {
    const oldConfig = { ...this.config }
    this.config = { ...this.config, ...updates }
    this.saveConfig()

    // Notify listeners of config changes
    this.listeners.forEach((listener) => {
      try {
        listener(this.getConfig())
      } catch (error) {
        console.error("Error in sync config listener:", error)
      }
    })

    if (this.config.debugMode) {
      console.log("Sync config updated:", {
        old: oldConfig,
        new: this.config,
        changes: updates,
      })
    }
  }

  isEnabled(): boolean {
    return this.config.enabled
  }

  enable(): void {
    this.updateConfig({ enabled: true })
  }

  disable(): void {
    this.updateConfig({ enabled: false })
  }

  toggle(): boolean {
    const newState = !this.config.enabled
    this.updateConfig({ enabled: newState })
    return newState
  }

  onConfigChange(listener: (config: SyncConfig) => void): () => void {
    this.listeners.push(listener)

    // Return unsubscribe function
    return () => {
      const index = this.listeners.indexOf(listener)
      if (index > -1) {
        this.listeners.splice(index, 1)
      }
    }
  }

  // Simple configuration method
  setServerUrl(url: string): void {
    this.updateConfig({ serverUrl: url })
  }

  // Validation
  validateConfig(): { isValid: boolean; errors: string[] } {
    const errors: string[] = []

    if (this.config.enabled) {
      if (!this.config.serverUrl || !this.config.serverUrl.trim()) {
        errors.push("Server URL is required when sync is enabled")
      }

      try {
        new URL(this.config.serverUrl)
      } catch {
        errors.push("Server URL must be a valid URL")
      }

      if (this.config.timeout < 1000) {
        errors.push("Timeout must be at least 1000ms")
      }

      if (this.config.retries < 0 || this.config.retries > 10) {
        errors.push("Retries must be between 0 and 10")
      }

      if (this.config.syncInterval < 5000) {
        errors.push("Sync interval must be at least 5000ms")
      }

      if (this.config.batchSize < 1 || this.config.batchSize > 100) {
        errors.push("Batch size must be between 1 and 100")
      }
    }

    return {
      isValid: errors.length === 0,
      errors,
    }
  }

  // Debug helpers
  logConfig(): void {
    if (this.config.debugMode) {
      console.group("🔄 Sync Configuration")
      console.table(this.config)
      console.groupEnd()
    }
  }

  getStatus(): string {
    if (!this.config.enabled) return "disabled"
    if (!navigator.onLine) return "offline"
    return "enabled"
  }
}

// Singleton instance
export const syncConfig = new SyncConfigManager()

// Export types for use in other files
export type { SyncConfig }
export { DEFAULT_CONFIG }

import { syncConfig } from "./sync-config"
import { ApiClient } from "../../api/editor/api-client"
import type { SyncQueueStats as QueueStats } from "./sync-types"

interface SyncQueueItem {
  id: string
  type: "create" | "update" | "delete" | "tags_update"
  projectId?: string
  data?: any
  timestamp: number
  retries: number
  status: "pending" | "processing" | "completed" | "failed"
  error?: string
  lastAttempt?: number
}

export class SyncQueue {
  private db: IDBDatabase | null = null
  private readonly DB_NAME = "GGEditorSyncDB"
  private readonly DB_VERSION = 1
  private readonly STORE_NAME = "sync_queue"
  private isInitialized = false
  private processingInterval: NodeJS.Timeout | null = null
  private apiClient: ApiClient

  constructor(apiClient: ApiClient) {
    this.apiClient = apiClient
  }

  async init(): Promise<void> {
    if (this.isInitialized) return

    await this.initIndexedDB()
    this.isInitialized = true

    // Start processing queue if sync is enabled
    if (syncConfig.isEnabled()) {
      this.startProcessing()
    }

    // Listen for config changes
    syncConfig.onConfigChange((config) => {
      if (config.enabled && !this.processingInterval) {
        this.startProcessing()
      } else if (!config.enabled && this.processingInterval) {
        this.stopProcessing()
      }
    })

    console.log("Sync Queue initialized")
  }

  private async initIndexedDB(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.DB_NAME, this.DB_VERSION)

      request.onerror = () => reject(request.error)
      request.onsuccess = () => {
        this.db = request.result
        resolve()
      }

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result

        if (!db.objectStoreNames.contains(this.STORE_NAME)) {
          const store = db.createObjectStore(this.STORE_NAME, { keyPath: "id" })
          store.createIndex("status", "status", { unique: false })
          store.createIndex("type", "type", { unique: false })
          store.createIndex("timestamp", "timestamp", { unique: false })
          store.createIndex("projectId", "projectId", { unique: false })
        }
      }
    })
  }

  async enqueue(item: Omit<SyncQueueItem, "id" | "timestamp" | "retries" | "status">): Promise<void> {
    if (!syncConfig.isEnabled()) {
      if (syncConfig.getConfig().debugMode) {
        console.log("Sync disabled, skipping queue item:", item)
      }
      return
    }

    if (!this.isInitialized) {
      throw new Error("Sync queue not initialized")
    }

    const queueItem: SyncQueueItem = {
      ...item,
      id: `${item.type}_${item.projectId}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      timestamp: Date.now(),
      retries: 0,
      status: "pending",
    }

    await this.saveItem(queueItem)

    if (syncConfig.getConfig().debugMode) {
      console.log("Enqueued sync item:", queueItem)
    }
  }

  private async saveItem(item: SyncQueueItem): Promise<void> {
    if (!this.db) throw new Error("IndexedDB not initialized")

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.STORE_NAME], "readwrite")
      const store = transaction.objectStore(this.STORE_NAME)
      const request = store.put(item)

      request.onsuccess = () => resolve()
      request.onerror = () => reject(request.error)
    })
  }

  async getStats(): Promise<QueueStats> {
    if (!this.isInitialized) {
      return { pending: 0, processing: 0, completed: 0, failed: 0, total: 0 }
    }

    const items = await this.getAllItems()
    const stats: QueueStats = {
      pending: 0,
      processing: 0,
      completed: 0,
      failed: 0,
      total: items.length,
    }

    items.forEach((item) => {
      stats[item.status]++
    })

    return stats
  }

  private async getAllItems(): Promise<SyncQueueItem[]> {
    if (!this.db) return []

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.STORE_NAME], "readonly")
      const store = transaction.objectStore(this.STORE_NAME)
      const request = store.getAll()

      request.onsuccess = () => resolve(request.result || [])
      request.onerror = () => reject(request.error)
    })
  }

  async getPendingItems(): Promise<SyncQueueItem[]> {
    if (!this.db) return []

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.STORE_NAME], "readonly")
      const store = transaction.objectStore(this.STORE_NAME)
      const index = store.index("status")
      const request = index.getAll("pending")

      request.onsuccess = () => {
        const items = request.result || []
        // Sort by timestamp (oldest first)
        items.sort((a, b) => a.timestamp - b.timestamp)
        resolve(items)
      }
      request.onerror = () => reject(request.error)
    })
  }

  async markAsProcessing(id: string): Promise<void> {
    const item = await this.getItem(id)
    if (item) {
      item.status = "processing"
      item.lastAttempt = Date.now()
      await this.saveItem(item)
    }
  }

  async markAsCompleted(id: string): Promise<void> {
    const item = await this.getItem(id)
    if (item) {
      item.status = "completed"
      await this.saveItem(item)
    }
  }

  async markAsFailed(id: string, error: string): Promise<void> {
    const item = await this.getItem(id)
    if (item) {
      item.status = "failed"
      item.error = error
      item.retries++
      await this.saveItem(item)
    }
  }

  private async getItem(id: string): Promise<SyncQueueItem | null> {
    if (!this.db) return null

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([this.STORE_NAME], "readonly")
      const store = transaction.objectStore(this.STORE_NAME)
      const request = store.get(id)

      request.onsuccess = () => resolve(request.result || null)
      request.onerror = () => reject(request.error)
    })
  }

  async retryFailedItems(): Promise<void> {
    if (!this.db) return

    const transaction = this.db.transaction([this.STORE_NAME], "readwrite")
    const store = transaction.objectStore(this.STORE_NAME)
    const index = store.index("status")
    const request = index.getAll("failed")

    request.onsuccess = () => {
      const failedItems = request.result || []
      const config = syncConfig.getConfig()

      failedItems.forEach((item) => {
        if (item.retries < config.retries) {
          item.status = "pending"
          item.error = undefined
          store.put(item)
        }
      })
    }
  }

  async clearCompleted(): Promise<void> {
    if (!this.db) return

    const transaction = this.db.transaction([this.STORE_NAME], "readwrite")
    const store = transaction.objectStore(this.STORE_NAME)
    const index = store.index("status")
    const request = index.getAll("completed")

    request.onsuccess = () => {
      const completedItems = request.result || []
      const cutoff = Date.now() - 24 * 60 * 60 * 1000 // 24 hours ago

      completedItems.forEach((item) => {
        if (item.timestamp < cutoff) {
          store.delete(item.id)
        }
      })
    }
  }

  private startProcessing(): void {
    if (this.processingInterval) return

    const config = syncConfig.getConfig()
    this.processingInterval = setInterval(() => {
      this.processQueue().catch((error) => {
        if (config.debugMode) {
          console.error("Error processing sync queue:", error)
        }
      })
    }, config.syncInterval)

    if (config.debugMode) {
      console.log("Started sync queue processing")
    }
  }

  private stopProcessing(): void {
    if (this.processingInterval) {
      clearInterval(this.processingInterval)
      this.processingInterval = null

      if (syncConfig.getConfig().debugMode) {
        console.log("Stopped sync queue processing")
      }
    }
  }

  private async processQueue(): Promise<void> {
    if (!syncConfig.isEnabled() || !navigator.onLine) {
      return
    }

    const pendingItems = await this.getPendingItems()
    const config = syncConfig.getConfig()
    const batchSize = Math.min(pendingItems.length, config.batchSize)

    if (batchSize === 0) return

    const batch = pendingItems.slice(0, batchSize)

    if (config.debugMode) {
      console.log(`Processing ${batch.length} sync items`)
    }

    for (const item of batch) {
      try {
        await this.markAsProcessing(item.id)

        let response
        switch (item.type) {
          case "create":
            if (!item.data) throw new Error("Missing data for create operation")
            // Assuming createProject is on apiClient
            response = await this.apiClient.createProject(item.data)
            break
          case "update":
            if (!item.data) throw new Error("Missing data for update operation")
            response = await this.apiClient.updateProject(item.data)
            break
          case "delete":
            if (!item.projectId) throw new Error("Missing projectId for delete operation")
            response = await this.apiClient.deleteProject(item.projectId)
            break
          case "tags_update":
            if (!item.data) throw new Error("Missing data for tags_update operation")
            response = await this.apiClient.syncTags(item.data)
            break
          default:
            throw new Error(`Unknown sync item type: ${item.type}`)
        }

        if (response.success) {
          await this.markAsCompleted(item.id)
        } else {
          throw new Error(response.message || "API operation failed")
        }
      } catch (error) {
        let errorMessage = "Unknown error"
        if (error instanceof Error) {
          errorMessage = error.message
        } else if (typeof error === "string") {
          errorMessage = error
        }
        await this.markAsFailed(item.id, errorMessage)
      }
    }

    // Clean up old completed items
    await this.clearCompleted()
  }

  destroy(): void {
    this.stopProcessing()
    if (this.db) {
      this.db.close()
      this.db = null
    }
    this.isInitialized = false
  }
}

"use client"

import { ListNode, SerializedListNode, ListType } from "@lexical/list"
import type { LexicalNode, NodeKey, EditorConfig, SerializedLexicalNode } from "lexical"

export interface SerializedCustomListNode extends SerializedListNode {
  listStyleType?: string
  markerColor?: string
}

export class CustomListNode extends ListNode {
  __listStyleType: string
  __markerColor: string

  static getType(): string {
    // Tipo próprio (distinto de "list") para evitar conflito de
    // type/klass com o ListNode padrão no registry do Lexical.
    return "custom-list"
  }

  constructor(listType: ListType, start: number, listStyleType?: string, markerColor?: string, key?: NodeKey) {
    super(listType, start, key)
    this.__listStyleType = listStyleType || "decimal"
    this.__markerColor = markerColor || "#3b82f6" // Sempre definir cor padrão
  }

  getListStyleType(): string {
    return this.__listStyleType
  }

  setListStyleType(listStyleType: string): void {
    const writable = this.getWritable()
    writable.__listStyleType = listStyleType
  }

  getMarkerColor(): string {
    return this.__markerColor
  }

  setMarkerColor(markerColor: string): void {
    const writable = this.getWritable()
    writable.__markerColor = markerColor
    
    // Forçar re-aplicação da cor imediatamente
    setTimeout(() => {
      const latestNode = this.getLatest()
      const element = (latestNode as any).__dom
      if (element) {
        // Aplicar cor usando o nó mais recente
        (latestNode as CustomListNode).applyMarkerColor(element)
      }
    }, 0)
  }

  static clone(node: CustomListNode): CustomListNode {
    return new CustomListNode(
      node.getListType(),
      node.getStart(),
      node.__listStyleType,
      node.__markerColor,
      node.__key
    )
  }

  createDOM(config: EditorConfig): HTMLElement {
    const element = super.createDOM(config)
    
    // Limpar todas as classes CSS do tema
    element.className = ""
    
    // Aplicar estilos baseado no tipo de lista (tanto ordered quanto unordered)
    this.applyListStyles(element)
    
    // Definir atributo apropriado baseado no tipo
    if (this.getListType() === "number") {
      element.setAttribute("data-list-style-type", this.__listStyleType || "decimal")
    } else {
      element.setAttribute("data-list-style-type", this.__listStyleType || "disc")
    }
    
    // IMPORTANTE: Aplicar cor imediatamente após a criação do DOM
    this.applyMarkerColor(element)
    
    return element
  }

  updateDOM(prevNode: CustomListNode, dom: HTMLElement, config: EditorConfig): boolean {
    const result = super.updateDOM(prevNode as this, dom, config)
    
    // Limpar todas as classes CSS do tema
    dom.className = ""
    
    // Aplicar estilos baseado no tipo de lista (tanto ordered quanto unordered)
    this.applyListStyles(dom)
    
    // Definir atributo apropriado baseado no tipo
    if (this.getListType() === "number") {
      dom.setAttribute("data-list-style-type", this.__listStyleType || "decimal")
    } else {
      dom.setAttribute("data-list-style-type", this.__listStyleType || "disc")
    }
    
    // IMPORTANTE: Reaplicar cor após atualização do DOM
    this.applyMarkerColor(dom)
    
    return result
  }

  private applyMarkerColor(element: HTMLElement): void {
    // Aplicar cor especificamente aos marcadores após o DOM estar pronto
    const listType = this.__listStyleType || "decimal"
    const markerColor = this.__markerColor || "#3b82f6"
    
    // Remover instância anterior se existir
    const oldInstanceId = element.getAttribute("data-list-instance")
    if (oldInstanceId) {
      // Remover estilos antigos
      const oldStyle = document.querySelector(`#instance-${oldInstanceId}`)
      if (oldStyle) {
        oldStyle.remove()
      }
    }
    
    // Adicionar um identificador único para essa instância específica
    const instanceId = `list-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
    element.setAttribute("data-list-instance", instanceId)
    
    // SEMPRE aplicar estilos de cor, incluindo a cor padrão
    // Isso garante que a deserialização funcione corretamente
    switch (listType) {
      case "decimal":
      case "upper-alpha":
      case "lower-alpha":
      case "upper-roman":
      case "lower-roman":
      case "decimal-leading-zero":
      case "disc":
      case "circle":
      case "square":
        this.addStandardListMarkerStyles(element, listType, markerColor)
        break
      case "greek-upper":
        this.addGreekNumberStyles(element, markerColor)
        break
      case "circled":
        this.addCircledNumberStyles(element, markerColor)
        break
      case "arrow":
        this.addArrowListStyles(element, markerColor)
        break
      case "star":
        this.addStarListStyles(element, markerColor)
        break
    }
  }

  private applyListStyles(element: HTMLElement): void {
    const listType = this.__listStyleType || "decimal"
    const markerColor = this.__markerColor || "#3b82f6"
    
    // Estilos básicos para todas as listas
    element.style.listStylePosition = "inside"
    element.style.paddingLeft = "1rem"
    element.style.marginTop = "1rem"
    element.style.marginBottom = "1rem"
    
    // IMPORTANTE: NÃO aplicar cor ao elemento da lista inteira
    // A cor será aplicada apenas aos marcadores através de CSS
    
    // Estilos específicos por tipo
    switch (listType) {
      case "decimal":
      case "upper-alpha":
      case "lower-alpha":
      case "upper-roman":
      case "lower-roman":
      case "decimal-leading-zero":
        element.style.listStyleType = listType
        // Para listas padrão, aplicar cor apenas aos marcadores via CSS
        this.addStandardListMarkerStyles(element, listType, markerColor)
        break
      case "greek-upper":
        // Numeração grega customizada
        element.style.listStyleType = "none"
        element.style.counterReset = "greek-counter"
        this.addGreekNumberStyles(element, markerColor)
        break
      case "circled":
        element.style.listStyleType = "none"
        element.style.counterReset = "circled-counter"
        this.addCircledNumberStyles(element, markerColor)
        break
      // Estilos para listas não ordenadas (bullet)
      case "disc":
      case "circle":
      case "square":
        element.style.listStyleType = listType
        // Para listas padrão, aplicar cor apenas aos marcadores via CSS
        this.addStandardListMarkerStyles(element, listType, markerColor)
        break
      case "arrow":
        element.style.listStyleType = "none"
        element.setAttribute("data-arrow-list", "true")
        this.addArrowListStyles(element, markerColor)
        break
      case "star":
        element.style.listStyleType = "none"
        element.setAttribute("data-star-list", "true")
        this.addStarListStyles(element, markerColor)
        break
      default:
        // Determinar estilo padrão baseado no tipo de lista
        if (this.getListType() === "bullet") {
          element.style.listStyleType = "disc"
          this.addStandardListMarkerStyles(element, "disc", markerColor)
        } else {
          element.style.listStyleType = "decimal"
          this.addStandardListMarkerStyles(element, "decimal", markerColor)
        }
    }
  }

  private addStandardListMarkerStyles(element: HTMLElement, listType: string, markerColor: string): void {
    const instanceId = element.getAttribute("data-list-instance")
    
    if (instanceId) {
      const specificStyleId = `instance-${instanceId}`
      // Remover estilo anterior se existir
      const oldStyle = document.querySelector(`#${specificStyleId}`)
      if (oldStyle) {
        oldStyle.remove()
      }
      
      const instanceStyle = document.createElement('style')
      instanceStyle.id = specificStyleId
      const listTag = this.getListType() === "bullet" ? "ul" : "ol"
      
      // Criar seletores mais específicos e poderosos
      instanceStyle.textContent = `
        /* Seletores específicos para a instância */
        ${listTag}[data-list-instance="${instanceId}"] {
          list-style-type: ${listType};
        }
        ${listTag}[data-list-instance="${instanceId}"] li::marker {
          color: ${markerColor} !important;
          font-weight: inherit;
        }
        ${listTag}[data-list-instance="${instanceId}"] li {
          color: inherit !important;
        }
        
        /* Seletores para o editor Lexical */
        .lexical-editor ${listTag}[data-list-instance="${instanceId}"] li::marker {
          color: ${markerColor} !important;
        }
        .lexical-editor ${listTag}[data-list-instance="${instanceId}"] li {
          color: inherit !important;
        }
        
        /* Fallback genérico */
        ${listTag}[data-list-style-type="${listType}"][data-list-instance="${instanceId}"] li::marker {
          color: ${markerColor} !important;
        }
      `
      document.head.appendChild(instanceStyle)
    }
  }

  private addGreekNumberStyles(element: HTMLElement, markerColor: string): void {
    // Criar estilos CSS para numeração grega se ainda não existirem
    const styleId = `greek-number-${markerColor.replace(/[^\w]/g, '')}`
    const instanceId = element.getAttribute("data-list-instance")
    
    if (!document.querySelector(`#${styleId}`)) {
      const style = document.createElement('style')
      style.id = styleId
      style.textContent = `
        ol[data-list-style-type="greek-upper"] {
          counter-reset: greek-counter;
        }
        ol[data-list-style-type="greek-upper"] li::before {
          counter-increment: greek-counter;
          content: attr(data-greek-number);
          font-weight: bold;
          color: ${markerColor} !important;
          margin-right: 0.5rem;
          display: inline-block;
        }
        ol[data-list-style-type="greek-upper"] li {
          color: inherit; /* Manter cor do texto normal */
        }
      `
      document.head.appendChild(style)
    }
    
    // Aplicar estilo específico para a instância
    if (instanceId) {
      const specificStyleId = `greek-instance-${instanceId}`
      if (!document.querySelector(`#${specificStyleId}`)) {
        const instanceStyle = document.createElement('style')
        instanceStyle.id = specificStyleId
        instanceStyle.textContent = `
          ol[data-list-instance="${instanceId}"] li::before {
            counter-increment: greek-counter;
            content: attr(data-greek-number);
            font-weight: bold;
            color: ${markerColor} !important;
            margin-right: 0.5rem;
            display: inline-block;
          }
          ol[data-list-instance="${instanceId}"] {
            counter-reset: greek-counter;
          }
          ol[data-list-instance="${instanceId}"] li {
            color: inherit;
          }
        `
        document.head.appendChild(instanceStyle)
      }
    }
  }

  private addCircledNumberStyles(element: HTMLElement, markerColor: string): void {
    // Criar estilos CSS para números circulados se ainda não existirem
    const styleId = `circled-number-${markerColor.replace(/[^\w]/g, '')}`
    const instanceId = element.getAttribute("data-list-instance")
    
    if (!document.querySelector(`#${styleId}`)) {
      const style = document.createElement('style')
      style.id = styleId
      style.textContent = `
        ol[data-list-style-type="circled"] {
          counter-reset: circled-counter;
        }
        ol[data-list-style-type="circled"] li::before {
          counter-increment: circled-counter;
          content: "(" counter(circled-counter) ")";
          font-weight: bold;
          color: ${markerColor} !important;
          margin-right: 0.5rem;
          display: inline-block;
        }
        ol[data-list-style-type="circled"] li {
          color: inherit; /* Manter cor do texto normal */
        }
      `
      document.head.appendChild(style)
    }
    
    // Aplicar estilo específico para a instância
    if (instanceId) {
      const specificStyleId = `circled-instance-${instanceId}`
      if (!document.querySelector(`#${specificStyleId}`)) {
        const instanceStyle = document.createElement('style')
        instanceStyle.id = specificStyleId
        instanceStyle.textContent = `
          ol[data-list-instance="${instanceId}"] li::before {
            counter-increment: circled-counter;
            content: "(" counter(circled-counter) ")";
            font-weight: bold;
            color: ${markerColor} !important;
            margin-right: 0.5rem;
            display: inline-block;
          }
          ol[data-list-instance="${instanceId}"] {
            counter-reset: circled-counter;
          }
          ol[data-list-instance="${instanceId}"] li {
            color: inherit;
          }
        `
        document.head.appendChild(instanceStyle)
      }
    }
  }

  private addArrowListStyles(element: HTMLElement, markerColor: string): void {
    const instanceId = element.getAttribute("data-list-instance")
    
    if (instanceId) {
      const specificStyleId = `arrow-instance-${instanceId}`
      // Remover estilo anterior se existir
      const oldStyle = document.querySelector(`#${specificStyleId}`)
      if (oldStyle) {
        oldStyle.remove()
      }
      
      const instanceStyle = document.createElement('style')
      instanceStyle.id = specificStyleId
      const listTag = this.getListType() === "bullet" ? "ul" : "ol"
      
      instanceStyle.textContent = `
        ${listTag}[data-list-instance="${instanceId}"] {
          list-style: none;
        }
        ${listTag}[data-list-instance="${instanceId}"] li::before {
          content: "▶";
          font-weight: bold;
          color: ${markerColor} !important;
          margin-right: 0.5rem;
          display: inline-block;
        }
        ${listTag}[data-list-instance="${instanceId}"] li {
          color: inherit !important;
        }
        .lexical-editor ${listTag}[data-list-instance="${instanceId}"] li::before {
          color: ${markerColor} !important;
        }
      `
      document.head.appendChild(instanceStyle)
    }
  }

  private addStarListStyles(element: HTMLElement, markerColor: string): void {
    const instanceId = element.getAttribute("data-list-instance")
    
    if (instanceId) {
      const specificStyleId = `star-instance-${instanceId}`
      // Remover estilo anterior se existir
      const oldStyle = document.querySelector(`#${specificStyleId}`)
      if (oldStyle) {
        oldStyle.remove()
      }
      
      const instanceStyle = document.createElement('style')
      instanceStyle.id = specificStyleId
      const listTag = this.getListType() === "bullet" ? "ul" : "ol"
      
      instanceStyle.textContent = `
        ${listTag}[data-list-instance="${instanceId}"] {
          list-style: none;
        }
        ${listTag}[data-list-instance="${instanceId}"] li::before {
          content: "★";
          font-weight: bold;
          color: ${markerColor} !important;
          margin-right: 0.5rem;
          display: inline-block;
        }
        ${listTag}[data-list-instance="${instanceId}"] li {
          color: inherit !important;
        }
        .lexical-editor ${listTag}[data-list-instance="${instanceId}"] li::before {
          color: ${markerColor} !important;
        }
      `
      document.head.appendChild(instanceStyle)
    }
  }

  static importJSON(serializedNode: SerializedLexicalNode & Record<string, unknown>): CustomListNode {
    const payload = serializedNode as Partial<SerializedCustomListNode>
    const listType = payload.listType ?? "number"
    const start = payload.start ?? 1
    const listStyleType = payload.listStyleType
    const markerColor = payload.markerColor
    const node = new CustomListNode(listType as ListType, start, listStyleType, markerColor)
    
    // IMPORTANTE: Sempre definir a cor, incluindo a padrão
    // Se não há cor salva, usar a padrão
    const finalColor = markerColor || "#3b82f6"
    node.__markerColor = finalColor
    
    return node
  }

  exportJSON(): SerializedCustomListNode {
    return {
      ...super.exportJSON(),
      listStyleType: this.__listStyleType,
      markerColor: this.__markerColor || "#3b82f6",
      type: "custom-list",
    }
  }
}

export function $createCustomListNode(
  listType: ListType,
  start = 1,
  listStyleType = "decimal",
  markerColor = "#3b82f6" // Sempre definir cor padrão
): CustomListNode {
  return new CustomListNode(listType, start, listStyleType, markerColor)
}

export function $isCustomListNode(
  node: LexicalNode | null | undefined
): node is CustomListNode {
  return node instanceof CustomListNode
}

"use client"

import { useState } from "react"
import type { SerializedAudioNode } from "../../nodes/audio-node"

export function PreviewAudio({ node }: { node: SerializedAudioNode }) {
  const [hasError, setHasError] = useState(false)

  if (!node?.data) {
    console.error("Invalid audio node structure:", node)
    return null
  }

  const { src, title, artist, caption, size = 100 } = node.data as any

  // Verificar se é um áudio incorporado
  const getAudioEmbedInfo = (url: string): { type: string; id: string } | null => {
    if (!url) return null
    
    // YouTube
    const youtubeRegex = /(?:youtube\.com\/(?:[^/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?/\s]{11})/i
    const youtubeMatch = url.match(youtubeRegex)
    if (youtubeMatch && youtubeMatch[1]) {
      return { type: "youtube", id: youtubeMatch[1] }
    }

    // Spotify
    const spotifyRegex = /(?:spotify\.com\/track\/|spotify:track:)([a-zA-Z0-9]+)/i
    const spotifyMatch = url.match(spotifyRegex)
    if (spotifyMatch && spotifyMatch[1]) {
      return { type: "spotify", id: spotifyMatch[1] }
    }

    // SoundCloud
    const soundcloudRegex = /soundcloud\.com\/([^/]+\/[^/]+)/i
    const soundcloudMatch = url.match(soundcloudRegex)
    if (soundcloudMatch && soundcloudMatch[1]) {
      return { type: "soundcloud", id: soundcloudMatch[1] }
    }

    return null
  }

  const embedInfo = getAudioEmbedInfo(src)

  // Extrair nome do arquivo de áudio da URL
  const getAudioTitle = () => {
    if (title) return title

    try {
      const url = new URL(src)
      const pathSegments = url.pathname.split("/")
      const filename = pathSegments[pathSegments.length - 1] ?? ''
      return decodeURIComponent(filename.split(".")[0] ?? 'Audio')
    } catch (e) {
      return "Audio"
    }
  }

  // Renderizar áudio incorporado
  if (embedInfo) {
    let embedUrl = ""
    let embedTitle = ""
    let height = "80"
    let className = "w-full rounded-lg border"

    switch (embedInfo.type) {
      case "youtube":
        // Adicionar parâmetros para ocultar o vídeo e mostrar apenas os controles
        // Adicionando vq=small para forçar qualidade 144p e economizar recursos
        embedUrl = `https://www.youtube-nocookie.com/embed/${embedInfo.id}?feature=oembed&enablejsapi=1&showinfo=0&controls=1&disablekb=1&rel=0&modestbranding=1&vq=small&iv_load_policy=3&fs=0`
        embedTitle = "YouTube audio player"
        height = "60" // Altura reduzida para mostrar apenas os controles
        className = "w-full rounded-lg border youtube-audio-embed" // Classe especial para estilização
        break
      case "spotify":
        embedUrl = `https://open.spotify.com/embed/track/${embedInfo.id}`
        embedTitle = "Spotify audio player"
        height = "80"
        break
      case "soundcloud":
        embedUrl = `https://w.soundcloud.com/player/?url=https%3A//soundcloud.com/${embedInfo.id}&color=%23ff5500&auto_play=false&hide_related=false&show_comments=true&show_user=true&show_reposts=false&show_teaser=true`
        embedTitle = "SoundCloud audio player"
        height = "166"
        break
      default:
        return null
    }

    return (
      <div className="my-4 relative" style={{ width: `${size}%`, margin: "0 auto" }}>
        <iframe
          src={embedUrl}
          title={embedTitle}
          className={className}
          height={height}
          allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture"
          loading="lazy"
          // @ts-expect-error credentialless is not yet in React's iframe types
          credentialless="true"
        ></iframe>
        {caption && <div className="mt-2 text-sm text-muted-foreground text-center">{caption}</div>}
      </div>
    )
  }

  // Renderizar áudio nativo
  return (
    <div className="my-4 relative">
      <div className="w-full rounded-lg border bg-card p-4" style={{ width: `${size}%`, margin: "0 auto" }}>
        <div className="flex flex-col gap-2">
          <div className="flex items-center justify-between">
            <div className="font-medium truncate">{getAudioTitle()}</div>
            {artist && <div className="text-sm text-muted-foreground">{artist}</div>}
          </div>

          <audio src={src} controls className="w-full" preload="metadata" onError={() => setHasError(true)} />
        </div>
      </div>
      {caption && <div className="mt-2 text-sm text-muted-foreground text-center">{caption}</div>}
    </div>
  )
}

"use client"

import type { SerializedButtonNode } from "../../nodes/button-node"
import { Copy, Download, ExternalLink, Mail,
  Link, Link2,
  ArrowDownToLine, FileDown,
  ClipboardCopy, CopyCheck,
  AtSign, Send
} from "lucide-react"
import {
  BASE_BUTTON_STYLES,
  getSizeStyles,
  getVariantBaseStyles,
  getLayoutStyles,
  getIconSpacingClass,
  getIconSizeClass,
  getColorStyles,
  getFontFamilyClass,
  getFontSizeClass,
} from "@/components/block-content-editor/extras/button/button-styles"

export function PreviewButton({ node }: { node: SerializedButtonNode }) {
  if (!node?.data) {
    console.error("Invalid button node structure:", node)
    return null
  }

  const { text, url, actionType, variant, size, showIcon, iconVariant, iconPosition, iconSize, colorPalette, customColors, fontFamily, fontSize } = node.data

  const getActionIcon = () => {
    const iconSizeClass = getIconSizeClass(size, iconSize || "md")

    const iconsByType = {
      url: [
        <ExternalLink className={iconSizeClass} key="url-0" />,
        <Link2 className={iconSizeClass} key="url-1" />,
        <Link className={iconSizeClass} key="url-2" />,
      ],
      download: [
        <Download className={iconSizeClass} key="download-0" />,
        <ArrowDownToLine className={iconSizeClass} key="download-1" />,
        <FileDown className={iconSizeClass} key="download-2" />,
      ],
      copy: [
        <Copy className={iconSizeClass} key="copy-0" />,
        <ClipboardCopy className={iconSizeClass} key="copy-1" />,
        <CopyCheck className={iconSizeClass} key="copy-2" />,
      ],
      email: [
        <Mail className={iconSizeClass} key="email-0" />,
        <AtSign className={iconSizeClass} key="email-1" />,
        <Send className={iconSizeClass} key="email-2" />,
      ],
    }

    return iconsByType[actionType][iconVariant || 0] || iconsByType[actionType][0]
  }

  const getButtonStyles = () => {
    const isVerticalIcon = showIcon && (iconPosition === "top" || iconPosition === "bottom")
    const palette = colorPalette || "blue"
    const font = fontFamily || "sans"
    const textSize = fontSize || "md"
    return `${BASE_BUTTON_STYLES} cursor-pointer ${getSizeStyles(size, isVerticalIcon)} ${getVariantBaseStyles(variant, size)} ${getColorStyles(palette, variant)} ${getLayoutStyles(iconPosition || "right")} ${getFontFamilyClass(font)} ${getFontSizeClass(size, textSize)}`
  }

  const getCustomStyle = () => {
    if (colorPalette === "custom" && customColors) {
      const { primary, secondary, text, hoverPrimary, hoverSecondary, hoverText } = customColors
      if (variant === "solid") {
        return {
          background: `linear-gradient(to right, ${primary}, ${secondary})`,
          color: text,
          "--hover-bg": `linear-gradient(to right, ${hoverPrimary}, ${hoverSecondary})`,
          "--hover-text": hoverText,
        } as React.CSSProperties
      } else if (variant === "outline") {
        return {
          borderColor: primary,
          color: text,
          "--hover-bg": hoverPrimary,
          "--hover-border": hoverPrimary,
          "--hover-text": hoverText,
        } as React.CSSProperties
      } else if (variant === "soft") {
        return {
          backgroundColor: `${primary}20`,
          color: text,
          "--hover-bg": `${hoverPrimary}30`,
          "--hover-text": hoverText,
        } as React.CSSProperties
      } else if (variant === "minimal") {
        return {
          color: text,
          "--hover-border": hoverPrimary,
          "--hover-text": hoverText,
        } as React.CSSProperties
      }
    }
    return {}
  }

  const handleButtonAction = () => {
    switch (actionType) {
      case "url":
        window.open(url, "_blank")
        break
      case "download": {
        const link = document.createElement("a")
        link.href = url
        link.download = ""
        document.body.appendChild(link)
        link.click()
        document.body.removeChild(link)
        break
      }
      case "copy":
        navigator.clipboard.writeText(url)
        break
      case "email":
        window.location.href = `mailto:${url}`
        break
    }
  }

  const iconSpacingClass = getIconSpacingClass(iconPosition || "right")

  return (
    <div className="my-4 flex justify-center">
      <style>{`
        .custom-button-hover:hover {
          background: var(--hover-bg) !important;
          color: var(--hover-text) !important;
          border-color: var(--hover-border) !important;
        }
      `}</style>
      <button 
        className={`${getButtonStyles()} ${colorPalette === "custom" ? "custom-button-hover" : ""}`}
        style={getCustomStyle()}
        onClick={handleButtonAction}
      >
        {text}
        {showIcon && <span className={iconSpacingClass}>{getActionIcon()}</span>}
      </button>
    </div>
  )
}

"use client"

import { ImageIcon } from 'lucide-react'
import type { SerializedGalleryNode } from "../../nodes/gallery-node"
import { AssetImage } from "../../extras/media/asset-image"

export function PreviewGallery({ node }: { node: SerializedGalleryNode }) {
  if (!node?.data) {
    console.error("Invalid gallery node structure:", node)
    return null
  }

  const { layout, caption, images } = node.data
  const captionStyle = (node.data as any).captionStyle

  // Get caption style classes
  const getCaptionStyleClasses = () => {
    const classes = ["text-center text-muted-foreground"]

    // Font size
    if (captionStyle?.fontSize === "xs") classes.push("text-xs")
    else if (captionStyle?.fontSize === "sm") classes.push("text-sm")
    else if (captionStyle?.fontSize === "base") classes.push("text-base")
    else if (captionStyle?.fontSize === "lg") classes.push("text-lg")
    else classes.push("text-sm") // Default

    // Font family
    if (captionStyle?.fontFamily === "serif") classes.push("font-serif")
    else if (captionStyle?.fontFamily === "mono") classes.push("font-mono")
    else classes.push("font-sans") // Default

    // Font weight
    if (captionStyle?.fontWeight === "medium") classes.push("font-medium")
    else if (captionStyle?.fontWeight === "normal") classes.push("font-normal")
    else if (captionStyle?.fontWeight === "bold") classes.push("font-bold")
    else classes.push("font-normal") // Default

    return classes.join(" ")
  }

  if (images.length === 0) {
    return (
      <div className="my-4 flex items-center justify-center h-40 bg-muted/20 rounded-lg border border-dashed">
        <div className="text-center">
          <ImageIcon className="h-8 w-8 mx-auto text-muted-foreground" />
          <p className="mt-2 text-sm text-muted-foreground">No images in gallery</p>
        </div>
      </div>
    )
  }

  // Get grid template columns based on layout
  const getGridTemplateColumns = () => {
    return `repeat(${layout}, 1fr)`
  }

  return (
    <div className="my-4">
      <div
        className="grid gap-2"
        style={{
          gridTemplateColumns: getGridTemplateColumns(),
          gridAutoRows: "auto",
        }}
      >
        {images.map((image) => {
          // Check if this is a placeholder (empty src means it's a placeholder)
          const isPlaceholder = !image.src || image.src.trim() === ''

          // Calculate grid area style
          const gridAreaStyle = {
            gridRow: image.span === "2x1" || image.span === "2x2" ? "span 2" : undefined,
            gridColumn: image.span === "1x2" || image.span === "2x2" ? "span 2" : undefined,
          }

          return (
            <div key={image.id} className="space-y-1" style={gridAreaStyle}>
              <div
                className="relative overflow-hidden rounded-md"
                style={{ aspectRatio: image.displayMode === "crop" ? "1/1" : "16/9" }}
              >
                {isPlaceholder || !image.src ? (
                  // Render empty space for placeholders - maintains aspect ratio from parent
                  <div className="h-full w-full" />
                ) : (
                  // Render actual image
                  <AssetImage
                    src={image.src}
                    alt={image.alt}
                    className={
                      image.displayMode === "crop" ? "h-full w-full object-cover" : "h-auto w-full object-contain"
                    }
                  />
                )}
              </div>
              {image.caption && <div className={getCaptionStyleClasses()}>{image.caption}</div>}
            </div>
          )
        })}
      </div>
      {caption && <div className={`mt-2 ${getCaptionStyleClasses()}`}>{caption}</div>}
    </div>
  )
}

"use client"

import React from "react"

interface PreviewHeadingProps {
  node: any
  children: React.ReactNode
  index?: number
}

export function PreviewHeading({ node, children, index = 0 }: PreviewHeadingProps) {
  const headingClasses = ["font-bold my-4"]
  if (node.format === "left") headingClasses.push("text-left")
  else if (node.format === "center") headingClasses.push("text-center")
  else if (node.format === "right") headingClasses.push("text-right")
  else if (node.format === "justify") headingClasses.push("text-justify")

  // Get inline styles from the node if they exist
  const headingStyles: React.CSSProperties = {}
  if (node.style) {
    const styleString = node.style
    const styleRules = styleString.split(";").filter((rule: string) => rule.trim())

    styleRules.forEach((rule: { split: (arg0: string) => { (): any; new(): any; map: { (arg0: (s: any) => any): [any, any]; new(): any } } }) => {
      const [property, value] = rule.split(":").map((s) => s.trim())
      if (property && value) {
        const camelCaseProperty = property.replace(/-([a-z])/g, (match: any, letter: string) => letter.toUpperCase())
        headingStyles[camelCaseProperty as keyof React.CSSProperties] = value
      }
    })
  }

  const extractTextFromChildren = (children: React.ReactNode): string => {
    if (typeof children === "string") return children
    if (typeof children === "number") return children.toString()
    if (Array.isArray(children)) {
      return children.map(extractTextFromChildren).join("")
    }
    if (React.isValidElement(children)) {
      // Type guard to safely access props.children
      const element = children as React.ReactElement<{ children?: React.ReactNode }>
      if (element.props && "children" in element.props) {
        return extractTextFromChildren(element.props.children)
      }
    }
    return ""
  }

  const headingText = extractTextFromChildren(children)
  const headingId = `heading-${index}`

  console.log("[v0] PreviewHeading - Generated heading ID:", headingId)
  console.log("[v0] PreviewHeading - Index received:", index)
  console.log("[v0] PreviewHeading - Heading text:", headingText)

  const commonProps = {
    className: headingClasses.join(" "),
    style: headingStyles,
    "data-heading-id": headingId,
    children,
  }

  switch (node.tag) {
    case "h1":
    case 1:
      return (
        <h1 className={`text-4xl ${headingClasses.join(" ")}`} style={headingStyles} data-heading-id={headingId}>
          {children}
        </h1>
      )
    case "h2":
    case 2:
      return (
        <h2 className={`text-3xl ${headingClasses.join(" ")}`} style={headingStyles} data-heading-id={headingId}>
          {children}
        </h2>
      )
    case "h3":
    case 3:
      return (
        <h3 className={`text-2xl ${headingClasses.join(" ")}`} style={headingStyles} data-heading-id={headingId}>
          {children}
        </h3>
      )
    case "h4":
    case 4:
      return (
        <h4 className={`text-xl ${headingClasses.join(" ")}`} style={headingStyles} data-heading-id={headingId}>
          {children}
        </h4>
      )
    case "h5":
    case 5:
      return (
        <h5 className={`text-lg ${headingClasses.join(" ")}`} style={headingStyles} data-heading-id={headingId}>
          {children}
        </h5>
      )
    case "h6":
    case 6:
      return (
        <h6 className={`text-base ${headingClasses.join(" ")}`} style={headingStyles} data-heading-id={headingId}>
          {children}
        </h6>
      )
    default:
      return (
        <h2 className={`text-3xl ${headingClasses.join(" ")}`} style={headingStyles} data-heading-id={headingId}>
          {children}
        </h2>
      )
  }
}

"use client"

import { useEffect, useMemo, useRef, useState } from "react"

import type { SerializedHTMLNode } from "../../nodes/html-node"
import { buildHTMLPreviewSrcDoc } from "../../extras/html/html-utils"

/**
 * Read-only preview of an "html" custom-node. Mirrors the editor's
 * sandbox model: no scripts, no same-origin, cross-file references
 * resolved against the block's `files` array via data URLs.
 *
 * The iframe self-reports its scroll height on load so the surrounding
 * page can flow naturally.
 */
export function PreviewHTML({ node }: { node: SerializedHTMLNode }) {
  const iframeRef = useRef<HTMLIFrameElement>(null)
  const [height, setHeight] = useState(0)

  const files = node.data.files ?? []
  const srcDoc = useMemo(() => buildHTMLPreviewSrcDoc(files), [files])

  useEffect(() => {
    const iframe = iframeRef.current
    if (!iframe) return
    const onLoad = () => {
      try {
        const doc = iframe.contentDocument
        if (doc?.documentElement) {
          setHeight(doc.documentElement.scrollHeight)
        }
      } catch {
        // Ignore — sandbox=" " keeps us same-origin-less.
      }
    }
    iframe.addEventListener("load", onLoad)
    return () => iframe.removeEventListener("load", onLoad)
  }, [srcDoc])

  return (
    <div className="my-0">
      <iframe
        ref={iframeRef}
        srcDoc={srcDoc}
        className="w-full rounded-md border"
        style={{ height: height ? `${height + 2}px` : "120px" }}
        sandbox=""
        title="HTML Preview"
      />
    </div>
  )
}

