"use client"

import type React from "react"
import type { SerializedTextNode } from "lexical"

interface PreviewTextProps {
  node: Pick<SerializedTextNode, "text"> & Partial<Pick<SerializedTextNode, "style" | "format" | "version">>
}

export function PreviewText({ node }: PreviewTextProps) {
  let textContent: React.ReactNode = node.text

  // Get inline styles from the node
  const inlineStyles: React.CSSProperties & Record<string, string> = {}
  if (node.style) {
    // Parse the style string and convert to React CSSProperties
    const styleString = node.style
    const styleRules = styleString.split(";").filter((rule: string) => rule.trim())

    styleRules.forEach((rule: string) => {
      const [property, value] = rule.split(":").map((s: string) => s.trim())
      if (property && value) {
        // Convert CSS property names to camelCase for React
        const camelCaseProperty = property.replace(/-([a-z])/g, (_match: string, letter: string) => letter.toUpperCase())
        ;(inlineStyles as Record<string, string>)[camelCaseProperty] = value
      }
    })
  }

  // Apply text formatting
  if (node.format) {
    if (node.format & 1) {
      // Bold
      textContent = (
        <strong key={`bold-${node.version || Math.random()}`} style={inlineStyles}>
          {textContent}
        </strong>
      )
    }
    if (node.format & 2) {
      // Italic
      textContent = (
        <em key={`italic-${node.version || Math.random()}`} style={inlineStyles}>
          {textContent}
        </em>
      )
    }
    if (node.format & 8) {
      // Underline (format flag 4)
      textContent = (
        <u key={`underline-${node.version || Math.random()}`} style={inlineStyles}>
          {textContent}
        </u>
      )
    }
    if (node.format & 4) {
      // Strikethrough (format flag 8)
      textContent = (
        <s key={`strikethrough-${node.version || Math.random()}`} style={inlineStyles}>
          {textContent}
        </s>
      )
    }
    if (node.format & 32) {
      // Subscript (format flag 32)
      textContent = (
        <sub key={`subscript-${node.version || Math.random()}`} style={inlineStyles}>
          {textContent}
        </sub>
      )
    }
    if (node.format & 64) {
      // Superscript (format flag 16)
      textContent = (
        <sup key={`superscript-${node.version || Math.random()}`} style={inlineStyles}>
          {textContent}
        </sup>
      )
    }
    if (node.format & 64) {
      // Code
      textContent = (
        <code
          key={`code-${node.version || Math.random()}`}
          style={inlineStyles}
          className="bg-muted px-1 py-0.5 rounded text-sm"
        >
          {textContent}
        </code>
      )
    }
    if (node.format & 128) {
      // Assuming format flag 128 for short quote
      textContent = (
        <q key={`quote-${node.version || Math.random()}`} style={inlineStyles}>
          {textContent}
        </q>
      )
    }
  } else if (Object.keys(inlineStyles).length > 0) {
    // Apply inline styles even if no formatting flags are set
    textContent = (
      <span key={`styled-${node.version || Math.random()}`} style={inlineStyles}>
        {textContent}
      </span>
    )
  }

  return <>{textContent}</>
}

"use client"

import { ProjectExporter, type ProjectData as ExportProjectData, type ProjectMetadata } from "../../lib/interopAdapter/project-exporter"
import { ProjectImporter, type FolderStructureData } from "../../lib/interopAdapter/project-importer"
import { HashManager } from "../../lib/sync/editor/hash-manager"

interface GoogleDriveFile {
  id: string
  name: string
  mimeType: string
  createdTime: string
  modifiedTime: string
  size?: string
}

interface GoogleDriveProjectData {
  id: string
  name: string
  data: string
  tags: string[]
  size: number
  createdAt: string
  updatedAt: string
  hash: string
  driveFileId?: string
  storageType: string
}

type GoogleDriveProjectMetadata = Pick<ProjectMetadata,
  "id" | "name" | "tags" | "size" | "createdAt" | "updatedAt" | "hash">

type ValidProjectData = Pick<GoogleDriveProjectData,
  "id" | "name" | "data" | "tags" | "createdAt" | "updatedAt">

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

export class GoogleDriveService {
  private static instance: GoogleDriveService
  private folderId: string | null = null
  private accessToken: string | null = null
  private readyState: boolean | null = null // Cache for isReady state
  private lastReadyCheck: number = 0
  private readonly READY_CHECK_CACHE_MS = 5000 // Cache isReady for 5 seconds

  private constructor() {
    // Load saved folder ID
    if (typeof window !== 'undefined') {
      this.folderId = localStorage.getItem('block-content-editor_google_drive_folder')
    }
  }

  static getInstance(): GoogleDriveService {
    if (!GoogleDriveService.instance) {
      GoogleDriveService.instance = new GoogleDriveService()
    }
    return GoogleDriveService.instance
  }

  // Set authentication token and folder
  setAuth(accessToken: string, folderId: string) {
    this.accessToken = accessToken
    this.folderId = folderId
    this.readyState = null // Reset cache when auth changes
  }

  // Check if service is ready (with caching)
  isReady(): boolean {
    const now = Date.now()

    // Return cached result if within cache period
    if (this.readyState !== null && (now - this.lastReadyCheck) < this.READY_CHECK_CACHE_MS) {
      return this.readyState
    }

    const hasToken = !!this.accessToken
    const hasFolder = !!this.folderId
    const hasGapi = !!(window.gapi?.client?.drive)

    this.readyState = hasToken && hasFolder && hasGapi
    this.lastReadyCheck = now

    if (this.readyState) {
      console.log("GoogleDriveService ready:", {
        hasToken,
        hasFolder,
        hasGapi,
        folderId: this.folderId
      })
    }

    return this.readyState
  }

  // Set authentication token for GAPI client
  private setAuthToken() {
    if (this.accessToken && window.gapi?.client) {
      window.gapi.client.setToken({ access_token: this.accessToken })
    }
  }

  // Upload file content as JSON
  private async uploadJsonFile(
    fileName: string,
    content: object,
    fileId?: string
  ): Promise<string | null> {
    if (!this.isReady()) {
      throw new Error('Google Drive service not ready')
    }

    const jsonContent = JSON.stringify(content, null, 2)
    const metadata = {
      name: fileName,
      parents: fileId ? undefined : [this.folderId!],
      mimeType: 'application/json',
    }

    try {
      const form = new FormData()
      form.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }))
      form.append('file', new Blob([jsonContent], { type: 'application/json' }))

      const url = fileId
        ? `https://www.googleapis.com/upload/drive/v3/files/${fileId}?uploadType=multipart`
        : 'https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart'

      const method = fileId ? 'PATCH' : 'POST'

      const response = await fetch(url, {
        method,
        headers: {
          'Authorization': `Bearer ${this.accessToken}`,
        },
        body: form,
      })

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`)
      }

      const result = await response.json()
      return result.id
    } catch (error) {
      console.error('Failed to upload file:', error)
      throw new Error('Falha ao salvar arquivo no Google Drive')
    }
  }

  // Download file content
  private async downloadJsonFile(fileId: string): Promise<unknown> {
    if (!this.isReady()) {
      throw new Error('Google Drive service not ready')
    }

    try {
      // Set auth token before API call
      this.setAuthToken()

      const response = await window.gapi.client.drive.files.get({
        fileId: fileId,
        alt: 'media',
      })

      return JSON.parse(response.body)
    } catch (error) {
      console.error('Failed to download file:', error)
      return null
    }
  }

  // List projects using new folder structure
  async listProjects(): Promise<GoogleDriveProjectData[]> {
    if (!this.isReady()) {
      return []
    }

    try {
      // Set auth token before API call
      this.setAuthToken()

      // Find all project folders (projeto-*)
      const response = await window.gapi.client.drive.files.list({
        q: `'${this.folderId}' in parents and mimeType='application/vnd.google-apps.folder' and name contains 'projeto-' and trashed=false`,
        fields: 'files(id, name, createdTime, modifiedTime)',
        orderBy: 'modifiedTime desc',
      })

      const projectFolders = response.result.files || []
      const projects: GoogleDriveProjectData[] = []

      // For each project folder, get metadata from index.json
      for (const folder of projectFolders) {
        try {
          const indexFileResponse = await window.gapi.client.drive.files.list({
            q: `'${folder.id}' in parents and name='index.json' and trashed=false`,
            fields: 'files(id)',
          })

          const indexFile = indexFileResponse.result.files?.[0]
          if (indexFile) {
            const metadata = await this.downloadJsonFile(indexFile.id!)
            if (this.isValidProjectMetadata(metadata)) {
              projects.push({
                id: metadata.id,
                name: metadata.name,
                data: "", // Placeholder - actual data loaded when opening project
                tags: metadata.tags,
                size: metadata.size,
                createdAt: metadata.createdAt,
                updatedAt: metadata.updatedAt,
                hash: metadata.hash,
                driveFileId: folder.id!, // Use folder ID for reference
                storageType: "google-drive"
              })
            }
          }
        } catch (error) {
          console.error(`Failed to load project metadata from folder ${folder.name}:`, error)
        }
      }

      return projects
    } catch (error) {
      console.error('Failed to list projects:', error)
      return []
    }
  }

  // Save project to Google Drive using new folder structure
  async saveProject(
    id: string,
    name: string,
    data: string,
    tags: string[]
  ): Promise<void> {
    if (!this.isReady()) {
      throw new Error('Google Drive service not ready')
    }

    this.setAuthToken()

    const hash = await HashManager.generateHash(data)

    try {
      // 1. Prepare project data for export using ProjectExporter
      const projectData: ExportProjectData = {
        id,
        name,
        data,
        tags,
        size: new Blob([data]).size,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        hash,
        storageType: "google-drive"
      }

      const exportedProject = await ProjectExporter.prepareForExport(projectData, hash)
      if (exportedProject.assets.length > 0) {
        throw new Error(
          "Google Drive folder sync cannot carry browser-local assets yet. Download a ZIP bundle instead.",
        )
      }

      // 2. Create or find project folder
      let projectFolderId = await this.findProjectFolder(exportedProject.folderName)

      if (!projectFolderId) {
        projectFolderId = await this.createProjectFolder(exportedProject.folderName)
      }

      // 3. Save index.json (metadata) using ProjectExporter format
      await this.saveFileToFolder(
        projectFolderId,
        'index.json',
        JSON.stringify(exportedProject.metadata, null, 2),
        'application/json'
      )

      // 4. Save data file using ProjectExporter format
      await this.saveFileToFolder(
        projectFolderId,
        'data.block-content-editor',
        exportedProject.data,
        'application/json'
      )

      console.log(`Project ${id} saved successfully to Google Drive using ProjectExporter`)

    } catch (error) {
      console.error('Save project failed:', error)
      throw error
    }
  }

  // Helper: Find project folder by name
  private async findProjectFolder(folderName: string): Promise<string | null> {
    try {
      const response = await window.gapi.client.drive.files.list({
        q: `name='${folderName}' and mimeType='application/vnd.google-apps.folder' and parents in '${this.folderId}' and trashed=false`,
        fields: 'files(id, name)',
      })

      return response.result.files?.[0]?.id || null
    } catch (error) {
      console.error('Failed to find project folder:', error)
      return null
    }
  }

  // Helper: Create project folder
  private async createProjectFolder(folderName: string): Promise<string> {
    try {
      const response = await window.gapi.client.drive.files.create({
        resource: {
          name: folderName,
          mimeType: 'application/vnd.google-apps.folder',
          parents: [this.folderId!],
        },
        fields: 'id',
      })

      return response.result.id!
    } catch (error) {
      console.error('Failed to create project folder:', error)
      throw error
    }
  }

  // Helper: Save file to specific folder
  private async saveFileToFolder(
    folderId: string,
    fileName: string,
    content: string,
    mimeType: string
  ): Promise<string> {
    try {
      // Check if file already exists
      const existingFileResponse = await window.gapi.client.drive.files.list({
        q: `name='${fileName}' and parents in '${folderId}' and trashed=false`,
        fields: 'files(id)',
      })

      const existingFileId = existingFileResponse.result.files?.[0]?.id

      if (existingFileId) {
        // Update existing file
        const response = await window.gapi.client.request({
          path: `https://www.googleapis.com/upload/drive/v3/files/${existingFileId}`,
          method: 'PATCH',
          params: {
            uploadType: 'media',
          },
          headers: {
            'Content-Type': mimeType,
          },
          body: content,
        })
        return existingFileId
      } else {
        // Create new file
        const response = await window.gapi.client.request({
          path: 'https://www.googleapis.com/upload/drive/v3/files',
          method: 'POST',
          params: {
            uploadType: 'multipart',
          },
          headers: {
            'Content-Type': 'multipart/related; boundary="foo_bar_baz"',
          },
          body: this.createMultipartBody(fileName, content, mimeType, folderId),
        })
        return response.result.id
      }
    } catch (error) {
      console.error(`Failed to save file ${fileName}:`, error)
      throw error
    }
  }

  // Helper: Create multipart body for file upload
  private createMultipartBody(
    fileName: string,
    content: string,
    mimeType: string,
    parentId: string
  ): string {
    const metadata = {
      name: fileName,
      parents: [parentId],
    }

    const delimiter = 'foo_bar_baz'
    const close_delim = `\r\n--${delimiter}--`

    let body = `--${delimiter}\r\n`
    body += 'Content-Type: application/json\r\n\r\n'
    body += JSON.stringify(metadata) + '\r\n'
    body += `--${delimiter}\r\n`
    body += `Content-Type: ${mimeType}\r\n\r\n`
    body += content
    body += close_delim

    return body
  }

  // Update existing project
  async updateProject(
    projectId: string,
    name: string,
    data: string,
    tags: string[]
  ): Promise<void> {
    const existingProjects = await this.listProjects()
    const project = existingProjects.find(p => p.id === projectId)

    if (!project) {
      throw new Error('Project not found')
    }

    // Use the standard saveProject method which now uses ProjectExporter
    await this.saveProject(projectId, name, data, tags)
  }

  // Delete project from Google Drive
  async deleteProject(projectId: string): Promise<void> {
    if (!this.isReady()) {
      throw new Error('Google Drive service not ready')
    }

    const existingProjects = await this.listProjects()
    const project = existingProjects.find(p => p.id === projectId)

    if (!project) {
      throw new Error('Project not found')
    }

    try {
      // Set auth token before API call
      this.setAuthToken()

      await window.gapi.client.drive.files.delete({
        fileId: project.driveFileId!,
      })
    } catch (error) {
      console.error('Delete project failed:', error)
      throw new Error('Falha ao excluir projeto do Google Drive')
    }
  }

  // Get project by ID with full data
  async getProject(projectId: string): Promise<GoogleDriveProjectData | null> {
    console.log(`GoogleDriveService.getProject called with ID: ${projectId}`)

    if (!this.isReady()) {
      console.error("GoogleDriveService not ready in getProject")
      return null
    }

    try {
      this.setAuthToken()

      // Find project folder
      const projectFolderName = `projeto-${projectId}`
      console.log(`Looking for project folder: ${projectFolderName}`)
      const projectFolderId = await this.findProjectFolder(projectFolderName)

      if (!projectFolderId) {
        console.error(`Project folder not found: ${projectFolderName}`)
        return null
      }

      console.log(`Found project folder with ID: ${projectFolderId}`)

      // Get metadata from index.json
      const indexFileResponse = await window.gapi.client.drive.files.list({
        q: `'${projectFolderId}' in parents and name='index.json' and trashed=false`,
        fields: 'files(id)',
      })

      const indexFile = indexFileResponse.result.files?.[0]
      if (!indexFile) {
        console.error("index.json file not found in project folder")
        return null
      }

      console.log(`Found index.json with ID: ${indexFile.id}`)
      const indexData = await this.downloadJsonFile(indexFile.id!)
      if (!indexData) {
        console.error("Failed to download or parse index.json")
        return null
      }

      console.log("Downloaded index.json:", indexData)

      // Get data from data.block-content-editor file (updated to use new filename)
      const dataFileResponse = await window.gapi.client.drive.files.list({
        q: `'${projectFolderId}' in parents and name='data.block-content-editor' and trashed=false`,
        fields: 'files(id)',
      })

      const dataFile = dataFileResponse.result.files?.[0]
      if (!dataFile) {
        console.error("data.block-content-editor file not found in project folder")
        return null
      }

      console.log(`Found data.block-content-editor with ID: ${dataFile.id}`)
      const dataResponse = await window.gapi.client.drive.files.get({
        fileId: dataFile.id!,
        alt: 'media',
      })

      console.log("Downloaded data.block-content-editor content length:", dataResponse.body?.length)

      // Use ProjectImporter to process the folder structure
      const folderData: FolderStructureData = {
        indexContent: JSON.stringify(indexData),
        dataContent: dataResponse.body,
        folderName: projectFolderName
      }

      console.log("Calling ProjectImporter.importFromFolderStructure with:", {
        indexContentLength: folderData.indexContent.length,
        dataContentLength: folderData.dataContent.length,
        folderName: folderData.folderName
      })

      const importedProject = await ProjectImporter.importFromFolderStructure(folderData)

      console.log("ProjectImporter returned:", {
        id: importedProject?.id,
        name: importedProject?.name,
        dataLength: importedProject?.data?.length,
        tagsCount: importedProject?.tags?.length
      })

      // Validate that the imported project has the required data
      if (!importedProject || !importedProject.data) {
        console.error('ProjectImporter returned invalid data:', importedProject)
        return null
      }

      // Validate that the data is valid JSON
      try {
        JSON.parse(importedProject.data)
        console.log("Project data is valid JSON")
      } catch (parseError) {
        console.error('Project data is not valid JSON:', parseError, importedProject.data)
        return null
      }

      // Convert to GoogleDriveProjectData format
      const projectData = {
        id: importedProject.id,
        name: importedProject.name,
        data: importedProject.data,
        tags: importedProject.tags,
        size: importedProject.metadata?.size || new Blob([importedProject.data]).size,
        createdAt: importedProject.metadata?.createdAt || new Date().toISOString(),
        updatedAt: importedProject.metadata?.updatedAt || new Date().toISOString(),
        hash: importedProject.metadata?.hash || '',
        driveFileId: projectFolderId,
        storageType: "google-drive" as const
      }

      // Final validation
      if (!this.isValidProjectData(projectData)) {
        console.error('Generated project data is invalid:', projectData)
        return null
      }

      console.log("Returning valid project data:", {
        id: projectData.id,
        name: projectData.name,
        dataLength: projectData.data.length,
        storageType: projectData.storageType
      })

      return projectData

    } catch (error) {
      console.error(`Failed to get project ${projectId}:`, error)
      return null
    }
  }

  // Validate project data structure
  private isValidProjectData(data: unknown): data is ValidProjectData {
    return (
      isRecord(data) &&
      typeof data.id === 'string' &&
      typeof data.name === 'string' &&
      typeof data.data === 'string' &&
      Array.isArray(data.tags) &&
      data.tags.every((tag: unknown) => typeof tag === 'string') &&
      typeof data.createdAt === 'string' &&
      typeof data.updatedAt === 'string'
    )
  }

  // Validate project metadata structure (lighter validation for index.json)
  private isValidProjectMetadata(data: unknown): data is GoogleDriveProjectMetadata {
    return (
      isRecord(data) &&
      typeof data.id === 'string' &&
      typeof data.name === 'string' &&
      Array.isArray(data.tags) &&
      data.tags.every((tag: unknown) => typeof tag === 'string') &&
      typeof data.hash === 'string' &&
      typeof data.size === 'number' &&
      typeof data.createdAt === 'string' &&
      typeof data.updatedAt === 'string'
    )
  }

  // Search projects by name or tags
  async searchProjects(query: string): Promise<GoogleDriveProjectData[]> {
    const allProjects = await this.listProjects()

    if (!query.trim()) {
      return allProjects
    }

    const searchTerm = query.toLowerCase()

    return allProjects.filter(project =>
      project.name.toLowerCase().includes(searchTerm) ||
      project.tags.some(tag => tag.toLowerCase().includes(searchTerm))
    )
  }

  // Get storage statistics
  async getStorageStats(): Promise<{ totalSize: number; projectCount: number }> {
    const projects = await this.listProjects()

    return {
      totalSize: projects.reduce((total, project) => total + (project.size || 0), 0),
      projectCount: projects.length,
    }
  }

  // Cleanup - reset authentication
  cleanup() {
    this.accessToken = null
    this.folderId = null
  }
}

"use client"

/**
 * Security utilities for Google Drive integration
 * Implements additional security measures and validation
 */

interface TokenValidationResult {
  isValid: boolean
  expiresIn?: number
  error?: string
}

export class GoogleDriveSecurity {
  private static readonly MAX_TOKEN_AGE = 3600000 // 1 hour in milliseconds
  private static readonly ALLOWED_FILE_TYPES = ['application/json']
  private static readonly MAX_FILE_SIZE = 10 * 1024 * 1024 // 10MB

  /**
   * Validate access token and check expiration
   */
  static async validateToken(accessToken: string): Promise<TokenValidationResult> {
    try {
      const response = await fetch(
        `https://www.googleapis.com/oauth2/v1/tokeninfo?access_token=${accessToken}`
      )

      if (!response.ok) {
        return { isValid: false, error: 'Token validation failed' }
      }

      const tokenInfo = await response.json()

      // Check if token has expired
      const expiresIn = parseInt(tokenInfo.expires_in || '0')
      if (expiresIn <= 0) {
        return { isValid: false, error: 'Token has expired' }
      }

      // Check if token has the required scope
      const scopes = tokenInfo.scope?.split(' ') || []
      if (!scopes.includes('https://www.googleapis.com/auth/drive.file')) {
        return { isValid: false, error: 'Insufficient permissions' }
      }

      return { isValid: true, expiresIn }
    } catch (error) {
      console.error('Token validation error:', error)
      return { isValid: false, error: 'Token validation failed' }
    }
  }

  /**
   * Sanitize and validate file names
   */
  static sanitizeFileName(fileName: string): string {
    // Remove potentially dangerous characters
    const sanitized = fileName
      .replace(/[<>:"/\\|?*]/g, '_') // Replace invalid characters with underscore
      .replace(/\.\./g, '_') // Prevent directory traversal
      .replace(/^\./, '_') // Prevent hidden files
      .trim()

    // Ensure file has .block-content-editor.json extension
    if (!sanitized.endsWith('.block-content-editor.json')) {
      const baseName = sanitized.replace(/\.json$/, '').replace(/\.block-content-editor$/, '')
      return `${baseName}.block-content-editor.json`
    }

    return sanitized
  }

  /**
   * Validate project data before uploading
   */
  static validateProjectData(data: any): { isValid: boolean; error?: string } {
    if (!data || typeof data !== 'object') {
      return { isValid: false, error: 'Invalid data format' }
    }

    const requiredFields = ['id', 'name', 'data', 'tags', 'createdAt', 'updatedAt']
    for (const field of requiredFields) {
      if (!(field in data)) {
        return { isValid: false, error: `Missing required field: ${field}` }
      }
    }

    // Validate field types
    if (typeof data.id !== 'string' || data.id.length === 0) {
      return { isValid: false, error: 'Invalid project ID' }
    }

    if (typeof data.name !== 'string' || data.name.length === 0) {
      return { isValid: false, error: 'Invalid project name' }
    }

    if (typeof data.data !== 'string') {
      return { isValid: false, error: 'Invalid project data' }
    }

    if (!Array.isArray(data.tags)) {
      return { isValid: false, error: 'Invalid tags format' }
    }

    // Validate dates
    const createdAt = new Date(data.createdAt)
    const updatedAt = new Date(data.updatedAt)
    
    if (isNaN(createdAt.getTime()) || isNaN(updatedAt.getTime())) {
      return { isValid: false, error: 'Invalid date format' }
    }

    // Check data size
    const dataSize = JSON.stringify(data).length
    if (dataSize > this.MAX_FILE_SIZE) {
      return { isValid: false, error: 'Project data too large' }
    }

    return { isValid: true }
  }

  /**
   * Generate secure project ID
   */
  static generateSecureId(): string {
    const timestamp = Date.now().toString(36)
    const randomPart = Math.random().toString(36).substr(2, 9)
    return `ggl_${timestamp}_${randomPart}`
  }

  /**
   * Encrypt sensitive data before storing (simple obfuscation)
   */
  static obfuscateData(data: string): string {
    // Simple base64 encoding for basic obfuscation
    // In production, consider using proper encryption
    try {
      return btoa(unescape(encodeURIComponent(data)))
    } catch (error) {
      console.error('Data obfuscation failed:', error)
      return data
    }
  }

  /**
   * Decrypt obfuscated data
   */
  static deobfuscateData(data: string): string {
    try {
      return decodeURIComponent(escape(atob(data)))
    } catch (error) {
      console.error('Data deobfuscation failed:', error)
      return data
    }
  }

  /**
   * Rate limiting for API calls
   */
  private static lastApiCall = 0
  private static readonly MIN_API_INTERVAL = 100 // 100ms between API calls

  static async throttleApiCall<T>(apiCall: () => Promise<T>): Promise<T> {
    const now = Date.now()
    const timeSinceLastCall = now - this.lastApiCall

    if (timeSinceLastCall < this.MIN_API_INTERVAL) {
      await new Promise(resolve => 
        setTimeout(resolve, this.MIN_API_INTERVAL - timeSinceLastCall)
      )
    }

    this.lastApiCall = Date.now()
    return apiCall()
  }

  /**
   * Validate environment configuration
   */
  static validateEnvironment(): { isValid: boolean; errors: string[] } {
    const errors: string[] = []

    if (!process.env.NEXT_PUBLIC_GOOGLE_DRIVE_CLIENT_ID) {
      errors.push('NEXT_PUBLIC_GOOGLE_DRIVE_CLIENT_ID not configured')
    }

    if (!process.env.NEXT_PUBLIC_GOOGLE_DRIVE_API_KEY) {
      errors.push('NEXT_PUBLIC_GOOGLE_DRIVE_API_KEY not configured')
    }

    // Validate Client ID format (should end with .googleusercontent.com)
    const clientId = process.env.NEXT_PUBLIC_GOOGLE_DRIVE_CLIENT_ID
    if (clientId && !clientId.endsWith('.googleusercontent.com')) {
      errors.push('Invalid Client ID format')
    }

    return {
      isValid: errors.length === 0,
      errors
    }
  }

  /**
   * Clean up expired tokens and data
   */
  static cleanupExpiredData(): void {
    if (typeof window === 'undefined') return

    try {
      // Remove expired authentication data
      const stored = localStorage.getItem('block-content-editor_google_drive_auth_time')
      if (stored) {
        const authTime = parseInt(stored)
        const now = Date.now()
        
        if (now - authTime > this.MAX_TOKEN_AGE) {
          localStorage.removeItem('block-content-editor_google_drive_folder')
          localStorage.removeItem('block-content-editor_google_drive_folder_name')
          localStorage.removeItem('block-content-editor_google_drive_auth_time')
        }
      }
    } catch (error) {
      console.error('Cleanup failed:', error)
    }
  }

  /**
   * Log security events (for monitoring)
   */
  static logSecurityEvent(event: string, details?: unknown): void {
    const securityLog = {
      timestamp: new Date().toISOString(),
      event,
      details,
      userAgent: navigator.userAgent,
      url: window.location.href,
    }

    // In production, send to security monitoring service
    console.log('Security Event:', securityLog)
  }
}

