interface AiRequestFailure {
  error: string;
  status: number;
  code?: string;
}

const ERROR_COPY: Record<string, string> = {
  AI_QUOTA_EXCEEDED:
    "AI usage quota exceeded. Wait for the quota window to reset.",
  INSUFFICIENT_AI_CREDITS:
    "Not enough soft credits to start this run.",
  AI_EXECUTION_FAILED: "The AI run failed. Try again.",
  AI_RUN_INTERRUPTED: "The AI run was interrupted.",
  AI_IDEMPOTENCY_CONFLICT:
    "This run was already submitted with the same key.",
  AI_PROPOSAL_KIND_NOT_ALLOWED:
    "That change type is not available for this post format.",
  BLOG_REVISION_CONFLICT: "The post changed while the AI worked. Reload and retry.",
};

function errorCopy(failure: AiRequestFailure): string {
  if (failure.code && ERROR_COPY[failure.code]) return ERROR_COPY[failure.code];
  return failure.error || "Copilot request failed.";
}

function parseStreamFrame(frame: string): unknown | null {
  const data = frame
    .split("\n")
    .filter((line) => line.startsWith("data:"))
    .map((line) => line.slice(5).trimStart())
    .join("\n");
  if (!data) return null;
  try {
    return JSON.parse(data);
  } catch {
    return null;
  }
}

async function aiRead<T>(path: string): Promise<
  | { success: true; data: T }
  | { success: false; error: string; status: number; code?: string }
> {
  const response = await fetch(path);
  if (!response.ok) {
    const body = (await response.json().catch(() => null)) as
      | { detail?: unknown; title?: unknown; code?: unknown }
      | null;
    return {
      success: false,
      error:
        (typeof body?.detail === "string" && body.detail) ||
        (typeof body?.title === "string" && body.title) ||
        "Copilot request failed.",
      status: response.status,
      code: typeof body?.code === "string" ? body.code : undefined,
    };
  }
  return { success: true, data: (await response.json()) as T };
}

const activeRunStorageKeyFor = (postId: string) => `blog-ai-run:${postId}`;

export function BlogCopilotPanel({
  postId,
  postRevision,
  format,
  onRevisionChange,
  selection = null,
}: BlogCopilotPanelProps) {
  const [messages, setMessages] = useState<BlogAiMessage[]>([]);
  const [conversationId, setConversationId] = useState<string | null>(null);
  const [prompt, setPrompt] = useState("");
  const [isRunning, setIsRunning] = useState(false);
  const [activeRun, setActiveRun] = useState<BlogAiRun | null>(null);
  const [proposal, setProposal] = useState<BlogAiProposal | null>(null);
  const [diffOpen, setDiffOpen] = useState(false);
  const [entitlement, setEntitlement] = useState<BlogAiEntitlement | null>(null);
  const [aiError, setAiError] = useState<string | null>(null);
  const [mode, setMode] = useState<CopilotMode>("content");
  const [unifiedDiff, setUnifiedDiff] = useState(false);
  const { resolvedTheme } = useTheme();

  const streamAbortRef = useRef<AbortController | null>(null);
  const restoredRunRef = useRef(false);
  const revisionRef = useRef(postRevision);
  const activeRunStorageKey = activeRunStorageKeyFor(postId);

  useEffect(() => {
    revisionRef.current = postRevision;
  }, [postRevision]);

  useEffect(() => {
    void Promise.all([
      aiRead<BlogAiEntitlement>(
        `/api/blogs/authoring/${encodeURIComponent(postId)}/ai/entitlement`,
      ),
      aiRead<BlogAiConversation[]>(
        `/api/blogs/authoring/${encodeURIComponent(postId)}/ai/conversations`,
      ),
    ]).then(([creditResult, conversationResult]) => {
      if (creditResult.success) setEntitlement(creditResult.data);
      if (conversationResult.success && conversationResult.data[0]?.id) {
        setConversationId(conversationResult.data[0].id as string);
        setMessages(
          (conversationResult.data[0].messages ?? []).map(
            (message, index) => ({
              id: message.id ?? `restored-${index}`,
              role: message.role ?? "assistant",
              content: message.content ?? "",
              runId: message.runId ?? undefined,
              createdAt: message.createdAt ?? new Date().toISOString(),
            }),
          ),
        );
      }
    });
  }, [postId]);

  const readRunStream = useCallback(
    async (run: BlogAiRun) => {
      let lastEventId = 0;
      let reconnectAttempts = 0;
      streamAbortRef.current?.abort();
      const abortController = new AbortController();
      streamAbortRef.current = abortController;
      window.sessionStorage.setItem(activeRunStorageKey, run.id);

      while (!abortController.signal.aborted) {
        try {
          const response = await fetch(
            `/api/blogs/authoring/${encodeURIComponent(postId)}/runs/${encodeURIComponent(run.id)}/stream`,
            {
              headers: lastEventId
                ? { "Last-Event-ID": String(lastEventId) }
                : {},
              signal: abortController.signal,
            },
          );
          if (!response.ok || !response.body)
            throw new Error("The Copilot stream could not be opened.");
          reconnectAttempts = 0;
          const reader = response.body.getReader();
          const decoder = new TextDecoder();
          let buffer = "";
          while (true) {
            const { done, value } = await reader.read();
            buffer += decoder.decode(value, { stream: !done });
            const frames = buffer.split("\n\n");
            // String#split always returns at least one segment.
            buffer = frames.pop() as string;
            for (const frame of frames) {
              const id = frame.match(/^id:\s*(\d+)/m)?.[1];
              if (id) lastEventId = Number(id);
              const event = parseStreamFrame(frame) as {
                delta?: string;
                proposal?: BlogAiProposal;
                errorCode?: string;
              } | null;
              if (event?.delta) {
                const delta = event.delta;
                setMessages((current) => {
                  const last = current.at(-1);
                  if (last?.role === "assistant" && last.runId === run.id)
                    return [
                      ...current.slice(0, -1),
                      { ...last, content: last.content + delta },
                    ];
                  return [
                    ...current,
                    {
                      id: `stream-${run.id}`,
                      role: "assistant",
                      content: delta,
                      runId: run.id,
                      createdAt: new Date().toISOString(),
                    },
                  ];
                });
              }
              if (event?.proposal) {
                setProposal(event.proposal);
                setDiffOpen(true);
              }
              if (
                event?.errorCode &&
                !["AI_CANCEL_REQUESTED", "AI_CANCELLED"].includes(
                  event.errorCode,
                )
              )
                setAiError(ERROR_COPY[event.errorCode] ?? event.errorCode);
            }
            if (done) break;
          }

          const latest = await aiRead<BlogAiRun>(
            `/api/blogs/authoring/${encodeURIComponent(postId)}/ai/runs/${encodeURIComponent(run.id)}`,
          );
          if (!latest.success)
            throw new Error(latest.error || "Copilot run lookup failed.");
          setActiveRun(latest.data);
          if (latest.data.proposal) {
            setProposal(latest.data.proposal);
            setDiffOpen(latest.data.proposal.status === "Pending");
          }
          if (
            ["Completed", "Failed", "Cancelled"].includes(
              latest.data.status ?? "",
            )
          ) {
            window.sessionStorage.removeItem(activeRunStorageKey);
            if (latest.data.status === "Failed")
              setAiError(latest.data.errorMessage ?? "Copilot generation failed.");
            const balance = await aiRead<BlogAiEntitlement>(
              `/api/blogs/authoring/${encodeURIComponent(postId)}/ai/entitlement`,
            );
            if (balance.success) setEntitlement(balance.data);
            return;
          }
        } catch (error) {
          if (abortController.signal.aborted) return;
          reconnectAttempts += 1;
          if (reconnectAttempts > 4) throw error;
        }
        await new Promise((resolve) =>
          window.setTimeout(
            resolve,
            Math.min(750 * 2 ** reconnectAttempts, 5000),
          ),
        );
      }
    },
    [activeRunStorageKey, postId],
  );

  useEffect(() => {
    if (restoredRunRef.current) return;
    restoredRunRef.current = true;
    const runId = window.sessionStorage.getItem(activeRunStorageKey);
    if (!runId) return;
    void aiRead<BlogAiRun>(
      `/api/blogs/authoring/${encodeURIComponent(postId)}/ai/runs/${encodeURIComponent(runId)}`,
    ).then(async (result) => {
      if (!result.success) {
        window.sessionStorage.removeItem(activeRunStorageKey);
        return;
      }
      setActiveRun(result.data);
      if (result.data.proposal) {
        setProposal(result.data.proposal);
        setDiffOpen(result.data.proposal.status === "Pending");
      }
      if (["Completed", "Failed", "Cancelled"].includes(result.data.status ?? "")) {
        window.sessionStorage.removeItem(activeRunStorageKey);
        return;
      }
      setIsRunning(true);
      try {
        await readRunStream(result.data);
      } catch (error) {
        setAiError(
          error instanceof Error
            ? error.message
            : "Copilot stopped unexpectedly.",
        );
      } finally {
        setIsRunning(false);
      }
    });
  }, [activeRunStorageKey, postId, readRunStream]);

  const runCopilot = async (instruction = prompt) => {
    if (!instruction.trim() || isRunning) return;
    setAiError(null);
    setIsRunning(true);
    setMessages((current) => [
      ...current,
      {
        id: `local-${crypto.randomUUID()}`,
        role: "user",
        content: instruction.trim(),
        createdAt: new Date().toISOString(),
      },
    ]);
    const kind = selectProposalKind(format, !!selection?.text, mode);
    const result = await createAiRun(postId, {
      conversationId,
      postRevision: revisionRef.current,
      instruction: instruction.trim(),
      proposalKind: kind,
      selection: selection?.text ?? null,
      idempotencyKey: crypto.randomUUID(),
    });
    if (!result.success) {
      setAiError(errorCopy(result));
      setIsRunning(false);
      return;
    }
    setPrompt("");
    const run = result.data as unknown as BlogAiRun;
    setActiveRun(run);
    setConversationId(run.conversationId);
    try {
      await readRunStream(run);
    } catch (error) {
      setAiError(
        error instanceof Error
          ? error.message
          : "Copilot stopped unexpectedly.",
      );
    } finally {
      setIsRunning(false);
    }
  };

  const stopCopilot = async () => {
    if (!activeRun) return;
    const result = await cancelAiRun(postId, activeRun.id);
    if (!result.success) {
      setAiError(errorCopy(result));
      return;
    }
    setActiveRun(result.data as unknown as BlogAiRun);
    if ((result.data as unknown as BlogAiRun).status === "Cancelled") {
      streamAbortRef.current?.abort();
      window.sessionStorage.removeItem(activeRunStorageKey);
      setIsRunning(false);
      const balance = await aiRead<BlogAiEntitlement>(
        `/api/blogs/authoring/${encodeURIComponent(postId)}/ai/entitlement`,
      );
      if (balance.success) setEntitlement(balance.data);
    }
  };

  const acceptProposal = async (proposalToApply: BlogAiProposal) => {
    const result = await applyProposal(
      postId,
      proposalToApply.id,
      revisionRef.current,
      proposalToApply.kind === "InsertAtCursor"
        ? selection?.cursorOffset ?? 0
        : undefined,
    );
    if (!result.success) {
      setAiError(errorCopy(result));
      return;
    }
    const updated = result.data as BlogPostDetail;
    onRevisionChange(updated);
    revisionRef.current = updated.revision ?? revisionRef.current;
    setProposal({ ...proposalToApply, status: "Applied" });
    setDiffOpen(false);
  };

  const rejectProposal = async (proposalToDiscard: BlogAiProposal) => {
    const result = await discardProposal(postId, proposalToDiscard.id);
    if (result.success) setProposal(result.data as unknown as BlogAiProposal);
    setDiffOpen(false);
  };

  const newConversation = () => {
    if (isRunning) return;
    setConversationId(null);
    setMessages([]);
    setAiError(null);
  };

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <div className="border-b px-4 py-3">
        <div className="flex items-center justify-between gap-2">
          <div>
            <p className="text-sm font-medium">Blog Copilot</p>
            <p className="text-sm text-muted-foreground">
              Changes always require your approval.
            </p>
          </div>
          <Badge variant="outline" className="font-mono text-sm">
            {entitlement
              ? `${entitlement.availableSoftCredits} SC`
              : "… SC"}
          </Badge>
        </div>
        <Button
          variant="ghost"
          size="xs"
          className="mt-2"
          disabled={isRunning}
          onClick={newConversation}
        >
          <Sparkles /> New conversation
        </Button>
      </div>
      <ScrollArea className="min-h-0 flex-1">
        <div className="space-y-3 p-3">
          {messages.length === 0 ? (
            <div className="py-5 text-center">
              <Sparkles className="mx-auto size-5 text-primary" />
              <p className="mt-2 text-sm font-medium">Improve this post</p>
              <p className="mx-auto mt-1 max-w-56 text-sm text-muted-foreground">
                Ask for a rewrite, a better title, an excerpt, tags, or SEO
                metadata.
              </p>
              <div className="mt-4 grid gap-1.5">
                {[
                  "Make this clearer and more concise",
                  "Write a compelling excerpt",
                  "Suggest tags and SEO metadata",
                ].map((suggestion) => (
                  <Button
                    key={suggestion}
                    variant="outline"
                    size="sm"
                    className="h-auto justify-start py-2 text-left text-sm"
                    onClick={() => void runCopilot(suggestion)}
                  >
                    {suggestion}
                  </Button>
                ))}
              </div>
            </div>
          ) : null}
          {messages.map((message) => (
            <div
              key={message.id}
              className={
                message.role === "user"
                  ? "ml-7 rounded-lg bg-primary px-3 py-2 text-sm text-primary-foreground"
                  : "mr-3 rounded-lg bg-muted px-3 py-2 text-sm leading-relaxed"
              }
            >
              {message.content}
            </div>
          ))}
          {isRunning ? (
            <div className="flex items-center justify-between gap-3 px-2 py-1 text-sm text-muted-foreground">
              <span className="flex items-center gap-2">
                <Loader2 className="size-3 animate-spin" />
                {activeRun?.errorCode === "AI_CANCEL_REQUESTED"
                  ? "Stopping Copilot…"
                  : "Generating proposal…"}
              </span>
              <Button
                variant="ghost"
                size="xs"
                disabled={activeRun?.errorCode === "AI_CANCEL_REQUESTED"}
                onClick={() => void stopCopilot()}
              >
                Stop
              </Button>
            </div>
          ) : null}
          {aiError ? (
            <p className="rounded-md bg-destructive/10 p-2 text-sm text-destructive">
              {aiError}
            </p>
          ) : null}
          {activeRun?.usage?.maximumEstimatedCost ? (
            <div className="rounded-md bg-muted/50 p-2 text-sm text-muted-foreground">
              Max {activeRun.usage.maximumEstimatedCost} SC · Used{" "}
              {(activeRun.usage.inputTokens ?? 0) +
                (activeRun.usage.outputTokens ?? 0)}{" "}
              tokens · Settled {activeRun.usage.settledCost ?? 0} SC
            </div>
          ) : null}
        </div>
      </ScrollArea>
      <div className="space-y-2 border-t p-3">
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <Bot className="size-4" />
          <Select
            value={mode}
            onValueChange={(value) => setMode(value as CopilotMode)}
          >
            <SelectTrigger
              aria-label="Proposal application"
              className="h-8 flex-1 text-sm"
            >
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="content">Revise post content</SelectItem>
              <SelectItem value="metadata">
                Improve settings / metadata
              </SelectItem>
            </SelectContent>
          </Select>
          {format === "Markdown" ? (
            <label className="flex items-center gap-1.5 text-xs">
              <input
                type="checkbox"
                checked={!!selection?.text}
                readOnly
              />
              Selection {selection?.text ? "attached" : "none"}
            </label>
          ) : null}
        </div>
        <p className="rounded-md bg-muted/50 px-2.5 py-2 text-xs text-muted-foreground">
          Applies as{" "}
          <span className="font-mono">
            {selectProposalKind(format, !!selection?.text, mode)}
          </span>
        </p>
        <div className="relative">
          <Textarea
            aria-label="Ask Copilot"
            value={prompt}
            onChange={(event) => setPrompt(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Enter" && !event.shiftKey) {
                event.preventDefault();
                void runCopilot();
              }
            }}
            rows={3}
            className="resize-none pr-10 text-sm"
            placeholder="Ask AI to revise this post…"
          />
          <Button
            size="icon-sm"
            className="absolute bottom-2 right-2"
            aria-label="Send to Copilot"
            disabled={!prompt.trim() || isRunning}
            onClick={() => void runCopilot()}
          >
            {isRunning ? <Loader2 className="animate-spin" /> : <Send />}
          </Button>
        </div>
        <p className="text-sm text-muted-foreground">
          Maximum cost is reserved first. Only actual token usage is charged to
          your wallet.
        </p>
      </div>

      <Dialog open={diffOpen} onOpenChange={setDiffOpen}>
        <DialogContent className="grid h-[88dvh] max-w-[94vw] grid-rows-[auto_minmax(0,1fr)_auto] gap-0 overflow-hidden p-0 sm:max-w-[94vw]">
          <DialogHeader className="border-b px-5 py-4">
            <div className="flex items-start justify-between gap-4 pr-10">
              <div>
                <DialogTitle>Review AI proposal</DialogTitle>
                <DialogDescription>
                  Compare the current post with the proposed content before
                  applying it.
                </DialogDescription>
              </div>
              <div className="flex rounded-md border p-0.5">
                <Button
                  variant={!unifiedDiff ? "secondary" : "ghost"}
                  size="xs"
                  onClick={() => setUnifiedDiff(false)}
                >
                  Side by side
                </Button>
                <Button
                  variant={unifiedDiff ? "secondary" : "ghost"}
                  size="xs"
                  onClick={() => setUnifiedDiff(true)}
                >
                  Unified
                </Button>
              </div>
            </div>
          </DialogHeader>
          <div className="min-h-0 bg-background">
            {proposal ? (
              <Suspense
                fallback={
                  <div className="flex h-full items-center justify-center">
                    <Loader2 className="animate-spin" />
                  </div>
                }
              >
                <MonacoDiffEditor
                  original={proposal.originalContent ?? ""}
                  modified={proposal.proposedContent ?? ""}
                  language={format === "Lexical" ? "json" : "markdown"}
                  theme={resolvedTheme === "light" ? "vs-light" : "vs-dark"}
                  height="100%"
                  options={{
                    readOnly: true,
                    renderSideBySide: !unifiedDiff,
                    minimap: { enabled: false },
                    wordWrap: "on",
                  }}
                />
              </Suspense>
            ) : null}
          </div>
          <DialogFooter className="border-t px-5 py-3">
            <div className="mr-auto text-sm text-muted-foreground">
              Base post revision {proposal?.basePostRevision}
            </div>
            {proposal ? (
              <>
                <Button
                  variant="outline"
                  onClick={() => void rejectProposal(proposal)}
                >
                  Discard
                </Button>
                <Button onClick={() => void acceptProposal(proposal)}>
                  <Check /> Accept and apply
                </Button>
              </>
            ) : null}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

export default BlogCopilotPanel;

"use client";

import { useCallback, useEffect, useMemo, useReducer, useState } from "react";
import { useRouter } from "next/navigation";
import { Badge } from "@game-guild/ui/components/badge";
import { Button } from "@game-guild/ui/components/button";
import { Input } from "@game-guild/ui/components/input";
import { Separator } from "@game-guild/ui/components/separator";
import { Textarea } from "@game-guild/ui/components/textarea";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@game-guild/ui/components/tooltip";
import { Bot, Loader2, PanelRightClose, PanelRightOpen, RotateCcw, Settings2 } from "lucide-react";
import { changeSlug, reloadLatestPost, updateDraft } from "@/lib/blogs/actions";
import { normalizeSlug, slugify } from "@/lib/slugify";
import {
  blogEditorReducer,
  buildAutosavePayload,
  createBlogEditorState,
  isPayloadEmpty,
  type BlogEditorDraft,
} from "@/lib/blogs/editor-state";
import type { BlogPostAuthorView } from "@/lib/blogs/queries";
import { BlogBodyEditor } from "./blog-body-editor";
import { BlogCopilotPanel } from "./blog-copilot-panel";
import { BlogPublishBar } from "./blog-publish-bar";
import { BlogSettingsPanel, type BlogSettingsState } from "./blog-settings-panel";
import {
  BlogCoauthorManager,
  type BlogCoauthor,
} from "./blog-coauthor-manager";

const AUTOSAVE_DELAY_MS = 1500;
const TWITTER_CARD_DEFAULT = "summary_large_image";

export interface BlogEditorWorkspaceProps {
  post: BlogPostAuthorView;
  viewerUserId: string;
  primaryAuthorHandle: string;
  coauthors: BlogCoauthor[];
}

function draftFromPost(post: BlogPostAuthorView): BlogEditorDraft {
  return {
    title: post.title ?? "",
    content: post.content ?? "",
    jsonBody: post.jsonBody ?? null,
    excerpt: post.excerpt ?? "",
    tags: post.tags ?? [],
    metaTitle: post.metaTitle ?? "",
    metaDescription: post.metaDescription ?? "",
    ogImageUrl: post.ogImageUrl ?? "",
    canonicalUrlOverride: post.canonicalUrlOverride ?? "",
    twitterCard: post.twitterCard ?? TWITTER_CARD_DEFAULT,
    structuredDataOverride: post.structuredDataOverride ?? "",
    allowComments: post.allowComments ?? true,
    format: post.format ?? "Markdown",
  };
}

export function BlogEditorWorkspace({
  post: initialPost,
  viewerUserId,
  primaryAuthorHandle,
  coauthors,
}: BlogEditorWorkspaceProps) {
  const router = useRouter();
  const [post, setPost] = useState(initialPost);
  const [state, dispatch] = useReducer(
    blogEditorReducer,
    { draft: draftFromPost(initialPost), revision: initialPost.revision ?? 1 },
    ({ draft, revision }) => createBlogEditorState(draft, revision),
  );
  const [baseline, setBaseline] = useState<BlogEditorDraft>(() => draftFromPost(initialPost));
  const [slugEditing, setSlugEditing] = useState(false);
  const [slugValue, setSlugValue] = useState(initialPost.slug ?? "");
  const [slugError, setSlugError] = useState<string | null>(null);
  const [rightOpen, setRightOpen] = useState(true);
  const [rightPanel, setRightPanel] = useState<"settings" | "authors" | "copilot">("settings");

  const viewerIsPrimary = post.primaryAuthorId === viewerUserId;
  const persist = useCallback(async () => {
    const current = state;
    if (current.status === "conflict") return;
    const payload = buildAutosavePayload(current.draft, baseline);
    if (isPayloadEmpty(payload)) return;
    dispatch({ type: "saving" });
    const result = await updateDraft(post.id, {
      ...payload,
      revision: current.revision,
    });
    if (!result.success) {
      if (result.code === "revision-conflict" && "expectedRevision" in result) {
        dispatch({
          type: "conflict",
          expectedRevision: result.expectedRevision,
          currentRevision: result.currentRevision,
          message: result.error,
        });
      } else {
        dispatch({ type: "error", message: result.error });
      }
      return;
    }
    const saved = result.data as unknown as BlogPostAuthorView;
    setBaseline({ ...current.draft });
    dispatch({ type: "saved", revision: saved.revision ?? current.revision + 1, savedAt: new Date().toISOString() });
    setPost((prev) => ({ ...prev, revision: saved.revision, updatedAt: saved.updatedAt }));
  }, [post.id, state, baseline]);

  const dirty = useMemo(
    () => !isPayloadEmpty(buildAutosavePayload(state.draft, baseline)),
    [state.draft, baseline],
  );

  useEffect(() => {
    if (!dirty || state.status === "conflict" || state.status === "saving") return;
    const timer = window.setTimeout(() => void persist(), AUTOSAVE_DELAY_MS);
    return () => window.clearTimeout(timer);
  }, [dirty, state.status, persist]);

  useEffect(() => {
    if (state.status !== "conflict") return;
    const warn = (event: BeforeUnloadEvent) => {
      event.preventDefault();
      event.returnValue = "";
    };
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [state.status]);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "s") {
        event.preventDefault();
        void persist();
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [persist]);

  const reloadLatest = async () => {
    const result = await reloadLatestPost(primaryAuthorHandle, post.slug ?? "");
    if (!result.success) {
      dispatch({ type: "error", message: result.error });
      return;
    }
    const fresh = result.post;
    const freshDraft = draftFromPost(fresh);
    setBaseline({ ...freshDraft });
    dispatch({ type: "reload-latest", post: { revision: fresh.revision ?? 1, draft: freshDraft } });
    setPost(fresh);
  };

  const edit = (patch: Partial<Omit<BlogEditorDraft, "format">>) => {
    dispatch({ type: "edit", patch });
  };

  const editSettings = (patch: Partial<BlogSettingsState>) => {
    edit(patch);
  };

  const saveSlug = async () => {
    const next = normalizeSlug(slugValue);
    if (!next || next === post.slug) {
      setSlugEditing(false);
      setSlugValue(post.slug ?? "");
      return;
    }
    const result = await changeSlug(post.id, next);
    if (!result.success) {
      setSlugError(result.error);
      return;
    }
    const saved = result.data as unknown as BlogPostAuthorView;
    setSlugError(null);
    setSlugEditing(false);
    setPost(saved);
    setBaseline(draftFromPost(saved));
    dispatch({ type: "saved", revision: saved.revision ?? state.revision, savedAt: new Date().toISOString() });
    router.replace(`/blogs/${primaryAuthorHandle}/${saved.slug}/edit`);
  };

  const settingsDraft = useMemo(
    () => ({
      tags: state.draft.tags,
      excerpt: state.draft.excerpt,
      metaTitle: state.draft.metaTitle,
      metaDescription: state.draft.metaDescription,
      ogImageUrl: state.draft.ogImageUrl,
      canonicalUrlOverride: state.draft.canonicalUrlOverride,
      twitterCard: state.draft.twitterCard,
      structuredDataOverride: state.draft.structuredDataOverride,
      allowComments: state.draft.allowComments,
    }),
    [state.draft],
  );

  const statusCopy =
    state.status === "saving"
      ? "Saving…"
      : state.status === "conflict"
        ? "Conflict"
        : state.status === "error"
          ? state.lastError ?? "Save failed"
          : state.lastSavedAt
            ? `Saved ${new Date(state.lastSavedAt).toLocaleTimeString()}`
            : "Saved";

  return (
    <div className="flex h-dvh min-h-0 flex-col overflow-hidden bg-background text-foreground">
      <header className="relative z-50 flex h-14 shrink-0 items-center gap-2 border-b bg-background px-3">
        <div className="min-w-0 flex-1">
          <p className="truncate text-sm font-medium">
            {state.draft.title || "Untitled post"}
          </p>
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            <span className={state.status === "conflict" ? "text-destructive" : ""}>
              {state.status === "saving" ? (
                <Loader2 className="mr-1 inline size-3 animate-spin" />
              ) : null}
              {statusCopy}
            </span>
            <Badge variant="outline" className="h-5 rounded-sm px-1.5 text-xs">
              Rev {state.revision}
            </Badge>
          </div>
        </div>
        <BlogPublishBar
          post={post}
          viewerUserId={viewerUserId}
          onChanged={(updated) => {
            setPost(updated);
            setBaseline(draftFromPost(updated));
            dispatch({
              type: "reload-latest",
              post: { revision: updated.revision ?? state.revision, draft: draftFromPost(updated) },
            });
          }}
          onDeleted={() => router.push("/blogs")}
        />
        <Tooltip>
          <TooltipTrigger
            render={
              <Button
                variant="ghost"
                size="icon-sm"
                aria-label="Toggle blog panel"
                onClick={() => setRightOpen((open) => !open)}
              />
            }
          >
            {rightOpen ? <PanelRightClose /> : <PanelRightOpen />}
          </TooltipTrigger>
          <TooltipContent>Toggle blog panel</TooltipContent>
        </Tooltip>
      </header>

      {state.status === "conflict" && state.conflict ? (
        <div
          role="alert"
          className="flex min-h-10 shrink-0 items-center justify-between gap-3 bg-destructive/10 px-4 py-1.5 text-sm text-destructive"
        >
          <span className="truncate">
            This post changed elsewhere (revision {state.conflict.currentRevision}). Reloading
            discards your unsaved local edits.
          </span>
          <Button variant="ghost" size="xs" onClick={() => void reloadLatest()}>
            <RotateCcw /> Reload latest (discard local)
          </Button>
        </div>
      ) : null}

      <main className="relative flex min-h-0 flex-1">
        <section className="h-full min-w-0 flex-1 overflow-auto bg-background px-5 py-6 xl:px-8">
          <div className="mx-auto w-full max-w-4xl">
            <Textarea
              aria-label="Post title"
              value={state.draft.title}
              onChange={(event) => edit({ title: event.target.value })}
              rows={1}
              className="mb-3 min-h-0 resize-none overflow-hidden border-0 bg-transparent px-0 text-2xl font-semibold leading-tight shadow-none focus-visible:ring-0 md:text-3xl [field-sizing:content]"
            />
            <div className="mb-5 flex flex-wrap items-center gap-2 text-sm text-muted-foreground">
              <span>/blogs/{primaryAuthorHandle}/</span>
              {slugEditing && viewerIsPrimary ? (
                <span className="flex items-center gap-1">
                  <Input
                    aria-label="URL slug"
                    value={slugValue}
                    onChange={(event) => setSlugValue(slugify(event.target.value))}
                    onBlur={() => setSlugValue(normalizeSlug(slugValue))}
                    onKeyDown={(event) => {
                      if (event.key === "Enter") {
                        event.preventDefault();
                        void saveSlug();
                      }
                    }}
                    className="h-7 w-52 text-sm"
                    autoFocus
                  />
                  <Button variant="secondary" size="xs" onClick={() => void saveSlug()}>
                    Save
                  </Button>
                  <Button
                    variant="ghost"
                    size="xs"
                    onClick={() => {
                      setSlugEditing(false);
                      setSlugValue(post.slug ?? "");
                      setSlugError(null);
                    }}
                  >
                    Cancel
                  </Button>
                </span>
              ) : (
                <button
                  type="button"
                  className="underline decoration-dotted hover:text-foreground"
                  disabled={!viewerIsPrimary}
                  onClick={() => {
                    setSlugValue(post.slug ?? "");
                    setSlugEditing(true);
                  }}
                >
                  {post.slug}
                </button>
              )}
              {viewerIsPrimary ? (
                <Tooltip>
                  <TooltipTrigger
                    render={<span className="cursor-help text-xs">ⓘ</span>}
                  >
                    <span />
                  </TooltipTrigger>
                  <TooltipContent>
                    Changing the slug is primary-author only. Old links will
                    redirect to the new URL.
                  </TooltipContent>
                </Tooltip>
              ) : null}
              {slugError ? <span className="text-destructive">{slugError}</span> : null}
            </div>
            <BlogBodyEditor
              postId={post.id}
              format={state.draft.format}
              markdown={state.draft.content}
              jsonBody={state.draft.jsonBody}
              onMarkdownChange={(value) => edit({ content: value })}
              onJsonBodyChange={(value) => edit({ jsonBody: value })}
            />
          </div>
        </section>

        {rightOpen ? (
          <aside
            aria-label="Blog settings"
            className="hidden w-80 shrink-0 flex-col border-l bg-background xl:flex"
          >
            <div className="flex h-12 items-center gap-1 border-b px-2">
              <Button
                variant={rightPanel === "settings" ? "secondary" : "ghost"}
                size="sm"
                className="flex-1"
                onClick={() => setRightPanel("settings")}
              >
                <Settings2 /> Settings
              </Button>
              <Button
                variant={rightPanel === "authors" ? "secondary" : "ghost"}
                size="sm"
                className="flex-1"
                onClick={() => setRightPanel("authors")}
              >
                Authors
              </Button>
              <Button
                variant={rightPanel === "copilot" ? "secondary" : "ghost"}
                size="sm"
                className="flex-1"
                onClick={() => setRightPanel("copilot")}
              >
                <Bot /> Copilot
              </Button>
            </div>
            <div className="min-h-0 flex-1 overflow-auto">
              {rightPanel === "settings" ? (
                <>
                  <BlogSettingsPanel
                    postId={post.id}
                    post={post}
                    revision={() => state.revision}
                    settings={settingsDraft}
                    onChange={editSettings}
                    onPostSaved={(updated) => setPost(updated)}
                  />
                  <Separator />
                  <div className="space-y-1 p-4 text-sm text-muted-foreground">
                    <div className="flex justify-between">
                      <span>Format</span>
                      <span className="text-foreground">{state.draft.format}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Revision</span>
                      <span className="text-foreground">{state.revision}</span>
                    </div>
                  </div>
                </>
              ) : rightPanel === "copilot" ? (
                <BlogCopilotPanel
                  postId={post.id}
                  postRevision={state.revision}
                  format={state.draft.format}
                  onRevisionChange={(updated) => {
                    setPost((prev) => ({ ...prev, ...updated }));
                    setBaseline({ ...draftFromPost({ ...post, ...updated }) });
                    dispatch({
                      type: "reload-latest",
                      post: {
                        revision: updated.revision ?? state.revision,
                        draft: draftFromPost({ ...post, ...updated }),
                      },
                    });
                  }}
                />
              ) : (
                <BlogCoauthorManager
                  post={post}
                  viewerUserId={viewerUserId}
                  coauthors={coauthors}
                  onChanged={(updated) => setPost(updated)}
                />
              )}
            </div>
          </aside>
        ) : null}
      </main>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { Badge } from "@game-guild/ui/components/badge";
import { Button } from "@game-guild/ui/components/button";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@game-guild/ui/components/alert-dialog";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@game-guild/ui/components/tooltip";
import { buttonVariants } from "@game-guild/ui/components/button";
import { Check, EyeOff, Eye, Loader2, Trash2 } from "lucide-react";
import { deletePost, publish, unpublish } from "@/lib/blogs/actions";
import type { BlogPostAuthorView } from "@/lib/blogs/queries";

interface BlogPublishBarProps {
  post: BlogPostAuthorView;
  viewerUserId: string;
  onChanged: (post: BlogPostAuthorView) => void;
  onDeleted: () => void;
}

export function BlogPublishBar({
  post,
  viewerUserId,
  onChanged,
  onDeleted,
}: BlogPublishBarProps) {
  const [confirming, setConfirming] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [pending, startTransition] = useTransition();

  const viewerIsPrimary = post.primaryAuthorId === viewerUserId;
  const isPublished = post.status === "Published";

  const runPublish = () => {
    if (!viewerIsPrimary || pending) return;
    startTransition(async () => {
      setError(null);
      const result = isPublished ? await unpublish(post.id) : await publish(post.id);
      if (!result.success) {
        setError(result.error);
        return;
      }
      onChanged(result.data as unknown as BlogPostAuthorView);
    });
  };

  const runDelete = () => {
    setConfirming(false);
    if (!viewerIsPrimary || pending) return;
    startTransition(async () => {
      setError(null);
      const result = await deletePost(post.id);
      if (!result.success) {
        setError(result.error);
        return;
      }
      onDeleted();
    });
  };

  const statusBadge = (
    <Badge variant={isPublished ? "default" : "outline"} data-testid="blog-status">
      {isPublished ? "Published" : "Draft"}
    </Badge>
  );

  return (
    <div className="flex items-center gap-2">
      {statusBadge}
      {isPublished && post.publishedAt ? (
        <span className="hidden text-xs text-muted-foreground sm:inline">
          {new Date(post.publishedAt).toLocaleDateString()}
        </span>
      ) : null}

      {error ? (
        <p className="text-sm text-destructive" role="alert">
          {error}
        </p>
      ) : null}

      {viewerIsPrimary ? (
        <>
          <Button
            size="sm"
            disabled={pending}
            aria-label={isPublished ? "Unpublish post" : "Publish post"}
            onClick={runPublish}
          >
            {pending ? <Loader2 className="animate-spin" /> : isPublished ? <EyeOff /> : <Eye />}
            {isPublished ? "Unpublish" : "Publish"}
          </Button>
          <Button
            variant="ghost"
            size="icon-sm"
            aria-label="Delete post"
            disabled={pending}
            onClick={() => setConfirming(true)}
          >
            <Trash2 />
          </Button>
        </>
      ) : (
        <Tooltip>
          <TooltipTrigger
            render={
              <Button size="sm" disabled aria-label="Publish (primary author only)">
                <Check />
                {isPublished ? "Unpublish" : "Publish"}
              </Button>
            }
          >
            <span />
          </TooltipTrigger>
          <TooltipContent>
            Only the primary author can publish, unpublish, or delete.
          </TooltipContent>
        </Tooltip>
      )}

      <AlertDialog open={confirming} onOpenChange={setConfirming}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete this post?</AlertDialogTitle>
            <AlertDialogDescription>
              The post and its public URL are removed permanently. This cannot
              be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              className={buttonVariants({ variant: "destructive" })}
              onClick={runDelete}
            >
              Delete post
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Button } from "@game-guild/ui/components/button";
import { Input } from "@game-guild/ui/components/input";
import { Label } from "@game-guild/ui/components/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@game-guild/ui/components/select";
import { Switch } from "@game-guild/ui/components/switch";
import { Textarea } from "@game-guild/ui/components/textarea";
import { Loader2, Sparkles, X } from "lucide-react";
import { createAiRun, applyProposal, getAiRun } from "@/lib/blogs/actions";
import type { BlogPostAuthorView } from "@/lib/blogs/queries";

const MAX_TAGS = 20;
const TWITTER_CARDS = ["summary", "summary_large_image"] as const;

export interface BlogSettingsState {
  tags: string[];
  excerpt: string;
  metaTitle: string;
  metaDescription: string;
  ogImageUrl: string;
  canonicalUrlOverride: string;
  twitterCard: string;
  structuredDataOverride: string;
  allowComments: boolean;
}

interface BlogSettingsPanelProps {
  postId: string;
  post: BlogPostAuthorView;
  revision: () => number;
  settings: BlogSettingsState;
  onChange: (patch: Partial<BlogSettingsState>) => void;
  onPostSaved: (post: BlogPostAuthorView) => void;
}

export function BlogSettingsPanel({
  postId,
  post,
  revision,
  settings,
  onChange,
  onPostSaved,
}: BlogSettingsPanelProps) {
  const [tagInput, setTagInput] = useState("");
  const [summaryStatus, setSummaryStatus] = useState<
    "idle" | "generating" | "error"
  >("idle");
  const [summaryError, setSummaryError] = useState<string | null>(null);

  const addTag = () => {
    const tag = tagInput.trim().toLowerCase();
    if (!tag) return;
    if (settings.tags.length >= MAX_TAGS || settings.tags.includes(tag)) {
      setTagInput("");
      return;
    }
    onChange({ tags: [...settings.tags, tag] });
    setTagInput("");
  };

  const generateSummary = async () => {
    if (summaryStatus === "generating") return;
    setSummaryStatus("generating");
    setSummaryError(null);
    const run = await createAiRun(postId, {
      postRevision: revision(),
      instruction:
        "Write a concise summary (excerpt) for this post based on its current content.",
      proposalKind: "MetadataPatch",
      idempotencyKey: crypto.randomUUID(),
    });
    if (!run.success) {
      setSummaryStatus("error");
      setSummaryError(run.error);
      return;
    }
    const runId = (run.data as { id?: string }).id;
    if (!runId) {
      setSummaryStatus("error");
      setSummaryError("The AI run could not be started.");
      return;
    }
    const interval = window.setInterval(async () => {
      const applied = await pollAndApply(runId);
      if (applied !== "pending") window.clearInterval(interval);
    }, 3000);
    window.setTimeout(() => {
      window.clearInterval(interval);
      setSummaryStatus((status) =>
        status === "generating" ? "error" : status,
      );
      setSummaryError((error) => error ?? "Summary generation timed out.");
    }, 180_000);
  };

  const pollAndApply = async (runId: string): Promise<"pending" | "done" | "failed"> => {
    const result = await getAiRun(postId, runId);
    if (!result.success) {
      setSummaryStatus("error");
      setSummaryError(result.error);
      return "failed";
    }
    const run = result.data as {
      status?: string;
      proposal?: { id?: string } | null;
      errorMessage?: string | null;
    };
    if (!["Completed", "Failed", "Cancelled"].includes(run.status ?? "")) {
      return "pending";
    }
    const proposal = run.proposal;
    if (run.status !== "Completed" || !proposal?.id) {
      setSummaryStatus("error");
      setSummaryError(run.errorMessage ?? "Summary generation failed.");
      return "failed";
    }
    const applied = await applyProposal(postId, proposal.id, revision());
    if (!applied.success) {
      setSummaryStatus("error");
      setSummaryError(applied.error);
      return "failed";
    }
    const updated = applied.data as { excerpt?: string | null };
    if (typeof updated.excerpt === "string") {
      onChange({ excerpt: updated.excerpt });
    } else {
      onPostSaved(post);
    }
    setSummaryStatus("idle");
    return "done";
  };

  return (
    <div className="space-y-6 p-4">
      <div className="space-y-2">
        <Label htmlFor="blog-tags">Tags</Label>
        <div className="flex flex-wrap gap-1.5">
          {settings.tags.map((tag) => (
            <span
              key={tag}
              className="inline-flex items-center gap-1 rounded-md bg-muted px-2 py-0.5 text-xs lowercase"
            >
              {tag}
              <button
                type="button"
                aria-label={`Remove tag ${tag}`}
                className="text-muted-foreground hover:text-foreground"
                onClick={() =>
                  onChange({ tags: settings.tags.filter((t) => t !== tag) })
                }
              >
                <X className="size-3" />
              </button>
            </span>
          ))}
        </div>
        <div className="flex gap-2">
          <Input
            id="blog-tags"
            value={tagInput}
            placeholder={settings.tags.length >= MAX_TAGS ? `Max ${MAX_TAGS} tags` : "Add a tag"}
            disabled={settings.tags.length >= MAX_TAGS}
            onChange={(event) => setTagInput(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Enter") {
                event.preventDefault();
                addTag();
              }
            }}
            onBlur={addTag}
          />
        </div>
      </div>

      <div className="space-y-1.5">
        <div className="flex items-center justify-between">
          <Label htmlFor="blog-excerpt">Excerpt</Label>
          <Button
            type="button"
            variant="ghost"
            size="xs"
            disabled={summaryStatus === "generating"}
            onClick={() => void generateSummary()}
          >
            {summaryStatus === "generating" ? (
              <Loader2 className="animate-spin" />
            ) : (
              <Sparkles />
            )}
            Generate summary
          </Button>
        </div>
        {summaryStatus === "generating" ? (
          <p className="text-xs text-muted-foreground" role="status">
            Generating summary… Reload the panel when the run completes if it
            does not fill in automatically.
          </p>
        ) : null}
        {summaryStatus === "error" && summaryError ? (
          <p className="text-xs text-destructive" role="alert">
            {summaryError}
          </p>
        ) : null}
        <Textarea
          id="blog-excerpt"
          rows={3}
          value={settings.excerpt}
          onChange={(event) => onChange({ excerpt: event.target.value })}
        />
      </div>

      <div className="space-y-3">
        <h3 className="text-sm font-semibold uppercase tracking-wide text-muted-foreground">
          SEO
        </h3>
        <div className="space-y-1.5">
          <Label htmlFor="blog-meta-title">Meta title</Label>
          <Input
            id="blog-meta-title"
            value={settings.metaTitle}
            onChange={(event) => onChange({ metaTitle: event.target.value })}
          />
        </div>
        <div className="space-y-1.5">
          <Label htmlFor="blog-meta-description">Meta description</Label>
          <Textarea
            id="blog-meta-description"
            rows={2}
            value={settings.metaDescription}
            onChange={(event) =>
              onChange({ metaDescription: event.target.value })
            }
          />
        </div>
        <div className="space-y-1.5">
          <Label htmlFor="blog-og-image">OG image URL</Label>
          <Input
            id="blog-og-image"
            value={settings.ogImageUrl}
            onChange={(event) => onChange({ ogImageUrl: event.target.value })}
          />
        </div>
        <div className="space-y-1.5">
          <Label htmlFor="blog-canonical">Canonical URL override</Label>
          <Input
            id="blog-canonical"
            value={settings.canonicalUrlOverride}
            onChange={(event) =>
              onChange({ canonicalUrlOverride: event.target.value })
            }
          />
        </div>
        <div className="space-y-1.5">
          <Label htmlFor="blog-twitter-card">Twitter card</Label>
          <Select
            value={settings.twitterCard || TWITTER_CARDS[1]}
            onValueChange={(value) => onChange({ twitterCard: value ?? TWITTER_CARDS[1] })}
          >
            <SelectTrigger id="blog-twitter-card" className="w-full">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {TWITTER_CARDS.map((card) => (
                <SelectItem key={card} value={card}>
                  {card}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-1.5">
          <Label htmlFor="blog-structured-data">Structured data override (JSON-LD)</Label>
          <Textarea
            id="blog-structured-data"
            rows={3}
            value={settings.structuredDataOverride}
            onChange={(event) =>
              onChange({ structuredDataOverride: event.target.value })
            }
          />
        </div>
      </div>

      <div className="flex items-center justify-between gap-3">
        <div>
          <Label htmlFor="blog-allow-comments">Allow comments</Label>
          <p className="mt-0.5 text-sm text-muted-foreground">
            Readers can reply to this post.
          </p>
        </div>
        <Switch
          id="blog-allow-comments"
          checked={settings.allowComments}
          onCheckedChange={(value) => onChange({ allowComments: value })}
        />
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@game-guild/ui/components/button";
import { Input } from "@game-guild/ui/components/input";
import { Label } from "@game-guild/ui/components/label";
import { Loader2 } from "lucide-react";
import { createPost } from "@/lib/blogs/actions";
import type { BlogContentFormat } from "@/lib/blogs/types";

const FORMATS: ReadonlyArray<{
  value: BlogContentFormat;
  label: string;
  description: string;
}> = [
  {
    value: "Markdown",
    label: "Markdown",
    description: "Write in plain Markdown with a code-style editor.",
  },
  {
    value: "Lexical",
    label: "Rich text",
    description: "Compose with the visual rich-text editor.",
  },
];

export function NewBlogPostForm() {
  const router = useRouter();
  const [title, setTitle] = useState("");
  const [format, setFormat] = useState<BlogContentFormat>("Markdown");
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const submit = async () => {
    if (!title.trim() || submitting) return;
    setSubmitting(true);
    setError(null);
    const result = await createPost({ title: title.trim(), format });
    if (!result.success) {
      setError(result.error);
      setSubmitting(false);
      return;
    }
    if (result.editUrl) {
      router.replace(result.editUrl);
      return;
    }
    router.push("/blogs");
  };

  return (
    <div className="mx-auto w-full max-w-2xl px-4 py-10">
      <h1 className="text-2xl font-semibold tracking-tight">New blog post</h1>
      <p className="mt-1 text-sm text-muted-foreground">
        Pick a title and a format. The format is locked once the post is
        created.
      </p>

      <div className="mt-8 space-y-6">
        <div className="space-y-1.5">
          <Label htmlFor="blog-new-title">Title</Label>
          <Input
            id="blog-new-title"
            value={title}
            placeholder="How we built it"
            onChange={(event) => setTitle(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Enter") {
                event.preventDefault();
                void submit();
              }
            }}
            autoFocus
          />
        </div>

        <fieldset>
          <legend className="text-sm font-medium">Format</legend>
          <div
            role="radiogroup"
            aria-label="Post format"
            className="mt-2 grid gap-3 sm:grid-cols-2"
          >
            {FORMATS.map((option) => {
              const selected = format === option.value;
              return (
                <button
                  key={option.value}
                  type="button"
                  role="radio"
                  aria-checked={selected}
                  data-testid={`format-${option.value}`}
                  className={`rounded-lg border p-4 text-left transition-colors ${
                    selected
                      ? "border-primary bg-primary/5"
                      : "border-border hover:border-muted-foreground/40"
                  }`}
                  onClick={() => setFormat(option.value)}
                >
                  <span className="block text-sm font-medium">{option.label}</span>
                  <span className="mt-1 block text-sm text-muted-foreground">
                    {option.description}
                  </span>
                </button>
              );
            })}
          </div>
        </fieldset>

        {error ? (
          <p className="text-sm text-destructive" role="alert">
            {error}
          </p>
        ) : null}

        <div className="flex items-center gap-2">
          <Button disabled={!title.trim() || submitting} onClick={() => void submit()}>
            {submitting ? <Loader2 className="animate-spin" /> : null}
            Create post
          </Button>
          <Button variant="ghost" onClick={() => router.back()}>
            Cancel
          </Button>
        </div>
      </div>
    </div>
  );
}

