export interface DeliverabilityEvent {
  id: string;
  occurredAt: string;
  eventType: string;
  recipientEmail: string;
  providerMessageId: string;
  bounceType: string | null;
  diagnosticCode: string | null;
  payloadPreview: string | null;
}

export interface DeliverabilitySuppression {
  id: string;
  emailAddress: string;
  reason: string;
  bounceType: string | null;
  suppressedAt: string;
  releasedAt: string | null;
  isActive: boolean;
}

export interface DeliverabilityDeadLetter {
  id: string;
  title: string;
  type: string;
  channel: string;
  recipientEmail: string | null;
  recipientId: string | null;
  lastError: string | null;
  attemptCount: number;
  requeueCount: number;
  createdAt: string;
}

interface TimelineState {
  notificationId: string;
  loading: boolean;
  error: boolean;
  providerMessageId: string | null;
  events: TimelineEvent[];
}

/** Deterministic UTC rendering ("2026-08-19 10:01") — stable across locales and test environments. */
function formatUtc(iso: string): string {
  return iso ? `${iso.slice(0, 10)} ${iso.slice(11, 16)} UTC` : '—';
}

function eventTypeBadgeVariant(eventType: string): 'default' | 'secondary' | 'destructive' | 'outline' {
  if (eventType === 'Bounce' || eventType === 'Complaint') return 'destructive';
  if (eventType === 'Delivery') return 'default';
  if (eventType === 'Open') return 'secondary';
  return 'outline';
}

export function EmailDeliverability({
  events,
  suppressions,
  deadLetters,
}: {
  events: DeliverabilityEvent[];
  suppressions: DeliverabilitySuppression[];
  deadLetters: DeliverabilityDeadLetter[];
}) {
  const t = useTranslations('emailDeliverability');
  const [isPending, startTransition] = useTransition();
  const [tab, setTab] = useState('events');
  const [deadLetterFilter, setDeadLetterFilter] = useState<string | null>(null);
  const [confirmUnsuppress, setConfirmUnsuppress] = useState<DeliverabilitySuppression | null>(null);
  const [timeline, setTimeline] = useState<TimelineState | null>(null);

  const activeSuppressedEmails = useMemo(
    () => new Set(suppressions.filter((s) => s.isActive).map((s) => s.emailAddress.toLowerCase())),
    [suppressions],
  );

  const visibleDeadLetters = useMemo(
    () =>
      deadLetterFilter
        ? deadLetters.filter((row) => row.recipientEmail?.toLowerCase() === deadLetterFilter.toLowerCase())
        : deadLetters,
    [deadLetters, deadLetterFilter],
  );

  function reportActionFailure(status: string) {
    toast.error(status === 'unauthorized' ? t('toast.unauthorized') : t('toast.error'));
  }

  function handleUnsuppress(email: string) {
    startTransition(async () => {
      const result = await unsuppressEmailAction(email);
      if (result.success) {
        toast.success(t('toast.unsuppressed'));
      } else {
        reportActionFailure(result.status);
      }
    });
  }

  function handleRequeue(notificationId: string) {
    startTransition(async () => {
      const result = await requeueNotificationAction(notificationId);
      if (result.success) {
        toast.success(t('toast.requeued'));
      } else {
        reportActionFailure(result.status);
      }
    });
  }

  async function handleOpenTimeline(deadLetter: DeliverabilityDeadLetter) {
    setTimeline({ notificationId: deadLetter.id, loading: true, error: false, providerMessageId: null, events: [] });
    const result = await getNotificationTimelineAction(deadLetter.id);
    setTimeline({
      notificationId: deadLetter.id,
      loading: false,
      error: !result.success,
      providerMessageId: result.providerMessageId,
      // Defensive sort: the API returns oldest-first, keep it guaranteed chronological.
      events: [...result.events].sort((a, b) => a.occurredAt.localeCompare(b.occurredAt)),
    });
  }

  function viewDeadLettersFor(email: string) {
    setDeadLetterFilter(email);
    setTab('deadLetters');
  }

  return (
    <Tabs value={tab} onValueChange={setTab}>
      <TabsList>
        <TabsTrigger value="events">{t('tabs.events')}</TabsTrigger>
        <TabsTrigger value="suppressions">{t('tabs.suppressions')}</TabsTrigger>
        <TabsTrigger value="deadLetters">{t('tabs.deadLetters')}</TabsTrigger>
      </TabsList>

      <TabsContent value="events">
        <Card>
          <CardHeader>
            <CardTitle>{t('tabs.events')}</CardTitle>
            <CardDescription>{t('events.description')}</CardDescription>
          </CardHeader>
          <CardContent>
            {events.length === 0 ? (
              <div data-testid="empty-events" className="rounded-lg border border-dashed p-8 text-center text-sm text-muted-foreground">
                {t('events.empty')}
              </div>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>{t('events.time')}</TableHead>
                    <TableHead>{t('events.type')}</TableHead>
                    <TableHead>{t('events.recipient')}</TableHead>
                    <TableHead>{t('events.diagnostic')}</TableHead>
                    <TableHead className="text-right" />
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {events.map((event) => (
                    <TableRow key={event.id}>
                      <TableCell className="whitespace-nowrap text-sm" title={event.occurredAt}>
                        {formatUtc(event.occurredAt)}
                      </TableCell>
                      <TableCell>
                        <Badge variant={eventTypeBadgeVariant(event.eventType)}>
                          {t(`events.types.${event.eventType}`, { defaultMessage: event.eventType })}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-sm">{event.recipientEmail}</TableCell>
                      <TableCell className="max-w-72 text-sm">
                        {event.bounceType || event.diagnosticCode ? (
                          <span className="flex flex-col">
                            {event.bounceType ? <span className="font-medium">{event.bounceType}</span> : null}
                            {event.diagnosticCode ? (
                              <span className="text-xs text-muted-foreground" title={event.diagnosticCode}>
                                {event.diagnosticCode}
                              </span>
                            ) : null}
                          </span>
                        ) : (
                          <span className="text-muted-foreground">—</span>
                        )}
                      </TableCell>
                      <TableCell className="text-right">
                        <Button
                          type="button"
                          variant="ghost"
                          size="sm"
                          onClick={() => viewDeadLettersFor(event.recipientEmail)}
                        >
                          {t('events.viewDeadLetters')}
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            )}
          </CardContent>
        </Card>
      </TabsContent>

      <TabsContent value="suppressions">
        <Card>
          <CardHeader>
            <CardTitle>{t('tabs.suppressions')}</CardTitle>
            <CardDescription>{t('suppressions.description')}</CardDescription>
          </CardHeader>
          <CardContent>
            {suppressions.length === 0 ? (
              <div data-testid="empty-suppressions" className="rounded-lg border border-dashed p-8 text-center text-sm text-muted-foreground">
                {t('suppressions.empty')}
              </div>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>{t('suppressions.email')}</TableHead>
                    <TableHead>{t('suppressions.reason')}</TableHead>
                    <TableHead>{t('suppressions.bounceType')}</TableHead>
                    <TableHead>{t('suppressions.suppressedAt')}</TableHead>
                    <TableHead>{t('suppressions.releasedAt')}</TableHead>
                    <TableHead className="text-right">{t('suppressions.unsuppress')}</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {suppressions.map((suppression) => (
                    <TableRow key={suppression.id}>
                      <TableCell className="flex items-center gap-2 font-medium">
                        {suppression.isActive ? <ShieldOff className="size-4 text-destructive" /> : null}
                        {suppression.emailAddress}
                      </TableCell>
                      <TableCell>
                        <Badge variant={suppression.isActive ? 'destructive' : 'outline'}>
                          {t(`suppressions.reasons.${suppression.reason}`, { defaultMessage: suppression.reason })}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-sm text-muted-foreground">{suppression.bounceType ?? '—'}</TableCell>
                      <TableCell className="whitespace-nowrap text-sm" title={suppression.suppressedAt}>
                        {formatUtc(suppression.suppressedAt)}
                      </TableCell>
                      <TableCell className="whitespace-nowrap text-sm text-muted-foreground" title={suppression.releasedAt ?? undefined}>
                        {suppression.releasedAt ? formatUtc(suppression.releasedAt) : '—'}
                      </TableCell>
                      <TableCell className="text-right">
                        {suppression.isActive ? (
                          <Button
                            type="button"
                            variant="outline"
                            size="sm"
                            disabled={isPending}
                            onClick={() => setConfirmUnsuppress(suppression)}
                          >
                            {t('suppressions.unsuppress')}
                          </Button>
                        ) : (
                          <span className="text-sm text-muted-foreground">—</span>
                        )}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            )}
          </CardContent>
        </Card>
      </TabsContent>

      <TabsContent value="deadLetters">
        <Card>
          <CardHeader>
            <CardTitle>{t('tabs.deadLetters')}</CardTitle>
            <CardDescription>{t('deadLetters.description')}</CardDescription>
            {deadLetterFilter ? (
              <Button type="button" variant="ghost" size="sm" className="w-fit" onClick={() => setDeadLetterFilter(null)}>
                {t('deadLetters.clearFilter')}
              </Button>
            ) : null}
          </CardHeader>
          <CardContent>
            {visibleDeadLetters.length === 0 ? (
              <div data-testid="empty-deadletters" className="rounded-lg border border-dashed p-8 text-center text-sm text-muted-foreground">
                {t('deadLetters.empty')}
              </div>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>{t('deadLetters.title')}</TableHead>
                    <TableHead>{t('deadLetters.type')}</TableHead>
                    <TableHead>{t('deadLetters.recipient')}</TableHead>
                    <TableHead>{t('deadLetters.error')}</TableHead>
                    <TableHead>{t('deadLetters.attempts')}</TableHead>
                    <TableHead className="text-right">{t('deadLetters.requeue')}</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {visibleDeadLetters.map((row) => {
                    const suppressed = row.recipientEmail
                      ? activeSuppressedEmails.has(row.recipientEmail.toLowerCase())
                      : false;

                    return (
                      <TableRow key={row.id}>
                        <TableCell>
                          <div className="flex items-center gap-2">
                            <MailWarning className="size-4 text-muted-foreground" />
                            <span className="font-medium">{row.title}</span>
                          </div>
                        </TableCell>
                        <TableCell>
                          <Badge variant="outline">{row.type}</Badge>
                        </TableCell>
                        <TableCell className="text-sm">{row.recipientEmail ?? '—'}</TableCell>
                        <TableCell className="max-w-72 text-sm">
                          {row.lastError ? (
                            <span className="block truncate text-muted-foreground" title={row.lastError}>
                              {row.lastError}
                            </span>
                          ) : (
                            '—'
                          )}
                        </TableCell>
                        <TableCell className="text-sm text-muted-foreground">
                          {row.attemptCount} / {t('deadLetters.requeues')} {row.requeueCount}
                        </TableCell>
                        <TableCell className="text-right">
                          <div className="flex items-center justify-end gap-2">
                            <Button
                              type="button"
                              variant="ghost"
                              size="sm"
                              onClick={() => handleOpenTimeline(row)}
                              aria-label={`${t('deadLetters.viewTimeline')}: ${row.title}`}
                            >
                              {t('deadLetters.viewTimeline')}
                            </Button>
                            {suppressed ? (
                              <Tooltip>
                                <TooltipTrigger render={<span className="inline-flex" />}>
                                  <Button type="button" variant="outline" size="sm" disabled>
                                    {t('deadLetters.requeue')}
                                  </Button>
                                </TooltipTrigger>
                                <TooltipContent>{t('deadLetters.suppressedTooltip')}</TooltipContent>
                              </Tooltip>
                            ) : (
                              <Button
                                type="button"
                                variant="outline"
                                size="sm"
                                disabled={isPending}
                                onClick={() => handleRequeue(row.id)}
                              >
                                {isPending ? <Loader2 className="mr-2 size-4 animate-spin" /> : null}
                                {t('deadLetters.requeue')}
                              </Button>
                            )}
                          </div>
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            )}
          </CardContent>
        </Card>
      </TabsContent>

      <AlertDialog
        open={confirmUnsuppress !== null}
        onOpenChange={(open) => {
          if (!open) setConfirmUnsuppress(null);
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{t('suppressions.confirmTitle')}</AlertDialogTitle>
            <AlertDialogDescription>
              {t('suppressions.confirmDescription', { email: confirmUnsuppress?.emailAddress ?? '' })}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => setConfirmUnsuppress(null)}>{t('suppressions.cancel')}</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => {
                if (confirmUnsuppress) handleUnsuppress(confirmUnsuppress.emailAddress);
                setConfirmUnsuppress(null);
              }}
            >
              {t('suppressions.confirmAction')}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <Sheet open={timeline !== null} onOpenChange={(open) => (open ? null : setTimeline(null))}>
        <SheetContent className="w-full overflow-y-auto sm:max-w-md">
          <SheetHeader>
            <SheetTitle>{t('timeline.title')}</SheetTitle>
            <SheetDescription>{t('timeline.description')}</SheetDescription>
          </SheetHeader>
          {timeline?.loading ? (
            <div className="flex items-center gap-2 px-4 py-8 text-sm text-muted-foreground">
              <Loader2 className="size-4 animate-spin" />
            </div>
          ) : timeline?.error ? (
            <p className="px-4 py-8 text-sm text-destructive">{t('toast.error')}</p>
          ) : timeline && timeline.providerMessageId === null ? (
            <p data-testid="timeline-no-correlation" className="px-4 py-8 text-sm text-muted-foreground">
              {t('timeline.noCorrelation')}
            </p>
          ) : timeline && timeline.events.length === 0 ? (
            <p data-testid="timeline-empty" className="px-4 py-8 text-sm text-muted-foreground">
              {t('timeline.empty')}
            </p>
          ) : timeline ? (
            <ol data-testid="timeline-events" className="mt-2 space-y-3 px-4 pb-8">
              {timeline.events.map((event) => (
                <li key={event.id} className="flex gap-3 rounded-lg border p-3" data-testid={`timeline-event-${event.id}`}>
                  <span className="mt-0.5">
                    {event.eventType === 'Open' ? (
                      <MailOpen className="size-4 text-muted-foreground" />
                    ) : (
                      <Mail className="size-4 text-muted-foreground" />
                    )}
                  </span>
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center justify-between gap-2">
                      <Badge variant={eventTypeBadgeVariant(event.eventType)}>
                        {t(`events.types.${event.eventType}`, { defaultMessage: event.eventType })}
                      </Badge>
                      <span className="text-xs text-muted-foreground" title={event.occurredAt}>
                        {formatUtc(event.occurredAt)}
                      </span>
                    </div>
                    <p className="mt-1 truncate text-sm">{event.recipientEmail}</p>
                    {event.bounceType ? (
                      <p className="text-xs text-muted-foreground">{event.bounceType}</p>
                    ) : null}
                    {event.diagnosticCode ? (
                      <p className="truncate text-xs text-muted-foreground" title={event.diagnosticCode}>
                        {event.diagnosticCode}
                      </p>
                    ) : null}
                    {event.payloadPreview ? (
                      <details className="mt-1">
                        <summary className="cursor-pointer text-xs text-muted-foreground">{t('timeline.payload')}</summary>
                        {/* API-capped 500-char preview — the raw payload is never exposed. */}
                        <pre className="mt-1 max-h-32 overflow-auto whitespace-pre-wrap break-all rounded bg-muted p-2 text-xs">
                          {event.payloadPreview}
                        </pre>
                      </details>
                    ) : null}
                  </div>
                </li>
              ))}
            </ol>
          ) : null}
        </SheetContent>
      </Sheet>
    </Tabs>
  );
}

'use client';

import * as React from 'react';
import { ChevronsUpDown, Settings2 } from 'lucide-react';
import { Link, usePathname } from '@/i18n/navigation';
import type { DashboardContextSummary, DashboardContextType } from '@/lib/dashboard-contexts';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from '@game-guild/ui/components/dropdown-menu';
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem, useSidebar } from '@game-guild/ui/components/sidebar';

const contextMeta: Record<DashboardContextType, { label: string; icon: React.ElementType }> = {
  Workspace: { label: 'Workspace', icon: Settings2 },
  Team: { label: 'Team', icon: Settings2 },
  Project: { label: 'Project', icon: Settings2 },
  Operations: { label: 'Operations', icon: Settings2 },
};

function isOperationsPath(pathname: string | null): boolean {
  return Boolean(pathname?.startsWith('/workspace/testing-lab') || pathname?.startsWith('/console/community/launch-pad'));
}

export function ContextSwitcher({ contexts }: { contexts: readonly DashboardContextSummary[] }) {
  const { isMobile } = useSidebar();
  const pathname = usePathname();
  const available = contexts.length > 0
    ? contexts
    : [{ type: 'Workspace' as const, id: null, name: 'Workspace', route: '/workspace' }];
  const active = available.find((context) =>
    context.type === 'Operations'
      ? isOperationsPath(pathname)
      : context.route !== '/dashboard' && (pathname === context.route || pathname?.startsWith(`${context.route}/`)),
  ) ?? available.find((context) => context.type === 'Operations') ?? available[0]!;
  const ActiveIcon = contextMeta[active.type].icon;
  const activeTypeLabel = contextMeta[active.type].label;
  const showActiveType = active.name.trim().toLowerCase() !== activeTypeLabel.toLowerCase();

  if (available.length === 1) {
    return (
      <SidebarMenu>
        <SidebarMenuItem>
          <SidebarMenuButton size="lg" render={<Link href={active.route} />}>
            <div className="flex aspect-square size-8 items-center justify-center rounded-lg bg-sidebar-primary text-sidebar-primary-foreground">
              <ActiveIcon className="size-4" />
            </div>
            <div className="grid flex-1 text-left text-sm leading-tight">
              <span className="truncate font-medium">{active.name}</span>
              {showActiveType && (
                <span className="truncate text-xs text-sidebar-foreground/70">{activeTypeLabel}</span>
              )}
            </div>
          </SidebarMenuButton>
        </SidebarMenuItem>
      </SidebarMenu>
    );
  }

  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <SidebarMenuButton
                size="lg"
                className="data-[state=open]:bg-sidebar-accent data-[state=open]:text-sidebar-accent-foreground"
              />
            }
          >
            <div className="flex aspect-square size-8 items-center justify-center rounded-lg bg-sidebar-primary text-sidebar-primary-foreground">
              <ActiveIcon className="size-4" />
            </div>
            <div className="grid flex-1 text-left text-sm leading-tight">
              <span className="truncate font-medium">{active.name}</span>
              {showActiveType && (
                <span className="truncate text-xs text-sidebar-foreground/70">{activeTypeLabel}</span>
              )}
            </div>
            <ChevronsUpDown className="ml-auto size-4" />
          </DropdownMenuTrigger>
          <DropdownMenuContent
            className="w-[--radix-dropdown-menu-trigger-width] min-w-64 rounded-lg"
            align="start"
            side={isMobile ? 'bottom' : 'right'}
            sideOffset={4}
          >
            <DropdownMenuGroup>
              <DropdownMenuLabel className="text-xs text-muted-foreground">Switch context</DropdownMenuLabel>
              {available.map((context) => {
                const Icon = contextMeta[context.type].icon;
                return (
                  <DropdownMenuItem
                    key={`${context.type}:${context.id ?? 'root'}`}
                    render={<Link href={context.route} className="gap-2 p-2" />}
                  >
                    <div className="flex size-7 items-center justify-center rounded-md border">
                      <Icon className="size-3.5" />
                    </div>
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-sm font-medium">{context.name}</p>
                      <p className="text-xs text-muted-foreground">{contextMeta[context.type].label}</p>
                    </div>
                  </DropdownMenuItem>
                );
              })}
            </DropdownMenuGroup>
          </DropdownMenuContent>
        </DropdownMenu>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

export const TeamSwitcher = ContextSwitcher;

'use client';

import { Link, useRouter } from '@/i18n/navigation';
import { useAuth } from '@game-guild/client/react';
import { Avatar, AvatarFallback, AvatarImage } from '@game-guild/ui/components/avatar';
import { Button } from '@game-guild/ui/components/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@game-guild/ui/components/dropdown-menu';
import { BriefcaseBusiness, ChevronsUpDown, LogOut, Settings } from 'lucide-react';
import * as React from 'react';

export interface WorkspaceUser {
  id: string;
  name: string;
  email: string;
  image?: string | null;
}

function getInitials(name: string, email: string) {
  const source = name.trim().length > 0 ? name : email.split('@')[0] ?? 'GG';
  const parts = source
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2);

  return parts
    .map((part) => part[0])
    .join('')
    .toUpperCase();
}

export function WorkspaceUserMenu({ user }: { user: WorkspaceUser }) {
  const router = useRouter();
  const { signOut, isLoading } = useAuth();
  const [isSigningOut, setIsSigningOut] = React.useState(false);
  const disabled = isLoading || isSigningOut;

  const handleSignOut = React.useCallback(async () => {
    if (disabled) return;

    setIsSigningOut(true);

    try {
      await signOut({ redirect: false });
      router.push('/sign-in');
    } finally {
      setIsSigningOut(false);
    }
  }, [disabled, router, signOut]);

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button variant="ghost"
            className="h-11 max-w-72 justify-start gap-2 rounded-lg px-2 text-left"
            aria-label={`Open ${user.name} account menu`}
          />
        }
      >
        <Avatar size="sm">
          {user.image ? <AvatarImage src={user.image} alt={user.name} /> : null}
          <AvatarFallback>{getInitials(user.name, user.email)}</AvatarFallback>
        </Avatar>
        <span className="hidden min-w-0 flex-1 sm:block">
          <span className="block truncate text-sm font-semibold leading-tight">{user.name}</span>
          <span className="block truncate text-xs leading-tight text-muted-foreground">{user.email}</span>
        </span>
        <ChevronsUpDown className="hidden size-4 shrink-0 text-muted-foreground sm:block" aria-hidden="true" />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-64">
        <DropdownMenuItem render={<Link href="/workspace" />}>
          <BriefcaseBusiness className="size-4" />
          My Workspace
        </DropdownMenuItem>
        <DropdownMenuItem render={<Link href="/workspace/settings/account" />}>
          <Settings className="size-4" />
          Account Settings
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem
          disabled={disabled}
          onClick={(event) => {
            event.preventDefault();
            void handleSignOut();
          }}
        >
          <LogOut className="size-4" />
          {disabled ? 'Signing out...' : 'Sign out'}
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

'use server';

import {
  createCourse as createLearningCourse,
  deleteCourse as deleteLearningCourse,
  updateCourse as updateLearningCourse,
} from '@/lib/learning/actions';
import { courseService, getCourseCategoryName, getCourseLevelConfig } from '@/lib/courses/services/course.service';
import speakingurl from 'speakingurl';

export interface CourseLegacy {
  id: number;
  sourceId?: string;
  title: string;
  category: string;
  description: string;
  image: string;
  slug: string;
  level?: string;
  duration?: string;
  seatsLeft?: number;
}

function stableNumericId(value: unknown): number {
  const input = String(value ?? '');
  let hash = 0;

  for (let index = 0; index < input.length; index += 1) {
    hash = (hash * 31 + input.charCodeAt(index)) >>> 0;
  }

  return hash || Date.now();
}

function mapCourse(program: Awaited<ReturnType<typeof courseService.getCourses>>[number]): CourseLegacy {
  const sourceId = String(program.id ?? program.slug ?? '');
  const estimatedHours = typeof program.estimatedHours === 'number' ? program.estimatedHours : null;

  return {
    id: stableNumericId(sourceId),
    sourceId,
    title: typeof program.title === 'string' && program.title.length > 0 ? program.title : 'Untitled course',
    category: getCourseCategoryName(program.category as string | number | null | undefined),
    description: typeof program.description === 'string' ? program.description : '',
    image: typeof program.thumbnail === 'string' ? program.thumbnail : '',
    slug: typeof program.slug === 'string' && program.slug.length > 0 ? program.slug : speakingurl(sourceId),
    level: getCourseLevelConfig(program.difficulty as string | number | null | undefined).name,
    duration: estimatedHours ? `${estimatedHours} hours` : 'Self-paced',
    seatsLeft:
      typeof program.maxEnrollments === 'number' && typeof program.currentEnrollments === 'number'
        ? Math.max(program.maxEnrollments - program.currentEnrollments, 0)
        : undefined,
  };
}

export async function fetchCourses(): Promise<CourseLegacy[]> {
  const courses = await courseService.getCourses();
  return courses.map(mapCourse);
}

export async function getCourse(id: number): Promise<CourseLegacy | undefined> {
  const courses = await fetchCourses();
  return courses.find((course) => course.id === id);
}

export async function createCourse(course: Omit<CourseLegacy, 'id'>): Promise<CourseLegacy> {
  const result = await createLearningCourse({
    title: course.title,
    description: course.description,
    slug: course.slug || speakingurl(course.title),
  });

  if (!result.success) {
    throw new Error(result.error);
  }

  return {
    ...course,
    id: stableNumericId(result.data.id),
    sourceId: result.data.id,
    slug: course.slug || speakingurl(course.title),
  };
}

export async function updateCourse(id: number, updates: Partial<Omit<CourseLegacy, 'id'>>): Promise<CourseLegacy | undefined> {
  const existing = await getCourse(id);

  if (!existing?.sourceId) {
    return undefined;
  }

  const result = await updateLearningCourse({
    courseId: existing.sourceId,
    title: updates.title,
    description: updates.description,
    slug: updates.slug,
    thumbnail: updates.image,
    category: updates.category,
    difficulty: updates.level,
  });

  if (!result.success) {
    throw new Error(result.error);
  }

  return { ...existing, ...updates };
}

export async function deleteCourse(id: number): Promise<boolean> {
  const existing = await getCourse(id);

  if (!existing?.sourceId) {
    return false;
  }

  const result = await deleteLearningCourse(existing.sourceId);

  if (!result.success) {
    throw new Error(result.error);
  }

  return true;
}

