'use client';

import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { Card, CardContent, CardFooter, CardHeader } from '@/components/ui/card';
import type { GeneratedApi } from '@game-guild/client';
import { Archive, BookOpen, Clock, Eye, FileText, Play, Star, Users } from 'lucide-react';

type LearningCourse = GeneratedApi.LearningCoursesProgram;
type CourseProgramContent = GeneratedApi.LearningCoursesProgramContent | { id?: string | number; title?: string | null };

type CourseAnalytics = {
  enrollments?: number;
  averageRating?: number;
};

type Course = Omit<
  Partial<LearningCourse>,
  'id' | 'title' | 'slug' | 'description' | 'status' | 'difficulty' | 'category' | 'estimatedHours' | 'currentEnrollments' | 'averageRating' | 'totalRatings'
> & {
  id?: string | number;
  title?: string | null;
  slug?: string | null;
  description?: string | null;
  area?: string;
  status?: 'draft' | 'published' | 'archived' | string | number | null;
  level?: number | null;
  difficulty?: string | number | null;
  category?: string | number | null;
  estimatedHours?: number | null;
  currentEnrollments?: number | null;
  averageRating?: number | null;
  totalRatings?: number | null;
  programContents?: CourseProgramContent[] | null;
  analytics?: CourseAnalytics;
  tools?: string[];
  content?: unknown[];
};

export type CourseCardCourse = Course;

interface CourseCardProps {
  course: Course;
  onEdit?: (course: Course) => void;
  onView?: (course: Course) => void;
  onEnroll?: (course: Course) => void;
}

function normalizeStatusValue(status: Course['status']): string {
  if (typeof status === 'number') {
    if (status === 0) return 'draft';
    if (status === 1) return 'review';
    if (status === 2) return 'published';
    if (status === 3) return 'archived';
  }

  const normalized = typeof status === 'string' ? status.trim().toLowerCase() : '';
  if (normalized === 'underreview' || normalized === 'under-review' || normalized === 'review') return 'review';
  if (normalized === 'published') return 'published';
  if (normalized === 'archived') return 'archived';
  return 'draft';
}

function normalizeDifficultyLevel(course: Course): number {
  if (typeof course.level === 'number') return course.level;
  if (typeof course.difficulty === 'number') return course.difficulty + 1;

  const normalized = typeof course.difficulty === 'string' ? course.difficulty.trim().toLowerCase() : '';
  if (normalized === 'intermediate') return 2;
  if (normalized === 'advanced') return 3;
  if (normalized === 'expert') return 4;
  return 1;
}

export function CourseCard({ course, onEdit, onView, onEnroll }: CourseCardProps) {
  const normalizedStatus = normalizeStatusValue(course.status);
  const normalizedLevel = normalizeDifficultyLevel(course);
  const normalizedArea = (course.area as any) ?? (course.category as any);
  const lessonsCount = (course.content ?? course.programContents)?.length || 0;
  const analyticsEnrollments = course.analytics?.enrollments ?? (course.currentEnrollments as any) ?? 0;
  const analyticsRating = course.analytics?.averageRating ?? (typeof course.averageRating === 'number' ? course.averageRating : undefined);
  const title = course.title || 'Untitled course';

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'published':
        return 'bg-green-500/20 text-green-400 border-green-500/30';
      case 'draft':
        return 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30';
      case 'archived':
        return 'bg-red-500/20 text-red-400 border-red-500/30';
      default:
        return 'bg-slate-500/20 text-slate-400 border-slate-500/30';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'published':
        return <Eye className="h-3 w-3" />;
      case 'draft':
        return <FileText className="h-3 w-3" />;
      case 'archived':
        return <Archive className="h-3 w-3" />;
      default:
        return <FileText className="h-3 w-3" />;
    }
  };

  const getLevelColor = (level: number) => {
    switch (level) {
      case 1:
        return 'text-green-400';
      case 2:
        return 'text-yellow-400';
      case 3:
        return 'text-orange-400';
      case 4:
        return 'text-red-400';
      default:
        return 'text-slate-400';
    }
  };

  const getLevelName = (level: number) => {
    switch (level) {
      case 1:
        return 'Beginner';
      case 2:
        return 'Intermediate';
      case 3:
        return 'Advanced';
      case 4:
        return 'Expert';
      default:
        return 'Unknown';
    }
  };

  return (
    <Card className="group relative backdrop-blur-md bg-slate-900/40 border border-slate-700/50 hover:border-blue-500/50 transition-all duration-300 hover:shadow-xl hover:shadow-blue-500/10">
      <CardHeader className="pb-3">
        <div className="flex items-start justify-between gap-3">
          <div className="flex-1 min-w-0">
            <h3 className="font-semibold text-white text-lg leading-tight line-clamp-2 group-hover:text-blue-300 transition-colors">{title}</h3>
            <p className="text-slate-400 text-sm mt-1 capitalize">{normalizedArea || 'General'}</p>
          </div>
          <div className="flex flex-col gap-2 items-end shrink-0">
            <Badge className={`text-xs px-2 py-1 ${getStatusColor(normalizedStatus)} flex items-center gap-1`}>
              {getStatusIcon(normalizedStatus)}
              {normalizedStatus}
            </Badge>
            <div className={`text-xs font-medium ${getLevelColor(normalizedLevel)}`}>
              Level {normalizedLevel} • {getLevelName(normalizedLevel)}
            </div>
          </div>
        </div>
      </CardHeader>

      <CardContent className="pb-4">
        <p className="text-slate-300 text-sm line-clamp-3 mb-4">{course.description || ''}</p>

        <div className="flex items-center gap-4 text-sm text-slate-400">
          <div className="flex items-center gap-1">
            <BookOpen className="h-4 w-4" />
            <span>{lessonsCount} lessons</span>
          </div>
          <div className="flex items-center gap-1">
            <Clock className="h-4 w-4" />
            <span>{course.estimatedHours || 0}h</span>
          </div>
          <div className="flex items-center gap-1">
            <Users className="h-4 w-4" />
            <span>{analyticsEnrollments}</span>
          </div>
          {analyticsRating !== undefined && (
            <div className="flex items-center gap-1">
              <Star className="h-4 w-4 text-yellow-400" />
              <span>{analyticsRating.toFixed(1)}</span>
            </div>
          )}
        </div>

        {course.tools && course.tools.length > 0 && (
          <div className="mt-3 flex flex-wrap gap-1">
            {course.tools.slice(0, 3).map((tool: string) => (
              <Badge key={tool} variant="outline" className="text-xs px-2 py-0.5 bg-slate-800/50 text-slate-300 border-slate-600">
                {tool}
              </Badge>
            ))}
            {course.tools.length > 3 && (
              <Badge variant="outline" className="text-xs px-2 py-0.5 bg-slate-800/50 text-slate-300 border-slate-600">
                +{course.tools.length - 3} more
              </Badge>
            )}
          </div>
        )}
      </CardContent>

      <CardFooter className="pt-2">
        <div className="flex gap-2 w-full">
          {onView && (
            <Button size="sm" variant="outline" onClick={() => onView(course)} className="flex-1">
              <Eye className="h-4 w-4 mr-1" />
              View
            </Button>
          )}
          {onEdit && (
            <Button size="sm" variant="outline" onClick={() => onEdit(course)} className="flex-1">
              <FileText className="h-4 w-4 mr-1" />
              Edit
            </Button>
          )}
          {onEnroll && normalizedStatus === 'published' && (
            <Button size="sm" onClick={() => onEnroll(course)} className="flex-1">
              <Play className="h-4 w-4 mr-1" />
              Enroll
            </Button>
          )}
        </div>
      </CardFooter>
    </Card>
  );
}

'use client';

import type { Program } from '@/lib/api/generated/types.gen';
import { useRouter } from '@/i18n/navigation';
import { getCourseRouteParam } from '@/lib/learning/course-route';
import type { CourseCardCourse } from './course-card';
import { CourseList } from './course-list';

interface CourseListWrapperProps {
  courses: Program[];
}

export const CourseListWrapper = ({ courses }: CourseListWrapperProps): React.JSX.Element => {
  const router = useRouter();

  const getCourseIdentifier = (course: CourseCardCourse) => getCourseRouteParam({
    id: course.id == null ? null : String(course.id),
    slug: course.slug == null ? null : String(course.slug),
    creatorId: typeof course.creatorId === 'string' ? course.creatorId : null,
  });

  const navigateToCourse = (course: CourseCardCourse, suffix = '') => {
    const identifier = getCourseIdentifier(course);
    router.push(`/workspace/learning/courses/${identifier}${suffix}` as Parameters<typeof router.push>[0]);
  };

  const handleCreateCourse = () => {
    router.push('/workspace/learning/courses/new' as Parameters<typeof router.push>[0]);
  };

  const handleEditCourse = (course: CourseCardCourse) => {
    navigateToCourse(course, '/settings');
  };

  const handleViewCourse = (course: CourseCardCourse) => {
    navigateToCourse(course);
  };

  return <CourseList courses={courses} onCreate={handleCreateCourse} onEdit={handleEditCourse} onView={handleViewCourse} />;
};

'use client';

import { PeriodType } from '@/components/common/filters/filter-context';
import { CourseFilterControls } from '@/components/courses/common';
import { CourseLevelValue, CourseStatusValue, type CourseLevel, type CourseStatus } from '@/components/courses/common/course-taxonomy';
import { Button } from '@game-guild/ui/components/button';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@game-guild/ui/components/table';
import { ProgramCategory } from '@/lib/api/generated/types.gen';
import { Eye, FileText, Plus, Play } from 'lucide-react';
import React, { useMemo, useState } from 'react';
import { CourseCard, CourseCardCourse } from './course-card';

// Type aliases to maintain existing naming
type Course = CourseCardCourse;
type CourseArea = ProgramCategory;

interface CourseListProps {
  courses: Course[];
  onEdit?: (course: Course) => void;
  onView?: (course: Course) => void;
  onEnroll?: (course: Course) => void;
  onCreate?: () => void;
  initialViewMode?: 'cards' | 'row' | 'table';
  hideViewToggle?: boolean;
}

export const CourseList = ({ courses, onEdit, onView, onEnroll, onCreate, initialViewMode = 'cards', hideViewToggle = false }: CourseListProps): React.JSX.Element => {
  // Filter states
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStatuses, setSelectedStatuses] = useState<CourseStatus[]>([]);
  const [selectedAreas, setSelectedAreas] = useState<CourseArea[]>([]);
  const [selectedLevels, setSelectedLevels] = useState<CourseLevel[]>([]);
  const [selectedPeriod, setSelectedPeriod] = useState<PeriodType>('week');
  const [viewMode, setViewMode] = useState<'cards' | 'row' | 'table'>(initialViewMode);

  const normalizeStatus = (status: Course['status']): CourseStatus | undefined => {
    if (status === undefined || status === null) return undefined;
    const value = typeof status === 'number' ? status : String(status).toLowerCase();
    if (value === 0 || value === '0' || value === 'draft') return CourseStatusValue.DRAFT;
    if (value === 1 || value === '1' || value === 'under-review' || value === 'review') return CourseStatusValue.REVIEW;
    if (value === 2 || value === '2' || value === 'published') return CourseStatusValue.PUBLISHED;
    if (value === 3 || value === '3' || value === 'archived') return CourseStatusValue.ARCHIVED;
    return undefined;
  };

  const normalizeLevel = (level: Course['difficulty'] | Course['level']): CourseLevel | undefined => {
    if (level === undefined || level === null) return undefined;
    const value = typeof level === 'number' ? level : String(level).toLowerCase();
    if (value === 0 || value === '0' || value === 'beginner') return CourseLevelValue.BEGINNER;
    if (value === 1 || value === '1' || value === 'intermediate') return CourseLevelValue.INTERMEDIATE;
    if (value === 2 || value === '2' || value === 'advanced') return CourseLevelValue.ADVANCED;
    if (value === 3 || value === '3' || value === 'expert') return CourseLevelValue.EXPERT;
    return undefined;
  };

  const getStatusLabel = (course: Course): string => {
    const status = normalizeStatus(course.status);
    if (status === CourseStatusValue.DRAFT) return 'Draft';
    if (status === CourseStatusValue.REVIEW) return 'Under review';
    if (status === CourseStatusValue.PUBLISHED) return 'Published';
    if (status === CourseStatusValue.ARCHIVED) return 'Archived';
    return 'Unknown';
  };

  const getLevelLabel = (course: Course): string => {
    const level = normalizeLevel(course.difficulty ?? course.level);
    if (level === CourseLevelValue.BEGINNER) return 'Beginner';
    if (level === CourseLevelValue.INTERMEDIATE) return 'Intermediate';
    if (level === CourseLevelValue.ADVANCED) return 'Advanced';
    if (level === CourseLevelValue.EXPERT) return 'Expert';
    return 'Unknown';
  };

  // Filter handlers
  const handleToggleStatus = (status: CourseStatus) => {
    setSelectedStatuses((prev) => (prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]));
  };

  const handleToggleArea = (area: CourseArea) => {
    setSelectedAreas((prev) => (prev.includes(area) ? prev.filter((a) => a !== area) : [...prev, area]));
  };

  const handleToggleLevel = (level: CourseLevel) => {
    setSelectedLevels((prev) => (prev.includes(level) ? prev.filter((l) => l !== level) : [...prev, level]));
  };

  // Filtered courses
  const filteredCourses = useMemo(() => {
    return courses.filter((course) => {
      // Search filter
      if (searchTerm) {
        const searchLower = searchTerm.toLowerCase();
        const title = (course.title || '').toLowerCase();
        const description = (course.description || '').toLowerCase();
        if (!title.includes(searchLower) && !description.includes(searchLower)) {
          return false;
        }
      }

      // Status filter
      const normalizedStatus = normalizeStatus(course.status);
      if (selectedStatuses.length > 0 && normalizedStatus) {
        if (!selectedStatuses.includes(normalizedStatus)) {
          return false;
        }
      }

      // Area filter (category)
      if (selectedAreas.length > 0 && course.category) {
        if (!selectedAreas.includes(course.category as CourseArea)) {
          return false;
        }
      }

      // Level filter (difficulty)
      const normalizedLevel = normalizeLevel(course.difficulty ?? course.level);
      if (selectedLevels.length > 0 && normalizedLevel) {
        if (!selectedLevels.includes(normalizedLevel)) {
          return false;
        }
      }

      return true;
    });
  }, [courses, searchTerm, selectedStatuses, selectedAreas, selectedLevels]);

  const renderCourseGrid = () => {
    if (filteredCourses.length === 0) {
      return (
        <div className="col-span-full flex flex-col items-center justify-center py-12 text-center">
          <div className="text-slate-400 text-lg mb-2">No courses found</div>
          <div className="text-slate-500 text-sm mb-4">{searchTerm || selectedStatuses.length > 0 || selectedAreas.length > 0 || selectedLevels.length > 0 ? 'Try adjusting your filters' : 'No courses available at the moment'}</div>
          {onCreate && courses.length === 0 && (
            <Button onClick={onCreate} className="flex items-center gap-2">
              <Plus className="h-4 w-4" />
              Create Your First Course
            </Button>
          )}
        </div>
      );
    }

    switch (viewMode) {
      case 'cards':
        return (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {filteredCourses.map((course) => (
              <CourseCard key={course.id} course={course} onEdit={onEdit} onView={onView} onEnroll={onEnroll} />
            ))}
          </div>
        );

      case 'row':
        return (
          <div className="space-y-4">
            {filteredCourses.map((course) => (
              <div key={course.id} className="w-full">
                <CourseCard course={course} onEdit={onEdit} onView={onView} onEnroll={onEnroll} />
              </div>
            ))}
          </div>
        );

      case 'table':
        return (
          <div className="overflow-hidden rounded-xl border border-slate-700/60 bg-slate-950/40">
            <Table aria-label="Courses">
              <TableHeader>
                <TableRow className="border-slate-800">
                  <TableHead>Course</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Area</TableHead>
                  <TableHead>Level</TableHead>
                  <TableHead className="text-right">Hours</TableHead>
                  <TableHead className="text-right">Enrollments</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredCourses.map((course) => {
                  const title = course.title || 'Untitled course';
                  const status = getStatusLabel(course);
                  const area = ((course.area as string | undefined) ?? (course.category as string | undefined) ?? 'General').toString();
                  const level = getLevelLabel(course);
                  const hours = course.estimatedHours ?? 0;
                  const enrollments = course.analytics?.enrollments ?? (course.currentEnrollments as number | undefined) ?? 0;
                  const isPublished = normalizeStatus(course.status) === CourseStatusValue.PUBLISHED;

                  return (
                    <TableRow key={course.id ?? title} className="border-slate-800">
                      <TableCell>
                        <div className="min-w-0">
                          <div className="font-medium text-slate-100">{title}</div>
                          {course.description && <div className="max-w-md truncate text-xs text-slate-400">{course.description}</div>}
                        </div>
                      </TableCell>
                      <TableCell>
                        <span className="rounded-full border border-slate-700 bg-slate-900 px-2 py-1 text-xs text-slate-200">{status}</span>
                      </TableCell>
                      <TableCell className="capitalize text-slate-300">{area}</TableCell>
                      <TableCell className="text-slate-300">{level}</TableCell>
                      <TableCell className="text-right text-slate-300">{hours}h</TableCell>
                      <TableCell className="text-right text-slate-300">{enrollments}</TableCell>
                      <TableCell>
                        <div className="flex justify-end gap-2">
                          {onView && (
                            <Button size="sm" variant="outline" onClick={() => onView(course)}>
                              <Eye className="mr-1 h-4 w-4" />
                              View
                            </Button>
                          )}
                          {onEdit && (
                            <Button size="sm" variant="outline" onClick={() => onEdit(course)}>
                              <FileText className="mr-1 h-4 w-4" />
                              Edit
                            </Button>
                          )}
                          {onEnroll && isPublished && (
                            <Button size="sm" onClick={() => onEnroll(course)}>
                              <Play className="mr-1 h-4 w-4" />
                              Enroll
                            </Button>
                          )}
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="space-y-6">
      {/* Filter Controls */}
      <CourseFilterControls
        searchTerm={searchTerm}
        onSearchChange={setSearchTerm}
        selectedStatuses={selectedStatuses}
        onToggleStatus={handleToggleStatus}
        selectedAreas={selectedAreas}
        onToggleArea={handleToggleArea}
        selectedLevels={selectedLevels}
        onToggleLevel={handleToggleLevel}
        selectedPeriod={selectedPeriod}
        onPeriodChange={setSelectedPeriod}
        viewMode={viewMode}
        onViewModeChange={setViewMode}
        hideViewToggle={hideViewToggle}
      />

      {/* Results Summary */}
      <div className="flex items-center justify-between text-sm text-slate-400">
        <span>
          Showing {filteredCourses.length} of {courses.length} courses
        </span>
        <div className="flex items-center gap-3">
          {(searchTerm || selectedStatuses.length > 0 || selectedAreas.length > 0 || selectedLevels.length > 0) && (
            <button
              onClick={() => {
                setSearchTerm('');
                setSelectedStatuses([]);
                setSelectedAreas([]);
                setSelectedLevels([]);
                setSelectedPeriod('month');
              }}
              className="text-blue-400 hover:text-blue-300 transition-colors"
            >
              Clear all filters
            </button>
          )}
          {onCreate && (
            <Button onClick={onCreate} size="sm" className="flex items-center gap-2">
              <Plus className="h-4 w-4" />
              Create Course
            </Button>
          )}
        </div>
      </div>

      {/* Course Grid */}
      {renderCourseGrid()}
    </div>
  );
};

