  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "@game-guild/ui/components/drawer";
import { cn } from "@/lib/utils";

function slugify(text: string) {
  return text
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)+/g, "");
}

export function CourseCreateDrawer({ className }: { className?: string }) {
  const router = useRouter();
  const [open, setOpen] = React.useState(false);
  const [title, setTitle] = React.useState("");
  const [slug, setSlug] = React.useState("");
  const [description, setDescription] = React.useState("");
  const [category, setCategory] = React.useState("");
  const [difficulty, setDifficulty] = React.useState("");

  React.useEffect(() => {
    setSlug(slugify(title));
  }, [title]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    // Navigate to create page for now
    router.push('/dashboard/courses/create');
    setOpen(false);
  };

  const resetForm = () => {
    setTitle("");
    setSlug("");
    setDescription("");
    setCategory("");
    setDifficulty("");
  };

  const handleOpenChange = (newOpen: boolean) => {
    setOpen(newOpen);
    if (!newOpen) {
      resetForm();
    }
  };

  return (
    <Drawer open={open} onOpenChange={handleOpenChange}>
      <DrawerTrigger render={<Button className={cn("", className)}>Create Course</Button>} />
      <DrawerContent className="mx-auto w-full max-w-md">
        <DrawerHeader>
          <DrawerTitle>Create New Course</DrawerTitle>
        </DrawerHeader>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div className="space-y-2">
            <Label htmlFor="title">Course Title</Label>
            <Input
              id="title"
              placeholder="Enter course title"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="slug">URL Slug</Label>
            <Input
              id="slug"
              placeholder="course-url-slug"
              value={slug}
              onChange={(e) => setSlug(e.target.value)}
              required
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description</Label>
            <Textarea
              id="description"
              placeholder="Course description..."
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={3}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="category">Category</Label>
              <Select value={category} onValueChange={(value) => value !== null && setCategory(value)}>
                <SelectTrigger>
                  <SelectValue placeholder="Select category" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="programming">Programming</SelectItem>
                  <SelectItem value="design">Design</SelectItem>
                  <SelectItem value="game-development">Game Development</SelectItem>
                  <SelectItem value="business">Business</SelectItem>
                  <SelectItem value="other">Other</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="difficulty">Difficulty</Label>
              <Select value={difficulty} onValueChange={(value) => value !== null && setDifficulty(value)}>
                <SelectTrigger>
                  <SelectValue placeholder="Select level" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="beginner">Beginner</SelectItem>
                  <SelectItem value="intermediate">Intermediate</SelectItem>
                  <SelectItem value="advanced">Advanced</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <DrawerFooter className="px-0">
            <Button type="submit" disabled={!title.trim()}>
              Create Course
            </Button>
            <DrawerClose render={<Button variant="outline">Cancel</Button>} />
          </DrawerFooter>
        </form>
      </DrawerContent>
    </Drawer>
  );
}

'use client';

import { useCourseEditor } from '@/components/courses/editor/context/course-editor-provider';
import { createCourse, saveCourse } from '@/components/courses/editor/actions';
import { Button } from '@game-guild/ui/components/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { ArrowLeft, BookOpen, DollarSign, Eye, FileText, Image, Save, Settings } from 'lucide-react';
import Link from 'next/link';
import { useState } from 'react';
import { ContentStructureSection } from './sections/content-structure-section';
import { GeneralDetailsSection } from './sections/general-details-section';
import { SalesShowcaseSection } from './sections/sales-showcase-section';
import { ThumbnailMediaSection } from './sections/thumbnail-media-section';

interface CourseEditorProps {
  slug?: string;
  isCreating?: boolean;
}

const SECTIONS = [
  { id: 'general', label: 'General Details', icon: FileText, description: 'Title, description, category' },
  { id: 'media', label: 'Media & Assets', icon: Image, description: 'Thumbnail, videos, images' },
  { id: 'content', label: 'Course Content', icon: BookOpen, description: 'Lessons, modules, materials' },
  { id: 'pricing', label: 'Pricing & Sales', icon: DollarSign, description: 'Products, pricing, enrollment' },
  { id: 'settings', label: 'Settings', icon: Settings, description: 'Publishing, access, advanced' },
] as const;

export function CourseEditor({ slug, isCreating = false }: CourseEditorProps) {
  const { state, validate } = useCourseEditor();
  const [activeSection, setActiveSection] = useState<string>('general');
  const [isSaving, setIsSaving] = useState(false);
  const [saveMessage, setSaveMessage] = useState<string | null>(null);

  const level: 'Beginner' | 'Intermediate' | 'Advanced' = state.difficulty >= 3 ? 'Advanced' : state.difficulty === 2 ? 'Intermediate' : 'Beginner';

  const handleSave = async () => {
    const validation = validate();
    setSaveMessage(null);

    if (!validation.isValid) {
      return;
    }

    try {
      setIsSaving(true);
      const payload = {
        id: slug ?? state.slug,
        title: state.title,
        slug: state.slug,
        description: state.description || state.summary,
        area: state.category,
        level,
        thumbnail: state.media.thumbnail?.url,
        videoShowcaseUrl: state.media.showcaseVideo?.url,
        estimatedHours: state.estimatedHours,
        maxEnrollments: state.enrollment.maxEnrollments,
        enrollmentDeadline: state.enrollment.deadline,
        enrollmentStatus: state.enrollment.isOpen ? 'open' : 'closed',
        status: state.status,
        tags: state.tags,
        tools: [],
        isPublic: state.status === 'published',
      };

      const result = isCreating ? await createCourse(payload) : await saveCourse(payload);

      setSaveMessage(result ? `Course ${isCreating ? 'created' : 'saved'}.` : 'Course could not be saved.');
    } catch (error) {
      console.error('Failed to save course:', error);
      setSaveMessage('Course could not be saved.');
    } finally {
      setIsSaving(false);
    }
  };

  const handlePreview = () => {
    const previewSlug = slug ?? state.slug;
    if (previewSlug) {
      window.open(`/courses/${previewSlug}`, '_blank', 'noopener,noreferrer');
    }
  };

  return (
    <div className="min-h-screen bg-background">
      {/* Sticky Header */}
      <div className="sticky top-0 z-50 bg-background/95 backdrop-blur-sm border-b border-border shadow-sm">
        <div className="container mx-auto max-w-7xl px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <Link href="/dashboard/courses">
                <Button variant="ghost" size="sm">
                  <ArrowLeft className="h-4 w-4 mr-2" />
                  Back to Courses
                </Button>
              </Link>

              <div>
                <h1 className="text-2xl font-bold text-foreground">{isCreating ? 'Create New Course' : 'Edit Course'}</h1>
                {slug && (
                  <p className="text-sm text-muted-foreground">
                    /{slug}
                  </p>
                )}
              </div>
            </div>

            <div className="flex items-center gap-3">
              {/* Status Badge */}
              <div className="px-3 py-1 rounded-full text-xs font-medium bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400">
                Draft
              </div>

              {/* Action Buttons */}
              <Button variant="outline" onClick={handlePreview} disabled={!slug}>
                <Eye className="h-4 w-4 mr-2" />
                Preview
              </Button>

              <Button onClick={handleSave} disabled={isSaving} className="bg-gradient-to-r from-primary to-chart-2 hover:from-primary/90 hover:to-chart-2/90">
                <Save className="h-4 w-4 mr-2" />
                {isSaving ? 'Saving...' : isCreating ? 'Create Course' : 'Save Changes'}
              </Button>
            </div>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="container mx-auto max-w-7xl p-6">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main Content Column */}
          <div className="lg:col-span-2 space-y-8">
            {/* General Details */}
            <Card className="shadow-lg border-border bg-card/50 backdrop-blur-sm">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">📝 General Details</CardTitle>
              </CardHeader>
              <CardContent>
                {Object.keys(state.errors).length > 0 && (
                  <div role="alert" className="mb-4 rounded-md border border-destructive/30 bg-destructive/10 p-3 text-sm text-destructive">
                    <p className="font-medium">Fix course details before saving.</p>
                    <ul className="mt-2 list-disc space-y-1 pl-5">
                      {Object.entries(state.errors).map(([field, error]) => (
                        <li key={field}>{error}</li>
                      ))}
                    </ul>
                  </div>
                )}
                {saveMessage && (
                  <div role="status" className="mb-4 rounded-md border border-border bg-muted p-3 text-sm text-foreground">
                    {saveMessage}
                  </div>
                )}
                <GeneralDetailsSection />
              </CardContent>
            </Card>

            {/* Thumbnail & Media */}
            <Card className="shadow-lg border-border bg-card/50 backdrop-blur-sm">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">🎨 Thumbnail & Media</CardTitle>
              </CardHeader>
              <CardContent>
                <ThumbnailMediaSection />
              </CardContent>
            </Card>

            {/* Course Content */}
            <Card className="shadow-lg border-border bg-card/50 backdrop-blur-sm">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">📚 Course Content</CardTitle>
              </CardHeader>
              <CardContent>
                <ContentStructureSection />
              </CardContent>
            </Card>
          </div>

          {/* Sidebar */}
          <div className="space-y-8">
            {/* Sales & Showcase */}
            <Card className="shadow-lg border-border bg-card/50 backdrop-blur-sm">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">💰 Sales & Showcase</CardTitle>
              </CardHeader>
              <CardContent>
                <SalesShowcaseSection />
              </CardContent>
            </Card>

            <Card className="shadow-lg border-border bg-card/50 backdrop-blur-sm">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">Preview</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="aspect-video overflow-hidden rounded-lg bg-muted">
                  {state.media.thumbnail?.url ? (
                    // eslint-disable-next-line @next/next/no-img-element
                    <img src={state.media.thumbnail.url} alt={state.media.thumbnail.alt || state.title || 'Course thumbnail'} className="h-full w-full object-cover" />
                  ) : (
                    <div className="flex h-full items-center justify-center text-sm text-muted-foreground">No thumbnail</div>
                  )}
                </div>

                <div>
                  <h3 className="line-clamp-2 font-semibold text-foreground">{state.title || 'Untitled Course'}</h3>
                  <p className="mt-1 line-clamp-2 text-sm text-muted-foreground">{state.summary || 'No summary provided'}</p>
                </div>

                <div className="flex items-center justify-between text-sm">
                  <span className="text-muted-foreground">
                    {state.estimatedHours}h - {state.category || 'No category'}
                  </span>
                  <span className="rounded-full bg-muted px-2 py-1 text-xs text-muted-foreground">{level}</span>
                </div>

                {state.tags.length > 0 && (
                  <div className="flex flex-wrap gap-1">
                    {state.tags.map((tag) => (
                      <span key={tag} className="rounded bg-muted px-2 py-1 text-xs">
                        {tag}
                      </span>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@game-guild/ui/components/dialog';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from '@game-guild/ui/components/dropdown-menu';
import { Input } from '@game-guild/ui/components/input';
import { Switch } from '@game-guild/ui/components/switch';
import { Textarea } from '@game-guild/ui/components/textarea';
import { Activity, BookOpen, CheckSquare, ChevronDown, ChevronRight, Copy, Edit, Eye, EyeOff, File, FileText, Folder, FolderOpen, GripVertical, HelpCircle, MoreHorizontal, Plus, Redo, Trash2, Undo, Video } from 'lucide-react';
import { useState } from 'react';
import { useCourseEditor } from '../../editor/context/course-editor-provider';

type CourseLesson = {
  id: string;
  title: string;
  description: string;
  type: LessonFormData['type'];
  visibility: LessonFormData['visibility'];
  status: LessonFormData['status'];
  isRequired: boolean;
  duration: number;
};

type CourseModule = {
  id: string;
  title: string;
  description: string;
  visibility: ModuleFormData['visibility'];
  status: ModuleFormData['status'];
  estimatedDuration: number;
  isExpanded?: boolean;
  lessons: CourseLesson[];
};

// Content type icons
const CONTENT_TYPE_ICONS = {
  text: FileText,
  video: Video,
  quiz: HelpCircle,
  assignment: CheckSquare,
  file: File,
  interactive: Activity,
} as const;

// Content type colors
const CONTENT_TYPE_COLORS = {
  text: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400',
  video: 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-400',
  quiz: 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-400',
  assignment: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400',
  file: 'bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-400',
  interactive: 'bg-pink-100 text-pink-800 dark:bg-pink-900/30 dark:text-pink-400',
} as const;

interface ModuleFormData {
  title: string;
  description: string;
  visibility: 'public' | 'private' | 'premium';
  status: 'draft' | 'published' | 'archived';
  sortOrder: number;
  estimatedDuration: number;
}

interface LessonFormData {
  title: string;
  description: string;
  type: 'text' | 'video' | 'quiz' | 'assignment' | 'file' | 'interactive';
  visibility: 'public' | 'private' | 'premium';
  status: 'draft' | 'published' | 'archived';
  isRequired: boolean;
  duration: number;
  sortOrder: number;
}

const defaultModuleData: ModuleFormData = {
  title: '',
  description: '',
  visibility: 'public',
  status: 'draft',
  sortOrder: 0,
  estimatedDuration: 60,
};

const defaultLessonData: LessonFormData = {
  title: '',
  description: '',
  type: 'text',
  visibility: 'public',
  status: 'draft',
  isRequired: true,
  duration: 15,
  sortOrder: 0,
};

export function ContentStructureSection() {
  const { state, dispatch } = useCourseEditor();
  const [showModuleDialog, setShowModuleDialog] = useState(false);
  const [showLessonDialog, setShowLessonDialog] = useState(false);
  const [selectedModuleId, setSelectedModuleId] = useState<string | null>(null);
  const [editingModuleId, setEditingModuleId] = useState<string | null>(null);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [moduleFormData, setModuleFormData] = useState<ModuleFormData>(defaultModuleData);
  const [lessonFormData, setLessonFormData] = useState<LessonFormData>(defaultLessonData);  // Handle adding a new module
  const handleSaveModule = () => {
    if (!moduleFormData.title.trim()) return;

    const moduleData = {
      title: moduleFormData.title,
      description: moduleFormData.description,
      sortOrder: state.content.modules.length,
      status: moduleFormData.status,
      visibility: moduleFormData.visibility,
      lessons: [],
      submodules: [],
      estimatedDuration: moduleFormData.estimatedDuration,
    };

    if (editingModuleId) {
      dispatch({ type: 'UPDATE_MODULE', moduleId: editingModuleId, updates: moduleData });
    } else {
      dispatch({ type: 'ADD_MODULE', module: { ...moduleData, lessons: [], submodules: [] } });
    }

    setModuleFormData(defaultModuleData);
    setEditingModuleId(null);
    setShowModuleDialog(false);
  };

  // Handle adding a new lesson
  const handleSaveLesson = () => {
    if (!lessonFormData.title.trim() || !selectedModuleId) return;

    const lessonData = {
      title: lessonFormData.title,
      description: lessonFormData.description,
      type: lessonFormData.type,
      duration: lessonFormData.duration,
      status: lessonFormData.status,
      visibility: lessonFormData.visibility,
      isRequired: lessonFormData.isRequired,
    };

    if (editingLessonId) {
      dispatch({ type: 'UPDATE_LESSON', lessonId: editingLessonId, updates: lessonData });
    } else {
      dispatch({ type: 'ADD_LESSON', moduleId: selectedModuleId, lesson: lessonData });
    }

    setLessonFormData(defaultLessonData);
    setEditingLessonId(null);
    setShowLessonDialog(false);
    setSelectedModuleId(null);
  };

  // Handle module actions
  const handleModuleAction = (moduleId: string, action: string) => {
    const module = state.content.modules.find((m) => m.id === moduleId);

    switch (action) {
      case 'edit':
        if (module) {
          setEditingModuleId(moduleId);
          setModuleFormData({
            title: module.title,
            description: module.description,
            visibility: module.visibility,
            status: module.status,
            sortOrder: module.sortOrder,
            estimatedDuration: module.estimatedDuration,
          });
          setShowModuleDialog(true);
        }
        break;
      case 'delete':
        dispatch({ type: 'REMOVE_MODULE', moduleId });
        break;
      case 'duplicate':
        dispatch({ type: 'DUPLICATE_MODULE', moduleId });
        break;
      case 'toggle-visibility':
        dispatch({
          type: 'UPDATE_MODULE',
          moduleId,
          updates: {
            visibility: state.content.modules.find((m: any) => m.id === moduleId)?.visibility === 'public' ? 'private' : 'public',
          },
        });
        break;
      case 'toggle-expanded':
        dispatch({ type: 'TOGGLE_MODULE_EXPANDED', moduleId });
        break;
    }
  };

  // Handle lesson actions
  const handleLessonAction = (lessonId: string, action: string) => {
    const owningModule = state.content.modules.find((module) => module.lessons.some((lesson) => lesson.id === lessonId));
    const lesson = owningModule?.lessons.find((item) => item.id === lessonId);

    switch (action) {
      case 'edit':
        if (owningModule && lesson) {
          setSelectedModuleId(owningModule.id);
          setEditingLessonId(lessonId);
          setLessonFormData({
            title: lesson.title,
            description: lesson.description,
            type: lesson.type,
            visibility: lesson.visibility,
            status: lesson.status,
            isRequired: lesson.isRequired,
            duration: lesson.duration,
            sortOrder: 0,
          });
          setShowLessonDialog(true);
        }
        break;
      case 'delete':
        dispatch({ type: 'REMOVE_LESSON', lessonId });
        break;
      case 'duplicate':
        dispatch({ type: 'DUPLICATE_LESSON', lessonId });
        break;
      case 'toggle-visibility':
        if (lesson) {
          dispatch({
            type: 'UPDATE_LESSON',
            lessonId,
            updates: {
              visibility: lesson.visibility === 'public' ? 'private' : 'public',
            },
          });
        }
        break;
    }
  };

  // Render lesson item
  const renderLesson = (lesson: CourseLesson) => {
    const IconComponent = CONTENT_TYPE_ICONS[lesson.type as keyof typeof CONTENT_TYPE_ICONS] || FileText;
    const colorClass = CONTENT_TYPE_COLORS[lesson.type as keyof typeof CONTENT_TYPE_COLORS] || 'text-slate-400';

    return (
      <div
        key={lesson.id}
        className={`group flex items-center gap-3 p-3 rounded-lg border transition-all hover:shadow-sm ${state.content.selectedItems.includes(lesson.id) ? 'bg-primary/5 border-primary/20' : 'bg-background border-border hover:border-border/60'
          }`}
      >
        {/* Drag handle */}
        <GripVertical className="h-4 w-4 text-muted-foreground opacity-0 group-hover:opacity-100 cursor-grab" />

        {/* Content type icon */}
        <div className={`p-1.5 rounded ${colorClass}`}>
          <IconComponent className="h-3 w-3" />
        </div>

        {/* Lesson info */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <h4 className="text-sm font-medium truncate">{lesson.title}</h4>
            {lesson.isRequired && (
              <Badge variant="secondary" className="text-xs">
                Required
              </Badge>
            )}
            {lesson.visibility === 'private' && <EyeOff className="h-3 w-3 text-muted-foreground" />}
          </div>
          {lesson.description && <p className="text-xs text-muted-foreground truncate mt-1">{lesson.description}</p>}
          <div className="flex items-center gap-2 mt-1">
            <Badge variant="outline" className="text-xs">
              {lesson.type}
            </Badge>
            <span className="text-xs text-muted-foreground">{lesson.duration}m</span>
            <Badge variant={lesson.status === 'published' ? 'default' : 'secondary'} className="text-xs">
              {lesson.status}
            </Badge>
          </div>
        </div>

        {/* Actions */}
        <DropdownMenu>
          <DropdownMenuTrigger render={<Button variant="ghost" size="sm" className="h-8 w-8 p-0 opacity-0 group-hover:opacity-100" />}>
            <MoreHorizontal className="h-4 w-4" />
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-48">
            <DropdownMenuItem onClick={() => handleLessonAction(lesson.id, 'edit')}>
              <Edit className="h-4 w-4 mr-2" />
              Edit Lesson
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => handleLessonAction(lesson.id, 'duplicate')}>
              <Copy className="h-4 w-4 mr-2" />
              Duplicate
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => handleLessonAction(lesson.id, 'toggle-visibility')}>
              {lesson.visibility === 'public' ? (
                <>
                  <EyeOff className="h-4 w-4 mr-2" />
                  Make Private
                </>
              ) : (
                <>
                  <Eye className="h-4 w-4 mr-2" />
                  Make Public
                </>
              )}
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={() => handleLessonAction(lesson.id, 'delete')} className="text-destructive focus:text-destructive">
              <Trash2 className="h-4 w-4 mr-2" />
              Delete
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    );
  };

  // Render module item
  const renderModule = (module: CourseModule) => {
    const isExpanded = module.isExpanded ?? false;
    const lessonCount = module.lessons?.length ?? 0;
    const totalDuration = module.lessons?.reduce((sum: number, lesson: any) => sum + lesson.duration, 0) ?? 0;

    return (
      <div key={module.id} className="border border-border rounded-lg overflow-hidden">
        {/* Module header */}
        <div className={`group flex items-center gap-3 p-4 transition-all hover:bg-muted/30 ${state.content.selectedItems.includes(module.id) ? 'bg-primary/5 border-primary/20' : 'bg-background'}`}>
          {/* Drag handle */}
          <GripVertical className="h-4 w-4 text-muted-foreground opacity-0 group-hover:opacity-100 cursor-grab" />

          {/* Expand/collapse button */}
          <Button variant="ghost" size="sm" className="h-6 w-6 p-0" onClick={() => handleModuleAction(module.id, 'toggle-expanded')}>
            {isExpanded ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
          </Button>

          {/* Module icon */}
          <div className="p-1.5 rounded bg-primary/10 text-primary">{isExpanded ? <FolderOpen className="h-4 w-4" /> : <Folder className="h-4 w-4" />}</div>

          {/* Module info */}
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2">
              <h3 className="font-medium truncate">{module.title}</h3>
              {module.visibility === 'private' && <EyeOff className="h-4 w-4 text-muted-foreground" />}
            </div>
            {module.description && <p className="text-sm text-muted-foreground truncate mt-1">{module.description}</p>}
            <div className="flex items-center gap-3 mt-2">
              <span className="text-xs text-muted-foreground">
                {lessonCount} lesson{lessonCount !== 1 ? 's' : ''}
              </span>
              <span className="text-xs text-muted-foreground">~{Math.round(totalDuration)}m</span>
              <Badge variant={module.status === 'published' ? 'default' : 'secondary'} className="text-xs">
                {module.status}
              </Badge>
            </div>
          </div>

          {/* Add lesson button */}
          <Button
            variant="outline"
            size="sm"
            className="opacity-0 group-hover:opacity-100 transition-opacity"
            onClick={() => {
              setSelectedModuleId(module.id);
              setShowLessonDialog(true);
            }}
          >
            <Plus className="h-4 w-4 mr-2" />
            Add Lesson
          </Button>

          {/* Module actions */}
          <DropdownMenu>
            <DropdownMenuTrigger render={<Button variant="ghost" size="sm" className="h-8 w-8 p-0 opacity-0 group-hover:opacity-100" />}>
              <MoreHorizontal className="h-4 w-4" />
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-48">
              <DropdownMenuItem onClick={() => handleModuleAction(module.id, 'edit')}>
                <Edit className="h-4 w-4 mr-2" />
                Edit Module
              </DropdownMenuItem>
              <DropdownMenuItem onClick={() => handleModuleAction(module.id, 'duplicate')}>
                <Copy className="h-4 w-4 mr-2" />
                Duplicate
              </DropdownMenuItem>
              <DropdownMenuItem onClick={() => handleModuleAction(module.id, 'toggle-visibility')}>
                {module.visibility === 'public' ? (
                  <>
                    <EyeOff className="h-4 w-4 mr-2" />
                    Make Private
                  </>
                ) : (
                  <>
                    <Eye className="h-4 w-4 mr-2" />
                    Make Public
                  </>
                )}
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem onClick={() => handleModuleAction(module.id, 'delete')} className="text-destructive focus:text-destructive">
                <Trash2 className="h-4 w-4 mr-2" />
                Delete
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>

        {/* Module lessons (when expanded) */}
        {isExpanded && (
          <div className="p-4 pt-0 space-y-2 bg-muted/20">
            {module.lessons && module.lessons.length > 0 ? (
              module.lessons.map((lesson: any) => renderLesson(lesson))
            ) : (
              <div className="text-center py-8 text-muted-foreground">
                <BookOpen className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p className="text-sm">No lessons yet</p>
                <Button
                  variant="outline"
                  size="sm"
                  className="mt-2"
                  onClick={() => {
                    setSelectedModuleId(module.id);
                    setShowLessonDialog(true);
                  }}
                >
                  <Plus className="h-4 w-4 mr-2" />
                  Add First Lesson
                </Button>
              </div>
            )}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold">Course Content</h2>
          <p className="text-sm text-muted-foreground">Organize your course into modules and lessons</p>
        </div>

        <div className="flex items-center gap-2">
          {/* Undo/Redo */}
          <Button variant="outline" size="sm" disabled={!state.undoRedo.canUndo} onClick={() => dispatch({ type: 'UNDO' })}>
            <Undo className="h-4 w-4" />
          </Button>
          <Button variant="outline" size="sm" disabled={!state.undoRedo.canRedo} onClick={() => dispatch({ type: 'REDO' })}>
            <Redo className="h-4 w-4" />
          </Button>

          {/* Add Module Button */}
          <Button onClick={() => setShowModuleDialog(true)} className="bg-gradient-to-r from-primary to-chart-2">
            <Plus className="h-4 w-4 mr-2" />
            Add Module
          </Button>
        </div>
      </div>

      {/* Content */}
      {state.content.modules.length > 0 ? (
        <div className="space-y-4">{state.content.modules.map(renderModule)}</div>
      ) : (
        <div className="text-center py-12 border-2 border-dashed border-border rounded-lg">
          <BookOpen className="h-12 w-12 mx-auto mb-4 text-muted-foreground/50" />
          <h3 className="text-lg font-medium mb-2">No modules yet</h3>
          <p className="text-muted-foreground mb-4">Start building your course by adding your first module</p>
          <Button onClick={() => setShowModuleDialog(true)} className="bg-gradient-to-r from-primary to-chart-2">
            <Plus className="h-4 w-4 mr-2" />
            Add First Module
          </Button>
        </div>
      )}

      {/* Add Module Dialog */}
      <Dialog open={showModuleDialog} onOpenChange={setShowModuleDialog}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>{editingModuleId ? 'Edit Module' : 'Add New Module'}</DialogTitle>
            <DialogDescription>Define the module name, visibility, status, and expected duration.</DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm font-medium">Title</label>
              <Input placeholder="Module title..." value={moduleFormData.title} onChange={(e) => setModuleFormData({ ...moduleFormData, title: e.target.value })} />
            </div>

            <div>
              <label className="text-sm font-medium">Description</label>
              <Textarea placeholder="Brief description of this module..." value={moduleFormData.description} onChange={(e) => setModuleFormData({ ...moduleFormData, description: e.target.value })} rows={3} />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium">Visibility</label>
                <select
                  className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-background"
                  value={moduleFormData.visibility}
                  onChange={(e) =>
                    setModuleFormData({
                      ...moduleFormData,
                      visibility: e.target.value as 'public' | 'private' | 'premium',
                    })
                  }
                >
                  <option value="public">Public</option>
                  <option value="private">Private</option>
                  <option value="premium">Premium</option>
                </select>
              </div>

              <div>
                <label className="text-sm font-medium">Status</label>
                <select
                  className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-background"
                  value={moduleFormData.status}
                  onChange={(e) =>
                    setModuleFormData({
                      ...moduleFormData,
                      status: e.target.value as 'draft' | 'published' | 'archived',
                    })
                  }
                >
                  <option value="draft">Draft</option>
                  <option value="published">Published</option>
                  <option value="archived">Archived</option>
                </select>
              </div>
            </div>

            <div className="flex justify-end gap-2 pt-4">
              <Button
                variant="outline"
                onClick={() => {
                  setEditingModuleId(null);
                  setModuleFormData(defaultModuleData);
                  setShowModuleDialog(false);
                }}
              >
                Cancel
              </Button>
              <Button onClick={handleSaveModule} disabled={!moduleFormData.title.trim()}>
                {editingModuleId ? 'Save Module' : 'Add Module'}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* Add Lesson Dialog */}
      <Dialog open={showLessonDialog} onOpenChange={setShowLessonDialog}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>{editingLessonId ? 'Edit Lesson' : 'Add New Lesson'}</DialogTitle>
            <DialogDescription>Define the lesson metadata students will see in the course outline.</DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <label className="text-sm font-medium">Title</label>
              <Input placeholder="Lesson title..." value={lessonFormData.title} onChange={(e) => setLessonFormData({ ...lessonFormData, title: e.target.value })} />
            </div>

            <div>
              <label className="text-sm font-medium">Description</label>
              <Textarea placeholder="Brief description of this lesson..." value={lessonFormData.description} onChange={(e) => { setLessonFormData({ ...lessonFormData, description: e.target.value }); }} rows={3} />
            </div>

            <div>
              <label className="text-sm font-medium">Content Type</label>
              <select
                className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-background"
                value={lessonFormData.type}
                onChange={(e) =>
                  setLessonFormData({
                    ...lessonFormData,
                    type: e.target.value as 'text' | 'video' | 'quiz' | 'assignment' | 'file' | 'interactive',
                  })
                }
              >
                <option value="text">Text/Article</option>
                <option value="video">Video</option>
                <option value="quiz">Quiz</option>
                <option value="assignment">Assignment</option>
                <option value="file">File/Download</option>
                <option value="interactive">Interactive</option>
              </select>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium">Duration (minutes)</label>
                <Input
                  type="number"
                  min="1"
                  value={lessonFormData.duration}
                  onChange={(e) =>
                    setLessonFormData({
                      ...lessonFormData,
                      duration: parseInt(e.target.value) || 15,
                    })
                  }
                />
              </div>

              <div>
                <label className="text-sm font-medium">Status</label>
                <select
                  className="w-full mt-1 px-3 py-2 border border-border rounded-md bg-background"
                  value={lessonFormData.status}
                  onChange={(e) =>
                    setLessonFormData({
                      ...lessonFormData,
                      status: e.target.value as 'draft' | 'published' | 'archived',
                    })
                  }
                >
                  <option value="draft">Draft</option>
                  <option value="published">Published</option>
                  <option value="archived">Archived</option>
                </select>
              </div>
            </div>

            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-2">
                <Switch
                  checked={lessonFormData.isRequired}
                  onCheckedChange={(checked) =>
                    setLessonFormData({
                      ...lessonFormData,
                      isRequired: checked,
                    })
                  }
                />
                <label className="text-sm font-medium">Required lesson</label>
              </div>
            </div>

            <div className="flex justify-end gap-2 pt-4">
              <Button
                variant="outline"
                onClick={() => {
                  setEditingLessonId(null);
                  setSelectedModuleId(null);
                  setLessonFormData(defaultLessonData);
                  setShowLessonDialog(false);
                }}
              >
                Cancel
              </Button>
              <Button onClick={handleSaveLesson} disabled={!lessonFormData.title.trim()}>
                {editingLessonId ? 'Save Lesson' : 'Add Lesson'}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import type { CourseLevel } from '@/lib/courses/catalog-types';
import { Input } from '@game-guild/ui/components/input';
import { Label } from '@game-guild/ui/components/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@game-guild/ui/components/select';
import { Textarea } from '@game-guild/ui/components/textarea';
import { useCourseEditor } from '../../editor/context/course-editor-provider';
import { RichTextEditor } from '../rich-text-editor';

const CATEGORIES = ['Web Development', 'Mobile Development', 'Data Science', 'Machine Learning', 'DevOps', 'Design', 'Business', 'Marketing', 'Other'];

const DIFFICULTY_LEVELS = [
  { value: 1, label: 'Beginner', description: 'No prior experience needed' },
  { value: 2, label: 'Intermediate', description: 'Some experience helpful' },
  { value: 3, label: 'Advanced', description: 'Significant experience required' },
  { value: 4, label: 'Expert', description: 'Professional level expertise' },
];

export function GeneralDetailsSection() {
  const {
    state,
    updateTitle,
    updateSlug,
    updateSummary,
    updateDescription,
    updateCategory,
    updateDifficulty,
  } = useCourseEditor();

  const handleTitleChange = (value: string) => {
    updateTitle(value);
  };

  const handleSlugChange = (value: string) => {
    updateSlug(value);
  };

  return (
    <div className="space-y-6">
      {/* Title */}
      <div className="space-y-2">
        <Label htmlFor="title" className="text-sm font-medium">
          Course Title *
        </Label>
        <Input id="title" value={state.title} onChange={(e) => handleTitleChange(e.target.value)} placeholder="Enter a compelling course title..." className={state.errors.title ? 'border-red-500' : ''} />
        {state.errors.title && <p className="text-sm text-red-600">{state.errors.title}</p>}
      </div>

      {/* Slug */}
      <div className="space-y-2">
        <Label htmlFor="slug" className="text-sm font-medium">
          Course URL Slug *
        </Label>
        <div className="flex items-center space-x-2">
          <span className="text-sm text-muted-foreground">/courses/</span>
          <Input id="slug" value={state.slug} onChange={(e) => handleSlugChange(e.target.value)} placeholder="course-url-slug" className={`flex-1 ${state.errors.slug ? 'border-red-500' : ''}`} />
        </div>
        {state.errors.slug && <p className="text-sm text-red-600">{state.errors.slug}</p>}
        <p className="text-xs text-muted-foreground">This will be the URL for your course. Use lowercase letters, numbers, and hyphens only.</p>
      </div>

      {/* Summary */}
      <div className="space-y-2">
        <Label htmlFor="summary" className="text-sm font-medium">
          Short Summary *
        </Label>
        <Textarea
          id="summary"
          value={state.summary}
          onChange={(e) => updateSummary(e.target.value)}
          placeholder="Write a brief, compelling summary that appears in course listings..."
          rows={3}
          className={state.errors.summary ? 'border-red-500' : ''}
        />
        {state.errors.summary && <p className="text-sm text-red-600">{state.errors.summary}</p>}
        <p className="text-xs text-muted-foreground">{state.summary.length}/200 characters</p>
      </div>

      {/* Category & Difficulty Row */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* Category */}
        <div className="space-y-2">
          <Label className="text-sm font-medium">Category *</Label>
          <Select value={state.category} onValueChange={(value) => value !== null && updateCategory(value)}>
            <SelectTrigger className={state.errors.category ? 'border-red-500' : ''}>
              <SelectValue placeholder="Select category" />
            </SelectTrigger>
            <SelectContent>
              {CATEGORIES.map((category) => (
                <SelectItem key={category} value={category}>
                  {category}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          {state.errors.category && <p className="text-sm text-red-600">{state.errors.category}</p>}
        </div>

        {/* Difficulty */}
        <div className="space-y-2">
          <Label className="text-sm font-medium">Difficulty Level *</Label>
          <Select value={state.difficulty.toString()} onValueChange={(value) => value !== null && updateDifficulty(parseInt(value) as CourseLevel)}>
            <SelectTrigger className={state.errors.difficulty ? 'border-red-500' : ''}>
              <SelectValue placeholder="Select difficulty" />
            </SelectTrigger>
            <SelectContent>
              {DIFFICULTY_LEVELS.map((level) => (
                <SelectItem key={level.value} value={level.value.toString()}>
                  <div className="flex items-center gap-2">
                    <div className="flex gap-1">
                      {Array.from({ length: level.value }, (_, i) => (
                        <div key={i} className="w-2 h-2 bg-primary rounded-full" />
                      ))}
                      {Array.from({ length: 4 - level.value }, (_, i) => (
                        <div key={i} className="w-2 h-2 bg-muted rounded-full" />
                      ))}
                    </div>
                    <span>{level.label}</span>
                  </div>
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          {state.errors.difficulty && <p className="text-sm text-red-600">{state.errors.difficulty}</p>}
        </div>
      </div>

      {/* Description */}
      <div className="space-y-2">
        <Label className="text-sm font-medium">Detailed Description</Label>
        <div className={`border rounded-md ${state.errors.description ? 'border-red-500' : 'border-input'}`}>
          <RichTextEditor content={state.description} onChange={updateDescription} placeholder="Write a detailed description of your course, including what students will learn, prerequisites, and outcomes..." />
        </div>
        {state.errors.description && <p className="text-sm text-red-600">{state.errors.description}</p>}
        <p className="text-xs text-muted-foreground">Use this space to provide comprehensive information about your course content, learning objectives, and what makes it valuable.</p>
      </div>
    </div>
  );
}

'use client';

import { useCourseEditor } from '@/components/courses/editor/context/course-editor-provider';
import { Button } from '@game-guild/ui/components/button';
import { Input } from '@game-guild/ui/components/input';
import { Label } from '@game-guild/ui/components/label';
import { Play, Upload, X } from 'lucide-react';
import React, { useRef } from 'react';

export function ThumbnailMediaSection() {
  const { state, setThumbnail, setShowcaseVideo } = useCourseEditor();

  const thumbnailInputRef = useRef<HTMLInputElement>(null);
  const videoInputRef = useRef<HTMLInputElement>(null);

  const handleThumbnailUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setThumbnail({
        url,
        alt: `Thumbnail for course`,
        file,
      });
    }
  };

  const handleVideoUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setShowcaseVideo({
        url,
        platform: 'direct' as const,
        embedId: undefined,
      });
    }
  };

  const removeThumbnail = () => {
    setThumbnail(undefined);
    if (thumbnailInputRef.current) {
      thumbnailInputRef.current.value = '';
    }
  };

  const removeVideo = () => {
    setShowcaseVideo(undefined);
    if (videoInputRef.current) {
      videoInputRef.current.value = '';
    }
  };

  const handleThumbnailUrlChange = (value: string) => {
    setThumbnail(value.trim() ? { url: value, alt: state.title ? `Thumbnail for ${state.title}` : 'Course thumbnail' } : undefined);
  };

  const handleVideoUrlChange = (value: string) => {
    setShowcaseVideo(value.trim() ? { url: value, platform: 'hosted-url' } : undefined);
  };

  return (
    <div className="space-y-6">
      {/* Thumbnail Section */}
      <div className="space-y-4">
        <Label className="text-sm font-medium">Course Thumbnail</Label>

        <div className="space-y-2">
          <Label htmlFor="thumbnailUrl" className="text-sm">
            Hosted image URL
          </Label>
          <Input
            id="thumbnailUrl"
            type="url"
            value={state.media.thumbnail?.file ? '' : state.media.thumbnail?.url ?? ''}
            onChange={(event) => handleThumbnailUrlChange(event.target.value)}
            placeholder="https://example.com/course-cover.jpg"
          />
          <p className="text-xs text-muted-foreground">Use a durable hosted image URL for public course landing pages. File upload preview is still available for local drafting.</p>
        </div>

        {state.media.thumbnail ? (
          <div className="relative">
            <div className="aspect-video bg-muted rounded-lg overflow-hidden border border-border">
              <img src={state.media.thumbnail.url} alt={state.media.thumbnail.alt} className="w-full h-full object-cover" />
            </div>
            <Button variant="destructive" size="sm" className="absolute top-2 right-2" onClick={removeThumbnail}>
              <X className="h-4 w-4" />
            </Button>
            <div className="mt-2 text-xs text-muted-foreground">
              {state.media.thumbnail.file?.name} • {Math.round((state.media.thumbnail.file?.size || 0) / 1024)} KB
            </div>
          </div>
        ) : (
          <div className="aspect-video bg-muted rounded-lg border-2 border-dashed border-border hover:border-primary/50 transition-colors">
            <div className="flex flex-col items-center justify-center h-full gap-3">
              <Upload className="h-8 w-8 text-muted-foreground" />
              <div className="text-center">
                <p className="text-sm font-medium">Upload Thumbnail</p>
                <p className="text-xs text-muted-foreground">Recommended: 1280x720px, JPG or PNG</p>
              </div>
              <Button variant="outline" onClick={() => thumbnailInputRef.current?.click()}>
                Choose File
              </Button>
            </div>
          </div>
        )}

        <input ref={thumbnailInputRef} type="file" accept="image/*" onChange={handleThumbnailUpload} className="hidden" />

        {state.errors.thumbnail && <p className="text-sm text-red-600">{state.errors.thumbnail}</p>}
      </div>

      {/* Video Section */}
      <div className="space-y-4">
        <Label className="text-sm font-medium">Showcase Video (Optional)</Label>

        <div className="space-y-2">
          <Label htmlFor="showcaseVideoUrl" className="text-sm">
            Hosted video URL
          </Label>
          <Input
            id="showcaseVideoUrl"
            type="url"
            value={state.media.showcaseVideo?.platform === 'direct' ? '' : state.media.showcaseVideo?.url ?? ''}
            onChange={(event) => handleVideoUrlChange(event.target.value)}
            placeholder="https://youtube.com/watch?v=..."
          />
          <p className="text-xs text-muted-foreground">Paste a YouTube, Vimeo, or hosted MP4 URL to persist the public promo video.</p>
        </div>

        {state.media.showcaseVideo ? (
          <div className="relative">
            <div className="aspect-video bg-muted rounded-lg overflow-hidden border border-border">
              <video src={state.media.showcaseVideo.url} className="w-full h-full object-cover" controls preload="metadata">
                Your browser does not support the video tag.
              </video>
            </div>
            <Button variant="destructive" size="sm" className="absolute top-2 right-2" onClick={removeVideo}>
              <X className="h-4 w-4" />
            </Button>
            <div className="mt-2 text-xs text-muted-foreground">Video uploaded • {state.media.showcaseVideo.platform} format</div>
          </div>
        ) : (
          <div className="aspect-video bg-muted rounded-lg border-2 border-dashed border-border hover:border-primary/50 transition-colors">
            <div className="flex flex-col items-center justify-center h-full gap-3">
              <Play className="h-8 w-8 text-muted-foreground" />
              <div className="text-center">
                <p className="text-sm font-medium">Upload Showcase Video</p>
                <p className="text-xs text-muted-foreground">Recommended: MP4, max 100MB</p>
              </div>
              <Button variant="outline" onClick={() => videoInputRef.current?.click()}>
                Choose Video
              </Button>
            </div>
          </div>
        )}

        <input ref={videoInputRef} type="file" accept="video/*" onChange={handleVideoUpload} className="hidden" />

        {state.errors.video && <p className="text-sm text-red-600">{state.errors.video}</p>}
      </div>

      {/* Media Guidelines */}
      <div className="p-4 bg-muted/50 rounded-lg space-y-2">
        <h4 className="font-medium text-sm">Media Guidelines</h4>
        <ul className="text-xs text-muted-foreground space-y-1">
          <li>• Thumbnail: Use high-quality images that represent your course content</li>
          <li>• Video: Keep showcase videos under 2 minutes for best engagement</li>
          <li>• Both: Ensure content is appropriate and follows platform guidelines</li>
          <li>• Formats: JPG/PNG for images, MP4 for videos</li>
        </ul>
      </div>
    </div>
  );
}

'use client';

import { Program } from '@/lib/api/generated';
import { useCourseContext } from '@/lib/courses';
import { CourseGrid } from './course-grid';

// ProgramDifficulty enum values (from backend)
const ProgramDifficulty = {
  Beginner: 0,
  Intermediate: 1,
  Advanced: 2,
  Expert: 3,
} as const;

// EnrollmentStatus enum values (from backend)
const EnrollmentStatus = {
  Pending: 0,
  Active: 1,
  Completed: 2,
  Cancelled: 3,
  Expired: 4,
} as const;

// Transform Program to CourseGridCourse format
function transformProgramToCourse(program: Program, index: number) {
  const fallbackId = `course-${index + 1}`;
  const thumbnail = typeof program.thumbnail === 'string' && program.thumbnail.length > 0
    ? program.thumbnail
    : '/default-course-thumbnail.jpg';
  const title = typeof program.title === 'string' && program.title.length > 0
    ? program.title
    : `Course ${index + 1}`;
  const description = typeof program.description === 'string' ? program.description : '';
  const difficulty = Number(program.difficulty ?? ProgramDifficulty.Beginner);
  const rating = typeof program.averageRating === 'number' ? program.averageRating : 0;
  const enrollmentStatus = Number(program.enrollmentStatus ?? EnrollmentStatus.Pending);
  const slug = typeof program.slug === 'string' && program.slug.length > 0
    ? program.slug
    : String(program.id ?? fallbackId);

  return {
    id: String(program.id ?? fallbackId),
    title,
    description,
    category: String(program.category ?? 'General'),
    level: (difficulty === ProgramDifficulty.Beginner
      ? 'Beginner'
      : difficulty === ProgramDifficulty.Intermediate
        ? 'Intermediate'
        : 'Advanced') as 'Beginner' | 'Intermediate' | 'Advanced',
    duration: Number(program.estimatedHours ?? 0),
    enrolledStudents: Number(program.currentEnrollments ?? 0),
    rating,
    price: 0,
    image: thumbnail,
    thumbnailUrl: thumbnail,
    coverUrl: thumbnail,
    slug,
    instructor: {
      name: 'Instructor',
      avatar: ''
    },
    isEnrolled: enrollmentStatus === EnrollmentStatus.Active,
    progress: 0,
    certification: false
  };
}

export function CourseGridEnhanced() {
  const { state, paginatedCourses } = useCourseContext();
  const transformedCourses = paginatedCourses.map((program, index) => transformProgramToCourse(program, index));
  return <CourseGrid courses={transformedCourses} loading={state.isLoading} />;
}

import { CourseCard } from './course-card';

interface CourseGridCourse {
  id: string;
  title: string;
  description: string;
  category: string;
  level: 'Beginner' | 'Intermediate' | 'Advanced';
  duration: number; // Changed from string to number to match CourseCardCourse
  enrolledStudents: number;
  rating: number;
  price: number;
  image: string;
  thumbnailUrl?: string;
  coverUrl?: string;
  slug: string;
  instructor: {
    name: string;
    avatar: string;
  };
  isEnrolled: boolean;
  progress: number;
  certification: boolean;
}

interface CourseGridProps {
  courses: CourseGridCourse[];
  variant?: 'default' | 'compact' | 'featured';
  columns?: 1 | 2 | 3 | 4;
  loading?: boolean;
}

export function CourseGrid({ courses, variant = 'default', columns = 3, loading = false }: CourseGridProps) {
  const gridClass = {
    1: 'grid-cols-1',
    2: 'grid-cols-1 lg:grid-cols-2',
    3: 'grid-cols-1 lg:grid-cols-2 xl:grid-cols-3',
    4: 'grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4',
  }[columns];

  if (loading) {
    return (
      <div className={`grid ${gridClass} gap-6`}>
        {Array.from({ length: 6 }).map((_, index) => (
          <div key={index} className="animate-pulse">
            <div className="bg-muted rounded-lg h-48 mb-4" />
            <div className="space-y-2">
              <div className="h-4 bg-muted rounded w-3/4" />
              <div className="h-3 bg-muted rounded w-1/2" />
              <div className="h-3 bg-muted rounded w-full" />
            </div>
          </div>
        ))}
      </div>
    );
  }

  if (courses.length === 0) {
    return (
      <div className="text-center py-12">
        <div className="mx-auto w-16 h-16 bg-muted rounded-full flex items-center justify-center mb-4">
          <span className="text-2xl">📚</span>
        </div>
        <h3 className="text-lg font-semibold mb-2">No courses found</h3>
        <p className="text-muted-foreground">Try adjusting your filters or search criteria.</p>
      </div>
    );
  }

  return (
    <div className={`grid ${gridClass} gap-6`}>
      {courses.map((course) => (
        <CourseCard key={course.id} course={course} />
      ))}
    </div>
  );
}

'use client';

import { cn } from "@game-guild/ui/lib/utils";
import { Badge } from '@game-guild/ui/components/badge';
import { Button, buttonVariants } from '@game-guild/ui/components/button';
import { Link } from '@/i18n/navigation';
import type { Program } from '@/lib/api/generated';
import { getCourseCategoryName, getCourseLevelConfig } from '@/lib/courses/services/course.service';
import { getCourseShowcase, getProgramForCourse } from '@/lib/courses/public-programs';
import { ArrowRight, ChevronLeft, ChevronRight } from 'lucide-react';
import Image from 'next/image';
import { useMemo, useState } from 'react';

interface CourseHighlightCarouselProps {
  readonly courses: Program[];
}

function getString(value: unknown): string | null {
  return typeof value === 'string' && value.trim().length > 0 ? value : null;
}

function getNumber(value: unknown): number | null {
  return typeof value === 'number' && Number.isFinite(value) ? value : null;
}

export function CourseHighlightCarousel({ courses }: CourseHighlightCarouselProps) {
  const highlights = useMemo(() => courses.slice(0, 5), [courses]);
  const [activeIndex, setActiveIndex] = useState(0);
  const activeCourse = highlights[activeIndex] ?? highlights[0];

  if (!activeCourse) {
    return null;
  }

  const title = getString(activeCourse.title) ?? 'GameGuild course';
  const slug = getString(activeCourse.slug);
  const description = getString(activeCourse.description) ?? 'Explore a GameGuild course landing page.';
  const image = getString(activeCourse.thumbnail) ?? 'https://images.unsplash.com/photo-1550745165-9bc0b252726f?w=1400&h=900&fit=crop';
  const level = getCourseLevelConfig(activeCourse.difficulty as string | number | null | undefined).name;
  const category = getCourseCategoryName(activeCourse.category as string | number | null | undefined);
  const hours = getNumber(activeCourse.estimatedHours);
  const program = getProgramForCourse(slug);
  const showcase = getCourseShowcase(slug);

  function move(delta: number) {
    setActiveIndex((current) => (current + delta + highlights.length) % highlights.length);
  }

  return (
    <div className="relative">
      <div className="absolute -inset-8 rounded-[3rem] bg-gradient-to-br from-sky-500/10 via-violet-500/10 to-transparent blur-3xl" />
      <section className="relative overflow-hidden rounded-[2rem] border border-white/10 bg-white/[0.055] shadow-2xl shadow-black/40 backdrop-blur">
        <div className="relative min-h-[520px]">
          <Image
            key={image}
            src={image}
            alt={title}
            fill
            unoptimized={image.endsWith('.svg')}
            className="object-cover transition duration-500"
            sizes="(min-width: 1024px) 48vw, 100vw"
            priority
          />
          <div className="absolute inset-0 bg-gradient-to-t from-[#070a12]/82 via-[#070a12]/10 to-transparent" />
          <div className="absolute inset-0 bg-gradient-to-r from-[#070a12]/30 via-transparent to-transparent" />

          <div className="absolute left-5 right-5 top-5 flex items-center justify-between gap-3">
            <div className="flex flex-wrap gap-2">
              <Badge variant="outline" className="border-white/20 bg-black/35 text-white backdrop-blur">
                {program?.shortTitle ?? category}
              </Badge>
              <Badge variant="outline" className="border-white/20 bg-black/35 text-white backdrop-blur">
                {level}
              </Badge>
              {hours ? (
                <Badge variant="outline" className="border-white/20 bg-black/35 text-white backdrop-blur">
                  {hours}h
                </Badge>
              ) : null}
            </div>

            <div className="flex gap-2">
              <Button type="button" size="icon" variant="outline" aria-label="Previous highlight" onClick={() => move(-1)} className="h-9 w-9 border-white/20 bg-black/30 text-white hover:bg-white/10 hover:text-white">
                <ChevronLeft />
              </Button>
              <Button type="button" size="icon" variant="outline" aria-label="Next highlight" onClick={() => move(1)} className="h-9 w-9 border-white/20 bg-black/30 text-white hover:bg-white/10 hover:text-white">
                <ChevronRight />
              </Button>
            </div>
          </div>

          <div className="absolute inset-x-0 bottom-0 flex flex-col gap-6 p-7">
            <div className="max-w-2xl">
              <h2 className="text-4xl font-semibold leading-tight tracking-tight md:text-5xl">{title}</h2>
              <p className="mt-4 line-clamp-3 text-sm leading-6 text-slate-300">
                {showcase?.headline ?? description}
              </p>
            </div>

            <div className="grid gap-3 sm:grid-cols-[1fr_auto] sm:items-end">
              <div className="flex gap-2">
                {highlights.map((course, index) => {
                  const courseTitle = getString(course.title) ?? `Course ${index + 1}`;

                  return (
                    <button
                      key={getString(course.slug) ?? String(course.id ?? index)}
                      type="button"
                      aria-label={`Show ${courseTitle}`}
                      aria-current={index === activeIndex}
                      onClick={() => setActiveIndex(index)}
                      className={`h-2.5 rounded-full transition-all ${index === activeIndex ? 'w-10 bg-white' : 'w-2.5 bg-white/35 hover:bg-white/60'}`}
                    />
                  );
                })}
              </div>

              <div className="flex flex-wrap gap-3">
                {slug ? (
                  <Link
                    href={`/courses/${slug}`}
                    className={cn(
                      buttonVariants({
                        className: "bg-white text-slate-950 hover:bg-slate-200",
                      }),
                    )}
                  >
                    Open course
                    <ArrowRight />
                  </Link>
                ) : null}
                {program ? (
                  <Link
                    href={`/programs/${program.slug}`}
                    className={cn(
                      buttonVariants({
                        variant: "outline",
                        className:
                          "border-white/15 bg-white/5 text-white hover:bg-white/10 hover:text-white",
                      }),
                    )}
                  >
                    View package
                  </Link>
                ) : null}
              </div>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
}

