'use client';

import type { CatalogCourse } from '@/lib/courses/catalog-types';
import type { Course } from '@/lib/courses/types';
import { useEffect, useMemo, useState } from 'react';
import CourseList from './course-list';

export default function CourseListWrapper({ courses }: { courses: CatalogCourse[] }) {
  // Ensure courses is an array and filter out invalid entries using useMemo to prevent re-renders
  const validCourses = useMemo(() =>
    Array.isArray(courses) ? courses.filter(course => course && course.id && course.area) : []
    , [courses]);

  // Transform legacy courses to new Course format
  const transformedCourses: Course[] = useMemo(() =>
    validCourses.map((legacyCourse: any) => ({
      id: String(legacyCourse.id),
      title: String(legacyCourse.title ?? 'Untitled course'),
      slug: String(legacyCourse.slug ?? legacyCourse.id),
      description: String(legacyCourse.description ?? ''),
      category: String(legacyCourse.area ?? 'General'),
      level: 'Beginner' as const,
      duration: '0h',
      enrolledStudents: 0,
      rating: 0,
      price: 0,
      image: String(legacyCourse.image ?? ''),
      instructor: {
        name: 'Instructor',
        avatar: '',
      },
      isEnrolled: false,
      progress: 0,
      certification: false,
    }))
    , [validCourses]);

  const categories = Array.from(new Set(validCourses.map((c) => c.area)));
  const [selectedCategory, setSelectedCategory] = useState<string>('All');
  const [filtered, setFiltered] = useState(transformedCourses);

  // Update filtered courses when transformedCourses changes
  useEffect(() => {
    setFiltered(selectedCategory === 'All' ? transformedCourses : transformedCourses.filter((c) => c.category === selectedCategory));
  }, [transformedCourses, selectedCategory]);

  function handleFilter(cat: string) {
    setSelectedCategory(cat);
    setFiltered(cat === 'All' ? transformedCourses : transformedCourses.filter((c) => c.category === cat));
  }

  return (
    <div>
      {/* Simple filter buttons */}
      <div className="flex gap-2 mb-6">
        <button onClick={() => handleFilter('All')} className={`px-3 py-1 rounded ${selectedCategory === 'All' ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground'}`}>
          All
        </button>
        {categories.map((cat) => (
          <button key={cat} onClick={() => handleFilter(cat)} className={`px-3 py-1 rounded ${selectedCategory === cat ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground'}`}>
            {cat}
          </button>
        ))}
      </div>
      <CourseList courses={filtered} />
    </div>
  );
}

'use client';

import { Badge } from '@game-guild/ui/components/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@game-guild/ui/components/select';
import { getTestingLocations } from '@/lib/api/testing-lab';
import type { TestingLocation as TestingLocationFull } from '@/lib/api/testing-types';
import { AlertCircle, CheckCircle, FolderOpen, MapPin, Users } from 'lucide-react';
import { useEffect, useState } from 'react';

interface CourseLocationSelectorProps {
  onLocationSelected: (location: TestingLocationFull, maxTests: number, maxProjects: number) => void;
}

export function CourseLocationSelector({ onLocationSelected }: CourseLocationSelectorProps) {
  const [locations, setLocations] = useState<TestingLocationFull[]>([]);
  const [selectedLocation, setSelectedLocation] = useState<TestingLocationFull | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isLoadingContent, setIsLoadingContent] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadLocations = async () => {
      try {
        setIsLoading(true);
        setError(null);
        const testingLocations = await getTestingLocations(0, 50);

        // Filter to active locations only and cast to full type with status property
        const activeLocations = testingLocations.filter((location: any) => location.status === 1) as TestingLocationFull[]; // Active status

        setLocations(activeLocations);
      } catch (err) {
        console.error('Failed to load testing locations:', err);
        setError('Failed to load testing locations');
      } finally {
        setIsLoading(false);
      }
    };

    loadLocations();
  }, []);

  const handleLocationChange = async (locationId: string) => {
    const location = locations.find((loc) => loc.id === locationId);
    if (!location) return;

    setSelectedLocation(location);
    setIsLoadingContent(true);

    try {
      // Location selection drives the maximum content loading
      const maxTests = location.maxTestersCapacity;
      const maxProjects = location.maxProjectsCapacity;

      // Notify parent component with location and capacity limits
      onLocationSelected(location, maxTests, maxProjects);
    } finally {
      setIsLoadingContent(false);
    }
  };

  const getLocationStatusColor = (status: number) => {
    switch (status) {
      case 1:
        return 'bg-green-500/20 text-green-400 border-green-500/30'; // Active
      case 2:
        return 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30'; // Maintenance
      default:
        return 'bg-gray-500/20 text-gray-400 border-gray-500/30'; // Inactive
    }
  };

  const getLocationStatusText = (status: number) => {
    switch (status) {
      case 1:
        return 'Active';
      case 2:
        return 'Maintenance';
      default:
        return 'Inactive';
    }
  };

  if (isLoading) {
    return (
      <Card className="bg-gray-900 border-gray-800">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <MapPin className="h-5 w-5" />
            Testing Location
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="animate-pulse">
            <div className="h-10 bg-gray-700 rounded mb-4"></div>
            <div className="h-4 bg-gray-700 rounded w-3/4"></div>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <Card className="bg-gray-900 border-gray-800">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <MapPin className="h-5 w-5" />
            Testing Location
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-2 text-red-400">
            <AlertCircle className="h-4 w-4" />
            <span className="text-sm">{error}</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="bg-gray-900 border-gray-800">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <MapPin className="h-5 w-5" />
          Select Testing Location
        </CardTitle>
        <p className="text-sm text-gray-400">Choose a testing location to determine maximum available tests and projects</p>
      </CardHeader>
      <CardContent className="space-y-4">
        <div>
          <Select onValueChange={(value: string | null) => value !== null && handleLocationChange(value)} disabled={isLoadingContent}>
            <SelectTrigger>
              <SelectValue placeholder="Choose a testing location..." />
            </SelectTrigger>
            <SelectContent>
              {locations.map((location) => (
                <SelectItem key={location.id} value={location.id || ''}>
                  <div className="flex items-center gap-2 w-full">
                    <span className="flex-1">{location.name}</span>
                    <Badge className={getLocationStatusColor(location.status)}>{getLocationStatusText(location.status)}</Badge>
                  </div>
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {selectedLocation && (
          <div className="space-y-4">
            <div className="p-4 bg-gray-800/50 rounded-lg border border-gray-700">
              <div className="flex items-start justify-between mb-3">
                <div>
                  <h4 className="font-medium text-white">{selectedLocation.name}</h4>
                  {selectedLocation.description && <p className="text-sm text-gray-400 mt-1">{selectedLocation.description}</p>}
                  {selectedLocation.address && <p className="text-xs text-gray-500 mt-1">{selectedLocation.address}</p>}
                </div>
                <Badge className={getLocationStatusColor(selectedLocation.status)}>{getLocationStatusText(selectedLocation.status)}</Badge>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="bg-blue-500/10 border border-blue-500/20 rounded-lg p-3">
                  <div className="flex items-center gap-2 text-blue-400">
                    <Users className="h-4 w-4" />
                    <span className="font-medium text-lg">{selectedLocation.maxTestersCapacity}</span>
                  </div>
                  <p className="text-xs text-blue-300 mt-1">Max Testers</p>
                </div>

                <div className="bg-green-500/10 border border-green-500/20 rounded-lg p-3">
                  <div className="flex items-center gap-2 text-green-400">
                    <FolderOpen className="h-4 w-4" />
                    <span className="font-medium text-lg">{selectedLocation.maxProjectsCapacity}</span>
                  </div>
                  <p className="text-xs text-green-300 mt-1">Max Projects</p>
                </div>
              </div>

              {selectedLocation.equipmentAvailable && (
                <div className="mt-3 pt-3 border-t border-gray-700">
                  <p className="text-xs text-gray-400">
                    <strong>Equipment:</strong> {selectedLocation.equipmentAvailable}
                  </p>
                </div>
              )}
            </div>

            <div className="flex items-center gap-2 text-green-400 text-sm">
              <CheckCircle className="h-4 w-4" />
              <span>
                Location selected. Content will be limited to {selectedLocation.maxTestersCapacity} tests and {selectedLocation.maxProjectsCapacity} projects.
              </span>
            </div>

            {isLoadingContent && (
              <div className="flex items-center gap-2 text-blue-400 text-sm">
                <div className="animate-spin h-4 w-4 border-2 border-blue-400 border-t-transparent rounded-full"></div>
                <span>Loading content based on location capacity...</span>
              </div>
            )}
          </div>
        )}

        {locations.length === 0 && (
          <div className="text-center py-4">
            <p className="text-sm text-gray-400">No active testing locations available</p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { cn } from "@game-guild/ui/lib/utils";
import { Badge } from "@game-guild/ui/components/badge";
import { Button, buttonVariants } from "@game-guild/ui/components/button";
import { Link } from "@/i18n/navigation";
import type { Program } from "@/lib/api/generated";
import type { Product } from "@/lib/courses/actions/enrollment.actions";
import { getLearnerCourseContentHref } from "@/lib/learner/paths";
import type { CourseViewerAccess } from "@/lib/courses/services/course-viewer-access";
import {
  getCourseCategoryName,
  getCourseLevelConfig,
} from "@/lib/courses/services/course.service";
import {
  getCourseShowcase,
  getProgramForCourse,
} from "@/lib/courses/public-programs";
import {
  ArrowLeft,
  ArrowRight,
  BookOpen,
  Clock,
  Layers3,
  Play,
  Users,
} from "lucide-react";
import Image from "next/image";
import { CourseCheckoutButton } from "./course-checkout-button";
import { shouldUseUnoptimizedCourseImage } from "./course-image";
import { CourseSelfEnrollButton } from "./course-self-enroll-button";

interface CourseHeaderProps {
  readonly course: Program;
  readonly viewerAccess?: CourseViewerAccess;
  readonly products?: Product[];
}

function getPrimaryCta(
  courseSlug: string | null,
  isEnrollmentOpen: boolean | null | undefined,
  hasProducts: boolean,
  viewerAccess?: CourseViewerAccess,
): {
  label: string;
  href?: string;
  kind: "link" | "checkout" | "enroll" | "disabled";
} {
  const signInHref = courseSlug
    ? `/sign-in?redirectTo=${encodeURIComponent(`/courses/${courseSlug}`)}`
    : "/sign-in";

  if (viewerAccess?.state === "has-access" && courseSlug) {
    return {
      label: "Continue learning",
      href: getLearnerCourseContentHref(courseSlug),
      kind: "link",
    };
  }

  if (viewerAccess?.state === "signed-out") {
    return { label: "Sign in to enroll", href: signInHref, kind: "link" };
  }

  if (
    viewerAccess?.state === "no-access" &&
    isEnrollmentOpen &&
    courseSlug &&
    hasProducts
  ) {
    return { label: "Checkout", kind: "checkout" };
  }

  if (viewerAccess?.state === "no-access" && isEnrollmentOpen && courseSlug) {
    return { label: "Enroll now", kind: "enroll" };
  }

  if (viewerAccess?.state === "unavailable") {
    return { label: "Access temporarily unavailable", kind: "disabled" };
  }

  return { label: "Sign in to enroll", href: signInHref, kind: "link" };
}

export function CourseHeader({
  course,
  viewerAccess,
  products = [],
}: CourseHeaderProps) {
  const thumbnailSrc =
    typeof course.thumbnail === "string" && course.thumbnail.length > 0
      ? course.thumbnail
      : null;
  const courseTitle =
    typeof course.title === "string" && course.title.length > 0
      ? course.title
      : "Course";
  const courseSlug =
    typeof course.slug === "string" && course.slug.length > 0
      ? course.slug
      : null;
  const courseDescription =
    typeof course.description === "string" ? course.description.trim() : "";
  const { name: levelName } = getCourseLevelConfig(
    course.difficulty as string | number | null | undefined,
  );
  const categoryName = getCourseCategoryName(
    course.category as string | number | null | undefined,
  );
  const program = getProgramForCourse(courseSlug);
  const showcase = getCourseShowcase(courseSlug);
  const heroImage = thumbnailSrc || program?.image;
  const isEnrollmentOpen = course.isEnrollmentOpen === true;
  const primaryCta = getPrimaryCta(
    courseSlug,
    isEnrollmentOpen,
    products.length > 0,
    viewerAccess,
  );

  return (
    <section className="relative min-h-[780px] overflow-hidden border-b border-white/10">
      <div className="pointer-events-none absolute inset-0">
