        <div className="absolute inset-0 bg-gradient-to-r from-[#070a12] via-[#070a12]/90 to-[#070a12]/38" />
        <div className="absolute inset-0 bg-gradient-to-t from-[#070a12] via-transparent to-[#070a12]/25" />
      </div>

      <div className="container relative z-10 mx-auto flex min-h-[780px] flex-col px-4 py-10">
        <Link
          href="/courses"
          className={cn(
            buttonVariants({
              variant: "ghost",
              className: "w-fit text-slate-300 hover:bg-white/10 hover:text-white",
            }),
          )}
        >
          <ArrowLeft />
          Back to catalog
        </Link>

        <div className="grid flex-1 gap-12 py-16 lg:grid-cols-[1fr_420px] lg:items-end">
          <div className="flex max-w-4xl flex-col gap-8">
            <div className="flex flex-wrap gap-2">
              <Badge
                variant="outline"
                className="border-white/20 bg-black/35 text-white backdrop-blur"
              >
                {categoryName}
              </Badge>
              <Badge
                variant="outline"
                className="border-white/20 bg-black/35 text-white backdrop-blur"
              >
                {levelName}
              </Badge>
              {program ? (
                <Badge
                  variant="outline"
                  className="border-white/20 bg-black/35 text-white backdrop-blur"
                >
                  {program.shortTitle} package
                </Badge>
              ) : null}
            </div>

            <div className="flex flex-col gap-6">
              <h1 className="text-5xl font-semibold leading-[0.98] tracking-tight md:text-7xl">
                {courseTitle}
              </h1>
              <p className="max-w-3xl text-lg leading-8 text-slate-300 md:text-xl">
                {courseDescription || showcase?.headline}
              </p>
            </div>

            <div className="flex flex-wrap gap-3">
              {primaryCta.kind === "checkout" && courseSlug ? (
                <CourseCheckoutButton
                  courseSlug={courseSlug}
                  products={products}
                  buttonClassName="h-10 px-6 text-sm font-medium md:h-11"
                />
              ) : primaryCta.kind === "enroll" && courseSlug ? (
                <CourseSelfEnrollButton
                  courseSlug={courseSlug}
                  buttonClassName="h-10 bg-white px-6 text-sm font-medium text-slate-950 hover:bg-slate-200 md:h-11"
                />
              ) : primaryCta.kind === "link" && primaryCta.href ? (
                <Link
                  href={primaryCta.href}
                  className={cn(
                    buttonVariants({
                      size: "lg",
                      className: "bg-white text-slate-950 hover:bg-slate-200",
                    }),
                  )}
                >
                  {primaryCta.label}
                  <ArrowRight />
                </Link>
              ) : (
                <Button size="lg" disabled className="bg-white/20 text-white">
                  {primaryCta.label}
                </Button>
              )}
              {course.videoShowcaseUrl ? (
                <Link
                  href={course.videoShowcaseUrl}
                  className={cn(
                    buttonVariants({
                      size: "lg",
                      variant: "outline",
                      className:
                        "border-white/15 bg-white/5 text-white hover:bg-white/10 hover:text-white",
                    }),
                  )}
                >
                  Watch preview
                  <Play />
                </Link>
              ) : null}
              <Link
                href="#curriculum"
                className={cn(
                  buttonVariants({
                    size: "lg",
                    variant: "outline",
                    className:
                      "border-white/15 bg-white/5 text-white hover:bg-white/10 hover:text-white",
                  }),
                )}
              >
                View curriculum
                <Layers3 />
              </Link>
            </div>
          </div>

          <aside className="rounded-[2rem] border border-white/10 bg-white/[0.055] p-6 shadow-2xl shadow-black/30 backdrop-blur">
            <div className="flex flex-col gap-5">
              <div>
