'use client';

import { useCoursesSync } from '@/lib/courses/context/course-management.context';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { Loader2, RefreshCw, BookOpen, Users, BarChart3, TrendingUp } from 'lucide-react';

export function CoursesOverviewContent() {
  const { state, getEnhancedCourses, syncWithServer } = useCoursesSync();

  const courses = getEnhancedCourses();

  // Calculate stats
  const totalCourses = courses.length;
  const coursesByArea = courses.reduce(
    (acc, course) => {
      acc[course.area] = (acc[course.area] || 0) + 1;
      return acc;
    },
    {} as Record<string, number>,
  );

  const coursesByLevel = courses.reduce(
    (acc, course) => {
      const levelName = course.level === 1 ? 'Beginner' : course.level === 2 ? 'Intermediate' : course.level === 3 ? 'Advanced' : 'Arcane';
      acc[levelName] = (acc[levelName] || 0) + 1;
      return acc;
    },
    {} as Record<string, number>,
  );

  const handleRefresh = async () => {
    await syncWithServer();
  };

  if (state.isLoading && courses.length === 0) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Sync Status */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <h2 className="text-xl font-semibold">Course Statistics</h2>
          {state.syncStatus === 'syncing' && <Loader2 className="h-4 w-4 animate-spin text-blue-500" />}
          {state.pendingChanges.size > 0 && (
            <Badge variant="outline" className="text-orange-600">
              {state.pendingChanges.size} pending changes
            </Badge>
          )}
        </div>

        <Button variant="outline" size="sm" onClick={handleRefresh}>
          <RefreshCw className="h-4 w-4 mr-2" />
          Refresh
        </Button>
      </div>

      {/* Overview Stats */}
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Courses</CardTitle>
            <BookOpen className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{totalCourses}</div>
            <p className="text-xs text-muted-foreground">Across all areas and levels</p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Most Popular Area</CardTitle>
            <TrendingUp className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold capitalize">{Object.entries(coursesByArea).sort(([, a], [, b]) => b - a)[0]?.[0] || 'N/A'}</div>
            <p className="text-xs text-muted-foreground">{Object.entries(coursesByArea).sort(([, a], [, b]) => b - a)[0]?.[1] || 0} courses</p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Sync Status</CardTitle>
            <BarChart3 className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold capitalize">{state.syncStatus}</div>
            <p className="text-xs text-muted-foreground">{state.lastSyncTime ? `Last: ${state.lastSyncTime.toLocaleTimeString()}` : 'Never synced'}</p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Pending Changes</CardTitle>
            <Users className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{state.pendingChanges.size}</div>
            <p className="text-xs text-muted-foreground">Waiting to sync</p>
          </CardContent>
        </Card>
      </div>

      {/* Courses by Area */}
      <Card>
        <CardHeader>
          <CardTitle>Courses by Area</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {Object.entries(coursesByArea).map(([area, count]) => (
              <div key={area} className="flex items-center justify-between">
                <span className="capitalize font-medium">{area}</span>
                <Badge variant="secondary">{count}</Badge>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Courses by Level */}
      <Card>
        <CardHeader>
          <CardTitle>Courses by Level</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {Object.entries(coursesByLevel).map(([level, count]) => (
              <div key={level} className="flex items-center justify-between">
                <span className="font-medium">{level}</span>
                <Badge variant="outline">{count}</Badge>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Recent Courses */}
      <Card>
        <CardHeader>
          <CardTitle>Recent Courses</CardTitle>
        </CardHeader>
        <CardContent>
          {courses.length === 0 ? (
            <p className="text-center text-muted-foreground py-4">No courses available</p>
          ) : (
            <div className="space-y-3">
              {courses.slice(0, 5).map((course) => (
                <div key={course.id} className="flex items-start gap-3 p-3 border rounded-lg">
                  {course.image && <img src={course.image} alt={course.title} className="h-12 w-12 rounded object-cover" />}
                  <div className="flex-1 min-w-0">
                    <h4 className="font-medium truncate">{course.title}</h4>
                    <p className="text-sm text-muted-foreground truncate">{course.description}</p>
                    <div className="flex gap-2 mt-2">
                      <Badge variant="outline" className="text-xs">
                        {course.area}
                      </Badge>
                      <Badge variant="secondary" className="text-xs">
                        Level {course.level}
                      </Badge>
                    </div>
                  </div>
                  {state.pendingChanges.has(course.id) && (
                    <Badge variant="outline" className="text-orange-600">
                      Pending
                    </Badge>
                  )}
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

'use server';

import { getToken } from '@/auth';
import {
  createServerClient,
  GeneratedApi,
  type LearningCoursesCreateProgram,
  type LearningCoursesProgram,
  type ProgramCategory,
  type LearningCoursesUpdateProgram,
} from '@game-guild/client';
import { revalidatePath } from 'next/cache';

import type { Course } from '@/lib/courses';
import { optionalPercentUnitsToPercentage, percentageToPercentUnits } from '@/lib/learning/academic-values';

interface EditorCourse extends Partial<Course> {
  id: string;
  title: string;
  slug: string;
  description: string;
  area?: string;
  level: 'Beginner' | 'Intermediate' | 'Advanced';
  difficulty?: number;
  thumbnail?: string;
  videoShowcaseUrl?: string;
  estimatedHours?: number;
  maxEnrollments?: number;
  enrollmentDeadline?: string;
  enrollmentStatus?: string;
  status?: string;
  tools?: string[];
  tags?: string[];
  instructors?: unknown[];
  isPublic?: boolean;
  isFeatured?: boolean;
  passingScore?: number;
  content?: unknown;
  createdAt?: string;
  updatedAt?: string;
}

const DEFAULT_API_URL = process.env.API_URL || process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8080';

function getApiClient() {
  return createServerClient({
    baseUrl: DEFAULT_API_URL.replace(/\/$/, ''),
    auth: { getAccessToken: () => getToken() },
  });
}

function createCourseModules() {
  const client = getApiClient();

  return {
    programs: new GeneratedApi.LearningCoursesProgramModule(client),
    lifecycle: new GeneratedApi.LearningCoursesProgramLifecycleModule(client),
  };
}

function normalizeSlug(slug: string): string {
  const normalizedSlug = slug.trim().toLowerCase();
  if (!normalizedSlug) {
    throw new Error('Empty slug provided');
  }

  return normalizedSlug;
}

function normalizeLevel(value: unknown): EditorCourse['level'] {
  if (value === 2 || value === '2') return 'Advanced';
  if (value === 1 || value === '1') return 'Intermediate';

  const text = typeof value === 'string' ? value.trim().toLowerCase() : '';
  if (text === 'advanced' || text === 'expert') return 'Advanced';
  if (text === 'intermediate') return 'Intermediate';
  return 'Beginner';
}

function toVisibility(isPublic: boolean | undefined, status: string | undefined): LearningCoursesUpdateProgram['visibility'] {
  if (isPublic === false) return 'Private';
  if (isPublic === true) return 'Public';
  return status?.toLowerCase() === 'published' ? 'Public' : undefined;
}

function joinList(values: string[] | undefined): string | undefined {
  return values && values.length > 0 ? values.join(', ') : undefined;
}

function toProgramCategory(value: string | undefined): ProgramCategory | undefined {
  const normalized = value?.replace(/[^a-zA-Z]/g, '').toLowerCase();
  switch (normalized) {
    case 'programming':
      return 'Programming';
    case 'datascience':
      return 'DataScience';
    case 'webdevelopment':
      return 'WebDevelopment';
    case 'mobiledevelopment':
      return 'MobileDevelopment';
    case 'gamedevelopment':
      return 'GameDevelopment';
    case 'ai':
      return 'AI';
    case 'cybersecurity':
      return 'Cybersecurity';
    case 'devops':
      return 'DevOps';
    case 'database':
      return 'Database';
    case 'business':
      return 'Business';
    case 'design':
      return 'Design';
    case 'marketing':
      return 'Marketing';
    case 'projectmanagement':
      return 'ProjectManagement';
    case 'personaldevelopment':
      return 'PersonalDevelopment';
    case 'creativearts':
      return 'CreativeArts';
    case 'science':
      return 'Science';
    case 'language':
      return 'Language';
    case 'other':
      return 'Other';
    default:
      return value ? 'General' : undefined;
  }
}

function toEnrollmentStatus(value: string | undefined): LearningCoursesUpdateProgram['enrollmentStatus'] {
  switch (value) {
    case 'closed':
      return 'Closed';
    case 'waitlist':
      return 'Waitlist';
    case 'invite-only':
      return 'InviteOnly';
    case 'open':
      return 'Open';
    default:
      return undefined;
  }
}

function toIsoDate(value: string | undefined): string | undefined {
  if (!value) return undefined;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? undefined : date.toISOString();
}

function mapCourse(program: LearningCoursesProgram): EditorCourse {
  const visibility = typeof program.visibility === 'string' ? program.visibility.toLowerCase() : '';

  return {
    id: program.id ?? '',
    title: program.title ?? '',
    slug: program.slug ?? '',
    description: program.description ?? '',
    area: typeof program.category === 'string' ? program.category : undefined,
    level: normalizeLevel(program.difficulty),
    status: typeof program.status === 'string' ? program.status : undefined,
    thumbnail: program.thumbnail ?? undefined,
    videoShowcaseUrl: program.videoShowcaseUrl ?? undefined,
    estimatedHours: program.estimatedHours ?? undefined,
    maxEnrollments: program.maxEnrollments ?? undefined,
    enrollmentDeadline: typeof program.enrollmentDeadline === 'string' ? program.enrollmentDeadline : undefined,
    enrollmentStatus: typeof program.enrollmentStatus === 'string' ? program.enrollmentStatus : undefined,
    isPublic: visibility === 'public',
    isFeatured: false,
    passingScore: optionalPercentUnitsToPercentage(program.passingScore) ?? undefined,
    tools: typeof program.skillsRequired === 'string'
      ? program.skillsRequired.split(',').map((tool) => tool.trim()).filter(Boolean)
      : [],
    tags: typeof program.skillsProvided === 'string'
      ? program.skillsProvided.split(',').map((tag) => tag.trim()).filter(Boolean)
      : [],
    instructors: [],
    createdAt: typeof program.createdAt === 'string' ? program.createdAt : undefined,
    updatedAt: typeof program.updatedAt === 'string' ? program.updatedAt : undefined,
    content: {
      chapters: [],
      syllabus: '',
      prerequisites: typeof program.skillsRequired === 'string' ? program.skillsRequired.split(',').map((item) => item.trim()).filter(Boolean) : [],
      objectives: typeof program.skillsProvided === 'string' ? program.skillsProvided.split(',').map((item) => item.trim()).filter(Boolean) : [],
      totalDuration: program.estimatedHours ? program.estimatedHours * 60 : 0,
      totalLessons: 0,
    },
  };
}

function toUpdateCourse(course: EditorCourse): LearningCoursesUpdateProgram {
  return {
    title: course.title.trim(),
    slug: course.slug.trim(),
    description: course.description.trim(),
    thumbnail: course.thumbnail?.trim() || undefined,
    videoShowcaseUrl: course.videoShowcaseUrl?.trim() || undefined,
    estimatedHours: course.estimatedHours,
    difficulty: course.level,
    category: toProgramCategory(course.area),
    visibility: toVisibility(course.isPublic, course.status),
    skillsProvided: joinList(course.tags),
    skillsRequired: joinList(course.tools),
    maxEnrollments: course.maxEnrollments,
    enrollmentDeadline: toIsoDate(course.enrollmentDeadline),
    enrollmentStatus: toEnrollmentStatus(course.enrollmentStatus),
    passingScore: course.passingScore == null ? undefined : percentageToPercentUnits(course.passingScore),
  };
}

export async function getCourseBySlug(slug: string): Promise<EditorCourse | null> {
  try {
    if (!slug) throw new Error('Invalid slug provided');

    const { programs } = createCourseModules();
    const result = await programs.getCoursesSlug(normalizeSlug(slug));

    return result.ok ? mapCourse(result.data) : null;
  } catch (error) {
    console.error('[getCourseBySlug] Error:', error);
    return null;
  }
}

export async function saveCourse(course: EditorCourse): Promise<boolean> {
  try {
    if (!course || typeof course !== 'object') throw new Error('Invalid course provided');
    if (!course.id) throw new Error('Course ID is required');

    const { programs } = createCourseModules();
    const result = await programs.putCourses(course.id, toUpdateCourse(course));

    if (!result.ok) return false;

    revalidatePath(`/workspace/learning/courses/${course.id}`);
    revalidatePath('/workspace/learning/courses');
    return true;
  } catch (error) {
    console.error('[saveCourse] Error:', error);
    return false;
  }
}

export async function autoSaveCourse(course: EditorCourse): Promise<boolean> {
  return saveCourse(course);
}

export async function createCourse(courseData: Partial<EditorCourse>): Promise<EditorCourse | null> {
  try {
    const title = courseData.title?.trim();
    const slug = courseData.slug?.trim();

    if (!title || title.length < 3) throw new Error('Title must be at least 3 characters');
    if (!slug) throw new Error('Slug is required');

    const body: LearningCoursesCreateProgram = {
      title,
      slug,
      description: courseData.description?.trim() ?? '',
      thumbnail: courseData.thumbnail?.trim() || undefined,
    };

    const { programs } = createCourseModules();
    const result = await programs.postCourses(body);

    if (!result.ok) return null;

    revalidatePath('/workspace/learning/courses');
    return mapCourse(result.data);
  } catch (error) {
    console.error('[createCourse] Error:', error);
    return null;
  }
}

export async function publishCourse(courseId: string): Promise<boolean> {
  try {
    if (!courseId) throw new Error('Course ID is required');

    const { lifecycle } = createCourseModules();
    const result = await lifecycle.postCoursesPublish(courseId);

    if (!result.ok) return false;

    revalidatePath(`/workspace/learning/courses/${courseId}`);
    revalidatePath('/workspace/learning/courses');
    return true;
  } catch (error) {
    console.error('[publishCourse] Error:', error);
    return false;
  }
}

'use client';

import React, { createContext, useContext, useMemo, useState } from 'react';

type CourseStatus = 'draft' | 'published' | 'archived';
type Visibility = 'public' | 'private' | 'premium';
type LessonType = 'text' | 'video' | 'quiz' | 'assignment' | 'file' | 'interactive';

interface CourseSession {
  id: string;
  title: string;
  startDate: string;
  endDate: string;
  capacity: number;
}

interface CourseProduct {
  id: string;
  name: string;
  price: number;
  currency: string;
  type: string;
}

interface CourseMediaAsset {
  url: string;
  alt?: string;
  file?: File;
  platform?: string;
  embedId?: string;
}

interface CourseLesson {
  id: string;
  title: string;
  description: string;
  type: LessonType;
  visibility: Visibility;
  status: CourseStatus;
  isRequired: boolean;
  duration: number;
  sortOrder: number;
}

interface CourseModule {
  id: string;
  title: string;
  description: string;
  visibility: Visibility;
  status: CourseStatus;
  sortOrder: number;
  estimatedDuration: number;
  isExpanded: boolean;
  lessons: CourseLesson[];
  submodules: CourseModule[];
}

interface CourseEditorState {
  title: string;
  slug: string;
  summary: string;
  description: string;
  category: string;
  difficulty: number;
  manualSlugEdit: boolean;
  status: CourseStatus;
  isValid: boolean;
  errors: Record<string, string>;
  media: {
    thumbnail?: CourseMediaAsset;
    showcaseVideo?: CourseMediaAsset;
  };
  products: CourseProduct[];
  enrollment: {
    isOpen: boolean;
    maxEnrollments?: number;
    currentEnrollments: number;
    deadline: string;
  };
  estimatedHours: number;
  tags: string[];
  content: {
    modules: CourseModule[];
    selectedItems: string[];
  };
  undoRedo: {
    canUndo: boolean;
    canRedo: boolean;
  };
  delivery: {
    mode: string;
    sessions: CourseSession[];
    timezone: string;
  };
  accessWindow: {
    start: string;
    end: string;
  };
  enrollmentWindow: {
    start: string;
    end: string;
  };
}

type ContentAction =
  | { type: 'ADD_MODULE'; module: Omit<CourseModule, 'id' | 'isExpanded'> & Partial<Pick<CourseModule, 'isExpanded'>> }
  | { type: 'REMOVE_MODULE'; moduleId: string }
  | { type: 'UPDATE_MODULE'; moduleId: string; updates: Partial<CourseModule> }
  | { type: 'TOGGLE_MODULE_EXPANDED'; moduleId: string }
  | { type: 'DUPLICATE_MODULE'; moduleId: string }
  | { type: 'ADD_LESSON'; moduleId: string; lesson: Omit<CourseLesson, 'id' | 'sortOrder'> & Partial<Pick<CourseLesson, 'sortOrder'>> }
  | { type: 'REMOVE_LESSON'; lessonId: string }
  | { type: 'UPDATE_LESSON'; lessonId: string; updates: Partial<CourseLesson> }
  | { type: 'DUPLICATE_LESSON'; lessonId: string }
  | { type: 'UNDO' }
  | { type: 'REDO' };

interface CourseEditorContextType {
  state: CourseEditorState;
  updateTitle: (title: string) => void;
  updateSlug: (slug: string) => void;
  updateSummary: (summary: string) => void;
  updateDescription: (description: string) => void;
  updateCategory: (category: string) => void;
  updateDifficulty: (difficulty: number) => void;
  setThumbnail: (asset?: CourseMediaAsset) => void;
  setShowcaseVideo: (asset?: CourseMediaAsset) => void;
  addProduct: (product: CourseProduct) => void;
  removeProduct: (productId: string) => void;
  updateProduct: (productId: string, updates: Partial<CourseProduct>) => void;
  setEnrollmentStatus: (isOpen: boolean) => void;
  setMaxEnrollments: (maxEnrollments?: number) => void;
  setEnrollmentDeadline: (deadline: string) => void;
  setEstimatedHours: (hours: number) => void;
  addTag: (tag: string) => void;
  removeTag: (tag: string) => void;
  setStatus: (status: CourseStatus) => void;
  dispatch: (action: ContentAction) => void;
  setDeliveryMode: (mode: string) => void;
  setAccessWindow: (window: { start: string; end: string }) => void;
  setEnrollmentWindow: (window: { start: string; end: string }) => void;
  addSession: (session: Omit<CourseSession, 'id'>) => void;
  removeSession: (sessionId: string) => void;
  setTimezone: (timezone: string) => void;
  validate: () => { isValid: boolean; errors: string[] };
}

const CourseEditorContext = createContext<CourseEditorContextType | undefined>(undefined);

function createId(prefix: string) {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) {
    return `${prefix}-${crypto.randomUUID()}`;
  }

  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function slugify(value: string) {
  return value
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

const initialState: CourseEditorState = {
  title: '',
  slug: '',
  summary: '',
  description: '',
  category: '',
  difficulty: 1,
  manualSlugEdit: false,
  status: 'draft',
  isValid: true,
  errors: {},
  media: {},
  products: [],
  enrollment: {
    isOpen: false,
    currentEnrollments: 0,
    deadline: '',
  },
  estimatedHours: 1,
  tags: [],
  content: {
    modules: [],
    selectedItems: [],
  },
  undoRedo: {
    canUndo: false,
    canRedo: false,
  },
  delivery: {
    mode: 'self-paced',
    sessions: [],
    timezone: 'UTC',
  },
  accessWindow: {
    start: '',
    end: '',
  },
  enrollmentWindow: {
    start: '',
    end: '',
  },
};

function applyContentAction(state: CourseEditorState, action: ContentAction): CourseEditorState {
  switch (action.type) {
    case 'ADD_MODULE': {
      const newModule: CourseModule = {
        id: createId('module'),
        title: action.module.title,
        description: action.module.description,
        visibility: action.module.visibility,
        status: action.module.status,
        sortOrder: action.module.sortOrder,
        estimatedDuration: action.module.estimatedDuration,
        isExpanded: action.module.isExpanded ?? true,
        lessons: action.module.lessons ?? [],
        submodules: action.module.submodules ?? [],
      };

      return {
        ...state,
        content: {
          ...state.content,
          modules: [...state.content.modules, newModule],
        },
        undoRedo: { ...state.undoRedo, canUndo: true },
      };
    }

    case 'REMOVE_MODULE':
      return {
        ...state,
        content: {
          ...state.content,
          modules: state.content.modules.filter((module) => module.id !== action.moduleId),
        },
        undoRedo: { ...state.undoRedo, canUndo: true },
      };

    case 'UPDATE_MODULE':
      return {
        ...state,
        content: {
          ...state.content,
          modules: state.content.modules.map((module) =>
            module.id === action.moduleId ? { ...module, ...action.updates } : module,
          ),
        },
        undoRedo: { ...state.undoRedo, canUndo: true },
      };

    case 'TOGGLE_MODULE_EXPANDED':
      return {
        ...state,
        content: {
          ...state.content,
          modules: state.content.modules.map((module) =>
            module.id === action.moduleId ? { ...module, isExpanded: !module.isExpanded } : module,
          ),
        },
      };

    case 'DUPLICATE_MODULE': {
      const module = state.content.modules.find((item) => item.id === action.moduleId);
      if (!module) return state;

      return {
        ...state,
        content: {
          ...state.content,
          modules: [
            ...state.content.modules,
            {
              ...module,
              id: createId('module'),
              title: `${module.title} copy`,
              lessons: module.lessons.map((lesson) => ({ ...lesson, id: createId('lesson') })),
            },
          ],
        },
        undoRedo: { ...state.undoRedo, canUndo: true },
      };
    }

    case 'ADD_LESSON':
      return {
        ...state,
        content: {
          ...state.content,
          modules: state.content.modules.map((module) => {
            if (module.id !== action.moduleId) return module;

            const lesson: CourseLesson = {
              id: createId('lesson'),
              title: action.lesson.title,
              description: action.lesson.description,
              type: action.lesson.type,
              visibility: action.lesson.visibility,
              status: action.lesson.status,
              isRequired: action.lesson.isRequired,
              duration: action.lesson.duration,
              sortOrder: action.lesson.sortOrder ?? module.lessons.length,
            };

            return { ...module, isExpanded: true, lessons: [...module.lessons, lesson] };
          }),
        },
        undoRedo: { ...state.undoRedo, canUndo: true },
      };

    case 'REMOVE_LESSON':
      return {
        ...state,
        content: {
          ...state.content,
          modules: state.content.modules.map((module) => ({
            ...module,
            lessons: module.lessons.filter((lesson) => lesson.id !== action.lessonId),
          })),
        },
        undoRedo: { ...state.undoRedo, canUndo: true },
      };

    case 'UPDATE_LESSON':
      return {
        ...state,
        content: {
          ...state.content,
          modules: state.content.modules.map((module) => ({
            ...module,
            lessons: module.lessons.map((lesson) =>
              lesson.id === action.lessonId ? { ...lesson, ...action.updates } : lesson,
            ),
          })),
        },
        undoRedo: { ...state.undoRedo, canUndo: true },
      };

    case 'DUPLICATE_LESSON':
      return {
        ...state,
        content: {
          ...state.content,
          modules: state.content.modules.map((module) => {
            const lesson = module.lessons.find((item) => item.id === action.lessonId);
            if (!lesson) return module;

            return {
              ...module,
              lessons: [...module.lessons, { ...lesson, id: createId('lesson'), title: `${lesson.title} copy` }],
            };
          }),
        },
        undoRedo: { ...state.undoRedo, canUndo: true },
      };

    case 'UNDO':
    case 'REDO':
    default:
      return state;
  }
}

export function CourseEditorProvider({ children }: { children: React.ReactNode }) {
  const [state, setState] = useState<CourseEditorState>(initialState);

  const value = useMemo<CourseEditorContextType>(
    () => ({
      state,
      updateTitle: (title) =>
        setState((prev) => ({
          ...prev,
          title,
          slug: prev.manualSlugEdit ? prev.slug : slugify(title),
        })),
      updateSlug: (slug) => setState((prev) => ({ ...prev, slug: slugify(slug), manualSlugEdit: true })),
      updateSummary: (summary) => setState((prev) => ({ ...prev, summary: summary.slice(0, 200) })),
      updateDescription: (description) => setState((prev) => ({ ...prev, description })),
      updateCategory: (category) => setState((prev) => ({ ...prev, category })),
      updateDifficulty: (difficulty) => setState((prev) => ({ ...prev, difficulty })),
      setThumbnail: (asset) => setState((prev) => ({ ...prev, media: { ...prev.media, thumbnail: asset } })),
      setShowcaseVideo: (asset) => setState((prev) => ({ ...prev, media: { ...prev.media, showcaseVideo: asset } })),
      addProduct: (product) => setState((prev) => ({ ...prev, products: [...prev.products, product] })),
      removeProduct: (productId) =>
        setState((prev) => ({ ...prev, products: prev.products.filter((product) => product.id !== productId) })),
      updateProduct: (productId, updates) =>
        setState((prev) => ({
          ...prev,
          products: prev.products.map((product) => (product.id === productId ? { ...product, ...updates } : product)),
        })),
      setEnrollmentStatus: (isOpen) =>
        setState((prev) => ({ ...prev, enrollment: { ...prev.enrollment, isOpen } })),
      setMaxEnrollments: (maxEnrollments) =>
        setState((prev) => ({ ...prev, enrollment: { ...prev.enrollment, maxEnrollments } })),
      setEnrollmentDeadline: (deadline) =>
        setState((prev) => ({ ...prev, enrollment: { ...prev.enrollment, deadline } })),
      setEstimatedHours: (hours) => setState((prev) => ({ ...prev, estimatedHours: Math.max(1, hours) })),
      addTag: (tag) =>
        setState((prev) => {
          const normalized = tag.trim();
          if (!normalized || prev.tags.includes(normalized)) return prev;
          return { ...prev, tags: [...prev.tags, normalized] };
        }),
      removeTag: (tag) => setState((prev) => ({ ...prev, tags: prev.tags.filter((item) => item !== tag) })),
      setStatus: (status) => setState((prev) => ({ ...prev, status })),
      dispatch: (action) => setState((prev) => applyContentAction(prev, action)),
      setDeliveryMode: (mode) =>
        setState((prev) => ({
          ...prev,
          delivery: { ...prev.delivery, mode },
        })),
      setAccessWindow: (window) => setState((prev) => ({ ...prev, accessWindow: window })),
      setEnrollmentWindow: (window) => setState((prev) => ({ ...prev, enrollmentWindow: window })),
      addSession: (sessionData) =>
        setState((prev) => ({
          ...prev,
          delivery: {
            ...prev.delivery,
            sessions: [...prev.delivery.sessions, { ...sessionData, id: createId('session') }],
          },
        })),
      removeSession: (sessionId) =>
        setState((prev) => ({
          ...prev,
          delivery: {
            ...prev.delivery,
            sessions: prev.delivery.sessions.filter((session) => session.id !== sessionId),
          },
        })),
      setTimezone: (timezone) =>
        setState((prev) => ({
          ...prev,
          delivery: { ...prev.delivery, timezone },
        })),
      validate: () => {
        const errors: Record<string, string> = {};
        if (!state.title.trim()) errors.title = 'Course title is required';
        if (!state.slug.trim()) errors.slug = 'Course slug is required';
        if (!state.summary.trim()) errors.summary = 'Course summary is required';
        if (!state.category.trim()) errors.category = 'Course category is required';

        const isValid = Object.keys(errors).length === 0;
        setState((prev) => ({ ...prev, isValid, errors }));

        return { isValid, errors: Object.values(errors) };
      },
    }),
    [state],
  );

  return <CourseEditorContext.Provider value={value}>{children}</CourseEditorContext.Provider>;
}

export function useCourseEditor() {
  const context = useContext(CourseEditorContext);
  if (context === undefined) {
    throw new Error('useCourseEditor must be used within a CourseEditorProvider');
  }
  return context;
}

