export function CourseEditorSidebar() {
  const pathname = usePathname();
  const params = useParams();
  const courseParam = params.course ?? params.slug;
  const courseId = Array.isArray(courseParam) ? (courseParam[0] ?? '') : (courseParam ?? '');
  const coursesDashboardHref = '/workspace/learning/courses' as Route;
  const { state, validate } = useCourseEditor();
  const [isSaving, setIsSaving] = useState(false);
  const [saveMessage, setSaveMessage] = useState<string | null>(null);

  // Initialize collapsed state based on defaultOpen
  const [collapsedGroups, setCollapsedGroups] = useState<Record<string, boolean>>(() => {
    const initial: Record<string, boolean> = {};
    COURSE_SECTION_GROUPS.forEach((group) => {
      initial[group.label] = !group.defaultOpen;
    });
    return initial;
  });

  const basePath = `/workspace/learning/courses/${courseId}`;

  const toggleGroup = (groupLabel: string) => {
    setCollapsedGroups((prev) => ({
      ...prev,
      [groupLabel]: !prev[groupLabel],
    }));
  };

  const renderSection = (section: typeof OVERVIEW_SECTION) => {
    const sectionHref = `${basePath}${section.path}` as Route;
    const isActive = pathname === sectionHref || (section.path === '' && pathname === basePath);

    return (
      <SidebarMenuItem key={section.id}>
        <SidebarMenuButton render={<Link href={sectionHref}
            className={cn(
              'flex items-center gap-3 p-3 rounded-lg transition-all duration-200 group border backdrop-blur-md',
              isActive
                ? 'bg-gradient-to-r from-blue-600/20 to-purple-600/20 text-white border-blue-500/30 shadow-lg shadow-blue-500/10'
                : 'bg-slate-800/30 text-slate-300 border-slate-700/30 hover:bg-slate-700/40 hover:text-white hover:border-slate-600/40',
            )} />}>
          <div className={cn('p-2 rounded-lg transition-all duration-200', isActive ? 'bg-gradient-to-r from-blue-600 to-purple-600 shadow-lg' : 'bg-slate-700/50 group-hover:bg-slate-600/50')}>
            <section.icon className="h-4 w-4 text-white" />
          </div>
          <div className="flex-1 min-w-0">
            <div className="font-medium text-sm truncate">{section.label}</div>
            <div className={cn('text-xs truncate transition-colors duration-200', isActive ? 'text-blue-200' : 'text-slate-400 group-hover:text-slate-300')}>{section.description}</div>
          </div>
          {isActive && <div className="w-2 h-2 bg-blue-400 rounded-full animate-pulse flex-shrink-0" />}
        </SidebarMenuButton>
      </SidebarMenuItem>
    );
  };

  const handleSave = async () => {
    const validation = validate();
    setSaveMessage(null);

    if (!validation.isValid) {
      return;
    }

    try {
      setIsSaving(true);
      const level: 'Beginner' | 'Intermediate' | 'Advanced' = state.difficulty >= 3 ? 'Advanced' : state.difficulty === 2 ? 'Intermediate' : 'Beginner';
      const saved = await saveCourse({
        id: courseId || state.slug,
        title: state.title,
        slug: state.slug,
        description: state.description || state.summary,
        area: state.category,
        level,
        status: state.status,
        tags: state.tags,
        tools: [],
        isPublic: state.status === 'published',
      });

      setSaveMessage(saved ? 'Course saved.' : 'Course could not be saved.');
    } catch (error) {
      console.error('Failed to save course:', error);
      setSaveMessage('Course could not be saved.');
    } finally {
      setIsSaving(false);
    }
  };

  const handlePreview = () => {
    const previewSlug = state.slug || courseId;
    if (previewSlug) {
      window.open(`/courses/${previewSlug}`, '_blank', 'noopener,noreferrer');
    }
  };

  return (
    <Sidebar collapsible="none" className="border-r border-slate-700/50">
      <SidebarHeader className="border-b border-slate-700/50 bg-gradient-to-b from-slate-900/95 via-slate-900/90 to-slate-800/95 backdrop-blur-xl">
        <div className="p-4">
          <Link href={coursesDashboardHref}>
            <Button variant="ghost" size="sm" className="mb-4 bg-slate-900/30 backdrop-blur-md border border-slate-700/50 text-slate-200 hover:text-white hover:bg-slate-800/40 hover:border-slate-600/50 transition-all duration-200">
              <ArrowLeft className="h-4 w-4 mr-2" />
              Back to Courses
            </Button>
          </Link>

          <div className="space-y-3">
            <h2 className="font-semibold text-xl bg-gradient-to-r from-blue-400 to-purple-400 bg-clip-text text-transparent truncate">{state.title || 'Untitled Course'}</h2>
            {state.slug && <p className="text-sm text-slate-400 truncate font-mono bg-slate-800/30 px-2 py-1 rounded border border-slate-700/30">/{state.slug}</p>}
          </div>

          {/* Status Badge */}
          <div className="mt-4">
            <div
              className={cn(
                'px-4 py-2 rounded-full text-sm font-medium inline-flex items-center gap-2 backdrop-blur-md border',
                state.status === 'published' ? 'bg-green-900/30 text-green-400 border-green-700/50' : state.status === 'draft' ? 'bg-amber-900/30 text-amber-400 border-amber-700/50' : 'bg-slate-900/30 text-slate-400 border-slate-700/50',
              )}
            >
              <div className={cn('w-2 h-2 rounded-full', state.status === 'published' ? 'bg-green-400' : state.status === 'draft' ? 'bg-amber-400 animate-pulse' : 'bg-slate-400')} />
              {state.status.charAt(0).toUpperCase() + state.status.slice(1)}
            </div>
          </div>
        </div>
      </SidebarHeader>

      <SidebarContent className="bg-gradient-to-b from-slate-900/95 via-slate-900/90 to-slate-800/95 backdrop-blur-xl p-4">
        {/* Overview Section - Always visible */}
        <div className="mb-6">
          <SidebarMenu className="space-y-1">{renderSection(OVERVIEW_SECTION)}</SidebarMenu>
        </div>

        {/* Collapsible Groups */}
        {COURSE_SECTION_GROUPS.map((group) => (
          <div key={group.label} className="mb-6">
            <div
              className="px-3 py-2 cursor-pointer hover:bg-slate-800/30 rounded-lg transition-all duration-200 flex items-center justify-between group border border-transparent hover:border-slate-700/30"
              onClick={() => toggleGroup(group.label)}
            >
              <span className="text-sm font-semibold bg-gradient-to-r from-slate-300 to-slate-400 bg-clip-text text-transparent group-hover:from-blue-300 group-hover:to-purple-300 transition-all duration-200">{group.label}</span>
              <div className="text-slate-400 group-hover:text-slate-300 transition-colors duration-200">{collapsedGroups[group.label] ? <ChevronRight className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}</div>
            </div>

            {!collapsedGroups[group.label] && (
              <div className="mt-2 space-y-1 border-l-2 border-gradient-to-b border-slate-700/30 ml-3 pl-3">
                <SidebarMenu className="space-y-1">{group.sections.map((section) => renderSection(section))}</SidebarMenu>
              </div>
            )}
          </div>
        ))}

        {/* Validation Errors */}
        {Object.keys(state.errors).length > 0 && (
          <div className="mt-6 p-4 bg-gradient-to-r from-red-900/30 to-rose-900/30 backdrop-blur-md border border-red-700/50 rounded-lg">
            <h4 className="font-semibold text-sm text-red-300 mb-3 flex items-center gap-2">
              <div className="w-2 h-2 bg-red-400 rounded-full animate-pulse" />
              Validation Errors
            </h4>
            <ul className="space-y-2 text-sm text-red-200">
              {Object.entries(state.errors)
                .slice(0, 3)
                .map(([field, error]) => (
                  <li key={field} className="flex items-start gap-2">
                    <div className="w-1 h-1 bg-red-400 rounded-full mt-2 flex-shrink-0" />
                    <span className="truncate">{error}</span>
                  </li>
                ))}
              {Object.keys(state.errors).length > 3 && <li className="text-red-300 font-medium text-xs">+{Object.keys(state.errors).length - 3} more errors</li>}
            </ul>
          </div>
        )}
      </SidebarContent>

      <SidebarFooter className="border-t border-slate-700/50 bg-gradient-to-b from-slate-900/95 via-slate-900/90 to-slate-800/95 backdrop-blur-xl p-4">
        <div className="space-y-3">
          {saveMessage && (
            <div role="status" className="rounded-lg border border-slate-700/50 bg-slate-800/40 px-3 py-2 text-xs text-slate-200">
              {saveMessage}
            </div>
          )}

          {/* Save Button */}
          <Button
            onClick={handleSave}
            disabled={isSaving}
            className="w-full bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 text-white border-0 shadow-lg shadow-blue-500/20 hover:shadow-blue-500/30 transition-all duration-200 h-10"
            size="sm"
          >
            <Save className="h-4 w-4 mr-2" />
            {isSaving ? 'Saving...' : 'Save Changes'}
          </Button>

          {/* Preview Button */}
          <Button
            variant="outline"
            onClick={handlePreview}
            disabled={!state.slug}
            className="w-full bg-slate-800/30 backdrop-blur-md border border-slate-700/50 text-slate-200 hover:text-white hover:bg-slate-700/40 hover:border-slate-600/50 transition-all duration-200"
            size="sm"
          >
            <Eye className="h-4 w-4 mr-2" />
            Preview
          </Button>
        </div>
      </SidebarFooter>
    </Sidebar>
  );
}

'use client';

import { Button } from '@game-guild/ui/components/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@game-guild/ui/components/input';
import { Label } from '@game-guild/ui/components/label';
import { Textarea } from '@game-guild/ui/components/textarea';
import { createCourse } from '@/lib/learning/actions';
import { getCourseRouteParam } from '@/lib/learning/course-route';
import { useRouter } from '@/i18n/navigation';
import { AlertCircle, ArrowLeft, Loader2, Save } from 'lucide-react';
import React, { useState } from 'react';
import speakingurl from 'speakingurl';

interface CreateCourseFormData {
  title: string;
  description: string;
  slug: string;
}

export const CreateCourseForm = (): React.JSX.Element => {
  const router = useRouter();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formData, setFormData] = useState<CreateCourseFormData>({
    title: '',
    description: '',
    slug: '',
  });
  const [error, setError] = useState<string | null>(null);

  const handleInputChange = (field: keyof CreateCourseFormData, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear error when user starts typing
    if (error) setError(null);
  };

  const handleTitleChange = (value: string) => {
    handleInputChange('title', value);
    // Auto-generate slug from title
    const slug = speakingurl(value);
    setFormData(prev => ({ ...prev, slug }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError(null);

    try {
      // Validate form data
      if (!formData.title.trim()) {
        throw new Error('Title is required');
      }
      if (!formData.description.trim()) {
        throw new Error('Description is required');
      }
      if (!formData.slug.trim()) {
        throw new Error('Slug is required');
      }

      const result = await createCourse({
        title: formData.title.trim(),
        description: formData.description.trim(),
        slug: formData.slug.trim(),
      });

      if (!result.success) {
        console.error('Error from API:', result.error);
        throw new Error(result.error);
      }

      const courseRouteParam = result.data.routeParam || getCourseRouteParam(result.data);
      router.push(`/workspace/learning/courses/${courseRouteParam}` as Parameters<typeof router.push>[0]);
    } catch (err) {
      console.error('Error creating course:', err);

      // Handle different types of errors
      if (err instanceof Error) {
        // Check for specific error patterns that need special handling
        if (err.message.includes('Authentication required') || err.message.includes('no access token') || err.message.includes('401')) {
          setError('Please sign in to create a course. Redirecting to sign-in page...');
          setTimeout(() => {
            router.push('/sign-in');
          }, 2000);
        } else if (err.message.includes('fetch failed') || err.message.includes('ECONNREFUSED') || err.message.includes('connection')) {
          setError('Unable to connect to the server. Please ensure the API server is running and try again.');
        } else if (err.message.includes('Failed to create course - no data returned from server')) {
          setError('The course creation request completed, but no response was received. Please check if the course was created successfully.');
        } else {
          // Use the specific error message from the API
          setError(err.message);
        }
      } else {
        setError('An unexpected error occurred while creating the course. Please try again.');
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto p-6">
      <Card className="shadow-lg border-0">
        <CardHeader>
          <div className="flex items-center gap-4">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => router.back()}
              className="flex items-center gap-2"
            >
              <ArrowLeft className="h-4 w-4" />
              Back
            </Button>
            <CardTitle className="text-2xl font-bold">Create New Course</CardTitle>
          </div>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-6">
            {error && (
              <div className="bg-destructive/10 border border-destructive/20 rounded-lg p-4">
                <div className="flex items-start gap-3">
                  <AlertCircle className="h-5 w-5 text-destructive mt-0.5 flex-shrink-0" />
                  <div>
                    <p className="text-destructive font-medium">Error</p>
                    <p className="text-destructive/80 text-sm mt-1">{error}</p>
                  </div>
                </div>
              </div>
            )}

            <div className="space-y-4">
              <div>
                <Label htmlFor="title" className="text-sm font-medium">
                  Course Title *
                </Label>
                <Input
                  id="title"
                  type="text"
                  value={formData.title}
                  onChange={(e) => handleTitleChange(e.target.value)}
                  placeholder="Enter course title"
                  required
                  className="mt-1 !border-border focus:!border-ring focus:!ring-ring/50"
                />
              </div>

              <div>
                <Label htmlFor="description" className="text-sm font-medium">
                  Description *
                </Label>
                <Textarea
                  id="description"
                  value={formData.description}
                  onChange={(e) => handleInputChange('description', e.target.value)}
                  placeholder="Enter course description"
                  rows={4}
                  required
                  className="mt-1 border-0 !border-border focus:!border-ring focus:!ring-ring/50 resize-none overflow-hidden [&_.grammarly-desktop-integration]:!hidden [&_.grammarly-extension]:!hidden [&_.grammarly-extension__editing-area]:!border-none [&_.grammarly-extension__editing-area]:!outline-none [&_.grammarly-extension__editing-area]:!resize-none [&_.grammarly-extension__editing-area]:!overflow-hidden"
                />
              </div>

              <div>
                <Label htmlFor="slug" className="text-sm font-medium">
                  URL Slug *
                </Label>
                <Input
                  id="slug"
                  type="text"
                  value={formData.slug}
                  onChange={(e) => handleInputChange('slug', e.target.value)}
                  placeholder="course-url-slug"
                  required
                  className="mt-1 !border-border focus:!border-ring focus:!ring-ring/50"
                />
                <p className="text-xs text-muted-foreground mt-1">
                  This will be used in the course URL. Use only lowercase letters, numbers, and hyphens.
                </p>
              </div>
            </div>

            <div className="flex gap-4 pt-4">
              <Button
                type="button"
                variant="outline"
                onClick={() => router.back()}
                disabled={isSubmitting}
                className="flex-1"
              >
                Cancel
              </Button>
              <Button
                type="submit"
                disabled={isSubmitting || !formData.title.trim() || !formData.description.trim() || !formData.slug.trim()}
                className="flex-1"
              >
                {isSubmitting ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Creating...
                  </>
                ) : (
                  <>
                    <Save className="mr-2 h-4 w-4" />
                    Create Course
                  </>
                )}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
};

'use client';

import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@game-guild/ui/components/input';
import { Label } from '@game-guild/ui/components/label';
import { Textarea } from '@game-guild/ui/components/textarea';
import {
  createEmptyQuizAnswer,
  evaluateQuizAnswer,
  type QuizAnswer,
  type QuizLearnerEntry,
  type QuizPracticeEntry,
} from '@game-guild/quiz';
import type {
  AssessmentSubmissionRuntimeViewV1,
  SelfReviewEvidenceV1,
} from '@game-guild/grading';
import {
  createQuizAnswerEnvelope,
  parseQuizAnswerEnvelope,
  QUIZ_ASSESSMENT_TYPE_ADAPTER,
  type QuizLearnerDeliveryItemV1,
} from '@game-guild/grading-adapter-quiz';
import { isQuizRuntimeContentDocument } from '@game-guild/quiz-content';
import {
  QuizPlayer,
  QuizPracticePlayer,
  type QuizSubmissionResult,
} from '@game-guild/quiz-surface/player';
import { submitActivity } from '@/lib/courses/server-actions';
import {
  getRuntimeSubmission,
  saveCollectiveRuntimeSelfReviewDraft,
  startContentRuntimeSubmission,
  submitRuntimeSubmission,
  submitRuntimeSelfReview,
} from '@/lib/learning/grading-runtime-actions';
import { SelfReviewForm } from '@/components/learning/grading/self-review-form';
import { Clock, Code, FileText, MessageSquare, Play, Save, Send, Upload } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';

interface ContentItem {
  id: string;
  title: string;
  type: 'lesson' | 'activity' | 'quiz' | 'assignment' | 'peer-review';
  status: 'locked' | 'available' | 'in-progress' | 'completed';
  duration?: number;
  description?: string;
  order: number;
  isRequired: boolean;
  activityType?: 'text' | 'code' | 'file' | 'quiz' | 'discussion';
  content?: unknown;
  progress?: number;
}

interface ActivityComponentProps {
  item: ContentItem;
  courseId?: string;
  existingSubmissionId?: string | null;
  onComplete: (score?: number) => void;
}

interface QuizActivityQuestion<Entry> {
  id: string;
  data: Entry;
}

type QuizActivityContent =
  | {
      questions: Array<QuizActivityQuestion<QuizLearnerEntry>>;
      serverGraded: true;
    }
  | {
      questions: Array<QuizActivityQuestion<QuizPracticeEntry>>;
      serverGraded: false;
    };

export function ActivityComponent({
  item,
  courseId,
  existingSubmissionId,
  onComplete,
}: ActivityComponentProps) {
  const [hasStarted, setHasStarted] = useState(false);
  const [isStarting, setIsStarting] = useState(Boolean(existingSubmissionId));
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [runtimeError, setRuntimeError] = useState<string | null>(null);
  const [runtimeSubmission, setRuntimeSubmission] = useState<
    AssessmentSubmissionRuntimeViewV1<QuizLearnerDeliveryItemV1> | null
  >(null);
  const [submission, setSubmission] = useState<Record<string, unknown>>({});
  const [currentStep, setCurrentStep] = useState(0);
  const [quizAnswers, setQuizAnswers] = useState<Record<string, QuizAnswer>>({});
  const [quizSubmissionResults, setQuizSubmissionResults] = useState<
    Record<string, QuizSubmissionResult>
  >({});
  const startIdempotencyKey = useRef(createIdempotencyKey());
  const submitCommand = useRef<{ payload: string; key: string } | null>(null);
  const selfReviewDraftCommand = useRef<{ payload: string; key: string } | null>(null);
  const selfReviewSubmitCommand = useRef<{ payload: string; key: string } | null>(null);

  useEffect(() => {
    if (!existingSubmissionId || item.type !== 'quiz') return;

    let cancelled = false;

    void getRuntimeSubmission(existingSubmissionId).then((result) => {
      if (cancelled) return;
      setIsStarting(false);
      if (!result.success) {
        setRuntimeError(result.error);
        return;
      }

      const nextSubmission =
        result.data as AssessmentSubmissionRuntimeViewV1<QuizLearnerDeliveryItemV1>;
      const quiz = readQuizActivityContent(item.content, nextSubmission);
      setRuntimeSubmission(nextSubmission);
      setQuizAnswers(readSubmittedQuizAnswers(nextSubmission));
      setQuizSubmissionResults(
        quiz.serverGraded
          ? buildQuizSubmissionResults(nextSubmission, quiz)
          : {},
      );
      setHasStarted(true);
    });

    return () => {
      cancelled = true;
    };
  }, [existingSubmissionId, item.content, item.type]);

  const handleStart = async () => {
    const authoredQuiz =
      item.type === 'quiz'
        ? readQuizActivityContent(item.content, null)
        : null;
    if (!authoredQuiz?.serverGraded) {
      setHasStarted(true);
      return;
    }

    setIsStarting(true);
    setRuntimeError(null);
    const result = await startContentRuntimeSubmission(
      item.id,
      startIdempotencyKey.current,
    );
    setIsStarting(false);
    if (!result.success) {
      setRuntimeError(result.error);
      return;
    }

    setRuntimeSubmission(
      result.data as AssessmentSubmissionRuntimeViewV1<QuizLearnerDeliveryItemV1>,
    );
    if (result.data.contentCompleted) onComplete();
    setHasStarted(true);
  };

  const handleSubmit = async () => {
    setIsSubmitting(true);

    try {
      const quiz =
        item.type === 'quiz'
          ? readQuizActivityContent(item.content, runtimeSubmission)
          : null;
      const quizResponse = quiz
        ? createQuizAnswerEnvelope(Object.fromEntries(
            quiz.questions.map((question) => {
              const answer =
                quizAnswers[question.id] ??
                createEmptyQuizAnswer(question.data.type);
              return [question.id, answer];
            }),
          ))
        : null;

      if (quiz?.serverGraded) {
        if (!runtimeSubmission || !quizResponse) {
          setRuntimeError('The official quiz attempt is not available.');
          return;
        }
        if (runtimeSubmission.status !== 'inProgress') {
          setRuntimeError('This attempt has already been submitted.');
          return;
        }

        const canonicalResponse = JSON.stringify(quizResponse);
        if (submitCommand.current?.payload !== canonicalResponse) {
          submitCommand.current = {
            payload: canonicalResponse,
            key: createIdempotencyKey(),
          };
        }
        const result = await submitRuntimeSubmission(
          runtimeSubmission.submissionId,
          quizResponse,
          submitCommand.current.key,
        );
        if (!result.success) {
          setRuntimeError(result.error);
          return;
        }

        const nextSubmission =
          result.data as AssessmentSubmissionRuntimeViewV1<QuizLearnerDeliveryItemV1>;
        setRuntimeSubmission(nextSubmission);
        setRuntimeError(null);
        setQuizSubmissionResults(buildQuizSubmissionResults(nextSubmission, quiz));
        if (nextSubmission.contentCompleted) {
          const visible = nextSubmission.execution.learnerVisibleResult;
          const score =
            visible?.score != null && visible.maxScore > 0
              ? Math.round((visible.score / visible.maxScore) * 100)
              : undefined;
          onComplete(score);
        }
        submitCommand.current = null;
        return;
      }

      const submissionData = {
        activityId: item.id,
        courseId,
        activityType: item.activityType || 'text',
        content: quizResponse ?? submission,
        isGraded:
          item.type === 'quiz'
            ? quiz?.serverGraded ?? false
            : item.type === 'assignment',
        attempt: 1,
      };

      const result = await submitActivity(submissionData);

      if (result.success) {
        const localPracticeScore =
          quiz && !quiz.serverGraded ? calculateQuizScore(quiz) : undefined;
        onComplete(result.score ?? localPracticeScore);
      } else {
        console.error('Submission failed:', result.message);
      }
    } catch (error) {
      console.error('Error submitting activity:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const saveSelfReviewDraft = async (evidence: SelfReviewEvidenceV1) => {
    if (!runtimeSubmission?.execution.selfReview) return;
    const payload = JSON.stringify(evidence);
    if (selfReviewDraftCommand.current?.payload !== payload) {
      selfReviewDraftCommand.current = {
        payload,
        key: createIdempotencyKey(),
      };
    }
    setIsSubmitting(true);
    setRuntimeError(null);
    const result = await saveCollectiveRuntimeSelfReviewDraft(
      runtimeSubmission.submissionId,
      evidence,
      runtimeSubmission.execution.selfReview.draftVersion,
      selfReviewDraftCommand.current.key,
    );
    setIsSubmitting(false);
    if (!result.success) {
      setRuntimeError(result.error);
      return;
    }
    selfReviewDraftCommand.current = null;
    setRuntimeSubmission(
      result.data as AssessmentSubmissionRuntimeViewV1<QuizLearnerDeliveryItemV1>,
    );
  };

  const submitSelfReview = async (evidence: SelfReviewEvidenceV1) => {
    if (!runtimeSubmission?.execution.selfReview) return;
    const payload = JSON.stringify(evidence);
    if (selfReviewSubmitCommand.current?.payload !== payload) {
      selfReviewSubmitCommand.current = {
        payload,
        key: createIdempotencyKey(),
      };
    }
    setIsSubmitting(true);
    setRuntimeError(null);
    const result = await submitRuntimeSelfReview(
      runtimeSubmission.submissionId,
      evidence,
      selfReviewSubmitCommand.current.key,
      runtimeSubmission.courseGroupId
        ? runtimeSubmission.execution.selfReview.draftVersion
        : undefined,
    );
    setIsSubmitting(false);
    if (!result.success) {
      setRuntimeError(result.error);
      return;
    }
    selfReviewSubmitCommand.current = null;
    const nextSubmission =
      result.data as AssessmentSubmissionRuntimeViewV1<QuizLearnerDeliveryItemV1>;
    setRuntimeSubmission(nextSubmission);
    const quiz = getQuizContent();
    if (quiz.serverGraded) {
      setQuizSubmissionResults(buildQuizSubmissionResults(nextSubmission, quiz));
    }
    if (nextSubmission.contentCompleted) onComplete();
  };

  const calculateQuizScore = (
    quiz: Extract<QuizActivityContent, { serverGraded: false }>,
  ): number => {
    const totals = quiz.questions.reduce(
      (current, question) => {
        const points = Number(question.data.points ?? "00000001.0000");
        const answer =
          quizAnswers[question.id] ??
          createEmptyQuizAnswer(question.data.type);
        const result = evaluateQuizAnswer(question.data, answer);

        return {
          possible: current.possible + points,
          earned: current.earned + (result.status === 'correct' ? points : 0),
        };
      },
      { possible: 0, earned: 0 },
    );

    return totals.possible > 0
      ? Math.round((totals.earned / totals.possible) * 100)
      : 0;
  };

  const getQuizContent = (): QuizActivityContent => {
    return readQuizActivityContent(item.content, runtimeSubmission);
  };

  const getActivityIcon = () => {
    switch (item.activityType || item.type) {
      case 'text':
        return <FileText className="h-16 w-16 text-blue-400" />;
      case 'code':
        return <Code className="h-16 w-16 text-purple-400" />;
      case 'file':
        return <Upload className="h-16 w-16 text-green-400" />;
      case 'quiz':
        return <MessageSquare className="h-16 w-16 text-yellow-400" />;
      default:
        return <Play className="h-16 w-16 text-slate-400" />;
    }
  };

  const renderQuizActivity = () => {
    const quiz = getQuizContent();
    const currentQuestion = quiz.questions[currentStep];
    if (!currentQuestion) {
      return (
        <div className="rounded-md border p-8 text-center text-sm text-muted-foreground">
          This quiz has no published questions.
        </div>
      );
    }
    const isLastQuestion = currentStep === quiz.questions.length - 1;
    const answer =
      quizAnswers[currentQuestion.id] ??
      createEmptyQuizAnswer(currentQuestion.data.type);
    const learnerEntry = quiz.serverGraded
      ? quiz.questions[currentStep]?.data
      : null;
    const practiceEntry = !quiz.serverGraded
      ? quiz.questions[currentStep]?.data
      : null;
    const setAnswer = (nextAnswer: QuizAnswer) => {
      setQuizAnswers((current) => ({
        ...current,
        [currentQuestion.id]: nextAnswer,
      }));
    };

    return (
      <div className="space-y-6">
        {runtimeError && (
          <div role="alert" className="rounded-md border border-destructive bg-destructive/10 p-3 text-sm text-destructive">
            {runtimeError}
          </div>
        )}
        <div className="flex items-center justify-between">
          <h3 className="text-lg font-semibold">
            Question {currentStep + 1} of {quiz.questions.length}
          </h3>
          <Badge variant="outline">
            {Number(currentQuestion.data.points ?? "00000001.0000")} points
          </Badge>
        </div>

        <Card>
          <CardContent className="p-6">
            {quiz.serverGraded ? (
              <QuizPlayer
                entry={learnerEntry!}
                answer={answer}
                disabled={runtimeSubmission?.status !== 'inProgress'}
                onAnswerChange={setAnswer}
                onSubmit={(nextAnswer) => {
                  setAnswer(nextAnswer);
                  setQuizSubmissionResults((current) => ({
                    ...current,
                    [currentQuestion.id]: {
                      status: 'pending',
                      feedback: 'Answer recorded. Submit the quiz to grade it.',
                    },
                  }));
                }}
                submissionResult={
                  quizSubmissionResults[currentQuestion.id] ?? { status: 'idle' }
                }
              />
            ) : (
              <QuizPracticePlayer
                entry={practiceEntry!}
                answer={answer}
                onAnswerChange={setAnswer}
              />
            )}
          </CardContent>
        </Card>

        <div className="flex justify-between">
          <Button variant="outline" onClick={() => setCurrentStep(Math.max(0, currentStep - 1))} disabled={currentStep === 0} className="border-gray-600">
            Previous
          </Button>

          {isLastQuestion ? (
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting || (quiz.serverGraded && runtimeSubmission?.status !== 'inProgress')}
              className="bg-green-600 hover:bg-green-700"
            >
              {isSubmitting ? 'Submitting...' : 'Submit Quiz'}
            </Button>
          ) : (
            <Button onClick={() => setCurrentStep(Math.min(quiz.questions.length - 1, currentStep + 1))} className="bg-blue-600 hover:bg-blue-700">
              Next
            </Button>
          )}
        </div>

        {runtimeSubmission?.execution.submittedResponse &&
          runtimeSubmission.execution.selfReview && (
            <SelfReviewForm
              items={quiz.questions.map((question) => ({
                itemId: question.id,
                label: question.data.stem || question.id,
                maxScore:
                  runtimeSubmission.execution.itemMaxScores[question.id] ?? 0,
              }))}
              state={runtimeSubmission.execution.selfReview}
              busy={isSubmitting}
              onSaveDraft={
                runtimeSubmission.courseGroupId
                  ? saveSelfReviewDraft
                  : undefined
              }
              onSubmit={submitSelfReview}
            />
          )}
      </div>
    );
  };

  const renderTextActivity = () => (
    <div className="space-y-6">
      <Card className="bg-gradient-to-br from-slate-900/50 to-slate-800/50 backdrop-blur-sm border-slate-700/50 shadow-lg">
        <CardHeader>
          <CardTitle className="text-white">Activity Instructions</CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-slate-400 mb-4">{item.description || 'Complete this text-based activity by providing your response below.'}</p>

          {item.id === 'activity-1' && (
            <div className="bg-gradient-to-br from-slate-800/50 to-slate-700/50 p-4 rounded border border-slate-600 backdrop-blur-sm">
              <h4 className="font-semibold mb-2 text-white">Setup Instructions:</h4>
              <ol className="list-decimal list-inside space-y-2 text-slate-400">
                <li>Download and install your preferred game engine (Unity, Unreal Engine, or Godot)</li>
                <li>Set up a code editor (Visual Studio Code, Visual Studio, or similar)</li>
                <li>Create a new project in your chosen engine</li>
                <li>Familiarize yourself with the interface and basic navigation</li>
                <li>Document any challenges you encountered during setup</li>
              </ol>
            </div>
          )}
        </CardContent>
      </Card>

      <Card className="bg-gradient-to-br from-slate-900/50 to-slate-800/50 backdrop-blur-sm border-slate-700/50 shadow-lg">
        <CardHeader>
          <CardTitle className="text-white">Your Response</CardTitle>
        </CardHeader>
        <CardContent>
          <Textarea
            placeholder="Describe your setup process, any challenges encountered, and what you learned..."
            value={(submission.response as string) || ''}
            onChange={(e) => setSubmission((prev) => ({ ...prev, response: e.target.value }))}
            className="bg-slate-800/50 border-slate-600 text-white min-h-[200px] backdrop-blur-sm"
          />
          <p className="text-sm text-slate-400 mt-2">Minimum 100 words required for completion.</p>
        </CardContent>
      </Card>

      <div className="flex justify-end gap-2">
        <Button variant="outline" onClick={() => setSubmission((prev) => ({ ...prev, saved: true }))} className="bg-slate-800/50 border-slate-600 text-slate-200 hover:bg-slate-700/50 hover:border-slate-500">
          <Save className="h-4 w-4 mr-2" />
          Save Draft
        </Button>
        <Button
          onClick={handleSubmit}
          disabled={isSubmitting || ((submission.response as string) || '').length < 100}
          className="bg-gradient-to-r from-green-600 to-teal-600 hover:from-green-700 hover:to-teal-700 border-0 shadow-lg hover:shadow-xl hover:shadow-green-500/25 transition-all"
        >
          <Send className="h-4 w-4 mr-2" />
          {isSubmitting ? 'Submitting...' : 'Submit Activity'}
        </Button>
      </div>
    </div>
  );

  const renderCodeActivity = () => (
    <div className="space-y-6">
      <Card className="bg-gradient-to-br from-slate-900/50 to-slate-800/50 backdrop-blur-sm border-slate-700/50 shadow-lg">
        <CardHeader>
          <CardTitle className="text-white">Coding Challenge</CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-slate-400 mb-4">Create a simple player movement script based on the lesson content.</p>

          <div className="bg-gradient-to-br from-slate-800/50 to-slate-700/50 p-4 rounded border border-slate-600 mb-4 backdrop-blur-sm">
            <h4 className="font-semibold mb-2 text-white">Requirements:</h4>
            <ul className="list-disc list-inside space-y-1 text-slate-400">
              <li>Create a script that handles player input (WASD or arrow keys)</li>
              <li>Implement basic movement in 2D or 3D space</li>
              <li>Include comments explaining your code</li>
              <li>Test your script and document any issues</li>
            </ul>
          </div>
        </CardContent>
      </Card>

      <Card className="bg-gradient-to-br from-slate-900/50 to-slate-800/50 backdrop-blur-sm border-slate-700/50 shadow-lg">
        <CardHeader>
          <CardTitle className="text-white">Code Submission</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <div>
              <Label htmlFor="language">Programming Language</Label>
              <Input
                id="language"
                placeholder="e.g., C#, JavaScript, GDScript"
                value={(submission.language as string) || ''}
                onChange={(e) => setSubmission((prev) => ({ ...prev, language: e.target.value }))}
                className="bg-gray-800 border-gray-600 text-white"
              />
            </div>

            <div>
              <Label htmlFor="code">Your Code</Label>
              <Textarea
                id="code"
                placeholder="Paste your player movement script here..."
                value={(submission.code as string) || ''}
                onChange={(e) => setSubmission((prev) => ({ ...prev, code: e.target.value }))}
                className="bg-gray-800 border-gray-600 text-white font-mono min-h-[300px]"
              />
            </div>

            <div>
              <Label htmlFor="explanation">Code Explanation</Label>
              <Textarea
                id="explanation"
                placeholder="Explain how your code works and any challenges you faced..."
                value={(submission.explanation as string) || ''}
                onChange={(e) => setSubmission((prev) => ({ ...prev, explanation: e.target.value }))}
                className="bg-gray-800 border-gray-600 text-white min-h-[150px]"
              />
            </div>
          </div>
        </CardContent>
      </Card>

      <div className="flex justify-end gap-2">
        <Button variant="outline" onClick={() => setSubmission((prev) => ({ ...prev, saved: true }))} className="border-gray-600">
          <Save className="h-4 w-4 mr-2" />
          Save Draft
        </Button>
        <Button onClick={handleSubmit} disabled={isSubmitting || !((submission.code as string) || '').trim()} className="bg-green-600 hover:bg-green-700">
          <Send className="h-4 w-4 mr-2" />
          {isSubmitting ? 'Submitting...' : 'Submit Code'}
        </Button>
      </div>
    </div>
  );

  if (!hasStarted) {
    return (
      <div className="text-center py-12">
        <div className="mb-6">{getActivityIcon()}</div>
        <h3 className="text-xl font-semibold mb-2 mt-4 text-white">{item.title}</h3>
        <p className="text-slate-400 mb-6 max-w-md mx-auto">{item.description || 'Ready to start this activity?'}</p>
        <div className="flex items-center justify-center gap-4 mb-6">
          {item.duration && (
            <div className="flex items-center gap-1 text-sm text-slate-400">
              <Clock className="h-4 w-4" />
              {item.duration} minutes
            </div>
          )}
          {item.isRequired && (
            <Badge variant="secondary" className="bg-gradient-to-r from-purple-500/20 to-blue-500/20 border-purple-500/30 text-purple-300">
              Required
            </Badge>
          )}
        </div>
        {runtimeError && (
          <p role="alert" className="mb-4 text-sm text-destructive">
            {runtimeError}
          </p>
        )}
        <Button
          onClick={() => void handleStart()}
          disabled={isStarting}
          className="bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 border-0 shadow-lg hover:shadow-xl hover:shadow-blue-500/25 transition-all"
        >
          {isStarting ? 'Starting...' : 'Start Activity'}
        </Button>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto">
      {item.type === 'quiz' && renderQuizActivity()}
      {item.activityType === 'text' && renderTextActivity()}
      {item.activityType === 'code' && renderCodeActivity()}
      {item.activityType === 'file' && (
        <div className="text-center py-12">
          <Upload className="h-16 w-16 text-gray-400 mx-auto mb-4" />
          <p className="text-gray-400">File upload activity - Implementation in progress</p>
        </div>
      )}
    </div>
  );
}

function readQuizActivityContent(
  content: unknown,
  runtimeSubmission: AssessmentSubmissionRuntimeViewV1<QuizLearnerDeliveryItemV1> | null,
): QuizActivityContent {
  if (runtimeSubmission) {
    const { delivery } = runtimeSubmission.execution;
    const questions = delivery.itemOrder.map((itemId) => {
      const itemDelivery = delivery.items[itemId];
      if (
        !itemDelivery ||
        itemDelivery.adapterKey !== QUIZ_ASSESSMENT_TYPE_ADAPTER.key ||
        itemDelivery.adapterVersion !== QUIZ_ASSESSMENT_TYPE_ADAPTER.version
      ) {
        throw new Error(`Unsupported quiz delivery for item ${itemId}.`);
      }
      const payload = itemDelivery.learnerPayload;
      if (payload.itemId !== itemId) {
        throw new Error(`Quiz delivery item ${itemId} has a mismatched payload.`);
      }
      return { id: itemId, data: payload.entry };
    });
    return { questions, serverGraded: true };
  }

  if (!isQuizRuntimeContentDocument(content)) {
    return { questions: [], serverGraded: false };
  }

  const rawQuestions = content.document.order.flatMap((entry) => {
    if (
      !Array.isArray(entry) ||
      typeof entry[0] !== 'string' ||
      entry[1] !== 'quiz'
    ) {
      return [];
    }

    const data = content.document.blocks[entry[0]];
    if (!data || typeof data !== 'object' || Array.isArray(data)) return [];
    return [{ id: entry[0], data }];
  });

  return content.mode === 'server-graded'
    ? {
        questions: rawQuestions as Array<
          QuizActivityQuestion<QuizLearnerEntry>
        >,
        serverGraded: true,
      }
    : {
        questions: rawQuestions as Array<
          QuizActivityQuestion<QuizPracticeEntry>
        >,
        serverGraded: false,
      };
}

function readSubmittedQuizAnswers(
  submission: AssessmentSubmissionRuntimeViewV1<QuizLearnerDeliveryItemV1>,
): Record<string, QuizAnswer> {
  if (!submission.execution.submittedResponse) return {};

  try {
    return {
      ...parseQuizAnswerEnvelope(submission.execution.submittedResponse).payload
        .answers,
    };
  } catch {
    return {};
  }
}

function createIdempotencyKey(): string {
  return globalThis.crypto?.randomUUID?.() ?? `grading-${Date.now()}-${Math.random()}`;
}

function buildQuizSubmissionResults(
  submission: AssessmentSubmissionRuntimeViewV1<QuizLearnerDeliveryItemV1>,
  quiz: Extract<QuizActivityContent, { serverGraded: true }>,
): Record<string, QuizSubmissionResult> {
  const visible = submission.execution.learnerVisibleResult;
  if (!visible) {
    return Object.fromEntries(
      quiz.questions.map((question) => [
        question.id,
        {
          status: 'pending' as const,
          feedback: submission.execution.requiresInstructorReview
            ? 'Submitted for instructor review.'
            : 'Submitted. The result has not been released yet.',
        },
      ]),
    );
  }

  const byId = new Map(visible.items.map((item) => [item.itemId, item]));
  return Object.fromEntries(
    quiz.questions.map((question) => {
      const item = byId.get(question.id);
      if (!item || item.score == null) {
        return [question.id, { status: 'pending' as const, feedback: item?.feedback }];
      }
      return [
        question.id,
        {
          status: item.score === item.maxScore ? ('correct' as const) : ('incorrect' as const),
          feedback: item.feedback,
        },
      ];
    }),
  );
}

