  }

  return <EconomyWorkspace>
    <EconomyPageHeader title={t('bounties.title')} description={t('bounties.description')} />
    <EconomyIssue issue={data.issue} /><EconomyActionNotice result={result} />
    <Card><CardHeader><CardTitle>{t('bounties.create')}</CardTitle></CardHeader><CardContent>
      <form className="grid gap-4 md:grid-cols-3" onSubmit={(event) => {
        event.preventDefault();
        const form = new FormData(event.currentTarget);
        run(() => createBountyAction({ amountUnits: Number(amount), currency: 'HardCoin', expiresAt: new Date(expiresAt).toISOString(), idempotencyKey: crypto.randomUUID(), minimumReputation: Number(minimumReputation), requiresInstructorVerification: form.get('instructor') === 'on', requiresPrerequisite: form.get('prerequisite') === 'on' }));
      }}>
        <Field label={t('common.amount')}><Input min="1" onChange={(event) => setAmount(event.target.value)} required type="number" value={amount} /></Field>
        <Field label={t('bounties.expires')}><Input onChange={(event) => setExpiresAt(event.target.value)} required type="datetime-local" value={expiresAt} /></Field>
        <Field label={t('bounties.minimumReputation')}><Input min="0" onChange={(event) => setMinimumReputation(event.target.value)} required type="number" value={minimumReputation} /></Field>
        <label className="flex items-center gap-2 text-sm"><input name="prerequisite" type="checkbox" />{t('bounties.prerequisite')}</label>
        <label className="flex items-center gap-2 text-sm"><input name="instructor" type="checkbox" />{t('bounties.instructor')}</label>
        <Button disabled={pending} type="submit">{t('bounties.create')}</Button>
      </form>
    </CardContent></Card>
    <div className="grid gap-4 lg:grid-cols-2">{data.bounties.map((bounty) => {
      const id = bounty.id?.value ?? '';
      return <Card key={id}><CardHeader><div className="flex items-center justify-between gap-3"><CardTitle className="font-mono text-base"><Link className="underline underline-offset-4" href={`/workspace/economy/bounties/${id}`}>{id}</Link></CardTitle><Badge variant="secondary">{bounty.status}</Badge></div></CardHeader><CardContent className="grid gap-4"><p className="text-sm">{formatEconomyUnits(bounty.amount?.units)} {bounty.amount?.currency}</p><p className="text-sm text-muted-foreground">{t('bounties.expires')}: {formatEconomyDate(bounty.expiresAt)}</p><div className="flex gap-2"><Button disabled={pending || bounty.status !== 'Open'} onClick={() => run(() => claimBountyAction(id, crypto.randomUUID()))} size="sm" type="button">{t('bounties.claim')}</Button><Button disabled={pending || bounty.status !== 'Expired'} onClick={() => run(() => reclaimBountyAction(id, crypto.randomUUID()))} size="sm" type="button" variant="outline">{t('bounties.reclaim')}</Button></div></CardContent></Card>;
    })}</div>
  </EconomyWorkspace>;
}

function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="flex flex-col gap-2 text-sm font-medium">{label}{children}</label>; }

'use client';

import {
  beginEconomyConsoleStepUpAction,
  executeEconomyConsoleAction,
  verifyEconomyConsoleStepUpAction,
  type EconomyConsoleActionResult,
} from '@/lib/economy/console-actions';
import {
  economyConsoleActionDefinitions,
  type EconomyConsoleActionDefinition,
  type EconomyConsoleActionField,
} from '@/lib/economy/console-action-definitions';
import type { EconomyConsoleSurface } from '@/lib/economy/console';
import { Alert, AlertDescription, AlertTitle } from '@game-guild/ui/components/alert';
import { Button } from '@game-guild/ui/components/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@game-guild/ui/components/card';
import { Input } from '@game-guild/ui/components/input';
import { CheckCircle2, KeyRound, ShieldAlert } from 'lucide-react';
import { useTranslations } from 'next-intl';
import { useRouter } from 'next/navigation';
import { useMemo, useState, useTransition } from 'react';

function translationKey(action: string) {
  return action.replaceAll('.', '_').replaceAll('-', '_');
}

function initialValues(definition: EconomyConsoleActionDefinition | undefined) {
  return Object.fromEntries((definition?.fields ?? []).map((item) => [item.key,
    ['payload', 'buffers'].includes(item.key) ? '{}' : ['services', 'custodyObservationIds', 'verifiedSessionIds'].includes(item.key) ? '[]' : '',
  ]));
}

function ActionField({ field, value, onChange }: {
  field: EconomyConsoleActionField;
  value: string | boolean;
  onChange: (value: string | boolean) => void;
}) {
  const t = useTranslations('economy.console.fields');
  const label = t.has(field.key) ? t(field.key) : field.key;
  if (field.kind === 'checkbox') {
    return (
      <label className="flex items-center gap-2 rounded-md border p-3 text-sm">
        <input checked={Boolean(value)} onChange={(event) => onChange(event.target.checked)} type="checkbox" />
        <span>{label}</span>
      </label>
    );
  }
  if (field.kind === 'select') {
    return (
      <label className="grid gap-1.5 text-sm">
        <span className="font-medium">{label}</span>
        <select className="h-10 rounded-md border bg-background px-3" onChange={(event) => onChange(event.target.value)} required={field.required} value={String(value)}>
          <option value="">—</option>
          {field.options.map((option) => <option key={option} value={option}>{option}</option>)}
        </select>
      </label>
    );
  }
  if (field.kind === 'textarea') {
    return (
      <label className="grid gap-1.5 text-sm sm:col-span-2">
        <span className="font-medium">{label}</span>
        <textarea className="min-h-24 rounded-md border bg-background p-3 font-mono text-sm" onChange={(event) => onChange(event.target.value)} required={field.required} value={String(value)} />
      </label>
    );
  }
  return (
    <label className="grid gap-1.5 text-sm">
      <span className="font-medium">{label}</span>
      <Input min={field.kind === 'number' ? 0 : undefined} onChange={(event) => onChange(event.target.value)} required={field.required} type={field.kind} value={String(value)} />
    </label>
  );
}

export function EconomyConsoleActions({ surface }: { surface: EconomyConsoleSurface }) {
  const t = useTranslations('economy.console');
  const router = useRouter();
  const definitions = useMemo(() => economyConsoleActionDefinitions[surface] ?? [], [surface]);
  const [selectedAction, setSelectedAction] = useState<string>(definitions[0]?.action ?? '');
  const definition = definitions.find((item) => item.action === selectedAction);
  const [values, setValues] = useState<Record<string, string | boolean>>(() => initialValues(definition));
  const [challengeId, setChallengeId] = useState<string | null>(null);
  const [mfaCode, setMfaCode] = useState('');
  const [result, setResult] = useState<EconomyConsoleActionResult | null>(null);
  const [pending, startTransition] = useTransition();

  if (!definition) return null;
  const activeDefinition = definition;

  function choose(actionName: string) {
    const next = definitions.find((item) => item.action === actionName);
    setSelectedAction(actionName);
    setValues(initialValues(next));
    setChallengeId(null);
    setMfaCode('');
    setResult(null);
  }

  function complete(actionResult: EconomyConsoleActionResult) {
    setResult(actionResult);
    if (actionResult.success) router.refresh();
  }

  function submit() {
    startTransition(async () => {
      if (activeDefinition.stepUp) {
        const challenge = await beginEconomyConsoleStepUpAction(activeDefinition.action, values);
        setResult(challenge);
        if (challenge.success && challenge.challengeId) setChallengeId(challenge.challengeId);
        return;
      }
      complete(await executeEconomyConsoleAction(activeDefinition.action, values));
    });
  }

  function verifyAndExecute(activeChallengeId: string) {
    startTransition(async () => {
      const verified = await verifyEconomyConsoleStepUpAction(activeChallengeId, mfaCode);
      if (!verified.success || !verified.receipt) {
        setResult(verified);
        return;
      }
      const executed = await executeEconomyConsoleAction(activeDefinition.action, values, verified.receipt);
      setChallengeId(null);
      setMfaCode('');
      complete(executed);
    });
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>{t('title')}</CardTitle>
        <CardDescription>{t('description')}</CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {result ? (
          <Alert variant={result.success ? 'default' : 'destructive'}>
            {result.success ? <CheckCircle2 className="size-4" /> : <ShieldAlert className="size-4" />}
            <AlertTitle>{result.success ? t('accepted') : t('rejected')}</AlertTitle>
            <AlertDescription>{result.message}</AlertDescription>
          </Alert>
        ) : null}

        <label className="grid gap-1.5 text-sm">
          <span className="font-medium">{t('selectAction')}</span>
          <select className="h-10 rounded-md border bg-background px-3" disabled={pending || Boolean(challengeId)} onChange={(event) => choose(event.target.value)} value={selectedAction}>
            {definitions.map((item) => <option key={item.action} value={item.action}>{t(`actions.${translationKey(item.action)}`)}</option>)}
          </select>
        </label>

        <div className="grid gap-3 sm:grid-cols-2">
          {activeDefinition.fields.map((item) => (
            <ActionField key={item.key} field={item} value={values[item.key] as string | boolean} onChange={(value) => setValues((current) => ({ ...current, [item.key]: value }))} />
          ))}
        </div>

        {challengeId ? (
          <div className="grid gap-3 rounded-lg border border-amber-500/40 bg-amber-500/5 p-4">
            <div className="flex items-center gap-2 font-medium"><KeyRound className="size-4" />{t('mfaTitle')}</div>
            <p className="text-sm text-muted-foreground">{t('mfaDescription')}</p>
            <Input autoComplete="one-time-code" inputMode="numeric" onChange={(event) => setMfaCode(event.target.value)} placeholder={t('mfaCode')} value={mfaCode} />
            <div className="flex gap-2">
              <Button disabled={pending || !mfaCode.trim()} onClick={() => verifyAndExecute(challengeId)} type="button">{pending ? t('pending') : t('verifyAndExecute')}</Button>
              <Button disabled={pending} onClick={() => { setChallengeId(null); setMfaCode(''); }} type="button" variant="outline">{t('cancel')}</Button>
            </div>
          </div>
        ) : (
          <Button disabled={pending} onClick={submit} type="button">{pending ? t('pending') : activeDefinition.stepUp ? t('beginMfa') : t('execute')}</Button>
        )}
      </CardContent>
    </Card>
  );
}

'use client';

import { createKycAccessTokenAction, startKycOnboardingAction, type EconomyActionResult } from '@/lib/economy/actions';
import type { EconomyKycData } from '@/lib/economy/queries';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@game-guild/ui/components/card';
import { useRouter } from 'next/navigation';
import { useLocale, useTranslations } from 'next-intl';
import { useEffect, useState, useTransition } from 'react';
import { EconomyActionNotice, EconomyIssue, EconomyPageHeader, EconomyWorkspace, formatEconomyDate } from './economy-ui';

type SumsubWebSdkComponent = typeof import('@sumsub/websdk-react')['default'];

export function EconomyKycWorkspace({ data }: { data: EconomyKycData }) {
  const t = useTranslations('economy');
  const locale = useLocale();
  const router = useRouter();
  const [result, setResult] = useState<EconomyActionResult<unknown> | null>(null);
  const [pending, startTransition] = useTransition();
  const [accessToken, setAccessToken] = useState<string | null>(null);
  const [SumsubWebSdk, setSumsubWebSdk] = useState<SumsubWebSdkComponent | null>(null);

  useEffect(() => {
    let active = true;
    void import('@sumsub/websdk-react')
      .then(({ default: sdk }) => {
        if (active) setSumsubWebSdk(() => sdk);
      })
      .catch(() => {
        if (active) setResult({ success: false, message: t('kyc.unavailable') });
      });
    return () => { active = false; };
  }, [t]);

  async function renewAccessToken() {
    const refreshed = await createKycAccessTokenAction();
    if (!refreshed.success || !refreshed.data?.token) throw new Error(t('kyc.renewalFailed'));
    setAccessToken(refreshed.data.token);
    return refreshed.data.token;
  }

  function start() {
    startTransition(async () => {
      const onboarding = await startKycOnboardingAction(crypto.randomUUID());
      if (!onboarding.success) return setResult(onboarding);
      const token = await createKycAccessTokenAction();
      setResult(token);
      if (token.success && token.data?.token) {
        setAccessToken(token.data.token);
        router.refresh();
      }
    });
  }

  return (
    <EconomyWorkspace>
      <EconomyPageHeader title={t('kyc.title')} description={t('kyc.description')} />
      <EconomyIssue issue={data.issue} />
      <EconomyActionNotice result={result} />
      <Card className="max-w-3xl">
        <CardHeader>
          <div className="flex items-center justify-between gap-4">
            <CardTitle>{data.status?.result ?? t('kyc.notStarted')}</CardTitle>
            <Badge variant={data.status?.isCurrent ? 'default' : 'secondary'}>{data.status?.isCurrent ? t('kyc.current') : t('common.disabled')}</Badge>
          </div>
          <CardDescription>{t('kyc.unavailable')}</CardDescription>
        </CardHeader>
        <CardContent className="grid gap-5 sm:grid-cols-2">
          <div><p className="text-sm text-muted-foreground">{t('kyc.expires')}</p><p className="mt-1 text-sm font-medium">{formatEconomyDate(data.status?.expiresAt)}</p></div>
          <div><p className="text-sm text-muted-foreground">{t('common.version')}</p><p className="mt-1 text-sm font-medium">{data.status?.version ?? t('common.notAvailable')}</p></div>
          <Button className="sm:col-span-2 sm:w-fit" disabled={pending} onClick={start} type="button">{data.status?.hasEvidence ? t('kyc.resume') : t('kyc.start')}</Button>
          {accessToken && SumsubWebSdk ? (
            <div className="min-h-96 overflow-hidden rounded-lg border bg-background sm:col-span-2" aria-live="polite">
              <SumsubWebSdk
                accessToken={accessToken}
                expirationHandler={renewAccessToken}
                config={{ lang: locale === 'pt-BR' ? 'pt' : 'en' }}
                options={{ addViewportTag: true, adaptIframeHeight: true }}
                onMessage={(type: string) => {
                  if (type === 'idCheck.onApplicantStatusChanged') router.refresh();
                }}
                onError={() => setResult({ success: false, message: t('kyc.unavailable') })}
              />
            </div>
          ) : null}
        </CardContent>
      </Card>
    </EconomyWorkspace>
  );
}

'use client';

import type { EconomyConsoleData } from '@/lib/economy/console';
import { Badge } from '@game-guild/ui/components/badge';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@game-guild/ui/components/card';
