import { createTopUpAction, type EconomyActionResult } from '@/lib/economy/actions';
import type { EconomyTopUpsData } from '@/lib/economy/queries';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@game-guild/ui/components/card';
import { Input } from '@game-guild/ui/components/input';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@game-guild/ui/components/table';
import { useRouter } from 'next/navigation';
import { useTranslations } from 'next-intl';
import { useState, useTransition } from 'react';
import { Link } from '@/i18n/navigation';
import { EconomyActionNotice, EconomyIssue, EconomyPageHeader, EconomyWorkspace, formatEconomyDate, formatEconomyUnits } from './economy-ui';
import { TopUpStripePaymentElement } from './top-up-stripe-payment-element';

export function EconomyTopUpsWorkspace({ data }: { data: EconomyTopUpsData }) {
  const t = useTranslations('economy');
  const router = useRouter();
  const [units, setUnits] = useState('');
  const [result, setResult] = useState<EconomyActionResult<unknown> | null>(null);
  const [payment, setPayment] = useState<{ clientSecret: string; publishableKey: string; topUpId: string } | null>(null);
  const [pending, startTransition] = useTransition();

  return (
    <EconomyWorkspace>
      <EconomyPageHeader title={t('topUps.title')} description={t('topUps.description')} />
      <EconomyIssue issue={data.issue} />
      <EconomyActionNotice result={result} />
      <Card>
        <CardHeader>
          <CardTitle>{t('topUps.create')}</CardTitle>
          <CardDescription>{t('topUps.paymentRequired')}</CardDescription>
        </CardHeader>
        <CardContent>
          <form className="flex max-w-xl flex-col gap-4 sm:flex-row sm:items-end" onSubmit={(event) => {
            event.preventDefault();
            startTransition(async () => {
              const next = await createTopUpAction(Number(units), crypto.randomUUID());
              setResult(next);
              if (next.success && next.data?.clientSecret && next.data.publishableKey && next.data.topUpId) {
                setPayment({
                  clientSecret: next.data.clientSecret,
                  publishableKey: next.data.publishableKey,
                  topUpId: next.data.topUpId,
                });
              }
              if (next.success) router.refresh();
            });
          }}>
            <label className="flex flex-1 flex-col gap-2 text-sm font-medium" htmlFor="top-up-units">
              {t('topUps.units')}
              <Input id="top-up-units" inputMode="numeric" min="1" onChange={(event) => setUnits(event.target.value)} required type="number" value={units} />
            </label>
            <Button disabled={pending} type="submit">{t('topUps.create')}</Button>
          </form>
          {payment ? <div className="mt-5"><TopUpStripePaymentElement {...payment} /></div> : null}
        </CardContent>
      </Card>
      <Card>
        <CardHeader><CardTitle>{t('topUps.history')}</CardTitle></CardHeader>
        <CardContent className="overflow-x-auto">
          <Table>
            <TableHeader><TableRow><TableHead>{t('common.identifier')}</TableHead><TableHead>{t('common.amount')}</TableHead><TableHead>{t('common.state')}</TableHead><TableHead>{t('common.updated')}</TableHead></TableRow></TableHeader>
            <TableBody>
              {data.topUps.map((topUp) => (
                <TableRow key={topUp.topUpId}>
                  <TableCell className="font-mono text-sm"><Link className="underline underline-offset-4" href={`/workspace/economy/top-ups/${topUp.topUpId}`}>{topUp.topUpId}</Link></TableCell>
                  <TableCell>{formatEconomyUnits(topUp.hardCoinUnits)} HardCoin</TableCell>
                  <TableCell><Badge variant="secondary">{topUp.status}</Badge></TableCell>
                  <TableCell>{formatEconomyDate(topUp.providerBoundAt ?? topUp.requestedAt)}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
          {!data.topUps.length ? <p className="py-6 text-center text-sm text-muted-foreground">{t('common.empty')}</p> : null}
        </CardContent>
      </Card>
    </EconomyWorkspace>
  );
}

'use client';

import { createTransferAction, type EconomyActionResult } from '@/lib/economy/actions';
import type { FinanceEconomyContractsEconomyWalletTransaction as EconomyContractsEconomyWalletTransaction } from '@game-guild/client';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { Card, CardContent, CardHeader, CardTitle } from '@game-guild/ui/components/card';
import { Input } from '@game-guild/ui/components/input';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@game-guild/ui/components/table';
import { useRouter } from 'next/navigation';
import { useTranslations } from 'next-intl';
import { useState, useTransition } from 'react';
import { EconomyActionNotice, EconomyPageHeader, EconomyWorkspace, formatEconomyDate, formatEconomyUnits } from './economy-ui';

export function EconomyTransfersWorkspace({ transactions }: { transactions: EconomyContractsEconomyWalletTransaction[] }) {
  const t = useTranslations('economy');
  const router = useRouter();
  const [recipient, setRecipient] = useState('');
  const [amount, setAmount] = useState('');
  const [currency, setCurrency] = useState<'HardCoin' | 'SoftCoin'>('HardCoin');
  const [type, setType] = useState<'Tip' | 'Gift' | 'CreatorSupport'>('Tip');
  const [result, setResult] = useState<EconomyActionResult | null>(null);
  const [pending, startTransition] = useTransition();

  return (
    <EconomyWorkspace>
      <EconomyPageHeader title={t('transfers.title')} description={t('transfers.description')} />
      <EconomyActionNotice result={result} />
      <Card>
        <CardContent className="pt-6">
          <form className="grid gap-4 md:grid-cols-2 xl:grid-cols-5" onSubmit={(event) => {
            event.preventDefault();
            startTransition(async () => {
              const next = await createTransferAction(recipient, Number(amount), currency, type, crypto.randomUUID());
              setResult(next);
              if (next.success) router.refresh();
            });
          }}>
            <Field label={t('transfers.recipient')}><Input onChange={(event) => setRecipient(event.target.value)} required value={recipient} /></Field>
            <Field label={t('common.amount')}><Input inputMode="numeric" min="1" onChange={(event) => setAmount(event.target.value)} required type="number" value={amount} /></Field>
            <Field label={t('common.currency')}><select className="h-10 rounded-md border bg-background px-3 text-sm" onChange={(event) => setCurrency(event.target.value as typeof currency)} value={currency}><option>HardCoin</option><option>SoftCoin</option></select></Field>
            <Field label={t('transfers.type')}><select className="h-10 rounded-md border bg-background px-3 text-sm" onChange={(event) => setType(event.target.value as typeof type)} value={type}><option value="Tip">{t('transfers.tip')}</option><option value="Gift">{t('transfers.gift')}</option><option value="CreatorSupport">{t('transfers.creatorSupport')}</option></select></Field>
            <Button className="self-end" disabled={pending} type="submit">{t('transfers.send')}</Button>
          </form>
        </CardContent>
      </Card>
      <Card>
        <CardHeader><CardTitle>{t('transfers.history')}</CardTitle></CardHeader>
        <CardContent className="overflow-x-auto">
          <Table><TableHeader><TableRow><TableHead>{t('common.identifier')}</TableHead><TableHead>{t('common.amount')}</TableHead><TableHead>{t('common.state')}</TableHead><TableHead>{t('common.created')}</TableHead></TableRow></TableHeader>
            <TableBody>{transactions.map((entry) => <TableRow key={entry.journalEntryId}><TableCell className="font-mono text-sm">{entry.journalEntryId}</TableCell><TableCell>{formatEconomyUnits(entry.amountUnits)} {entry.currency}</TableCell><TableCell><Badge variant="secondary">{entry.templateKind}</Badge></TableCell><TableCell>{formatEconomyDate(entry.recordedAt)}</TableCell></TableRow>)}</TableBody>
          </Table>
        </CardContent>
      </Card>
    </EconomyWorkspace>
  );
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return <label className="flex flex-col gap-2 text-sm font-medium">{label}{children}</label>;
}

'use client';

import {
  cancelPayoutRequestAction,
  convertHardToSoftAction,
  submitPayoutRequestAction,
  type EconomyActionResult,
} from '@/lib/economy/actions';
import type { EconomyWorkspaceData } from '@/lib/economy/queries';
import { Alert, AlertDescription, AlertTitle } from '@game-guild/ui/components/alert';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@game-guild/ui/components/card';
import { Input } from '@game-guild/ui/components/input';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@game-guild/ui/components/table';
import { AlertTriangle, ArrowRightLeft, Landmark, ShieldCheck, WalletCards } from 'lucide-react';
import { useRouter } from 'next/navigation';
import { type ReactNode, useState, useTransition } from 'react';

function amount(value: number | null | undefined) {
  return new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 }).format(value ?? 0);
}

function timestamp(value: string | null | undefined) {
  return value ? `${value.slice(0, 10)} ${value.slice(11, 16)} UTC` : '—';
}

function isReady(data: EconomyWorkspaceData, capability: string) {
  return data.capabilities.some(
    (item) => item.capability === capability && item.state === 'Ready',
  );
}

function capabilityDiagnostic(data: EconomyWorkspaceData, capability: string) {
  return data.capabilities
    .find((item) => item.capability === capability)
    ?.diagnostics?.filter(Boolean)
    .join(' · ');
}

function requestBadgeVariant(state: string | null | undefined): 'default' | 'destructive' | 'outline' | 'secondary' {
  if (state === 'Rejected') return 'destructive';
  if (state === 'Approved') return 'default';
  return state === 'Cancelled' ? 'outline' : 'secondary';
}

function operationBadgeVariant(state: string | null | undefined): 'default' | 'destructive' | 'outline' | 'secondary' {
  if (state === 'Failed') return 'destructive';
  if (state === 'Succeeded') return 'default';
  return state === 'Cancelled' ? 'outline' : 'secondary';
}

export function EconomyWalletWorkspace({ data }: { data: EconomyWorkspaceData }) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [message, setMessage] = useState<EconomyActionResult | null>(null);
  const [payoutAmount, setPayoutAmount] = useState('');
  const [conversionAmount, setConversionAmount] = useState('');
  const canConvert = isReady(data, 'ConvertHardToSoft');
  const payoutDiagnostic = capabilityDiagnostic(data, 'PayoutExecution');
  const conversionDiagnostic = capabilityDiagnostic(data, 'ConvertHardToSoft');

  function execute(action: () => Promise<EconomyActionResult>) {
    startTransition(async () => {
      const result = await action();
      setMessage(result);
      if (result.success) router.refresh();
    });
  }

  return (
    <div className="flex min-h-0 flex-col gap-8 p-6">
      <div className="flex flex-col gap-2">
        <div className="flex flex-wrap items-center gap-2">
          <WalletCards className="size-5" aria-hidden="true" />
          <h1 className="text-2xl font-semibold">Economy wallet</h1>
          <Badge variant="secondary">Safe reads</Badge>
        </div>
        <p className="text-sm text-muted-foreground">
          Wallet balances, provenance, requests, and value-movement readiness remain explicit.
        </p>
      </div>

      {data.issue ? (
        <Alert variant="destructive">
          <AlertTriangle className="size-4" />
          <AlertTitle>Economy data is unavailable</AlertTitle>
          <AlertDescription>{data.issue}</AlertDescription>
        </Alert>
      ) : null}

      {message ? (
        <Alert variant={message.success ? 'default' : 'destructive'}>
          {message.success ? <ShieldCheck className="size-4" /> : <AlertTriangle className="size-4" />}
          <AlertTitle>{message.success ? 'Recorded safely' : 'Action not completed'}</AlertTitle>
          <AlertDescription>{message.message}</AlertDescription>
        </Alert>
      ) : null}

      <section className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4" aria-label="Wallet balances">
        <BalanceCard label="Withdrawable HardCoin" value={data.wallet?.withdrawableHard} />
        <BalanceCard label="Available HardCoin" value={data.wallet?.availableHardToSpend} />
        <BalanceCard label="SoftCoin" value={data.wallet?.availableSoftToSpend ?? data.wallet?.soft} />
        <BalanceCard label="Pending / held HardCoin" value={(data.wallet?.pendingHard ?? 0) + (data.wallet?.heldHard ?? 0)} />
      </section>

      <section className="grid grid-cols-1 gap-5 xl:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-lg">
              <Landmark className="size-4" aria-hidden="true" />
              Payout request
            </CardTitle>
            <CardDescription>
              A request is reviewable evidence only. It does not reserve, dispatch, or transfer value.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <form
              className="flex flex-col gap-4"
              onSubmit={(event) => {
                event.preventDefault();
                execute(() => submitPayoutRequestAction(Number(payoutAmount), crypto.randomUUID()));
              }}
            >
              <label className="flex flex-col gap-2 text-sm font-medium" htmlFor="economy-payout-amount">
                HardCoin units
                <Input
                  id="economy-payout-amount"
                  inputMode="numeric"
                  min="1"
                  name="hardCoinUnits"
                  onChange={(event) => setPayoutAmount(event.target.value)}
                  required
                  type="number"
                  value={payoutAmount}
                />
              </label>
              <Button disabled={pending} type="submit">
                Record payout request
              </Button>
              <p className="text-sm text-muted-foreground">
                {payoutDiagnostic || 'Execution is assessed independently after review.'}
              </p>
            </form>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-lg">
              <ArrowRightLeft className="size-4" aria-hidden="true" />
              Hard-to-soft conversion
            </CardTitle>
            <CardDescription>
              This command remains disabled until the signed policy and capability predicates are ready.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <form
              className="flex flex-col gap-4"
              onSubmit={(event) => {
                event.preventDefault();
                execute(() => convertHardToSoftAction(Number(conversionAmount), crypto.randomUUID()));
              }}
            >
              <label className="flex flex-col gap-2 text-sm font-medium" htmlFor="economy-conversion-amount">
                HardCoin units
                <Input
                  disabled={!canConvert}
                  id="economy-conversion-amount"
                  inputMode="numeric"
                  min="1"
                  name="principalHardCoinUnits"
                  onChange={(event) => setConversionAmount(event.target.value)}
                  required
                  type="number"
                  value={conversionAmount}
                />
              </label>
              <Button disabled={pending || !canConvert} type="submit">
                {canConvert ? 'Convert HardCoin' : 'Conversion disabled'}
              </Button>
              <p className="text-sm text-muted-foreground">
                {conversionDiagnostic || 'Capability readiness has not been reported.'}
              </p>
            </form>
          </CardContent>
        </Card>
      </section>

      <section className="grid grid-cols-1 gap-5 2xl:grid-cols-2">
        <DataTable
          columns={['Request', 'Amount', 'State', 'Updated', 'Action']}
          title="Payout requests"
          empty="No payout requests have been recorded."
        >
          {data.payoutRequests.map((request) => (
            <TableRow key={request.id}>
              <TableCell className="font-mono text-sm">{request.id || '—'}</TableCell>
              <TableCell>{amount(request.hardCoinUnits)}</TableCell>
              <TableCell><Badge variant={requestBadgeVariant(request.state)}>{request.state || 'Unknown'}</Badge></TableCell>
              <TableCell>{timestamp(request.updatedAt)}</TableCell>
              <TableCell className="text-right">
                {request.state === 'Submitted' ? (
                  <Button
                    disabled={pending || !request.id}
                    onClick={() => execute(() => cancelPayoutRequestAction(request.id!))}
                    size="sm"
                    type="button"
                    variant="outline"
                  >
                    Cancel
                  </Button>
                ) : null}
              </TableCell>
            </TableRow>
          ))}
        </DataTable>

        <DataTable
          columns={['Operation', 'Amount', 'State', 'Updated', '']}
          title="Payout operations"
          empty="No payout operations have been created."
        >
          {data.payoutOperations.map((operation) => (
            <TableRow key={operation.id}>
              <TableCell className="font-mono text-sm">{operation.id || '—'}</TableCell>
              <TableCell>{amount(operation.hardCoinUnits)}</TableCell>
              <TableCell><Badge variant={operationBadgeVariant(operation.state)}>{operation.state || 'Unknown'}</Badge></TableCell>
              <TableCell>{timestamp(operation.updatedAt)}</TableCell>
              <TableCell />
            </TableRow>
          ))}
        </DataTable>
      </section>

      <DataTable
        columns={['Recorded', 'Template', 'Provenance', 'Side', 'Amount']}
        title="Journal history"
        empty="No wallet journal entries are available."
      >
        {data.transactions.map((transaction) => (
          <TableRow key={`${transaction.journalEntryId}-${transaction.journalSequence}`}>
            <TableCell>{timestamp(transaction.recordedAt)}</TableCell>
            <TableCell>{transaction.templateKind || 'Unknown'}</TableCell>
            <TableCell>{transaction.provenance || '—'}</TableCell>
            <TableCell>{transaction.side || '—'}</TableCell>
            <TableCell>{amount(transaction.amountUnits)} {transaction.currency || ''}</TableCell>
          </TableRow>
        ))}
      </DataTable>
    </div>
  );
}

function BalanceCard({ label, value }: { label: string; value: number | null | undefined }) {
  return (
    <Card>
      <CardContent className="flex flex-col gap-2 p-4">
        <span className="text-sm text-muted-foreground">{label}</span>
        <strong className="text-2xl font-semibold">{amount(value)}</strong>
      </CardContent>
    </Card>
  );
}

function DataTable({
  children,
  columns,
  empty,
  title,
}: {
  children: ReactNode;
  columns: string[];
  empty: string;
  title: string;
}) {
  const rows = children as ReactNode[];
  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg">{title}</CardTitle>
      </CardHeader>
      <CardContent>
        {rows.length === 0 ? (
          <p className="text-sm text-muted-foreground">{empty}</p>
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                {columns.map((column, index) => (
                  <TableHead key={`${column}-${index}`} className={index === columns.length - 1 ? 'text-right' : undefined}>
                    {column}
                  </TableHead>
                ))}
              </TableRow>
            </TableHeader>
            <TableBody>{children}</TableBody>
          </Table>
        )}
      </CardContent>
    </Card>
  );
}

'use client';

import { Elements, PaymentElement, useElements, useStripe } from '@stripe/react-stripe-js';
import { loadStripe } from '@stripe/stripe-js';
import { Button } from '@game-guild/ui/components/button';
import { useLocale, useTranslations } from 'next-intl';
import { useMemo, useState, type FormEvent } from 'react';
import { EconomyActionNotice } from './economy-ui';

function TopUpConfirmationForm({ topUpId }: { topUpId: string }) {
  const stripe = useStripe();
  const elements = useElements();
  const locale = useLocale();
  const t = useTranslations('economy');
  const [pending, setPending] = useState(false);
  const [result, setResult] = useState<{ success: boolean; message: string } | null>(null);

  async function submit(event: FormEvent) {
    event.preventDefault();
    if (!stripe || !elements) return;
    setPending(true);
    const confirmation = await stripe.confirmPayment({
      elements,
      confirmParams: { return_url: `${window.location.origin}/${locale}/workspace/economy/top-ups/${topUpId}` },
      redirect: 'if_required',
    });
    setResult(confirmation.error
      ? { success: false, message: confirmation.error.message ?? t('topUps.confirmationFailed') }
      : { success: true, message: t('topUps.confirmationPending') });
    setPending(false);
  }

  return (
    <form className="space-y-4 rounded-lg border p-4" onSubmit={submit}>
      <PaymentElement />
      <Button disabled={!stripe || !elements || pending} type="submit">{t('topUps.confirm')}</Button>
      <EconomyActionNotice result={result} />
    </form>
  );
}

export function TopUpStripePaymentElement({ clientSecret, publishableKey, topUpId }: {
  clientSecret: string;
  publishableKey: string;
  topUpId: string;
}) {
  const stripe = useMemo(() => loadStripe(publishableKey), [publishableKey]);
  return (
    <Elements options={{ clientSecret, appearance: { theme: 'stripe' } }} stripe={stripe}>
      <TopUpConfirmationForm topUpId={topUpId} />
    </Elements>
  );
}

"use client";

import { useState, type FormEvent } from "react";
import { useAuth } from "@game-guild/client/react";
import { Link } from "@/i18n/navigation";
import { requestEmailCode } from "@/lib/auth/email-code-request";
import { Button } from "@game-guild/ui/components/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@game-guild/ui/components/card";
import {
  Field,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@game-guild/ui/components/field";
import { Input } from "@game-guild/ui/components/input";
import { AlertCircle, Loader2 } from "lucide-react";
import { MfaChallengeForm } from "./auth/mfa-challenge-form";

export interface EmailCodeMessages {
  request: {
    title: string;
    description: string;
    emailLabel: string;
    emailPlaceholder: string;
    submit: string;
    pending: string;
    successTitle: string;
    successDescription: string;
    error: string;
  };
  consume: {
    title: string;
    description: string;
    codeLabel: string;
    codePlaceholder: string;
    submit: string;
    pending: string;
    useDifferentEmail: string;
    errorTitle: string;
    error: string;
  };
  backToSignIn: string;
}

export function EmailCodeFlow({
  redirectTo = "/",
  apiUrl,
  messages,
}: {
  redirectTo?: string;
  apiUrl: string;
  messages: EmailCodeMessages;
}) {
  const [email, setEmail] = useState("");
  const [stage, setStage] = useState<"request" | "consume">("request");

  return stage === "consume" ? (
    <EmailCodeConsumer
      email={email}
      redirectTo={redirectTo}
      messages={messages}
      onUseDifferentEmail={() => setStage("request")}
    />
  ) : (
    <EmailCodeRequestForm
      email={email}
      onEmailChange={setEmail}
      onSubmitted={() => setStage("consume")}
      apiUrl={apiUrl}
      messages={messages}
    />
  );
}

function EmailCodeRequestForm({
  email,
  onEmailChange,
  onSubmitted,
  apiUrl,
  messages,
}: {
  email: string;
  onEmailChange: (value: string) => void;
  onSubmitted: () => void;
  apiUrl: string;
  messages: EmailCodeMessages;
}) {
  const [pending, setPending] = useState(false);
  const [failed, setFailed] = useState(false);

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setPending(true);
    setFailed(false);

    try {
      const sent = await requestEmailCode(email, apiUrl);
      if (!sent) {
        setFailed(true);
        return;
      }

      onSubmitted();
    } catch {
      setFailed(true);
    } finally {
      setPending(false);
    }
  }

  return (
    <Card className="border-white/10 bg-slate-900/85 text-white shadow-2xl shadow-sky-950/30 backdrop-blur">
      <CardHeader className="text-center">
        <CardTitle className="text-2xl">
          <h1>{messages.request.title}</h1>
        </CardTitle>
        <CardDescription className="text-slate-300">
          {messages.request.description}
        </CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={(event) => void handleSubmit(event)}>
          <FieldGroup>
            <Field>
              <FieldLabel htmlFor="email-code-email">
                {messages.request.emailLabel}
              </FieldLabel>
              <Input
                id="email-code-email"
                name="email"
                type="email"
                placeholder={messages.request.emailPlaceholder}
                autoComplete="email"
                required
                value={email}
                disabled={pending}
                onChange={(event) => onEmailChange(event.currentTarget.value)}
                className="h-10 border-white/10 bg-white/5 text-white placeholder:text-slate-500"
                aria-invalid={failed}
                aria-describedby={
                  failed ? "email-code-request-error" : undefined
                }
              />
              {failed ? (
                <FieldError id="email-code-request-error" role="alert">
                  <AlertCircle
                    className="mr-1 inline size-4"
                    aria-hidden="true"
                  />
                  {messages.request.error}
                </FieldError>
              ) : null}
            </Field>
            <Field>
              <Button
                type="submit"
                size="lg"
                disabled={pending || !email.trim()}
              >
                {pending ? (
                  <Loader2
                    className="mr-2 size-4 animate-spin"
                    aria-hidden="true"
                  />
                ) : null}
                {pending ? messages.request.pending : messages.request.submit}
              </Button>
              <FieldDescription className="text-center text-slate-300">
                <Link
                  href="/sign-in"
                  className="text-sky-200 underline-offset-4 hover:underline"
                >
                  {messages.backToSignIn}
                </Link>
              </FieldDescription>
            </Field>
          </FieldGroup>
        </form>
      </CardContent>
    </Card>
  );
}

function EmailCodeConsumer({
  email,
  redirectTo,
  messages,
  onUseDifferentEmail,
}: {
  email: string;
  redirectTo: string;
  messages: EmailCodeMessages;
  onUseDifferentEmail: () => void;
}) {
  const { signIn, mfaChallenge } = useAuth();
  const [code, setCode] = useState("");
  const [pending, setPending] = useState(false);
  const [failed, setFailed] = useState(false);

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setPending(true);
    setFailed(false);

    try {
      await signIn("credentials", {
        emailCode: code,
        emailCodeEmail: email,
        redirectTo,
      });
      setPending(false);
    } catch {
      setPending(false);
      setFailed(true);
    }
  }

  if (mfaChallenge) {
    return <MfaChallengeForm redirectTo={redirectTo} />;
  }

  return (
    <Card className="border-white/10 bg-slate-900/85 text-white shadow-2xl shadow-sky-950/30 backdrop-blur">
      <CardHeader className="text-center">
        <CardTitle className="text-2xl">
          <h1>
            {failed ? messages.consume.errorTitle : messages.consume.title}
          </h1>
        </CardTitle>
        <CardDescription className="text-slate-300" role={failed ? "alert" : undefined}>
          {failed
            ? messages.consume.error
            : `${messages.consume.description} ${email}`}
        </CardDescription>
      </CardHeader>
      <CardContent>
        {failed ? (
          <div className="flex flex-col gap-4 text-center">
            <AlertCircle
              className="mx-auto size-5 text-amber-200"
              aria-hidden="true"
            />
            <button
              type="button"
              onClick={onUseDifferentEmail}
              className="text-sky-200 underline-offset-4 hover:underline"
            >
              {messages.consume.useDifferentEmail}
            </button>
            <Link
              href="/sign-in"
