"use client";

import { PostCard } from "@/components/feed/post-card";
import { loadSocialFeedPage } from "@/lib/feed/pagination";
import type { FeedScope, SocialFeedItem } from "@/lib/feed/contracts";
import { Bookmark, Gamepad2, Loader2, Users } from "lucide-react";
import * as React from "react";

const EMPTY = {
  saved: {
    title: "No saved posts yet",
    detail: "Posts you save will appear here.",
    icon: Bookmark,
  },
  following: {
    title: "Your following feed is quiet",
    detail: "Follow creators to see their latest work here.",
    icon: Users,
  },
  "for-you": {
    title: "Your feed is ready for its first build",
    detail:
      "Follow creators or share what you are making. Project updates and community sessions will appear here.",
    icon: Gamepad2,
  },
  community: {
    title: "No community activity yet",
    detail: "Public builds and Testing Lab sessions will appear here.",
    icon: Gamepad2,
  },
} satisfies Record<
  FeedScope,
  { title: string; detail: string; icon: typeof Gamepad2 }
>;

export function InfinitePostFeed({
  scope,
  tag = null,
  initialItems,
  initialNextCursor,
  currentUserId,
  publishedItem = null,
  publishedIdentity,
}: {
  scope: FeedScope;
  tag?: string | null;
  initialItems: SocialFeedItem[];
  initialNextCursor: string | null;
  currentUserId?: string | null;
  publishedItem?: SocialFeedItem | null;
  publishedIdentity?: string;
}): React.JSX.Element {
  const feedIdentity = `${scope}:${tag ?? ""}`;
  const [items, setItems] = React.useState(initialItems);
  const [nextCursor, setNextCursor] = React.useState(initialNextCursor);
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState(false);
  const sentinelRef = React.useRef<HTMLDivElement | null>(null);
  const cursorRef = React.useRef(initialNextCursor);
  const loadingRef = React.useRef(false);
  const seenRef = React.useRef(new Set(initialItems.map((item) => item.id)));
  const requestRef = React.useRef(0);
  const activeControllerRef = React.useRef<AbortController | null>(null);
  const publishedItemRef = React.useRef<SocialFeedItem | null>(null);
  const identityRef = React.useRef(feedIdentity);

  React.useEffect(() => {
    activeControllerRef.current?.abort();
    activeControllerRef.current = null;
    loadingRef.current = false;
    setLoading(false);
    if (identityRef.current !== feedIdentity) {
      identityRef.current = feedIdentity;
      publishedItemRef.current = null;
    }
    const retained = publishedItemRef.current;
    setItems(retained && !initialItems.some((item) => item.id === retained.id) ? [retained, ...initialItems] : initialItems);
    setNextCursor(initialNextCursor);
    setError(false);
    cursorRef.current = initialNextCursor;
    seenRef.current = new Set([...(retained ? [retained] : []), ...initialItems].map((item) => item.id));
    requestRef.current += 1;
  }, [feedIdentity, initialItems, initialNextCursor, scope, tag]);

  React.useEffect(() => {
    if (!publishedItem || (publishedIdentity ?? feedIdentity) !== feedIdentity || seenRef.current.has(publishedItem.id)) return;
    publishedItemRef.current = publishedItem;
    seenRef.current.add(publishedItem.id);
    setItems((current) => [publishedItem, ...current]);
  }, [feedIdentity, publishedIdentity, publishedItem]);

  React.useEffect(
    () => () => activeControllerRef.current?.abort(),
    [],
  );

  const loadMore = React.useCallback(() => {
    if (loadingRef.current || cursorRef.current === null) return;
    const cursor = cursorRef.current;
    const requestId = ++requestRef.current;
    const controller = new AbortController();
    activeControllerRef.current = controller;
    loadingRef.current = true;
    setLoading(true);
    setError(false);
    void loadSocialFeedPage({ scope, cursor, tag, signal: controller.signal })
      .then((page) => {
        if (requestId !== requestRef.current) return;
        const fresh = page.items.filter(
          (item) => !seenRef.current.has(item.id),
        );
        fresh.forEach((item) => seenRef.current.add(item.id));
        setItems((current) => [...current, ...fresh]);
        cursorRef.current = page.nextCursor;
        setNextCursor(page.nextCursor);
      })
      .catch(() => {
        if (controller.signal.aborted || requestId !== requestRef.current) return;
        setError(true);
      })
      .finally(() => {
        if (controller.signal.aborted || requestId !== requestRef.current) return;
        if (activeControllerRef.current === controller) activeControllerRef.current = null;
        loadingRef.current = false;
        setLoading(false);
      });
  }, [scope, tag]);

  React.useEffect(() => {
    const node = sentinelRef.current;
    if (!node || typeof IntersectionObserver === "undefined") return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting) loadMore();
      },
      { rootMargin: "600px 0px" },
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [loadMore]);

  const empty = EMPTY[scope];
  const EmptyIcon = empty.icon;
  return (
    <div>
      {items.map((item) => (
        <PostCard
          key={`${item.kind}-${item.id}`}
          item={item}
          currentUserId={currentUserId}
        />
      ))}

      {items.length === 0 && !loading ? (
        <div className="mx-4 my-8 flex flex-col items-center rounded-2xl bg-card px-6 py-12 text-center text-card-foreground sm:mx-6">
          <span className="flex size-11 items-center justify-center rounded-xl bg-primary/10 text-primary">
            <EmptyIcon className="size-5" aria-hidden="true" />
          </span>
          <p className="mt-4 text-sm font-semibold text-foreground">
            {empty.title}
          </p>
          <p className="mt-1 max-w-sm text-sm leading-6 text-muted-foreground">
            {empty.detail}
          </p>
        </div>
      ) : null}

      <div ref={sentinelRef} aria-hidden="true" className="h-px" />

      {loading ? (
        <p className="flex items-center justify-center gap-2 py-5 text-sm text-muted-foreground">
          <Loader2 className="size-4 animate-spin" aria-hidden="true" />
          Loading more…
        </p>
      ) : error ? (
        <div className="flex justify-center py-5">
          <button
            type="button"
            onClick={loadMore}
            className="rounded-lg bg-accent px-3 py-2 text-sm font-semibold text-foreground hover:bg-accent/80"
          >
            Try again
          </button>
        </div>
      ) : nextCursor === null && items.length > 0 ? (
        <p className="py-5 text-center text-xs text-muted-foreground/70">
          You&apos;re all caught up.
        </p>
      ) : null}
    </div>
  );
}

"use client";

import {
  createPostComment,
  deletePostComment,
  loadPostCommentRepliesPageAction,
  loadPostCommentsPageAction,
  updatePostComment,
} from "@/lib/feed/actions";
import type { PostComment } from "@/lib/feed/contracts";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@game-guild/ui/components/alert-dialog";
import { Button } from "@game-guild/ui/components/button";
import {
  Drawer,
  DrawerContent,
  DrawerDescription,
  DrawerHeader,
  DrawerTitle,
} from "@game-guild/ui/components/drawer";
import { Textarea } from "@game-guild/ui/components/textarea";
import { TurnstileWidget } from "@/components/antibot/turnstile-widget";
import { Loader2, Send } from "lucide-react";
import Image from "next/image";
import * as React from "react";
import { toast } from "sonner";

const COMMENT_PAGE_SIZE = 10;
const REPLY_PAGE_SIZE = 2;

function useResponsiveMobile() {
  const [mobile, setMobile] = React.useState(() => typeof window !== "undefined" && window.innerWidth < 768);
  React.useEffect(() => {
    if (typeof window.matchMedia !== "function") return;
    const query = window.matchMedia("(max-width: 767px)");
    const update = () => setMobile(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);
  return mobile;
}

function initials(name: string, id: string) {
  const parts = (name.trim() || id.replace(/[-_]+/g, " ") || "GG").split(/\s+/).filter(Boolean);
  return parts.length > 1
    ? `${parts[0]?.[0] ?? ""}${parts.at(-1)?.[0] ?? ""}`.toUpperCase()
    : parts[0]?.slice(0, 2).toUpperCase() || "GG";
}

function CommentAvatar({ comment }: { comment: PostComment }) {
  return (
    <span className="flex size-9 shrink-0 items-center justify-center overflow-hidden rounded-full bg-muted text-xs font-bold text-foreground">
      {comment.authorAvatarUrl ? (
        <Image src={comment.authorAvatarUrl} alt="" width={36} height={36} unoptimized className="size-9 object-cover" />
      ) : initials(comment.authorName, comment.authorId)}
    </span>
  );
}

function findComment(comments: PostComment[], id: string): PostComment | null {
  for (const comment of comments) {
    if (comment.id === id) return comment;
    const child = findComment(comment.replies, id);
    if (child) return child;
  }
  return null;
}

function flattenComments(comments: PostComment[]): PostComment[] {
  return comments.flatMap((comment) => [{ ...comment, replies: [] }, ...flattenComments(comment.replies)]);
}

function appendComments(current: PostComment[], incoming: PostComment[]) {
  const next = structuredClone(current) as PostComment[];
  for (const comment of flattenComments(incoming)) {
    if (findComment(next, comment.id)) continue;
    const parent = comment.parentCommentId ? findComment(next, comment.parentCommentId) : null;
    if (parent) parent.replies.push(comment);
    else next.push(comment);
  }
  return next;
}

function replaceComment(comments: PostComment[], replacement: PostComment): PostComment[] {
  return comments.map((comment) => {
    if (comment.id === replacement.id) {
      return { ...comment, ...replacement, replies: replacement.replies?.length ? replacement.replies : comment.replies };
    }
    return { ...comment, replies: replaceComment(comment.replies, replacement) };
  });
}

function removeComment(comments: PostComment[], commentId: string): PostComment[] {
  return comments
    .filter((comment) => comment.id !== commentId)
    .map((comment) => ({ ...comment, replies: removeComment(comment.replies, commentId) }));
}

function seedReplyOffsets(comments: PostComment[], current: Record<string, number | null> = {}) {
  const next = { ...current };
  for (const comment of comments) {
    if (!(comment.id in next)) {
      next[comment.id] = comment.replies.length >= REPLY_PAGE_SIZE ? comment.replies.length : null;
    }
    Object.assign(next, seedReplyOffsets(comment.replies, next));
  }
  return next;
}

function CommentThread({
  comments,
  currentUserId,
  replyNextSkips,
  replyPendingIds,
  editingId,
  editValue,
  editPending,
  deletePendingIds,
  onReply,
  onMoreReplies,
  onBeginEdit,
  onEditValue,
  onCancelEdit,
  onSaveEdit,
  onDelete,
}: {
  comments: PostComment[];
  currentUserId?: string | null;
  replyNextSkips: Record<string, number | null>;
  replyPendingIds: Set<string>;
  editingId: string | null;
  editValue: string;
  editPending: boolean;
  deletePendingIds: Set<string>;
  onReply: (comment: PostComment) => void;
  onMoreReplies: (comment: PostComment) => void;
  onBeginEdit: (comment: PostComment) => void;
  onEditValue: (value: string) => void;
  onCancelEdit: () => void;
  onSaveEdit: (comment: PostComment) => void;
  onDelete: (comment: PostComment) => void;
}) {
  return (
    <div className="space-y-4">
      {comments.map((comment) => {
        const nextReplySkip = comment.id in replyNextSkips
          ? replyNextSkips[comment.id]
          : comment.replies.length >= REPLY_PAGE_SIZE ? comment.replies.length : null;
        const replyPending = replyPendingIds.has(comment.id);
        const deletePending = deletePendingIds.has(comment.id);
        return (
          <div key={comment.id} className="flex gap-3">
            <CommentAvatar comment={comment} />
            <div className="min-w-0 flex-1">
              <div className="rounded-xl bg-accent/45 px-3 py-2.5">
                <p className="text-xs font-semibold text-foreground">{comment.authorName}</p>
                {editingId === comment.id ? (
                  <div className="mt-2 space-y-2">
                    <Textarea
                      aria-label="Edit comment"
                      rows={2}
                      maxLength={2000}
                      autoFocus
                      value={editValue}
                      onChange={(event) => onEditValue(event.target.value)}
                    />
                    <div className="flex justify-end gap-2">
                      <Button type="button" size="xs" variant="ghost" disabled={editPending} onClick={onCancelEdit}>Cancel</Button>
                      <Button type="button" size="xs" disabled={editPending || !editValue.trim()} aria-label="Save comment" onClick={() => onSaveEdit(comment)}>
                        {editPending ? "Saving…" : "Save"}
                      </Button>
                    </div>
                  </div>
                ) : (
                  <p className="mt-0.5 whitespace-pre-wrap text-sm leading-5 text-foreground">{comment.content}</p>
                )}
              </div>
              <button type="button" aria-label={`Reply to ${comment.authorName}`} onClick={() => onReply(comment)} className="mt-1 px-2 text-xs text-muted-foreground hover:text-foreground">Reply</button>
              {currentUserId === comment.authorId ? (
                <>
                  <button type="button" aria-label={`Edit comment by ${comment.authorName}`} onClick={() => onBeginEdit(comment)} className="mt-1 px-2 text-xs text-muted-foreground hover:text-foreground">Edit</button>
                  <AlertDialog>
                    <AlertDialogTrigger
                      render={
                        <button
                          type="button"
                          aria-label={`Delete comment by ${comment.authorName}`}
                          className="mt-1 px-2 text-xs text-muted-foreground hover:text-destructive"
                        />
                      }
                    >
                      Delete
                    </AlertDialogTrigger>
                    <AlertDialogContent>
                      <AlertDialogHeader>
                        <AlertDialogTitle>Delete comment?</AlertDialogTitle>
                        <AlertDialogDescription>This permanently removes your comment and its replies.</AlertDialogDescription>
                      </AlertDialogHeader>
                      <AlertDialogFooter>
                        <AlertDialogCancel disabled={deletePending}>Cancel</AlertDialogCancel>
                        <AlertDialogAction
                          disabled={deletePending}
                          aria-label="Delete comment"
                          onClick={(event) => {
                            event.preventDefault();
                            onDelete(comment);
                          }}
                        >
                          {deletePending ? "Deleting…" : "Delete"}
                        </AlertDialogAction>
                      </AlertDialogFooter>
                    </AlertDialogContent>
                  </AlertDialog>
                </>
              ) : null}
              {comment.replies.length > 0 ? (
                <div className="mt-3 border-l border-border/50 pl-3">
                  <CommentThread
                    comments={comment.replies}
                    currentUserId={currentUserId}
                    replyNextSkips={replyNextSkips}
                    replyPendingIds={replyPendingIds}
                    editingId={editingId}
                    editValue={editValue}
                    editPending={editPending}
                    deletePendingIds={deletePendingIds}
                    onReply={onReply}
                    onMoreReplies={onMoreReplies}
                    onBeginEdit={onBeginEdit}
                    onEditValue={onEditValue}
                    onCancelEdit={onCancelEdit}
                    onSaveEdit={onSaveEdit}
                    onDelete={onDelete}
                  />
                </div>
              ) : null}
              {nextReplySkip !== null ? (
                <button type="button" disabled={replyPending} aria-label={`Load more replies to ${comment.authorName}`} onClick={() => onMoreReplies(comment)} className="mt-2 text-xs font-medium text-primary disabled:opacity-60">
                  {replyPending ? "Loading…" : "Load more replies"}
                </button>
              ) : null}
            </div>
          </div>
        );
      })}
    </div>
  );
}

function CommentsPanel({
  postId,
  currentUserId,
  onCommentCountChange,
  onCommentCountReconciled,
  onCommentCountInvalidated,
}: {
  postId: string;
  currentUserId?: string | null;
  onCommentCountChange?: (change: number) => void;
  onCommentCountReconciled?: (count: number) => void;
  onCommentCountInvalidated?: () => void;
}) {
  const [comments, setComments] = React.useState<PostComment[]>([]);
  const [nextSkip, setNextSkip] = React.useState<number | null>(null);
  const [loading, setLoading] = React.useState(true);
  const [pagePending, setPagePending] = React.useState(false);
  const [commentPending, setCommentPending] = React.useState(false);
  const [commentText, setCommentText] = React.useState("");
  const [replyingTo, setReplyingTo] = React.useState<PostComment | null>(null);
  const [replyNextSkips, setReplyNextSkips] = React.useState<Record<string, number | null>>({});
  const [replyPendingIds, setReplyPendingIds] = React.useState<Set<string>>(new Set());
  const [editingId, setEditingId] = React.useState<string | null>(null);
  const [editValue, setEditValue] = React.useState("");
  const [editPending, setEditPending] = React.useState(false);
  const [deletePendingIds, setDeletePendingIds] = React.useState<Set<string>>(new Set());
  const [error, setError] = React.useState<string | null>(null);
  const [turnstileToken, setTurnstileToken] = React.useState<string | null>(null);
  const pagePendingRef = React.useRef(false);
  const commentPendingRef = React.useRef(false);
  const editPendingRef = React.useRef(false);
  const deletePendingIdsRef = React.useRef(new Set<string>());
  const replyPendingIdsRef = React.useRef(new Set<string>());

  React.useEffect(() => {
    let active = true;
    void loadPostCommentsPageAction(postId, 0, COMMENT_PAGE_SIZE)
      .then((page) => {
        if (!active) return;
        setComments(page.items);
        setReplyNextSkips(seedReplyOffsets(page.items));
        setNextSkip(page.nextSkip);
      })
      .catch((reason) => {
        if (!active) return;
        const message = reason instanceof Error ? reason.message : "Comments could not be loaded.";
        setError(message);
        toast.error(message);
      })
      .finally(() => active && setLoading(false));
    return () => { active = false; };
  }, [postId]);

  async function loadMore() {
    if (nextSkip === null || pagePendingRef.current) return;
    pagePendingRef.current = true;
    setPagePending(true);
    setError(null);
    try {
      const page = await loadPostCommentsPageAction(postId, nextSkip, COMMENT_PAGE_SIZE);
      setComments((current) => appendComments(current, page.items));
      setNextSkip(page.nextSkip);
    } catch (reason) {
      const message = reason instanceof Error ? reason.message : "More comments could not be loaded.";
      setError(message);
      toast.error(message);
    } finally {
      pagePendingRef.current = false;
      setPagePending(false);
    }
  }

  async function loadMoreReplies(comment: PostComment) {
    if (replyPendingIdsRef.current.has(comment.id)) return;
    const skip = comment.id in replyNextSkips ? replyNextSkips[comment.id] : comment.replies.length;
    if (skip === null) return;
    replyPendingIdsRef.current.add(comment.id);
    setReplyPendingIds(new Set(replyPendingIdsRef.current));
    setError(null);
    try {
      const page = await loadPostCommentRepliesPageAction(postId, comment.id, skip, REPLY_PAGE_SIZE);
      setComments((current) => appendComments(current, page.items));
      setReplyNextSkips((current) => seedReplyOffsets(page.items, { ...current, [comment.id]: page.nextSkip }));
    } catch (reason) {
      const message = reason instanceof Error ? reason.message : "More replies could not be loaded.";
      setError(message);
      toast.error(message);
    } finally {
      replyPendingIdsRef.current.delete(comment.id);
      setReplyPendingIds(new Set(replyPendingIdsRef.current));
    }
  }

  async function submitComment(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const value = commentText.trim();
    if (!value || commentPendingRef.current) return;
    commentPendingRef.current = true;
    setCommentPending(true);
    setError(null);
    const spentToken = turnstileToken;
    try {
      const persisted = await createPostComment(postId, {
        content: value,
        ...(replyingTo ? { parentCommentId: replyingTo.id } : {}),
        turnstileToken,
      });
      setComments((current) => {
        if (!persisted.parentCommentId) return [persisted, ...current];
        return appendComments(current, [persisted]);
      });
      setCommentText("");
      setReplyingTo(null);
      onCommentCountChange?.(1);
    } catch (reason) {
      const message = reason instanceof Error ? reason.message : "Comment could not be published.";
      setError(message);
      toast.error(message);
    } finally {
      // Single-use token: consumed by this submit regardless of outcome —
      // unless the widget already re-issued a fresh one during the await.
      setTurnstileToken((current) => (current === spentToken ? null : current));
      commentPendingRef.current = false;
      setCommentPending(false);
    }
  }

  async function saveEdit(comment: PostComment) {
    const value = editValue.trim();
    if (!value || editPendingRef.current) return;
    editPendingRef.current = true;
    setEditPending(true);
    setError(null);
    try {
      const persisted = await updatePostComment(postId, comment.id, value);
      setComments((current) => replaceComment(current, persisted));
      setEditingId(null);
      setEditValue("");
    } catch (reason) {
      const message = reason instanceof Error ? reason.message : "Comment could not be updated.";
      setError(message);
      toast.error(message);
    } finally {
      editPendingRef.current = false;
      setEditPending(false);
    }
  }

  async function remove(comment: PostComment) {
    if (deletePendingIdsRef.current.has(comment.id)) return;
    deletePendingIdsRef.current.add(comment.id);
    setDeletePendingIds(new Set(deletePendingIdsRef.current));
    setError(null);
    try {
      const result = await deletePostComment(postId, comment.id);
      setComments((current) => removeComment(current, comment.id));
      if (result.kind === "confirmed") onCommentCountReconciled?.(result.commentsCount);
      else onCommentCountInvalidated?.();
    } catch (reason) {
      const message = reason instanceof Error ? reason.message : "Comment could not be deleted.";
      setError(message);
      toast.error(message);
    } finally {
      deletePendingIdsRef.current.delete(comment.id);
      setDeletePendingIds(new Set(deletePendingIdsRef.current));
    }
  }

  return (
    <div className="flex min-h-0 flex-1 flex-col px-4 pb-4 sm:px-0 sm:pb-0">
      <div className="min-h-0 flex-1 overflow-y-auto py-2">
        {loading ? (
          <p className="flex items-center gap-2 text-sm text-muted-foreground"><Loader2 className="size-4 animate-spin" /> Loading comments…</p>
        ) : comments.length > 0 ? (
          <CommentThread
            comments={comments}
            currentUserId={currentUserId}
            replyNextSkips={replyNextSkips}
            replyPendingIds={replyPendingIds}
            editingId={editingId}
            editValue={editValue}
            editPending={editPending}
            deletePendingIds={deletePendingIds}
            onReply={setReplyingTo}
            onMoreReplies={(comment) => void loadMoreReplies(comment)}
            onBeginEdit={(comment) => {
              setEditingId(comment.id);
              setEditValue(comment.content);
            }}
            onEditValue={setEditValue}
            onCancelEdit={() => setEditingId(null)}
            onSaveEdit={(comment) => void saveEdit(comment)}
            onDelete={(comment) => void remove(comment)}
          />
        ) : <p className="text-sm text-muted-foreground">No comments yet.</p>}
        {nextSkip !== null ? (
          <Button type="button" variant="ghost" size="sm" disabled={pagePending} onClick={() => void loadMore()} className="mt-4 w-full">
            {pagePending ? "Loading…" : "Load more comments"}
          </Button>
        ) : null}
      </div>
      {error ? <p role="alert" className="mt-2 text-sm text-destructive">{error}</p> : null}
      <form onSubmit={submitComment} className="mt-4 flex items-end gap-2 border-t pt-4">
        <div className="min-w-0 flex-1">
          {replyingTo ? (
            <p className="mb-1 text-xs text-muted-foreground">
              Replying to {replyingTo.authorName}
              <button type="button" onClick={() => setReplyingTo(null)} className="ml-1 text-primary">Cancel</button>
            </p>
          ) : null}
          <Textarea
            value={commentText}
            onChange={(event) => setCommentText(event.target.value)}
            rows={1}
            maxLength={2000}
            placeholder={replyingTo ? "Add a reply…" : "Add a comment…"}
            className="min-h-10 resize-none"
          />
          <TurnstileWidget onToken={setTurnstileToken} id="post-comment-turnstile" />
        </div>
        <Button type="submit" size="icon" disabled={commentPending || !commentText.trim()} aria-label={replyingTo ? "Publish reply" : "Publish comment"}>
          <Send className="size-4" />
        </Button>
      </form>
    </div>
  );
}

export function PostComments({
  postId,
  currentUserId,
  open,
  onOpenChange,
  onCommentCountChange,
  onCommentCountReconciled,
  onCommentCountInvalidated,
}: {
  postId: string;
  currentUserId?: string | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onCommentCountChange?: (change: number) => void;
  onCommentCountReconciled?: (count: number) => void;
  onCommentCountInvalidated?: () => void;
}): React.JSX.Element {
  const isMobile = useResponsiveMobile();
  const panel = open ? (
    <CommentsPanel
      key={postId}
      postId={postId}
      currentUserId={currentUserId}
      onCommentCountChange={onCommentCountChange}
      onCommentCountReconciled={onCommentCountReconciled}
      onCommentCountInvalidated={onCommentCountInvalidated}
    />
  ) : null;

  return isMobile ? (
    <Drawer open={open} onOpenChange={onOpenChange}>
      <DrawerContent className="max-h-[85vh]">
        <DrawerHeader>
          <DrawerTitle>Comments</DrawerTitle>
          <DrawerDescription>Read the discussion or add a reply.</DrawerDescription>
        </DrawerHeader>
        {panel}
      </DrawerContent>
    </Drawer>
  ) : open ? (
    <section aria-label="Comments" className="mx-4 mt-3 border-t px-0 pb-4 pt-4 sm:mx-6">
      <div className="mb-3 flex items-center justify-between gap-3">
        <div>
          <h3 className="text-sm font-semibold text-foreground">Comments</h3>
          <p className="text-xs text-muted-foreground">Read the discussion or add a reply.</p>
        </div>
        <Button type="button" variant="ghost" size="xs" onClick={() => onOpenChange(false)}>Close</Button>
      </div>
      {panel}
    </section>
  ) : <></>;
}

"use client";

import { deleteSocialPost, updateSocialPost } from "@/lib/feed/actions";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@game-guild/ui/components/alert-dialog";
import { Button } from "@game-guild/ui/components/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@game-guild/ui/components/dialog";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@game-guild/ui/components/dropdown-menu";
import { Textarea } from "@game-guild/ui/components/textarea";
import { MoreHorizontal, Pencil, Trash2 } from "lucide-react";
import * as React from "react";
import { toast } from "sonner";

export function PostOwnerMenu({
  postId,
  content,
  canEdit,
  canDelete,
  onContentChange,
  onDeleted,
}: {
  postId: string;
  content: string;
  canEdit: boolean;
  canDelete: boolean;
  onContentChange: (content: string) => void;
  onDeleted: () => void;
}): React.JSX.Element | null {
  const [editOpen, setEditOpen] = React.useState(false);
  const [deleteOpen, setDeleteOpen] = React.useState(false);
  const [editContent, setEditContent] = React.useState(content);
  const [editPending, setEditPending] = React.useState(false);
  const [deletePending, setDeletePending] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  const editPendingRef = React.useRef(false);
  const deletePendingRef = React.useRef(false);

  if (!canEdit && !canDelete) return null;

  async function submitEdit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const next = editContent.trim();
    if (!next || editPendingRef.current) return;
    editPendingRef.current = true;
    setEditPending(true);
    setError(null);
    try {
      const state = await updateSocialPost(postId, next);
      onContentChange(state.content);
      setEditOpen(false);
      toast.success("Post updated.");
    } catch (reason) {
      const message = reason instanceof Error ? reason.message : "Post could not be updated.";
      setError(message);
      toast.error(message);
    } finally {
      editPendingRef.current = false;
      setEditPending(false);
    }
  }

  async function removePost() {
    if (deletePendingRef.current) return;
    deletePendingRef.current = true;
    setDeletePending(true);
    setError(null);
    try {
      await deleteSocialPost(postId);
      setDeleteOpen(false);
      onDeleted();
      toast.success("Post deleted.");
    } catch (reason) {
      const message = reason instanceof Error ? reason.message : "Post could not be deleted.";
      setError(message);
      toast.error(message);
    } finally {
      deletePendingRef.current = false;
      setDeletePending(false);
    }
  }

  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger
          render={<Button variant="ghost" size="icon-sm" aria-label="Post options" />}
        >
          <MoreHorizontal className="size-5" />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          {canEdit ? (
            <DropdownMenuItem
              onClick={() => {
                setError(null);
                setEditContent(content);
                setEditOpen(true);
              }}
            >
              <Pencil /> Edit post
            </DropdownMenuItem>
          ) : null}
          {canEdit && canDelete ? <DropdownMenuSeparator /> : null}
          {canDelete ? (
            <DropdownMenuItem
              variant="destructive"
              onClick={() => {
                setError(null);
                setDeleteOpen(true);
              }}
            >
              <Trash2 /> Delete post
            </DropdownMenuItem>
          ) : null}
        </DropdownMenuContent>
      </DropdownMenu>

      <Dialog open={editOpen} onOpenChange={(next) => !editPending && setEditOpen(next)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Edit post</DialogTitle>
            <DialogDescription>Update the text shown in this post.</DialogDescription>
          </DialogHeader>
          <form onSubmit={submitEdit} className="space-y-4">
            <Textarea
              aria-label="Edit post"
              value={editContent}
              maxLength={5000}
              onChange={(event) => setEditContent(event.target.value)}
            />
            {error ? <p role="alert" className="text-sm text-destructive">{error}</p> : null}
            <DialogFooter>
              <Button type="button" variant="outline" disabled={editPending} onClick={() => setEditOpen(false)}>Cancel</Button>
              <Button type="submit" disabled={editPending || !editContent.trim()} aria-label="Save post changes">
                {editPending ? "Saving…" : "Save"}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      <AlertDialog open={deleteOpen} onOpenChange={(next) => !deletePending && setDeleteOpen(next)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete post?</AlertDialogTitle>
            <AlertDialogDescription>This permanently removes the post and its discussion.</AlertDialogDescription>
          </AlertDialogHeader>
          {error ? <p role="alert" className="text-sm text-destructive">{error}</p> : null}
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deletePending}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              disabled={deletePending}
              aria-label="Delete post"
              onClick={(event) => {
                event.preventDefault();
                void removePost();
              }}
            >
              {deletePending ? "Deleting…" : "Delete"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

"use client";

import { repostPost } from "@/lib/feed/actions";
import { Button } from "@game-guild/ui/components/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@game-guild/ui/components/dialog";
import {
  Drawer,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
} from "@game-guild/ui/components/drawer";
import { Textarea } from "@game-guild/ui/components/textarea";
import { Repeat2 } from "lucide-react";
import * as React from "react";
import { toast } from "sonner";

function useResponsiveMobile() {
  const [mobile, setMobile] = React.useState(() => typeof window !== "undefined" && window.innerWidth < 768);
  React.useEffect(() => {
    if (typeof window.matchMedia !== "function") return;
    const query = window.matchMedia("(max-width: 767px)");
    const update = () => setMobile(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);
  return mobile;
}

function responseBoolean(value: unknown, key: string, fallback: boolean) {
  if (!value || typeof value !== "object") return fallback;
  const candidate = (value as Record<string, unknown>)[key];
  return typeof candidate === "boolean" ? candidate : fallback;
}

function responseCount(value: unknown, key: string, fallback: number) {
  if (!value || typeof value !== "object") return fallback;
  const candidate = (value as Record<string, unknown>)[key];
  return typeof candidate === "number" && Number.isFinite(candidate) ? candidate : fallback;
}

function RepostForm({
  commentary,
  error,
  pending,
  onCommentaryChange,
  onCancel,
  onSubmit,
}: {
  commentary: string;
  error: string | null;
  pending: boolean;
  onCommentaryChange: (value: string) => void;
  onCancel: () => void;
  onSubmit: (event: React.FormEvent<HTMLFormElement>) => void;
}) {
  return (
    <form onSubmit={onSubmit} className="space-y-4 px-4 pb-4 sm:px-0 sm:pb-0">
      <Textarea
        aria-label="Repost commentary"
        placeholder="Add a thought (optional)"
        maxLength={1000}
        value={commentary}
        onChange={(event) => onCommentaryChange(event.target.value)}
      />
      {error ? <p role="alert" className="text-sm text-destructive">{error}</p> : null}
      <div className="flex justify-end gap-2">
        <Button type="button" variant="outline" onClick={onCancel} disabled={pending}>Cancel</Button>
        <Button type="submit" disabled={pending} aria-label="Publish repost">{pending ? "Publishing…" : "Repost"}</Button>
      </div>
    </form>
  );
}

export function RepostDialog({
  postId,
  initialReposted,
  initialCount,
}: {
  postId: string;
  initialReposted: boolean;
  initialCount: number;
}): React.JSX.Element {
  const isMobile = useResponsiveMobile();
  const [open, setOpen] = React.useState(false);
  const [commentary, setCommentary] = React.useState("");
  const [reposted, setReposted] = React.useState(initialReposted);
  const [count, setCount] = React.useState(initialCount);
  const [pending, setPending] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  const pendingRef = React.useRef(false);

  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (pendingRef.current || reposted) return;
    pendingRef.current = true;
    const previousReposted = reposted;
    const previousCount = count;
    setReposted(true);
    setCount((value) => value + 1);
    setPending(true);
    setError(null);
    try {
      const state = await repostPost(postId, commentary.trim());
      setReposted(responseBoolean(state, "hasReposted", true));
      setCount(responseCount(state, "repostsCount", previousCount + 1));
      setCommentary("");
      setOpen(false);
      toast.success("Reposted.");
    } catch (reason) {
      setReposted(previousReposted);
      setCount(previousCount);
      const message = reason instanceof Error ? reason.message : "Post could not be reposted.";
      setError(message);
      toast.error(message);
    } finally {
      pendingRef.current = false;
      setPending(false);
    }
  }

  const form = (
    <RepostForm
      commentary={commentary}
      error={error}
      pending={pending}
      onCommentaryChange={setCommentary}
      onCancel={() => setOpen(false)}
      onSubmit={submit}
    />
  );

  return (
    <>
      <button
        type="button"
        onClick={() => {
          setError(null);
          setOpen(true);
        }}
        disabled={reposted || pending}
        aria-label={reposted ? "Reposted" : "Repost"}
        aria-pressed={reposted}
        className={`inline-flex min-h-9 items-center gap-2 rounded-lg px-2 text-sm hover:bg-accent disabled:opacity-70 ${reposted ? "text-success" : "text-muted-foreground hover:text-success"}`}
      >
        <Repeat2 className="size-[19px]" />
        {count > 0 ? count : null}
      </button>
      {isMobile ? (
        <Drawer open={open} onOpenChange={setOpen}>
          <DrawerContent>
            <DrawerHeader>
              <DrawerTitle>Repost this post</DrawerTitle>
              <DrawerDescription>Add optional commentary before sharing it with your followers.</DrawerDescription>
            </DrawerHeader>
            {form}
            <DrawerFooter className="hidden" />
          </DrawerContent>
        </Drawer>
      ) : (
        <Dialog open={open} onOpenChange={setOpen}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Repost this post</DialogTitle>
              <DialogDescription>Add optional commentary before sharing it with your followers.</DialogDescription>
            </DialogHeader>
            {form}
            <DialogFooter className="hidden" />
          </DialogContent>
        </Dialog>
      )}
    </>
  );
}

"use client";

import { createSocialPost, getSocialMediaStatus, hydrateSocialPost } from "@/lib/feed/actions";
import type { SocialMediaAsset, SocialPostItem, SocialPostPublicationResult } from "@/lib/feed/contracts";
import { uploadSocialMediaWithProgress } from "@/lib/feed/social-media-upload";
import { Button } from "@game-guild/ui/components/button";
import { Textarea } from "@game-guild/ui/components/textarea";
import { Loader2, Send, X } from "lucide-react";
import * as React from "react";
import { toast } from "sonner";
import { SocialMediaPicker, type SelectedSocialMedia } from "./social-media-picker";

const CHARACTER_LIMIT = 4000;

function initials(name: string) { return name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]).join("").toUpperCase(); }
function tagsFrom(content: string) { return [...new Set([...content.matchAll(/#([\p{L}\p{N}_]+)/gu)].map((match) => match[1]!.toLowerCase()))].slice(0, 10); }

async function waitUntilReady(asset: SocialMediaAsset, signal: AbortSignal, processing: () => void) {
  let current = asset;
  if (current.state === "Processing") processing();
  for (let attempt = 0; current.state === "Processing" && attempt < 20; attempt += 1) {
    if (signal.aborted) throw new Error("Media upload cancelled.");
    await new Promise((resolve) => setTimeout(resolve, Math.min(500 + attempt * 250, 2_000)));
    if (signal.aborted) throw new Error("Media upload cancelled.");
    current = await getSocialMediaStatus(current.assetReferenceId);
  }
  if (current.state === "Rejected") throw new Error("The media file was rejected during processing.");
  if (current.state !== "Ready") throw new Error("Media processing timed out. Please try again.");
  return current;
}

export function SocialComposer({ userName, onPublished }: { userName: string; onPublished?: (post: SocialPostItem) => void }): React.JSX.Element {
  const [expanded, setExpanded] = React.useState(false);
  const [content, setContent] = React.useState("");
  const [media, setMedia] = React.useState<SelectedSocialMedia | null>(null);
  const [pending, setPending] = React.useState(false);
  const [phase, setPhase] = React.useState<"idle" | "uploading" | "processing" | "failed">("idle");
  const [progress, setProgress] = React.useState<{ loaded: number; total: number; percent: number } | null>(null);
  const [failure, setFailure] = React.useState<string | null>(null);
  const [committedPostId, setCommittedPostId] = React.useState<string | null>(null);
  const pendingRef = React.useRef(false);
  const controllerRef = React.useRef<AbortController | null>(null);
  const publishedIdsRef = React.useRef(new Set<string>());

  React.useEffect(() => { const open = () => setExpanded(true); window.addEventListener("social:compose", open); return () => window.removeEventListener("social:compose", open); }, []);
  React.useEffect(() => () => controllerRef.current?.abort(), []);

  async function publish(event?: React.FormEvent) {
    event?.preventDefault();
    if (pendingRef.current) return;
    const text = content.trim();
    if (text.length > CHARACTER_LIMIT) { setFailure(`Posts can be up to ${CHARACTER_LIMIT} characters.`); return; }
    if (!text && !media && !committedPostId) return;
    pendingRef.current = true; setPending(true); setFailure(null);
    const controller = new AbortController(); controllerRef.current = controller;
    try {
      let publication: SocialPostPublicationResult;
      if (committedPostId) {
        publication = { kind: "published", post: await hydrateSocialPost(committedPostId) };
      } else {
        let assetReferenceId: string | null = null;
        if (media) {
          setPhase("uploading");
          const uploaded = await uploadSocialMediaWithProgress(media.file, { signal: controller.signal, onProgress: setProgress });
          assetReferenceId = (await waitUntilReady(uploaded, controller.signal, () => setPhase("processing"))).assetReferenceId;
        }
        publication = await createSocialPost({ content: text, visibility: "Public", assetReferenceId, tags: tagsFrom(text) });
      }
      if (publication.kind === "needs-hydration") {
        const message = "Your post was published. Retry to add it to the feed.";
        setCommittedPostId(publication.postId);
        setFailure(message);
        setPhase("failed");
        toast.error(message);
        return;
      }
      const post = publication.post;
      if (!publishedIdsRef.current.has(post.id)) { publishedIdsRef.current.add(post.id); onPublished?.(post); }
    setContent(""); setMedia(null); setProgress(null); setPhase("idle"); setCommittedPostId(null); setExpanded(false); toast.success("Post published.");
    } catch (error) {
      const message = error instanceof Error ? error.message : "The post could not be published.";
      setFailure(message); setPhase("failed"); toast.error(message);
    } finally {
      if (controllerRef.current === controller) controllerRef.current = null;
      pendingRef.current = false; setPending(false);
    }
  }

  if (!expanded) return <section id="social-composer" className="px-4 py-3 sm:px-6"><div className="flex items-center gap-3 rounded-xl bg-card p-2.5 text-card-foreground"><span className="flex size-9 shrink-0 items-center justify-center rounded-full bg-primary/15 text-xs font-bold text-foreground">{initials(userName)}</span><button type="button" aria-label="Share your progress" onClick={() => setExpanded(true)} className="min-w-0 flex-1 rounded-lg px-2 py-2 text-left text-sm text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground">Share your progress…</button></div></section>;
  return <section id="social-composer" className="px-4 py-4 sm:px-6"><form onSubmit={publish} className="rounded-xl bg-card p-4 text-card-foreground"><div className="flex items-start gap-3"><span className="flex size-9 shrink-0 items-center justify-center rounded-full bg-primary/15 text-xs font-bold text-foreground">{initials(userName)}</span><Textarea autoFocus rows={3} maxLength={CHARACTER_LIMIT} value={content} onChange={(event) => setContent(event.target.value)} placeholder="What are you building?" aria-describedby="social-composer-character-count" className="min-h-20 flex-1 resize-none border-0 bg-transparent px-1 py-1 text-sm shadow-none focus-visible:ring-0" /><Button type="button" variant="ghost" size="icon-sm" disabled={pending} onClick={() => setExpanded(false)} aria-label="Close composer"><X className="size-4" /></Button></div><div className="ml-12 mt-3"><SocialMediaPicker value={media} onChange={setMedia} disabled={pending} /></div>{progress ? <div className="ml-12 mt-2" aria-live="polite"><div role="progressbar" aria-label="Media upload progress" aria-valuemin={0} aria-valuemax={100} aria-valuenow={progress.percent} className="h-2 overflow-hidden rounded-full bg-primary/20"><div className="h-full bg-primary" style={{ width: `${progress.percent}%` }} /></div><p className="mt-1 text-xs text-muted-foreground">Uploading {progress.loaded} of {progress.total} bytes ({progress.percent}%)</p></div> : null}{phase === "processing" ? <p className="ml-12 mt-2 text-xs text-muted-foreground" aria-live="polite">Processing media…</p> : null}{failure ? <div className="ml-12 mt-2 flex items-center gap-2" role="alert"><p className="text-xs text-destructive">{failure}</p>{media || committedPostId ? <Button type="button" variant="ghost" size="sm" onClick={() => void publish()}>{committedPostId ? "Retry feed update" : "Retry upload"}</Button> : null}</div> : null}<div className="ml-12 mt-3 flex items-center justify-between gap-3"><span id="social-composer-character-count" className="text-xs text-muted-foreground" aria-live="polite">{content.length}/{CHARACTER_LIMIT} characters</span><div className="flex gap-2">{pending ? <Button type="button" variant="ghost" size="sm" onClick={() => controllerRef.current?.abort()}>Cancel upload</Button> : null}<Button type="submit" size="sm" disabled={pending || ((!content.trim() && !media) && !committedPostId)} aria-label="Publish">{pending ? <Loader2 className="size-4 animate-spin" /> : <Send className="size-4" />}{pending ? "Publishing…" : "Publish"}</Button></div></div></form></section>;
}

import { auth } from "@/auth";
import {
  BuildStories,
  type SocialStoryPreview,
} from "@/components/feed/build-stories";
import { FeedSkeleton } from "@/components/feed/feed-skeleton";
import { SocialFeedClient } from "@/components/feed/social-feed-client";
import {
  SocialFeedTabs,
  type SocialFeedTab,
} from "@/components/feed/social-feed-tabs";
import {
  SocialRail,
  type SocialSessionPreview,
} from "@/components/feed/social-rail";
import type { FeedScope, SocialProfile } from "@/lib/feed/contracts";
import {
  loadSocialFeed,
  loadSocialProfile,
  loadCreatorSuggestions,
  loadStories,
  loadTrendingTags,
} from "@/lib/feed/queries";
import { AlertCircle } from "lucide-react";
import { Suspense } from "react";

const TAB_SCOPE: Record<SocialFeedTab, FeedScope> = {
  foryou: "for-you",
  following: "following",
  community: "community",
  saved: "saved",
};

async function optional<T>(operation: Promise<T>, fallback: T): Promise<T> {
  try {
    return await operation;
  } catch {
    return fallback;
  }
}

export function SocialShell({
  tab = "foryou",
  tag = null,
}: {
  tab?: SocialFeedTab;
  tag?: string | null;
}): React.JSX.Element {
  return (
    <Suspense fallback={<FeedSkeleton />}>
      <SocialFeed tab={tab} tag={tag} />
    </Suspense>
  );
}

export async function SocialFeed({
  tab = "foryou",
  tag = null,
}: {
  tab?: SocialFeedTab;
  tag?: string | null;
}): Promise<React.JSX.Element> {
  const scope = TAB_SCOPE[tab];
  const session = await auth();
  const user = session && typeof session !== "function" ? session.user : null;
  const userName =
    user?.name?.trim() || user?.email?.split("@")[0] || "GameGuild member";
  const currentUserId = user?.id ?? null;

  const emptyFeed = { items: [], nextCursor: null };
  // Captured, not awaited: a rejection must not kill the parallel batch below.
  const primaryPromise = loadSocialFeed({ scope, tag })
    .then((feed) => ({ failed: false as const, feed }))
    .catch(() => ({ failed: true as const, feed: emptyFeed }));

  const [primaryResult, storiesTrack, currentProfile, suggestedProfiles, trendingTags, community] =
    await Promise.all([
      primaryPromise,
      optional(
        loadStories().then(async (stories) => {
          const authorProfiles = await Promise.all(
            [...new Set(stories.map((story) => story.authorId))].map((id) =>
              optional(loadSocialProfile(id), null),
            ),
          );
          return { stories, authorProfiles };
        }),
        { stories: [], authorProfiles: [] },
      ),
      currentUserId
        ? optional(loadSocialProfile(currentUserId), null)
        : Promise.resolve(null),
      currentUserId
        ? optional(loadCreatorSuggestions(currentUserId, 8), [])
        : Promise.resolve([]),
      optional(loadTrendingTags(6), []),
      scope === "community"
        ? primaryPromise.then(({ feed }) => feed)
        : optional(loadSocialFeed({ scope: "community", take: 8 }), emptyFeed),
    ]);

  const { failed: primaryError, feed: primary } = primaryResult;
  const { stories, authorProfiles } = storiesTrack;
  const storyAuthorIds = [...new Set(stories.map((story) => story.authorId))];
  const storyProfiles = new Map<string, SocialProfile>();
  storyAuthorIds.forEach((authorId, index) => {
    const profile = authorProfiles[index];
    if (profile) storyProfiles.set(authorId, profile);
  });
  const storyPreviews: SocialStoryPreview[] = stories.map((story) => {
    const profile = storyProfiles.get(story.authorId);
    const ownStory = story.authorId === currentUserId;
    return {
      ...story,
      authorName: profile?.displayName || (ownStory ? userName : "GameGuild creator"),
      authorHandle: profile?.handle || "creator",
      authorAvatarUrl: profile?.avatarUrl ?? null,
      isOwn: ownStory,
    };
  });
  const sessions: SocialSessionPreview[] = community.items
    .filter((item) => item.kind === "TestingSession" && item.testingSession)
    .map((item) => ({ id: item.id, ...item.testingSession! }));
  const creators = suggestedProfiles.filter(
    (profile) => profile.userId && profile.userId !== currentUserId,
  );

  return (
    <div
      data-testid="social-shell"
      className="min-h-[calc(100svh-4rem)] bg-background text-foreground"
    >
      <div className="mx-auto grid min-h-[calc(100svh-4rem)] w-full max-w-[1260px] grid-cols-1 gap-0 xl:grid-cols-[minmax(0,820px)_360px] xl:gap-6">
        <div className="min-w-0">
          <SocialFeedTabs active={tab} />
          <BuildStories
            key={storyPreviews.map((story) => story.id).join(":")}
            userName={userName}
            stories={storyPreviews}
            currentProfile={currentProfile}
          />
          {primaryError ? (
            <div role="alert" className="mx-4 my-8 flex items-start gap-3 rounded-xl bg-card px-5 py-6 sm:mx-6">
              <AlertCircle className="mt-0.5 size-5 shrink-0 text-destructive" />
              <div>
                <p className="font-semibold text-foreground">The feed is temporarily unavailable</p>
                <p className="mt-1 text-sm text-muted-foreground">No placeholder posts were substituted. Refresh to retry the live feed.</p>
              </div>
            </div>
          ) : (
            <SocialFeedClient
              userName={userName}
              scope={scope}
              tag={tag}
              initialItems={primary.items}
              initialNextCursor={primary.nextCursor}
              currentUserId={currentUserId}
            />
          )}
        </div>
        <SocialRail
          currentProfile={currentProfile}
          sessions={sessions}
          creators={creators}
          tags={trendingTags}
          activeTab={tab}
        />
      </div>
    </div>
  );
}

"use client";

import { createStory, getSocialMediaStatus } from "@/lib/feed/actions";
import type { SocialMediaAsset, SocialStory } from "@/lib/feed/contracts";
import { uploadSocialMediaWithProgress } from "@/lib/feed/social-media-upload";
import { Button } from "@game-guild/ui/components/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@game-guild/ui/components/dialog";
import { Textarea } from "@game-guild/ui/components/textarea";
import { Loader2, Plus } from "lucide-react";
import * as React from "react";
import { SocialMediaPicker, type SelectedSocialMedia } from "./social-media-picker";

const STORY_CAPTION_LIMIT = 500;
const STORY_PROCESSING_ATTEMPTS = 20;

function initials(name: string) {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join("")
    .toUpperCase();
}

function processingDelay(attempt: number) {
  return Math.min(500 + attempt * 250, 2_000);
}

async function waitForStoryMedia(
  asset: SocialMediaAsset,
  signal: AbortSignal,
  onProcessing: () => void,
) {
  let current = asset;
  if (current.state === "Processing") onProcessing();
  for (
    let attempt = 0;
    current.state === "Processing" && attempt < STORY_PROCESSING_ATTEMPTS;
    attempt += 1
  ) {
    if (signal.aborted) throw new Error("Media upload cancelled.");
    await new Promise((resolve) => window.setTimeout(resolve, processingDelay(attempt)));
    if (signal.aborted) throw new Error("Media upload cancelled.");
    current = await getSocialMediaStatus(current.assetReferenceId);
  }
  if (current.state === "Rejected") {
    throw new Error("The story media could not be processed.");
  }
  if (current.state !== "Ready") {
    throw new Error("Story media processing timed out. Please try again.");
  }
  return current;
}

export function StoryComposer({
  userName,
  onPublished,
}: {
  userName: string;
  onPublished: (story: SocialStory) => void;
}): React.JSX.Element {
  const [open, setOpen] = React.useState(false);
  const [media, setMedia] = React.useState<SelectedSocialMedia | null>(null);
  const [caption, setCaption] = React.useState("");
  const [pending, setPending] = React.useState(false);
  const [phase, setPhase] = React.useState<"idle" | "uploading" | "processing" | "failed">("idle");
  const [progress, setProgress] = React.useState<{
    loaded: number;
    total: number;
    percent: number;
  } | null>(null);
  const [error, setError] = React.useState<string | null>(null);
  const pendingRef = React.useRef(false);
  const controllerRef = React.useRef<AbortController | null>(null);
  const readyAssetRef = React.useRef<SocialMediaAsset | null>(null);
  const publishedIdsRef = React.useRef(new Set<string>());

  React.useEffect(() => () => controllerRef.current?.abort(), []);

  function resetDraft() {
    setMedia(null);
    setCaption("");
    setProgress(null);
    setError(null);
    setPhase("idle");
    readyAssetRef.current = null;
  }

  function changeMedia(next: SelectedSocialMedia | null) {
    readyAssetRef.current = null;
    setProgress(null);
    setError(null);
    setPhase("idle");
    setMedia(next);
  }

  async function publish(event?: React.FormEvent<HTMLFormElement>) {
    event?.preventDefault();
    if (!media || pendingRef.current) return;
    pendingRef.current = true;
    setPending(true);
    setError(null);
    const controller = new AbortController();
    controllerRef.current = controller;

    try {
      let asset = readyAssetRef.current;
      if (!asset) {
        setPhase("uploading");
        asset = await uploadSocialMediaWithProgress(media.file, {
          signal: controller.signal,
          onProgress: setProgress,
        });
        asset = await waitForStoryMedia(asset, controller.signal, () =>
          setPhase("processing"),
        );
        readyAssetRef.current = asset;
      }
      const story = await createStory(asset.assetReferenceId, caption.trim() || null);
      if (!publishedIdsRef.current.has(story.id)) {
        publishedIdsRef.current.add(story.id);
        onPublished(story);
      }
      resetDraft();
      setOpen(false);
    } catch (reason) {
      const message =
        reason instanceof Error ? reason.message : "The story could not be published.";
      if (phase === "processing" || /process|timed out/i.test(message)) {
        readyAssetRef.current = null;
      }
      setError(message);
      setPhase("failed");
    } finally {
      if (controllerRef.current === controller) controllerRef.current = null;
      pendingRef.current = false;
      setPending(false);
    }
  }

  return (
    <>
      <button
        type="button"
        onClick={() => setOpen(true)}
        className="group flex w-[4.5rem] shrink-0 flex-col items-center gap-2 text-center"
        aria-label="Add story"
      >
        <span className="relative flex size-14 items-center justify-center rounded-full bg-muted text-sm font-bold text-foreground transition-transform group-hover:scale-[1.03]">
          {initials(userName)}
          <span className="absolute -bottom-0.5 -right-0.5 flex size-5 items-center justify-center rounded-full border-2 border-background bg-primary text-primary-foreground">
            <Plus className="size-3" aria-hidden="true" />
          </span>
        </span>
        <span className="w-full truncate text-[11px] font-medium text-muted-foreground">
          Your story
        </span>
      </button>

      <Dialog
        open={open}
        onOpenChange={(next) => {
          if (!pending) setOpen(next);
        }}
      >
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Create a story</DialogTitle>
            <DialogDescription>
              Share one image or video for the next 24 hours.
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={publish} className="space-y-4">
            <SocialMediaPicker value={media} onChange={changeMedia} disabled={pending} />
            <div>
              <Textarea
                aria-label="Story caption"
                value={caption}
                maxLength={STORY_CAPTION_LIMIT}
                disabled={pending}
                onChange={(event) => setCaption(event.target.value)}
                placeholder="Add a caption (optional)"
              />
              <p className="mt-1 text-right text-xs text-muted-foreground">
                {caption.length}/{STORY_CAPTION_LIMIT}
              </p>
            </div>

            {progress ? (
              <div aria-live="polite">
                <div
                  role="progressbar"
                  aria-label="Story upload progress"
                  aria-valuemin={0}
                  aria-valuemax={100}
                  aria-valuenow={progress.percent}
                  className="h-2 overflow-hidden rounded-full bg-primary/20"
                >
                  <div
                    className="h-full bg-primary"
                    style={{ width: `${progress.percent}%` }}
                  />
                </div>
                <p className="mt-1 text-xs text-muted-foreground">
                  Uploading {progress.loaded} of {progress.total} bytes ({progress.percent}%)
                </p>
              </div>
            ) : null}
            {phase === "processing" ? (
              <p className="text-sm text-muted-foreground" aria-live="polite">
                Processing story media…
              </p>
            ) : null}
            {error ? (
              <div role="alert" className="flex items-center justify-between gap-3">
                <p className="text-sm text-destructive">{error}</p>
                {media ? (
                  <Button type="button" variant="ghost" size="sm" onClick={() => void publish()}>
                    Retry story upload
                  </Button>
                ) : null}
              </div>
            ) : null}

            <DialogFooter>
              {pending ? (
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => controllerRef.current?.abort()}
                  aria-label="Cancel upload"
                >
                  Cancel upload
                </Button>
              ) : (
                <Button type="button" variant="outline" onClick={() => setOpen(false)}>
                  Cancel
                </Button>
              )}
              <Button
                type="submit"
                disabled={!media || pending}
                aria-label={pending ? "Publishing story" : "Publish story"}
              >
                {pending ? <Loader2 className="size-4 animate-spin" /> : null}
                {pending ? "Publishing…" : "Publish story"}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </>
  );
}

"use client";

import { deleteStory, markStoryViewed } from "@/lib/feed/actions";
import type { SocialStory } from "@/lib/feed/contracts";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@game-guild/ui/components/alert-dialog";
import { Button } from "@game-guild/ui/components/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@game-guild/ui/components/dialog";
import { ChevronLeft, ChevronRight, Pause, Play, Trash2 } from "lucide-react";
import Image from "next/image";
import * as React from "react";

const IMAGE_STORY_DURATION_MS = 5_000;
const STORY_TICK_MS = 100;

export interface SocialStoryPreview extends SocialStory {
  authorName: string;
  authorHandle: string;
  authorAvatarUrl: string | null;
  isOwn: boolean;
}

interface StoryViewerProps {
  stories: SocialStoryPreview[];
  activeStoryId: string | null;
  onActiveStoryChange: (storyId: string | null) => void;
  onStoryViewed: (storyId: string) => void;
  onStoryDeleted: (storyId: string) => void;
}

function useReducedMotion() {
  const [reduced, setReduced] = React.useState(false);
  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(media.matches);
    update();
    media.addEventListener?.("change", update);
    return () => media.removeEventListener?.("change", update);
  }, []);
  return reduced;
}

export function StoryViewer({
  ...props
}: StoryViewerProps): React.JSX.Element {
  return <StoryViewerSession key={props.activeStoryId ?? "closed"} {...props} />;
}

function StoryViewerSession({
  stories,
  activeStoryId,
  onActiveStoryChange,
  onStoryViewed,
  onStoryDeleted,
}: StoryViewerProps): React.JSX.Element {
  const activeIndex = activeStoryId
    ? stories.findIndex((story) => story.id === activeStoryId)
    : -1;
  const active = activeIndex >= 0 ? stories[activeIndex] ?? null : null;
  const reducedMotion = useReducedMotion();
  const [elapsed, setElapsed] = React.useState(0);
  const [videoProgress, setVideoProgress] = React.useState(0);
  const [manuallyPaused, setManuallyPaused] = React.useState(false);
  const [pointerPaused, setPointerPaused] = React.useState(false);
  const [deleteOpen, setDeleteOpen] = React.useState(false);
  const [deletePending, setDeletePending] = React.useState(false);
  const [deleteError, setDeleteError] = React.useState<string | null>(null);
  const deletePendingRef = React.useRef(false);
  const viewedRef = React.useRef(new Set<string>());
  const videoRef = React.useRef<HTMLVideoElement>(null);
  const isVideo = active?.mediaType?.startsWith("video") ?? false;
  const paused = reducedMotion || manuallyPaused || pointerPaused;

  const selectOffset = React.useCallback(
    (offset: -1 | 1) => {
      if (!active) return;
      const next = activeIndex + offset;
      if (next < 0) return;
      if (next >= stories.length) {
        onActiveStoryChange(null);
        return;
      }
      onActiveStoryChange(stories[next]?.id ?? null);
    },
    [active, activeIndex, onActiveStoryChange, stories],
  );

  React.useEffect(() => {
    if (!active || active.isViewed || viewedRef.current.has(active.id)) return;
    viewedRef.current.add(active.id);
    onStoryViewed(active.id);
    void markStoryViewed(active.id).catch(() => {
      // Viewing stays available even when the idempotent receipt cannot be saved.
    });
  }, [active, onStoryViewed]);

  React.useEffect(() => {
    if (!active || isVideo || paused) return;
    const timer = window.setInterval(() => {
      setElapsed((current) => Math.min(IMAGE_STORY_DURATION_MS, current + STORY_TICK_MS));
    }, STORY_TICK_MS);
    return () => window.clearInterval(timer);
  }, [active, isVideo, paused]);

  React.useEffect(() => {
    if (!active || isVideo || elapsed < IMAGE_STORY_DURATION_MS || paused) return;
    selectOffset(1);
  }, [active, elapsed, isVideo, paused, selectOffset]);

  React.useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    if (paused) video.pause();
    else {
      const playback = video.play();
      if (playback) void playback.catch(() => undefined);
    }
  }, [activeStoryId, paused]);

  async function confirmDelete() {
    if (!active || deletePendingRef.current) return;
    deletePendingRef.current = true;
    setDeletePending(true);
    setDeleteError(null);
    try {
      await deleteStory(active.id);
      onStoryDeleted(active.id);
      onActiveStoryChange(null);
      setDeleteOpen(false);
    } catch (reason) {
      setDeleteError(
        reason instanceof Error ? reason.message : "Story could not be deleted.",
      );
    } finally {
      deletePendingRef.current = false;
      setDeletePending(false);
    }
  }

  const progress = isVideo
    ? videoProgress
    : Math.round((elapsed / IMAGE_STORY_DURATION_MS) * 100);

  return (
    <>
      <Dialog
        open={Boolean(active)}
        onOpenChange={(open) => {
          if (!open) onActiveStoryChange(null);
        }}
      >
        <DialogContent
          className="overflow-hidden p-0 sm:max-w-lg"
          showCloseButton
          onKeyDown={(event) => {
            if (event.key === "ArrowLeft") {
              event.preventDefault();
              selectOffset(-1);
            } else if (event.key === "ArrowRight") {
              event.preventDefault();
              selectOffset(1);
            } else if (event.key === "Escape") {
              event.preventDefault();
              onActiveStoryChange(null);
            }
          }}
        >
          {active ? (
            <>
              <div className="absolute inset-x-3 top-2 z-10 flex gap-1 pr-9">
                {stories.map((story, index) => {
                  const value = index < activeIndex ? 100 : index === activeIndex ? progress : 0;
                  return (
                    <div
                      key={story.id}
                      role={index === activeIndex ? "progressbar" : undefined}
                      aria-label={index === activeIndex ? "Story progress" : undefined}
                      aria-valuemin={index === activeIndex ? 0 : undefined}
                      aria-valuemax={index === activeIndex ? 100 : undefined}
                      aria-valuenow={index === activeIndex ? value : undefined}
                      className="h-1 flex-1 overflow-hidden rounded-full bg-foreground/20"
                    >
                      <span
                        className="block h-full bg-primary"
                        style={{ width: `${value}%` }}
                      />
                    </div>
                  );
                })}
              </div>
              <DialogHeader className="px-4 pt-5 text-left">
                <DialogTitle>{active.authorName}</DialogTitle>
                <DialogDescription>
                  @{active.authorHandle} ·{" "}
                  <time dateTime={active.createdAt}>
                    {new Date(active.createdAt).toLocaleString()}
                  </time>
                </DialogDescription>
              </DialogHeader>
              <div
                data-testid="story-media-surface"
                className="relative flex min-h-80 touch-none items-center justify-center bg-black"
                onPointerDown={() => setPointerPaused(true)}
                onPointerUp={() => setPointerPaused(false)}
                onPointerCancel={() => setPointerPaused(false)}
                onPointerLeave={() => setPointerPaused(false)}
              >
                {isVideo ? (
                  <video
                    ref={videoRef}
                    src={active.mediaUrl ?? undefined}
                    aria-label={`Story video by ${active.authorName}`}
                    autoPlay={!reducedMotion}
                    playsInline
                    onEnded={() => {
                      if (!reducedMotion) selectOffset(1);
                    }}
                    onTimeUpdate={(event) => {
                      const video = event.currentTarget;
                      setVideoProgress(
                        video.duration > 0
                          ? Math.min(100, Math.round((video.currentTime / video.duration) * 100))
                          : 0,
                      );
                    }}
                    className="max-h-[70vh] w-full object-contain"
                  />
                ) : active.mediaUrl ? (
                  <Image
                    src={active.mediaUrl}
                    alt={active.caption || `Story by ${active.authorName}`}
                    width={900}
                    height={1200}
                    unoptimized
                    className="max-h-[70vh] w-full object-contain"
                  />
                ) : null}
                <Button
                  type="button"
                  variant="secondary"
                  size="icon"
                  aria-label="Previous story"
                  disabled={activeIndex === 0}
                  onClick={() => selectOffset(-1)}
                  className="absolute left-3 top-1/2 -translate-y-1/2 rounded-full bg-background/80"
                >
                  <ChevronLeft className="size-5" />
                </Button>
                <Button
                  type="button"
                  variant="secondary"
                  size="icon"
                  aria-label="Next story"
                  onClick={() => selectOffset(1)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 rounded-full bg-background/80"
                >
                  <ChevronRight className="size-5" />
                </Button>
              </div>
              <div className="flex items-center gap-3 px-4 pb-4">
                <p className="min-w-0 flex-1 text-sm text-foreground">
                  {active.caption}
                </p>
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={() => setManuallyPaused((current) => !current)}
                  aria-label={manuallyPaused ? "Play story" : "Pause story"}
                  aria-pressed={manuallyPaused}
                >
                  {manuallyPaused ? <Play className="size-4" /> : <Pause className="size-4" />}
                  {manuallyPaused ? "Play" : "Pause"}
                </Button>
                {active.isOwn ? (
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    aria-label="Delete story"
                    onClick={() => {
                      setDeleteError(null);
                      setDeleteOpen(true);
                    }}
                  >
                    <Trash2 className="size-4" /> Delete
                  </Button>
                ) : null}
              </div>
              {reducedMotion ? (
                <p className="sr-only" aria-live="polite">
                  Automatic advance is off because reduced motion is enabled.
                </p>
              ) : null}
            </>
          ) : null}
        </DialogContent>
      </Dialog>

      <AlertDialog
        open={deleteOpen}
        onOpenChange={(open) => {
          if (!deletePending) setDeleteOpen(open);
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete story?</AlertDialogTitle>
            <AlertDialogDescription>
              This removes the story before its scheduled expiration.
            </AlertDialogDescription>
          </AlertDialogHeader>
          {deleteError ? (
            <p role="alert" className="text-sm text-destructive">
              {deleteError}
            </p>
          ) : null}
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deletePending}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              disabled={deletePending}
              aria-label={deletePending ? "Deleting story" : "Confirm story deletion"}
              onClick={(event) => {
                event.preventDefault();
                void confirmDelete();
              }}
            >
              {deletePending ? "Deleting…" : "Delete"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

'use client';

import { type FormEvent, useState } from 'react';
import Link from 'next/link';
import { cn } from '@/lib/utils';
import { Button, buttonVariants } from '@game-guild/ui/components/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@game-guild/ui/components/card';
import { Field, FieldDescription, FieldError, FieldGroup, FieldLabel } from '@game-guild/ui/components/field';
import { Input } from '@game-guild/ui/components/input';
import { TurnstileWidget } from '@/components/antibot/turnstile-widget';

type ActionResult<T> = { success: true; data: T } | { success: false; error: string };

interface ForgotPasswordFormProps extends React.ComponentProps<'div'> {
  onRequestReset?: (email: string, turnstileToken?: string | null) => Promise<ActionResult<void>>;
  initialEmail?: string;
}

export function ForgotPasswordForm({ className, initialEmail = '', onRequestReset, ...props }: ForgotPasswordFormProps) {
  const [email, setEmail] = useState(initialEmail);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [turnstileToken, setTurnstileToken] = useState<string | null>(null);

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError(null);

    if (!email.trim()) {
      setError('Email is required.');
      return;
    }

    setIsLoading(true);

    try {
      if (onRequestReset) {
        const result = await onRequestReset(email.trim(), turnstileToken);
        if (!result.success) {
          throw new Error(result.error);
        }
      }
      setIsSubmitted(true);
    } catch (err) {
      // Single-use token: reset on failure so the widget re-issues a fresh one.
      setTurnstileToken(null);
      setError(err instanceof Error ? err.message : 'Something went wrong.');
    } finally {
      setIsLoading(false);
    }
  }

  if (isSubmitted) {
    return (
      <div className={cn('flex flex-col gap-6', className)} {...props}>
        <Card>
          <CardHeader className="text-center">
            <CardTitle className="text-xl">Check your email</CardTitle>
            <CardDescription>
              If an account with that email exists, we&apos;ve sent password reset instructions to <span className="font-medium">{email}</span>.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <FieldGroup>
              <Field>
                <Link href="/sign-in" className={cn(buttonVariants({ variant: "outline" }))}>
                  Back to Sign In
                </Link>
              </Field>
              <FieldDescription className="text-center">
                Didn&apos;t receive the email?{' '}
                <button type="button" className="underline underline-offset-4 hover:text-primary" onClick={() => setIsSubmitted(false)}>
                  Try again
                </button>
              </FieldDescription>
            </FieldGroup>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className={cn('flex flex-col gap-6', className)} {...props}>
      <Card>
        <CardHeader className="text-center">
          <CardTitle className="text-xl">Reset your password</CardTitle>
          <CardDescription>Enter your email address and we&apos;ll send you a link to reset your password.</CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} noValidate>
            <FieldGroup>
              <Field>
                <FieldLabel htmlFor="email">Email</FieldLabel>
                <Input
                  id="email"
                  name="email"
                  type="email"
                  placeholder="name@example.com"
                  autoComplete="email"
                  required
                  disabled={isLoading}
                  aria-invalid={!!error}
                  value={email}
                  onChange={(e) => {
                    setEmail(e.target.value);
                    if (error) setError(null);
                  }}
                />
                {error && <FieldError>{error}</FieldError>}
              </Field>
              <Field>
                <TurnstileWidget onToken={setTurnstileToken} action="forgot-password" id="forgot-password-turnstile" />
                <Button type="submit" disabled={isLoading}>
                  {isLoading ? 'Sending...' : 'Send Reset Link'}
                </Button>
                <FieldDescription className="text-center">
                  Remember your password? <Link href="/sign-in">Sign in</Link>
                </FieldDescription>
              </Field>
            </FieldGroup>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

"use client"

import { useEffect } from "react"
import { useAuth } from "@game-guild/client/react"
import { useGoogleIdentityService } from "./use-google-identity-service"

export interface GoogleOneTapProps {
  /**
   * Suppress the One Tap prompt when the user is already authenticated.
   * The sign-in page (the only public mount point today) leaves this false;
   * mount points that may render for logged-in users pass true.
   */
  authenticated?: boolean
  /** URL to redirect to after successful sign-in (e.g. "/dashboard"). */
  redirectTo?: string
}

/**
 * Triggers Google's One Tap prompt. The GIS credential callback routes
 * the (untrusted) Google ID token to signIn("google", { idToken }), which
 * exchanges it server-side via GoogleProvider.
 *
 * The underlying GIS hook (useGoogleIdentityService) is idempotent: the
 * GIS script and google.accounts.id.initialize run once per page even if
 * multiple consumers (e.g. <GoogleSignInButton/>) reuse the hook.
 */
export function GoogleOneTap({
  authenticated = false,
  redirectTo,
}: GoogleOneTapProps) {
  const { signIn } = useAuth()
  const { status, prompt } = useGoogleIdentityService({
    onCredential: (credential) => {
      // credential is an untrusted ID token — backend verifies it.
      // .catch() swallows the re-thrown error (error state is already set by useAuth)
      signIn("google", { idToken: credential, redirectTo }).catch((e) => {console.warn(e)})
    },
  })

  useEffect(() => {
    if (status === "ready" && !authenticated) {
      prompt()
    }
  }, [status, prompt, authenticated])

  // ponytail: One Tap renders into GIS's own iframe; no DOM output here.
  return null
}

"use client"

import { useEffect, useRef } from "react"
import { useAuth } from "@game-guild/client/react"
import {
  useGoogleIdentityService,
  type GisRenderButtonOptions,
} from "./use-google-identity-service"

const DEFAULT_BUTTON_OPTIONS: GisRenderButtonOptions = {
  type: "standard",
  theme: "outline",
  size: "large",
  text: "signin_with",
  shape: "rectangular",
  // ponytail: 400 is GIS max-width. Card content is ~400px (max-w-md 448px
  // minus padding), so this matches the Sign in button width.
  width: 400,
}

export interface GoogleSignInButtonProps {
  className?: string
  /** Override the default GIS button rendering options. */
  options?: GisRenderButtonOptions
  /** URL to redirect to after successful sign-in (e.g. "/dashboard"). */
  redirectTo?: string
}

/**
 * Renders Google's branded Sign-In button. The GIS credential callback
 * routes the (untrusted) Google ID token to signIn("google", { idToken }),
 * which exchanges it server-side via GoogleProvider (T2/T3).
 *
 * The underlying GIS hook (useGoogleIdentityService) is idempotent: the
 * GIS script and google.accounts.id.initialize run once per page even if
 * multiple consumers (e.g. <GoogleOneTap/> in T6) reuse the hook.
 */
export function GoogleSignInButton({
  className,
  options,
  redirectTo,
}: GoogleSignInButtonProps) {
  const { signIn } = useAuth()
  const containerRef = useRef<HTMLDivElement>(null)
  const { status, renderButton } = useGoogleIdentityService({
    onCredential: (credential) => {
      // credential is an untrusted ID token — backend verifies it.
      // .catch() swallows the re-thrown error (error state is already set by useAuth)
      signIn("google", { idToken: credential, redirectTo }).catch((e) => {console.warn(e)})
    },
  })

  useEffect(() => {
    if (status === "ready" && containerRef.current) {
      renderButton(containerRef.current, { ...DEFAULT_BUTTON_OPTIONS, ...options })
    }
  }, [status, renderButton, options])

  if (status === "error") {
    // A missing/unloaded Google provider renders nothing — the other
    // sign-in methods (Discord, email) carry the card.
    return null
  }

  return (
    <div
      ref={containerRef}
      data-testid="google-sign-in-button"
      className={className}
      // Reserve layout while GIS hydrates the button to prevent CLS.
      style={{ minHeight: 40, width: "100%", display: "flex", justifyContent: "center" }}
    />
  )
}

"use client"

import { type FormEvent, useState, useCallback } from "react"
import Link from "next/link"
import { Button } from "@game-guild/ui/components/button"
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@game-guild/ui/components/card"
import {
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
} from "@game-guild/ui/components/field"
import {
  InputOTP,
  InputOTPGroup,
  InputOTPSeparator,
  InputOTPSlot,
} from "@game-guild/ui/components/input-otp"
import { RefreshCwIcon } from "lucide-react"

interface InputOTPFormProps {
  /** The email address the OTP was sent to */
  email: string
  /** Called when the user submits the OTP code */
  onVerify: (code: string) => Promise<void>
  /** Called when the user requests a new code */
  onResend?: () => Promise<void>
}

export function InputOTPForm({ email, onVerify, onResend }: InputOTPFormProps) {
  const [code, setCode] = useState("")
  const [isVerifying, setIsVerifying] = useState(false)
  const [isResending, setIsResending] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const handleSubmit = useCallback(
    async (e: FormEvent<HTMLFormElement>) => {
      e.preventDefault()
      setError(null)

      if (code.length !== 6) {
        setError("Please enter the full 6-digit code.")
        return
      }

      setIsVerifying(true)
      try {
        await onVerify(code)
      } catch (err) {
        setError(
          err instanceof Error ? err.message : "Verification failed. Please try again."
        )
      } finally {
        setIsVerifying(false)
      }
    },
    [code, onVerify]
  )

  const handleResend = useCallback(async () => {
    if (!onResend) return
    setIsResending(true)
    setError(null)
    try {
      await onResend()
    } catch (err) {
      setError(
        err instanceof Error ? err.message : "Failed to resend code."
      )
    } finally {
      setIsResending(false)
    }
  }, [onResend])

  return (
    <form onSubmit={handleSubmit}>
      <Card className="mx-auto max-w-md">
        <CardHeader>
          <CardTitle>Verify your login</CardTitle>
          <CardDescription>
            Enter the verification code we sent to your email address:{" "}
            <span className="font-medium">{email}</span>.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Field>
            <div className="flex items-center justify-between">
              <FieldLabel htmlFor="otp-verification">
                Verification code
              </FieldLabel>
              {onResend && (
                <Button
                  variant="outline"
                  size="sm"
                  type="button"
                  disabled={isResending || isVerifying}
                  onClick={handleResend}
                >
                  <RefreshCwIcon />
                  {isResending ? "Sending..." : "Resend Code"}
                </Button>
              )}
            </div>
            <InputOTP
              maxLength={6}
              id="otp-verification"
              value={code}
              onChange={(value) => {
                setCode(value)
                if (error) setError(null)
              }}
              disabled={isVerifying}
              required
            >
              <InputOTPGroup className="*:data-[slot=input-otp-slot]:h-12 *:data-[slot=input-otp-slot]:w-11 *:data-[slot=input-otp-slot]:text-xl">
                <InputOTPSlot index={0} />
                <InputOTPSlot index={1} />
                <InputOTPSlot index={2} />
              </InputOTPGroup>
              <InputOTPSeparator className="mx-2" />
              <InputOTPGroup className="*:data-[slot=input-otp-slot]:h-12 *:data-[slot=input-otp-slot]:w-11 *:data-[slot=input-otp-slot]:text-xl">
                <InputOTPSlot index={3} />
                <InputOTPSlot index={4} />
                <InputOTPSlot index={5} />
              </InputOTPGroup>
            </InputOTP>
            {error && <FieldError>{error}</FieldError>}
            <FieldDescription>
              <Link href="/support">
                I no longer have access to this email address.
              </Link>
            </FieldDescription>
          </Field>
        </CardContent>
        <CardFooter>
          <Field>
            <Button type="submit" className="w-full" disabled={isVerifying || code.length !== 6}>
              {isVerifying ? "Verifying..." : "Verify"}
            </Button>
            <div className="text-muted-foreground text-sm">
              Having trouble signing in?{" "}
              <Link
                href="/support"
                className="hover:text-primary underline underline-offset-4 transition-colors"
              >
                Contact support
              </Link>
            </div>
          </Field>
        </CardFooter>
      </Card>
    </form>
  )
}

'use client';

import React, { useCallback, useMemo, useState } from 'react';
import {
  CodingAssessmentEditor,
  type AssessmentRunResult,
} from '@game-guild/emception-ui';
import {
  createAssessmentWorkspaceConfig,
  type CodingLanguage,
} from '@game-guild/emception-ui/assessment/presets';

import { formatFeedback } from '@/lib/emception/scoring';
import type { CodeFile } from '@/lib/coding-assignment/code-payload';
import type { CodingAssignmentContent } from '@/lib/coding-assignment/client';

export interface ComputedScore {
  score: number;
  autoFeedback: string;
}

export interface AssessmentGraderProps {
  assignment: CodingAssignmentContent;
  submittedFiles: CodeFile[];
  maxScore: number;
  manifestUrl: string;
  submissionId?: string;
  onComputedScore?: (result: ComputedScore) => void;
}

function buildPrivatePaths(assignment: CodingAssignmentContent): Set<string> {
  return new Set(
    Object.entries(assignment.Data.Files)
      .filter(([, file]) => file.Visibility === 'Private')
      .map(([path]) => path),
  );
}

/** Merge a frozen instructor workspace with student files without trusting private-path overrides. */
export function mergeWorkspaceWithSubmission(
  assignment: CodingAssignmentContent,
  submittedFiles: CodeFile[],
): CodeFile[] {
  const privatePaths = buildPrivatePaths(assignment);
  const merged = new Map<string, string>();

  for (const [path, file] of Object.entries(assignment.Data.Files)) {
    merged.set(path, file.Content);
  }
  for (const file of submittedFiles) {
    if (privatePaths.has(file.path)) {
      console.warn(
        `[grade] Submission attempted to override private workspace file ${file.path}; skipping`,
      );
      continue;
    }
    merged.set(file.path, file.content);
  }

  return [...merged].map(([path, content]) => ({ path, content }));
}

/**
 * Composes the GameGuild assessment adapter over the neutral IDE. Private
 * files are omitted from the editor workspace; the session overlays them only
 * while running trusted full tests in the instructor's browser.
 */
export function AssessmentGrader({
  assignment,
  submittedFiles,
  maxScore,
  manifestUrl,
  submissionId,
  onComputedScore,
}: AssessmentGraderProps): React.JSX.Element {
  const [computed, setComputed] = useState<ComputedScore | null>(null);
  const mergedFiles = useMemo(
    () => mergeWorkspaceWithSubmission(assignment, submittedFiles),
    [assignment, submittedFiles],
  );
  const workspaceConfig = useMemo(() => {
    const privatePaths = buildPrivatePaths(assignment);
    const files = Object.fromEntries(
      mergedFiles
        .filter((file) => !privatePaths.has(file.path))
        .map((file) => [
          file.path,
          {
            encoding: assignment.Data.Files[file.path]?.Encoding ?? 'text',
            content: file.content,
          },
        ]),
    );
    const language = (assignment.Environment.Language || 'cpp') as CodingLanguage;
    return createAssessmentWorkspaceConfig(language, files);
  }, [assignment, mergedFiles]);
  const noStudentCode = submittedFiles.length === 0;

  const handleRunResult = useCallback(
    (result: AssessmentRunResult) => {
      const next = {
        score: result.score.score,
        autoFeedback: formatFeedback(result.report, result.score.score),
      };
      setComputed(next);
      onComputedScore?.(next);
    },
    [onComputedScore],
  );

  return (
    <div data-testid="code-grader-panel" className="flex h-full flex-col gap-3 p-3">
      {computed ? (
        <p className="text-sm font-semibold" data-testid="computed-score">
          Computed score: {computed.score} / {maxScore}
        </p>
      ) : null}

      {noStudentCode ? (
        <div
          data-testid="no-student-code"
          className="rounded border border-amber-500 bg-amber-50 p-3 text-sm text-amber-800 dark:bg-amber-950 dark:text-amber-200"
        >
          This submission contains no student code. The editor shows the assignment template only.
        </div>
      ) : null}

      <div className="min-h-[400px] flex-1 border">
        <CodingAssessmentEditor
          mode="grader"
          definition={assignment}
          manifestUrl={manifestUrl}
          title="Grade submission"
          workspaceConfig={workspaceConfig}
          workspaceStorageKey={submissionId ? `emception:grader:${submissionId}` : undefined}
          enableWorkspace={false}
          maxScore={maxScore}
          passingScore={0}
          onRunResult={handleRunResult}
        />
      </div>
    </div>
  );
}

"use client";

import type { CodingAssignmentContent } from "@/lib/coding-assignment/types";
import type { CodingAssessmentEditorProps } from "@game-guild/emception-ui/assessment/editor";
import {
  createAssessmentWorkspaceConfig,
  type CodingLanguage,
} from "@game-guild/emception-ui/assessment/presets";
import { useEffect, useMemo, useState, type ComponentType } from "react";
import { EMCEPTION_MANIFEST_URL } from "@/lib/emception/manifest-url";

interface CodingAssignmentPreviewProps {
  assignment: CodingAssignmentContent;
}

export function CodingAssignmentPreview({
  assignment,
}: CodingAssignmentPreviewProps) {
  const [Editor, setEditor] =
    useState<ComponentType<CodingAssessmentEditorProps> | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const language = (assignment.Environment.Language || "cpp") as CodingLanguage;
  const publicFiles = useMemo(
    () =>
      Object.fromEntries(
        Object.entries(assignment.Data.Files)
          .filter(([, file]) => file.Visibility !== "Private")
          .map(([path, file]) => [
            path,
            { encoding: file.Encoding, content: file.Content },
          ]),
      ),
    [assignment],
  );
  const workspaceConfig = useMemo(
    () => createAssessmentWorkspaceConfig(language, publicFiles),
    [language, publicFiles],
  );

  useEffect(() => {
    let active = true;
    void import("@game-guild/emception-ui/assessment/editor")
      .then(({ CodingAssessmentEditor }) => {
        if (active) setEditor(() => CodingAssessmentEditor);
      })
      .catch((error: unknown) => {
        if (active) {
          setLoadError(
            error instanceof Error
              ? error.message
              : "Unable to load the coding assignment preview.",
          );
        }
      });
    return () => {
      active = false;
    };
  }, []);

  if (loadError) {
    return (
      <p role="alert" className="text-sm text-destructive">
        {loadError}
      </p>
    );
  }

  if (!Editor) {
    return (
      <div className="flex h-96 items-center justify-center rounded-md border text-sm text-muted-foreground">
        Loading coding assignment preview…
      </div>
    );
  }

  return (
    <div className="h-[70vh] min-h-[500px] overflow-hidden rounded-md border">
      <Editor
        mode="learner"
        manifestUrl={EMCEPTION_MANIFEST_URL}
        definition={assignment}
        workspaceConfig={workspaceConfig}
        enableWorkspace={false}
        maxScore={assignment.Grading.MaxScore}
      />
    </div>
  );
}

