          </TooltipTrigger>
          <TooltipContent>Toggle curriculum</TooltipContent>
        </Tooltip>
        <Button
          variant="ghost"
          size="sm"
          className="gap-2 text-muted-foreground"
          onClick={() =>
            router.push(
              `${learningBase}/courses/${encodeURIComponent(courseSlug)}/content`,
            )
          }
        >
          <ArrowLeft />
          <span className="hidden md:inline">Curriculum</span>
        </Button>
        <Separator
          orientation="vertical"
          className="mx-1 hidden h-5 md:block"
        />
        <div className="hidden min-w-0 flex-1 md:block">
          <p className="truncate text-sm font-medium">{payload.title}</p>
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            <Badge variant="outline" className="h-5 rounded-sm px-1.5 text-sm">
              {item.status === "published" ? "Published" : "Draft"}
            </Badge>
            <span
              className={saveStatus === "conflict" ? "text-destructive" : ""}
            >
              {saveStatus === "saving" ? (
                <Loader2 className="mr-1 inline size-3 animate-spin" />
              ) : null}
              {statusCopy[saveStatus]}
            </span>
          </div>
        </div>
        <Select
          items={[
            { value: "editor", label: "Editor" },
            { value: "preview", label: "Preview" },
          ]}
          value={mode === "preview" ? "preview" : "editor"}
          onValueChange={(value) => setMode(value as "editor" | "preview")}
        >
          <SelectTrigger
            aria-label="Editor view"
            size="sm"
            className="w-24 lg:hidden"
          >
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectGroup>
              <SelectItem value="editor">Editor</SelectItem>
              <SelectItem value="preview">Preview</SelectItem>
            </SelectGroup>
          </SelectContent>
        </Select>
        <div className="hidden items-center rounded-md border bg-muted/25 p-0.5 lg:flex">
          {(["editor", "split", "preview"] as EditorMode[]).map((value) => (
            <Button
              key={value}
              aria-label={value}
              variant={mode === value ? "secondary" : "ghost"}
              size="sm"
              className="h-7 capitalize"
              onClick={() => setMode(value)}
            >
              {value === "split" ? (
                <SplitSquareHorizontal />
              ) : value === "preview" ? (
                <Play />
              ) : (
                <FileCode2 />
              )}
              <span className="hidden xl:inline">{value}</span>
            </Button>
          ))}
        </div>
        <Tooltip>
          <TooltipTrigger
            render={
              <Button
                variant="ghost"
                size="icon-sm"
                aria-label="Open student view"
                onClick={() => {
                  const learnerBase = `/${params.locale ?? "en-US"}/learn/courses/${encodeURIComponent(courseSlug)}`;
                  const href =
                    (payload.type === "Code" ||
                      payload.type === "Questionnaire") &&
                    linkedAssessment
                      ? `${learnerBase}/activities/assessment-${encodeURIComponent(linkedAssessment.id)}`
                      : payload.type === "Lesson"
                        ? `${learnerBase}/lessons/${encodeURIComponent(payload.slug)}`
                        : `${learnerBase}/activities/content-${encodeURIComponent(item.id)}`;
                  window.open(href, "_blank", "noopener,noreferrer");
                }}
              />
            }
          >
            <Users />
          </TooltipTrigger>
          <TooltipContent>Student view</TooltipContent>
        </Tooltip>
        <Button
          variant={
            rightPanel === "copilot" && rightOpen ? "secondary" : "ghost"
          }
          size="sm"
          aria-label="Open Copilot"
          onClick={openCopilot}
        >
          <Sparkles />
          <span className="hidden lg:inline">Copilot</span>
        </Button>
        <Button
          size="sm"
          aria-label="Publish changes"
          disabled={isPublishing || saveStatus === "conflict"}
          onClick={() => void handlePublish()}
        >
          {isPublishing ? <Loader2 className="animate-spin" /> : <Check />}
          <span className="hidden md:inline">Publish changes</span>
        </Button>
        <Tooltip>
          <TooltipTrigger
            render={
              <Button
                variant="ghost"
                size="icon-sm"
                aria-label="Insert media"
                onClick={() => setAssetPickerOpen(true)}
              />
            }
          >
            <ImageIcon className="size-4" />
          </TooltipTrigger>
          <TooltipContent>Insert media</TooltipContent>
        </Tooltip>
        <Tooltip>
          <TooltipTrigger
            render={
              <Button
                variant="ghost"
                size="icon-sm"
                aria-label="Toggle lesson panel"
                onClick={toggleRightPanel}
              />
            }
          >
            {rightOpen ? <PanelRightClose /> : <PanelRightOpen />}
          </TooltipTrigger>
          <TooltipContent>Toggle lesson panel</TooltipContent>
        </Tooltip>
      </header>

      {saveError || conflictBackup ? (
        <div
          role="status"
          className={`flex min-h-10 shrink-0 items-center justify-between gap-3 px-4 py-1.5 text-sm ${saveStatus === "conflict" ? "bg-destructive/10 text-destructive" : "bg-muted text-foreground"}`}
        >
          <span className="truncate">
            {saveStatus === "conflict"
              ? saveError
              : conflictBackup
                ? "Latest draft loaded. Your unsaved version is still available."
                : saveError}
          </span>
          <div className="flex shrink-0 items-center gap-1">
            {saveStatus === "conflict" ? (
              <Button
                variant="ghost"
                size="xs"
                onClick={() => void loadLatestDraft()}
              >
                <RotateCcw /> Load latest
              </Button>
            ) : conflictBackup ? (
              <>
                <Button
                  variant="ghost"
                  size="xs"
                  onClick={() => setConflictBackup(null)}
                >
                  Discard my copy
                </Button>
                <Button
                  variant="secondary"
                  size="xs"
                  onClick={restoreConflictCopy}
                >
                  Restore my changes
                </Button>
              </>
            ) : (
              <Button variant="ghost" size="xs" onClick={() => void persist()}>
                <RotateCcw /> Retry
              </Button>
            )}
          </div>
        </div>
      ) : null}

      <main className="relative flex min-h-0 flex-1">
        {mobileLeftOpen ? (
          <button
            type="button"
            aria-label="Close curriculum"
            className="fixed inset-x-0 bottom-0 top-14 z-30 bg-background/80 backdrop-blur-sm lg:hidden"
            onClick={() => setMobileLeftOpen(false)}
          />
        ) : null}
        {leftOpen || mobileLeftOpen ? (
          <aside
            aria-label="Course curriculum"
            className={`${mobileLeftOpen ? "flex" : "hidden"} fixed bottom-0 left-0 top-14 z-40 w-72 shrink-0 flex-col border-r bg-background shadow-xl lg:static lg:z-auto lg:w-64 lg:shadow-none ${leftOpen ? "lg:flex" : "lg:hidden"}`}
          >
            <div className="flex h-14 items-center gap-3 px-4">
              <div className="flex size-8 items-center justify-center rounded-md bg-primary/10 text-primary">
                <BookOpen className="size-4" />
              </div>
              <div className="min-w-0">
                <p className="truncate text-sm font-medium">{courseTitle}</p>
                <p className="text-sm text-muted-foreground">Curriculum</p>
              </div>
            </div>
            <div className="px-3 pb-3">
              <div className="relative">
                <Search className="absolute left-2.5 top-2.5 size-3.5 text-muted-foreground" />
                <Input
                  value={curriculumSearch}
                  onChange={(event) => setCurriculumSearch(event.target.value)}
                  placeholder="Search lessons and quizzes"
                  className="h-8 pl-8 text-sm"
                />
              </div>
            </div>
            <Separator />
            <ScrollArea className="min-h-0 flex-1">
              <nav aria-label="Course curriculum" className="space-y-0.5 p-2">
                {filteredCurriculum.map((entry) => {
                  const Icon = iconFor(entry.type);
                  const active = entry.id === item.id;
                  return (
                    <button
                      key={entry.id}
                      type="button"
                      className={`flex w-full items-center gap-2 rounded-md px-2.5 py-2 text-left text-sm transition-colors ${
                        active
                          ? "bg-primary/10 text-primary"
                          : "text-muted-foreground hover:bg-muted hover:text-foreground"
                      }`}
                      onClick={() => {
                        setMobileLeftOpen(false);
                        router.push(
                          `${learningBase}/courses/${encodeURIComponent(courseSlug)}/content/${encodeURIComponent(entry.slug)}`,
                        );
                      }}
                    >
                      <Icon className="size-3.5 shrink-0" />
                      <span className="min-w-0 flex-1 truncate">
                        {entry.title}
                      </span>
                      {entry.status === "published" ? (
                        <Check
                          className="size-3 text-primary"
                          aria-label="Published"
                        />
                      ) : (
                        <Clock3
                          className="size-3 text-muted-foreground"
                          aria-label="Draft"
                        />
                      )}
                    </button>
                  );
                })}
              </nav>
            </ScrollArea>
            <div className="flex h-10 items-center border-t px-3 text-sm text-muted-foreground">
              <span>{curriculum.length} items</span>
            </div>
          </aside>
        ) : null}

        <div className="min-w-0 flex-1">
          {mode === "split" ? (
            <div className="grid h-full min-h-0 grid-cols-1 2xl:grid-cols-2">
              <div className="min-h-0 border-r">{editorPanel}</div>
              <div className="hidden min-h-0 2xl:block">{previewPanel}</div>
            </div>
          ) : mode === "preview" ? (
            previewPanel
          ) : (
            editorPanel
          )}
        </div>

        {mobileRightOpen ? (
          <button
            type="button"
            aria-label="Close lesson panel"
            className="fixed inset-x-0 bottom-0 top-14 z-30 bg-background/80 backdrop-blur-sm xl:hidden"
            onClick={() => setMobileRightOpen(false)}
          />
        ) : null}
        {rightOpen || mobileRightOpen ? (
          <aside
            aria-label={
              rightPanel === "settings"
                ? "Lesson settings"
                : "AI authoring copilot"
            }
            className={`${mobileRightOpen ? "flex" : "hidden"} fixed bottom-0 right-0 top-14 z-40 w-[min(24rem,92vw)] shrink-0 flex-col border-l bg-background shadow-xl xl:static xl:z-auto xl:w-80 xl:shadow-none ${rightOpen ? "xl:flex" : "xl:hidden"}`}
          >
            <div className="flex h-12 items-center gap-1 border-b px-2">
              <Button
                variant={rightPanel === "settings" ? "secondary" : "ghost"}
                size="sm"
                className="flex-1"
                onClick={() => setRightPanel("settings")}
              >
                <Settings2 /> Settings
              </Button>
              <Button
                variant={rightPanel === "copilot" ? "secondary" : "ghost"}
                size="sm"
                className="flex-1"
                onClick={() => setRightPanel("copilot")}
              >
                <Bot /> Copilot
              </Button>
            </div>
            {rightPanel === "settings" ? (
              <ScrollArea className="min-h-0 flex-1">
                <div className="space-y-5 p-4">
                  <div>
                    <h2 className="text-sm font-semibold uppercase tracking-wide text-muted-foreground">
                      Publishing
                    </h2>
                    <div className="mt-3 space-y-4">
                      <div className="space-y-1.5">
                        <Label htmlFor="authoring-visibility">
                          Lesson access
                        </Label>
                        <Select
                          items={[
                            { value: "Public", label: "Enrolled students" },
                            { value: "MembersOnly", label: "Members only" },
                            { value: "Private", label: "Private" },
                          ]}
                          value={payload.visibility}
                          onValueChange={(value) =>
                            updatePayload(
                              "visibility",
                              value as AuthoringContentPayload["visibility"],
                            )
                          }
                        >
                          <SelectTrigger id="authoring-visibility" className="w-full">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectGroup>
                              <SelectItem value="Public">Enrolled students</SelectItem>
                              <SelectItem value="MembersOnly">Members only</SelectItem>
                              <SelectItem value="Private">Private</SelectItem>
                            </SelectGroup>
                          </SelectContent>
                        </Select>
                      </div>
                      <div className="flex items-center justify-between gap-3">
                        <div>
                          <Label htmlFor="authoring-required">
                            Required for completion
                          </Label>
                          <p className="mt-0.5 text-sm text-muted-foreground">
                            Students must complete this item.
                          </p>
                        </div>
                        <Switch
                          id="authoring-required"
                          checked={payload.isRequired}
                          onCheckedChange={(value) =>
                            updatePayload("isRequired", value)
                          }
                        />
                      </div>
                    </div>
                  </div>
                  {isGradedType ? (
                    <div className="space-y-3 rounded-md border p-4">
                      <div className="flex items-center justify-between gap-3">
                        <div>
                          <p className="font-medium">Graded</p>
                          <p className="text-sm text-muted-foreground">
                            Link this content to a gradebook assessment.
                          </p>
                        </div>
                        <Switch
                          aria-label="Graded"
                          checked={gradedChecked}
                          disabled={isGradedPending}
                          onCheckedChange={handleGradedToggle}
                        />
                      </div>
                      {isGradedPending && (
                        <p className="text-sm text-muted-foreground">
                          <Loader2 className="mr-2 inline h-3 w-3 animate-spin" />
                          Updating gradebook link…
                        </p>
                      )}
                      {gradedError && (
                        <p className="text-sm text-destructive">{gradedError}</p>
                      )}
                      {isCode && gradedChecked && isAutomatedReview && (
                        <div className="space-y-1 text-sm text-muted-foreground">
                          <p className="font-medium">Coding tests</p>
                          <p>
                            Language: {codingAssignment?.Environment.Language}
                          </p>
                          <p>
                            Test cases:{" "}
                            {(codingAssignment?.Tests.Public.length ?? 0) +
                              (codingAssignment?.Tests.Private.length ?? 0)}{" "}
                            ({codingAssignment?.Tests.Public.length ?? 0} public)
                          </p>
                          <p>
                            Passing score: {codingAssignment?.Grading.MaxScore}
                          </p>
                        </div>
                      )}
                      <AlertDialog
                        open={showGradedOffConfirm}
                        onOpenChange={setShowGradedOffConfirm}
                      >
                        <AlertDialogContent>
                          <AlertDialogHeader>
                            <AlertDialogTitle>Remove grading?</AlertDialogTitle>
                            <AlertDialogDescription>
                              This soft-deletes the linked assessment.
                              Existing submissions are preserved. Toggle Graded
                              back on to restore it.
                            </AlertDialogDescription>
                          </AlertDialogHeader>
                          <AlertDialogFooter>
                            <AlertDialogCancel>Cancel</AlertDialogCancel>
                            <AlertDialogAction
                              className={buttonVariants({
                                variant: "destructive",
                              })}
                              onClick={confirmGradedOff}
                            >
                              Remove grading
                            </AlertDialogAction>
                          </AlertDialogFooter>
                        </AlertDialogContent>
                      </AlertDialog>
                    </div>
                  ) : null}
                  <Separator />
                  <div className="space-y-3">
                    <h2 className="text-sm font-semibold uppercase tracking-wide text-muted-foreground">
                      Lesson details
                    </h2>
                    <div className="space-y-1.5">
                      <Label htmlFor="authoring-title">Title</Label>
                      <Input
                        id="authoring-title"
                        value={payload.title}
                        onChange={(event) => handleTitle(event.target.value)}
                      />
                    </div>
                    <div className="space-y-1.5">
                      <Label htmlFor="authoring-slug">URL slug</Label>
                      <Input
                        id="authoring-slug"
                        value={payload.slug}
                        onChange={(event) =>
                          updatePayload("slug", slugify(event.target.value))
                        }
                        onBlur={() =>
                          updatePayload("slug", normalizeSlug(payload.slug))
                        }
                      />
                      <p className="break-all text-xs text-muted-foreground">
                        {learningBase}/courses/{courseSlug}/content/
                        {payload.slug}
                      </p>
                    </div>
                    <div className="space-y-1.5">
                      <Label htmlFor="authoring-description">Description</Label>
                      <Textarea
                        id="authoring-description"
                        rows={3}
                        value={payload.description ?? ""}
                        onChange={(event) =>
                          updatePayload("description", event.target.value)
                        }
                      />
                    </div>
                    <div className="space-y-1.5">
                      <Label htmlFor="authoring-minutes">
                        Estimated minutes
                      </Label>
                      <div className="relative">
                        <Clock3 className="absolute left-2.5 top-2.5 size-3.5 text-muted-foreground" />
                        <Input
                          id="authoring-minutes"
                          type="number"
                          min={0}
                          className="pl-8"
                          value={payload.estimatedMinutes ?? ""}
                          onChange={(event) => {
                            const value = event.target.value;
                            updatePayload(
                              "estimatedMinutes",
                              value ? Number(value) : null,
                            );
                            updatePayload(
                              "estimatedMinutesSource",
                              value ? "Manual" : "Auto",
                            );
                          }}
                          placeholder="Auto"
                        />
                      </div>
                    </div>
                  </div>
                  <Separator />
                  <div className="space-y-2 text-sm text-muted-foreground">
                    <div className="flex justify-between">
                      <span>Format</span>
                      <span className="text-foreground">{formatLabel}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Draft revision</span>
                      <span className="text-foreground">{draft.revision}</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Published version</span>
                      <span className="text-foreground">
                        {draft.basePublishedVersion}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span>Last saved</span>
                      <AuthoringLocalTime
                        className="text-foreground"
                        value={draft.lastEditedAt}
                      />
                    </div>
                  </div>
                </div>
              </ScrollArea>
            ) : (
              <div className="flex min-h-0 flex-1 flex-col">
                <div className="border-b px-4 py-3">
                  <div className="flex items-center justify-between gap-2">
                    <div>
                      <p className="text-sm font-medium">
                        AI authoring copilot
                      </p>
                      <p className="text-sm text-muted-foreground">
                        Changes always require your approval.
                      </p>
                    </div>
                    <Badge variant="outline" className="font-mono text-sm">
                      {entitlement
                        ? `${entitlement.availableSoftCredits} SC`
                        : "… SC"}
                    </Badge>
                  </div>
                </div>
                <ScrollArea className="min-h-0 flex-1">
                  <div className="space-y-3 p-3">
                    {messages.length === 0 ? (
                      <div className="py-5 text-center">
                        <Sparkles className="mx-auto size-5 text-primary" />
                        <p className="mt-2 text-sm font-medium">
                          Improve this lesson
                        </p>
                        <p className="mx-auto mt-1 max-w-56 text-sm text-muted-foreground">
                          Ask for a rewrite, explanation, example, code sample,
                          summary, or quiz.
                        </p>
                        <div className="mt-4 grid gap-1.5">
                          {[
                            "Make this clearer and more concise",
                            "Add a practical example",
                            "Create a short knowledge check",
                          ].map((suggestion) => (
                            <Button
                              key={suggestion}
                              variant="outline"
                              size="sm"
                              className="h-auto justify-start py-2 text-left text-sm"
                              onClick={() => void runCopilot(suggestion)}
                            >
                              {suggestion}
                            </Button>
                          ))}
                        </div>
                      </div>
                    ) : null}
                    {messages.map((message) => (
                      <div
                        key={message.id}
                        className={
                          message.role === "user"
                            ? "ml-7 rounded-lg bg-primary px-3 py-2 text-sm text-primary-foreground"
                            : "mr-3 rounded-lg bg-muted px-3 py-2 text-sm leading-relaxed"
                        }
                      >
                        {message.content}
                      </div>
                    ))}
                    {isRunning ? (
                      <div className="flex items-center justify-between gap-3 px-2 py-1 text-sm text-muted-foreground">
                        <span className="flex items-center gap-2">
                          <Loader2 className="size-3 animate-spin" />
                          {activeRun?.errorCode === "AI_CANCEL_REQUESTED"
                            ? "Stopping Copilot…"
                            : "Generating proposal…"}
                        </span>
                        <Button
                          variant="ghost"
                          size="xs"
                          disabled={
                            activeRun?.errorCode === "AI_CANCEL_REQUESTED"
                          }
                          onClick={() => void stopCopilot()}
                        >
                          Stop
                        </Button>
                      </div>
                    ) : null}
                    {aiError ? (
                      <p className="rounded-md bg-destructive/10 p-2 text-sm text-destructive">
                        {aiError}
                      </p>
                    ) : null}
                    {activeRun?.usage.maximumEstimatedCost ? (
                      <div className="rounded-md bg-muted/50 p-2 text-sm text-muted-foreground">
                        Max {activeRun.usage.maximumEstimatedCost} SC · Used{" "}
                        {activeRun.usage.inputTokens +
                          activeRun.usage.outputTokens}{" "}
                        tokens · Settled {activeRun.usage.settledCost} SC
                      </div>
                    ) : null}
                  </div>
                </ScrollArea>
                <div className="space-y-2 border-t p-3">
                  {!isStructured &&
                  format !== "Video" &&
                  format !== "ExternalLink" ? (
                    <Select
                      items={[
                        { value: "ReplaceDocument", label: "Replace document" },
                        { value: "InsertAtCursor", label: "Insert at cursor" },
                      ]}
                      value={proposalMode}
                      onValueChange={(value) => setProposalMode(value as AiProposalKind)}
                    >
                      <SelectTrigger
                        aria-label="Proposal application"
                        className="h-8 w-full text-sm"
                      >
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectGroup>
                          <SelectItem value="ReplaceDocument">Replace document</SelectItem>
                          <SelectItem value="InsertAtCursor">Insert at cursor</SelectItem>
                        </SelectGroup>
                      </SelectContent>
                    </Select>
                  ) : null}
                  {format === "Video" || format === "ExternalLink" ? (
                    <p className="rounded-md bg-muted/50 px-2.5 py-2 text-sm text-muted-foreground">
                      {format === "Video"
                        ? "Video media is protected. Copilot can only propose metadata changes."
                        : "External resources are protected. Copilot can only propose metadata changes."}
                    </p>
                  ) : null}
                  <div className="relative">
                    <Textarea
                      aria-label="Ask Copilot"
                      value={copilotPrompt}
                      onChange={(event) => setCopilotPrompt(event.target.value)}
                      onKeyDown={(event) => {
                        if (event.key === "Enter" && !event.shiftKey) {
                          event.preventDefault();
                          void runCopilot();
                        }
                      }}
                      rows={3}
                      className="resize-none pr-10 text-sm"
                      placeholder="Ask AI to revise this lesson…"
                    />
                    <Button
                      size="icon-sm"
                      className="absolute bottom-2 right-2"
                      aria-label="Send to Copilot"
                      disabled={!copilotPrompt.trim() || isRunning}
                      onClick={() => void runCopilot()}
                    >
                      {isRunning ? (
                        <Loader2 className="animate-spin" />
                      ) : (
                        <Send />
                      )}
                    </Button>
                  </div>
                  <p className="text-sm text-muted-foreground">
                    Maximum cost is reserved first. Only actual token usage is
                    charged to your wallet.
                  </p>
                </div>
              </div>
            )}
          </aside>
        ) : null}
      </main>

      <Dialog open={diffOpen} onOpenChange={setDiffOpen}>
        <DialogContent className="grid h-[88dvh] max-w-[94vw] grid-rows-[auto_minmax(0,1fr)_auto] gap-0 overflow-hidden p-0 sm:max-w-[94vw]">
          <DialogHeader className="border-b px-5 py-4">
            <div className="flex items-start justify-between gap-4 pr-10">
              <div>
                <DialogTitle>Review AI proposal</DialogTitle>
                <DialogDescription>
                  Compare the current draft with the proposed content before
                  applying it.
                </DialogDescription>
              </div>
              <div className="flex rounded-md border p-0.5">
                <Button
                  variant={!unifiedDiff ? "secondary" : "ghost"}
                  size="xs"
                  onClick={() => setUnifiedDiff(false)}
                >
                  <ChevronsRight /> Side by side
                </Button>
                <Button
                  variant={unifiedDiff ? "secondary" : "ghost"}
                  size="xs"
                  onClick={() => setUnifiedDiff(true)}
                >
                  <ChevronsLeft /> Unified
                </Button>
              </div>
            </div>
          </DialogHeader>
          <div className="min-h-0 bg-background">
            {proposal ? (
              <Suspense
                fallback={
                  <div className="flex h-full items-center justify-center">
                    <Loader2 className="animate-spin" />
                  </div>
                }
              >
                <MonacoDiffEditor
                  original={proposal.originalContent}
                  modified={proposal.proposedContent}
                  language={format === "Html" ? "html" : "markdown"}
                  theme={resolvedTheme === "light" ? "vs-light" : "vs-dark"}
                  height="100%"
                  options={{
                    readOnly: true,
                    renderSideBySide: !unifiedDiff,
                    minimap: { enabled: false },
                    wordWrap: "on",
                  }}
                />
              </Suspense>
            ) : null}
          </div>
          <DialogFooter className="border-t px-5 py-3">
            <div className="mr-auto text-sm text-muted-foreground">
              Base draft revision {proposal?.baseDraftRevision}
            </div>
            {proposal ? (
              <>
                <Button
                  variant="outline"
                  onClick={() => void rejectProposal(proposal)}
                >
                  Discard
                </Button>
                <Button onClick={() => void acceptProposal(proposal)}>
                  <Check /> Accept and apply
                </Button>
              </>
            ) : null}
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <AssetsProvider scope={assetScope}>
        <AssetPickerDialog
          open={assetPickerOpen}
          onOpenChange={setAssetPickerOpen}
          onSelect={handleMediaSelected}
          title="Insert media"
          accept="image/*"
          kinds={["image"]}
        />
      </AssetsProvider>
    </div>
  );
}

"use client";

import { useRouter } from "@/i18n/navigation";
import { filesToCodePayload } from "@/lib/coding-assignment/code-payload";
import type { CodingAssignmentContent } from "@/lib/coding-assignment/types";
import type { LearnerMutationResult } from "@/lib/learner/activity-actions";
import { startIndividualRuntimeSubmission, submitRuntimeSubmission } from "@/lib/learning/grading-runtime-actions";
import { readCodeRuntimeDefinition } from "@/lib/coding-assignment/runtime";
import type { AssessmentSubmissionRuntimeViewV1 } from "@game-guild/grading";
import { buildAssessmentExecutionPlan } from "@game-guild/emception-ui/assessment/plan";
import type {
  AssessmentRunResult,
  AssessmentSession,
  CodingAssessmentEditorProps,
} from "@game-guild/emception-ui/assessment/editor";
import { EMCEPTION_MANIFEST_URL } from "@/lib/emception/manifest-url";
import {
  createAssessmentWorkspaceConfig,
  type CodingLanguage,
} from "@game-guild/emception-ui/assessment/presets";
import { workspaceStorageKey } from "@game-guild/emception-ui/assessment/storage";
import { Button } from "@game-guild/ui/components/button";
import { scoreUnitsToPoints } from "@/lib/learning/academic-values";
import type { TestReport, WorkspaceConfig } from "emception";
import Script from "next/script";
import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ComponentType,
  type FormEvent,
} from "react";
import { PublicTestEstimateBanner } from "./public-test-estimate-banner";
import { publicSeedFiles, type SeedFile } from "./resolve-seed";

type CodingEditorLoader = () => Promise<
  ComponentType<CodingAssessmentEditorProps>
>;

async function loadCodingEditor(): Promise<
  ComponentType<CodingAssessmentEditorProps>
> {
  const { CodingAssessmentEditor } =
    await import("@game-guild/emception-ui/assessment/editor");
  return CodingAssessmentEditor;
}

function IdeSkeleton() {
  return (
    <div
      data-testid="ide-skeleton"
      className="flex h-96 items-center justify-center rounded-md border border-white/10 bg-white/[0.03] text-sm text-muted-foreground"
    >
      Loading IDE…
    </div>
  );
}

export interface CodingActivityClientProps {
  assessmentId: string;
  enrollmentId: string;
  courseId: string;
  slug: string;
  /** v1 CodingAssignmentContent (Public-only — server strips Private). */
  assignment: CodingAssignmentContent;
  manifestUrl?: string;
  /** Namespaces the draft-storage token per user (page supplies; optional so
   *  the page can wire it independently — a bare assessmentId keeps the
   *  pre-namespacing keys, still reachable via the legacy fallback read). */
  userId?: string;
  /** Prior submission files for overlay restore; null = no submission yet. */
  submissionFiles?: SeedFile[] | null;
  /** Alternate lazy loader used by embedded hosts and deterministic tests. */
  loadEditor?: CodingEditorLoader;
}

export function CodingActivityClient(props: CodingActivityClientProps) {
  return <CodingActivitySession key={`${props.assessmentId}:${props.enrollmentId}`} {...props} />;
}

function CodingActivitySession({
  assessmentId,
  enrollmentId,
  slug,
  assignment: initialAssignment,
  manifestUrl,
  userId,
  submissionFiles,
  loadEditor = loadCodingEditor,
}: CodingActivityClientProps) {
  const sessionRef = useRef<AssessmentSession | null>(null);
  const router = useRouter();
  const [submitting, setSubmitting] = useState(false);
  const [report, setReport] = useState<TestReport | null>(null);
  const [result, setResult] = useState<LearnerMutationResult | null>(null);
  const [sessionReady, setSessionReady] = useState(false);
  const [assignment, setAssignment] = useState(initialAssignment);
  const [runtime, setRuntime] = useState<AssessmentSubmissionRuntimeViewV1 | null>(null);
  const [runtimeError, setRuntimeError] = useState<string | null>(null);
  const [startKey] = useState(() => crypto.randomUUID());
  const submitKey = useRef<string | null>(null);
  const [Editor, setEditor] =
    useState<ComponentType<CodingAssessmentEditorProps> | null>(null);
  const [editorLoadError, setEditorLoadError] = useState<string | null>(null);

  useEffect(() => {
    let active = true;
    void startIndividualRuntimeSubmission(assessmentId, enrollmentId, startKey).then((result) => {
      if (!active) return;
      if (!result.success) { setRuntimeError(result.error); return; }
      try {
        setAssignment(readCodeRuntimeDefinition(result.data));
        setRuntime(result.data);
      } catch (error) {
        setRuntimeError(error instanceof Error ? error.message : "The Code attempt is unavailable.");
      }
    }).catch((error: unknown) => {
      if (active) setRuntimeError(error instanceof Error ? error.message : "The Code attempt is unavailable.");
    });
    return () => { active = false; };
  }, [assessmentId, enrollmentId, startKey]);

  // The neutral IDE owns browser-only APIs (Monaco, Worker and WASM). Import it
  // after hydration so the server never evaluates its module graph. This avoids
  // Next's app-page loadable alias while keeping the IDE outside SSR.
  useEffect(() => {
    let active = true;

    void loadEditor()
      .then((CodingAssessmentEditor) => {
        if (active) setEditor(() => CodingAssessmentEditor);
      })
      .catch((error: unknown) => {
        if (!active) return;
        setEditorLoadError(
          error instanceof Error
            ? error.message
            : "Unable to load the coding editor.",
        );
      });

    return () => {
      active = false;
    };
  }, [loadEditor]);

  const receiveSession = useCallback((session: AssessmentSession) => {
    sessionRef.current = session;
    setSessionReady(true);
  }, []);
  const receiveRunResult = useCallback((runResult: AssessmentRunResult) => {
    setReport(runResult.report);
  }, []);

  const seedFiles = useMemo(() => publicSeedFiles(assignment), [assignment]);
  const publicPlan = useMemo(
    () => buildAssessmentExecutionPlan(assignment, "public").plan,
    [assignment],
  );
  const maxScore = assignment.Grading.MaxScore;
  // ponytail: PassingScore moved from GradingConfig to Program (T1/T3). Learner context
  // doesn't surface Program.PassingScore yet — default to 60 (the C# default + historical
  // constant) until T13 wires the course-level field through getCourseLearnerContext.
  const passingScore = 60;

  const language =
    (assignment.Environment.Language as CodingLanguage | undefined) ?? "cpp";
  const restoredFiles = useMemo(() => {
    const response = runtime?.execution.submittedResponse;
    if (!response) return submissionFiles ?? [];
    const payload = response.payload as { files: Record<string, { content: string; encoding: 'text' }> };
    return Object.entries(payload.files).map(([path, file]) => ({ path, ...file }));
  }, [runtime, submissionFiles]);
  const alreadySubmitted = runtime?.execution.submittedResponse != null;
  // The host template supplies language-specific compiler/runtime settings.
  // Its files are the public seed overlaid by a previous server submission;
  // the neutral IDE restores a newer local draft from workspaceStorageKey.
  const workspaceConfig = useMemo<WorkspaceConfig>(() => {
    const files = new Map(
      seedFiles.map(({ path, content, encoding }) => [
        path,
        { encoding, content },
      ]),
    );
    for (const file of restoredFiles) {
      files.set(file.path, { encoding: file.encoding, content: file.content });
    }
    return createAssessmentWorkspaceConfig(language, Object.fromEntries(files));
  }, [language, seedFiles, restoredFiles]);

  if (result?.success) {
    return (
      <div
        role="status"
        className="rounded-md border border-emerald-500/30 bg-emerald-500/10 p-5 text-emerald-100"
      >
        Submission received. Grades and instructor feedback will appear here
        when available.
      </div>
    );
  }

  async function handleSubmit(event: FormEvent) {
    event.preventDefault();
    if (submitting || !runtime || alreadySubmitted) return;
    setSubmitting(true);
    try {
      // Submission serializes the current editor state without recompiling it.
      // Public tests have their own explicit action; repeating a full browser
      // toolchain run here can keep the form in "Submitting" for over a minute.
      // The assessment session returns only editable public changes plus
      // permitted student-created text files.
      const modified = (await sessionRef.current?.getSubmissionDelta()) ?? [];
      submitKey.current ??= crypto.randomUUID();
      const outcome = await submitRuntimeSubmission(runtime.submissionId, {
        schemaVersion: 1,
        contentType: "coding-assignment",
        payloadSchema: "code-files/v1",
        payload: { files: JSON.parse(filesToCodePayload([...modified])) as Record<string, { content: string; encoding: 'text' }> },
      }, submitKey.current);
      setResult(outcome.success ? { success: true } : { success: false, error: outcome.error });
      if (outcome.success) {
        router.push(`/learn/courses/${slug}/activities`);
      }
    } catch (error) {
      setResult({
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Unable to submit the coding activity.",
      });
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <>
      <Script src="/coi-serviceworker.js" strategy="afterInteractive" />
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="h-[70vh] min-h-[500px]">
          {Editor && runtime ? (
            <Editor
              mode="learner"
              definition={assignment}
              workspaceConfig={workspaceConfig}
              workspaceStorageKey={workspaceStorageKey(
                userId ? `${userId}:${assessmentId}` : assessmentId,
                workspaceConfig.id,
              )}
              manifestUrl={manifestUrl ?? EMCEPTION_MANIFEST_URL}
              maxScore={maxScore}
              passingScore={passingScore}
              onSessionReady={receiveSession}
              onRunResult={receiveRunResult}
            />
          ) : runtimeError || editorLoadError ? (
            <p role="alert" className="text-sm text-destructive">
              {runtimeError || editorLoadError}
            </p>
          ) : (
            <IdeSkeleton />
          )}
        </div>
        {report ? (
          <PublicTestEstimateBanner
            report={report}
            plan={publicPlan}
            maxScore={maxScore}
            passingScore={passingScore}
          />
        ) : null}
        {result?.error ? (
          <p role="alert" className="text-sm text-destructive">
            {result.error}
          </p>
        ) : null}
        {alreadySubmitted ? (
          <div role="status" className="rounded-md border p-4 text-sm">
            <p>Submission received.</p>
            {runtime?.execution.learnerVisibleResult ? (
              <>
                <p>
                  Score: {scoreUnitsToPoints(runtime.execution.learnerVisibleResult.score ?? 0)} /{' '}
                  {scoreUnitsToPoints(runtime.execution.learnerVisibleResult.maxScore)}
                </p>
                {runtime.execution.learnerVisibleResult.feedback ? (
                  <p>{runtime.execution.learnerVisibleResult.feedback}</p>
                ) : null}
              </>
            ) : (
              <p>Grades and instructor feedback will appear here when available.</p>
            )}
          </div>
        ) : null}
        <div className="flex justify-end">
          <Button type="submit" disabled={submitting || !sessionReady || !runtime || alreadySubmitted}>
            {submitting ? "Submitting…" : "Submit"}
          </Button>
        </div>
      </form>
    </>
  );
}

"use client";

import { cn } from "@game-guild/ui/lib/utils";
import React, { useCallback, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@game-guild/ui/components/card";
import { Badge } from "@game-guild/ui/components/badge";
import { Button, buttonVariants } from "@game-guild/ui/components/button";
import { Input } from "@game-guild/ui/components/input";
import { Label } from "@game-guild/ui/components/label";
import { Textarea } from "@game-guild/ui/components/textarea";
import {
  SelectGroup,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@game-guild/ui/components/select";
import { Switch } from "@game-guild/ui/components/switch";
import { Separator } from "@game-guild/ui/components/separator";
import {
  ArrowLeft,
  CheckCircle2,
  ClipboardCheck,
  Clock,
  Code,
  FileCheck2,
  Gauge,
  Loader2,
  Plus,
  RotateCcw,
  Save,
  Trash2,
  Upload,
  X,
} from "lucide-react";
import type {
  Assessment,
  AssessmentAuthoringState,
  AssessmentGroup,
  AssessmentPresentationMode,
  AssessmentType,
} from "@/lib/learning/queries/assessments";
import {
  ASSESSMENT_PRIMARY_REVIEW_METHODS,
  buildReviewWorkflow,
  isPrimaryReviewMethodAvailable,
  readReviewWorkflow,
  REVIEW_METHOD_LABELS,
  type AssessmentReviewMethod,
} from "@/lib/learning/assessment-grading-methods";
import type { CourseContentItemViewModel } from "@/lib/learning/queries/course";
import { Link } from "@/i18n/navigation";
import {
  deleteAssessment,
  deleteRubric,
  prepareAssessmentRevision,
  publishAssessmentRevision,
  saveRubric,
  unpublishAssessmentRevision,
  updateAssessment,
} from "@/lib/learning/actions";
import { useLearningBase } from "@/lib/learning/use-learning-base";
import { normalizeSlug, slugify } from "@/lib/slugify";
import { RuntimeQuizTestRun } from "@/components/learning/grading/runtime-quiz-test-run";

const ASSESSMENT_TYPE_OPTIONS: { value: AssessmentType; label: string }[] = [
  { value: "Quiz", label: "Quiz" },
  { value: "Assignment", label: "Assignment" },
  { value: "Project", label: "Project" },
  { value: "PeerReview", label: "Peer Review" },
  { value: "SelfAssessment", label: "Self Assessment" },
];

const GROUP_SET_NONE = "none";

const RUBRIC_LOCK_MESSAGE = "Rubric locked after grading started";

const DEFAULT_PEER_REVIEWS = 3;

export function resolvePeerReviewsRequiredCount(value: string): number {
  const parsed = Number(value);
  return Number.isInteger(parsed) && parsed > 0 ? parsed : DEFAULT_PEER_REVIEWS;
}

function readPeerReviewsRequired(configuration: string | null): number {
  if (!configuration) return DEFAULT_PEER_REVIEWS;
  try {
    const parsed = JSON.parse(configuration) as {
      peer?: { reviewsRequiredPerSubmission?: unknown } | null;
    };
    const value = parsed.peer?.reviewsRequiredPerSubmission;
    return typeof value === "number" && Number.isInteger(value) && value > 0
      ? value
      : DEFAULT_PEER_REVIEWS;
  } catch {
    return DEFAULT_PEER_REVIEWS;
  }
}

function buildReviewConfiguration(
  current: string | null,
  primary: AssessmentReviewMethod,
  requiresInstructorReview: boolean,
  peerReviewsRequired: number,
): string {
  let parsed: Record<string, unknown> = {};
  try {
    parsed = current ? (JSON.parse(current) as Record<string, unknown>) : {};
  } catch {
    parsed = {};
  }

  const instructorSelected =
    primary === "InstructorReview" || requiresInstructorReview;
  return JSON.stringify({
    schemaVersion: 1,
    peer:
      primary === "PeerReview"
        ? {
            ...((parsed.peer as Record<string, unknown> | null) ?? {}),
            reviewsPerReviewer: peerReviewsRequired,
            reviewsRequiredPerSubmission: peerReviewsRequired,
            minimumReviewsToFinalize: peerReviewsRequired,
            aggregation: "mean",
            claimLeaseMinutes: 30,
            evidenceWindowMinutes: 10080,
            onInsufficientEvidence: "await-instructor-resolution",
          }
        : null,
    ai:
      primary === "AIReview"
        ? (parsed.ai ?? { providerKey: "unconfigured", policyVersion: "1" })
        : null,
    self:
      primary === "SelfReview"
        ? (parsed.self ?? { instructions: null, requireFeedback: true })
        : null,
    instructor: instructorSelected
      ? (parsed.instructor ?? { requireOverrideReason: false })
      : null,
  });
}

export interface GroupSetOption {
  id: string;
  name: string;
}

export interface RubricCriterionRow {
  description: string;
  points: number | null;
}

export interface RubricViewModel {
  title: string;
  criteria: { description: string; points: number; order: number }[];
}

interface AssessmentEditorProps {
  courseId: string;
  assessment: Assessment;
  authoringState?: AssessmentAuthoringState | null;
  assessmentGroups?: AssessmentGroup[];
  courseContent?: CourseContentItemViewModel[];
  groupSets?: GroupSetOption[];
  rubric?: RubricViewModel | null;
  rubricLocked?: boolean;
  canManage?: boolean;
}

function formatWeight(weightPercent: number) {
  return `${Number.isInteger(weightPercent) ? weightPercent : weightPercent.toFixed(1)}% of Total`;
}

export function AssessmentEditor({
  courseId,
  assessment,
  authoringState = null,
  assessmentGroups = [],
  courseContent = [],
  groupSets = [],
  rubric = null,
  rubricLocked = false,
  canManage = false,
}: AssessmentEditorProps) {
  const learningBase = useLearningBase();
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [isDeleting, startDeleteTransition] = useTransition();
  const [isPolicyPending, startPolicyTransition] = useTransition();
  const [isRubricPending, startRubricTransition] = useTransition();
  const [isLifecyclePending, startLifecycleTransition] = useTransition();
  const isQuiz = assessment.type === "Quiz";
  const isLinkedQuiz = isQuiz && assessment.contentId != null;
  const isLinkedCode = assessment.contentId != null && courseContent.some(
    (content) => content.id === assessment.contentId && content.type === "Code",
  );
  const [versionOverride, setVersionOverride] = useState<{
    source: number;
    value: number;
  } | null>(null);
  const assessmentVersion =
    versionOverride?.source === assessment.version
      ? versionOverride.value
      : assessment.version;
  const setAssessmentVersion = useCallback(
    (next: number | ((current: number) => number)) => {
      setVersionOverride((current) => {
        const currentVersion =
          current?.source === assessment.version
            ? current.value
            : assessment.version;

        return {
          source: assessment.version,
          value:
            typeof next === "function" ? next(currentVersion) : next,
        };
      });
    },
    [assessment.version],
  );

  const [title, setTitle] = useState(assessment.title);
  const [slug, setSlug] = useState(assessment.slug);
  // Slug starts in auto mode regardless of the stored value (it may be a
  // legacy backfill): title edits regenerate it until the slug is edited
  // directly in this session, which detaches it.
  const [autoSlug, setAutoSlug] = useState(true);
  const [description, setDescription] = useState(assessment.description ?? "");
  const [maxScore, setMaxScore] = useState(String(assessment.maxScore));
  const [passingScore, setPassingScore] = useState(
    String(assessment.passingScore),
  );
  const [timeLimitMinutes, setTimeLimitMinutes] = useState(
    assessment.timeLimitMinutes != null
      ? String(assessment.timeLimitMinutes)
      : "",
  );
  const [maxAttempts, setMaxAttempts] = useState(
    assessment.maxAttempts != null ? String(assessment.maxAttempts) : "",
  );
  const [isRequired, setIsRequired] = useState(assessment.isRequired);
  const [assessmentGroupId, setAssessmentGroupId] = useState(
    assessment.assessmentGroupId ?? "none",
  );
  const [presentationMode, setPresentationMode] =
    useState<AssessmentPresentationMode>(assessment.presentationMode);
  const [availableFrom, setAvailableFrom] = useState(
    assessment.availableFrom ? assessment.availableFrom.slice(0, 16) : "",
  );
  const [availableUntil, setAvailableUntil] = useState(
    assessment.availableUntil ? assessment.availableUntil.slice(0, 16) : "",
  );
  const initialReviewWorkflow = readReviewWorkflow(assessment.reviewMethods);
  const [primaryReviewMethod, setPrimaryReviewMethod] =
    useState<AssessmentReviewMethod>(
      initialReviewWorkflow.primary ?? "InstructorReview",
    );
  const [requiresInstructorReview, setRequiresInstructorReview] = useState(
    initialReviewWorkflow.requiresInstructorReview,
  );
  const [contentCompletionMode, setContentCompletionMode] = useState(
    assessment.contentCompletionMode,
  );
  const [resultReleaseMode, setResultReleaseMode] = useState(
    assessment.resultReleaseMode,
  );
  const [groupSetId, setGroupSetId] = useState(
    assessment.groupSetId ?? GROUP_SET_NONE,
  );
  const [groupAssignmentOn, setGroupAssignmentOn] = useState(
    assessment.groupSetId != null,
  );
  const [peerReviewsRequired, setPeerReviewsRequired] = useState(
    String(
      readPeerReviewsRequired(assessment.reviewConfigurationCanonicalJson),
    ),
  );
  const [rubricOn, setRubricOn] = useState(rubric != null);
  const [rubricTitle] = useState(rubric?.title ?? "Rubric");
  const [criteria, setCriteria] = useState<RubricCriterionRow[]>(() =>
    rubric != null && rubric.criteria.length > 0
      ? rubric.criteria.map((criterion) => ({
          description: criterion.description,
          points: criterion.points,
        }))
      : [{ description: "", points: null }],
  );
  const [rubricLockedLocal, setRubricLockedLocal] = useState(rubricLocked);
  const [rubricSaved, setRubricSaved] = useState(false);

  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);

  function handleTitleChange(value: string) {
    setTitle(value);
    if (autoSlug) {
      setSlug(slugify(value));
    }
  }

  function handleSlugChange(value: string) {
    setAutoSlug(false);
    setSlug(slugify(value));
  }

  function handleSave() {
    if (!title.trim()) {
      setError("Title is required.");
      return;
    }
    setError(null);
    setSaved(false);

    startTransition(async () => {
      const reviewMethods = buildReviewWorkflow(
        primaryReviewMethod,
        requiresInstructorReview,
      );
      const requiredPeerReviews =
        resolvePeerReviewsRequiredCount(peerReviewsRequired);
      const result = await updateAssessment({
        courseId,
        assessmentId: assessment.id,
        expectedVersion: assessmentVersion,
        ...(isLinkedQuiz
          ? {}
          : {
              title: title.trim(),
              slug: normalizeSlug(slug) || normalizeSlug(title),
              description: description.trim() || null,
            }),
        maxScore: isLinkedQuiz
          ? undefined
          : maxScore === ""
            ? undefined
            : Number(maxScore),
        passingScore: passingScore === "" ? undefined : Number(passingScore),
        timeLimitMinutes: timeLimitMinutes ? Number(timeLimitMinutes) : null,
        maxAttempts: maxAttempts ? Number(maxAttempts) : null,
        isRequired,
        availableFrom: availableFrom || null,
        availableUntil: availableUntil || null,
        assessmentGroupId:
          assessmentGroupId === "none" ? null : assessmentGroupId,
        clearAssessmentGroupId: assessmentGroupId === "none",
        presentationMode,
        reviewMethods,
        reviewConfigurationCanonicalJson: buildReviewConfiguration(
          assessment.reviewConfigurationCanonicalJson,
          primaryReviewMethod,
          requiresInstructorReview,
          requiredPeerReviews,
        ),
        contentCompletionMode,
        resultReleaseMode,
      });

      if (!result.success) {
        setError(result.error);
        return;
      }

      setAssessmentVersion(result.data.version);
      setSaved(true);

      // The editor route resolves by slug or id — after a slug change the
      // current URL is stale, so replace it instead of refreshing in place.
      const savedSlug = normalizeSlug(slug) || normalizeSlug(title);
      if (!isLinkedQuiz && savedSlug && savedSlug !== assessment.slug) {
        router.replace(
          `${learningBase}/courses/${encodeURIComponent(courseId)}/assessments/${savedSlug}`,
        );
      } else {
        router.refresh();
      }
    });
  }

  function handleDelete() {
    if (!confirm("Are you sure you want to delete this assessment?")) return;

    startDeleteTransition(async () => {
      const result = await deleteAssessment(courseId, assessment.id);
      if (result.success) {
        router.push(
          `${learningBase}/courses/${encodeURIComponent(courseId)}/assessments`,
        );
      } else {
        setError(result.error);
      }
    });
  }

  function handleBack() {
    router.push(
      `${learningBase}/courses/${encodeURIComponent(courseId)}/assessments`,
    );
  }

  function handleGroupAssignmentToggle(checked: boolean) {
    setGroupAssignmentOn(checked);
    setError(null);

    if (checked || groupSetId === GROUP_SET_NONE) {
      return;
    }

    const previous = groupSetId;
    setGroupSetId(GROUP_SET_NONE);

    startPolicyTransition(async () => {
      const result = await updateAssessment({
        courseId,
        assessmentId: assessment.id,
        expectedVersion: assessmentVersion,
        groupSetId: null,
        clearGroupSetId: true,
      });

      if (!result.success) {
        setGroupSetId(previous);
        setGroupAssignmentOn(true);
        setError(result.error);
        return;
      }

      setAssessmentVersion(result.data.version);
      router.refresh();
    });
  }

  function handleGroupSetChange(value: string) {
    const previous = groupSetId;
    setGroupSetId(value);
    setError(null);

    startPolicyTransition(async () => {
      const result = await updateAssessment({
        courseId,
        assessmentId: assessment.id,
        expectedVersion: assessmentVersion,
        groupSetId: value === GROUP_SET_NONE ? null : value,
        clearGroupSetId: value === GROUP_SET_NONE,
      });

      if (!result.success) {
        setGroupSetId(previous);
        setError(result.error);
        return;
      }

      setAssessmentVersion(result.data.version);
      router.refresh();
    });
  }

  const rubricLockedNow = rubricLockedLocal;
  const criteriaPointsSum = criteria.reduce(
    (sum, row) => sum + (row.points ?? 0),
    0,
  );
  const criteriaValid =
    criteria.length > 0 &&
    criteria.every(
      (row) =>
        row.description.trim() !== "" && row.points != null && row.points > 0,
    );
  const rubricSumMatches = criteriaPointsSum === assessment.maxScore;
  const canSaveRubric = criteriaValid && rubricSumMatches && !rubricLockedNow;

  function addCriterionRow() {
    setCriteria((rows) => [...rows, { description: "", points: null }]);
  }

  function removeCriterionRow(index: number) {
    setCriteria((rows) =>
      rows.length > 1
        ? rows.filter((_, rowIndex) => rowIndex !== index)
        : [{ description: "", points: null }],
    );
  }

  function handleSaveRubric() {
    setError(null);
    setRubricSaved(false);

    startRubricTransition(async () => {
      const result = await saveRubric({
        assessmentId: assessment.id,
        title: rubricTitle,
        criteria: criteria.map((row, index) => ({
          description: row.description.trim(),
          // The save action is enabled only when every criterion has points.
          points: row.points as number,
          order: index,
        })),
      });

      if (!result.success) {
        if (result.error.includes(RUBRIC_LOCK_MESSAGE)) {
          setRubricLockedLocal(true);
          setError(null);
          return;
        }
        setError(result.error);
        return;
      }

      setRubricSaved(true);
      router.refresh();
    });
  }

  function handleDeleteRubric() {
    if (
      !confirm(
        "Are you sure you want to remove the rubric from this assessment?",
      )
    ) {
      return;
    }

    startRubricTransition(async () => {
      const result = await deleteRubric(assessment.id);

      if (!result.success) {
        if (result.error.includes(RUBRIC_LOCK_MESSAGE)) {
          setRubricLockedLocal(true);
          setError(null);
          return;
        }
        setError(result.error);
        return;
      }

      setRubricOn(false);
      setCriteria([{ description: "", points: null }]);
      router.refresh();
    });
  }

  function handlePrepareRevision() {
    setError(null);
    startLifecycleTransition(async () => {
      const result = await prepareAssessmentRevision(
        courseId,
        assessment.id,
        assessmentVersion,
      );
      if (!result.success) {
        setError(result.error);
        return;
      }
      router.refresh();
    });
  }

  function handlePublishRevision() {
    const candidate = authoringState?.candidate;
    if (!candidate) return;

    setError(null);
    startLifecycleTransition(async () => {
      const result = await publishAssessmentRevision(
        courseId,
        assessment.id,
        candidate.revisionId,
        assessmentVersion,
      );
      if (!result.success) {
        setError(result.error);
        return;
      }
      setAssessmentVersion((version) => version + 1);
      router.refresh();
    });
  }

  function handleUnpublishRevision() {
    const published = authoringState?.published;
    if (!published) return;

    setError(null);
    startLifecycleTransition(async () => {
      const result = await unpublishAssessmentRevision(
        courseId,
        assessment.id,
        published.revisionId,
        assessmentVersion,
        crypto.randomUUID(),
      );
      if (!result.success) {
        setError(result.error);
        return;
      }
      setAssessmentVersion((version) => version + 1);
      router.refresh();
    });
  }

  const typeLabel =
    ASSESSMENT_TYPE_OPTIONS.find((o) => o.value === assessment.type)?.label ??
    assessment.type;
  const selectedAssessmentGroup = assessmentGroups.find(
    (group) => group.id === assessmentGroupId,
  );
  const assessmentRole = !selectedAssessmentGroup
    ? "Unconfigured"
    : selectedAssessmentGroup.weightPercent === 0
      ? "Practice"
      : "Gradebook";

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="sm" onClick={handleBack}>
          <ArrowLeft className="mr-2 h-4 w-4" />
          Back
        </Button>
        <div className="flex-1">
          <p className="text-muted-foreground text-sm">Assessment Editor</p>
          <h1 className="text-2xl font-bold">{assessment.title}</h1>
        </div>
        {canManage && (
          <Link
            href={`/speedgrader/assessments/${assessment.id}?course=${encodeURIComponent(courseId)}`}
            data-testid="start-speedgrader-button"
            className={cn(buttonVariants({ variant: "outline", size: "sm" }))}
          >
            <Gauge className="mr-2 h-4 w-4" />
            SpeedGrader
          </Link>
        )}
        {canManage && (
          <Link
            href={`${learningBase}/courses/${encodeURIComponent(courseId)}/assessments/${assessment.slug}/submissions`}
            data-testid="grade-submissions-button"
            className={cn(buttonVariants({ variant: "outline", size: "sm" }))}
          >
            <ClipboardCheck className="mr-2 h-4 w-4" />
            Grade submissions
          </Link>
        )}
        <Badge variant="secondary">{typeLabel}</Badge>
        <Badge variant={assessmentRole === "Gradebook" ? "default" : "outline"}>
          {assessmentRole}
        </Badge>
      </div>

      <div className="grid gap-6 lg:grid-cols-3">
        {/* Main editor */}
        <div className="space-y-6 lg:col-span-2">
          <Card>
            <CardHeader>
              <CardTitle>Details</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="title">Title</Label>
                <Input
                  id="title"
                  value={title}
                  onChange={(e) => handleTitleChange(e.target.value)}
                  placeholder="Assessment title"
                  disabled={isLinkedQuiz}
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="slug">URL Slug</Label>
                <Input
                  id="slug"
                  value={slug}
                  onChange={(e) => handleSlugChange(e.target.value)}
                  onBlur={() => setSlug(normalizeSlug(slug))}
                  placeholder="midterm-exam"
                  disabled={isLinkedQuiz}
                />
                <p className="text-muted-foreground text-xs">
                  Auto-generated from title. Edit to customize.
                </p>
              </div>

              <div className="space-y-2">
                <Label htmlFor="description">Description</Label>
                <Textarea
                  id="description"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="Instructions or description for students"
                  rows={4}
                  disabled={isLinkedQuiz}
                />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>Scoring</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="max-score">Max Score</Label>
                  <Input
                    id="max-score"
                    type="number"
                    min={1}
                    value={maxScore}
                    onChange={(e) => setMaxScore(e.target.value)}
                    disabled={isLinkedQuiz}
                  />
                  {isQuiz && assessment.contentId != null && (
                    <p className="text-muted-foreground text-xs">
                      Calculated from the quiz question points.
                    </p>
                  )}
                </div>
                <div className="space-y-2">
                  <Label htmlFor="passing-score">Passing Score</Label>
                  <Input
                    id="passing-score"
                    type="number"
                    min={0}
                    value={passingScore}
                    onChange={(e) => setPassingScore(e.target.value)}
                  />
                </div>
              </div>
              <p className="text-muted-foreground text-xs">
                Students need at least {passingScore || 0} out of{" "}
                {maxScore || 0} points to pass (
                {maxScore && Number(maxScore) > 0
                  ? Math.round(
                      (Number(passingScore || 0) / Number(maxScore)) * 100,
                    )
                  : 0}
                %).
              </p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle>Rubric</CardTitle>
                <div className="flex items-center gap-2">
                  <Label
                    htmlFor="grade-by-rubric"
                    className="text-sm font-normal text-muted-foreground"
                  >
                    Grade by rubric
                  </Label>
                  <Switch
                    id="grade-by-rubric"
                    checked={rubricOn}
                    onCheckedChange={(checked) => setRubricOn(checked === true)}
                    disabled={rubricLockedNow}
                  />
                </div>
              </div>
            </CardHeader>
            {rubricOn && (
              <CardContent className="space-y-4">
                {rubricLockedNow && (
                  <p className="text-destructive text-sm" role="alert">
                    {RUBRIC_LOCK_MESSAGE}
                  </p>
                )}
                <div className="space-y-3">
                  {criteria.map((row, index) => (
                    <div key={index} className="flex items-end gap-2">
                      <div className="flex-1 space-y-1">
                        <Label htmlFor={`criterion-${index + 1}-description`}>
                          Criterion {index + 1} description
                        </Label>
                        <Input
                          id={`criterion-${index + 1}-description`}
                          value={row.description}
                          onChange={(e) =>
                            setCriteria((rows) =>
                              rows.map((current, rowIndex) =>
                                rowIndex === index
                                  ? { ...current, description: e.target.value }
                                  : current,
                              ),
                            )
                          }
                          placeholder="What this criterion assesses"
                          disabled={isRubricPending || rubricLockedNow}
                        />
                      </div>
                      <div className="w-24 space-y-1">
                        <Label htmlFor={`criterion-${index + 1}-points`}>
                          Criterion {index + 1} points
                        </Label>
                        <Input
                          id={`criterion-${index + 1}-points`}
                          type="number"
                          min={0.01}
                          step={0.01}
                          value={row.points ?? ""}
                          onChange={(e) =>
                            setCriteria((rows) =>
                              rows.map((current, rowIndex) =>
                                rowIndex === index
                                  ? {
                                      ...current,
                                      points: e.target.value
                                        ? Number(e.target.value)
                                        : null,
                                    }
                                  : current,
                              ),
                            )
                          }
                          disabled={isRubricPending || rubricLockedNow}
                        />
                      </div>
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        aria-label={`Remove criterion ${index + 1}`}
                        onClick={() => removeCriterionRow(index)}
                        disabled={isRubricPending}
                      >
                        <X className="size-4" />
                      </Button>
                    </div>
                  ))}
                </div>

                <div className="flex items-center justify-between">
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={addCriterionRow}
                    disabled={isRubricPending}
                  >
                    <Plus className="mr-2 size-4" />
                    Add criterion
                  </Button>
                  <p
                    data-testid="rubric-sum"
                    className={`text-sm font-semibold ${
                      rubricSumMatches ? "text-green-600" : "text-destructive"
                    }`}
                  >
                    Σ {criteriaPointsSum} / {assessment.maxScore}
                    {!rubricSumMatches && (
                      <span>
                        {" "}
                        ({criteriaPointsSum > assessment.maxScore ? "+" : ""}
                        {criteriaPointsSum - assessment.maxScore})
                      </span>
                    )}
                  </p>
                </div>

                <div className="flex items-center gap-2">
                  <Button
                    type="button"
                    onClick={handleSaveRubric}
                    disabled={!canSaveRubric || isRubricPending}
                  >
                    {isRubricPending ? (
                      <Loader2 className="mr-2 size-4 animate-spin" />
                    ) : (
                      <Save className="mr-2 size-4" />
                    )}
                    Save rubric
                  </Button>
                  <Button
                    type="button"
                    variant="outline"
                    onClick={handleDeleteRubric}
                    disabled={isRubricPending}
                  >
                    <Trash2 className="mr-2 size-4" />
                    Delete rubric
                  </Button>
                  {rubricSaved && (
                    <span className="text-sm text-green-600">
                      Rubric saved.
                    </span>
                  )}
                </div>
                <p className="text-muted-foreground text-xs">
                  Criterion points must sum to the assessment max score. Locked
                  after grading starts.
                </p>
              </CardContent>
            )}
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>Availability</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="available-from">Available From</Label>
                  <Input
                    id="available-from"
                    type="datetime-local"
                    value={availableFrom}
                    onChange={(e) => setAvailableFrom(e.target.value)}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="available-until">Available Until</Label>
                  <Input
                    id="available-until"
                    type="datetime-local"
                    value={availableUntil}
                    onChange={(e) => setAvailableUntil(e.target.value)}
                  />
                </div>
              </div>
              <p className="text-muted-foreground text-xs">
                Leave empty to make the assessment always available.
              </p>
            </CardContent>
          </Card>
        </div>

        {/* Sidebar */}
        <div className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>Settings</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <Label>Type</Label>
                <Select
                  items={[
                    ...ASSESSMENT_TYPE_OPTIONS.map((opt) => ({
                      value: opt.value,
                      label: opt.label,
                    })),
                  ]}
                  value={assessment.type}
                  disabled
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectGroup>
                      {ASSESSMENT_TYPE_OPTIONS.map((opt) => (
                        <SelectItem key={opt.value} value={opt.value}>
                          {opt.label}
                        </SelectItem>
                      ))}
                    </SelectGroup>
                  </SelectContent>
                </Select>
                <p className="text-muted-foreground text-xs">
                  Type cannot be changed after creation.
                </p>
              </div>

              <Separator />

              <div className="space-y-2">
                <Label htmlFor="grade-group">Grading group</Label>
                <Select
                  items={[
                    { value: "none", label: "No group" },
                    ...assessmentGroups.map((group) => ({
                      value: group.id,
                      label: `${group.name} (${formatWeight(group.weightPercent)})`,
                    })),
                  ]}
                  value={assessmentGroupId}
                  onValueChange={(value) => setAssessmentGroupId(value ?? "none")}
                >
                  <SelectTrigger id="grade-group">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectGroup>
                      <SelectItem value="none">No group</SelectItem>
                      {assessmentGroups.map((group) => (
                        <SelectItem key={group.id} value={group.id}>
                          {group.name} ({formatWeight(group.weightPercent)})
                        </SelectItem>
                      ))}
                    </SelectGroup>
                  </SelectContent>
                </Select>
                <p className="text-muted-foreground text-xs">
                  Zero-weight groups are practice activities. Positive-weight
                  groups contribute to the gradebook.
                </p>
              </div>

              <div className="space-y-2">
                <Label>Assessment role</Label>
                <Input value={assessmentRole} readOnly className="bg-muted" />
              </div>

              <Separator />

              <div className="space-y-2">
                <Label>Linked content</Label>
                {(() => {
                  const item = courseContent.find(
                    (c) => c.id === assessment.contentId,
                  );
                  return assessment.contentId != null ? (
                    <div className="space-y-1">
                      <Link
                        href={`${learningBase}/courses/${encodeURIComponent(courseId)}/content/${item?.slug ?? assessment.contentId}`}
                        className="text-sm text-primary underline-offset-4 hover:underline"
                        data-testid="linked-content-link"
                      >
                        {item?.title ?? assessment.contentId}
                      </Link>
                      <p className="text-muted-foreground text-xs">
                        This assessment was created by its content and cannot be
                        unlinked.
                      </p>
                    </div>
                  ) : (
                    <p
                      className="text-muted-foreground text-sm"
                      data-testid="linked-content-none"
                    >
                      Not linked (standalone assessment).
                    </p>
                  );
                })()}
              </div>

              <Separator />

              {(isLinkedQuiz || isLinkedCode) && authoringState && (
                <>
                  <div
                    className="space-y-3"
                    data-testid="assessment-publication-state"
                  >
                    <div className="flex items-center justify-between gap-3">
                      <Label>Revision lifecycle</Label>
                      <Badge
                        variant={
                          authoringState.lifecycle === "published"
                            ? "default"
                            : authoringState.lifecycle === "changes-pending"
                              ? "destructive"
                              : "outline"
                        }
                      >
                        {authoringState.lifecycle === "draft" && "Draft"}
                        {authoringState.lifecycle === "candidate" &&
                          "Candidate"}
                        {authoringState.lifecycle === "published" &&
                          "Published"}
                        {authoringState.lifecycle === "changes-pending" &&
                          "Changes pending"}
                      </Badge>
                    </div>

                    <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-1">
                      <div className="rounded-md border p-3">
                        <div className="flex items-center gap-2 text-sm font-medium">
                          <FileCheck2 className="size-4" aria-hidden="true" />
                          Candidate
                        </div>
                        <p className="text-muted-foreground mt-1 text-xs">
                          {authoringState.candidate
                            ? `Revision ${authoringState.candidate.revisionNumber}${
                                authoringState.candidateMatchesDraft
                                  ? " matches the draft"
                                  : " is outdated"
                              }.`
                            : "No candidate prepared."}
                        </p>
                      </div>
                      <div className="rounded-md border p-3">
                        <div className="flex items-center gap-2 text-sm font-medium">
                          <CheckCircle2 className="size-4" aria-hidden="true" />
                          Active
                        </div>
                        <p className="text-muted-foreground mt-1 text-xs">
                          {authoringState.published
                            ? `Revision ${authoringState.published.revisionNumber}${
                                authoringState.publishedMatchesDraft
                                  ? " matches the draft"
                                  : " has unpublished changes"
                              }.`
                            : "No active revision."}
                        </p>
                      </div>
                    </div>

                    <div className="flex flex-wrap gap-2">
                      <Button
                        type="button"
                        size="sm"
                        variant="outline"
                        onClick={handlePrepareRevision}
                        disabled={
                          isLifecyclePending ||
                          !authoringState.prepare.available
                        }
                      >
                        {isLifecyclePending ? (
                          <Loader2 className="mr-2 size-4 animate-spin" />
                        ) : (
                          <FileCheck2 className="mr-2 size-4" />
                        )}
                        Prepare
                      </Button>
                      {isLinkedQuiz && authoringState.candidate && (
                        <RuntimeQuizTestRun
                          assessmentId={assessment.id}
                          revisionId={authoringState.candidate.revisionId}
                          reviewMethods={assessment.reviewMethods}
                          peerReviewsRequired={readPeerReviewsRequired(
                            assessment.reviewConfigurationCanonicalJson,
                          )}
                          disabled={
                            isLifecyclePending ||
                            !authoringState.candidateMatchesDraft
                          }
                        />
                      )}
                      <Button
                        type="button"
                        size="sm"
                        onClick={handlePublishRevision}
                        disabled={
                          isLifecyclePending ||
                          !authoringState.publish.available ||
                          !authoringState.candidateMatchesDraft
                        }
                      >
                        <Upload className="mr-2 size-4" />
                        Publish
                      </Button>
                      {authoringState.published && (
                        <Button
                          type="button"
                          size="sm"
                          variant="outline"
                          onClick={handleUnpublishRevision}
                          disabled={isLifecyclePending}
                        >
                          <RotateCcw className="mr-2 size-4" />
                          Unpublish
                        </Button>
                      )}
                    </div>

                    {!authoringState.prepare.available &&
                      authoringState.prepare.message && (
                        <p
                          className="text-muted-foreground text-xs"
                          role="status"
                        >
                          Test capability: {authoringState.prepare.message}
                        </p>
                      )}
                    {authoringState.candidateMatchesDraft &&
                      !authoringState.publish.available &&
                      authoringState.publish.message && (
                        <p
                          className="text-muted-foreground text-xs"
                          role="status"
                        >
                          Official capability: {authoringState.publish.message}
                        </p>
                      )}
                  </div>
                  <Separator />
                </>
              )}

              <div className="space-y-3">
                <div className="space-y-2">
                  <Label htmlFor="primary-review-method">Primary review</Label>
                  <Select
                    items={[
                      ...ASSESSMENT_PRIMARY_REVIEW_METHODS.map((method) => ({
                        value: method,
                        label: REVIEW_METHOD_LABELS[method],
                      })),
                    ]}
                    value={primaryReviewMethod}
                    onValueChange={(value) => {
                      const method = value as AssessmentReviewMethod;
                      setPrimaryReviewMethod(method);
                      if (method === "InstructorReview") {
                        setRequiresInstructorReview(false);
                      }
                    }}
                  >
                    <SelectTrigger id="primary-review-method">
                      <SelectValue>
                        {(value) =>
                          REVIEW_METHOD_LABELS[value as AssessmentReviewMethod] ??
                          "Select review method"
                        }
                      </SelectValue>
                    </SelectTrigger>
                    <SelectContent>
                      <SelectGroup>
                        {ASSESSMENT_PRIMARY_REVIEW_METHODS.map((method) => (
                          <SelectItem
                            key={method}
                            value={method}
                            disabled={!isPrimaryReviewMethodAvailable(method)}
                          >
                            {REVIEW_METHOD_LABELS[method]}
                            {method === "AIReview" && " (provider required)"}
                          </SelectItem>
                        ))}
                      </SelectGroup>
                    </SelectContent>
                  </Select>
                </div>

                {primaryReviewMethod !== "InstructorReview" && (
                  <div className="flex items-start justify-between gap-3 rounded-md border p-3">
                    <div>
                      <Label htmlFor="instructor-final-review">
                        Final instructor review
                      </Label>
                      <p className="text-muted-foreground mt-1 text-xs">
                        The primary reviewer proposes the result; an instructor
                        performs the final review.
                      </p>
                    </div>
                    <Switch
                      id="instructor-final-review"
                      checked={requiresInstructorReview}
                      onCheckedChange={(checked) =>
                        setRequiresInstructorReview(checked === true)
                      }
                    />
                  </div>
                )}

                <p className="text-muted-foreground text-xs">
                  Sequence: {REVIEW_METHOD_LABELS[primaryReviewMethod]}
                  {requiresInstructorReview &&
                  primaryReviewMethod !== "InstructorReview"
                    ? ` -> ${REVIEW_METHOD_LABELS.InstructorReview}`
                    : ""}
                </p>
              </div>

              <Separator />

              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <Label htmlFor="group-assignment">Group assignment</Label>
                  <Switch
                    id="group-assignment"
                    checked={groupAssignmentOn}
                    onCheckedChange={handleGroupAssignmentToggle}
                    disabled={isPolicyPending}
                  />
                </div>
                {groupAssignmentOn && (
                  <div className="space-y-2">
                    <Label htmlFor="group-set">Group set</Label>
                    <Select
                      items={[
                        { value: GROUP_SET_NONE, label: "No group set" },
                        ...groupSets.map((set) => ({ value: set.id, label: set.name })),
                      ]}
                      value={groupSetId}
                      onValueChange={(value) => handleGroupSetChange(value ?? GROUP_SET_NONE)}
                      disabled={isPolicyPending}
                    >
                      <SelectTrigger id="group-set">
                        <SelectValue>
                          {groupSets.find((set) => set.id === groupSetId)?.name ?? "No group set"}
                        </SelectValue>
                      </SelectTrigger>
                      <SelectContent>
                        <SelectGroup>
                          <SelectItem value={GROUP_SET_NONE}>No group set</SelectItem>
                          {groupSets.map((set) => (
                            <SelectItem key={set.id} value={set.id}>
                              {set.name}
                            </SelectItem>
                          ))}
                        </SelectGroup>
                      </SelectContent>
                    </Select>
                    <p className="text-muted-foreground text-xs">
                      Students submit once per group; the grade applies to every
                      member.
                    </p>
                  </div>
                )}
              </div>

              <Separator />

              {primaryReviewMethod === "PeerReview" && (
                <>
                  <div className="space-y-2">
                    <Label htmlFor="required-reviews">
                      Required peer reviews
                    </Label>
                    <Input
                      id="required-reviews"
                      type="number"
                      min={1}
                      value={peerReviewsRequired}
                      onChange={(e) => setPeerReviewsRequired(e.target.value)}
                    />
                    <p className="text-muted-foreground text-xs">
                      Each student reviews this many submissions from other
                      students.
                    </p>
                  </div>
                  <Separator />
                </>
              )}

              <div className="space-y-2">
                <Label htmlFor="result-release-mode">Result release</Label>
                <Select
                  items={[
                    { value: "immediate", label: "Immediate" },
                    { value: "manual", label: "Manual" },
                  ]}
                  value={resultReleaseMode}
                  onValueChange={(value) => setResultReleaseMode(value ?? "manual")}
                >
                  <SelectTrigger id="result-release-mode">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectGroup>
                      <SelectItem value="immediate">Immediate</SelectItem>
                      <SelectItem value="manual">Manual</SelectItem>
                    </SelectGroup>
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label htmlFor="content-completion-mode">
                  Content completion
                </Label>
                <Select
                  items={[
                    { value: "on-submit", label: "On submission" },
                    { value: "on-finalize", label: "On final result" },
                    { value: "on-release", label: "On result release" },
                    { value: "on-release-and-pass", label: "On released passing result" },
                  ]}
                  value={contentCompletionMode}
                  onValueChange={(value) => setContentCompletionMode(value ?? "on-submit")}
                >
                  <SelectTrigger id="content-completion-mode">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectGroup>
                      <SelectItem value="on-submit">On submission</SelectItem>
                      <SelectItem value="on-finalize">On final result</SelectItem>
                      <SelectItem value="on-release">On result release</SelectItem>
                      <SelectItem value="on-release-and-pass">
                        On released passing result
                      </SelectItem>
                    </SelectGroup>
                  </SelectContent>
                </Select>
              </div>

              <Separator />

              {isQuiz && (
                <>
                  <div className="space-y-2">
                    <Label htmlFor="presentation-mode">Presentation</Label>
                    <Select
                      items={[
                        { value: "Continuous", label: "Continuous list" },
                        { value: "SingleStep", label: "One at a time" },
                      ]}
                      value={presentationMode}
                      onValueChange={(value) =>
                        setPresentationMode(value as AssessmentPresentationMode)
                      }
                    >
                      <SelectTrigger id="presentation-mode">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectGroup>
                          <SelectItem value="Continuous">Continuous list</SelectItem>
                          <SelectItem value="SingleStep">One at a time</SelectItem>
                        </SelectGroup>
                      </SelectContent>
                    </Select>
                  </div>

                  <Separator />
                </>
              )}

              <div className="space-y-2">
                <Label htmlFor="time-limit">
                  <Clock className="mr-1 inline h-3 w-3" />
                  Time Limit (minutes)
                </Label>
                <Input
                  id="time-limit"
                  type="number"
                  min={0}
                  value={timeLimitMinutes}
                  onChange={(e) => setTimeLimitMinutes(e.target.value)}
                  placeholder="No limit"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="max-attempts">Max Attempts</Label>
                <Input
                  id="max-attempts"
                  type="number"
                  min={1}
                  value={maxAttempts}
                  onChange={(e) => setMaxAttempts(e.target.value)}
                  placeholder="1"
                  disabled
                />
              </div>

              <div className="flex items-center justify-between">
                <Label htmlFor="required">Required</Label>
                <Switch
                  id="required"
                  checked={isRequired}
                  onCheckedChange={setIsRequired}
                />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>Coding Assignment</CardTitle>
            </CardHeader>
            <CardContent>
              <Button
                className="w-full"
                onClick={() =>
                  router.push(
                    `${learningBase}/courses/${encodeURIComponent(courseId)}/assessments/${assessment.slug}/coding-definition`,
                  )
                }
              >
                <Code className="mr-2 h-4 w-4" />
                Edit Coding Definition
              </Button>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>Actions</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              {error && <p className="text-destructive text-sm">{error}</p>}
              {saved && (
                <p className="text-sm text-green-600">Saved successfully.</p>
              )}

              <Button
                className="w-full"
                onClick={handleSave}
                disabled={isPending}
              >
                {isPending ? (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                ) : (
                  <Save className="mr-2 h-4 w-4" />
                )}
                Save Changes
              </Button>
              <Button variant="outline" className="w-full" onClick={handleBack}>
                Cancel
              </Button>

              <Separator />

              <Button
                variant="destructive"
                className="w-full"
                onClick={handleDelete}
                disabled={isDeleting || isLinkedQuiz}
              >
                {isDeleting ? (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                ) : (
                  <Trash2 className="mr-2 h-4 w-4" />
                )}
                Delete Assessment
              </Button>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>Info</CardTitle>
            </CardHeader>
            <CardContent className="text-muted-foreground space-y-1 text-sm">
              <p>Type: {typeLabel}</p>
              <p>Order: {assessment.order}</p>
              <p>
                Available:{" "}
                <Badge
                  variant={assessment.isAvailable ? "default" : "secondary"}
                  className="text-xs"
                >
                  {assessment.isAvailable ? "Yes" : "No"}
                </Badge>
              </p>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

