  embedded?: boolean;
  onSaved?: (content: CodingAssignmentContent) => void;
}

interface TestRow {
  test: Test;
  visibility: FileVisibility;
}

export function CodingDefinitionEditor({
  courseId,
  assessmentSlug,
  programId,
  contentId,
  assessmentTitle,
  initialContent,
  embedded = false,
  onSaved,
}: EditorProps): ReactElement {
  const learningBase = useLearningBase();
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const ideControllerRef = useRef<AssessmentIdeController | null>(null);

  // ── Editor state ──
  const initialLang =
    (initialContent?.Environment.Language as CodingLanguage) ?? "cpp";
  const [language, setLanguage] = useState<CodingLanguage>(initialLang);
  const [allowStudentCreateFiles, setAllowStudentCreateFiles] =
    useState<boolean>(
      initialContent?.Environment.AllowStudentCreateFiles ?? false,
    );
  const [fileRows, setFileRows] = useState<AssignmentFileRow[]>(() =>
    initialContent
      ? Object.entries(initialContent.Data.Files).map(([path, meta]) => ({
          path,
          content: meta.Content,
          encoding: meta.Encoding ?? "text",
          visibility: meta.Visibility,
          modifiable: meta.Modifiable,
        }))
      : [],
  );
  const [testRows, setTestRows] = useState<TestRow[]>(() =>
    initialContent
      ? [
          ...initialContent.Tests.Public.map((test) => ({
            test,
            visibility: "Public" as FileVisibility,
          })),
          ...initialContent.Tests.Private.map((test) => ({
            test,
            visibility: "Private" as FileVisibility,
          })),
        ]
      : [],
  );
  const maxScore = initialContent?.Grading.MaxScore ?? 100;

  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const ideMounted = useSyncExternalStore(
    () => () => undefined,
    () => true,
    () => false,
  );

  // ── Autosave bookkeeping ──
  const autosaveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const dirtyRef = useRef(false);
  const savingRef = useRef(false);
  const hydratedRef = useRef(false);
  const seededRef = useRef(false);
  const performSaveRef = useRef<() => Promise<void>>(null!);

  // ── WorkspaceConfig for the IDE — derive from language preset + files ──
  const workspaceConfig = useMemo(() => {
    const sample = ASSIGNMENT_SAMPLES[language as CodingLanguage];
    if (!sample) return null;
    const files: WorkspaceConfig["files"] = {};
    for (const row of fileRows) {
      files[row.path] = { encoding: row.encoding, content: row.content };
    }
    // ponytail: if no files yet, fall back to the preset so the IDE has something to boot with.
    return createAssessmentWorkspaceConfig(
      language,
      Object.keys(files).length > 0 ? files : sample.workspaceConfig.files,
    );
  }, [language, fileRows]);

  // ── Auto-seed default sample on first mount when no initialContent ──
  // The Language preset Card used to host this seed via handleLanguageChange;
  // the page no longer has that surface (preset picker moved into the IDE
  // header). Seed once on mount so fileRows + testRows aren't empty.
  useEffect(() => {
    if (initialContent) return;
    seededRef.current = true;
    handleLanguageChange(initialLang);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ── Validation ──
  const validationErrors = useMemo(
    () => validateAll({ testRows, fileRows }),
    [testRows, fileRows],
  );
  const isValid = validationErrors.length === 0;

  // ── Handlers ──
  function handleLanguageChange(next: CodingLanguage) {
    setLanguage(next);
    const sample = ASSIGNMENT_SAMPLES[next as CodingLanguage];
    if (!sample) return;
    const rows: AssignmentFileRow[] = Object.entries(
      sample.workspaceConfig.files,
    ).map(([path, bundle]) => ({
      path,
      content: bundle.content,
      encoding: bundle.encoding,
      visibility: "Public" as FileVisibility,
      modifiable: true,
    }));
    setFileRows(rows);
    const controller = ideControllerRef.current;
    if (controller) {
      void controller
        .replaceFiles(
          rows.map(({ path, content }) => ({
            path,
            content,
            type: "text" as const,
          })),
        )
        .catch((replaceError) => {
          setError(
            replaceError instanceof Error
              ? `Could not switch editor workspace: ${replaceError.message}`
              : "Could not switch editor workspace.",
          );
        });
    }
    // ponytail: do NOT seed testRows here — authoring flows expect add-*
    // clicks to produce row index 0. Seeding files only keeps the IDE useful
    // on first mount without breaking test-row assumptions.
  }

  function handleAddStandard() {
    setTestRows((prev) => [
      ...prev,
      {
        test: {
          kind: "standard",
          Name: "",
          Stdin: "",
          Stdout: "",
          Weight: 1,
        },
        visibility: "Public",
      },
    ]);
  }

  function handleAddFunctional() {
    setTestRows((prev) => [
      ...prev,
      {
        test: {
          kind: "functional",
          Name: "",
          Weight: 1,
          Function: {
            FunctionName: "",
            Parameters: [],
            ReturnType: { Type: "integer" },
          },
          Cases: [],
        },
        visibility: "Public",
      },
    ]);
  }

  function handleTestChange(idx: number, patch: Partial<Test>) {
    setTestRows((prev) =>
      prev.map((row, i) =>
        i === idx ? { ...row, test: { ...row.test, ...patch } as Test } : row,
      ),
    );
  }

  function handleTestVisibilityChange(idx: number, next: FileVisibility) {
    setTestRows((prev) =>
      prev.map((row, i) => (i === idx ? { ...row, visibility: next } : row)),
    );
  }

  function handleRemoveTest(idx: number) {
    setTestRows((prev) => prev.filter((_, i) => i !== idx));
  }

  async function synchronizeFilePolicies(controller: AssessmentIdeController) {
    try {
      const liveFiles = await controller.getFiles();
      setFileRows((previous) => reconcileAssignmentFiles(previous, liveFiles));
      setError(null);
    } catch (readError) {
      setError(
        readError instanceof Error
          ? `Could not read editor files: ${readError.message}`
          : "Could not read editor files.",
      );
    }
  }

  async function performSave() {
    if (savingRef.current) return;
    if (!contentId) {
      setError("No content item linked to this assessment.");
      return;
    }
    savingRef.current = true;
    setError(null);
    setSaved(false);

    // Pull source edits from the neutral controller. Assessment policy stays in
    // this component, so the IDE never owns visibility, tests, or language.
    let liveFileRows = fileRows;
    if (ideControllerRef.current) {
      try {
        const liveFiles = await ideControllerRef.current.getFiles();
        liveFileRows = reconcileAssignmentFiles(fileRows, liveFiles);
      } catch (readError) {
        setError(
          readError instanceof Error
            ? `Could not read editor files: ${readError.message}`
            : "Could not read editor files.",
        );
        savingRef.current = false;
        return;
      }
    }

    const content = buildContent({
      language,
      allowStudentCreateFiles,
      fileRows: liveFileRows,
      testRows,
      maxScore,
    });

    // 10MB budget — matches the backend's files_too_large FluentValidation rule.
    if (JSON.stringify(content).length > 10_000_000) {
      setError(
        "Assignment exceeds 10MB total (texts+images+tests). Remove some files.",
      );
      savingRef.current = false;
      return;
    }

    startTransition(async () => {
      try {
        const result = await putCodingAssignmentAction(
          programId,
          contentId,
          content,
        );
        if (!result.success) {
          setError(result.error);
          return;
        }
        setSaved(true);
        onSaved?.(content);
        dirtyRef.current = false;
        if (autosaveTimerRef.current) {
          clearTimeout(autosaveTimerRef.current);
          autosaveTimerRef.current = null;
        }
      } finally {
        savingRef.current = false;
      }
    });
  }

  useEffect(() => {
    performSaveRef.current = performSave;
  });

  // Debounced autosave: 30s after the LAST authored change. The cleanup clears
  // the pending timer on the next change (reset) and on unmount (teardown).
  // ponytail: a change landing while a save is in flight gets its timer
  // canceled by the success path — tiny window, next change re-arms.
  useEffect(() => {
    if (!hydratedRef.current) {
      hydratedRef.current = true;
      return;
    }
    if (seededRef.current) {
      seededRef.current = false;
      return;
    }
    dirtyRef.current = true;
    autosaveTimerRef.current = setTimeout(() => {
      autosaveTimerRef.current = null;
      if (!isValid || !contentId) return;
      void performSaveRef.current();
    }, AUTOSAVE_DELAY_MS);
    return () => {
      if (autosaveTimerRef.current) {
        clearTimeout(autosaveTimerRef.current);
        autosaveTimerRef.current = null;
      }
    };
  }, [
    testRows,
    fileRows,
    language,
    allowStudentCreateFiles,
    isValid,
    contentId,
  ]);

  function handleBack() {
    router.push(
      `${learningBase}/courses/${encodeURIComponent(courseId)}/assessments/${assessmentSlug}`,
    );
  }

  const stdioErrorCount = validationErrors.length;

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        {!embedded ? (
          <Button variant="ghost" size="sm" onClick={handleBack}>
            <ArrowLeft className="mr-2 h-4 w-4" />
            Back
          </Button>
        ) : null}
        <div className="flex-1">
          <p className="text-muted-foreground text-sm">Coding assignment</p>
          {!embedded ? (
            <h1 className="text-2xl font-bold">{assessmentTitle}</h1>
          ) : null}
        </div>
        {saved && <p className="text-sm text-green-600">Saved.</p>}
        {error && <p className="text-destructive text-sm">{error}</p>}
        <Badge variant="secondary">{language}</Badge>
        <Button
          onClick={performSave}
          disabled={!isValid || isPending}
          data-testid="save-button"
        >
          {isPending ? (
            <Loader2 className="mr-2 h-4 w-4 animate-spin" />
          ) : (
            <Save className="mr-2 h-4 w-4" />
          )}
          Save Definition
        </Button>
      </div>

      {stdioErrorCount > 0 && (
        <div className="text-destructive text-sm space-y-1">
          {validationErrors.slice(0, 5).map((e, i) => (
            <p key={i}>{e.message}</p>
          ))}
        </div>
      )}

      {workspaceConfig && (
        <Card
          className={embedded ? "rounded-none border-0 shadow-none" : undefined}
        >
          {!embedded ? (
            <CardHeader>
              <CardTitle>Workspace</CardTitle>
            </CardHeader>
          ) : null}
          <CardContent className="space-y-4">
            <div
              data-testid="ide-mount"
              className={
                embedded
                  ? "h-[calc(100dvh-13rem)] min-h-[500px]"
                  : "h-[70vh] min-h-[500px]"
              }
            >
              {ideMounted ? (
                <CodingAssessmentEditor
                  mode="author"
                  manifestUrl={EMCEPTION_MANIFEST_URL}
                  definition={buildContent({
                    language,
                    allowStudentCreateFiles,
                    fileRows,
                    testRows,
                    maxScore,
                  })}
                  workspaceConfig={workspaceConfig}
                  maxScore={maxScore}
                  onReady={(controller) => {
                    ideControllerRef.current = controller;
                  }}
                  extensions={
                    [
                      {
                        id: "gameguild-assessment-authoring",
                        toolbarEnd: () => (
                          <div className="flex items-center gap-2">
                            <select
                              aria-label="Workspace preset"
                              data-testid="preset-picker"
                              value={language}
                              onChange={(event) =>
                                handleLanguageChange(
                                  event.target.value as CodingLanguage,
                                )
                              }
                            >
                              {LANGUAGE_OPTIONS.map((option) => (
                                <option key={option.value} value={option.value}>
                                  {option.label}
                                </option>
                              ))}
                            </select>
                            <button
                              type="button"
                              data-testid="allow-student-create"
                              onClick={() =>
                                setAllowStudentCreateFiles((value) => !value)
                              }
                            >
                              {allowStudentCreateFiles ? "🔓" : "🔒"}
                            </button>
                          </div>
                        ),
                        explorerFooter: () => (
                          <section
                            aria-label="Assignment file policies"
                            className="space-y-2 border-t border-border p-2 text-xs"
                          >
                            <div className="flex items-center justify-between gap-2">
                              <strong>File policies</strong>
                              <button
                                type="button"
                                data-testid="sync-file-policies"
                                onClick={() => {
                                  const controller = ideControllerRef.current;
                                  if (!controller) {
                                    setError(
                                      "Editor is still loading. Try again shortly.",
                                    );
                                    return;
                                  }
                                  void synchronizeFilePolicies(controller);
                                }}
                              >
                                Sync files
                              </button>
                            </div>
                            {fileRows.map((row) => (
                              <div key={row.path} className="space-y-1">
                                <p
                                  className="truncate font-mono"
                                  title={row.path}
                                >
                                  {row.path}
                                </p>
                                <div className="flex items-center gap-2">
                                  <select
                                    aria-label={`Visibility for ${row.path}`}
                                    value={row.visibility}
                                    onChange={(event) =>
                                      setFileRows((previous) =>
                                        previous.map((file) =>
                                          file.path === row.path
                                            ? {
                                                ...file,
                                                visibility: event.target
                                                  .value as FileVisibility,
                                              }
                                            : file,
                                        ),
                                      )
                                    }
                                  >
                                    <option value="Public">Public</option>
                                    <option value="Private">Private</option>
                                  </select>
                                  <label className="flex items-center gap-1">
                                    <input
                                      aria-label={`Student can edit ${row.path}`}
                                      type="checkbox"
                                      checked={row.modifiable}
                                      onChange={(event) =>
                                        setFileRows((previous) =>
                                          previous.map((file) =>
                                            file.path === row.path
                                              ? {
                                                  ...file,
                                                  modifiable:
                                                    event.target.checked,
                                                }
                                              : file,
                                          ),
                                        )
                                      }
                                    />
                                    Editable
                                  </label>
                                </div>
                              </div>
                            ))}
                          </section>
                        ),
                        bottomPanel: () => (
                          <div className="space-y-4">
                            {testRows.length === 0 && (
                              <p
                                className="text-muted-foreground text-sm"
                                data-testid="empty-tests"
                              >
                                No tests yet. Add a Standard or Functional test
                                below.
                              </p>
                            )}
                            {testRows.map((row, i) =>
                              row.test.kind === "standard" ? (
                                <StandardTestEditor
                                  key={i}
                                  index={i}
                                  test={row.test as StandardTest}
                                  visibility={row.visibility}
                                  errors={validationErrors.filter((e) =>
                                    e.field.startsWith(`tests[${i}]`),
                                  )}
                                  onChange={handleTestChange}
                                  onVisibilityChange={
                                    handleTestVisibilityChange
                                  }
                                  onRemove={handleRemoveTest}
                                />
                              ) : (
                                <FunctionalTestEditor
                                  key={i}
                                  index={i}
                                  test={row.test as FunctionalTestGroup}
                                  visibility={row.visibility}
                                  errors={validationErrors.filter((e) =>
                                    e.field.startsWith(`tests[${i}]`),
                                  )}
                                  onChange={handleTestChange}
                                  onVisibilityChange={
                                    handleTestVisibilityChange
                                  }
                                  onRemove={handleRemoveTest}
                                />
                              ),
                            )}
                            <div className="flex flex-wrap gap-2">
                              <Button
                                variant="outline"
                                size="sm"
                                onClick={handleAddStandard}
                                data-testid="add-standard"
                              >
                                <Plus className="mr-1 h-3 w-3" /> Standard test
                              </Button>
                              <Button
                                variant="outline"
                                size="sm"
                                onClick={handleAddFunctional}
                                data-testid="add-functional"
                              >
                                <Plus className="mr-1 h-3 w-3" /> Functional
                                test
                              </Button>
                            </div>
                          </div>
                        ),
                      },
                    ] satisfies readonly AssessmentIdeExtension[]
                  }
                />
              ) : (
                <div
                  className="flex h-full min-h-[500px] items-center justify-center gap-2 text-sm text-muted-foreground"
                  data-testid="ide-loading"
                  role="status"
                >
                  <Loader2 className="h-4 w-4 animate-spin" />
                  Loading coding editor…
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

// ── Validation helpers ────────────────────────────────────────────────────

interface ValidationState {
  testRows: TestRow[];
  fileRows: AssignmentFileRow[];
}

interface ValidationErr {
  field: string;
  code: string;
  message: string;
}

/**
 * Mirror of Task 1 FluentValidation rules — runs on the client before PUT so
 * the backend never sees a malformed payload. Error codes match the backend's
 * `WithErrorCode` strings exactly.
 */
function validateAll(state: ValidationState): ValidationErr[] {
  const errors: ValidationErr[] = [];

  // Per-file: Private + Modifiable makes no sense.
  state.fileRows.forEach((f, i) => {
    if (f.visibility === "Private" && f.modifiable) {
      errors.push({
        field: `Data.Files[${i}]`,
        code: "private_file_not_modifiable",
        message: `File "${f.path}" cannot be both Private and Modifiable.`,
      });
    }
  });

  // Per-test rules
  state.testRows.forEach((row, i) => {
    const path = `tests[${i}]`;
    const t = row.test;
    if (t.Weight != null && t.Weight < 0) {
      errors.push({
        field: `${path}.Weight`,
        code: "weight_non_negative",
        message: "Weight must be ≥ 0.",
      });
    }
    if (t.kind === "standard") {
      const std = t as StandardTest;
      if (!std.Stdout || std.Stdout.length === 0) {
        errors.push({
          field: `${path}.Stdout`,
          code: "standard_stdout_required",
          message: "Standard test requires non-empty Stdout.",
        });
      }
    } else {
      const fn = t as FunctionalTestGroup;
      if (!FUNCTION_NAME_RE.test(fn.Function.FunctionName)) {
        errors.push({
          field: `${path}.Function.FunctionName`,
          code: "invalid_function_name",
          message:
            "Function name must match ^[A-Za-z_][A-Za-z0-9_]*$ (C/C++ global scope).",
        });
      }
      for (const p of fn.Function.Parameters) {
        // The select restricts to v1 4 types — this catches a hand-built payload.
        if (!isV1ParamType(p.Type)) {
          errors.push({
            field: `${path}.Function.Parameters`,
            code: "functional_param_type_not_supported_v1",
            message: `Parameter type "${p.Type}" is not supported in v1.`,
          });
        }
      }
      if (!isV1ParamType(fn.Function.ReturnType.Type)) {
        errors.push({
          field: `${path}.Function.ReturnType`,
          code: "functional_param_type_not_supported_v1",
          message: `Return type "${fn.Function.ReturnType.Type}" is not supported in v1.`,
        });
      }
      if (fn.Cases.length === 0) {
        errors.push({
          field: `${path}.Cases`,
          code: "at_least_one_case",
          message: "Functional test requires at least one case.",
        });
      }
    }
  });

  return errors;
}

function isV1ParamType(t: string): t is FunctionParameterType {
  return t === "string" || t === "boolean" || t === "integer" || t === "float";
}

// ── Payload assembly ──────────────────────────────────────────────────────

interface BuildArgs {
  language: CodingLanguage;
  allowStudentCreateFiles: boolean;
  fileRows: AssignmentFileRow[];
  testRows: TestRow[];
  maxScore: number;
}

function buildContent(args: BuildArgs): CodingAssignmentContent {
  const files: Record<
    string,
    {
      Content: string;
      Encoding: FileEncoding;
      Visibility: FileVisibility;
      Modifiable: boolean;
    }
  > = {};
  for (const row of args.fileRows) {
    files[row.path] = {
      Content: row.content,
      Encoding: row.encoding,
      Visibility: row.visibility,
      Modifiable: row.modifiable,
    };
  }

  const pub: Test[] = [];
  const priv: Test[] = [];
  for (const row of args.testRows) {
    (row.visibility === "Public" ? pub : priv).push(row.test);
  }

  const environment: CodingEnvironment = {
    Language: args.language,
    Tools: DEFAULT_TOOLS[args.language],
    LibBundle: args.language === "allegro-cpp" ? "allegro" : null,
    AllowStudentCreateFiles: args.allowStudentCreateFiles,
  };

  return {
    Type: "coding-assignment",
    Version: 1,
    Environment: environment,
    Data: { Files: files },
    Tests: { Public: pub, Private: priv },
    Grading: { MaxScore: args.maxScore },
  };
}

"use client";

import React, { type ReactElement } from "react";
import { Plus, Trash2 } from "lucide-react";
import { Badge } from "@game-guild/ui/components/badge";
import { Button } from "@game-guild/ui/components/button";
import { Input } from "@game-guild/ui/components/input";
import { Label } from "@game-guild/ui/components/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@game-guild/ui/components/select";
import type {
  FileVisibility,
  FunctionParameter,
  FunctionParameterWithName,
  FunctionParameterType,
  FunctionParameterValue,
  FunctionalTestCase,
  FunctionalTestGroup,
} from "@/lib/coding-assignment/types";
import { VisibilitySelect } from "./visibility-select";

/** v1 supports exactly these 4 primitive types — Array/Dictionary rejected. */
const PARAM_TYPES: { value: FunctionParameterType; label: string }[] = [
  { value: "string", label: "String" },
  { value: "boolean", label: "Boolean" },
  { value: "integer", label: "Integer" },
  { value: "float", label: "Float" },
];

export interface FunctionalTestEditorProps {
  index: number;
  test: FunctionalTestGroup;
  visibility: FileVisibility;
  errors: Array<{ field: string; code: string; message: string }>;
  onChange: (idx: number, patch: Partial<FunctionalTestGroup>) => void;
  onVisibilityChange: (idx: number, next: FileVisibility) => void;
  onRemove: (idx: number) => void;
}

/**
 * Form for a v1 `FunctionalTestGroup` — signature authored ONCE on top,
 * multiple `FunctionalTestCase` rows below. Each case carries its own
 * Inputs (one per signature parameter) + Expected value.
 *
 * Parameter type select is RESTRICTED to the v1 4 primitive types
 * (server-side validator rejects Array/Dictionary with
 * `functional_param_type_not_supported_v1`).
 */
export function FunctionalTestEditor({
  index,
  test,
  visibility,
  errors,
  onChange,
  onVisibilityChange,
  onRemove,
}: FunctionalTestEditorProps): ReactElement {
  const errFor = (suffix: string) => errors.find((e) => e.field.endsWith(suffix));
  const fn = test.Function;

  // ---------- signature patchers ----------
  function patchFunction(patch: Partial<typeof fn>) {
    onChange(index, { Function: { ...fn, ...patch } });
  }

  function patchParameter(pIndex: number, patch: Partial<FunctionParameterWithName>) {
    const next = fn.Parameters.map((p, i) => (i === pIndex ? { ...p, ...patch } : p));
    patchFunction({ Parameters: next });
  }

  function addParameter() {
    const next: FunctionParameterWithName = {
      Name: "",
      Type: "string",
    };
    patchFunction({ Parameters: [...fn.Parameters, next] });
  }

  function removeParameter(pIndex: number) {
    patchFunction({
      Parameters: fn.Parameters.filter((_, i) => i !== pIndex),
    });
  }

  function patchReturnType(nextType: FunctionParameterType) {
    patchFunction({
      ReturnType: { Type: nextType },
    });
  }

  // ---------- cases patchers ----------
  function patchCases(next: readonly FunctionalTestCase[]) {
    onChange(index, { Cases: next });
  }

  function patchCase(cIndex: number, patch: Partial<FunctionalTestCase>) {
    const next = test.Cases.map((c, i) => (i === cIndex ? { ...c, ...patch } : c));
    patchCases(next);
  }

  function patchCaseInput(cIndex: number, pIndex: number, raw: string) {
    const param = fn.Parameters[pIndex]!;
    const case_ = test.Cases[cIndex]!;
    const inputs = fn.Parameters.map((signatureParameter, i) => {
      const input = case_.Inputs[i] ?? {
        Type: signatureParameter.Type,
        Content: defaultFunctionalContentForType(signatureParameter.Type, ""),
      };
      return i === pIndex
        ? { Type: param.Type, Content: parseFunctionalContent(param.Type, raw) }
        : input;
    });
    patchCase(cIndex, { Inputs: inputs });
  }

  function patchCaseExpected(cIndex: number, raw: string) {
    const expected: FunctionParameter = {
      Type: fn.ReturnType.Type,
      Content: parseFunctionalContent(fn.ReturnType.Type, raw),
    };
    patchCase(cIndex, { Expected: expected });
  }

  function addCase() {
    const inputs: FunctionParameter[] = fn.Parameters.map((p) => ({
      Type: p.Type,
      Content: defaultFunctionalContentForType(p.Type, ""),
    }));
    const expected: FunctionParameter = {
      Type: fn.ReturnType.Type,
      Content: defaultFunctionalContentForType(fn.ReturnType.Type, ""),
    };
    patchCases([...test.Cases, { Inputs: inputs, Expected: expected }]);
  }

  function removeCase(cIndex: number) {
    patchCases(test.Cases.filter((_, i) => i !== cIndex));
  }

  return (
    <div
      className="border rounded-md p-4 space-y-3"
      data-testid={`functional-test-${index}`}
    >
      {/* header: badge + name + visibility + remove-group */}
      <div className="flex items-center gap-2">
        <Badge variant="outline">functional</Badge>
        <Input
          placeholder="Test name (optional)"
          value={test.Name ?? ""}
          onChange={(e) => onChange(index, { Name: e.target.value })}
          className="flex-1"
          data-testid={`functional-name-${index}`}
        />
        <div className="w-32">
          <VisibilitySelect
            value={visibility}
            onChange={(v) => onVisibilityChange(index, v)}
            testId={`functional-visibility-${index}`}
          />
        </div>
        <Button
          variant="ghost"
          size="sm"
          onClick={() => onRemove(index)}
          data-testid={`functional-remove-${index}`}
        >
          <Trash2 className="h-3 w-3" />
        </Button>
      </div>

      {/* weight */}
      <div className="space-y-1 w-32">
        <Label className="text-xs">Weight</Label>
        <Input
          type="number"
          min={0}
          step="any"
          value={test.Weight ?? 1}
          onChange={(e) => onChange(index, { Weight: Number(e.target.value) })}
          data-testid={`functional-weight-${index}`}
        />
        {errFor(".Weight") && (
          <p className="text-destructive text-xs">{errFor(".Weight")!.message}</p>
        )}
      </div>

      {/* ---------------- SIGNATURE ---------------- */}
      <div
        className="border rounded-md p-3 space-y-2"
        data-testid={`functional-signature-${index}`}
      >
        <div className="flex items-center justify-between">
          <Label className="text-xs uppercase tracking-wide text-muted-foreground">
            Signature (authored once)
          </Label>
        </div>
        <div className="grid grid-cols-2 gap-3">
          <div className="space-y-1">
            <Label className="text-xs">Function name</Label>
            <Input
              value={fn.FunctionName}
              onChange={(e) => patchFunction({ FunctionName: e.target.value })}
              placeholder="add"
              data-testid={`functional-functionName-${index}`}
            />
            {errFor(".FunctionName") && (
              <p className="text-destructive text-xs">
                {errFor(".FunctionName")!.message}
              </p>
            )}
          </div>
          <div className="space-y-1">
            <Label className="text-xs">Return type</Label>
            <Select
              value={fn.ReturnType.Type}
              onValueChange={(v) => patchReturnType(v as FunctionParameterType)}
            >
              <SelectTrigger data-testid={`functional-returnType-${index}`}>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {PARAM_TYPES.map((t) => (
                  <SelectItem key={t.value} value={t.value}>
                    {t.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>

        {/* signature parameters: Name + Type only (values live in cases) */}
        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <Label className="text-xs">Parameters</Label>
            <Button
              variant="outline"
              size="sm"
              onClick={addParameter}
              data-testid={`functional-add-param-${index}`}
            >
              <Plus className="mr-1 h-3 w-3" /> Add parameter
            </Button>
          </div>
          {fn.Parameters.length === 0 && (
            <p
              className="text-muted-foreground text-xs"
              data-testid={`functional-no-params-${index}`}
            >
              No parameters. Click &quot;Add parameter&quot;.
            </p>
          )}
          {fn.Parameters.map((p, pIndex) => (
            <div
              key={pIndex}
              className="grid grid-cols-[1fr_8rem_auto] gap-2 items-end"
              data-testid={`functional-param-${index}-${pIndex}`}
            >
              <div className="space-y-1">
                <Label className="text-xs">Name</Label>
                <Input
                  value={p.Name}
                  onChange={(e) => patchParameter(pIndex, { Name: e.target.value })}
                  placeholder="a"
                  data-testid={`functional-param-name-${index}-${pIndex}`}
                />
              </div>
              <div className="space-y-1">
                <Label className="text-xs">Type</Label>
                <Select
                  value={p.Type}
                  onValueChange={(v) =>
                    patchParameter(pIndex, { Type: v as FunctionParameterType })
                  }
                >
                  <SelectTrigger data-testid={`functional-param-type-${index}-${pIndex}`}>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {PARAM_TYPES.map((t) => (
                      <SelectItem key={t.value} value={t.value}>
                        {t.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => removeParameter(pIndex)}
                data-testid={`functional-param-remove-${index}-${pIndex}`}
              >
                <Trash2 className="h-3 w-3" />
              </Button>
            </div>
          ))}
        </div>
      </div>

      {/* ---------------- CASES ---------------- */}
      <div
        className="border rounded-md p-3 space-y-2"
        data-testid={`functional-cases-${index}`}
      >
        <div className="flex items-center justify-between">
          <Label className="text-xs uppercase tracking-wide text-muted-foreground">
            Cases ({test.Cases.length})
          </Label>
          <Button
            variant="outline"
            size="sm"
            onClick={addCase}
            data-testid={`functional-add-case-${index}`}
          >
            <Plus className="mr-1 h-3 w-3" /> Add case
          </Button>
        </div>
        {test.Cases.length === 0 && (
          <p
            className="text-muted-foreground text-xs"
            data-testid={`functional-no-cases-${index}`}
          >
            No cases. Click &quot;Add case&quot;.
          </p>
        )}
        {test.Cases.map((c, cIndex) => (
          <div
            key={cIndex}
            className="grid grid-cols-[auto_1fr_auto] items-end gap-2 border-t pt-2"
            data-testid={`functional-case-${index}-${cIndex}`}
          >
            <div className="text-xs text-muted-foreground pt-2">#{cIndex + 1}</div>
            <div className="space-y-2">
              {/* inputs: one per signature parameter, type-driven by signature */}
              {fn.Parameters.length === 0 && (
                <p className="text-muted-foreground text-xs">
                  No parameters in signature.
                </p>
              )}
              <div className="grid grid-cols-2 gap-2">
                {fn.Parameters.map((p, pIndex) => {
                  const inp = c.Inputs[pIndex] ?? {
                    Type: p.Type,
                    Content: defaultFunctionalContentForType(p.Type, ""),
                  };
                  return (
                    <div
                      key={pIndex}
                      className="space-y-1"
                      data-testid={`functional-case-input-${index}-${cIndex}-${pIndex}`}
                    >
                      <Label className="text-xs">
                        {p.Name || `param ${pIndex + 1}`} ({p.Type})
                      </Label>
                      <Input
                        value={String(inp.Content)}
                        onChange={(e) => patchCaseInput(cIndex, pIndex, e.target.value)}
                        data-testid={`functional-case-input-value-${index}-${cIndex}-${pIndex}`}
                      />
                    </div>
                  );
                })}
              </div>
              {/* expected: typed by ReturnType */}
              <div
                className="space-y-1"
                data-testid={`functional-case-expected-${index}-${cIndex}`}
              >
                <Label className="text-xs">
                  Expected ({fn.ReturnType.Type})
                </Label>
                <Input
                  value={String(c.Expected.Content)}
                  onChange={(e) => patchCaseExpected(cIndex, e.target.value)}
                  data-testid={`functional-case-expected-value-${index}-${cIndex}`}
                />
              </div>
            </div>
            <Button
              variant="ghost"
              size="sm"
              onClick={() => removeCase(cIndex)}
              data-testid={`functional-case-remove-${index}-${cIndex}`}
            >
              <Trash2 className="h-3 w-3" />
            </Button>
          </div>
        ))}
      </div>
    </div>
  );
}

/** Coerce a string input into the wire value for the given parameter type. */
export function parseFunctionalContent(type: FunctionParameterType, raw: string): FunctionParameterValue {
  switch (type) {
    case "integer":
      return Number.isNaN(Number(raw)) ? 0 : Number(raw);
    case "float":
      return Number.isNaN(Number(raw)) ? 0 : Number(raw);
    case "boolean":
      return raw === "true" || raw === "1";
    case "string":
      return raw;
  }
}

/** Reset content to a sane default when the type changes. */
export function defaultFunctionalContentForType(
  type: FunctionParameterType,
  current: FunctionParameterValue,
): FunctionParameterValue {
  switch (type) {
    case "integer":
    case "float":
      return typeof current === "number" ? current : 0;
    case "boolean":
      return typeof current === "boolean" ? current : false;
    case "string":
      return typeof current === "string" ? current : "";
  }
}

/**
 * Helper for callers: parse a FunctionParameter from raw wire (e.g. for tests).
 * Exported so the editor's tests can construct fixtures without repeating the cast.
 */
export function makeFunctionParameter(
  type: FunctionParameterType,
  content: FunctionParameterValue,
): FunctionParameter {
  return { Type: type, Content: content };
}

'use client';

import { Loader2 } from 'lucide-react';
import { Link } from '@/i18n/navigation';
import { Badge } from '@game-guild/ui/components/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@game-guild/ui/components/table';
import type { LearningAssessmentsAssessmentSubmission } from '@game-guild/client';
import { useLearningBase } from '@/lib/learning/use-learning-base';
import { scoreUnitsToPoints } from '@/lib/learning/academic-values';

// ponytail: simple list render; add server-side pagination when submission count exceeds 200

const dateFormatter = new Intl.DateTimeFormat('en-US', {
  year: 'numeric',
  month: 'short',
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
});

export type SubmissionStatusVariant =
  | 'default'
  | 'secondary'
  | 'destructive'
  | 'outline';

export function statusBadgeVariant(
  status: LearningAssessmentsAssessmentSubmission['status'],
): SubmissionStatusVariant {
  switch (status) {
    case 'Submitted':
      return 'default';
    case 'Graded':
      return 'secondary';
    case 'Late':
      return 'destructive';
    case 'InProgress':
    case 'Returned':
    case undefined:
      return 'outline';
  }
}

export interface SubmissionsListProps {
  courseSlug: string;
  assessmentId: string;
  assessmentSlug: string;
  maxScore: number;
  submissions: LearningAssessmentsAssessmentSubmission[];
  error?: string;
  isLoading?: boolean;
}

export function SubmissionsList({
  courseSlug,
  assessmentId,
  assessmentSlug,
  maxScore,
  submissions,
  error,
  isLoading = false,
}: SubmissionsListProps): React.JSX.Element {
  const learningBase = useLearningBase();
  if (isLoading) {
    return (
      <div data-testid="submissions-loading" className="flex items-center gap-2 text-muted-foreground">
        <Loader2 className="h-4 w-4 animate-spin" />
        <span>Loading submissions…</span>
      </div>
    );
  }

  if (error) {
    return (
      <div data-testid="submissions-error" className="text-destructive">
        {error}
      </div>
    );
  }

  if (submissions.length === 0) {
    return (
      <div data-testid="submissions-empty" className="text-muted-foreground">
        No submissions yet for this assessment.
      </div>
    );
  }

  return (
    <Table data-testid="submissions-table">
      <TableHeader>
        <TableRow>
          <TableHead>Student</TableHead>
          <TableHead>Attempt</TableHead>
          <TableHead>Started</TableHead>
          <TableHead>Submitted</TableHead>
          <TableHead>Status</TableHead>
          <TableHead>Score</TableHead>
          <TableHead>Actions</TableHead>
        </TableRow>
      </TableHeader>
      <TableBody>
        {submissions.map((submission) => (
          <SubmissionRow
            key={submission.id ?? `${submission.userId}-${submission.attemptNumber}`}
            submission={submission}
            courseSlug={courseSlug}
            assessmentId={assessmentId}
            assessmentSlug={assessmentSlug}
            maxScore={maxScore}
          />
        ))}
      </TableBody>
    </Table>
  );
}

interface SubmissionRowProps {
  submission: LearningAssessmentsAssessmentSubmission;
  courseSlug: string;
  assessmentId: string;
  assessmentSlug: string;
  maxScore: number;
}

function SubmissionRow({
  submission,
  courseSlug,
  assessmentId,
  assessmentSlug,
  maxScore,
}: SubmissionRowProps): React.JSX.Element {
  const learningBase = useLearningBase();
  const studentLabel =
    submission.userId && submission.userId.length > 8
      ? `${submission.userId.slice(0, 8)}…`
      : (submission.userId ?? '—');

  const submittedAt = submission.submittedAt
    ? dateFormatter.format(new Date(submission.submittedAt))
    : '—';

  const startedAt = submission.startedAt
    ? dateFormatter.format(new Date(submission.startedAt))
    : '—';

  const scoreLabel =
    submission.score != null
      ? `${scoreUnitsToPoints(submission.score)}/${maxScore}`
      : '—';

  const gradeHref = `${learningBase}/courses/${courseSlug}/assessments/${assessmentSlug}/submissions/${submission.id}/grade`;

  return (
    <TableRow data-testid={`submission-row-${submission.id}`}>
      <TableCell>{studentLabel}</TableCell>
      <TableCell>{submission.attemptNumber ?? '—'}</TableCell>
      <TableCell>{startedAt}</TableCell>
      <TableCell>{submittedAt}</TableCell>
      <TableCell>
        <Badge variant={statusBadgeVariant(submission.status)} data-testid={`submission-status-${submission.id}`}>
          {submission.status ?? 'InProgress'}
        </Badge>
      </TableCell>
      <TableCell>{scoreLabel}</TableCell>
      <TableCell>
        <Link
          href={gradeHref}
          className="text-primary underline-offset-4 hover:underline"
          data-testid={`submission-grade-link-${submission.id}`}
        >
          Grade
        </Link>
      </TableCell>
    </TableRow>
  );
}

