'use client';

import type {
  LearningCohortsCohortSchedule,
  LearningCohortsCohortScheduleItem,
  LearningCohortsCohortScheduleItemStatus,
  LearningCohortsCohortVisibilityOverride,
  LearningCohortsScheduleShiftScope,
} from '@game-guild/client';
import { Alert, AlertDescription, AlertTitle } from '@game-guild/ui/components/alert';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@game-guild/ui/components/dialog';
import { Input } from '@game-guild/ui/components/input';
import { Label } from '@game-guild/ui/components/label';
import { RadioGroup, RadioGroupItem } from '@game-guild/ui/components/radio-group';
import {
  SelectGroup,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@game-guild/ui/components/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@game-guild/ui/components/tabs';
import { AlertTriangle, CalendarDays, Clock3, ListTree, Loader2, MoveRight, Pencil, ShieldCheck } from 'lucide-react';
import { useCallback, useEffect, useState } from 'react';

import { shiftCohortScheduleItem, updateCohortScheduleItem } from '@/lib/learning/actions/cohorts';
import type { CourseCohortSummary } from '@/lib/learning/queries/cohorts';
import { CalendarView } from './calendar-view';
import { ScheduleBuilderSheet } from './schedule-builder-sheet';
import { SyllabusView } from './syllabus-view';
import { TimelineView } from './timeline-view';

type ScheduleView = 'syllabus' | 'calendar' | 'timeline';

interface CohortScheduleWorkspaceProps {
  courseId: string;
  cohort: CourseCohortSummary;
  initialSchedule: LearningCohortsCohortSchedule | null;
}

interface EditItemForm {
  title: string;
  location: string;
  meetingUrl: string;
  status: LearningCohortsCohortScheduleItemStatus;
  visibilityOverride: LearningCohortsCohortVisibilityOverride;
}

function editForm(item: LearningCohortsCohortScheduleItem): EditItemForm {
  return {
    title: item.title?.trim() || '',
    location: item.location?.trim() || '',
    meetingUrl: item.meetingUrl?.trim() || '',
    status: item.status ?? 'Scheduled',
    visibilityOverride: item.visibilityOverride ?? 'Inherited',
  };
}

export function CohortScheduleWorkspace({ courseId, cohort, initialSchedule }: CohortScheduleWorkspaceProps) {
  'use no memo';

  const [schedule, setSchedule] = useState(initialSchedule);
  const [view, setView] = useState<ScheduleView>('syllabus');
  const [shiftItem, setShiftItem] = useState<LearningCohortsCohortScheduleItem | null>(null);
  const [shiftDays, setShiftDays] = useState('7');
  const [shiftScope, setShiftScope] = useState<LearningCohortsScheduleShiftScope>('Single');
  const [editItem, setEditItem] = useState<LearningCohortsCohortScheduleItem | null>(null);
  const [editValues, setEditValues] = useState<EditItemForm | null>(null);
  const [pending, setPending] = useState<'shift' | 'edit' | null>(null);
  const [mutationError, setMutationError] = useState<string | null>(null);
  const readOnly = cohort.status === 'completed' || cohort.status === 'cancelled';

  useEffect(() => {
    const query = window.matchMedia('(max-width: 767px)');
    if (query.matches) setView('timeline');
  }, []);

  const openEdit = (item: LearningCohortsCohortScheduleItem) => {
    setEditItem(item);
    setEditValues(editForm(item));
    setMutationError(null);
  };

  const submitShift = async () => {
    const days = Number(shiftDays);
    if (!Number.isInteger(days) || days === 0) {
      setMutationError('Enter a non-zero whole number of days.');
      return;
    }
    setPending('shift');
    setMutationError(null);
    const result = await shiftCohortScheduleItem(courseId, cohort.id, shiftItem!.id!, {
      expectedVersion: schedule!.version ?? 0,
      days,
      scope: shiftScope,
    });
    setPending(null);
    if (!result.success) {
      setMutationError(result.error);
      return;
    }
    setSchedule(result.data);
    setShiftItem(null);
  };

  const submitEdit = useCallback(async () => {
    if (!editValues!.title.trim()) {
      setMutationError('Schedule item title is required.');
      return;
    }
    setPending('edit');
    setMutationError(null);
    const result = await updateCohortScheduleItem(courseId, cohort.id, editItem!.id!, {
      expectedVersion: schedule!.version ?? 0,
      item: {
        title: editValues!.title.trim(),
        startsAt: editItem!.startsAt,
        endsAt: editItem!.endsAt,
        availableFrom: editItem!.availableFrom,
        availableUntil: editItem!.availableUntil,
        dueAt: editItem!.dueAt,
        location: editValues!.location.trim() || null,
        meetingUrl: editValues!.meetingUrl.trim() || null,
        status: editValues!.status,
        visibilityOverride: editValues!.visibilityOverride,
      },
    });
    setPending(null);
    if (!result.success) {
      setMutationError(result.error);
      return;
    }
    setSchedule(result.data);
    setEditItem(null);
    setEditValues(null);
  }, [cohort.id, courseId, editItem, editValues, schedule]);

  return (
    <div className="min-w-0 space-y-5">
      <header className="flex flex-col gap-3 border-b pb-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <div className="flex flex-wrap items-center gap-2">
            <h2 className="text-xl font-semibold">Class schedule</h2>
            {schedule ? <Badge variant="outline">Version {schedule.version ?? 0}</Badge> : <Badge variant="secondary">Not configured</Badge>}
          </div>
          <p className="mt-1 text-sm text-muted-foreground">
            Plan content release, live meetings, and assessments for this class without changing the canonical course.
          </p>
        </div>
        {!readOnly ? (
          <ScheduleBuilderSheet courseId={courseId} cohort={cohort} schedule={schedule} onApplied={setSchedule} />
        ) : null}
      </header>

      {readOnly ? (
        <Alert>
          <ShieldCheck />
          <AlertTitle>Completed classes are read only.</AlertTitle>
          <AlertDescription>The schedule remains available for records and reporting, but it can no longer be changed.</AlertDescription>
        </Alert>
      ) : null}

      {mutationError && !shiftItem && !editItem ? (
        <Alert variant="destructive">
          <AlertTriangle />
          <AlertTitle>Schedule update failed</AlertTitle>
          <AlertDescription>{mutationError}</AlertDescription>
        </Alert>
      ) : null}

      {schedule ? (
        <>
          <div className="grid gap-3 sm:grid-cols-3">
            <div className="flex items-center gap-3 rounded-md border px-3 py-2.5">
              <Clock3 className="size-4 text-muted-foreground" />
              <div className="min-w-0"><p className="text-xs text-muted-foreground">Timezone</p><p className="truncate text-sm font-medium">{schedule.timezoneId || 'UTC'}</p></div>
            </div>
            <div className="flex items-center gap-3 rounded-md border px-3 py-2.5">
              <CalendarDays className="size-4 text-muted-foreground" />
              <div className="min-w-0"><p className="text-xs text-muted-foreground">Meeting days</p><p className="truncate text-sm font-medium">{schedule.meetingDays?.join(', ') || 'Manual'}</p></div>
            </div>
            <div className="flex items-center gap-3 rounded-md border px-3 py-2.5">
              <ListTree className="size-4 text-muted-foreground" />
              <div className="min-w-0"><p className="text-xs text-muted-foreground">Scheduled items</p><p className="text-sm font-medium">{schedule.items?.length ?? 0}</p></div>
            </div>
          </div>

          {(schedule.unscheduledContentIds?.length ?? 0) > 0 ? (
            <Alert>
              <AlertTriangle />
              <AlertTitle>Curriculum changed after this schedule was built</AlertTitle>
              <AlertDescription>{schedule.unscheduledContentIds?.length} course items still need dates. Generate a new preview before the class starts.</AlertDescription>
            </Alert>
          ) : null}

          <Tabs value={view} onValueChange={(value) => setView(value as ScheduleView)}>
            <TabsList variant="line" className="w-full justify-start overflow-x-auto border-b">
              <TabsTrigger value="syllabus"><ListTree />Syllabus</TabsTrigger>
              <TabsTrigger value="calendar"><CalendarDays />Calendar</TabsTrigger>
              <TabsTrigger value="timeline"><Clock3 />Timeline</TabsTrigger>
            </TabsList>
            <TabsContent value="syllabus" className="pt-3">
              <SyllabusView schedule={schedule} readOnly={readOnly} onEdit={openEdit} onShift={(item) => { setShiftItem(item); setMutationError(null); }} />
            </TabsContent>
            <TabsContent value="calendar" className="pt-3"><CalendarView schedule={schedule} /></TabsContent>
            <TabsContent value="timeline" className="pt-3"><TimelineView schedule={schedule} /></TabsContent>
          </Tabs>
        </>
      ) : (
        <div className="border-y border-dashed py-16 text-center">
          <CalendarDays className="mx-auto size-8 text-muted-foreground" />
          <h3 className="mt-4 font-medium">This class does not have a schedule yet</h3>
          <p className="mx-auto mt-1 max-w-lg text-sm text-muted-foreground">Define its cadence once, review the generated syllabus, and apply it only when the dates are correct.</p>
        </div>
      )}

      <Dialog open={Boolean(shiftItem)} onOpenChange={() => { setShiftItem(null); setMutationError(null); }}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Shift {shiftItem?.title || 'schedule item'}</DialogTitle>
            <DialogDescription>Move this date only, or preserve the cadence by moving this item and everything after it.</DialogDescription>
          </DialogHeader>
          {mutationError ? <p role="alert" className="text-sm text-destructive">{mutationError}</p> : null}
          <div className="space-y-2">
            <Label htmlFor="shift-days">Days to shift</Label>
            <Input id="shift-days" type="number" step={1} value={shiftDays} onChange={(event) => setShiftDays(event.target.value)} />
            <p className="text-xs text-muted-foreground">Use a negative value to move the schedule earlier.</p>
          </div>
          <RadioGroup value={shiftScope} onValueChange={(value) => setShiftScope(value as LearningCohortsScheduleShiftScope)}>
            <div className="flex items-start gap-3 rounded-md border p-3">
              <RadioGroupItem id="shift-single" value="Single" aria-label="Only this item" />
              <Label htmlFor="shift-single" className="cursor-pointer font-normal"><span className="block text-sm font-medium">Only this item</span><span className="block text-xs text-muted-foreground">Other schedule dates stay unchanged.</span></Label>
            </div>
            <div className="flex items-start gap-3 rounded-md border p-3">
              <RadioGroupItem id="shift-following" value="Following" aria-label="This and following items" />
              <Label htmlFor="shift-following" className="cursor-pointer font-normal"><span className="block text-sm font-medium">This and following items</span><span className="block text-xs text-muted-foreground">Keeps the remaining sequence aligned.</span></Label>
            </div>
          </RadioGroup>
          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => setShiftItem(null)}>Cancel</Button>
            <Button type="button" onClick={submitShift} disabled={pending !== null}>
              {pending === 'shift' ? <Loader2 className="size-4 animate-spin" /> : <MoveRight className="size-4" />}
              Shift schedule item
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={Boolean(editItem)} onOpenChange={() => { setEditItem(null); setEditValues(null); setMutationError(null); }}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Edit schedule item</DialogTitle>
            <DialogDescription>Change delivery metadata for this class. Use Shift when dates need to move.</DialogDescription>
          </DialogHeader>
          {mutationError ? <p role="alert" className="text-sm text-destructive">{mutationError}</p> : null}
          {editValues ? (
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2 sm:col-span-2">
                <Label htmlFor="schedule-item-title">Schedule item title</Label>
                <Input id="schedule-item-title" value={editValues.title} onChange={(event) => setEditValues({ ...editValues, title: event.target.value })} />
              </div>
              <div className="space-y-2">
                <Label htmlFor="schedule-item-status">Status</Label>
                <Select
                  items={[
                    { value: "Draft", label: "Draft" },
                    { value: "Scheduled", label: "Scheduled" },
                    { value: "Published", label: "Published" },
                    { value: "Completed", label: "Completed" },
                    { value: "Cancelled", label: "Cancelled" },
                  ]}
                  value={editValues.status}
                  onValueChange={(value) =>
                    setEditValues({
                      ...editValues,
                      status: value as LearningCohortsCohortScheduleItemStatus,
                    })
                  }
                >
                  <SelectTrigger id="schedule-item-status" className="w-full">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectGroup>
                      <SelectItem value="Draft">Draft</SelectItem>
                      <SelectItem value="Scheduled">Scheduled</SelectItem>
                      <SelectItem value="Published">Published</SelectItem>
                      <SelectItem value="Completed">Completed</SelectItem>
                      <SelectItem value="Cancelled">Cancelled</SelectItem>
                    </SelectGroup>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="schedule-item-visibility">Student visibility</Label>
                <Select
                  items={[
                    { value: "Inherited", label: "Follow course content" },
                    { value: "Visible", label: "Force visible" },
                    { value: "Hidden", label: "Hide from students" },
                  ]}
                  value={editValues.visibilityOverride}
                  onValueChange={(value) =>
                    setEditValues({
                      ...editValues,
                      visibilityOverride: value as LearningCohortsCohortVisibilityOverride,
                    })
                  }
                >
                  <SelectTrigger id="schedule-item-visibility" className="w-full">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectGroup>
                      <SelectItem value="Inherited">Follow course content</SelectItem>
                      <SelectItem value="Visible">Force visible</SelectItem>
                      <SelectItem value="Hidden">Hide from students</SelectItem>
                    </SelectGroup>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="schedule-item-location">Location</Label>
                <Input id="schedule-item-location" value={editValues.location} onChange={(event) => setEditValues({ ...editValues, location: event.target.value })} />
              </div>
              <div className="space-y-2">
                <Label htmlFor="schedule-item-url">Meeting URL</Label>
                <Input id="schedule-item-url" type="url" value={editValues.meetingUrl} onChange={(event) => setEditValues({ ...editValues, meetingUrl: event.target.value })} />
              </div>
            </div>
          ) : null}
          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => setEditItem(null)}>Cancel</Button>
            <Button type="button" onClick={submitEdit} disabled={pending !== null}>
              {pending === 'edit' ? <Loader2 className="size-4 animate-spin" /> : <Pencil className="size-4" />}
              Save schedule item
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import type {
  LearningCohortsCohortPacingMode,
  LearningCohortsCohortReleasePolicy,
  LearningCohortsCohortSchedule,
  LearningCohortsCohortSchedulePreview,
  LearningCohortsPreviewCohortScheduleInput,
  SystemDayOfWeek,
} from '@game-guild/client';
import { Alert, AlertDescription, AlertTitle } from '@game-guild/ui/components/alert';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { Checkbox } from '@game-guild/ui/components/checkbox';
import { Input } from '@game-guild/ui/components/input';
import { Label } from '@game-guild/ui/components/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@game-guild/ui/components/select';
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from '@game-guild/ui/components/sheet';
import { AlertTriangle, ArrowLeft, CalendarRange, CheckCircle2, Loader2, WandSparkles } from 'lucide-react';
import { useState } from 'react';

import { applyCohortSchedule, previewCohortSchedule } from '@/lib/learning/actions/cohorts';
import type { CourseCohortSummary } from '@/lib/learning/queries/cohorts';
import { formatScheduleDate } from './schedule-view-utils';

interface ScheduleBuilderSheetProps {
  courseId: string;
  cohort: CourseCohortSummary;
  schedule: LearningCohortsCohortSchedule | null;
  readOnly?: boolean;
  onApplied: (schedule: LearningCohortsCohortSchedule) => void;
}

interface ScheduleRulesForm {
  firstInstructionalDate: string;
  cohortEndDate: string;
  timezoneId: string;
  meetingDays: SystemDayOfWeek[];
  meetingStartTime: string;
  meetingDurationMinutes: number;
  pacingMode: LearningCohortsCohortPacingMode;
  unitsPerPeriod: number;
  releasePolicy: LearningCohortsCohortReleasePolicy;
  skippedDates: string;
  assessmentDueOffsetDays: number;
}

const meetingDayOptions: Array<{ value: SystemDayOfWeek; label: string }> = [
  { value: 'Monday', label: 'Mon' },
  { value: 'Tuesday', label: 'Tue' },
  { value: 'Wednesday', label: 'Wed' },
  { value: 'Thursday', label: 'Thu' },
  { value: 'Friday', label: 'Fri' },
  { value: 'Saturday', label: 'Sat' },
  { value: 'Sunday', label: 'Sun' },
];

function datePart(value: string | null | undefined): string {
  return value?.slice(0, 10) || '';
}

function initialRules(cohort: CourseCohortSummary, schedule: LearningCohortsCohortSchedule | null): ScheduleRulesForm {
  return {
    firstInstructionalDate: datePart(cohort.period.startsAt),
    cohortEndDate: datePart(cohort.period.endsAt),
    timezoneId: schedule?.timezoneId?.trim() || 'UTC',
    meetingDays: schedule?.meetingDays?.length ? [...schedule.meetingDays] : ['Monday'],
    meetingStartTime: schedule?.meetingStartTime?.slice(0, 5) || '09:00',
    meetingDurationMinutes: schedule?.meetingDurationMinutes ?? 90,
    pacingMode: schedule?.pacingMode ?? 'OneModulePerWeek',
    unitsPerPeriod: schedule?.unitsPerPeriod ?? 1,
    releasePolicy: schedule?.releasePolicy ?? 'Weekly',
    skippedDates: '',
    assessmentDueOffsetDays: 0,
  };
}

function toPreviewInput(rules: ScheduleRulesForm): LearningCohortsPreviewCohortScheduleInput {
  return {
    firstInstructionalDate: rules.firstInstructionalDate,
    cohortEndDate: rules.cohortEndDate,
    timezoneId: rules.timezoneId.trim(),
    meetingDays: rules.meetingDays,
    meetingStartTime: `${rules.meetingStartTime}:00`,
    meetingDurationMinutes: rules.meetingDurationMinutes,
    pacingMode: rules.pacingMode,
    unitsPerPeriod: rules.unitsPerPeriod,
    releasePolicy: rules.releasePolicy,
    skippedDates: rules.skippedDates
      .split(/[\s,]+/)
      .map((value) => value.trim())
      .filter(Boolean),
    assessmentDueOffsetDays: rules.assessmentDueOffsetDays,
  };
}

export function ScheduleBuilderSheet({
  courseId,
  cohort,
  schedule,
  readOnly = false,
  onApplied,
}: ScheduleBuilderSheetProps) {
  const [open, setOpen] = useState(false);
  const [rules, setRules] = useState<ScheduleRulesForm>(() => initialRules(cohort, schedule));
  const [preview, setPreview] = useState<LearningCohortsCohortSchedulePreview | null>(null);
  const [pending, setPending] = useState<'preview' | 'apply' | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [advisoriesConfirmed, setAdvisoriesConfirmed] = useState(false);

  const updateRules = <K extends keyof ScheduleRulesForm>(key: K, value: ScheduleRulesForm[K]) => {
    setRules((current) => ({ ...current, [key]: value }));
    setPreview(null);
    setAdvisoriesConfirmed(false);
    setError(null);
  };

  const toggleMeetingDay = (day: SystemDayOfWeek, checked: boolean) => {
    updateRules(
      'meetingDays',
      checked ? [...new Set([...rules.meetingDays, day])] : rules.meetingDays.filter((value) => value !== day),
    );
  };

  const generatePreview = async () => {
    if (rules.meetingDays.length === 0) {
      setError('Select at least one meeting day.');
      return;
    }
    setPending('preview');
    setError(null);
    const result = await previewCohortSchedule(courseId, cohort.id, toPreviewInput(rules));
    setPending(null);
    if (!result.success) {
      setError(result.error);
      return;
    }
    setPreview(result.data);
  };

  const conflicts = preview?.conflicts ?? [];
  const previewItems = preview?.items ?? [];
  const hasBlockingConflicts = preview?.hasBlockingConflicts || conflicts.some((conflict) => conflict.severity === 'Blocking');
  const hasAdvisoryConflicts = conflicts.some((conflict) => conflict.severity === 'Advisory');
  const canApply = Boolean(preview) && !hasBlockingConflicts && (!hasAdvisoryConflicts || advisoriesConfirmed) && pending === null;

  const applyPreview = async () => {
    setPending('apply');
    setError(null);
    const result = await applyCohortSchedule(courseId, cohort.id, {
      expectedVersion: schedule?.version ?? 0,
      rules: toPreviewInput(rules),
      confirmAdvisories: advisoriesConfirmed,
    });
    setPending(null);
    if (!result.success) {
      setError(result.error);
      return;
    }
    onApplied(result.data);
    setOpen(false);
    setPreview(null);
  };

  if (readOnly) return null;

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger render={<Button variant={schedule ? 'outline' : 'default'} />}>
        <CalendarRange className="size-4" />
        {schedule ? 'Edit schedule' : 'Build schedule'}
      </SheetTrigger>
      <SheetContent className="w-full overflow-y-auto sm:max-w-2xl">
        <SheetHeader className="border-b">
          <div className="flex items-center gap-2 text-xs font-medium text-muted-foreground">
            <span className={preview ? '' : 'text-foreground'}>1. Rules</span>
            <span aria-hidden="true">/</span>
            <span className={preview ? 'text-foreground' : ''}>2. Preview</span>
          </div>
          <SheetTitle>{schedule ? 'Edit class schedule' : 'Build class schedule'}</SheetTitle>
          <SheetDescription>
            Configure the delivery cadence for {cohort.name}. Previewing never changes the live schedule.
          </SheetDescription>
        </SheetHeader>

        <div className="flex-1 px-4 pb-4">
          {error ? (
            <Alert variant="destructive" className="mb-4">
              <AlertTriangle />
              <AlertTitle>Schedule could not be processed</AlertTitle>
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          ) : null}

          {!preview ? (
            <div className="space-y-6">
              <section aria-labelledby="calendar-rules-heading">
                <h3 id="calendar-rules-heading" className="text-sm font-semibold">Calendar</h3>
                <div className="mt-3 grid gap-4 sm:grid-cols-2">
                  <div className="space-y-2">
                    <Label htmlFor="first-instructional-date">First instructional date</Label>
                    <Input id="first-instructional-date" type="date" value={rules.firstInstructionalDate} onChange={(event) => updateRules('firstInstructionalDate', event.target.value)} />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="cohort-end-date">Class end date</Label>
                    <Input id="cohort-end-date" type="date" value={rules.cohortEndDate} onChange={(event) => updateRules('cohortEndDate', event.target.value)} />
                  </div>
                  <div className="space-y-2 sm:col-span-2">
                    <Label htmlFor="schedule-timezone">Timezone</Label>
                    <Input id="schedule-timezone" value={rules.timezoneId} onChange={(event) => updateRules('timezoneId', event.target.value)} placeholder="America/Sao_Paulo" />
                  </div>
                </div>
              </section>

              <section aria-labelledby="meeting-rules-heading">
                <h3 id="meeting-rules-heading" className="text-sm font-semibold">Meeting pattern</h3>
                <div className="mt-3 flex flex-wrap gap-2">
                  {meetingDayOptions.map((day) => (
                    <label key={day.value} className="flex cursor-pointer items-center gap-2 rounded-md border px-3 py-2 text-sm has-[[data-state=checked]]:border-primary has-[[data-state=checked]]:bg-primary/5">
                      <Checkbox checked={rules.meetingDays.includes(day.value)} onCheckedChange={(checked) => toggleMeetingDay(day.value, checked === true)} />
                      {day.label}
                    </label>
                  ))}
                </div>
                <div className="mt-4 grid gap-4 sm:grid-cols-2">
                  <div className="space-y-2">
                    <Label htmlFor="meeting-start-time">Meeting start time</Label>
                    <Input id="meeting-start-time" type="time" value={rules.meetingStartTime} onChange={(event) => updateRules('meetingStartTime', event.target.value)} />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="meeting-duration">Meeting duration (minutes)</Label>
                    <Input id="meeting-duration" type="number" min={15} step={15} value={rules.meetingDurationMinutes} onChange={(event) => updateRules('meetingDurationMinutes', Number(event.target.value))} />
                  </div>
                </div>
              </section>

              <section aria-labelledby="pacing-rules-heading">
                <h3 id="pacing-rules-heading" className="text-sm font-semibold">Pacing and release</h3>
                <div className="mt-3 grid gap-4 sm:grid-cols-2">
                  <div className="space-y-2">
                    <Label htmlFor="pacing-mode">Pacing mode</Label>
                    <Select value={rules.pacingMode} onValueChange={(value) => updateRules('pacingMode', value as LearningCohortsCohortPacingMode)}>
                      <SelectTrigger id="pacing-mode" className="w-full"><SelectValue /></SelectTrigger>
                      <SelectContent>
                        <SelectItem value="OneModulePerWeek">One module per week</SelectItem>
                        <SelectItem value="OneLessonPerMeeting">One lesson per meeting</SelectItem>
                        <SelectItem value="FixedLessonsPerWeek">Fixed lessons per week</SelectItem>
                        <SelectItem value="Manual">Manual</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="units-per-period">Units per period</Label>
                    <Input id="units-per-period" type="number" min={1} value={rules.unitsPerPeriod} onChange={(event) => updateRules('unitsPerPeriod', Number(event.target.value))} />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="release-policy">Release policy</Label>
                    <Select value={rules.releasePolicy} onValueChange={(value) => updateRules('releasePolicy', value as LearningCohortsCohortReleasePolicy)}>
                      <SelectTrigger id="release-policy" className="w-full"><SelectValue /></SelectTrigger>
                      <SelectContent>
                        <SelectItem value="Weekly">At the start of the instructional week</SelectItem>
                        <SelectItem value="BeforeMeeting">Before each meeting</SelectItem>
                        <SelectItem value="Manual">Manual release</SelectItem>
                        <SelectItem value="Immediately">Immediately</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="assessment-offset">Assessment due offset (days)</Label>
                    <Input id="assessment-offset" type="number" value={rules.assessmentDueOffsetDays} onChange={(event) => updateRules('assessmentDueOffsetDays', Number(event.target.value))} />
                  </div>
                  <div className="space-y-2 sm:col-span-2">
                    <Label htmlFor="skipped-dates">Skipped dates</Label>
                    <Input id="skipped-dates" value={rules.skippedDates} onChange={(event) => updateRules('skippedDates', event.target.value)} placeholder="2026-09-07, 2026-10-12" />
                    <p className="text-xs text-muted-foreground">Separate holidays and breaks with commas.</p>
                  </div>
                </div>
              </section>
            </div>
          ) : (
            <div className="space-y-5">
              <div className="flex flex-wrap items-center justify-between gap-3">
                <Button type="button" variant="ghost" size="sm" onClick={() => setPreview(null)}>
                  <ArrowLeft className="size-4" /> Back to rules
                </Button>
                <Badge variant="outline">Ends {preview.calculatedEndDate || rules.cohortEndDate}</Badge>
              </div>

              <section aria-labelledby="preview-summary-heading">
                <h3 id="preview-summary-heading" className="text-sm font-semibold">Generated schedule</h3>
                <div className="mt-3 divide-y rounded-md border">
                  {previewItems.slice(0, 8).map((item, index) => (
                    <div key={`${item.programContentId ?? item.assessmentId ?? 'item'}-${index}`} className="flex items-center justify-between gap-3 px-3 py-2.5 text-sm">
                      <div className="min-w-0">
                        <p className="truncate font-medium">{item.title?.trim() || 'Untitled schedule item'}</p>
                        <p className="text-xs text-muted-foreground">Week {Math.max(1, item.instructionalWeek ?? 1)}</p>
                      </div>
                      <span className="shrink-0 text-xs text-muted-foreground">
                        {formatScheduleDate(item.availableFrom ?? item.startsAt ?? item.dueAt, rules.timezoneId) || 'Date not set'}
                      </span>
                    </div>
                  ))}
                </div>
                {previewItems.length > 8 ? <p className="mt-2 text-xs text-muted-foreground">And {previewItems.length - 8} more items.</p> : null}
              </section>

              {conflicts.length > 0 ? (
                <section aria-labelledby="conflicts-heading">
                  <h3 id="conflicts-heading" className="text-sm font-semibold">Conflicts to review</h3>
                  <div className="mt-3 space-y-2">
                    {conflicts.map((conflict, index) => (
                      <Alert key={`${conflict.code ?? 'conflict'}-${index}`} variant={conflict.severity === 'Blocking' ? 'destructive' : 'default'}>
                        <AlertTriangle />
                        <AlertTitle>{conflict.severity === 'Blocking' ? 'Blocking conflict' : 'Advisory'}</AlertTitle>
                        <AlertDescription>{conflict.message || 'Review this schedule conflict.'}</AlertDescription>
                      </Alert>
                    ))}
                  </div>
                  {hasAdvisoryConflicts && !hasBlockingConflicts ? (
                    <div className="mt-3 flex items-start gap-2 rounded-md border p-3">
                      <Checkbox id="confirm-advisories" checked={advisoriesConfirmed} onCheckedChange={(checked) => setAdvisoriesConfirmed(checked === true)} />
                      <Label htmlFor="confirm-advisories" className="cursor-pointer font-normal leading-4">I reviewed the advisory conflicts</Label>
                    </div>
                  ) : null}
                </section>
              ) : (
                <Alert>
                  <CheckCircle2 />
                  <AlertTitle>Ready to apply</AlertTitle>
                  <AlertDescription>No schedule conflicts were found.</AlertDescription>
                </Alert>
              )}
            </div>
          )}
        </div>

        <SheetFooter className="border-t bg-background">
          {!preview ? (
            <Button type="button" onClick={generatePreview} disabled={pending !== null}>
              {pending === 'preview' ? <Loader2 className="size-4 animate-spin" /> : <WandSparkles className="size-4" />}
              Generate preview
            </Button>
          ) : (
            <Button type="button" onClick={applyPreview} disabled={!canApply}>
              {pending === 'apply' ? <Loader2 className="size-4 animate-spin" /> : <CheckCircle2 className="size-4" />}
              Apply schedule
            </Button>
          )}
        </SheetFooter>
      </SheetContent>
    </Sheet>
  );
}

import type {
  LearningCohortsCohortSchedule,
  LearningCohortsCohortScheduleItem,
  LearningCohortsCohortScheduleItemType,
} from '@game-guild/client';

export function scheduleItems(schedule: LearningCohortsCohortSchedule): LearningCohortsCohortScheduleItem[] {
  return [...(schedule.items ?? [])].sort((left, right) => {
    const weekDifference = (left.instructionalWeek ?? 0) - (right.instructionalWeek ?? 0);
    return weekDifference || (left.sortOrder ?? 0) - (right.sortOrder ?? 0);
  });
}

export function itemPrimaryDate(item: LearningCohortsCohortScheduleItem): string | null {
  return item.availableFrom ?? item.startsAt ?? item.dueAt ?? item.availableUntil ?? null;
}

export function formatScheduleDate(
  value: string | null | undefined,
  timezoneId: string | null | undefined,
  options: Intl.DateTimeFormatOptions = {},
): string | null {
  if (!value) return null;
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return null;

  return new Intl.DateTimeFormat('en-US', {
    timeZone: timezoneId || 'UTC',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
    ...options,
  }).format(date);
}

export function formatCalendarDay(value: string, timezoneId: string | null | undefined): string {
  return new Intl.DateTimeFormat('en-US', {
    timeZone: timezoneId || 'UTC',
    weekday: 'long',
    month: 'long',
    day: 'numeric',
    year: 'numeric',
  }).format(new Date(value));
}

export function calendarDayKey(value: string, timezoneId: string | null | undefined): string {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: timezoneId || 'UTC',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(new Date(value));
  const part = (type: Intl.DateTimeFormatPartTypes) => parts.find((candidate) => candidate.type === type)?.value ?? '';
  return `${part('year')}-${part('month')}-${part('day')}`;
}

export function itemTypeLabel(type: LearningCohortsCohortScheduleItemType | undefined): string {
  if (type === 'ContentRelease') return 'Content release';
  if (type === 'LiveSession') return 'Live class';
  if (type === 'AssessmentWindow') return 'Assessment';
  return 'Milestone';
}

'use client';

import type { LearningCohortsCohortSchedule, LearningCohortsCohortScheduleItem } from '@game-guild/client';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { CalendarClock, FileClock, MoveRight, Pencil, Radio, Target } from 'lucide-react';

import { formatScheduleDate, itemTypeLabel, scheduleItems } from './schedule-view-utils';

interface SyllabusViewProps {
  schedule: LearningCohortsCohortSchedule;
  readOnly?: boolean;
  onShift?: (item: LearningCohortsCohortScheduleItem) => void;
  onEdit?: (item: LearningCohortsCohortScheduleItem) => void;
}

function typeIcon(item: LearningCohortsCohortScheduleItem) {
  if (item.type === 'LiveSession') return Radio;
  if (item.type === 'AssessmentWindow') return Target;
  if (item.type === 'Milestone') return CalendarClock;
  return FileClock;
}

function itemMeta(item: LearningCohortsCohortScheduleItem, timezoneId: string | null | undefined) {
  const values: string[] = [];
  const available = formatScheduleDate(item.availableFrom, timezoneId);
  const starts = formatScheduleDate(item.startsAt, timezoneId);
  const due = formatScheduleDate(item.dueAt, timezoneId);
  if (available) values.push(`Available ${available}`);
  if (starts) values.push(`Starts ${starts}`);
  if (due) values.push(`Due ${due}`);
  if (item.location) values.push(item.location);
  return values;
}

export function SyllabusView({ schedule, readOnly = false, onShift, onEdit }: SyllabusViewProps) {
  const weeks = new Map<number, LearningCohortsCohortScheduleItem[]>();
  for (const item of scheduleItems(schedule)) {
    const week = Math.max(1, item.instructionalWeek ?? 1);
    weeks.set(week, [...(weeks.get(week) ?? []), item]);
  }

  if (weeks.size === 0) {
    return (
      <div className="border-y border-dashed py-14 text-center">
        <h3 className="font-medium">No scheduled content yet</h3>
        <p className="mt-1 text-sm text-muted-foreground">Build a schedule to turn the course curriculum into a class syllabus.</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {[...weeks.entries()].map(([week, items]) => {
        const anchor = items.find((item) => item.type === 'ContentRelease') ?? items[0];
        const heading = `Week ${week} - ${anchor?.title?.trim() || 'Instructional plan'}`;

        return (
          <section key={week} className="overflow-hidden rounded-md border bg-card" aria-labelledby={`week-${week}`}>
            <div className="flex min-h-12 items-center justify-between gap-3 border-b bg-muted/35 px-4 py-2.5">
              <h3 id={`week-${week}`} className="text-sm font-semibold">{heading}</h3>
              <Badge variant="outline">{items.length} {items.length === 1 ? 'item' : 'items'}</Badge>
            </div>
            <div className="divide-y">
              {items.map((item, index) => {
                const Icon = typeIcon(item);
                const title = item.title?.trim() || 'Untitled schedule item';
                return (
                  <div key={item.id ?? `${week}-${index}`} className="flex min-h-16 items-center gap-3 px-4 py-3">
                    <span className="flex size-8 shrink-0 items-center justify-center rounded-md bg-muted text-muted-foreground">
                      <Icon className="size-4" aria-hidden="true" />
                    </span>
                    <div className="min-w-0 flex-1">
                      <div className="flex flex-wrap items-center gap-2">
                        <p className="truncate text-sm font-medium">{title}</p>
                        <Badge variant="secondary" className="font-normal">{itemTypeLabel(item.type)}</Badge>
                      </div>
                      <p className="mt-1 truncate text-xs text-muted-foreground">
                        {itemMeta(item, schedule.timezoneId).join(' · ') || 'Date not set'}
                      </p>
                    </div>
                    {!readOnly && item.id ? (
                      <div className="flex shrink-0 items-center gap-1">
                        {onEdit ? (
                          <Button type="button" variant="ghost" size="icon-sm" aria-label={`Edit ${title}`} onClick={() => onEdit(item)}>
                            <Pencil className="size-4" />
                          </Button>
                        ) : null}
                        {onShift ? (
                          <Button type="button" variant="ghost" size="icon-sm" aria-label={`Shift ${title}`} onClick={() => onShift(item)}>
                            <MoveRight className="size-4" />
                          </Button>
                        ) : null}
                      </div>
                    ) : null}
                  </div>
                );
              })}
            </div>
          </section>
        );
      })}
    </div>
  );
}

'use client';

import type { LearningCohortsCohortSchedule } from '@game-guild/client';
import { Badge } from '@game-guild/ui/components/badge';

import { formatScheduleDate, itemPrimaryDate, itemTypeLabel, scheduleItems } from './schedule-view-utils';

export function TimelineView({ schedule }: { schedule: LearningCohortsCohortSchedule }) {
  const items = scheduleItems(schedule)
    .map((item, index) => ({ item, index, date: itemPrimaryDate(item) }))
    .sort((left, right) => {
      const dateDifference = new Date(left.date ?? 0).getTime() - new Date(right.date ?? 0).getTime();
      return dateDifference || (left.item.sortOrder ?? left.index) - (right.item.sortOrder ?? right.index);
    });

  if (items.length === 0) {
    return <p className="border-y border-dashed py-14 text-center text-sm text-muted-foreground">No timeline items have been scheduled.</p>;
  }

  return (
    <ol className="relative ml-3 border-l">
      {items.map(({ item, index, date }) => (
        <li key={item.id ?? index} data-testid="timeline-entry" className="relative pb-6 pl-7 last:pb-0">
          <span className="absolute -left-1.5 top-2 size-3 rounded-full border-2 border-background bg-primary" aria-hidden="true" />
          <div className="flex flex-wrap items-start justify-between gap-2 rounded-md border bg-card px-4 py-3">
            <div className="min-w-0">
              <p className="text-xs text-muted-foreground">
                {date ? formatScheduleDate(date, schedule.timezoneId) : 'Date not set'}
              </p>
              <p className="mt-1 text-sm font-medium">{item.title?.trim() || 'Untitled schedule item'}</p>
              {item.dueAt && item.dueAt !== date ? (
                <p className="mt-1 text-xs text-muted-foreground">Due {formatScheduleDate(item.dueAt, schedule.timezoneId)}</p>
              ) : null}
            </div>
            <div className="flex items-center gap-2">
              <Badge variant="outline">Week {Math.max(1, item.instructionalWeek ?? 1)}</Badge>
              <Badge variant="secondary">{itemTypeLabel(item.type)}</Badge>
            </div>
          </div>
        </li>
      ))}
    </ol>
  );
}

'use client';

import { updateCohort, updateCohortStatus } from '@/lib/learning/actions/cohorts';
import type { CourseCohortDetail } from '@/lib/learning/queries/cohorts';
import { useRouter } from '@/i18n/navigation';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@game-guild/ui/components/alert-dialog';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { Input } from '@game-guild/ui/components/input';
import { Label } from '@game-guild/ui/components/label';
import { Textarea } from '@game-guild/ui/components/textarea';
import { Ban, CheckCircle2, Loader2, Lock, Save, Unlock } from 'lucide-react';
import { FormEvent, useState, useTransition } from 'react';

interface CohortSettingsFormProps {
  courseId: string;
  cohort: CourseCohortDetail;
}

export function CohortSettingsForm({ courseId, cohort }: CohortSettingsFormProps) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [message, setMessage] = useState<{ kind: 'success' | 'error'; text: string } | null>(null);

  const save = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setMessage(null);
    const data = new FormData(event.currentTarget);
    const startDate = String(data.get('startDate') ?? '');
    const endDate = String(data.get('endDate') ?? '');

    startTransition(async () => {
      try {
        const result = await updateCohort({
          courseId,
          cohortId: cohort.id,
          name: String(data.get('name') ?? ''),
          description: String(data.get('description') ?? ''),
          startDate: `${startDate}T00:00:00`,
          endDate: `${endDate}T23:59:59`,
          maxCapacity: Number.parseInt(String(data.get('capacity') ?? ''), 10),
          meetingSchedule: String(data.get('meetingPattern') ?? ''),
        });

        setMessage(result.success ? { kind: 'success', text: 'Class settings saved.' } : { kind: 'error', text: result.error });
        if (result.success) router.refresh();
      } catch (saveError) {
        setMessage({
          kind: 'error',
          text: saveError instanceof Error ? saveError.message : 'Unable to save class settings.',
        });
      }
    });
  };

  const runStatus = (action: 'open' | 'close' | 'complete' | 'cancel') => {
    setMessage(null);
    startTransition(async () => {
      try {
        const result = await updateCohortStatus(courseId, cohort.id, action);
        setMessage(result.success ? { kind: 'success', text: 'Class status updated.' } : { kind: 'error', text: result.error });
        if (result.success) router.refresh();
      } catch (statusError) {
        setMessage({
          kind: 'error',
          text: statusError instanceof Error ? statusError.message : 'Unable to update class status.',
        });
      }
    });
  };

  return (
    <div className="space-y-6">
      <form onSubmit={save} className="space-y-5 rounded-lg border p-5">
        <div className="flex items-center justify-between gap-4">
          <div><h3 className="font-medium">Class settings</h3><p className="mt-1 text-sm text-muted-foreground">Period, capacity, and meeting identity.</p></div>
          <Badge variant="outline" className="capitalize">{cohort.status}</Badge>
        </div>

        <div className="space-y-2"><Label htmlFor="settings-name">Name</Label><Input id="settings-name" name="name" defaultValue={cohort.name} minLength={3} required disabled={pending} /></div>
        <div className="space-y-2"><Label htmlFor="settings-description">Description</Label><Textarea id="settings-description" name="description" defaultValue={cohort.description} rows={3} disabled={pending} /></div>
        <div className="grid gap-4 sm:grid-cols-2">
          <div className="space-y-2"><Label htmlFor="settings-start">Start date</Label><Input id="settings-start" name="startDate" type="date" defaultValue={cohort.period.startsAt.slice(0, 10)} required disabled={pending} /></div>
          <div className="space-y-2"><Label htmlFor="settings-end">End date</Label><Input id="settings-end" name="endDate" type="date" defaultValue={cohort.period.endsAt.slice(0, 10)} required disabled={pending} /></div>
        </div>
        <div className="grid gap-4 sm:grid-cols-2">
          <div className="space-y-2"><Label htmlFor="settings-capacity">Capacity</Label><Input id="settings-capacity" name="capacity" type="number" min={1} defaultValue={cohort.enrollment.capacity ?? 24} required disabled={pending} /></div>
          <div className="space-y-2"><Label htmlFor="settings-pattern">Meeting pattern</Label><Input id="settings-pattern" name="meetingPattern" defaultValue={cohort.meetingPattern ?? ''} placeholder="Tue/Thu - 19:00" disabled={pending} /></div>
        </div>
        {message ? <p role={message.kind === 'success' ? 'status' : 'alert'} className={message.kind === 'success' ? 'text-sm text-emerald-600' : 'text-sm text-destructive'}>{message.text}</p> : null}
        <Button type="submit" disabled={pending}>{pending ? <Loader2 className="size-4 animate-spin" /> : <Save className="size-4" />}Save settings</Button>
      </form>

      <section className="space-y-4 rounded-lg border p-5">
        <div><h3 className="font-medium">Enrollment and lifecycle</h3><p className="mt-1 text-sm text-muted-foreground">Current enrollment: {cohort.enrollment.current} students.</p></div>
        <div className="flex flex-wrap gap-2">
          {cohort.isOpen ? (
            <Button variant="outline" onClick={() => runStatus('close')} disabled={pending}><Lock className="size-4" />Close enrollment</Button>
          ) : (
            <Button variant="outline" onClick={() => runStatus('open')} disabled={pending}><Unlock className="size-4" />Open enrollment</Button>
          )}
          <Button variant="outline" onClick={() => runStatus('complete')} disabled={pending || cohort.status === 'completed'}><CheckCircle2 className="size-4" />Mark complete</Button>
          <AlertDialog>
            <AlertDialogTrigger render={<Button variant="destructive" disabled={pending || cohort.status === 'cancelled'} />}><Ban className="size-4" />Cancel class</AlertDialogTrigger>
            <AlertDialogContent>
              <AlertDialogHeader><AlertDialogTitle>Cancel {cohort.name}?</AlertDialogTitle><AlertDialogDescription>Enrollment will close and the class schedule will no longer be active. Existing student records remain preserved.</AlertDialogDescription></AlertDialogHeader>
              <AlertDialogFooter><AlertDialogCancel>Keep class</AlertDialogCancel><AlertDialogAction variant="destructive" onClick={() => runStatus('cancel')}>Cancel class</AlertDialogAction></AlertDialogFooter>
            </AlertDialogContent>
          </AlertDialog>
        </div>
      </section>
    </div>
  );
}

'use client';

import { Link } from '@/i18n/navigation';
import type { CourseCohortSummary } from '@/lib/learning/queries/cohorts';
import type { LearningCohortsCohortCalendarEntry } from '@game-guild/client';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { CalendarDays, Clock3 } from 'lucide-react';
import { useState } from 'react';
import { useLearningBase } from '@/lib/learning/use-learning-base';

interface GeneralCohortCalendarProps {
  courseId: string;
  cohorts: CourseCohortSummary[];
  entries: LearningCohortsCohortCalendarEntry[];
}

const laneColors = [
  'border-l-emerald-500 bg-emerald-500/5',
  'border-l-sky-500 bg-sky-500/5',
  'border-l-amber-500 bg-amber-500/5',
  'border-l-fuchsia-500 bg-fuchsia-500/5',
];
const dateTimeFormatter = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZone: 'UTC' });

export function GeneralCohortCalendar({ courseId, cohorts, entries }: GeneralCohortCalendarProps) {
  const learningBase = useLearningBase();
  const [mode, setMode] = useState<'week' | 'month'>('week');

  return (
    <div className="space-y-5">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
        <div>
          <h2 className="text-xl font-semibold">General class calendar</h2>
          <p className="mt-1 text-sm text-muted-foreground">Compare overlapping cohorts without merging their schedules.</p>
        </div>
        <div className="inline-flex w-fit rounded-md border p-1" aria-label="Calendar view">
          <Button type="button" size="sm" variant={mode === 'week' ? 'secondary' : 'ghost'} onClick={() => setMode('week')}>Week</Button>
          <Button type="button" size="sm" variant={mode === 'month' ? 'secondary' : 'ghost'} onClick={() => setMode('month')}>Month</Button>
        </div>
      </div>

      <div className="space-y-3" data-calendar-mode={mode}>
        {cohorts.map((cohort, index) => {
          const cohortEntries = entries
            .filter((entry) => entry.cohortId === cohort.id)
            .sort((left, right) => String(left.startsAt ?? left.availableFrom ?? '').localeCompare(String(right.startsAt ?? right.availableFrom ?? '')));

          return (
            <section
              key={cohort.id}
              aria-label={`${cohort.name} calendar lane`}
              className={`rounded-lg border border-l-4 ${laneColors[index % laneColors.length]}`}
            >
              <header className="flex flex-col gap-2 border-b px-4 py-3 sm:flex-row sm:items-center sm:justify-between">
                <div>
                  <Link href={`${learningBase}/courses/${courseId}/classes/${cohort.id}/schedule`} className="font-medium hover:underline">{cohort.name}</Link>
                  <p className="mt-0.5 text-xs text-muted-foreground">{cohort.meetingPattern ?? 'Meeting pattern not configured'}</p>
                </div>
                <Badge variant="outline">{cohortEntries.length} scheduled items</Badge>
              </header>

              <div className={mode === 'week' ? 'grid gap-2 p-3 sm:grid-cols-2 xl:grid-cols-4' : 'grid gap-2 p-3 sm:grid-cols-2 lg:grid-cols-3'}>
                {cohortEntries.length === 0 ? (
                  <div className="col-span-full flex items-center gap-2 px-2 py-6 text-sm text-muted-foreground">
                    <CalendarDays className="size-4" /> No schedule has been applied to this class.
                  </div>
                ) : cohortEntries.map((entry, itemIndex) => {
                  const instant = entry.startsAt ?? entry.availableFrom ?? entry.dueAt;
                  return (
                    <Link
                      key={entry.itemId ?? `${cohort.id}-${itemIndex}`}
                      href={`${learningBase}/courses/${courseId}/classes/${cohort.id}/schedule#item-${entry.itemId ?? itemIndex}`}
                      className="min-w-0 rounded-md border bg-background p-3 transition-colors hover:bg-muted/50"
                    >
                      <p className="truncate text-sm font-medium">{entry.title || 'Untitled schedule item'}</p>
                      <div className="mt-2 flex items-center gap-1.5 text-xs text-muted-foreground">
                        <Clock3 className="size-3.5" />
                        {instant ? dateTimeFormatter.format(new Date(instant)) : 'Date not set'}
                      </div>
                      <p className="mt-1 text-xs text-muted-foreground">{entry.type ?? 'Schedule item'}</p>
                    </Link>
                  );
                })}
              </div>
            </section>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import { createCohort } from "@/lib/learning/actions/cohorts";
import { useRouter } from "@/i18n/navigation";
import { Button } from "@game-guild/ui/components/button";
import { Input } from "@game-guild/ui/components/input";
import { Label } from "@game-guild/ui/components/label";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@game-guild/ui/components/sheet";
import { Textarea } from "@game-guild/ui/components/textarea";
import { ArrowRight, Loader2, Plus } from "lucide-react";
import { FormEvent, useState, useTransition } from "react";
import { useLearningBase } from '@/lib/learning/use-learning-base';

interface NewClassSheetProps {
  courseId: string;
}

export function NewClassSheet({ courseId }: NewClassSheetProps) {
  const learningBase = useLearningBase();
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [pending, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setError(null);

    const data = new FormData(event.currentTarget);
    const startDate = String(data.get("startDate") ?? "");
    const endDate = String(data.get("endDate") ?? "");
    const capacity = Number.parseInt(String(data.get("capacity") ?? ""), 10);

    startTransition(async () => {
      const result = await createCohort({
        courseId,
        name: String(data.get("name") ?? ""),
        description: String(data.get("description") ?? ""),
        startDate: `${startDate}T00:00:00`,
        endDate: `${endDate}T23:59:59`,
        maxCapacity: capacity,
        meetingSchedule: String(data.get("meetingPattern") ?? ""),
      });

      if (!result.success) {
        setError(result.error);
        return;
      }

      setOpen(false);
      router.push(
        `${learningBase}/courses/${courseId}/classes/${result.data.id}/schedule`,
      );
    });
  };

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger render={<Button />}>
        <Plus className="size-4" />
        New class
      </SheetTrigger>
      <SheetContent className="w-full overflow-y-auto sm:max-w-xl">
        <SheetHeader className="border-b px-6 py-5">
          <SheetTitle>Create class</SheetTitle>
          <SheetDescription>
            Define the cohort period first. Build its meetings, releases, and
            due dates in the next step.
          </SheetDescription>
        </SheetHeader>

        <form onSubmit={submit} className="flex min-h-0 flex-1 flex-col">
          <div className="flex-1 space-y-5 px-6 py-5">
            <div className="space-y-2">
              <Label htmlFor="cohort-name">Class name</Label>
              <Input
                id="cohort-name"
                name="name"
                placeholder="2026.2 - Evening"
                minLength={3}
                required
                disabled={pending}
              />
              <p className="text-xs text-muted-foreground">
                Use a name that distinguishes period, shift, or audience.
              </p>
            </div>

            <div className="space-y-2">
              <Label htmlFor="cohort-description">Description</Label>
              <Textarea
                id="cohort-description"
                name="description"
                rows={3}
                placeholder="Evening cohort for working professionals."
                disabled={pending}
              />
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label htmlFor="cohort-start">Start date</Label>
                <Input
                  id="cohort-start"
                  name="startDate"
                  type="date"
                  required
                  disabled={pending}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="cohort-end">End date</Label>
                <Input
                  id="cohort-end"
                  name="endDate"
                  type="date"
                  required
                  disabled={pending}
                />
              </div>
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label htmlFor="cohort-capacity">Capacity</Label>
                <Input
                  id="cohort-capacity"
                  name="capacity"
                  type="number"
                  min={1}
                  defaultValue={24}
                  required
                  disabled={pending}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="cohort-meeting-pattern">Meeting pattern</Label>
                <Input
                  id="cohort-meeting-pattern"
                  name="meetingPattern"
                  placeholder="Tue/Thu - 19:00"
                  disabled={pending}
                />
              </div>
            </div>

            <div className="rounded-md border bg-muted/30 p-4 text-sm">
              <p className="font-medium">Next: build the class schedule</p>
              <p className="mt-1 text-muted-foreground">
                Choose the timezone, meeting days, weekly pacing, content
                release policy, and skipped dates.
              </p>
            </div>

            {error ? (
              <p role="alert" className="text-sm text-destructive">
                {error}
              </p>
            ) : null}
          </div>

          <SheetFooter className="border-t px-6 py-4 sm:flex-row sm:justify-end">
            <Button
              type="button"
              variant="outline"
              onClick={() => setOpen(false)}
              disabled={pending}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={pending}>
              {pending ? (
                <Loader2 className="size-4 animate-spin" />
              ) : (
                <ArrowRight className="size-4" />
              )}
              Create and build schedule
            </Button>
          </SheetFooter>
        </form>
      </SheetContent>
    </Sheet>
  );
}

