"use client";

import { cn } from "@game-guild/ui/lib/utils";
import { Link, usePathname, useRouter } from "@/i18n/navigation";
import { buildDashboardCoursePath } from "@/lib/learning/course-route";
import type { CourseFeatures } from "@/lib/learning/types";
import {
  publishCourse,
  restoreCourse,
  unpublishCourse,
} from "@/lib/learning/actions";
import { Badge } from "@game-guild/ui/components/badge";
import { Button, buttonVariants } from "@game-guild/ui/components/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@game-guild/ui/components/dialog";
import {
  ArrowLeft,
  Award,
  BookOpen,
  CalendarDays,
  Eye,
  EyeOff,
  GraduationCap,
  Info,
  LayoutDashboard,
  Loader2,
  MessageSquare,
  Settings,
  Share2,
  Users,
  UsersRound,
  type LucideIcon,
} from "lucide-react";
import { useEffect, useState, type ReactNode } from "react";
import { useLearningBase } from "@/lib/learning/use-learning-base";
import type { CourseAccessCapabilities } from "@/lib/learning/queries/course";

interface CourseNavProps {
  courseTitle: string;
  courseDescription: string;
  courseStatus: "draft" | "published" | "archived";
  courseSlug: string | null;
  courseRouteParam: string;
  locale: string;
  features: CourseFeatures;
  access: CourseAccessCapabilities;
  children: ReactNode;
}

interface NavItem {
  title: string;
  icon: LucideIcon;
  segment: string;
  enabled: boolean;
}

function getStatusBadge(status: string) {
  switch (status) {
    case "published":
      return (
        <Badge className="bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200">
          Published
        </Badge>
      );
    case "draft":
      return <Badge variant="secondary">Draft</Badge>;
    case "archived":
      return <Badge variant="outline">Archived</Badge>;
    default:
      return null;
  }
}

function buildNavItems(
  features: CourseFeatures,
  access: CourseAccessCapabilities,
): NavItem[] {
  return [
    {
      title: "Overview",
      icon: LayoutDashboard,
      segment: "overview",
      enabled: true,
    },
    {
      title: "Listing",
      icon: Info,
      segment: "listing",
      enabled: access.canEdit || access.canPublish,
    },
    {
      title: "Content",
      icon: BookOpen,
      segment: "content",
      enabled: access.canEdit,
    },
    {
      title: "Classes",
      icon: CalendarDays,
      segment: "classes",
      enabled: access.canEdit && features.hasClasses,
    },
    {
      title: "Assessments",
      icon: GraduationCap,
      segment: "assessments",
      enabled:
        features.hasAssessments && (access.canEdit || access.canReviewAsStaff),
    },
    {
      title: "Certificates",
      icon: Award,
      segment: "certificates",
      enabled: access.canEdit && features.hasCertificate,
    },
    {
      title: "Groups",
      icon: UsersRound,
      segment: "groups",
      enabled: access.canEdit,
    },
    {
      title: "Students",
      icon: Users,
      segment: "students",
      enabled: access.canReviewAsStaff,
    },
    {
      title: "Support",
      icon: MessageSquare,
      segment: "support",
      enabled: access.canEdit,
    },
    {
      title: "Settings",
      icon: Settings,
      segment: "settings",
      enabled: access.canEdit,
    },
  ].filter((item) => item.enabled);
}

export function CourseNav({
  courseTitle,
  courseDescription,
  courseStatus,
  courseSlug,
  courseRouteParam,
  locale,
  features,
  access,
  children,
}: CourseNavProps) {
  const learningBase = useLearningBase();
  const pathname = usePathname() ?? "";
  const router = useRouter();
  const publicCourseHref = courseSlug?.trim()
    ? `/courses/${courseSlug.trim()}`
    : null;
  const previewHref = buildDashboardCoursePath(courseRouteParam, "preview");
  const [shareLabel, setShareLabel] = useState("Share");
  const [status, setStatus] = useState(courseStatus);
  const [isPending, setIsPending] = useState(false);
  const [showUnpublishDialog, setShowUnpublishDialog] = useState(false);
  const [actionError, setActionError] = useState<string | null>(null);

  const navItems = buildNavItems(features, access);

  useEffect(() => {
    setStatus(courseStatus);
  }, [courseStatus]);

  async function copyPublicCourseUrl() {
    if (!publicCourseHref || !navigator.clipboard?.writeText) {
      return;
    }

    await navigator.clipboard.writeText(
      `${window.location.origin}${publicCourseHref}`,
    );
    setShareLabel("Copied");
  }

  async function runLifecycleAction(
    action: "publish" | "unpublish" | "restore",
  ) {
    setActionError(null);
    setIsPending(true);
    try {
      const result =
        action === "publish"
          ? await publishCourse(courseRouteParam)
          : action === "restore"
            ? await restoreCourse(courseRouteParam)
            : await unpublishCourse(courseRouteParam);

      if (result.success) {
        setStatus(action === "publish" ? "published" : "draft");
        setShowUnpublishDialog(false);
        router.refresh();
      } else {
        setActionError(result.error);
      }
    } catch (error) {
      setActionError(
        error instanceof Error
          ? error.message
          : "The course lifecycle action failed.",
      );
    } finally {
      setIsPending(false);
    }
  }

  // Match the active segment after the dynamic course route param.
  const activeSegment = (() => {
    const marker = "/workspace/learning/courses/";
    const idx = pathname.indexOf(marker);
    if (idx === -1) return "";
    const tail = pathname.slice(idx + marker.length);
    return tail.split("/")[1] ?? "";
  })();

  return (
    <div className="flex min-w-0 max-w-full flex-col gap-6 overflow-x-hidden">
      {/* Header */}
      <div className="flex min-w-0 max-w-full flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex min-w-0 items-center gap-4">
          <Link
            href="/workspace/learning/courses"
            locale={locale}
            prefetch={false}
            className={cn(buttonVariants({ variant: "ghost", size: "icon" }))}
          >
            <ArrowLeft className="size-5" />
          </Link>
          <div className="flex size-12 shrink-0 items-center justify-center rounded-lg bg-linear-to-br from-emerald-500 to-teal-600">
            <BookOpen className="size-6 text-white" />
          </div>
          <div className="min-w-0">
            <div className="flex min-w-0 flex-wrap items-center gap-2">
              <h1 className="min-w-0 break-words text-2xl font-bold tracking-tight">
                {courseTitle}
              </h1>
              {getStatusBadge(status)}
            </div>
            <p className="max-w-prose break-words text-sm text-muted-foreground">
              {courseDescription}
            </p>
          </div>
        </div>
        <div className="flex flex-wrap items-center gap-2 sm:justify-end">
          {access.canEdit && (
            <Link
              href={previewHref}
              locale={locale}
              prefetch={false}
              className={cn(buttonVariants({ variant: "outline", size: "sm" }))}
            >
              <Eye className="mr-2 size-4" />
              Preview
            </Link>
          )}
          {access.canPublish && (
            <Button
              variant="outline"
              size="sm"
              type="button"
              disabled={!publicCourseHref}
              onClick={copyPublicCourseUrl}
            >
              <Share2 className="mr-2 size-4" />
              {shareLabel}
            </Button>
          )}
          {access.canPublish && (status === "published" ? (
            <Button
              variant="outline"
              size="sm"
              type="button"
              disabled={isPending}
              onClick={() => setShowUnpublishDialog(true)}
            >
              {isPending ? (
                <Loader2 className="mr-2 size-4 animate-spin" />
              ) : (
                <EyeOff className="mr-2 size-4" />
              )}
              Unpublish
            </Button>
          ) : status === "archived" ? (
            <Button
              variant="outline"
              size="sm"
              type="button"
              disabled={isPending}
              onClick={() => void runLifecycleAction("restore")}
            >
              {isPending ? (
                <Loader2 className="mr-2 size-4 animate-spin" />
              ) : (
                <Eye className="mr-2 size-4" />
              )}
              Restore
            </Button>
          ) : (
            <Button
              variant="outline"
              size="sm"
              type="button"
              disabled={isPending}
              onClick={() => void runLifecycleAction("publish")}
            >
              {isPending ? (
                <Loader2 className="mr-2 size-4 animate-spin" />
              ) : (
                <Eye className="mr-2 size-4" />
              )}
              Publish
            </Button>
          ))}
          {access.canEdit && (
            <Link
              href={buildDashboardCoursePath(courseRouteParam, "settings")}
              locale={locale}
              prefetch={false}
              className={cn(buttonVariants({ variant: "outline", size: "sm" }))}
            >
              <Settings className="mr-2 size-4" />
              Settings
            </Link>
          )}
        </div>
      </div>

      {actionError && (
        <div className="rounded-md border border-destructive/30 bg-destructive/10 px-3 py-2 text-sm text-destructive">
          {actionError}
        </div>
      )}

      {/* Nav Tabs + Content */}
      <div className="flex min-w-0 flex-1 gap-6">
        {/* Sidebar Nav */}
        <nav className="hidden w-48 shrink-0 flex-col gap-1 lg:flex">
          {navItems.map((item) => {
            const isActive = activeSegment === item.segment;
            return (
              <Link
                key={item.segment}
                href={buildDashboardCoursePath(courseRouteParam, item.segment)}
                locale={locale}
                prefetch={false}
                className={`flex items-center gap-2 rounded-md px-3 py-2 text-sm font-medium transition-colors ${
                  isActive
                    ? "bg-muted text-foreground"
                    : "text-muted-foreground hover:bg-muted/50 hover:text-foreground"
                }`}
              >
                <item.icon className="size-4" />
                {item.title}
              </Link>
            );
          })}
        </nav>

        <div className="flex min-w-0 w-full flex-1 flex-col gap-6">
          {/* Mobile tabs - scrollable */}
          <div className="flex min-w-0 max-w-full gap-1 overflow-x-auto border-b pb-2 lg:hidden">
            {navItems.map((item) => {
              const isActive = activeSegment === item.segment;
              return (
                <Link
                  key={item.segment}
                  href={buildDashboardCoursePath(
                    courseRouteParam,
                    item.segment,
                  )}
                  locale={locale}
                  prefetch={false}
                  className={`flex shrink-0 items-center gap-1.5 rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
                    isActive
                      ? "bg-muted text-foreground"
                      : "text-muted-foreground hover:text-foreground"
                  }`}
                >
                  <item.icon className="size-3.5" />
                  {item.title}
                </Link>
              );
            })}
          </div>
          <div className="min-w-0 flex-1">{children}</div>
        </div>
      </div>

      <Dialog open={showUnpublishDialog} onOpenChange={setShowUnpublishDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Unpublish this course?</DialogTitle>
            <DialogDescription>
              This will remove the course from the public catalog and block new
              enrollments. Existing students and course data are preserved.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              variant="outline"
              type="button"
              onClick={() => setShowUnpublishDialog(false)}
              disabled={isPending}
            >
              Cancel
            </Button>
            <Button
              type="button"
              onClick={() => void runLifecycleAction("unpublish")}
              disabled={isPending}
            >
              {isPending && <Loader2 className="mr-2 size-4 animate-spin" />}
              Unpublish course
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

'use client';

import { updateCourseFaq } from '@/lib/learning/actions';
import type { CourseFaqItem } from '@/lib/learning/queries/listing';
import { Button } from '@game-guild/ui/components/button';
import { Input } from '@game-guild/ui/components/input';
import { Label } from '@game-guild/ui/components/label';
import { Textarea } from '@game-guild/ui/components/textarea';
import { Loader2, Plus, Save, Trash2 } from 'lucide-react';
import type { FormEvent } from 'react';
import { useState } from 'react';

interface FaqEditorFormProps {
  courseId: string;
  items: CourseFaqItem[];
}

interface EditableFaqItem {
  id: string;
  question: string;
  answer: string;
  category: string;
}

function createEmptyItem(): EditableFaqItem {
  return {
    id: `new-${Date.now()}`,
    question: '',
    answer: '',
    category: 'Course details',
  };
}

export function FaqEditorForm({ courseId, items }: FaqEditorFormProps) {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [draftItems, setDraftItems] = useState<EditableFaqItem[]>(
    items.length > 0
      ? items.map((item) => ({
          id: item.id,
          question: item.question,
          answer: item.answer,
          category: item.category ?? 'Course details',
        }))
      : [createEmptyItem()],
  );
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  function updateItem(id: string, field: keyof Omit<EditableFaqItem, 'id'>, value: string) {
    setDraftItems((current) => current.map((item) => (item.id === id ? { ...item, [field]: value } : item)));
    setError(null);
    setSuccess(false);
  }

  function addItem() {
    setDraftItems((current) => [...current, createEmptyItem()]);
    setSuccess(false);
  }

  function removeItem(id: string) {
    setDraftItems((current) => {
      const next = current.filter((item) => item.id !== id);
      return next.length > 0 ? next : [createEmptyItem()];
    });
    setSuccess(false);
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(null);
    setSuccess(false);

    const incompleteIndex = draftItems.findIndex((item) => {
      const question = item.question.trim();
      const answer = item.answer.trim();
      return (question.length > 0 || answer.length > 0) && (question.length === 0 || answer.length === 0);
    });

    if (incompleteIndex >= 0) {
      setError(`Complete both the question and answer for Question ${incompleteIndex + 1}.`);
      return;
    }

    const persistedItems = draftItems.filter((item) => item.question.trim().length > 0 && item.answer.trim().length > 0).slice(0, 12);

    setIsSubmitting(true);

    try {
      const result = await updateCourseFaq(courseId, persistedItems);

      if (!result.success) {
        setError(result.error);
        return;
      }

      setDraftItems(persistedItems.length > 0 ? persistedItems : [createEmptyItem()]);
      setSuccess(true);
    } catch (error) {
      setError(error instanceof Error ? error.message : 'The FAQ could not be saved.');
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-5">
      <div className="space-y-4">
        {draftItems.map((item, index) => (
          <div key={item.id} className="rounded-lg border p-4">
            <div className="mb-4 flex items-center justify-between gap-4">
              <p className="text-sm font-medium">Question {index + 1}</p>
              <Button type="button" variant="ghost" size="icon" onClick={() => removeItem(item.id)} aria-label={`Remove question ${index + 1}`}>
                <Trash2 className="size-4" />
              </Button>
            </div>

            <div className="grid gap-4">
              <div className="grid gap-2">
                <Label htmlFor={`${item.id}-question`}>Question</Label>
                <Input
                  id={`${item.id}-question`}
                  value={item.question}
                  onChange={(event) => updateItem(item.id, 'question', event.target.value)}
                  placeholder="What will students need before joining?"
                />
              </div>

              <div className="grid gap-2">
                <Label htmlFor={`${item.id}-answer`}>Answer</Label>
                <Textarea
                  id={`${item.id}-answer`}
                  value={item.answer}
                  onChange={(event) => updateItem(item.id, 'answer', event.target.value)}
                  placeholder="Give a clear, student-facing answer."
                  rows={4}
                />
              </div>

              <div className="grid gap-2">
                <Label htmlFor={`${item.id}-category`}>Category</Label>
                <Input
                  id={`${item.id}-category`}
                  value={item.category}
                  onChange={(event) => updateItem(item.id, 'category', event.target.value)}
                  placeholder="Course details"
                />
              </div>
            </div>
          </div>
        ))}
      </div>

      {error ? (
        <div role="alert" className="rounded-md border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:border-red-900 dark:bg-red-950 dark:text-red-300">
          {error}
        </div>
      ) : null}
      {success ? (
        <div className="rounded-md border border-green-200 bg-green-50 p-3 text-sm text-green-700 dark:border-green-900 dark:bg-green-950 dark:text-green-300">
          FAQ updated successfully.
        </div>
      ) : null}

      <div className="flex flex-wrap gap-3">
        <Button type="button" variant="outline" onClick={addItem}>
          <Plus className="mr-2 size-4" />
          Add question
        </Button>
        <Button type="submit" disabled={isSubmitting}>
          {isSubmitting ? <Loader2 className="mr-2 size-4 animate-spin" /> : <Save className="mr-2 size-4" />}
          Save FAQ
        </Button>
      </div>
    </form>
  );
}

'use client';

import React, { useState, useTransition } from 'react';
import { updateCourse } from '@/lib/learning/actions';
import type { CourseDetails } from '@/lib/learning/types';
import { ENROLLMENT_STATUSES, formatEnumLabel } from '@/lib/learning/enums';
import { Button } from '@game-guild/ui/components/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@game-guild/ui/components/card';
import { Input } from '@game-guild/ui/components/input';
import { Label } from '@game-guild/ui/components/label';
import { SelectGroup,  Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@game-guild/ui/components/select';
import { Loader2, Save } from 'lucide-react';

interface ListingLaunchFormProps {
  course: CourseDetails;
}

export function toDateTimeLocal(value: string | null): string {
  if (!value) {
    return '';
  }

  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return '';
  }

  const localDate = new Date(date.getTime() - date.getTimezoneOffset() * 60000);
  return localDate.toISOString().slice(0, 16);
}

export function toIsoDateTime(value: string): string | null {
  if (!value) {
    return null;
  }

  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date.toISOString();
}

export function parseEnrollmentCap(value: string): number | null {
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
}

export function ListingLaunchForm({ course }: ListingLaunchFormProps) {
  const [isPending, startTransition] = useTransition();
  const [visibility, setVisibility] = useState<'public' | 'private'>(course.visibility === 'public' ? 'public' : 'private');
  const [enrollmentStatus, setEnrollmentStatus] = useState(course.enrollmentStatus || 'Open');
  const [enrollmentDeadline, setEnrollmentDeadline] = useState(toDateTimeLocal(course.enrollmentDeadline));
  const [maxEnrollments, setMaxEnrollments] = useState(course.maxEnrollments?.toString() ?? '');
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(null);
    setSuccess(false);

    startTransition(async () => {
      const result = await updateCourse({
        courseId: course.id,
        visibility: visibility === 'public' ? 'Public' : 'Private',
        enrollmentStatus,
        enrollmentDeadline: toIsoDateTime(enrollmentDeadline),
        maxEnrollments: parseEnrollmentCap(maxEnrollments),
      });

      if (!result.success) {
        setError(result.error);
        return;
      }

      setSuccess(true);
    });
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>Launch Controls</CardTitle>
        <CardDescription>
          Control visibility and enrollment on today&apos;s shared course contract. Teaser-first scheduling stays blocked until the API adds explicit launch timestamps.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-5">
          <div className="space-y-2">
            <Label htmlFor="catalog-visibility">Catalog visibility</Label>
            <Select
              items={[
                { value: "public", label: "Public" },
                { value: "private", label: "Private" },
              ]}
              value={visibility}
              onValueChange={(value) => setVisibility(value ?? "public")}
            >
              <SelectTrigger id="catalog-visibility">
                <SelectValue>{visibility === 'public' ? 'Public' : 'Private'}</SelectValue>
              </SelectTrigger>
              <SelectContent>
                <SelectGroup>
                  <SelectItem value="public">Public</SelectItem>
                  <SelectItem value="private">Private</SelectItem>
                </SelectGroup>
              </SelectContent>
            </Select>
            <p className="text-xs text-muted-foreground">Public courses can appear in the catalog. Private courses stay hidden.</p>
          </div>

          <div className="space-y-2">
            <Label htmlFor="listing-enrollment-status">Enrollment status</Label>
            <Select
              items={[
                ...ENROLLMENT_STATUSES.map((value) => ({
                  value: value,
                  label: formatEnumLabel(value),
                })),
              ]}
              value={enrollmentStatus}
              onValueChange={(value) => setEnrollmentStatus(value ?? "Open")}
            >
              <SelectTrigger id="listing-enrollment-status">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectGroup>
                  {ENROLLMENT_STATUSES.map((value) => (
                    <SelectItem key={value} value={value}>
                      {formatEnumLabel(value)}
                    </SelectItem>
                  ))}
                </SelectGroup>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label htmlFor="enrollmentDeadline">Enrollment deadline</Label>
            <Input
              id="enrollmentDeadline"
              type="datetime-local"
              value={enrollmentDeadline}
              onChange={(event) => setEnrollmentDeadline(event.target.value)}
            />
            <p className="text-xs text-muted-foreground">Leave blank to keep enrollments open until manually closed.</p>
          </div>

          <div className="space-y-2">
            <Label htmlFor="maxEnrollments">Enrollment cap</Label>
            <Input
              id="maxEnrollments"
              type="number"
              min="0"
              value={maxEnrollments}
              onChange={(event) => setMaxEnrollments(event.target.value)}
              placeholder="0 for unlimited"
            />
            <p className="text-xs text-muted-foreground">Use 0 or leave blank for unlimited seats.</p>
          </div>

          {error ? (
            <div className="rounded-md border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:border-red-900 dark:bg-red-950 dark:text-red-300">
              {error}
            </div>
          ) : null}

          {success ? (
            <div className="rounded-md border border-green-200 bg-green-50 p-3 text-sm text-green-700 dark:border-green-900 dark:bg-green-950 dark:text-green-300">
              Listing controls updated successfully.
            </div>
          ) : null}

          <Button type="submit" disabled={isPending} className="w-full">
            {isPending ? (
              <>
                <Loader2 className="mr-2 size-4 animate-spin" /> Saving...
              </>
            ) : (
              <>
                <Save className="mr-2 size-4" /> Save launch controls
              </>
            )}
          </Button>
        </form>
      </CardContent>
    </Card>
  );
}

'use client';

import { updateCourseLandingProjects } from '@/lib/learning/actions';
import type { CourseLandingProject } from '@/lib/learning/queries/listing';
import { Button } from '@game-guild/ui/components/button';
import { Input } from '@game-guild/ui/components/input';
import { Label } from '@game-guild/ui/components/label';
import { Textarea } from '@game-guild/ui/components/textarea';
import { Loader2, Plus, Save, Trash2 } from 'lucide-react';
import type { FormEvent } from 'react';
import { useState } from 'react';

interface ProjectCarouselEditorFormProps {
  courseId: string;
  items: CourseLandingProject[];
}

interface EditableProjectItem {
  id: string;
  title: string;
  summary: string;
  image: string;
  skills: string;
  deliverable: string;
  moduleLabel: string;
}

function createEmptyProject(index: number): EditableProjectItem {
  return {
    id: `new-project-${index}`,
    title: '',
    summary: '',
    image: '',
    skills: '',
    deliverable: '',
    moduleLabel: `Project ${String(index).padStart(2, '0')}`,
  };
}

export function ProjectCarouselEditorForm({ courseId, items }: ProjectCarouselEditorFormProps) {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [draftItems, setDraftItems] = useState<EditableProjectItem[]>(
    items.length > 0
      ? items.map((item) => ({
          id: item.id,
          title: item.title,
          summary: item.summary,
          image: item.image,
          skills: item.skills.join(', '),
          deliverable: item.deliverable,
          moduleLabel: item.moduleLabel,
        }))
      : [createEmptyProject(1)],
  );
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  function updateItem(id: string, field: keyof Omit<EditableProjectItem, 'id'>, value: string) {
    setDraftItems((current) => current.map((item) => (item.id === id ? { ...item, [field]: value } : item)));
    setError(null);
    setSuccess(false);
  }

  function addItem() {
    setDraftItems((current) => [...current, { ...createEmptyProject(current.length + 1), id: `new-project-${Date.now()}` }]);
    setSuccess(false);
  }

  function removeItem(id: string) {
    setDraftItems((current) => {
      const next = current.filter((item) => item.id !== id);
      return next.length > 0 ? next : [createEmptyProject(1)];
    });
    setSuccess(false);
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(null);
    setSuccess(false);

    const incompleteIndex = draftItems.findIndex((item) => {
      const requiredValues = [item.title, item.summary, item.deliverable];
      const hasAuthoredContent = requiredValues.some((value) => value.trim().length > 0) || item.image.trim().length > 0 || item.skills.trim().length > 0;

      return hasAuthoredContent && requiredValues.some((value) => value.trim().length === 0);
    });

    if (incompleteIndex >= 0) {
      setError(`Complete the title, summary, and deliverable for Project ${incompleteIndex + 1}.`);
      return;
    }

    const persistedItems = draftItems
      .filter((item) => item.title.trim().length > 0 && item.summary.trim().length > 0 && item.deliverable.trim().length > 0)
      .slice(0, 6);

    setIsSubmitting(true);

    try {
      const result = await updateCourseLandingProjects(courseId, persistedItems);

      if (!result.success) {
        setError(result.error);
        return;
      }

      setDraftItems(persistedItems.length > 0 ? persistedItems : [createEmptyProject(1)]);
      setSuccess(true);
    } catch (error) {
      setError(error instanceof Error ? error.message : 'The project carousel could not be saved.');
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-5">
      <div className="space-y-4">
        {draftItems.map((item, index) => (
          <div key={item.id} className="rounded-lg border p-4">
            <div className="mb-4 flex items-center justify-between gap-4">
              <p className="text-sm font-medium">Project {index + 1}</p>
              <Button type="button" variant="ghost" size="icon" onClick={() => removeItem(item.id)} aria-label={`Remove project ${index + 1}`}>
                <Trash2 className="size-4" />
              </Button>
            </div>

            <div className="grid gap-4 lg:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor={`${item.id}-title`}>Project title {index + 1}</Label>
                <Input
                  id={`${item.id}-title`}
                  value={item.title}
                  onChange={(event) => updateItem(item.id, 'title', event.target.value)}
                  placeholder="Boss behavior sandbox"
                />
              </div>

              <div className="grid gap-2">
                <Label htmlFor={`${item.id}-module-label`}>Module label {index + 1}</Label>
                <Input
                  id={`${item.id}-module-label`}
                  value={item.moduleLabel}
                  onChange={(event) => updateItem(item.id, 'moduleLabel', event.target.value)}
                  placeholder="Project 01"
                />
              </div>

              <div className="grid gap-2 lg:col-span-2">
                <Label htmlFor={`${item.id}-summary`}>Summary {index + 1}</Label>
                <Textarea
                  id={`${item.id}-summary`}
                  value={item.summary}
                  onChange={(event) => updateItem(item.id, 'summary', event.target.value)}
                  placeholder="Describe the project in clear student-facing language."
                  rows={3}
                />
              </div>

              <div className="grid gap-2 lg:col-span-2">
                <Label htmlFor={`${item.id}-deliverable`}>Deliverable {index + 1}</Label>
                <Textarea
                  id={`${item.id}-deliverable`}
                  value={item.deliverable}
                  onChange={(event) => updateItem(item.id, 'deliverable', event.target.value)}
                  placeholder="Explain what students will ship or present."
                  rows={3}
                />
              </div>

              <div className="grid gap-2">
                <Label htmlFor={`${item.id}-image`}>Image URL {index + 1}</Label>
                <Input
                  id={`${item.id}-image`}
                  type="url"
                  value={item.image}
                  onChange={(event) => updateItem(item.id, 'image', event.target.value)}
                  placeholder="https://example.com/project.jpg"
                />
              </div>

              <div className="grid gap-2">
                <Label htmlFor={`${item.id}-skills`}>Skills {index + 1}</Label>
                <Input
                  id={`${item.id}-skills`}
                  value={item.skills}
                  onChange={(event) => updateItem(item.id, 'skills', event.target.value)}
                  placeholder="State debugging, Combat pacing"
                />
              </div>
            </div>
          </div>
        ))}
      </div>

      {error ? (
        <div role="alert" className="rounded-md border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:border-red-900 dark:bg-red-950 dark:text-red-300">
          {error}
        </div>
      ) : null}
      {success ? (
        <div className="rounded-md border border-green-200 bg-green-50 p-3 text-sm text-green-700 dark:border-green-900 dark:bg-green-950 dark:text-green-300">
          Project carousel updated successfully.
        </div>
      ) : null}

      <div className="flex flex-wrap gap-3">
        <Button type="button" variant="outline" onClick={addItem}>
          <Plus className="mr-2 size-4" />
          Add project
        </Button>
        <Button type="submit" disabled={isSubmitting}>
          {isSubmitting ? <Loader2 className="mr-2 size-4 animate-spin" /> : <Save className="mr-2 size-4" />}
          Save project carousel
        </Button>
      </div>
    </form>
  );
}

