  const [progressStudent, setProgressStudent] = useState<Student | null>(null);
  const [operationError, setOperationError] = useState<string | null>(null);
  const [operationStatus, setOperationStatus] = useState<string | null>(null);

  useEffect(() => {
    const availableIds = new Set(students.map((student) => student.id));
    setItems(students);
    setSelectedIds(
      (current) => new Set([...current].filter((id) => availableIds.has(id))),
    );
  }, [students]);

  const submitManualEnrollment = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setManualEnrollError(null);
    setOperationStatus(null);

    startTransition(async () => {
      const result = await manualEnrollStudent({
        courseId,
        userId: manualUserId,
        cohortId: manualCohortId || null,
      });

      if (result.success) {
        setManualEnrollOpen(false);
        setManualUserId("");
        setManualCohortId("");
        setOperationStatus("Student enrolled successfully.");
        router.refresh();
        return;
      }

      setManualEnrollError(result.error);
    });
  };

  const filtered = useMemo(() => {
    let result = items;

    if (search) {
      const q = search.toLowerCase();
      result = result.filter(
        (s) =>
          s.name.toLowerCase().includes(q) || s.email.toLowerCase().includes(q),
      );
    }

    if (statusFilter !== "all") {
      result = result.filter((s) => getStatusLabel(s) === statusFilter);
    }

    return result;
  }, [items, search, statusFilter]);

  const selectedStudents = useMemo(
    () => items.filter((student) => selectedIds.has(student.id)),
    [items, selectedIds],
  );

  const toggleAll = () => {
    if (selectedIds.size === filtered.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(filtered.map((s) => s.id)));
    }
  };

  const toggleOne = (id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const requestRemoval = (targets: Student[]) => {
    setOperationError(null);
    setRemoveTargets(targets);
    setRemoveOpen(true);
  };

  const confirmRemoval = () => {
    startTransition(async () => {
      const result = await removeCourseStudents(
        courseId,
        removeTargets.map((student) => student.userId),
      );
      if (!result.success) {
        setOperationError(result.error);
        return;
      }

      const removedIds = new Set(removeTargets.map((student) => student.id));
      setItems((current) =>
        current.filter((student) => !removedIds.has(student.id)),
      );
      setSelectedIds(new Set());
      setRemoveOpen(false);
      setOperationStatus(
        `${result.data.removed} ${result.data.removed === 1 ? "student" : "students"} removed.`,
      );
    });
  };

  const openMessageDialog = (targets: Student[]) => {
    setOperationError(null);
    setMessageTargets(targets);
    setMessageOpen(true);
  };

  const submitMessage = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setOperationError(null);
    startTransition(async () => {
      const result = await sendCourseStudentMessage({
        courseId,
        userIds: messageTargets.map((student) => student.userId),
        subject: messageSubject,
        message: messageBody,
      });
      if (!result.success) {
        setOperationError(result.error);
        return;
      }

      setMessageOpen(false);
      setMessageSubject("");
      setMessageBody("");
      setOperationStatus(
        `Message sent to ${result.data.sent} ${result.data.sent === 1 ? "student" : "students"}.`,
      );
    });
  };

  const exportStudents = () => {
    const escape = (value: string | number) =>
      `"${String(value).replaceAll('"', '""')}"`;
    const rows = [
      ["Name", "Email", "Status", "Progress", "Enrolled", "Last active"],
      ...filtered.map((student) => [
        student.name,
        student.email,
        getStatusLabel(student),
        student.completionPercent,
        student.enrolledAt,
        student.lastActivity,
      ]),
    ];
    const url = URL.createObjectURL(
      new Blob([rows.map((row) => row.map(escape).join(",")).join("\n")], {
        type: "text/csv;charset=utf-8",
      }),
    );
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `course-${courseId}-students.csv`;
    anchor.click();
    URL.revokeObjectURL(url);
  };

  return (
    <Card>
      <CardHeader>
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <CardTitle>Enrolled Students</CardTitle>
            <CardDescription>
              {items.length > 0
                ? `${items.length} ${items.length === 1 ? "student" : "students"} enrolled`
                : "No students enrolled yet"}
            </CardDescription>
          </div>
          <div className="flex flex-wrap gap-2">
            <Dialog open={manualEnrollOpen} onOpenChange={setManualEnrollOpen}>
              <DialogTrigger render={<Button size="sm" />}>
                <UserPlus className="mr-2 size-4" />
                Enroll student
              </DialogTrigger>
              <DialogContent>
                <form onSubmit={submitManualEnrollment} className="space-y-5">
                  <DialogHeader>
                    <DialogTitle>Enroll student manually</DialogTitle>
                    <DialogDescription>
                      Add an existing GameGuild user to this course by email,
                      username, or canonical user ID.
                    </DialogDescription>
                  </DialogHeader>
                  <div className="space-y-4">
                    <div className="space-y-2">
                      <Label htmlFor="manual-user-id">Student</Label>
                      <Input
                        id="manual-user-id"
                        value={manualUserId}
                        onChange={(event) =>
                          setManualUserId(event.target.value)
                        }
                        placeholder="student@example.com, username, or user ID"
                        required
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="manual-cohort-id">Cohort ID</Label>
                      <Input
                        id="manual-cohort-id"
                        value={manualCohortId}
                        onChange={(event) =>
                          setManualCohortId(event.target.value)
                        }
                        placeholder="Optional"
                      />
                      <p className="text-xs text-muted-foreground">
                        Leave blank to enroll the student directly in the
                        course.
                      </p>
                    </div>
                    {manualEnrollError && (
                      <p className="text-sm text-destructive">
                        {manualEnrollError}
                      </p>
                    )}
                  </div>
                  <DialogFooter>
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => setManualEnrollOpen(false)}
                    >
                      Cancel
                    </Button>
                    <Button
                      type="submit"
                      disabled={isPending || !manualUserId.trim()}
                    >
                      {isPending && (
                        <Loader2 className="mr-2 size-4 animate-spin" />
                      )}
                      Enroll student
                    </Button>
                  </DialogFooter>
                </form>
              </DialogContent>
            </Dialog>
            <Button variant="outline" size="sm" onClick={exportStudents}>
              <Download className="mr-2 size-4" />
              Export
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent>
        {/* Filters */}
        <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-center">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              placeholder="Search by name or email..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-9"
            />
          </div>
          <Select value={statusFilter} onValueChange={(value) => setStatusFilter(value ?? "")}>
            <SelectTrigger className="w-full sm:w-[160px]">
              <SelectValue placeholder="Filter" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Students</SelectItem>
              <SelectItem value="active">Active</SelectItem>
              <SelectItem value="completed">Completed</SelectItem>
              <SelectItem value="inactive">Inactive</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Bulk Actions */}
        {selectedIds.size > 0 && (
          <div className="mb-4 flex items-center justify-between rounded-lg bg-muted/50 p-3">
            <span className="text-sm">
              {selectedIds.size} student(s) selected
            </span>
            <div className="flex gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => openMessageDialog(selectedStudents)}
              >
                <Mail className="mr-2 size-4" />
                Send Message
              </Button>
              <Button
                variant="outline"
                size="sm"
                className="text-destructive"
                onClick={() => requestRemoval(selectedStudents)}
              >
                <UserMinus className="mr-2 size-4" />
                Remove
              </Button>
            </div>
          </div>
        )}

        {filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12 text-center">
            <Users className="mb-4 size-12 text-muted-foreground" />
            <h3 className="text-lg font-semibold">No students found</h3>
            <p className="text-sm text-muted-foreground">
              {search || statusFilter !== "all"
                ? "Try adjusting your search or filter criteria."
                : "Students will appear here once they enroll in this course."}
            </p>
          </div>
        ) : (
          <>
            <div className="rounded-md border">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="w-12">
                      <Checkbox
                        checked={
                          selectedIds.size === filtered.length &&
                          filtered.length > 0
                        }
                        onCheckedChange={toggleAll}
                      />
                    </TableHead>
                    <TableHead>Student</TableHead>
                    <TableHead>Progress</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="hidden md:table-cell">
                      Enrolled
                    </TableHead>
                    <TableHead className="hidden lg:table-cell">
                      Last Active
                    </TableHead>
                    <TableHead className="w-12" />
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filtered.map((student) => {
                    const initials = student.name
                      .split(" ")
                      .map((n) => n[0])
                      .join("")
                      .toUpperCase()
                      .slice(0, 2);
                    return (
                      <TableRow key={student.id}>
                        <TableCell>
                          <Checkbox
                            checked={selectedIds.has(student.id)}
                            onCheckedChange={() => toggleOne(student.id)}
                          />
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center gap-3">
                            <Avatar className="size-8">
                              <AvatarFallback className="text-xs">
                                {initials}
                              </AvatarFallback>
                            </Avatar>
                            <div className="flex flex-col">
                              <span className="font-medium">
                                {student.name}
                              </span>
                              <span className="text-xs text-muted-foreground">
                                {student.email}
                              </span>
                            </div>
                          </div>
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center gap-2">
                            <Progress
                              value={student.completionPercent}
                              className="w-20"
                            />
                            <span
                              className={`text-sm font-medium ${progressColor(student.completionPercent)}`}
                            >
                              {student.completionPercent}%
                            </span>
                          </div>
                        </TableCell>
                        <TableCell>
                          <StatusBadge student={student} />
                        </TableCell>
                        <TableCell className="hidden text-sm text-muted-foreground md:table-cell">
                          {new Date(student.enrolledAt).toLocaleDateString()}
                        </TableCell>
                        <TableCell className="hidden text-sm text-muted-foreground lg:table-cell">
                          {new Date(student.lastActivity).toLocaleDateString()}
                        </TableCell>
                        <TableCell>
                          <DropdownMenu>
                            <DropdownMenuTrigger
                              render={
                                <Button variant="ghost"
                                  size="icon"
                                  className="size-8"
                                  aria-label={`Actions for ${student.name}`}
                                />
                              }
                            >
                              <MoreHorizontal className="size-4" />
                            </DropdownMenuTrigger>
                            <DropdownMenuContent align="end">
                              <DropdownMenuItem
                                render={
                                  <Link
                                    href={`/console/community/members/users/${student.userId}`}
                                  />
                                }
                              >
                                <Eye className="mr-2 size-4" />
                                View profile
                              </DropdownMenuItem>
                              <DropdownMenuItem
                                onClick={() => setProgressStudent(student)}
                              >
                                <TrendingUp className="mr-2 size-4" />
                                View progress
                              </DropdownMenuItem>
                              <DropdownMenuSeparator />
                              <DropdownMenuItem
                                className="text-destructive"
                                onClick={() => requestRemoval([student])}
                              >
                                <UserMinus className="mr-2 size-4" />
                                Remove from Course
                              </DropdownMenuItem>
                            </DropdownMenuContent>
                          </DropdownMenu>
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </div>

            <div className="mt-4 flex items-center justify-between">
              <p className="text-sm text-muted-foreground">
                Showing {filtered.length} of {items.length} students
              </p>
            </div>
          </>
        )}
      </CardContent>

      {operationStatus && (
        <p role="status" className="sr-only">
          {operationStatus}
        </p>
      )}
      {operationError && (
        <p role="alert" className="px-6 pb-4 text-sm text-destructive">
          {operationError}
        </p>
      )}

      <Dialog open={removeOpen} onOpenChange={setRemoveOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Remove students</DialogTitle>
            <DialogDescription>
              Remove {removeTargets.length} selected{" "}
              {removeTargets.length === 1 ? "student" : "students"} from this
              course. Their course access will end immediately.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button variant="outline" onClick={() => setRemoveOpen(false)}>
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={confirmRemoval}
              disabled={isPending}
            >
              {isPending && <Loader2 className="mr-2 size-4 animate-spin" />}
              Confirm removal
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={messageOpen} onOpenChange={setMessageOpen}>
        <DialogContent>
          <form onSubmit={submitMessage} className="space-y-5">
            <DialogHeader>
              <DialogTitle>Message students</DialogTitle>
              <DialogDescription>
                Send an in-app notification to {messageTargets.length} selected{" "}
                {messageTargets.length === 1 ? "student" : "students"}.
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="student-message-subject">Subject</Label>
                <Input
                  id="student-message-subject"
                  value={messageSubject}
                  onChange={(event) => setMessageSubject(event.target.value)}
                  required
                  minLength={3}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="student-message-body">Message</Label>
                <Textarea
                  id="student-message-body"
                  value={messageBody}
                  onChange={(event) => setMessageBody(event.target.value)}
                  required
                />
              </div>
            </div>
            <DialogFooter>
              <Button
                type="button"
                variant="outline"
                onClick={() => setMessageOpen(false)}
              >
                Cancel
              </Button>
              <Button
                type="submit"
                disabled={
                  isPending ||
                  messageSubject.trim().length < 3 ||
                  !messageBody.trim()
                }
              >
                {isPending && <Loader2 className="mr-2 size-4 animate-spin" />}
                Send message
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      <Dialog
        open={Boolean(progressStudent)}
        onOpenChange={() => setProgressStudent(null)}
      >
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{progressStudent?.name} progress</DialogTitle>
            <DialogDescription>
              Current completion and activity for this course enrollment.
            </DialogDescription>
          </DialogHeader>
          {progressStudent && (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <span>Completion</span>
                <strong>{progressStudent.completionPercent}% complete</strong>
              </div>
              <Progress value={progressStudent.completionPercent} />
              <div className="grid gap-3 text-sm sm:grid-cols-2">
                <div>
                  <p className="text-muted-foreground">Enrolled</p>
                  <p>
                    {new Date(progressStudent.enrolledAt).toLocaleDateString()}
                  </p>
                </div>
                <div>
                  <p className="text-muted-foreground">Last active</p>
                  <p>
                    {new Date(
                      progressStudent.lastActivity,
                    ).toLocaleDateString()}
                  </p>
                </div>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </Card>
  );
}

'use client';

import { cn } from "@game-guild/ui/lib/utils";
import { Link, useRouter } from '@/i18n/navigation';
import { createCourseDiscussion } from '@/lib/learner/activity-actions';
import type { LearningExperienceSocialServicesCourseDiscussion } from '@game-guild/client';
import { Alert, AlertDescription, AlertTitle } from '@game-guild/ui/components/alert';
import { Badge } from '@game-guild/ui/components/badge';
import { Button, buttonVariants } from '@game-guild/ui/components/button';
import { Card, CardContent } from '@game-guild/ui/components/card';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@game-guild/ui/components/dialog';
import { Input } from '@game-guild/ui/components/input';
import { Textarea } from '@game-guild/ui/components/textarea';
import { ArrowRight, CheckCircle2, MessageCircle, MessagesSquare, Plus } from 'lucide-react';
import { type FormEvent, useState } from 'react';

interface CourseCommunityProps {
  courseId: string;
  courseSlug: string;
  courseTitle: string;
  discussions: LearningExperienceSocialServicesCourseDiscussion[];
}

export function CourseCommunity({
  courseId,
  courseSlug,
  courseTitle,
  discussions,
}: CourseCommunityProps) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setPending(true);
    setError(null);
    try {
      const result = await createCourseDiscussion(new FormData(event.currentTarget));
      if (!result.success) {
        setError(result.error || 'The discussion could not be published.');
        return;
      }

      setSuccess(true);
      router.refresh();
    } catch (submissionError) {
      setError(
        submissionError instanceof Error
          ? submissionError.message
          : 'The discussion could not be published.',
      );
    } finally {
      setPending(false);
    }
  }

  return (
    <div className="space-y-6">
      <header className="flex flex-col gap-4 border-b pb-6 sm:flex-row sm:items-end sm:justify-between">
        <div>
          <p className="text-sm font-medium text-primary">{courseTitle}</p>
          <h1 className="mt-2 text-3xl font-semibold">Course community</h1>
          <p className="mt-2 text-sm text-muted-foreground">
            Ask questions, coordinate peer learning, and continue cohort conversations.
          </p>
        </div>

        <Dialog
          open={open}
          onOpenChange={(value) => {
            setOpen(value);
            if (!value) {
              setError(null);
              setSuccess(false);
            }
          }}
        >
          <DialogTrigger render={<Button />}>
            <Plus className="size-4" />
            Start discussion
          </DialogTrigger>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Start a course discussion</DialogTitle>
              <DialogDescription>
                Everyone enrolled in this course can read and reply.
              </DialogDescription>
            </DialogHeader>

            {success ? (
              <Alert>
                <CheckCircle2 className="size-4 text-emerald-600" />
                <AlertTitle>Discussion published</AlertTitle>
                <AlertDescription>
                  Your thread is now available to the course community.
                </AlertDescription>
              </Alert>
            ) : (
              <form onSubmit={handleSubmit} className="space-y-4">
                <input type="hidden" name="courseId" value={courseId} />
                <input type="hidden" name="courseSlug" value={courseSlug} />
                <div className="space-y-2">
                  <label htmlFor="discussion-title" className="text-sm font-medium">
                    Title
                  </label>
                  <Input id="discussion-title" name="title" required maxLength={160} />
                </div>
                <div className="space-y-2">
                  <label htmlFor="discussion-message" className="text-sm font-medium">
                    Message
                  </label>
                  <Textarea id="discussion-message" name="content" required rows={7} />
                </div>
                {error ? (
                  <Alert variant="destructive">
                    <AlertTitle>Could not publish</AlertTitle>
                    <AlertDescription>{error}</AlertDescription>
                  </Alert>
                ) : null}
                <div className="flex justify-end">
                  <Button type="submit" disabled={pending}>
                    {pending ? 'Publishing...' : 'Publish discussion'}
                  </Button>
                </div>
              </form>
            )}
          </DialogContent>
        </Dialog>
      </header>

      {discussions.length === 0 ? (
        <Card>
          <CardContent className="flex min-h-56 flex-col items-center justify-center text-center">
            <MessagesSquare className="size-9 text-muted-foreground" />
            <h2 className="mt-4 font-semibold">No discussions yet</h2>
            <p className="mt-2 text-sm text-muted-foreground">
              Start the first conversation for this course.
            </p>
          </CardContent>
        </Card>
      ) : (
        <div className="divide-y border-y">
          {discussions.map((discussion) => (
            <article key={discussion.id} className="px-3 py-5">
              <div className="flex flex-wrap items-center gap-2">
                <h2 className="font-semibold">{discussion.title || 'Course discussion'}</h2>
                {discussion.isPinned ? <Badge variant="secondary">Pinned</Badge> : null}
                {discussion.isResolved ? <Badge variant="outline">Resolved</Badge> : null}
              </div>
              <p className="mt-2 line-clamp-3 text-sm leading-6 text-muted-foreground">
                {discussion.content}
              </p>
              <div className="mt-4 flex flex-wrap items-center justify-between gap-3">
                <p className="inline-flex items-center gap-2 text-xs text-muted-foreground">
                  <MessageCircle className="size-3.5" />
                  {discussion.replyCount ?? 0} replies
                </p>
                <Link
                  href={`/learn/courses/${courseSlug}/community/${discussion.id}`}
                  className={cn(buttonVariants({ size: "sm", variant: "ghost" }))}
                >
                  Open discussion
                  <ArrowRight className="size-4" />
                </Link>
              </div>
            </article>
          ))}
        </div>
      )}
    </div>
  );
}

import { Link } from '@/i18n/navigation';
import type { CourseAttendanceData } from '@/lib/learner/courses';
import { Badge } from '@game-guild/ui/components/badge';
import { CheckCircle2, ChevronRight, Circle, Clock3, Lock } from 'lucide-react';

function statusIcon(status: string) {
  if (status === 'completed') return <CheckCircle2 className="size-4 text-emerald-500" />;
  if (status === 'locked') return <Lock className="size-4 text-muted-foreground" />;
  if (status === 'in-progress') return <Clock3 className="size-4 text-primary" />;
  return <Circle className="size-4 text-muted-foreground" />;
}

export function CourseContentOutline({ course }: { course: CourseAttendanceData }) {
  const courseHref = `/learn/courses/${course.slug}`;

  return (
    <div className="space-y-8">
      <header className="border-b pb-6">
        <p className="text-sm font-medium text-primary">{course.title}</p>
        <h1 className="mt-2 text-3xl font-semibold">Course content</h1>
        <p className="mt-2 max-w-2xl text-sm text-muted-foreground">
          Follow the published syllabus in order. Locked lessons become available when their
          prerequisites are complete.
        </p>
      </header>

      <div className="space-y-6">
        {course.modules.map((module, moduleIndex) => (
          <section key={module.id} aria-labelledby={`module-${module.id}`} className="border-y">
            <div className="flex flex-wrap items-center justify-between gap-3 bg-muted/30 px-4 py-4">
              <div>
                <p className="text-xs font-medium uppercase text-muted-foreground">
                  Module {moduleIndex + 1}
                </p>
                <h2 id={`module-${module.id}`} className="mt-1 font-semibold">
                  {module.title}
                </h2>
              </div>
              <Badge variant="outline">{module.progress}% complete</Badge>
            </div>

            <div className="divide-y">
              {module.items.map((item) => {
                const isActivity = item.type !== 'lesson';
                const isParticipatory = ['Discussion', 'Reflection', 'Survey'].includes(item.contentType || '');
                const href = !isActivity
                  ? `${courseHref}/lessons/${item.slug || item.id}`
                  : isParticipatory
                    ? `${courseHref}/activities/content-${item.slug || item.id}`
                    : `${courseHref}/activities`;
                const locked = item.status === 'locked';

                if (locked) {
                  return (
                    <div key={item.id} className="flex items-center gap-3 px-4 py-4 opacity-60">
                      {statusIcon(item.status)}
                      <div className="min-w-0 flex-1">
                        <p className="truncate text-sm font-medium">{item.title}</p>
                        <p className="mt-1 text-xs text-muted-foreground">Locked</p>
                      </div>
                    </div>
                  );
                }

                return (
                  <Link
                    key={item.id}
                    href={href}
                    className="flex items-center gap-3 px-4 py-4 transition-colors hover:bg-muted/40"
                  >
                    {statusIcon(item.status)}
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-sm font-medium">{item.title}</p>
                      <p className="mt-1 text-xs text-muted-foreground">
                        {isActivity ? item.type : 'Lesson'}
                        {item.duration ? ` · ${item.duration} min` : ''}
                      </p>
                    </div>
                    <ChevronRight className="size-4 text-muted-foreground" />
                  </Link>
                );
              })}
            </div>
          </section>
        ))}
      </div>
    </div>
  );
}

"use client";

import { cn } from "@game-guild/ui/lib/utils";
import { Link, useRouter } from "@/i18n/navigation";
import { createCourseDiscussionReply } from "@/lib/learner/activity-actions";
import type {
  LearningExperienceSocialServicesCourseDiscussion,
  LearningExperienceSocialServicesDiscussionReply,
} from "@game-guild/client";
import {
  Alert,
  AlertDescription,
  AlertTitle,
} from "@game-guild/ui/components/alert";
import { Badge } from "@game-guild/ui/components/badge";
import { Button, buttonVariants } from "@game-guild/ui/components/button";
import { Textarea } from "@game-guild/ui/components/textarea";
import {
  ArrowLeft,
  CheckCircle2,
  MessageCircle,
  Send,
  ThumbsUp,
} from "lucide-react";
import { type FormEvent, useState } from "react";

interface CourseDiscussionThreadProps {
  courseSlug: string;
  courseTitle: string;
  discussion: LearningExperienceSocialServicesCourseDiscussion;
  replies: LearningExperienceSocialServicesDiscussionReply[];
}

function formatDate(value?: string) {
  if (!value) return null;
  return new Intl.DateTimeFormat("en-US", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(new Date(value));
}

export function CourseDiscussionThread({
  courseSlug,
  courseTitle,
  discussion,
  replies,
}: CourseDiscussionThreadProps) {
  const router = useRouter();
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  async function handleReply(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = event.currentTarget;
    setPending(true);
    setError(null);
    setSuccess(false);
    const result = await createCourseDiscussionReply(new FormData(form));
    setPending(false);

    if (!result.success) {
      setError(result.error || "The reply could not be published.");
      return;
    }

    form.reset();
    setSuccess(true);
    router.refresh();
  }

  return (
    <div className="mx-auto w-full max-w-4xl space-y-8">
      <header className="space-y-5 border-b pb-6">
        <Link
          href={`/learn/courses/${courseSlug}/community`}
          className={cn(buttonVariants({ size: "sm", variant: "ghost" }))}
        >
          <ArrowLeft className="size-4" />
          Back to community
        </Link>
        <div>
          <p className="text-sm font-medium text-primary">{courseTitle}</p>
          <div className="mt-2 flex flex-wrap items-center gap-2">
            <h1 className="text-3xl font-semibold">
              {discussion.title || "Course discussion"}
            </h1>
            {discussion.isPinned ? (
              <Badge variant="secondary">Pinned</Badge>
            ) : null}
            {discussion.isResolved ? (
              <Badge variant="outline">Resolved</Badge>
            ) : null}
          </div>
          <p className="mt-3 text-sm text-muted-foreground">
            {formatDate(discussion.createdAt) || "Course conversation"}
            {" / "}
            {discussion.viewCount ?? 0} views
          </p>
        </div>
      </header>

      <article
        aria-label="Discussion message"
        className="border-l-2 border-primary pl-5"
      >
        <p className="whitespace-pre-wrap text-base leading-7">
          {discussion.content || "No discussion message was provided."}
        </p>
      </article>

      <section aria-labelledby="discussion-replies" className="space-y-4">
        <div className="flex items-center justify-between gap-3">
          <h2 id="discussion-replies" className="text-xl font-semibold">
            Replies
          </h2>
          <Badge variant="outline">
            <MessageCircle className="size-3" />
            {replies.length}
          </Badge>
        </div>

        {replies.length === 0 ? (
          <div className="flex min-h-32 items-center justify-center border-y text-center text-sm text-muted-foreground">
            No replies yet. Continue the conversation below.
          </div>
        ) : (
          <div className="divide-y border-y">
            {replies.map((reply) => (
              <article
                key={reply.id}
                className={
                  reply.parentReplyId ? "ml-8 py-5 pl-4 border-l" : "py-5"
                }
              >
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="text-sm font-medium">
                      Community member
                    </span>
                    {reply.isAcceptedAnswer ? (
                      <Badge variant="secondary">
                        <CheckCircle2 className="size-3" />
                        Accepted answer
                      </Badge>
                    ) : null}
                  </div>
                  <time className="text-xs text-muted-foreground">
                    {formatDate(reply.createdAt)}
                  </time>
                </div>
                <p className="mt-3 whitespace-pre-wrap text-sm leading-6">
                  {reply.content}
                </p>
                <p className="mt-3 inline-flex items-center gap-1 text-xs text-muted-foreground">
                  <ThumbsUp className="size-3" />
                  {reply.upvoteCount ?? 0} helpful
                </p>
              </article>
            ))}
          </div>
        )}
      </section>

      <section
        aria-labelledby="reply-heading"
        className="rounded-md border p-5"
      >
        <h2 id="reply-heading" className="font-semibold">
          Add a reply
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">
          Keep the response specific to this course conversation.
        </p>
        <form onSubmit={handleReply} className="mt-4 space-y-4">
          <input type="hidden" name="discussionId" value={discussion.id} />
          <input type="hidden" name="courseSlug" value={courseSlug} />
          <Textarea
            aria-label="Reply message"
            name="content"
            rows={6}
            required
            placeholder="Write your reply..."
          />
          {error ? (
            <Alert variant="destructive">
              <AlertTitle>Could not publish reply</AlertTitle>
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          ) : null}
          {success ? (
            <Alert>
              <CheckCircle2 className="size-4 text-emerald-600" />
              <AlertTitle>Reply published</AlertTitle>
              <AlertDescription>
                The conversation has been updated.
              </AlertDescription>
            </Alert>
          ) : null}
          <div className="flex justify-end">
            <Button type="submit" disabled={pending}>
              <Send className="size-4" />
              {pending ? "Publishing..." : "Publish reply"}
            </Button>
          </div>
        </form>
      </section>
    </div>
  );
}

"use client";

import { cn } from "@game-guild/ui/lib/utils";
import {
  submitAssessment,
  submitContentActivity,
} from "@/lib/learner/activity-actions";
import { getPreferredSubmissionModality } from "@/lib/learner/activity-contracts";
import { scoreUnitsToPoints } from "@/lib/learning/academic-values";
import type {
  LearningAssessmentsAssessment,
  LearningAssessmentsLearnerAssessmentSubmission,
  LearningCoursesProgramContentType,
  ProjectsProjectApiOutput,
} from "@game-guild/client";
import {
  Alert,
  AlertDescription,
  AlertTitle,
} from "@game-guild/ui/components/alert";
import { Badge } from "@game-guild/ui/components/badge";
import { Button, buttonVariants } from "@game-guild/ui/components/button";
import { Input } from "@game-guild/ui/components/input";

import { Textarea } from "@game-guild/ui/components/textarea";
import { CheckCircle2, Clock3, FolderKanban, Send, Upload } from "lucide-react";
import Link from "next/link";
import { useActionState, useState } from "react";

export type LearnerActivityDescriptor =
  | {
      kind: "assessment";
      assessment: LearningAssessmentsAssessment;
      submission?: LearningAssessmentsLearnerAssessmentSubmission;
      projects?: ProjectsProjectApiOutput[];
    }
  | {
      kind: "content";
      contentId: string;
      contentType: Extract<
        LearningCoursesProgramContentType,
        "Discussion" | "Reflection" | "Survey"
      >;
      title: string;
      description?: string;
      completed?: boolean;
    };

function responseLabel(activity: LearnerActivityDescriptor, modality: string) {
  if (activity.kind === "content") {
    if (activity.contentType === "Reflection") return "Your reflection";
    if (activity.contentType === "Survey") return "Your response";
    return "Your contribution";
  }
  if (modality === "Code") return "Your code";
  if (modality === "Url" || modality === "Media") return "Submission URL";
  return "Your submission";
}

export function LearnerActivityForm({
  courseId,
  courseSlug,
  enrollmentId,
  activity,
}: {
  courseId: string;
  courseSlug: string;
  enrollmentId: string;
  activity: LearnerActivityDescriptor;
}) {
  const [response, setResponse] = useState("");
  const submitAction =
    activity.kind === "assessment" ? submitAssessment : submitContentActivity;
  const [submission, formAction, pending] = useActionState(submitAction, {
    success: false,
  });
  const modality =
    activity.kind === "assessment"
      ? getPreferredSubmissionModality(
          activity.assessment.type,
          activity.assessment.submissionModalities,
        )
      : "Text";
  const finalSubmission =
    activity.kind === "assessment" &&
    activity.submission &&
    activity.submission.status !== "InProgress"
      ? activity.submission
      : undefined;

  if (submission.success) {
    return (
      <Alert className="border-emerald-500/30 bg-emerald-500/10 text-emerald-100">
        <CheckCircle2 className="size-4" />
        <AlertTitle>Submission received</AlertTitle>
        <AlertDescription>
          Your response is stored in the course record. Grades and instructor
          feedback will appear here when available.
        </AlertDescription>
      </Alert>
    );
  }

  if (finalSubmission) {
    return (
      <div className="space-y-4 rounded-md border border-white/10 bg-white/[0.03] p-5">
        <div className="flex flex-wrap items-center gap-2">
          <Badge className="bg-emerald-500/15 text-emerald-300">
            {finalSubmission.status}
          </Badge>
          {finalSubmission.score != null ? (
            <strong className="text-lg text-white">
              {scoreUnitsToPoints(finalSubmission.score)} points
            </strong>
          ) : (
            <span className="text-sm text-muted-foreground">
              Awaiting grading
            </span>
          )}
        </div>
        {finalSubmission.feedback ? (
          <div className="border-l-2 border-primary pl-4">
            <p className="text-xs font-medium uppercase tracking-wide text-primary">
              Instructor feedback
            </p>
            <p className="mt-2 text-sm leading-6 text-foreground">
              {finalSubmission.feedback}
            </p>
          </div>
        ) : null}
      </div>
    );
  }

  if (activity.kind === "content" && activity.completed) {
    return (
      <Alert className="border-emerald-500/30 bg-emerald-500/10 text-emerald-100">
        <CheckCircle2 className="size-4" />
        <AlertTitle>Activity completed</AlertTitle>
        <AlertDescription>
          Your course response has already been submitted.
        </AlertDescription>
      </Alert>
    );
  }

  if (activity.kind === "assessment" && activity.assessment.type === "Quiz") {
    return (
      <Alert>
        <AlertTitle>Quiz attempt unavailable</AlertTitle>
        <AlertDescription>
          This quiz cannot be answered through the generic assessment form.
        </AlertDescription>
      </Alert>
    );
  }

  const label = responseLabel(activity, modality);
  const projects =
    activity.kind === "assessment" ? (activity.projects ?? []) : [];
  const contentKind =
    activity.kind === "content" ? activity.contentType.toLowerCase() : null;
  const projectSubmissionUnavailable =
    modality === "Project" && projects.length === 0;
  const projectsUrl = `${process.env.NEXT_PUBLIC_WEB_URL || "http://localhost:3000"}/projects`;

  return (
    <form action={formAction} className="space-y-5">
      {activity.kind === "assessment" ? (
        <>
          <input
            type="hidden"
            name="assessmentId"
            value={activity.assessment.id}
          />
          <input type="hidden" name="modality" value={modality} />
        </>
      ) : (
        <>
          <input type="hidden" name="courseId" value={courseId} />
          <input type="hidden" name="contentId" value={activity.contentId} />
          <input
            type="hidden"
            name="kind"
            value={activity.contentType.toLowerCase()}
          />
        </>
      )}
      <input type="hidden" name="enrollmentId" value={enrollmentId} />
      <input type="hidden" name="courseSlug" value={courseSlug} />

      {modality === "File" ? (
        <div className="space-y-2">
          <label
            htmlFor="activity-file"
            className="text-sm font-medium text-white"
          >
            Choose file
          </label>
          <Input
            id="activity-file"
            name="file"
            type="file"
            required
            className="border-white/10 bg-white/[0.03]"
          />
          <p className="text-xs text-muted-foreground">
            The file is stored privately and linked to this assessment attempt.
          </p>
        </div>
      ) : modality === "Project" && projects.length > 0 ? (
        <div className="space-y-2">
          <label
            htmlFor="project-response"
            className="text-sm font-medium text-white"
          >
            Project
          </label>
          <select
            id="project-response"
            name="response"
            required
            value={response}
            onChange={(event) => setResponse(event.target.value)}
            className="flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-xs outline-none transition-[color,box-shadow] focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 dark:bg-input/30"
          >
            <option value="" disabled>
              Choose one of your projects
            </option>
            {projects
              .filter((project) => project.id)
              .map((project) => (
                <option key={project.id} value={project.id!}>
                  {project.title || "Untitled project"}
                </option>
              ))}
          </select>
          <p className="text-xs text-muted-foreground">
            Only existing GameGuild projects can be attached.
          </p>
        </div>
      ) : projectSubmissionUnavailable ? (
        <div className="flex flex-col gap-4 border-y border-white/10 py-5 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex gap-3">
            <FolderKanban className="mt-0.5 size-5 shrink-0 text-primary" />
            <div>
              <p className="font-medium text-white">
                Create a project before submitting
              </p>
              <p className="mt-1 text-sm text-muted-foreground">
                Project assessments only accept projects owned by your GameGuild account.
              </p>
            </div>
          </div>
          <Link
            href={projectsUrl}
            className={cn(buttonVariants({ variant: "outline" }))}
          >
            Open projects
          </Link>
        </div>
      ) : modality === "Url" || modality === "Media" ? (
        <div className="space-y-2">
          <label
            htmlFor="activity-response"
            className="text-sm font-medium text-white"
          >
            {label}
          </label>
          <Input
            id="activity-response"
            name="response"
            type="url"
            required
            value={response}
            onChange={(event) => setResponse(event.target.value)}
            placeholder="https://"
          />
        </div>
      ) : (
        <div className="space-y-2">
          <label
            htmlFor="activity-response"
            className="text-sm font-medium text-white"
          >
            {label}
          </label>
          <Textarea
            id="activity-response"
            name="response"
            required
            rows={modality === "Code" ? 14 : 8}
            value={response}
            onChange={(event) => setResponse(event.target.value)}
            className={`border-white/10 bg-white/[0.03] ${modality === "Code" ? "font-mono" : ""}`}
            placeholder={
              contentKind === "discussion"
                ? "Add a constructive contribution to the course conversation."
                : "Write your response here."
            }
          />
        </div>
      )}

      {submission.error ? (
        <Alert variant="destructive">
          <AlertTitle>Submission failed</AlertTitle>
          <AlertDescription>{submission.error}</AlertDescription>
        </Alert>
      ) : null}
      <div className="flex flex-wrap items-center justify-between gap-3 border-t border-white/10 pt-4">
        <p className="inline-flex items-center gap-2 text-xs text-muted-foreground">
          <Clock3 className="size-3.5" />
          Submitting creates a timestamped course record.
        </p>
        <Button
          type="submit"
          disabled={pending || projectSubmissionUnavailable}
        >
          {modality === "File" ? (
            <Upload className="size-4" />
          ) : (
            <Send className="size-4" />
          )}
          {pending
            ? "Submitting..."
            : activity.kind === "assessment"
              ? "Submit assessment"
              : `Submit ${contentKind}`}
        </Button>
      </div>
    </form>
  );
}

'use client';

import { cn } from "@game-guild/ui/lib/utils";
import { AssetImage } from '@/components/block-content-editor/extras/media/asset-image';
import { getLearningAssetRepository } from '@/lib/learning/assets/learning-asset-repository';
import { recordLessonEvent } from '@/lib/learner/lesson-interaction-actions';
import { AssetsProvider, useResolvedAssetUrl } from '@game-guild/assets/react';
import type { LearningCoursesLessonContentFormat } from '@game-guild/client';
import { MarkdownRenderer } from '@game-guild/content-rendering';
import { Button, buttonVariants } from '@game-guild/ui/components/button';
import { ChevronLeft, ChevronRight, ExternalLink } from 'lucide-react';
import { lazy, Suspense, useRef, useState } from 'react';
import { defaultUrlTransform, type Components } from 'react-markdown';

type ContentRecord = Record<string, unknown>;

export function learningImageSource(source: string | Blob | undefined): string | undefined {
    return typeof source === 'string' ? source : undefined;
}

const ASSET_MARKDOWN_COMPONENTS: Components = {
    img: ({ src, alt, ...props }) => <AssetImage src={learningImageSource(src)} alt={alt} {...props} />,
};

export function learningUrlTransform(url: string): string {
    return url.startsWith('asset://') ? url : defaultUrlTransform(url);
}

function LessonMarkdown({ content }: { content: string }) {
    return <MarkdownRenderer content={content} components={ASSET_MARKDOWN_COMPONENTS} urlTransform={learningUrlTransform} />;
}

const LexicalLessonRenderer = lazy(async () => {
    const mod = await import('./lexical-lesson-renderer');
    return { default: mod.LexicalLessonRenderer };
});

export function asRecord(content: unknown): ContentRecord | null {
    if (content && typeof content === 'object' && !Array.isArray(content)) return content as ContentRecord;
    if (typeof content === 'string') {
        try { const parsed = JSON.parse(content) as unknown; return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed as ContentRecord : null; } catch { return null; }
    }
    return null;
}

export function textContent(content: unknown): string {
    if (typeof content === 'string') return content;
    const record = asRecord(content);
    if (!record) return '';
    for (const key of ['markdown', 'content', 'text', 'source']) {
        if (typeof record[key] === 'string') return record[key] as string;
    }
    return '';
}

export function videoSource(content: unknown): string {
    const record = asRecord(content);
    return typeof record?.videoUrl === 'string'
        ? record.videoUrl
        : typeof record?.url === 'string'
          ? record.url
          : typeof record?.src === 'string'
            ? record.src
            : textContent(content);
}

export function externalLinkSource(content: unknown): string {
    const record = asRecord(content);
    const candidate = typeof record?.url === 'string'
        ? record.url
        : typeof record?.href === 'string'
          ? record.href
          : typeof record?.src === 'string'
            ? record.src
            : textContent(content);
    try {
        const url = new URL(candidate);
        return url.protocol === 'http:' || url.protocol === 'https:' ? url.href : '';
    } catch {
        return '';
    }
}

function RevealRenderer({ content }: { content: unknown }) {
    const slides = textContent(content).split(/^\s*---\s*$/m).map((slide) => slide.trim()).filter(Boolean);
    const [index, setIndex] = useState(0);
    if (!slides.length) return <p className="text-sm text-muted-foreground">This presentation has no published slides.</p>;
    return <section aria-label="Slide presentation" className="bg-muted/30 p-6 sm:p-10">
        <div className="min-h-72"><LessonMarkdown content={slides[index]} /></div>
        <footer className="mt-6 flex items-center justify-between border-t pt-4">
            <Button variant="outline" size="icon" aria-label="Previous slide" disabled={index === 0} onClick={() => setIndex((value) => Math.max(0, value - 1))}><ChevronLeft /></Button>
            <span className="text-sm text-muted-foreground">{index + 1} / {slides.length}</span>
            <Button variant="outline" size="icon" aria-label="Next slide" disabled={index === slides.length - 1} onClick={() => setIndex((value) => Math.min(slides.length - 1, value + 1))}><ChevronRight /></Button>
        </footer>
    </section>;
}

function VideoRenderer({ courseId, enrollmentId, itemId, content }: { courseId: string; enrollmentId?: string; itemId: string; content: unknown }) {
    const src = videoSource(content);
    const { url: resolvedSrc, loading } = useResolvedAssetUrl(src);
    const lastHeartbeat = useRef(0);
    const send = (type: 'Opened' | 'Progressed' | 'Paused' | 'Completed', video: HTMLVideoElement) => {
        if (!enrollmentId) return;
        void recordLessonEvent({ courseId, enrollmentId, contentId: itemId, type, positionSeconds: Math.round(video.currentTime), durationSeconds: Number.isFinite(video.duration) ? Math.round(video.duration) : undefined, progressPercentage: Number.isFinite(video.duration) && video.duration > 0 ? Math.round((video.currentTime / video.duration) * 100) : undefined, idempotencyKey: crypto.randomUUID() });
    };
    if (!src) return <p className="text-sm text-muted-foreground">This video lesson has no published media.</p>;
    if (loading) return <div className="aspect-video w-full animate-pulse bg-muted" aria-label="Loading video" />;
    if (!resolvedSrc) return <p className="text-sm text-destructive">This lesson media is unavailable.</p>;
    return <video aria-label="Video lesson" controls preload="metadata" src={resolvedSrc} className="aspect-video w-full bg-black" onPlay={(event) => send('Opened', event.currentTarget)} onPause={(event) => send('Paused', event.currentTarget)} onEnded={(event) => send('Completed', event.currentTarget)} onTimeUpdate={(event) => { const second = Math.floor(event.currentTarget.currentTime); if (second - lastHeartbeat.current >= 15) { lastHeartbeat.current = second; send('Progressed', event.currentTarget); } }} />;
}

function HtmlRenderer({ content }: { content: unknown }) {
    const html = textContent(content);
    if (!html) return <p className="text-sm text-muted-foreground">This HTML lesson has no published content.</p>;
    return <iframe
        title="HTML lesson"
        sandbox=""
        referrerPolicy="no-referrer"
        srcDoc={html}
        className="min-h-[32rem] w-full border-0 bg-white"
    />;
}

function ExternalLinkRenderer({ content }: { content: unknown }) {
    const href = externalLinkSource(content);
    if (!href) return <p className="text-sm text-muted-foreground">This lesson resource link is unavailable.</p>;
    return <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      className={cn(buttonVariants({}))}
    >
      Open lesson resource
      <ExternalLink className="ml-2 h-4 w-4" />
    </a>;
}

export function LearnerLessonRenderer({ courseId, enrollmentId, itemId, format, content }: { courseId: string; enrollmentId?: string; itemId: string; format?: LearningCoursesLessonContentFormat; content: unknown }) {
    const assetRepository = getLearningAssetRepository();
    return <AssetsProvider repository={assetRepository} scope={{ type: 'ProgramContent', id: itemId }}>
        <LearnerLessonContent courseId={courseId} enrollmentId={enrollmentId} itemId={itemId} format={format} content={content} />
    </AssetsProvider>;
}

function LearnerLessonContent({ courseId, enrollmentId, itemId, format, content }: { courseId: string; enrollmentId?: string; itemId: string; format?: LearningCoursesLessonContentFormat; content: unknown }) {
    switch (format ?? 'Markdown') {
        case 'Lexical': return <Suspense fallback={<div className="min-h-32 animate-pulse rounded-md bg-muted" />}><LexicalLessonRenderer content={content} itemId={itemId} /></Suspense>;
        case 'RevealJs': return <RevealRenderer content={content} />;
        case 'Video': return <VideoRenderer courseId={courseId} enrollmentId={enrollmentId} itemId={itemId} content={content} />;
        case 'Html': return <HtmlRenderer content={content} />;
        case 'ExternalLink': return <ExternalLinkRenderer content={content} />;
        case 'Markdown':
        default: {
            const markdown = textContent(content);
            return markdown ? <LessonMarkdown content={markdown} /> : <p className="text-sm text-muted-foreground">This lesson has no published content.</p>;
        }
    }
}

