              <Field>
                <FieldLabel htmlFor="email">Email</FieldLabel>
                <Input
                  id="email"
                  name="email"
                  type="email"
                  placeholder="name@example.com"
                  autoComplete="email"
                  required
                  disabled={isLoading}
                  aria-invalid={!!fieldErrors.email}
                  onChange={() => fieldErrors.email && setFieldErrors((prev) => ({ ...prev, email: '' }))}
                />
