'use client';

import { reconcileMarketplaceStripeOrderAction, type MarketplaceActionResult } from '@/lib/marketplace/actions';
import { Elements, PaymentElement, useElements, useStripe } from '@stripe/react-stripe-js';
import { loadStripe } from '@stripe/stripe-js';
import { Button } from '@game-guild/ui/components/button';
import { useMemo, useState, type FormEvent } from 'react';
import { useTranslations } from 'next-intl';
import { MarketplaceActionNotice } from './marketplace-action-notice';

function StripeConfirmationForm({ locale, orderId }: { locale: string; orderId: string }) {
  const stripe = useStripe();
  const elements = useElements();
  const t = useTranslations('marketplace');
  const [pending, setPending] = useState(false);
  const [result, setResult] = useState<MarketplaceActionResult | null>(null);

  async function submit(event: FormEvent) {
    event.preventDefault();
    if (!stripe || !elements) return;
    setPending(true);
    const confirmation = await stripe.confirmPayment({
      elements,
      confirmParams: { return_url: `${window.location.origin}/${locale}/workspace/economy/orders/${orderId}` },
      redirect: 'if_required',
    });
    if (confirmation.error) {
      setResult({ success: false, message: confirmation.error.message ?? t('stripeConfirmationFailed') });
    } else {
      const paymentMethod = confirmation.paymentIntent?.payment_method;
      const paymentMethodId = typeof paymentMethod === 'string' ? paymentMethod : paymentMethod?.id;
      setResult(paymentMethodId
        ? await reconcileMarketplaceStripeOrderAction(orderId, paymentMethodId)
        : { success: true, message: t('stripeReconciliationPending') });
    }
    setPending(false);
  }

  return (
    <form onSubmit={submit} className="space-y-4 rounded-lg border p-4">
      <PaymentElement />
      <Button type="submit" disabled={!stripe || !elements || pending}>{t('confirmStripe')}</Button>
      <MarketplaceActionNotice result={result} />
    </form>
  );
}

export function StripePaymentElement({ clientSecret, locale, orderId, publishableKey }: {
  clientSecret: string;
  locale: string;
  orderId: string;
  publishableKey: string;
}) {
  const stripe = useMemo(() => loadStripe(publishableKey), [publishableKey]);
  return (
    <Elements stripe={stripe} options={{ clientSecret, appearance: { theme: 'stripe' } }}>
      <StripeConfirmationForm locale={locale} orderId={orderId} />
    </Elements>
  );
}

'use client';

import { type FormEvent, useState } from 'react';
import { useSession } from '@game-guild/client/react';
import { toast } from 'sonner';
import { Button } from '@game-guild/ui/components/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Checkbox } from '@game-guild/ui/components/checkbox';
import { Input } from '@game-guild/ui/components/input';
import { Label } from '@game-guild/ui/components/label';
import {
  changePasswordAction,
  type PasswordChangeActionResult,
} from '@/lib/auth/password-change-action';
import { Field, FieldDescription, FieldError, FieldGroup, FieldLabel } from '@game-guild/ui/components/field';
import { Loader2 } from 'lucide-react';
import { useTranslations } from 'next-intl';

/**
 * Password change card for the account settings page. Session refresh after
 * the server's TokenVersion bump goes through useSession().update() — this
 * component must never call signIn.
 */
export function PasswordCard() {
  const t = useTranslations('passwordChange');
  const { update } = useSession();
  const [pending, setPending] = useState(false);
  const [mismatch, setMismatch] = useState(false);

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const currentPassword = (formData.get('currentPassword') as string) ?? '';
    const newPassword = (formData.get('newPassword') as string) ?? '';
    const confirmPassword = (formData.get('confirmPassword') as string) ?? '';
    const revokeOtherSessions = formData.get('revokeOtherSessions') === 'on';
    const form = e.currentTarget;

    if (newPassword !== confirmPassword) {
      setMismatch(true);
      return;
    }
    setMismatch(false);
    setPending(true);

    let result: PasswordChangeActionResult;
    try {
      result = await changePasswordAction({
        currentPassword,
        newPassword,
        confirmPassword,
        revokeOtherSessions,
      });
    } catch {
      result = { success: false, status: 'error' };
    } finally {
      setPending(false);
    }

    if (result.success) {
      toast.success(t('success'));
      form.reset();
      await update();
      return;
    }

    switch (result.status) {
      case 'wrongCurrent':
        toast.error(result.message ?? t('errors.wrongCurrent'));
        break;
      case 'weakPassword':
        toast.error(result.message ?? t('errors.weakPassword'));
        break;
      case 'unauthorized':
      case 'error':
        toast.error(t('errors.generic'));
        break;
    }
  }

  return (
    <Card data-testid="password-card">
      <CardHeader>
        <CardTitle>{t('title')}</CardTitle>
        <CardDescription>{t('description')}</CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} noValidate>
          <FieldGroup>
            <Field>
              <FieldLabel htmlFor="currentPassword">{t('currentLabel')}</FieldLabel>
              <Input
                id="currentPassword"
                name="currentPassword"
                type="password"
                autoComplete="current-password"
                disabled={pending}
              />
              <FieldDescription>{t('currentHelp')}</FieldDescription>
            </Field>
            <Field>
              <FieldLabel htmlFor="newPassword">{t('newLabel')}</FieldLabel>
              <Input
                id="newPassword"
                name="newPassword"
                type="password"
                autoComplete="new-password"
                required
                disabled={pending}
                aria-invalid={mismatch}
                onChange={() => mismatch && setMismatch(false)}
              />
              <FieldDescription>{t('hintLine')}</FieldDescription>
            </Field>
            <Field>
              <FieldLabel htmlFor="confirmPassword">{t('confirmLabel')}</FieldLabel>
              <Input
                id="confirmPassword"
                name="confirmPassword"
                type="password"
                autoComplete="new-password"
                required
                disabled={pending}
                aria-invalid={mismatch}
                onChange={() => mismatch && setMismatch(false)}
              />
              {mismatch && <FieldError>{t('errors.mismatch')}</FieldError>}
            </Field>
            <Field>
              <div className="flex items-center gap-2">
                <Checkbox id="revokeOtherSessions" name="revokeOtherSessions" defaultChecked disabled={pending} />
                <Label htmlFor="revokeOtherSessions" className="font-normal">
                  {t('revokeLabel')}
                </Label>
              </div>
            </Field>
            <Field>
              <Button type="submit" disabled={pending}>
                {pending ? <Loader2 className="size-4 animate-spin" /> : null}
                {t('submit')}
              </Button>
            </Field>
          </FieldGroup>
        </form>
      </CardContent>
    </Card>
  );
}

'use client';

import { cn } from "@game-guild/ui/lib/utils";
import { type FormEvent, useState } from 'react';
import Link from 'next/link';
import { Button, buttonVariants } from '@game-guild/ui/components/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@game-guild/ui/components/card';
import { Field, FieldDescription, FieldError, FieldGroup, FieldLabel } from '@game-guild/ui/components/field';
import { Input } from '@game-guild/ui/components/input';
import { TurnstileWidget } from '@/components/antibot/turnstile-widget';

type ActionResult = { success: true; data: void } | { success: false; error: string };

interface ResetPasswordFormProps {
  token: string;
  onReset: (token: string, newPassword: string, confirmPassword: string, turnstileToken?: string | null) => Promise<ActionResult>;
}

export function ResetPasswordForm({ token, onReset }: ResetPasswordFormProps) {
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isComplete, setIsComplete] = useState(false);
  const [turnstileToken, setTurnstileToken] = useState<string | null>(null);

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(null);
    setIsLoading(true);

    try {
      const result = await onReset(token, newPassword, confirmPassword, turnstileToken);
      if (!result.success) {
        // Single-use token: reset on failure so the widget re-issues a fresh one.
        setTurnstileToken(null);
        setError(result.error);
        return;
      }
      setIsComplete(true);
    } finally {
      setIsLoading(false);
    }
  }

  if (isComplete) {
    return (
      <Card>
        <CardHeader className="text-center">
          <CardTitle>Password updated</CardTitle>
          <CardDescription>You can now sign in and review your workspace invitations.</CardDescription>
        </CardHeader>
        <CardContent>
          <Link
            href="/sign-in?callbackUrl=/invitations"
            className={cn(buttonVariants({ className: "w-full" }))}
          >
            Continue to sign in
          </Link>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader className="text-center">
        <CardTitle>Choose a new password</CardTitle>
        <CardDescription>Use at least 8 characters for your GameGuild account.</CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} noValidate>
          <FieldGroup>
            <Field>
              <FieldLabel htmlFor="new-password">New password</FieldLabel>
              <Input id="new-password" type="password" autoComplete="new-password" required minLength={8} disabled={isLoading} value={newPassword} onChange={(event) => setNewPassword(event.target.value)} />
            </Field>
            <Field>
              <FieldLabel htmlFor="confirm-password">Confirm password</FieldLabel>
              <Input id="confirm-password" type="password" autoComplete="new-password" required minLength={8} disabled={isLoading} value={confirmPassword} onChange={(event) => setConfirmPassword(event.target.value)} aria-invalid={Boolean(error)} />
              {error ? <FieldError>{error}</FieldError> : null}
            </Field>
            <Field>
              <TurnstileWidget onToken={setTurnstileToken} action="reset-password" id="reset-password-turnstile" />
              <Button type="submit" disabled={isLoading || !token}>
                {isLoading ? 'Updating...' : 'Update password'}
              </Button>
              {!token ? <FieldError>This reset link is missing its security token.</FieldError> : null}
              <FieldDescription className="text-center"><Link href="/forgot-password">Request a new link</Link></FieldDescription>
            </Field>
          </FieldGroup>
        </form>
      </CardContent>
    </Card>
  );
}

'use client';

import { updateAccessibilityPreferenceAction } from '@/lib/user-settings/actions';
import { applyAccessibilityPreferences } from '@/components/settings/accessibility-sync-initializer';
import {
  MAX_FONT_SIZE,
  MIN_FONT_SIZE,
  type AccessibilityPreferenceData,
} from '@/lib/user-settings/preferences-mappers';
import { Field, FieldDescription, FieldGroup, FieldLabel } from '@game-guild/ui/components/field';
import { Label } from '@game-guild/ui/components/label';
import { Slider } from '@game-guild/ui/components/slider';
import { Switch } from '@game-guild/ui/components/switch';
import { useTranslations } from 'next-intl';
import * as React from 'react';
import { toast } from 'sonner';

interface AccessibilityFormProps {
  defaultValues: AccessibilityPreferenceData;
}

interface ToggleRowProps {
  id: string;
  label: string;
  description: string;
  checked: boolean;
  disabled: boolean;
  onCheckedChange: (checked: boolean) => void;
}

function ToggleRow({
  id,
  label,
  description,
  checked,
  disabled,
  onCheckedChange,
}: ToggleRowProps) {
  return (
    <div className="flex items-start justify-between gap-4 rounded-lg border p-4">
      <div className="min-w-0">
        <Label htmlFor={id} className="text-sm font-medium">
          {label}
        </Label>
        <p className="mt-1 text-xs text-muted-foreground">{description}</p>
      </div>
      <Switch
        id={id}
        checked={checked}
        disabled={disabled}
        onCheckedChange={onCheckedChange}
        aria-label={label}
      />
    </div>
  );
}

export function AccessibilityForm({ defaultValues }: AccessibilityFormProps) {
  const t = useTranslations('settings.accessibility');
  const [values, setValues] = React.useState<AccessibilityPreferenceData>(defaultValues);
  const [isPending, startTransition] = React.useTransition();

  function persist(next: AccessibilityPreferenceData) {
    setValues(next);
    applyAccessibilityPreferences(next);
    startTransition(async () => {
      const result = await updateAccessibilityPreferenceAction(next);
      if (!result.success) {
        applyAccessibilityPreferences(values);
        toast.error(t('saveFailed'), { description: result.error });
      }
    });
  }

  function update<K extends keyof AccessibilityPreferenceData>(
    key: K,
    value: AccessibilityPreferenceData[K],
  ) {
    persist({ ...values, [key]: value });
  }

  const fontSize = Math.min(MAX_FONT_SIZE, Math.max(MIN_FONT_SIZE, values.fontSize));

  return (
    <FieldGroup>
      <Field>
        <FieldLabel>{t('displayLabel')}</FieldLabel>
        <div className="flex flex-col gap-3">
          <ToggleRow
            id="accessibility-high-contrast"
            label={t('highContrast.label')}
            description={t('highContrast.description')}
            checked={values.highContrast}
            disabled={isPending}
            onCheckedChange={(checked) => update('highContrast', checked)}
          />
          <ToggleRow
            id="accessibility-large-text"
            label={t('largeText.label')}
            description={t('largeText.description')}
            checked={values.largeText}
            disabled={isPending}
            onCheckedChange={(checked) => update('largeText', checked)}
          />
          <ToggleRow
            id="accessibility-reduced-motion"
            label={t('reducedMotion.label')}
            description={t('reducedMotion.description')}
            checked={values.reducedMotion}
            disabled={isPending}
            onCheckedChange={(checked) => update('reducedMotion', checked)}
          />
        </div>
      </Field>

      <Field>
        <FieldLabel htmlFor="accessibility-font-size">
          {t('fontSize.label')} <span aria-hidden="true">({fontSize}px)</span>
        </FieldLabel>
        <Slider
          id="accessibility-font-size"
          min={MIN_FONT_SIZE}
          max={MAX_FONT_SIZE}
          step={1}
          value={fontSize}
          onValueChange={(value) => update('fontSize', Array.isArray(value) ? value[0] ?? fontSize : value)}
          disabled={isPending}
          aria-label={t('fontSize.label')}
        />
        <FieldDescription>
          {t('fontSize.description', { min: MIN_FONT_SIZE, max: MAX_FONT_SIZE })}
        </FieldDescription>
      </Field>
    </FieldGroup>
  );
}

'use client';

import { setPreferredLocaleCookie } from '@/i18n/locale-detection';
import { updateLocalizationPreferenceAction } from '@/lib/user-settings/actions';
import { usePathname, useRouter } from '@/i18n/navigation';
import type { LocalizationPreferenceData } from '@/lib/user-settings/preferences-mappers';
import { Button } from '@game-guild/ui/components/button';
import {
  Field,
  FieldDescription,
  FieldGroup,
  FieldLabel,
} from '@game-guild/ui/components/field';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@game-guild/ui/components/select';
import { Save } from 'lucide-react';
import { useTranslations } from 'next-intl';
import * as React from 'react';
import { toast } from 'sonner';

const LANGUAGE_OPTIONS = [
  { value: 'en-US', label: 'English (United States)' },
  { value: 'pt-BR', label: 'Português (Brasil)' },
] as const;

const DATE_FORMAT_OPTIONS = ['MM/dd/yyyy', 'dd/MM/yyyy', 'yyyy-MM-dd'] as const;

const TIME_FORMAT_OPTIONS = [
  { value: '12h', label: '12-hour' },
  { value: '24h', label: '24-hour' },
] as const;

const CURRENCY_OPTIONS = ['USD', 'EUR', 'BRL', 'GBP', 'CAD', 'JPY'] as const;

const FALLBACK_TIMEZONES = [
  'UTC',
  'America/Sao_Paulo',
  'America/New_York',
  'America/Chicago',
  'America/Los_Angeles',
  'Europe/London',
  'Europe/Berlin',
  'Europe/Lisbon',
  'Asia/Tokyo',
] as const;

function getTimezoneOptions(): readonly string[] {
  try {
    const supported = Intl.supportedValuesOf('timeZone');
    return supported.length > 0 ? supported : FALLBACK_TIMEZONES;
  } catch {
    return FALLBACK_TIMEZONES;
  }
}

interface LocalizationFormProps {
  defaultValues: LocalizationPreferenceData;
}

export function LocalizationForm({ defaultValues }: LocalizationFormProps) {
  const t = useTranslations('settings.localization');
  const pathname = usePathname();
  const router = useRouter();
  const [values, setValues] = React.useState<LocalizationPreferenceData>(defaultValues);
  const [isPending, startTransition] = React.useTransition();

  // The timezone list is environment-dependent; regenerate on mount so the
  // user's current value is always selectable even if it isn't in the
  // fallback list.
  const timezoneOptions = React.useMemo(getTimezoneOptions, []);
  const timezoneSelectable =
    values.timezone === 'UTC' || timezoneOptions.includes(values.timezone);

  function update<K extends keyof LocalizationPreferenceData>(
    key: K,
    value: LocalizationPreferenceData[K],
  ) {
    setValues((prev) => ({ ...prev, [key]: value }));
  }

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    startTransition(async () => {
      const result = await updateLocalizationPreferenceAction(values);
      if (result.success) {
        toast.success(t('saved'));
        if (values.language === 'en-US' || values.language === 'pt-BR') {
          // Persist the explicit choice before navigating (issues #92/#99):
          // the proxy's automatic locale detection reads this cookie and
          // must not bounce the visitor back to their browser locale once
          // they deliberately picked a language. Without it, switching to
          // the unprefixed default locale loses the choice on reload.
          setPreferredLocaleCookie(values.language);
          router.replace(pathname, { locale: values.language });
        }
      } else {
        toast.error(t('saveFailed'), { description: result.error });
      }
    });
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <FieldGroup>
        <Field>
          <FieldLabel htmlFor="localization-language">{t('language')}</FieldLabel>
          <Select
            value={values.language}
            onValueChange={(value) => update('language', value ?? '')}
            disabled={isPending}
          >
            <SelectTrigger id="localization-language" className="w-full sm:max-w-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {LANGUAGE_OPTIONS.map((option) => (
                <SelectItem key={option.value} value={option.value}>
                  {option.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Field>

        <Field>
          <FieldLabel htmlFor="localization-timezone">{t('timezone')}</FieldLabel>
          <Select
            value={values.timezone}
            onValueChange={(value) => update('timezone', value ?? '')}
            disabled={isPending}
          >
            <SelectTrigger id="localization-timezone" className="w-full sm:max-w-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent className="max-h-72">
              {!timezoneSelectable && (
                <SelectItem value={values.timezone}>{values.timezone}</SelectItem>
              )}
              {timezoneOptions.map((zone) => (
                <SelectItem key={zone} value={zone}>
                  {zone}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Field>

        <div className="grid gap-6 sm:grid-cols-2">
          <Field>
            <FieldLabel htmlFor="localization-date-format">{t('dateFormat')}</FieldLabel>
            <Select
              value={values.dateFormat}
              onValueChange={(value) => update('dateFormat', value ?? '')}
              disabled={isPending}
            >
              <SelectTrigger id="localization-date-format" className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {DATE_FORMAT_OPTIONS.map((format) => (
                  <SelectItem key={format} value={format}>
                    {format}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </Field>

          <Field>
            <FieldLabel htmlFor="localization-time-format">{t('timeFormat')}</FieldLabel>
            <Select
              value={values.timeFormat}
              onValueChange={(value) => update('timeFormat', value ?? '')}
              disabled={isPending}
            >
              <SelectTrigger id="localization-time-format" className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {TIME_FORMAT_OPTIONS.map((option) => (
                  <SelectItem key={option.value} value={option.value}>
                    {option.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </Field>
        </div>

        <Field>
          <FieldLabel htmlFor="localization-currency">{t('currency')}</FieldLabel>
          <Select
            value={values.currency}
            onValueChange={(value) => update('currency', value ?? '')}
            disabled={isPending}
          >
            <SelectTrigger id="localization-currency" className="w-full sm:max-w-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {CURRENCY_OPTIONS.map((code) => (
                <SelectItem key={code} value={code}>
                  {code}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <FieldDescription>{t('currencyDescription')}</FieldDescription>
        </Field>

        <Field>
          <Button type="submit" disabled={isPending}>
            <Save className="size-4" />
            {isPending ? t('saving') : t('save')}
          </Button>
        </Field>
      </FieldGroup>
    </form>
  );
}

'use client';

import {
  completeSmsEnrollmentAction,
  completeTotpEnrollmentAction,
  disableMfaAction,
  regenerateBackupCodesAction,
  startSmsEnrollmentAction,
  startTotpEnrollmentAction,
  type MfaPageData,
} from '@/lib/auth/mfa-actions';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@game-guild/ui/components/card';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@game-guild/ui/components/alert-dialog';
import { Input } from '@game-guild/ui/components/input';
import { Label } from '@game-guild/ui/components/label';
import { KeyRound, MessageSquare, ShieldCheck, Smartphone } from 'lucide-react';
import { useTranslations } from 'next-intl';
import * as React from 'react';
import { toast } from 'sonner';

/**
 * MFA method-management surface (settings/security, issue #244): enrolled-method list with
 * add flows for the authenticator app and SMS, recovery-code status with one-time
 * regenerate view, and password-verified disable. All mutations go through server actions
 * (mfa-actions.ts); revalidatePath refreshes the server-rendered data after each action.
 */

type MethodState =
  | { kind: 'idle' }
  | { kind: 'totp-active'; secretKey: string; qrCodeUri: string }
  | { kind: 'sms-active'; maskedPhone: string };

export function MfaMethodsManager({ data }: { data: MfaPageData }) {
  const t = useTranslations('settings.security.mfa');
  const tShared = useTranslations('settings.security');
  const [methodState, setMethodState] = React.useState<MethodState>({ kind: 'idle' });
  const [code, setCode] = React.useState('');
  const [phone, setPhone] = React.useState('');
  const [password, setPassword] = React.useState('');
  const [disableOpen, setDisableOpen] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const [freshCodes, setFreshCodes] = React.useState<string[] | null>(null);

  const configuration = data.configuration;
  const isEnabled = configuration?.isEnabled === true;
  const methods = data.methods?.methods ?? [];
  const backupCodes = data.backupCodes;

  const totp = methods.find((m) => m.method === 'Totp');
  const sms = methods.find((m) => m.method === 'Sms');
  const backupCode = methods.find((m) => m.method === 'BackupCode');

  const reportFailure = (message?: string) => {
    toast.error(message ?? tShared('actionFailed'));
  };

  async function handleStartTotp() {
    setBusy(true);
    try {
      const result = await startTotpEnrollmentAction();
      if (result.success && result.setup?.secretKey) {
        setMethodState({ kind: 'totp-active', secretKey: result.setup.secretKey, qrCodeUri: result.setup.qrCodeUri ?? '' });
        setCode('');
        toast.success(t('totp.started'));
      } else {
        reportFailure(result.message);
      }
    } finally {
      setBusy(false);
    }
  }

  async function handleCompleteTotp() {
    if (methodState.kind !== 'totp-active') {
      return;
    }
    setBusy(true);
    try {
      const result = await completeTotpEnrollmentAction(code, methodState.secretKey);
      if (result.success) {
        setMethodState({ kind: 'idle' });
        setCode('');
        toast.success(t('totp.completed'));
      } else {
        reportFailure(result.message);
      }
    } finally {
      setBusy(false);
    }
  }

  async function handleStartSms() {
    setBusy(true);
    try {
      const result = await startSmsEnrollmentAction(phone);
      if (result.success && result.smsSetup) {
        setMethodState({ kind: 'sms-active', maskedPhone: result.smsSetup.phoneNumberMasked ?? phone });
        setCode('');
        toast.success(t('sms.sent', { phone: result.smsSetup.phoneNumberMasked ?? '' }));
      } else {
        reportFailure(result.message);
      }
    } finally {
      setBusy(false);
    }
  }

  async function handleCompleteSms() {
    setBusy(true);
    try {
      const result = await completeSmsEnrollmentAction(code);
      if (result.success) {
        setMethodState({ kind: 'idle' });
        setCode('');
        setPhone('');
        toast.success(t('sms.completed'));
      } else {
        reportFailure(result.message);
      }
    } finally {
      setBusy(false);
    }
  }

  async function handleRegenerate() {
    setBusy(true);
    try {
      const result = await regenerateBackupCodesAction();
      if (result.success) {
        setFreshCodes(result.codes ?? []);
        toast.success(t('recovery.regenerated'));
      } else {
        reportFailure(result.message);
      }
    } finally {
      setBusy(false);
    }
  }

  async function handleDisable() {
    setBusy(true);
    try {
      const result = await disableMfaAction(password);
      if (result.success) {
        setDisableOpen(false);
        setPassword('');
        setMethodState({ kind: 'idle' });
        toast.success(t('disable.success'));
      } else {
        reportFailure(result.message ?? t('disable.wrongPassword'));
      }
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <ShieldCheck className="size-5" aria-hidden />
            {t('title')}
          </CardTitle>
          <CardDescription>{t('description')}</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium">{t('status.label')}</p>
              <p className="text-muted-foreground text-sm">
                {isEnabled ? t('status.enabled', { date: configuration?.enabledAt ?? '' }) : t('status.disabled')}
              </p>
            </div>
            <Badge variant={isEnabled ? 'default' : 'secondary'} data-testid="mfa-status-badge">
              {isEnabled ? t('status.badgeEnabled') : t('status.badgeDisabled')}
            </Badge>
          </div>

          <ul className="divide-y rounded-lg border" data-testid="mfa-method-list">
            {methods.map((method) => (
              <li key={method.method} className="flex items-center justify-between gap-4 p-4">
                <div className="flex items-start gap-3">
                  {method.method === 'Totp' ? (
                    <KeyRound className="text-muted-foreground mt-0.5 size-5" aria-hidden />
                  ) : method.method === 'Sms' ? (
                    <MessageSquare className="text-muted-foreground mt-0.5 size-5" aria-hidden />
                  ) : (
                    <Smartphone className="text-muted-foreground mt-0.5 size-5" aria-hidden />
                  )}
                  <div>
                    <p className="text-sm font-medium">{method.name}</p>
                    <p className="text-muted-foreground text-sm">{method.description}</p>
                    {!method.isAvailable && method.method === 'Sms' ? <p className="text-muted-foreground text-xs">{t('sms.unavailable')}</p> : null}
                  </div>
                </div>
                <Badge variant={method.isEnabled ? 'default' : 'outline'}>
                  {method.isEnabled ? t('methods.enrolled') : method.isAvailable ? t('methods.available') : t('methods.unavailable')}
                </Badge>
              </li>
            ))}
          </ul>

          <div className="flex flex-wrap gap-2">
            {!totp?.isEnabled && (
              <Button onClick={() => void handleStartTotp()} disabled={busy} data-testid="mfa-totp-start">
                {t('totp.start')}
              </Button>
            )}
            {!sms?.isEnabled && sms?.isAvailable && methodState.kind !== 'sms-active' && (
              <Button variant="outline" onClick={() => setMethodState({ kind: 'sms-active', maskedPhone: '' })} disabled={busy} data-testid="mfa-sms-start">
                {t('sms.start')}
              </Button>
            )}
            {isEnabled && (
              <Button variant="destructive" onClick={() => setDisableOpen(true)} disabled={busy} data-testid="mfa-disable">
                {t('disable.title')}
              </Button>
            )}
          </div>

          {methodState.kind === 'totp-active' && (
            <div className="space-y-3 rounded-lg border p-4" data-testid="mfa-totp-panel">
              <p className="text-sm">{t('totp.scan')}</p>
              <p className="break-all rounded bg-muted p-2 font-mono text-xs" data-testid="mfa-totp-secret">
                {methodState.secretKey}
              </p>
              {methodState.qrCodeUri ? (
                <p className="break-all text-muted-foreground text-xs">{methodState.qrCodeUri}</p>
              ) : null}
              <div className="grid gap-2">
                <Label htmlFor="mfa-totp-code">{t('totp.codeLabel')}</Label>
                <Input
                  id="mfa-totp-code"
                  value={code}
                  onChange={(event) => setCode(event.target.value)}
                  inputMode="numeric"
                  autoComplete="one-time-code"
                  placeholder="123456"
                />
              </div>
              <div className="flex gap-2">
                <Button onClick={() => void handleCompleteTotp()} disabled={busy || code.length < 6}>
                  {t('totp.complete')}
                </Button>
                <Button variant="ghost" onClick={() => setMethodState({ kind: 'idle' })} disabled={busy}>
                  {t('methods.cancel')}
                </Button>
              </div>
            </div>
          )}

          {methodState.kind === 'sms-active' && (
            <div className="space-y-3 rounded-lg border p-4" data-testid="mfa-sms-panel">
              <div className="grid gap-2">
                <Label htmlFor="mfa-sms-phone">{t('sms.phoneLabel')}</Label>
                <Input
                  id="mfa-sms-phone"
                  value={phone}
                  onChange={(event) => setPhone(event.target.value)}
                  inputMode="tel"
                  placeholder="+15551234567"
                />
              </div>
              <div className="flex gap-2">
                <Button onClick={() => void handleStartSms()} disabled={busy || phone.trim().length < 9}>
                  {t('sms.send')}
                </Button>
                <Button variant="ghost" onClick={() => setMethodState({ kind: 'idle' })} disabled={busy}>
                  {t('methods.cancel')}
                </Button>
              </div>
              {methodState.maskedPhone ? (
                <div className="grid gap-2">
                  <Label htmlFor="mfa-sms-code">{t('sms.codeLabel')}</Label>
                  <Input
                    id="mfa-sms-code"
                    value={code}
                    onChange={(event) => setCode(event.target.value)}
                    inputMode="numeric"
                    autoComplete="one-time-code"
                    placeholder="123456"
                  />
                  <Button onClick={() => void handleCompleteSms()} disabled={busy || code.length < 6}>
                    {t('sms.complete')}
                  </Button>
                </div>
              ) : null}
            </div>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <KeyRound className="size-5" aria-hidden />
            {t('recovery.title')}
          </CardTitle>
          <CardDescription>{t('recovery.description')}</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {backupCodes?.hasBackupCodes ? (
            <p className="text-muted-foreground text-sm" data-testid="mfa-recovery-status">
              {t('recovery.remaining', { remaining: backupCodes.remainingCount, total: backupCodes.totalCount })}
            </p>
          ) : (
            <p className="text-muted-foreground text-sm">{t('recovery.none')}</p>
          )}

          {freshCodes ? (
            <div className="space-y-2 rounded-lg border p-4" data-testid="mfa-recovery-codes">
              <p className="text-sm font-medium">{t('recovery.freshWarning')}</p>
              <div className="grid grid-cols-2 gap-1 font-mono text-sm sm:grid-cols-3">
                {freshCodes.map((recoveryCode) => (
                  <span key={recoveryCode}>{recoveryCode}</span>
                ))}
              </div>
              <Button variant="outline" onClick={() => setFreshCodes(null)}>
                {t('recovery.hide')}
              </Button>
            </div>
          ) : (
            <Button variant="outline" onClick={() => void handleRegenerate()} disabled={busy} data-testid="mfa-recovery-regenerate">
              {backupCode?.isEnabled ? t('recovery.regenerate') : t('recovery.generate')}
            </Button>
          )}
        </CardContent>
      </Card>

      <AlertDialog open={disableOpen} onOpenChange={setDisableOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{t('disable.title')}</AlertDialogTitle>
            <AlertDialogDescription>{t('disable.description')}</AlertDialogDescription>
          </AlertDialogHeader>
          <div className="grid gap-2">
            <Label htmlFor="mfa-disable-password">{t('disable.passwordLabel')}</Label>
            <Input
              id="mfa-disable-password"
              type="password"
              value={password}
              onChange={(event) => setPassword(event.target.value)}
              autoComplete="current-password"
            />
          </div>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => setPassword('')}>{t('disable.cancel')}</AlertDialogCancel>
            <AlertDialogAction onClick={() => void handleDisable()} disabled={busy || password.length === 0} data-testid="mfa-disable-confirm">
              {t('disable.confirm')}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

'use client';

import {
  updateProfileAction,
  updateProfileVisibilityAction,
  type ProfileFormInput,
  type ProfileVisibilitySetting,
} from '@/lib/user-settings/actions';
import { Link } from '@/i18n/navigation';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@game-guild/ui/components/avatar';
import { Button } from '@game-guild/ui/components/button';
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@game-guild/ui/components/card';
import {
  Field,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLabel,
} from '@game-guild/ui/components/field';
import { Input } from '@game-guild/ui/components/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@game-guild/ui/components/select';
import { Separator } from '@game-guild/ui/components/separator';
import { Textarea } from '@game-guild/ui/components/textarea';
import { Eye, ExternalLink, ImagePlus, Link2, Save, UserRound } from 'lucide-react';
import { useTranslations } from 'next-intl';
import { useRouter } from 'next/navigation';
import * as React from 'react';
import { toast } from 'sonner';

interface ProfileFormProps {
  defaultValues: ProfileFormInput;
  accountName: string;
  accountEmail: string;
  defaultVisibility: ProfileVisibilitySetting | null;
  hasCommunityProfile: boolean;
  publicProfilePath: string;
}

type FieldName = keyof ProfileFormInput;
type FieldErrors = Partial<Record<FieldName, string>>;

const FIELD_LIMITS = {
  handle: 80,
  displayName: 100,
  bio: 1000,
  location: 100,
  website: 255,
  jobTitle: 100,
  company: 100,
  avatarUrl: 500,
  bannerUrl: 500,
} as const;

const URL_FIELDS = ['website', 'avatarUrl', 'bannerUrl'] as const;

const VISIBILITY_VALUES = ['public', 'members', 'private'] as const;

function formText(formData: FormData, field: FieldName): string {
  const value = formData.get(field);
  return typeof value === 'string' ? value : '';
}

function isHttpUrl(value: string): boolean {
  try {
    const url = new URL(value);
    return url.protocol === 'http:' || url.protocol === 'https:';
  } catch {
    return false;
  }
}

function handleInitials(name: string) {
  return name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]).join('').toUpperCase();
}

export function ProfileForm({
  defaultValues,
  accountName,
  accountEmail,
  defaultVisibility,
  hasCommunityProfile,
  publicProfilePath,
}: ProfileFormProps) {
  const t = useTranslations('settings.profile');
  const router = useRouter();
  const [fieldErrors, setFieldErrors] = React.useState<FieldErrors>({});
  const [bioLength, setBioLength] = React.useState(defaultValues.bio.length);
  const [isPending, startTransition] = React.useTransition();
  const [visibility, setVisibility] = React.useState<ProfileVisibilitySetting | null>(defaultVisibility);
  const [isVisibilityPending, startVisibilityTransition] = React.useTransition();

  function clearFieldError(field: FieldName) {
    setFieldErrors((prev) => {
      if (!prev[field]) return prev;
      const next = { ...prev };
      delete next[field];
      return next;
    });
  }

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setFieldErrors({});

    const formData = new FormData(event.currentTarget);
    const input: ProfileFormInput = {
      handle: formText(formData, 'handle'),
      displayName: formText(formData, 'displayName'),
      bio: formText(formData, 'bio'),
      location: formText(formData, 'location'),
      website: formText(formData, 'website'),
      jobTitle: formText(formData, 'jobTitle'),
      company: formText(formData, 'company'),
      avatarUrl: formText(formData, 'avatarUrl'),
      bannerUrl: formText(formData, 'bannerUrl'),
    };

    const errors: FieldErrors = {};
    if (input.handle.trim().replace(/^@/, '').length < 3) {
      errors.handle = t('errors.handleRequired');
    }
    if (input.displayName.trim().length === 0) {
      errors.displayName = t('errors.required');
    }
    for (const field of Object.keys(FIELD_LIMITS) as Array<FieldName>) {
      if (input[field].length > FIELD_LIMITS[field]) {
        errors[field] = t('errors.tooLong', { limit: FIELD_LIMITS[field] });
      }
    }
    for (const field of URL_FIELDS) {
      if (input[field].trim() && !isHttpUrl(input[field].trim())) {
        errors[field] = t('errors.url');
      }
    }

    if (Object.keys(errors).length > 0) {
      setFieldErrors(errors);
      return;
    }

    startTransition(async () => {
      const result = await updateProfileAction(input);
      if (result.success) {
        toast.success(t('saved'));
        router.refresh();
      } else {
        toast.error(t('saveFailed'), { description: result.error });
      }
    });
  }

  function handleVisibilityChange(next: ProfileVisibilitySetting) {
    const previous = visibility;
    setVisibility(next);
    startVisibilityTransition(async () => {
      const result = await updateProfileVisibilityAction(next);
      if (result.success) {
        toast.success(t('visibility.saved'));
      } else {
        if (previous !== null) setVisibility(previous);
        toast.error(t('visibility.saveFailed'), { description: result.error });
      }
    });
  }

  const avatarPreview = defaultValues.avatarUrl.trim();

  return (
    <form onSubmit={handleSubmit} noValidate>
      <FieldGroup>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <UserRound className="size-4 text-muted-foreground" aria-hidden />
              {t('sections.account')}
            </CardTitle>
            <CardDescription>{t('sections.accountDescription')}</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex min-h-10 items-center gap-3 rounded-md border bg-muted/40 px-3 py-2">
              <span className="sr-only">{t('accountLabel')}</span>
              <div className="min-w-0">
                <p className="truncate text-sm font-medium">{accountName}</p>
                <p className="truncate text-xs text-muted-foreground">{accountEmail}</p>
              </div>
            </div>
            <FieldDescription>{t('accountDescription')}</FieldDescription>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <UserRound className="size-4 text-muted-foreground" aria-hidden />
              {t('sections.community')}
            </CardTitle>
            <CardDescription>{t('sections.communityDescription')}</CardDescription>
          </CardHeader>
          <CardContent className="space-y-6">
            <Field data-invalid={fieldErrors.handle ? 'true' : undefined}>
              <FieldLabel htmlFor="profile-handle">{t('handle')}</FieldLabel>
              <div className="relative">
                <span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-sm text-muted-foreground">@</span>
                <Input
                  id="profile-handle"
                  name="handle"
                  type="text"
                  required
                  pattern="[a-zA-Z0-9_-]+"
                  minLength={3}
                  maxLength={FIELD_LIMITS.handle}
                  defaultValue={defaultValues.handle}
                  disabled={isPending}
                  aria-invalid={Boolean(fieldErrors.handle)}
                  className="pl-7"
                  onChange={() => clearFieldError('handle')}
                />
              </div>
              {fieldErrors.handle && <FieldError>{fieldErrors.handle}</FieldError>}
              <FieldDescription>{t('handleDescription')}</FieldDescription>
            </Field>

            <Field data-invalid={fieldErrors.displayName ? 'true' : undefined}>
              <FieldLabel htmlFor="profile-display-name">
                {t('displayName')}
                <span className="text-destructive" aria-hidden> *</span>
              </FieldLabel>
              <Input
                id="profile-display-name"
                name="displayName"
                type="text"
                required
                maxLength={FIELD_LIMITS.displayName}
                defaultValue={defaultValues.displayName}
                disabled={isPending}
                aria-invalid={Boolean(fieldErrors.displayName)}
                onChange={() => clearFieldError('displayName')}
              />
              {fieldErrors.displayName && <FieldError>{fieldErrors.displayName}</FieldError>}
            </Field>

            <Field data-invalid={fieldErrors.bio ? 'true' : undefined}>
              <FieldLabel htmlFor="profile-bio">{t('bio')}</FieldLabel>
              <Textarea
                id="profile-bio"
                name="bio"
                rows={4}
                maxLength={FIELD_LIMITS.bio}
                defaultValue={defaultValues.bio}
                disabled={isPending}
                aria-invalid={Boolean(fieldErrors.bio)}
                onChange={(event) => {
                  setBioLength(event.currentTarget.value.length);
                  clearFieldError('bio');
                }}
              />
              {fieldErrors.bio && <FieldError>{fieldErrors.bio}</FieldError>}
              <FieldDescription>
                {t('bioCount', { current: bioLength, limit: FIELD_LIMITS.bio })}
              </FieldDescription>
            </Field>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Link2 className="size-4 text-muted-foreground" aria-hidden />
              {t('sections.details')}
            </CardTitle>
            <CardDescription>{t('sections.detailsDescription')}</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="grid gap-6 sm:grid-cols-2">
              <Field>
                <FieldLabel htmlFor="profile-location">{t('location')}</FieldLabel>
                <Input
                  id="profile-location"
                  name="location"
                  type="text"
                  maxLength={FIELD_LIMITS.location}
                  defaultValue={defaultValues.location}
                  disabled={isPending}
                  onChange={() => clearFieldError('location')}
                />
                <FieldDescription>{t('optional')}</FieldDescription>
              </Field>
              <Field data-invalid={fieldErrors.website ? 'true' : undefined}>
                <FieldLabel htmlFor="profile-website">{t('website')}</FieldLabel>
                <Input
                  id="profile-website"
                  name="website"
                  type="url"
                  inputMode="url"
                  placeholder="https://"
                  maxLength={FIELD_LIMITS.website}
                  defaultValue={defaultValues.website}
                  disabled={isPending}
                  aria-invalid={Boolean(fieldErrors.website)}
                  onChange={() => clearFieldError('website')}
                />
                {fieldErrors.website && <FieldError>{fieldErrors.website}</FieldError>}
                <FieldDescription>{t('optional')}</FieldDescription>
              </Field>
              <Field>
                <FieldLabel htmlFor="profile-job-title">{t('jobTitle')}</FieldLabel>
                <Input
                  id="profile-job-title"
                  name="jobTitle"
                  type="text"
                  maxLength={FIELD_LIMITS.jobTitle}
                  defaultValue={defaultValues.jobTitle}
                  disabled={isPending}
                  onChange={() => clearFieldError('jobTitle')}
                />
                <FieldDescription>{t('optional')}</FieldDescription>
              </Field>
              <Field>
                <FieldLabel htmlFor="profile-company">{t('company')}</FieldLabel>
                <Input
                  id="profile-company"
                  name="company"
                  type="text"
                  maxLength={FIELD_LIMITS.company}
                  defaultValue={defaultValues.company}
                  disabled={isPending}
                  onChange={() => clearFieldError('company')}
                />
                <FieldDescription>{t('optional')}</FieldDescription>
              </Field>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <ImagePlus className="size-4 text-muted-foreground" aria-hidden />
              {t('sections.images')}
            </CardTitle>
            <CardDescription>{t('sections.imagesDescription')}</CardDescription>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="flex items-center gap-4">
              <Avatar className="size-16">
                {avatarPreview ? <AvatarImage src={avatarPreview} alt="" /> : null}
                <AvatarFallback>{handleInitials(defaultValues.displayName || accountName)}</AvatarFallback>
              </Avatar>
              <Field className="flex-1" data-invalid={fieldErrors.avatarUrl ? 'true' : undefined}>
                <FieldLabel htmlFor="profile-avatar-url">{t('avatarUrl')}</FieldLabel>
                <Input
                  id="profile-avatar-url"
                  name="avatarUrl"
                  type="url"
                  inputMode="url"
                  placeholder="https://"
                  maxLength={FIELD_LIMITS.avatarUrl}
                  defaultValue={defaultValues.avatarUrl}
                  disabled={isPending}
                  aria-invalid={Boolean(fieldErrors.avatarUrl)}
                  onChange={() => clearFieldError('avatarUrl')}
                />
                {fieldErrors.avatarUrl && <FieldError>{fieldErrors.avatarUrl}</FieldError>}
                <FieldDescription>{t('avatarUrlDescription')}</FieldDescription>
              </Field>
            </div>
            <Separator />
            <Field data-invalid={fieldErrors.bannerUrl ? 'true' : undefined}>
              <FieldLabel htmlFor="profile-banner-url">{t('bannerUrl')}</FieldLabel>
              <Input
                id="profile-banner-url"
                name="bannerUrl"
                type="url"
                inputMode="url"
                placeholder="https://"
                maxLength={FIELD_LIMITS.bannerUrl}
                defaultValue={defaultValues.bannerUrl}
                disabled={isPending}
                aria-invalid={Boolean(fieldErrors.bannerUrl)}
                onChange={() => clearFieldError('bannerUrl')}
              />
              {fieldErrors.bannerUrl && <FieldError>{fieldErrors.bannerUrl}</FieldError>}
              <FieldDescription>{t('bannerUrlDescription')}</FieldDescription>
            </Field>
          </CardContent>
          <CardFooter>
            <Button type="submit" disabled={isPending}>
              <Save className="size-4" />
              {isPending ? t('saving') : t('save')}
            </Button>
          </CardFooter>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Eye className="size-4 text-muted-foreground" aria-hidden />
              {t('visibility.title')}
            </CardTitle>
            <CardDescription>{t('visibility.description')}</CardDescription>
            {hasCommunityProfile ? (
              <CardAction>
                <Link
                  href={publicProfilePath}
                  target="_blank"
                  rel="noreferrer"
                  className="text-sm font-medium text-primary hover:underline inline-flex items-center gap-1"
                >
                  {t('viewPublicProfile')} <ExternalLink className="size-3.5" aria-hidden />
                </Link>
              </CardAction>
            ) : null}
          </CardHeader>
          <CardContent>
            <Field>
              <FieldLabel htmlFor="profile-visibility">{t('visibility.label')}</FieldLabel>
              <Select
                value={visibility ?? undefined}
                onValueChange={(value) => {
                  if (value !== null && (VISIBILITY_VALUES as readonly string[]).includes(value)) {
                    handleVisibilityChange(value);
                  }
                }}
                disabled={!hasCommunityProfile || isVisibilityPending || visibility === null}
              >
                <SelectTrigger id="profile-visibility" className="w-full sm:w-72">
                  <SelectValue placeholder={t('visibility.placeholder')} />
                </SelectTrigger>
                <SelectContent>
                  {VISIBILITY_VALUES.map((value) => (
                    <SelectItem key={value} value={value}>
                      {t(`visibility.${value}`)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <FieldDescription>
                {hasCommunityProfile ? t('visibility.hint') : t('visibility.requiresProfile')}
              </FieldDescription>
            </Field>
          </CardContent>
        </Card>
      </FieldGroup>
    </form>
  );
}

'use client';

import {
  renameSessionAction,
  revokeTrustedDeviceAction,
  terminateAllSessionsAction,
  terminateOtherSessionsAction,
  terminateSessionAction,
  trustCurrentDeviceAction,
  type SessionsPageData,
} from '@/lib/auth/sessions-actions';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@game-guild/ui/components/card';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@game-guild/ui/components/alert-dialog';
import { Monitor, Smartphone, Tablet } from 'lucide-react';
import { useTranslations } from 'next-intl';
import { useRouter } from 'next/navigation';
import * as React from 'react';
import { toast } from 'sonner';

/**
 * Session management surface (settings/security, issue #278): active session list
 * with device/location metadata, per-session custom naming, single/bulk termination,
 * the current-session security analysis, and the trusted-device list.
 *
 * All mutations go through server actions (sessions-actions.ts); revalidatePath
 * refreshes the server-rendered data after every action, and router.refresh()
 * guarantees the client re-renders even when the route has no cache entry for
 * revalidatePath to invalidate (dynamic routes in dev — see the session-state
 * browser acceptance flake).
 */

const RISK_TONE: Record<string, 'default' | 'secondary' | 'destructive'> = {
  low: 'secondary',
  medium: 'default',
  high: 'destructive',
  critical: 'destructive',
};

const subscribeToHydration = () => () => undefined;

function formatTimestamp(iso: string | null | undefined, locale: string): string {
  if (!iso) {
    return '—';
  }
  const parsed = new Date(iso);
  if (Number.isNaN(parsed.getTime())) {
    return '—';
  }
  return new Intl.DateTimeFormat(locale, { dateStyle: 'medium', timeStyle: 'short' }).format(parsed);
}

function DeviceIcon({ isMobile }: { isMobile: boolean | undefined }) {
  if (isMobile) {
    return <Smartphone className="size-4 shrink-0" aria-hidden />;
  }
  return <Monitor className="size-4 shrink-0" aria-hidden />;
}

function deviceSummary(
  session: SessionsPageData['sessions'][number],
): { name: string; detail: string | undefined } {
  const info = session.deviceInfo;
  const name =
    info?.deviceName?.trim() ||
    [info?.deviceType, info?.operatingSystem].filter(Boolean).join(' · ') ||
    'Unknown device';
  const detail = [info?.browser, info?.browserVersion].filter(Boolean).join(' ');
  return { name, detail: detail || undefined };
}

function riskTone(riskLevel: string | null | undefined) {
  if (riskLevel && RISK_TONE[riskLevel.toLowerCase()]) {
    return RISK_TONE[riskLevel.toLowerCase()];
  }
  return 'default' as const;
}

export function SessionsManager({ data, locale }: { data: SessionsPageData; locale: string }) {
  const t = useTranslations('settings.security');
  const router = useRouter();
  const [isPending, startTransition] = React.useTransition();
  // Server HTML is visible before React installs the action handlers. Keep these
  // controls disabled until hydration so an early click cannot silently disappear.
  const isHydrated = React.useSyncExternalStore(subscribeToHydration, () => true, () => false);
  const isUnavailable = isPending || !isHydrated;
  const [renamingId, setRenamingId] = React.useState<string | null>(null);
  const [renameValue, setRenameValue] = React.useState('');
  const [confirmTerminateAll, setConfirmTerminateAll] = React.useState(false);

  function run(action: () => Promise<{ success: boolean }>, successMessage: string) {
    startTransition(async () => {
      const result = await action();
      if (result.success) {
        router.refresh();
        toast.success(successMessage);
      } else {
        toast.error(t('actionFailed'));
      }
    });
  }

  function submitRename(sessionId: string) {
    const name = renameValue.trim();
    if (name.length < 1) {
      toast.error(t('rename.nameRequired'));
      return;
    }
    if (name.length > 64) {
      toast.error(t('rename.nameTooLong'));
      return;
    }
    setRenamingId(null);
    run(() => renameSessionAction(sessionId, name), t('rename.success'));
  }

  const analysis = data.analysis;
  const currentSession = data.sessions.find((session) => session.isCurrent);

  return (
    <div className="space-y-6">
      {analysis ? (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center justify-between gap-2">
              <span>{t('analysis.title')}</span>
              <Badge variant={riskTone(analysis.riskLevel)}>
                {t(`analysis.risk.${(analysis.riskLevel ?? 'low').toLowerCase()}`)}
              </Badge>
            </CardTitle>
            <CardDescription>
              {t('analysis.description', {
                sessions: analysis.activeSessionCount ?? data.sessions.length,
                devices: analysis.totalDeviceCount ?? 0,
              })}
            </CardDescription>
          </CardHeader>
          {(analysis.riskFactors?.length ?? 0) > 0 && (
            <CardContent>
              <ul className="list-disc space-y-1 pl-5 text-sm text-muted-foreground">
                {analysis.riskFactors!.map((factor) => (
                  <li key={factor}>{factor}</li>
                ))}
              </ul>
            </CardContent>
          )}
        </Card>
      ) : null}

      <Card>
        <CardHeader>
          <CardTitle>{t('sessions.title')}</CardTitle>
          <CardDescription>{t('sessions.description')}</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <ul className="space-y-3">
            {data.sessions.length === 0 && <li className="text-sm text-muted-foreground">{t('sessions.empty')}</li>}
            {data.sessions.map((session) => {
              const { name, detail } = deviceSummary(session);
              const location = session.location?.displayLocation;
              return (
                <li
                  key={session.id}
                  data-testid={`session-row-${session.id}`}
                  className="flex flex-col gap-3 rounded-lg border p-4 sm:flex-row sm:items-center sm:justify-between"
                >
                  <div className="flex min-w-0 items-start gap-3">
                    <span className="mt-0.5 text-muted-foreground">
                      <DeviceIcon isMobile={session.deviceInfo?.isMobile} />
                    </span>
                    <div className="min-w-0">
                      <p className="flex flex-wrap items-center gap-2 text-sm font-medium">
                        <span className="truncate">{name}</span>
                        {session.isCurrent && <Badge data-testid="current-session-badge">{t('sessions.current')}</Badge>}
                        {session.isTrustedDevice && <Badge variant="secondary">{t('sessions.trusted')}</Badge>}
                      </p>
                      <p className="mt-1 text-xs text-muted-foreground">
                        {[detail, location, session.ipAddress].filter(Boolean).join(' · ')}
                      </p>
                      <p className="mt-1 text-xs text-muted-foreground">
                        {t('sessions.lastUsed', {
                          time: formatTimestamp(session.lastUsedAt, locale),
                        })}
                      </p>
                    </div>
                  </div>
                  <div className="flex shrink-0 items-center gap-2">
                    {renamingId === session.id ? (
                      <div className="flex items-center gap-2">
                        <label className="sr-only" htmlFor={`rename-${session.id}`}>
                          {t('rename.label')}
                        </label>
                        <input
                          id={`rename-${session.id}`}
                          value={renameValue}
                          onChange={(event) => setRenameValue(event.target.value)}
                          onKeyDown={(event) => {
                            if (event.key === 'Enter') {
                              submitRename(session.id!);
                            }
                            if (event.key === 'Escape') {
                              setRenamingId(null);
                            }
                          }}
                          maxLength={64}
                          disabled={isUnavailable}
                          className="h-8 w-40 rounded-md border bg-transparent px-2 text-sm"
                          data-testid={`rename-input-${session.id}`}
                        />
                        <Button
                          size="sm"
                          disabled={isUnavailable}
                          onClick={() => submitRename(session.id!)}
                          data-testid={`rename-save-${session.id}`}
                        >
                          {t('rename.save')}
                        </Button>
                        <Button
                          size="sm"
                          variant="ghost"
                          disabled={isUnavailable}
                          onClick={() => setRenamingId(null)}
                        >
                          {t('rename.cancel')}
                        </Button>
                      </div>
                    ) : (
                      <Button
                        size="sm"
                        variant="outline"
                        disabled={isUnavailable}
                        onClick={() => {
                          setRenamingId(session.id!);
                          setRenameValue(session.deviceInfo?.deviceName ?? '');
                        }}
                        aria-label={t('rename.aria', { name })}
                      >
                        {t('rename.trigger')}
                      </Button>
                    )}
                    {!session.isCurrent && (
                      <Button
                        size="sm"
                        variant="destructive"
                        disabled={isUnavailable}
                        onClick={() => run(() => terminateSessionAction(session.id!), t('sessions.terminated'))}
                        aria-label={t('sessions.terminateAria', { name })}
                      >
                        {t('sessions.terminate')}
                      </Button>
                    )}
                  </div>
                </li>
              );
            })}
          </ul>
          <div className="flex flex-wrap gap-2 border-t pt-4">
            <Button
              variant="outline"
              disabled={isUnavailable || data.sessions.length <= 1}
              onClick={() => run(() => terminateOtherSessionsAction(), t('sessions.othersTerminated'))}
            >
              {t('sessions.terminateOthers')}
            </Button>
            <Button
              variant="destructive"
              disabled={isUnavailable}
              onClick={() => setConfirmTerminateAll(true)}
            >
              {t('sessions.terminateAll')}
            </Button>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>{t('trustedDevices.title')}</CardTitle>
          <CardDescription>{t('trustedDevices.description')}</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <ul className="space-y-3">
            {data.trustedDevices.length === 0 && (
              <li className="text-sm text-muted-foreground">{t('trustedDevices.empty')}</li>
            )}
            {data.trustedDevices.map((device) => (
              <li
                key={device.id}
                data-testid={`trusted-device-row-${device.id}`}
                className="flex items-center justify-between gap-3 rounded-lg border p-4"
              >
                <div className="flex min-w-0 items-start gap-3">
                  <Tablet className="mt-0.5 size-4 shrink-0 text-muted-foreground" aria-hidden />
                  <div className="min-w-0">
                    <p className="truncate text-sm font-medium">
                      {device.deviceName || device.deviceInfo?.deviceName || t('trustedDevices.unnamed')}
                    </p>
                    <p className="mt-1 text-xs text-muted-foreground">
                      {t('trustedDevices.trustedAt', {
                        time: formatTimestamp(device.trustedAt, locale),
                      })}
                      {device.expiresAt
                        ? ` · ${t('trustedDevices.expiresAt', { time: formatTimestamp(device.expiresAt, locale) })}`
                        : ''}
                    </p>
                  </div>
                </div>
                <Button
                  size="sm"
                  variant="outline"
                  disabled={isUnavailable}
                  onClick={() => run(() => revokeTrustedDeviceAction(device.id!), t('trustedDevices.revoked'))}
                >
                  {t('trustedDevices.revoke')}
                </Button>
              </li>
            ))}
          </ul>
          {currentSession && !currentSession.isTrustedDevice && (
            <div className="flex items-center justify-between gap-3 rounded-lg border p-4">
              <div>
                <p className="text-sm font-medium">{t('trustedDevices.trustCurrent')}</p>
                <p className="mt-1 text-xs text-muted-foreground">{t('trustedDevices.trustCurrentDescription')}</p>
              </div>
              <Button
                size="sm"
                variant="outline"
                disabled={isUnavailable}
                onClick={() => run(() => trustCurrentDeviceAction(), t('trustedDevices.trustedCurrent'))}
              >
                {t('trustedDevices.trustCurrentButton')}
              </Button>
            </div>
          )}
        </CardContent>
      </Card>

      <AlertDialog open={confirmTerminateAll} onOpenChange={setConfirmTerminateAll}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{t('sessions.confirmTerminateAllTitle')}</AlertDialogTitle>
            <AlertDialogDescription>{t('sessions.confirmTerminateAllDescription')}</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isUnavailable}>{t('sessions.confirmCancel')}</AlertDialogCancel>
            <AlertDialogAction
              disabled={isUnavailable}
              onClick={() => run(() => terminateAllSessionsAction(), t('sessions.allTerminated'))}
            >
              {t('sessions.confirmTerminateAll')}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

"use client";

import { type FormEvent, useState, useSyncExternalStore } from "react";
import { Link, useRouter } from "@/i18n/navigation";
import { useAuth } from "@game-guild/client/react";
import { cn } from "@/lib/utils";
import { Button } from "@game-guild/ui/components/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@game-guild/ui/components/card";
import {
  Field,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@game-guild/ui/components/field";
import { Input } from "@game-guild/ui/components/input";
import { Checkbox } from "@game-guild/ui/components/checkbox";
import { PasswordInput } from "@/components/ui/password-input";
import { TurnstileWidget } from "@/components/antibot/turnstile-widget";

const subscribeToHydration = () => () => undefined;

export function SignInForm({
  className,
  redirectTo = "/",
  magicLinkLabel,
  emailCodeLabel,
  providers,
  guestEntry,
  ...props
}: React.ComponentProps<"div"> & {
  redirectTo?: string;
  magicLinkLabel?: string;
  emailCodeLabel?: string;
  providers?: React.ReactNode;
  /** Capability-gated "Continue as guest" affordance (issue #213); rendered by the page. */
  guestEntry?: React.ReactNode;
}) {
  const router = useRouter();
  const { signIn, isLoading, error, clearError } = useAuth();
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [turnstileToken, setTurnstileToken] = useState<string | null>(null);
  const isHydrated = useSyncExternalStore(
    subscribeToHydration,
    () => true,
    () => false,
  );

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    clearError();
    setFieldErrors({});

    const form = e.currentTarget;
    const formData = new FormData(form);
    const email = formData.get("email") as string;
    const password = formData.get("password") as string;
    const rememberMe = formData.get("rememberMe") === "on";

    if (!email) {
      setFieldErrors((prev) => ({ ...prev, email: "Email is required." }));
      return;
    }
    if (!password) {
      setFieldErrors((prev) => ({
        ...prev,
        password: "Password is required.",
      }));
      return;
    }

    try {
      await signIn("credentials", {
        email,
        password,
        rememberMe,
        redirectTo,
        turnstileToken,
      });
    } catch (err) {
      // Single-use token: reset on failure so the widget re-issues a fresh one.
      setTurnstileToken(null);
      // The MFA challenge lives on the dedicated /sign-in/2fa route; the
      // app-wide useAuth state (mfaChallenge) survives the navigation.
      // redirectTo rides along so the challenge returns to the caller's
      // original target (issue #864 callbackUrl flow).
      if (
        err instanceof Error &&
        "type" in err &&
        err.type === "MfaRequired"
      ) {
        form.reset();
        router.replace({ pathname: "/sign-in/2fa", query: { redirectTo } });
      }
      // error state is set by useAuth
    }
  }

  return (
    <div className={cn("flex flex-col gap-6", className)} {...props}>
      <Card className="border-white/10 bg-slate-900/85 text-white shadow-2xl shadow-sky-950/30 backdrop-blur">
        <CardHeader className="text-center">
          <CardTitle className="text-2xl">
            <h1>Welcome back</h1>
          </CardTitle>
          <CardDescription className="text-slate-300">
            Sign in to continue.
          </CardDescription>
        </CardHeader>
        <CardContent>
          {providers && (
            <>
              <div className="mb-6">{providers}</div>
              <div className="flex w-full items-center gap-3 text-xs text-slate-400">
                <div className="h-px flex-1 bg-white/10" />
                <span>or sign in with email</span>
                <div className="h-px flex-1 bg-white/10" />
              </div>
            </>
          )}
          <form
            method="post"
            onSubmit={(event) => {
              void handleSubmit(event);
            }}
            noValidate
            data-auth-ready={isHydrated ? "true" : "false"}
          >
            <FieldGroup>
              <Field>
                <FieldLabel htmlFor="email">Email</FieldLabel>
                <Input
                  id="email"
                  name="email"
                  type="email"
                  placeholder="name@example.com"
                  autoComplete="email"
                  required
                  disabled={isLoading}
                  className="h-10 border-white/10 bg-white/5 text-white placeholder:text-slate-500"
                  aria-invalid={!!fieldErrors.email}
                  onChange={() =>
                    fieldErrors.email &&
                    setFieldErrors((prev) => ({ ...prev, email: "" }))
                  }
                />
                {fieldErrors.email && (
                  <FieldError>{fieldErrors.email}</FieldError>
                )}
              </Field>
              <Field>
                <FieldLabel htmlFor="password">Password</FieldLabel>
                <PasswordInput
                  id="password"
                  name="password"
                  autoComplete="current-password"
                  required
                  disabled={isLoading}
                  className="h-10 border-white/10 bg-white/5 text-white"
                  aria-invalid={!!fieldErrors.password}
                  onChange={() =>
                    fieldErrors.password &&
                    setFieldErrors((prev) => ({ ...prev, password: "" }))
                  }
                />
                {fieldErrors.password && (
                  <FieldError>{fieldErrors.password}</FieldError>
                )}
                <Link
                  href="/forgot-password"
                  className="ml-auto w-fit text-sm text-sky-200 underline-offset-4 hover:underline"
                  tabIndex={-1}
                >
                  Forgot your password?
                </Link>
              </Field>
              <Field>
                <label
                  htmlFor="rememberMe"
                  className="flex cursor-pointer items-center gap-2 text-sm text-slate-300 select-none"
                >
                  <Checkbox
                    id="rememberMe"
                    name="rememberMe"
                    disabled={isLoading}
                    aria-label="Remember me on this device"
                  />
                  Remember me
                </label>
                <FieldDescription className="text-slate-400">
                  Keeps you signed in on this device for up to 30 days.
                </FieldDescription>
              </Field>
              {error &&
                !("type" in error && error.type === "MfaRequired") && (
                  <FieldError>{error.message}</FieldError>
                )}
              <Field>
                <TurnstileWidget onToken={setTurnstileToken} action="sign-in" id="sign-in-turnstile" />
                <Button
                  type="submit"
                  size="lg"
                  disabled={isLoading || !isHydrated}
                >
                  {isLoading ? "Signing in..." : "Sign in"}
                </Button>
                <FieldDescription className="text-center text-slate-300">
                  Don&apos;t have an account?{" "}
                  <Link
                    href={
                      redirectTo
                        ? `/sign-up?redirectTo=${encodeURIComponent(redirectTo)}`
                        : "/sign-up"
                    }
                    className="text-sky-200 underline-offset-4 hover:underline"
                  >
                    Sign up
                  </Link>
                </FieldDescription>
                {magicLinkLabel ? (
                  <FieldDescription className="text-center text-slate-300">
                    <Link
                      href={`/magic-link?redirectTo=${encodeURIComponent(redirectTo)}`}
                      className="text-sky-200 underline-offset-4 hover:underline"
                    >
                      {magicLinkLabel}
                    </Link>
                  </FieldDescription>
                ) : null}
                {emailCodeLabel ? (
                  <FieldDescription className="text-center text-slate-300">
                    <Link
                      href="/email-code"
                      className="text-sky-200 underline-offset-4 hover:underline"
                    >
                      {emailCodeLabel}
                    </Link>
                  </FieldDescription>
                ) : null}
              </Field>
            </FieldGroup>
          </form>
          {guestEntry ? (
            <>
              <div className="mt-4 flex w-full items-center gap-3 text-xs text-slate-400">
                <div className="h-px flex-1 bg-white/10" />
                <span>or</span>
                <div className="h-px flex-1 bg-white/10" />
              </div>
              <div className="mt-4">{guestEntry}</div>
            </>
          ) : null}
        </CardContent>
      </Card>
    </div>
  );
}

"use client"

import { type FormEvent, useState } from "react"
import { Link } from "@/i18n/navigation"
import { useLocale } from "next-intl"
import { useAuth } from "@game-guild/client/react"
import { cn } from "@/lib/utils"
import {
  clearGuestSession,
  loadGuestSession,
} from "@/lib/auth/guest-session"
import { Button } from "@game-guild/ui/components/button"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@game-guild/ui/components/card"
import {
  Field,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@game-guild/ui/components/field"
import { Input } from "@game-guild/ui/components/input"
import { PasswordInput } from "@/components/ui/password-input"
import { TurnstileWidget } from "@/components/antibot/turnstile-widget"

export function SignupForm({
  className,
  redirectTo = "/",
  providers,
  guestSessionId,
  guestUpgradeNotice,
  ...props
}: React.ComponentProps<"div"> & {
  redirectTo?: string
  providers?: React.ReactNode
  /**
   * Guest upgrade entry (issue #213): when set, the sign-up presents the
   * matching guest bearer from the browser's guest slot so the backend
   * upgrade flow links the new account to the guest session.
   */
  guestSessionId?: string
  guestUpgradeNotice?: string
}) {
  const { signUp, isLoading, error, clearError } = useAuth()
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({})
  const [turnstileToken, setTurnstileToken] = useState<string | null>(null)
  const locale = useLocale()

  function clearFieldError(field: string) {
    setFieldErrors((prev) => {
      if (!prev[field]) return prev
      const next = { ...prev }
      delete next[field]
      return next
    })
  }

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault()
    clearError()
    setFieldErrors({})

    const formData = new FormData(e.currentTarget)
    const name = (formData.get("name") as string).trim()
    const email = (formData.get("email") as string).trim()
    const password = formData.get("password") as string
    const confirmPassword = formData.get("confirm-password") as string

    const errors: Record<string, string> = {}

    if (!name) errors.name = "Full name is required."
    if (!email) errors.email = "Email is required."
    if (!password) errors.password = "Password is required."
    else if (password.length < 8)
      errors.password = "Password must be at least 8 characters."
    if (!confirmPassword)
      errors["confirm-password"] = "Please confirm your password."
    else if (password && password !== confirmPassword)
      errors["confirm-password"] = "Passwords do not match."

    if (Object.keys(errors).length > 0) {
      setFieldErrors(errors)
      return
    }

    // Guest upgrade (issue #213): the guest banner's CTA arrives with the
    // guest-session id; only the matching stored guest session's bearer is
    // presented (a stale or absent session never blocks registration).
    const guestSession = guestSessionId ? loadGuestSession() : null
    const guestAccessToken =
      guestSession && guestSession.guestSessionId === guestSessionId
        ? guestSession.accessToken
        : undefined

    try {
      await signUp({
        username: email.split("@")[0],
        email,
        password,
        firstName: name.split(" ")[0],
        lastName: name.split(" ").slice(1).join(" ") || undefined,
        redirectTo,
        turnstileToken,
        ...(guestAccessToken ? { guestAccessToken } : {}),
      } as Parameters<typeof signUp>[0])

      // The upgrade verdict is the backend's (UpgradedFromGuestSessionId on
      // the sign-up response); once an authenticated session exists the guest
      // slot has served its purpose and is cleared either way.
      if (guestSessionId) clearGuestSession()
    } catch {
      // Single-use token: reset on failure so the widget re-issues a fresh one.
      setTurnstileToken(null)
      // error state is set by useAuth
    }
  }

  return (
    <div className={cn("flex flex-col gap-6", className)} {...props}>
      <Card className="border-white/10 bg-slate-900/85 text-white shadow-2xl shadow-sky-950/30 backdrop-blur">
        <CardHeader className="text-center">
          <CardTitle className="text-2xl">
            <h1>Create your GameGuild account</h1>
          </CardTitle>
          <CardDescription className="text-slate-300">
            Join the community to learn, share projects, and collect useful feedback.
          </CardDescription>
        </CardHeader>
        <CardContent>
          {providers && (
            <>
              <div className="mb-6">{providers}</div>
              <div className="flex w-full items-center gap-3 text-xs text-slate-400">
                <div className="h-px flex-1 bg-white/10" />
                <span>or sign up with email</span>
                <div className="h-px flex-1 bg-white/10" />
              </div>
            </>
          )}
          <form onSubmit={handleSubmit} noValidate>
            <FieldGroup>
              {guestUpgradeNotice ? (
                <p
                  data-testid="guest-upgrade-notice"
                  className="rounded-md border border-sky-400/25 bg-sky-400/10 px-3 py-2 text-sm text-sky-100"
                >
                  {guestUpgradeNotice}
                </p>
              ) : null}
              <Field>
                <FieldLabel htmlFor="name">Full Name</FieldLabel>
                <Input
                  id="name"
                  name="name"
                  type="text"
                  placeholder="John Doe"
                  autoComplete="name"
                  required
                  disabled={isLoading}
                  className="border-white/10 bg-white/5 text-white placeholder:text-slate-500"
                  aria-invalid={!!fieldErrors.name}
                  onChange={() => clearFieldError("name")}
                />
                {fieldErrors.name && (
                  <FieldError>{fieldErrors.name}</FieldError>
                )}
              </Field>
              <Field>
                <FieldLabel htmlFor="email">Email</FieldLabel>
                <Input
                  id="email"
                  name="email"
                  type="email"
                  placeholder="name@example.com"
                  autoComplete="email"
                  required
                  disabled={isLoading}
                  className="border-white/10 bg-white/5 text-white placeholder:text-slate-500"
                  aria-invalid={!!fieldErrors.email}
                  onChange={() => clearFieldError("email")}
                />
                {fieldErrors.email && (
                  <FieldError>{fieldErrors.email}</FieldError>
                )}
              </Field>
              <Field>
                <Field className="grid grid-cols-2 gap-4">
                  <Field>
                    <FieldLabel htmlFor="password">Password</FieldLabel>
                    <PasswordInput
                      id="password"
                      name="password"
                      autoComplete="new-password"
                      required
                      disabled={isLoading}
                      className="border-white/10 bg-white/5 text-white"
                      aria-invalid={!!fieldErrors.password}
                      onChange={() => clearFieldError("password")}
                    />
                    {fieldErrors.password && (
                      <FieldError>{fieldErrors.password}</FieldError>
                    )}
                  </Field>
                  <Field>
                    <FieldLabel htmlFor="confirm-password">
                      Confirm Password
                    </FieldLabel>
                    <PasswordInput
                      id="confirm-password"
                      name="confirm-password"
                      autoComplete="new-password"
                      required
                      disabled={isLoading}
                      className="border-white/10 bg-white/5 text-white"
                      aria-invalid={!!fieldErrors["confirm-password"]}
                      onChange={() => clearFieldError("confirm-password")}
                    />
                    {fieldErrors["confirm-password"] && (
                      <FieldError>{fieldErrors["confirm-password"]}</FieldError>
                    )}
                  </Field>
                </Field>
                <FieldDescription className="text-slate-400">
                  Must be at least 8 characters long.
                </FieldDescription>
              </Field>
              {error && <FieldError>{error.message}</FieldError>}
              <Field>
                <TurnstileWidget onToken={setTurnstileToken} action="sign-up" id="sign-up-turnstile" />
                <Button type="submit" disabled={isLoading}>
                  {isLoading ? "Creating account..." : "Create Account"}
                </Button>
                <FieldDescription className="text-center text-slate-300">
                  Already have an account?{" "}
                  <Link
                    href={redirectTo ? `/sign-in?redirectTo=${encodeURIComponent(redirectTo)}` : "/sign-in"}
                    locale={locale}
                    className="text-sky-200 underline-offset-4 hover:underline"
                  >
                    Sign in
                  </Link>
                </FieldDescription>
              </Field>
            </FieldGroup>
          </form>
        </CardContent>
      </Card>
    </div>
  )
}

import { Gamepad2 } from "lucide-react";

const COVER_THEMES = [
  {
    base: "from-violet-600 via-indigo-600 to-sky-500",
    glow: ["bg-fuchsia-400", "bg-cyan-300"],
  },
  {
    base: "from-fuchsia-600 via-purple-600 to-indigo-500",
    glow: ["bg-pink-300", "bg-sky-400"],
  },
  {
    base: "from-sky-500 via-blue-600 to-indigo-600",
    glow: ["bg-cyan-300", "bg-violet-400"],
  },
  {
    base: "from-emerald-500 via-teal-600 to-cyan-600",
    glow: ["bg-lime-300", "bg-sky-300"],
  },
  {
    base: "from-amber-500 via-orange-600 to-rose-500",
    glow: ["bg-yellow-300", "bg-pink-400"],
  },
  {
    base: "from-rose-500 via-pink-600 to-purple-600",
    glow: ["bg-orange-300", "bg-indigo-400"],
  },
] as const;

function themeIndex(seed: string) {
  let hash = 0;
  for (let position = 0; position < seed.length; position += 1) {
    hash = (hash * 31 + seed.charCodeAt(position)) % 1_000_003;
  }
  return hash % COVER_THEMES.length;
}

/**
 * Decorative, deterministic cover artwork for testing sessions. Sessions carry
 * no imagery, so the cover is seeded from the event id: the same session always
 * gets the same gradient family wherever it appears (directory cards, feed).
 */
export function EventCoverArt({
  seed,
  className = "",
}: {
  seed: string;
  className?: string;
}) {
  const theme = COVER_THEMES[themeIndex(seed)]!;
  return (
    <div
      aria-hidden="true"
      className={`absolute inset-0 overflow-hidden bg-gradient-to-br ${theme.base} ${className}`}
    >
      <div
        className={`absolute -left-10 -top-12 size-48 rounded-full opacity-25 blur-3xl ${theme.glow[0]}`}
      />
      <div
        className={`absolute -bottom-14 -right-12 size-56 rounded-full opacity-20 blur-3xl ${theme.glow[1]}`}
      />
      <div className="absolute inset-0 opacity-10 [background-image:radial-gradient(circle,white_1.5px,transparent_1.5px)] [background-size:22px_22px]" />
      <Gamepad2
        strokeWidth={1}
        className="absolute -bottom-6 -right-5 size-36 -rotate-12 text-white/15"
      />
      <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-black/5 to-black/20" />
    </div>
  );
}

