function calendarDateParts(date: Date, timeZoneId: string) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: timeZoneId,
    year: "numeric",
    month: "numeric",
    day: "numeric",
  }).formatToParts(date);
  return {
    year: Number(parts.find((part) => part.type === "year")?.value),
    month: Number(parts.find((part) => part.type === "month")?.value),
    day: Number(parts.find((part) => part.type === "day")?.value),
  };
}

function calendarDayKey(date: Date) {
  return `${date.getUTCFullYear()}-${date.getUTCMonth()}-${date.getUTCDate()}`;
}

function localDayKey(date: Date, timeZoneId: string) {
  const { year, month, day } = calendarDateParts(date, timeZoneId);
  return `${year}-${month - 1}-${day}`;
}

function formatCalendarMonth(year: number, month: number, locale: string, options: Intl.DateTimeFormatOptions) {
  return new Intl.DateTimeFormat(locale, { ...options, timeZone: "UTC" })
    .format(new Date(Date.UTC(year, month, 1)));
}

/** Month-grid calendar over the filtered sessions; dates are UTC to match the
 *  rest of the directory. Rows are ISO weeks with the week number on the left;
 *  each event pill links to the event page. */
export function TestingEventsCalendar({
  sessions,
  projectId,
}: {
  sessions: TestingEventViewModel[];
  projectId?: string;
}) {
  const scheduled = sessions.filter(
    (session) => session.startsAt && !Number.isNaN(new Date(session.startsAt).valueOf()),
  );
  const timeZoneId = scheduled[0]?.timeZoneId ?? "UTC";
  const dateLocale = scheduled[0]?.dateLocale ?? "en-US";
  const [anchor, setAnchor] = useState<Date>(() =>
    scheduled.length > 0 ? new Date(scheduled[0]!.startsAt!) : new Date(),
  );

  const eventsByDay = new Map<string, TestingEventViewModel[]>();
  for (const session of scheduled) {
    const key = localDayKey(new Date(session.startsAt!), timeZoneId);
    const bucket = eventsByDay.get(key) ?? [];
    bucket.push(session);
    eventsByDay.set(key, bucket);
  }

  const anchorParts = calendarDateParts(anchor, timeZoneId);
  const anchorYear = anchorParts.year;
  const anchorMonth = anchorParts.month - 1;
  const monthLabel = formatCalendarMonth(anchorYear, anchorMonth, dateLocale, { month: "long", year: "numeric" });
  const firstWeekday = new Date(Date.UTC(anchorYear, anchorMonth, 1)).getUTCDay();
  const daysInMonth = new Date(Date.UTC(anchorYear, anchorMonth + 1, 0)).getUTCDate();
  const todayKey = localDayKey(new Date(), timeZoneId);
  const monthEventCount = scheduled.filter((session) => {
    const date = calendarDateParts(new Date(session.startsAt!), timeZoneId);
    return date.year === anchorYear && date.month === anchorMonth + 1;
  }).length;

  const shiftMonth = (delta: number) =>
    setAnchor(new Date(Date.UTC(anchorYear, anchorMonth + delta, 1)));

  // Fill the grid with real dates: previous-month tail, this month, and the
  // next-month head, so the rectangle is complete and adjacent events bleed in.
  const leading = Array.from(
    { length: firstWeekday },
    (_, index) =>
      new Date(Date.UTC(anchorYear, anchorMonth, index - firstWeekday + 1)),
  );
  const monthDays = Array.from(
    { length: daysInMonth },
    (_, index) => new Date(Date.UTC(anchorYear, anchorMonth, index + 1)),
  );
  const trailingCount =
    (7 - ((leading.length + monthDays.length) % 7)) % 7;
  const trailing = Array.from(
    { length: trailingCount },
    (_, index) => new Date(Date.UTC(anchorYear, anchorMonth + 1, index + 1)),
  );
  const allDays = [...leading, ...monthDays, ...trailing];
  const weeks: Array<Array<Date>> = [];
  for (let index = 0; index < allDays.length; index += 7) {
    weeks.push(allDays.slice(index, index + 7));
  }

  const monthOptions = Array.from({ length: 25 }, (_, index) => {
    const base = calendarDateParts(new Date(), timeZoneId);
    return new Date(
      Date.UTC(base.year, base.month - 1 - 12 + index, 1),
    );
  });
  const weekdayLabels = Array.from({ length: 7 }, (_, index) =>
    new Intl.DateTimeFormat(dateLocale, { weekday: "short", timeZone: "UTC" })
      .format(new Date(Date.UTC(2023, 0, 1 + index))),
  );
  const shortMonthLabel = formatCalendarMonth(anchorYear, anchorMonth, dateLocale, { month: "short", year: "numeric" });

  return (
    <div>
      <div className="mb-5 flex flex-wrap items-end justify-between gap-3">
        <div>
          <h3 className="text-2xl font-semibold tracking-tight text-foreground">
            {monthLabel}
          </h3>
          <p className="mt-1 text-xs text-muted-foreground">
            {monthEventCount} {monthEventCount === 1 ? "event" : "events"} this month
          </p>
        </div>
        <div className="flex items-center gap-1">
          <DropdownMenu>
            <DropdownMenuTrigger
              render={
                <button
                  type="button"
                  aria-label="Select month"
                  className="flex h-8 items-center gap-1.5 rounded-full px-3 text-xs font-medium text-muted-foreground transition hover:bg-muted hover:text-foreground"
                />
              }
            >
              {shortMonthLabel}
              <ChevronDown className="size-3.5" aria-hidden="true" />
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="max-h-72 overflow-y-auto">
              {monthOptions.map((option) => {
                const isActive =
                  option.getUTCFullYear() === anchorYear &&
                  option.getUTCMonth() === anchorMonth;
                return (
                  <DropdownMenuItem
                    key={option.valueOf()}
                    onClick={() => setAnchor(option)}
                    className={isActive ? "font-medium text-primary" : ""}
                  >
                    {new Intl.DateTimeFormat(dateLocale, {
                      month: "short",
                      year: "numeric",
                      timeZone: "UTC",
                    }).format(option)}
                  </DropdownMenuItem>
                );
              })}
            </DropdownMenuContent>
          </DropdownMenu>
          <span aria-hidden="true" className="mx-1 h-4 w-px bg-border" />
          <button
            type="button"
            aria-label="Previous month"
            onClick={() => shiftMonth(-1)}
            className="flex size-8 items-center justify-center rounded-full text-muted-foreground transition hover:bg-muted hover:text-foreground"
          >
            <ChevronLeft className="size-4" aria-hidden="true" />
          </button>
          <button
            type="button"
            aria-label="Next month"
            onClick={() => shiftMonth(1)}
            className="flex size-8 items-center justify-center rounded-full text-muted-foreground transition hover:bg-muted hover:text-foreground"
          >
            <ChevronRight className="size-4" aria-hidden="true" />
          </button>
        </div>
      </div>
      {/* Borderless grid with real adjacent-month days as quiet ghosts; day
          numbers lead from the left, events stack underneath, hover lifts a
          day into a soft surface. */}
      <div role="grid" aria-label={`${monthLabel} event calendar`}>
        <div className="mb-2 grid grid-cols-[2rem_repeat(7,minmax(0,1fr))]">
          <div />
              {weekdayLabels.map((label, index) => (
            <div
              key={label}
              className={`px-2 text-[11px] font-medium uppercase tracking-widest ${
                index === 0 || index === 6
                  ? "text-muted-foreground/50"
                  : "text-muted-foreground/70"
              }`}
            >
              {label}
            </div>
          ))}
        </div>
        <div className="space-y-1">
          {weeks.map((week, weekIndex) => {
            const weekNumber = getISOWeek(week[0] ?? anchor);
            return (
              <div
                key={`week-${weekIndex}`}
                role="row"
                className="grid grid-cols-[2rem_repeat(7,minmax(0,1fr))]"
              >
                <div className="pt-2 text-center text-[10px] font-medium text-muted-foreground/35">
                  {weekNumber}
                </div>
                {week.map((day, dayIndex) => {
                  const key = calendarDayKey(day);
                  const dayEvents = eventsByDay.get(key) ?? [];
                  const isToday = key === todayKey;
                  const isOutside =
                    day.getUTCMonth() !== anchorMonth ||
                    day.getUTCFullYear() !== anchorYear;
                  const isWeekend = dayIndex === 0 || dayIndex === 6;
                  const visibleEvents = dayEvents.slice(0, 2);
                  const hiddenCount = dayEvents.length - visibleEvents.length;
                  return (
                    <div
                      key={key}
                      role={isOutside ? undefined : "gridcell"}
                      aria-label={
                        isOutside
                          ? undefined
                          : new Intl.DateTimeFormat(dateLocale, {
                              month: "short",
                              day: "numeric",
                              timeZone: "UTC",
                            }).format(day)
                      }
                      className={`group flex min-h-32 flex-col rounded-lg p-2 ${
                        isOutside ? "" : "transition hover:bg-muted/50"
                      }`}
                    >
                      <div className="mb-1.5">
                        {isToday ? (
                          <span className="flex size-6 items-center justify-center rounded-full bg-primary text-xs font-semibold text-primary-foreground">
                            {day.getUTCDate()}
                          </span>
                        ) : (
                          <span
                            className={`text-xs tabular-nums ${
                              isOutside
                                ? "text-muted-foreground/25"
                                : isWeekend
                                  ? "text-muted-foreground/50"
                                  : "text-muted-foreground"
                            }`}
                          >
                            {day.getUTCDate()}
                          </span>
                        )}
                      </div>
                      <div className={`space-y-0.5 ${isOutside ? "opacity-40" : ""}`}>
                        {visibleEvents.map((session) => (
                          <HoverCard key={session.id}>
                            <HoverCardTrigger
                              render={
                                <Link
                                  href={eventHref(session.id, projectId)}
                                  title={session.title}
                                  className="flex items-center gap-1.5 rounded-md px-1.5 py-1 text-[11px] font-medium leading-tight text-foreground/80 transition hover:bg-primary/10 hover:text-primary"
                                />
                              }
                            >
                              <span
                                aria-hidden="true"
                                className={`size-1.5 shrink-0 rounded-full ${statusDotClasses(session.status)}`}
                              />
                              <span className="truncate">{session.title}</span>
                            </HoverCardTrigger>
                            <HoverCardContent side="top" className="w-72">
                              <p className="text-sm font-semibold text-foreground">
                                {session.title}
                              </p>
                              <p className="mt-1 line-clamp-3 text-xs leading-5 text-muted-foreground">
                                {session.description}
                              </p>
                              <div className="mt-3 space-y-1.5 text-xs text-muted-foreground">
                                <p className="flex items-center gap-1.5">
                                  <Calendar className="size-3.5 shrink-0" aria-hidden="true" />
                                  {formatDate(session.startsAt, session)} · {formatTime(session.startsAt, session)}
                                </p>
                                <p className="flex items-center gap-1.5">
                                  <MapPin className="size-3.5 shrink-0" aria-hidden="true" />
                                  {session.location}
                                </p>
                                <p className="flex items-center gap-1.5">
                                  <Users className="size-3.5 shrink-0" aria-hidden="true" />
                                  {capacityLabel(session.testerCount, session.testerLimit, "testers")}
                                </p>
                              </div>
                              <p className="mt-3 text-xs font-medium text-primary">
                                View event →
                              </p>
                            </HoverCardContent>
                          </HoverCard>
                        ))}
                        {hiddenCount > 0 ? (
                          <p className="px-1.5 text-[10px] font-medium text-muted-foreground/60">
                            +{hiddenCount} more
                          </p>
                        ) : null}
                      </div>
                    </div>
                  );
                })}
              </div>
            );
          })}
        </div>
      </div>
      {sessions.length > scheduled.length ? (
        <p className="mt-4 text-xs text-muted-foreground">
          {sessions.length - scheduled.length} unscheduled{" "}
          {sessions.length - scheduled.length === 1 ? "event is" : "events are"} not
          shown on the calendar.
        </p>
      ) : null}
    </div>
  );
}

import type { TestingLabPublicTestingEventProjection } from "@game-guild/client";

export type TestingEventStatus =
  "open" | "in-progress" | "completed" | "closed";

export interface TestingEventViewModel {
  id: string;
  title: string;
  description: string;
  mode: string;
  status: TestingEventStatus;
  statusLabel: string;
  startsAt?: string;
  endsAt?: string;
  location: string;
  testerCount: number;
  testerLimit: number | null;
  projectCount: number;
  projectLimit: number | null;
  availableTesterCount: number | null;
  testerRegistrationOpen: boolean;
  gameSubmissionsOpen: boolean;
  gameImageUrl: string | null;
  scheduleCount: number;
  timeZoneId: string;
  dateLocale: string;
  hour12: boolean;
}

export interface TestingEventFormatting {
  timeZoneId?: string;
  dateLocale?: string;
  hour12?: boolean;
}

const STATUS_LABELS: Record<TestingEventStatus, string> = {
  open: "Open",
  "in-progress": "In progress",
  completed: "Playtest ended",
  closed: "Registration closed",
};

function timestamp(value?: string | null): number | null {
  if (!value) return null;
  const parsed = new Date(value).valueOf();
  return Number.isFinite(parsed) ? parsed : null;
}

function remainingTesterCapacity(slot: NonNullable<TestingLabPublicTestingEventProjection["slots"]>[number]): number | null {
  if (slot.maxTesters == null) return null;
  if (slot.availableTesterCount != null) return Math.max(0, slot.availableTesterCount);
  return Math.max(0, slot.maxTesters - (slot.registeredTesterCount ?? 0));
}

function sumLimit(values: Array<number | null | undefined>): number | null {
  if (values.length === 0 || values.some((value) => value == null)) return null;
  return values.reduce<number>((total, value) => total + value!, 0);
}

export function presentTestingEvents(
  events: TestingLabPublicTestingEventProjection[],
  now = new Date(),
  formatting: TestingEventFormatting = {},
): TestingEventViewModel[] {
  return events.map((event) => {
    const slots = event.slots ?? [];
    const nowTimestamp = now.valueOf();
    const eventEndsAt = timestamp(event.endsAt);
    const eventEnded =
      event.status === "Completed" ||
      (eventEndsAt != null && eventEndsAt <= nowTimestamp);
    const eligibleTesterStatus = ["ApplicationsClosed", "Scheduled", "Active"].includes(
      event.status ?? "",
    );
    const configurationReady = Boolean(
      event.configuration?.frozenAt && event.configuration.testerRegistrationSchema,
    );
    const testerSlots = slots.filter((slot) => {
      const slotEndsAt = timestamp(slot.endsAt) ?? eventEndsAt;
      return (
        !eventEnded &&
        eligibleTesterStatus &&
        configurationReady &&
        (slotEndsAt == null || slotEndsAt > nowTimestamp)
      );
    });
    const testerRegistrationOpen = testerSlots.length > 0;
    const applicationsOpenAt = timestamp(event.applicationsOpenAt);
    const applicationsCloseAt = timestamp(event.applicationsCloseAt);
    const withinApplicationsWindow =
      (applicationsOpenAt == null || applicationsOpenAt <= nowTimestamp) &&
      (applicationsCloseAt == null || applicationsCloseAt >= nowTimestamp);
    const gameSubmissionsOpen =
      !eventEnded && event.status === "ApplicationsOpen" && withinApplicationsWindow;
    const status: TestingEventStatus = eventEnded
      ? "completed"
      : event.status === "Cancelled"
        ? "closed"
        : event.status === "Active"
          ? "in-progress"
          : testerRegistrationOpen || gameSubmissionsOpen
            ? "open"
            : "closed";
    const statusLabel =
      event.status === "Cancelled"
        ? "Cancelled"
        : event.status === "Active"
          ? STATUS_LABELS[status]
          : testerRegistrationOpen
            ? "Tester sign-up open"
            : gameSubmissionsOpen
              ? "Game submissions open"
              : STATUS_LABELS[status];
    const locations = [
      ...new Set(
        slots.flatMap((slot) => {
          const location = [slot.campusName, slot.roomName]
            .filter(Boolean)
            .join(" - ");
          return location ? [location] : [];
        }),
      ),
    ];
    const startsAt =
      slots
        .map((slot) => slot.startsAt)
        .filter((value): value is string => Boolean(value))
        .sort()[0] ?? event.startsAt;
    const endsAt =
      slots
        .map((slot) => slot.endsAt)
        .filter((value): value is string => Boolean(value))
        .sort()
        .at(-1) ?? event.endsAt;

    return {
      id: event.id ?? "",
      title: event.name?.trim() || "Untitled testing event",
      description:
        event.description?.trim() ||
        "A managed GameGuild project testing event.",
      mode: event.mode === "InPerson" ? "In person" : (event.mode ?? "Online"),
      status,
      statusLabel,
      startsAt,
      endsAt,
      location:
        locations.length > 0
          ? locations.join(", ")
          : event.mode === "Online"
            ? "Online"
            : "Location pending",
      testerCount: slots.reduce(
        (total, slot) => total + (slot.registeredTesterCount ?? 0),
        0,
      ),
      testerLimit: sumLimit(slots.map((slot) => slot.maxTesters)),
      projectCount: slots.reduce(
        (total, slot) => total + (slot.approvedProjectCount ?? 0),
        0,
      ),
      projectLimit: sumLimit(slots.map((slot) => slot.maxProjects)),
      availableTesterCount: !testerRegistrationOpen
        ? 0
        : testerSlots.some((slot) => remainingTesterCapacity(slot) == null)
          ? null
          : testerSlots.reduce(
              (total, slot) => total + (remainingTesterCapacity(slot) ?? 0),
              0,
            ),
      testerRegistrationOpen,
      gameSubmissionsOpen,
      gameImageUrl:
        event.games?.find((game) => Boolean(game.imageUrl?.trim()))?.imageUrl?.trim() ??
        null,
      scheduleCount: slots.length,
      timeZoneId: formatting.timeZoneId ?? "UTC",
      dateLocale: formatting.dateLocale ?? "en-US",
      hour12: formatting.hour12 ?? true,
    };
  });
}

'use client';

import type {
  TestingLabQuestionnaireConditionOperator,
  TestingLabQuestionnaireOutput,
  TestingLabQuestionnaireQuestion,
  TestingLabQuestionnaireQuestionType,
  TestingLabQuestionnaireSchema,
} from '@game-guild/client';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { Input } from '@game-guild/ui/components/input';
import { Label } from '@game-guild/ui/components/label';
import { ArrowDown, ArrowUp, Eye, Plus, Trash2 } from 'lucide-react';
import { useId, useState } from 'react';
import { QuestionnaireFieldset } from './questionnaire-fieldset';

function stableId(prefix: string) {
  return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
}

function normalizeQuestion(question: TestingLabQuestionnaireQuestion): TestingLabQuestionnaireQuestion {
  const type = question.type ?? 'FreeText';
  return {
    ...question,
    type,
    options: type === 'FreeText' ? [] : question.options ?? [],
  };
}

export function QuestionnaireBuilder({
  value,
  onChange,
  required,
}: {
  value: TestingLabQuestionnaireSchema;
  onChange: (value: TestingLabQuestionnaireSchema) => void;
  required?: boolean;
}) {
  const titleId = useId();
  const [preview, setPreview] = useState(false);
  const [previewAnswers, setPreviewAnswers] = useState<TestingLabQuestionnaireOutput>({ answers: [] });
  const questions = value.questions ?? [];

  function updateQuestion(index: number, patch: Partial<TestingLabQuestionnaireQuestion>) {
    const next = [...questions];
    next[index] = normalizeQuestion({ ...next[index], ...patch });
    onChange({ ...value, questions: next });
  }

  function move(index: number, offset: -1 | 1) {
    const target = index + offset;
    const next = [...questions];
    [next[index], next[target]] = [next[target], next[index]];
    onChange({ ...value, questions: next });
  }

  if (preview) {
    return (
      <div className="space-y-4 rounded-md border bg-muted/20 p-4">
        <div className="flex items-center justify-between gap-3">
          <Badge variant="secondary">Preview</Badge>
          <Button type="button" variant="outline" size="sm" onClick={() => setPreview(false)}>Back to builder</Button>
        </div>
        <QuestionnaireFieldset schema={value} value={previewAnswers} onChange={setPreviewAnswers} submitLabel="Finish preview" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="space-y-2">
        <Label htmlFor={titleId}>Questionnaire title</Label>
        <Input
          id={titleId}
          value={value.title ?? ''}
          onChange={(event) => onChange({ ...value, title: event.currentTarget.value })}
          placeholder="Playtest feedback"
        />
      </div>

      {questions.map((question, index) => {
        const questionOptions = question.options ?? [];
        return (
        <section key={question.id ?? index} className="space-y-3 rounded-md border p-4">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <Badge variant="outline">Question {index + 1}</Badge>
            <div className="flex gap-1">
              <Button type="button" size="icon-sm" variant="ghost" aria-label="Move question up" disabled={index === 0} onClick={() => move(index, -1)}><ArrowUp /></Button>
              <Button type="button" size="icon-sm" variant="ghost" aria-label="Move question down" disabled={index === questions.length - 1} onClick={() => move(index, 1)}><ArrowDown /></Button>
              <Button type="button" size="icon-sm" variant="ghost" aria-label="Delete question" onClick={() => onChange({ ...value, questions: questions.filter((_, candidate) => candidate !== index) })}><Trash2 /></Button>
            </div>
          </div>
          <div className="grid gap-3 sm:grid-cols-[minmax(0,1fr)_180px]">
            <div className="space-y-2">
              <Label htmlFor={`question-prompt-${question.id}`}>Prompt</Label>
              <Input id={`question-prompt-${question.id}`} value={question.prompt ?? ''} onChange={(event) => updateQuestion(index, { prompt: event.currentTarget.value })} />
            </div>
            <div className="space-y-2">
              <Label htmlFor={`question-type-${question.id}`}>Answer type</Label>
              <select
                id={`question-type-${question.id}`}
                value={question.type ?? 'FreeText'}
                onChange={(event) => updateQuestion(index, { type: event.currentTarget.value as TestingLabQuestionnaireQuestionType })}
                className="flex h-9 w-full rounded-md border border-input bg-background px-3 text-sm"
              >
                <option value="FreeText">Free text</option>
                <option value="SingleChoice">Single choice</option>
                <option value="MultipleChoice">Multiple choice</option>
              </select>
            </div>
          </div>
          <label className="flex items-center gap-2 text-sm">
            <input type="checkbox" checked={question.required ?? false} onChange={(event) => updateQuestion(index, { required: event.currentTarget.checked })} />
            Required question
          </label>

          {question.type !== 'FreeText' ? (
            <div className="space-y-2">
              <Label>Options</Label>
              {questionOptions.map((option, optionIndex) => (
                <div key={option.id ?? optionIndex} className="flex gap-2">
                  <Input
                    value={option.label ?? ''}
                    aria-label={`Option ${optionIndex + 1}`}
                    onChange={(event) => {
                      const options = [...questionOptions];
                      options[optionIndex] = { ...option, label: event.currentTarget.value };
                      updateQuestion(index, { options });
                    }}
                  />
                  <Button type="button" variant="ghost" size="icon-sm" aria-label="Delete option" onClick={() => updateQuestion(index, { options: questionOptions.filter((_, candidate) => candidate !== optionIndex) })}><Trash2 /></Button>
                </div>
              ))}
              <Button type="button" variant="outline" size="sm" onClick={() => updateQuestion(index, { options: [...questionOptions, { id: stableId('option'), label: '' }] })}>
                <Plus className="mr-2 size-4" /> Add option
              </Button>
            </div>
          ) : null}

          {index > 0 ? (
            <div className="space-y-2 border-t pt-3">
              <Label htmlFor={`condition-source-${question.id}`}>Show condition (optional)</Label>
              <div className="grid gap-2 sm:grid-cols-3">
                <select
                  id={`condition-source-${question.id}`}
                  value={question.condition?.questionId ?? ''}
                  onChange={(event) => updateQuestion(index, { condition: event.currentTarget.value ? { questionId: event.currentTarget.value, operator: question.condition?.operator ?? 'Equals', value: question.condition?.value ?? '' } : undefined })}
                  className="flex h-9 rounded-md border border-input bg-background px-3 text-sm"
                >
                  <option value="">Always show</option>
                  {questions.slice(0, index).flatMap((source) => source.id
                    ? [<option key={source.id} value={source.id}>{source.prompt || source.id}</option>]
                    : [])}
                </select>
                <select
                  value={question.condition?.operator ?? 'Equals'}
                  disabled={!question.condition}
                  onChange={(event) => question.condition && updateQuestion(index, { condition: { ...question.condition, operator: event.currentTarget.value as TestingLabQuestionnaireConditionOperator } })}
                  className="flex h-9 rounded-md border border-input bg-background px-3 text-sm"
                >
                  <option value="Equals">equals</option>
                  <option value="NotEquals">does not equal</option>
                  <option value="Includes">includes</option>
                </select>
                <Input
                  value={question.condition?.value ?? ''}
                  disabled={!question.condition}
                  placeholder="Answer or option ID"
                  onChange={(event) => question.condition && updateQuestion(index, { condition: { ...question.condition, value: event.currentTarget.value } })}
                />
              </div>
            </div>
          ) : null}
        </section>
        );
      })}

      <div className="flex flex-wrap gap-2">
        <Button
          type="button"
          variant="outline"
          onClick={() => onChange({
            ...value,
            questions: [...questions, { id: stableId('question'), prompt: '', type: 'FreeText', required: true, options: [] }],
          })}
        >
          <Plus className="mr-2 size-4" /> Add question
        </Button>
        <Button type="button" variant="ghost" disabled={questions.length === 0} onClick={() => setPreview(true)}>
          <Eye className="mr-2 size-4" /> Preview
        </Button>
      </div>
      {required && questions.length === 0 ? <p className="text-sm text-destructive">Add at least one feedback question.</p> : null}
    </div>
  );
}

'use client';

import type {
  TestingLabQuestionnaireAnswer,
  TestingLabQuestionnaireOutput,
  TestingLabQuestionnaireQuestion,
  TestingLabQuestionnaireSchema,
} from '@game-guild/client';
import {
  Questionnaire,
  QuestionnaireActions,
  QuestionnaireChoice,
  QuestionnaireChoices,
  QuestionnaireError,
  QuestionnaireInput,
  QuestionnaireItem,
  QuestionnaireNext,
  QuestionnairePrevious,
  QuestionnaireProgress,
  QuestionnaireSkip,
  QuestionnaireSubmit,
  QuestionnaireTitle,
} from '@game-guild/ui/components/questionnaire';

function valuesFor(answer?: TestingLabQuestionnaireAnswer) {
  const selectedOptionIds = answer?.selectedOptionIds ?? [];
  if (selectedOptionIds.length > 0) return selectedOptionIds;
  const textValue = answer?.textValue?.trim();
  return textValue ? [textValue] : [];
}

function isActive(question: TestingLabQuestionnaireQuestion, answers: TestingLabQuestionnaireAnswer[]) {
  const condition = question.condition;
  if (!condition?.questionId || !condition.value) return true;
  const sourceValues = valuesFor(answers.find((answer) => answer.questionId === condition.questionId));
  const contains = sourceValues.includes(condition.value);
  if (condition.operator === 'NotEquals') return sourceValues.length > 0 && !contains;
  if (condition.operator === 'Equals') return sourceValues.length === 1 && contains;
  return contains;
}

function setAnswer(
  output: TestingLabQuestionnaireOutput,
  questionId: string,
  answer: Omit<TestingLabQuestionnaireAnswer, 'questionId'>,
) {
  const answers = [...(output.answers ?? [])];
  const index = answers.findIndex((candidate) => candidate.questionId === questionId);
  const next = { questionId, ...answer };
  if (index >= 0) answers[index] = next;
  else answers.push(next);
  return { answers } satisfies TestingLabQuestionnaireOutput;
}

export function QuestionnaireFieldset({
  schema,
  value,
  onChange,
  onComplete,
  submitLabel = 'Continue',
  description,
}: {
  schema?: TestingLabQuestionnaireSchema | null;
  value: TestingLabQuestionnaireOutput;
  onChange: (value: TestingLabQuestionnaireOutput) => void;
  onComplete?: () => void;
  submitLabel?: string;
  description?: string;
}) {
  const questions = (schema?.questions ?? []).filter(
    (question): question is TestingLabQuestionnaireQuestion & { id: string } =>
      Boolean(question.id) && isActive(question, value.answers ?? []),
  );

  if (questions.length === 0) {
    return (
      <div className="space-y-3 rounded-md border border-dashed p-4 text-sm text-muted-foreground">
        <p>This questionnaire has no questions.</p>
        {onComplete ? <button type="button" className="text-sm font-medium text-foreground underline underline-offset-4" onClick={onComplete}>{submitLabel}</button> : null}
      </div>
    );
  }

  return (
    <Questionnaire
      items={questions.map((question) => ({
        name: question.id,
        required: question.required,
        choices: (question.options ?? []).flatMap((option) =>
          option.id ? [{ value: option.id }] : [],
        ),
      }))}
      shortcuts="letters"
      onSubmit={(event) => {
        event.preventDefault();
        onComplete?.();
      }}
    >
      <div className="flex items-center justify-between gap-3 text-xs text-muted-foreground">
        <span>{schema?.title || 'Questionnaire'}</span>
        <QuestionnaireProgress>
          {questions.length} {questions.length === 1 ? 'question' : 'questions'}
        </QuestionnaireProgress>
      </div>
      {description ? <p className="text-sm text-pretty text-muted-foreground">{description}</p> : null}
      {questions.map((question) => {
        const answer = value.answers?.find((candidate) => candidate.questionId === question.id);
        const selected = answer?.selectedOptionIds ?? [];
        const multiple = question.type === 'MultipleChoice';
        return (
          <QuestionnaireItem
            key={question.id}
            name={question.id}
            required={question.required}
            multiple={multiple}
          >
            <QuestionnaireTitle>
              {question.prompt}
              {question.required ? <span className="ml-1 text-destructive" aria-hidden="true">*</span> : null}
            </QuestionnaireTitle>
            {question.type === 'FreeText' ? (
              <QuestionnaireInput
                aria-label={question.prompt ?? question.id}
                value={answer?.textValue ?? ''}
                placeholder="Type your answer"
                onChange={(event) =>
                  onChange(setAnswer(value, question.id, { textValue: event.currentTarget.value, selectedOptionIds: [] }))
                }
              />
            ) : (
              <QuestionnaireChoices>
                {(question.options ?? []).map((option) =>
                  option.id ? (
                    <QuestionnaireChoice
                      key={option.id}
                      value={option.id}
                      checked={selected.includes(option.id)}
                      onChange={(event) => {
                        const nextSelected = multiple
                          ? event.currentTarget.checked
                            ? [...selected, option.id!]
                            : selected.filter((id) => id !== option.id)
                          : [option.id!];
                        onChange(setAnswer(value, question.id, { textValue: null, selectedOptionIds: nextSelected }));
                      }}
                    >
                      {option.label || option.id}
                    </QuestionnaireChoice>
                  ) : null,
                )}
              </QuestionnaireChoices>
            )}
            <QuestionnaireError>Please answer this required question.</QuestionnaireError>
          </QuestionnaireItem>
        );
      })}
      <QuestionnaireActions>
        <QuestionnairePrevious>Previous</QuestionnairePrevious>
        <QuestionnaireSkip>Skip</QuestionnaireSkip>
        <QuestionnaireNext>Next</QuestionnaireNext>
        <QuestionnaireSubmit>{submitLabel}</QuestionnaireSubmit>
      </QuestionnaireActions>
    </Questionnaire>
  );
}

'use client';

import { configureTestingEvent } from '@/lib/testing-lab/events-actions';
import type {
  TestingLabQuestionnaireSchema,
  TestingLabTestingEventConfigurationProjection,
  TestingLabTestingEventStatus,
} from '@game-guild/client';
import { Alert, AlertDescription } from '@game-guild/ui/components/alert';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { Label } from '@game-guild/ui/components/label';
import { Textarea } from '@game-guild/ui/components/textarea';
import { AlertCircle, CheckCircle2, FileLock2, Loader2 } from 'lucide-react';
import { useState, useTransition, type FormEvent } from 'react';
import { useRouter } from 'next/navigation';
import { QuestionnaireBuilder } from './questionnaire-builder';

function emptySchema(title: string): TestingLabQuestionnaireSchema {
  return { title, questions: [] };
}

export function TestingEventConfigurationEditor({
  eventId,
  status,
  configuration,
}: {
  eventId: string;
  status?: TestingLabTestingEventStatus;
  configuration?: TestingLabTestingEventConfigurationProjection;
}) {
  const editable = (status ?? 'Draft') === 'Draft';
  const router = useRouter();
  const [applicationSchema, setApplicationSchema] = useState<TestingLabQuestionnaireSchema>(
    configuration?.projectApplicationSchema ?? emptySchema('Project application'),
  );
  const [registrationSchema, setRegistrationSchema] = useState<TestingLabQuestionnaireSchema>(
    configuration?.testerRegistrationSchema ?? emptySchema('Tester registration'),
  );
  const [pending, startTransition] = useTransition();
  const [result, setResult] = useState<Awaited<ReturnType<typeof configureTestingEvent>> | null>(null);

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    formData.set('projectApplicationSchemaJson', JSON.stringify(applicationSchema));
    formData.set('testerRegistrationSchemaJson', JSON.stringify(registrationSchema));
    startTransition(async () => {
      try {
        const saved = await configureTestingEvent(formData);
        setResult(saved);
        if (saved.success) router.refresh();
      } catch (error) {
        setResult({
          success: false,
          error:
            error instanceof Error
              ? error.message
              : 'The Testing Lab operation failed.',
        });
      }
    });
  }

  if (!editable) {
    return (
      <section className="space-y-5 rounded-md border p-5" aria-labelledby="event-configuration-heading">
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div>
            <h2 id="event-configuration-heading" className="font-semibold">Rules, instructions, and forms</h2>
            <p className="mt-1 text-sm text-muted-foreground">This snapshot was frozen when applications opened.</p>
          </div>
          <Badge variant="secondary"><FileLock2 className="mr-1 size-3.5" /> Frozen</Badge>
        </div>
        <div className="grid gap-5 lg:grid-cols-3">
          <ReadOnlyText title="General rules" value={configuration?.generalRules} />
          <ReadOnlyText title="Game submission instructions" value={configuration?.candidateInstructions} />
          <ReadOnlyText title="Tester instructions" value={configuration?.testerInstructions} />
        </div>
        <dl className="grid gap-3 rounded-md bg-muted/40 p-4 text-sm sm:grid-cols-2">
          <div><dt className="text-muted-foreground">Project application form</dt><dd className="font-medium">{configuration?.projectApplicationSchema?.questions?.length ?? 0} questions</dd></div>
          <div><dt className="text-muted-foreground">Tester registration form</dt><dd className="font-medium">{configuration?.testerRegistrationSchema?.questions?.length ?? 0} questions</dd></div>
          {configuration?.sourceTemplateRevisionId ? <div className="sm:col-span-2"><dt className="text-muted-foreground">Template revision</dt><dd className="font-mono text-xs">{configuration.sourceTemplateRevisionId}</dd></div> : null}
        </dl>
      </section>
    );
  }

  return (
    <form className="space-y-8 rounded-md border p-5" onSubmit={submit}>
      <input type="hidden" name="eventId" value={eventId} />
      <div>
        <h2 id="event-configuration-heading" className="font-semibold">Rules, instructions, and forms</h2>
        <p className="mt-1 text-sm text-muted-foreground">Save the participation rules before publishing. These rules stay fixed once sign-ups open.</p>
      </div>
      <section className="grid gap-4 lg:grid-cols-3" aria-labelledby="event-copy-heading">
        <h3 id="event-copy-heading" className="sr-only">Event copy</h3>
        <TextField name="generalRules" label="General rules" defaultValue={configuration?.generalRules} placeholder="Participation, conduct, confidentiality, and completion rules." />
        <TextField name="candidateInstructions" label="Game submission instructions" defaultValue={configuration?.candidateInstructions} placeholder="What creators need to prepare before submitting a game." />
        <TextField name="testerInstructions" label="Tester instructions" defaultValue={configuration?.testerInstructions} placeholder="What assigned testers must do during and after the session." />
      </section>
      <details className="space-y-4 border-t pt-5">
        <summary className="cursor-pointer text-sm font-medium">Sign-up questions <span className="font-normal text-muted-foreground">· optional</span></summary>
        <div className="grid gap-6 lg:grid-cols-2">
          <section className="space-y-3" aria-labelledby="application-form-heading">
            <div><h3 id="application-form-heading" className="font-medium">Project application form</h3><p className="text-sm text-muted-foreground">Ask creators for any extra information you need.</p></div>
            <QuestionnaireBuilder value={applicationSchema} onChange={setApplicationSchema} />
          </section>
          <section className="space-y-3" aria-labelledby="registration-form-heading">
            <div><h3 id="registration-form-heading" className="font-medium">Tester registration form</h3><p className="text-sm text-muted-foreground">Ask testers for any extra information you need.</p></div>
            <QuestionnaireBuilder value={registrationSchema} onChange={setRegistrationSchema} />
          </section>
        </div>
      </details>
      <div className="flex flex-wrap items-center gap-3 border-t pt-5">
        <Button type="submit" disabled={pending}>{pending ? <Loader2 className="mr-2 size-4 animate-spin" /> : null}Save draft configuration</Button>
        <p className="text-xs text-muted-foreground">After saving, use “Publish and open sign-ups” above.</p>
      </div>
      {result ? <Alert variant={result.success ? 'default' : 'destructive'}>{result.success ? <CheckCircle2 className="size-4" /> : <AlertCircle className="size-4" />}<AlertDescription>{result.success ? result.message : result.error}</AlertDescription></Alert> : null}
    </form>
  );
}

function TextField({ name, label, defaultValue, placeholder }: { name: string; label: string; defaultValue?: string | null; placeholder: string }) {
  return <div className="space-y-2"><Label htmlFor={`event-${name}`}>{label}</Label><Textarea id={`event-${name}`} name={name} rows={8} defaultValue={defaultValue ?? ''} placeholder={placeholder} required /></div>;
}

function ReadOnlyText({ title, value }: { title: string; value?: string | null }) {
  return <div><h3 className="text-sm font-medium">{title}</h3><p className="mt-2 whitespace-pre-wrap text-sm text-muted-foreground">{value || 'Not provided'}</p></div>;
}

"use client";

import { usePathname, useRouter } from "@/i18n/navigation";
import type { TestingLabTestingEventStatus } from "@game-guild/client";
import { Button } from "@game-guild/ui/components/button";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@game-guild/ui/components/input-group";
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@game-guild/ui/components/select";
import { ArrowRight, ListFilter, Search, X } from "lucide-react";
import { type FormEvent, useState, useTransition } from "react";

type DirectoryFilter = TestingLabTestingEventStatus | "all" | "archived";

const filterOptions: Array<{ value: DirectoryFilter; label: string }> = [
  { value: "all", label: "All statuses" },
  { value: "Draft", label: "Draft" },
  { value: "ApplicationsOpen", label: "Applications open" },
  { value: "ApplicationsClosed", label: "Applications closed" },
  { value: "Scheduled", label: "Scheduled" },
  { value: "Active", label: "Active" },
  { value: "Completed", label: "Completed" },
  { value: "Cancelled", label: "Cancelled" },
  { value: "archived", label: "Archived" },
];

export function TestingEventDirectoryFilters({
  search,
  status,
  archived = false,
}: {
  search?: string;
  status?: TestingLabTestingEventStatus;
  archived?: boolean;
}) {
  const pathname = usePathname();
  const router = useRouter();
  const [query, setQuery] = useState(search ?? "");
  const [isPending, startTransition] = useTransition();
  const selectedFilter: DirectoryFilter = archived ? "archived" : status ?? "all";
  const hasFilters = Boolean(search || status || archived);

  function navigate(nextSearch: string, nextFilter: DirectoryFilter) {
    const params = new URLSearchParams();
    const normalizedSearch = nextSearch.trim();

    if (normalizedSearch) params.set("q", normalizedSearch);
    if (nextFilter === "archived") params.set("archived", "true");
    else if (nextFilter !== "all") params.set("status", nextFilter);

    const suffix = params.toString();
    const destination = suffix ? `${pathname}?${suffix}` : pathname;
    startTransition(() => router.replace(destination));
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    navigate(query, selectedFilter);
  }

  return (
    <div className="flex flex-col gap-2 sm:flex-row sm:items-center">
      <form onSubmit={handleSubmit} className="min-w-0 flex-1 sm:max-w-md">
        <InputGroup>
          <InputGroupInput
            type="search"
            aria-label="Search testing events"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Search events"
            disabled={isPending}
          />
          <InputGroupAddon>
            <Search aria-hidden="true" />
          </InputGroupAddon>
          <InputGroupAddon align="inline-end">
            <InputGroupButton
              type="submit"
              size="icon-xs"
              aria-label="Run event search"
              disabled={isPending}
            >
              <ArrowRight aria-hidden="true" />
            </InputGroupButton>
          </InputGroupAddon>
        </InputGroup>
      </form>

      <div className="flex items-center gap-1">
        <Select
          items={filterOptions}
          value={selectedFilter}
          onValueChange={(value) => navigate(query, value as DirectoryFilter)}
          disabled={isPending}
        >
          <SelectTrigger
            size="default"
            className="w-full sm:w-48"
            aria-label="Filter testing events by status"
          >
            <ListFilter aria-hidden="true" />
            <SelectValue />
          </SelectTrigger>
          <SelectContent alignItemWithTrigger={false}>
            <SelectGroup>
              {filterOptions.map((option) => (
                <SelectItem key={option.value} value={option.value}>
                  {option.label}
                </SelectItem>
              ))}
            </SelectGroup>
          </SelectContent>
        </Select>

        {hasFilters ? (
          <Button
            type="button"
            variant="ghost"
            size="icon"
            aria-label="Clear event filters"
            title="Clear filters"
            disabled={isPending}
            onClick={() => {
              setQuery("");
              navigate("", "all");
            }}
          >
            <X aria-hidden="true" />
          </Button>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import type { TestingLabPublicTestingEventGameProjection } from "@game-guild/client";
import { Badge } from "@game-guild/ui/components/badge";
import { Link } from "@/i18n/navigation";
import { ArrowLeft, ArrowRight, Gamepad2 } from "lucide-react";
import Image from "next/image";
import { useEffect, useState, type ReactNode } from "react";

type GameApplicationSummary = {
  id: string;
  projectId?: string | null;
  title: string;
  status: string;
};

function GameArtwork({
  game,
  alt,
  className,
}: {
  game: TestingLabPublicTestingEventGameProjection;
  alt: string;
  className: string;
}) {
  return (
    <div className={"relative shrink-0 overflow-hidden bg-muted " + className}>
      {game.imageUrl ? (
        <Image
          src={game.imageUrl}
          alt={alt}
          fill
          sizes="(max-width: 1024px) 100vw, calc(100vw - 38rem)"
          unoptimized
          className="object-cover"
        />
      ) : (
        <div
          aria-hidden="true"
          className="absolute inset-0 grid place-items-center bg-muted/80"
        >
          <Gamepad2 className="size-12 text-muted-foreground/60" />
        </div>
      )}
    </div>
  );
}

function gameTitle(game: TestingLabPublicTestingEventGameProjection) {
  return game.title?.trim() || "Untitled game";
}

function gameDescription(game: TestingLabPublicTestingEventGameProjection) {
  return game.description?.trim() || game.shortDescription?.trim() || null;
}

export function TestingEventGames({
  games,
  eventId,
  applications = [],
  emptyState,
  children,
}: {
  games: readonly TestingLabPublicTestingEventGameProjection[];
  eventId: string;
  applications?: readonly GameApplicationSummary[];
  emptyState?: ReactNode;
  children?: ReactNode;
}) {
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [carouselPaused, setCarouselPaused] = useState(false);
  const [reducedMotion, setReducedMotion] = useState(false);
  const selectedGame = games[selectedIndex];

  useEffect(() => {
    if (typeof window.matchMedia !== "function") return;
    const motionPreference = window.matchMedia("(prefers-reduced-motion: reduce)");
    const syncPreference = () => setReducedMotion(motionPreference.matches);
    syncPreference();
    motionPreference.addEventListener?.("change", syncPreference);
    return () => motionPreference.removeEventListener?.("change", syncPreference);
  }, []);

  useEffect(() => {
    if (games.length < 2 || carouselPaused || reducedMotion) return;
    const timer = window.setInterval(() => {
      setSelectedIndex((current) => (current + 1) % games.length);
    }, 7000);
    return () => window.clearInterval(timer);
  }, [games.length, carouselPaused, reducedMotion]);

  const applicationsByProjectId = new Map(
    applications.flatMap((application) =>
      application.projectId
        ? [[application.projectId, application] as const]
        : [],
    ),
  );
  const publishedProjectIds = new Set(
    games.flatMap((game) => (game.projectId ? [game.projectId] : [])),
  );
  const unlistedApplications = applications.filter(
    (application) =>
      !application.projectId || !publishedProjectIds.has(application.projectId),
  );

  const showPreviousGame = () => {
    setSelectedIndex((current) =>
      current === 0 ? games.length - 1 : current - 1,
    );
  };
  const showNextGame = () => {
    setSelectedIndex((current) => (current + 1) % games.length);
  };

  return (
    <section
      aria-label="Game content"
      className="order-1 min-w-0 pl-4 pt-0 sm:pl-6 lg:order-none lg:col-start-2 lg:row-start-1 lg:pl-0 lg:pt-0"
    >
      {selectedGame ? (
        <section
          id="event-hero"
          role="region"
          aria-label={"Featured game: " + gameTitle(selectedGame)}
          aria-roledescription="carousel"
          onMouseEnter={() => setCarouselPaused(true)}
          onMouseLeave={() => setCarouselPaused(false)}
          onFocusCapture={() => setCarouselPaused(true)}
          onBlurCapture={(event) => {
            if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
              setCarouselPaused(false);
            }
          }}
          className="relative isolate h-[62vh] min-h-[24rem] max-h-[52rem] overflow-hidden bg-neutral-950 sm:h-[68vh]"
        >
          <div className="absolute inset-0">
            <GameArtwork
              game={selectedGame}
              alt={"Artwork for " + gameTitle(selectedGame)}
              className="h-full w-full"
            />
          </div>
          <div
            aria-hidden="true"
            className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/20 to-transparent"
          />

          <div className="absolute left-5 top-5 rounded-full border border-white/25 bg-black/55 px-3 py-1 text-xs font-medium text-white backdrop-blur-sm">
            {String(selectedIndex + 1).padStart(2, "0")} /{" "}
            {String(games.length).padStart(2, "0")}
          </div>

          <div
            aria-live={carouselPaused ? "polite" : "off"}
            aria-atomic="true"
            className="absolute inset-x-0 bottom-0 px-6 pb-7 pt-20 text-white sm:px-10 sm:pb-10"
          >
            <h2 className="max-w-4xl text-3xl font-semibold leading-tight tracking-tight sm:text-5xl">
              {gameTitle(selectedGame)}
            </h2>
            {gameDescription(selectedGame) ? (
              <p className="mt-3 max-w-3xl whitespace-pre-line text-sm leading-6 text-white/90 sm:text-base">
                {gameDescription(selectedGame)}
              </p>
            ) : null}
          </div>

          {games.length > 1 ? (
            <>
              <button
                type="button"
                aria-label="Previous game"
                onClick={showPreviousGame}
                className="absolute left-3 top-1/2 grid size-11 -translate-y-1/2 place-items-center rounded-full border border-white/35 bg-black/55 text-white backdrop-blur transition hover:bg-black/80 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white sm:left-5"
              >
                <ArrowLeft className="size-5" aria-hidden="true" />
              </button>
              <button
                type="button"
                aria-label="Next game"
                onClick={showNextGame}
                className="absolute right-3 top-1/2 grid size-11 -translate-y-1/2 place-items-center rounded-full border border-white/35 bg-black/55 text-white backdrop-blur transition hover:bg-black/80 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white sm:right-5"
              >
                <ArrowRight className="size-5" aria-hidden="true" />
              </button>
            </>
          ) : null}
        </section>
      ) : emptyState ? (
        <div className="grid min-h-72 place-items-center border-y border-border p-8 text-center">
          {emptyState}
        </div>
      ) : null}

      {games.length > 0 || unlistedApplications.length > 0 ? (
        <ol
          aria-label="Games and submissions"
          className="mt-6 divide-y divide-border border-t border-border"
        >
          {games.map((game, index) => {
            const title = gameTitle(game);
            const description = gameDescription(game);
            const selected = selectedIndex === index;
            const application = game.projectId
              ? applicationsByProjectId.get(game.projectId)
              : undefined;
            const applicationHref = application?.projectId
              ? `/testing-lab/events/${eventId}?joinAs=developer&applicationId=${encodeURIComponent(application.id)}&projectId=${encodeURIComponent(application.projectId)}#join`
              : "#join";

            return (
              <li
                key={game.projectId ?? title + "-" + index}
                className="py-2 first:pt-1 last:pb-1"
              >
                <button
                  type="button"
                  aria-label={"Show " + title + " in carousel"}
                  aria-current={selected ? "true" : undefined}
                  onClick={() => setSelectedIndex(index)}
                  className={
                    "grid w-full grid-cols-[4rem_minmax(0,1fr)] items-center gap-3 py-2 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring " +
                    (selected ? "text-foreground" : "text-muted-foreground")
                  }
                >
                  <GameArtwork
                    game={game}
                    alt=""
                    className="aspect-square w-16 rounded-sm"
                  />
                  <span className="min-w-0">
                    <span className="block text-sm font-semibold leading-5">
                      {title}
                    </span>
                    {description ? (
                      <span className="mt-1 block line-clamp-3 text-sm leading-5">
                        {description}
                      </span>
                    ) : null}
                  </span>
                </button>
                {application ? (
                  <div className="ml-[4.75rem] flex flex-wrap items-center gap-x-2 gap-y-1 pb-2 text-xs">
                    <Badge variant="outline">Your game</Badge>
                    <Badge variant="secondary">{application.status}</Badge>
                    <Link
                      href={applicationHref}
                      aria-label={`Review ${title} application`}
                      className="min-h-8 inline-flex items-center font-medium text-primary underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      Manage submission
                    </Link>
                  </div>
                ) : null}
              </li>
            );
          })}
          {unlistedApplications.map((application) => {
            const applicationHref = application.projectId
              ? `/testing-lab/events/${eventId}?joinAs=developer&applicationId=${encodeURIComponent(application.id)}&projectId=${encodeURIComponent(application.projectId)}#join`
              : `/testing-lab/events/${eventId}?joinAs=developer&applicationId=${encodeURIComponent(application.id)}#join`;

            return (
              <li
                key={`submission-${application.id}`}
                className="flex flex-wrap items-start justify-between gap-3 py-3"
              >
                <div className="min-w-0">
                  <p className="text-sm font-semibold">{application.title}</p>
                  <p className="text-xs text-muted-foreground">
                    Your game submission
                  </p>
                </div>
                <div className="flex items-center gap-3">
                  <Badge variant="secondary">{application.status}</Badge>
                  <Link
                    href={applicationHref}
                    aria-label={`Review ${application.title} application`}
                    className="min-h-8 inline-flex items-center text-sm font-medium text-primary underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    Manage
                  </Link>
                </div>
              </li>
            );
          })}
        </ol>
      ) : null}
      {children}
    </section>
  );
}

'use client';

import { TestingProjectApplication } from '@/components/testing-lab/testing-project-application';
import { TestingSlotRegistration } from '@/components/testing-lab/testing-slot-registration';
import { Button } from '@game-guild/ui/components/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@game-guild/ui/components/dialog';
import { ArrowLeft, ArrowRight, FolderKanban, Gamepad2 } from 'lucide-react';
import { Link } from '@/i18n/navigation';
import { useState, type ComponentProps } from 'react';

type RegistrationProps = ComponentProps<typeof TestingSlotRegistration>;
type ProjectApplicationFlowProps = Pick<
  ComponentProps<typeof TestingProjectApplication>,
  | 'acceptsApplications'
  | 'projectVersions'
  | 'applications'
  | 'applicationSchema'
  | 'generalRules'
  | 'candidateInstructions'
  | 'requiresFeedback'
  | 'initialProjectId'
  | 'selectedApplicationId'
>;

interface TesterSessionOption {
  id: string;
  label: string;
  slot: RegistrationProps['slot'];
  registration?: RegistrationProps['registration'];
  registrationOpen: boolean;
}

type JoinStep = 'roles' | 'tester-sessions' | 'tester-form' | 'developer-form';

export function TestingEventJoin({
  eventId,
  isAuthenticated,
  testerSessions,
  testerUnavailableReason,
  testerRegistrationSchema,
  generalRules,
  testerInstructions,
  timeZoneId,
  locale,
  hour12,
  projectApplication,
  initialMode,
  initialSlotId,
  initialProjectId,
  selectedApplicationId,
}: {
  eventId: string;
  isAuthenticated: boolean;
  testerSessions: TesterSessionOption[];
  testerUnavailableReason: string;
  testerRegistrationSchema?: RegistrationProps['registrationSchema'];
  generalRules?: string | null;
  testerInstructions?: string | null;
  timeZoneId: string;
  locale: string;
  hour12: boolean;
  projectApplication: ProjectApplicationFlowProps;
  initialMode?: 'tester' | 'developer';
  initialSlotId?: string;
  initialProjectId?: string;
  selectedApplicationId?: string;
}) {
  const initialSession = initialSlotId
    ? testerSessions.find((session) => session.id === initialSlotId)
    : undefined;
  const canJoinAsTester = testerSessions.some((session) => session.registrationOpen);
  const hasExistingSubmission = projectApplication.applications?.some((application) =>
    selectedApplicationId
      ? application.id === selectedApplicationId
      : Boolean(initialProjectId && application.projectId === initialProjectId),
  ) ?? false;
  const canJoinAsDeveloper = projectApplication.acceptsApplications || hasExistingSubmission;
  const canStartJoin = canJoinAsTester || canJoinAsDeveloper;
  const validInitialMode = initialMode === 'developer' && canJoinAsDeveloper
    ? 'developer'
    : initialMode === 'tester' && initialSession?.registrationOpen
      ? 'tester'
      : undefined;
  const [open, setOpen] = useState(Boolean(validInitialMode));
  const [step, setStep] = useState<JoinStep>(() =>
    validInitialMode === 'developer'
      ? 'developer-form'
      : validInitialMode === 'tester'
        ? 'tester-form'
        : 'roles',
  );
  const [selectedTesterSessionId, setSelectedTesterSessionId] = useState(initialSession?.id ?? '');
  const [hasStartedProjectFlow, setHasStartedProjectFlow] = useState(validInitialMode === 'developer');

  const selectedTesterSession = testerSessions.find((session) => session.id === selectedTesterSessionId);
  const projectSignInReturnUrl = `/testing-lab/events/${eventId}?joinAs=developer${initialProjectId ? `&projectId=${encodeURIComponent(initialProjectId)}` : ''}${selectedApplicationId ? `&applicationId=${encodeURIComponent(selectedApplicationId)}` : ''}#join`;

  function resetAndOpen() {
    setStep('roles');
    setSelectedTesterSessionId('');
    setHasStartedProjectFlow(false);
    setOpen(true);
  }

  function startTesterFlow() {
    if (!canJoinAsTester) return;
    if (testerSessions.filter((session) => session.registrationOpen).length > 1) {
      setStep('tester-sessions');
      return;
    }
    const session = testerSessions.find((item) => item.registrationOpen);
    if (!session) return;
    setSelectedTesterSessionId(session.id);
    setStep('tester-form');
  }

  function startDeveloperFlow() {
    if (!canJoinAsDeveloper) return;
    setHasStartedProjectFlow(true);
    setStep('developer-form');
  }

  function closeDialog(nextOpen: boolean) {
    setOpen(nextOpen);
    if (!nextOpen) {
      setStep('roles');
      setSelectedTesterSessionId('');
      setHasStartedProjectFlow(false);
    }
  }

  const title = step === 'roles'
    ? 'How would you like to join?'
    : step === 'tester-sessions'
      ? 'Choose a session'
      : step === 'tester-form'
        ? 'Join as a tester'
        : 'Submit a game';
  const description = step === 'tester-sessions'
    ? 'Choose the session you want to join.'
    : step === 'tester-form'
      ? selectedTesterSession?.label
      : step === 'developer-form'
        ? 'Choose a game and build to submit for testing.'
        : undefined;
  const contentWidth = step === 'developer-form' ? 'sm:max-w-2xl' : step === 'tester-form' ? 'sm:max-w-xl' : 'sm:max-w-md';

  return (
    <div id="join" className="grid scroll-mt-6 gap-3 border-t border-border pt-4">
      <Button className="w-full" disabled={!canStartJoin} onClick={resetAndOpen}>
