import {
  AlertCircle,
  Archive,
  CheckCircle2,
  Loader2,
  Plus,
  RotateCcw,
} from 'lucide-react';
import { useState, useTransition, type FormEvent } from 'react';
import { QuestionnaireBuilder } from './questionnaire-builder';

function emptySchema(title: string): TestingLabQuestionnaireSchema {
  return { title, questions: [] };
}

export function TestingEventTemplateManagement({
  templates,
}: {
  templates: TestingLabTestingEventTemplateProjection[];
}) {
  const [selectedId, setSelectedId] = useState<string | null>(
    templates.find((template) => !template.isArchived)?.id ?? null,
  );
  const selected =
    templates.find((template) => template.id === selectedId) ?? null;

  return (
    <div className="grid gap-8 xl:grid-cols-[240px_minmax(0,1fr)]">
      <aside className="flex flex-col gap-3">
        <Button
          type="button"
          variant={selectedId === null ? 'secondary' : 'outline'}
          className="w-full justify-start"
          onClick={() => setSelectedId(null)}
        >
          <Plus data-icon="inline-start" />
          New calendar
        </Button>
        <div className="flex flex-col gap-1" aria-label="Event calendars">
          {templates.map((template) => (
            <button
              key={template.id}
              type="button"
              onClick={() => setSelectedId(template.id ?? null)}
              className={cn(
                'w-full rounded-md px-3 py-2.5 text-left transition-colors',
                selectedId === template.id
                  ? 'bg-accent text-accent-foreground'
                  : 'hover:bg-muted/50',
              )}
            >
              <span className="flex items-center justify-between gap-2">
                <span className="truncate text-sm font-medium">
                  {template.name || 'Untitled calendar'}
                </span>
                {template.isArchived ? (
                  <Badge variant="outline">Archived</Badge>
                ) : null}
              </span>
              <span className="mt-1 block text-xs text-muted-foreground">
                Revision {template.currentRevisionNumber ?? 1}
              </span>
            </button>
          ))}
          {templates.length === 0 ? (
            <p className="px-3 py-4 text-sm text-muted-foreground">
              No calendars yet. Create one to group events and reuse defaults.
            </p>
          ) : null}
        </div>
      </aside>
      <TemplateEditor key={selected?.id ?? 'new'} template={selected} />
    </div>
  );
}

function TemplateEditor({
  template,
}: {
  template: TestingLabTestingEventTemplateProjection | null;
}) {
  const revision = template?.currentRevision;
  const [applicationSchema, setApplicationSchema] =
    useState<TestingLabQuestionnaireSchema>(
      revision?.projectApplicationSchema ?? emptySchema('Project application'),
    );
  const [registrationSchema, setRegistrationSchema] =
    useState<TestingLabQuestionnaireSchema>(
      revision?.testerRegistrationSchema ?? emptySchema('Tester registration'),
    );
  const [pending, startTransition] = useTransition();
  const [result, setResult] = useState<
    Awaited<ReturnType<typeof saveTestingEventTemplate>> | null
  >(null);
  const router = useRouter();

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    formData.set(
      'projectApplicationSchemaJson',
      JSON.stringify(applicationSchema),
    );
    formData.set(
      'testerRegistrationSchemaJson',
      JSON.stringify(registrationSchema),
    );
    startTransition(async () => {
      try {
        const next = await saveTestingEventTemplate(formData);
        setResult(next);
        if (next.success) router.refresh();
      } catch (error) {
        setResult({
          success: false,
          error: error instanceof Error
            ? error.message
            : 'The Testing Lab operation failed.',
        });
      }
    });
  }

  function toggleArchived() {
    if (!template?.id) return;
    const formData = new FormData();
    formData.set('templateId', template.id);
    if (template.isArchived) formData.set('restore', 'true');
    startTransition(async () => {
      try {
        const next = await setTestingEventTemplateArchived(formData);
        setResult(next);
        if (next.success) router.refresh();
      } catch (error) {
        setResult({
          success: false,
          error: error instanceof Error
            ? error.message
            : 'The Testing Lab operation failed.',
        });
      }
    });
  }

  return (
    <form className="flex max-w-4xl flex-col gap-7" onSubmit={submit}>
      {template?.id ? (
        <input type="hidden" name="templateId" value={template.id} />
      ) : null}
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="flex flex-col gap-1">
          <h2 className="font-semibold">
            {template
              ? 'Create a new calendar revision'
              : 'Create an event calendar'}
          </h2>
          <p className="text-sm text-muted-foreground">
            Events keep the selected revision, so future calendar changes never
            alter existing sessions.
          </p>
        </div>
        {template ? (
          <Button
            type="button"
            size="sm"
            variant="outline"
            disabled={pending}
            onClick={toggleArchived}
          >
            {template.isArchived ? (
              <RotateCcw data-icon="inline-start" />
            ) : (
              <Archive data-icon="inline-start" />
            )}
            {template.isArchived ? 'Restore' : 'Archive'}
          </Button>
        ) : null}
      </div>

      <Separator />

      <FieldGroup className="gap-6">
        <div className="grid gap-5 sm:grid-cols-2">
          <Field>
            <FieldLabel htmlFor="template-name">Calendar name</FieldLabel>
            <Input
              id="template-name"
              name="name"
              defaultValue={template?.name ?? ''}
              required
            />
          </Field>
          <Field>
            <FieldLabel htmlFor="template-description">
              Description
            </FieldLabel>
            <Input
              id="template-description"
              name="description"
              defaultValue={template?.description ?? ''}
            />
          </Field>
        </div>
        <Field>
          <FieldLabel htmlFor="template-rules">General rules</FieldLabel>
          <Textarea
            id="template-rules"
            name="generalRules"
            rows={3}
            defaultValue={revision?.generalRules ?? ''}
            required
          />
        </Field>
        <div className="grid gap-5 sm:grid-cols-2">
          <Field>
            <FieldLabel htmlFor="template-candidate-instructions">
              Candidate instructions
            </FieldLabel>
            <Textarea
              id="template-candidate-instructions"
              name="candidateInstructions"
              rows={3}
              defaultValue={revision?.candidateInstructions ?? ''}
              required
            />
          </Field>
          <Field>
            <FieldLabel htmlFor="template-tester-instructions">
              Tester instructions
            </FieldLabel>
            <Textarea
              id="template-tester-instructions"
              name="testerInstructions"
              rows={3}
              defaultValue={revision?.testerInstructions ?? ''}
              required
            />
          </Field>
        </div>
      </FieldGroup>

      <Separator />

      <FieldSet className="gap-5">
        <FieldLegend>Event defaults</FieldLegend>
        <div className="grid gap-5 sm:grid-cols-2">
          <Field>
            <FieldLabel htmlFor="template-mode">Event format</FieldLabel>
            <Select
              name="defaultMode"
              defaultValue={revision?.defaultMode ?? 'Online'}
            >
              <SelectTrigger id="template-mode" className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectGroup>
                  <SelectItem value="Online">Online</SelectItem>
                  <SelectItem value="InPerson">In person</SelectItem>
                  <SelectItem value="Hybrid">Hybrid</SelectItem>
                </SelectGroup>
              </SelectContent>
            </Select>
          </Field>
          <Field>
            <FieldLabel htmlFor="template-approval">
              Project review
            </FieldLabel>
            <Select
              name="defaultApprovalMode"
              defaultValue={revision?.defaultApprovalMode ?? 'ManagerOnly'}
            >
              <SelectTrigger id="template-approval" className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectGroup>
                  <SelectItem value="ManagerOnly">
                    Event managers decide
                  </SelectItem>
                  <SelectItem value="Committee">
                    Review committee votes
                  </SelectItem>
                </SelectGroup>
              </SelectContent>
            </Select>
          </Field>
        </div>
        <Field orientation="horizontal">
          <Checkbox
            id="template-feedback"
            name="defaultRequiresFeedback"
            defaultChecked={revision?.defaultRequiresFeedback ?? true}
          />
          <FieldContent>
            <FieldLabel htmlFor="template-feedback">
              Require developer feedback by default
            </FieldLabel>
            <FieldDescription>
              Attendance is completed after the required project feedback is
              submitted.
            </FieldDescription>
          </FieldContent>
        </Field>
      </FieldSet>

      <Separator />

      <section className="flex flex-col gap-4">
        <div className="flex flex-col gap-1">
          <h3 className="font-medium">Project application form</h3>
          <p className="text-sm text-muted-foreground">
            Questions for project teams applying to this calendar.
          </p>
        </div>
        <QuestionnaireBuilder
          value={applicationSchema}
          onChange={setApplicationSchema}
        />
      </section>

      <Separator />

      <section className="flex flex-col gap-4">
        <div className="flex flex-col gap-1">
          <h3 className="font-medium">Tester registration form</h3>
          <p className="text-sm text-muted-foreground">
            Questions for testers joining events in this calendar.
          </p>
        </div>
        <QuestionnaireBuilder
          value={registrationSchema}
          onChange={setRegistrationSchema}
        />
      </section>

      {result ? (
        <Alert variant={result.success ? 'default' : 'destructive'}>
          {result.success ? <CheckCircle2 /> : <AlertCircle />}
          <AlertDescription>
            {result.success ? result.message : result.error}
          </AlertDescription>
        </Alert>
      ) : null}

      <div className="flex flex-wrap items-center justify-end gap-3">
        <Button type="submit" disabled={pending || template?.isArchived}>
          {pending ? (
            <Loader2 data-icon="inline-start" className="animate-spin" />
          ) : null}
          {template ? 'Save new revision' : 'Create calendar'}
        </Button>
        {template?.isArchived ? (
          <p className="text-xs text-muted-foreground">
            Restore this calendar before creating another revision.
          </p>
        ) : null}
      </div>
    </form>
  );
}

'use client';

import { submitTestingEventFeedback, type TestingEventActionResult } from '@/lib/testing-lab/events-actions';
import type {
  TestingLabQuestionnaireOutput,
  TestingLabTestingApplicationReviewPackageProjection,
  TestingLabTestingProjectBrief,
} from '@game-guild/client';
import { Alert, AlertDescription } from '@game-guild/ui/components/alert';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { buttonVariants } from '@game-guild/ui/components/button-variants';
import { Input } from '@game-guild/ui/components/input';
import { Label } from '@game-guild/ui/components/label';
import { Textarea } from '@game-guild/ui/components/textarea';
import { AlertCircle, CheckCircle2, Loader2, MessageSquareText } from 'lucide-react';
import Link from 'next/link';
import { useState, useTransition } from 'react';
import { QuestionnaireFieldset } from './questionnaire-fieldset';

interface FeedbackObligation {
  id?: string | null;
  applicationId?: string | null;
  questionnaireRevisionId?: string | null;
  status?: string | null;
  reviewPackage?: TestingLabTestingApplicationReviewPackageProjection | null;
}
function BriefSummary({ brief }: { brief?: TestingLabTestingProjectBrief }) {
  if (!brief) return null;
  return (
    <div className="space-y-3 rounded-md border bg-muted/20 p-4 text-sm">
      <div><p className="font-medium">Test objective</p><p className="mt-1 text-muted-foreground whitespace-pre-wrap">{brief.testObjective}</p></div>
      <div><p className="font-medium">Installation and access</p><p className="mt-1 text-muted-foreground whitespace-pre-wrap">{brief.installationAndAccess}</p></div>
      <div><p className="font-medium">Tasks</p><ol className="mt-1 list-decimal space-y-1 pl-5 text-muted-foreground">{(brief.testTasks ?? []).map((task, index) => <li key={`${index}-${task}`}>{task}</li>)}</ol></div>
      <div className="grid gap-3 sm:grid-cols-2"><div><p className="font-medium">Controls</p><p className="mt-1 text-muted-foreground whitespace-pre-wrap">{brief.controls}</p></div><div><p className="font-medium">Known limitations</p><p className="mt-1 text-muted-foreground whitespace-pre-wrap">{brief.knownLimitations}</p></div></div>
    </div>
  );
}

function FeedbackForm({ eventId, obligation }: { eventId: string; obligation: FeedbackObligation }) {
  const [pending, startTransition] = useTransition();
  const [result, setResult] = useState<TestingEventActionResult<unknown> | null>(null);
  const [responses, setResponses] = useState<TestingLabQuestionnaireOutput>({ answers: [] });
  const [questionnaireComplete, setQuestionnaireComplete] = useState(false);
  const [rating, setRating] = useState('');
  const [recommendation, setRecommendation] = useState('');
  const [notes, setNotes] = useState('');
  const reviewPackage = obligation.reviewPackage;

  function submit() {
    const formData = new FormData();
    formData.set('eventId', eventId);
    formData.set('obligationId', obligation.id!);
    formData.set('questionnaireRevisionId', obligation.questionnaireRevisionId ?? '');
    formData.set('responsesJson', JSON.stringify(responses));
    formData.set('overallRating', rating);
    formData.set('wouldRecommend', String(recommendation === 'yes'));
    formData.set('additionalNotes', notes);
    startTransition(async () => {
      try {
        setResult(await submitTestingEventFeedback(formData));
      } catch (error) {
        setResult({
          success: false,
          error: error instanceof Error ? error.message : 'The Testing Lab operation failed.',
        });
      }
    });
  }

  return (
    <section className="space-y-4 rounded-md border bg-card p-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div><p className="font-medium">{reviewPackage?.versionNumber ? `Version ${reviewPackage.versionNumber}` : 'Assigned project feedback'}</p><p className="text-xs text-muted-foreground">Developer questionnaire revision {obligation.questionnaireRevisionId?.slice(0, 8)}</p></div>
        <Badge variant="secondary">Required</Badge>
      </div>
      <BriefSummary brief={reviewPackage?.brief} />
      {(reviewPackage?.assets?.length ?? 0) > 0 ? (
        <div className="space-y-2"><p className="text-sm font-medium">Test assets</p><div className="flex flex-wrap gap-2">{reviewPackage?.assets?.map((asset) => asset.accessUrl ? <a key={asset.assetReferenceId} href={asset.accessUrl} target="_blank" rel="noreferrer" className={buttonVariants({ size: 'sm', variant: 'outline' })}>{asset.displayName || 'Open asset'}</a> : null)}</div></div>
      ) : null}
      <QuestionnaireFieldset
        schema={reviewPackage?.feedbackQuestionnaire}
        value={responses}
        onChange={(value) => { setResponses(value); setQuestionnaireComplete(false); }}
        onComplete={() => setQuestionnaireComplete(true)}
        submitLabel="Confirm questionnaire answers"
      />
      <div className="grid gap-4 sm:grid-cols-2">
        <div className="space-y-2"><Label htmlFor={`rating-${obligation.id}`}>Overall rating (1–10)</Label><Input id={`rating-${obligation.id}`} value={rating} onChange={(event) => setRating(event.currentTarget.value)} type="number" min={1} max={10} required /></div>
        <div className="space-y-2"><Label htmlFor={`recommend-${obligation.id}`}>Would you recommend it?</Label><select id={`recommend-${obligation.id}`} value={recommendation} onChange={(event) => setRecommendation(event.currentTarget.value)} className="flex h-9 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Choose</option><option value="yes">Yes</option><option value="no">No</option></select></div>
      </div>
      <div className="space-y-2"><Label htmlFor={`notes-${obligation.id}`}>Additional observations (optional)</Label><Textarea id={`notes-${obligation.id}`} value={notes} onChange={(event) => setNotes(event.currentTarget.value)} rows={3} /></div>
      <Button type="button" disabled={pending || !obligation.id || !questionnaireComplete || !rating || !recommendation} onClick={submit}>
        {pending ? <Loader2 className="mr-2 size-4 animate-spin" /> : null}Submit required feedback
      </Button>
      {result ? <Alert variant={result.success ? 'default' : 'destructive'} aria-live="polite">{result.success ? <CheckCircle2 className="size-4" /> : <AlertCircle className="size-4" />}<AlertDescription>{result.success ? result.message : result.error}</AlertDescription></Alert> : null}
    </section>
  );
}

export function TestingFeedbackSubmission({ eventId, isAuthenticated, obligations }: { eventId: string; isAuthenticated: boolean; obligations: FeedbackObligation[] }) {
  const pending = obligations.filter((obligation) => obligation.status === 'Pending');
  if (!isAuthenticated && pending.length > 0) return <Link href="/sign-in" className={buttonVariants()}>Sign in to submit feedback</Link>;
  if (obligations.length === 0) return <p className="text-sm text-muted-foreground">No feedback assigned yet.</p>;
  if (pending.length === 0) return <Alert><CheckCircle2 className="size-4" /><AlertDescription>All assigned feedback is complete.</AlertDescription></Alert>;
  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2 text-sm text-muted-foreground"><MessageSquareText className="size-4" />{pending.length} required feedback {pending.length === 1 ? 'submission remains' : 'submissions remain'}</div>
      {pending.map((obligation) => <FeedbackForm key={obligation.id ?? obligation.applicationId} eventId={eventId} obligation={obligation} />)}
    </div>
  );
}

"use client";

import {
  assignTestingLabRole,
  grantTestingLabResourcePermission,
  inspectTestingLabUserAccess,
  revokeTestingLabResourcePermission,
  revokeTestingLabRole,
  type TestingLabActionResult,
} from "@/lib/testing-lab/actions";
import type {
  TestingLabTestingLabRoleTemplate,
  TestingLabUserTestingLabPermissions,
} from "@game-guild/client";
import { Alert, AlertDescription } from "@game-guild/ui/components/alert";
import { Badge } from "@game-guild/ui/components/badge";
import { Button } from "@game-guild/ui/components/button";
import { DateTimePicker } from "@/components/ui/date-time-picker";
import { Input } from "@game-guild/ui/components/input";
import { Label } from "@game-guild/ui/components/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@game-guild/ui/components/select";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@game-guild/ui/components/sheet";
import {
  AlertCircle,
  CheckCircle2,
  Clock3,
  Loader2,
  RefreshCw,
  ShieldCheck,
  ShieldMinus,
  ShieldPlus,
  Trash2,
  UserCog,
} from "lucide-react";
import { useMemo, useState, useTransition } from "react";

interface MemberOption {
  id: string;
  label: string;
}

interface ResourceOption {
  id: string;
  label: string;
  type: "TestingRequest" | "TestingSession" | "TestingLocation";
}

type Operation = (
  formData: FormData,
) => Promise<TestingLabActionResult<unknown>>;
type AccessInspection = (
  formData: FormData,
) => Promise<TestingLabActionResult<TestingLabUserTestingLabPermissions>>;

const resourceActions: Record<ResourceOption["type"], readonly string[]> = {
  TestingRequest: ["read", "edit", "delete", "approve"],
  TestingSession: ["read", "edit", "delete"],
  TestingLocation: ["read", "edit", "delete"],
};

export function getTestingLabResourceActions(
  resourceType: ResourceOption["type"],
): readonly string[] {
  return resourceActions[resourceType];
}

function createFormData(values: Record<string, string>) {
  const formData = new FormData();
  Object.entries(values).forEach(([key, value]) => formData.set(key, value));
  return formData;
}

function accessFailure(error: unknown): TestingLabActionResult<unknown> {
  return {
    success: false,
    error:
      error instanceof Error
        ? error.message
        : "The Testing Lab access operation failed.",
  };
}

export async function executeTestingLabAccessMutation(
  operation: Operation,
  inspect: AccessInspection,
  values: Record<string, string>,
): Promise<{
  result: TestingLabActionResult<unknown>;
  effectiveAccess: TestingLabUserTestingLabPermissions | null;
  refreshError: string | null;
}> {
  let result: TestingLabActionResult<unknown>;
  try {
    result = await operation(createFormData(values));
  } catch (error) {
    return {
      result: accessFailure(error),
      effectiveAccess: null,
      refreshError: null,
    };
  }
  if (!result.success)
    return { result, effectiveAccess: null, refreshError: null };

  let refreshed: Awaited<ReturnType<AccessInspection>>;
  try {
    refreshed = await inspect(
      createFormData({ userId: values.userId ?? "" }),
    );
  } catch (error) {
    return {
      result,
      effectiveAccess: null,
      refreshError:
        error instanceof Error
          ? error.message
          : "Effective access could not be refreshed.",
    };
  }
  if (!refreshed.success) {
    return { result, effectiveAccess: null, refreshError: refreshed.error };
  }

  return { result, effectiveAccess: refreshed.data, refreshError: null };
}

function ResultAlert({
  result,
  refreshError,
}: {
  result: TestingLabActionResult<unknown> | null;
  refreshError?: string | null;
}) {
  if (!result && !refreshError) return null;
  const success = Boolean(result?.success) && !refreshError;
  const message = refreshError
    ? "The change was saved, but effective access could not be refreshed: " +
      refreshError
    : result?.success
      ? result.message
      : result?.error;

  return (
    <Alert variant={success ? "default" : "destructive"} aria-live="polite">
      {success ? (
        <CheckCircle2 className="size-4" />
      ) : (
        <AlertCircle className="size-4" />
      )}
      <AlertDescription>{message}</AlertDescription>
    </Alert>
  );
}

function permissionLabel(permission: string) {
  return permission
    .replace(/^can/, "")
    .replace(/([A-Z])/g, " $1")
    .trim();
}

function formatPermissionExpiry(value: string) {
  return new Intl.DateTimeFormat("en-US", {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone: "UTC",
  }).format(new Date(value));
}

export function TestingLabAccessManagement({
  members,
  roles,
  resources,
}: {
  members: MemberOption[];
  roles: TestingLabTestingLabRoleTemplate[];
  resources: ResourceOption[];
}) {
  const [memberId, setMemberId] = useState("");
  const [roleName, setRoleName] = useState("");
  const [resourceType, setResourceType] =
    useState<ResourceOption["type"]>("TestingRequest");
  const [resourceId, setResourceId] = useState("");
  const [permissionAction, setPermissionAction] = useState("read");
  const [expiresAt, setExpiresAt] = useState("");
  const [open, setOpen] = useState(false);
  const [pending, startTransition] = useTransition();
  const [result, setResult] = useState<TestingLabActionResult<unknown> | null>(
    null,
  );
  const [refreshError, setRefreshError] = useState<string | null>(null);
  const [effectiveAccess, setEffectiveAccess] =
    useState<TestingLabUserTestingLabPermissions | null>(null);

  const selectedMember = members.find((member) => member.id === memberId);
  const filteredResources = useMemo(
    () => resources.filter((resource) => resource.type === resourceType),
    [resourceType, resources],
  );
  const resourceById = useMemo(
    () => new Map(resources.map((resource) => [resource.id, resource])),
    [resources],
  );
  const availableActions = getTestingLabResourceActions(resourceType);

  function loadAccess(userId: string) {
    startTransition(async () => {
      try {
        const access = await inspectTestingLabUserAccess(
          createFormData({ userId }),
        );
        setResult(access);
        setRefreshError(null);
        setEffectiveAccess(access.success ? access.data : null);
      } catch (error) {
        setResult(accessFailure(error));
        setRefreshError(null);
        setEffectiveAccess(null);
      }
    });
  }

  function openMemberAccess() {
    setOpen(true);
    loadAccess(memberId);
  }

  function execute(operation: Operation, values: Record<string, string>) {
    startTransition(async () => {
      const outcome = await executeTestingLabAccessMutation(
        operation,
        inspectTestingLabUserAccess,
        values,
      );
      setResult(outcome.result);
      setRefreshError(outcome.refreshError);
      if (outcome.effectiveAccess) setEffectiveAccess(outcome.effectiveAccess);
    });
  }

  const roleDisabled = !memberId || !roleName;
  const resourceDisabled = !memberId || !resourceId || !permissionAction;

  return (
    <div className="space-y-3">
      <Label htmlFor="access-member">Member</Label>
      <div className="grid gap-2 sm:grid-cols-[minmax(0,1fr)_auto]">
        <Select
          value={memberId}
          onValueChange={(value) => {
            setMemberId(value ?? "");
            setEffectiveAccess(null);
            setResult(null);
            setRefreshError(null);
          }}
        >
          <SelectTrigger id="access-member">
            <SelectValue placeholder="Choose a community member" />
          </SelectTrigger>
          <SelectContent>
            {members.map((member) => (
              <SelectItem key={member.id} value={member.id}>
                {member.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Button type="button" disabled={!memberId} onClick={openMemberAccess}>
          <UserCog aria-hidden="true" className="mr-2 size-4" />
          Manage access
        </Button>
      </div>

      <Sheet open={open} onOpenChange={setOpen}>
        <SheetContent className="w-full gap-0 overflow-y-auto p-0 sm:max-w-2xl">
          <SheetHeader className="sticky top-0 z-10 border-b bg-background pr-12">
            <SheetTitle>
              {selectedMember
                ? "Testing Lab access · " + selectedMember.label
                : "Testing Lab access"}
            </SheetTitle>
            <SheetDescription>
              Roles define baseline access. Resource exceptions add time-limited
              access to one request, session, or location.
            </SheetDescription>
          </SheetHeader>

          <div className="space-y-7 p-4 sm:p-6">
            <ResultAlert result={result} refreshError={refreshError} />

            <section className="space-y-3">
              <div className="flex items-start justify-between gap-3">
                <div>
                  <h3 className="font-semibold">Effective access</h3>
                  <p className="text-sm text-muted-foreground">
                    Merged roles, permissions, and active resource exceptions.
                  </p>
                </div>
                <Button
                  type="button"
                  size="icon"
                  variant="ghost"
                  disabled={pending || !memberId}
                  onClick={() => loadAccess(memberId)}
                  title="Refresh access"
                >
                  {pending ? (
                    <Loader2
                      aria-hidden="true"
                      className="size-4 animate-spin"
                    />
                  ) : (
                    <RefreshCw aria-hidden="true" className="size-4" />
                  )}
                  <span className="sr-only">Refresh access</span>
                </Button>
              </div>

              {effectiveAccess ? (
                <div className="space-y-4 rounded-md border p-4">
                  <div>
                    <p className="mb-2 text-xs font-medium uppercase text-muted-foreground">
                      Assigned roles
                    </p>
                    <div className="flex flex-wrap gap-1.5">
                      {(effectiveAccess.assignedRoles ?? []).length > 0 ? (
                        effectiveAccess.assignedRoles?.map((role) => (
                          <Badge key={role}>{role}</Badge>
                        ))
                      ) : (
                        <span className="text-sm text-muted-foreground">
                          No Testing Lab roles assigned.
                        </span>
                      )}
                    </div>
                  </div>
                  <div>
                    <p className="mb-2 text-xs font-medium uppercase text-muted-foreground">
                      Effective permissions
                    </p>
                    <div className="flex flex-wrap gap-1.5">
                      {Object.entries(effectiveAccess.permissions ?? {})
                        .filter(([, enabled]) => enabled)
                        .map(([permission]) => (
                          <Badge key={permission} variant="outline">
                            {permissionLabel(permission)}
                          </Badge>
                        ))}
                    </div>
                  </div>
                </div>
              ) : (
                <div className="rounded-md border border-dashed p-4 text-sm text-muted-foreground">
                  Access is loaded when this sheet opens.
                </div>
              )}
            </section>

            <section className="space-y-3 border-t pt-6">
              <div>
                <h3 className="font-semibold">Role assignment</h3>
                <p className="text-sm text-muted-foreground">
                  Apply or remove a reusable role in the current tenant.
                </p>
              </div>
              <div className="grid gap-2 sm:grid-cols-[minmax(0,1fr)_auto_auto]">
                <Select value={roleName} onValueChange={(value) => setRoleName(value ?? "")}>
                  <SelectTrigger aria-label="Testing Lab role">
                    <SelectValue placeholder="Choose a role" />
                  </SelectTrigger>
                  <SelectContent>
                    {roles.filter((role) => role.name).map((role) => (
                      <SelectItem
                        key={role.id ?? role.name}
                        value={role.name!}
                      >
                        {role.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Button
                  type="button"
                  disabled={roleDisabled || pending}
                  onClick={() =>
                    execute(assignTestingLabRole, {
                      userId: memberId,
                      roleName,
                    })
                  }
                >
                  <ShieldPlus aria-hidden="true" className="mr-2 size-4" />
                  Assign
                </Button>
                <Button
                  type="button"
                  variant="outline"
                  disabled={roleDisabled || pending}
                  onClick={() =>
                    execute(revokeTestingLabRole, {
                      userId: memberId,
                      roleName,
                    })
                  }
                >
                  <ShieldMinus aria-hidden="true" className="mr-2 size-4" />
                  Revoke
                </Button>
              </div>
            </section>

            <section className="space-y-4 border-t pt-6">
              <div>
                <h3 className="font-semibold">Resource exceptions</h3>
                <p className="text-sm text-muted-foreground">
                  Grant one supported action on one operational resource, with
                  an optional expiry.
                </p>
              </div>

              {(effectiveAccess?.resourcePermissions ?? []).length > 0 ? (
                <div className="divide-y rounded-md border">
                  {effectiveAccess?.resourcePermissions?.map((permission) => {
                    const resource = resourceById.get(
                      permission.resourceId ?? "",
                    );
                    return (
                      <div
                        key={[
                          permission.resourceType,
                          permission.resourceId,
                          permission.action,
                        ].join(":")}
                        className="flex items-center justify-between gap-3 p-3"
                      >
                        <div className="min-w-0">
                          <p className="truncate text-sm font-medium">
                            {resource?.label ?? permission.resourceId}
                          </p>
                          <p className="mt-1 flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
                            <span>
                              {permission.resourceType?.replace("Testing", "")}
                            </span>
                            <span>·</span>
                            <span>{permission.action}</span>
                            {permission.expiresAt ? (
                              <>
                                <span>·</span>
                                <span className="inline-flex items-center gap-1">
                                  <Clock3
                                    aria-hidden="true"
                                    className="size-3"
                                  />
                                  Expires{" "}
                                  {formatPermissionExpiry(
                                    permission.expiresAt,
                                  )}{" "}
                                  UTC
                                </span>
                              </>
                            ) : null}
                          </p>
                        </div>
                        <Button
                          type="button"
                          size="icon"
                          variant="ghost"
                          disabled={pending}
                          title="Revoke resource permission"
                          onClick={() =>
                            execute(revokeTestingLabResourcePermission, {
                              userId: memberId,
                              resourceType: permission.resourceType ?? "",
                              resourceId: permission.resourceId ?? "",
                              action: permission.action ?? "",
                            })
                          }
                        >
                          <Trash2 aria-hidden="true" className="size-4" />
                          <span className="sr-only">
                            Revoke resource permission
                          </span>
                        </Button>
                      </div>
                    );
                  })}
                </div>
              ) : (
                <p className="text-sm text-muted-foreground">
                  No active resource exceptions.
                </p>
              )}

              <div className="grid gap-3 rounded-md bg-muted/25 p-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="testing-access-resource-type">Resource type</Label>
                  <Select
                    value={resourceType}
                    onValueChange={(value) => {
                      const type = value as ResourceOption["type"];
                      setResourceType(type);
                      setResourceId("");
                      setPermissionAction(getTestingLabResourceActions(type)[0]!);
                    }}
                  >
                    <SelectTrigger id="testing-access-resource-type">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="TestingRequest">Request</SelectItem>
                      <SelectItem value="TestingSession">Session</SelectItem>
                      <SelectItem value="TestingLocation">Location</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="testing-access-action">Action</Label>
                  <Select
                    value={permissionAction}
                    onValueChange={(value) => setPermissionAction(value ?? "read")}
                  >
                    <SelectTrigger id="testing-access-action">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {getTestingLabResourceActions(resourceType).map(
                        (action) => (
                          <SelectItem key={action} value={action}>
                            {action}
                          </SelectItem>
                        ),
                      )}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2 sm:col-span-2">
                  <Label htmlFor="testing-access-resource">Resource</Label>
                  <Select value={resourceId} onValueChange={(value) => setResourceId(value ?? "")}>
                    <SelectTrigger id="testing-access-resource">
                      <SelectValue placeholder="Choose a resource" />
                    </SelectTrigger>
                    <SelectContent>
                      {filteredResources.map((resource) => (
                        <SelectItem key={resource.id} value={resource.id}>
                          {resource.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="permission-expiry">Optional expiry</Label>
                  <DateTimePicker
                    id="permission-expiry"
                    name="permissionExpiry"
                    value={expiresAt}
                    onValueChange={setExpiresAt}
                  />
                </div>
                <div className="flex items-end">
                  <Button
                    type="button"
                    className="w-full"
                    disabled={resourceDisabled || pending}
                    onClick={() =>
                      execute(grantTestingLabResourcePermission, {
                        userId: memberId,
                        resourceType,
                        resourceId,
                        action: permissionAction,
                        expiresAt,
                      })
                    }
                  >
                    <ShieldCheck aria-hidden="true" className="mr-2 size-4" />
                    Grant exception
                  </Button>
                </div>
              </div>
            </section>
          </div>
        </SheetContent>
      </Sheet>
    </div>
  );
}

