  versionNumber: string;
  status: string;
}
interface CurrentApplication {
  id: string;
  projectId?: string | null;
  projectVersionId?: string | null;
  preferredAvailability?: string | null;
  status?: string | null;
  decisionRationale?: string | null;
  brief?: TestingLabTestingProjectBrief;
  eventApplicationResponse?: TestingLabQuestionnaireOutput;
  feedbackQuestionnaire?: TestingLabQuestionnaireSchema;
  rulesAcceptedAt?: string | null;
  submittedAssetReferenceIds?: string[] | null;
  submissionVersionPolicy?: string | null;
}

const STEPS = ['Game & build', 'Test brief', 'Feedback form', 'Event questions', 'Review'] as const;
const emptyBrief: TestingLabTestingProjectBrief = {
  testObjective: '',
  installationAndAccess: '',
  testTasks: [],
  controls: '',
  knownLimitations: '',
  links: [],
};

function ResultMessage({ result }: { result: TestingEventActionResult<unknown> | null }) {
  if (!result) return null;
  return (
    <Alert variant={result.success ? 'default' : 'destructive'} aria-live="polite">
      {result.success ? <CheckCircle2 className="size-4" /> : <AlertCircle className="size-4" />}
      <AlertDescription>{result.success ? result.message : result.error}</AlertDescription>
    </Alert>
  );
}

function lines(value?: string[] | null) {
  return (value ?? []).join('\n');
}

function parseLines(value: string) {
  return value.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
}

async function saveDraftInBrowser(input: {
  eventId: string;
  projectId: string;
  applicationId?: string;
  projectVersionId?: string;
  brief: TestingLabTestingProjectBrief;
  feedbackQuestionnaire: TestingLabQuestionnaireSchema;
  eventApplicationResponse: TestingLabQuestionnaireOutput;
  acceptedRules: boolean;
  preferredAvailability: string;
  submittedAssetReferenceIds: string[];
  intent: 'save' | 'submit';
}): Promise<TestingEventActionResult<CurrentApplication>> {
  try {
    const response = await fetch('/api/testing-lab/applications/draft', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify(input),
    });
    const result = await response.json().catch(() => null) as TestingEventActionResult<CurrentApplication> | null;
    if (result && typeof result.success === 'boolean') return result;
    return { success: false, error: 'The application draft could not be saved.' };
  } catch {
    return { success: false, error: 'The application draft could not be saved.' };
  }
}

function ApplicationWizard({
  eventId,
  application,
  projectVersions,
  initialProjectId,
  applicationSchema,
  generalRules,
  candidateInstructions,
  requiresFeedback,
  acceptsApplications,
}: {
  eventId: string;
  application?: CurrentApplication;
  projectVersions: ProjectVersionOption[];
  initialProjectId?: string;
  applicationSchema?: TestingLabQuestionnaireSchema | null;
  generalRules?: string | null;
  candidateInstructions?: string | null;
  requiresFeedback: boolean;
  acceptsApplications: boolean;
}) {
  const [pending, startTransition] = useTransition();
  const [result, setResult] = useState<TestingEventActionResult<unknown> | null>(null);
  const [applicationId, setApplicationId] = useState(application?.id ?? '');
  const [status, setStatus] = useState(application?.status ?? 'Draft');
  const [draftProjectId, setDraftProjectId] = useState(application?.projectId ?? '');
  const matchingVersions = draftProjectId
    ? projectVersions.filter((version) => version.projectId === draftProjectId)
    : projectVersions;
  const eligibleVersions = matchingVersions.filter((version) => ['ReadyForTesting', 'Released'].includes(version.status));
  const initialVersion = application?.projectVersionId && eligibleVersions.some((version) => version.id === application.projectVersionId)
    ? application.projectVersionId
    : eligibleVersions.find((version) => version.projectId === initialProjectId)?.id ?? '';
  const [selectedVersionId, setSelectedVersionId] = useState(initialVersion);
  const selectedVersion = projectVersions.find((version) => version.id === selectedVersionId);
  const gameGroups = Array.from(
    eligibleVersions
      .reduce((groups, version) => {
        const group = groups.get(version.projectId);
        if (group) group.versions.push(version);
        else groups.set(version.projectId, { projectId: version.projectId, projectTitle: version.projectTitle, imageUrl: version.imageUrl, versions: [version] });
        return groups;
      }, new Map<string, { projectId: string; projectTitle: string; imageUrl?: string | null; versions: ProjectVersionOption[] }>())
      .values(),
  );
  const projectId = draftProjectId || selectedVersion?.projectId || '';
  const [step, setStep] = useState(0);
  const [brief, setBrief] = useState<TestingLabTestingProjectBrief>(application?.brief ?? emptyBrief);
  const [feedbackQuestionnaire, setFeedbackQuestionnaire] = useState<TestingLabQuestionnaireSchema>(
    application?.feedbackQuestionnaire ?? { title: 'Playtest feedback', questions: [] },
  );
  const [eventResponses, setEventResponses] = useState<TestingLabQuestionnaireOutput>(
    application?.eventApplicationResponse ?? { answers: [] },
  );
  const [acceptedRules, setAcceptedRules] = useState(Boolean(application?.rulesAcceptedAt));
  const [preferredAvailability, setPreferredAvailability] = useState(application?.preferredAvailability ?? '');
  const [assetIds, setAssetIds] = useState(lines(application?.submittedAssetReferenceIds));
  const editable = acceptsApplications && (status === 'Draft' || status === 'Pending');
  const canWithdraw = Boolean(applicationId) && ['Draft', 'Pending', 'UnderReview', 'Waitlisted'].includes(status);
  const versionMutable = status === 'Draft' || application?.submissionVersionPolicy !== 'ReleasedImmutable';

  function persist(intent: 'save' | 'submit', nextStep?: number) {
    startTransition(async () => {
      const next = await saveDraftInBrowser({
        eventId,
        projectId,
        applicationId: applicationId || undefined,
        projectVersionId: selectedVersionId || undefined,
        brief,
        feedbackQuestionnaire,
        eventApplicationResponse: eventResponses,
        acceptedRules,
        preferredAvailability,
        submittedAssetReferenceIds: parseLines(assetIds),
        intent,
      });
      setResult(next);
      if (!next.success) return;
      if (next.data?.id) setApplicationId(next.data.id);
      if (next.data?.projectId) setDraftProjectId(next.data.projectId);
      if (next.data?.status) setStatus(next.data.status);
      if (nextStep !== undefined) setStep(nextStep);
    });
  }

  function withdraw() {
    const formData = new FormData();
    formData.set('eventId', eventId);
    formData.set('applicationId', applicationId);
    startTransition(async () => {
      try {
        setResult(await withdrawTestingProjectApplication(formData));
      } catch (error) {
        setResult({
          success: false,
          error: error instanceof Error ? error.message : 'The Testing Lab operation failed.',
        });
      }
    });
  }

  if (!editable) {
    return (
      <section className="space-y-3 rounded-md border p-4">
        <Badge variant="outline">{status}</Badge>
        <p className="text-sm text-muted-foreground">This application package is frozen for review and historical integrity.</p>
        {application?.decisionRationale ? <Alert><AlertCircle className="size-4" /><AlertDescription>{application.decisionRationale}</AlertDescription></Alert> : null}
        {canWithdraw ? (
          <Button type="button" variant="ghost" className="text-destructive" disabled={pending} onClick={withdraw}>
            Withdraw application
          </Button>
        ) : null}
        <ResultMessage result={result} />
      </section>
    );
  }

  return (
    <section className={`space-y-5 ${step === 0 ? '' : 'rounded-md border bg-card p-4'}`}>
      {applicationId ? (
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-2">
            <Badge variant={status === 'Draft' ? 'secondary' : 'outline'}>{status}</Badge>
            <span className="text-xs text-muted-foreground">Application {applicationId.slice(0, 8)}</span>
          </div>
          <Button type="button" variant="ghost" size="sm" disabled={pending || !projectId} onClick={() => persist('save')}>
            {pending ? <Loader2 className="mr-2 size-4 animate-spin" /> : <Save className="mr-2 size-4" />}
            Save progress
          </Button>
        </div>
      ) : null}

      <div className="space-y-2" aria-label="Application progress">
        <div className="flex items-center justify-between gap-3 text-xs">
          <span className="font-medium text-foreground">{STEPS[step]}</span>
          <span className="text-muted-foreground">Step {step + 1} of {STEPS.length}</span>
        </div>
        <div className="grid grid-cols-5 gap-1" aria-hidden="true">
          {STEPS.map((label, index) => (
            <span key={label} className={`h-1 rounded-full ${index <= step ? 'bg-primary' : 'bg-muted'}`} />
          ))}
        </div>
      </div>

      {step === 0 ? (
        <div className="space-y-4">
          <div className="flex items-end justify-between gap-3">
            <div>
              <h3 className="font-medium">Choose your game</h3>
              <p className="mt-1 text-sm text-muted-foreground">Select the build you want players to test.</p>
            </div>
            {gameGroups.length > 0 ? <span className="shrink-0 text-xs text-muted-foreground">{gameGroups.length} {gameGroups.length === 1 ? 'game' : 'games'}</span> : null}
          </div>

          {gameGroups.length > 0 ? (
            <div role="radiogroup" aria-label="Choose a game build" className="space-y-3">
              {gameGroups.map((game) => {
                const gameIsSelected = game.versions.some((version) => version.id === selectedVersionId);
                return (
                  <section key={game.projectId} className={`overflow-hidden rounded-xl border transition-colors ${gameIsSelected ? 'border-primary bg-primary/[0.04]' : 'border-border bg-card/50'}`}>
                    <div className="flex items-center gap-3 px-3 py-3 sm:px-4">
                      <div className="relative size-12 shrink-0 overflow-hidden rounded-lg bg-muted">
                        {game.imageUrl ? (
                          <Image src={game.imageUrl} alt="" fill sizes="48px" unoptimized className="object-cover" />
                        ) : (
                          <div className="grid size-full place-items-center text-muted-foreground"><Gamepad2 className="size-5" aria-hidden="true" /></div>
                        )}
                      </div>
                      <div className="min-w-0 flex-1">
                        <h4 className="truncate font-semibold">{game.projectTitle}</h4>
                        <p className="text-xs text-muted-foreground">{game.versions.length} eligible {game.versions.length === 1 ? 'build' : 'builds'}</p>
                      </div>
                      {gameIsSelected ? <Check className="size-5 shrink-0 text-primary" aria-hidden="true" /> : null}
                    </div>
                    <div className="space-y-2 border-t border-border/70 p-2 sm:p-3">
                      {game.versions.map((version) => {
                        const selected = version.id === selectedVersionId;
                        const eligibility = version.status === 'Released' ? 'Released' : 'Ready for testing';
                        return (
                          <label key={version.id} className="block cursor-pointer">
                            <input
                              type="radio"
                              name={`testing-project-version-${eventId}`}
                              value={version.id}
                              checked={selected}
                              disabled={!versionMutable}
                              onChange={() => setSelectedVersionId(version.id)}
                              aria-label={`${game.projectTitle} · ${version.versionNumber} · ${eligibility}`}
                              className="peer sr-only"
                            />
                            <span className={`flex min-h-12 items-center justify-between gap-3 rounded-lg border px-3 py-2 transition-colors peer-focus-visible:outline-none peer-focus-visible:ring-2 peer-focus-visible:ring-ring ${selected ? 'border-primary/70 bg-primary/10' : 'border-transparent bg-background/60 hover:border-border hover:bg-background'} ${!versionMutable ? 'cursor-not-allowed opacity-60' : ''}`}>
                              <span className="min-w-0">
                                <span className="font-medium">{version.versionNumber}</span>
                                <span className={`ml-2 inline-flex rounded-full px-2 py-0.5 text-[11px] font-medium ${version.status === 'Released' ? 'bg-muted text-muted-foreground' : 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-300'}`}>{eligibility}</span>
                              </span>
                              {selected ? <Check className="size-4 shrink-0 text-primary" aria-hidden="true" /> : <span className="size-4 shrink-0 rounded-full border border-muted-foreground/50" aria-hidden="true" />}
                            </span>
                          </label>
                        );
                      })}
                    </div>
                  </section>
                );
              })}
            </div>
          ) : (
            <div className="flex flex-col items-center gap-3 rounded-xl border border-dashed p-6 text-center">
              <div className="grid size-10 place-items-center rounded-full bg-muted text-muted-foreground"><Gamepad2 className="size-5" aria-hidden="true" /></div>
              <div className="space-y-1">
                <p className="font-medium">No test-ready builds yet</p>
                <p className="max-w-sm text-sm text-muted-foreground">Publish a build as Ready for Testing or Released, then come back to submit it here.</p>
              </div>
              <Link href="/projects" className={buttonVariants({ variant: 'outline', size: 'sm' })}>Open your projects</Link>
            </div>
          )}
        </div>
      ) : null}

      {step === 1 ? (
        <div className="space-y-4">
          {candidateInstructions ? <Alert><AlertDescription>{candidateInstructions}</AlertDescription></Alert> : null}
          <div className="space-y-2"><Label htmlFor={`objective-${applicationId}`}>Test objective</Label><Textarea id={`objective-${applicationId}`} rows={3} value={brief.testObjective ?? ''} onChange={(event) => setBrief({ ...brief, testObjective: event.currentTarget.value })} /></div>
          <div className="space-y-2"><Label htmlFor={`install-${applicationId}`}>Installation and access</Label><Textarea id={`install-${applicationId}`} rows={3} value={brief.installationAndAccess ?? ''} onChange={(event) => setBrief({ ...brief, installationAndAccess: event.currentTarget.value })} /></div>
          <div className="space-y-2"><Label htmlFor={`tasks-${applicationId}`}>Test tasks (one per line)</Label><Textarea id={`tasks-${applicationId}`} rows={4} value={lines(brief.testTasks)} onChange={(event) => setBrief({ ...brief, testTasks: parseLines(event.currentTarget.value) })} /></div>
          <div className="space-y-2"><Label htmlFor={`controls-${applicationId}`}>Controls</Label><Textarea id={`controls-${applicationId}`} rows={2} value={brief.controls ?? ''} onChange={(event) => setBrief({ ...brief, controls: event.currentTarget.value })} /></div>
          <div className="space-y-2"><Label htmlFor={`limitations-${applicationId}`}>Known limitations</Label><Textarea id={`limitations-${applicationId}`} rows={2} value={brief.knownLimitations ?? ''} onChange={(event) => setBrief({ ...brief, knownLimitations: event.currentTarget.value })} /></div>
          <div className="space-y-2"><Label htmlFor={`links-${applicationId}`}>Links (one absolute URL per line)</Label><Textarea id={`links-${applicationId}`} rows={2} value={lines(brief.links)} onChange={(event) => setBrief({ ...brief, links: parseLines(event.currentTarget.value) })} /></div>
          <div className="space-y-2"><Label htmlFor={`assets-${applicationId}`}>Existing asset reference IDs (optional, one per line)</Label><Textarea id={`assets-${applicationId}`} rows={2} value={assetIds} onChange={(event) => setAssetIds(event.currentTarget.value)} /></div>
        </div>
      ) : null}

      {step === 2 ? (
        <div className="space-y-3">
          <div><h3 className="font-medium">Developer feedback questionnaire</h3><p className="text-sm text-muted-foreground">Testers answer this immutable revision after assignment.</p></div>
          <QuestionnaireBuilder value={feedbackQuestionnaire} onChange={setFeedbackQuestionnaire} required={requiresFeedback} />
        </div>
      ) : null}

      {step === 3 ? (
        <div className="space-y-4">
          <QuestionnaireFieldset schema={applicationSchema} value={eventResponses} onChange={setEventResponses} onComplete={() => persist('save', 4)} submitLabel="Review application" description="These fields were defined by the event organizer and are frozen for this event." />
          <Button type="button" variant="outline" onClick={() => setStep(2)}><ChevronLeft className="mr-2 size-4" />Back to feedback form</Button>
        </div>
      ) : null}

      {step === 4 ? (
        <div className="space-y-4">
          <div className="rounded-md bg-muted/40 p-4 text-sm">
            <p className="font-medium">{selectedVersion?.projectTitle} · {selectedVersion?.versionNumber}</p>
            <p className="mt-1 text-muted-foreground">{brief.testTasks?.length ?? 0} test tasks · {feedbackQuestionnaire.questions?.length ?? 0} developer questions</p>
          </div>
          <div className="space-y-2"><Label htmlFor={`availability-${applicationId}`}>Preferred availability</Label><Textarea id={`availability-${applicationId}`} rows={2} value={preferredAvailability} onChange={(event) => setPreferredAvailability(event.currentTarget.value)} /></div>
          <div className="max-h-48 overflow-y-auto rounded-md border p-3 text-sm leading-6 whitespace-pre-wrap">{generalRules || 'Event rules are unavailable.'}</div>
          <label className="flex items-start gap-3 text-sm"><input className="mt-1 size-4" type="checkbox" checked={acceptedRules} onChange={(event) => setAcceptedRules(event.currentTarget.checked)} /><span>I have read and accept the frozen rules for this Testing Lab event.</span></label>
          <div className="flex flex-wrap gap-2">
            <Button type="button" variant="outline" onClick={() => setStep(3)}><ChevronLeft className="mr-2 size-4" />Back</Button>
            <Button type="button" disabled={pending || !acceptedRules || !selectedVersionId} onClick={() => persist(status === 'Draft' ? 'submit' : 'save')}>
              {pending ? <Loader2 className="mr-2 size-4 animate-spin" /> : null}
              {status === 'Draft' ? 'Submit for review' : 'Update pending application'}
            </Button>
          </div>
        </div>
      ) : null}

      {step === 0 ? (
        <div className="flex items-center justify-between gap-3 border-t pt-4">
          <p aria-live="polite" aria-atomic="true" className="min-w-0 truncate text-sm text-muted-foreground">
            {selectedVersion ? <><span className="font-medium text-foreground">{selectedVersion.projectTitle}</span><span> · {selectedVersion.versionNumber}</span></> : 'Choose a build to continue.'}
          </p>
          <Button type="button" className="shrink-0" disabled={pending || !eligibleVersions.some((version) => version.id === selectedVersionId)} onClick={() => persist('save', 1)}>
            {pending ? <Loader2 className="mr-2 size-4 animate-spin" /> : null}Continue<ChevronRight className="ml-2 size-4" />
          </Button>
        </div>
      ) : step < 3 ? (
        <div className="flex items-center justify-between gap-2 border-t pt-4">
          <Button type="button" variant="outline" onClick={() => setStep((current) => Math.max(0, current - 1))}><ChevronLeft className="mr-2 size-4" />Previous</Button>
          <Button type="button" disabled={pending} onClick={() => persist('save', step + 1)}>
            {pending ? <Loader2 className="mr-2 size-4 animate-spin" /> : null}Save and continue<ChevronRight className="ml-2 size-4" />
          </Button>
        </div>
      ) : null}

      {canWithdraw ? (
        <Button type="button" variant="ghost" className="text-destructive" disabled={pending} onClick={withdraw}>Withdraw application</Button>
      ) : null}
      <ResultMessage result={result} />
    </section>
  );
}

export function TestingProjectApplication({
  eventId,
  isAuthenticated,
  acceptsApplications,
  projectVersions,
  application,
  applications,
  initialProjectId,
  selectedApplicationId,
  applicationSchema,
  generalRules,
  candidateInstructions,
  requiresFeedback = false,
  signInReturnUrl,
}: {
  eventId: string;
  isAuthenticated: boolean;
  acceptsApplications: boolean;
  projectVersions: ProjectVersionOption[];
  application?: CurrentApplication;
  applications?: CurrentApplication[];
  initialProjectId?: string;
  selectedApplicationId?: string;
  applicationSchema?: TestingLabQuestionnaireSchema | null;
  generalRules?: string | null;
  candidateInstructions?: string | null;
  requiresFeedback?: boolean;
  signInReturnUrl?: string;
}) {
  const [lastAuthenticatedData] = useState(() =>
    isAuthenticated ? { application, applications, initialProjectId, projectVersions } : null,
  );

  // A Server Action can cause Next to merge a refreshed public RSC payload
  // without its request cookies. Keep the last verified private projection for
  // this mounted wizard so a saved draft does not disappear mid-flow. Every
  // mutation still performs its authorization and eligibility checks in the API.
  const applicationData = isAuthenticated
    ? { application, applications, initialProjectId, projectVersions }
    : lastAuthenticatedData;

  if (!applicationData) {
    if (!acceptsApplications) {
      return <p className="text-sm text-muted-foreground">Game submissions are closed for this event. Browse the Testing Lab for another opportunity.</p>;
    }
    const redirectTo = signInReturnUrl ?? `/testing-lab/events/${eventId}#join`;
    const signInHref = `/sign-in?redirectTo=${encodeURIComponent(redirectTo)}`;
    return (
      <div className="space-y-2">
        <Link href={signInHref} className={buttonVariants({ className: 'w-full sm:w-auto' })}>Sign in or create a free account</Link>
        <p className="text-xs text-muted-foreground">You’ll return to this event to choose a build and complete your application.</p>
      </div>
    );
  }

  const currentApplications = applicationData.applications ?? (applicationData.application ? [applicationData.application] : []);
  const activeProjectIds = new Set(currentApplications.filter((item) => !['Rejected', 'Withdrawn'].includes(item.status ?? '')).map((item) => item.projectId).filter((id): id is string => Boolean(id)));
  const availableVersions = applicationData.projectVersions.filter((version) => !activeProjectIds.has(version.projectId));
  const applicationsToReview = selectedApplicationId
    ? currentApplications.filter((item) => item.id === selectedApplicationId)
    : initialProjectId
      ? currentApplications.filter((item) => item.projectId === initialProjectId)
      : [];

  return (
    <div className="space-y-5">
      {applicationsToReview.map((item) => (
        <ApplicationWizard key={item.id} eventId={eventId} application={item} projectVersions={applicationData.projectVersions} applicationSchema={applicationSchema} generalRules={generalRules} candidateInstructions={candidateInstructions} requiresFeedback={requiresFeedback} acceptsApplications={acceptsApplications} />
      ))}
      {!acceptsApplications ? <p className="text-sm text-muted-foreground">Game submissions are closed for this event. You can still review any application already in progress.</p> : availableVersions.length > 0 ? (
        <ApplicationWizard eventId={eventId} projectVersions={availableVersions} initialProjectId={applicationData.initialProjectId} applicationSchema={applicationSchema} generalRules={generalRules} candidateInstructions={candidateInstructions} requiresFeedback={requiresFeedback} acceptsApplications={acceptsApplications} />
      ) : currentApplications.length === 0 ? (
        <div className="grid gap-4 rounded-xl border border-dashed bg-card/40 p-5 sm:grid-cols-[auto_1fr] sm:items-start">
          <div className="grid size-11 place-items-center rounded-lg bg-muted text-muted-foreground"><Gamepad2 className="size-5" aria-hidden="true" /></div>
          <div className="space-y-3">
            <div className="space-y-1">
              <p className="font-semibold">No test-ready builds available</p>
              <p className="text-sm text-muted-foreground">Choose a project with a build marked Ready for Testing or Released. You can submit it here once it is ready.</p>
            </div>
            <Link href="/projects" className={buttonVariants({ variant: 'outline', size: 'sm' })}>Open your projects</Link>
          </div>
        </div>
      ) : null}
    </div>
  );
}

'use client';

import {
  cancelTestingEventRegistration,
  registerForTestingEventSlot,
  type TestingEventActionResult,
} from '@/lib/testing-lab/events-actions';
import { Alert, AlertDescription } from '@game-guild/ui/components/alert';
import { Badge } from '@game-guild/ui/components/badge';
import { Button } from '@game-guild/ui/components/button';
import { buttonVariants } from '@game-guild/ui/components/button-variants';
import { AlertCircle, ArrowLeft, ArrowRight, CalendarDays, CheckCircle2, Loader2, MapPin } from 'lucide-react';
import { Link } from '@/i18n/navigation';
import { useState, useTransition } from 'react';
import type { TestingLabQuestionnaireOutput, TestingLabQuestionnaireSchema } from '@game-guild/client';
import { TestingEventDateRange } from './testing-event-date-range';
import { QuestionnaireFieldset } from './questionnaire-fieldset';

interface PublicSlot {
  id?: string | null;
  mode?: string | null;
  startsAt?: string | null;
  endsAt?: string | null;
  maxTesters?: number | null;
  maxProjects?: number | null;
  campusName?: string | null;
  roomName?: string | null;
  registeredTesterCount?: number | null;
  approvedProjectCount?: number | null;
  availableTesterCount?: number | null;
  availableProjectCount?: number | null;
}

interface CurrentRegistration {
  id?: string | null;
  status?: string | null;
  waitlistPosition?: number | null;
}

export function TestingSlotRegistration({
  eventId,
  isAuthenticated,
  registrationOpen = true,
  showClosedMessage = true,
  timeZoneId = 'UTC',
  locale = 'en-US',
  hour12 = true,
  slot,
  registration,
  registrationSchema,
  generalRules,
  testerInstructions,
  initiallyJoining = false,
  onBack,
  signInReturnUrl,
}: {
  eventId: string;
  isAuthenticated: boolean;
  registrationOpen?: boolean;
  showClosedMessage?: boolean;
  timeZoneId?: string;
  locale?: string;
  hour12?: boolean;
  slot: PublicSlot;
  registration?: CurrentRegistration;
  registrationSchema?: TestingLabQuestionnaireSchema | null;
  generalRules?: string | null;
  testerInstructions?: string | null;
  initiallyJoining?: boolean;
  onBack?: () => void;
  signInReturnUrl?: string;
}) {
  const [pending, startTransition] = useTransition();
  const [result, setResult] = useState<TestingEventActionResult<unknown> | null>(null);
  const [responses, setResponses] = useState<TestingLabQuestionnaireOutput>({ answers: [] });
  const [questionnaireComplete, setQuestionnaireComplete] = useState((registrationSchema?.questions?.length ?? 0) === 0);
  const [acceptedRules, setAcceptedRules] = useState(false);
  const [joining, setJoining] = useState(initiallyJoining);
  const isFull = slot.availableTesterCount !== null && slot.availableTesterCount !== undefined && slot.availableTesterCount <= 0;
  const location = [slot.campusName, slot.roomName].filter(Boolean).join(' · ');
  const registrationId = registration?.id ?? null;
  const redirectTo = signInReturnUrl ?? `/testing-lab/events/${eventId}?slotId=${encodeURIComponent(slot.id ?? '')}#session-${slot.id ?? ''}`;
  const signInHref = `/sign-in?redirectTo=${encodeURIComponent(redirectTo)}`;

  function register() {
    const formData = new FormData();
    formData.set('eventId', eventId);
    formData.set('slotId', slot.id!);
    formData.set('registrationResponseJson', JSON.stringify(responses));
    formData.set('acceptedRules', String(acceptedRules));
    startTransition(async () => {
      try {
        const next = await registerForTestingEventSlot(formData);
        setResult(next);
      } catch (error) {
        setResult({
          success: false,
          error: error instanceof Error ? error.message : 'The Testing Lab operation failed.',
        });
      }
    });
  }

  function cancel() {
    const formData = new FormData();
    formData.set('eventId', eventId);
    formData.set('registrationId', registrationId!);
    startTransition(async () => {
      try {
        const next = await cancelTestingEventRegistration(formData);
        setResult(next);
      } catch (error) {
        setResult({
          success: false,
          error: error instanceof Error ? error.message : 'The Testing Lab operation failed.',
        });
      }
    });
  }

  const modeLabel = slot.mode === 'InPerson' ? 'In person' : slot.mode ?? 'Online';
  const availabilityLabel = !registrationOpen
    ? 'Sign-ups closed'
    : isFull
      ? 'Waitlist open'
      : slot.availableTesterCount != null
        ? `${slot.availableTesterCount} tester ${slot.availableTesterCount === 1 ? 'spot' : 'spots'} left`
        : 'Sign-up open';

  return (
    <article id={slot.id && !initiallyJoining ? `session-${slot.id}` : undefined} className="scroll-mt-24">
      {!joining ? (
        <div className="flex items-start gap-3">
          <CalendarDays className="mt-0.5 size-4 shrink-0 text-muted-foreground" aria-hidden="true" />
          <div className="min-w-0 flex-1">
            <div className="flex flex-wrap items-center justify-between gap-x-2 gap-y-1">
              <p className="text-sm font-medium">{modeLabel} playtest</p>
              <Badge variant="secondary" className="whitespace-nowrap">{availabilityLabel}</Badge>
            </div>
            <div className="mt-2">
              <TestingEventDateRange startsAt={slot.startsAt} endsAt={slot.endsAt} timeZone={timeZoneId} locale={locale} hour12={hour12} />
            </div>
            {location ? (
              <p className="mt-2 flex items-center gap-2 text-xs text-muted-foreground">
                <MapPin className="size-3.5 shrink-0" aria-hidden="true" />
                {location}
              </p>
            ) : null}
          </div>
        </div>
      ) : null}

      {registration && registration.status !== 'Cancelled' ? (
        <div className="flex flex-wrap items-center justify-between gap-3 pt-2">
          <div>
            <p className="font-medium">{registration.status ?? 'Registered'}</p>
            {registration.status === 'Waitlisted' && registration.waitlistPosition ? (
              <p className="text-sm text-muted-foreground">Waitlist position {registration.waitlistPosition}</p>
            ) : null}
          </div>
          {registration.id && !['Cancelled', 'Completed', 'NoShow'].includes(registration.status ?? '') ? (
            <Button type="button" variant="outline" disabled={pending} onClick={cancel}>
              {pending ? <Loader2 className="mr-2 size-4 animate-spin" /> : null}
              Cancel registration
            </Button>
          ) : null}
        </div>
      ) : !registrationOpen && showClosedMessage ? (
        <div className="pt-2">
          <p className="text-sm text-muted-foreground">Sign-ups are closed for this playtest.</p>
        </div>
      ) : !registrationOpen ? null : !isAuthenticated ? (
        <div className="pt-3">
          <Link href={signInHref} className={buttonVariants({ className: 'w-full sm:w-auto' })}>
            Sign in or create a free account <ArrowRight className="ml-2 size-4" aria-hidden="true" />
          </Link>
        </div>
      ) : !joining ? (
        <div className="pt-3">
          <Button type="button" onClick={() => setJoining(true)}>
            {isFull ? 'Join the waitlist' : 'Join this playtest'} <ArrowRight className="ml-2 size-4" aria-hidden="true" />
          </Button>
        </div>
      ) : (
        <div className="space-y-3 pt-3">
          {testerInstructions?.trim() ? (
            <Alert><AlertDescription><span className="font-medium">Host’s note: </span>{testerInstructions}</AlertDescription></Alert>
          ) : null}
          {(registrationSchema?.questions?.length ?? 0) > 0 ? <QuestionnaireFieldset
            schema={registrationSchema}
            value={responses}
            onChange={(value) => { setResponses(value); setQuestionnaireComplete(false); }}
            onComplete={() => setQuestionnaireComplete(true)}
            submitLabel="Confirm registration answers"
          /> : null}
          <div className="max-h-48 overflow-y-auto rounded-md border bg-muted/20 p-3 text-sm leading-6 whitespace-pre-wrap">
            <p className="mb-1 font-medium">Playtest rules</p>
            {generalRules?.trim() || 'No event-specific rules have been published.'}
          </div>
          <label className="flex items-start gap-3 text-sm">
            <input className="mt-1 size-4" type="checkbox" checked={acceptedRules} onChange={(event) => setAcceptedRules(event.currentTarget.checked)} />
            <span>I’ve read and agree to follow the rules for this playtest.</span>
          </label>
          <Button type="button" className="w-full" disabled={pending || !slot.id || !questionnaireComplete || !acceptedRules} onClick={register}>
            {pending ? <Loader2 className="mr-2 size-4 animate-spin" /> : null}
            {isFull ? 'Join the waitlist' : 'Join playtest'}
          </Button>
          {onBack ? (
            <Button type="button" variant="ghost" className="w-full" disabled={pending} onClick={onBack}>
              <ArrowLeft className="mr-2 size-4" aria-hidden="true" /> Back
            </Button>
          ) : initiallyJoining ? (
            <Link href={`/testing-lab/events/${eventId}#schedule`} className="inline-flex min-h-9 w-full items-center justify-center text-sm text-muted-foreground underline-offset-4 hover:text-foreground hover:underline">
              Back to playtest details
            </Link>
          ) : (
            <Button type="button" variant="ghost" className="w-full" disabled={pending} onClick={() => setJoining(false)}>Back to session details</Button>
          )}
        </div>
      )}

      {result ? (
        <Alert variant={result.success ? 'default' : 'destructive'} aria-live="polite">
          {result.success ? <CheckCircle2 className="size-4" /> : <AlertCircle className="size-4" />}
          <AlertDescription>{result.success ? result.message : result.error}</AlertDescription>
        </Alert>
      ) : null}
    </article>
  );
}

"use client";

import { calendarDatePart, wallClockDate, wallClockToUtcIso } from "@/lib/date-time-zone";
import { Button } from "@game-guild/ui/components/button";
import { Calendar } from "@game-guild/ui/components/calendar";
import { Input } from "@game-guild/ui/components/input";
import { Popover, PopoverContent, PopoverTrigger } from "@game-guild/ui/components/popover";
import { cn } from "@game-guild/ui/lib/utils";
import { CalendarDays } from "lucide-react";
import * as React from "react";
import type { DateRange } from "react-day-picker";

export type DateTimeRangeValue = {
  start: string;
  end: string;
};

export interface DateTimeRangePickerProps {
  id: string;
  label: string;
  startLabel?: string;
  endLabel?: string;
  startName: string;
  endName: string;
  timeZoneId: string;
  value?: DateTimeRangeValue;
  defaultValue?: DateTimeRangeValue;
  onValueChange?: (value: DateTimeRangeValue) => void;
  required?: boolean;
  disabled?: boolean;
  className?: string;
  compact?: boolean;
}

function wallClockParts(value: string) {
  const [date = "", time = ""] = value.split("T", 2);
  return { date, time };
}

export function DateTimeRangePicker({ compact = false, ...props }: DateTimeRangePickerProps) {
  return compact ? <CompactDateTimeRangePicker {...props} /> : <DateTimeRangeFields {...props} />;
}

function DateTimeRangeFields({
  id,
  label,
  startLabel = "Starts",
  endLabel = "Ends",
  startName,
  endName,
  timeZoneId,
  value,
  defaultValue = { start: "", end: "" },
  onValueChange,
  required = false,
  disabled = false,
  className,
}: DateTimeRangePickerProps) {
  const controlled = value !== undefined;
  const current = value ?? defaultValue;
  const [internalValue, setInternalValue] = React.useState(defaultValue);
  const displayed = controlled ? current : internalValue;
  const rootRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const form = rootRef.current?.closest("form");
    if (!form || controlled) return;

    const reset = () => setInternalValue(defaultValue);
    form.addEventListener("reset", reset);
    return () => form.removeEventListener("reset", reset);
  }, [controlled, defaultValue]);

  function updateValue(field: "start" | "end", part: "date" | "time", nextPart: string) {
    const parts = wallClockParts(displayed[field]);
    const nextValue = `${part === "date" ? nextPart : parts.date}T${part === "time" ? nextPart : parts.time}`;
    const next = {
      ...displayed,
      [field]: nextValue === "T" ? "" : nextValue,
    };

    if (!controlled) setInternalValue(next);
    onValueChange?.(next);
  }

  function renderEndpoint(field: "start" | "end", endpointLabel: string) {
    const endpoint = wallClockParts(displayed[field]);
    const dateId = `${id}-${field}-date`;
    const timeId = `${id}-${field}-time`;

    return (
      <fieldset key={field} className="@container/endpoint min-w-0 space-y-1.5">
        <legend className="text-sm font-medium">{endpointLabel}</legend>
        <div className="grid min-w-0 gap-2 @min-[16rem]/endpoint:grid-cols-[minmax(0,1fr)_5.5rem]">
          <div className="grid min-w-0 gap-1">
            <label
              htmlFor={dateId}
              className="text-xs text-muted-foreground"
            >
              Date
            </label>
            <Input
              id={dateId}
              type="date"
              value={endpoint.date}
              onInput={(event) => updateValue(field, "date", event.currentTarget.value)}
              onChange={(event) =>
                updateValue(field, "date", event.target.value)
              }
              required={required}
              disabled={disabled}
              aria-label={`${endpointLabel} date`}
              className="w-full min-w-0 tabular-nums"
            />
          </div>
          <div className="grid min-w-0 gap-1">
            <label
              htmlFor={timeId}
              className="text-xs text-muted-foreground"
            >
              Time
            </label>
            <Input
              id={timeId}
              type="text"
              inputMode="numeric"
              autoComplete="off"
              placeholder="HH:MM"
              maxLength={5}
              pattern="(?:[01][0-9]|2[0-3]):[0-5][0-9]"
              value={endpoint.time}
              onChange={(event) =>
                updateValue(field, "time", event.target.value)
              }
              required={required}
              disabled={disabled}
              aria-label={`${endpointLabel} time`}
              className="w-full min-w-0 tabular-nums"
            />
          </div>
        </div>
      </fieldset>
    );
  }

  return (
    <div
      ref={rootRef}
      data-slot="date-time-range-picker"
      role="group"
      aria-label={`${label}, ${timeZoneId}, 24-hour clock`}
      className={cn("grid w-full min-w-0 grid-cols-[repeat(auto-fit,minmax(min(100%,16rem),1fr))] gap-3", className)}
    >
      <input type="hidden" name={startName} value={displayed.start} />
      <input type="hidden" name={endName} value={displayed.end} />
      {renderEndpoint("start", startLabel)}
      {renderEndpoint("end", endLabel)}
    </div>
  );
}

function displayDate(value: string) {
  const [year, month, day] = value.split("T", 1)[0]!.split("-");
  return year && month && day ? `${day}/${month}/${year}` : "Choose a date";
}

function displayRange(value: DateTimeRangeValue) {
  const start = wallClockParts(value.start);
  const end = wallClockParts(value.end);
  return `${displayDate(value.start)} · ${start.time} → ${displayDate(value.end)} · ${end.time}`;
}

function CompactDateTimeRangePicker({
  id, label, startLabel = "Starts", endLabel = "Ends", startName, endName,
  timeZoneId, value, defaultValue = { start: "", end: "" }, onValueChange,
  required = false, disabled = false, className,
}: DateTimeRangePickerProps) {
  const controlled = value !== undefined;
  const [internalValue, setInternalValue] = React.useState(defaultValue);
  const current = value ?? internalValue;
  const rootRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const [open, setOpen] = React.useState(false);
  const [draftRange, setDraftRange] = React.useState<DateRange | undefined>();
  const [selectingEnd, setSelectingEnd] = React.useState(false);
  const [startTime, setStartTime] = React.useState("09:00");
  const [endTime, setEndTime] = React.useState("17:00");
  const [error, setError] = React.useState<string | null>(null);
  const [monthCount, setMonthCount] = React.useState(1);

  React.useEffect(() => {
    const media = window.matchMedia("(min-width: 768px)");
    const update = () => setMonthCount(media.matches ? 2 : 1);
    update();
    media.addEventListener?.("change", update);
    return () => media.removeEventListener?.("change", update);
  }, []);

  React.useEffect(() => {
    const form = rootRef.current?.closest("form");
    if (!form || controlled) return;
    const reset = () => {
      setInternalValue(defaultValue);
      setOpen(false);
    };
    form.addEventListener("reset", reset);
    return () => form.removeEventListener("reset", reset);
  }, [controlled, defaultValue]);

  function handleOpenChange(next: boolean) {
    if (next) {
      const from = wallClockDate(current.start, timeZoneId);
      const to = wallClockDate(current.end, timeZoneId);
      setDraftRange(from ? { from, to } : undefined);
      setSelectingEnd(false);
      setStartTime(wallClockParts(current.start).time || "09:00");
      setEndTime(wallClockParts(current.end).time || "17:00");
      setError(null);
    }
    setOpen(next);
  }

  function applyRange() {
    if (!draftRange?.from || !draftRange.to) return;
    if (![startTime, endTime].every((time) => /^(?:[01]\d|2[0-3]):[0-5]\d$/.test(time))) {
      setError("Enter both times as HH:MM (24-hour).");
      return;
    }
    const next = {
      start: `${calendarDatePart(draftRange.from, timeZoneId)}T${startTime}`,
      end: `${calendarDatePart(draftRange.to, timeZoneId)}T${endTime}`,
    };
    const startInstant = wallClockToUtcIso(next.start, timeZoneId);
    const endInstant = wallClockToUtcIso(next.end, timeZoneId);
    if (!startInstant || !endInstant) {
      setError(`Choose valid dates and times in ${timeZoneId}.`);
      return;
    }
    if (Date.parse(endInstant) <= Date.parse(startInstant)) {
      setError(`${endLabel} must be after ${startLabel.toLowerCase()}.`);
      return;
    }
    if (!controlled) setInternalValue(next);
    onValueChange?.(next);
    setOpen(false);
  }

  function renderTime(endpoint: "start" | "end", endpointLabel: string, date?: Date) {
    return (
      <div className="grid min-w-0 gap-1">
        <label htmlFor={`${id}-${endpoint}-time`} className="text-xs font-medium">{endpointLabel}</label>
        <span className="text-xs text-muted-foreground tabular-nums">
          {date ? displayDate(calendarDatePart(date, timeZoneId)) : "Choose a date"}
        </span>
        <Input
          id={`${id}-${endpoint}-time`} aria-label={`${endpointLabel} time`}
          type="text" inputMode="numeric" autoComplete="off" placeholder="HH:MM" maxLength={5}
          pattern="(?:[01][0-9]|2[0-3]):[0-5][0-9]" className="w-full min-w-0 tabular-nums"
          value={endpoint === "start" ? startTime : endTime}
          onChange={(event) => {
            event.stopPropagation();
            (endpoint === "start" ? setStartTime : setEndTime)(event.target.value);
            setError(null);
          }}
        />
      </div>
    );
  }

  const hasValue = Boolean(current.start && current.end);
  return (
    <div ref={rootRef} data-slot="date-time-range-picker" role="group"
      aria-label={`${label}, ${timeZoneId}, 24-hour clock`} className={cn("w-full min-w-0", className)}>
      {(["start", "end"] as const).map((endpoint) => (
        <input key={endpoint} type="text" name={endpoint === "start" ? startName : endName}
          value={current[endpoint]} onChange={() => undefined} required={required} disabled={disabled}
          tabIndex={-1} aria-label={`${label} ${endpoint} value`} className="sr-only"
          onInvalid={(event) => {
            event.preventDefault();
            handleOpenChange(true);
            triggerRef.current?.focus();
          }}
        />
      ))}
      <Popover open={open} onOpenChange={handleOpenChange}>
        <PopoverTrigger render={
          <Button ref={triggerRef} id={id} type="button" variant="outline" disabled={disabled}
            aria-label={label} aria-required={required}
            className={cn("h-auto min-h-10 w-full justify-start gap-2 px-3 py-2 text-left font-normal", !hasValue && "text-muted-foreground")}>
            <CalendarDays className="size-4 shrink-0" aria-hidden="true" />
            <span className="min-w-0 flex-1 whitespace-normal text-xs leading-relaxed tabular-nums">
              {hasValue ? displayRange(current) : `Choose ${label.toLowerCase()}`}
            </span>
          </Button>
        } />
        <PopoverContent align="start" aria-label={`${label} dates and times`}
          className="max-h-[calc(100dvh-2rem)] w-auto max-w-[calc(100vw-2rem)] gap-0 overflow-y-auto p-0">
          <Calendar mode="range" selected={draftRange} defaultMonth={draftRange?.from}
            onSelect={(next, date) => {
              // Start a fresh interval instead of extending the prefilled dates.
              setDraftRange(selectingEnd ? next : { from: date, to: date });
              setSelectingEnd(!selectingEnd);
              setError(null);
            }}
            numberOfMonths={monthCount} timeZone={timeZoneId} />
          <div className="space-y-3 border-t p-3">
            <div className="grid grid-cols-2 gap-3">
              {renderTime("start", startLabel, draftRange?.from)}
              {renderTime("end", endLabel, draftRange?.to)}
            </div>
            <p className="text-xs text-muted-foreground">{timeZoneId} · 24-hour clock</p>
            {error ? <p role="alert" className="text-xs text-destructive">{error}</p> : null}
            <div className="flex justify-end gap-2">
              <Button type="button" variant="ghost" size="sm" onClick={() => setOpen(false)}>Cancel</Button>
              <Button type="button" size="sm" disabled={!draftRange?.from || !draftRange.to}
                onClick={applyRange} aria-label={`Apply ${label.toLowerCase()}`}>Apply</Button>
            </div>
          </div>
        </PopoverContent>
      </Popover>
    </div>
  );
}

'use client';

import React from 'react';
import { Slider } from '@game-guild/ui/components/slider';

export interface ImageSizeControlProps {
  size: number;
  onChange: (newSize: number) => void;
}

export function ImageSizeControl({ size, onChange }: ImageSizeControlProps) {
  const handleChange = (values: number | readonly number[]) => {
    const value = (Array.isArray(values) ? values[0] : values) ?? size;
    onChange(value);
  };

  return (
    <div className="flex items-center gap-3">
      <span className="text-sm w-16">Size</span>
      <Slider value={[size]} min={10} max={100} step={1} onValueChange={handleChange} className="flex-1" />
      <span className="text-sm w-10 text-right">{size}%</span>
    </div>
  );
}

"use client"

import { useCallback, useEffect, useRef, useState } from "react"

/**
 * Minimal ambient types for the Google Identity Services surface used here.
 * Avoids pulling in @types/google.accounts as a new dependency.
 */
export interface GisCredentialResponse {
  credential: string
  select_by?: string
}

export interface GisIdConfiguration {
  client_id: string
  callback: (response: GisCredentialResponse) => void
  auto_select?: boolean
  cancel_on_tap_outside?: boolean
}

export type GisButtonType = "standard" | "icon"
export type GisButtonTheme = "outline" | "filled_blue" | "filled_black"
export type GisButtonSize = "large" | "medium" | "small"
export type GisButtonShape = "rectangular" | "pill" | "circle" | "square"
export type GisButtonText =
  | "signin_with"
  | "signup_with"
  | "continue_with"
  | "signin"

export interface GisRenderButtonOptions {
  type?: GisButtonType
  theme?: GisButtonTheme
  size?: GisButtonSize
  text?: GisButtonText
  shape?: GisButtonShape
  width?: number
  locale?: string
}

export interface GisId {
  initialize: (config: GisIdConfiguration) => void
  renderButton: (parent: HTMLElement, options: GisRenderButtonOptions) => void
  prompt: () => void
  disableAutoSelect: () => void
  cancel: () => void
}

/**
 * Typed accessor for the GIS surface. Avoids redeclaring Window.google
 * globally (an existing module already declares it as `any`).
 */
function getGisId(): GisId | undefined {
  return (window as unknown as { google?: { accounts?: { id?: GisId } } })
    .google?.accounts?.id
}

/* ------------------------------------------------------------------ */
/*  Module-level singletons (one script, one initialize per page)     */
/* ------------------------------------------------------------------ */

const GIS_SCRIPT_SRC = "https://accounts.google.com/gsi/client"

// ponytail: module-level cache — GIS script must load once and initialize
// must run once per page even when multiple consumers mount. The One Tap
// component (T6) reuses this surface without re-initializing.
let scriptPromise: Promise<void> | null = null
let initialized = false

function loadGisScript(): Promise<void> {
  if (scriptPromise) return scriptPromise
  scriptPromise = new Promise<void>((resolve, reject) => {
    if (typeof window === "undefined" || typeof document === "undefined") {
      reject(new Error("Google Identity Services requires a browser environment"))
      return
    }
    // Already present (e.g. test pre-seed, or another tab instance).
    if (getGisId()) {
      resolve()
      return
    }
    const script = document.createElement("script")
    script.src = GIS_SCRIPT_SRC
    script.async = true
    script.defer = true
    script.onload = () => resolve()
    script.onerror = () => {
      // Allow a future consumer to retry after a transient failure.
      scriptPromise = null
      reject(new Error("Failed to load Google Identity Services script"))
    }
    document.head.appendChild(script)
  })
  return scriptPromise
}

/* ------------------------------------------------------------------ */
/*  Hook                                                               */
/* ------------------------------------------------------------------ */

export type GisStatus = "loading" | "ready" | "error"

export interface UseGoogleIdentityServiceOptions {
  /**
   * Invoked with the (untrusted) Google ID token. Callers route it to the
   * backend verifier via signIn("google", { idToken }). NEVER decode it
   * client-side.
   */
  onCredential: (credential: string) => void
}

export interface GoogleIdentityService {
  status: GisStatus
  /**
   * Renders Google's branded Sign-In button into `parent`. No-op until
   * status === "ready".
   */
  renderButton: (parent: HTMLElement, options: GisRenderButtonOptions) => void
  /**
   * Triggers the One Tap prompt. Reused by T6 (<GoogleOneTap/>).
   */
  prompt: () => void
}

/**
 * Test-only seam: resets the module-level singleton guards so each test
 * gets a clean initialize. NOT for production use.
 */
export function __resetGisForTest(): void {
  scriptPromise = null
  initialized = false
}

export function useGoogleIdentityService({
  onCredential,
}: UseGoogleIdentityServiceOptions): GoogleIdentityService {
  const [status, setStatus] = useState<GisStatus>("loading")
  // Latest callback in a ref so initialize (called once) always dispatches
  // to the freshest consumer without re-initializing.
  const callbackRef = useRef(onCredential)
  callbackRef.current = onCredential

  useEffect(() => {
    let alive = true
    const clientId = process.env.NEXT_PUBLIC_GOOGLE_CLIENT_ID
    if (!clientId) {
      setStatus("error")
      return
    }

    loadGisScript()
      .then(() => {
        if (!alive) return
        const id = getGisId()
        if (!id) {
          setStatus("error")
          return
        }
        if (!initialized) {
          id.initialize({
            client_id: clientId,
            callback: ({ credential }) => {
              if (credential) callbackRef.current(credential)
            },
            // ponytail: no auto_select — it silently re-signs-in the previous
            // Google account on /sign-in and hijacks manual credential logins
            // (bug: admin login landing as old account -> dashboard 403).
            // One Tap prompt + button still work via explicit click.
            auto_select: false,
            cancel_on_tap_outside: false,
          })
          initialized = true
        }
        setStatus("ready")
      })
      .catch(() => {
        if (alive) setStatus("error")
      })

    return () => {
      alive = false
    }
  }, [])

  const renderButton = useCallback(
    (parent: HTMLElement, options: GisRenderButtonOptions) => {
      getGisId()?.renderButton(parent, options)
    },
    [],
  )

  const prompt = useCallback(() => {
    getGisId()?.prompt()
  }, [])

  return { status, renderButton, prompt }
}

"use client";

import { useMemo, useState } from "react";
import { useAuth } from "@game-guild/client/react";
import { TurnstileWidget } from "@/components/antibot/turnstile-widget";
import {
  Web3Provider,
  createWalletAdapters,
  shortenAddress,
  useWeb3,
  useWalletAddress,
} from "@game-guild/web3";
import type { SiweTransport, WalletAdapter } from "@game-guild/web3";

/**
 * Wallet sign-in button group (issues #16/#17/#18/#38/#39 under umbrella
 * #291).
 *
 * Renders one button per available wallet from the wallet-adapter registry:
 * MetaMask whenever the injected provider is detected, Trust Wallet through
 * EIP-6963/injected detection with a mobile deep-link fallback (#17), and
 * WalletConnect behind NEXT_PUBLIC_WALLETCONNECT_PROJECT_ID (#18, adapter
 * additionally fails closed when the SDK is not installed). Torus stays
 * behind NEXT_PUBLIC_WALLET_TORUS_ENABLED. Clicking runs the full SIWE
 * journey against the existing backend endpoints: same-origin
 * /api/auth/web3/challenge proxy → personal_sign → signIn("credentials", …)
 * which the server-side web3 credentials wrapper verifies via
 * /v1/auth/web3:verify.
 */

const CHALLENGE_ENDPOINT = "/api/auth/web3/challenge";

const TORUS_ENABLED = process.env.NEXT_PUBLIC_WALLET_TORUS_ENABLED === "true";
const WALLETCONNECT_PROJECT_ID = process.env.NEXT_PUBLIC_WALLETCONNECT_PROJECT_ID;

export interface WalletSignInLabels {
  continueWithWallet: string;
  connecting: string;
  signing: string;
  connected: string;
  disconnect: string;
}

const ERROR_MESSAGES: Record<string, string> = {
  user_rejected: "You rejected the request in your wallet. Nothing was signed.",
  wallet_not_found: "This wallet was not detected in your browser.",
  challenge_failed: "Could not start wallet sign-in. Please try again.",
  "bot-check-failed": "Bot check failed. Please refresh and try again.",
  verification_failed: "Wallet sign-in failed. The challenge may have expired — please try again.",
  unauthorized: "Connect your wallet first.",
  disconnected: "Your wallet disconnected.",
};

const friendlyError = (code: string, detail: string): string => {
  const base = ERROR_MESSAGES[code] ?? "Wallet sign-in failed.";
  return detail && !ERROR_MESSAGES[code] ? `${base} ${detail}` : base;
};

const walletIcon = (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" aria-hidden="true" className="size-5">
    <path d="M3 7.5A2.5 2.5 0 0 1 5.5 5H18a2 2 0 0 1 2 2v1" strokeLinecap="round" />
    <path d="M3 7.5V17a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-3" strokeLinecap="round" />
    <path d="M21 10h-4.5a2.5 2.5 0 0 0 0 5H21v-5Z" strokeLinecap="round" />
  </svg>
);

/**
 * Wallet adapters registered for the sign-in buttons: the shared registry
 * (MetaMask + Trust Wallet by default, WalletConnect/Torus behind their
 * deployment gates). Exported for tests and host apps that render the same
 * wallet set elsewhere.
 */
export const createSignInWalletAdapters = (): WalletAdapter[] =>
  createWalletAdapters({
    ...(TORUS_ENABLED ? { torus: { enabled: true, network: { host: "mainnet" } } } : {}),
    // Config-gated fail-closed: without a project id the adapter reports
    // unavailable and the button stays hidden (#18).
    ...(WALLETCONNECT_PROJECT_ID
      ? { walletConnect: { enabled: true, projectId: WALLETCONNECT_PROJECT_ID } }
      : {}),
  });

export function WalletSignInButtons({
  redirectTo,
  labels,
  adapters,
}: {
  redirectTo?: string;
  labels: WalletSignInLabels;
  /** Overrides the default registry composition (tests, host reuse). */
  adapters?: readonly WalletAdapter[];
}) {
  const registered = useMemo<WalletAdapter[]>(
    () => (adapters ? [...adapters] : createSignInWalletAdapters()),
    [adapters],
  );

  return (
    <Web3Provider adapters={registered}>
      <WalletButtonGroup redirectTo={redirectTo} labels={labels} />
    </Web3Provider>
  );
}

function WalletButtonGroup({
  redirectTo,
  labels,
}: {
  redirectTo?: string;
  labels: WalletSignInLabels;
}) {
  const { signIn } = useAuth();
  // Keep the anti-bot token with the wallet context and clear it on challenge failure.
  const [turnstileToken, setTurnstileToken] = useState<string | null>(null);
  // Accessed through the context object (not destructured): the linter's
  // unbound-method rule fires on functions separated from their owning
  // object. `useWeb3` (not the `useWallet` snapshot) exposes `authenticate`
  // alongside the connection lifecycle.
  const web3 = useWeb3();
  const isPending =
    web3.state.status === "connecting" || web3.state.status === "signing";
  // The account lives on the full context state, not the wallet snapshot.
  const account = useWalletAddress() ?? null;

  const transport = useMemo<SiweTransport>(
    () => ({
      getChallenge: async (request) => {
        const response = await fetch(CHALLENGE_ENDPOINT, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            walletAddress: request.walletAddress,
            chainId: request.chainId,
            turnstileToken,
          }),
        }).catch((error) => {
          setTurnstileToken(null);
          throw error;
        });
        const data = (await response.json().catch(() => null)) as {
          challenge?: string;
          nonce?: string;
          expiresAt?: string;
          message?: string;
          error?: string;
        } | null;
        if (!response.ok || !data?.challenge || !data.nonce) {
          setTurnstileToken(null);
          throw new Error(data?.message ?? data?.error ?? "challenge_failed");
        }
        return { challenge: data.challenge, nonce: data.nonce, expiresAt: data.expiresAt };
      },
      verify: async (request) => {
        // The credentials server action verifies the signature against
        // /v1/auth/web3:verify and establishes the session cookie. Any
        // failure is rethrown so the context lands in verification_failed.
        await signIn("credentials", {
          siweWalletAddress: request.walletAddress,
          siweChallenge: request.challenge,
          siweSignature: request.signature,
          siweNonce: request.nonce,
          siweChainId: request.chainId,
          rememberMe: true,
          redirectTo,
        });
      },
    }),
    [signIn, redirectTo, turnstileToken],
  );

  async function handleConnect(walletId: string) {
    web3.clearError();
    try {
      await web3.connect(walletId);
      await web3.authenticate(transport);
    } catch {
      // State machine already surfaced the error below the buttons.
    }
  }

  const availableWallets = web3.wallets.filter((wallet) => wallet.available);

  if (availableWallets.length === 0) return null;

  if (account) {
    return (
      <div className="flex flex-col gap-2" data-testid="wallet-connected">
        <div className="flex h-10 w-full items-center justify-center gap-2 rounded-md border border-white/10 bg-white/5 text-sm font-medium text-white">
          {walletIcon}
          {labels.connected.replace("{address}", shortenAddress(account))}
        </div>
        <button
          type="button"
          data-testid="wallet-disconnect"
          onClick={() => void web3.disconnect().catch(() => undefined)}
          className="text-xs text-slate-400 underline-offset-4 hover:text-slate-200 hover:underline"
        >
          {labels.disconnect}
        </button>
        {web3.state.error ? <WalletError error={web3.state.error} /> : null}
      </div>
    );
  }

  return (
    <div className="contents" data-testid="wallet-sign-in-buttons">
      <TurnstileWidget onToken={setTurnstileToken} id="wallet-sign-in-turnstile" />
      {availableWallets.map((wallet) => (
        <button
          key={wallet.id}
          type="button"
          data-testid={`${wallet.id}-sign-in-button`}
          disabled={isPending}
          onClick={() => void handleConnect(wallet.id)}
          className="flex h-10 w-full items-center justify-center gap-2 rounded-md border border-white/10 bg-white/10 text-sm font-medium text-white shadow-xs transition hover:bg-white/15 focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-ring/50 active:translate-y-px disabled:cursor-not-allowed disabled:opacity-60"
        >
          {walletIcon}
          {web3.state.status === "signing"
            ? labels.signing
            : web3.state.status === "connecting"
              ? labels.connecting
              : labels.continueWithWallet.replace("{wallet}", wallet.name)}
        </button>
      ))}
      {web3.state.error ? <WalletError error={web3.state.error} /> : null}
    </div>
  );
}

function WalletError({ error }: { error: { code: string; message: string } }) {
  return (
    <p role="alert" data-testid="wallet-error" className="text-xs text-red-300">
      {friendlyError(error.code, error.message)}
    </p>
  );
}

