'use server';

import { getToken } from '@/auth';
import {
  createServerClient,
  GeneratedApi,
  type IdentityAuthenticationBackupCodesStatusOutput,
  type IdentityAuthenticationMfaConfigurationOutput,
  type IdentityAuthenticationMfaMethodsOutput,
  type IdentityAuthenticationMfaSetupOutput,
} from '@game-guild/client';
import { revalidatePath } from 'next/cache';

/**
 * Server actions for the MFA method-management surface (settings/security, issue #244).
 *
 * Mirrors sessions-actions.ts: bearer via createServerClient + getToken; every mutation
 * revalidates the security page so the method list, recovery-code status and profile state
 * reflect server state after each action.
 */

const SETTINGS_SECURITY_PATH = '/workspace/settings/security';

function getApiClient() {
  const apiUrl =
    process.env.API_URL ||
    process.env.NEXT_PUBLIC_API_URL ||
    'http://localhost:8080';
  return createServerClient({
    baseUrl: apiUrl,
    auth: { getAccessToken: () => getToken() },
  });
}

export interface MfaPageData {
  configuration: IdentityAuthenticationMfaConfigurationOutput | null;
  methods: IdentityAuthenticationMfaMethodsOutput | null;
  backupCodes: IdentityAuthenticationBackupCodesStatusOutput | null;
}

export type MfaActionStatus = 'success' | 'notFound' | 'unauthorized' | 'error';

export interface MfaActionResult {
  success: boolean;
  status: MfaActionStatus;
  message?: string;
}

/** Result of starting an enrollment: provisioning data (TOTP) or delivery metadata (SMS). */
export interface MfaEnrollmentStartResult extends MfaActionResult {
  setup?: IdentityAuthenticationMfaSetupOutput;
  smsSetup?: {
    message?: string | null;
    phoneNumberMasked?: string | null;
    expiresInSeconds?: number;
  };
}

/** Result of regenerating recovery codes: the fresh codes, shown exactly once. */
export interface MfaBackupCodesResult extends MfaActionResult {
  codes?: string[];
}

function statusFromError(error: { status?: number } | undefined): MfaActionStatus {
  switch (error?.status) {
    case 401:
      return 'unauthorized';
    case 404:
      return 'notFound';
    default:
      return 'error';
  }
}

function resultFrom(success: boolean, error?: { status?: number }, message?: string): MfaActionResult {
  return success
    ? { success: true, status: 'success', message }
    : { success: false, status: statusFromError(error) };
}

function errorMessage(error?: { message?: string; detail?: string }): string | undefined {
  const message = error?.detail ?? error?.message;
  return message && message.length > 0 ? message : undefined;
}

/**
 * Defensive read for page loaders (issue #864): the generated client's
 * safeParse THROWS on zod contract mismatch, and a throw inside a server
 * component render crashes the page with React #441. Any failure — thrown
 * validation/network error or a non-ok result — must degrade to `fallback`
 * so the security page renders with empty data instead of erroring.
 */
async function safeLoad<T>(call: () => Promise<{ ok: boolean; data?: T }>, fallback: T | null): Promise<T | null> {
  try {
    const result = await call();
    return result.ok ? (result.data ?? fallback) : fallback;
  } catch {
    // Contract drift between the deployed API and the generated client (issue #864):
    // render the page with degraded data rather than crashing the RSC render.
    return fallback;
  }
}

/** Loads the MFA configuration, method catalog and recovery-code status in one pass. */
export async function loadMfaData(): Promise<MfaPageData> {
  const mfaModule = new GeneratedApi.AuthMultiFactorModule(getApiClient());

  const [configuration, methods, backupCodes] = await Promise.all([
    safeLoad(() => mfaModule.getAuthMfa(), null),
    safeLoad(() => mfaModule.getAuthMfaMethods(), null),
    safeLoad(() => mfaModule.getAuthMfaBackupCodes(), null),
  ]);

  return { configuration, methods, backupCodes };
}

/** Starts authenticator-app (TOTP) enrollment, returning the secret and QR provisioning URI. */
export async function startTotpEnrollmentAction(): Promise<MfaEnrollmentStartResult> {
  const mfaModule = new GeneratedApi.AuthMultiFactorModule(getApiClient());
  const result = await mfaModule.postAuthMfaTotpSetup();

  if (!result.ok) {
    return { ...resultFrom(false, result.error, errorMessage(result.error)), setup: undefined };
  }

  return { success: true, status: 'success', setup: result.data ?? undefined };
}

/** Completes authenticator-app (TOTP) enrollment by verifying a code from the app. */
export async function completeTotpEnrollmentAction(code: string, secretKey: string): Promise<MfaActionResult> {
  const mfaModule = new GeneratedApi.AuthMultiFactorModule(getApiClient());
  // The generated contract carries the provisioning secret alongside the code; the server
  // verifies against the stored pending enrollment and ignores the echo for SMS.
  const result = await mfaModule.postAuthMfaTotpComplete({ code, secretKey });
  revalidatePath(SETTINGS_SECURITY_PATH);

  if (!result.ok) {
    return resultFrom(false, result.error, errorMessage(result.error));
  }

  return resultFrom(true);
}

/** Starts SMS enrollment by sending a verification code to the given phone number. */
export async function startSmsEnrollmentAction(phoneNumber: string): Promise<MfaEnrollmentStartResult> {
  const mfaModule = new GeneratedApi.AuthMultiFactorModule(getApiClient());
  const result = await mfaModule.postAuthMfaSmsSetup({ phoneNumber });

  if (!result.ok) {
    return { ...resultFrom(false, result.error, errorMessage(result.error)), smsSetup: undefined };
  }

  return { success: true, status: 'success', smsSetup: result.data ?? undefined };
}

/** Completes SMS enrollment by verifying the code sent to the pending phone number. */
export async function completeSmsEnrollmentAction(code: string): Promise<MfaActionResult> {
  const mfaModule = new GeneratedApi.AuthMultiFactorModule(getApiClient());
  // SMS enrollment has no provisioning secret; the contract field stays empty.
  const result = await mfaModule.postAuthMfaSmsComplete({ code, secretKey: '' });
  revalidatePath(SETTINGS_SECURITY_PATH);

  if (!result.ok) {
    return resultFrom(false, result.error, errorMessage(result.error));
  }

  return resultFrom(true);
}

/** Regenerates the recovery (backup) codes; the fresh set is shown exactly once. */
export async function regenerateBackupCodesAction(): Promise<MfaBackupCodesResult> {
  const mfaModule = new GeneratedApi.AuthMultiFactorModule(getApiClient());
  const result = await mfaModule.postAuthMfaBackupCodesRegenerate();
  revalidatePath(SETTINGS_SECURITY_PATH);

  if (!result.ok) {
    return { ...resultFrom(false, result.error, errorMessage(result.error)), codes: undefined };
  }

  return { success: true, status: 'success', codes: result.data?.codes ?? [] };
}

/** Disables MFA after re-verifying the account password (server enforces password proof). */
export async function disableMfaAction(password: string): Promise<MfaActionResult> {
  const mfaModule = new GeneratedApi.AuthMultiFactorModule(getApiClient());
  const result = await mfaModule.postAuthMfaDisable({ password });
  revalidatePath(SETTINGS_SECURITY_PATH);

  if (!result.ok) {
    return resultFrom(false, result.error, errorMessage(result.error));
  }

  return resultFrom(true);
}

'use server';

import { extractErrorMessage, verifyEmail, resendVerificationEmail } from '@game-guild/client';
import { verifyTurnstileToken } from '@/lib/antibot/turnstile';
import { forwardedIpHeaders } from '@/lib/server/forwarded-headers';
import { assertSafeServiceUrl } from '@/lib/security/safe-remote-url';

type ActionResult<T = void> = { success: true; data: T } | { success: false; error: string };

const apiUrl = process.env.API_URL || process.env.NEXT_PUBLIC_API_URL || '';

/**
 * Public password-reset surfaces: the `turnstileToken` is verified BEFORE any
 * API call, never forwarded in the request body, and the caller's trusted
 * client IP (`cf-connecting-ip`) rides along as `X-Forwarded-For` so backend
 * rate limiting sees the real visitor.
 */
export async function requestPasswordResetAction(email: string, turnstileToken?: string | null): Promise<ActionResult> {
  const verification = await verifyTurnstileToken(turnstileToken);
  if (!verification.success) {
    return { success: false, error: 'Bot check failed. Please refresh and try again.' };
  }

  if (!email?.trim()) {
    return { success: false, error: 'Email is required.' };
  }

  try {
    const response = await fetch(assertSafeServiceUrl(`${apiUrl}/v1/auth/password:reset-request`, apiUrl), {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(await forwardedIpHeaders()),
      },
      body: JSON.stringify({ email: email.trim() }),
    });

    // Always succeed from the caller's perspective (prevent email enumeration)
    // unless the backend explicitly rejects the request.
    if (!response.ok) {
      let payload: Record<string, unknown> | null = null;
      try {
        payload = (await response.json()) as Record<string, unknown>;
      } catch {
        payload = null;
      }
      return {
        success: false,
        error: extractErrorMessage(payload ?? {}, 'Failed to send reset email.'),
      };
    }

    return { success: true, data: undefined };
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : 'Failed to send reset email.',
    };
  }
}

export async function completePasswordResetAction(
  token: string,
  newPassword: string,
  confirmPassword: string,
  turnstileToken?: string | null,
): Promise<ActionResult> {
  const verification = await verifyTurnstileToken(turnstileToken);
  if (!verification.success) {
    return { success: false, error: 'Bot check failed. Please refresh and try again.' };
  }

  if (!token?.trim()) return { success: false, error: 'The password reset link is invalid or incomplete.' };
  if (newPassword.length < 8) return { success: false, error: 'Password must contain at least 8 characters.' };
  if (newPassword !== confirmPassword) return { success: false, error: 'Passwords do not match.' };

  try {
    const response = await fetch(assertSafeServiceUrl(`${apiUrl}/v1/auth/password:reset`, apiUrl), {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(await forwardedIpHeaders()),
      },
      body: JSON.stringify({ token: token.trim(), newPassword }),
    });

    if (!response.ok) {
      let payload: Record<string, unknown> | null = null;
      try {
        payload = (await response.json()) as Record<string, unknown>;
      } catch {
        payload = null;
      }
      return {
        success: false,
        error: extractErrorMessage(payload ?? {}, 'Password reset failed. Request a new link and try again.'),
      };
    }

    return { success: true, data: undefined };
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : 'Password reset failed. Request a new link and try again.',
    };
  }
}

export async function verifyEmailAction(token: string): Promise<ActionResult> {
  if (!token?.trim()) {
    return { success: false, error: 'Verification code is required.' };
  }

  try {
    await verifyEmail(apiUrl, { token: token.trim() });
    return { success: true, data: undefined };
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : 'Verification failed. Please try again.',
    };
  }
}

export async function resendVerificationEmailAction(email: string): Promise<ActionResult> {
  if (!email?.trim()) {
    return { success: false, error: 'Email is required.' };
  }

  try {
    await resendVerificationEmail(apiUrl, { email: email.trim() });
    return { success: true, data: undefined };
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : 'Failed to resend verification email.',
    };
  }
}

'use server';

import { getToken } from '@/auth';
import { createServerClient, GeneratedApi } from '@game-guild/client';
import { revalidatePath } from 'next/cache';

/**
 * Server action for the Password card (settings/account).
 *
 * Mirrors external-logins-actions.ts: bearer via createServerClient +
 * getToken; the card must never call signIn — session refresh after the
 * server's TokenVersion bump happens through useSession().update().
 */

const SETTINGS_ACCOUNT_PATH = '/workspace/settings/account';

export type PasswordChangeActionStatus =
  | 'success'
  /** 400 — current password missing/incorrect (or set-initial rejected). */
  | 'wrongCurrent'
  /** 400 — new password rejected by the server policy. */
  | 'weakPassword'
  /** 401 — no session / token missing. */
  | 'unauthorized'
  | 'error';

export interface PasswordChangeActionResult {
  success: boolean;
  status: PasswordChangeActionStatus;
  message?: string;
}

export interface PasswordChangeActionInput {
  currentPassword: string;
  newPassword: string;
  confirmPassword: string;
  revokeOtherSessions: boolean;
}

function getApiClient() {
  const apiUrl =
    process.env.API_URL ||
    process.env.NEXT_PUBLIC_API_URL ||
    'http://localhost:8080';
  return createServerClient({
    baseUrl: apiUrl,
    auth: { getAccessToken: () => getToken() },
  });
}

/**
 * Mirrors the server policy defaults (PasswordHasher: MinPasswordLength 8,
 * upper + lower + digit + special). The server message stays authoritative;
 * this only classifies a 400 whose body the client transport cannot read.
 */
function meetsServerPolicyDefaults(password: string): boolean {
  return (
    password.length >= 8 &&
    /[A-Z]/.test(password) &&
    /[a-z]/.test(password) &&
    /\d/.test(password) &&
    /[^A-Za-z0-9]/.test(password)
  );
}

/**
 * Classify a 400 from POST /v1/auth/password:change.
 *
 * Actual mechanism (verified): the server returns BadRequest(result) with the
 * PasswordChangeResult JSON body {success, message, sessionsRevoked}, but the
 * client transport (runtime/errors/transform.ts createApiError) only reads
 * ProblemDetails `title`/`detail` — the body's `message` is dropped and
 * error.message falls back to the statusText "Bad Request". So: prefer the
 * server message when a future client surfaces it; otherwise classify with
 * the policy mirror (policy-failing password -> weakPassword; policy-passing
 * password -> wrongCurrent, the only other reachable 400 after the client's
 * confirm-mismatch guard).
 */
function classifyBadRequest(
  newPassword: string,
  errorMessage: string | undefined,
  errorDetail: string | undefined,
): { status: PasswordChangeActionStatus; message?: string } {
  const detail = errorDetail?.trim() || undefined;
  const message =
    errorMessage && errorMessage.trim() !== '' && errorMessage !== 'Bad Request'
      ? errorMessage
      : undefined;
  const serverMessage = detail ?? message;
  if (serverMessage?.includes('Current password')) {
    return { status: 'wrongCurrent', message: serverMessage };
  }
  if (!meetsServerPolicyDefaults(newPassword)) {
    return { status: 'weakPassword', message: serverMessage };
  }
  return { status: 'wrongCurrent' };
}

export async function changePasswordAction(
  input: PasswordChangeActionInput,
): Promise<PasswordChangeActionResult> {
  const authModule = new GeneratedApi.AuthModule(getApiClient());
  const result = await authModule.postAuthPasswordChange({
    // Regenerated schema accepts null/undefined; an empty string is sent
    // as-is so null-hash (OAuth-only) accounts can set an initial password.
    currentPassword: input.currentPassword,
    newPassword: input.newPassword,
    confirmPassword: input.confirmPassword,
    revokeOtherSessions: input.revokeOtherSessions,
  });

  if (!result.ok) {
    const error = result.error;
    switch (error?.status) {
      case 400: {
        const classified = classifyBadRequest(input.newPassword, error.message, error.detail);
        return { success: false, ...classified };
      }
      case 401:
        return { success: false, status: 'unauthorized' };
      default:
        return { success: false, status: 'error' };
    }
  }

  revalidatePath(SETTINGS_ACCOUNT_PATH);
  return { success: true, status: 'success' };
}

'use server';

import { getToken } from '@/auth';
import {
  createServerClient,
  GeneratedApi,
  type IdentityAuthenticationSessionOutput,
  type IdentityAuthenticationSessionSecurityAnalysis,
  type IdentityAuthenticationTrustedDeviceOutput,
} from '@game-guild/client';
import { revalidatePath } from 'next/cache';

/**
 * Server actions for the session management surface (settings/security, issue #278).
 *
 * Mirrors password-change-action.ts: bearer via createServerClient + getToken. All
 * mutations revalidate the security page so the session and trusted-device lists
 * reflect server state after every action.
 */

const SETTINGS_SECURITY_PATH = '/workspace/settings/security';

function getApiClient() {
  const apiUrl =
    process.env.API_URL ||
    process.env.NEXT_PUBLIC_API_URL ||
    'http://localhost:8080';
  return createServerClient({
    baseUrl: apiUrl,
    auth: { getAccessToken: () => getToken() },
  });
}

export interface SessionsPageData {
  sessions: IdentityAuthenticationSessionOutput[];
  analysis: IdentityAuthenticationSessionSecurityAnalysis | null;
  trustedDevices: IdentityAuthenticationTrustedDeviceOutput[];
}

export type SessionActionStatus = 'success' | 'notFound' | 'unauthorized' | 'error';

export interface SessionActionResult {
  success: boolean;
  status: SessionActionStatus;
}

function statusFromError(error: { status?: number } | undefined): SessionActionStatus {
  switch (error?.status) {
    case 401:
      return 'unauthorized';
    case 404:
      return 'notFound';
    default:
      return 'error';
  }
}

function resultFrom(success: boolean, error?: { status?: number }): SessionActionResult {
  return success
    ? { success: true, status: 'success' }
    : { success: false, status: statusFromError(error) };
}

/**
 * Defensive read for page loaders (issue #864): the generated client's
 * safeParse THROWS on zod contract mismatch, and a throw inside a server
 * component render crashes the page with React #441. Any failure — thrown
 * validation/network error or a non-ok result — must degrade to `fallback`
 * so the security page renders with empty data instead of erroring.
 */
async function safeLoad<T>(call: () => Promise<{ ok: boolean; data?: T }>, fallback: T | null): Promise<T | null> {
  try {
    const result = await call();
    return result.ok ? (result.data ?? fallback) : fallback;
  } catch {
    // Contract drift between the deployed API and the generated client (issue #864):
    // render the page with degraded data rather than crashing the RSC render.
    return fallback;
  }
}

/**
 * Loads the session list, the current-session security analysis, and the trusted
 * device list in one pass for the settings/security page.
 */
export async function loadSessionsData(): Promise<SessionsPageData> {
  const client = getApiClient();
  const sessionsModule = new GeneratedApi.AuthSessionsModule(client);
  const trustedDevicesModule = new GeneratedApi.AuthTrustedDevicesModule(client);

  const [sessions, analysis, trustedDevices] = await Promise.all([
    safeLoad(() => sessionsModule.getAuthSessions(), []),
    safeLoad(() => sessionsModule.getAuthSessionsAnalyzeSecurity(), null),
    safeLoad(() => trustedDevicesModule.getAuthTrustedDevices(), []),
  ]);

  return {
    sessions: sessions ?? [],
    analysis,
    trustedDevices: trustedDevices ?? [],
  };
}

/** Names or renames one of the current user's own sessions (1–64 characters). */
export async function renameSessionAction(sessionId: string, name: string): Promise<SessionActionResult> {
  const sessionsModule = new GeneratedApi.AuthSessionsModule(getApiClient());
  const result = await sessionsModule.patchAuthSessionsName(sessionId, { name });
  revalidatePath(SETTINGS_SECURITY_PATH);
  return resultFrom(result.ok, result.ok ? undefined : result.error);
}

/** Terminates one specific session owned by the current user. */
export async function terminateSessionAction(sessionId: string): Promise<SessionActionResult> {
  const sessionsModule = new GeneratedApi.AuthSessionsModule(getApiClient());
  const result = await sessionsModule.deleteAuthSessions(sessionId);
  revalidatePath(SETTINGS_SECURITY_PATH);
  return resultFrom(result.ok, result.ok ? undefined : result.error);
}

/** Terminates every session except the current one. */
export async function terminateOtherSessionsAction(): Promise<SessionActionResult> {
  const sessionsModule = new GeneratedApi.AuthSessionsModule(getApiClient());
  const result = await sessionsModule.postAuthSessionsTerminateOthers();
  revalidatePath(SETTINGS_SECURITY_PATH);
  return resultFrom(result.ok, result.ok ? undefined : result.error);
}

/** Terminates every session including the current one (signs the user out everywhere). */
export async function terminateAllSessionsAction(): Promise<SessionActionResult> {
  const sessionsModule = new GeneratedApi.AuthSessionsModule(getApiClient());
  const result = await sessionsModule.postAuthSessionsTerminateAll();
  revalidatePath(SETTINGS_SECURITY_PATH);
  return resultFrom(result.ok, result.ok ? undefined : result.error);
}

/** Marks the device behind the current session as trusted. */
export async function trustCurrentDeviceAction(deviceName?: string): Promise<SessionActionResult> {
  const trustedDevicesModule = new GeneratedApi.AuthTrustedDevicesModule(getApiClient());
  const result = await trustedDevicesModule.postAuthTrustedDevices({
    deviceName: deviceName ?? '',
  });
  revalidatePath(SETTINGS_SECURITY_PATH);
  return resultFrom(result.ok, result.ok ? undefined : result.error);
}

/** Removes one device from the trusted device list. */
export async function revokeTrustedDeviceAction(deviceId: string): Promise<SessionActionResult> {
  const trustedDevicesModule = new GeneratedApi.AuthTrustedDevicesModule(getApiClient());
  const result = await trustedDevicesModule.deleteAuthTrustedDevices(deviceId);
  revalidatePath(SETTINGS_SECURITY_PATH);
  return resultFrom(result.ok, result.ok ? undefined : result.error);
}

import {
  AuthServiceUnavailableError,
  CredentialsSignInError,
  parseBackendAuthResponse,
  type CredentialsProviderConfig,
} from "@game-guild/client";

type CredentialsAuthorize = CredentialsProviderConfig["authorize"];

const WEB3_VERIFY_PATH = "/v1/auth/web3:verify";

/**
 * Extend the existing credentials provider with the SIWE wallet flow while
 * keeping email/password, magic-link and email-code authentication on their
 * existing implementations. When the browser submits a signed SIWE challenge
 * (`siweSignature` present) the wrapper verifies it against the backend's
 * `/v1/auth/web3:verify` endpoint and maps the response into the shared
 * session provider result.
 */
export function createWeb3CredentialsAuthorize(
  wrappedAuthorize: CredentialsAuthorize,
  apiUrl: string,
): CredentialsAuthorize {
  return async (credentials, request) => {
    if (!Object.hasOwn(credentials, "siweSignature")) {
      return wrappedAuthorize(credentials, request);
    }

    const walletAddress = credentials.siweWalletAddress;
    const challenge = credentials.siweChallenge;
    const signature = credentials.siweSignature;
    const nonce = credentials.siweNonce;
    const chainId = credentials.siweChainId;
    const invalid =
      typeof walletAddress !== "string" ||
      walletAddress.length === 0 ||
      typeof challenge !== "string" ||
      challenge.length === 0 ||
      typeof signature !== "string" ||
      signature.length === 0 ||
      typeof nonce !== "string" ||
      nonce.length === 0 ||
      typeof chainId !== "string" ||
      chainId.length === 0;
    if (invalid) {
      throw new CredentialsSignInError(
        "The wallet sign-in request is incomplete. Please try again.",
      );
    }

    const body: Record<string, unknown> = {
      walletAddress,
      challenge,
      signature,
      nonce,
      chainId,
    };
    const tenantId = credentials.tenantId;
    if (typeof tenantId === "string" && tenantId.trim().length > 0) {
      body.tenantId = tenantId.trim();
    }
    const deviceFingerprint = credentials.deviceFingerprint;
    if (typeof deviceFingerprint === "string" && deviceFingerprint.length > 0) {
      body.deviceFingerprint = deviceFingerprint;
    }
    if (credentials.rememberMe === true) {
      body.rememberMe = true;
    }

    const headers: Record<string, string> = {
      "Content-Type": "application/json",
    };
    const userAgent = request?.headers.get("user-agent");
    if (userAgent) headers["User-Agent"] = userAgent;

    let response: Response;
    try {
      response = await fetch(new URL(WEB3_VERIFY_PATH, apiUrl), {
        method: "POST",
        headers,
        body: JSON.stringify(body),
        cache: "no-store",
        credentials: "omit",
      });
    } catch (error) {
      throw new AuthServiceUnavailableError(
        "Authentication service is unreachable. Please try again.",
        error instanceof Error ? error : undefined,
      );
    }

    if (!response.ok) {
      if (response.status >= 500) throw new AuthServiceUnavailableError();
      const errorData = (await response.json().catch(() => ({}))) as {
        message?: string;
        detail?: string;
      };
      throw new CredentialsSignInError(
        errorData.message ||
          errorData.detail ||
          "Wallet sign-in failed. The challenge may have expired — please try again.",
      );
    }

    let data: unknown;
    try {
      data = await response.json();
    } catch {
      throw new AuthServiceUnavailableError(
        "The authentication service returned an invalid response.",
      );
    }

    if (typeof data !== "object" || data === null || Array.isArray(data)) {
      throw new AuthServiceUnavailableError(
        "The authentication service returned an invalid response.",
      );
    }

    const result = parseBackendAuthResponse(
      data as Record<string, unknown>,
      // Wallet accounts have no email; the backend may or may not provide one.
      "",
    );
    if (
      !result.user.id ||
      !result.tokens.accessToken ||
      !result.tokens.refreshToken
    ) {
      throw new AuthServiceUnavailableError(
        "The authentication service returned an incomplete sign-in response.",
      );
    }

    return {
      ...result,
      rememberMe: credentials.rememberMe === true,
    };
  };
}

'use server';

import { getRequestAuthContext } from '@/auth';
import { verifyTurnstileToken } from '@/lib/antibot/turnstile';
import { assertSafeServiceUrl } from '@/lib/security/safe-remote-url';
import { forwardedIpHeaders } from '@/lib/server/forwarded-headers';

import type {
  AddBlogCommentInput,
  BlogComment,
  BlogPostDetail,
  CreateBlogPostInput,
  UpdateBlogPostDraftInput,
} from './types';

const apiBaseUrl = (
  process.env.API_URL ||
  process.env.NEXT_PUBLIC_API_URL ||
  'http://localhost:8080'
).replace(/\/$/, '');

export type BlogActionResult<T> =
  | { success: true; data: T }
  | { success: false; error: string; status: number; code?: string }
  | {
      success: false;
      error: string;
      status: 409;
      code: 'revision-conflict';
      expectedRevision: number;
      currentRevision: number;
    };

interface ProblemDetails {
  title?: unknown;
  detail?: unknown;
  currentRevision?: unknown;
  expectedRevision?: unknown;
  errors?: unknown;
}

function readProblemField(body: unknown, name: string): unknown {
  if (body && typeof body === 'object' && name in body) {
    return (body as Record<string, unknown>)[name];
  }
  return undefined;
}

/**
 * Maps a failed API response to a typed action result. 409 ProblemDetails
 * responses carry `expectedRevision`/`currentRevision` and surface as the
 * `revision-conflict` variant so the editor can offer a reload.
 */
async function blogRequest<T>(path: string, init?: RequestInit): Promise<BlogActionResult<T>> {
  const { token, tenantId } = await getRequestAuthContext();
  if (!token || !tenantId) {
    return {
      success: false,
      error: 'You must be signed in to manage blog posts.',
      status: 401,
    };
  }

  const response = await fetch(assertSafeServiceUrl(`${apiBaseUrl}${path}`, apiBaseUrl), {
    ...init,
    redirect: 'error',
    headers: {
      Authorization: `Bearer ${token}`,
      'X-Tenant-Id': tenantId,
      ...(init?.body ? { 'Content-Type': 'application/json' } : {}),
      ...init?.headers,
    },
    cache: 'no-store',
  });

  const body = (await response.json().catch(() => null)) as ProblemDetails | T | null;
  if (!response.ok) {
    const error = readProblemField(body, 'detail');
    const message =
      (typeof error === 'string' && error) ||
      (typeof readProblemField(body, 'title') === 'string' && (readProblemField(body, 'title') as string)) ||
      response.statusText ||
      'Blog request failed.';

    if (response.status === 409) {
      return {
        success: false,
        error: message,
        status: 409,
        code: 'revision-conflict',
        expectedRevision: Number(readProblemField(body, 'expectedRevision') ?? 0),
        currentRevision: Number(readProblemField(body, 'currentRevision') ?? 0),
      };
    }

    return {
      success: false,
      error: message,
      status: response.status,
      code: typeof readProblemField(body, 'code') === 'string' ? (readProblemField(body, 'code') as string) : undefined,
    };
  }

  return { success: true, data: body as T };
}

function path(postId: string, suffix = ''): string {
  return `/api/social/blog/posts/${encodeURIComponent(postId)}${suffix}`;
}

const REACTION_TARGET_TYPE = 'BlogPost';
const REACTION_TYPE = 'Like';

export async function fetchViewerReaction(postId: string): Promise<{ reacted: boolean }> {
  const { token } = await getRequestAuthContext();
  if (!token) return { reacted: false };
  const response = await fetch(
    assertSafeServiceUrl(`${apiBaseUrl}/api/social/reactions/me/target/${REACTION_TARGET_TYPE}/${encodeURIComponent(postId)}`, apiBaseUrl),
    { redirect: 'error', headers: { Authorization: `Bearer ${token}` }, cache: 'no-store' },
  );
  if (!response.ok) return { reacted: false };
  const body = (await response.json().catch(() => null)) as { type?: string } | null;
  return { reacted: body?.type != null };
}

export async function setReaction(postId: string, react: boolean): Promise<{ ok: boolean }> {
  const { token, tenantId } = await getRequestAuthContext();
  if (!token || !tenantId) return { ok: false };
  const response = await fetch(assertSafeServiceUrl(`${apiBaseUrl}/api/social/reactions`, apiBaseUrl), {
    redirect: 'error',
    method: react ? 'PUT' : 'DELETE',
    headers: {
      Authorization: `Bearer ${token}`,
      'X-Tenant-Id': tenantId,
      ...(react ? { 'Content-Type': 'application/json' } : {}),
    },
    cache: 'no-store',
    ...(react ? { body: JSON.stringify({ targetType: REACTION_TARGET_TYPE, targetId: postId, type: REACTION_TYPE }) } : { body: JSON.stringify({ targetType: REACTION_TARGET_TYPE, targetId: postId }) }),
  });
  return { ok: response.ok };
}

export async function createPost(input: CreateBlogPostInput) {
  const result = await blogRequest<BlogPostDetail>('/api/social/blog/posts', {
    method: 'POST',
    body: JSON.stringify(input),
  });
  if (!result.success) return result;

  const primaryAuthorId = (result.data as { primaryAuthorId?: string }).primaryAuthorId;
  const handle = primaryAuthorId ? await fetchProfileHandle(primaryAuthorId) : null;
  const slug = result.data.slug;
  const editUrl = handle && slug ? `/blogs/${encodeURIComponent(handle)}/${encodeURIComponent(slug)}/edit` : null;
  return { success: true as const, data: result.data, editUrl };
}

async function fetchProfileHandle(userId: string): Promise<string | null> {
  const { token, tenantId } = await getRequestAuthContext();
  if (!token || !tenantId) return null;

  const response = await fetch(assertSafeServiceUrl(`${apiBaseUrl}/api/social/profiles/users/${encodeURIComponent(userId)}/or-create`, apiBaseUrl), {
    redirect: 'error',
    headers: { Authorization: `Bearer ${token}`, 'X-Tenant-Id': tenantId },
    cache: 'no-store',
  });
  if (!response.ok) return null;

  const profile = (await response.json().catch(() => null)) as { handle?: unknown } | null;
  return typeof profile?.handle === 'string' && profile.handle ? profile.handle : null;
}

/**
 * Public comment page for a post. Server action wrapper so client components
 * never import `@/lib/blogs/queries` (it chains to `@/auth` → `next/headers`,
 * which cannot be bundled for the client).
 */
export async function getBlogPostCommentsPage(
  postId: string,
  cursor?: { afterCreatedAt?: string; afterId?: string },
): Promise<{ items: BlogComment[]; hasMore: boolean } | null> {
  const { getBlogPostComments } = await import('./queries');
  const page = await getBlogPostComments(postId, cursor);
  if (!page) return null;
  return { items: page.items, hasMore: page.hasMore };
}

export async function updateDraft(postId: string, input: UpdateBlogPostDraftInput) {
  return blogRequest<BlogPostDetail>(path(postId), {
    method: 'PUT',
    body: JSON.stringify(input),
  });
}

export async function changeSlug(postId: string, newSlug: string) {
