import { createServerClient, GeneratedApi, type ApiError } from '@game-guild/client';

import { getRequestAuthContext } from '@/auth';

import type {
  BlogComment,
  BlogCommentPage,
  BlogPostDetail,
  BlogPostSummary,
  BlogPostSummaryPage,
  BlogRouteResolution,
} from './types';

const DEFAULT_API_URL = process.env.API_URL || process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8080';
const PUBLIC_BLOG_API_TIMEOUT_MS = Number(process.env.PUBLIC_BLOG_API_TIMEOUT_MS ?? 10_000);

function getApiUrl(): string {
  return DEFAULT_API_URL.replace(/\/$/, '');
}

function createPublicApiClient() {
  return createServerClient({
    baseUrl: getApiUrl(),
    timeout: Number.isFinite(PUBLIC_BLOG_API_TIMEOUT_MS) ? PUBLIC_BLOG_API_TIMEOUT_MS : 10_000,
  });
}

function createPublicBlogModules() {
  const client = createPublicApiClient();

  return {
    publicApi: new GeneratedApi.SocialBlogPublicModule(client),
  };
}

/**
 * Authenticated authoring client. Server-side only: resolves the session token
 * per request so the authoring module's `requiresAuth` requests carry Bearer +
 * tenant headers, mirroring the actions.ts fetch header contract.
 */
async function createAuthoringBlogModules() {
  const { token, tenantId } = await getRequestAuthContext();
  if (!token || !tenantId) {
    throw new Error('You must be signed in to manage blog posts.');
  }

  const client = createServerClient({
    baseUrl: getApiUrl(),
    auth: { getAccessToken: async () => token },
    tenant: { getTenantId: async () => tenantId },
    timeout: Number.isFinite(PUBLIC_BLOG_API_TIMEOUT_MS) ? PUBLIC_BLOG_API_TIMEOUT_MS : 10_000,
  });

  return {
    authoringApi: new GeneratedApi.SocialBlogAuthoringModule(client),
    profilesApi: new GeneratedApi.SocialProfilesModule(client),
  };
}

function errorStatus(error: ApiError | undefined): number | undefined {
  return error && typeof error.status === 'number' ? error.status : undefined;
}

/** Detail-or-redirect outcome for a `(handle, slug)` route. */
export type BlogPostLookup =
  | { status: 'ok'; post: BlogPostDetail }
  | { status: 'redirect'; redirect: BlogRouteResolution }
  | { status: 'not-found' };

export async function getBlogIndex(cursor?: {
  beforePublishedAt?: string;
  beforeId?: string;
}): Promise<BlogPostSummaryPage | null> {
  const { publicApi } = createPublicBlogModules();
  const result = await publicApi.getApiSocialBlogPublicPosts(cursor);
  if (!result.ok) {
    if (errorStatus(result.error) === 404) return null;
    throw new Error(`Failed to load blog index: ${result.error?.message ?? 'unknown error'}`);
  }

  return {
    items: (result.data.items ?? []) as BlogPostSummary[],
    hasMore: result.data.hasMore ?? false,
  };
}

export async function getAuthorPosts(
  handle: string,
  cursor?: { beforePublishedAt?: string; beforeId?: string },
): Promise<BlogPostSummaryPage | null> {
  const { publicApi } = createPublicBlogModules();
  const result = await publicApi.getApiSocialBlogPublicAuthorsForGetApiSocialBlogPublicAuthorsByHandle(handle, cursor);
  if (!result.ok) {
    if (errorStatus(result.error) === 404) return null;
    throw new Error(`Failed to load author posts: ${result.error?.message ?? 'unknown error'}`);
  }

  return {
    items: (result.data.items ?? []) as BlogPostSummary[],
    hasMore: result.data.hasMore ?? false,
  };
}

/**
 * Fetch a published post by route. Stale `(handle, slug)` pairs are resolved
 * through the slug-history endpoint so the page can 308-redirect to the
 * canonical route; unresolved routes yield `not-found` (caller calls
 * Next's `notFound()`).
 */
export async function getBlogPost(handle: string, slug: string): Promise<BlogPostLookup> {
  const { publicApi } = createPublicBlogModules();

  const detail = await publicApi.getApiSocialBlogPublicAuthorsForGetApiSocialBlogPublicAuthorsByHandleBySlug(handle, slug);
  if (detail.ok) {
    return { status: 'ok', post: detail.data as BlogPostDetail };
  }

  if (errorStatus(detail.error) !== 404) {
    throw new Error(`Failed to load blog post: ${detail.error?.message ?? 'unknown error'}`);
  }

  const resolution = await publicApi.getApiSocialBlogPublicResolve(handle, slug);
  if (resolution.ok && resolution.data.handle && resolution.data.slug) {
    return { status: 'redirect', redirect: { handle: resolution.data.handle, slug: resolution.data.slug } };
  }

  if (resolution.ok) {
    return { status: 'not-found' };
  }

  if (errorStatus(resolution.error) === 404) {
    return { status: 'not-found' };
  }

  throw new Error(`Failed to resolve blog route: ${resolution.error?.message ?? 'unknown error'}`);
}

export async function getBlogPostComments(
  postId: string,
  cursor?: { afterCreatedAt?: string; afterId?: string },
): Promise<BlogCommentPage | null> {
  const { publicApi } = createPublicBlogModules();
  const result = await publicApi.getApiSocialBlogPublicPostsComments(postId, cursor);
  if (!result.ok) {
    if (errorStatus(result.error) === 404) return null;
    throw new Error(`Failed to load comments: ${result.error?.message ?? 'unknown error'}`);
  }

  return {
    items: (result.data.items ?? []) as BlogComment[],
    hasMore: result.data.hasMore ?? false,
  };
}

export type { BlogPostSummary } from './types';

/**
 * Authoring-entity shape: same fields as the public detail DTO plus authorship
 * (primaryAuthorId) — the editor needs the id for primary-vs-coauthor role
 * checks, which the public DTO deliberately omits.
 */
export interface BlogPostAuthorView {
  id: string;
  primaryAuthorId: string;
  title: string | null;
  slug: string | null;
  excerpt: string | null;
  content: string | null;
  jsonBody: string | null;
  format: 'Markdown' | 'Lexical';
  tags: string[] | null;
  metaTitle: string | null;
  metaDescription: string | null;
  ogImageUrl: string | null;
  canonicalUrlOverride: string | null;
  twitterCard: string | null;
  structuredDataOverride: string | null;
  allowComments: boolean;
  status: 'Draft' | 'Published';
  publishedAt: string | null;
  revision: number;
  updatedAt: string;
}

export type MyPostLookup =
  | { status: 'ok'; post: BlogPostAuthorView }
  | { status: 'not-found' };

/**
 * Resolve an authoring route `(username, slug)` to the acting user's post.
 * The authoring surface is id-addressed (`GET mine` + `GET {id}`), so the slug
 * is matched within the actor's own post list — slugs are unique per primary
 * author, which the handle in the URL denotes.
 */
export async function getMyPostBySlug(username: string, slug: string): Promise<MyPostLookup> {
  void username;
  let authoringApi: InstanceType<typeof GeneratedApi.SocialBlogAuthoringModule>;
  try {
    ({ authoringApi } = await createAuthoringBlogModules());
  } catch {
    return { status: 'not-found' };
  }

  const mine = await authoringApi.getApiSocialBlogPostsMine();
  if (!mine.ok) {
    if (errorStatus(mine.error) === 404) return { status: 'not-found' };
    throw new Error(`Failed to load your blog posts: ${mine.error?.message ?? 'unknown error'}`);
  }

  const match = (mine.data ?? []).find((post) => post.slug === slug);
  if (!match?.id) return { status: 'not-found' };

  const detail = await authoringApi.getApiSocialBlogPosts(match.id);
  if (!detail.ok) {
    if (errorStatus(detail.error) === 404) return { status: 'not-found' };
    throw new Error(`Failed to load blog post: ${detail.error?.message ?? 'unknown error'}`);
  }

  return { status: 'ok', post: detail.data as unknown as BlogPostAuthorView };
}

/** Hub row for the workspace "Recent blog posts" card. */
export interface MyBlogPostRow {
  id: string;
  slug: string;
  title: string;
  status: 'Draft' | 'Published';
  format: 'Markdown' | 'Lexical';
  publishedAt: string | null;
  updatedAt: string;
  primaryAuthorHandle: string | null;
}

/**
 * The acting user's posts for hub management. The handle is resolved with a
 * read-only profile fetch (no or-create mutation on a listing surface); null
 * means the row links to the blogs index instead of the editor.
 */
export async function listMyBlogPosts(): Promise<MyBlogPostRow[]> {
  let authoringApi: InstanceType<typeof GeneratedApi.SocialBlogAuthoringModule>;
  let profilesApi: InstanceType<typeof GeneratedApi.SocialProfilesModule>;
  try {
    ({ authoringApi, profilesApi } = await createAuthoringBlogModules());
  } catch {
    return [];
  }

  const mine = await authoringApi.getApiSocialBlogPostsMine();
  if (!mine.ok) {
    throw new Error(`Failed to load your blog posts: ${mine.error?.message ?? 'unknown error'}`);
  }

  const posts = mine.data ?? [];
  if (posts.length === 0) return [];

  const primaryAuthorId = posts[0]?.primaryAuthorId;
  let handle: string | null = null;
  if (primaryAuthorId) {
    const profile = await profilesApi.getApiSocialProfilesUsers(primaryAuthorId);
    if (profile.ok && typeof profile.data.handle === 'string' && profile.data.handle) {
      handle = profile.data.handle;
    }
  }

  return posts.map((post) => ({
    id: post.id ?? '',
    slug: post.slug ?? '',
    title: post.title ?? 'Untitled',
    status: (post.status ?? 'Draft') as 'Draft' | 'Published',
    format: (post.format ?? 'Markdown') as 'Markdown' | 'Lexical',
    publishedAt: post.publishedAt ?? null,
    updatedAt: post.updatedAt,
    primaryAuthorHandle: handle,
  }));
}

import { buildBlogAuthorAbsoluteUrl, buildBlogAbsoluteCanonicalUrl, BLOG_SITE_BASE_URL } from '@/lib/blogs/seo';
import { getAuthorPosts } from '@/lib/blogs/queries';

export const RSS_ITEM_LIMIT = 20;

function xmlEscape(value: string): string {
  return value
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&apos;');
}

function rfc822(iso: string | null | undefined): string {
  if (!iso) return '';
  const date = new Date(iso);
  return Number.isNaN(date.getTime()) ? '' : date.toUTCString();
}

export async function buildAuthorRssXml(handle: string): Promise<string> {
  const page = await getAuthorPosts(handle);
  const items = (page?.items ?? []).slice(0, RSS_ITEM_LIMIT);
  const authorUrl = buildBlogAuthorAbsoluteUrl(BLOG_SITE_BASE_URL, handle);

  const itemXml = items
    .map((post) => {
      const link = buildBlogAbsoluteCanonicalUrl(BLOG_SITE_BASE_URL, handle, post.slug ?? '');
      const pubDate = rfc822(post.publishedAt);
      return [
        '    <item>',
        `      <title>${xmlEscape(post.title ?? '')}</title>`,
        `      <link>${xmlEscape(link)}</link>`,
        `      <guid isPermaLink="true">${xmlEscape(link)}</guid>`,
        `      <description>${xmlEscape(post.excerpt ?? '')}</description>`,
        pubDate ? `      <pubDate>${pubDate}</pubDate>` : null,
        '    </item>',
      ]
        .filter((line): line is string => line !== null)
        .join('\n');
    })
    .join('\n');

  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">',
    '  <channel>',
    `    <title>${xmlEscape(`${handle} — GameGuild Blog`)}</title>`,
    `    <link>${xmlEscape(authorUrl)}</link>`,
    `    <description>${xmlEscape(`Latest posts by ${handle} on GameGuild`)}</description>`,
    `    <atom:link href="${xmlEscape(`${authorUrl}/rss.xml`)}" rel="self" type="application/rss+xml" />`,
    itemXml,
    '  </channel>',
    '</rss>',
  ].join('\n');
}

export function authorRssResponse(xml: string): Response {
  return new Response(xml, {
    headers: {
      'Content-Type': 'application/rss+xml; charset=utf-8',
      'Cache-Control': 'public, s-maxage=3600, stale-while-revalidate=86400',
    },
  });
}

/**
 * Single source of truth for blog URLs (metadata, RSS, sitemap, JSON-LD).
 *
 * Canonical rule (plan todo 8, evidence `apps/web/src/proxy.ts:46-64`):
 * default locale `en-US` is externally unprefixed, so canonical URLs NEVER
 * carry a locale prefix.
 */
import type { Metadata } from 'next';

import type { BlogPostDetail } from './types';

export const BLOG_INDEX_PATH = '/blogs';

/** Site origin for absolute URLs — mirrors `app/sitemap.ts`. */
export const BLOG_SITE_BASE_URL = process.env.NEXT_PUBLIC_APP_URL ?? 'https://gameguild.gg';

export function buildBlogCanonicalUrl(handle: string, slug: string): string {
  return `${BLOG_INDEX_PATH}/${handle}/${slug}`;
}

export function buildBlogCanonicalPath(handle: string, slug: string): string {
  return buildBlogCanonicalUrl(handle, slug);
}

export function buildBlogAbsoluteCanonicalUrl(baseUrl: string, handle: string, slug: string): string {
  return `${baseUrl.replace(/\/$/, '')}${buildBlogCanonicalUrl(handle, slug)}`;
}

/** Author profile path — unprefixed canonical form (RSS channel link, cards). */
export function buildBlogAuthorPath(handle: string): string {
  return `${BLOG_INDEX_PATH}/${handle}`;
}

export function buildBlogAuthorAbsoluteUrl(baseUrl: string, handle: string): string {
  return `${baseUrl.replace(/\/$/, '')}${buildBlogAuthorPath(handle)}`;
}

/**
 * Next static routes shadow `[username]`; handles colliding with them must
 * never reach the dynamic route. `rss.xml` is reserved by the per-author RSS
 * route at `blogs/[username]/rss.xml`.
 */
const RESERVED_BLOG_SEGMENTS = new Set(['rss.xml']);

export function isReservedBlogSegment(username: string): boolean {
  return RESERVED_BLOG_SEGMENTS.has(username);
}

/** Author display info for metadata/JSON-LD (co-authors carry handles only). */
export interface BlogAuthorProfile {
  handle?: string | null;
  displayName?: string | null;
}

function blogAuthorNames(post: BlogPostDetail, authorProfiles?: BlogAuthorProfile[]): string[] {
  const names = authorProfiles?.map((profile) => profile.displayName ?? profile.handle).filter((n): n is string => Boolean(n));
  if (names && names.length > 0) return names;

  const primary = post.primaryAuthorDisplayName ?? post.primaryAuthorHandle;
  const coAuthors = (post.coAuthorHandles ?? []).filter((h): h is string => Boolean(h));
  return [...(primary ? [primary] : []), ...coAuthors];
}

function blogDescription(post: BlogPostDetail): string | undefined {
  return post.metaDescription ?? post.excerpt ?? undefined;
}

/**
 * Full Ghost-grade metadata for a published post. Canonical is an absolute
 * UNPREFIXED URL; `alternates.languages` maps every locale explicitly
 * (default locale without prefix, others with).
 */
export function buildBlogPostMetadata(post: BlogPostDetail, authorProfiles?: BlogAuthorProfile[]): Metadata {
  const handle = post.primaryAuthorHandle ?? '';
  const slug = post.slug ?? '';
  const canonical = buildBlogAbsoluteCanonicalUrl(BLOG_SITE_BASE_URL, handle, slug);
  const title = post.metaTitle ?? post.title ?? undefined;
  const description = blogDescription(post);
  const publishedTime = post.publishedAt ?? undefined;
  const twitterCard = (post.twitterCard ?? 'summary_large_image') as 'summary' | 'summary_large_image';

  return {
    title,
    description,
    robots: { index: true, follow: true },
    alternates: {
      canonical,
      languages: {
        'en-US': canonical,
        'pt-BR': `${BLOG_SITE_BASE_URL.replace(/\/$/, '')}/pt-BR${buildBlogCanonicalUrl(handle, slug)}`,
      },
    },
    openGraph: {
      type: 'article',
      title,
      description,
      url: canonical,
      siteName: 'GameGuild',
      ...(publishedTime ? { publishedTime } : {}),
      ...(post.ogImageUrl ? { images: [post.ogImageUrl] } : {}),
      authors: blogAuthorNames(post, authorProfiles),
      ...(post.tags && post.tags.length > 0 ? { tags: post.tags } : {}),
    },
    twitter: {
      card: twitterCard,
      title,
      description,
      ...(post.ogImageUrl ? { images: [post.ogImageUrl] } : {}),
    },
  };
}

/** `BlogPosting` JSON-LD object per plan todo 8 spec. */
export function buildBlogJsonLd(post: BlogPostDetail, authorProfiles?: BlogAuthorProfile[]): Record<string, unknown> {
  const handle = post.primaryAuthorHandle ?? '';
  const slug = post.slug ?? '';
  const canonical = buildBlogAbsoluteCanonicalUrl(BLOG_SITE_BASE_URL, handle, slug);
  const description = blogDescription(post);

  return {
    '@context': 'https://schema.org',
    '@type': 'BlogPosting',
    headline: post.title ?? '',
    ...(description ? { description } : {}),
    ...(post.ogImageUrl ? { image: [post.ogImageUrl] } : {}),
    ...(post.publishedAt ? { datePublished: post.publishedAt } : {}),
    dateModified: post.updatedAt ?? post.publishedAt ?? undefined,
    mainEntityOfPage: canonical,
    author: blogAuthorNames(post, authorProfiles).map((name) => ({ '@type': 'Person', name })),
    ...(post.tags && post.tags.length > 0 ? { keywords: post.tags.join(', ') } : {}),
    publisher: { '@type': 'Organization', name: 'GameGuild', url: BLOG_SITE_BASE_URL },
  };
}

/**
 * JSON-LD script payload: use the stored override when present or generate a
 * `BlogPosting`, then escape HTML script delimiters without changing JSON values.
 */
export function resolveBlogJsonLd(post: BlogPostDetail, authorProfiles?: BlogAuthorProfile[]): string {
  const payload = post.structuredDataOverride && post.structuredDataOverride.trim().length > 0
    ? post.structuredDataOverride
    : JSON.stringify(buildBlogJsonLd(post, authorProfiles));
  return payload.replace(/</g, '\\u003c');
}

export const BLOG_API_BASE_URL = (
  process.env.API_URL ||
  process.env.NEXT_PUBLIC_API_URL ||
  'http://localhost:8080'
).replace(/\/$/, '');

