      name,
      description,
      permissions,
      tenantId,
    },
    requiresAuth: true,
  });

  if (!result.ok) {
    redirect(buildRolesHref({ error: result.error.message }));
  }

  revalidateRoles();
  redirect(buildRolesHref({ message: `Created role ${name}.` }));
