}

export type CourseLookupFailureReason = 'not-found' | 'unavailable';

export interface CourseLookupResult {
    success: boolean;
    data?: Program;
    error?: string;
    reason?: CourseLookupFailureReason;
}

export interface CourseCatalogResult {
    success: boolean;
    data: Program[];
