} from "@game-guild/client";
import { FeedMutationError } from "./errors";
import type {
  DeletedPostComment,
  DeletedSocialPost,
  DeletedStoryState,
  PostComment,
  SavedPostState,
  SharedPostState,
  SocialFollowState,
  SocialFeedPage,
  SocialMediaAsset,
  SocialProfile,
