const KIND_LABELS: Record<string, string> = {
  NewCourse: 'New course',
  PopularCourse: 'Popular course',
  TrendingDiscussion: 'Discussion',
  FeaturedReview: 'Review',
  LearningPathSuggestion: 'Learning path',
