import type {
    LearningAssessmentsAssessmentType,
    LearningAssessmentsSubmissionModality,
    LearningAssessmentsSubmitAssessmentInput,
} from '@game-guild/client';

export type LearnerContentActivityKind = 'discussion' | 'reflection' | 'survey';

export function getPreferredSubmissionModality(
    assessmentType: LearningAssessmentsAssessmentType | undefined,
    configured: LearningAssessmentsSubmissionModality | undefined,
): LearningAssessmentsSubmissionModality {
    if (assessmentType === 'Quiz') return 'None';
    if (assessmentType === 'Project') return 'Project';
    return configured && configured !== 'None' ? configured : 'Text';
}

export function buildAssessmentPayload(
    modality: LearningAssessmentsSubmissionModality,
    value: string,
): LearningAssessmentsSubmitAssessmentInput {
    const normalized = value.trim();
    if (!normalized) throw new Error('A submission response is required.');

    switch (modality) {
        case 'File':
            return { filePayload: normalized };
        case 'Url':
            return { urlPayload: normalized };
        case 'Code':
            return { codePayload: normalized };
        case 'Media':
            return { mediaPayload: normalized };
        case 'Project':
            return { projectPayload: normalized };
        case 'Text':
            return { textPayload: normalized };
        case 'None':
        default:
            throw new Error('This assessment does not have a valid submission method.');
    }
}

export function buildContentActivityPayload(kind: LearnerContentActivityKind, value: string) {
    const normalized = value.trim();
    if (!normalized) throw new Error('A response is required.');

    switch (kind) {
        case 'discussion':
            return { kind: 'discussion' as const, body: normalized };
        case 'reflection':
            return { kind: 'reflection' as const, body: normalized };
        case 'survey':
            return { kind: 'survey' as const, answers: { response: normalized } };
    }
}

import type { LearningCoursesProgramContent } from '@game-guild/client';

export function flattenUniqueContent(items: LearningCoursesProgramContent[]): LearningCoursesProgramContent[] {
    const flattened: LearningCoursesProgramContent[] = [];
    const seenIds = new Set<string>();

    const visit = (item: LearningCoursesProgramContent) => {
        if (item.id && seenIds.has(item.id)) return;
        if (item.id) seenIds.add(item.id);
        flattened.push(item);
        for (const child of item.children ?? []) visit(child);
    };

    for (const item of items) visit(item);
    return flattened.sort((left, right) => (left.sortOrder ?? 0) - (right.sortOrder ?? 0));
}

// Private content is author-only: hide the item and its entire subtree from learners.
export function collectHiddenContentIds(
    items: LearningCoursesProgramContent[],
    hidden: Set<string> = new Set<string>(),
    parentHidden = false,
): Set<string> {
    for (const item of items) {
        const itemHidden = parentHidden || item.visibility === 'Private';
        if (itemHidden && item.id) hidden.add(item.id);
        if (item.children?.length) {
            collectHiddenContentIds(item.children, hidden, itemHidden);
        }
    }
    return hidden;
}

import {
  createServerClient,
  GeneratedApi,
  type LearningCoursesContentProgress,
  type LearningCoursesProgramContent,
  type LearningCoursesProgressStatus,
  type LearningWorkspacesLearnerCourseSummary,
  type LearningWorkspacesLearnerDashboard,
} from "@game-guild/client";
import { collectHiddenContentIds, flattenUniqueContent } from "@/lib/learner/content-tree";
import { percentUnitsToPercentage } from "@/lib/learning/academic-values";
import { unstable_rethrow } from "next/navigation";

export interface LearningCourseSummary {
  id: string;
  title: string;
  slug: string;
  description: string;
  thumbnail: string | null;
  category: string;
  difficulty: string;
  estimatedHours: number | null;
  currentEnrollments: number;
  averageRating: number;
  isEnrollmentOpen: boolean;
}

export interface CourseAttendanceItem {
  id: string;
  slug?: string;
  title: string;
  type: "lesson" | "activity" | "quiz" | "assignment" | "peer-review";
  status: "locked" | "available" | "in-progress" | "completed";
  duration?: number;
  description?: string;
  order: number;
  isRequired: boolean;
  content?: unknown;
  contentType?: LearningCoursesProgramContent["type"];
  lessonFormat?: LearningCoursesProgramContent["lessonFormat"];
  activitySettings?: LearningCoursesProgramContent["activitySettings"];
}

export interface CourseAttendanceModule {
  id: string;
  title: string;
  description: string;
  order: number;
  items: CourseAttendanceItem[];
  progress: number;
}

export type CourseAccessState =
  | { kind: "ready"; course: CourseAttendanceData }
  | { kind: "enrollment-required"; course: LearningCourseSummary }
  | {
      kind: "payment-required";
      course: LearningCourseSummary;
      price: number | null;
      currency: string;
    }
  | { kind: "enrollment-closed"; course: LearningCourseSummary }
  | { kind: "unavailable"; course?: LearningCourseSummary; message: string }
  | { kind: "not-found" };

export interface CourseAttendanceData {
  id: string;
  title: string;
  slug: string;
  description: string;
  thumbnail: string | null;
  modules: CourseAttendanceModule[];
  overallProgress: number;
  totalItems: number;
  completedItems: number;
  currentItem?: CourseAttendanceItem;
  remainingMinutes: number;
  enrollmentId?: string;
}

interface CourseAttendanceModuleSource {
  id: string;
  title: string;
  description: string;
  order: number;
  items: Array<LearningCoursesProgramContent & { id: string }>;
}

type ProgressItemStatus = "not-started" | "in-progress" | "completed";

async function getOptionalToken(): Promise<string | null> {
  const { getToken } = await import("@/auth");
  return getToken();
}

function getApiClient(getAccessToken?: () => Promise<string | null>) {
  const apiUrl =
    process.env.API_URL ||
    process.env.NEXT_PUBLIC_API_URL ||
    "http://localhost:8080";

  return createServerClient({
    baseUrl: apiUrl,
    auth: getAccessToken ? { getAccessToken } : undefined,
  });
}

function createCourseModules(getAccessToken?: () => Promise<string | null>) {
  const client = getApiClient(getAccessToken);

  return {
    programs: new GeneratedApi.LearningCoursesProgramModule(client),
    content: new GeneratedApi.LearningCoursesProgramContentModule(client),
    workspaces: new GeneratedApi.LearningWorkspacesLearnerWorkspaceModule(
      client,
    ),
  };
}

function mapCourse(
  program: GeneratedApi.LearningCoursesProgram,
): LearningCourseSummary {
  return {
    id: program.id ?? "",
    title: program.title ?? "Untitled course",
    slug: program.slug ?? "",
    description: program.description ?? "",
    thumbnail: program.thumbnail ?? null,
    category: String(program.category ?? "General"),
    difficulty: String(program.difficulty ?? "Beginner"),
    estimatedHours: program.estimatedHours ?? null,
    currentEnrollments: program.currentEnrollments ?? 0,
    averageRating: program.averageRating ?? 0,
    isEnrollmentOpen: program.isEnrollmentOpen ?? false,
  };
}

function mapWorkspaceItemType(
  type?: string | null,
): CourseAttendanceItem["type"] {
  switch (type) {
    case "Assignment":
      return "assignment";
    case "Questionnaire":
    case "Quiz":
      return "quiz";
    case "Discussion":
      return "peer-review";
    case "Code":
    case "Project":
    case "Reflection":
    case "Survey":
      return "activity";
    default:
      return "lesson";
  }
}

export function mapLearnerCourseSummary(
  course: LearningWorkspacesLearnerCourseSummary,
): CourseAttendanceData {
  const progress = Math.max(
    0,
    Math.min(
      100,
      Math.round(percentUnitsToPercentage(course.progressPercentage ?? 0)),
    ),
  );
  const currentItem = course.currentContentId
    ? {
        id: course.currentContentId,
        title: course.currentContentTitle || "Continue course",
        type: mapWorkspaceItemType(course.currentContentType),
        status:
          progress > 0 ? ("in-progress" as const) : ("available" as const),
        order: 0,
        isRequired: true,
      }
    : undefined;

  return {
    id: course.courseId ?? "",
    title: course.title ?? "Untitled course",
    slug: course.slug ?? "",
    description: course.description ?? "",
    thumbnail: course.thumbnail ?? null,
    modules: [],
    overallProgress: progress,
    totalItems: course.totalItems ?? 0,
    completedItems: course.completedItems ?? 0,
    currentItem,
    remainingMinutes: course.remainingMinutes ?? 0,
    enrollmentId: course.enrollmentId,
  };
}

function getContentProgressMap(
  contentProgress: LearningCoursesContentProgress[] | null | undefined,
) {
  return new Map(
    (contentProgress ?? [])
      .filter(
        (
          entry,
        ): entry is LearningCoursesContentProgress & { contentId: string } =>
          Boolean(entry.contentId),
      )
      .map((entry) => [entry.contentId, entry]),
  );
}

function mapProgressStatus(
  status?: LearningCoursesProgressStatus,
): ProgressItemStatus {
  switch (status) {
    case "Completed":
    case "Submitted":
      return "completed";
    case "InProgress":
      return "in-progress";
    case "NotStarted":
    default:
      return "not-started";
  }
}

function mapAttendanceStatus(
  progressStatus: ProgressItemStatus | undefined,
  unlocked: boolean,
): CourseAttendanceItem["status"] {
  if (progressStatus === "completed") {
    return "completed";
  }

  if (progressStatus === "in-progress") {
    return "in-progress";
  }

  return unlocked ? "available" : "locked";
}

function mapItemType(
  type: LearningCoursesProgramContent["type"],
): CourseAttendanceItem["type"] {
  switch (type) {
    case "Assignment":
      return "assignment";
    case "Questionnaire":
      return "quiz";
    case "Discussion":
      return "peer-review";
    case "Code":
    case "Project":
    case "Reflection":
    case "Survey":
      return "activity";
    case "Lesson":
    default:
      return "lesson";
  }
}

export async function getPublicCourses(): Promise<LearningCourseSummary[]> {
  try {
    const { programs } = createCourseModules();
    const result = await programs.getCoursesPublic();

    if (!result.ok || !Array.isArray(result.data)) {
      return [];
    }

    return result.data.map(mapCourse);
  } catch (error) {
    console.error("[learning] Failed to fetch public courses", error);
    return [];
  }
