  const client = await getClient();
  if (!client) return emptyContext();

  const result =
    await new GeneratedApi.LearningWorkspacesLearnerWorkspaceModule(
      client,
    ).getLearningCoursesWorkspace(courseId);
  return result.ok
    ? mapWorkspaceContext(result.data, courseId)
    : emptyContext();
}

