export interface CreateCourseInput {
  title: string;
  description: string;
  slug: string;
  passingScore?: number;
}

export async function createCourse(
  input: CreateCourseInput,
): Promise<ActionResult<{ id: string; slug: string; routeParam: string }>> {
  const { title, description, slug, passingScore } = input;

  if (!title || title.trim().length < 3) {
    return { success: false, error: "Title must be at least 3 characters." };
  }
  if (!description || description.trim().length < 10) {
    return {
      success: false,
      error: "Description must be at least 10 characters.",
    };
  }
  if (!slug || slug.trim().length < 1) {
    return { success: false, error: "Slug is required." };
  }

  try {
    const { programs, users } = createCourseModules();
    const result = await programs.postCourses({
      title: title.trim(),
      description: description.trim(),
      slug: slug.trim(),
      passingScore:
        passingScore == null
          ? undefined
          : percentValueFromPercentage(String(passingScore)),
    } as unknown as LearningCoursesCreateProgram);

    if (result.ok) {
      const id = result.data.id!;
      const createdSlug = result.data.slug?.trim() || slug.trim();
      const creatorId = result.data.creatorId ?? null;
      let creatorName: string | null = null;
      let creatorEmail: string | null = null;

      if (creatorId) {
        try {
          const creatorResult =
            await users.getUsersForGetUsersByUserId(creatorId);
          if (creatorResult.ok) {
            creatorName = creatorResult.data.name ?? null;
            creatorEmail = creatorResult.data.email ?? null;
          }
        } catch {
          // The creator ID remains a valid route fallback if identity lookup fails.
        }
      }

      revalidatePath("/workspace/learning/courses");
      revalidatePath("/console/learning/courses");
      return {
        success: true,
        data: {
          id,
          slug: createdSlug,
          routeParam: getCourseRouteParam({
            id,
            slug: createdSlug,
            creatorId,
            creatorName,
            creatorEmail,
          }),
        },
      };
    }

    return { success: false, error: extractError(result.error) };
  } catch (e) {
    return {
      success: false,
      error: `Unexpected error: ${e instanceof Error ? e.message : String(e)}`,
    };
  }
}

