const apiBaseUrl = (
  process.env.API_URL ||
  process.env.NEXT_PUBLIC_API_URL ||
  "http://localhost:8080"
).replace(/\/$/, "");

export type AiProposalKind =
  | "ReplaceDocument"
  | "InsertAtCursor"
  | "LexicalPatch"
  | "QuizPatch"
  | "MetadataPatch";

export interface AuthoringContentPayload {
