  ): Promise<{ rubric: AssessmentRubricView | null; locked: boolean }> => {
    try {
      const module = new GeneratedApi.LearningAssessmentsRubricsModule(
        getApiClient(),
      );
      const result = await module.getAssessmentsRubric(assessmentId);
      if (result.ok) {
        const rubric = result.data;
        return {
          rubric: {
            id: rubric.id ?? "",
            title: rubric.title ?? "",
            criteria: (rubric.criteria ?? []).map((criterion) => ({
              description: criterion.description ?? "",
              points: scoreToNumber(criterion.points, 0),
              order: criterion.order ?? 0,
            })),
          },
          locked: false,
        };
      }
      // 404 = no rubric assigned yet; 409 = locked after grading started.
      const status = (result.error as { status?: number } | undefined)?.status;
      if (status === 409) {
        return { rubric: null, locked: true };
      }
      return { rubric: null, locked: false };
    } catch (err) {
      console.error("Error fetching assessment rubric:", err);
      return { rubric: null, locked: false };
    }
  },
);

import { getToken } from '@/auth';
import {
  createServerClient,
  GeneratedApi,
  type LearningCohortsCohort,
  type LearningCohortsCohortSchedule,
  type LearningCohortsCourseCohortCalendar,
  type LearningEnrollmentsEnrollment,
  type SystemDayOfWeek,
} from '@game-guild/client';
import { cache } from 'react';

import { resolveCourseId } from './course';

export type CourseCohortStatus = 'scheduled' | 'active' | 'completed' | 'cancelled';

export interface CourseCohortScheduleSummary {
  version: number;
  timezoneId: string;
  meetingDays: SystemDayOfWeek[];
  meetingStartTime: string | null;
  pacingMode: string | null;
  releasePolicy: string | null;
  itemCount: number;
}

export interface CourseCohortSummary {
  id: string;
  courseId: string;
  name: string;
  description: string;
  instructor: { id: string; name: string | null } | null;
  period: { startsAt: string; endsAt: string };
  meetingPattern: string | null;
  enrollment: { current: number; capacity: number | null };
  nextMeetingAt: string | null;
  conflictCount: number;
  status: CourseCohortStatus;
  isOpen: boolean;
  schedule: CourseCohortScheduleSummary | null;
  createdAt: string;
}

export interface CourseCohortAttendee {
  id: string;
  userId: string;
  status: 'active' | 'paused' | 'completed' | 'dropped' | 'expired';
  progress: number;
  enrolledAt: string;
  completedAt: string | null;
  lastActivityAt: string | null;
}

export interface CourseCohortDetail extends CourseCohortSummary {
  attendees: CourseCohortAttendee[];
}

export interface CourseCohortCollection {
  cohorts: CourseCohortSummary[];
  total: number;
  scheduledCount: number;
  activeCount: number;
  completedCount: number;
}

function createCohortModules() {
  const apiUrl = process.env.API_URL || process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8080';
  const client = createServerClient({
    baseUrl: apiUrl,
    auth: { getAccessToken: () => getToken() },
  });

  return {
    cohorts: new GeneratedApi.LearningCohortsModule(client),
    schedules: new GeneratedApi.LearningCohortsSchedulesModule(client),
    enrollments: new GeneratedApi.LearningEnrollmentsModule(client),
  };
}

function mapStatus(status: LearningCohortsCohort['status']): CourseCohortStatus {
  if (status === 'Active') return 'active';
  if (status === 'Completed') return 'completed';
  if (status === 'Cancelled') return 'cancelled';
  return 'scheduled';
}

export function mapCohort(cohort: LearningCohortsCohort): CourseCohortSummary {
  const instructorId = cohort.instructorId ?? null;

  return {
    id: cohort.id ?? '',
    courseId: cohort.courseId ?? '',
    name: cohort.name?.trim() || 'Untitled class',
    description: cohort.description?.trim() || '',
    instructor: instructorId ? { id: instructorId, name: null } : null,
    period: {
      startsAt: cohort.startDate ?? '',
      endsAt: cohort.endDate ?? '',
    },
    meetingPattern: cohort.meetingSchedule?.trim() || null,
    enrollment: {
      current: cohort.currentEnrollmentCount ?? 0,
      capacity: cohort.maxCapacity ?? null,
    },
    nextMeetingAt: cohort.nextMeetingAt ?? null,
    conflictCount: cohort.conflictCount ?? 0,
    status: mapStatus(cohort.status),
    isOpen: cohort.isOpen ?? false,
    schedule: cohort.schedule
      ? {
          version: cohort.schedule.version ?? 0,
          timezoneId: cohort.schedule.timezoneId?.trim() || 'UTC',
          meetingDays: cohort.schedule.meetingDays ?? [],
          meetingStartTime: cohort.schedule.meetingStartTime ?? null,
          pacingMode: cohort.schedule.pacingMode ?? null,
          releasePolicy: cohort.schedule.releasePolicy ?? null,
          itemCount: cohort.schedule.itemCount ?? 0,
        }
      : null,
    createdAt: cohort.createdAt ?? '',
  };
}

function mapEnrollmentStatus(status: LearningEnrollmentsEnrollment['status']): CourseCohortAttendee['status'] {
  if (status === 'Paused') return 'paused';
  if (status === 'Completed') return 'completed';
  if (status === 'Dropped') return 'dropped';
  if (status === 'Expired') return 'expired';
  return 'active';
}

function mapAttendee(enrollment: LearningEnrollmentsEnrollment, index: number): CourseCohortAttendee {
  return {
    id: enrollment.id ?? `enrollment-${index}`,
    userId: enrollment.userId ?? 'unknown-user',
    status: mapEnrollmentStatus(enrollment.status),
    progress: Math.max(0, Math.min(100, Math.round(enrollment.progress ?? 0))),
    enrolledAt: enrollment.enrolledAt ?? '',
    completedAt: enrollment.completedAt ?? null,
    lastActivityAt: enrollment.lastActivityAt ?? null,
  };
}

export const getCourseCohorts = cache(async (courseIdentifier: string): Promise<CourseCohortCollection> => {
  const courseId = await resolveCourseId(courseIdentifier);
  const result = await createCohortModules().cohorts.getApiCohortsCourse(courseId);
  const cohorts = result.ok ? result.data.map(mapCohort) : [];

  return {
    cohorts,
    total: cohorts.length,
    scheduledCount: cohorts.filter((cohort) => cohort.status === 'scheduled').length,
    activeCount: cohorts.filter((cohort) => cohort.status === 'active').length,
    completedCount: cohorts.filter((cohort) => cohort.status === 'completed').length,
  };
});

export const getCohort = cache(async (cohortId: string): Promise<CourseCohortDetail | null> => {
  const modules = createCohortModules();
  const cohortResult = await modules.cohorts.getApiCohorts(cohortId);
  if (!cohortResult.ok) return null;

  const cohort = mapCohort(cohortResult.data);
  const enrollmentResult = await modules.enrollments.getApiLearningEnrollmentsCourses(cohort.courseId);
  const attendees = enrollmentResult.ok
    ? (enrollmentResult.data ?? [])
        .filter((enrollment) => enrollment.cohortId === cohort.id)
        .map(mapAttendee)
    : [];

  return { ...cohort, attendees };
});

export const getCohortSchedule = cache(async (courseIdentifier: string, cohortId: string): Promise<LearningCohortsCohortSchedule | null> => {
  const courseId = await resolveCourseId(courseIdentifier);
  const result = await createCohortModules().schedules.getCoursesCohortsSchedule(courseId, cohortId);
  return result.ok ? result.data : null;
});

export const getCourseCohortCalendar = cache(
  async (
    courseIdentifier: string,
    query?: { cohortId?: string; from?: string; to?: string },
  ): Promise<LearningCohortsCourseCohortCalendar | null> => {
    const courseId = await resolveCourseId(courseIdentifier);
    const result = await createCohortModules().schedules.getCoursesCohortsCalendar(courseId, query);
    return result.ok ? result.data : null;
  },
);

import { getToken } from '@/auth';
import { createServerClient, GeneratedApi, type LearningCoursesProgramContent } from '@game-guild/client';
import { cache } from 'react';

export interface LearningContentLibraryItem {
  id: string;
  slug: string;
  courseId: string;
  courseTitle: string;
  courseSlug: string;
  title: string;
  description: string | null;
  type: string;
  visibility: 'public' | 'private';
  status: 'draft' | 'published';
  durationMinutes: number | null;
  isRequired: boolean;
  updatedAt: string;
}

function getApiClient() {
  const apiUrl = process.env.API_URL || process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8080';
  return createServerClient({
    baseUrl: apiUrl,
    auth: { getAccessToken: () => getToken() },
  });
}

function createCourseModules() {
  const client = getApiClient();

  return {
    programs: new GeneratedApi.LearningCoursesProgramModule(client),
    content: new GeneratedApi.LearningCoursesProgramContentModule(client),
  };
}

function flattenContent(items: LearningCoursesProgramContent[]): LearningCoursesProgramContent[] {
  const flattened: LearningCoursesProgramContent[] = [];

  const visit = (item: LearningCoursesProgramContent) => {
    flattened.push(item);

    for (const child of item.children ?? []) {
      visit(child);
    }
  };

  for (const item of items) {
    visit(item);
  }

  return flattened.sort((left, right) => (left.sortOrder ?? 0) - (right.sortOrder ?? 0));
}

function mapVisibility(visibility: unknown): 'public' | 'private' {
  return String(visibility ?? '').toLowerCase() === 'public' ? 'public' : 'private';
}

function mapStatus(item: LearningCoursesProgramContent): 'draft' | 'published' {
  return mapVisibility(item.visibility) === 'public' ? 'published' : 'draft';
}

function normalizeContentType(type: string | null | undefined): string {
  if (type === 'Page') return 'Lesson';
  if (type === 'Challenge') return 'Assignment';
  return type ?? 'Lesson';
}

export const getLearningContentLibrary = cache(async (): Promise<{
  items: LearningContentLibraryItem[];
  error: string | null;
}> => {
  try {
    const { programs, content } = createCourseModules();
    const coursesResult = await programs.getCoursesForGetCourses({ take: 100 });

    if (!coursesResult.ok) {
      const err = coursesResult.error as { status?: number; code?: string; message?: string; detail?: string } | undefined;
      return {
        items: [],
        error: `[${err?.status ?? 'unknown'}${err?.code ? ' ' + err.code : ''}] ${err?.detail || err?.message || 'Failed to load courses'}`,
      };
    }

    const courseContent = await Promise.all(
      coursesResult.data
        .filter((course) => Boolean(course.id))
        .map(async (course) => {
          const courseId = String(course.id);
          const contentResult = await content.getCoursesContent(courseId);

          if (!contentResult.ok) {
            return [];
          }

          return flattenContent(contentResult.data)
            .filter((item) => Boolean(item.id))
            .map((item) => ({
              id: String(item.id),
              slug: item.slug ?? String(item.id),
              courseId,
              courseTitle: course.title ?? 'Untitled course',
              courseSlug: course.slug ?? '',
              title: item.title ?? 'Untitled content',
              description: item.description ?? null,
              type: normalizeContentType(item.type),
              visibility: mapVisibility(item.visibility),
              status: mapStatus(item),
              durationMinutes: item.estimatedMinutes ?? null,
              isRequired: item.isRequired ?? false,
              updatedAt: item.updatedAt ?? item.createdAt ?? course.updatedAt ?? new Date().toISOString(),
            }) satisfies LearningContentLibraryItem);
        }),
    );

    return {
      items: courseContent
        .flat()
        .sort((left, right) => new Date(right.updatedAt).getTime() - new Date(left.updatedAt).getTime()),
      error: null,
    };
  } catch (error) {
    return {
      items: [],
      error: `Unexpected: ${error instanceof Error ? error.message : String(error)}`,
    };
  }
});

import { auth, getToken } from "@/auth";
import { readContentGradingDefinition } from "@game-guild/grading";
import {
  createServerClient,
  GeneratedApi,
  type ContentStatus,
  type ContentVisibility,
  type LearningCoursesProgram,
  type LearningCoursesProgramContent,
  type LearningCoursesProgramContentType,
  type LearningCoursesLessonContentFormat,
} from "@game-guild/client";
import { cache } from "react";

// Dashboard view models are explicitly derived from generated DTOs so client components do not import server-only modules.
export type {
  CourseContentItemViewModel,
  CourseContentItemDetailViewModel,
  CourseAnalyticsViewModel,
  CourseContentViewModel,
  CourseDeliveryMode,
  CourseViewModel,
  CourseFeaturesViewModel,
  CoursePricingModel,
  CourseStudentsViewModel,
} from "@/lib/learning/view-models";

import type {
  CourseContentItemViewModel,
  CourseContentItemDetailViewModel,
  CourseAnalyticsViewModel,
  CourseContentViewModel,
  CourseViewModel,
  CourseStudentsViewModel,
} from "@/lib/learning/view-models";
import {
  getCourseLookupSlug,
  slugifyRoutePart,
} from "@/lib/learning/course-route";
import {
  optionalPercentUnitsToPercentage,
  percentUnitsToPercentage,
} from "@/lib/learning/academic-values";

// Re-export generated types for consumers
export type {
  LearningCoursesProgram,
  LearningCoursesProgramContent,
  LearningCoursesProgramContentType,
};

export interface CourseAccessCapabilities {
  courseId: string;
  courseExists: boolean;
  isTenantMember: boolean;
  isOwner: boolean;
  hasActiveEnrollment: boolean;
  canLearn: boolean;
  canEdit: boolean;
  canPublish: boolean;
  canReviewAsStaff: boolean;
  canAccessWorkspace: boolean;
}

function getApiClient(tenantId?: string) {
  const apiUrl =
    process.env.API_URL ||
    process.env.NEXT_PUBLIC_API_URL ||
    "http://localhost:8080";
  return createServerClient({
    baseUrl: apiUrl,
    auth: { getAccessToken: () => getToken() },
    // Sends X-Tenant-Id so the authorization API can resolve the actor tenant.
    ...(tenantId ? { tenant: { getTenantId: async () => tenantId } } : {}),
  });
}

function createCourseModules() {
  const client = getApiClient();

  return {
    programs: new GeneratedApi.LearningCoursesProgramModule(client),
    content: new GeneratedApi.LearningCoursesProgramContentModule(client),
    users: new GeneratedApi.UsersModule(client),
  };
}

function emptyCourseAnalytics(): CourseAnalyticsViewModel {
  return {
    totalUsers: 0,
    activeUsers: 0,
    completedUsers: 0,
    completionRate: 0,
    averageCompletionTime: null,
    totalViews: 0,
    lastActivity: null,
    enrollments: [],
    ratings: [],
    revenue: [],
  };
}

// Compatibility endpoints may serialize enums as either names or numeric values.
function mapStatus(
  s: ContentStatus | number | string | undefined,
): "draft" | "published" | "archived" {
  if (s === 2 || s === "2" || s === "Published" || s === "published")
    return "published";
  if (s === 3 || s === "3" || s === "Archived" || s === "archived")
    return "archived";
  return "draft";
}

// Map ContentVisibility string union to simplified frontend visibility
function mapVisibility(
  v: ContentVisibility | undefined,
): "public" | "private" | "unlisted" {
  if (v === "Public") return "public";
  return "private";
}

function normalizeLessonContentFormat(
  format: string | null | undefined,
): LearningCoursesLessonContentFormat | null {
  switch (format) {
    case "Markdown":
    case "Lexical":
    case "RevealJs":
    case "Video":
    case "Html":
    case "ExternalLink":
      return format;
    case null:
    case undefined:
      return null;
    default:
      return "Markdown";
  }
}

function isGuid(value: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
    value.trim(),
  );
}

async function resolveCreatorHandle(
  creatorId: string | null | undefined,
): Promise<string | null> {
  if (!creatorId) return null;

  const { users } = createCourseModules();

  try {
    const result = await users.getUsersForGetUsersByUserId(creatorId);
    if (!result.ok) return null;

    return (
      slugifyRoutePart(result.data.name ?? "") ||
      slugifyRoutePart(result.data.email?.split("@")[0] ?? "") ||
      null
    );
  } catch {
    return null;
  }
}

function mapProgramDtoToCourseViewModel(
  dto: LearningCoursesProgram,
  creatorHandle: string | null = null,
): CourseViewModel {
  return {
    id: dto.id!,
    creatorId: dto.creatorId ?? null,
    creatorHandle,
    title: dto.title ?? "",
    description: dto.description ?? "",
    metadata: dto.metadata ?? null,
    slug: dto.slug ?? "",
    status: mapStatus(dto.status),
    visibility: mapVisibility(dto.visibility),
    thumbnail: dto.thumbnail ?? null,
    videoShowcaseUrl: dto.videoShowcaseUrl ?? null,
    estimatedHours: dto.estimatedHours ?? null,
    passingScore: optionalPercentUnitsToPercentage(dto.passingScore),
    category: dto.category ?? "GeneralEducation",
    difficulty: dto.difficulty ?? "Beginner",
    skillsRequired: dto.skillsRequired ?? null,
    skillsProvided: dto.skillsProvided ?? null,
    enrollmentStatus: dto.enrollmentStatus ?? "Open",
    maxEnrollments: dto.maxEnrollments ?? null,
    enrollmentDeadline: dto.enrollmentDeadline ?? null,
    currentEnrollments: dto.currentEnrollments ?? 0,
    averageRating: dto.averageRating ?? 0,
    totalRatings: dto.totalRatings ?? 0,
    isEnrollmentOpen: dto.isEnrollmentOpen ?? true,
    deliveryMode: "on-demand",
    pricingModel: "free",
    features: {
      hasClasses: true,
      hasRecordings: true,
      hasSchedule: true,
      hasOnDemandContent: true,
      hasPricing: true,
      hasCertificate: true,
      hasAssessments: true,
      hasDiscussions: true,
    },
    createdAt: dto.createdAt ?? new Date().toISOString(),
    updatedAt: dto.updatedAt ?? dto.createdAt ?? new Date().toISOString(),
  };
}

async function fetchCourseBySlug(
  slug: string,
): Promise<CourseViewModel | null> {
  try {
    const { programs } = createCourseModules();
    const result = await programs.getCoursesSlug(slug);
    if (!result.ok) return null;

    return mapProgramDtoToCourseViewModel(
      result.data,
      await resolveCreatorHandle(result.data.creatorId),
    );
  } catch {
    return null;
  }
}

async function fetchCourseById(
  courseId: string,
): Promise<CourseViewModel | null> {
  try {
    const { programs } = createCourseModules();
    const result = await programs.getCoursesForGetCoursesById(courseId);
    if (!result.ok) return null;

    return mapProgramDtoToCourseViewModel(
      result.data,
      await resolveCreatorHandle(result.data.creatorId),
    );
  } catch {
    return null;
  }
}

/**
 * Fetch course details from the API by canonical ID or dashboard slug.
 */
export const getCourse = cache(
  async (courseIdentifier: string): Promise<CourseViewModel | null> => {
    const identifier = courseIdentifier.trim();
    if (!identifier) return null;

    if (isGuid(identifier)) {
      return fetchCourseById(identifier);
    }

    const slug = getCourseLookupSlug(identifier);
    return fetchCourseBySlug(slug);
  },
);

export const resolveCourseId = cache(
  async (courseIdentifier: string): Promise<string> => {
    if (isGuid(courseIdentifier)) return courseIdentifier.trim();

    const course = await getCourse(courseIdentifier);
    return course?.id ?? courseIdentifier;
  },
);

function deniedCourseAccess(courseId: string): CourseAccessCapabilities {
  return {
    courseId,
    courseExists: false,
    isTenantMember: false,
    isOwner: false,
    hasActiveEnrollment: false,
    canLearn: false,
    canEdit: false,
    canPublish: false,
    canReviewAsStaff: false,
    canAccessWorkspace: false,
  };
}

/**
 * Canonical server-side projection of the current actor's contextual course
 * access. The API remains authoritative; callers must fail closed when this
 * projection cannot be loaded.
 */
export const getCourseAccessCapabilities = cache(
  async (courseIdentifier: string): Promise<CourseAccessCapabilities> => {
    const courseId = await resolveCourseId(courseIdentifier);
    const denied = deniedCourseAccess(courseId);

    try {
      const session = await auth();
      if (!session?.user?.id || !session.tenantId || !isGuid(courseId)) {
        return denied;
      }

      const result = await getApiClient(session.tenantId).request<CourseAccessCapabilities>({
        method: "GET",
        path: `/v1/courses/${courseId}/access/capabilities`,
        requiresAuth: true,
        cache: "no-store",
      });

      return result.ok ? result.data : denied;
    } catch {
      return denied;
    }
  },
);

/**
 * Compatibility alias for authoring consumers. Course ownership and explicit
 * edit grants are resolved by the canonical API projection.
 */
export async function canManageCourse(
  courseIdentifier: string,
): Promise<boolean> {
  return (await getCourseAccessCapabilities(courseIdentifier)).canEdit;
}

/**
 * True when the API grants the current viewer contextual edit access.
 */
export async function canEditCourse(
  courseIdentifier: string,
): Promise<boolean> {
  return (await getCourseAccessCapabilities(courseIdentifier)).canEdit;
}

/**
 * Fetch course analytics data from the API.
 */
export const getCourseAnalytics = cache(
  async (courseId: string): Promise<CourseAnalyticsViewModel> => {
    const empty = emptyCourseAnalytics();
    try {
      const resolvedCourseId = await resolveCourseId(courseId);
      const { programs } = createCourseModules();
      const result = await programs.getCoursesAnalytics(resolvedCourseId);

      if (!result.ok) return empty;

      const dto = result.data;
      const totalUsers = Math.max(0, dto.totalUsers ?? 0);
      const completedUsers = Math.max(0, dto.completedUsers ?? 0);
      const completionRate =
        dto.completionRate ??
        (totalUsers > 0 ? (completedUsers / totalUsers) * 100 : 0);

      return {
        totalUsers,
        activeUsers: Math.max(0, dto.activeUsers ?? 0),
        completedUsers,
        completionRate: Math.max(0, Math.min(100, completionRate)),
        averageCompletionTime: dto.averageCompletionTime ?? null,
        totalViews: Math.max(0, dto.totalViews ?? 0),
        lastActivity: dto.lastActivity ?? null,
        enrollments: [],
        ratings: [],
        revenue: [],
      };
    } catch {
      return empty;
    }
  },
);

/**
 * Map a LearningCoursesProgramContent DTO to the frontend CourseContentItemViewModel shape.
 */
function readDtoGradingConfig(dto: LearningCoursesProgramContent) {
  return readContentGradingDefinition(dto.jsonBody ?? null);
}

function mapContentDto(
  dto: LearningCoursesProgramContent,
): CourseContentItemViewModel {
  const gradingConfig = readDtoGradingConfig(dto);
  const version = (dto as LearningCoursesProgramContent & { version?: number }).version;

  return {
    id: dto.id!,
    version: version ?? 0,
    slug: dto.slug ?? dto.id!,
    parentId: dto.parentId ?? null,
    order: dto.sortOrder ?? 0,
    type: dto.type ?? "Lesson",
    title: dto.title ?? "",
    description: dto.description ?? null,
    status: dto.visibility === "Public" ? "published" : "draft",
    visibility: dto.visibility ?? "Public",
    duration: dto.estimatedMinutes ?? null,
    estimatedMinutesSource: (dto.estimatedMinutesSource as "Auto" | "Manual" | null) ?? null,
    metadata: {},
    gradingConfig,
    createdAt: dto.createdAt ?? new Date().toISOString(),
    updatedAt: dto.updatedAt ?? dto.createdAt ?? new Date().toISOString(),
  };
}

function mapContentDetailDto(
  dto: LearningCoursesProgramContent,
): CourseContentItemDetailViewModel {
  const gradingConfig = readDtoGradingConfig(dto);

  return {
    ...mapContentDto(dto),
    content: dto.body ?? null,
    jsonBody: dto.jsonBody ?? null,
    settings: {
      isRequired: dto.isRequired,
      gradingConfig,
    },
    lessonFormat: normalizeLessonContentFormat(dto.lessonFormat),
  };
}

function findContentDto(
  dtos: LearningCoursesProgramContent[],
  contentIdOrSlug: string,
): LearningCoursesProgramContent | null {
  for (const dto of dtos) {
    if (dto.id === contentIdOrSlug || dto.slug === contentIdOrSlug) return dto;

    const child = findContentDto(dto.children ?? [], contentIdOrSlug);
    if (child) return child;
  }

  return null;
}

/**
 * Fetch course content items from the API (flat list for tree rendering).
 */
export const getCourseContent = cache(
  async (courseId: string): Promise<CourseContentViewModel> => {
    try {
      const resolvedCourseId = await resolveCourseId(courseId);
      const { content } = createCourseModules();
      const result = await content.getCoursesContent(resolvedCourseId);

      if (!result.ok) {
        const status =
          (result.error as { status?: number } | undefined)?.status ?? "error";
        return { items: [], total: 0, error: status };
      }

      const items: CourseContentItemViewModel[] = [];
      const seenIds = new Set<string>();
      const visit = (dto: LearningCoursesProgramContent) => {
        if (dto.id && !seenIds.has(dto.id)) {
          seenIds.add(dto.id);
          items.push(mapContentDto(dto));
        }

        for (const child of dto.children ?? []) visit(child);
      };

      for (const dto of result.data) {
        visit(dto);
      }

      return { items, total: items.length };
    } catch {
      return { items: [], total: 0, error: "error" };
    }
  },
);

/**
 * Fetch single content item detail.
 */
export const getContentItem = cache(
  async (
    courseId: string,
    contentIdOrSlug: string,
  ): Promise<CourseContentItemDetailViewModel | null> => {
    try {
      const resolvedCourseId = await resolveCourseId(courseId);
      const { content } = createCourseModules();

      if (isGuid(contentIdOrSlug)) {
        const result = await content.getCoursesContentById(
          resolvedCourseId,
          contentIdOrSlug,
        );
        if (result.ok) return mapContentDetailDto(result.data);
      }

      const courseContent = await content.getCoursesContent(resolvedCourseId);
      const fallbackDto = courseContent.ok
        ? findContentDto(courseContent.data, contentIdOrSlug)
        : null;
      return fallbackDto ? mapContentDetailDto(fallbackDto) : null;
    } catch {
      return null;
    }
  },
);

/**
 * Fetch course students from the API.
 */
export const getCourseStudents = cache(
  async (courseId: string): Promise<CourseStudentsViewModel> => {
    try {
      const resolvedCourseId = await resolveCourseId(courseId);
      const { programs } = createCourseModules();
      const result = await programs.getCoursesUsers(resolvedCourseId, {
        take: 200,
      });

      if (!result.ok) return { students: [], total: 0 };

      const students = result.data.map((dto, i) => {
        const userId = dto.userId ?? `user-${i}`;
        const name = dto.userName?.trim();
        const email = dto.userEmail?.trim() ?? "";

        return {
          id: dto.enrollmentId ?? userId,
          userId,
          name: name || email.split("@")[0] || `Student ${i + 1}`,
          email,
          enrolledAt: dto.startedAt ?? new Date().toISOString(),
          progress: Math.round(
            percentUnitsToPercentage(dto.completionPercentage ?? 0),
          ),
          completedAt: dto.completedAt ?? null,
          lastActivity:
            dto.lastAccessedAt ?? dto.startedAt ?? new Date().toISOString(),
        };
      });

      return { students, total: students.length };
    } catch {
      return { students: [], total: 0 };
    }
  },
);

