'use client';

import { useEffect, useMemo, useState } from 'react';
import { TRACK_CATALOG } from './catalog';

export interface Track {
  id: number | string;
  title: string;
  description: string;
  area: string;
  level: number | string;
  tools: string[];
  estimatedHours?: number;
  coursesCount?: number;
  image?: string;
  slug: string;
  knowledges: string[];
  obtained?: string;
  progress?: number;
}

export interface TrackFilters {
  area: string;
  tool: string;
  level: string;
  searchTerm: string;
}

/**
 * Hook for managing track filters and data
 */
export function useTrackFilters() {
  const [area, setArea] = useState('all');
  const [tool, setTool] = useState('all');
  const [level, setLevel] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [tracks, setTracks] = useState<Track[]>([]);
  const [availableTools, setAvailableTools] = useState<string[]>([]);

  // Load tracks data
  useEffect(() => {
    const loadTracks = async () => {
      const catalogTracks: Track[] = TRACK_CATALOG;

      setTracks(catalogTracks);

      // Extract unique tools from all tracks
      const tools = [...new Set(catalogTracks.flatMap((track) => track.tools))];
      setAvailableTools(tools);
    };

    loadTracks();
  }, []);

  // Filter tracks based on current filters
  const filteredTracks = useMemo(() => {
    let filtered = tracks;

    if (area !== 'all') {
      filtered = filtered.filter((track) => track.area === area);
    }

    if (tool !== 'all') {
      filtered = filtered.filter((track) => track.tools.includes(tool));
    }

    if (level !== 'all') {
      filtered = filtered.filter((track) => track.level.toString() === level);
    }

    if (searchTerm) {
      const search = searchTerm.toLowerCase();
      filtered = filtered.filter((track) => track.title.toLowerCase().includes(search) || track.description.toLowerCase().includes(search));
    }

    return filtered;
  }, [tracks, area, tool, level, searchTerm]);

  return {
    area,
    tool,
    level,
    searchTerm,
    tracks: filteredTracks,
    availableTools,
    setArea,
    setTool,
    setLevel,
    setSearchTerm,
  };
}

// Alias for backward compatibility
export const useFilteredTracks = useTrackFilters;

'use server';

/**
 * User settings server actions.
 *
 * All mutations go through the `@game-guild/client` ApiClient. The profile
 * and preference endpoints use the client's own `request` pipeline because
 * their generated schemas do not match the deployed API contracts. Using
 * `client.request` keeps the same auth, tenant, and error pipeline without
 * the mismatched generated validation.
 */

import { getAuthenticatedUserId, getUserSettingsApiClient } from './api-client';
import {
  type AccessibilityPreferenceData,
  type EditorGlobalPreferencesBlob,
  type LocalizationPreferenceData,
  type PreferencePatch,
  type PrivacyPreferenceData,
  type ThemePreference,
  buildAccessibilityPayload,
  buildLocalizationPayload,
  buildPrivacyPayload,
} from './preferences-mappers';
import { getAccessibilityPreference, getGeneralPreferences } from './queries';

export type ActionResult<T = void> =
  | { readonly success: true; readonly data: T }
  | { readonly success: false; readonly error: string };

const PROFILE_FIELD_LIMITS = {
  handle: 80,
  displayName: 100,
  bio: 1000,
  location: 100,
  website: 255,
  jobTitle: 100,
  company: 100,
  avatarUrl: 500,
  bannerUrl: 500,
} as const;

export interface ProfileFormInput {
  readonly handle: string;
  readonly displayName: string;
  readonly bio: string;
  readonly location: string;
  readonly website: string;
  readonly jobTitle: string;
  readonly company: string;
  readonly avatarUrl: string;
  readonly bannerUrl: string;
}

const PROFILE_FIELDS = [
  'handle',
  'displayName',
  'bio',
  'location',
  'website',
  'jobTitle',
  'company',
  'avatarUrl',
  'bannerUrl',
] as const;

const PROFILE_URL_FIELDS = ['website', 'avatarUrl', 'bannerUrl'] as const;

type AccountProfileBody = Pick<ProfileFormInput, 'displayName' | 'bio' | 'location' | 'website' | 'jobTitle' | 'company'>;

function isHttpUrl(value: string): boolean {
  try {
    const url = new URL(value);
    return url.protocol === 'http:' || url.protocol === 'https:';
  } catch {
    return false;
  }
}

function text(value: unknown): string {
  return typeof value === 'string' ? value : '';
}

async function patchPreferences(
  userId: string,
  body: PreferencePatch,
): Promise<ActionResult> {
  const client = getUserSettingsApiClient();
  const result = await client.request<void>({
    method: 'PATCH',
    path: `/v1/users/${userId}/preferences`,
    body,
    requiresAuth: true,
  });

  if (!result.ok) {
    return { success: false, error: result.error.message || 'Failed to save preferences.' };
  }

  return { success: true, data: undefined };
}

async function patchCategoryPreferences(
  category: 'localization' | 'privacy' | 'accessibility',
  body: PreferencePatch,
): Promise<ActionResult> {
  const userId = await getAuthenticatedUserId();
  if (!userId) return { success: false, error: 'Not authenticated.' };

  const client = getUserSettingsApiClient();
  const result = await client.request<void>({
    method: 'PATCH',
    path: `/v1/users/${userId}/preferences/${category}`,
    body,
    requiresAuth: true,
  });

  if (!result.ok) {
    return { success: false, error: result.error.message || 'Failed to save preferences.' };
  }

  return { success: true, data: undefined };
}

